module eink_half_integer_divider #(
    parameter integer COUNT_WIDTH = 64,
    parameter [COUNT_WIDTH-1:0] DIV_INT = 64'd4
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_ce,
    output wire o_refresh_clk
);
    localparam [COUNT_WIDTH-1:0] COUNT_ZERO = {COUNT_WIDTH{1'b0}};
    localparam [COUNT_WIDTH-1:0] COUNT_ONE = {{(COUNT_WIDTH-1){1'b0}}, 1'b1};

    reg [COUNT_WIDTH-1:0] phase_count;
    reg edge_select;
    reg rise_window;
    reg fall_window;
    reg armed;

    // edge_select names the edge used by the next dispatch:
    // zero selects rising, one selects falling.
    wire [COUNT_WIDTH-1:0] terminal_count;
    assign terminal_count = edge_select ? (DIV_INT - COUNT_ONE) : DIV_INT;

    initial phase_count = COUNT_ZERO;
    initial edge_select = 1'b0;
    initial rise_window = 1'b0;
    initial fall_window = 1'b0;
    initial armed = 1'b0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase_count <= COUNT_ZERO;
            edge_select <= 1'b0;
            rise_window <= 1'b0;
            fall_window <= 1'b0;
            armed <= 1'b0;
        end else if (i_ce) begin
            // Retire the previous edge window in the slot after dispatch.
            // Outside that slot, the window registers retain their values.
            if (phase_count == COUNT_ZERO) begin
                rise_window <= 1'b0;
                fall_window <= 1'b0;
            end

            if (phase_count == terminal_count) begin
                phase_count <= COUNT_ZERO;
                edge_select <= !edge_select;
                if (edge_select)
                    fall_window <= 1'b1;
                else
                    rise_window <= 1'b1;

                // Q is the first divider dispatch; the scope stays armed.
                armed <= 1'b1;
            end else begin
                phase_count <= phase_count + COUNT_ONE;
            end
        end
    end

    // With continuous enable, dispatch intervals alternate DIV_INT and
    // DIV_INT+1 input cycles. Alternating edge qualification makes successive
    // refresh pulses DIV_INT+0.5 input periods apart.
    assign o_refresh_clk = i_ce &&
                           ((rise_window && clk) ||
                            (fall_window && !clk));

    always @(posedge clk)
        assert (!armed || !(rise_window && fall_window));
endmodule

module block130_staged_encoder #(
    parameter integer WORD_BITS = 32'd64,
    parameter [63:0] STAGE_ENTRIES = 64'd128
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_ce,
    input  wire i_load,
    input  wire i_ordered_set,
    input  wire [WORD_BITS-32'd1:32'd0] i_word0,
    input  wire [WORD_BITS-32'd1:32'd0] i_word1,
    input  wire i_ready,
    output wire o_valid,
    output wire [WORD_BITS-32'd1:32'd0] o_chunk,
    output wire [63:0] o_chunk_bits
);
    // Default framing is a two-bit header followed by sixteen payload bytes.
    // WORD_BITS is byte-aligned; STAGE_ENTRIES is even and at least two.
    localparam [63:0] SYMBOLS_PER_WORD = WORD_BITS / 64'd8;
    localparam [63:0] SYMBOLS_PER_BLOCK = 64'd2 * SYMBOLS_PER_WORD;
    localparam [63:0] LAST_SYMBOL_MASK =
        64'd1 << (SYMBOLS_PER_BLOCK - 64'd1);

    // Successive blocks use successive pairs in this circular staging bank.
    reg [WORD_BITS-32'd1:32'd0] staged_data [64'd0:STAGE_ENTRIES-64'd1];
    reg [63:0] block_slot;
    reg [63:0] block_type;
    reg [63:0] busy;
    reg [63:0] header_pending;
    reg [63:0] symbol_count;
    reg [63:0] symbol_cursor;

    initial begin
        block_slot     = 64'd0;
        block_type     = 64'd0;
        busy           = 64'd0;
        header_pending = 64'd0;
        symbol_count   = 64'd0;
        symbol_cursor  = 64'd1;
    end

    genvar g;
    generate
        for (g = 32'd0; g < STAGE_ENTRIES; g = g + 32'd1) begin : init_staging
            initial staged_data[g] = 64'd0;
        end
    endgenerate

    wire first_word = symbol_count < SYMBOLS_PER_WORD;
    wire [63:0] byte_lane = first_word ? symbol_count :
                                           symbol_count - SYMBOLS_PER_WORD;
    wire [WORD_BITS-32'd1:32'd0] selected_word = first_word ?
        staged_data[block_slot] : staged_data[block_slot + 64'd1];

    // Accepted chunks concatenate into the encoded block: header, then payload.
    // Only the low o_chunk_bits bits are significant in each chunk.
    assign o_valid = i_ce && (busy != 64'd0);
    assign o_chunk_bits = (busy == 64'd0) ? 64'd0 :
                          (header_pending != 64'd0) ? 64'd2 : 64'd8;
    assign o_chunk = (header_pending != 64'd0) ?
                     ((block_type == 64'd0) ? 64'd1 : 64'd2) :
                     ((selected_word >> (byte_lane * 64'd8)) & 64'h00000000000000ff);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            block_slot     <= 64'd0;
            block_type     <= 64'd0;
            busy           <= 64'd0;
            header_pending <= 64'd0;
            symbol_count   <= 64'd0;
            symbol_cursor  <= 64'd1;
            for (integer r = 32'd0; r < STAGE_ENTRIES; r = r + 32'd1)
                staged_data[r] <= 64'd0;
        end else if (i_ce) begin
            if (busy == 64'd0) begin
                if (i_load) begin
                    staged_data[block_slot] <= i_word0;
                    staged_data[block_slot + 64'd1] <= i_word1;
                    block_type     <= i_ordered_set ? 64'd1 : 64'd0;
                    busy           <= 64'd1;
                    header_pending <= 64'd1;
                    symbol_count   <= 64'd0;
                    symbol_cursor  <= 64'd1;
                end
            end else if (i_ready) begin
                if (header_pending != 64'd0) begin
                    header_pending <= 64'd0;
                end else if (symbol_cursor == LAST_SYMBOL_MASK) begin
                    busy          <= 64'd0;
                    symbol_count  <= 64'd0;
                    symbol_cursor <= 64'd1;
                    if (block_slot == STAGE_ENTRIES - 64'd2)
                        block_slot <= 64'd0;
                    else
                        block_slot <= block_slot + 64'd2;
                end else begin
                    symbol_count  <= symbol_count + 64'd1;
                    symbol_cursor <= symbol_cursor << 64'd1;
                end
            end
        end
    end

    always @(posedge clk)
        assert (symbol_count <= SYMBOLS_PER_BLOCK - 64'd1);
endmodule

module descriptor_mcp_bridge #(
    parameter integer DATA_W = 16
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_submit,
    input  wire [DATA_W-1:0]     i_descriptor,
    input  wire                  i_end_window,
    output reg  [DATA_W-1:0]     dst_word
);
    reg [DATA_W-1:0] src_hold;
    reg src_toggle;
    reg req_meta, req_sync;
    reg dst_ack;
    reg ack_meta, ack_sync;
    reg audit_window;

    wire launch = i_submit && (src_toggle == ack_sync);
    wire capture = (req_sync != dst_ack);

    initial begin
        src_hold    = {DATA_W{1'b0}};
        dst_word    = {DATA_W{1'b0}};
        src_toggle  = 1'b0;
        req_meta    = 1'b0;
        req_sync    = 1'b0;
        dst_ack     = 1'b0;
        ack_meta    = 1'b0;
        ack_sync    = 1'b0;
        audit_window = 1'b0;
    end

    // Single-clock model of a held-word transfer with synchronized
    // request and acknowledgement toggles. No external handshake ports.
    always @(posedge clk) begin
        if (i_ce) begin
            req_meta <= src_toggle;
            req_sync <= req_meta;
            ack_meta <= dst_ack;
            ack_sync <= ack_meta;

            // The returned acknowledgement frees the holding register.
            if (launch) begin
                src_hold   <= i_descriptor;
                src_toggle <= ~src_toggle;
            end

            if (capture) begin
                dst_word <= src_hold;
                dst_ack  <= req_sync;
            end

            // Q: an accepted launch. R: an explicit audit-window end.
            // If R never arrives, the window remains armed.
            if (i_end_window)
                audit_window <= 1'b0;
            else if (launch)
                audit_window <= 1'b1;
        end
    end

    // During the audit window, an acknowledged current request must
    // identify a destination word equal to the source holding word.
    always @(*) begin
        if (audit_window)
            assert ((dst_ack != src_toggle) || (dst_word == src_hold));
    end
endmodule

module parking_policy_patch_rom #(
    parameter ENTRIES = 4
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        i_ce,
    input  wire        open_window,
    input  wire        close_window,
    input  wire        request_valid,
    input  wire [63:0] request_address,
    input  wire [63:0] rom_word,
    input  wire        cfg_write,
    input  wire [63:0] cfg_slot,
    input  wire [63:0] cfg_address,
    input  wire [63:0] cfg_word,
    input  wire        cfg_enable,
    output reg         busy,
    output reg  [63:0] response_word
);
    localparam [63:0] SLOT_COUNT = ENTRIES;

    reg [63:0] patch_address [0:ENTRIES-1];
    reg [63:0] patch_word    [0:ENTRIES-1];
    reg [ENTRIES-1:0] patch_enable;

    reg [63:0] fetch_address;
    reg [63:0] fallback_word;
    reg [63:0] scan_index;
    reg [63:0] remaining;
    reg [63:0] completed_requests;
    reg [63:0] deadline_events;
    reg window_open;
    reg past_valid;
    integer i;

    wire slot_hit = (scan_index < SLOT_COUNT) &&
                    patch_enable[scan_index] &&
                    (patch_address[scan_index] == fetch_address);
    wire scan_done = slot_hit || (scan_index == SLOT_COUNT - 64'd1);

    initial begin
        busy = 1'b0;
        response_word = 64'd0;
        fetch_address = 64'd0;
        fallback_word = 64'd0;
        scan_index = 64'd0;
        remaining = 64'd0;
        completed_requests = 64'd0;
        deadline_events = 64'd0;
        window_open = 1'b0;
        past_valid = 1'b0;
        patch_enable = {ENTRIES{1'b0}};
        for (i = 0; i < ENTRIES; i = i + 1) begin
            patch_address[i] = 64'd0;
            patch_word[i] = 64'd0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0;
            response_word <= 64'd0;
            fetch_address <= 64'd0;
            fallback_word <= 64'd0;
            scan_index <= 64'd0;
            remaining <= 64'd0;
            completed_requests <= 64'd0;
            deadline_events <= 64'd0;
            window_open <= 1'b0;
            past_valid <= 1'b0;
            patch_enable <= {ENTRIES{1'b0}};
            for (i = 0; i < ENTRIES; i = i + 1) begin
                patch_address[i] <= 64'd0;
                patch_word[i] <= 64'd0;
            end
        end else if (i_ce) begin
            past_valid <= 1'b1;

            // The scope can be opened and closed repeatedly.
            if (close_window)
                window_open <= 1'b0;
            else if (open_window)
                window_open <= 1'b1;

            if (!busy) begin
                if (cfg_write && (cfg_slot < SLOT_COUNT)) begin
                    patch_address[cfg_slot] <= cfg_address;
                    patch_word[cfg_slot] <= cfg_word;
                    patch_enable[cfg_slot] <= cfg_enable;
                end
                if (request_valid) begin
                    fetch_address <= request_address;
                    fallback_word <= rom_word;
                    scan_index <= 64'd0;
                    remaining <= SLOT_COUNT;
                    busy <= 1'b1;
                end
            end else begin
                // Search one patch slot per enabled cycle, first match wins.
                if (remaining != 64'd0)
                    remaining <= remaining - 64'd1;

                // Reaching the deadline is legal only with completion.
                if (remaining == 64'd1)
                    deadline_events <= deadline_events + 64'd1;

                if (scan_done) begin
                    response_word <= slot_hit ? patch_word[scan_index]
                                              : fallback_word;
                    completed_requests <= completed_requests + 64'd1;
                    busy <= 1'b0;
                    scan_index <= 64'd0;
                    remaining <= 64'd0;
                end else begin
                    scan_index <= scan_index + 64'd1;
                end
            end
        end
    end

    // Bounded response in enabled cycles: if completion did not change,
    // no deadline may have expired inside the latched scope window.
    always @(posedge clk)
        if (past_valid && window_open && $stable(completed_requests))
            assert ($stable(deadline_events));
endmodule

module approximate_lane_por #(
    parameter integer DATA_W = 32,
    parameter [DATA_W-1:0] DEFAULT_CYCLES = 32'd4
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    output wire                  o_ready,
    input  wire [DATA_W-1:0]     i_cmd,
    input  wire [DATA_W-1:0]     i_cycles,
    input  wire                  i_sample_stable,
    output logic                 por_reset_n
);
    localparam [DATA_W-1:0] ZERO       = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE        = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] CMD_ARM    = 32'd1;
    localparam [DATA_W-1:0] CMD_START  = 32'd2;
    localparam [DATA_W-1:0] CMD_SAMPLE = 32'd3;

    typedef enum logic [1:0] {
        WAIT_ARM   = 2'b00,
        WAIT_START = 2'b01,
        COUNTING   = 2'b10,
        DONE       = 2'b11
    } state_t;

    state_t state;
    logic [DATA_W-1:0] programmed_cycles;
    logic [DATA_W-1:0] stable_count;
    logic timer_running;
    logic scope_armed;
    logic past_valid;

    wire chain_finished = (state == DONE);

    // Back-pressure rejects commands that are premature or no longer useful.
    assign o_ready = i_ce &&
        (((state == WAIT_ARM)   && (i_cmd == CMD_ARM)) ||
         ((state == WAIT_START) && (i_cmd == CMD_START)) ||
         ((state == COUNTING)   && (i_cmd == CMD_SAMPLE)));

    wire fire = i_valid && o_ready;

    initial begin
        state             = WAIT_ARM;
        programmed_cycles = (DEFAULT_CYCLES == ZERO) ? ONE : DEFAULT_CYCLES;
        stable_count      = ZERO;
        timer_running     = 1'b0;
        por_reset_n       = 1'b0;
        scope_armed       = 1'b0;
        past_valid        = 1'b0;
    end

    // ARM programs the reset interval; START launches it; accepted stable
    // samples advance the POR timer. An unstable sample restarts the interval.
    // Every register holds its value when no command transfers.
    always @(posedge clk) begin
        if (fire) begin
            past_valid <= 1'b1;

            case (state)
                WAIT_ARM: begin
                    programmed_cycles <= (i_cycles == ZERO) ? ONE : i_cycles;
                    scope_armed <= 1'b1;
                    state <= WAIT_START;
                end
                WAIT_START: begin
                    timer_running <= 1'b1;
                    state <= COUNTING;
                end
                COUNTING: begin
                    if (i_sample_stable &&
                        (stable_count == programmed_cycles - ONE))
                        state <= DONE;
                end
                DONE: begin
                end
            endcase

            // The timer's run latch and the command controller advance
            // independently, but are synchronized by construction.
            if (timer_running) begin
                if (!i_sample_stable) begin
                    stable_count <= ZERO;
                end else if (stable_count == programmed_cycles - ONE) begin
                    stable_count <= programmed_cycles;
                    timer_running <= 1'b0;
                    por_reset_n <= 1'b1;
                end else begin
                    stable_count <= stable_count + ONE;
                end
            end
        end
    end

    // After the first accepted ARM, reset release may change only when
    // the ordered ARM -> START -> completion chain finishes.
    always @(posedge clk) begin
        if (past_valid && scope_armed && $stable(chain_finished))
            assert ($stable(por_reset_n));
    end
endmodule

module irda_sir_word_bridge #(
    parameter integer WORD_BITS = 128
) (
    input  wire                 clk,
    input  wire                 i_valid,
    output wire                 i_ready,
    input  wire [WORD_BITS-1:0]  i_uart_word,
    output wire                 o_sample_valid,
    input  wire                 o_sample_ready,
    output reg                  o_ir_tx,
    input  wire                 i_ir_rx,
    output reg  [WORD_BITS-1:0]  o_rx_word,
    output reg                  o_word_done
);
    localparam integer BIT_INDEX_W = (WORD_BITS > 1) ? $clog2(WORD_BITS) : 1;
    localparam [BIT_INDEX_W-1:0] LAST_BIT = BIT_INDEX_W'(WORD_BITS - 1);

    reg busy;
    reg armed;
    reg [WORD_BITS-1:0] tx_shift;
    reg [BIT_INDEX_W-1:0] bit_index;
    reg [3:0] phase;
    reg [1:0] pulse_left;
    reg zero_launch_shadow;

    reg rx_pulse_latch;
    reg [14:0] rx_history;
    reg [15:0] rx_evidence;
    reg rx_bit_valid;
    reg rx_decoded_bit;

    assign i_ready = !busy;
    assign o_sample_valid = busy;
    wire load_word = i_valid && i_ready;
    wire sample_fire = o_sample_valid && o_sample_ready;

    initial begin
        busy = 1'b0;
        armed = 1'b0;
        tx_shift = '0;
        bit_index = '0;
        phase = 4'd0;
        pulse_left = 2'd0;
        zero_launch_shadow = 1'b0;
        rx_pulse_latch = 1'b0;
        rx_history = 15'h0000;
        rx_evidence = 16'h0000;
        rx_bit_valid = 1'b0;
        rx_decoded_bit = 1'b1;
        o_ir_tx = 1'b0;
        o_rx_word = '0;
        o_word_done = 1'b0;
    end

    // Each accepted output sample advances one sixteenth of a bit time.
    // Back-pressure freezes the sample, the serializer, and the receiver.
    always @(posedge clk) begin
        if (load_word) begin
            busy <= 1'b1;
            armed <= 1'b1;
            tx_shift <= i_uart_word;
            bit_index <= '0;
            phase <= 4'd0;
            pulse_left <= 2'd0;
            zero_launch_shadow <= 1'b0;
            rx_pulse_latch <= 1'b0;
            rx_history <= 15'h0000;
            rx_evidence <= 16'h0000;
            rx_bit_valid <= 1'b0;
            rx_decoded_bit <= 1'b1;
            o_ir_tx <= 1'b0;
            o_rx_word <= '0;
            o_word_done <= 1'b0;
        end else if (sample_fire) begin
            rx_bit_valid <= 1'b0;

            // A UART zero produces three infrared samples, at phases 1..3.
            if (phase == 4'd0) begin
                zero_launch_shadow <= !tx_shift[0];
                o_ir_tx <= !tx_shift[0];
                pulse_left <= tx_shift[0] ? 2'd0 : 2'd2;
            end else begin
                o_ir_tx <= (pulse_left != 2'd0);
                if (pulse_left != 2'd0)
                    pulse_left <= pulse_left - 2'd1;
            end

            if (phase == 4'd15) begin
                phase <= 4'd0;
                rx_decoded_bit <= !(rx_pulse_latch || i_ir_rx);
                rx_evidence <= {i_ir_rx, rx_history};
                rx_bit_valid <= 1'b1;
                o_rx_word[bit_index] <= !(rx_pulse_latch || i_ir_rx);
                rx_pulse_latch <= 1'b0;
                rx_history <= 15'h0000;

                if (bit_index == LAST_BIT) begin
                    busy <= 1'b0;
                    o_word_done <= 1'b1;
                    o_ir_tx <= 1'b0;
                    pulse_left <= 2'd0;
                end else begin
                    bit_index <= bit_index + BIT_INDEX_W'(1);
                    tx_shift <= tx_shift >> 1'b1;
                end
            end else begin
                phase <= phase + 4'd1;
                rx_pulse_latch <= rx_pulse_latch || i_ir_rx;
                if (i_ir_rx)
                    rx_history <= rx_history | (15'h0001 << phase);
            end
        end
    end

    // After the first accepted word, observations require earlier evidence.
    always @(posedge clk) begin
        if (armed) begin
            assert (!o_sample_valid || !o_ir_tx || zero_launch_shadow);
            assert (!rx_bit_valid || rx_decoded_bit || (rx_evidence != 16'h0000));
        end
    end
endmodule

module operand_exchange_chain #(
    parameter WORD_WIDTH = 64,
    parameter COUNT_WIDTH = 64
) (
    input wire clk,
    input wire step,
    input wire q,
    input wire r,
    input wire arm,
    input wire load_right,
    input wire start,
    input wire finish,
    input wire [WORD_WIDTH-1:0] arm_data,
    input wire [WORD_WIDTH-1:0] right_data,
    output reg [WORD_WIDTH-1:0] word_left,
    output reg [WORD_WIDTH-1:0] word_right,
    output reg [COUNT_WIDTH-1:0] start_count,
    output reg [COUNT_WIDTH-1:0] finish_count
);
    reg arm_credit;
    reg start_credit;
    reg window;
    reg pv;

    // Each descriptor has a pending-token bit above its payload.
    // The credit FSM records whether the chain is armed or started.
    initial begin
        word_left = {WORD_WIDTH{1'b0}};
        word_right = {WORD_WIDTH{1'b0}};
        start_count = {COUNT_WIDTH{1'b0}};
        finish_count = {COUNT_WIDTH{1'b0}};
        arm_credit = 1'b0;
        start_credit = 1'b0;
        window = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (step) begin
            pv <= 1'b1;

            // Latch the after-Q-until-R scope, even if R never arrives.
            if (r)
                window <= 1'b0;
            else if (q)
                window <= 1'b1;

            if (arm && !word_left[WORD_WIDTH-1] &&
                       !word_right[WORD_WIDTH-1]) begin
                // Independent left load arms a new descriptor.
                word_left <= {1'b1, arm_data[WORD_WIDTH-2:0]};
                if (!arm_credit && !start_credit)
                    arm_credit <= 1'b1;
            end else if (load_right && !word_right[WORD_WIDTH-1]) begin
                // Independent right load prepares the other operand.
                word_right <= {1'b0, right_data[WORD_WIDTH-2:0]};
            end else if (start && word_left[WORD_WIDTH-1] &&
                                 !word_right[WORD_WIDTH-1]) begin
                // Exchange both complete words, including their token bits.
                word_left <= word_right;
                word_right <= word_left;
                start_count <= start_count +
                    {{(COUNT_WIDTH-1){1'b0}}, 1'b1};
                if (arm_credit && !start_credit) begin
                    arm_credit <= 1'b0;
                    start_credit <= 1'b1;
                end
            end else if (finish && word_right[WORD_WIDTH-1]) begin
                // Retirement consumes the descriptor delivered by exchange.
                word_right[WORD_WIDTH-1] <= 1'b0;
                finish_count <= finish_count +
                    {{(COUNT_WIDTH-1){1'b0}}, 1'b1};
                if (start_credit)
                    start_credit <= 1'b0;
            end
        end
    end

    // Start requires consumption of an earlier arm credit; finish requires
    // consumption of an earlier start credit. An unchanged or previously
    // absent credit therefore requires the corresponding count to be stable.
    always @(posedge clk) begin
        if (pv && window)
            assert (
                ((!$past(arm_credit) || $stable(arm_credit))
                    ? $stable(start_count) : 1'b1) &&
                ((!$past(start_credit) || $stable(start_credit))
                    ? $stable(finish_count) : 1'b1)
            );
    end
endmodule

module mcp_bus_deadline #(
    parameter integer WORD_WIDTH = 64,
    parameter integer TIMER_WIDTH = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  launch,
    input  wire [WORD_WIDTH-1:0]  i_word,
    output reg  [WORD_WIDTH-1:0]  dst_word
);
    localparam [TIMER_WIDTH-1:0] T0 = TIMER_WIDTH'(0);
    localparam [TIMER_WIDTH-1:0] T1 = TIMER_WIDTH'(1);
    localparam [TIMER_WIDTH-1:0] T2 = TIMER_WIDTH'(2);
    localparam [TIMER_WIDTH-1:0] T3 = TIMER_WIDTH'(3);
    localparam [TIMER_WIDTH-1:0] T4 = TIMER_WIDTH'(4);
    localparam [TIMER_WIDTH-1:0] T5 = TIMER_WIDTH'(5);
    localparam [TIMER_WIDTH-1:0] T6 = TIMER_WIDTH'(6);

    reg [WORD_WIDTH-1:0] hold_word;
    reg [TIMER_WIDTH-1:0] countdown;
    reg busy;
    reg req_toggle;
    reg req_meta;
    reg req_sync;
    reg ack_toggle;
    reg ack_meta;
    reg ack_sync;

    initial begin
        hold_word = {WORD_WIDTH{1'b0}};
        dst_word = {WORD_WIDTH{1'b0}};
        countdown = T0;
        busy = 1'b0;
        req_toggle = 1'b0;
        req_meta = 1'b0;
        req_sync = 1'b0;
        ack_toggle = 1'b0;
        ack_meta = 1'b0;
        ack_sync = 1'b0;
    end

    // A common clock models both ends; i_ce freezes the entire transport.
    // Launches while busy are ignored. There are no external handshake ports.
    always @(posedge clk) begin
        if (i_ce) begin
            // Forward toggle synchronization.
            req_meta <= req_toggle;
            req_sync <= req_meta;

            // Capture the held multibit word, then acknowledge its toggle.
            if (req_sync != ack_toggle) begin
                dst_word <= hold_word;
                ack_toggle <= req_sync;
            end

            // Return acknowledgment synchronization.
            ack_meta <= ack_toggle;
            ack_sync <= ack_meta;

            if (!busy) begin
                if (launch) begin
                    hold_word <= i_word;
                    req_toggle <= ~req_toggle;
                    busy <= 1'b1;
                    countdown <= T6;
                end
            end else if (ack_sync == req_toggle) begin
                busy <= 1'b0;
                countdown <= T0;
            end else if (countdown != T0) begin
                countdown <= countdown - T1;
            end
        end
    end

    // Every accepted transfer completes before its enabled-cycle budget expires.
    assert property (!busy || (countdown != T0));
endmodule

module sdram_rr_request_dispatch #(
    parameter integer BANKS = 4,
    parameter integer DATA_W = 64,
    parameter integer COUNTER_W = 64
) (
    input  wire                  i_clk,
    input  wire                  i_req_valid,
    output wire                  o_req_ready,
    input  wire [DATA_W-1:0]     i_req_data,
    output wire [BANKS-1:0]      o_bank_valid,
    input  wire [BANKS-1:0]      i_bank_ready,
    output wire [DATA_W-1:0]     o_bank_data
);
    localparam [COUNTER_W-1:0] COUNT_ZERO = {COUNTER_W{1'b0}};
    localparam [COUNTER_W-1:0] COUNT_ONE = {{(COUNTER_W-1){1'b0}}, 1'b1};
    localparam [COUNTER_W-1:0] BANK_COUNT = BANKS;
    localparam [COUNTER_W-1:0] LAST_BANK = BANK_COUNT - COUNT_ONE;
    localparam [BANKS-1:0] MASK_ZERO = {BANKS{1'b0}};
    localparam [BANKS-1:0] MASK_ONE = {{(BANKS-1){1'b0}}, 1'b1};

    // Binary next-bank pointer and its cached one-hot routing mask.
    reg [COUNTER_W-1:0] next_bank;
    reg [BANKS-1:0] next_mask;

    // One shared command slot: only its selected bank sees valid.
    reg pending_valid;
    reg [BANKS-1:0] pending_mask;
    reg [DATA_W-1:0] pending_data;
    reg armed;

    initial begin
        next_bank = COUNT_ZERO;
        next_mask = MASK_ONE;
        pending_valid = 1'b0;
        pending_mask = MASK_ZERO;
        pending_data = {DATA_W{1'b0}};
        armed = 1'b0;
    end

    wire [COUNTER_W-1:0] following_bank;
    wire retire;
    wire accept;

    assign following_bank = (next_bank == LAST_BANK)
                          ? COUNT_ZERO : next_bank + COUNT_ONE;
    assign o_bank_valid = pending_valid ? pending_mask : MASK_ZERO;
    assign o_bank_data = pending_data;
    assign retire = |(o_bank_valid & i_bank_ready);
    assign o_req_ready = !pending_valid || retire;
    assign accept = i_req_valid && o_req_ready;

    always @(posedge i_clk) begin
        if (accept) begin
            pending_valid <= 1'b1;
            pending_mask <= next_mask;
            pending_data <= i_req_data;
            armed <= 1'b1;

            next_bank <= following_bank;
            // Move the cached route from the old bank to the following bank.
            next_mask <= (next_mask & ~(MASK_ONE << next_bank))
                       | (MASK_ONE << following_bank);
        end else if (retire) begin
            pending_valid <= 1'b0;
        end
    end

    // After the first accepted command, banks zero and one must never
    // simultaneously own the shared command slot.
    always @(posedge i_clk)
        if (armed) assert (!(o_bank_valid[0] && o_bank_valid[1]));
endmodule

module scoped_masked_comparator #(
    parameter integer WORD_W = 64
) (
    input wire clk,
    input wire ce,
    input wire program_config,
    input wire open_window,
    input wire close_window,
    input wire [WORD_W-1:0] sample_in,
    input wire [WORD_W-1:0] mask_in,
    input wire [WORD_W-1:0] reference_in,
    output reg match
);
    reg [WORD_W-1:0] mask_reg;
    reg [WORD_W-1:0] reference_reg;
    reg [WORD_W-1:0] sample_reg;
    reg window_open;
    reg past_valid;

    wire [WORD_W-1:0] selected_mask =
        program_config ? mask_in : mask_reg;
    wire [WORD_W-1:0] selected_reference =
        program_config ? reference_in : reference_reg;

    initial begin
        mask_reg = {WORD_W{1'b1}};
        reference_reg = {WORD_W{1'b0}};
        sample_reg = {WORD_W{1'b0}};
        match = 1'b1;
        window_open = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            past_valid <= 1'b1;
            if (program_config) begin
                mask_reg <= mask_in;
                reference_reg <= reference_in;
            end
            sample_reg <= sample_in;
            match <= (((sample_in ^ selected_reference) & selected_mask)
                      == {WORD_W{1'b0}});

            if (close_window)
                window_open <= 1'b0;
            else if (open_window)
                window_open <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (past_valid && window_open &&
            $stable({mask_reg, reference_reg, sample_reg}))
            assert ($stable(match));
    end
endmodule

module banked_token_fifo #(
    parameter [31:0] DEPTH = 32'd32,
    parameter [31:0] WRITE_PORTS = 32'd4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire [WRITE_PORTS-32'd1:32'd0] in_valid,
    output wire [WRITE_PORTS-32'd1:32'd0] in_ready,
    input  wire [WRITE_PORTS*32'd32-32'd1:32'd0] in_data,
    input  wire read_enable,
    output wire out_empty,
    output wire [31:0] out_data,
    output reg  [31:0] used_count
);
    localparam [31:0] BANK_ROWS =
        (DEPTH + WRITE_PORTS - 32'd1) / WRITE_PORTS;

    wire [31:0] capacity_limit = DEPTH;
    reg [31:0] free_count;
    reg [31:0] write_ptr;
    reg [31:0] read_ptr;
    reg past_valid;
    reg [31:0] bank_mem [32'd0:WRITE_PORTS-32'd1]
                              [32'd0:BANK_ROWS-32'd1];

    wire [WRITE_PORTS-32'd1:32'd0] take;
    wire [31:0] accepted_prefix [32'd0:WRITE_PORTS];
    wire [31:0] write_address [32'd0:WRITE_PORTS-32'd1];
    wire [31:0] write_count = accepted_prefix[WRITE_PORTS];
    wire do_read = i_ce && read_enable && !out_empty;
    wire over_capacity = used_count > capacity_limit;

    function automatic [31:0] ring_add;
        input [31:0] base;
        input [31:0] amount;
        reg [32:0] total;
        begin
            total = {1'b0, base} + {1'b0, amount};
            if (total >= {1'b0, capacity_limit})
                ring_add = total - {1'b0, capacity_limit};
            else
                ring_add = total[31:0];
        end
    endfunction

    assign accepted_prefix[32'd0] = 32'd0;
    genvar lane;
    generate
        for (lane = 32'd0; lane < WRITE_PORTS; lane = lane + 32'd1) begin : ports
            // Earlier accepted lanes consume credits before later lanes.
            assign in_ready[lane] = i_ce &&
                                   (free_count > accepted_prefix[lane]);
            assign take[lane] = in_valid[lane] && in_ready[lane];
            assign accepted_prefix[lane + 32'd1] =
                accepted_prefix[lane] + (take[lane] ? 32'd1 : 32'd0);
            assign write_address[lane] = ring_add(write_ptr,
                                                  accepted_prefix[lane]);
        end
    endgenerate

    assign out_empty = free_count == capacity_limit;
    assign out_data = bank_mem[read_ptr % WRITE_PORTS]
                              [read_ptr / WRITE_PORTS];

    integer init_bank;
    integer init_row;
    initial begin
        used_count = 32'd0;
        free_count = DEPTH;
        write_ptr = 32'd0;
        read_ptr = 32'd0;
        past_valid = 1'b0;
        for (init_bank = 32'd0; init_bank < WRITE_PORTS;
             init_bank = init_bank + 32'd1)
            for (init_row = 32'd0; init_row < BANK_ROWS;
                 init_row = init_row + 32'd1)
                bank_mem[init_bank][init_row] = 32'd0;
    end

    integer port_index;
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            used_count <= used_count + write_count -
                          (do_read ? 32'd1 : 32'd0);
            free_count <= free_count - write_count +
                          (do_read ? 32'd1 : 32'd0);
            write_ptr <= ring_add(write_ptr, write_count);
            if (do_read)
                read_ptr <= ring_add(read_ptr, 32'd1);
            for (port_index = 32'd0; port_index < WRITE_PORTS;
                 port_index = port_index + 32'd1)
                if (take[port_index])
                    bank_mem[write_address[port_index] % WRITE_PORTS]
                            [write_address[port_index] / WRITE_PORTS]
                        <= in_data[port_index*32'd32 +: 32];
        end
    end

    // The fixed capacity starts with over_capacity false. Keeping that
    // predicate unchanged expresses the global bound used_count <= DEPTH.
    always @(posedge clk) begin
        if (past_valid && $stable(capacity_limit))
            assert ($stable(over_capacity));
    end
endmodule

module packed_minifloat_adder #(
    parameter integer LANES = 32
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_ce,
    input  wire scope_begin,
    input  wire scope_end,
    input  wire request,
    input  wire [7:0] i_lane_mode,
    input  wire [LANES*8-1:0] i_a,
    input  wire [LANES*8-1:0] i_b,
    output wire o_busy,
    output wire o_result_valid,
    output wire [LANES*8-1:0] o_result,
    output wire [LANES*8-1:0] o_flags
);
    // Unsigned finite E4M4 minifloats: exponent zero denotes subnormals.
    // All other exponents are finite; overflow saturates to 8'hff.
    // mode[0]: operate on the lower half only, zeroing other lanes.
    // mode[1]: round to nearest, ties to even; otherwise truncate.
    // Countdown units are enabled pipeline cycles.
    reg window_open;
    reg busy;
    reg [7:0] countdown;
    reg [7:0] lane_mode;
    reg [LANES*8-1:0] lane_phase;
    reg [LANES*8-1:0] exponent_a, exponent_b;
    reg [LANES*8-1:0] significand_a, significand_b;
    reg [LANES*8-1:0] lane_sum;
    reg [LANES*8-1:0] lane_result;
    // Each flag byte contains ready[7], inexact[1], overflow[0].
    reg [LANES*8-1:0] lane_flags;

    wire [LANES-1:0] lane_ready;
    wire [LANES-1:0] sum_in_range;
    // Each 16-bit slice is a pair of independent eight-bit words.
    wire [LANES*16-1:0] finished_words;

    function automatic [7:0] shift_jam;
        input [7:0] value;
        input [7:0] distance;
        reg [7:0] mask;
        begin
            mask = 8'd0;
            if (distance == 8'd0)
                shift_jam = value;
            else if (distance >= 8'd8)
                shift_jam = {7'd0, (|value)};
            else begin
                mask = 8'hff >> (8'd8 - distance);
                shift_jam = (value >> distance) |
                            {7'd0, (|(value & mask))};
            end
        end
    endfunction

    function automatic [15:0] finish_add;
        input [7:0] input_exp;
        input [7:0] input_sum;
        input [7:0] mode;
        reg [7:0] e;
        reg [7:0] m;
        reg [7:0] flags;
        reg [7:0] packed_value;
        begin
            e = input_exp;
            m = input_sum;
            flags = 8'h80;
            if (m[7]) begin
                m = (m >> 8'd1) | {7'd0, m[0]};
                e = e + 8'd1;
            end
            flags[1] = |m[1:0];
            if (mode[1] && m[1] && (m[0] || m[2]))
                m = m + 8'd4;
            if (m[7]) begin
                m = m >> 8'd1;
                e = e + 8'd1;
            end
            if (e > 8'd15) begin
                packed_value = 8'hff;
                flags[1:0] = 2'b11;
            end else if ((e == 8'd1) && !m[6]) begin
                packed_value = {4'd0, m[5:2]};
            end else begin
                packed_value = {e[3:0], m[5:2]};
            end
            finish_add = {flags, packed_value};
        end
    endfunction

    genvar g;
    generate
        for (g = 0; g < LANES; g = g + 1) begin : lane_wiring
            assign lane_ready[g] = lane_flags[g*8+7];
            assign sum_in_range[g] = lane_sum[g*8 +: 8] <= 8'd254;
            assign finished_words[g*16 +: 16] = finish_add(
                exponent_a[g*8 +: 8], lane_sum[g*8 +: 8], lane_mode);
        end
    endgenerate

    assign o_busy = busy;
    assign o_result_valid = &lane_ready;
    assign o_result = lane_result;
    assign o_flags = lane_flags;

    initial begin
        window_open = 1'b0;
        busy = 1'b0;
        countdown = 8'd0;
        lane_mode = 8'd0;
        lane_phase = {LANES{8'd0}};
        exponent_a = {LANES{8'd0}};
        exponent_b = {LANES{8'd0}};
        significand_a = {LANES{8'd0}};
        significand_b = {LANES{8'd0}};
        lane_sum = {LANES{8'd0}};
        lane_result = {LANES{8'd0}};
        lane_flags = {LANES{8'd0}};
    end

    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            window_open <= 1'b0;
            busy <= 1'b0;
            countdown <= 8'd0;
            lane_mode <= 8'd0;
            lane_phase <= {LANES{8'd0}};
            exponent_a <= {LANES{8'd0}};
            exponent_b <= {LANES{8'd0}};
            significand_a <= {LANES{8'd0}};
            significand_b <= {LANES{8'd0}};
            lane_sum <= {LANES{8'd0}};
            lane_result <= {LANES{8'd0}};
            lane_flags <= {LANES{8'd0}};
        end else if (i_ce) begin
            if (scope_end)
                window_open <= 1'b0;
            else if (scope_begin)
                window_open <= 1'b1;

            if (!busy) begin
                if (window_open && request) begin
                    busy <= 1'b1;
                    countdown <= 8'd4;
                    lane_mode <= i_lane_mode;
                    for (i = 0; i < LANES; i = i + 1) begin
                        lane_phase[i*8 +: 8] <= 8'd1;
                        lane_flags[i*8 +: 8] <= 8'd0;
                        exponent_a[i*8 +: 8] <=
                            (i_a[i*8+4 +: 4] == 4'd0) ? 8'd1 :
                            {4'd0, i_a[i*8+4 +: 4]};
                        exponent_b[i*8 +: 8] <=
                            (i_b[i*8+4 +: 4] == 4'd0) ? 8'd1 :
                            {4'd0, i_b[i*8+4 +: 4]};
                        significand_a[i*8 +: 8] <=
                            {1'b0, (|i_a[i*8+4 +: 4]),
                             i_a[i*8 +: 4], 2'b00};
                        significand_b[i*8 +: 8] <=
                            {1'b0, (|i_b[i*8+4 +: 4]),
                             i_b[i*8 +: 4], 2'b00};
                    end
                end
            end else if (&lane_ready) begin
                // Retire only when every parallel lane has finished.
                busy <= 1'b0;
                countdown <= 8'd0;
                lane_phase <= {LANES{8'd0}};
                for (i = 0; i < LANES; i = i + 1)
                    lane_flags[i*8+7] <= 1'b0;
            end else begin
                if (countdown != 8'd0)
                    countdown <= countdown - 8'd1;
                for (i = 0; i < LANES; i = i + 1) begin
                    case (lane_phase[i*8 +: 8])
                        8'd1: begin
                            // Align each lane independently.
                            if (lane_mode[0] && (i >= LANES/2)) begin
                                exponent_a[i*8 +: 8] <= 8'd1;
                                significand_a[i*8 +: 8] <= 8'd0;
                                significand_b[i*8 +: 8] <= 8'd0;
                            end else if (exponent_a[i*8 +: 8] >=
                                         exponent_b[i*8 +: 8]) begin
                                significand_b[i*8 +: 8] <= shift_jam(
                                    significand_b[i*8 +: 8],
                                    exponent_a[i*8 +: 8] -
                                    exponent_b[i*8 +: 8]);
                            end else begin
                                significand_a[i*8 +: 8] <= shift_jam(
                                    significand_a[i*8 +: 8],
                                    exponent_b[i*8 +: 8] -
                                    exponent_a[i*8 +: 8]);
                                exponent_a[i*8 +: 8] <= exponent_b[i*8 +: 8];
                            end
                            lane_phase[i*8 +: 8] <= 8'd2;
                        end
                        8'd2: begin
                            // Two seven-bit aligned significands fit in one byte.
                            lane_sum[i*8 +: 8] <= significand_a[i*8 +: 8] +
                                                  significand_b[i*8 +: 8];
                            lane_phase[i*8 +: 8] <= 8'd3;
                        end
                        8'd3: begin
                            // Normalize, round, and publish the per-lane flags.
                            lane_result[i*8 +: 8] <= finished_words[i*16 +: 8];
                            lane_flags[i*8 +: 8] <= finished_words[i*16+8 +: 8];
                            lane_phase[i*8 +: 8] <= 8'd4;
                        end
                        default: begin end
                    endcase
                end
            end
        end
    end

    always @(*) begin
        if (window_open)
            assert (!(busy && (countdown == 8'd0)));
    end
endmodule

module staged_composite_sbox #(
    parameter integer BYTE_W = 8
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [BYTE_W-1:0]     i_cmd,
    input  wire [BYTE_W-1:0]     i_byte,
    output wire                  o_valid,
    input  wire                  o_ready,
    output wire [BYTE_W-1:0]     o_byte
);
    // AES uses eight-bit bytes and four-bit subfield elements.
    localparam integer SUBFIELD_W = BYTE_W / 2;
    localparam [BYTE_W-1:0] CMD_ARM     = 8'd0;
    localparam [BYTE_W-1:0] CMD_START   = 8'd1;
    localparam [BYTE_W-1:0] CMD_FINISH  = 8'd2;
    localparam [BYTE_W-1:0] CMD_SIGNOFF = 8'd3;
    localparam [BYTE_W-1:0] PH_IDLE    = 8'd0;
    localparam [BYTE_W-1:0] PH_ARMED   = 8'd1;
    localparam [BYTE_W-1:0] PH_STARTED = 8'd2;
    localparam [BYTE_W-1:0] PH_HOLD    = 8'd3;
    localparam [BYTE_W-1:0] GF16_POLY = 8'h13;
    localparam [BYTE_W-1:0] TOWER_LAMBDA = 8'h08;

    // GF(16) is defined by t^4 + t + 1. Subfield values are
    // carried in the low nibble of an eight-bit datapath word.
    function automatic [BYTE_W-1:0] gf16_mul;
        input [BYTE_W-1:0] x;
        input [BYTE_W-1:0] y;
        reg [BYTE_W-1:0] a, b, p;
        integer j;
        begin
            a = x & 8'h0f;
            b = y & 8'h0f;
            p = 8'h00;
            for (j = 0; j < SUBFIELD_W; j = j + 1) begin
                if (b[0])
                    p = p ^ a;
                if (a[SUBFIELD_W-1])
                    a = (a << 1) ^ GF16_POLY;
                else
                    a = a << 1;
                b = b >> 1;
            end
            gf16_mul = p;
        end
    endfunction

    function automatic [BYTE_W-1:0] gf16_inverse;
        input [BYTE_W-1:0] x;
        reg [BYTE_W-1:0] q2, q4, q8;
        begin
            q2 = gf16_mul(x, x);
            q4 = gf16_mul(q2, q2);
            q8 = gf16_mul(q4, q4);
            gf16_inverse = gf16_mul(q8, gf16_mul(q4, q2));
        end
    endfunction

    // A tower byte represents a + b*u, with a in the low nibble,
    // b in the high nibble, and u^2 + u + 8 = 0 over GF(16).
    // The AES polynomial basis generator maps to tower byte 8'h20.
    // These columns are its successive powers, starting with one.
    function automatic [BYTE_W-1:0] aes_to_tower;
        input [BYTE_W-1:0] x;
        reg [BYTE_W-1:0] y;
        begin
            y = 8'h00;
            if (x[0]) y = y ^ 8'h01;
            if (x[1]) y = y ^ 8'h20;
            if (x[2]) y = y ^ 8'h46;
            if (x[3]) y = y ^ 8'h4c;
            if (x[4]) y = y ^ 8'h3c;
            if (x[5]) y = y ^ 8'hd5;
            if (x[6]) y = y ^ 8'h34;
            if (x[7]) y = y ^ 8'he5;
            aes_to_tower = y;
        end
    endfunction

    function automatic [BYTE_W-1:0] tower_to_aes;
        input [BYTE_W-1:0] y;
        reg [BYTE_W-1:0] x;
        begin
            x = 8'h00;
            x[0] = y[0] ^ y[7];
            x[1] = y[5] ^ y[7] ^ y[4];
            x[2] = y[1];
            x[3] = y[6] ^ y[1] ^ y[7];
            x[4] = y[3] ^ y[6] ^ y[1] ^ y[7];
            x[5] = y[4] ^ y[6] ^ y[2];
            x[6] = y[2] ^ y[1] ^ y[3] ^ y[7];
            x[7] = y[7] ^ y[4] ^ y[6] ^ y[2];
            tower_to_aes = x;
        end
    endfunction

    function automatic [BYTE_W-1:0] tower_inverse;
        input [BYTE_W-1:0] x;
        reg [BYTE_W-1:0] a, b, norm, norm_inv;
        begin
            a = x & 8'h0f;
            b = (x >> SUBFIELD_W) & 8'h0f;
            norm = gf16_mul(a, a ^ b)
                 ^ gf16_mul(TOWER_LAMBDA, gf16_mul(b, b));
            norm_inv = gf16_inverse(norm);
            tower_inverse = gf16_mul(a ^ b, norm_inv)
                          | (gf16_mul(b, norm_inv) << SUBFIELD_W);
        end
    endfunction

    function automatic [BYTE_W-1:0] aes_affine;
        input [BYTE_W-1:0] x;
        begin
            aes_affine = x
                       ^ {x[6:0], x[7]}
                       ^ {x[5:0], x[7:6]}
                       ^ {x[4:0], x[7:5]}
                       ^ {x[3:0], x[7:4]}
                       ^ 8'h63;
        end
    endfunction

    reg [BYTE_W-1:0] phase;
    reg [BYTE_W-1:0] mapped_byte;
    reg [BYTE_W-1:0] inverted_byte;
    reg [BYTE_W-1:0] result_byte;
    reg [BYTE_W-1:0] completion_count;
    reg arm_seen;
    reg start_seen;
    reg before_signoff;
    reg past_valid;

    wire command_fire;
    wire output_fire;
    wire chain_ready;

    // One byte is resident at a time. Each accepted command advances
    // exactly one arithmetic stage; only ARM consumes i_byte.
    assign i_ready = (i_cmd == CMD_SIGNOFF)
                   || ((phase == PH_IDLE) && (i_cmd == CMD_ARM))
                   || ((phase == PH_ARMED) && (i_cmd == CMD_START))
                   || ((phase == PH_STARTED) && (i_cmd == CMD_FINISH));
    assign command_fire = i_valid && i_ready;
    assign o_valid = (phase == PH_HOLD);
    assign o_byte = result_byte;
    assign output_fire = o_valid && o_ready;
    assign chain_ready = (phase == PH_STARTED) && arm_seen && start_seen;

    initial begin
        phase = PH_IDLE;
        mapped_byte = 8'h00;
        inverted_byte = 8'h00;
        result_byte = 8'h63;
        completion_count = 8'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        before_signoff = 1'b1;
        past_valid = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase <= PH_IDLE;
            mapped_byte <= 8'h00;
            inverted_byte <= 8'h00;
            result_byte <= 8'h63;
            completion_count <= 8'd0;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            before_signoff <= 1'b1;
            past_valid <= 1'b0;
        end else begin
            if (command_fire || output_fire)
                past_valid <= 1'b1;

            // The first accepted SIGNOFF command permanently ends
            // the checking scope, until the next reset.
            if (command_fire && (i_cmd == CMD_SIGNOFF))
                before_signoff <= 1'b0;

            if (output_fire) begin
                phase <= PH_IDLE;
            end else if (command_fire) begin
                case (i_cmd)
                    CMD_ARM: begin
                        mapped_byte <= aes_to_tower(i_byte);
                        arm_seen <= 1'b1;
                        start_seen <= 1'b0;
                        phase <= PH_ARMED;
                    end
                    CMD_START: begin
                        inverted_byte <= tower_inverse(mapped_byte);
                        start_seen <= 1'b1;
                        phase <= PH_STARTED;
                    end
                    CMD_FINISH: begin
                        result_byte <= aes_affine(tower_to_aes(inverted_byte));
                        completion_count <= completion_count + 8'd1;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= PH_HOLD;
                    end
                    default: begin end
                endcase
            end
        end
    end

    // Chain precedence before signoff: completion may change only
    // when an existing arm-then-start authorization is consumed.
    // In particular, unchanged authorization requires no completion
    // change; a newly rising authorization is not sufficient either.
    always @(posedge clk)
        if (past_valid && before_signoff &&
            ($stable(chain_ready) || !$past(chain_ready)))
            assert ($stable(completion_count));
endmodule

module signed_alu_retirement #(
    parameter integer DATA_W = 64
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [DATA_W-1:0]     in_a,
    input  wire [DATA_W-1:0]     in_b,
    input  wire                  in_sub,
    input  wire                  in_checkpoint,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [DATA_W-1:0]     out_result,
    output wire                  out_carry,
    output wire                  out_overflow
);
    reg                          req_valid;
    reg [DATA_W-1:0]             req_a, req_b;
    reg                          req_sub;
    // Shadow of the operand-sign eligibility observed at acceptance.
    reg                          req_eligible;

    // Sticky record of the most recently retired operation.
    reg                          retired_seen;
    reg                          retired_overflow;
    reg                          retired_prior_eligible;
    reg                          before_checkpoint;

    initial begin
        req_valid = 1'b0;
        req_a = {DATA_W{1'b0}};
        req_b = {DATA_W{1'b0}};
        req_sub = 1'b0;
        req_eligible = 1'b1;
        retired_seen = 1'b0;
        retired_overflow = 1'b0;
        retired_prior_eligible = 1'b0;
        before_checkpoint = 1'b1;
    end

    assign out_valid = req_valid;
    assign in_ready = !req_valid || out_ready;
    wire accept = in_valid && in_ready;
    wire retire = out_valid && out_ready;

    // Stateless adder-subtractor: complement B and inject the mode as carry-in.
    wire [DATA_W-1:0] effective_b = req_b ^ {DATA_W{req_sub}};
    wire [DATA_W:0] arithmetic_sum =
        {1'b0, req_a} + {1'b0, effective_b}
        + {{DATA_W{1'b0}}, req_sub};
    assign out_result = arithmetic_sum[DATA_W-1:0];
    assign out_carry = arithmetic_sum[DATA_W];
    assign out_overflow =
        !(req_a[DATA_W-1] ^ effective_b[DATA_W-1]) &&
         (out_result[DATA_W-1] ^ req_a[DATA_W-1]);

    always @(posedge clk) begin
        if (retire) begin
            req_valid <= 1'b0;
            retired_seen <= 1'b1;
            retired_overflow <= out_overflow;
            retired_prior_eligible <= req_eligible;
        end
        // Simultaneous retirement and acceptance replace the occupied slot.
        if (accept) begin
            req_valid <= 1'b1;
            req_a <= in_a;
            req_b <= in_b;
            req_sub <= in_sub;
            req_eligible <= !(in_a[DATA_W-1] ^ in_b[DATA_W-1] ^ in_sub);
            // The first accepted checkpoint permanently ends the scope.
            if (in_checkpoint)
                before_checkpoint <= 1'b0;
        end
    end

    // Before the first checkpoint, a recorded overflow must have been
    // preceded by acceptance of sign-eligible operands.
    always @(*) assert (
        !(before_checkpoint && retired_seen && retired_overflow)
        || retired_prior_eligible
    );
endmodule

module dram_temperature_refresh_adjuster #(
    parameter integer WORD_W = 32,
    parameter [WORD_W-1:0] POLL_CYCLES = 32'd4,
    parameter [WORD_W-1:0] BASE_INTERVAL = 32'd8
) (
    input wire clk,
    input wire i_ce,
    input wire mr_status_valid,
    output wire mr_status_ready,
    output wire mr_poll_request,
    input wire [WORD_W-1:0] mr_temperature,
    output reg [WORD_W-1:0] active_temperature,
    output reg [WORD_W-1:0] active_multiplier,
    output reg [WORD_W-1:0] refresh_interval
);
    reg [WORD_W-1:0] last_temperature;
    reg [WORD_W-1:0] staged_multiplier;
    reg [WORD_W-1:0] poll_timer;
    reg before_trip;

    function [WORD_W-1:0] temperature_multiplier;
        input [WORD_W-1:0] code;
        begin
            case (code & 32'd3)
                32'd0: temperature_multiplier = 32'd1;
                32'd1: temperature_multiplier = 32'd2;
                32'd2: temperature_multiplier = 32'd4;
                default: temperature_multiplier = 32'd8;
            endcase
        end
    endfunction

    function [WORD_W-1:0] temperature_interval;
        input [WORD_W-1:0] code;
        begin
            case (code & 32'd3)
                32'd0: temperature_interval = BASE_INTERVAL;
                32'd1: temperature_interval = BASE_INTERVAL >> 32'd1;
                32'd2: temperature_interval = BASE_INTERVAL >> 32'd2;
                default: temperature_interval = BASE_INTERVAL >> 32'd3;
            endcase
        end
    endfunction

    function [WORD_W-1:0] multiplier_interval;
        input [WORD_W-1:0] multiplier;
        begin
            case (multiplier)
                32'd1: multiplier_interval = BASE_INTERVAL;
                32'd2: multiplier_interval = BASE_INTERVAL >> 32'd1;
                32'd4: multiplier_interval = BASE_INTERVAL >> 32'd2;
                32'd8: multiplier_interval = BASE_INTERVAL >> 32'd3;
                default: multiplier_interval = 32'd0;
            endcase
        end
    endfunction

    initial begin
        last_temperature = 32'd0;
        staged_multiplier = 32'd1;
        poll_timer = 32'd0;
        active_temperature = 32'd0;
        active_multiplier = 32'd1;
        refresh_interval = BASE_INTERVAL;
        before_trip = 1'b1;
    end

    assign mr_status_ready = i_ce && (poll_timer == 32'd0);
    assign mr_poll_request = mr_status_ready;

    // A presented response advances the enabled polling delay. While
    // ready is low, its sender retains valid and the mode-register data.
    // No state moves with i_ce low or with mr_status_valid low.
    always @(posedge clk) begin
        if (i_ce && mr_status_valid) begin
            if (poll_timer != 32'd0) begin
                poll_timer <= poll_timer - 32'd1;
            end else if (mr_status_ready) begin
                poll_timer <= POLL_CYCLES - 32'd1;

                // Sample the new status and its decoded policy together.
                last_temperature <= mr_temperature;
                staged_multiplier <= temperature_multiplier(mr_temperature);

                // Apply the preceding sampled policy, giving one poll
                // of pipeline latency between sampling and application.
                active_temperature <= last_temperature;
                active_multiplier <= staged_multiplier;
                refresh_interval <= temperature_interval(last_temperature);

                // The first accepted thermal-trip report ends the scope.
                if (mr_temperature[WORD_W-1])
                    before_trip <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (before_trip) begin
            assert (active_multiplier == temperature_multiplier(active_temperature));
            assert (refresh_interval == multiplier_interval(active_multiplier));
        end
    end
endmodule

module dma_descriptor_chain #(
    parameter WORD_W = 32
) (
    input wire clk,
    input wire i_ce,
    input wire scope_open,
    input wire scope_close,
    input wire arm_request,
    input wire [WORD_W-1:0] descriptor_base,
    input wire [WORD_W-1:0] memory_data,
    output wire [WORD_W-1:0] memory_address,
    output wire [WORD_W-1:0] transfer_source,
    output wire [WORD_W-1:0] transfer_destination,
    output wire transfer_active,
    output wire descriptor_finished
);
    localparam [WORD_W-1:0] ST_IDLE   = WORD_W'(32'd0);
    localparam [WORD_W-1:0] ST_SOURCE = WORD_W'(32'd1);
    localparam [WORD_W-1:0] ST_DEST   = WORD_W'(32'd2);
    localparam [WORD_W-1:0] ST_LENGTH = WORD_W'(32'd3);
    localparam [WORD_W-1:0] ST_LINK   = WORD_W'(32'd4);
    localparam [WORD_W-1:0] ST_READY  = WORD_W'(32'd5);
    localparam [WORD_W-1:0] ST_RUN    = WORD_W'(32'd6);
    localparam [WORD_W-1:0] ST_DONE   = WORD_W'(32'd7);
    localparam [WORD_W-1:0] WORD_BYTES = WORD_W'(WORD_W / 32'd8);

    reg [WORD_W-1:0] fetch_state;
    reg [WORD_W-1:0] descriptor_pointer;
    reg [WORD_W-1:0] source_pointer;
    reg [WORD_W-1:0] destination_pointer;
    reg [WORD_W-1:0] transfer_words;
    reg [WORD_W-1:0] next_descriptor;
    reg [WORD_W-1:0] remaining_words;
    reg window;
    reg arm_seen;
    reg start_seen;
    reg pv;

    initial begin
        fetch_state = ST_IDLE;
        descriptor_pointer = WORD_W'(32'd0);
        source_pointer = WORD_W'(32'd0);
        destination_pointer = WORD_W'(32'd0);
        transfer_words = WORD_W'(32'd0);
        next_descriptor = WORD_W'(32'd0);
        remaining_words = WORD_W'(32'd0);
        window = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        pv = 1'b0;
    end

    // Fixed-rate descriptor reads: memory_data supplies the addressed word
    // on each enabled fetch cycle, without a request/response handshake.
    assign memory_address = descriptor_pointer +
        ((fetch_state == ST_DEST)   ? WORD_BYTES :
         (fetch_state == ST_LENGTH) ? WORD_BYTES * WORD_W'(32'd2) :
         (fetch_state == ST_LINK)   ? WORD_BYTES * WORD_W'(32'd3) :
                                     WORD_W'(32'd0));
    assign transfer_source = source_pointer;
    assign transfer_destination = destination_pointer;
    assign transfer_active = window && (fetch_state == ST_RUN);
    assign descriptor_finished = window && (fetch_state == ST_DONE);

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (scope_close) begin
                window <= 1'b0;
                fetch_state <= ST_IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
            end else if (!window) begin
                if (scope_open)
                    window <= 1'b1;
            end else begin
                case (fetch_state)
                    ST_IDLE: begin
                        if (arm_request) begin
                            descriptor_pointer <= descriptor_base;
                            arm_seen <= 1'b1;
                            start_seen <= 1'b0;
                            fetch_state <= ST_SOURCE;
                        end
                    end
                    ST_SOURCE: begin
                        source_pointer <= memory_data;
                        fetch_state <= ST_DEST;
                    end
                    ST_DEST: begin
                        destination_pointer <= memory_data;
                        fetch_state <= ST_LENGTH;
                    end
                    ST_LENGTH: begin
                        transfer_words <= memory_data;
                        fetch_state <= ST_LINK;
                    end
                    ST_LINK: begin
                        next_descriptor <= memory_data;
                        fetch_state <= ST_READY;
                    end
                    ST_READY: begin
                        remaining_words <= transfer_words;
                        start_seen <= 1'b1;
                        fetch_state <= ST_RUN;
                    end
                    ST_RUN: begin
                        if (remaining_words != WORD_W'(32'd0)) begin
                            source_pointer <= source_pointer + WORD_BYTES;
                            destination_pointer <= destination_pointer + WORD_BYTES;
                            remaining_words <= remaining_words - WORD_W'(32'd1);
                        end
                        if (remaining_words <= WORD_W'(32'd1))
                            fetch_state <= ST_DONE;
                    end
                    ST_DONE: begin
                        fetch_state <= ST_IDLE;
                    end
                    default: begin
                        fetch_state <= ST_IDLE;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                    end
                endcase
            end
        end
    end

    // A start requires an earlier arm; a finish requires both earlier steps.
    // Check those prerequisites in the previous sampled cycle.
    always @(posedge clk) begin
        if (pv && window)
            assert (((fetch_state != ST_RUN) || $past(arm_seen)) &&
                    ((fetch_state != ST_DONE) ||
                     ($past(arm_seen) && $past(start_seen))));
    end
endmodule

module video_link_tournament #(
    parameter integer WORD_WIDTH = 32,
    parameter integer ENTRIES = 64
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire line_start,
    input wire line_end,
    input wire req_valid,
    input wire [WORD_WIDTH-1:0] branch_pc,
    input wire resolved_taken,
    output wire req_ready,
    output reg result_valid,
    output reg prediction
);
    localparam [WORD_WIDTH-1:0] ZERO = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] ONE = {{(WORD_WIDTH-1){1'b0}}, 1'b1};
    localparam [WORD_WIDTH-1:0] TWO = ONE << 1'b1;
    localparam [WORD_WIDTH-1:0] THREE = TWO | ONE;
    localparam [WORD_WIDTH-1:0] MAX_COUNT = {WORD_WIDTH{1'b1}};
    localparam [WORD_WIDTH-1:0] INITIAL_COUNTER = {1'b1, {(WORD_WIDTH-1){1'b0}}};
    localparam [WORD_WIDTH-1:0] ENTRY_COUNT = ENTRIES;
    localparam [WORD_WIDTH-1:0] ST_IDLE = ZERO;
    localparam [WORD_WIDTH-1:0] ST_HISTORY = ONE;
    localparam [WORD_WIDTH-1:0] ST_LOCAL = TWO;
    localparam [WORD_WIDTH-1:0] ST_MERGE = THREE;

    reg [WORD_WIDTH-1:0] local_history [0:ENTRIES-1];
    reg [WORD_WIDTH-1:0] local_pattern [0:ENTRIES-1];
    reg [WORD_WIDTH-1:0] global_pattern [0:ENTRIES-1];
    reg [WORD_WIDTH-1:0] chooser [0:ENTRIES-1];
    reg [WORD_WIDTH-1:0] global_history;

    reg line_window;
    reg [WORD_WIDTH-1:0] phase;
    reg local_pending, global_pending;
    reg [WORD_WIDTH-1:0] local_budget, global_budget;
    reg [WORD_WIDTH-1:0] pc_slot, local_slot, global_slot;
    reg actual_taken;
    reg local_prediction, global_prediction, choose_global;

    function automatic [WORD_WIDTH-1:0] train_counter;
        input [WORD_WIDTH-1:0] old_counter;
        input increase;
        begin
            if (increase)
                train_counter = (old_counter == MAX_COUNT) ? MAX_COUNT : old_counter + ONE;
            else
                train_counter = (old_counter == ZERO) ? ZERO : old_counter - ONE;
        end
    endfunction

    assign req_ready = line_window && !line_end && (phase == ST_IDLE);

    initial begin
        global_history = ZERO;
        line_window = 1'b0;
        phase = ST_IDLE;
        local_pending = 1'b0;
        global_pending = 1'b0;
        local_budget = ZERO;
        global_budget = ZERO;
        pc_slot = ZERO;
        local_slot = ZERO;
        global_slot = ZERO;
        actual_taken = 1'b0;
        local_prediction = 1'b0;
        global_prediction = 1'b0;
        choose_global = 1'b0;
        result_valid = 1'b0;
        prediction = 1'b0;
    end

    // Each accepted request launches both predictor-component lookups.
    // Budgets count enabled cycles, so i_ce pauses the entire transaction.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            global_history <= ZERO;
            line_window <= 1'b0;
            phase <= ST_IDLE;
            local_pending <= 1'b0;
            global_pending <= 1'b0;
            local_budget <= ZERO;
            global_budget <= ZERO;
            pc_slot <= ZERO;
            local_slot <= ZERO;
            global_slot <= ZERO;
            actual_taken <= 1'b0;
            local_prediction <= 1'b0;
            global_prediction <= 1'b0;
            choose_global <= 1'b0;
            result_valid <= 1'b0;
            prediction <= 1'b0;
        end else if (i_ce) begin
            if (line_end)
                line_window <= 1'b0;
            else if (line_start)
                line_window <= 1'b1;

            result_valid <= 1'b0;
            if (local_pending && (local_budget != ZERO))
                local_budget <= local_budget - ONE;
            if (global_pending && (global_budget != ZERO))
                global_budget <= global_budget - ONE;

            case (phase)
                ST_IDLE: begin
                    if (req_valid && req_ready) begin
                        pc_slot <= branch_pc % ENTRY_COUNT;
                        global_slot <= global_history % ENTRY_COUNT;
                        actual_taken <= resolved_taken;
                        local_pending <= 1'b1;
                        global_pending <= 1'b1;
                        local_budget <= TWO;
                        global_budget <= ONE;
                        phase <= ST_HISTORY;
                    end
                end
                ST_HISTORY: begin
                    local_slot <= local_history[pc_slot] % ENTRY_COUNT;
                    global_prediction <= global_pattern[global_slot][WORD_WIDTH-1];
                    choose_global <= chooser[pc_slot][WORD_WIDTH-1];
                    global_pending <= 1'b0;
                    global_budget <= ZERO;
                    phase <= ST_LOCAL;
                end
                ST_LOCAL: begin
                    local_prediction <= local_pattern[local_slot][WORD_WIDTH-1];
                    local_pending <= 1'b0;
                    local_budget <= ZERO;
                    phase <= ST_MERGE;
                end
                ST_MERGE: begin
                    prediction <= choose_global ? global_prediction : local_prediction;
                    result_valid <= 1'b1;
                    global_history <= (global_history << 1'b1) |
                                      {{(WORD_WIDTH-1){1'b0}}, actual_taken};
                    phase <= ST_IDLE;
                end
                default: begin
                end
            endcase
        end
    end

    // Independent entries retain full-width saturating prediction counters.
    genvar entry;
    generate
        for (entry = 0; entry < ENTRIES; entry = entry + 1) begin : g_tables
            localparam [WORD_WIDTH-1:0] SLOT = entry;
            initial begin
                local_history[entry] = ZERO;
                local_pattern[entry] = INITIAL_COUNTER;
                global_pattern[entry] = INITIAL_COUNTER;
                chooser[entry] = INITIAL_COUNTER;
            end

            always @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    local_history[entry] <= ZERO;
                    local_pattern[entry] <= INITIAL_COUNTER;
                    global_pattern[entry] <= INITIAL_COUNTER;
                    chooser[entry] <= INITIAL_COUNTER;
                end else if (i_ce) begin
                    if (phase == ST_MERGE) begin
                        if (pc_slot == SLOT) begin
                            local_history[entry] <= (local_history[entry] << 1'b1) |
                                                    {{(WORD_WIDTH-1){1'b0}}, actual_taken};
                            if (local_prediction != global_prediction)
                                chooser[entry] <= train_counter(chooser[entry],
                                                               global_prediction == actual_taken);
                        end
                        if (local_slot == SLOT)
                            local_pattern[entry] <= train_counter(local_pattern[entry], actual_taken);
                        if (global_slot == SLOT)
                            global_pattern[entry] <= train_counter(global_pattern[entry], actual_taken);
                    end
                end
            end
        end
    endgenerate

    // Between line_start and line_end, neither component request may
    // remain outstanding when its enabled-cycle deadline expires.
    always @(posedge clk) begin
        if (line_window) begin
            assert (!local_pending || (local_budget != ZERO));
            assert (!global_pending || (global_budget != ZERO));
        end
    end
endmodule

module shared_wishbone_chain #(
    parameter integer MASTERS = 16,
    parameter integer SLAVES = 16,
    parameter integer DATA_WIDTH = 16
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_memory_ready,
    input  wire [MASTERS-1:0] i_master_cyc,
    input  wire [MASTERS-1:0] i_master_stb,
    input  wire [MASTERS-1:0] i_master_we,
    input  wire [MASTERS*DATA_WIDTH-1:0] i_master_addr,
    input  wire [MASTERS*DATA_WIDTH-1:0] i_master_wdata,
    input  wire [SLAVES-1:0] i_slave_ack,
    input  wire [SLAVES*DATA_WIDTH-1:0] i_slave_rdata,
    output wire [MASTERS-1:0] o_master_ack,
    output wire [DATA_WIDTH-1:0] o_master_rdata,
    output wire [SLAVES-1:0] o_slave_cyc,
    output wire [SLAVES-1:0] o_slave_stb,
    output wire o_bus_we,
    output wire [DATA_WIDTH-1:0] o_bus_addr,
    output wire [DATA_WIDTH-1:0] o_bus_wdata
);
    localparam [15:0] MASTER_COUNT = MASTERS;
    localparam [15:0] PH_ARMED = 16'd0;
    localparam [15:0] PH_RUN   = 16'd1;
    localparam [15:0] PH_DONE  = 16'd2;
    localparam integer SLAVE_BITS = (SLAVES > 16'd1) ? $clog2(SLAVES) : 16'd1;

    reg [15:0] current_owner;
    reg cycle_active;
    reg [15:0] phase;
    reg [MASTERS-1:0] armed_mask;
    reg [MASTERS-1:0] started_mask;
    reg [MASTERS-1:0] finished_mask;
    reg [DATA_WIDTH-1:0] return_data;
    reg scope_armed;

    reg [15:0] selected_master;
    reg any_request;
    integer m;

    wire [MASTERS-1:0] owner_mask =
        {{(MASTERS-1){1'b0}}, 1'b1} << current_owner;
    wire [MASTERS-1:0] selected_mask =
        {{(MASTERS-1){1'b0}}, 1'b1} << selected_master;

    // Fixed-priority arbitration is used only when the bus is unowned.
    always @* begin
        selected_master = 16'd0;
        any_request = 1'b0;
        for (m = 16'd0; m < MASTERS; m = m + 16'd1) begin
            if (!any_request && i_master_cyc[m]) begin
                selected_master = m;
                any_request = 1'b1;
            end
        end
    end

    // Address and data are shared; CYC and STB select one slave.
    assign o_bus_addr = cycle_active ?
        i_master_addr[current_owner*DATA_WIDTH +: DATA_WIDTH] :
        {DATA_WIDTH{1'b0}};
    assign o_bus_wdata = cycle_active ?
        i_master_wdata[current_owner*DATA_WIDTH +: DATA_WIDTH] :
        {DATA_WIDTH{1'b0}};
    assign o_bus_we = cycle_active && i_master_we[current_owner];

    wire [15:0] slave_index =
        (o_bus_addr >> (DATA_WIDTH-SLAVE_BITS)) % SLAVES;
    wire [SLAVES-1:0] slave_mask =
        {{(SLAVES-1){1'b0}}, 1'b1} << slave_index;

    assign o_slave_cyc = (cycle_active && i_master_cyc[current_owner]) ?
        slave_mask : {SLAVES{1'b0}};
    assign o_slave_stb = (cycle_active &&
        i_master_cyc[current_owner] && (phase == PH_RUN)) ?
        slave_mask : {SLAVES{1'b0}};
    assign o_master_ack = finished_mask & i_master_cyc;
    assign o_master_rdata = return_data;

    initial begin
        current_owner = 16'd0;
        cycle_active = 1'b0;
        phase = PH_ARMED;
        armed_mask = {MASTERS{1'b0}};
        started_mask = {MASTERS{1'b0}};
        finished_mask = {MASTERS{1'b0}};
        return_data = {DATA_WIDTH{1'b0}};
        scope_armed = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Q permanently opens the property scope.
            if (i_memory_ready)
                scope_armed <= 1'b1;

            if (!cycle_active) begin
                if (any_request) begin
                    current_owner <= selected_master;
                    cycle_active <= 1'b1;
                    phase <= PH_ARMED;
                    armed_mask <= selected_mask;
                    started_mask <= {MASTERS{1'b0}};
                    finished_mask <= {MASTERS{1'b0}};
                end
            end else if (!i_master_cyc[current_owner]) begin
                cycle_active <= 1'b0;
                phase <= PH_ARMED;
                armed_mask <= {MASTERS{1'b0}};
                started_mask <= {MASTERS{1'b0}};
                finished_mask <= {MASTERS{1'b0}};
            end else begin
                // Ownership cannot change while the owner's CYC remains high.
                case (phase)
                    PH_ARMED: begin
                        if (i_master_stb[current_owner]) begin
                            phase <= PH_RUN;
                            started_mask <= owner_mask;
                        end
                    end
                    PH_RUN: begin
                        if (i_slave_ack[slave_index]) begin
                            phase <= PH_DONE;
                            finished_mask <= owner_mask;
                            return_data <= i_slave_rdata[slave_index*DATA_WIDTH +: DATA_WIDTH];
                        end
                    end
                    PH_DONE: begin
                        // Completion remains recorded until CYC is released.
                    end
                    default: begin
                        // Illegal phase encodings hold their state.
                    end
                endcase
            end
        end
    end

    // Per-owner chain precedence: reserve, then start, then finish.
    assert property (!scope_armed ||
        (((started_mask & ~armed_mask) == {MASTERS{1'b0}}) &&
         ((finished_mask & ~started_mask) == {MASTERS{1'b0}})));
endmodule

module panel_request_encoder #(
    parameter CHANNELS = 32,
    parameter WORD_W = 16
) (
    input wire clk,
    input wire i_ce,
    input wire i_begin,
    input wire i_end,
    input wire i_load_limit,
    input wire [WORD_W-1:0] i_limit,
    input wire i_sample,
    input wire [CHANNELS-1:0] i_lines,
    input wire i_commit,
    input wire i_release,
    output reg [WORD_W-1:0] last_index,
    output reg last_error,
    output reg [WORD_W-1:0] used_count,
    output reg scope_active
);
    localparam [WORD_W-1:0] WORD_ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] WORD_ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] CHANNEL_LIMIT = CHANNELS;
    localparam [CHANNELS-1:0] LINE_ZERO = {CHANNELS{1'b0}};
    localparam [CHANNELS-1:0] LINE_ONE = {{(CHANNELS-1){1'b0}}, 1'b1};

    reg [WORD_W-1:0] admission_limit;
    reg [CHANNELS-1:0] sampled_lines;
    reg [CHANNELS-1:0] pending;

    wire input_onehot;
    wire sampled_onehot;
    wire [CHANNELS-1:0] selected_line;
    reg [WORD_W-1:0] encoded_index;
    integer scan;

    assign input_onehot = (i_lines != LINE_ZERO) &&
                          ((i_lines & (i_lines - LINE_ONE)) == LINE_ZERO);
    assign sampled_onehot = (sampled_lines != LINE_ZERO) &&
                            ((sampled_lines & (sampled_lines - LINE_ONE)) == LINE_ZERO);
    assign selected_line = LINE_ONE << last_index;

    always @(*) begin
        encoded_index = WORD_ZERO;
        for (scan = 0; scan < CHANNELS; scan = scan + 1) begin
            if (i_lines[scan])
                encoded_index = scan;
        end
    end

    // Combinational population sum of the pending-channel scoreboard.
    wire [WORD_W-1:0] population_prefix [0:CHANNELS];
    wire [WORD_W-1:0] pending_population;
    assign population_prefix[0] = WORD_ZERO;
    genvar g;
    generate
        for (g = 0; g < CHANNELS; g = g + 1) begin : population_sum
            assign population_prefix[g+1] = population_prefix[g] +
                {{(WORD_W-1){1'b0}}, pending[g]};
        end
    endgenerate
    assign pending_population = population_prefix[CHANNELS];

    initial begin
        last_index = WORD_ZERO;
        last_error = 1'b1;
        used_count = WORD_ZERO;
        scope_active = 1'b0;
        admission_limit = CHANNEL_LIMIT;
        sampled_lines = LINE_ZERO;
        pending = LINE_ZERO;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_end)
                scope_active <= 1'b0;
            else if (i_begin)
                scope_active <= 1'b1;

            if (i_load_limit)
                admission_limit <= i_limit;

            // Invalid samples update the error bit but retain the last index.
            if (i_sample) begin
                sampled_lines <= i_lines;
                last_error <= !input_onehot;
                if (input_onehot)
                    last_index <= encoded_index;
            end

            // Commit consumes the previously registered encoder result.
            if (i_commit && !last_error) begin
                if (i_release) begin
                    if ((pending & selected_line) != LINE_ZERO) begin
                        pending <= pending & ~selected_line;
                        used_count <= used_count - WORD_ONE;
                    end
                end else begin
                    if (((pending & selected_line) == LINE_ZERO) &&
                        (used_count < admission_limit)) begin
                        pending <= pending | selected_line;
                        used_count <= used_count + WORD_ONE;
                    end
                end
            end
        end
    end

    always @(*) begin
        if (scope_active)
            assert (used_count <= CHANNEL_LIMIT);
    end
endmodule

module message_packetizer #(
    parameter [31:0] PAYLOAD_WORDS = 32'd16
) (
    input  wire clk,
    input  wire i_ce,
    input  wire core_valid,
    input  wire [(32'd32 * PAYLOAD_WORDS)-32'd1:0] core_words,
    input  wire net_ready,
    output wire core_ready,
    output wire flit_valid,
    output wire [31:0] flit_data,
    output wire packet_done
);

    typedef enum logic [2:0] {
        IDLE    = 3'd0,
        ARMED   = 3'd1,
        PAYLOAD = 3'd2,
        FINISH  = 3'd3
    } state_t;

    state_t state;
    reg [31:0] pending_message [0:PAYLOAD_WORDS-32'd1];
    reg [31:0] flit_index;
    reg [31:0] assigned_psn;
    reg [31:0] next_psn;
    reg pending_valid;
    reg header_sent;

    initial begin
        state         = IDLE;
        flit_index    = 32'd0;
        assigned_psn  = 32'd0;
        next_psn      = 32'd0;
        pending_valid = 1'b0;
        header_sent   = 1'b0;
    end

    assign core_ready = i_ce && (state == IDLE) && !pending_valid;
    assign flit_valid = i_ce && ((state == ARMED) || (state == PAYLOAD));
    assign packet_done = (state == FINISH);

    // Index zero denotes the sequence-number header; subsequent indices
    // address the captured message's 32-bit payload words.
    assign flit_data = (state == ARMED) ? assigned_psn :
                       (state == PAYLOAD) ? pending_message[flit_index - 32'd1] :
                       32'd0;

    genvar word_number;
    generate
        for (word_number = 32'd0; word_number < PAYLOAD_WORDS;
             word_number = word_number + 32'd1) begin : message_words
            initial pending_message[word_number] = 32'd0;
            always @(posedge clk) begin
                if (core_ready && core_valid)
                    pending_message[word_number] <=
                        core_words[32'd32 * word_number +: 32];
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                IDLE: begin
                    // Arm: reserve the pending message and its packet number.
                    if (core_valid && !pending_valid) begin
                        pending_valid <= 1'b1;
                        header_sent   <= 1'b0;
                        assigned_psn  <= next_psn;
                        flit_index    <= 32'd0;
                        state         <= ARMED;
                    end
                end
                ARMED: begin
                    // Start: the network accepts the header before any payload.
                    if (net_ready) begin
                        header_sent <= 1'b1;
                        flit_index  <= 32'd1;
                        state       <= PAYLOAD;
                    end
                end
                PAYLOAD: begin
                    if (net_ready) begin
                        flit_index <= flit_index + 32'd1;
                        if (flit_index == PAYLOAD_WORDS)
                            state <= FINISH;
                    end
                end
                FINISH: begin
                    // Retire the message only after reporting completion.
                    pending_valid <= 1'b0;
                    header_sent   <= 1'b0;
                    flit_index    <= 32'd0;
                    next_psn      <= next_psn + 32'd1;
                    state         <= IDLE;
                end
                default: begin
                    state         <= IDLE;
                    pending_valid <= 1'b0;
                    header_sent   <= 1'b0;
                    flit_index    <= 32'd0;
                end
            endcase
        end
    end

    // Chain precedence: start requires an armed message, and finish
    // requires both that reservation and the earlier header acceptance.
    always @(posedge clk)
        if (header_sent || (state == FINISH))
            assert (pending_valid && ((state != FINISH) || header_sent));

endmodule

module rsa_crt_recombination #(
    parameter WORD_W = 128
) (
    input wire clk,
    input wire i_ce,
    input wire i_capture,
    input wire i_publish,
    input wire [WORD_W-1:0] i_residue_p,
    input wire [WORD_W-1:0] i_residue_q,
    output reg [WORD_W-1:0] result_word
);
    // Scaled fixed-key CRT arithmetic with word-sized storage.
    // p=17, q=13, and qInv=4 because 13*4 mod 17 = 1.
    localparam [WORD_W-1:0] MOD_P = {{(WORD_W-5){1'b0}}, 5'd17};
    localparam [WORD_W-1:0] MOD_Q = {{(WORD_W-4){1'b0}}, 4'd13};
    localparam [WORD_W-1:0] Q_INV = {{(WORD_W-3){1'b0}}, 3'd4};
    localparam [WORD_W-1:0] MOD_N = {{(WORD_W-8){1'b0}}, 8'd221};
    localparam [WORD_W-1:0] ZERO_WORD = {WORD_W{1'b0}};

    reg [WORD_W-1:0] residue_p;
    reg [WORD_W-1:0] residue_q;
    reg [WORD_W-1:0] q_inv;
    reg [WORD_W-1:0] garner_h;
    reg window_open;

    // Noncanonical input words are replaced with zero, without assumptions.
    wire [4:0] captured_p = (i_residue_p < MOD_P)
                            ? i_residue_p[4:0] : 5'd0;
    wire [3:0] captured_q = (i_residue_q < MOD_Q)
                            ? i_residue_q[3:0] : 4'd0;

    // h = ((m_p + p - m_q) * qInv) mod p.
    // Nine scratch bits suffice for these fixed primes and coefficient.
    wire [8:0] garner_product =
        (9'd17 + {4'd0, captured_p} - {5'd0, captured_q})
        * {6'd0, q_inv[2:0]};
    wire [8:0] captured_h = garner_product % 9'd17;

    initial begin
        residue_p = ZERO_WORD;
        residue_q = ZERO_WORD;
        q_inv = Q_INV;
        garner_h = ZERO_WORD;
        result_word = ZERO_WORD;
        window_open = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_capture) begin
                residue_p <= {{(WORD_W-5){1'b0}}, captured_p};
                residue_q <= {{(WORD_W-4){1'b0}}, captured_q};
                q_inv <= Q_INV;
                garner_h <= {{(WORD_W-9){1'b0}}, captured_h};
                // Capturing another pair ends the inspection window.
                window_open <= 1'b0;
            end else if (i_publish) begin
                // Garner recombination: m = m_q + q*h.
                result_word <= residue_q + MOD_Q * garner_h;
                // Publishing opens the window until the next capture.
                window_open <= 1'b1;
            end
        end
    end

    // The bound makes the byte-sized remainder checks equivalent to
    // checking the complete stored output against both CRT residues.
    assert property (!window_open ||
        ((result_word < MOD_N) &&
         (residue_p == {{(WORD_W-8){1'b0}},
                         (result_word[7:0] % 8'd17)}) &&
         (residue_q == {{(WORD_W-8){1'b0}},
                         (result_word[7:0] % 8'd13)})));
endmodule

module chien_scan_engine #(
    parameter integer COEFFS = 16
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [8*COEFFS-1:0]   i_coeffs,
    output reg                   o_valid,
    input  wire                  o_ready,
    output reg  [7:0]            o_position,
    output reg  [7:0]            o_value,
    output reg                   o_root
);
    // GF(256), with primitive polynomial x^8+x^4+x^3+x^2+1.
    function automatic [7:0] xtime;
        input [7:0] a;
        begin
            xtime = {a[6:0], 1'b0} ^ (a[7] ? 8'h1d : 8'h00);
        end
    endfunction

    function automatic [7:0] gf_mul;
        input [7:0] a;
        input [7:0] b;
        reg [7:0] aa, bb, product;
        integer k;
        begin
            aa = a;
            bb = b;
            product = 8'h00;
            for (k = 0; k < 8; k = k + 1) begin
                if (bb[0])
                    product = product ^ aa;
                aa = xtime(aa);
                bb = {1'b0, bb[7:1]};
            end
            gf_mul = product;
        end
    endfunction

    function automatic [7:0] alpha_power;
        input integer exponent;
        reg [7:0] value;
        integer k;
        begin
            value = 8'h01;
            for (k = 0; k < exponent; k = k + 1)
                value = xtime(value);
            alpha_power = value;
        end
    endfunction

    reg [7:0] terms [0:COEFFS-1];
    wire [7:0] next_terms [0:COEFFS-1];
    reg [7:0] eval_cache;
    reg [7:0] scan_position;
    reg window;

    reg [7:0] load_sum;
    reg [7:0] term_sum;
    reg [7:0] next_sum;
    integer reduction_index;

    genvar lane;
    generate
        for (lane = 0; lane < COEFFS; lane = lane + 1) begin : multipliers
            assign next_terms[lane] =
                gf_mul(terms[lane], alpha_power(lane));
        end
    endgenerate

    always @(*) begin
        load_sum = 8'h00;
        term_sum = 8'h00;
        next_sum = 8'h00;
        for (reduction_index = 0; reduction_index < COEFFS;
             reduction_index = reduction_index + 1) begin
            load_sum = load_sum ^ i_coeffs[8*reduction_index +: 8];
            term_sum = term_sum ^ terms[reduction_index];
            next_sum = next_sum ^ next_terms[reduction_index];
        end
    end

    // A polynomial cannot be replaced while its result stream is pending.
    assign i_ready = !o_valid;

    integer init_index;
    initial begin
        o_valid = 1'b0;
        o_position = 8'h00;
        o_value = 8'h00;
        o_root = 1'b1;
        eval_cache = 8'h00;
        scan_position = 8'h01;
        window = 1'b0;
        for (init_index = 0; init_index < COEFFS; init_index = init_index + 1)
            terms[init_index] = 8'h00;
    end

    integer state_index;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_valid <= 1'b0;
            o_position <= 8'h00;
            o_value <= 8'h00;
            o_root <= 1'b1;
            eval_cache <= 8'h00;
            scan_position <= 8'h01;
            window <= 1'b0;
            for (state_index = 0; state_index < COEFFS;
                 state_index = state_index + 1)
                terms[state_index] <= 8'h00;
        end else if (i_valid && i_ready) begin
            // Q: open the checking window and report the zero field element.
            window <= 1'b1;
            o_valid <= 1'b1;
            o_position <= 8'h00;
            o_value <= i_coeffs[0 +: 8];
            o_root <= (i_coeffs[0 +: 8] == 8'h00);
            scan_position <= 8'h01;
            eval_cache <= load_sum;
            for (state_index = 0; state_index < COEFFS;
                 state_index = state_index + 1)
                terms[state_index] <= i_coeffs[8*state_index +: 8];
        end else if (o_valid && o_ready) begin
            if (o_position == 8'hff) begin
                // Close only after the final result is accepted.
                o_valid <= 1'b0;
                window <= 1'b0;
            end else begin
                // Positions 1..255 enumerate alpha^0 through alpha^254.
                o_position <= scan_position;
                scan_position <= scan_position + 8'h01;
                // Cached reduction drives root detection; the payload also
                // captures an independent reduction of the coefficient lanes.
                o_root <= (eval_cache == 8'h00);
                o_value <= term_sum;
                eval_cache <= next_sum;
                for (state_index = 0; state_index < COEFFS;
                     state_index = state_index + 1)
                    terms[state_index] <= next_terms[state_index];
            end
        end
    end

    assert property (!window || (o_root == (o_value == 8'h00)));
endmodule

module placement_line_scanner #(
    parameter [15:0] NUM_LINES = 16'd8
) (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,
    input  wire [NUM_LINES-16'd1:0] resource_requests,
    output reg  [15:0] scan_index,
    output reg  found,
    output reg  [15:0] captured_index,
    output reg  exhausted
);
    localparam [15:0] LAST_LINE = NUM_LINES - 16'd1;

    initial begin
        scan_index     = 16'd0;
        found          = 1'b0;
        captured_index = 16'd0;
        exhausted      = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                scan_index     <= 16'd0;
                found          <= 1'b0;
                captured_index <= 16'd0;
                exhausted      <= 1'b0;
            end else if (!found && !exhausted) begin
                // Poll one placement-resource request per enabled cycle.
                if ((scan_index < NUM_LINES) && resource_requests[scan_index]) begin
                    found          <= 1'b1;
                    captured_index <= scan_index;
                end else begin
                    scan_index <= scan_index + 16'd1;
                    if (scan_index == LAST_LINE)
                        exhausted <= 1'b1;
                end
            end
        end
    end

    // No search skips more lines than the resource bank contains.
    always @(posedge clk) assert (scan_index <= NUM_LINES);
endmodule

module serial_pixel_multiplier #(
    parameter integer WORD_W = 8
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_ce,
    input  wire                  begin_pixel,
    input  wire                  end_pixel,
    input  wire [WORD_W-1:0]     pixel_value,
    input  wire                  multiplier_bit,
    output reg                   serial_product
);
    localparam [7:0] INPUT_STEPS = WORD_W;
    localparam [7:0] TOTAL_STEPS = 8'd2 * WORD_W;
    localparam [7:0] MAX_CARRIES = WORD_W - 1;
    localparam integer LOW_BITS = (WORD_W > 1) ? $clog2(WORD_W) : 1;

    reg [WORD_W-1:0] multiplicand_reg;
    reg [WORD_W-1:0] sum_cells;
    reg [WORD_W-1:0] carry_cells;
    reg [7:0] bit_count;
    reg [7:0] carry_population;
    reg window_open;
    reg past_valid;

    wire [WORD_W-1:0] partial_product;
    wire [WORD_W-1:0] cell_sum;
    wire [WORD_W-1:0] cell_carry;
    wire [7:0] birth_prefix [0:WORD_W];
    wire [7:0] death_prefix [0:WORD_W];
    wire [7:0] live_prefix [0:WORD_W];
    wire [7:0] live_carries;

    assign partial_product =
        ((bit_count < INPUT_STEPS) && multiplier_bit)
        ? multiplicand_reg : {WORD_W{1'b0}};

    assign birth_prefix[0] = 8'd0;
    assign death_prefix[0] = 8'd0;
    assign live_prefix[0] = 8'd0;
    assign live_carries = live_prefix[WORD_W];

    genvar g;
    generate
        for (g = 0; g < WORD_W; g = g + 1) begin : carry_save_chain
            assign cell_sum[g] = sum_cells[g] ^ carry_cells[g]
                               ^ partial_product[g];
            assign cell_carry[g] =
                (sum_cells[g] & carry_cells[g]) |
                (sum_cells[g] & partial_product[g]) |
                (carry_cells[g] & partial_product[g]);

            assign birth_prefix[g+1] = birth_prefix[g]
                + {7'd0, (cell_carry[g] & ~carry_cells[g])};
            assign death_prefix[g+1] = death_prefix[g]
                + {7'd0, (carry_cells[g] & ~cell_carry[g])};
            assign live_prefix[g+1] = live_prefix[g]
                + {7'd0, carry_cells[g]};
        end
    endgenerate

    initial begin
        multiplicand_reg = {WORD_W{1'b0}};
        sum_cells = {WORD_W{1'b0}};
        carry_cells = {WORD_W{1'b0}};
        bit_count = 8'd0;
        carry_population = 8'd0;
        window_open = 1'b0;
        past_valid = 1'b0;
        serial_product = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            multiplicand_reg <= {WORD_W{1'b0}};
            sum_cells <= {WORD_W{1'b0}};
            carry_cells <= {WORD_W{1'b0}};
            bit_count <= 8'd0;
            carry_population <= 8'd0;
            window_open <= 1'b0;
            past_valid <= 1'b0;
            serial_product <= 1'b0;
        end else if (i_ce) begin
            past_valid <= 1'b1;
            if (end_pixel) begin
                window_open <= 1'b0;
            end else if (begin_pixel) begin
                multiplicand_reg <= pixel_value;
                sum_cells <= {WORD_W{1'b0}};
                carry_cells <= {WORD_W{1'b0}};
                bit_count <= 8'd0;
                carry_population <= 8'd0;
                serial_product <= 1'b0;
                window_open <= 1'b1;
            end else if (window_open && (bit_count < TOTAL_STEPS)) begin
                // The residual is sum_cells + carry_cells. A CSA step
                // adds the partial product, emits its LSB, and divides by two.
                sum_cells <= {1'b0, cell_sum[WORD_W-1:1]};
                carry_cells <= cell_carry;
                serial_product <= cell_sum[0];
                bit_count <= bit_count + 8'd1;

                // Track occupied carry flops through births and retirements.
                carry_population <= carry_population
                    + birth_prefix[WORD_W] - death_prefix[WORD_W];
            end
        end
    end

    // The pixel window remains open until end_pixel, including during stalls.
    // Its carry occupancy stays within the budget, with no upper-band change.
    always @(posedge clk) begin
        if (past_valid && window_open && $stable(window_open))
            assert ($stable(carry_population[7:LOW_BITS]) &&
                    (carry_population <= MAX_CARRIES));
    end
endmodule

module dma_timeout_wheel #(
    parameter integer SLOTS = 4,
    parameter integer ENTRIES = 4
) (
    input  wire       clk,
    input  wire       i_enable,
    input  wire       i_tick,
    input  wire       i_valid,
    output wire       i_ready,
    input  wire       i_coarse,
    input  wire [7:0] i_slot,
    input  wire [7:0] i_fine_slot,
    input  wire [7:0] i_tag,
    output reg  [7:0] retired_count,
    output reg  [7:0] last_expired_id,
    output reg  [7:0] last_expired_tag
);
    localparam [7:0] EMPTY       = 8'hff;
    localparam [7:0] SLOT_COUNT  = SLOTS;
    localparam [7:0] ENTRY_COUNT = ENTRIES;
    localparam [7:0] LAST_SLOT   = SLOTS - 1;

    reg [7:0] fine_ptr, coarse_ptr;
    reg [SLOTS-1:0] fine_occupancy, coarse_occupancy;
    reg [7:0] fine_head   [0:SLOTS-1];
    reg [7:0] coarse_head [0:SLOTS-1];

    // Four shared timer records form the linked lists in both rings.
    reg [7:0] next_timer  [0:ENTRIES-1];
    reg [7:0] fine_target [0:ENTRIES-1];
    reg [7:0] timer_tag   [0:ENTRIES-1];

    // A bit records an earlier accepted scheduling request, until consumed.
    reg [ENTRIES-1:0] admission_shadow;
    reg armed;
    reg past_valid;

    integer init_i;
    initial begin
        fine_ptr = 8'd0;
        coarse_ptr = 8'd0;
        fine_occupancy = {SLOTS{1'b0}};
        coarse_occupancy = {SLOTS{1'b0}};
        admission_shadow = {ENTRIES{1'b0}};
        armed = 1'b0;
        past_valid = 1'b0;
        retired_count = 8'd0;
        last_expired_id = EMPTY;
        last_expired_tag = 8'd0;
        for (init_i = 0; init_i < SLOTS; init_i = init_i + 1) begin
            fine_head[init_i] = EMPTY;
            coarse_head[init_i] = EMPTY;
        end
        for (init_i = 0; init_i < ENTRIES; init_i = init_i + 1) begin
            next_timer[init_i] = EMPTY;
            fine_target[init_i] = 8'd0;
            timer_tag[init_i] = 8'd0;
        end
    end

    reg [7:0] free_id;
    integer search_i;
    always @* begin
        free_id = EMPTY;
        for (search_i = 0; search_i < ENTRIES; search_i = search_i + 1)
            if (!admission_shadow[search_i] && free_id == EMPTY)
                free_id = search_i[7:0];
    end

    // Tick maintenance has priority. A full pool back-pressures admission.
    assign i_ready = i_enable && !i_tick && (free_id != EMPTY);

    always @(posedge clk) begin
        if (i_enable) begin
            if (i_tick || (i_valid && i_ready))
                past_valid <= 1'b1;

            if (i_tick) begin
                if (fine_occupancy[fine_ptr]) begin
                    // Retire one list head; leave the slot selected until empty.
                    retired_count <= retired_count + 8'd1;
                    last_expired_id <= fine_head[fine_ptr];
                    last_expired_tag <= timer_tag[fine_head[fine_ptr]];
                    admission_shadow[fine_head[fine_ptr]] <= 1'b0;
                    fine_head[fine_ptr] <= next_timer[fine_head[fine_ptr]];
                    fine_occupancy[fine_ptr] <=
                        (next_timer[fine_head[fine_ptr]] != EMPTY);
                    next_timer[fine_head[fine_ptr]] <= EMPTY;
                end else if (fine_ptr == LAST_SLOT) begin
                    if (coarse_occupancy[coarse_ptr]) begin
                        // Cascade one coarse-list member to its fine slot.
                        fine_head[fine_target[coarse_head[coarse_ptr]]] <=
                            coarse_head[coarse_ptr];
                        fine_occupancy[fine_target[coarse_head[coarse_ptr]]] <= 1'b1;
                        next_timer[coarse_head[coarse_ptr]] <=
                            fine_head[fine_target[coarse_head[coarse_ptr]]];
                        coarse_head[coarse_ptr] <=
                            next_timer[coarse_head[coarse_ptr]];
                        coarse_occupancy[coarse_ptr] <=
                            (next_timer[coarse_head[coarse_ptr]] != EMPTY);
                    end else begin
                        fine_ptr <= 8'd0;
                        if (coarse_ptr == LAST_SLOT)
                            coarse_ptr <= 8'd0;
                        else
                            coarse_ptr <= coarse_ptr + 8'd1;
                    end
                end else begin
                    fine_ptr <= fine_ptr + 8'd1;
                end
            end else if (i_valid && i_ready) begin
                armed <= 1'b1;
                admission_shadow[free_id] <= 1'b1;
                timer_tag[free_id] <= i_tag;
                fine_target[free_id] <= i_fine_slot % SLOT_COUNT;
                if (i_coarse) begin
                    next_timer[free_id] <= coarse_head[i_slot % SLOT_COUNT];
                    coarse_head[i_slot % SLOT_COUNT] <= free_id;
                    coarse_occupancy[i_slot % SLOT_COUNT] <= 1'b1;
                end else begin
                    next_timer[free_id] <= fine_head[i_slot % SLOT_COUNT];
                    fine_head[i_slot % SLOT_COUNT] <= free_id;
                    fine_occupancy[i_slot % SLOT_COUNT] <= 1'b1;
                end
            end
        end
    end

    // Combinational topology summaries, including references from list links.
    reg [7:0] incoming_refs [0:ENTRIES-1];
    integer ref_i, slot_i, link_i;
    always @* begin
        for (ref_i = 0; ref_i < ENTRIES; ref_i = ref_i + 1) begin
            incoming_refs[ref_i] = 8'd0;
            for (slot_i = 0; slot_i < SLOTS; slot_i = slot_i + 1) begin
                if (fine_head[slot_i] == ref_i[7:0])
                    incoming_refs[ref_i] = incoming_refs[ref_i] + 8'd1;
                if (coarse_head[slot_i] == ref_i[7:0])
                    incoming_refs[ref_i] = incoming_refs[ref_i] + 8'd1;
            end
            for (link_i = 0; link_i < ENTRIES; link_i = link_i + 1)
                if (next_timer[link_i] == ref_i[7:0])
                    incoming_refs[ref_i] = incoming_refs[ref_i] + 8'd1;
        end
    end

    wire [SLOTS-1:0] slot_consistent;
    wire [ENTRIES-1:0] entry_consistent;
    genvar s, e;
    generate
        for (s = 0; s < SLOTS; s = s + 1) begin : slot_checks
            assign slot_consistent[s] =
                (fine_occupancy[s] == (fine_head[s] != EMPTY)) &&
                (coarse_occupancy[s] == (coarse_head[s] != EMPTY)) &&
                ((fine_head[s] == EMPTY) || (fine_head[s] < ENTRY_COUNT)) &&
                ((coarse_head[s] == EMPTY) || (coarse_head[s] < ENTRY_COUNT));
        end
        for (e = 0; e < ENTRIES; e = e + 1) begin : entry_checks
            assign entry_consistent[e] =
                ((next_timer[e] == EMPTY) || (next_timer[e] < ENTRY_COUNT)) &&
                (admission_shadow[e] || (next_timer[e] == EMPTY)) &&
                (fine_target[e] < SLOT_COUNT) &&
                (incoming_refs[e] == (admission_shadow[e] ? 8'd1 : 8'd0));
        end
    endgenerate

    // After the first admission, retirement must consume earlier-admission evidence.
    always @(posedge clk)
        if (past_valid && armed && $stable(admission_shadow))
            assert ($stable(retired_count));
endmodule

module irq_audit_md5 #(
    parameter integer WORD_W = 128,
    parameter integer BLOCK_WORDS = 16
) (
    input  wire                      clk,
    input  wire                      i_ce,
    input  wire                      i_valid,
    output wire                      o_ready,
    input  wire [WORD_W-1:0]         i_word,
    input  wire                      i_ack,
    output wire                      o_done,
    output wire [4*WORD_W-1:0]       o_state
);
    localparam integer ADDR_W = (BLOCK_WORDS > 1) ? $clog2(BLOCK_WORDS) : 1;

    // Interrupt-audit compression engine with widened MD5 words.
    // Transfers load a block, advance its 64 rounds, then acknowledge it.
    // The MD5 Boolean functions, message schedule, rotations and constants
    // are retained; all datapath arithmetic uses WORD_W-bit words.
    reg [WORD_W-1:0] message [0:BLOCK_WORDS-1];
    reg [WORD_W-1:0] a, b, c, d;
    reg [WORD_W-1:0] base_a, base_b, base_c, base_d;
    reg [5:0] step;
    reg [5:0] retired_step;
    reg [ADDR_W-1:0] load_index;
    reg running, done;
    reg armed, pv;

    initial begin
        a = WORD_W'(32'h67452301);
        b = WORD_W'(32'hefcdab89);
        c = WORD_W'(32'h98badcfe);
        d = WORD_W'(32'h10325476);
        base_a = WORD_W'(32'h67452301);
        base_b = WORD_W'(32'hefcdab89);
        base_c = WORD_W'(32'h98badcfe);
        base_d = WORD_W'(32'h10325476);
        step = 6'd0;
        retired_step = 6'd63;
        load_index = {ADDR_W{1'b0}};
        running = 1'b0;
        done = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
    end

    genvar j;
    generate
        for (j = 0; j < BLOCK_WORDS; j = j + 1) begin : init_message
            initial message[j] = {WORD_W{1'b0}};
        end
    endgenerate

    function automatic [WORD_W-1:0] md5_k(input [5:0] n);
        begin
            case (n)
                6'd0:  md5_k = WORD_W'(32'hd76aa478);
                6'd1:  md5_k = WORD_W'(32'he8c7b756);
                6'd2:  md5_k = WORD_W'(32'h242070db);
                6'd3:  md5_k = WORD_W'(32'hc1bdceee);
                6'd4:  md5_k = WORD_W'(32'hf57c0faf);
                6'd5:  md5_k = WORD_W'(32'h4787c62a);
                6'd6:  md5_k = WORD_W'(32'ha8304613);
                6'd7:  md5_k = WORD_W'(32'hfd469501);
                6'd8:  md5_k = WORD_W'(32'h698098d8);
                6'd9:  md5_k = WORD_W'(32'h8b44f7af);
                6'd10: md5_k = WORD_W'(32'hffff5bb1);
                6'd11: md5_k = WORD_W'(32'h895cd7be);
                6'd12: md5_k = WORD_W'(32'h6b901122);
                6'd13: md5_k = WORD_W'(32'hfd987193);
                6'd14: md5_k = WORD_W'(32'ha679438e);
                6'd15: md5_k = WORD_W'(32'h49b40821);
                6'd16: md5_k = WORD_W'(32'hf61e2562);
                6'd17: md5_k = WORD_W'(32'hc040b340);
                6'd18: md5_k = WORD_W'(32'h265e5a51);
                6'd19: md5_k = WORD_W'(32'he9b6c7aa);
                6'd20: md5_k = WORD_W'(32'hd62f105d);
                6'd21: md5_k = WORD_W'(32'h02441453);
                6'd22: md5_k = WORD_W'(32'hd8a1e681);
                6'd23: md5_k = WORD_W'(32'he7d3fbc8);
                6'd24: md5_k = WORD_W'(32'h21e1cde6);
                6'd25: md5_k = WORD_W'(32'hc33707d6);
                6'd26: md5_k = WORD_W'(32'hf4d50d87);
                6'd27: md5_k = WORD_W'(32'h455a14ed);
                6'd28: md5_k = WORD_W'(32'ha9e3e905);
                6'd29: md5_k = WORD_W'(32'hfcefa3f8);
                6'd30: md5_k = WORD_W'(32'h676f02d9);
                6'd31: md5_k = WORD_W'(32'h8d2a4c8a);
                6'd32: md5_k = WORD_W'(32'hfffa3942);
                6'd33: md5_k = WORD_W'(32'h8771f681);
                6'd34: md5_k = WORD_W'(32'h6d9d6122);
                6'd35: md5_k = WORD_W'(32'hfde5380c);
                6'd36: md5_k = WORD_W'(32'ha4beea44);
                6'd37: md5_k = WORD_W'(32'h4bdecfa9);
                6'd38: md5_k = WORD_W'(32'hf6bb4b60);
                6'd39: md5_k = WORD_W'(32'hbebfbc70);
                6'd40: md5_k = WORD_W'(32'h289b7ec6);
                6'd41: md5_k = WORD_W'(32'heaa127fa);
                6'd42: md5_k = WORD_W'(32'hd4ef3085);
                6'd43: md5_k = WORD_W'(32'h04881d05);
                6'd44: md5_k = WORD_W'(32'hd9d4d039);
                6'd45: md5_k = WORD_W'(32'he6db99e5);
                6'd46: md5_k = WORD_W'(32'h1fa27cf8);
                6'd47: md5_k = WORD_W'(32'hc4ac5665);
                6'd48: md5_k = WORD_W'(32'hf4292244);
                6'd49: md5_k = WORD_W'(32'h432aff97);
                6'd50: md5_k = WORD_W'(32'hab9423a7);
                6'd51: md5_k = WORD_W'(32'hfc93a039);
                6'd52: md5_k = WORD_W'(32'h655b59c3);
                6'd53: md5_k = WORD_W'(32'h8f0ccc92);
                6'd54: md5_k = WORD_W'(32'hffeff47d);
                6'd55: md5_k = WORD_W'(32'h85845dd1);
                6'd56: md5_k = WORD_W'(32'h6fa87e4f);
                6'd57: md5_k = WORD_W'(32'hfe2ce6e0);
                6'd58: md5_k = WORD_W'(32'ha3014314);
                6'd59: md5_k = WORD_W'(32'h4e0811a1);
                6'd60: md5_k = WORD_W'(32'hf7537e82);
                6'd61: md5_k = WORD_W'(32'hbd3af235);
                6'd62: md5_k = WORD_W'(32'h2ad7d2bb);
                default: md5_k = WORD_W'(32'heb86d391);
            endcase
        end
    endfunction

    function automatic [4:0] md5_rotation(input [5:0] n);
        begin
            case (n[5:4])
                2'd0: begin
                    case (n[1:0])
                        2'd0: md5_rotation = 5'd7;
                        2'd1: md5_rotation = 5'd12;
                        2'd2: md5_rotation = 5'd17;
                        default: md5_rotation = 5'd22;
                    endcase
                end
                2'd1: begin
                    case (n[1:0])
                        2'd0: md5_rotation = 5'd5;
                        2'd1: md5_rotation = 5'd9;
                        2'd2: md5_rotation = 5'd14;
                        default: md5_rotation = 5'd20;
                    endcase
                end
                2'd2: begin
                    case (n[1:0])
                        2'd0: md5_rotation = 5'd4;
                        2'd1: md5_rotation = 5'd11;
                        2'd2: md5_rotation = 5'd16;
                        default: md5_rotation = 5'd23;
                    endcase
                end
                default: begin
                    case (n[1:0])
                        2'd0: md5_rotation = 5'd6;
                        2'd1: md5_rotation = 5'd10;
                        2'd2: md5_rotation = 5'd15;
                        default: md5_rotation = 5'd21;
                    endcase
                end
            endcase
        end
    endfunction

    function automatic [ADDR_W-1:0] md5_address(input [5:0] n);
        reg [3:0] index16;
        begin
            case (n[5:4])
                2'd0: index16 = n[3:0];
                2'd1: index16 = 4'd5 * n[3:0] + 4'd1;
                2'd2: index16 = 4'd3 * n[3:0] + 4'd5;
                default: index16 = 4'd7 * n[3:0];
            endcase
            md5_address = ADDR_W'(index16 % BLOCK_WORDS);
        end
    endfunction

    wire [WORD_W-1:0] nonlinear =
        (step[5:4] == 2'd0) ? ((b & c) | ((~b) & d)) :
        (step[5:4] == 2'd1) ? ((b & d) | (c & (~d))) :
        (step[5:4] == 2'd2) ? (b ^ c ^ d) :
                                     (c ^ (b | (~d)));
    wire [ADDR_W-1:0] message_address = md5_address(step);
    wire [4:0] rotation = md5_rotation(step);
    wire [WORD_W-1:0] round_sum =
        a + nonlinear + message[message_address] + md5_k(step);
    wire [WORD_W-1:0] rotated_sum =
        (round_sum << rotation) | (round_sum >> (WORD_W - rotation));
    wire [WORD_W-1:0] round_b = b + rotated_sum;

    // Back-pressure prevents another block while its result is unacknowledged.
    assign o_ready = i_ce && (!done || i_ack);
    wire fire = i_valid && o_ready;
    assign o_done = done;
    assign o_state = {a, b, c, d};

    always @(posedge clk) begin
        if (fire) begin
            pv <= 1'b1;
            if (done) begin
                done <= 1'b0;
            end else if (!running) begin
                message[load_index] <= i_word;
                if (load_index == ADDR_W'(BLOCK_WORDS - 1)) begin
                    load_index <= {ADDR_W{1'b0}};
                    running <= 1'b1;
                    // Q: the first complete audit block has been accepted.
                    armed <= 1'b1;
                end else begin
                    load_index <= load_index + {{(ADDR_W-1){1'b0}}, 1'b1};
                end
            end else begin
                // Shadow the index of the operation that just retired.
                retired_step <= step;
                step <= step + 6'd1;
                if (step == 6'd0) begin
                    base_a <= a;
                    base_b <= b;
                    base_c <= c;
                    base_d <= d;
                end
                if (step == 6'd63) begin
                    a <= base_a + d;
                    b <= base_b + round_b;
                    c <= base_c + b;
                    d <= base_d + c;
                    running <= 1'b0;
                    done <= 1'b1;
                end else begin
                    a <= d;
                    b <= round_b;
                    c <= b;
                    d <= c;
                end
            end
        end
    end

    // After Q, a chaining-state change requires a new prior-round record.
    always @(posedge clk)
        if (pv && armed && $stable(retired_step))
            assert ($stable({a, b, c, d}));
endmodule

module condition_chain_engine #(
    parameter WORD_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              cmd_valid,
    output wire              cmd_ready,
    input  wire [1:0]        cmd_kind,
    input  wire [WORD_W-1:0] cmd_data,
    output reg               rsp_valid,
    input  wire              rsp_ready,
    output wire [WORD_W-1:0] rsp_data,
    output reg               arm_done,
    output reg               start_done
);
    localparam [1:0] CMD_ARM    = 2'b00;
    localparam [1:0] CMD_START  = 2'b01;
    localparam [1:0] CMD_FINISH = 2'b10;

    localparam [WORD_W-1:0] IDLE_WORD  = {WORD_W{1'b1}};
    localparam [WORD_W-1:0] ARM_WORD   = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] START_WORD = {{(WORD_W-1){1'b0}}, 1'b1};

    reg [WORD_W-1:0] phase_word;
    reg [WORD_W-1:0] payload;
    reg [3:0] flags; // {N,Z,C,V}

    initial begin
        phase_word = IDLE_WORD;
        payload = {WORD_W{1'b0}};
        flags = 4'b1000;
        arm_done = 1'b0;
        start_done = 1'b0;
        rsp_valid = 1'b0;
    end

    function automatic condition_eval;
        input [3:0] condition;
        input [3:0] f;
        begin
            case (condition)
                4'h0: condition_eval = f[2];
                4'h1: condition_eval = !f[2];
                4'h2: condition_eval = f[1];
                4'h3: condition_eval = !f[1];
                4'h4: condition_eval = f[3];
                4'h5: condition_eval = !f[3];
                4'h6: condition_eval = f[0];
                4'h7: condition_eval = !f[0];
                4'h8: condition_eval = f[1] && !f[2];
                4'h9: condition_eval = !f[1] || f[2];
                4'ha: condition_eval = (f[3] == f[0]);
                4'hb: condition_eval = (f[3] != f[0]);
                4'hc: condition_eval = !f[2] && (f[3] == f[0]);
                4'hd: condition_eval = f[2] || (f[3] != f[0]);
                4'he: condition_eval = 1'b1;
                default: condition_eval = 1'b0;
            endcase
        end
    endfunction

    // The phase ALU encodes idle, armed and started as -1, 0 and +1.
    // Its stored condition codes select the legal next micro-operation:
    // MI permits ARM, EQ permits START, and GT permits FINISH.
    wire [3:0] condition_field =
        (cmd_kind == CMD_ARM)    ? 4'h4 :
        (cmd_kind == CMD_START)  ? 4'h0 :
        (cmd_kind == CMD_FINISH) ? 4'hc : 4'hf;
    wire condition_true = condition_eval(condition_field, flags);

    wire [WORD_W:0] increment_result =
        {1'b0, phase_word} + {{WORD_W{1'b0}}, 1'b1};
    wire increment_overflow =
        !phase_word[WORD_W-1] && increment_result[WORD_W-1];

    assign cmd_ready = !rsp_valid && condition_true;
    assign rsp_data = payload;

    // With cmd_valid and rsp_ready low, every state register holds.
    // A pending response blocks commands and holds its payload until accepted.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase_word <= IDLE_WORD;
            payload <= {WORD_W{1'b0}};
            flags <= 4'b1000;
            arm_done <= 1'b0;
            start_done <= 1'b0;
            rsp_valid <= 1'b0;
        end else begin
            if (rsp_valid && rsp_ready) begin
                rsp_valid <= 1'b0;
                arm_done <= 1'b0;
                start_done <= 1'b0;
            end else if (cmd_valid && cmd_ready) begin
                case (cmd_kind)
                    CMD_ARM: begin
                        phase_word <= ARM_WORD;
                        flags <= 4'b0100;
                        payload <= cmd_data;
                        arm_done <= 1'b1;
                        start_done <= 1'b0;
                    end
                    CMD_START: begin
                        phase_word <= increment_result[WORD_W-1:0];
                        flags <= {
                            increment_result[WORD_W-1],
                            (increment_result[WORD_W-1:0] == ARM_WORD),
                            increment_result[WORD_W],
                            increment_overflow
                        };
                        start_done <= 1'b1;
                    end
                    CMD_FINISH: begin
                        phase_word <= IDLE_WORD;
                        flags <= 4'b1000;
                        rsp_valid <= 1'b1;
                    end
                    default: begin end
                endcase
            end
        end
    end

    // Globally, START requires ARM, and FINISH requires both predecessors.
    always @(posedge clk)
        assert (!(start_done || rsp_valid) ||
                (arm_done && (!rsp_valid || start_done)));
endmodule

module i2c_recovery_deadline #(
    parameter [15:0] MAX_PULSES = 16'd8
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        service_valid,
    output wire        service_ready,
    input  wire [15:0] service_data,
    output wire        scl_drive_low,
    output wire        sda_drive_low,
    output wire        outstanding
);
    localparam [15:0] PH_IDLE      = 16'd0;
    localparam [15:0] PH_LOW       = 16'd1;
    localparam [15:0] PH_HIGH      = 16'd2;
    localparam [15:0] PH_STOP_LOW  = 16'd3;
    localparam [15:0] PH_STOP_HIGH = 16'd4;
    localparam [15:0] PH_DRAIN     = 16'd5;
    localparam [15:0] BUDGET = (16'd2 * MAX_PULSES) + 16'd2;

    reg [15:0] phase;
    reg [15:0] pulse_count;
    reg [15:0] countdown;
    reg armed;
    reg past_valid;

    // An idle transfer requests recovery. Subsequent transfers are service
    // ticks carrying an SDA sample in bit zero. The deadline counts these
    // accepted ticks, so back-pressure pauses both the FSM and its timer.
    assign service_ready = i_ce;
    wire take = service_valid && service_ready;
    wire deadline_expired = (countdown == 16'd0);

    assign outstanding = (phase == PH_LOW) || (phase == PH_HIGH) ||
                         (phase == PH_STOP_LOW) || (phase == PH_STOP_HIGH);
    assign scl_drive_low = (phase == PH_LOW) || (phase == PH_STOP_LOW);
    assign sda_drive_low = (phase == PH_STOP_LOW) || (phase == PH_STOP_HIGH);

    initial begin
        phase       = PH_IDLE;
        pulse_count = 16'd0;
        countdown   = 16'd0;
        armed       = 1'b0;
        past_valid  = 1'b0;
    end

    always @(posedge clk) begin
        if (take) begin
            past_valid <= 1'b1;
            case (phase)
                PH_IDLE: begin
                    // Q: the first accepted recovery request arms the scope.
                    armed       <= 1'b1;
                    pulse_count <= 16'd0;
                    countdown   <= BUDGET;
                    phase       <= PH_LOW;
                end
                PH_LOW: begin
                    countdown <= countdown - 16'd1;
                    phase     <= PH_HIGH;
                end
                PH_HIGH: begin
                    countdown   <= countdown - 16'd1;
                    pulse_count <= pulse_count + 16'd1;
                    if (service_data[0] ||
                        (pulse_count == MAX_PULSES - 16'd1))
                        phase <= PH_STOP_LOW;
                    else
                        phase <= PH_LOW;
                end
                PH_STOP_LOW: begin
                    countdown <= countdown - 16'd1;
                    phase     <= PH_STOP_HIGH;
                end
                PH_STOP_HIGH: begin
                    // Releasing SDA with SCL high issues STOP and completes
                    // the bounded recovery attempt, even if SDA stayed stuck.
                    countdown <= countdown - 16'd1;
                    phase     <= PH_DRAIN;
                end
                PH_DRAIN: begin
                    // After early completion, retain the deadline until its
                    // expiration before accepting another recovery request.
                    if (countdown != 16'd0)
                        countdown <= countdown - 16'd1;
                    if (countdown <= 16'd1)
                        phase <= PH_IDLE;
                end
                default: begin
                    phase       <= PH_IDLE;
                    pulse_count <= 16'd0;
                    countdown   <= 16'd0;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (past_valid && armed && $rose(deadline_expired))
            assert (!outstanding);
    end
endmodule

module crypto_packet_reassembly #(
    parameter integer DEPTH = 32'd96
) (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_frag_valid,
    output wire       o_frag_ready,
    input  wire [7:0] i_frag_data,
    input  wire       i_release,
    input  wire [7:0] i_read_offset,
    output wire [7:0] o_read_data,
    output wire       o_packet_complete
);
    localparam [7:0] CAPACITY = DEPTH;
    localparam [7:0] LAST_INDEX = CAPACITY - 8'd1;

    // Fixed-length packets are assembled for a downstream crypto engine.
    reg [7:0] segment_mem [0:DEPTH-1];
    reg [7:0] segment_tag [0:DEPTH-1];
    reg [DEPTH-1:0] segment_valid;
    reg [7:0] write_offset;
    reg [7:0] received_length;
    reg packet_complete;

    // Scope: first accepted fragment until an accepted release command.
    reg window;

    // History of accepting the final fragment, including its payload.
    reg tail_seen;
    reg [7:0] tail_byte;

    integer init_index;
    initial begin
        write_offset = 8'd0;
        received_length = 8'd0;
        segment_valid = {DEPTH{1'b0}};
        packet_complete = 1'b0;
        window = 1'b0;
        tail_seen = 1'b0;
        tail_byte = 8'h00;
        for (init_index = 32'd0; init_index < DEPTH;
             init_index = init_index + 32'd1) begin
            segment_mem[init_index] = 8'h00;
            segment_tag[init_index] = 8'h00;
        end
    end

    // A release is a control beat on the same valid/ready input channel.
    // A full packet back-pressures data beats until its storage is released.
    assign o_frag_ready = i_ce &&
        (i_release ? packet_complete :
         (!packet_complete && received_length < CAPACITY));

    assign o_packet_complete = packet_complete;
    assign o_read_data =
        (packet_complete && i_read_offset < CAPACITY)
        ? segment_mem[i_read_offset] : 8'h00;

    always @(posedge clk) begin
        if (i_frag_valid && o_frag_ready) begin
            if (i_release) begin
                // The consumer has finished reading the complete packet.
                // Old payload and tags may remain, but no entry remains valid.
                write_offset <= 8'd0;
                received_length <= 8'd0;
                segment_valid <= {DEPTH{1'b0}};
                packet_complete <= 1'b0;
                window <= 1'b0;
                tail_seen <= 1'b0;
                tail_byte <= 8'h00;
            end else begin
                segment_mem[write_offset] <= i_frag_data;
                segment_tag[write_offset] <= received_length;
                segment_valid[write_offset] <= 1'b1;
                write_offset <= write_offset + 8'd1;
                received_length <= received_length + 8'd1;
                window <= 1'b1;

                if (write_offset == LAST_INDEX)
                    packet_complete <= 1'b1;

                if (received_length == LAST_INDEX) begin
                    tail_seen <= 1'b1;
                    tail_byte <= i_frag_data;
                end
            end
        end
    end

    // Observing completion within the collection window requires an earlier
    // final-fragment acceptance, with the accepted byte in the final slot.
    always @(*) begin
        if (window && packet_complete)
            assert (tail_seen &&
                    segment_mem[LAST_INDEX] == tail_byte);
    end
endmodule

module palette_mux_pipeline #(
    parameter integer ENTRIES = 128,
    parameter integer WORD_WIDTH = 8,
    localparam integer ADDR_WIDTH = (ENTRIES > 1) ? $clog2(ENTRIES) : 1
) (
    input wire clk,
    input wire rst_n,
    input wire ce,
    input wire frame_start,
    input wire wr_en,
    input wire [ADDR_WIDTH-1:0] wr_addr,
    input wire [WORD_WIDTH-1:0] wr_data,
    input wire [ADDR_WIDTH-1:0] rd_addr,
    output reg [WORD_WIDTH-1:0] pixel,
    output reg [WORD_WIDTH-1:0] reference_pixel
);
    localparam integer LEAF_COUNT = 2 ** ADDR_WIDTH;

    reg [WORD_WIDTH-1:0] palette [0:ENTRIES-1];
    wire [WORD_WIDTH-1:0] mux_tree [1:2*LEAF_COUNT-1];

    reg [WORD_WIDTH-1:0] low_sample;
    reg [WORD_WIDTH-1:0] high_sample;
    reg [WORD_WIDTH-1:0] root_sample;
    reg bank_sample;
    reg armed;

    // Writable palette storage; every word has initialization and reset.
    genvar slot;
    generate
        for (slot = 0; slot < ENTRIES; slot = slot + 1) begin : g_palette
            localparam [ADDR_WIDTH-1:0] SLOT_ADDR = slot;
            initial palette[slot] = {WORD_WIDTH{1'b0}};
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    palette[slot] <= {WORD_WIDTH{1'b0}};
                else if (ce && wr_en && (wr_addr == SLOT_ADDR))
                    palette[slot] <= wr_data;
            end
        end
    endgenerate

    // A full binary mux tree, padded with zero leaves when necessary.
    genvar leaf;
    genvar node;
    generate
        for (leaf = 0; leaf < LEAF_COUNT; leaf = leaf + 1) begin : g_leaf
            if (leaf < ENTRIES) begin : g_present
                assign mux_tree[LEAF_COUNT + leaf] = palette[leaf];
            end else begin : g_padding
                assign mux_tree[LEAF_COUNT + leaf] = {WORD_WIDTH{1'b0}};
            end
        end
        for (node = 1; node < LEAF_COUNT; node = node + 1) begin : g_mux
            localparam integer LEVEL = $clog2(node + 1) - 1;
            assign mux_tree[node] = rd_addr[ADDR_WIDTH - 1 - LEVEL]
                                 ? mux_tree[2*node + 1]
                                 : mux_tree[2*node];
        end
    endgenerate

    initial begin
        low_sample = {WORD_WIDTH{1'b0}};
        high_sample = {WORD_WIDTH{1'b0}};
        root_sample = {WORD_WIDTH{1'b0}};
        bank_sample = 1'b0;
        pixel = {WORD_WIDTH{1'b0}};
        reference_pixel = {WORD_WIDTH{1'b0}};
        armed = 1'b0;
    end

    // Compare selection before registration with a retimed final mux.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            low_sample <= {WORD_WIDTH{1'b0}};
            high_sample <= {WORD_WIDTH{1'b0}};
            root_sample <= {WORD_WIDTH{1'b0}};
            bank_sample <= 1'b0;
            pixel <= {WORD_WIDTH{1'b0}};
            reference_pixel <= {WORD_WIDTH{1'b0}};
            armed <= 1'b0;
        end else if (ce) begin
            low_sample <= mux_tree[2];
            high_sample <= mux_tree[3];
            bank_sample <= rd_addr[ADDR_WIDTH-1];
            root_sample <= mux_tree[1];
            pixel <= bank_sample ? high_sample : low_sample;
            reference_pixel <= root_sample;
            armed <= armed || frame_start;
        end
    end

    always @(posedge clk)
        if (armed)
            assert (pixel == reference_pixel);
endmodule

module posit_operand_pipeline #(
    parameter integer WORD_BITS = 16,
    parameter integer COUNT_BITS = 16,
    parameter integer PIPE_STAGES = 8,
    parameter integer DECODE_STAGES = 4
) (
    input wire clk,
    input wire i_enable,
    input wire i_scope_open,
    input wire i_scope_close,
    input wire i_request,
    input wire [WORD_BITS-1:0] i_posit,
    output reg [WORD_BITS-1:0] o_decode_word,
    output reg [WORD_BITS-1:0] o_result
);
    localparam [WORD_BITS-1:0] WORD_ZERO = {WORD_BITS{1'b0}};
    localparam [COUNT_BITS-1:0] COUNT_ZERO = {COUNT_BITS{1'b0}};
    localparam [COUNT_BITS-1:0] COUNT_ONE = {{(COUNT_BITS-1){1'b0}}, 1'b1};
    localparam [COUNT_BITS-1:0] DECODE_LIMIT = DECODE_STAGES;
    localparam [COUNT_BITS-1:0] RETIRE_LIMIT = PIPE_STAGES;
    localparam [PIPE_STAGES-1:0] TOKEN_ZERO = {PIPE_STAGES{1'b0}};
    localparam [PIPE_STAGES-1:0] TOKEN_ONE = {{(PIPE_STAGES-1){1'b0}}, 1'b1};

    reg window;
    reg decode_pending, retire_pending;
    reg [COUNT_BITS-1:0] decode_left, retire_left;
    reg [PIPE_STAGES-1:0] valid_pipe;
    reg [WORD_BITS-1:0] operand_pipe [0:PIPE_STAGES-1];

    wire accept = i_enable && window && i_request && !retire_pending;

    // Combinational distances represented by the request-token DFF chain.
    wire [COUNT_BITS-1:0] decode_sum [0:PIPE_STAGES];
    wire [COUNT_BITS-1:0] retire_sum [0:PIPE_STAGES];
    wire [COUNT_BITS-1:0] decode_distance;
    wire [COUNT_BITS-1:0] retire_distance;
    assign decode_sum[0] = COUNT_ZERO;
    assign retire_sum[0] = COUNT_ZERO;

    generate
        for (genvar g = 0; g < PIPE_STAGES; g = g + 1) begin : distance_terms
            localparam [COUNT_BITS-1:0] RETIRE_WEIGHT = PIPE_STAGES - g;
            localparam [COUNT_BITS-1:0] DECODE_WEIGHT =
                (g < DECODE_STAGES) ? (DECODE_STAGES - g) : COUNT_ZERO;
            assign decode_sum[g+1] = decode_sum[g] +
                (valid_pipe[g] ? DECODE_WEIGHT : COUNT_ZERO);
            assign retire_sum[g+1] = retire_sum[g] +
                (valid_pipe[g] ? RETIRE_WEIGHT : COUNT_ZERO);
        end
    endgenerate

    assign decode_distance = decode_sum[PIPE_STAGES];
    assign retire_distance = retire_sum[PIPE_STAGES];

    initial begin
        window = 1'b0;
        decode_pending = 1'b0;
        retire_pending = 1'b0;
        decode_left = COUNT_ZERO;
        retire_left = COUNT_ZERO;
        valid_pipe = TOKEN_ZERO;
        o_decode_word = WORD_ZERO;
        o_result = WORD_ZERO;
        for (integer n = 0; n < PIPE_STAGES; n = n + 1)
            operand_pipe[n] = WORD_ZERO;
    end

    // Enabled positive-edge DFFs carry the operand and its request token.
    // Both deadlines measure enabled clock cycles.
    always @(posedge clk) begin
        if (i_enable) begin
            if (i_scope_close)
                window <= 1'b0;
            else if (i_scope_open)
                window <= 1'b1;

            valid_pipe[0] <= accept;
            operand_pipe[0] <= accept ? i_posit : WORD_ZERO;
            for (integer n = 1; n < PIPE_STAGES; n = n + 1) begin
                valid_pipe[n] <= valid_pipe[n-1];
                operand_pipe[n] <= operand_pipe[n-1];
            end

            if (accept) begin
                decode_pending <= 1'b1;
                retire_pending <= 1'b1;
                decode_left <= DECODE_LIMIT;
                retire_left <= RETIRE_LIMIT;
            end else begin
                if (decode_pending) begin
                    if (decode_left != COUNT_ZERO)
                        decode_left <= decode_left - COUNT_ONE;
                    if (valid_pipe[DECODE_STAGES-1])
                        decode_pending <= 1'b0;
                end
                if (retire_pending) begin
                    if (retire_left != COUNT_ZERO)
                        retire_left <= retire_left - COUNT_ONE;
                    if (valid_pipe[PIPE_STAGES-1])
                        retire_pending <= 1'b0;
                end
            end

            if (valid_pipe[DECODE_STAGES-1])
                o_decode_word <= operand_pipe[DECODE_STAGES-1];
            if (valid_pipe[PIPE_STAGES-1])
                o_result <= operand_pipe[PIPE_STAGES-1];
        end
    end

    always @(posedge clk) begin
        if (window) begin
            assert (!decode_pending || (decode_left != COUNT_ZERO));
            assert (!retire_pending || (retire_left != COUNT_ZERO));
        end
    end
endmodule

module masked_priority_window #(
    parameter integer CHANNELS = 8
) (
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire                    cmd_valid,
    output wire                    cmd_ready,
    input  wire [7:0]              cmd_opcode,
    input  wire [CHANNELS-1:0]     cmd_data,
    output reg                     rsp_valid,
    input  wire                    rsp_ready,
    output reg  [7:0]              last_index
);
    localparam [7:0] CMD_MASK    = 8'h00;
    localparam [7:0] CMD_CAPTURE = 8'h01;
    localparam [7:0] CMD_ENCODE  = 8'h02;
    localparam [7:0] CMD_OPEN    = 8'h03;
    localparam [7:0] CMD_CLOSE   = 8'h04;

    reg [CHANNELS-1:0] sw_mask;
    reg [CHANNELS-1:0] captured_requests;
    reg [CHANNELS-1:0] encoded_requests;
    reg window_open;
    reg past_valid;

    // The highest numbered enabled channel has highest priority.
    // An empty selection is represented by the eight-bit sentinel ff.
    function automatic [7:0] encode_priority;
        input [CHANNELS-1:0] requests;
        integer lane;
        begin
            encode_priority = 8'hff;
            for (lane = 0; lane < CHANNELS; lane = lane + 1)
                if (requests[lane])
                    encode_priority = lane[7:0];
        end
    endfunction

    wire [7:0] encoded_priority = encode_priority(encoded_requests);
    assign cmd_ready = !rsp_valid || rsp_ready;
    wire cmd_fire = cmd_valid && cmd_ready;

    initial begin
        sw_mask          = {CHANNELS{1'b1}};
        captured_requests = {CHANNELS{1'b0}};
        encoded_requests  = {CHANNELS{1'b0}};
        last_index        = 8'hff;
        rsp_valid         = 1'b0;
        window_open       = 1'b0;
        past_valid        = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sw_mask           <= {CHANNELS{1'b1}};
            captured_requests <= {CHANNELS{1'b0}};
            encoded_requests  <= {CHANNELS{1'b0}};
            last_index        <= 8'hff;
            rsp_valid         <= 1'b0;
            window_open       <= 1'b0;
            past_valid        <= 1'b0;
        end else begin
            if (rsp_valid && rsp_ready)
                rsp_valid <= 1'b0;

            if (cmd_fire) begin
                past_valid <= 1'b1;
                case (cmd_opcode)
                    CMD_MASK: begin
                        sw_mask <= cmd_data;
                    end
                    CMD_CAPTURE: begin
                        // Record the earlier request event.
                        captured_requests <= cmd_data;
                    end
                    CMD_ENCODE: begin
                        // Publish a result from the earlier captured request.
                        // Keep its masked bitmap as the response's shadow.
                        encoded_requests <= captured_requests & sw_mask;
                        last_index <= encode_priority(captured_requests & sw_mask);
                        rsp_valid <= 1'b1;
                    end
                    CMD_OPEN: begin
                        window_open <= 1'b1;
                    end
                    CMD_CLOSE: begin
                        window_open <= 1'b0;
                    end
                    default: begin end
                endcase
            end
        end
    end

    // Within the window, a response-index change requires a change
    // in the shadow of the earlier captured, mask-qualified request.
    always @(posedge clk)
        if (past_valid && window_open && rsp_valid &&
            $stable(encoded_requests))
            assert ($stable(last_index));
endmodule

module hmac_pass_sequencer #(
    parameter [31:0] WORD_W = 32'd32,
    parameter [31:0] WORDS  = 32'd8
) (
    input  wire                         clk,
    input  wire                         i_ce,
    input  wire                         i_start,
    input  wire [WORDS*WORD_W-1:0]       i_key_block,
    input  wire [WORD_W-1:0]             i_message,
    output wire [WORD_W-1:0]             o_tag,
    output wire                         o_done
);
    localparam [31:0] PH_IDLE         = 32'd0;
    localparam [31:0] PH_INNER_KEY    = 32'd1;
    localparam [31:0] PH_INNER_MSG    = 32'd2;
    localparam [31:0] PH_OUTER_KEY    = 32'd3;
    localparam [31:0] PH_OUTER_DIGEST = 32'd4;
    localparam [31:0] PH_REPORT       = 32'd5;
    localparam [WORD_W-1:0] IPAD = {(WORD_W/32'd8){8'h36}};
    localparam [WORD_W-1:0] OPAD = {(WORD_W/32'd8){8'h5c}};
    localparam [WORD_W-1:0] HASH_IV = 32'h6a09e667;

    reg [31:0] phase;
    reg [31:0] word_index;
    reg window;
    reg inner_seen;
    reg [WORD_W-1:0] padded_key [0:WORDS-1];
    reg [WORD_W-1:0] message_word;
    reg [WORD_W-1:0] inner_digest;
    reg [WORD_W-1:0] inner_shadow;
    reg [WORD_W-1:0] hash_acc;
    reg [WORD_W-1:0] tag;

    initial begin
        phase         = PH_IDLE;
        word_index    = 32'd0;
        window        = 1'b0;
        inner_seen    = 1'b0;
        message_word  = {WORD_W{1'b0}};
        inner_digest  = {WORD_W{1'b0}};
        inner_shadow  = {WORD_W{1'b0}};
        hash_acc      = HASH_IV;
        tag           = {WORD_W{1'b0}};
    end

    // The input block is an already zero-padded HMAC key block.
    genvar lane;
    generate
        for (lane = 32'd0; lane < WORDS; lane = lane + 32'd1) begin : key_storage
            initial padded_key[lane] = {WORD_W{1'b0}};
            always @(posedge clk)
                if (i_ce && (phase == PH_IDLE) && i_start)
                    padded_key[lane] <= i_key_block[lane*WORD_W +: WORD_W];
        end
    endgenerate

    // Reduced fixed-latency hash-core model with a one-word digest.
    // The sequencer still performs separate ipad and opad key passes.
    function automatic [WORD_W-1:0] compress;
        input [WORD_W-1:0] acc;
        input [WORD_W-1:0] data_word;
        begin
            compress = {acc[WORD_W-2:0], acc[WORD_W-1]} ^ data_word;
        end
    endfunction

    wire core_seed = ((phase == PH_IDLE) && i_start) ||
                     (phase == PH_INNER_MSG);
    wire core_absorb = (phase == PH_INNER_KEY) ||
                       (phase == PH_INNER_MSG) ||
                       (phase == PH_OUTER_KEY) ||
                       (phase == PH_OUTER_DIGEST);
    wire [WORD_W-1:0] core_word =
        (phase == PH_INNER_KEY)    ? (padded_key[word_index] ^ IPAD) :
        (phase == PH_INNER_MSG)    ? message_word :
        (phase == PH_OUTER_KEY)    ? (padded_key[word_index] ^ OPAD) :
        (phase == PH_OUTER_DIGEST) ? inner_digest : {WORD_W{1'b0}};
    wire [WORD_W-1:0] core_result = compress(hash_acc, core_word);

    // At inner finalization, core_result is captured while the core reseeds.
    always @(posedge clk) begin
        if (i_ce) begin
            if (core_seed)
                hash_acc <= HASH_IV;
            else if (core_absorb)
                hash_acc <= core_result;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                PH_IDLE: begin
                    if (i_start) begin
                        window       <= 1'b1;
                        inner_seen   <= 1'b0;
                        inner_digest <= {WORD_W{1'b0}};
                        inner_shadow <= {WORD_W{1'b0}};
                        message_word <= i_message;
                        word_index   <= 32'd0;
                        phase        <= PH_INNER_KEY;
                    end
                end
                PH_INNER_KEY: begin
                    if (word_index == WORDS - 32'd1) begin
                        word_index <= 32'd0;
                        phase      <= PH_INNER_MSG;
                    end else begin
                        word_index <= word_index + 32'd1;
                    end
                end
                PH_INNER_MSG: begin
                    inner_digest <= core_result;
                    inner_shadow <= core_result;
                    inner_seen   <= 1'b1;
                    word_index   <= 32'd0;
                    phase        <= PH_OUTER_KEY;
                end
                PH_OUTER_KEY: begin
                    if (word_index == WORDS - 32'd1) begin
                        word_index <= 32'd0;
                        phase      <= PH_OUTER_DIGEST;
                    end else begin
                        word_index <= word_index + 32'd1;
                    end
                end
                PH_OUTER_DIGEST: begin
                    tag   <= core_result;
                    phase <= PH_REPORT;
                end
                PH_REPORT: begin
                    window     <= 1'b0;
                    inner_seen <= 1'b0;
                    word_index <= 32'd0;
                    phase      <= PH_IDLE;
                end
            endcase
        end
    end

    assign o_tag  = tag;
    assign o_done = (phase == PH_REPORT);

    // Between start and completion, presenting the inner digest to the
    // outer pass requires an earlier inner-finalization event and its value.
    assert property (!(window && (phase == PH_OUTER_DIGEST)) ||
                     (inner_seen && (inner_digest == inner_shadow)));
endmodule

module training_burst_ring #(
    parameter integer WORD_WIDTH = 64,
    parameter integer RING_STAGES = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    output wire                  o_ready,
    input  wire [WORD_WIDTH-1:0] i_training_word,
    input  wire                  i_video_start,
    output wire                  o_busy,
    output wire                  o_complete,
    output wire [WORD_WIDTH-1:0] o_training_word
);
    localparam [WORD_WIDTH-1:0] COUNT_ZERO = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] COUNT_ONE = {{(WORD_WIDTH-1){1'b0}}, 1'b1};
    localparam [WORD_WIDTH-1:0] BURST_CYCLES = RING_STAGES;
    localparam [RING_STAGES-1:0] TOKEN_ZERO = {RING_STAGES{1'b0}};
    localparam [RING_STAGES-1:0] TOKEN_ONE = {{(RING_STAGES-1){1'b0}}, 1'b1};

    reg [RING_STAGES-1:0] token;
    reg [WORD_WIDTH-1:0] remaining;
    reg [WORD_WIDTH-1:0] training_word;
    reg busy;
    reg before_video;

    initial begin
        token = TOKEN_ONE;
        remaining = COUNT_ZERO;
        training_word = COUNT_ZERO;
        busy = 1'b0;
        before_video = 1'b1;
    end

    // A single request is buffered; back-pressure blocks further requests.
    assign o_ready = i_ce && !busy;
    assign o_busy = busy;
    assign o_training_word = training_word;
    assign o_complete = i_ce && busy && token[RING_STAGES-1];

    always @(posedge clk) begin
        // Disabling link service freezes every state register.
        if (i_ce) begin
            if (i_video_start)
                before_video <= 1'b0;

            if (!busy) begin
                if (i_valid && o_ready) begin
                    training_word <= i_training_word;
                    busy <= 1'b1;
                    remaining <= BURST_CYCLES;
                    token <= TOKEN_ONE;
                end
            end else begin
                // One training phase per enabled service cycle.
                token <= {token[RING_STAGES-2:0], token[RING_STAGES-1]};
                if (remaining != COUNT_ZERO)
                    remaining <= remaining - COUNT_ONE;
                if (token[RING_STAGES-1])
                    busy <= 1'b0;
            end
        end
    end

    // Before the first video-start event, no outstanding burst may expire.
    always @(posedge clk)
        assert (!before_video || !busy || (remaining != COUNT_ZERO));
endmodule

module normalization_divsqrt #(
    parameter integer DATA_W = 8,
    parameter integer ITER_W = 8
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [7:0]            in_cmd,
    input  wire                  in_sqrt,
    input  wire [DATA_W-1:0]     in_operand,
    input  wire [DATA_W-1:0]     in_divisor,
    output reg                   out_valid,
    input  wire                  out_ready,
    output wire [DATA_W-1:0]     out_result,
    output wire [DATA_W-1:0]     out_remainder,
    output wire                  out_sqrt
);
    // DATA_W is even and at least two. ARM captures operands,
    // START launches execution, and each STEP advances one digit.
    localparam [7:0] CMD_ARM       = 8'd0;
    localparam [7:0] CMD_START     = 8'd1;
    localparam [7:0] CMD_STEP      = 8'd2;
    localparam [7:0] CMD_SCOPE_END = 8'd3;

    localparam [7:0] PH_IDLE  = 8'd0;
    localparam [7:0] PH_ARMED = 8'd1;
    localparam [7:0] PH_RUN   = 8'd2;
    localparam [7:0] PH_DONE  = 8'd3;
    localparam [ITER_W-1:0] DIV_STEPS  = DATA_W;
    localparam [ITER_W-1:0] SQRT_STEPS = DATA_W / 2;

    reg [7:0] phase;
    reg mode_sqrt;
    reg [DATA_W-1:0] operand_shift;
    reg [DATA_W-1:0] partial_remainder;
    reg [DATA_W-1:0] root_quotient;
    reg [DATA_W-1:0] divisor;
    reg [ITER_W-1:0] iteration;

    // Transaction history: accepted arm and start events, retained
    // through completion until the result is consumed.
    reg arm_seen;
    reg start_seen;
    reg before_scope;

    initial begin
        phase = PH_IDLE;
        mode_sqrt = 1'b0;
        operand_shift = {DATA_W{1'b0}};
        partial_remainder = {DATA_W{1'b0}};
        root_quotient = {DATA_W{1'b0}};
        divisor = {{(DATA_W-1){1'b0}}, 1'b1};
        iteration = {ITER_W{1'b0}};
        arm_seen = 1'b0;
        start_seen = 1'b0;
        before_scope = 1'b1;
        out_valid = 1'b0;
    end

    assign in_ready =
        ((phase == PH_IDLE) &&
         ((in_cmd == CMD_ARM) || (in_cmd == CMD_SCOPE_END))) ||
        ((phase == PH_ARMED) && (in_cmd == CMD_START)) ||
        ((phase == PH_RUN) && (in_cmd == CMD_STEP));

    wire input_transfer = in_valid && in_ready;
    wire output_transfer = out_valid && out_ready;

    assign out_result = root_quotient;
    assign out_remainder = partial_remainder;
    assign out_sqrt = mode_sqrt;

    // Shared restoring digit recurrence: division brings down one bit;
    // square root brings down a pair and uses 4*root+1 as its trial divisor.
    wire [DATA_W-1:0] incoming_digit = mode_sqrt
        ? {{(DATA_W-2){1'b0}}, operand_shift[DATA_W-1:DATA_W-2]}
        : {{(DATA_W-1){1'b0}}, operand_shift[DATA_W-1]};
    wire [DATA_W-1:0] shifted_remainder =
        (partial_remainder << (mode_sqrt ? 8'd2 : 8'd1)) |
        incoming_digit;
    wire [DATA_W-1:0] trial_divisor = mode_sqrt
        ? ((root_quotient << 8'd2) |
           {{(DATA_W-1){1'b0}}, 1'b1})
        : divisor;
    wire take_digit = shifted_remainder >= trial_divisor;
    wire [DATA_W-1:0] next_remainder = take_digit
        ? shifted_remainder - trial_divisor : shifted_remainder;
    wire [DATA_W-1:0] next_root_quotient =
        (root_quotient << 8'd1) |
        {{(DATA_W-1){1'b0}}, take_digit};
    wire [ITER_W-1:0] next_iteration =
        iteration + {{(ITER_W-1){1'b0}}, 1'b1};
    wire [ITER_W-1:0] iteration_limit =
        mode_sqrt ? SQRT_STEPS : DIV_STEPS;

    // No autonomous updates: in_valid=0 and out_ready=0 freeze all state.
    // While a result is back-pressured, no new command is accepted.
    always @(posedge clk) begin
        if (output_transfer) begin
            out_valid <= 1'b0;
            phase <= PH_IDLE;
            iteration <= {ITER_W{1'b0}};
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
        end else if (input_transfer) begin
            case (in_cmd)
                CMD_ARM: begin
                    mode_sqrt <= in_sqrt;
                    operand_shift <= in_operand;
                    divisor <= in_divisor;
                    partial_remainder <= {DATA_W{1'b0}};
                    root_quotient <= {DATA_W{1'b0}};
                    iteration <= {ITER_W{1'b0}};
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    out_valid <= 1'b0;
                    phase <= PH_ARMED;
                end
                CMD_START: begin
                    start_seen <= 1'b1;
                    phase <= PH_RUN;
                end
                CMD_STEP: begin
                    operand_shift <= operand_shift <<
                                     (mode_sqrt ? 8'd2 : 8'd1);
                    partial_remainder <= next_remainder;
                    root_quotient <= next_root_quotient;
                    iteration <= next_iteration;
                    if (next_iteration == iteration_limit) begin
                        out_valid <= 1'b1;
                        phase <= PH_DONE;
                    end
                end
                CMD_SCOPE_END: begin
                    before_scope <= 1'b0;
                end
                default: begin end
            endcase
        end
    end

    // Before the first accepted scope-end event: arm precedes start,
    // and both precede finish, represented by the pending result.
    always @(*) begin
        if (before_scope)
            assert ((!start_seen || arm_seen) &&
                    (!out_valid || (arm_seen && start_seen)));
    end
endmodule

module core_retention_controller #(
    parameter integer DATA_W = 16,
    parameter integer ENTRIES = 2
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_power_down,
    input  wire i_wake,
    input  wire i_load,
    input  wire [ENTRIES*DATA_W-1:0] i_live_data,
    output wire [ENTRIES*DATA_W-1:0] o_live_data,
    output wire arm_strobe,
    output wire save_strobe,
    output wire restore_strobe,
    output wire power_off
);
    typedef enum logic [2:0] {
        RET_RUN     = 3'd0,
        RET_ARM     = 3'd1,
        RET_SAVE    = 3'd2,
        RET_SLEEP   = 3'd3,
        RET_RESTORE = 3'd4
    } retention_phase_t;

    retention_phase_t phase;
    logic save_done;
    logic restore_pending;
    logic [DATA_W-1:0] live_words [0:ENTRIES-1];
    logic [DATA_W-1:0] retention_words [0:ENTRIES-1];

    initial begin
        phase = RET_RUN;
        save_done = 1'b0;
        restore_pending = 1'b0;
        for (integer n = 0; n < ENTRIES; n = n + 1) begin
            live_words[n] = {DATA_W{1'b0}};
            retention_words[n] = {DATA_W{1'b0}};
        end
    end

    // Decoded strobes are committed only on an enabled clock edge.
    assign arm_strobe = (phase == RET_ARM);
    assign save_strobe = (phase == RET_SAVE);
    assign restore_strobe = (phase == RET_RESTORE);
    assign power_off = (phase == RET_SLEEP);

    generate
        for (genvar g = 0; g < ENTRIES; g = g + 1) begin : expose_live_words
            assign o_live_data[g*DATA_W +: DATA_W] = live_words[g];
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                RET_RUN: begin
                    if (i_load) begin
                        for (integer n = 0; n < ENTRIES; n = n + 1)
                            live_words[n] <= i_live_data[n*DATA_W +: DATA_W];
                    end
                    if (i_power_down)
                        phase <= RET_ARM;
                end
                RET_ARM: begin
                    // Arm retention before issuing the save operation.
                    restore_pending <= 1'b1;
                    phase <= RET_SAVE;
                end
                RET_SAVE: begin
                    for (integer n = 0; n < ENTRIES; n = n + 1) begin
                        retention_words[n] <= live_words[n];
                        live_words[n] <= {DATA_W{1'b0}};
                    end
                    save_done <= 1'b1;
                    phase <= RET_SLEEP;
                end
                RET_SLEEP: begin
                    if (i_wake)
                        phase <= RET_RESTORE;
                end
                RET_RESTORE: begin
                    for (integer n = 0; n < ENTRIES; n = n + 1)
                        live_words[n] <= retention_words[n];
                    save_done <= 1'b0;
                    restore_pending <= 1'b0;
                    phase <= RET_RUN;
                end
                default: begin
                    phase <= RET_RUN;
                    save_done <= 1'b0;
                    restore_pending <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence: save requires arm; restore requires arm and save.
    always @(posedge clk)
        if (save_strobe || restore_strobe)
            assert (restore_pending && (!restore_strobe || save_done));
endmodule

module approximate_cam_hit_counter #(
    parameter integer KEY_BITS = 64,
    parameter integer ENTRIES = 2
) (
    input wire clk,
    input wire ce,
    input wire search,
    input wire [KEY_BITS-1:0] search_key,
    input wire [ENTRIES-1:0] write_mask,
    input wire [KEY_BITS-1:0] write_data,
    input wire write_valid,
    input wire threshold_we,
    input wire [63:0] threshold_data,
    input wire acknowledge,
    output reg [63:0] hit_count,
    output reg [ENTRIES-1:0] match_mask,
    output wire done
);
    typedef enum logic [1:0] {
        IDLE  = 2'b00,
        DRAIN = 2'b01,
        DONE  = 2'b10
    } state_t;

    localparam [63:0] ENTRY_LIMIT = ENTRIES;
    localparam [ENTRIES-1:0] MASK_ONE = {{(ENTRIES-1){1'b0}}, 1'b1};

    state_t state;
    reg [KEY_BITS-1:0] keys [0:ENTRIES-1];
    reg [ENTRIES-1:0] valid;
    reg [63:0] threshold;
    reg [ENTRIES-1:0] pending_mask;
    reg armed;

    reg [63:0] distance [0:ENTRIES-1];
    wire [ENTRIES-1:0] candidate_mask;
    reg [63:0] retired_count;
    integer r;

    assign done = (state == DONE);

    initial begin
        state = IDLE;
        threshold = 64'd0;
        hit_count = 64'd0;
        match_mask = {ENTRIES{1'b0}};
        pending_mask = {ENTRIES{1'b0}};
        armed = 1'b0;
    end

    genvar e;
    generate
        for (e = 0; e < ENTRIES; e = e + 1) begin : cam_entry
            integer b;

            initial begin
                keys[e] = {KEY_BITS{1'b0}};
                valid[e] = 1'b0;
            end

            always @(posedge clk) begin
                if (ce && state == IDLE && !search && write_mask[e]) begin
                    keys[e] <= write_data;
                    valid[e] <= write_valid;
                end
            end

            // Every stored entry has its own parallel Hamming-distance logic.
            always @(*) begin
                distance[e] = 64'd0;
                for (b = 0; b < KEY_BITS; b = b + 1) begin
                    if (keys[e][b] != search_key[b])
                        distance[e] = distance[e] + 64'd1;
                end
            end

            assign candidate_mask[e] = valid[e] && (distance[e] <= threshold);
        end
    endgenerate

    // Same-cycle population of captured matches already retired by DRAIN.
    always @(*) begin
        retired_count = 64'd0;
        for (r = 0; r < ENTRIES; r = r + 1) begin
            if (match_mask[r] && !pending_mask[r])
                retired_count = retired_count + 64'd1;
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                IDLE: begin
                    if (search) begin
                        match_mask <= candidate_mask;
                        pending_mask <= candidate_mask;
                        hit_count <= 64'd0;
                        armed <= 1'b1;
                        state <= DRAIN;
                    end else if (threshold_we) begin
                        threshold <= threshold_data;
                    end
                end

                DRAIN: begin
                    if (pending_mask != {ENTRIES{1'b0}}) begin
                        // Retire exactly the lowest pending match.
                        pending_mask <= pending_mask & (pending_mask - MASK_ONE);
                        hit_count <= hit_count + 64'd1;
                    end else begin
                        state <= DONE;
                    end
                end

                DONE: begin
                    if (acknowledge)
                        state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        assert (!armed || (hit_count <= ENTRY_LIMIT));
endmodule

module link_manchester_chain #(
    parameter [31:0] WORD_BITS = 32'd32
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 arm_cmd,
    input  wire [WORD_BITS-1:0]  word_in,
    input  wire                 scope_end,
    output reg                  tx_line,
    output reg                  start_pulse,
    output reg                  finish_pulse
);
    localparam [1:0] ST_IDLE    = 2'd0;
    localparam [1:0] ST_ARMED   = 2'd1;
    localparam [1:0] ST_STARTED = 2'd2;
    localparam [1:0] ST_DONE    = 2'd3;
    localparam [31:0] LAST_BIT  = WORD_BITS - 32'd1;

    reg [WORD_BITS-1:0] shift_data;
    reg [31:0] bit_index;
    reg half_phase;
    reg [1:0] stage;
    reg scope_open;
    reg pv;

    initial begin
        shift_data  = {WORD_BITS{1'b0}};
        bit_index   = 32'd0;
        half_phase  = 1'b0;
        stage       = ST_IDLE;
        scope_open  = 1'b1;
        pv          = 1'b0;
        tx_line     = 1'b0;
        start_pulse = 1'b0;
        finish_pulse = 1'b0;
    end

    // Each enabled clock emits one Manchester half-bit. All state,
    // including the registered event strobes, holds during a stall.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (scope_end)
                scope_open <= 1'b0;

            start_pulse  <= 1'b0;
            finish_pulse <= 1'b0;

            case (stage)
                ST_IDLE, ST_DONE: begin
                    if (arm_cmd) begin
                        shift_data <= word_in;
                        bit_index  <= 32'd0;
                        half_phase <= 1'b0;
                        stage      <= ST_ARMED;
                    end
                end

                ST_ARMED, ST_STARTED: begin
                    if (!half_phase) begin
                        tx_line    <= shift_data[0];
                        half_phase <= 1'b1;
                        if (bit_index == 32'd0) begin
                            start_pulse <= 1'b1;
                            stage       <= ST_STARTED;
                        end
                    end else begin
                        tx_line    <= ~shift_data[0];
                        shift_data <= shift_data >> 32'd1;
                        half_phase <= 1'b0;
                        if (bit_index == LAST_BIT) begin
                            bit_index    <= 32'd0;
                            finish_pulse <= 1'b1;
                            stage        <= ST_DONE;
                        end else begin
                            bit_index <= bit_index + 32'd1;
                        end
                    end
                end
            endcase
        end
    end

    // Check the events produced by the previous enabled clock:
    // starting requires an earlier arm; finishing requires an earlier start.
    // scope_open permanently closes on the first enabled scope_end event.
    always @(posedge clk) begin
        if (pv && scope_open && $past(i_ce))
            assert ((!start_pulse || ($past(stage) == ST_ARMED)) &&
                    (!finish_pulse || ($past(stage) == ST_STARTED)));
    end
endmodule

module layer_token_forwarder #(
    parameter integer ENTRIES = 16,
    parameter integer WORD_W = 8,
    parameter integer ADDR_W = $clog2(ENTRIES)
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    output reg                   o_ready,
    input  wire [2:0]            i_cmd,
    input  wire [ADDR_W-1:0]     i_lane,
    output wire [WORD_W-1:0]     o_operand
);
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        ACTIVE = 2'b01
    } state_t;

    localparam logic [2:0] CMD_OPEN   = 3'd0;
    localparam logic [2:0] CMD_ARM    = 3'd1;
    localparam logic [2:0] CMD_START  = 3'd2;
    localparam logic [2:0] CMD_FINISH = 3'd3;
    localparam logic [2:0] CMD_CLOSE  = 3'd4;
    localparam logic [2:0] CMD_NOP    = 3'd5;

    localparam logic [WORD_W-1:0] TOKEN_EMPTY    = WORD_W'(8'd0);
    localparam logic [WORD_W-1:0] TOKEN_ARMED    = WORD_W'(8'd1);
    localparam logic [WORD_W-1:0] TOKEN_STARTED  = WORD_W'(8'd2);
    localparam logic [WORD_W-1:0] TOKEN_FINISHED = WORD_W'(8'd3);
    localparam logic [ADDR_W:0] LANE_COUNT = (ADDR_W+1)'(ENTRIES);

    state_t state;
    reg scope_window;
    reg [WORD_W-1:0] token_rf [0:ENTRIES-1];

    reg ex_valid, wb_valid;
    reg [ADDR_W-1:0] ex_lane, wb_lane;
    reg [WORD_W-1:0] ex_token, wb_token;

    reg [ENTRIES-1:0] arm_seen, start_seen;
    reg start_mark, finish_mark;
    reg [ADDR_W-1:0] event_lane;

    wire [WORD_W-1:0] bypass_view [0:ENTRIES-1];
    wire [ENTRIES-1:0] visible_armed;
    wire [ENTRIES-1:0] visible_started;
    wire [ENTRIES-1:0] rf_in_range;
    wire lane_valid = ({1'b0, i_lane} < LANE_COUNT);
    wire fire = i_valid && o_ready;

    // Newest result wins over writeback, which wins over the register file.
    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : forwarding
            assign bypass_view[g] =
                (ex_valid && ex_lane == ADDR_W'(g)) ? ex_token :
                (wb_valid && wb_lane == ADDR_W'(g)) ? wb_token :
                token_rf[g];
            assign visible_armed[g] = bypass_view[g] >= TOKEN_ARMED;
            assign visible_started[g] = bypass_view[g] >= TOKEN_STARTED;
            assign rf_in_range[g] = token_rf[g] <= TOKEN_FINISHED;
        end
    endgenerate

    assign o_operand = bypass_view[i_lane];

    // Dependency back-pressure: a command waits for its prerequisite token.
    always @(*) begin
        o_ready = 1'b0;
        if (i_ce && lane_valid) begin
            case (state)
                IDLE: o_ready = (i_cmd == CMD_OPEN);
                ACTIVE: begin
                    case (i_cmd)
                        CMD_ARM:    o_ready = (o_operand == TOKEN_EMPTY);
                        CMD_START:  o_ready = (o_operand == TOKEN_ARMED);
                        CMD_FINISH: o_ready = (o_operand == TOKEN_STARTED);
                        CMD_CLOSE, CMD_NOP: o_ready = 1'b1;
                        default: o_ready = 1'b0;
                    endcase
                end
                default: o_ready = 1'b0;
            endcase
        end
    end

    integer k;
    initial begin
        state = IDLE;
        scope_window = 1'b0;
        ex_valid = 1'b0;
        wb_valid = 1'b0;
        ex_lane = {ADDR_W{1'b0}};
        wb_lane = {ADDR_W{1'b0}};
        ex_token = TOKEN_EMPTY;
        wb_token = TOKEN_EMPTY;
        arm_seen = {ENTRIES{1'b0}};
        start_seen = {ENTRIES{1'b0}};
        start_mark = 1'b0;
        finish_mark = 1'b0;
        event_lane = {ADDR_W{1'b0}};
        for (k = 0; k < ENTRIES; k = k + 1)
            token_rf[k] = TOKEN_EMPTY;
    end

    // Every state element holds unless an input item is accepted.
    // OPEN starts a fresh layer window; CLOSE ends it.
    always @(posedge clk) begin
        if (fire) begin
            start_mark <= 1'b0;
            finish_mark <= 1'b0;
            event_lane <= i_lane;

            if (state == IDLE) begin
                state <= ACTIVE;
                scope_window <= 1'b1;
                arm_seen <= {ENTRIES{1'b0}};
                start_seen <= {ENTRIES{1'b0}};
                ex_valid <= 1'b0;
                wb_valid <= 1'b0;
                ex_lane <= {ADDR_W{1'b0}};
                wb_lane <= {ADDR_W{1'b0}};
                ex_token <= TOKEN_EMPTY;
                wb_token <= TOKEN_EMPTY;
                for (k = 0; k < ENTRIES; k = k + 1)
                    token_rf[k] <= TOKEN_EMPTY;
            end else begin
                if (wb_valid)
                    token_rf[wb_lane] <= wb_token;
                wb_valid <= ex_valid;
                wb_lane <= ex_lane;
                wb_token <= ex_token;
                ex_valid <= 1'b0;

                case (i_cmd)
                    CMD_ARM: begin
                        ex_valid <= 1'b1;
                        ex_lane <= i_lane;
                        ex_token <= TOKEN_ARMED;
                        arm_seen[i_lane] <= 1'b1;
                    end
                    CMD_START: begin
                        ex_valid <= 1'b1;
                        ex_lane <= i_lane;
                        ex_token <= o_operand + TOKEN_ARMED;
                        start_seen[i_lane] <= 1'b1;
                        start_mark <= 1'b1;
                    end
                    CMD_FINISH: begin
                        ex_valid <= 1'b1;
                        ex_lane <= i_lane;
                        ex_token <= o_operand + TOKEN_ARMED;
                        finish_mark <= 1'b1;
                    end
                    CMD_CLOSE: begin
                        state <= IDLE;
                        scope_window <= 1'b0;
                    end
                    default: begin end
                endcase
            end
        end
    end

    // Marks describe the most recently accepted item and hold during stalls.
    // Within the open window, START requires ARM, and FINISH requires both.
    always @(posedge clk)
        assert (!scope_window ||
                ((!start_mark || arm_seen[event_lane]) &&
                 (!finish_mark ||
                  (arm_seen[event_lane] && start_seen[event_lane]))));
endmodule

module operand_forward_window #(
    parameter integer WORD_W = 32,
    parameter integer REG_ENTRIES = 48
) (
    input wire clk,
    input wire i_ce,
    input wire open_decode,
    input wire close_decode,
    input wire [31:0] i_src_a,
    input wire [31:0] i_src_b,
    input wire i_ex_valid,
    input wire [31:0] i_ex_rd,
    input wire [WORD_W-1:0] i_ex_value,
    input wire i_wb_valid,
    input wire [31:0] i_wb_rd,
    input wire [WORD_W-1:0] i_wb_value,
    output logic [WORD_W-1:0] operand_a,
    output logic [WORD_W-1:0] operand_b,
    output wire operands_ready
);
    typedef enum logic [1:0] {
        QUIET     = 2'b00,
        RESOLVE_A = 2'b01,
        RESOLVE_B = 2'b10,
        READY     = 2'b11
    } phase_t;

    phase_t phase;
    logic window_open;
    logic past_valid;
    logic [1:0] resolved;
    logic [1:0] used_forward;
    logic [31:0] forward_count;
    logic [31:0] src_a, src_b;

    logic ex_valid, wb_valid;
    logic [31:0] ex_rd, wb_rd;
    logic [WORD_W-1:0] ex_value, wb_value;
    logic [WORD_W-1:0] regfile [0:REG_ENTRIES-1];

    // Address inputs are unrestricted. Out-of-range register reads return zero.
    wire a_in_range = src_a < REG_ENTRIES;
    wire b_in_range = src_b < REG_ENTRIES;
    wire a_ex_hit = a_in_range && ex_valid && (src_a == ex_rd);
    wire a_wb_hit = a_in_range && wb_valid && (src_a == wb_rd);
    wire b_ex_hit = b_in_range && ex_valid && (src_b == ex_rd);
    wire b_wb_hit = b_in_range && wb_valid && (src_b == wb_rd);
    wire a_uses_forward = a_ex_hit || a_wb_hit;
    wire b_uses_forward = b_ex_hit || b_wb_hit;

    wire [WORD_W-1:0] rf_a = a_in_range ? regfile[src_a] : {WORD_W{1'b0}};
    wire [WORD_W-1:0] rf_b = b_in_range ? regfile[src_b] : {WORD_W{1'b0}};

    // The newer EX producer has priority over the WB producer.
    wire [WORD_W-1:0] mux_a = a_ex_hit ? ex_value :
                                  a_wb_hit ? wb_value : rf_a;
    wire [WORD_W-1:0] mux_b = b_ex_hit ? ex_value :
                                  b_wb_hit ? wb_value : rf_b;

    assign operands_ready = (phase == READY);

    initial begin
        phase = QUIET;
        window_open = 1'b0;
        past_valid = 1'b0;
        resolved = 2'b00;
        used_forward = 2'b00;
        forward_count = 32'd0;
        src_a = 32'd0;
        src_b = 32'd0;
        ex_valid = 1'b0;
        wb_valid = 1'b0;
        ex_rd = 32'd0;
        wb_rd = 32'd0;
        ex_value = {WORD_W{1'b0}};
        wb_value = {WORD_W{1'b0}};
        operand_a = {WORD_W{1'b0}};
        operand_b = {WORD_W{1'b0}};
        for (integer n = 32'd0; n < REG_ENTRIES; n = n + 32'd1)
            regfile[n] = {WORD_W{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            ex_valid <= i_ex_valid;
            ex_rd <= i_ex_rd;
            ex_value <= i_ex_value;
            wb_valid <= i_wb_valid;
            wb_rd <= i_wb_rd;
            wb_value <= i_wb_value;

            if (wb_valid && (wb_rd < REG_ENTRIES))
                regfile[wb_rd] <= wb_value;

            case (phase)
                QUIET: begin
                    if (open_decode) begin
                        src_a <= i_src_a;
                        src_b <= i_src_b;
                        resolved <= 2'b00;
                        used_forward <= 2'b00;
                        forward_count <= 32'd0;
                        window_open <= 1'b1;
                        phase <= RESOLVE_A;
                    end
                end
                RESOLVE_A: begin
                    operand_a <= mux_a;
                    resolved[0] <= 1'b1;
                    used_forward[0] <= a_uses_forward;
                    forward_count <= forward_count +
                                     (a_uses_forward ? 32'd1 : 32'd0);
                    phase <= RESOLVE_B;
                end
                RESOLVE_B: begin
                    operand_b <= mux_b;
                    resolved[1] <= 1'b1;
                    used_forward[1] <= b_uses_forward;
                    forward_count <= forward_count +
                                     (b_uses_forward ? 32'd1 : 32'd0);
                    phase <= READY;
                end
                READY: begin
                    if (close_decode) begin
                        window_open <= 1'b0;
                        phase <= QUIET;
                    end
                end
            endcase
        end
    end

    // Within each decode window, at most two operands use forwarding.
    // If resolution progress is unchanged, its forwarding count is unchanged.
    always @(posedge clk) begin
        if (past_valid && window_open)
            assert ((forward_count <= 32'd2) &&
                    (!$stable(resolved) || $stable(forward_count)));
    end
endmodule

module uart_flow_monitor #(
    parameter [63:0] RX_DEPTH = 64'd2
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cts,
    input  wire        tx_request,
    input  wire        rx_push,
    input  wire        rx_pop,
    input  wire        cfg_valid,
    input  wire [63:0] cfg_assert_threshold,
    input  wire [63:0] cfg_deassert_threshold,
    input  wire        end_capture,
    output reg         rts,
    output reg         tx_grant,
    output reg  [63:0] rx_fill
);
    typedef enum logic [1:0] {
        CTS_BLOCKED = 2'b00,
        CTS_READY   = 2'b01
    } tx_state_t;

    tx_state_t tx_state;
    reg cts_meta;
    reg cts_sync;
    reg [63:0] assert_threshold;
    reg [63:0] deassert_threshold;
    reg before_end;
    reg pv;

    wire take_rx = rx_push && (rx_fill < RX_DEPTH);
    wire take_pop = rx_pop && (rx_fill != 64'd0);
    wire [63:0] next_fill =
        (take_rx && !take_pop) ? rx_fill + 64'd1 :
        (take_pop && !take_rx) ? rx_fill - 64'd1 : rx_fill;

    wire accept_config = cfg_valid &&
        (cfg_assert_threshold > 64'd0) &&
        (cfg_assert_threshold <= RX_DEPTH) &&
        (cfg_deassert_threshold < cfg_assert_threshold);
    wire [63:0] next_assert_threshold = accept_config ?
        cfg_assert_threshold : assert_threshold;
    wire [63:0] next_deassert_threshold = accept_config ?
        cfg_deassert_threshold : deassert_threshold;

    initial begin
        tx_state = CTS_BLOCKED;
        cts_meta = 1'b0;
        cts_sync = 1'b0;
        assert_threshold = RX_DEPTH;
        deassert_threshold = 64'd0;
        rx_fill = 64'd0;
        rts = 1'b1;
        tx_grant = 1'b0;
        before_end = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (end_capture)
                before_end <= 1'b0;

            // The permission controller decodes the final CTS sample.
            cts_meta <= cts;
            cts_sync <= cts_meta;
            if (cts_meta)
                tx_state <= CTS_READY;
            else
                tx_state <= CTS_BLOCKED;

            tx_grant <= tx_request && (tx_state == CTS_READY);

            rx_fill <= next_fill;
            assert_threshold <= next_assert_threshold;
            deassert_threshold <= next_deassert_threshold;

            // Active-high RTS permits reception; retain it in the hysteresis band.
            if (next_fill >= next_assert_threshold)
                rts <= 1'b0;
            else if (next_fill <= next_deassert_threshold)
                rts <= 1'b1;
        end
    end

    // Before capture ends, a grant for the previous enabled cycle must
    // never coincide with CTS having been blocked in that cycle.
    always @(posedge clk) begin
        if (pv && before_end && $past(i_ce))
            assert (!(tx_grant && !$past(cts_sync)));
    end
endmodule

module soc_event_pending_sync #(
    parameter integer DATA_W = 128,
    parameter integer DEPTH = 2
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_ce,
    input  wire                  i_pulse,
    input  wire                  i_slow_tick,
    input  wire [DATA_W-1:0]     i_data,
    output wire                  o_ready,
    output wire                  o_slow_pulse,
    output reg  [DATA_W-1:0]     o_slow_data
);
    localparam integer PTR_W = (DEPTH > 1) ? $clog2(DEPTH) : 1;
    localparam integer PEND_W = $clog2(DEPTH + 1);
    localparam integer OUT_W = $clog2(DEPTH + 2);

    localparam [PTR_W-1:0] LAST_PTR = DEPTH - 1;
    localparam [PTR_W-1:0] PTR_ONE = {{(PTR_W-1){1'b0}}, 1'b1};
    localparam [PEND_W-1:0] PENDING_LIMIT = DEPTH;
    localparam [PEND_W-1:0] PENDING_ONE = {{(PEND_W-1){1'b0}}, 1'b1};
    localparam [OUT_W-1:0] OUTSTANDING_LIMIT = DEPTH + 1;
    localparam [OUT_W-1:0] OUTSTANDING_ONE = {{(OUT_W-1){1'b0}}, 1'b1};

    reg [DATA_W-1:0] payload_mem [0:DEPTH-1];
    reg [DATA_W-1:0] flight_data;
    reg [PTR_W-1:0] wr_ptr, rd_ptr;
    reg [PEND_W-1:0] pending;
    reg [OUT_W-1:0] outstanding;
    reg req_toggle, req_meta, req_sync;
    reg ack_toggle, ack_meta, ack_sync;

    wire enqueue;
    wire launch;
    wire retire;

    assign o_ready = pending < PENDING_LIMIT;
    assign enqueue = i_pulse && o_ready;
    assign launch = (pending != {PEND_W{1'b0}}) &&
                    (req_toggle == ack_sync);
    assign retire = i_slow_tick && (req_sync != ack_toggle);
    assign o_slow_pulse = i_ce && retire;

    initial begin
        flight_data = {DATA_W{1'b0}};
        o_slow_data = {DATA_W{1'b0}};
        wr_ptr = {PTR_W{1'b0}};
        rd_ptr = {PTR_W{1'b0}};
        pending = {PEND_W{1'b0}};
        outstanding = {OUT_W{1'b0}};
        req_toggle = 1'b0;
        req_meta = 1'b0;
        req_sync = 1'b0;
        ack_toggle = 1'b0;
        ack_meta = 1'b0;
        ack_sync = 1'b0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : gen_payload
            localparam [PTR_W-1:0] SLOT_INDEX = g;
            initial payload_mem[g] = {DATA_W{1'b0}};
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    payload_mem[g] <= {DATA_W{1'b0}};
                else if (i_ce && enqueue && (wr_ptr == SLOT_INDEX))
                    payload_mem[g] <= i_data;
            end
        end
    endgenerate

    // i_slow_tick models edges of the slower destination domain.
    // The request and acknowledgement each cross through two stages.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            flight_data <= {DATA_W{1'b0}};
            o_slow_data <= {DATA_W{1'b0}};
            wr_ptr <= {PTR_W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}};
            pending <= {PEND_W{1'b0}};
            outstanding <= {OUT_W{1'b0}};
            req_toggle <= 1'b0;
            req_meta <= 1'b0;
            req_sync <= 1'b0;
            ack_toggle <= 1'b0;
            ack_meta <= 1'b0;
            ack_sync <= 1'b0;
        end else if (i_ce) begin
            ack_meta <= ack_toggle;
            ack_sync <= ack_meta;

            if (i_slow_tick) begin
                req_meta <= req_toggle;
                req_sync <= req_meta;
                if (req_sync != ack_toggle) begin
                    ack_toggle <= req_sync;
                    o_slow_data <= flight_data;
                end
            end

            if (enqueue) begin
                if (wr_ptr == LAST_PTR)
                    wr_ptr <= {PTR_W{1'b0}};
                else
                    wr_ptr <= wr_ptr + PTR_ONE;
            end

            if (launch) begin
                flight_data <= payload_mem[rd_ptr];
                req_toggle <= ~req_toggle;
                if (rd_ptr == LAST_PTR)
                    rd_ptr <= {PTR_W{1'b0}};
                else
                    rd_ptr <= rd_ptr + PTR_ONE;
            end

            case ({enqueue, launch})
                2'b10: pending <= pending + PENDING_ONE;
                2'b01: pending <= pending - PENDING_ONE;
                default: begin end
            endcase

            // Account for accepted pulses until destination consumption.
            case ({enqueue, retire})
                2'b10: outstanding <= outstanding + OUTSTANDING_ONE;
                2'b01: outstanding <= outstanding - OUTSTANDING_ONE;
                default: begin end
            endcase
        end
    end

    assert property (
        !((pending == {PEND_W{1'b0}}) && (req_toggle == ack_toggle)) ||
        (outstanding == {OUT_W{1'b0}})
    );
endmodule

module soc_oai_access_partition #(
    parameter WORD_W = 128
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_commit,
    input  wire [WORD_W-1:0]     i_core_mask,
    input  wire [WORD_W-1:0]     i_accel_mask,
    input  wire [WORD_W-1:0]     i_region_mask,
    output wire [WORD_W-1:0]     o_allow,
    output wire [WORD_W-1:0]     o_deny
);
    reg [WORD_W-1:0] core_mask_q;
    reg [WORD_W-1:0] accel_mask_q;
    reg [WORD_W-1:0] region_mask_q;
    reg [WORD_W-1:0] oai_deny_q;
    reg [WORD_W-1:0] allow_q;
    reg [WORD_W-1:0] deny_q;
    reg before_commit;

    // A bank of combinational OAI21 gates; no state inside this stage.
    wire [WORD_W-1:0] oai_deny;
    assign oai_deny = ~((i_core_mask | i_accel_mask) & i_region_mask);

    // The scope-ending event is an enabled commit.
    wire commit_event;
    assign commit_event = i_ce && i_commit;

    initial begin
        core_mask_q  = {WORD_W{1'b0}};
        accel_mask_q = {WORD_W{1'b0}};
        region_mask_q = {WORD_W{1'b0}};
        oai_deny_q   = {WORD_W{1'b1}};
        allow_q      = {WORD_W{1'b0}};
        deny_q       = {WORD_W{1'b1}};
        before_commit = 1'b1;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            core_mask_q   <= i_core_mask;
            accel_mask_q  <= i_accel_mask;
            region_mask_q <= i_region_mask;
            oai_deny_q    <= oai_deny;

            // Assemble complementary access classifications from the snapshot.
            allow_q <= (core_mask_q | accel_mask_q) & region_mask_q;
            deny_q  <= oai_deny_q;

            if (commit_event)
                before_commit <= 1'b0;
        end
    end

    assign o_allow = allow_q;
    assign o_deny  = deny_q;

    always @(posedge clk) begin
        if (before_commit) begin
            assert ((allow_q & deny_q) == {WORD_W{1'b0}});
            assert ((allow_q | deny_q) == {WORD_W{1'b1}});
        end
    end
endmodule

module display_permission_pipeline #(
    parameter integer WORD_W = 16
) (
    input wire clk,
    input wire i_ce,
    input wire i_frame_end,
    input wire [WORD_W-1:0] i_request,
    input wire [WORD_W-1:0] i_grant,
    output reg issued
);
    localparam [WORD_W-1:0] WORD_ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] WORD_ONES = {WORD_W{1'b1}};

    reg [WORD_W-1:0] request_word;
    reg [WORD_W-1:0] grant_word;
    reg [WORD_W-1:0] implication_word;
    reg [WORD_W-1:0] shadow_request;
    reg [WORD_W-1:0] shadow_grant;
    reg before_frame_end;
    reg past_valid;

    // One stateless IMPLY gate per display-request bit.
    wire [WORD_W-1:0] implication_gate;
    assign implication_gate = (~i_request) | i_grant;

    initial begin
        request_word = WORD_ZERO;
        grant_word = WORD_ZERO;
        implication_word = WORD_ONES;
        shadow_request = WORD_ZERO;
        shadow_grant = WORD_ZERO;
        issued = 1'b0;
        before_frame_end = 1'b1;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Capture requests, their permissions, and the IMPLY result.
            request_word <= i_request;
            grant_word <= i_grant;
            implication_word <= implication_gate;

            // Issue the preceding request only if every implication passed.
            issued <= (request_word != WORD_ZERO) &&
                      (implication_word == WORD_ONES);
            shadow_request <= request_word;
            shadow_grant <= grant_word;

            past_valid <= 1'b1;
            if (i_frame_end)
                before_frame_end <= 1'b0;
        end
    end

    // Before the first frame-end event, an issue rising edge must be
    // preceded by a nonempty request with all requested permissions granted.
    always @(posedge clk) begin
        if (past_valid && before_frame_end && $rose(issued))
            assert ((shadow_request != WORD_ZERO) &&
                    ((shadow_request & ~shadow_grant) == WORD_ZERO));
    end
endmodule

module scoped_bridge_token_cam #(
    parameter integer ENTRIES = 32'd32,
    parameter integer DATA_W = 32'd16
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire scope_open,
    input wire scope_close,
    input wire byte_valid,
    input wire [DATA_W-1:0] stream_data,
    input wire cfg_write,
    input wire [DATA_W-1:0] cfg_addr,
    input wire [DATA_W-1:0] cfg_data,
    output reg scope_active,
    output reg arm_seen,
    output reg start_seen,
    output reg finish_seen
);
    localparam integer ARM_COUNT = ENTRIES / 32'd4;
    localparam integer START_COUNT = ENTRIES / 32'd4;
    localparam [DATA_W-1:0] ENTRY_LIMIT = DATA_W'(ENTRIES);
    localparam [ENTRIES-1:0] ARM_MASK =
        {ENTRIES{1'b1}} >> (ENTRIES - ARM_COUNT);
    localparam [ENTRIES-1:0] START_MASK =
        ({ENTRIES{1'b1}} >> (ENTRIES - START_COUNT)) << ARM_COUNT;
    localparam [ENTRIES-1:0] FINISH_MASK = ~(ARM_MASK | START_MASK);

    reg [DATA_W-1:0] patterns [0:ENTRIES-1];
    reg [ENTRIES-1:0] pattern_valid;
    reg [DATA_W-1:0] window;

    // Each accepted transfer contributes its low byte to the sliding window.
    wire [DATA_W-1:0] shifted_window;
    assign shifted_window =
        {window[DATA_W-32'd9:0], stream_data[7:0]};

    wire [ENTRIES-1:0] match_bits;
    genvar g;
    generate
        for (g = 32'd0; g < ENTRIES; g = g + 32'd1) begin : cam_compare
            assign match_bits[g] = pattern_valid[g] &&
                                   (patterns[g] == shifted_window);
        end
    endgenerate

    wire arm_hit = |(match_bits & ARM_MASK);
    wire start_hit = |(match_bits & START_MASK);
    wire finish_hit = |(match_bits & FINISH_MASK);

    initial begin
        scope_active = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        finish_seen = 1'b0;
        pattern_valid = {ENTRIES{1'b0}};
        window = {DATA_W{1'b0}};
        for (integer n = 32'd0; n < ENTRIES; n = n + 32'd1)
            patterns[n] = DATA_W'(16'h4100) + DATA_W'(n);
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            scope_active <= 1'b0;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            finish_seen <= 1'b0;
            pattern_valid <= {ENTRIES{1'b0}};
            window <= {DATA_W{1'b0}};
            for (integer n = 32'd0; n < ENTRIES; n = n + 32'd1)
                patterns[n] <= DATA_W'(16'h4100) + DATA_W'(n);
        end else if (i_ce) begin
            if (cfg_write && (cfg_addr < ENTRY_LIMIT))
                patterns[cfg_addr] <= cfg_data;

            if (byte_valid)
                window <= shifted_window;

            // The CAM bank-valid mask encodes the sequencing state:
            // ARM bank, START bank, FINISH bank, then no enabled bank.
            if (scope_close) begin
                scope_active <= 1'b0;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                finish_seen <= 1'b0;
                pattern_valid <= {ENTRIES{1'b0}};
            end else if (scope_open && !scope_active) begin
                scope_active <= 1'b1;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                finish_seen <= 1'b0;
                pattern_valid <= ARM_MASK;
            end else if (scope_active && byte_valid) begin
                if (arm_hit) begin
                    arm_seen <= 1'b1;
                    pattern_valid <= START_MASK;
                end else if (start_hit) begin
                    start_seen <= 1'b1;
                    pattern_valid <= FINISH_MASK;
                end else if (finish_hit) begin
                    finish_seen <= 1'b1;
                    pattern_valid <= {ENTRIES{1'b0}};
                end
            end
        end
    end

    // Within the latched scope, START requires ARM and FINISH requires both.
    always @(*) begin
        if (scope_active)
            assert ((!start_seen || arm_seen) &&
                    (!finish_seen || (arm_seen && start_seen)));
    end
endmodule

module split_counter_response #(
    parameter integer WORD_WIDTH = 64,
    parameter integer WORK_CYCLES = 4
) (
    input  wire                  clk,
    input  wire                  request_valid,
    output wire                  request_ready,
    output wire                  response_valid,
    input  wire                  response_ready,
    output wire [WORD_WIDTH-1:0]  response_data,
    output wire                  response_last
);
    localparam logic [WORD_WIDTH-1:0] ZERO = {WORD_WIDTH{1'b0}};
    localparam logic [WORD_WIDTH-1:0] ONE = {{(WORD_WIDTH-1){1'b0}}, 1'b1};
    localparam logic [WORD_WIDTH-1:0] WORK_LIMIT = WORD_WIDTH'(WORK_CYCLES);
    localparam logic [WORD_WIDTH-1:0] START_LOW = ONE - WORK_LIMIT;

    typedef enum logic [1:0] {
        IDLE = 2'b00,
        BUSY = 2'b01,
        DONE = 2'b10
    } state_t;

    state_t state;
    logic [WORD_WIDTH-1:0] low_word;
    logic [WORD_WIDTH-1:0] high_word;
    logic carry_q;
    logic [WORD_WIDTH-1:0] countdown;
    logic before_first_completion;

    wire [WORD_WIDTH-1:0] high_next;
    assign high_next = high_word + {{(WORD_WIDTH-1){1'b0}}, carry_q};

    assign request_ready = (state == IDLE);
    assign response_valid = (state == BUSY) || (state == DONE);
    assign response_data = countdown;
    assign response_last = (state == DONE);

    initial begin
        state = IDLE;
        low_word = ZERO;
        high_word = ZERO;
        carry_q = 1'b0;
        countdown = ZERO;
        before_first_completion = 1'b1;
    end

    // Response transfers are enabled work cycles. Back-pressure pauses
    // both the split counter and its deadline, holding the output steady.
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (request_valid && request_ready) begin
                    state <= BUSY;
                    low_word <= START_LOW;
                    high_word <= ZERO;
                    carry_q <= 1'b0;
                    countdown <= WORK_LIMIT;
                end
            end

            BUSY: begin
                if (response_valid && response_ready && countdown != ZERO) begin
                    low_word <= low_word + ONE;
                    high_word <= high_next;
                    // The high segment consumes this carry on the next
                    // enabled cycle, not on the low segment's wrap cycle.
                    carry_q <= &low_word;
                    countdown <= countdown - ONE;
                    if (high_next == ONE)
                        state <= DONE;
                end
            end

            DONE: begin
                if (response_valid && response_ready) begin
                    state <= IDLE;
                    low_word <= ZERO;
                    high_word <= ZERO;
                    carry_q <= 1'b0;
                    countdown <= ZERO;
                    // Scope ends permanently at the first final transfer.
                    before_first_completion <= 1'b0;
                end
            end

            default: begin
                // Unused controller encoding holds its state.
            end
        endcase
    end

    // Before the first completion transfer, an accepted request must
    // finish processing before its enabled-cycle countdown expires.
    always @(*) begin
        if (before_first_completion && state == BUSY)
            assert (countdown != ZERO);
    end
endmodule

module video_allpass_sweep #(
    parameter [31:0] DEPTH = 32'd256,
    parameter [31:0] GAIN_SHIFT = 32'd1
) (
    input  wire               clk,
    input  wire               i_ce,
    input  wire               i_frame_sync,
    input  wire               i_block_start,
    input  wire signed [31:0] i_sample,
    output reg  signed [31:0] o_sample
);
    reg signed [31:0] delay_mem [0:DEPTH-32'd1];
    reg [31:0] ptr;
    reg [31:0] countdown;
    reg busy;
    reg armed;
    integer init_index;

    // Schroeder allpass with dyadic gain g = 2^(-GAIN_SHIFT):
    // y = delayed - g*x; delay_write = x + g*y.
    // Arithmetic shifts implement the fixed-point gain coefficient.
    wire signed [31:0] delayed_sample;
    wire signed [31:0] feedforward;
    wire signed [31:0] allpass_sample;
    wire signed [31:0] feedback;
    wire signed [31:0] delay_write;

    assign delayed_sample = delay_mem[ptr];
    assign feedforward = i_sample >>> GAIN_SHIFT;
    assign allpass_sample = delayed_sample - feedforward;
    assign feedback = allpass_sample >>> GAIN_SHIFT;
    assign delay_write = i_sample + feedback;

    initial begin
        ptr = 32'd0;
        countdown = 32'd0;
        busy = 1'b0;
        armed = 1'b0;
        o_sample = 32'sd0;
        for (init_index = 32'd0; init_index < DEPTH;
             init_index = init_index + 32'd1)
            delay_mem[init_index] = 32'sd0;
    end

    // Each accepted block processes one complete circular-buffer sweep.
    // Countdown measures enabled processing cycles; i_ce freezes all state.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_frame_sync)
                armed <= 1'b1;

            if (!busy) begin
                if (i_block_start) begin
                    busy <= 1'b1;
                    ptr <= 32'd0;
                    countdown <= DEPTH;
                end
            end else begin
                o_sample <= allpass_sample;
                delay_mem[ptr] <= delay_write;

                if (ptr == (DEPTH - 32'd1)) begin
                    ptr <= 32'd0;
                    countdown <= 32'd0;
                    busy <= 1'b0;
                end else begin
                    ptr <= ptr + 32'd1;
                    countdown <= countdown - 32'd1;
                end
            end
        end
    end

    // After the first enabled frame-sync event, an outstanding block
    // must never exhaust its processing-cycle deadline.
    assert property (!armed || !busy || (countdown != 32'd0));
endmodule

module gesture_operand_sort #(
    parameter integer WORD_W = 128,
    parameter integer EXP_W = 15
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_a_sig,
    input  wire [WORD_W-1:0]     in_b_sig,
    input  wire [EXP_W-1:0]      in_a_exp,
    input  wire [EXP_W-1:0]      in_b_exp,
    input  wire                  in_last,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [WORD_W-1:0]     large_sig,
    output reg  [WORD_W-1:0]     small_sig,
    output reg  [EXP_W-1:0]      large_exp,
    output reg  [EXP_W-1:0]      small_exp,
    output reg  [EXP_W-1:0]      exponent_gap,
    output reg                   swap_flag,
    output reg                   out_last,
    output reg  [EXP_W-1:0]      retired_span
);
    reg before_frame_end;
    reg pv;

    wire swap_inputs = (in_a_exp < in_b_exp) ||
                       ((in_a_exp == in_b_exp) &&
                        (in_a_sig < in_b_sig));
    assign in_ready = !out_valid || out_ready;
    wire in_fire = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    initial begin
        out_valid = 1'b0;
        large_sig = {WORD_W{1'b0}};
        small_sig = {WORD_W{1'b0}};
        large_exp = {EXP_W{1'b0}};
        small_exp = {EXP_W{1'b0}};
        exponent_gap = {EXP_W{1'b0}};
        swap_flag = 1'b0;
        out_last = 1'b0;
        retired_span = {EXP_W{1'b0}};
        before_frame_end = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (in_fire || out_fire)
            pv <= 1'b1;

        if (in_fire) begin
            out_valid <= 1'b1;
            swap_flag <= swap_inputs;
            out_last <= in_last;
            if (swap_inputs) begin
                large_sig <= in_b_sig;
                small_sig <= in_a_sig;
                large_exp <= in_b_exp;
                small_exp <= in_a_exp;
                exponent_gap <= in_b_exp - in_a_exp;
            end else begin
                large_sig <= in_a_sig;
                small_sig <= in_b_sig;
                large_exp <= in_a_exp;
                small_exp <= in_b_exp;
                exponent_gap <= in_a_exp - in_b_exp;
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end

        // Alignment-span telemetry for the operand pair just consumed.
        if (out_fire)
            retired_span <= large_exp - small_exp;

        // Permanently close the checking scope at the first frame end.
        if (out_fire && out_last)
            before_frame_end <= 1'b0;
    end

    always @(posedge clk) begin
        if (pv && before_frame_end && $past(out_fire))
            assert (retired_span == $past(exponent_gap));
    end
endmodule

module rrip_partition_replacer #(
    parameter integer ENTRIES = 64,
    parameter integer WORD_W = 8
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  cmd_valid,
    output wire                  cmd_ready,
    input  wire [7:0]            cmd_opcode,
    input  wire [WORD_W-1:0]     cmd_index,
    output reg                   victim_valid,
    input  wire                  victim_ready,
    output reg [WORD_W-1:0]      victim_index
);
    localparam [7:0] CMD_OPEN  = 8'h01;
    localparam [7:0] CMD_PROBE = 8'h02;
    localparam [7:0] CMD_TOUCH = 8'h03;
    localparam [WORD_W-1:0] ZERO_AGE = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] AGE_ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] MAX_AGE = {WORD_W{1'b1}};
    localparam [WORD_W-1:0] INSERT_AGE = MAX_AGE - AGE_ONE;

    // Packed storage contains one re-reference prediction counter per line.
    reg [ENTRIES*WORD_W-1:0] rrpv;
    reg [ENTRIES-1:0] far_mask;
    wire [ENTRIES-1:0] far_from_age;
    reg window_active;
    reg far_seen_at_probe;
    reg [WORD_W-1:0] candidate_index;

    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : decode_age
            assign far_from_age[g] =
                (rrpv[g*WORD_W +: WORD_W] == MAX_AGE);
        end
    endgenerate

    integer k;
    always @(*) begin
        candidate_index = ZERO_AGE;
        for (k = 32'd0; k < ENTRIES; k = k + 32'd1)
            if (far_mask[k])
                candidate_index = k;
    end

    // OPEN starts a replacement window. Each PROBE services one search
    // step. TOUCH records reuse outside a replacement transaction.
    wire legal_command =
        ((cmd_opcode == CMD_OPEN) && !window_active) ||
        ((cmd_opcode == CMD_PROBE) && window_active) ||
        ((cmd_opcode == CMD_TOUCH) && !window_active &&
         (cmd_index < ENTRIES));
    assign cmd_ready = !victim_valid && legal_command;

    initial begin
        rrpv = {ENTRIES{INSERT_AGE}};
        far_mask = {ENTRIES{1'b0}};
        window_active = 1'b0;
        far_seen_at_probe = 1'b0;
        victim_valid = 1'b0;
        victim_index = ZERO_AGE;
    end

    integer n;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rrpv <= {ENTRIES{INSERT_AGE}};
            far_mask <= {ENTRIES{1'b0}};
            window_active <= 1'b0;
            far_seen_at_probe <= 1'b0;
            victim_valid <= 1'b0;
            victim_index <= ZERO_AGE;
        end else begin
            if (victim_valid && victim_ready) begin
                // Install the replacement only when the victim is accepted.
                rrpv[victim_index*WORD_W +: WORD_W] <= INSERT_AGE;
                far_mask[victim_index] <= 1'b0;
                victim_valid <= 1'b0;
                window_active <= 1'b0;
                far_seen_at_probe <= 1'b0;
            end else if (cmd_valid && cmd_ready) begin
                case (cmd_opcode)
                    CMD_OPEN: begin
                        window_active <= 1'b1;
                        far_seen_at_probe <= 1'b0;
                    end
                    CMD_PROBE: begin
                        if (|far_mask) begin
                            victim_index <= candidate_index;
                            victim_valid <= 1'b1;
                            // Shadow the eligibility observed before issue.
                            far_seen_at_probe <=
                                (rrpv[candidate_index*WORD_W +: WORD_W] == MAX_AGE);
                        end else begin
                            // RRIP ages all predictions when no victim exists.
                            for (n = 32'd0; n < ENTRIES; n = n + 32'd1) begin
                                if (rrpv[n*WORD_W +: WORD_W] != MAX_AGE)
                                    rrpv[n*WORD_W +: WORD_W] <=
                                        rrpv[n*WORD_W +: WORD_W] + AGE_ONE;
                                far_mask[n] <=
                                    (rrpv[n*WORD_W +: WORD_W] >= INSERT_AGE);
                            end
                        end
                    end
                    CMD_TOUCH: begin
                        rrpv[cmd_index*WORD_W +: WORD_W] <= ZERO_AGE;
                        far_mask[cmd_index] <= 1'b0;
                    end
                    default: begin end
                endcase
            end
        end
    end

    // Inside the open-to-accept window, presenting a victim requires an
    // earlier probe that observed the selected line at maximum age.
    assert property (!(window_active && victim_valid) || far_seen_at_probe);
endmodule

module can_tx_write_order #(
    parameter integer DATA_WIDTH = 128,
    parameter integer DEPTH = 8,
    parameter integer PORTS = 4,
    parameter integer DEST_W = (PORTS > 1) ? $clog2(PORTS) : 1
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_scope_begin,
    input  wire                  i_scope_end,
    input  wire                  i_aw_issue,
    input  wire [DEST_W-1:0]     i_aw_dest,
    input  wire                  i_w_issue,
    input  wire [DATA_WIDTH-1:0] i_wdata,
    input  wire                  i_wlast,
    output wire [DEST_W-1:0]     o_wdest,
    output wire [DATA_WIDTH-1:0] o_wdata,
    output wire                  o_wbeat
);
    localparam integer PTR_W = (DEPTH > 1) ? $clog2(DEPTH) : 1;
    localparam integer COUNT_W = $clog2(DEPTH + 1);
    localparam [PTR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W:0] EXT_CAPACITY = DEPTH;
    localparam [1:0] PH_WAIT   = 2'd0;
    localparam [1:0] PH_START  = 2'd1;
    localparam [1:0] PH_STREAM = 2'd2;
    localparam [1:0] PH_FINISH = 2'd3;

    // AW commands arm FIFO entries in address-acceptance order.
    reg [DEST_W-1:0] dest_fifo [0:DEPTH-1];
    reg [PTR_W-1:0] rd_ptr, wr_ptr;
    reg [COUNT_W-1:0] count;
    reg [DEPTH-1:0] armed_map;
    reg [DEPTH-1:0] started_map;

    // START observes the first routed W beat; FINISH awaits retirement.
    reg [1:0] phase;
    reg first_last;
    reg window;
    reg [DATA_WIDTH-1:0] routed_data;
    reg [DEST_W-1:0] routed_dest;
    reg routed_beat;

    wire accept_aw = i_aw_issue && (count < CAPACITY);
    wire retire_head = (phase == PH_FINISH);

    wire [COUNT_W:0] head_plus_count = {1'b0, count} + rd_ptr;
    wire [PTR_W-1:0] expected_wr_ptr =
        (head_plus_count >= EXT_CAPACITY)
        ? (head_plus_count - EXT_CAPACITY) : head_plus_count;

    // Combinational circular interval occupied by the queue.
    wire [DEPTH-1:0] resident_mask;
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : slots
            initial dest_fifo[g] = {DEST_W{1'b0}};
            assign resident_mask[g] = (g >= rd_ptr)
                ? ((g - rd_ptr) < count)
                : ((g + DEPTH - rd_ptr) < count);
        end
    endgenerate

    initial begin
        rd_ptr = {PTR_W{1'b0}};
        wr_ptr = {PTR_W{1'b0}};
        count = {COUNT_W{1'b0}};
        armed_map = {DEPTH{1'b0}};
        started_map = {DEPTH{1'b0}};
        phase = PH_WAIT;
        first_last = 1'b0;
        window = 1'b0;
        routed_data = {DATA_WIDTH{1'b0}};
        routed_dest = {DEST_W{1'b0}};
        routed_beat = 1'b0;
    end

    // Command/strobe interface: no ready/acknowledge handshake.
    // AW is accepted when space exists. W commands are consumed in WAIT
    // or STREAM; START and FINISH are internal sequencing cycles.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_scope_end)
                window <= 1'b0;
            else if (i_scope_begin)
                window <= 1'b1;

            routed_beat <= 1'b0;

            case ({accept_aw, retire_head})
                2'b10: count <= count + {{(COUNT_W-1){1'b0}}, 1'b1};
                2'b01: count <= count - {{(COUNT_W-1){1'b0}}, 1'b1};
                default: count <= count;
            endcase

            if (accept_aw) begin
                dest_fifo[wr_ptr] <= i_aw_dest;
                armed_map[wr_ptr] <= 1'b1;
                started_map[wr_ptr] <= 1'b0;
                if (wr_ptr == LAST_SLOT)
                    wr_ptr <= {PTR_W{1'b0}};
                else
                    wr_ptr <= wr_ptr + {{(PTR_W-1){1'b0}}, 1'b1};
            end

            case (phase)
                PH_WAIT: begin
                    if (i_w_issue && (count != {COUNT_W{1'b0}})) begin
                        routed_data <= i_wdata;
                        routed_dest <= dest_fifo[rd_ptr];
                        routed_beat <= 1'b1;
                        first_last <= i_wlast;
                        phase <= PH_START;
                    end
                end
                PH_START: begin
                    // Record that this queue entry has passed START.
                    started_map[rd_ptr] <= 1'b1;
                    if (first_last)
                        phase <= PH_FINISH;
                    else
                        phase <= PH_STREAM;
                end
                PH_STREAM: begin
                    if (i_w_issue) begin
                        routed_data <= i_wdata;
                        routed_dest <= dest_fifo[rd_ptr];
                        routed_beat <= 1'b1;
                        if (i_wlast)
                            phase <= PH_FINISH;
                    end
                end
                PH_FINISH: begin
                    armed_map[rd_ptr] <= 1'b0;
                    started_map[rd_ptr] <= 1'b0;
                    if (rd_ptr == LAST_SLOT)
                        rd_ptr <= {PTR_W{1'b0}};
                    else
                        rd_ptr <= rd_ptr + {{(PTR_W-1){1'b0}}, 1'b1};
                    phase <= PH_WAIT;
                end
            endcase
        end
    end

    assign o_wdest = routed_dest;
    assign o_wdata = routed_data;
    assign o_wbeat = routed_beat;

    // Within the latched window: START requires an earlier AW arm,
    // and FINISH requires both that arm and an earlier START.
    assert property (!window ||
        (((phase != PH_START) || armed_map[rd_ptr]) &&
         ((phase != PH_FINISH) ||
          (armed_map[rd_ptr] && started_map[rd_ptr]))));
endmodule

module serial_alpha_blender #(
    parameter integer PIXEL_BITS = 8,
    parameter integer ALPHA_BITS = 8,
    parameter integer COUNT_BITS = 8
) (
    input  wire                    clk,
    input  wire                    i_ce,
    input  wire                    i_begin,
    input  wire                    i_end,
    input  wire [PIXEL_BITS-1:0]   i_foreground,
    input  wire [PIXEL_BITS-1:0]   i_background,
    input  wire [ALPHA_BITS-1:0]   i_alpha,
    output reg  [PIXEL_BITS-1:0]   o_pixel,
    output wire [COUNT_BITS-1:0]   o_foreground_terms
);
    localparam [ALPHA_BITS-1:0] MASK_ZERO = {ALPHA_BITS{1'b0}};
    localparam [ALPHA_BITS-1:0] MASK_ALL = {ALPHA_BITS{1'b1}};
    localparam [ALPHA_BITS-1:0] MASK_ONE = {{(ALPHA_BITS-1){1'b0}}, 1'b1};
    localparam [COUNT_BITS-1:0] COUNT_ZERO = {COUNT_BITS{1'b0}};
    localparam [COUNT_BITS-1:0] COUNT_ONE = {{(COUNT_BITS-1){1'b0}}, 1'b1};
    localparam [COUNT_BITS-1:0] MAX_TERMS = ALPHA_BITS;

    reg window_active;
    reg [PIXEL_BITS-1:0] foreground_q, background_q, accumulator;
    reg [ALPHA_BITS-1:0] alpha_q, remaining_mask, seen_mask;
    reg [COUNT_BITS-1:0] term_count;

    // Visit alpha bits from least significant to most significant.
    wire [ALPHA_BITS-1:0] bit_mask =
        remaining_mask & (~remaining_mask + MASK_ONE);
    wire [ALPHA_BITS-1:0] selected_mask = alpha_q & bit_mask;
    wire use_foreground = (selected_mask != MASK_ZERO);
    wire [ALPHA_BITS-1:0] next_remaining =
        remaining_mask & (remaining_mask - MASK_ONE);
    wire [PIXEL_BITS-1:0] selected_pixel =
        use_foreground ? foreground_q : background_q;
    wire [PIXEL_BITS:0] mix_sum =
        {1'b0, accumulator} + {1'b0, selected_pixel};
    wire [PIXEL_BITS-1:0] half_mix = mix_sum[PIXEL_BITS:1];

    // Combinational population count of the foreground terms already used.
    wire [COUNT_BITS-1:0] pop_sum [0:ALPHA_BITS];
    wire [COUNT_BITS-1:0] seen_count;
    assign pop_sum[0] = COUNT_ZERO;
    genvar g;
    generate
        for (g = 0; g < ALPHA_BITS; g = g + 1) begin : count_seen
            assign pop_sum[g+1] = pop_sum[g] +
                {{(COUNT_BITS-1){1'b0}}, seen_mask[g]};
        end
    endgenerate
    assign seen_count = pop_sum[ALPHA_BITS];
    assign o_foreground_terms = term_count;

    initial begin
        window_active = 1'b0;
        foreground_q = {PIXEL_BITS{1'b0}};
        background_q = {PIXEL_BITS{1'b0}};
        accumulator = {PIXEL_BITS{1'b0}};
        alpha_q = MASK_ZERO;
        remaining_mask = MASK_ZERO;
        seen_mask = MASK_ZERO;
        term_count = COUNT_ZERO;
        o_pixel = {PIXEL_BITS{1'b0}};
    end

    // Each enabled microstep halves the accumulator plus one selected pixel.
    // Starting at background makes the final result exactly
    // floor((alpha*foreground + (2**ALPHA_BITS-alpha)*background)
    //       / 2**ALPHA_BITS).
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_end) begin
                window_active <= 1'b0;
            end else if (i_begin) begin
                window_active <= 1'b1;
                foreground_q <= i_foreground;
                background_q <= i_background;
                alpha_q <= i_alpha;
                accumulator <= i_background;
                remaining_mask <= MASK_ALL;
                seen_mask <= MASK_ZERO;
                term_count <= COUNT_ZERO;
            end else if (window_active && remaining_mask != MASK_ZERO) begin
                accumulator <= half_mix;
                remaining_mask <= next_remaining;
                seen_mask <= seen_mask | selected_mask;
                if (use_foreground)
                    term_count <= term_count + COUNT_ONE;
                if (next_remaining == MASK_ZERO)
                    o_pixel <= half_mix;
            end
        end
    end

    // Between begin and end, at most ALPHA_BITS foreground terms may occur.
    assert property (!window_active || (term_count <= MAX_TERMS));
endmodule

module windowed_trap_regfile #(
    parameter integer DATA_W  = 32,
    parameter integer ENTRIES = 256,
    parameter integer WINDOWS = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_req_valid,
    output wire                  o_req_ready,
    input  wire [2:0]            i_cmd,
    input  wire [1:0]            i_bank,
    input  wire [31:0]           i_reg_num,
    input  wire [DATA_W-1:0]     i_req_data,
    output reg  [DATA_W-1:0]     o_read_data,
    output wire                 o_trap_pending,
    output wire                 o_trap_is_fill,
    output wire [DATA_W-1:0]     o_trap_entry
);
    // Legal geometry: WINDOWS >= 2 and ENTRIES is a multiple of 2*WINDOWS.
    // Each physical window contains locals followed by outs. Its ins alias
    // the preceding window's outs, including across the circular boundary.
    localparam [31:0] ENTRY_COUNT  = ENTRIES;
    localparam [31:0] WINDOW_COUNT = WINDOWS;
    localparam [31:0] WINDOW_WORDS = ENTRIES / WINDOWS;
    localparam [31:0] BANK_WORDS   = WINDOW_WORDS / 32'd2;
    localparam [31:0] LAST_WINDOW  = WINDOW_COUNT - 32'd1;
    localparam [31:0] LAST_WORD    = WINDOW_WORDS - 32'd1;

    localparam [2:0] CMD_READ    = 3'd0;
    localparam [2:0] CMD_WRITE   = 3'd1;
    localparam [2:0] CMD_SAVE    = 3'd2;
    localparam [2:0] CMD_RESTORE = 3'd3;
    localparam [2:0] CMD_VECTOR  = 3'd4;
    localparam [2:0] CMD_ERET    = 3'd5;

    reg [DATA_W-1:0] physical [0:ENTRIES-1];
    reg [DATA_W-1:0] backing  [0:ENTRIES-1];
    reg [31:0] cwp;
    reg [WINDOWS-1:0] window_invalid;

    reg trap_busy;
    reg trap_fill;
    reg [31:0] trap_window;
    reg [31:0] scan_word;
    reg [31:0] transfer_addr;
    reg [31:0] cycles_left;
    reg deadline_expired;
    reg [DATA_W-1:0] trap_vector;
    reg before_first_eret;
    reg past_valid;

    wire [31:0] next_cwp = (cwp == LAST_WINDOW)
                           ? 32'd0 : cwp + 32'd1;
    wire [31:0] prev_cwp = (cwp == 32'd0)
                           ? LAST_WINDOW : cwp - 32'd1;
    wire [31:0] lane = i_reg_num % BANK_WORDS;
    wire [31:0] visible_addr =
        (i_bank == 2'd0) ? prev_cwp * WINDOW_WORDS + BANK_WORDS + lane :
        (i_bank == 2'd1) ? cwp * WINDOW_WORDS + lane :
                           cwp * WINDOW_WORDS + BANK_WORDS + lane;
    wire [31:0] next_sentinel = trap_fill
        ? ((trap_window == 32'd0) ? LAST_WINDOW : trap_window - 32'd1)
        : ((trap_window == LAST_WINDOW) ? 32'd0 : trap_window + 32'd1);

    // Receiver back-pressure: no command is accepted during trap service.
    assign o_req_ready = i_ce && !trap_busy;
    assign o_trap_pending = trap_busy;
    assign o_trap_is_fill = trap_fill;
    assign o_trap_entry = trap_vector;

    integer j;
    initial begin
        cwp = 32'd0;
        window_invalid = {1'b1, {(WINDOWS-1){1'b0}}};
        trap_busy = 1'b0;
        trap_fill = 1'b0;
        trap_window = 32'd0;
        scan_word = 32'd0;
        transfer_addr = 32'd0;
        cycles_left = 32'd0;
        deadline_expired = 1'b1;
        trap_vector = {DATA_W{1'b0}};
        o_read_data = {DATA_W{1'b0}};
        before_first_eret = 1'b1;
        past_valid = 1'b0;
        for (j = 32'd0; j < ENTRIES; j = j + 32'd1) begin
            physical[j] = {DATA_W{1'b0}};
            backing[j] = {DATA_W{1'b0}};
        end
    end

    // i_ce freezes every state register, including an outstanding operation.
    // The deadline therefore counts enabled service cycles.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            if (trap_busy) begin
                if (trap_fill)
                    physical[transfer_addr] <= backing[transfer_addr];
                else
                    backing[transfer_addr] <= physical[transfer_addr];

                if (scan_word == LAST_WORD) begin
                    trap_busy <= 1'b0;
                    cycles_left <= 32'd0;
                    deadline_expired <= 1'b1;
                    cwp <= trap_window;
                    window_invalid[trap_window] <= 1'b0;
                    window_invalid[next_sentinel] <= 1'b1;
                end else begin
                    scan_word <= scan_word + 32'd1;
                    transfer_addr <= transfer_addr + 32'd1;
                    cycles_left <= cycles_left - 32'd1;
                    deadline_expired <= (cycles_left == 32'd1);
                end
            end else if (i_req_valid && o_req_ready) begin
                case (i_cmd)
                    CMD_READ: o_read_data <= physical[visible_addr];
                    CMD_WRITE: physical[visible_addr] <= i_req_data;
                    CMD_SAVE: begin
                        if (window_invalid[next_cwp]) begin
                            trap_busy <= 1'b1;
                            trap_fill <= 1'b0;
                            trap_window <= next_cwp;
                            scan_word <= 32'd0;
                            transfer_addr <= next_cwp * WINDOW_WORDS;
                            cycles_left <= WINDOW_WORDS;
                            deadline_expired <= 1'b0;
                        end else begin
                            cwp <= next_cwp;
                        end
                    end
                    CMD_RESTORE: begin
                        if (window_invalid[prev_cwp]) begin
                            trap_busy <= 1'b1;
                            trap_fill <= 1'b1;
                            trap_window <= prev_cwp;
                            scan_word <= 32'd0;
                            transfer_addr <= prev_cwp * WINDOW_WORDS;
                            cycles_left <= WINDOW_WORDS;
                            deadline_expired <= 1'b0;
                        end else begin
                            cwp <= prev_cwp;
                        end
                    end
                    CMD_VECTOR: trap_vector <= i_req_data;
                    CMD_ERET: before_first_eret <= 1'b0;
                    default: begin end
                endcase
            end
        end
    end

    // Before the first accepted ERET, a continuously outstanding request
    // must not change its expiration flag. Acceptance initializes that flag
    // low; it may rise only when the bounded spill/fill operation completes.
    always @(posedge clk) begin
        if (past_valid && before_first_eret && trap_busy)
            assert (!$stable(trap_busy) || $stable(deadline_expired));
    end
endmodule

module trace_scale_queue #(
    parameter integer WORD_W = 16,
    parameter integer DEPTH = 24
) (
    input  wire                  i_clk,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [WORD_W-1:0]     i_value,
    input  wire [WORD_W-1:0]     i_scale,
    output wire                  o_valid,
    input  wire                  o_ready,
    output wire [WORD_W-1:0]     o_word,
    output wire                  o_zero,
    output wire                  o_odd,
    output reg  [WORD_W-1:0]     retired_word,
    output reg                   retired_zero,
    output reg                   retired_odd
);
    localparam [WORD_W-1:0] WORD_ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] WORD_ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] DEPTH_COUNT = DEPTH;
    localparam [WORD_W-1:0] LAST_SLOT = DEPTH - 1;

    // Parallel partial-product rows and a regular row-adder array.
    // Trace scaling is modulo 2**WORD_W; upper product bits are discarded.
    wire [WORD_W-1:0] partial_product [0:WORD_W-1];
    wire [WORD_W-1:0] row_sum [0:WORD_W];
    assign row_sum[0] = WORD_ZERO;
    genvar row;
    generate
        for (row = 0; row < WORD_W; row = row + 1) begin : multiplier_rows
            assign partial_product[row] =
                (i_value & {WORD_W{i_scale[row]}}) << row;
            assign row_sum[row+1] = row_sum[row] + partial_product[row];
        end
    endgenerate

    reg [WORD_W-1:0] word_mem [0:DEPTH-1];
    reg [DEPTH-1:0] zero_tags;
    reg [DEPTH-1:0] odd_tags;
    reg [WORD_W-1:0] rd_ptr;
    reg [WORD_W-1:0] wr_ptr;
    reg [WORD_W-1:0] fill_count;
    reg armed;
    wire [DEPTH-1:0] slot_used;

    assign i_ready = fill_count < DEPTH_COUNT;
    assign o_valid = fill_count != WORD_ZERO;
    wire push = i_valid && i_ready;
    wire pop = o_valid && o_ready;

    assign o_word = word_mem[rd_ptr];
    assign o_zero = zero_tags[rd_ptr];
    assign o_odd = odd_tags[rd_ptr];

    genvar slot;
    generate
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin : queue_slots
            localparam [WORD_W-1:0] SLOT_INDEX = slot;
            initial word_mem[slot] = WORD_ZERO;
            assign slot_used[slot] = (fill_count != WORD_ZERO) &&
                ((rd_ptr < wr_ptr) ?
                    ((rd_ptr <= SLOT_INDEX) && (SLOT_INDEX < wr_ptr)) :
                    ((rd_ptr <= SLOT_INDEX) || (SLOT_INDEX < wr_ptr)));
        end
    endgenerate

    initial begin
        zero_tags = {DEPTH{1'b0}};
        odd_tags = {DEPTH{1'b0}};
        rd_ptr = WORD_ZERO;
        wr_ptr = WORD_ZERO;
        fill_count = WORD_ZERO;
        armed = 1'b0;
        retired_word = WORD_ZERO;
        retired_zero = 1'b1;
        retired_odd = 1'b0;
    end

    // Both handshakes idle when i_valid=0 and o_ready=0.
    // A stalled output cannot be overwritten, even when the queue is full.
    always @(posedge i_clk) begin
        if (push) begin
            word_mem[wr_ptr] <= row_sum[WORD_W];
            zero_tags[wr_ptr] <= (i_value == WORD_ZERO) ||
                                 (i_scale == WORD_ZERO);
            odd_tags[wr_ptr] <= i_value[0] & i_scale[0];
            if (wr_ptr == LAST_SLOT)
                wr_ptr <= WORD_ZERO;
            else
                wr_ptr <= wr_ptr + WORD_ONE;
        end

        if (pop) begin
            retired_word <= word_mem[rd_ptr];
            retired_zero <= zero_tags[rd_ptr];
            retired_odd <= odd_tags[rd_ptr];
            armed <= 1'b1;
            if (rd_ptr == LAST_SLOT)
                rd_ptr <= WORD_ZERO;
            else
                rd_ptr <= rd_ptr + WORD_ONE;
        end

        case ({push, pop})
            2'b10: fill_count <= fill_count + WORD_ONE;
            2'b01: fill_count <= fill_count - WORD_ONE;
            default: begin end
        endcase
    end

    // After the first emitted trace word, both relations hold universally.
    always @(posedge i_clk) begin
        if (armed) begin
            assert (!retired_zero || (retired_word == WORD_ZERO));
            assert (retired_word[0] == retired_odd);
        end
    end
endmodule

module priority_interrupt_dispatch #(
    parameter integer IRQ_COUNT = 128,
    parameter integer SERVICE_STAGES = 4
) (
    input  wire                   clk,
    input  wire                   i_ce,
    input  wire                   i_reset,
    input  wire [IRQ_COUNT-1:0]   i_irq_lines,
    input  wire                   i_enable_write,
    input  wire [IRQ_COUNT-1:0]   i_enable_word,
    input  wire                   i_scope_open,
    input  wire                   i_scope_close,
    output reg  [IRQ_COUNT-1:0]   o_vector_word,
    output reg                    o_vector_valid
);
    // SERVICE_STAGES must be at least two. Deadlines count enabled edges.
    localparam integer TIMER_W = $clog2(SERVICE_STAGES + 1);
    localparam [IRQ_COUNT-1:0] IRQ_ZERO = {IRQ_COUNT{1'b0}};
    localparam [IRQ_COUNT-1:0] IRQ_ONE = {{(IRQ_COUNT-1){1'b0}}, 1'b1};
    localparam [IRQ_COUNT-1:0] IRQ_ALL = {IRQ_COUNT{1'b1}};
    localparam [SERVICE_STAGES-1:0] PIPE_ZERO = {SERVICE_STAGES{1'b0}};
    localparam [SERVICE_STAGES-1:0] PIPE_ONE = {{(SERVICE_STAGES-1){1'b0}}, 1'b1};
    localparam [TIMER_W-1:0] TIMER_ZERO = {TIMER_W{1'b0}};
    localparam [TIMER_W-1:0] TIMER_ONE = {{(TIMER_W-1){1'b0}}, 1'b1};
    localparam [TIMER_W-1:0] RETIRE_LIMIT = SERVICE_STAGES;

    reg [IRQ_COUNT-1:0] pending;
    reg [IRQ_COUNT-1:0] irq_enable;
    reg [IRQ_COUNT-1:0] in_service;
    reg [SERVICE_STAGES-1:0] pipeline;
    reg vector_wait;
    reg [1:0] dispatch_budget;
    reg [TIMER_W-1:0] retire_budget;
    reg window;

    wire [IRQ_COUNT-1:0] eligible = pending & irq_enable;
    // Isolate the lowest-numbered eligible interrupt.
    wire [IRQ_COUNT-1:0] priority_mask = eligible & (~eligible + IRQ_ONE);
    wire accept_irq = (in_service == IRQ_ZERO) && (priority_mask != IRQ_ZERO);

    initial begin
        pending = IRQ_ZERO;
        irq_enable = IRQ_ALL;
        in_service = IRQ_ZERO;
        pipeline = PIPE_ZERO;
        vector_wait = 1'b0;
        dispatch_budget = 2'd0;
        retire_budget = TIMER_ZERO;
        window = 1'b0;
        o_vector_word = IRQ_ZERO;
        o_vector_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_reset) begin
                pending <= IRQ_ZERO;
                irq_enable <= IRQ_ALL;
                in_service <= IRQ_ZERO;
                pipeline <= PIPE_ZERO;
                vector_wait <= 1'b0;
                dispatch_budget <= 2'd0;
                retire_budget <= TIMER_ZERO;
                window <= 1'b0;
                o_vector_word <= IRQ_ZERO;
                o_vector_valid <= 1'b0;
            end else begin
                if (i_scope_close)
                    window <= 1'b0;
                else if (i_scope_open)
                    window <= 1'b1;

                if (i_enable_write)
                    irq_enable <= i_enable_word;

                pending <= (pending | i_irq_lines)
                         & ~(accept_irq ? priority_mask : IRQ_ZERO);
                pipeline <= {pipeline[SERVICE_STAGES-2:0], accept_irq};
                o_vector_valid <= 1'b0;

                if (accept_irq) begin
                    in_service <= priority_mask;
                    vector_wait <= 1'b1;
                    dispatch_budget <= 2'd2;
                    retire_budget <= RETIRE_LIMIT;
                end else begin
                    if (vector_wait && (dispatch_budget != 2'd0))
                        dispatch_budget <= dispatch_budget - 2'd1;
                    if ((in_service != IRQ_ZERO) && (retire_budget != TIMER_ZERO))
                        retire_budget <= retire_budget - TIMER_ONE;

                    // Present the selected one-hot vector after two enabled edges.
                    if (pipeline[1]) begin
                        o_vector_word <= in_service;
                        o_vector_valid <= 1'b1;
                        vector_wait <= 1'b0;
                    end

                    // The fixed-latency dispatch backend then retires service.
                    if (pipeline[SERVICE_STAGES-1])
                        in_service <= IRQ_ZERO;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (window) begin
            assert (!vector_wait || (dispatch_budget != 2'd0));
            assert ((in_service == IRQ_ZERO) || (retire_budget != TIMER_ZERO));
        end
    end
endmodule

module onewire_word_master #(
    parameter [31:0] WORD_BITS = 32'd32,
    parameter [31:0] SLOT_TICKS = 32'd8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_ce,
    input  wire arm_request,
    input  wire start_request,
    input  wire read_request,
    input  wire [WORD_BITS-32'd1:0] tx_word,
    input  wire ow_in,
    output wire ow_drive_low,
    output reg  presence_detected,
    output reg  transfer_started,
    output wire transfer_done,
    output wire [WORD_BITS-32'd1:0] received_word
);
    localparam [31:0] RESET_TICKS = SLOT_TICKS * 32'd8;
    localparam [31:0] SAMPLE_TICK = SLOT_TICKS >> 32'd1;
    localparam [31:0] WRITE_ZERO_LOW = SLOT_TICKS - 32'd2;

    localparam [31:0] ST_IDLE     = 32'd0;
    localparam [31:0] ST_RESET    = 32'd1;
    localparam [31:0] ST_PRESENCE = 32'd2;
    localparam [31:0] ST_ARMED    = 32'd3;
    localparam [31:0] ST_WRITE    = 32'd4;
    localparam [31:0] ST_READ     = 32'd5;
    localparam [31:0] ST_FINISH   = 32'd6;

    reg [31:0] phase;
    reg [31:0] slot_timer;
    reg [31:0] bit_count;
    // A host word is serialized LSB first. Its low octet is the
    // current byte, with subsequent bytes queued above it.
    reg [WORD_BITS-32'd1:0] byte_shift;
    reg read_sample;

    initial begin
        phase = ST_IDLE;
        slot_timer = 32'd0;
        bit_count = 32'd0;
        byte_shift = 32'd0;
        read_sample = 1'b0;
        presence_detected = 1'b0;
        transfer_started = 1'b0;
    end

    // Split open-drain pad interface: drive_low requests a zero;
    // otherwise the external pad releases the same line sensed by ow_in.
    assign ow_drive_low =
        (phase == ST_RESET) ||
        ((phase == ST_WRITE) &&
         ((slot_timer == 32'd0) ||
          (!byte_shift[0] && (slot_timer < WRITE_ZERO_LOW)))) ||
        ((phase == ST_READ) && (slot_timer == 32'd0));

    assign transfer_done = (phase == ST_FINISH);
    assign received_word = byte_shift;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase <= ST_IDLE;
            slot_timer <= 32'd0;
            bit_count <= 32'd0;
            byte_shift <= 32'd0;
            read_sample <= 1'b0;
            presence_detected <= 1'b0;
            transfer_started <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                ST_IDLE, ST_FINISH: begin
                    if (arm_request) begin
                        phase <= ST_RESET;
                        slot_timer <= 32'd0;
                        bit_count <= 32'd0;
                        byte_shift <= 32'd0;
                        read_sample <= 1'b0;
                        presence_detected <= 1'b0;
                        transfer_started <= 1'b0;
                    end
                end

                ST_RESET: begin
                    if (slot_timer == RESET_TICKS - 32'd1) begin
                        phase <= ST_PRESENCE;
                        slot_timer <= 32'd0;
                    end else begin
                        slot_timer <= slot_timer + 32'd1;
                    end
                end

                ST_PRESENCE: begin
                    // Sample presence after releasing the reset pulse,
                    // then allow the rest of the recovery interval.
                    if (slot_timer == SLOT_TICKS - 32'd1)
                        presence_detected <= !ow_in;
                    if (slot_timer == RESET_TICKS - 32'd1) begin
                        slot_timer <= 32'd0;
                        if (presence_detected)
                            phase <= ST_ARMED;
                        else
                            phase <= ST_IDLE;
                    end else begin
                        slot_timer <= slot_timer + 32'd1;
                    end
                end

                ST_ARMED: begin
                    if (start_request) begin
                        phase <= read_request ? ST_READ : ST_WRITE;
                        transfer_started <= 1'b1;
                        slot_timer <= 32'd0;
                        bit_count <= 32'd0;
                        byte_shift <= read_request ? 32'd0 : tx_word;
                        read_sample <= 1'b0;
                    end
                end

                ST_WRITE: begin
                    if (slot_timer == SLOT_TICKS - 32'd1) begin
                        slot_timer <= 32'd0;
                        byte_shift <= byte_shift >> 32'd1;
                        if (bit_count == WORD_BITS - 32'd1)
                            phase <= ST_FINISH;
                        else
                            bit_count <= bit_count + 32'd1;
                    end else begin
                        slot_timer <= slot_timer + 32'd1;
                    end
                end

                ST_READ: begin
                    if (slot_timer == SAMPLE_TICK)
                        read_sample <= ow_in;
                    if (slot_timer == SLOT_TICKS - 32'd1) begin
                        slot_timer <= 32'd0;
                        byte_shift <= {read_sample,
                                       byte_shift[WORD_BITS-32'd1:32'd1]};
                        if (bit_count == WORD_BITS - 32'd1)
                            phase <= ST_FINISH;
                        else
                            bit_count <= bit_count + 32'd1;
                    end else begin
                        slot_timer <= slot_timer + 32'd1;
                    end
                end

                default: begin
                    phase <= ST_IDLE;
                    slot_timer <= 32'd0;
                    bit_count <= 32'd0;
                    byte_shift <= 32'd0;
                    read_sample <= 1'b0;
                    presence_detected <= 1'b0;
                    transfer_started <= 1'b0;
                end
            endcase
        end
    end

    // Global chain precedence: successful arming precedes start,
    // and start precedes finish. These are transaction status flags,
    // not a separate property-scope latch.
    always @(*) begin
        if (transfer_started || transfer_done)
            assert (presence_detected &&
                    (!transfer_done || transfer_started));
    end
endmodule

module axi_apb_write_bridge64 #(
    parameter integer ADDR_WIDTH = 64,
    parameter integer DATA_WIDTH = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_axi_awvalid,
    input  wire [ADDR_WIDTH-1:0] i_axi_awaddr,
    output wire                  o_axi_awready,
    input  wire                  i_axi_wvalid,
    input  wire [DATA_WIDTH-1:0] i_axi_wdata,
    output wire                  o_axi_wready,
    output reg                   o_axi_capture,
    output wire                  o_axi_bvalid,
    input  wire                  i_axi_bready,
    output wire [1:0]            o_axi_bresp,
    output reg  [ADDR_WIDTH-1:0] o_apb_paddr,
    output reg  [DATA_WIDTH-1:0] o_apb_pwdata,
    output reg                   o_apb_psel,
    output reg                   o_apb_penable,
    output wire                  o_apb_pwrite,
    input  wire                  i_apb_pready
);
    typedef enum logic [1:0] {
        IDLE     = 2'b00,
        SETUP    = 2'b01,
        ACCESS   = 2'b10,
        RESPONSE = 2'b11
    } state_t;

    state_t phase;
    reg pv;

    initial begin
        phase = IDLE;
        pv = 1'b0;
        o_axi_capture = 1'b0;
        o_apb_paddr = {ADDR_WIDTH{1'b0}};
        o_apb_pwdata = {DATA_WIDTH{1'b0}};
        o_apb_psel = 1'b0;
        o_apb_penable = 1'b0;
    end

    // Coupled AW/W acceptance: capture one complete write descriptor.
    assign o_axi_awready = i_ce && (phase == IDLE) && i_axi_wvalid;
    assign o_axi_wready  = i_ce && (phase == IDLE) && i_axi_awvalid;
    assign o_axi_bvalid  = i_ce && (phase == RESPONSE);
    assign o_axi_bresp   = 2'b00;
    assign o_apb_pwrite  = 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            o_axi_capture <= 1'b0;
            case (phase)
                IDLE: begin
                    o_apb_psel <= 1'b0;
                    o_apb_penable <= 1'b0;
                    if (i_axi_awvalid && i_axi_wvalid) begin
                        o_apb_paddr <= i_axi_awaddr;
                        o_apb_pwdata <= i_axi_wdata;
                        o_axi_capture <= 1'b1;
                        o_apb_psel <= 1'b1;
                        phase <= SETUP;
                    end
                end
                SETUP: begin
                    o_apb_psel <= 1'b1;
                    o_apb_penable <= 1'b1;
                    phase <= ACCESS;
                end
                ACCESS: begin
                    o_apb_psel <= 1'b1;
                    o_apb_penable <= 1'b1;
                    if (i_apb_pready) begin
                        o_apb_psel <= 1'b0;
                        o_apb_penable <= 1'b0;
                        phase <= RESPONSE;
                    end
                end
                RESPONSE: begin
                    o_apb_psel <= 1'b0;
                    o_apb_penable <= 1'b0;
                    if (i_axi_bready)
                        phase <= IDLE;
                end
                default: begin
                    phase <= IDLE;
                    o_apb_psel <= 1'b0;
                    o_apb_penable <= 1'b0;
                end
            endcase
        end
    end

    // The registered capture acknowledgement and the preceding cycle's
    // APB access ownership must never overlap. Capture is retained on stalls.
    always @(posedge clk)
        if (pv)
            assert (!(o_axi_capture && $past(o_apb_penable)));
endmodule

module telemetry_ring #(
    parameter integer TOKEN_BITS = 32,
    parameter integer WORD_BITS = 32
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire                 step_enable,
    input  wire                 tick_valid,
    output wire                 tick_ready,
    input  wire [WORD_BITS-1:0]  tick_command,
    output wire [WORD_BITS-1:0]  elapsed_ticks,
    output wire                 beacon_grant,
    output wire                 rollover_grant
);
    localparam [TOKEN_BITS-1:0] TOKEN_ONE =
        {{(TOKEN_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] COUNT_ONE =
        {{(WORD_BITS-1){1'b0}}, 1'b1};

    reg [TOKEN_BITS-1:0] token;
    reg [WORD_BITS-1:0] tick_count;
    reg window_active;

    initial begin
        token = TOKEN_ONE;
        tick_count = {WORD_BITS{1'b0}};
        window_active = 1'b0;
    end

    // The receiver accepts one tick per enabled handshake.
    assign tick_ready = step_enable;
    assign elapsed_ticks = tick_count;
    assign beacon_grant = token[0];
    assign rollover_grant = token[TOKEN_BITS-1];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            token <= TOKEN_ONE;
            tick_count <= {WORD_BITS{1'b0}};
            window_active <= 1'b0;
        end else if (tick_valid && tick_ready) begin
            token <= {token[TOKEN_BITS-2:0], token[TOKEN_BITS-1]};
            tick_count <= tick_count + COUNT_ONE;

            // Accepted bit 0 opens the monitoring window (Q).
            // Accepted bit 1 closes it (R), with closing priority.
            if (tick_command[1])
                window_active <= 1'b0;
            else if (tick_command[0])
                window_active <= 1'b1;
        end
    end

    // During the latched window, the two transmit slots never coincide.
    always @(posedge clk)
        assert (!window_active ||
                !(token[0] && token[TOKEN_BITS-1]));
endmodule

module fft_lane_route_latch #(
    parameter integer WORD_W = 16,
    parameter integer MASK_ENTRIES = 2
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire [WORD_W-1:0]     i_scale_mask,
    output reg  [WORD_W-1:0]     scale_grant,
    output reg  [WORD_W-1:0]     bypass_grant
);
    typedef enum logic [1:0] {
        IDLE  = 2'b00,
        TRACK = 2'b01,
        ISSUE = 2'b10
    } state_t;

    state_t state;
    reg armed;
    reg [WORD_W-1:0] route_hold [0:MASK_ENTRIES-1];

    initial begin
        state = IDLE;
        armed = 1'b0;
        scale_grant = {WORD_W{1'b0}};
        bypass_grant = {WORD_W{1'b0}};
    end

    // Complementary routing rails are stored in active-high D latches.
    // Even entries select scaled lanes; odd entries select bypass lanes.
    generate
        for (genvar g = 0; g < MASK_ENTRIES; g = g + 1) begin : route_latches
            if ((g % 2) == 0) begin : scaled
                initial route_hold[g] = {WORD_W{1'b0}};
                always @(*) begin
                    if (i_ce && (state == TRACK))
                        route_hold[g] = i_scale_mask;
                end
            end else begin : bypassed
                initial route_hold[g] = {WORD_W{1'b1}};
                always @(*) begin
                    if (i_ce && (state == TRACK))
                        route_hold[g] = ~i_scale_mask;
                end
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                IDLE: state <= TRACK;
                TRACK: state <= ISSUE;
                ISSUE: begin
                    scale_grant <= route_hold[0];
                    bypass_grant <= route_hold[1];
                    armed <= 1'b1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    // After the first routing issue, no lane may receive both grants.
    always @(posedge clk)
        if (armed)
            assert ((scale_grant & bypass_grant) == {WORD_W{1'b0}});
endmodule

module serial_cell_divider #(
    parameter integer WORD_BITS = 32'd16
) (
    input  wire                 clk,
    input  wire                 i_valid,
    output wire                 i_ready,
    input  wire                 i_dividend_bit,
    input  wire [WORD_BITS-1:0] i_divisor,
    output wire                 o_valid,
    input  wire                 o_ready,
    output wire [WORD_BITS-1:0] o_quotient,
    output wire [WORD_BITS-1:0] o_remainder
);
    localparam [WORD_BITS-1:0] ZERO_WORD = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] ONE_WORD = {{(WORD_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] FIRST_BIT = {1'b1, {(WORD_BITS-1){1'b0}}};
    localparam [WORD_BITS-1:0] STEP_LIMIT = WORD_BITS;

    reg [WORD_BITS-1:0] remainder_word;
    reg                 remainder_negative;
    reg [WORD_BITS-1:0] quotient;
    reg [WORD_BITS-1:0] divisor;
    reg [WORD_BITS-1:0] step_count;
    reg [WORD_BITS-1:0] scan_mask;
    reg                 result_valid;

    initial begin
        remainder_word = ZERO_WORD;
        remainder_negative = 1'b0;
        quotient = ZERO_WORD;
        divisor = ONE_WORD;
        step_count = ZERO_WORD;
        scan_mask = FIRST_BIT;
        result_valid = 1'b0;
    end

    // Each accepted input supplies one numerator bit, most significant first.
    // The divisor is sampled on the first bit; zero is normalized to one.
    // A complete result occupies the output until its ready/valid transfer.
    assign i_ready = !result_valid || o_ready;
    assign o_valid = result_valid;
    assign o_quotient = quotient;
    assign o_remainder = remainder_negative
                       ? remainder_word + divisor : remainder_word;

    wire start_word = (step_count == ZERO_WORD) || (scan_mask == ZERO_WORD);
    wire [WORD_BITS-1:0] active_mask = start_word ? FIRST_BIT : scan_mask;
    wire [WORD_BITS-1:0] active_divisor = start_word
        ? ((i_divisor == ZERO_WORD) ? ONE_WORD : i_divisor)
        : divisor;
    wire active_negative = start_word ? 1'b0 : remainder_negative;

    // The remainder word and its separate sign flag form the signed
    // non-restoring partial remainder. Arithmetic is modulo its extended width.
    wire [WORD_BITS:0] shifted_remainder = start_word
        ? {{WORD_BITS{1'b0}}, i_dividend_bit}
        : {remainder_word, i_dividend_bit};
    wire [WORD_BITS:0] next_remainder = active_negative
        ? shifted_remainder + {1'b0, active_divisor}
        : shifted_remainder - {1'b0, active_divisor};
    wire [WORD_BITS-1:0] quotient_base = start_word ? ZERO_WORD : quotient;
    wire [WORD_BITS-1:0] next_quotient = quotient_base
        | (next_remainder[WORD_BITS] ? ZERO_WORD : active_mask);

    always @(posedge clk) begin
        if (result_valid && o_ready)
            result_valid <= 1'b0;

        if (i_valid && i_ready) begin
            divisor <= active_divisor;
            remainder_word <= next_remainder[WORD_BITS-1:0];
            remainder_negative <= next_remainder[WORD_BITS];
            quotient <= next_quotient;
            scan_mask <= active_mask >> 1'b1;
            step_count <= start_word ? ONE_WORD : step_count + ONE_WORD;

            if (active_mask == ONE_WORD)
                result_valid <= 1'b1;
        end
    end

    assert property (step_count <= STEP_LIMIT);
endmodule

module trellis_acs_accel #(
    parameter WORD_W = 128,
    parameter STATES = 8,
    parameter TRACE_DEPTH = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_valid,
    output wire i_ready,
    input  wire [STATES*WORD_W-1:0] i_branch_a,
    input  wire [STATES*WORD_W-1:0] i_branch_b,
    output wire o_valid,
    input  wire o_ready,
    output wire [WORD_W-1:0] o_terminal_metric,
    output wire [WORD_W-1:0] o_terminal_runner_up,
    output wire [STATES-1:0] o_survivors,
    input  wire [((TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1)-1:0] trace_read_addr,
    output wire [WORD_W-1:0] trace_read_word
);
    localparam TRACE_AW = (TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1;

    reg [WORD_W-1:0] path_metric [0:STATES-1];
    reg [WORD_W-1:0] runner_up   [0:STATES-1];
    reg [WORD_W-1:0] cand_a      [0:STATES-1];
    reg [WORD_W-1:0] cand_b      [0:STATES-1];
    reg [STATES-1:0] survivor;
    reg [WORD_W-1:0] traceback [0:TRACE_DEPTH-1];
    reg [TRACE_AW-1:0] trace_wr;
    reg pending;
    reg armed;

    function automatic [WORD_W-1:0] metric_add;
        input [WORD_W-1:0] a;
        input [WORD_W-1:0] b;
        reg [WORD_W:0] total;
        begin
            total = {1'b0, a} + {1'b0, b};
            metric_add = total[WORD_W] ? {WORD_W{1'b1}} : total[WORD_W-1:0];
        end
    endfunction

    wire [WORD_W-1:0] next_a [0:STATES-1];
    wire [WORD_W-1:0] next_b [0:STATES-1];

    genvar g;
    generate
        for (g = 0; g < STATES; g = g + 1) begin : trellis
            localparam PRED_A = (2*g) % STATES;
            localparam PRED_B = (2*g + 1) % STATES;
            assign next_a[g] = metric_add(
                path_metric[PRED_A], i_branch_a[g*WORD_W +: WORD_W]);
            assign next_b[g] = metric_add(
                path_metric[PRED_B], i_branch_b[g*WORD_W +: WORD_W]);
        end
    endgenerate

    assign i_ready = !pending;
    assign o_valid = pending;
    wire accept_branches = i_valid && i_ready;
    wire retire_survivors = o_valid && o_ready;

    assign o_terminal_metric = survivor[0] ? cand_b[0] : cand_a[0];
    assign o_terminal_runner_up = survivor[0] ? cand_a[0] : cand_b[0];
    assign o_survivors = survivor;
    assign trace_read_word = traceback[trace_read_addr];
    wire [WORD_W-1:0] survivor_word = {{(WORD_W-STATES){1'b0}}, survivor};

    initial begin
        pending = 1'b0;
        armed = 1'b0;
        survivor = {STATES{1'b0}};
        trace_wr = {TRACE_AW{1'b0}};
        for (integer s = 0; s < STATES; s = s + 1) begin
            path_metric[s] = {WORD_W{1'b0}};
            runner_up[s] = {WORD_W{1'b0}};
            cand_a[s] = {WORD_W{1'b0}};
            cand_b[s] = {WORD_W{1'b0}};
        end
        for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
            traceback[t] = {WORD_W{1'b0}};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending <= 1'b0;
            armed <= 1'b0;
            survivor <= {STATES{1'b0}};
            trace_wr <= {TRACE_AW{1'b0}};
            for (integer s = 0; s < STATES; s = s + 1) begin
                path_metric[s] <= {WORD_W{1'b0}};
                runner_up[s] <= {WORD_W{1'b0}};
                cand_a[s] <= {WORD_W{1'b0}};
                cand_b[s] <= {WORD_W{1'b0}};
            end
            for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
                traceback[t] <= {WORD_W{1'b0}};
        end else begin
            // Capture both path candidates and their comparison together.
            if (accept_branches) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    cand_a[s] <= next_a[s];
                    cand_b[s] <= next_b[s];
                    survivor[s] <= (next_b[s] < next_a[s]);
                end
                pending <= 1'b1;
            end

            // Back-pressure holds the candidate bank and output unchanged.
            // Retain the losing metric for decoder confidence estimation.
            if (retire_survivors) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    path_metric[s] <= survivor[s] ? cand_b[s] : cand_a[s];
                    runner_up[s] <= survivor[s] ? cand_a[s] : cand_b[s];
                end
                traceback[trace_wr] <= survivor_word;
                if (trace_wr == TRACE_AW'(TRACE_DEPTH - 1))
                    trace_wr <= {TRACE_AW{1'b0}};
                else
                    trace_wr <= trace_wr + {{(TRACE_AW-1){1'b0}}, 1'b1};
                pending <= 1'b0;
                // Q: the first completed trellis update.
                armed <= 1'b1;
            end
        end
    end

    // After Q, the committed terminal-state survivor never exceeds its runner-up.
    always @(posedge clk)
        assert (!armed || (path_metric[0] <= runner_up[0]));
endmodule

module dma_tdm_deadlines #(
    parameter integer ENTRIES = 8
) (
    input  wire                    clk,
    input  wire                    rst_n,

    input  wire                    cfg_valid,
    output wire                    cfg_ready,
    input  wire [63:0]             cfg_slots,
    input  wire [ENTRIES*64-1:0]    cfg_words,

    input  wire                    req_a_valid,
    output wire                    req_a_ready,
    input  wire [63:0]             req_a_slot,
    output reg                     pending_a,
    output wire                    done_a,

    input  wire                    req_b_valid,
    output wire                    req_b_ready,
    input  wire [63:0]             req_b_slot,
    output reg                     pending_b,
    output wire                    done_b,

    output wire                    out_valid,
    input  wire                    out_ready,
    output wire [63:0]             out_data,
    output wire [63:0]             out_slot
);
    localparam [63:0] MAX_SLOTS = ENTRIES;

    reg [63:0] bank [0:ENTRIES-1];
    reg loaded;
    reg [63:0] slot_count;
    reg [63:0] slot;
    reg [63:0] target_a;
    reg [63:0] target_b;
    reg [63:0] remaining_a;
    reg [63:0] remaining_b;

    wire [63:0] programmed_count =
        (cfg_slots < 64'd1) ? 64'd1 :
        ((cfg_slots > MAX_SLOTS) ? MAX_SLOTS : cfg_slots);

    assign out_valid = loaded;
    assign out_data = bank[slot];
    assign out_slot = slot;
    wire out_fire = out_valid && out_ready;

    // Replacing a running bank requires its current word to transfer.
    // An outstanding observation request prevents reprogramming.
    assign cfg_ready = !pending_a && !pending_b && (!loaded || out_ready);
    wire cfg_fire = cfg_valid && cfg_ready;

    assign req_a_ready = loaded && !pending_a && !cfg_valid;
    assign req_b_ready = loaded && !pending_b && !cfg_valid;
    wire accept_a = req_a_valid && req_a_ready;
    wire accept_b = req_b_valid && req_b_ready;

    wire [63:0] selected_a =
        (req_a_slot < slot_count) ? req_a_slot : (slot_count - 64'd1);
    wire [63:0] selected_b =
        (req_b_slot < slot_count) ? req_b_slot : (slot_count - 64'd1);

    wire [63:0] advanced_slot =
        (slot == slot_count - 64'd1) ? 64'd0 : (slot + 64'd1);
    wire [63:0] admission_slot = out_fire ? advanced_slot : slot;

    wire [63:0] initial_budget_a =
        (selected_a >= admission_slot) ?
        (selected_a - admission_slot + 64'd1) :
        (slot_count - admission_slot + selected_a + 64'd1);
    wire [63:0] initial_budget_b =
        (selected_b >= admission_slot) ?
        (selected_b - admission_slot + 64'd1) :
        (slot_count - admission_slot + selected_b + 64'd1);

    assign done_a = pending_a && out_fire && (slot == target_a);
    assign done_b = pending_b && out_fire && (slot == target_b);

    initial begin
        loaded = 1'b0;
        slot_count = MAX_SLOTS;
        slot = 64'd0;
        target_a = 64'd0;
        target_b = 64'd0;
        pending_a = 1'b0;
        pending_b = 1'b0;
        remaining_a = 64'd0;
        remaining_b = 64'd0;
    end

    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : sampled_inputs
            initial bank[g] = 64'd0;
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    bank[g] <= 64'd0;
                else if (cfg_fire)
                    bank[g] <= cfg_words[g*64 +: 64];
            end
        end
    endgenerate

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            loaded <= 1'b0;
            slot_count <= MAX_SLOTS;
            slot <= 64'd0;
            target_a <= 64'd0;
            target_b <= 64'd0;
            pending_a <= 1'b0;
            pending_b <= 1'b0;
            remaining_a <= 64'd0;
            remaining_b <= 64'd0;
        end else if (cfg_fire) begin
            loaded <= 1'b1;
            slot_count <= programmed_count;
            slot <= 64'd0;
            target_a <= 64'd0;
            target_b <= 64'd0;
            pending_a <= 1'b0;
            pending_b <= 1'b0;
            remaining_a <= 64'd0;
            remaining_b <= 64'd0;
        end else begin
            if (out_fire)
                slot <= advanced_slot;

            // A service cycle is an accepted output transfer. Back-pressure
            // freezes both the repeating schedule and its deadline budgets.
            // Requests accepted on a transfer start with the following slot.
            if (accept_a) begin
                target_a <= selected_a;
                pending_a <= 1'b1;
                remaining_a <= initial_budget_a;
            end else if (pending_a && out_fire) begin
                if (slot == target_a) begin
                    pending_a <= 1'b0;
                    remaining_a <= 64'd0;
                end else begin
                    remaining_a <= remaining_a - 64'd1;
                end
            end

            if (accept_b) begin
                target_b <= selected_b;
                pending_b <= 1'b1;
                remaining_b <= initial_budget_b;
            end else if (pending_b && out_fire) begin
                if (slot == target_b) begin
                    pending_b <= 1'b0;
                    remaining_b <= 64'd0;
                end else begin
                    remaining_b <= remaining_b - 64'd1;
                end
            end
        end
    end

    // Globally, neither accepted request may exhaust its service-cycle
    // budget while its requested slot transfer remains outstanding.
    always @(posedge clk) begin
        if (pending_a)
            assert (remaining_a != 64'd0);
        if (pending_b)
            assert (remaining_b != 64'd0);
    end
endmodule

module queued_scan_encoder #(
    parameter integer WORD_W = 32'd32,
    parameter integer DEPTH = 32'd4
) (
    input  wire clk,
    input  wire in_valid,
    output wire in_ready,
    input  wire [WORD_W-1:0] in_lines,
    output wire out_valid,
    input  wire out_ready,
    output wire [WORD_W-1:0] out_index,
    output wire out_error,
    output reg  [WORD_W-1:0] last_index,
    output reg  last_error,
    output reg  last_good
);
    localparam [31:0] DEPTH_COUNT = DEPTH;
    localparam [31:0] LAST_SLOT = DEPTH_COUNT - 32'd1;
    localparam [WORD_W-1:0] ZERO_WORD = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE_WORD = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] LINE_COUNT = WORD_W;
    localparam [WORD_W-1:0] LAST_LINE = LINE_COUNT - ONE_WORD;

    reg [WORD_W-1:0] samples [0:DEPTH-1];
    reg [DEPTH-1:0] stored_bad;
    reg [DEPTH-1:0] valid_bits;
    reg [31:0] read_ptr;
    reg [31:0] write_ptr;
    reg [31:0] fill_count;
    reg have_result;
    reg before_terminal;

    wire [DEPTH-1:0] stored_onehot;
    wire [DEPTH-1:0] occupied;
    wire input_onehot;
    wire head_onehot;
    wire push;
    wire pop;
    reg [WORD_W-1:0] head_index;
    integer lane;
    integer init_slot;

    assign input_onehot = (in_lines != ZERO_WORD) &&
                          ((in_lines & (in_lines - ONE_WORD)) == ZERO_WORD);

    genvar g;
    generate
        for (g = 32'd0; g < DEPTH; g = g + 32'd1) begin : entry_logic
            localparam [31:0] SLOT = g;
            assign stored_onehot[g] = (samples[g] != ZERO_WORD) &&
                ((samples[g] & (samples[g] - ONE_WORD)) == ZERO_WORD);
            assign occupied[g] = (SLOT >= read_ptr) ?
                ((SLOT - read_ptr) < fill_count) :
                ((SLOT + DEPTH_COUNT - read_ptr) < fill_count);
        end
    endgenerate

    assign in_ready = fill_count < DEPTH_COUNT;
    assign out_valid = fill_count != 32'd0;
    assign push = in_valid && in_ready;
    assign pop = out_valid && out_ready;
    assign head_onehot = stored_onehot[read_ptr];
    assign out_index = head_onehot ? head_index : last_index;
    assign out_error = stored_bad[read_ptr];

    always @(*) begin
        head_index = ZERO_WORD;
        for (lane = 32'd0; lane < WORD_W; lane = lane + 32'd1) begin
            if (samples[read_ptr][lane])
                head_index = lane;
        end
    end

    initial begin
        read_ptr = 32'd0;
        write_ptr = 32'd0;
        fill_count = 32'd0;
        valid_bits = {DEPTH{1'b0}};
        stored_bad = {DEPTH{1'b1}};
        last_index = ZERO_WORD;
        last_error = 1'b0;
        last_good = 1'b0;
        have_result = 1'b0;
        before_terminal = 1'b1;
        for (init_slot = 32'd0; init_slot < DEPTH;
             init_slot = init_slot + 32'd1)
            samples[init_slot] = ZERO_WORD;
    end

    always @(posedge clk) begin
        if (pop) begin
            valid_bits[read_ptr] <= 1'b0;
            if (read_ptr == LAST_SLOT)
                read_ptr <= 32'd0;
            else
                read_ptr <= read_ptr + 32'd1;

            // Encode the consumed request; retain the previous index on error.
            last_good <= head_onehot;
            last_error <= stored_bad[read_ptr];
            have_result <= 1'b1;
            if (head_onehot)
                last_index <= head_index;

            // End the checking scope at the first accepted terminal-line request.
            if (head_onehot && (head_index == LAST_LINE))
                before_terminal <= 1'b0;
        end

        if (push) begin
            samples[write_ptr] <= in_lines;
            stored_bad[write_ptr] <= !input_onehot;
            valid_bits[write_ptr] <= 1'b1;
            if (write_ptr == LAST_SLOT)
                write_ptr <= 32'd0;
            else
                write_ptr <= write_ptr + 32'd1;
        end

        case ({push, pop})
            2'b10: fill_count <= fill_count + 32'd1;
            2'b01: fill_count <= fill_count - 32'd1;
            default: fill_count <= fill_count;
        endcase
    end

    always @(posedge clk)
        if (before_terminal && have_result)
            assert (!(last_good && last_error));
endmodule

module fabric_config_fifo #(
    parameter [31:0] DEPTH = 32'd4,
    parameter [31:0] WRITE_PORTS = 32'd4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire cmd_valid,
    output wire cmd_ready,
    input  wire [31:0] cmd_count,
    input  wire [WRITE_PORTS*32'd32-32'd1:0] cmd_words,
    input  wire cmd_read,
    input  wire cmd_end_scope,
    output wire [31:0] head_word,
    output wire fifo_empty,
    output wire fifo_full
);
    typedef enum logic [1:0] {
        CFG_EMPTY  = 2'b00,
        CFG_ACTIVE = 2'b01,
        CFG_FULL   = 2'b10
    } state_t;

    state_t state;
    reg [31:0] occupancy;
    reg [31:0] wptr;
    reg [31:0] rptr;
    reg scope_open;
    reg [31:0] banks [0:DEPTH-32'd1];

    initial begin
        state = CFG_EMPTY;
        occupancy = 32'd0;
        wptr = 32'd0;
        rptr = 32'd0;
        scope_open = 1'b0;
    end

    wire [31:0] read_count = cmd_read ? 32'd1 : 32'd0;
    wire [31:0] available_slots = DEPTH - occupancy + read_count;
    wire [31:0] next_occupancy = occupancy - read_count + cmd_count;

    // A command atomically enqueues several words and optionally retires
    // the current head. An oversized command is back-pressured intact.
    assign cmd_ready = i_ce
                    && (!cmd_read || (state != CFG_EMPTY))
                    && (cmd_count <= WRITE_PORTS)
                    && (cmd_count <= available_slots);
    wire cmd_fire = cmd_valid && cmd_ready;

    assign head_word = banks[rptr];
    assign fifo_empty = (state == CFG_EMPTY);
    assign fifo_full = (state == CFG_FULL);

    // Each physical bank has its own write path. The lane offset selects
    // which incoming word belongs to that bank after circular addressing.
    generate
        for (genvar b = 32'd0; b < DEPTH; b = b + 32'd1) begin : g_bank
            localparam [31:0] BANK_INDEX = b;
            wire [31:0] lane_offset = (BANK_INDEX >= wptr)
                                   ? BANK_INDEX - wptr
                                   : DEPTH - wptr + BANK_INDEX;

            initial banks[b] = 32'd0;

            always @(posedge clk) begin
                if (cmd_fire && (lane_offset < cmd_count))
                    banks[b] <= cmd_words[lane_offset*32'd32 +: 32];
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (cmd_fire) begin
            occupancy <= next_occupancy;
            wptr <= (wptr + cmd_count) % DEPTH;
            if (cmd_read)
                rptr <= (rptr + 32'd1) % DEPTH;

            if (next_occupancy == 32'd0)
                state <= CFG_EMPTY;
            else if (next_occupancy == DEPTH)
                state <= CFG_FULL;
            else
                state <= CFG_ACTIVE;

            // Q: an accepted nonempty write bundle.
            // R: an accepted end-of-scope command; R takes precedence.
            if (cmd_end_scope)
                scope_open <= 1'b0;
            else if (cmd_count != 32'd0)
                scope_open <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (scope_open) begin
            assert ((state != CFG_EMPTY) || (wptr == rptr));
            assert ((state != CFG_FULL) || (wptr == rptr));
        end
    end
endmodule

module uart_sample_budget #(
    parameter integer DATA_BITS = 16,
    parameter integer COUNT_WIDTH = 16
) (
    input  wire clk,
    input  wire i_ce,
    input  wire frame_start,
    input  wire sample_tick,
    input  wire serial_in,
    input  wire acknowledge,
    output logic [DATA_BITS-1:0] word_data,
    output logic [COUNT_WIDTH-1:0] bit_count,
    output wire frame_done
);
    localparam logic [COUNT_WIDTH-1:0] COUNT_ZERO = {COUNT_WIDTH{1'b0}};
    localparam logic [COUNT_WIDTH-1:0] COUNT_ONE = COUNT_WIDTH'(1);
    localparam logic [COUNT_WIDTH-1:0] WORD_LIMIT = COUNT_WIDTH'(DATA_BITS);

    typedef enum logic [1:0] {
        RX_IDLE = 2'b00,
        RX_DATA = 2'b01,
        RX_DONE = 2'b10
    } state_t;

    state_t state, state_d;
    logic [COUNT_WIDTH-1:0] bit_count_d;
    logic [DATA_BITS-1:0] word_data_d;
    logic progress_toggle, progress_toggle_d;
    logic room_q;
    wire room_d;
    logic past_valid;

    initial begin
        state = RX_IDLE;
        bit_count = COUNT_ZERO;
        word_data = {DATA_BITS{1'b0}};
        progress_toggle = 1'b0;
        room_q = 1'b1;
        past_valid = 1'b0;
    end

    assign frame_done = (state == RX_DONE);

    always @* begin
        state_d = state;
        bit_count_d = bit_count;
        word_data_d = word_data;
        progress_toggle_d = progress_toggle;

        case (state)
            RX_IDLE: begin
                if (frame_start) begin
                    state_d = RX_DATA;
                    bit_count_d = COUNT_ZERO;
                    word_data_d = {DATA_BITS{1'b0}};
                    progress_toggle_d = ~progress_toggle;
                end
            end

            RX_DATA: begin
                if (sample_tick) begin
                    // Registered permission controls data-bit capture.
                    if (room_q) begin
                        bit_count_d = bit_count + COUNT_ONE;
                        word_data_d = {serial_in, word_data[DATA_BITS-1:1]};
                    end

                    // The event token marks data progress, not the stop sample.
                    if (bit_count < WORD_LIMIT)
                        progress_toggle_d = ~progress_toggle;
                    else
                        state_d = RX_DONE;
                end
            end

            RX_DONE: begin
                if (acknowledge)
                    state_d = RX_IDLE;
            end

            default: state_d = RX_IDLE;
        endcase
    end

    // Look-ahead D input for the single-bit capture-permission flip-flop.
    assign room_d = (bit_count_d < WORD_LIMIT);

    always @(posedge clk) begin
        if (i_ce)
            room_q <= room_d;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            state <= state_d;
            bit_count <= bit_count_d;
            word_data <= word_data_d;
            progress_toggle <= progress_toggle_d;
            past_valid <= 1'b1;
        end
    end

    always @(posedge clk)
        if (past_valid && $stable(progress_toggle))
            assert ($stable(bit_count) && (bit_count <= WORD_LIMIT));
endmodule

module raster_evidence_window #(
    parameter integer K = 32'd4,
    parameter integer LINE_PIXELS = 32'd32,
    parameter integer WINDOW_ENTRIES = 32'd32
) (
    input  wire clk,
    input  wire i_valid,
    output wire i_ready,
    input  wire [31:0] i_pixel,
    input  wire i_capture_end,
    output reg  o_valid,
    input  wire o_ready,
    output wire [(32*K*K)-1:0] o_window
);
    // Supported geometry: 2 <= K <= LINE_PIXELS, K*K <= WINDOW_ENTRIES.
    localparam [31:0] LAST_COLUMN = LINE_PIXELS - 32'd1;
    localparam [31:0] LAST_ROW = K - 32'd1;

    reg [31:0] column;
    reg [31:0] rows_seen;
    reg before_end;

    // Cascaded full-row delays and a 32-entry tap register bank.
    // The first K*K tap entries form the output neighborhood.
    reg [31:0] line_buffer [0:K-2][0:LINE_PIXELS-1];
    reg [31:0] window [0:WINDOW_ENTRIES-1];

    wire take;
    assign i_ready = !o_valid || o_ready;
    assign take = i_valid && i_ready;

    initial begin
        column = 32'd0;
        rows_seen = 32'd0;
        before_end = 1'b1;
        o_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (take) begin
            if (column == LAST_COLUMN) begin
                column <= 32'd0;
                if (rows_seen < LAST_ROW)
                    rows_seen <= rows_seen + 32'd1;
            end else begin
                column <= column + 32'd1;
            end

            // Suppress neighborhoods crossing the initial or left borders.
            o_valid <= (rows_seen == LAST_ROW) && (column >= LAST_ROW);
            if (i_capture_end)
                before_end <= 1'b0;
        end else if (o_valid && o_ready) begin
            o_valid <= 1'b0;
        end
    end

    genvar r, c, n, h;
    generate
        for (r = 32'd0; r < K-32'd1; r = r+32'd1) begin : g_lines
            for (c = 32'd0; c < LINE_PIXELS; c = c+32'd1) begin : g_init
                initial line_buffer[r][c] = 32'd0;
            end
            if (r == 32'd0) begin : g_input_row
                always @(posedge clk)
                    if (take)
                        line_buffer[r][column] <= i_pixel;
            end else begin : g_delayed_row
                always @(posedge clk)
                    if (take)
                        line_buffer[r][column] <= line_buffer[r-32'd1][column];
            end
        end

        for (n = 32'd0; n < WINDOW_ENTRIES; n = n+32'd1) begin : g_taps
            initial window[n] = 32'd0;
            if (n < K*K) begin : g_active
                if ((n % K) == 32'd0) begin : g_new_column
                    if (n == 32'd0) begin : g_current_pixel
                        always @(posedge clk)
                            if (take)
                                window[n] <= i_pixel;
                    end else begin : g_previous_line
                        always @(posedge clk)
                            if (take)
                                window[n] <= line_buffer[(n/K)-32'd1][column];
                    end
                end else begin : g_shift
                    always @(posedge clk)
                        if (take)
                            window[n] <= window[n-32'd1];
                end
                assign o_window[n*32 +: 32] = window[n];
            end
        end
    endgenerate

    wire [31:0] history_column [0:K-1];
    wire [K-2:0] row0_history_matches;
    generate
        for (h = 32'd0; h < K; h = h+32'd1) begin : g_history
            localparam [31:0] DISTANCE = h + 32'd1;
            assign history_column[h] = (column >= DISTANCE)
                ? column - DISTANCE
                : column + LINE_PIXELS - DISTANCE;
            if (h < K-32'd1) begin : g_match
                assign row0_history_matches[h] =
                    (window[h] == line_buffer[0][history_column[h]]);
            end
        end
    endgenerate

    // Universality before the first accepted capture-end marker.
    always @(posedge clk)
        if (before_end)
            assert (window[K-1] == line_buffer[0][history_column[K-1]]);
endmodule

module query_i2c_condition_monitor #(
    parameter integer WORD_WIDTH = 32
) (
    input  wire                  clk,
    input  wire                  sample_valid,
    output wire                  sample_ready,
    input  wire [WORD_WIDTH-1:0] sample_data,
    output reg                   event_valid,
    input  wire                  event_ready,
    output reg  [WORD_WIDTH-1:0] event_data,
    output reg                   bus_busy,
    output reg                   repeated_start
);
    localparam [WORD_WIDTH-1:0] EVENT_NONE = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] EVENT_START = {{(WORD_WIDTH-2){1'b0}}, 2'b01};
    localparam [WORD_WIDTH-1:0] EVENT_REPEAT = {{(WORD_WIDTH-2){1'b0}}, 2'b10};
    localparam [WORD_WIDTH-1:0] EVENT_STOP = {{(WORD_WIDTH-2){1'b0}}, 2'b11};

    reg prev_scl;
    reg prev_sda;
    reg first_start_seen;
    reg in_query_window;
    reg past_valid;

    wire sample_scl = sample_data[1];
    wire sample_sda = sample_data[0];
    wire start_detect = prev_scl && sample_scl && prev_sda && !sample_sda;
    wire stop_detect = prev_scl && sample_scl && !prev_sda && sample_sda;

    // A single event slot back-pressures the sampled bus input.
    assign sample_ready = !event_valid || event_ready;
    wire sample_fire = sample_valid && sample_ready;

    initial begin
        prev_scl = 1'b1;
        prev_sda = 1'b1;
        bus_busy = 1'b0;
        repeated_start = 1'b0;
        first_start_seen = 1'b0;
        in_query_window = 1'b0;
        past_valid = 1'b0;
        event_valid = 1'b0;
        event_data = EVENT_NONE;
    end

    // With sample_valid and event_ready both low, every register holds.
    always @(posedge clk) begin
        if (event_valid && event_ready)
            event_valid <= 1'b0;

        if (sample_fire) begin
            past_valid <= 1'b1;
            prev_scl <= sample_scl;
            prev_sda <= sample_sda;
            repeated_start <= start_detect && bus_busy;

            if (start_detect) begin
                bus_busy <= 1'b1;
                event_valid <= 1'b1;
                event_data <= bus_busy ? EVENT_REPEAT : EVENT_START;

                // Only an opening START establishes the earlier-event history.
                if (!bus_busy) begin
                    first_start_seen <= 1'b1;
                    in_query_window <= 1'b1;
                end
            end else if (stop_detect) begin
                bus_busy <= 1'b0;
                first_start_seen <= 1'b0;
                in_query_window <= 1'b0;
                event_valid <= 1'b1;
                event_data <= EVENT_STOP;
            end
        end
    end

    // After an opening START until STOP, a repeated START requires
    // the recorded occurrence of the earlier opening START.
    always @(posedge clk) begin
        if (past_valid && in_query_window && $rose(repeated_start))
            assert (first_start_seen);
    end
endmodule

module ctr_block_generator #(
    parameter integer WORD_W = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_open,
    input  wire                  i_close,
    input  wire                  i_take,
    input  wire [WORD_W-1:0]     i_nonce,
    input  wire [WORD_W-1:0]     i_start_counter,
    output reg  [WORD_W-1:0]     keystream_buf,
    output wire                  keystream_valid
);
    localparam [WORD_W-1:0] WORD_ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] WORD_ONE = {{(WORD_W-1){1'b0}}, 1'b1};

    typedef enum logic [1:0] {
        IDLE  = 2'b00,
        BUILD = 2'b01,
        READY = 2'b10
    } state_t;

    state_t state;
    reg window;
    reg [WORD_W-1:0] nonce_reg;
    reg [WORD_W-1:0] counter_reg;

    // Registered counter block, represented as two separate words.
    reg [WORD_W-1:0] block_nonce;
    reg [WORD_W-1:0] block_counter;

    assign keystream_valid = window && (state == READY);

    initial begin
        state         = IDLE;
        window        = 1'b0;
        nonce_reg     = WORD_ZERO;
        counter_reg   = WORD_ZERO;
        block_nonce   = WORD_ZERO;
        block_counter = WORD_ZERO;
        keystream_buf = WORD_ZERO;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Closing ends the scope; a later open starts another session.
            if (i_close) begin
                state  <= IDLE;
                window <= 1'b0;
            end else begin
                case (state)
                    IDLE: begin
                        if (i_open) begin
                            nonce_reg     <= i_nonce;
                            counter_reg   <= i_start_counter;
                            block_nonce   <= i_nonce;
                            block_counter <= i_start_counter;
                            window        <= 1'b1;
                            state         <= BUILD;
                        end
                    end
                    BUILD: begin
                        // Lightweight block-to-keystream datapath model;
                        // this XOR is not intended as a cryptographic cipher.
                        keystream_buf <= block_nonce ^ block_counter;
                        state         <= READY;
                    end
                    READY: begin
                        if (i_take) begin
                            counter_reg   <= counter_reg + WORD_ONE;
                            block_nonce   <= nonce_reg;
                            block_counter <= counter_reg + WORD_ONE;
                            state         <= BUILD;
                        end
                    end
                    default: begin
                        state  <= IDLE;
                        window <= 1'b0;
                    end
                endcase
            end
        end
    end

    always @(posedge clk)
        if (window && (state == READY))
            assert (keystream_buf == (nonce_reg ^ counter_reg));
endmodule

module power_mode_sequencer #(
    parameter integer DATA_W = 64,
    parameter integer NUM_BANKS = 32,
    parameter integer CONFIG_ENTRIES = 32,
    localparam integer PROFILES_PER_MODE = CONFIG_ENTRIES / 4,
    localparam integer PROFILE_W = (PROFILES_PER_MODE > 1) ? $clog2(PROFILES_PER_MODE) : 1,
    localparam integer CONFIG_INDEX_W = (CONFIG_ENTRIES > 1) ? $clog2(CONFIG_ENTRIES) : 1
) (
    input  wire                     clk,
    input  wire                     i_ce,
    input  wire                     cmd_valid,
    output wire                     cmd_ready,
    input  wire                     cmd_advance,
    input  wire                     cmd_cfg_write,
    input  wire [1:0]               cmd_mode,
    input  wire [PROFILE_W-1:0]     cmd_profile,
    input  wire [DATA_W-1:0]        cmd_data,
    output reg  [DATA_W-1:0]        active_count,
    output reg  [DATA_W-1:0]        active_mask
);
    typedef enum logic [1:0] {
        RUN        = 2'b00,
        IDLE       = 2'b01,
        SLEEP      = 2'b10,
        DEEP_SLEEP = 2'b11
    } mode_t;

    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] BANK_COUNT = NUM_BANKS;
    localparam [DATA_W-1:0] LAST_BANK = NUM_BANKS - 1;
    localparam [DATA_W-1:0] BANK_MASK = {DATA_W{1'b1}} >> (DATA_W - NUM_BANKS);
    localparam [DATA_W-1:0] IDLE_MASK = BANK_MASK >> (NUM_BANKS / 2);
    localparam [DATA_W-1:0] SLEEP_MASK = BANK_MASK >> ((3 * NUM_BANKS) / 4);
    localparam [PROFILE_W:0] PROFILE_LIMIT = PROFILES_PER_MODE;
    localparam [CONFIG_INDEX_W:0] CONFIG_LIMIT = CONFIG_ENTRIES;

    mode_t current_mode;
    mode_t pending_mode;
    reg pending_valid;
    reg window_open;
    reg [DATA_W-1:0] pending_target;
    reg [DATA_W-1:0] scan_index;

    // Four groups of per-mode configuration registers, with profiles in each group.
    reg [DATA_W-1:0] mode_config [0:CONFIG_ENTRIES-1];

    wire [CONFIG_INDEX_W:0] config_index =
        (cmd_mode * PROFILES_PER_MODE) + cmd_profile;
    wire profile_legal = {1'b0, cmd_profile} < PROFILE_LIMIT;

    // While a mode change is pending, only bank-acknowledgment tokens are accepted.
    // Software/configuration requests see back-pressure rather than being dropped.
    assign cmd_ready = i_ce &&
        (cmd_advance ? pending_valid :
         (!pending_valid && profile_legal && config_index < CONFIG_LIMIT));

    reg [DATA_W-1:0] enabled_total;
    integer bank_i;
    always @(*) begin
        enabled_total = ZERO;
        for (bank_i = 0; bank_i < NUM_BANKS; bank_i = bank_i + 1)
            enabled_total = enabled_total +
                {{(DATA_W-1){1'b0}}, active_mask[bank_i]};
    end

    integer config_i;
    initial begin
        current_mode = RUN;
        pending_mode = RUN;
        pending_valid = 1'b0;
        window_open = 1'b0;
        pending_target = BANK_MASK;
        scan_index = ZERO;
        active_mask = BANK_MASK;
        active_count = BANK_COUNT;
        for (config_i = 0; config_i < CONFIG_ENTRIES; config_i = config_i + 1) begin
            case (config_i / PROFILES_PER_MODE)
                RUN:        mode_config[config_i] = BANK_MASK;
                IDLE:       mode_config[config_i] = IDLE_MASK;
                SLEEP:      mode_config[config_i] = SLEEP_MASK;
                DEEP_SLEEP: mode_config[config_i] = ZERO;
                default:    mode_config[config_i] = ZERO;
            endcase
        end
    end

    // Every state change consumes a command token. With valid low, or i_ce low,
    // the complete controller and its configuration storage remain unchanged.
    always @(posedge clk) begin
        if (cmd_valid && cmd_ready) begin
            if (cmd_advance) begin
                // A power-control acknowledgment applies the next bank setting.
                if (pending_target[scan_index] != active_mask[scan_index]) begin
                    active_mask[scan_index] <= pending_target[scan_index];
                    if (pending_target[scan_index])
                        active_count <= active_count + ONE;
                    else
                        active_count <= active_count - ONE;
                end

                if (scan_index == LAST_BANK) begin
                    scan_index <= ZERO;
                    pending_valid <= 1'b0;
                    current_mode <= pending_mode;
                end else begin
                    scan_index <= scan_index + ONE;
                end
            end else if (cmd_cfg_write) begin
                mode_config[config_index] <= cmd_data;
            end else begin
                pending_target <= mode_config[config_index];
                pending_valid <= 1'b1;
                scan_index <= ZERO;
                case (cmd_mode)
                    RUN:        pending_mode <= RUN;
                    IDLE:       pending_mode <= IDLE;
                    SLEEP:      pending_mode <= SLEEP;
                    DEEP_SLEEP: pending_mode <= DEEP_SLEEP;
                endcase

                // Q: accept a low-power request. R: accept a RUN/wake request.
                if (cmd_mode == RUN)
                    window_open <= 1'b0;
                else
                    window_open <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        assert (!window_open || active_count <= BANK_COUNT);
endmodule

module probe_ethertype_demux #(
    parameter integer WORD_W = 16,
    parameter integer ENTRIES = 8,
    parameter integer QUEUES = 8
) (
    input  wire                       i_clk,
    input  wire                       i_ce,
    input  wire                       i_header_valid,
    output wire                       o_header_ready,
    input  wire [WORD_W-1:0]          i_header_word,
    input  wire                       i_cfg_valid,
    output wire                       o_cfg_ready,
    input  wire [WORD_W-1:0]          i_cfg_index,
    input  wire [WORD_W-1:0]          i_cfg_type,
    input  wire [WORD_W-1:0]          i_cfg_queue,
    input  wire                       i_cfg_enable,
    input  wire                       i_take,
    input  wire [WORD_W-1:0]          i_take_queue,
    output wire [QUEUES-1:0]          o_queue_full,
    output wire [QUEUES*WORD_W-1:0]   o_queue_data,
    output wire                       o_route_done,
    output wire [WORD_W-1:0]          o_route_queue
);
    // A header slicer supplies six MAC-address words followed by EtherType.
    // Each protocol queue is a one-entry EtherType descriptor mailbox.
    // Mailbox removal uses an explicit clock-enabled take command.
    localparam [WORD_W-1:0] TYPE_WORD_INDEX = WORD_W'(16'd6);
    localparam [WORD_W-1:0] TABLE_LIMIT = WORD_W'(ENTRIES);
    localparam [WORD_W-1:0] QUEUE_LIMIT = WORD_W'(QUEUES);

    typedef enum logic [1:0] { HEADER, LOOKUP, ENQUEUE, DONE } state_t;
    state_t state;

    reg [WORD_W-1:0] header_word;
    reg [WORD_W-1:0] type_reg;
    reg [WORD_W-1:0] type_table [0:ENTRIES-1];
    reg [WORD_W-1:0] queue_table [0:ENTRIES-1];
    reg [ENTRIES-1:0] match_valid;
    reg [WORD_W-1:0] match_index;

    // Shadow of the earlier successful table lookup.
    reg lookup_seen;
    reg [WORD_W-1:0] lookup_queue;
    reg [WORD_W-1:0] routed_queue;
    reg armed;
    reg past_valid;

    reg [QUEUES-1:0] queue_full;
    reg [WORD_W-1:0] queue_data [0:QUEUES-1];

    reg match_found;
    reg [WORD_W-1:0] found_index;
    reg [WORD_W-1:0] found_queue;
    reg table_queues_legal;

    initial begin
        state = HEADER;
        header_word = WORD_W'(16'd0);
        type_reg = WORD_W'(16'd0);
        match_index = WORD_W'(16'd0);
        lookup_seen = 1'b0;
        lookup_queue = WORD_W'(16'd0);
        routed_queue = WORD_W'(16'd0);
        armed = 1'b0;
        past_valid = 1'b0;
        match_valid = {ENTRIES{1'b1}};
        queue_full = {QUEUES{1'b0}};
        for (integer n = 0; n < ENTRIES; n = n + 1) begin
            type_table[n] = WORD_W'(16'h88b5) + WORD_W'(n);
            queue_table[n] = WORD_W'(n % QUEUES);
        end
        for (integer n = 0; n < QUEUES; n = n + 1)
            queue_data[n] = WORD_W'(16'd0);
    end

    always @(*) begin
        match_found = 1'b0;
        found_index = WORD_W'(16'd0);
        found_queue = WORD_W'(16'd0);
        table_queues_legal = 1'b1;
        for (integer n = 0; n < ENTRIES; n = n + 1) begin
            table_queues_legal = table_queues_legal &&
                                 (queue_table[n] < QUEUE_LIMIT);
            if (!match_found && match_valid[n] &&
                type_table[n] == type_reg) begin
                match_found = 1'b1;
                found_index = WORD_W'(n);
                found_queue = queue_table[n];
            end
        end
    end

    // Configuration is accepted only between complete headers.
    assign o_cfg_ready = i_ce && state == HEADER &&
                         header_word == WORD_W'(16'd0) &&
                         i_cfg_index < TABLE_LIMIT &&
                         i_cfg_queue < QUEUE_LIMIT;
    assign o_header_ready = i_ce && state == HEADER &&
                            !(i_cfg_valid &&
                              header_word == WORD_W'(16'd0));
    assign o_queue_full = queue_full;
    assign o_route_done = state == DONE;
    assign o_route_queue = routed_queue;

    generate
        for (genvar q = 0; q < QUEUES; q = q + 1) begin : queue_outputs
            assign o_queue_data[q*WORD_W +: WORD_W] = queue_data[q];
        end
    endgenerate

    always @(posedge i_clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;

            if (i_take && i_take_queue < QUEUE_LIMIT)
                queue_full[i_take_queue] <= 1'b0;

            if (i_cfg_valid && o_cfg_ready) begin
                type_table[i_cfg_index] <= i_cfg_type;
                queue_table[i_cfg_index] <= i_cfg_queue;
                match_valid[i_cfg_index] <= i_cfg_enable;
            end

            case (state)
                HEADER: begin
                    if (i_header_valid && o_header_ready) begin
                        if (header_word == WORD_W'(16'd0))
                            lookup_seen <= 1'b0;
                        if (header_word == TYPE_WORD_INDEX) begin
                            type_reg <= i_header_word;
                            header_word <= WORD_W'(16'd0);
                            armed <= 1'b1;
                            state <= LOOKUP;
                        end else begin
                            header_word <= header_word + WORD_W'(16'd1);
                        end
                    end
                end
                LOOKUP: begin
                    if (match_found) begin
                        match_index <= found_index;
                        lookup_queue <= found_queue;
                        lookup_seen <= 1'b1;
                        state <= ENQUEUE;
                    end else begin
                        state <= HEADER;
                    end
                end
                ENQUEUE: begin
                    // A full destination back-pressures the header receiver.
                    if (!queue_full[queue_table[match_index]]) begin
                        queue_data[queue_table[match_index]] <= type_reg;
                        queue_full[queue_table[match_index]] <= 1'b1;
                        routed_queue <= queue_table[match_index];
                        state <= DONE;
                    end
                end
                DONE: begin
                    state <= HEADER;
                end
            endcase
        end
    end

    // After the first EtherType extraction, every new routing completion
    // must agree with the successful lookup recorded earlier.
    always @(posedge i_clk) begin
        if (past_valid && armed && $rose(o_route_done))
            assert (lookup_seen && routed_queue == lookup_queue);
    end
endmodule

module axi_qword_page_splitter #(
    parameter integer WORD_W = 64,
    parameter [WORD_W-1:0] MAX_BURST_BEATS = 64'd8
) (
    input wire clk,
    input wire ce,
    input wire flush,
    input wire load,
    input wire split,
    input wire return_rsp,
    input wire [WORD_W-1:0] req_addr,
    input wire [WORD_W-1:0] req_beats,
    output reg [WORD_W-1:0] burst_addr,
    output reg [WORD_W-1:0] burst_beats,
    output reg burst_last,
    output reg burst_issued,
    output reg merged_response
);
    // Command-driven splitter for 64-bit payload beats; no ready/valid handshake.
    localparam [WORD_W-1:0] BEAT_BYTES = 64'd8;
    localparam [WORD_W-1:0] PAGE_BYTES = 64'd4096;
    localparam [WORD_W-1:0] PAGE_MASK = PAGE_BYTES - 64'd1;

    reg active;
    reg before_flush;
    reg [WORD_W-1:0] remaining;
    reg [WORD_W-1:0] next_addr;
    reg [WORD_W-1:0] request_end;
    reg [WORD_W-1:0] outstanding;

    // Shadows of the earlier issuance of the request's final sub-burst.
    reg tail_seen;
    reg [WORD_W-1:0] last_issue_end;

    wire [WORD_W-1:0] page_beats;
    wire [WORD_W-1:0] issue_beats;
    assign page_beats = (PAGE_BYTES - (next_addr & PAGE_MASK)) / BEAT_BYTES;
    assign issue_beats = (remaining < page_beats) ? remaining : page_beats;

    wire legal_request;
    assign legal_request =
        (req_beats != 64'd0) &&
        (req_beats <= MAX_BURST_BEATS) &&
        ((req_addr % BEAT_BYTES) == 64'd0) &&
        (req_addr <= ({WORD_W{1'b1}} - req_beats * BEAT_BYTES));

    initial begin
        active = 1'b0;
        before_flush = 1'b1;
        remaining = 64'd0;
        next_addr = 64'd0;
        request_end = 64'd0;
        outstanding = 64'd0;
        tail_seen = 1'b0;
        last_issue_end = 64'd0;
        burst_addr = 64'd0;
        burst_beats = 64'd0;
        burst_last = 1'b0;
        burst_issued = 1'b0;
        merged_response = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            burst_issued <= 1'b0;
            if (flush) begin
                // The first flush permanently ends the monitored scope.
                before_flush <= 1'b0;
                active <= 1'b0;
                remaining <= 64'd0;
                next_addr <= 64'd0;
                request_end <= 64'd0;
                outstanding <= 64'd0;
                tail_seen <= 1'b0;
                last_issue_end <= 64'd0;
                burst_addr <= 64'd0;
                burst_beats <= 64'd0;
                burst_last <= 1'b0;
                merged_response <= 1'b0;
            end else if (load && (!active || merged_response) && legal_request) begin
                active <= 1'b1;
                remaining <= req_beats;
                next_addr <= req_addr;
                request_end <= req_addr + req_beats * BEAT_BYTES;
                outstanding <= 64'd0;
                tail_seen <= 1'b0;
                last_issue_end <= 64'd0;
                merged_response <= 1'b0;
            end else if (split && active && !merged_response &&
                         (remaining != 64'd0)) begin
                // Emit the largest prefix contained within the current 4KB page.
                burst_addr <= next_addr;
                burst_beats <= issue_beats;
                burst_last <= (issue_beats == remaining);
                burst_issued <= 1'b1;
                remaining <= remaining - issue_beats;
                next_addr <= next_addr + issue_beats * BEAT_BYTES;
                outstanding <= outstanding + 64'd1;
                last_issue_end <= next_addr + issue_beats * BEAT_BYTES;
                if (issue_beats == remaining)
                    tail_seen <= 1'b1;
            end else if (return_rsp && active && !merged_response &&
                         (outstanding != 64'd0)) begin
                outstanding <= outstanding - 64'd1;
                if ((remaining == 64'd0) && (outstanding == 64'd1))
                    merged_response <= 1'b1;
            end
        end
    end

    // Before the first flush, merged completion must be preceded by issuance
    // of the final sub-burst, whose recorded endpoint matches this request.
    always @(posedge clk)
        if (before_flush && merged_response)
            assert (tail_seen && (last_issue_end == request_end));
endmodule

module keypad_combination_lock #(
    parameter integer DATA_W = 128,
    parameter integer CODE_DIGITS = 16,
    parameter integer MAX_FAILURES = 4,
    parameter integer LOCKOUT_CYCLES = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  start_session,
    input  wire                  end_session,
    input  wire                  digit_valid,
    input  wire [DATA_W-1:0]     keypad_digit,
    output wire                  access_granted
);
    localparam integer POS_W = (CODE_DIGITS > 1) ? $clog2(CODE_DIGITS) : 1;
    localparam integer FAIL_W = (MAX_FAILURES > 0) ? $clog2(MAX_FAILURES + 1) : 1;
    localparam integer TIMER_W = (LOCKOUT_CYCLES > 0) ? $clog2(LOCKOUT_CYCLES + 1) : 1;

    localparam logic [POS_W-1:0] LAST_POSITION = POS_W'(CODE_DIGITS - 1);
    localparam logic [FAIL_W-1:0] FAILURE_LIMIT = FAIL_W'(MAX_FAILURES);
    localparam logic [TIMER_W-1:0] TIMER_LIMIT = TIMER_W'(LOCKOUT_CYCLES);

    typedef enum logic [2:0] {
        IDLE     = 3'b000,
        COLLECT  = 3'b001,
        VERIFIED = 3'b010,
        UNLOCKED = 3'b011,
        LOCKOUT  = 3'b100
    } state_t;

    state_t state;
    logic [DATA_W-1:0] stored_code [0:CODE_DIGITS-1];
    logic [POS_W-1:0] digit_position;
    logic [FAIL_W-1:0] failed_attempts;
    logic [TIMER_W-1:0] lockout_timer;
    logic window;
    logic completion_seen;
    integer i;

    initial begin
        state = IDLE;
        digit_position = '0;
        failed_attempts = '0;
        lockout_timer = '0;
        window = 1'b0;
        completion_seen = 1'b0;
        for (i = 0; i < CODE_DIGITS; i = i + 1)
            stored_code[i] = DATA_W'(128'h7351_9024_ABCD_0027_6193_8456_1020_3000) + DATA_W'(i);
    end

    assign access_granted = (state == UNLOCKED);

    always @(posedge clk) begin
        if (i_ce) begin
            // Q is an accepted start_session; R is an accepted end_session.
            if (window && end_session) begin
                state <= IDLE;
                window <= 1'b0;
                completion_seen <= 1'b0;
                digit_position <= '0;
                failed_attempts <= '0;
                lockout_timer <= '0;
            end else begin
                case (state)
                    IDLE: begin
                        if (start_session) begin
                            state <= COLLECT;
                            window <= 1'b1;
                            completion_seen <= 1'b0;
                            digit_position <= '0;
                            failed_attempts <= '0;
                            lockout_timer <= '0;
                        end
                    end

                    COLLECT: begin
                        if (digit_valid) begin
                            if (keypad_digit == stored_code[digit_position]) begin
                                if (digit_position == LAST_POSITION) begin
                                    // Remember the earlier complete-code event.
                                    completion_seen <= 1'b1;
                                    state <= VERIFIED;
                                end else begin
                                    digit_position <= digit_position + POS_W'(1);
                                end
                            end else begin
                                digit_position <= '0;
                                completion_seen <= 1'b0;
                                if (failed_attempts >= FAILURE_LIMIT - FAIL_W'(1)) begin
                                    failed_attempts <= FAILURE_LIMIT;
                                    lockout_timer <= TIMER_LIMIT;
                                    state <= LOCKOUT;
                                end else begin
                                    failed_attempts <= failed_attempts + FAIL_W'(1);
                                end
                            end
                        end
                    end

                    VERIFIED: begin
                        // Grant only on a later enabled edge than completion.
                        state <= UNLOCKED;
                    end

                    UNLOCKED: begin
                        // The session remains open until end_session.
                    end

                    LOCKOUT: begin
                        if (lockout_timer > TIMER_W'(1)) begin
                            lockout_timer <= lockout_timer - TIMER_W'(1);
                        end else begin
                            lockout_timer <= '0;
                            failed_attempts <= '0;
                            digit_position <= '0;
                            state <= COLLECT;
                        end
                    end

                    default: begin
                        state <= IDLE;
                        window <= 1'b0;
                        completion_seen <= 1'b0;
                        digit_position <= '0;
                        failed_attempts <= '0;
                        lockout_timer <= '0;
                    end
                endcase
            end
        end
    end

    // Within the session, an observed grant requires prior code completion.
    always @(posedge clk)
        assert (!(window && (state == UNLOCKED)) || completion_seen);
endmodule

module zq_chain_scheduler #(
    parameter integer DATA_WIDTH = 128,
    parameter integer INTERVAL_CYCLES = 6,
    parameter integer BLOCK_CYCLES = 4
) (
    input  wire                  clk,
    input  wire                  tick_valid,
    input  wire [DATA_WIDTH-1:0]  cfg_zq_word,
    output wire                  zq_valid,
    input  wire                  zq_ready,
    output reg  [DATA_WIDTH-1:0]  zq_data,
    output reg                   cal_in_progress,
    output wire                  finish_fire
);
    localparam integer INTERVAL_W = (INTERVAL_CYCLES > 1) ? $clog2(INTERVAL_CYCLES) : 1;
    localparam integer BLOCK_W = (BLOCK_CYCLES > 0) ? $clog2(BLOCK_CYCLES + 1) : 1;
    localparam [INTERVAL_W-1:0] INTERVAL_ZERO = {INTERVAL_W{1'b0}};
    localparam [INTERVAL_W-1:0] INTERVAL_ONE = INTERVAL_W'(1);
    localparam [INTERVAL_W-1:0] INTERVAL_LAST = INTERVAL_W'(INTERVAL_CYCLES - 1);
    localparam [BLOCK_W-1:0] BLOCK_ZERO = {BLOCK_W{1'b0}};
    localparam [BLOCK_W-1:0] BLOCK_ONE = BLOCK_W'(1);
    localparam [BLOCK_W-1:0] BLOCK_LIMIT = BLOCK_W'(BLOCK_CYCLES);

    typedef enum logic [1:0] {
        WAIT_INTERVAL = 2'd0,
        ARMED         = 2'd1,
        STARTED       = 2'd2,
        FINISHED      = 2'd3
    } state_t;

    state_t phase;
    reg [INTERVAL_W-1:0] interval_count;
    reg [BLOCK_W-1:0] block_timer;
    reg pv;

    wire arm_fire;
    wire start_fire;

    assign arm_fire = tick_valid && (phase == WAIT_INTERVAL) &&
                      (interval_count == INTERVAL_LAST);
    assign zq_valid = (phase == ARMED);
    assign start_fire = zq_valid && zq_ready;
    assign finish_fire = tick_valid && cal_in_progress &&
                         (block_timer == BLOCK_ONE);

    initial begin
        phase = WAIT_INTERVAL;
        interval_count = INTERVAL_ZERO;
        block_timer = BLOCK_ZERO;
        cal_in_progress = 1'b0;
        zq_data = {DATA_WIDTH{1'b0}};
        pv = 1'b0;
    end

    // tick_valid advances enabled time. A command starts only on its
    // valid/ready handshake. With tick_valid and zq_ready low, all state holds.
    always @(posedge clk) begin
        if (tick_valid || start_fire)
            pv <= 1'b1;

        case (phase)
            WAIT_INTERVAL: begin
                if (arm_fire) begin
                    interval_count <= INTERVAL_ZERO;
                    zq_data <= cfg_zq_word;
                    phase <= ARMED;
                end else if (tick_valid) begin
                    interval_count <= interval_count + INTERVAL_ONE;
                end
            end
            ARMED: begin
                // Neither valid nor data changes under back-pressure.
                if (start_fire)
                    phase <= STARTED;
            end
            STARTED: begin
                if (finish_fire)
                    phase <= FINISHED;
            end
            FINISHED: begin
                if (tick_valid)
                    phase <= WAIT_INTERVAL;
            end
        endcase

        // The blocking timer tracks the independently maintained busy flag.
        if (start_fire) begin
            cal_in_progress <= 1'b1;
            block_timer <= BLOCK_LIMIT;
        end else if (tick_valid && cal_in_progress) begin
            if (block_timer == BLOCK_ONE) begin
                block_timer <= BLOCK_ZERO;
                cal_in_progress <= 1'b0;
            end else begin
                block_timer <= block_timer - BLOCK_ONE;
            end
        end
    end

    // ARMED witnesses the earlier arm; STARTED witnesses arm followed by start.
    // Check both precedence requirements about the previous cycle globally.
    always @(posedge clk) begin
        if (pv && $past(start_fire || finish_fire))
            assert ((!$past(start_fire) || $past(phase == ARMED)) &&
                    (!$past(finish_fire) || $past(phase == STARTED)));
    end
endmodule

module decimal_instruction_unit #(
    parameter integer DIGITS = 8
) (
    input  wire                    clk,
    input  wire                    i_ce,
    input  wire                    start,
    input  wire                    trap_event,
    input  wire [4*DIGITS-1:0]     operand_a,
    input  wire [4*DIGITS-1:0]     operand_b,
    output reg  [4*DIGITS-1:0]     result,
    output reg  [4*DIGITS-1:0]     carry_count,
    output reg                     complete
);
    localparam integer WORD_WIDTH = 4 * DIGITS;
    localparam [WORD_WIDTH-1:0] DIGIT_LIMIT = DIGITS;
    localparam [WORD_WIDTH-1:0] ZERO = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] ONE = {{(WORD_WIDTH-1){1'b0}}, 1'b1};

    reg [WORD_WIDTH-1:0] digits_done;
    reg [WORD_WIDTH-1:0] carry_queue;
    reg before_trap;
    reg pv;

    wire [WORD_WIDTH-1:0] decimal_sum;
    wire [WORD_WIDTH-1:0] decimal_carries;
    wire [DIGITS:0] digit_carry;
    wire [DIGITS-1:0] result_digit_ok;
    wire result_is_bcd;

    assign digit_carry[0] = 1'b0;
    assign decimal_carries[WORD_WIDTH-1:DIGITS] =
        {(WORD_WIDTH-DIGITS){1'b0}};
    assign result_is_bcd = &result_digit_ok;

    // Packed-decimal ripple adder. Invalid input digits are treated as zero,
    // giving defined behavior for every input without environmental premises.
    genvar d;
    generate
        for (d = 0; d < DIGITS; d = d + 1) begin : decimal_digit
            wire [3:0] a_digit;
            wire [3:0] b_digit;
            wire [4:0] raw_sum;
            wire [4:0] corrected_sum;

            assign a_digit = (operand_a[4*d +: 4] <= 4'd9)
                           ? operand_a[4*d +: 4] : 4'd0;
            assign b_digit = (operand_b[4*d +: 4] <= 4'd9)
                           ? operand_b[4*d +: 4] : 4'd0;
            assign raw_sum = {1'b0, a_digit} + {1'b0, b_digit}
                           + {4'b0000, digit_carry[d]};
            assign digit_carry[d+1] = (raw_sum > 5'd9);
            assign corrected_sum = digit_carry[d+1]
                                 ? raw_sum + 5'd6 : raw_sum;
            assign decimal_sum[4*d +: 4] = corrected_sum[3:0];
            assign decimal_carries[d] = digit_carry[d+1];
            assign result_digit_ok[d] = (result[4*d +: 4] <= 4'd9);
        end
    endgenerate

    initial begin
        result = ZERO;
        carry_count = ZERO;
        digits_done = ZERO;
        carry_queue = ZERO;
        complete = 1'b0;
        before_trap = 1'b1;
        pv = 1'b0;
    end

    // A decimal instruction captures its sum and carry chain, then scans one
    // digit-carry per enabled cycle to produce its carry-event statistic.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (trap_event)
                before_trap <= 1'b0;

            if (start) begin
                result <= decimal_sum;
                carry_queue <= decimal_carries;
                digits_done <= ZERO;
                carry_count <= ZERO;
                complete <= 1'b0;
            end else if (digits_done < DIGIT_LIMIT) begin
                carry_queue <= carry_queue >> 1'b1;
                digits_done <= digits_done + ONE;
                carry_count <= carry_count
                             + {{(WORD_WIDTH-1){1'b0}}, carry_queue[0]};
                if (digits_done == DIGIT_LIMIT - ONE)
                    complete <= 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (pv && before_trap && $rose(complete))
            assert (carry_count <= DIGIT_LIMIT);
    end
endmodule

module packet_mlt3_encoder #(
    parameter integer WORD_W = 64
) (
    input  wire                     clk,
    input  wire                     rst_n,
    input  wire                     s_valid,
    output wire                     s_ready,
    input  wire [WORD_W-1:0]        s_data,
    output reg                      m_valid,
    input  wire                     m_ready,
    output reg signed [WORD_W-1:0]  line_level
);
    localparam [WORD_W-1:0] LEVEL_ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] LEVEL_POS  = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] LEVEL_NEG  = {WORD_W{1'b1}};

    // MLT-3 sequence: negative, zero, positive, zero.
    reg [1:0] phase;
    reg signed [WORD_W-1:0] before_level;
    reg pv;

    assign s_ready = !m_valid || m_ready;
    wire take = s_valid && s_ready;

    initial begin
        phase        = 2'd1;
        line_level   = LEVEL_ZERO;
        before_level = LEVEL_ZERO;
        m_valid      = 1'b0;
        pv           = 1'b0;
    end

    // Each input word supplies one line-code bit in bit zero.
    // The output slot supports simultaneous retirement and replacement.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase        <= 2'd1;
            line_level   <= LEVEL_ZERO;
            before_level <= LEVEL_ZERO;
            m_valid      <= 1'b0;
            pv           <= 1'b0;
        end else begin
            if (take) begin
                before_level <= line_level;
                m_valid      <= 1'b1;
                pv           <= 1'b1;
                if (s_data[0]) begin
                    phase <= phase + 2'd1;
                    case (phase)
                        2'd0: line_level <= LEVEL_ZERO;
                        2'd1: line_level <= LEVEL_POS;
                        2'd2: line_level <= LEVEL_ZERO;
                        2'd3: line_level <= LEVEL_NEG;
                    endcase
                end
            end else if (m_valid && m_ready) begin
                m_valid <= 1'b0;
            end
        end
    end

    // A nonzero symbol produced by a one bit must have been
    // preceded by zero; the shadow records that earlier level.
    always @(posedge clk) begin
        if (pv && m_valid && (line_level != LEVEL_ZERO) &&
            $past(take && s_data[0]))
            assert ((before_level == $past(line_level)) &&
                    (before_level == LEVEL_ZERO));
    end
endmodule

module scheduled_test_mux #(
    parameter [31:0] CHANNELS = 32'd6
) (
    input  wire                              clk,
    input  wire                              i_ce,
    input  wire                              i_program,
    input  wire [31:0]                       i_slot_count,
    input  wire                              i_window_open,
    input  wire                              i_window_close,
    input  wire [32'd32*CHANNELS-32'd1:0]     i_sources,
    output wire [31:0]                       o_data,
    output wire [CHANNELS-32'd1:0]           o_owner
);
    // Supported configurations have 3 through 16 channels.
    reg [31:0] slot;
    reg [31:0] slot_count;
    reg [31:0] owner_token;
    reg        window_active;

    initial begin
        slot          = 32'd0;
        slot_count    = CHANNELS;
        owner_token   = 32'd1;
        window_active = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // A latched checking window, independently reopenable each round.
            if (i_window_close)
                window_active <= 1'b0;
            else if (i_window_open)
                window_active <= 1'b1;

            if (i_program) begin
                if (i_slot_count < 32'd3)
                    slot_count <= 32'd3;
                else if (i_slot_count > CHANNELS)
                    slot_count <= CHANNELS;
                else
                    slot_count <= i_slot_count;
                slot        <= 32'd0;
                owner_token <= 32'd1;
            end else if (slot == slot_count - 32'd1) begin
                slot        <= 32'd0;
                owner_token <= 32'd1;
            end else begin
                slot        <= slot + 32'd1;
                owner_token <= owner_token << 32'd1;
            end
        end
    end

    // The dedicated test lane uses the binary slot decoder; other lanes
    // use the rotating ownership token. Their selected words share an OR mux.
    wire [31:0] mux_chain [0:CHANNELS];
    assign mux_chain[0] = 32'd0;

    genvar lane;
    generate
        for (lane = 0; lane < CHANNELS; lane = lane + 1) begin : g_lane
            if (lane == 1) begin : g_test_lane
                assign o_owner[lane] = (slot == 32'd1);
            end else begin : g_token_lane
                assign o_owner[lane] = owner_token[lane];
            end
            assign mux_chain[lane+1] = mux_chain[lane]
                | (i_sources[32*lane +: 32] & {32{o_owner[lane]}});
        end
    endgenerate

    assign o_data = mux_chain[CHANNELS];

    always @(posedge clk)
        if (window_active)
            assert (!(o_owner[1] && o_owner[2]));
endmodule

module ahb_axi_write_bridge #(
    parameter integer ADDR_WIDTH = 16,
    parameter integer DATA_WIDTH = 16
) (
    input  wire                  clk,
    input  wire                  haddr_valid,
    output wire                  hready,
    input  wire [ADDR_WIDTH-1:0] haddr,
    input  wire [2:0]            hsize,
    input  wire [2:0]            hburst,
    input  wire                  hwdata_valid,
    output wire                  hwdata_ready,
    input  wire [DATA_WIDTH-1:0] hwdata,

    output wire                  axi_awvalid,
    input  wire                  axi_awready,
    output wire [ADDR_WIDTH-1:0] axi_awaddr,
    output wire [2:0]            axi_awsize,
    output wire [1:0]            axi_awburst,
    output wire [7:0]            axi_awlen,
    output wire                  axi_wvalid,
    input  wire                  axi_wready,
    output wire [DATA_WIDTH-1:0] axi_wdata,
    output wire                  axi_wlast,
    input  wire                  axi_bvalid,
    output wire                  axi_bready
);
    // Write-only bridge: each qualified AHB beat becomes one AXI beat.
    // Separate address/data qualifiers identify the AHB phases.
    localparam [1:0] PH_IDLE  = 2'd0;
    localparam [1:0] PH_DATA  = 2'd1;
    localparam [1:0] PH_ISSUE = 2'd2;
    localparam [1:0] PH_RESP  = 2'd3;

    reg [1:0] phase;
    reg [ADDR_WIDTH-1:0] saved_haddr;
    reg [2:0] saved_hsize;
    reg [2:0] saved_hburst;
    reg [DATA_WIDTH-1:0] wdata_buffer;
    reg aw_pending;
    reg wbuf_valid;
    reg waiting_response;
    reg scope_window;
    reg past_valid;

    initial begin
        phase = PH_IDLE;
        saved_haddr = {ADDR_WIDTH{1'b0}};
        saved_hsize = 3'd0;
        saved_hburst = 3'd0;
        wdata_buffer = {DATA_WIDTH{1'b0}};
        aw_pending = 1'b0;
        wbuf_valid = 1'b0;
        waiting_response = 1'b0;
        scope_window = 1'b0;
        past_valid = 1'b0;
    end

    assign hready = !waiting_response;
    assign hwdata_ready = (phase == PH_DATA);
    assign axi_awvalid = aw_pending;
    assign axi_awaddr = saved_haddr;
    assign axi_awsize = saved_hsize;
    // Bursts are decomposed into individual AXI transactions.
    assign axi_awburst = (saved_hburst == 3'd0) ? 2'b00 : 2'b01;
    assign axi_awlen = 8'd0;
    assign axi_wvalid = wbuf_valid;
    assign axi_wdata = wdata_buffer;
    assign axi_wlast = 1'b1;
    assign axi_bready = (phase == PH_RESP);

    wire addr_fire = haddr_valid && hready;
    wire data_fire = hwdata_valid && hwdata_ready;
    wire aw_fire = axi_awvalid && axi_awready;
    wire w_fire = axi_wvalid && axi_wready;
    wire b_fire = axi_bvalid && axi_bready;

    // No autonomous transitions: with input valids and AXI readies low,
    // every register holds, including the history-valid register.
    always @(posedge clk) begin
        case (phase)
            PH_IDLE: begin
                if (addr_fire) begin
                    saved_haddr <= haddr;
                    saved_hsize <= hsize;
                    saved_hburst <= hburst;
                    waiting_response <= 1'b1;
                    scope_window <= 1'b1; // Q: address accepted
                    past_valid <= 1'b1;
                    phase <= PH_DATA;
                end
            end
            PH_DATA: begin
                if (data_fire) begin
                    wdata_buffer <= hwdata;
                    wbuf_valid <= 1'b1;
                    aw_pending <= 1'b1;
                    phase <= PH_ISSUE;
                end
            end
            PH_ISSUE: begin
                if (aw_fire)
                    aw_pending <= 1'b0;
                if (w_fire)
                    wbuf_valid <= 1'b0;
                if ((aw_fire || w_fire) &&
                    (!aw_pending || aw_fire) &&
                    (!wbuf_valid || w_fire))
                    phase <= PH_RESP;
            end
            PH_RESP: begin
                if (b_fire) begin
                    waiting_response <= 1'b0;
                    scope_window <= 1'b0; // R: response accepted
                    phase <= PH_IDLE;
                end
            end
        endcase
    end

    // Within the transaction window, unchanged buffer validity means
    // the buffered data must also be unchanged.
    always @(posedge clk)
        if (past_valid && scope_window && $stable(wbuf_valid))
            assert ($stable(wdata_buffer));
endmodule

module duty_cycle_corrector #(
    parameter integer WORD_W = 64
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_high_ticks,
    input  wire [WORD_W-1:0]     in_low_ticks,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [WORD_W-1:0]     out_high_ticks,
    output reg  [WORD_W-1:0]     applied_high_time
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] HALF_SCALE = {1'b1, {(WORD_W-1){1'b0}}};

    reg [WORD_W-1:0] high_shadow;
    reg [WORD_W-1:0] low_shadow;
    reg [WORD_W-1:0] correction_code;
    reg pending;
    reg armed;
    reg pv;

    // The code is a two's-complement adjustment in high-time units.
    // Halving each measured interval avoids overflowing the imbalance.
    wire [WORD_W-1:0] shadow_half_imbalance =
        (high_shadow >> ONE) - (low_shadow >> ONE);
    wire [WORD_W-1:0] reference_high =
        HALF_SCALE - shadow_half_imbalance;

    assign in_ready = !pending;
    assign out_valid = pending;
    assign out_high_ticks = HALF_SCALE + correction_code;

    wire take_measurement = in_valid && in_ready;
    wire apply_correction = out_valid && out_ready;

    initial begin
        high_shadow = ZERO;
        low_shadow = ZERO;
        correction_code = ZERO;
        applied_high_time = HALF_SCALE;
        pending = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (take_measurement) begin
            high_shadow <= in_high_ticks;
            low_shadow <= in_low_ticks;
            correction_code <= (in_low_ticks >> ONE)
                             - (in_high_ticks >> ONE);
            pending <= 1'b1;
            // Q: the first accepted duty-cycle measurement.
            armed <= 1'b1;
        end

        if (apply_correction) begin
            applied_high_time <= out_high_ticks;
            pending <= 1'b0;
        end

        // No checker state changes during an idle cycle either.
        if (take_measurement || apply_correction)
            pv <= 1'b1;
    end

    // Once armed, a committed setting must agree with the measurement
    // shadows that already existed in the previous cycle.
    always @(posedge clk)
        if (pv && armed && !pending)
            assert (applied_high_time == $past(reference_high));
endmodule

module segmented_bus_switch #(
    parameter PORTS = 2,
    parameter DATA_BITS = 64
) (
    input  wire                             clk,
    input  wire [PORTS-1:0]                 in_valid,
    output reg  [PORTS-1:0]                 in_ready,
    input  wire [PORTS*PORTS-1:0]           in_request,
    input  wire [PORTS*DATA_BITS-1:0]       in_data,
    output wire [PORTS-1:0]                 out_valid,
    input  wire [PORTS-1:0]                 out_ready,
    output wire [PORTS*DATA_BITS-1:0]       out_data,
    input  wire                             q_open,
    input  wire                             r_close
);
    // One holding slot per bus output: two stored words by default.
    reg [DATA_BITS-1:0] slot_data [0:PORTS-1];
    reg [63:0] slot_live [0:PORTS-1];
    reg [63:0] resident [0:PORTS-1];
    reg [63:0] rr_in [0:PORTS-1];
    reg [63:0] rr_out [0:PORTS-1];
    reg [63:0] window;

    // Combinational allocator results, not pipeline state.
    reg [PORTS-1:0] first_valid;
    reg [63:0] first_choice [0:PORTS-1];
    reg [PORTS-1:0] push;
    reg [63:0] winner [0:PORTS-1];
    wire [PORTS-1:0] pop;
    wire [PORTS-1:0] input_fire;
    assign input_fire = in_valid & in_ready;

    integer i;
    integer o;
    integer k;
    integer candidate;
    always @(*) begin
        first_valid = {PORTS{1'b0}};
        push = {PORTS{1'b0}};
        in_ready = {PORTS{1'b0}};
        candidate = 0;
        for (i = 0; i < PORTS; i = i + 1) begin
            first_choice[i] = 64'd0;
            winner[i] = 64'd0;
        end

        // Stage one: each input chooses one requested output.
        for (i = 0; i < PORTS; i = i + 1) begin
            for (k = 0; k < PORTS; k = k + 1) begin
                candidate = (rr_in[i] + k) % PORTS;
                if (!first_valid[i] && in_valid[i] &&
                    in_request[i*PORTS + candidate]) begin
                    first_valid[i] = 1'b1;
                    first_choice[i] = candidate;
                end
            end
        end

        // Stage two: each available output chooses one proposing input.
        for (o = 0; o < PORTS; o = o + 1) begin
            for (k = 0; k < PORTS; k = k + 1) begin
                candidate = (rr_out[o] + k) % PORTS;
                if (!push[o] &&
                    ((slot_live[o] == 64'd0) || out_ready[o]) &&
                    first_valid[candidate] &&
                    (first_choice[candidate] == o)) begin
                    push[o] = 1'b1;
                    winner[o] = candidate;
                    in_ready[candidate] = 1'b1;
                end
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < PORTS; g = g + 1) begin : channels
            assign out_valid[g] = (slot_live[g] != 64'd0);
            assign out_data[g*DATA_BITS +: DATA_BITS] = slot_data[g];
            assign pop[g] = out_valid[g] && out_ready[g];

            initial begin
                slot_data[g] = {DATA_BITS{1'b0}};
                slot_live[g] = 64'd0;
                resident[g] = 64'd0;
                rr_in[g] = 64'd0;
                rr_out[g] = 64'd0;
            end

            always @(posedge clk) begin
                if (input_fire[g]) begin
                    if (first_choice[g] == (PORTS - 64'd1))
                        rr_in[g] <= 64'd0;
                    else
                        rr_in[g] <= first_choice[g] + 64'd1;
                end

                if (push[g]) begin
                    if (winner[g] == (PORTS - 64'd1))
                        rr_out[g] <= 64'd0;
                    else
                        rr_out[g] <= winner[g] + 64'd1;
                    slot_data[g] <= in_data[winner[g]*DATA_BITS +: DATA_BITS];
                    slot_live[g] <= 64'd1;
                end else if (pop[g]) begin
                    slot_live[g] <= 64'd0;
                end

                case ({push[g], pop[g]})
                    2'b10: resident[g] <= resident[g] + 64'd1;
                    2'b01: resident[g] <= resident[g] - 64'd1;
                    default: resident[g] <= resident[g];
                endcase
            end
        end
    endgenerate

    // Q and R are command events on accepted input transactions.
    // Closing takes priority when both command bits accompany a transfer.
    initial window = 64'd0;
    always @(posedge clk) begin
        if (|input_fire) begin
            if (r_close)
                window <= 64'd0;
            else if (q_open)
                window <= 64'd1;
        end
    end

    // With in_valid and out_ready both zero, every state register holds.
    // A blocked output retains both its valid indication and its data.
    always @(posedge clk) begin
        if (window == 64'd1) begin
            assert (resident[0] <= 64'd1);
            assert (resident[1] <= 64'd1);
        end
    end
endmodule

module tdm_tunnel_demux #(
    parameter integer CHANNELS = 32'd16,
    parameter integer DATA_W = 32'd32
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_ce,
    input  wire i_valid,
    output wire i_ready,
    input  wire i_frame_sync,
    input  wire i_rekey,
    input  wire [DATA_W-1:0] i_data,
    output wire [CHANNELS*DATA_W-1:0] o_channels,
    output reg frame_done
);
    localparam [31:0] WAIT_SYNC = 32'd0;
    localparam [31:0] ARMED     = 32'd1;
    localparam [31:0] STREAMING = 32'd2;
    localparam [31:0] COMPLETE  = 32'd3;
    localparam [31:0] LAST_SLOT = CHANNELS - 32'd1;

    reg [31:0] phase;
    reg [31:0] slot;
    reg sync_seen;
    reg start_seen;
    reg before_rekey;
    reg [DATA_W-1:0] channel_data [0:CHANNELS-1];

    // A sync token arms a frame; subsequent data tokens occupy its slots.
    // Unsynchronized data and data following a complete frame are backpressured.
    // An accepted sync token explicitly starts or restarts frame assembly.
    assign i_ready = i_ce &&
                     (i_frame_sync || phase == ARMED || phase == STREAMING);
    wire take_input = i_valid && i_ready;

    initial begin
        phase = WAIT_SYNC;
        slot = 32'd0;
        sync_seen = 1'b0;
        start_seen = 1'b0;
        frame_done = 1'b0;
        before_rekey = 1'b1;
    end

    // Each channel retains the most recently accepted word for its slot.
    genvar g;
    generate
        for (g = 32'd0; g < CHANNELS; g = g + 32'd1) begin : channel_bank
            localparam [31:0] CHANNEL_INDEX = g;
            assign o_channels[g*DATA_W +: DATA_W] = channel_data[g];
            initial channel_data[g] = {DATA_W{1'b0}};
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    channel_data[g] <= {DATA_W{1'b0}};
                else if (take_input && !i_frame_sync &&
                         (phase == ARMED || phase == STREAMING) &&
                         slot == CHANNEL_INDEX)
                    channel_data[g] <= i_data;
            end
        end
    endgenerate

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase <= WAIT_SYNC;
            slot <= 32'd0;
            sync_seen <= 1'b0;
            start_seen <= 1'b0;
            frame_done <= 1'b0;
            before_rekey <= 1'b1;
        end else if (take_input) begin
            // The first accepted rekey event permanently ends this scope.
            if (i_rekey)
                before_rekey <= 1'b0;

            if (i_frame_sync) begin
                phase <= ARMED;
                slot <= 32'd0;
                sync_seen <= 1'b1;
                start_seen <= 1'b0;
                frame_done <= 1'b0;
            end else begin
                case (phase)
                    ARMED: begin
                        start_seen <= 1'b1;
                        if (LAST_SLOT == 32'd0) begin
                            phase <= COMPLETE;
                            slot <= 32'd0;
                            frame_done <= 1'b1;
                        end else begin
                            phase <= STREAMING;
                            slot <= 32'd1;
                        end
                    end
                    STREAMING: begin
                        if (slot == LAST_SLOT) begin
                            phase <= COMPLETE;
                            slot <= 32'd0;
                            frame_done <= 1'b1;
                        end else begin
                            slot <= slot + 32'd1;
                        end
                    end
                    default: begin end
                endcase
            end
        end
    end

    // Chain precedence, before the first accepted rekey:
    // starting slot delivery requires an earlier frame-arm token;
    // completing the frame requires an earlier delivery start.
    always @(posedge clk) begin
        if (before_rekey && start_seen)
            assert (sync_seen);
        if (before_rekey && frame_done)
            assert (start_seen);
    end
endmodule

module mm_tolerance_compare #(
    parameter integer DATA_WIDTH = 32
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire epsilon_we,
    input wire [DATA_WIDTH-1:0] epsilon_wdata,
    input wire compare_req,
    input wire [DATA_WIDTH-1:0] value_a,
    input wire [DATA_WIDTH-1:0] value_b,
    output reg pending,
    output reg within_tolerance
);
    localparam [DATA_WIDTH-1:0] ZERO = {DATA_WIDTH{1'b0}};
    localparam [DATA_WIDTH-1:0] ONE = {{(DATA_WIDTH-1){1'b0}}, 1'b1};
    localparam [DATA_WIDTH-1:0] BUDGET = DATA_WIDTH;

    reg [DATA_WIDTH-1:0] epsilon;
    reg [DATA_WIDTH-1:0] difference_work;
    reg [DATA_WIDTH-1:0] epsilon_work;
    reg [DATA_WIDTH-1:0] remaining;

    initial begin
        epsilon = ZERO;
        difference_work = ZERO;
        epsilon_work = ZERO;
        remaining = ZERO;
        pending = 1'b0;
        within_tolerance = 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            epsilon <= ZERO;
            difference_work <= ZERO;
            epsilon_work <= ZERO;
            remaining <= ZERO;
            pending <= 1'b0;
            within_tolerance <= 1'b1;
        end else if (i_ce) begin
            if (!pending) begin
                // Configuration writes take priority over accepting a request.
                if (epsilon_we) begin
                    epsilon <= epsilon_wdata;
                end else if (compare_req) begin
                    difference_work <= (value_a >= value_b)
                                     ? (value_a - value_b)
                                     : (value_b - value_a);
                    epsilon_work <= epsilon;
                    remaining <= BUDGET;
                    pending <= 1'b1;
                    within_tolerance <= 1'b1;
                end
            end else begin
                // Scan from least to most significant bit. Each unequal pair
                // overrides the result from all less significant pairs.
                if (difference_work[0] != epsilon_work[0])
                    within_tolerance <= epsilon_work[0];

                difference_work <= difference_work >> ONE;
                epsilon_work <= epsilon_work >> ONE;

                if (((difference_work >> ONE) == ZERO) &&
                    ((epsilon_work >> ONE) == ZERO)) begin
                    pending <= 1'b0;
                    remaining <= ZERO;
                end else begin
                    remaining <= remaining - ONE;
                end
            end
        end
    end

    // The enabled-cycle completion budget must not expire while outstanding.
    assert property (!pending || (remaining != ZERO));
endmodule

module completion_ring_writer #(
    parameter integer ENTRIES = 16,
    parameter [15:0] BASE_ADDR = 16'h1000,
    parameter [15:0] RECORD_BYTES = 16'd4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        transfer_done,
    input  wire [15:0] transfer_status,
    input  wire [15:0] transfer_length,
    input  wire [15:0] host_read_index,
    output wire [15:0] host_read_status,
    output wire [15:0] host_read_length,
    output reg         host_write_valid,
    output reg  [15:0] host_write_address,
    output reg  [15:0] host_write_status,
    output reg  [15:0] host_write_length,
    output reg         host_success,
    output reg         host_fault
);
    localparam [15:0] RING_CAPACITY = ENTRIES;

    reg [15:0] ring_base;
    reg [15:0] ring_size;
    reg [15:0] producer_index;
    reg [15:0] ring_status [0:ENTRIES-1];
    reg [15:0] ring_length [0:ENTRIES-1];

    reg        pending_valid;
    reg [15:0] pending_status;
    reg [15:0] pending_length;
    reg        pending_success;

    initial begin
        ring_base = BASE_ADDR;
        ring_size = RING_CAPACITY;
        producer_index = 16'd0;
        pending_valid = 1'b0;
        pending_status = 16'h0000;
        pending_length = 16'd0;
        pending_success = 1'b1;
        host_write_valid = 1'b0;
        host_write_address = 16'd0;
        host_write_status = 16'h0000;
        host_write_length = 16'd0;
        host_success = 1'b0;
        host_fault = 1'b0;
    end

    genvar slot;
    generate
        for (slot = 32'd0; slot < ENTRIES; slot = slot + 32'd1) begin : init_slots
            initial begin
                ring_status[slot] = 16'h0000;
                ring_length[slot] = 16'd0;
            end
        end
    endgenerate

    assign host_read_status = (host_read_index < ring_size)
                            ? ring_status[host_read_index] : 16'h0000;
    assign host_read_length = (host_read_index < ring_size)
                            ? ring_length[host_read_index] : 16'd0;

    // Each enabled cycle retires the old pending record and can capture a new one.
    // There is no ready/acknowledge handshake.
    always @(posedge clk) begin
        if (i_ce) begin
            host_write_valid <= pending_valid;
            if (pending_valid) begin
                ring_status[producer_index] <= pending_status;
                ring_length[producer_index] <= pending_length;
                host_write_address <= ring_base + producer_index * RECORD_BYTES;
                host_write_status <= pending_status;
                host_write_length <= pending_length;

                // Success uses the capture-stage predecode; fault uses the status word.
                host_success <= pending_success;
                host_fault <= (pending_status != 16'h0000);

                if (producer_index == ring_size - 16'd1)
                    producer_index <= 16'd0;
                else
                    producer_index <= producer_index + 16'd1;
            end

            pending_valid <= transfer_done;
            if (transfer_done) begin
                pending_status <= transfer_status;
                pending_length <= transfer_length;
                pending_success <= (transfer_status == 16'h0000);
            end
        end
    end

    always @(posedge clk)
        if (host_write_valid)
            assert (!(host_success && host_fault));
endmodule

module skewed_cache_deadline #(
    parameter [31:0] ENTRIES = 32'd4,
    parameter integer WORD_W = 32
) (
    input wire clk,
    input wire i_ce,
    input wire req_valid,
    output wire req_ready,
    input wire [1:0] req_cmd,
    input wire req_way,
    input wire [WORD_W-1:0] req_addr,
    input wire [WORD_W-1:0] req_data,
    input wire [WORD_W-1:0] req_hash0,
    input wire [WORD_W-1:0] req_hash1,
    output reg complete,
    output reg result_hit,
    output reg [WORD_W-1:0] result_data
);
    // Commands: 0 configures hashes, 1 fills, 2 looks up, 3 invalidates.
    // A lookup probes the two skewed ways in at most two enabled cycles.
    reg [WORD_W-1:0] hash_cfg0;
    reg [WORD_W-1:0] hash_cfg1;
    reg [ENTRIES-1:0] valid0;
    reg [ENTRIES-1:0] valid1;
    reg [WORD_W-1:0] tag0 [0:ENTRIES-1];
    reg [WORD_W-1:0] tag1 [0:ENTRIES-1];
    reg [WORD_W-1:0] data0 [0:ENTRIES-1];
    reg [WORD_W-1:0] data1 [0:ENTRIES-1];

    reg pending;
    reg probe_way;
    reg [31:0] countdown;
    reg [WORD_W-1:0] lookup_addr;
    reg past_valid;

    wire [31:0] fill_index0 = (req_addr ^ hash_cfg0) % ENTRIES;
    wire [31:0] fill_index1 = ((req_addr >> 32'd2) ^ req_addr ^ hash_cfg1) % ENTRIES;
    wire [31:0] lookup_index0 = (lookup_addr ^ hash_cfg0) % ENTRIES;
    wire [31:0] lookup_index1 = ((lookup_addr >> 32'd2) ^ lookup_addr ^ hash_cfg1) % ENTRIES;
    wire hit0 = valid0[lookup_index0] && tag0[lookup_index0] == lookup_addr;
    wire hit1 = valid1[lookup_index1] && tag1[lookup_index1] == lookup_addr;
    wire [ENTRIES-1:0] placement0_ok;
    wire [ENTRIES-1:0] placement1_ok;

    assign req_ready = i_ce && !pending;

    initial begin
        hash_cfg0 = {WORD_W{1'b0}};
        hash_cfg1 = {WORD_W{1'b0}};
        valid0 = {ENTRIES{1'b0}};
        valid1 = {ENTRIES{1'b0}};
        pending = 1'b0;
        probe_way = 1'b0;
        countdown = 32'd0;
        lookup_addr = {WORD_W{1'b0}};
        past_valid = 1'b0;
        complete = 1'b0;
        result_hit = 1'b0;
        result_data = {WORD_W{1'b0}};
    end

    generate
        for (genvar g = 0; g < ENTRIES; g = g + 1) begin : cache_rows
            localparam [31:0] ROW = g;
            initial begin
                tag0[g] = {WORD_W{1'b0}};
                tag1[g] = {WORD_W{1'b0}};
                data0[g] = {WORD_W{1'b0}};
                data1[g] = {WORD_W{1'b0}};
            end
            assign placement0_ok[g] = !valid0[g] ||
                (((tag0[g] ^ hash_cfg0) % ENTRIES) == ROW);
            assign placement1_ok[g] = !valid1[g] ||
                ((((tag1[g] >> 32'd2) ^ tag1[g] ^ hash_cfg1) % ENTRIES) == ROW);
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            if (pending) begin
                countdown <= countdown - 32'd1;
                if (!probe_way) begin
                    if (hit0) begin
                        pending <= 1'b0;
                        countdown <= 32'd0;
                        complete <= 1'b1;
                        result_hit <= 1'b1;
                        result_data <= data0[lookup_index0];
                    end else begin
                        probe_way <= 1'b1;
                    end
                end else begin
                    pending <= 1'b0;
                    countdown <= 32'd0;
                    complete <= 1'b1;
                    result_hit <= hit1;
                    if (hit1)
                        result_data <= data1[lookup_index1];
                    else
                        result_data <= {WORD_W{1'b0}};
                end
            end else if (req_valid && req_ready) begin
                case (req_cmd)
                    2'd0: begin
                        hash_cfg0 <= req_hash0;
                        hash_cfg1 <= req_hash1;
                        valid0 <= {ENTRIES{1'b0}};
                        valid1 <= {ENTRIES{1'b0}};
                    end
                    2'd1: begin
                        if (!req_way) begin
                            valid0[fill_index0] <= 1'b1;
                            tag0[fill_index0] <= req_addr;
                            data0[fill_index0] <= req_data;
                        end else begin
                            valid1[fill_index1] <= 1'b1;
                            tag1[fill_index1] <= req_addr;
                            data1[fill_index1] <= req_data;
                        end
                    end
                    2'd2: begin
                        lookup_addr <= req_addr;
                        pending <= 1'b1;
                        probe_way <= 1'b0;
                        countdown <= 32'd2;
                        complete <= 1'b0;
                    end
                    2'd3: begin
                        valid0 <= {ENTRIES{1'b0}};
                        valid1 <= {ENTRIES{1'b0}};
                    end
                endcase
            end
        end
    end

    // While outstanding remains unchanged, expiration must not change either.
    always @(posedge clk) begin
        if (past_valid && pending && $stable(pending))
            assert ($stable(countdown == 32'd0));
    end
endmodule

module accelerator_power_stagger #(
    parameter integer SEGMENTS = 32'd32,
    parameter [15:0] STEP_DELAY = 16'd3
) (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,
    input  wire request_on,
    output reg  [SEGMENTS-1:0] switch_enable,
    output wire arm_on,
    output wire start_on,
    output wire finish_on
);
    // SEGMENTS is between 4 and 65535. The packed vector contains
    // one control bit per switch segment, rather than datapath words.
    localparam [15:0] SEGMENT_COUNT = SEGMENTS;
    localparam [15:0] START_INDEX = SEGMENTS / 32'd2;
    localparam [15:0] OFF      = 16'd0;
    localparam [15:0] ARMED    = 16'd1;
    localparam [15:0] STARTED  = 16'd2;
    localparam [15:0] FINISHED = 16'd3;

    reg [15:0] phase;
    reg [15:0] segment_index;
    reg [15:0] delay_count;

    // Ordered supply milestones: front-end arm, compute start,
    // and completion of the final power-switch group.
    assign arm_on   = switch_enable[0];
    assign start_on = switch_enable[START_INDEX];
    assign finish_on = switch_enable[SEGMENTS-1];

    initial begin
        phase = OFF;
        segment_index = 16'd0;
        delay_count = 16'd0;
        switch_enable = {SEGMENTS{1'b0}};
    end

    always @(posedge clk) begin
        // Clock enable also gates the synchronous reset, so i_ce=0
        // leaves every state register unchanged.
        if (i_ce) begin
            if (rst) begin
                phase <= OFF;
                segment_index <= 16'd0;
                delay_count <= 16'd0;
                switch_enable <= {SEGMENTS{1'b0}};
            end else begin
                case (phase)
                    OFF: begin
                        if (request_on) begin
                            switch_enable <= {{(SEGMENTS-1){1'b0}}, 1'b1};
                            segment_index <= 16'd1;
                            delay_count <= STEP_DELAY;
                            phase <= ARMED;
                        end
                    end
                    ARMED, STARTED: begin
                        if (delay_count != 16'd0) begin
                            delay_count <= delay_count - 16'd1;
                        end else begin
                            switch_enable <= {switch_enable[SEGMENTS-2:0], 1'b1};
                            segment_index <= segment_index + 16'd1;
                            delay_count <= STEP_DELAY;
                            if (segment_index == SEGMENT_COUNT - 16'd1)
                                phase <= FINISHED;
                            else if (segment_index == START_INDEX)
                                phase <= STARTED;
                        end
                    end
                    FINISHED: begin
                        // Keep the powered domain enabled until reset.
                    end
                    default: begin
                        phase <= OFF;
                        segment_index <= 16'd0;
                        delay_count <= 16'd0;
                        switch_enable <= {SEGMENTS{1'b0}};
                    end
                endcase
            end
        end
    end

    // Global chain precedence: start requires arm; finish requires both.
    always @(posedge clk)
        if (start_on || finish_on)
            assert (arm_on && (!finish_on || start_on));
endmodule

module spectrum_alpha_blender #(
    parameter integer WORD_BITS = 64
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 i_request,
    input  wire                 i_retune,
    input  wire [WORD_BITS-1:0] i_foreground,
    input  wire [WORD_BITS-1:0] i_background,
    input  wire [WORD_BITS-1:0] i_alpha,
    output reg  [WORD_BITS-1:0] o_pixel
);
    localparam [WORD_BITS-1:0] ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] BLEND_STEPS = WORD_BITS;
    localparam [WORD_BITS-1:0] LAST_STEP = BLEND_STEPS - ONE;

    reg before_retune;
    reg pending;
    reg [WORD_BITS-1:0] phase;
    reg [WORD_BITS-1:0] deadline;
    reg [WORD_BITS-1:0] foreground;
    reg [WORD_BITS-1:0] background;
    reg [WORD_BITS-1:0] alpha_shift;
    reg [WORD_BITS-1:0] accumulator;

    wire [WORD_BITS-1:0] selected_pixel;
    wire [WORD_BITS-1:0] next_mix;

    assign selected_pixel = alpha_shift[0] ? foreground : background;
    // Overflow-free floor((accumulator + selected_pixel) / 2).
    assign next_mix = (accumulator & selected_pixel)
                    + ((accumulator ^ selected_pixel) >> ONE);

    initial begin
        before_retune = 1'b1;
        pending = 1'b0;
        phase = ZERO;
        deadline = ZERO;
        foreground = ZERO;
        background = ZERO;
        alpha_shift = ZERO;
        accumulator = ZERO;
        o_pixel = ZERO;
    end

    // A request is accepted when idle on an enabled edge. There is no
    // external handshake; requests received during a blend are ignored.
    // Processing alpha LSB-first implements the unsigned blend
    // floor(background + (foreground-background)*alpha/2**WORD_BITS)
    // without a double-width product. Completion takes WORD_BITS
    // enabled iterations after acceptance.
    always @(posedge clk) begin
        if (i_ce) begin
            // The first enabled retune permanently ends the checking scope.
            if (i_retune)
                before_retune <= 1'b0;

            if (!pending) begin
                if (i_request) begin
                    foreground <= i_foreground;
                    background <= i_background;
                    alpha_shift <= i_alpha;
                    accumulator <= i_background;
                    phase <= ZERO;
                    deadline <= BLEND_STEPS;
                    pending <= 1'b1;
                end
            end else begin
                accumulator <= next_mix;
                alpha_shift <= alpha_shift >> ONE;
                phase <= phase + ONE;
                deadline <= deadline - ONE;
                if (phase == LAST_STEP) begin
                    o_pixel <= next_mix;
                    pending <= 1'b0;
                end
            end
        end
    end

    // Before the first retune, an outstanding blend must not exhaust
    // its enabled-cycle completion budget.
    always @(posedge clk)
        assert (!before_retune || !pending || (deadline != ZERO));
endmodule

module memory_aux_spread_pwm #(
    parameter integer WORD_W = 16,
    parameter [WORD_W-1:0] NOMINAL_FLOOR = 16'd8,
    parameter [WORD_W-1:0] PROFILE_SPAN = 16'd7
) (
    input wire i_clk,
    input wire i_ce,
    input wire i_config,
    input wire [WORD_W-1:0] i_profile,
    input wire i_training_done,
    output wire o_aux_pwm
);
    localparam [WORD_W-1:0] PERIOD_LIMIT = NOMINAL_FLOOR + PROFILE_SPAN;
    localparam [WORD_W-1:0] MIN_PERIOD = NOMINAL_FLOOR - PROFILE_SPAN;
    localparam [WORD_W-1:0] MAX_COUNT = PERIOD_LIMIT - 16'd1;

    reg [WORD_W-1:0] period_counter;
    reg [WORD_W-1:0] base_period;
    reg [WORD_W-1:0] dither_depth;
    reg [WORD_W-1:0] lfsr;
    reg [WORD_W-1:0] active_period;
    reg before_training_done;

    wire [WORD_W-1:0] configured_base;
    wire [WORD_W-1:0] configured_depth;
    wire [WORD_W-1:0] configured_period;
    wire [WORD_W-1:0] lfsr_next;
    wire [WORD_W-1:0] next_period;

    assign configured_base = NOMINAL_FLOOR + (i_profile & PROFILE_SPAN);
    // Trade nominal period against the available positive dither headroom.
    assign configured_depth = PERIOD_LIMIT - configured_base;
    assign configured_period = lfsr[WORD_W-1]
        ? configured_base - (lfsr & configured_depth)
        : configured_base + (lfsr & configured_depth);

    assign lfsr_next = {lfsr[WORD_W-2:0],
        lfsr[WORD_W-1] ^ lfsr[WORD_W-3] ^
        lfsr[WORD_W-4] ^ lfsr[WORD_W-6]};
    assign next_period = lfsr_next[WORD_W-1]
        ? base_period - (lfsr_next & dither_depth)
        : base_period + (lfsr_next & dither_depth);

    initial begin
        period_counter = 16'd0;
        base_period = NOMINAL_FLOOR;
        dither_depth = PROFILE_SPAN;
        lfsr = 16'h0001;
        active_period = NOMINAL_FLOOR + (16'h0001 & PROFILE_SPAN);
        before_training_done = 1'b1;
    end

    always @(posedge i_clk) begin
        if (i_ce) begin
            // The scope ends permanently on the first enabled training event.
            if (i_training_done)
                before_training_done <= 1'b0;

            if (i_config) begin
                base_period <= configured_base;
                dither_depth <= configured_depth;
                active_period <= configured_period;
                period_counter <= 16'd0;
            end else if (period_counter == active_period - 16'd1) begin
                period_counter <= 16'd0;
                lfsr <= lfsr_next;
                active_period <= next_period;
            end else begin
                period_counter <= period_counter + 16'd1;
            end
        end
    end

    assign o_aux_pwm = period_counter < (active_period >> 16'd1);

    always @(posedge i_clk)
        assert (!before_training_done || (period_counter <= MAX_COUNT));
endmodule

module dma_first_fault_capture #(
    parameter integer WORD_W = 8,
    parameter integer CHANNELS = 8
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  ce,
    input  wire                  bus_error,
    input  wire                  descriptor_fault,
    input  wire                  alignment_fault,
    input  wire [WORD_W-1:0]     address_in,
    input  wire [WORD_W-1:0]     channel_in,
    input  wire                  report_req,
    input  wire                  recovery,
    output reg                   fault_valid,
    output reg  [WORD_W-1:0]     report_address,
    output reg  [WORD_W-1:0]     report_code,
    output reg  [WORD_W-1:0]     report_channel
);
    localparam [WORD_W-1:0] CODE_NONE = WORD_W'(8'h00);
    localparam [WORD_W-1:0] CODE_BUS = WORD_W'(8'h01);
    localparam [WORD_W-1:0] CODE_DESC = WORD_W'(8'h02);
    localparam [WORD_W-1:0] CODE_ALIGN = WORD_W'(8'h03);
    localparam [WORD_W-1:0] CHANNEL_LIMIT = WORD_W'(CHANNELS);

    reg [WORD_W-1:0] fault_address;
    reg [WORD_W-1:0] fault_code;
    reg [WORD_W-1:0] fault_channel;
    reg latched_bus;
    reg latched_desc;
    reg latched_align;
    reg before_recovery;
    reg pv;

    wire any_fault = bus_error || descriptor_fault || alignment_fault;
    wire [WORD_W-1:0] decoded_latched_code =
        latched_bus ? CODE_BUS :
        latched_desc ? CODE_DESC :
        latched_align ? CODE_ALIGN : CODE_NONE;

    initial begin
        fault_valid = 1'b0;
        fault_address = {WORD_W{1'b0}};
        fault_code = CODE_NONE;
        fault_channel = {WORD_W{1'b0}};
        latched_bus = 1'b0;
        latched_desc = 1'b0;
        latched_align = 1'b0;
        report_address = {WORD_W{1'b0}};
        report_code = CODE_NONE;
        report_channel = {WORD_W{1'b0}};
        before_recovery = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            fault_valid <= 1'b0;
            fault_address <= {WORD_W{1'b0}};
            fault_code <= CODE_NONE;
            fault_channel <= {WORD_W{1'b0}};
            latched_bus <= 1'b0;
            latched_desc <= 1'b0;
            latched_align <= 1'b0;
            report_address <= {WORD_W{1'b0}};
            report_code <= CODE_NONE;
            report_channel <= {WORD_W{1'b0}};
            before_recovery <= 1'b1;
            pv <= 1'b0;
        end else if (ce) begin
            pv <= 1'b1;

            // Recovery ends the observation scope permanently until reset.
            if (recovery) begin
                before_recovery <= 1'b0;
                fault_valid <= 1'b0;
                fault_address <= {WORD_W{1'b0}};
                fault_code <= CODE_NONE;
                fault_channel <= {WORD_W{1'b0}};
                latched_bus <= 1'b0;
                latched_desc <= 1'b0;
                latched_align <= 1'b0;
            end else if (!fault_valid && any_fault &&
                         (channel_in < CHANNEL_LIMIT)) begin
                // Preserve the first fault, including simultaneous raw causes.
                fault_valid <= 1'b1;
                fault_address <= address_in;
                fault_channel <= channel_in;
                latched_bus <= bus_error;
                latched_desc <= descriptor_fault;
                latched_align <= alignment_fault;
                fault_code <= bus_error ? CODE_BUS :
                              descriptor_fault ? CODE_DESC : CODE_ALIGN;
            end

            // The reporting formatter encodes the retained diagnostic causes.
            if (report_req && fault_valid) begin
                report_address <= fault_address;
                report_channel <= fault_channel;
                report_code <= decoded_latched_code;
            end
        end
    end

    always @(posedge clk) begin
        if (pv && before_recovery &&
            $past(ce && report_req && fault_valid))
            assert ((report_address == $past(fault_address)) &&
                    (report_code == $past(fault_code)) &&
                    (report_channel == $past(fault_channel)));
    end
endmodule

module dead_block_predictor_window #(
    parameter integer DATA_W = 32,
    parameter integer ENTRIES = 16
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_ce,
    input  wire                  i_scope_open,
    input  wire                  i_scope_close,
    input  wire                  i_request,
    input  wire [DATA_W-1:0]     i_request_line,
    input  wire                  i_fill,
    input  wire [DATA_W-1:0]     i_fill_line,
    input  wire [DATA_W-1:0]     i_fill_signature,
    input  wire                  i_train,
    input  wire [DATA_W-1:0]     i_train_line,
    input  wire                  i_was_dead,
    output wire                  o_ready,
    output reg                   o_response,
    output reg                   o_predicted_dead,
    output reg  [DATA_W-1:0]     o_confidence
);
    // ENTRIES is a power of two; addresses select its low index bits.
    localparam integer INDEX_W = $clog2(ENTRIES);
    localparam [DATA_W-1:0] C_ZERO  = DATA_W'(0);
    localparam [DATA_W-1:0] C_ONE   = DATA_W'(1);
    localparam [DATA_W-1:0] C_TWO   = DATA_W'(2);
    localparam [DATA_W-1:0] C_THREE = DATA_W'(3);
    localparam [DATA_W-1:0] C_FOUR  = DATA_W'(4);
    localparam [DATA_W-1:0] C_MAX   = {DATA_W{1'b1}};

    reg [DATA_W-1:0] confidence [0:ENTRIES-1];
    reg [DATA_W-1:0] line_signature [0:ENTRIES-1];
    reg window;
    reg outstanding;
    reg [DATA_W-1:0] phase;
    reg [DATA_W-1:0] deadline;
    reg [DATA_W-1:0] saved_line;
    reg [DATA_W-1:0] read_signature;
    reg [DATA_W-1:0] sampled_confidence;

    wire [DATA_W-1:0] training_signature;
    wire [INDEX_W-1:0] training_index;
    assign training_signature = line_signature[i_train_line[INDEX_W-1:0]];
    assign training_index = training_signature[INDEX_W-1:0];
    assign o_ready = window && !outstanding && !i_scope_close;

    integer n;
    initial begin
        window = 1'b0;
        outstanding = 1'b0;
        phase = C_ZERO;
        deadline = C_ZERO;
        saved_line = C_ZERO;
        read_signature = C_ZERO;
        sampled_confidence = C_ZERO;
        o_response = 1'b0;
        o_predicted_dead = 1'b0;
        o_confidence = C_ZERO;
        for (n = 0; n < ENTRIES; n = n + 1) begin
            confidence[n] = C_ZERO;
            line_signature[n] = C_ZERO;
        end
    end

    integer r;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            window <= 1'b0;
            outstanding <= 1'b0;
            phase <= C_ZERO;
            deadline <= C_ZERO;
            saved_line <= C_ZERO;
            read_signature <= C_ZERO;
            sampled_confidence <= C_ZERO;
            o_response <= 1'b0;
            o_predicted_dead <= 1'b0;
            o_confidence <= C_ZERO;
            for (r = 0; r < ENTRIES; r = r + 1) begin
                confidence[r] <= C_ZERO;
                line_signature[r] <= C_ZERO;
            end
        end else if (i_ce) begin
            if (i_scope_close)
                window <= 1'b0;
            else if (i_scope_open)
                window <= 1'b1;

            if (i_fill)
                line_signature[i_fill_line[INDEX_W-1:0]] <= i_fill_signature;

            // Train the signature-indexed saturating confidence counter.
            if (i_train) begin
                if (i_was_dead) begin
                    if (confidence[training_index] != C_MAX)
                        confidence[training_index] <= confidence[training_index] + C_ONE;
                end else begin
                    if (confidence[training_index] != C_ZERO)
                        confidence[training_index] <= confidence[training_index] - C_ONE;
                end
            end

            o_response <= 1'b0;
            if (!outstanding) begin
                if (i_request && o_ready) begin
                    saved_line <= i_request_line;
                    outstanding <= 1'b1;
                    phase <= C_ONE;
                    deadline <= C_THREE;
                end
            end else begin
                deadline <= deadline - C_ONE;
                case (phase)
                    C_ONE: begin
                        // First enabled cycle: fetch the line's signature.
                        read_signature <= line_signature[saved_line[INDEX_W-1:0]];
                        phase <= C_TWO;
                    end
                    C_TWO: begin
                        // Second enabled cycle: consult its confidence entry.
                        sampled_confidence <= confidence[read_signature[INDEX_W-1:0]];
                        phase <= C_THREE;
                    end
                    C_THREE: begin
                        // Third enabled cycle: return the prediction.
                        o_confidence <= sampled_confidence;
                        o_predicted_dead <= sampled_confidence[DATA_W-1];
                        o_response <= 1'b1;
                        outstanding <= 1'b0;
                        phase <= C_ZERO;
                        deadline <= C_ZERO;
                    end
                    default: begin
                        outstanding <= 1'b0;
                        phase <= C_ZERO;
                        deadline <= C_ZERO;
                    end
                endcase
            end
        end
    end

    // Within the latched scope, an outstanding lookup must not expire.
    // The service budget is three enabled cycles after acceptance.
    assert property (!(window && outstanding) || (deadline != C_ZERO));
endmodule

module probe_ring_monitor #(
    parameter integer WORD_W = 64
) (
    input  wire              clk,
    input  wire              i_ce,
    input  wire              i_begin_window,
    input  wire              i_end_window,
    output wire [WORD_W-1:0]  o_probe_word,
    output wire              o_carry
);
    localparam [WORD_W-1:0] MARKERS = 64'd2;

    reg [WORD_W-1:0] probe_word;
    reg             carry;
    reg [WORD_W-1:0] in_word_count;
    reg             window;

    initial begin
        probe_word   = 64'h0000000000000003;
        carry        = 1'b0;
        in_word_count = MARKERS;
        window       = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Rotate two probe markers through the word and extra carry stage.
            probe_word <= {probe_word[WORD_W-2:0], carry};
            carry      <= probe_word[WORD_W-1];

            // Account for the marker entering and the marker leaving the word.
            in_word_count <= in_word_count
                           + {{(WORD_W-1){1'b0}}, carry}
                           - {{(WORD_W-1){1'b0}}, probe_word[WORD_W-1]};

            // End takes priority when both window events occur together.
            if (i_end_window)
                window <= 1'b0;
            else if (i_begin_window)
                window <= 1'b1;
        end
    end

    assign o_probe_word = probe_word;
    assign o_carry = carry;

    always @(*) begin
        if (window)
            assert (in_word_count <= MARKERS);
    end
endmodule

module pixel_dot_accumulator #(
    parameter integer LANES = 16,
    parameter integer WORD_W = 64
) (
    input wire clk,
    input wire ce,
    input wire end_frame,
    input wire [(LANES*WORD_W)-1:0] shade_operands,
    input wire [(LANES*WORD_W)-1:0] texture_operands,
    output wire [WORD_W-1:0] accumulated_value
);
    // Products and additions use fixed-width modular arithmetic.
    reg [WORD_W-1:0] products [0:LANES-1];
    wire [WORD_W-1:0] incoming_product [0:LANES-1];
    wire [WORD_W-1:0] adder_tree [1:(2*LANES)-1];
    wire [LANES-1:0] incoming_nonzero;
    wire [LANES-1:0] staged_nonzero;
    wire pending_nonzero;

    reg [WORD_W-1:0] running_sum;
    reg seen_nonzero_issue;
    reg before_end;
    reg past_valid;

    initial begin
        running_sum = {WORD_W{1'b0}};
        seen_nonzero_issue = 1'b0;
        before_end = 1'b1;
        past_valid = 1'b0;
    end

    genvar lane;
    generate
        for (lane = 0; lane < LANES; lane = lane + 1) begin : lanes
            assign incoming_product[lane] =
                shade_operands[lane*WORD_W +: WORD_W] *
                texture_operands[lane*WORD_W +: WORD_W];
            assign incoming_nonzero[lane] =
                incoming_product[lane] != {WORD_W{1'b0}};
            assign staged_nonzero[lane] =
                products[lane] != {WORD_W{1'b0}};
            assign adder_tree[LANES+lane] = products[lane];

            initial products[lane] = {WORD_W{1'b0}};
            always @(posedge clk) begin
                if (ce)
                    products[lane] <= incoming_product[lane];
            end
        end
    endgenerate

    genvar node;
    generate
        for (node = 1; node < LANES; node = node + 1) begin : reduction_tree
            assign adder_tree[node] =
                adder_tree[2*node] + adder_tree[2*node+1];
        end
    endgenerate

    assign pending_nonzero = |staged_nonzero;
    assign accumulated_value = running_sum;

    always @(posedge clk) begin
        if (ce) begin
            running_sum <= running_sum + adder_tree[1];
            // History of a nonzero product entering the preceding stage.
            seen_nonzero_issue <= seen_nonzero_issue || (|incoming_nonzero);
            past_valid <= 1'b1;
            if (end_frame)
                before_end <= 1'b0;
        end
    end

    // Before the first frame-end event, a rising nonzero accumulated value
    // must be preceded by an issued nonzero product.
    always @(posedge clk) begin
        if (past_valid && before_end &&
            $rose(running_sum != {WORD_W{1'b0}}))
            assert (seen_nonzero_issue);
    end
endmodule

module forwarded_sample_buffer #(
    parameter integer unsigned DEPTH = 32'd24,
    parameter integer unsigned DATA_WIDTH = 32'd32,
    parameter integer unsigned INDEX_WIDTH = 32'd32
) (
    input  wire clk,
    input  wire forwarded_clk,
    input  wire i_ce,
    input  wire in_valid,
    output wire in_ready,
    input  wire [DATA_WIDTH-32'd1:0] in_data,
    output wire out_valid,
    input  wire out_ready,
    output logic [DATA_WIDTH-32'd1:0] out_data
);
    typedef enum logic [1:0] {
        RX_IDLE  = 2'd0,
        RX_STORE = 2'd1,
        RX_WAIT  = 2'd2
    } rx_state_t;

    typedef enum logic [1:0] {
        TX_IDLE  = 2'd0,
        TX_VALID = 2'd1
    } tx_state_t;

    localparam logic [INDEX_WIDTH-32'd1:0] LAST_INDEX =
        INDEX_WIDTH'(DEPTH - 32'd1);

    rx_state_t rx_state;
    tx_state_t tx_state;
    logic [DATA_WIDTH-32'd1:0] capture_data;
    logic [DATA_WIDTH-32'd1:0] sample_buffer [0:DEPTH-32'd1];
    logic [INDEX_WIDTH-32'd1:0] write_index;
    logic [INDEX_WIDTH-32'd1:0] read_index;
    logic request_toggle;
    logic acknowledge_toggle;
    logic past_valid;

    wire [INDEX_WIDTH-32'd1:0] next_write_index =
        (write_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        write_index + INDEX_WIDTH'(32'd1);
    wire [INDEX_WIDTH-32'd1:0] next_read_index =
        (read_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        read_index + INDEX_WIDTH'(32'd1);

    assign in_ready = i_ce && (rx_state == RX_IDLE);
    assign out_valid = (tx_state == TX_VALID);

    initial begin
        rx_state = RX_IDLE;
        tx_state = TX_IDLE;
        capture_data = {DATA_WIDTH{1'b0}};
        out_data = {DATA_WIDTH{1'b0}};
        write_index = {INDEX_WIDTH{1'b0}};
        read_index = {INDEX_WIDTH{1'b0}};
        request_toggle = 1'b0;
        acknowledge_toggle = 1'b0;
        past_valid = 1'b0;
        for (integer k = 32'd0; k < DEPTH; k = k + 32'd1)
            sample_buffer[k] = {DATA_WIDTH{1'b0}};
    end

    // Forwarded-clock capture followed by a write into the rotating buffer.
    // One outstanding transfer keeps the bundled sample and its slot stable
    // until the local-clock consumer acknowledges it.
    always @(posedge forwarded_clk) begin
        if (i_ce) begin
            case (rx_state)
                RX_IDLE: begin
                    if (in_valid && in_ready) begin
                        capture_data <= in_data;
                        rx_state <= RX_STORE;
                    end
                end
                RX_STORE: begin
                    sample_buffer[write_index] <= capture_data;
                    request_toggle <= !request_toggle;
                    rx_state <= RX_WAIT;
                end
                RX_WAIT: begin
                    if (request_toggle == acknowledge_toggle) begin
                        write_index <= next_write_index;
                        rx_state <= RX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    // The other port of the buffer is read in the local-clock domain.
    // Output data and valid remain held throughout back-pressure.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            case (tx_state)
                TX_IDLE: begin
                    if (request_toggle != acknowledge_toggle) begin
                        out_data <= sample_buffer[read_index];
                        tx_state <= TX_VALID;
                    end
                end
                TX_VALID: begin
                    if (out_valid && out_ready) begin
                        acknowledge_toggle <= request_toggle;
                        read_index <= next_read_index;
                        tx_state <= TX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    always @(posedge clk) begin
        if (past_valid && $rose(out_valid))
            assert (out_data == capture_data);
    end
endmodule

module soc_edf_arbiter #(
    parameter integer REQUESTERS = 32'd16,
    parameter [7:0] INITIAL_PERIOD = 8'd16
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire [REQUESTERS-1:0]  i_request,
    input  wire                  cfg_load,
    input  wire [7:0]            cfg_index,
    input  wire [7:0]            cfg_period,
    output reg  [REQUESTERS-1:0]  grant
);
    reg [REQUESTERS-1:0] pending;
    reg [REQUESTERS-1:0] request_seen;
    reg armed;

    reg [7:0] period   [0:REQUESTERS-1];
    reg [7:0] deadline [0:REQUESTERS-1];

    reg [REQUESTERS-1:0] winner;
    reg [7:0] best_deadline;
    reg found;
    integer k;

    initial begin
        pending      = {REQUESTERS{1'b0}};
        request_seen = {REQUESTERS{1'b0}};
        grant        = {REQUESTERS{1'b0}};
        armed        = 1'b0;
    end

    // Choose the nearest pending deadline; lower indices win ties.
    always @(*) begin
        winner = {REQUESTERS{1'b0}};
        best_deadline = 8'hff;
        found = 1'b0;
        for (k = 32'd0; k < REQUESTERS; k = k + 32'd1) begin
            if (pending[k] && (!found || deadline[k] < best_deadline)) begin
                winner = {REQUESTERS{1'b0}};
                winner[k] = 1'b1;
                best_deadline = deadline[k];
                found = 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // A fresh request may replace a request served on this edge.
            pending <= (pending & ~winner) | i_request;
            request_seen <= request_seen | i_request;
            grant <= winner;

            // Q: the first accepted period-programming command.
            if (cfg_load && cfg_index < REQUESTERS)
                armed <= 1'b1;
        end
    end

    genvar n;
    generate
        for (n = 32'd0; n < REQUESTERS; n = n + 32'd1) begin : channel
            initial begin
                period[n] = INITIAL_PERIOD;
                deadline[n] = 8'd0;
            end

            always @(posedge clk) begin
                if (i_ce) begin
                    if (cfg_load && cfg_index == n)
                        period[n] <= cfg_period;

                    // Concurrent programming affects subsequent reloads.
                    if (winner[n])
                        deadline[n] <= period[n];
                    else if (deadline[n] != 8'd0)
                        deadline[n] <= deadline[n] - 8'd1;
                end
            end
        end
    endgenerate

    // After configuration has occurred, every observed grant must have
    // a preceding request recorded in the sticky request-history shadow.
    always @(*) begin
        if (armed && grant != {REQUESTERS{1'b0}})
            assert ((grant & ~request_seen) == {REQUESTERS{1'b0}});
    end
endmodule

module fft_twiddle_stream #(
    parameter integer WORD_W = 128,
    parameter integer ROM_DEPTH = 16,
    parameter integer STAGES = $clog2(ROM_DEPTH) + 1
) (
    input  wire clk,
    input  wire i_job_valid,
    output wire o_job_ready,
    output wire o_coeff_valid,
    input  wire i_coeff_ready,
    output wire [WORD_W-1:0] o_coeff_data,
    output wire [$clog2(ROM_DEPTH)-1:0] o_coeff_addr,
    output wire o_start,
    output wire o_finish
);
    localparam integer INDEX_W = $clog2(ROM_DEPTH);
    localparam integer STAGE_W = $clog2(STAGES);
    localparam integer COUNT_W = $clog2(ROM_DEPTH + 1);
    localparam [1:0] PH_IDLE = 2'd0;
    localparam [1:0] PH_ARMED = 2'd1;
    localparam [1:0] PH_RUN = 2'd2;
    localparam [STAGE_W-1:0] LAST_STAGE = STAGE_W'(STAGES - 1);
    localparam [INDEX_W-1:0] LAST_INDEX = INDEX_W'(ROM_DEPTH - 1);
    localparam [COUNT_W-1:0] FULL_COUNT = COUNT_W'(ROM_DEPTH);
    localparam [STAGE_W-1:0] STAGE_ONE = STAGE_W'(1);
    localparam [INDEX_W-1:0] INDEX_ONE = INDEX_W'(1);

    reg [1:0] phase;
    reg job_loaded;
    reg first_issued;
    reg [STAGE_W-1:0] stage;
    reg [INDEX_W-1:0] butterfly_index;
    reg [INDEX_W-1:0] twiddle_addr;

    // Preloaded coefficient table: two packed complex Q1.31 lanes per word.
    reg [WORD_W-1:0] coeff_rom [0:ROM_DEPTH-1];
    reg [ROM_DEPTH-1:0] rom_valid;
    reg [COUNT_W-1:0] rom_count;

    function automatic [WORD_W-1:0] coefficient_image(input integer slot);
        begin
            case (slot)
                32'd0:  coefficient_image = 128'h7fffffff000000007fffffff00000000;
                32'd1:  coefficient_image = 128'h7d8a5f40e70747c47d8a5f40e70747c4;
                32'd2:  coefficient_image = 128'h7641af3dcf043ab37641af3dcf043ab3;
                32'd3:  coefficient_image = 128'h6a6d98a4b8e313196a6d98a4b8e31319;
                32'd4:  coefficient_image = 128'h5a82799aa57d86665a82799aa57d8666;
                32'd5:  coefficient_image = 128'h471cece79592675c471cece79592675c;
                32'd6:  coefficient_image = 128'h30fbc54d89be50c330fbc54d89be50c3;
                32'd7:  coefficient_image = 128'h18f8b83c8275a0c018f8b83c8275a0c0;
                32'd8:  coefficient_image = 128'h00000000800000000000000080000000;
                32'd9:  coefficient_image = 128'he70747c48275a0c0e70747c48275a0c0;
                32'd10: coefficient_image = 128'hcf043ab389be50c3cf043ab389be50c3;
                32'd11: coefficient_image = 128'hb8e313199592675cb8e313199592675c;
                32'd12: coefficient_image = 128'ha57d8666a57d8666a57d8666a57d8666;
                32'd13: coefficient_image = 128'h9592675cb8e313199592675cb8e31319;
                32'd14: coefficient_image = 128'h89be50c3cf043ab389be50c3cf043ab3;
                32'd15: coefficient_image = 128'h8275a0c0e70747c48275a0c0e70747c4;
                default: coefficient_image = {WORD_W{1'b0}};
            endcase
        end
    endfunction

    function automatic [INDEX_W-1:0] address_for(
        input [STAGE_W-1:0] s,
        input [INDEX_W-1:0] b
    );
        begin
            address_for =
                (b & ({INDEX_W{1'b1}} >> (STAGES - 1 - s)))
                << (STAGES - 1 - s);
        end
    endfunction

    genvar g;
    generate
        for (g = 0; g < ROM_DEPTH; g = g + 1) begin : initialize_coefficients
            initial coeff_rom[g] = coefficient_image(g);
        end
    endgenerate

    initial begin
        phase = PH_IDLE;
        job_loaded = 1'b0;
        first_issued = 1'b0;
        stage = {STAGE_W{1'b0}};
        butterfly_index = {INDEX_W{1'b0}};
        twiddle_addr = {INDEX_W{1'b0}};
        rom_valid = {ROM_DEPTH{1'b1}};
        rom_count = FULL_COUNT;
    end

    assign o_job_ready = (phase == PH_IDLE) && !job_loaded &&
                         (rom_count == FULL_COUNT);
    assign o_coeff_valid = (phase != PH_IDLE) && rom_valid[twiddle_addr];
    assign o_coeff_data = coeff_rom[twiddle_addr];
    assign o_coeff_addr = twiddle_addr;
    assign o_start = (phase == PH_ARMED) && !first_issued;
    assign o_finish = (stage == LAST_STAGE) &&
                      (butterfly_index == LAST_INDEX);

    // Accepting a job arms the generator. Accepting its first coefficient
    // starts it. Only accepted coefficients advance the FFT traversal.
    always @(posedge clk) begin
        if (phase == PH_IDLE) begin
            if (i_job_valid && o_job_ready) begin
                phase <= PH_ARMED;
                job_loaded <= 1'b1;
                first_issued <= 1'b0;
                stage <= {STAGE_W{1'b0}};
                butterfly_index <= {INDEX_W{1'b0}};
                twiddle_addr <= {INDEX_W{1'b0}};
            end
        end else if (o_coeff_valid && i_coeff_ready) begin
            if (phase == PH_ARMED) begin
                phase <= PH_RUN;
                first_issued <= 1'b1;
            end

            if ((stage == LAST_STAGE) &&
                (butterfly_index == LAST_INDEX)) begin
                phase <= PH_IDLE;
                job_loaded <= 1'b0;
                first_issued <= 1'b0;
                stage <= {STAGE_W{1'b0}};
                butterfly_index <= {INDEX_W{1'b0}};
                twiddle_addr <= {INDEX_W{1'b0}};
            end else if (butterfly_index == LAST_INDEX) begin
                stage <= stage + STAGE_ONE;
                butterfly_index <= {INDEX_W{1'b0}};
                twiddle_addr <= {INDEX_W{1'b0}};
            end else begin
                butterfly_index <= butterfly_index + INDEX_ONE;
                twiddle_addr <= address_for(stage, butterfly_index + INDEX_ONE);
            end
        end
    end

    // Globally, a finish beat requires an accepted arm and an earlier start.
    always @(posedge clk)
        if (o_coeff_valid && o_finish)
            assert (job_loaded && first_issued);
endmodule

module debug_hysteresis_chain #(
    parameter integer DATA_W = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_q_open,
    input  wire                  i_r_close,
    input  wire                  i_arm,
    input  wire [DATA_W-1:0]     i_threshold_base,
    input  wire [DATA_W-1:0]     i_sample,
    output wire                  o_trigger_high,
    output wire                  o_start,
    output wire                  o_finish
);
    // DATA_W must be at least 3. Thresholds delimit a hysteresis band.
    typedef enum logic [1:0] {
        WAIT_ARM = 2'b00,
        ARMED    = 2'b01,
        RUNNING  = 2'b10,
        COMPLETE = 2'b11
    } state_t;

    state_t phase;
    reg [DATA_W-1:0] fall_threshold;
    reg [DATA_W-1:0] rise_threshold;
    reg hyst_high;
    reg window;
    reg arm_seen;
    reg start_seen;
    reg start_event;
    reg finish_event;

    initial begin
        phase          = WAIT_ARM;
        fall_threshold = {DATA_W{1'b0}};
        rise_threshold = {{(DATA_W-2){1'b0}}, 2'b11};
        hyst_high      = 1'b0;
        window         = 1'b0;
        arm_seen       = 1'b0;
        start_seen     = 1'b0;
        start_event    = 1'b0;
        finish_event   = 1'b0;
    end

    assign o_trigger_high = hyst_high;
    assign o_start        = start_event;
    assign o_finish       = finish_event;

    always @(posedge clk) begin
        if (i_ce) begin
            start_event  <= 1'b0;
            finish_event <= 1'b0;

            // R closes the current acquisition window, including an abort.
            if (i_r_close) begin
                window     <= 1'b0;
                phase      <= WAIT_ARM;
                hyst_high  <= 1'b0;
                arm_seen   <= 1'b0;
                start_seen <= 1'b0;
            end else if (i_q_open && !window) begin
                // Q opens a fresh window and programs its threshold band.
                window         <= 1'b1;
                phase          <= WAIT_ARM;
                fall_threshold <= {i_threshold_base[DATA_W-1:2], 2'b00};
                rise_threshold <= {i_threshold_base[DATA_W-1:2], 2'b11};
                hyst_high      <= 1'b0;
                arm_seen       <= 1'b0;
                start_seen     <= 1'b0;
            end else if (window) begin
                case (phase)
                    WAIT_ARM: begin
                        if (i_arm) begin
                            phase    <= ARMED;
                            arm_seen <= 1'b1;
                        end
                    end

                    // The registered comparator level selects which crossing
                    // is meaningful; values inside the band retain the level.
                    ARMED, RUNNING: begin
                        if (!hyst_high && (i_sample >= rise_threshold)) begin
                            hyst_high   <= 1'b1;
                            phase       <= RUNNING;
                            start_seen  <= 1'b1;
                            start_event <= 1'b1;
                        end else if (hyst_high && (i_sample <= fall_threshold)) begin
                            hyst_high    <= 1'b0;
                            phase        <= COMPLETE;
                            finish_event <= 1'b1;
                        end
                    end

                    COMPLETE: begin
                        // Wait for the window to close before another capture.
                    end
                endcase
            end
        end
    end

    // Within each Q-to-R window: arm precedes start, and start precedes finish.
    always @(*) begin
        if (window)
            assert ((!start_event || arm_seen) &&
                    (!finish_event || (arm_seen && start_seen)));
    end
endmodule

module pll_lock_reporter #(
    parameter integer WORD_W = 32,
    parameter [WORD_W-1:0] LOCK_SAMPLES = 32'd6,
    parameter [WORD_W-1:0] PHASE_WINDOW = 32'd8
) (
    input  wire                  clk,
    input  wire                  sample_valid,
    output wire                  sample_ready,
    input  wire [WORD_W-1:0]     phase_error_magnitude,
    input  wire                  end_tracking,
    output reg                   report_valid,
    input  wire                  report_ready,
    output wire [WORD_W-1:0]     report_count,
    output reg                   locked
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] QUALIFY_LIMIT =
        (LOCK_SAMPLES == ZERO) ? ONE : LOCK_SAMPLES;

    reg [WORD_W-1:0] good_count;
    reg qualification_seen;
    reg before_tracking_end;

    assign sample_ready = !report_valid || report_ready;
    assign report_count = good_count;
    wire sample_take = sample_valid && sample_ready;
    wire in_window = phase_error_magnitude <= PHASE_WINDOW;

    initial begin
        good_count = ZERO;
        locked = 1'b0;
        qualification_seen = 1'b0;
        before_tracking_end = 1'b1;
        report_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (sample_take) begin
            report_valid <= 1'b1;

            // The scope ends permanently at the first accepted end marker.
            if (end_tracking)
                before_tracking_end <= 1'b0;

            if (in_window) begin
                if (good_count < QUALIFY_LIMIT)
                    good_count <= good_count + ONE;

                // Remember the sample that completed qualification.
                if (good_count == QUALIFY_LIMIT - ONE)
                    qualification_seen <= 1'b1;

                // A subsequent in-window sample confirms lock.
                locked <= (good_count == QUALIFY_LIMIT);
            end else begin
                good_count <= ZERO;
                locked <= 1'b0;
            end
        end else if (report_valid && report_ready) begin
            report_valid <= 1'b0;
        end
    end

    // A pending report blocks new samples, preserving its count and lock bit.
    // Before tracking ends, observed lock requires earlier qualification.
    assert property (!(before_tracking_end && locked) || qualification_seen);
endmodule

module byte_patch_session #(
    parameter integer WORD_WIDTH = 16
) (
    input  wire                         clk,
    input  wire                         in_valid,
    output wire                         in_ready,
    input  wire                         in_seal,
    input  wire [WORD_WIDTH-1:0]        in_data,
    input  wire [(WORD_WIDTH/8)-1:0]    in_strb,
    output wire                         out_valid,
    input  wire                         out_ready,
    output wire [WORD_WIDTH-1:0]        out_data
);
    localparam integer BYTE_BITS = 8;
    localparam integer BYTE_LANES = WORD_WIDTH / BYTE_BITS;
    localparam logic [15:0] BYTE_LIMIT = BYTE_LANES;

    typedef enum logic [1:0] {
        IDLE     = 2'b00,
        PATCHING = 2'b01,
        SEALED   = 2'b10
    } state_t;

    state_t state;
    reg [WORD_WIDTH-1:0] image;
    reg [BYTE_LANES-1:0] dirty;
    reg [15:0] byte_count;
    reg window_active;
    reg pv;

    reg [15:0] dirty_population;
    reg [15:0] new_population;
    integer lane;
    integer write_lane;

    wire accept_in = in_valid && in_ready;
    wire accept_out = out_valid && out_ready;

    assign in_ready = (state == IDLE) || (state == PATCHING);
    assign out_valid = (state == SEALED);
    assign out_data = image;

    initial begin
        state = IDLE;
        image = {WORD_WIDTH{1'b0}};
        dirty = {BYTE_LANES{1'b0}};
        byte_count = 16'd0;
        window_active = 1'b0;
        pv = 1'b0;
    end

    always @(*) begin
        dirty_population = 16'd0;
        new_population = 16'd0;
        for (lane = 0; lane < BYTE_LANES; lane = lane + 1) begin
            if (dirty[lane])
                dirty_population = dirty_population + 16'd1;
            if (in_strb[lane] && !dirty[lane])
                new_population = new_population + 16'd1;
        end
    end

    // An accepted input in IDLE opens a patch session (Q).
    // An accepted sealed output closes that session (R).
    always @(posedge clk) begin
        if (accept_in || accept_out)
            pv <= 1'b1;

        case (state)
            IDLE: begin
                if (accept_in) begin
                    state <= PATCHING;
                    window_active <= 1'b1;
                    image <= {WORD_WIDTH{1'b0}};
                    dirty <= {BYTE_LANES{1'b0}};
                    byte_count <= 16'd0;
                end
            end

            PATCHING: begin
                if (accept_in) begin
                    if (in_seal) begin
                        state <= SEALED;
                    end else begin
                        for (write_lane = 0; write_lane < BYTE_LANES;
                             write_lane = write_lane + 1) begin
                            if (in_strb[write_lane])
                                image[write_lane*BYTE_BITS +: BYTE_BITS]
                                    <= in_data[write_lane*BYTE_BITS +: BYTE_BITS];
                        end
                        dirty <= dirty | in_strb;
                        byte_count <= byte_count + new_population;
                    end
                end
            end

            SEALED: begin
                if (accept_out) begin
                    state <= IDLE;
                    window_active <= 1'b0;
                end
            end
        endcase
    end

    // During an open session, the previous cycle's distinct-byte
    // occupancy must not exceed the number of byte lanes.
    always @(posedge clk)
        if (pv && window_active)
            assert ($past(byte_count) <= BYTE_LIMIT);
endmodule

module stereo_ctr_stream #(
    parameter integer WORD_W = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire [WORD_W-1:0]     frame_nonce,
    output wire [WORD_W-1:0]     block_nonce,
    output wire [WORD_W-1:0]     block_counter,
    output reg  [WORD_W-1:0]     stream_word,
    output reg                   stream_valid
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};

    reg [WORD_W-1:0] nonce_reg;
    reg [WORD_W-1:0] counter_reg;
    reg [WORD_W-1:0] keystream_buffer;

    // Shadows record the nonce/counter block used at the earlier launch.
    reg [WORD_W-1:0] issued_nonce;
    reg [WORD_W-1:0] issued_counter;
    reg pending;
    reg armed;

    wire [WORD_W-1:0] launch_nonce;
    assign launch_nonce = armed ? nonce_reg : frame_nonce;
    assign block_nonce = issued_nonce;
    assign block_counter = issued_counter;

    initial begin
        nonce_reg = ZERO;
        counter_reg = ZERO;
        keystream_buffer = ZERO;
        issued_nonce = ZERO;
        issued_counter = ZERO;
        pending = 1'b0;
        armed = 1'b0;
        stream_word = ZERO;
        stream_valid = 1'b0;
    end

    // Alternate counter-block generation and buffered pixel-mask delivery.
    // XOR is an abstract byte-wide block transform, not a secure cipher.
    always @(posedge clk) begin
        if (i_ce) begin
            if (!pending) begin
                nonce_reg <= launch_nonce;
                issued_nonce <= launch_nonce;
                issued_counter <= counter_reg;
                keystream_buffer <= launch_nonce ^ counter_reg;
                counter_reg <= counter_reg + ONE;
                pending <= 1'b1;
                stream_valid <= 1'b0;
                // Q: a counter block has been launched; scope stays armed.
                armed <= 1'b1;
            end else begin
                stream_word <= keystream_buffer;
                stream_valid <= 1'b1;
                pending <= 1'b0;
            end
        end
    end

    // Every observed stream word matches the earlier recorded block.
    always @(*) begin
        if (armed && stream_valid)
            assert (stream_word == (issued_nonce ^ issued_counter));
    end
endmodule

module render_stream_ghash #(
    parameter integer WORD_BITS = 32
) (
    input  wire clk,
    input  wire i_valid,
    output wire i_ready,
    input  wire [WORD_BITS-1:0] i_cmd,
    input  wire [WORD_BITS-1:0] i_word0,
    input  wire [WORD_BITS-1:0] i_word1,
    input  wire [WORD_BITS-1:0] i_word2,
    input  wire [WORD_BITS-1:0] i_word3,
    output wire o_valid,
    input  wire o_ready,
    output reg [WORD_BITS-1:0] o_tag0,
    output reg [WORD_BITS-1:0] o_tag1,
    output reg [WORD_BITS-1:0] o_tag2,
    output reg [WORD_BITS-1:0] o_tag3
);
    // Four 32-bit limbs form each 128-bit GHASH field element.
    // Limb 3 is most significant. No multi-item storage is used.
    localparam [WORD_BITS-1:0] PH_IDLE   = 32'd0;
    localparam [WORD_BITS-1:0] PH_ARMED  = 32'd1;
    localparam [WORD_BITS-1:0] PH_MUL    = 32'd2;
    localparam [WORD_BITS-1:0] PH_RESULT = 32'd3;
    localparam [WORD_BITS-1:0] CMD_ARM   = 32'd1;
    localparam [WORD_BITS-1:0] CMD_START = 32'd2;
    localparam [WORD_BITS-1:0] CMD_STEP  = 32'd3;
    localparam [WORD_BITS-1:0] CMD_CLOSE = 32'd4;
    localparam [WORD_BITS-1:0] LAST_BIT = 32'd4 * WORD_BITS - 32'd1;
    localparam [WORD_BITS-1:0] REDUCE_HI = {8'he1, {(WORD_BITS-8){1'b0}}};

    reg [WORD_BITS-1:0] phase;
    reg [WORD_BITS-1:0] bit_count;
    reg [WORD_BITS-1:0] scope_window;
    reg [WORD_BITS-1:0] key_armed;
    reg [WORD_BITS-1:0] block_started;
    reg [WORD_BITS-1:0] block_finished;

    reg [WORD_BITS-1:0] h0, h1, h2, h3;
    reg [WORD_BITS-1:0] x0, x1, x2, x3;
    reg [WORD_BITS-1:0] v0, v1, v2, v3;
    reg [WORD_BITS-1:0] z0, z1, z2, z3;

    wire [WORD_BITS-1:0] round_z0 = z0 ^ (x3[WORD_BITS-1] ? v0 : {WORD_BITS{1'b0}});
    wire [WORD_BITS-1:0] round_z1 = z1 ^ (x3[WORD_BITS-1] ? v1 : {WORD_BITS{1'b0}});
    wire [WORD_BITS-1:0] round_z2 = z2 ^ (x3[WORD_BITS-1] ? v2 : {WORD_BITS{1'b0}});
    wire [WORD_BITS-1:0] round_z3 = z3 ^ (x3[WORD_BITS-1] ? v3 : {WORD_BITS{1'b0}});

    // Commands advance only on an input handshake. A result blocks
    // further commands until its output handshake has completed.
    assign i_ready = ((phase == PH_IDLE) && (i_cmd == CMD_ARM)) ||
                     ((phase == PH_ARMED) &&
                      ((i_cmd == CMD_START) || (i_cmd == CMD_CLOSE))) ||
                     ((phase == PH_MUL) && (i_cmd == CMD_STEP));
    assign o_valid = (phase == PH_RESULT);

    initial begin
        phase = PH_IDLE;
        bit_count = 32'd0;
        scope_window = 32'd0;
        key_armed = 32'd0;
        block_started = 32'd0;
        block_finished = 32'd0;
        h0 = 32'd0; h1 = 32'd0; h2 = 32'd0; h3 = 32'd0;
        x0 = 32'd0; x1 = 32'd0; x2 = 32'd0; x3 = 32'd0;
        v0 = 32'd0; v1 = 32'd0; v2 = 32'd0; v3 = 32'd0;
        z0 = 32'd0; z1 = 32'd0; z2 = 32'd0; z3 = 32'd0;
        o_tag0 = 32'd0; o_tag1 = 32'd0;
        o_tag2 = 32'd0; o_tag3 = 32'd0;
    end

    always @(posedge clk) begin
        if (i_valid && i_ready) begin
            case (phase)
                PH_IDLE: begin
                    // Q: ARM opens the authentication scope and loads H.
                    h0 <= i_word0;
                    h1 <= i_word1;
                    h2 <= i_word2;
                    h3 <= i_word3;
                    o_tag0 <= 32'd0;
                    o_tag1 <= 32'd0;
                    o_tag2 <= 32'd0;
                    o_tag3 <= 32'd0;
                    bit_count <= 32'd0;
                    scope_window <= 32'd1;
                    key_armed <= 32'd1;
                    block_started <= 32'd0;
                    block_finished <= 32'd0;
                    phase <= PH_ARMED;
                end
                PH_ARMED: begin
                    if (i_cmd == CMD_CLOSE) begin
                        // R: CLOSE ends the scope, if it ever arrives.
                        phase <= PH_IDLE;
                        bit_count <= 32'd0;
                        scope_window <= 32'd0;
                        key_armed <= 32'd0;
                        block_started <= 32'd0;
                        block_finished <= 32'd0;
                    end else begin
                        // Start the next recurrence: tag := (tag XOR block) * H.
                        x0 <= o_tag0 ^ i_word0;
                        x1 <= o_tag1 ^ i_word1;
                        x2 <= o_tag2 ^ i_word2;
                        x3 <= o_tag3 ^ i_word3;
                        v0 <= h0; v1 <= h1; v2 <= h2; v3 <= h3;
                        z0 <= 32'd0; z1 <= 32'd0;
                        z2 <= 32'd0; z3 <= 32'd0;
                        bit_count <= 32'd0;
                        block_started <= 32'd1;
                        block_finished <= 32'd0;
                        phase <= PH_MUL;
                    end
                end
                PH_MUL: begin
                    // One MSB-first GF(2^128) multiplication round.
                    // Right-shift reduction implements x^128+x^7+x^2+x+1.
                    z0 <= round_z0;
                    z1 <= round_z1;
                    z2 <= round_z2;
                    z3 <= round_z3;
                    x0 <= {x0[WORD_BITS-2:0], 1'b0};
                    x1 <= {x1[WORD_BITS-2:0], x0[WORD_BITS-1]};
                    x2 <= {x2[WORD_BITS-2:0], x1[WORD_BITS-1]};
                    x3 <= {x3[WORD_BITS-2:0], x2[WORD_BITS-1]};
                    v0 <= {v1[0], v0[WORD_BITS-1:1]};
                    v1 <= {v2[0], v1[WORD_BITS-1:1]};
                    v2 <= {v3[0], v2[WORD_BITS-1:1]};
                    v3 <= {1'b0, v3[WORD_BITS-1:1]} ^
                          (v0[0] ? REDUCE_HI : {WORD_BITS{1'b0}});
                    if (bit_count == LAST_BIT) begin
                        o_tag0 <= round_z0;
                        o_tag1 <= round_z1;
                        o_tag2 <= round_z2;
                        o_tag3 <= round_z3;
                        block_finished <= 32'd1;
                        phase <= PH_RESULT;
                    end else begin
                        bit_count <= bit_count + 32'd1;
                    end
                end
                default: begin end
            endcase
        end else if (o_valid && o_ready) begin
            // Keep H and the running tag for another block in this scope.
            phase <= PH_ARMED;
            bit_count <= 32'd0;
            block_started <= 32'd0;
            block_finished <= 32'd0;
        end
        // With i_valid=0 and o_ready=0, every register holds its value.
    end

    // Within the latched ARM-to-CLOSE scope, start requires arm,
    // and finish requires both arm and start.
    always @(posedge clk)
        assert ((scope_window != 32'd1) ||
                (((block_started == 32'd0) || (key_armed == 32'd1)) &&
                 ((block_finished == 32'd0) ||
                  ((key_armed == 32'd1) && (block_started == 32'd1)))));
endmodule

module chien_deadline_search #(
    parameter integer FIELD_W = 8,
    parameter integer COEFFS = 4,
    parameter [FIELD_W-1:0] REDUCTION = 8'h1d
) (
    input  wire clk,
    input  wire req_valid,
    output wire req_ready,
    input  wire [COEFFS*FIELD_W-1:0] req_coeffs,
    output wire result_valid,
    input  wire result_ready,
    output reg  [FIELD_W-1:0] position,
    output reg  hit
);
    localparam [FIELD_W-1:0] FIELD_ZERO = {FIELD_W{1'b0}};
    localparam [FIELD_W-1:0] FIELD_ONE = {{(FIELD_W-1){1'b0}}, 1'b1};
    localparam [FIELD_W-1:0] LAST_POSITION = {FIELD_W{1'b1}};
    localparam [FIELD_W:0] FIELD_SIZE = {1'b1, {FIELD_W{1'b0}}};
    localparam [FIELD_W:0] CREDIT_ONE = {{FIELD_W{1'b0}}, 1'b1};

    reg busy;
    reg armed;
    reg pv;
    reg [FIELD_W:0] credits;
    reg [FIELD_W-1:0] terms [0:COEFFS-1];
    wire [FIELD_W-1:0] stepped_terms [0:COEFFS-1];
    reg [FIELD_W-1:0] eval_now;
    reg [FIELD_W-1:0] eval_next;

    wire request_fire;
    wire trial_fire;
    assign req_ready = !busy;
    assign result_valid = busy;
    assign request_fire = req_valid && req_ready;
    assign trial_fire = result_valid && result_ready;

    function automatic [FIELD_W-1:0] gf_xtime;
        input [FIELD_W-1:0] a;
        begin
            gf_xtime = (a << 1'b1) ^
                       (a[FIELD_W-1] ? REDUCTION : FIELD_ZERO);
        end
    endfunction

    function automatic [FIELD_W-1:0] gf_mul;
        input [FIELD_W-1:0] a;
        input [FIELD_W-1:0] b;
        reg [FIELD_W-1:0] multiplicand;
        reg [FIELD_W-1:0] multiplier;
        reg [FIELD_W-1:0] product;
        integer bit_index;
        begin
            multiplicand = a;
            multiplier = b;
            product = FIELD_ZERO;
            for (bit_index = 0; bit_index < FIELD_W; bit_index = bit_index + 1) begin
                if (multiplier[0])
                    product = product ^ multiplicand;
                multiplicand = gf_xtime(multiplicand);
                multiplier = multiplier >> 1'b1;
            end
            gf_mul = product;
        end
    endfunction

    function automatic [FIELD_W-1:0] alpha_factor;
        input integer exponent;
        reg [FIELD_W-1:0] factor;
        integer power_index;
        begin
            factor = FIELD_ONE;
            for (power_index = 0; power_index < exponent; power_index = power_index + 1)
                factor = gf_xtime(factor);
            alpha_factor = factor;
        end
    endfunction

    genvar coefficient;
    generate
        for (coefficient = 0; coefficient < COEFFS; coefficient = coefficient + 1) begin : coefficient_steps
            assign stepped_terms[coefficient] =
                gf_mul(terms[coefficient], alpha_factor(coefficient));
        end
    endgenerate

    integer eval_index;
    always @(*) begin
        eval_now = FIELD_ZERO;
        eval_next = FIELD_ZERO;
        for (eval_index = 0; eval_index < COEFFS; eval_index = eval_index + 1) begin
            eval_now = eval_now ^ terms[eval_index];
            eval_next = eval_next ^ stepped_terms[eval_index];
        end
    end

    integer init_index;
    initial begin
        busy = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
        credits = {1'b0, FIELD_ZERO};
        position = FIELD_ZERO;
        hit = 1'b0;
        for (init_index = 0; init_index < COEFFS; init_index = init_index + 1)
            terms[init_index] = FIELD_ZERO;
    end

    // Position zero tests x=0. Positions 1..255 test alpha^0..alpha^254.
    // Each accepted result consumes one enabled search cycle. Back-pressure
    // freezes the countdown, multiplier registers, position and hit flag.
    integer state_index;
    always @(posedge clk) begin
        if (request_fire || trial_fire)
            pv <= 1'b1;

        if (request_fire) begin
            armed <= 1'b1;
            busy <= 1'b1;
            credits <= FIELD_SIZE;
            position <= FIELD_ZERO;
            hit <= (req_coeffs[0 +: FIELD_W] == FIELD_ZERO);
            for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                terms[state_index] <= req_coeffs[state_index*FIELD_W +: FIELD_W];
        end else if (trial_fire) begin
            credits <= credits - CREDIT_ONE;
            if (position == LAST_POSITION) begin
                busy <= 1'b0;
            end else begin
                position <= position + FIELD_ONE;
                if (position == FIELD_ZERO) begin
                    // The first nonzero element is one; coefficients stay unchanged.
                    hit <= (eval_now == FIELD_ZERO);
                end else begin
                    for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                        terms[state_index] <= stepped_terms[state_index];
                    hit <= (eval_next == FIELD_ZERO);
                end
            end
        end
    end

    // After the first accepted request, consuming the previous cycle's final
    // countdown credit must leave no search outstanding.
    always @(posedge clk)
        if (pv && armed && $past(trial_fire))
            assert (!busy || ($past(credits) > CREDIT_ONE));
endmodule

module compressed_fetch_queue #(
    parameter integer DEPTH = 32'd8
) (
    input  wire        clk,
    input  wire        ce,
    input  wire        fetch_valid,
    input  wire [31:0] fetch_word,
    output wire        fetch_ready,
    input  wire        decode_ready,
    output wire        decode_valid,
    output wire [31:0] decode_instruction,
    output reg  [31:0] occupancy
);
    reg [31:0] instructions [0:DEPTH-32'd1];
    reg [DEPTH-32'd1:0] valid;
    reg [31:0] rd_ptr;
    reg [31:0] wr_ptr;

    reg [31:0] fetch_buffer;
    reg [31:0] halves_left;
    // The saved halfword is zero-extended into a 32-bit holding register.
    reg [31:0] half_hold;
    reg        have_low;

    // RV32 compressed subset: C.ADDI and C.LI expand to ADDI.
    // Unsupported compressed encodings are treated as NOPs.
    function automatic [31:0] expand_compressed(input [15:0] c);
        begin
            case ({c[15:13], c[1:0]})
                5'b00001:
                    expand_compressed = {{7{c[12]}}, c[6:2],
                                         c[11:7], 3'b000,
                                         c[11:7], 7'b0010011};
                5'b01001:
                    expand_compressed = {{7{c[12]}}, c[6:2],
                                         5'd0, 3'b000,
                                         c[11:7], 7'b0010011};
                default:
                    expand_compressed = 32'h00000013;
            endcase
        end
    endfunction

    function automatic [31:0] next_pointer(input [31:0] p);
        begin
            next_pointer = (p == DEPTH - 32'd1) ? 32'd0 : p + 32'd1;
        end
    endfunction

    wire compressed_half = fetch_buffer[1:0] != 2'b11;
    wire produces_instruction = have_low || compressed_half;
    wire consume_half = ce && (halves_left != 32'd0) &&
                        (!produces_instruction || !valid[wr_ptr]);
    wire enqueue = consume_half && produces_instruction;
    wire dequeue = ce && decode_ready && valid[rd_ptr];
    wire [31:0] expanded_instruction = have_low
        ? {fetch_buffer[15:0], half_hold[15:0]}
        : expand_compressed(fetch_buffer[15:0]);

    assign fetch_ready = ce && (halves_left == 32'd0);
    assign decode_valid = valid[rd_ptr];
    assign decode_instruction = instructions[rd_ptr];

    initial begin
        occupancy = 32'd0;
        rd_ptr = 32'd0;
        wr_ptr = 32'd0;
        valid = {DEPTH{1'b0}};
        fetch_buffer = 32'd0;
        halves_left = 32'd0;
        half_hold = 32'd0;
        have_low = 1'b0;
        for (integer i = 32'd0; i < DEPTH; i = i + 32'd1)
            instructions[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (fetch_valid && fetch_ready) begin
                fetch_buffer <= fetch_word;
                halves_left <= 32'd2;
            end else if (consume_half) begin
                fetch_buffer <= {16'd0, fetch_buffer[31:16]};
                halves_left <= halves_left - 32'd1;
                if (have_low) begin
                    have_low <= 1'b0;
                    half_hold <= 32'd0;
                end else if (!compressed_half) begin
                    have_low <= 1'b1;
                    half_hold <= {16'd0, fetch_buffer[15:0]};
                end
            end

            // Slot-valid bits, rather than the redundant count, provide
            // backpressure. A full queue cannot overwrite a live instruction.
            if (enqueue) begin
                instructions[wr_ptr] <= expanded_instruction;
                valid[wr_ptr] <= 1'b1;
                wr_ptr <= next_pointer(wr_ptr);
            end
            if (dequeue) begin
                valid[rd_ptr] <= 1'b0;
                rd_ptr <= next_pointer(rd_ptr);
            end

            case ({enqueue, dequeue})
                2'b10: occupancy <= occupancy + 32'd1;
                2'b01: occupancy <= occupancy - 32'd1;
                default: begin end
            endcase
        end
    end

    assert property (occupancy <= DEPTH);
endmodule

module diagnostic_reassembly #(
    parameter [63:0] SEGMENTS = 64'd48
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_fragment,
    input  wire [63:0] i_fragment_data,
    input  wire        i_publish,
    input  wire [63:0] i_read_segment,
    output wire [63:0] o_segment_data,
    output reg  [63:0] received_length,
    output reg  [63:0] descriptor_end
);
    localparam [63:0] SEGMENT_BYTES = 64'd8;

    reg [63:0] segment_mem [0:SEGMENTS-64'd1];
    reg [63:0] write_offset;
    reg before_publish;

    initial begin
        write_offset    = 64'd0;
        received_length = 64'd0;
        descriptor_end  = 64'd0;
        before_publish  = 1'b1;
    end

    genvar n;
    generate
        for (n = 32'd0; n < SEGMENTS; n = n + 32'd1) begin : g_init
            initial segment_mem[n] = 64'd0;
        end
    endgenerate

    assign o_segment_data = (i_read_segment < SEGMENTS)
                          ? segment_mem[i_read_segment] : 64'd0;

    // Each accepted fragment contributes one eight-byte segment.
    // write_offset addresses contiguous segment slots; descriptor_end
    // records the exclusive byte extent calculated from that address.
    always @(posedge clk) begin
        if (i_ce) begin
            // The first enabled publication event permanently ends the scope.
            if (i_publish)
                before_publish <= 1'b0;

            if (before_publish && !i_publish && i_fragment &&
                (write_offset < SEGMENTS)) begin
                segment_mem[write_offset] <= i_fragment_data;
                write_offset    <= write_offset + 64'd1;
                received_length <= received_length + SEGMENT_BYTES;
                descriptor_end  <= (write_offset + 64'd1) * SEGMENT_BYTES;
            end
        end
    end

    always @(*)
        assert (!before_publish || (descriptor_end == received_length));
endmodule

module usb_report_mailbox #(
    parameter integer DEPTH = 32'd256,
    parameter integer DATA_WIDTH = 32'd32,
    parameter integer ADDR_WIDTH = 32'd32
) (
    input  wire                  wr_clk,
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [DATA_WIDTH-1:0] in_data,
    input  wire                  release_read,
    input  wire                  session_end,
    output reg                   read_valid,
    output reg  [DATA_WIDTH-1:0] read_data
);
    localparam [ADDR_WIDTH-1:0] LAST_ADDR = DEPTH - 32'd1;
    localparam [ADDR_WIDTH-1:0] ADDR_ONE =
        {{(ADDR_WIDTH-32'd1){1'b0}}, 1'b1};

    // Single-write-port, synchronous-read-port RAM in separate domains.
    reg [DATA_WIDTH-1:0] ram [0:DEPTH-1];
    reg [ADDR_WIDTH-1:0] next_wr_addr;
    reg [ADDR_WIDTH-1:0] wr_addr;
    reg [ADDR_WIDTH-1:0] rd_addr;

    // The mailbox permits one outstanding report. The writer keeps its
    // accepted payload and address unchanged until the reader releases it.
    reg [DATA_WIDTH-1:0] accepted_payload;
    reg request;
    reg acknowledge;
    reg before_session_end;
    reg pv;
    integer init_index;

    initial begin
        next_wr_addr = {ADDR_WIDTH{1'b0}};
        wr_addr = {ADDR_WIDTH{1'b0}};
        rd_addr = {ADDR_WIDTH{1'b0}};
        accepted_payload = {DATA_WIDTH{1'b0}};
        request = 1'b0;
        acknowledge = 1'b0;
        read_valid = 1'b0;
        read_data = {DATA_WIDTH{1'b0}};
        before_session_end = 1'b1;
        pv = 1'b0;
        for (init_index = 32'd0; init_index < DEPTH;
             init_index = init_index + 32'd1)
            ram[init_index] = {DATA_WIDTH{1'b0}};
    end

    // Back-pressure prevents another input handshake while a report is pending.
    assign in_ready = i_ce && (request == acknowledge);

    always @(posedge wr_clk) begin
        if (in_valid && in_ready) begin
            ram[next_wr_addr] <= in_data;
            wr_addr <= next_wr_addr;
            accepted_payload <= in_data;
            request <= !request;
            if (next_wr_addr == LAST_ADDR)
                next_wr_addr <= {ADDR_WIDTH{1'b0}};
            else
                next_wr_addr <= next_wr_addr + ADDR_ONE;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (session_end)
                before_session_end <= 1'b0;

            if (!read_valid && (request != acknowledge)) begin
                rd_addr <= wr_addr;
                read_data <= ram[wr_addr];
                read_valid <= 1'b1;
            end else if (read_valid && release_read) begin
                read_valid <= 1'b0;
                acknowledge <= request;
            end
        end
    end

    // Before session termination, an observed report must match the payload
    // recorded by an earlier input handshake, sampled on the previous cycle.
    always @(posedge clk) begin
        if (pv && before_session_end && read_valid)
            assert (read_data == $past(accepted_payload));
    end
endmodule

module priority_interrupt_dispatch #(
    parameter integer WORD_W = 32'd32,
    parameter integer IRQ_COUNT = 32'd64
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  cmd_valid,
    output wire                  cmd_ready,
    input  wire [WORD_W-1:0]     cmd,
    input  wire [WORD_W-1:0]     cmd_irq,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [WORD_W-1:0]     out_vector
);
    localparam [WORD_W-1:0] CMD_RAISE    = 32'd0;
    localparam [WORD_W-1:0] CMD_ENABLE   = 32'd1;
    localparam [WORD_W-1:0] CMD_DISABLE  = 32'd2;
    localparam [WORD_W-1:0] CMD_COMPLETE = 32'd3;
    localparam [WORD_W-1:0] CMD_DISPATCH = 32'd4;
    localparam [WORD_W-1:0] CMD_SHUTDOWN = 32'd5;
    localparam [WORD_W-1:0] STATUS_LIMIT = 32'd7;

    // One 32-bit software-visible register per interrupt source.
    // Bit 0: pending; bit 1: enabled; bit 2: in service.
    // The remaining bits are reserved and stay zero.
    reg [WORD_W-1:0] irq_state [0:IRQ_COUNT-1];
    reg [WORD_W-1:0] irq_state_next [0:IRQ_COUNT-1];

    // Cached highest-priority eligible source: lowest index wins.
    reg cached_valid;
    reg [WORD_W-1:0] cached_vector;
    reg cached_valid_next;
    reg [WORD_W-1:0] cached_vector_next;

    reg out_valid_next;
    reg [WORD_W-1:0] out_vector_next;
    reg before_shutdown;
    reg before_shutdown_next;

    wire take_command = cmd_valid && cmd_ready;
    wire take_vector = out_valid && out_ready;
    wire move = take_command || take_vector;
    assign cmd_ready = !out_valid;

    integer init_i;
    integer next_i;
    integer priority_i;
    integer clock_i;
    integer bound_i;

    initial begin
        out_valid = 1'b0;
        out_vector = {WORD_W{1'b0}};
        cached_valid = 1'b0;
        cached_vector = {WORD_W{1'b0}};
        before_shutdown = 1'b1;
        for (init_i = 32'd0; init_i < IRQ_COUNT; init_i = init_i + 32'd1)
            irq_state[init_i] = {WORD_W{1'b0}};
    end

    always @(*) begin
        for (next_i = 32'd0; next_i < IRQ_COUNT; next_i = next_i + 32'd1)
            irq_state_next[next_i] = irq_state[next_i];
        out_valid_next = out_valid;
        out_vector_next = out_vector;
        before_shutdown_next = before_shutdown;

        if (take_vector) begin
            irq_state_next[out_vector][0] = 1'b0;
            irq_state_next[out_vector][2] = 1'b1;
            out_valid_next = 1'b0;
        end else if (take_command) begin
            case (cmd)
                CMD_RAISE:
                    if (cmd_irq < IRQ_COUNT)
                        irq_state_next[cmd_irq][0] = 1'b1;
                CMD_ENABLE:
                    if (cmd_irq < IRQ_COUNT)
                        irq_state_next[cmd_irq][1] = 1'b1;
                CMD_DISABLE:
                    if (cmd_irq < IRQ_COUNT)
                        irq_state_next[cmd_irq][1] = 1'b0;
                CMD_COMPLETE:
                    if (cmd_irq < IRQ_COUNT)
                        irq_state_next[cmd_irq][2] = 1'b0;
                CMD_DISPATCH:
                    if (cached_valid) begin
                        out_valid_next = 1'b1;
                        out_vector_next = cached_vector;
                    end
                CMD_SHUTDOWN:
                    before_shutdown_next = 1'b0;
                default: begin end
            endcase
        end

        // Refresh the priority cache from the updated source registers.
        cached_valid_next = 1'b0;
        cached_vector_next = {WORD_W{1'b0}};
        for (priority_i = 32'd0; priority_i < IRQ_COUNT; priority_i = priority_i + 32'd1) begin
            if (!cached_valid_next && irq_state_next[priority_i][0] &&
                irq_state_next[priority_i][1] && !irq_state_next[priority_i][2]) begin
                cached_valid_next = 1'b1;
                cached_vector_next = priority_i;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 1'b0;
            out_vector <= {WORD_W{1'b0}};
            cached_valid <= 1'b0;
            cached_vector <= {WORD_W{1'b0}};
            before_shutdown <= 1'b1;
            for (clock_i = 32'd0; clock_i < IRQ_COUNT; clock_i = clock_i + 32'd1)
                irq_state[clock_i] <= {WORD_W{1'b0}};
        end else if (move) begin
            out_valid <= out_valid_next;
            out_vector <= out_vector_next;
            cached_valid <= cached_valid_next;
            cached_vector <= cached_vector_next;
            before_shutdown <= before_shutdown_next;
            for (clock_i = 32'd0; clock_i < IRQ_COUNT; clock_i = clock_i + 32'd1)
                irq_state[clock_i] <= irq_state_next[clock_i];
        end
    end

    // Combinational helper for the separately supplied register bounds.
    reg table_words_bounded;
    always @(*) begin
        table_words_bounded = 1'b1;
        for (bound_i = 32'd0; bound_i < IRQ_COUNT; bound_i = bound_i + 32'd1)
            if (irq_state[bound_i] > STATUS_LIMIT)
                table_words_bounded = 1'b0;
    end

    // Universality before the first accepted shutdown command.
    always @(posedge clk) begin
        if (before_shutdown && out_valid)
            assert (irq_state[out_vector][0]);
        if (before_shutdown && out_valid)
            assert (irq_state[out_vector][1] && !irq_state[out_vector][2]);
    end
endmodule

module dither_pwm_sequence #(
    parameter integer WORD_W = 32'd32,
    parameter [WORD_W-1:0] PERIOD = 32'd8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    output wire                  o_ready,
    input  wire [1:0]            i_command,
    input  wire [WORD_W-1:0]     i_duty_integer,
    input  wire [WORD_W-1:0]     i_duty_fraction,
    output wire                  o_pwm,
    output wire [WORD_W-1:0]     o_period_duty
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] ST_EMPTY = ZERO;
    localparam [WORD_W-1:0] ST_ARMED = ONE;
    localparam [WORD_W-1:0] ST_RUN = ONE + ONE;
    localparam [1:0] CMD_ARM = 2'd0;
    localparam [1:0] CMD_START = 2'd1;
    localparam [1:0] CMD_TICK = 2'd2;

    reg [WORD_W-1:0] phase;
    reg [WORD_W-1:0] period_count;
    reg [WORD_W-1:0] duty_integer;
    reg [WORD_W-1:0] duty_fraction;
    reg [WORD_W-1:0] fraction_error;
    reg [WORD_W-1:0] period_duty;
    reg dither_carry;
    reg arm_seen;
    reg start_seen;
    reg finish_seen;
    reg scope_armed;

    wire [WORD_W-1:0] limited_integer =
        (i_duty_integer < PERIOD) ? i_duty_integer : (PERIOD - ONE);
    wire [WORD_W:0] fraction_sum =
        {1'b0, fraction_error} + {1'b0, duty_fraction};
    wire [WORD_W-1:0] next_carry_word =
        {{(WORD_W-1){1'b0}}, fraction_sum[WORD_W]};

    // Commands are accepted only when the PWM controller can execute them.
    assign o_ready = i_ce &&
        (((i_command == CMD_ARM) && (phase != ST_RUN)) ||
         ((i_command == CMD_START) && (phase == ST_ARMED)) ||
         ((i_command == CMD_TICK) && (phase == ST_RUN)));
    wire transfer = i_valid && o_ready;

    assign o_pwm = (phase == ST_RUN) && (period_count < period_duty);
    assign o_period_duty = period_duty;

    initial begin
        phase = ST_EMPTY;
        period_count = ZERO;
        duty_integer = ZERO;
        duty_fraction = ZERO;
        fraction_error = ZERO;
        period_duty = ZERO;
        dither_carry = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        finish_seen = 1'b0;
        scope_armed = 1'b0;
    end

    // Accepted TICK commands advance the PWM timebase; back-pressure pauses it.
    always @(posedge clk) begin
        if (transfer) begin
            case (i_command)
                CMD_ARM: begin
                    phase <= ST_ARMED;
                    period_count <= ZERO;
                    duty_integer <= limited_integer;
                    duty_fraction <= i_duty_fraction;
                    fraction_error <= ZERO;
                    period_duty <= limited_integer;
                    dither_carry <= 1'b0;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    finish_seen <= 1'b0;
                end
                CMD_START: begin
                    phase <= ST_RUN;
                    period_count <= ZERO;
                    fraction_error <= fraction_sum[WORD_W-1:0];
                    dither_carry <= fraction_sum[WORD_W];
                    period_duty <= duty_integer + next_carry_word;
                    start_seen <= 1'b1;
                    finish_seen <= 1'b0;
                    // Q: the first fractional overflow used to extend a period's duty.
                    if (fraction_sum[WORD_W])
                        scope_armed <= 1'b1;
                end
                CMD_TICK: begin
                    if (period_count == PERIOD - ONE) begin
                        phase <= ST_ARMED;
                        period_count <= ZERO;
                        finish_seen <= 1'b1;
                    end else begin
                        period_count <= period_count + ONE;
                    end
                end
                default: begin end
            endcase
        end
    end

    // After Q, every observed start requires an arm, and every finish
    // requires both the preceding arm and a start since that arm.
    assert property (!scope_armed ||
        ((!start_seen || arm_seen) &&
         (!finish_seen || (arm_seen && start_seen))));
endmodule

module accelerator_command_fifo #(
    parameter integer DEPTH = 32'd8,
    parameter integer WORD_WIDTH = 32'd32,
    parameter integer PTR_WIDTH = 32'd32
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_WIDTH-1:0]  in_data,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [WORD_WIDTH-1:0]  out_data
);
    // DEPTH is a power of two. Each pointer contains an address and
    // one wrap bit; its remaining high bits stay zero.
    localparam integer ADDR_BITS = $clog2(DEPTH);
    localparam [PTR_WIDTH-1:0] PTR_ZERO = {PTR_WIDTH{1'b0}};
    localparam [PTR_WIDTH-1:0] PTR_ONE = {{(PTR_WIDTH-1){1'b0}}, 1'b1};
    localparam [PTR_WIDTH-1:0] DEPTH_COUNT = DEPTH;
    localparam [PTR_WIDTH-1:0] PTR_LAST =
        (DEPTH_COUNT << 32'd1) - PTR_ONE;

    localparam [WORD_WIDTH-1:0] CMD_ARM = 32'd0;
    localparam [WORD_WIDTH-1:0] CMD_START = 32'd1;
    localparam [WORD_WIDTH-1:0] CMD_FINISH = 32'd2;
    localparam [WORD_WIDTH-1:0] PHASE_COUNT = 32'd3;
    localparam [WORD_WIDTH-1:0] PHASE_ONE = 32'd1;

    reg [PTR_WIDTH-1:0] wptr;
    reg [PTR_WIDTH-1:0] rptr;
    reg [WORD_WIDTH-1:0] mem [0:DEPTH-1];

    // Producer and consumer protocol machines: expect ARM, START, FINISH.
    reg [WORD_WIDTH-1:0] issue_phase;
    reg [WORD_WIDTH-1:0] retire_phase;
    reg before_first_finish;

    initial begin
        wptr = PTR_ZERO;
        rptr = PTR_ZERO;
        issue_phase = CMD_ARM;
        retire_phase = CMD_ARM;
        before_first_finish = 1'b1;
    end

    wire empty = (wptr == rptr);
    wire full = (wptr == (rptr ^ DEPTH_COUNT));

    // This is combinational pointer distance, not an occupancy register.
    wire [PTR_WIDTH-1:0] used = (wptr - rptr) & PTR_LAST;

    assign in_ready = !full && (in_data == issue_phase);
    assign out_valid = !empty;
    assign out_data = mem[rptr[ADDR_BITS-1:0]];

    wire push = in_valid && in_ready;
    wire pop = out_valid && out_ready;

    always @(posedge clk) begin
        if (push) begin
            mem[wptr[ADDR_BITS-1:0]] <= in_data;
            wptr <= (wptr == PTR_LAST) ? PTR_ZERO : wptr + PTR_ONE;
            issue_phase <= (issue_phase == CMD_FINISH)
                         ? CMD_ARM : issue_phase + PHASE_ONE;
        end

        if (pop) begin
            rptr <= (rptr == PTR_LAST) ? PTR_ZERO : rptr + PTR_ONE;
            case (out_data)
                CMD_ARM: retire_phase <= CMD_START;
                CMD_START: retire_phase <= CMD_FINISH;
                CMD_FINISH: begin
                    retire_phase <= CMD_ARM;
                    before_first_finish <= 1'b0;
                end
                default: retire_phase <= CMD_ARM;
            endcase
        end
    end

    // Combinational descriptions of the live circular RAM contents.
    wire [DEPTH-1:0] slot_order_ok;
    genvar slot;
    generate
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin : g_slot
            localparam [PTR_WIDTH-1:0] OFFSET = slot;
            wire [PTR_WIDTH-1:0] slot_ptr = (rptr + OFFSET) & PTR_LAST;
            wire [WORD_WIDTH-1:0] expected_command =
                (retire_phase + OFFSET) % PHASE_COUNT;

            initial mem[slot] = CMD_ARM;

            assign slot_order_ok[slot] =
                (used <= OFFSET) ||
                (mem[slot_ptr[ADDR_BITS-1:0]] == expected_command);
        end
    endgenerate

    // Before the first completed FINISH, START requires a retired ARM,
    // and FINISH requires a retired ARM followed by a retired START.
    always @(posedge clk)
        if (before_first_finish && out_valid &&
            ((out_data == CMD_START) || (out_data == CMD_FINISH)))
            assert (((out_data == CMD_START) && (retire_phase == CMD_START)) ||
                    ((out_data == CMD_FINISH) && (retire_phase == CMD_FINISH)));
endmodule

module board_serial_divider #(
    parameter integer WORD_BITS = 8
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 i_launch,
    input  wire                 i_close_window,
    input  wire [WORD_BITS-1:0] i_dividend,
    input  wire [WORD_BITS-1:0] i_divisor,
    output wire [WORD_BITS-1:0] o_quotient,
    output wire [WORD_BITS-1:0] o_remainder,
    output wire [WORD_BITS-1:0] o_iterations
);
    localparam [WORD_BITS-1:0] ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] WORD_ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] FIRST_DIGIT = {1'b1, {(WORD_BITS-1){1'b0}}};
    localparam [WORD_BITS-1:0] ITER_LIMIT = WORD_BITS;

    reg [WORD_BITS-1:0] dividend_hold;
    reg [WORD_BITS-1:0] divisor_hold;
    reg [WORD_BITS-1:0] partial_remainder;
    reg [WORD_BITS-1:0] quotient;
    reg [WORD_BITS-1:0] digit_mask;
    reg [WORD_BITS-1:0] iteration_count;
    reg window_open;

    initial begin
        dividend_hold = ZERO;
        divisor_hold = WORD_ONE;
        partial_remainder = ZERO;
        quotient = ZERO;
        digit_mask = ZERO;
        iteration_count = ITER_LIMIT;
        window_open = 1'b0;
    end

    // The mask selects both the incoming dividend bit and its quotient position.
    wire dividend_bit = |(dividend_hold & digit_mask);
    wire [WORD_BITS-1:0] shifted_remainder =
        {partial_remainder[WORD_BITS-2:0], dividend_bit};
    wire [WORD_BITS-1:0] trial_difference =
        shifted_remainder - divisor_hold;

    // The discarded shift bit is the trial remainder's carry bit.
    wire trial_succeeds = partial_remainder[WORD_BITS-1] ||
                          (shifted_remainder >= divisor_hold);

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_launch) begin
                dividend_hold <= i_dividend;
                // Define division by zero as division by one.
                divisor_hold <= (i_divisor == ZERO) ? WORD_ONE : i_divisor;
                partial_remainder <= ZERO;
                quotient <= ZERO;
                digit_mask <= FIRST_DIGIT;
                iteration_count <= ZERO;
                window_open <= 1'b1;
            end else begin
                // Closing the observation window does not stop arithmetic.
                // Without this event, the window remains open after completion.
                if (i_close_window)
                    window_open <= 1'b0;

                if (digit_mask != ZERO) begin
                    if (trial_succeeds) begin
                        partial_remainder <= trial_difference;
                        quotient <= quotient | digit_mask;
                    end else begin
                        // Restore the unsubtracted trial remainder.
                        partial_remainder <= shifted_remainder;
                    end
                    digit_mask <= digit_mask >> 1'b1;
                    iteration_count <= iteration_count + WORD_ONE;
                end
            end
        end
    end

    assign o_quotient = quotient;
    assign o_remainder = partial_remainder;
    assign o_iterations = iteration_count;

    assert property (!window_open || (iteration_count <= ITER_LIMIT));
endmodule

module i2c_stretch_handler #(
    parameter integer COUNTER_WIDTH = 32,
    parameter [COUNTER_WIDTH-1:0] RESET_MAX_STRETCH = 32'd8
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire request_high,
    input wire scl_in,
    input wire config_valid,
    input wire [COUNTER_WIDTH-1:0] config_max_stretch,
    output wire scl_release,
    output wire high_phase_done,
    output reg high_pending,
    output reg stretching_active,
    output reg stretch_timeout,
    output reg [COUNTER_WIDTH-1:0] stretch_duration,
    output reg [COUNTER_WIDTH-1:0] max_stretch
);
    localparam [COUNTER_WIDTH-1:0] COUNT_ZERO = {COUNTER_WIDTH{1'b0}};
    localparam [COUNTER_WIDTH-1:0] COUNT_ONE = {{(COUNTER_WIDTH-1){1'b0}}, 1'b1};
    reg past_valid;

    initial begin
        high_pending = 1'b0;
        stretching_active = 1'b0;
        stretch_timeout = 1'b0;
        stretch_duration = COUNT_ZERO;
        max_stretch = RESET_MAX_STRETCH;
        past_valid = 1'b0;
    end

    // Release the open-drain SCL output throughout the pending high phase.
    // Even a timeout does not end that phase before the slave releases SCL.
    assign scl_release = high_pending;
    assign high_phase_done = high_pending && scl_in;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            high_pending <= 1'b0;
            stretching_active <= 1'b0;
            stretch_timeout <= 1'b0;
            stretch_duration <= COUNT_ZERO;
            max_stretch <= RESET_MAX_STRETCH;
            past_valid <= 1'b0;
        end else if (i_ce) begin
            past_valid <= 1'b1;
            if (!high_pending) begin
                stretching_active <= 1'b0;
                if (config_valid) begin
                    max_stretch <= config_max_stretch;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end else if (request_high) begin
                    high_pending <= 1'b1;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end
            end else if (scl_in) begin
                high_pending <= 1'b0;
                stretching_active <= 1'b0;
            end else begin
                stretching_active <= 1'b1;
                // Saturate the duration at the programmed stretch budget.
                if (stretch_duration < max_stretch) begin
                    stretch_duration <= stretch_duration + COUNT_ONE;
                    if ((stretch_duration + COUNT_ONE) == max_stretch)
                        stretch_timeout <= 1'b1;
                end else begin
                    stretch_timeout <= 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (past_valid && $rose(stretch_timeout))
            assert (stretch_duration == max_stretch);
endmodule

module viterbi_acs_trace (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    output wire                  o_ready,
    input  wire [1:0]            i_cmd,
    input  wire [WORD_W-1:0]     i_branch_self,
    input  wire [WORD_W-1:0]     i_branch_prev,
    input  wire [WORD_W-1:0]     i_start_state,
    output wire                  o_trace_self,
    output wire                  o_trace_prev,
    output wire [WORD_W-1:0]     o_trace_state,
    output wire [WORD_W-1:0]     o_path_metric
);
    parameter integer WORD_W = 16;
    parameter integer ENTRIES = 24;

    localparam [1:0] CMD_ACS   = 2'b00;
    localparam [1:0] CMD_START = 2'b01;
    localparam [1:0] CMD_TRACE = 2'b10;
    localparam [1:0] CMD_END   = 2'b11;
    localparam [WORD_W-1:0] ZERO_WORD = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE_WORD = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] TWO_WORD = {{(WORD_W-2){1'b0}}, 2'b10};
    localparam [WORD_W-1:0] INF_WORD = {WORD_W{1'b1}};
    localparam [WORD_W-1:0] ENTRY_LIMIT = ENTRIES;
    localparam [WORD_W-1:0] LAST_ENTRY = ENTRIES - 32'd1;

    reg [WORD_W-1:0] path_metric [0:ENTRIES-1];
    reg [WORD_W-1:0] next_metric [0:ENTRIES-1];
    // Each word encodes the survivor edge: self=1, previous state=2.
    reg [WORD_W-1:0] traceback_mem [0:ENTRIES-1];
    reg [WORD_W-1:0] sweep_index;
    reg [WORD_W-1:0] trace_state;
    reg scope_open;
    reg pv;

    initial begin
        sweep_index = ZERO_WORD;
        trace_state = ZERO_WORD;
        scope_open = 1'b0;
        pv = 1'b0;
    end

    // A ring trellis has two incoming edges per state: self and predecessor.
    function automatic [WORD_W-1:0] sat_add;
        input [WORD_W-1:0] a;
        input [WORD_W-1:0] b;
        begin
            if (a > (INF_WORD - b))
                sat_add = INF_WORD;
            else
                sat_add = a + b;
        end
    endfunction

    wire [WORD_W-1:0] acs_predecessor =
        (sweep_index == ZERO_WORD) ? LAST_ENTRY : sweep_index - ONE_WORD;
    wire [WORD_W-1:0] trace_predecessor =
        (trace_state == ZERO_WORD) ? LAST_ENTRY : trace_state - ONE_WORD;
    wire [WORD_W-1:0] candidate_self =
        sat_add(path_metric[sweep_index], i_branch_self);
    wire [WORD_W-1:0] candidate_prev =
        sat_add(path_metric[acs_predecessor], i_branch_prev);
    wire select_self = candidate_self <= candidate_prev;
    wire [WORD_W-1:0] selected_metric =
        select_self ? candidate_self : candidate_prev;
    wire [WORD_W-1:0] selected_survivor =
        select_self ? ONE_WORD : TWO_WORD;

    // Traceback locks the survivor bank. Unsupported commands are backpressured.
    assign o_ready = i_ce &&
        (((i_cmd == CMD_ACS) && !scope_open) ||
         ((i_cmd == CMD_START) && !scope_open &&
          (sweep_index == ZERO_WORD) && (i_start_state < ENTRY_LIMIT)) ||
         ((i_cmd == CMD_TRACE) && scope_open) ||
         (i_cmd == CMD_END));

    wire accept = i_valid && o_ready;
    wire acs_fire = accept && (i_cmd == CMD_ACS);
    wire trace_fire = accept && (i_cmd == CMD_TRACE);

    assign o_trace_self = trace_fire && traceback_mem[trace_state][0];
    assign o_trace_prev = trace_fire && traceback_mem[trace_state][1];
    assign o_trace_state = trace_state;
    assign o_path_metric = path_metric[trace_state];

    wire [ENTRIES-1:0] survivor_legal;
    wire survivor_codes_legal = &survivor_legal;

    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : state_bank
            localparam [WORD_W-1:0] SLOT = g;
            initial begin
                path_metric[g] = (SLOT == ZERO_WORD) ? ZERO_WORD : INF_WORD;
                next_metric[g] = INF_WORD;
                traceback_mem[g] = ONE_WORD;
            end

            assign survivor_legal[g] =
                (traceback_mem[g] == ONE_WORD) ||
                (traceback_mem[g] == TWO_WORD);

            always @(posedge clk) begin
                if (acs_fire) begin
                    if (sweep_index == SLOT) begin
                        next_metric[g] <= selected_metric;
                        traceback_mem[g] <= selected_survivor;
                    end
                    // Commit a complete trellis layer, bypassing the final write.
                    if (sweep_index == LAST_ENTRY)
                        path_metric[g] <= (SLOT == LAST_ENTRY) ?
                                          selected_metric : next_metric[g];
                end
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (accept) begin
            // Once set, this also certifies that a previous clock sample exists.
            pv <= 1'b1;
            case (i_cmd)
                CMD_ACS: begin
                    if (sweep_index == LAST_ENTRY)
                        sweep_index <= ZERO_WORD;
                    else
                        sweep_index <= sweep_index + ONE_WORD;
                end
                CMD_START: begin
                    scope_open <= 1'b1;
                    trace_state <= i_start_state;
                end
                CMD_TRACE: begin
                    if (traceback_mem[trace_state][1])
                        trace_state <= trace_predecessor;
                end
                CMD_END: begin
                    scope_open <= 1'b0;
                end
            endcase
        end
    end

    // In the START-until-END window, the preceding cycle never took both edges.
    always @(posedge clk)
        if (pv && $past(scope_open))
            assert (!($past(o_trace_self) && $past(o_trace_prev)));
endmodule

module shift_request_pipeline #(
    parameter WORD_WIDTH = 32,
    parameter DEPTH = 12
) (
    input  wire                  clk,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [WORD_WIDTH-1:0] i_data,
    input  wire [WORD_WIDTH-1:0] i_shift,
    input  wire                  i_open_window,
    input  wire                  i_close_window,
    output wire                  o_valid,
    input  wire                  o_ready,
    output wire [WORD_WIDTH-1:0] o_data
);
    localparam [WORD_WIDTH-1:0] WORD_ZERO = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] WORD_ONE = {{(WORD_WIDTH-1){1'b0}}, 1'b1};
    localparam [WORD_WIDTH-1:0] WORD_ALL = {WORD_WIDTH{1'b1}};
    localparam [WORD_WIDTH-1:0] CAPACITY = DEPTH;

    reg [WORD_WIDTH-1:0] partial       [0:DEPTH-1];
    reg [WORD_WIDTH-1:0] remaining     [0:DEPTH-1];
    // Shadows record the earlier accepted request, not a recomputed result.
    reg [WORD_WIDTH-1:0] request_data  [0:DEPTH-1];
    reg [WORD_WIDTH-1:0] request_shift [0:DEPTH-1];
    reg [DEPTH-1:0] valid;
    reg [WORD_WIDTH-1:0] occupancy;
    reg window;
    reg past_valid;

    wire [WORD_WIDTH-1:0] processed_mask [0:DEPTH-1];
    wire [WORD_WIDTH-1:0] prior_operand;
    wire [WORD_WIDTH-1:0] prior_amount;
    wire advance;

    assign o_valid = valid[DEPTH-1];
    assign o_data = partial[DEPTH-1];
    assign prior_operand = request_data[DEPTH-1];
    assign prior_amount = request_shift[DEPTH-1];

    // Global pipeline stall: a blocked valid output freezes every entry.
    assign i_ready = !valid[DEPTH-1] || o_ready;
    assign advance = i_ready && (i_valid || o_ready);

    initial begin
        valid = {DEPTH{1'b0}};
        occupancy = WORD_ZERO;
        window = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (advance) begin
            valid <= {valid[DEPTH-2:0], i_valid};
            past_valid <= 1'b1;

            // Count actual admissions and departures, not valid-bit sums.
            case ({i_valid, valid[DEPTH-1]})
                2'b10: occupancy <= occupancy + WORD_ONE;
                2'b01: occupancy <= occupancy - WORD_ONE;
                default: occupancy <= occupancy;
            endcase

            // Q and R are accepted commands carrying the respective tag.
            // Without a closing command, the window remains armed forever.
            if (i_valid) begin
                if (i_close_window)
                    window <= 1'b0;
                else if (i_open_window)
                    window <= 1'b1;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin: shift_stage
            localparam [WORD_WIDTH-1:0] STAGE_MASK = WORD_ONE << g;
            localparam [WORD_WIDTH-1:0] DONE_MASK =
                (g == DEPTH-1) ? WORD_ALL :
                (WORD_ALL >> ((g < WORD_WIDTH) ? (WORD_WIDTH-g-1) : 0));

            assign processed_mask[g] = DONE_MASK;

            initial begin
                partial[g] = WORD_ZERO;
                remaining[g] = WORD_ZERO;
                request_data[g] = WORD_ZERO;
                request_shift[g] = WORD_ZERO;
            end

            if (g == 0) begin: admission
                always @(posedge clk) begin
                    if (advance) begin
                        if (i_valid) begin
                            partial[g] <= i_data >> (i_shift & STAGE_MASK);
                            remaining[g] <= i_shift & ~STAGE_MASK;
                            request_data[g] <= i_data;
                            request_shift[g] <= i_shift;
                        end else begin
                            partial[g] <= WORD_ZERO;
                            remaining[g] <= WORD_ZERO;
                            request_data[g] <= WORD_ZERO;
                            request_shift[g] <= WORD_ZERO;
                        end
                    end
                end
            end else if (g == DEPTH-1) begin: finish_shift
                // Consume all remaining amount bits in the final stage.
                always @(posedge clk) begin
                    if (advance) begin
                        partial[g] <= partial[g-1] >> remaining[g-1];
                        remaining[g] <= WORD_ZERO;
                        request_data[g] <= request_data[g-1];
                        request_shift[g] <= request_shift[g-1];
                    end
                end
            end else begin: consume_amount_bit
                always @(posedge clk) begin
                    if (advance) begin
                        partial[g] <= partial[g-1] >> (remaining[g-1] & STAGE_MASK);
                        remaining[g] <= remaining[g-1] & ~STAGE_MASK;
                        request_data[g] <= request_data[g-1];
                        request_shift[g] <= request_shift[g-1];
                    end
                end
            end
        end
    endgenerate

    // During the latched window, a changed valid result requires a change
    // in the shadow of the earlier request. Identical request shadows must
    // not produce a changed result.
    always @(posedge clk) begin
        if (past_valid && window && o_valid &&
            $stable(prior_operand) && $stable(prior_amount))
            assert ($stable(o_data));
    end
endmodule

module display_qos_arbiter #(
    parameter integer NUM_RT = 32,
    parameter [63:0] BYTE_BUDGET = 64'd8,
    parameter [63:0] PERIOD_CYCLES = 64'd8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [NUM_RT-1:0]     i_requests,
    input  wire                  i_background_request,
    input  wire [63:0]           i_bytes,
    output reg                   rt_grant,
    output reg                   background_grant,
    output reg  [63:0]           grant_index,
    output reg  [63:0]           grant_bytes
);
    // Each accepted input is an arbitration round. Outputs retain its result.
    // The renewal slot applies back-pressure rather than accepting a round.
    reg [63:0] period_timer;
    reg [NUM_RT*64-1:0] consumed_bytes;
    reg [NUM_RT*64-1:0] remaining_bytes;
    reg pv;

    wire active = i_ce && i_valid;
    wire renewal = (period_timer == PERIOD_CYCLES - 64'd1);
    assign i_ready = i_ce && !renewal;

    reg credit_found;
    reg consumed_found;
    reg [63:0] winner_index;
    wire [NUM_RT-1:0] accounting_ok;

    initial begin
        period_timer = 64'd0;
        rt_grant = 1'b0;
        background_grant = 1'b0;
        grant_index = 64'd0;
        grant_bytes = 64'd0;
        pv = 1'b0;
    end

    // Lowest numbered eligible real-time requester has priority.
    // The real-time and background paths use the two accounting views.
    always @(*) begin
        credit_found = 1'b0;
        consumed_found = 1'b0;
        winner_index = 64'd0;
        for (integer n = 0; n < NUM_RT; n = n + 1) begin
            if (i_requests[n] && (i_bytes != 64'd0)) begin
                if (i_bytes <= remaining_bytes[n*64 +: 64]) begin
                    if (!credit_found)
                        winner_index = n;
                    credit_found = 1'b1;
                end
                if ((consumed_bytes[n*64 +: 64] <= BYTE_BUDGET) &&
                    (i_bytes <= BYTE_BUDGET - consumed_bytes[n*64 +: 64]))
                    consumed_found = 1'b1;
            end
        end
    end

    generate
        for (genvar g = 0; g < NUM_RT; g = g + 1) begin : accounts
            localparam [63:0] REQUEST_ID = g;

            assign accounting_ok[g] =
                (consumed_bytes[g*64 +: 64] <= BYTE_BUDGET) &&
                (remaining_bytes[g*64 +: 64] <= BYTE_BUDGET) &&
                (remaining_bytes[g*64 +: 64] ==
                    BYTE_BUDGET - consumed_bytes[g*64 +: 64]);

            initial begin
                consumed_bytes[g*64 +: 64] = 64'd0;
                remaining_bytes[g*64 +: 64] = BYTE_BUDGET;
            end

            always @(posedge clk) begin
                if (active) begin
                    if (renewal) begin
                        consumed_bytes[g*64 +: 64] <= 64'd0;
                        remaining_bytes[g*64 +: 64] <= BYTE_BUDGET;
                    end else if (credit_found && (winner_index == REQUEST_ID)) begin
                        consumed_bytes[g*64 +: 64] <=
                            consumed_bytes[g*64 +: 64] + i_bytes;
                        remaining_bytes[g*64 +: 64] <=
                            remaining_bytes[g*64 +: 64] - i_bytes;
                    end
                end
            end
        end
    endgenerate

    // The regulation timer counts enabled rounds, including renewal slots.
    // Neither a stalled sender nor a disabled arbiter changes any state.
    always @(posedge clk) begin
        if (active) begin
            pv <= 1'b1;
            if (renewal) begin
                period_timer <= 64'd0;
            end else begin
                period_timer <= period_timer + 64'd1;
                rt_grant <= credit_found;
                background_grant <= i_background_request && !consumed_found;
                grant_index <= credit_found ? winner_index : 64'd0;
                grant_bytes <= i_bytes;
            end
        end
    end

    // Absence of overlapping grants, checked whenever either grant rises.
    always @(posedge clk) begin
        if (pv && ($rose(rt_grant) || $rose(background_grant)))
            assert (!(rt_grant && background_grant));
    end
endmodule

module stream_window_budget #(
    parameter integer WORD_BITS = 128,
    parameter integer LINE_WORDS = 8,
    parameter integer K = 8
) (
    input wire i_clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_scope_begin,
    input wire i_scope_end,
    input wire i_request,
    input wire [WORD_BITS-1:0] i_pixel,
    output reg o_done,
    output wire [WORD_BITS*K*K-1:0] o_window
);
    localparam integer ROW_W = (K > 1) ? $clog2(K) : 1;
    localparam integer COL_W = (LINE_WORDS > 1) ? $clog2(LINE_WORDS) : 1;
    localparam integer BUDGET_W = $clog2(K + 2);

    localparam [WORD_BITS-1:0] WORD_ZERO = {WORD_BITS{1'b0}};
    localparam [ROW_W-1:0] ROW_ZERO = {ROW_W{1'b0}};
    localparam [ROW_W-1:0] ROW_ONE = {{(ROW_W-1){1'b0}}, 1'b1};
    localparam [ROW_W-1:0] LAST_ROW = K - 1;
    localparam [COL_W-1:0] COL_ZERO = {COL_W{1'b0}};
    localparam [COL_W-1:0] COL_ONE = {{(COL_W-1){1'b0}}, 1'b1};
    localparam [COL_W-1:0] LAST_COLUMN = LINE_WORDS - 1;
    localparam [BUDGET_W-1:0] BUDGET_ZERO = {BUDGET_W{1'b0}};
    localparam [BUDGET_W-1:0] BUDGET_ONE = {{(BUDGET_W-1){1'b0}}, 1'b1};
    localparam [BUDGET_W-1:0] ROW_LIMIT = K;
    localparam [BUDGET_W-1:0] RESPONSE_LIMIT = K + 1;

    // Each line buffer stores eight raster pixels at the default size.
    // Each window row also contains eight 128-bit pixels.
    reg [WORD_BITS-1:0] line_buffer [0:K-2][0:LINE_WORDS-1];
    reg [WORD_BITS-1:0] window_pixels [0:K-1][0:K-1];
    reg [WORD_BITS-1:0] carry_pixel;
    reg [ROW_W-1:0] row_index;
    reg [COL_W-1:0] column_index;
    reg [BUDGET_W-1:0] row_budget;
    reg [BUDGET_W-1:0] response_budget;
    reg assembling;
    reg outstanding;
    reg scope_active;

    initial begin
        carry_pixel = WORD_ZERO;
        row_index = ROW_ZERO;
        column_index = COL_ZERO;
        row_budget = BUDGET_ZERO;
        response_budget = BUDGET_ZERO;
        assembling = 1'b0;
        outstanding = 1'b0;
        scope_active = 1'b0;
        o_done = 1'b0;
        for (integer r = 0; r < K-1; r = r + 1)
            for (integer c = 0; c < LINE_WORDS; c = c + 1)
                line_buffer[r][c] = WORD_ZERO;
        for (integer r = 0; r < K; r = r + 1)
            for (integer c = 0; c < K; c = c + 1)
                window_pixels[r][c] = WORD_ZERO;
    end

    genvar gr, gc;
    generate
        for (gr = 0; gr < K; gr = gr + 1) begin : g_row
            for (gc = 0; gc < K; gc = gc + 1) begin : g_column
                assign o_window[((gr*K+gc)*WORD_BITS) +: WORD_BITS]
                    = window_pixels[gr][gc];
            end
        end
    endgenerate

    // One enabled cycle updates one neighborhood row.  The final enabled
    // cycle publishes completion.  Requests presented while busy are ignored.
    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_reset) begin
                carry_pixel <= WORD_ZERO;
                row_index <= ROW_ZERO;
                column_index <= COL_ZERO;
                row_budget <= BUDGET_ZERO;
                response_budget <= BUDGET_ZERO;
                assembling <= 1'b0;
                outstanding <= 1'b0;
                scope_active <= 1'b0;
                o_done <= 1'b0;
                for (integer r = 0; r < K-1; r = r + 1)
                    for (integer c = 0; c < LINE_WORDS; c = c + 1)
                        line_buffer[r][c] <= WORD_ZERO;
                for (integer r = 0; r < K; r = r + 1)
                    for (integer c = 0; c < K; c = c + 1)
                        window_pixels[r][c] <= WORD_ZERO;
            end else begin
                if (i_scope_end)
                    scope_active <= 1'b0;
                else if (i_scope_begin)
                    scope_active <= 1'b1;

                o_done <= 1'b0;
                if (!outstanding) begin
                    if (i_request) begin
                        carry_pixel <= i_pixel;
                        row_index <= ROW_ZERO;
                        row_budget <= ROW_LIMIT;
                        response_budget <= RESPONSE_LIMIT;
                        assembling <= 1'b1;
                        outstanding <= 1'b1;
                    end
                end else begin
                    if (response_budget != BUDGET_ZERO)
                        response_budget <= response_budget - BUDGET_ONE;

                    if (assembling) begin
                        if (row_budget != BUDGET_ZERO)
                            row_budget <= row_budget - BUDGET_ONE;

                        // Shift the selected horizontal neighborhood row.
                        // Clear its left padding at each raster-line boundary.
                        for (integer c = 0; c < K-1; c = c + 1) begin
                            if (column_index == COL_ZERO)
                                window_pixels[row_index][c] <= WORD_ZERO;
                            else
                                window_pixels[row_index][c]
                                    <= window_pixels[row_index][c+1];
                        end
                        window_pixels[row_index][K-1] <= carry_pixel;

                        // Read-before-write cascades pixels through line delays.
                        if (row_index != LAST_ROW) begin
                            carry_pixel <= line_buffer[row_index][column_index];
                            line_buffer[row_index][column_index] <= carry_pixel;
                            row_index <= row_index + ROW_ONE;
                        end else begin
                            assembling <= 1'b0;
                        end
                    end else begin
                        outstanding <= 1'b0;
                        o_done <= 1'b1;
                        if (column_index == LAST_COLUMN)
                            column_index <= COL_ZERO;
                        else
                            column_index <= column_index + COL_ONE;
                    end
                end
            end
        end
    end

    // Deadlines count enabled cycles, including all row updates and commit.
    always @(posedge i_clk) begin
        if (scope_active) begin
            assert (!assembling || (row_budget != BUDGET_ZERO));
            assert (!outstanding || (response_budget != BUDGET_ZERO));
        end
    end
endmodule

module csr_window_quota #(
    parameter integer WORD_W = 32,
    parameter [WORD_W-1:0] QUOTA = WORD_W'(8)
) (
    input wire clk,
    input wire i_ce,
    input wire i_reset,
    input wire i_window_open,
    input wire i_window_close,
    input wire i_csr_write,
    output wire [WORD_W-1:0] o_used,
    output wire [WORD_W-1:0] o_overruns
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};

    reg window;
    reg past_valid;
    reg [WORD_W-1:0] used_count;
    reg [WORD_W-1:0] overrun_count;
    reg [WORD_W-1:0] permit_word;

    reg window_next;
    reg [WORD_W-1:0] used_next;
    reg [WORD_W-1:0] overrun_next;

    initial begin
        window = 1'b0;
        past_valid = 1'b0;
        used_count = ZERO;
        overrun_count = ZERO;
        permit_word = {WORD_W{1'b1}};
    end

    always @(*) begin
        window_next = window;
        used_next = used_count;
        overrun_next = overrun_count;

        if (i_window_close) begin
            window_next = 1'b0;
            used_next = ZERO;
            overrun_next = ZERO;
        end else if (i_window_open && !window) begin
            window_next = 1'b1;
            used_next = ZERO;
            overrun_next = ZERO;
        end else if (window && i_csr_write && permit_word[0]) begin
            used_next = used_count + ONE;
            // Diagnostic accounting for an accepted write beyond the quota.
            if (used_count >= QUOTA)
                overrun_next = overrun_count + ONE;
        end
    end

    // A combinational NAND bank computes the permission for the next state.
    wire [WORD_W-1:0] active_mask = {WORD_W{window_next}};
    wire [WORD_W-1:0] quota_mask = {WORD_W{used_next >= QUOTA}};
    wire [WORD_W-1:0] nand_permission = ~(active_mask & quota_mask);

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_reset) begin
                window <= 1'b0;
                past_valid <= 1'b0;
                used_count <= ZERO;
                overrun_count <= ZERO;
                permit_word <= {WORD_W{1'b1}};
            end else begin
                window <= window_next;
                past_valid <= 1'b1;
                used_count <= used_next;
                overrun_count <= overrun_next;
                permit_word <= nand_permission;
            end
        end
    end

    assign o_used = used_count;
    assign o_overruns = overrun_count;

    // Within an established window, quota use is bounded and the
    // overrun tally cannot change while the window guard stays unchanged.
    always @(posedge clk) begin
        if (past_valid && window && $stable(window))
            assert ((used_count <= QUOTA) && $stable(overrun_count));
    end
endmodule

module debug_funnel_reader #(
    parameter integer WORD_BITS = 64
) (
    input  wire                 clk,
    input  wire                 cmd_valid,
    output wire                 cmd_ready,
    input  wire [WORD_BITS-1:0]  cmd_lo,
    input  wire [WORD_BITS-1:0]  cmd_hi,
    input  wire [WORD_BITS-1:0]  cmd_offset,
    output wire                 rsp_valid,
    input  wire                 rsp_ready,
    output wire [WORD_BITS-1:0]  rsp_data
);
    typedef enum logic [1:0] {
        PARKED   = 2'b00,
        ARMED    = 2'b01,
        RESPONSE = 2'b10
    } state_t;

    localparam logic [WORD_BITS-1:0] WORD_LIMIT = WORD_BITS;

    state_t state;
    logic window_open;
    logic [WORD_BITS-1:0] source_lo;
    logic [WORD_BITS-1:0] source_hi;
    logic [WORD_BITS-1:0] shift_amt;
    logic [WORD_BITS-1:0] staged_word;
    logic [WORD_BITS-1:0] response_word;

    wire [WORD_BITS-1:0] normalized_offset;
    wire [(2*WORD_BITS)-1:0] incoming_shifted;
    wire [(2*WORD_BITS)-1:0] stored_shifted;
    wire [WORD_BITS-1:0] incoming_funnel;
    wire [WORD_BITS-1:0] funnel_word;

    assign normalized_offset = cmd_offset % WORD_LIMIT;

    // Combinational funnel shifters: select a word across two adjacent words.
    assign incoming_shifted = {cmd_hi, cmd_lo} >> normalized_offset;
    assign incoming_funnel = incoming_shifted[WORD_BITS-1:0];
    assign stored_shifted = {source_hi, source_lo} >> shift_amt;
    assign funnel_word = stored_shifted[WORD_BITS-1:0];

    assign cmd_ready = (state == PARKED) || (state == ARMED);
    assign rsp_valid = (state == RESPONSE);
    assign rsp_data = response_word;

    initial begin
        state = PARKED;
        window_open = 1'b0;
        source_lo = {WORD_BITS{1'b0}};
        source_hi = {WORD_BITS{1'b0}};
        shift_amt = {WORD_BITS{1'b0}};
        staged_word = {WORD_BITS{1'b0}};
        response_word = {WORD_BITS{1'b0}};
    end

    // Two-beat debug command: capture the field description, then commit it.
    // Q is the capture handshake; R is the response-consumption handshake.
    always @(posedge clk) begin
        case (state)
            PARKED: begin
                if (cmd_valid && cmd_ready) begin
                    source_lo <= cmd_lo;
                    source_hi <= cmd_hi;
                    shift_amt <= normalized_offset;
                    staged_word <= incoming_funnel;
                    window_open <= 1'b1;
                    state <= ARMED;
                end
            end
            ARMED: begin
                if (cmd_valid && cmd_ready) begin
                    response_word <= staged_word;
                    state <= RESPONSE;
                end
            end
            RESPONSE: begin
                if (rsp_valid && rsp_ready) begin
                    window_open <= 1'b0;
                    state <= PARKED;
                end
            end
            default: begin
            end
        endcase
    end

    // Throughout an open transaction, any presented response agrees with
    // extraction from the retained source words and offset.
    assert property (!(window_open && (state == RESPONSE)) ||
                     (response_word == funnel_word));
endmodule

module thermal_refresh_adjuster #(
    parameter integer WORD_W = 32,
    parameter integer TABLE_ENTRIES = 128,
    parameter [WORD_W-1:0] POLL_PERIOD = 32'd8,
    parameter [WORD_W-1:0] MR_LATENCY = 32'd4,
    parameter [WORD_W-1:0] BASE_REFRESH_INTERVAL = 32'd4096
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_begin_window,
    input  wire                  i_end_window,
    input  wire                  i_mr_ready,
    input  wire [WORD_W-1:0]     i_mr_temperature,
    output wire                  o_mr_request,
    output wire                  o_mr_sample,
    output wire [WORD_W-1:0]     o_last_temperature,
    output wire [WORD_W-1:0]     o_refresh_multiplier,
    output wire [WORD_W-1:0]     o_refresh_interval
);
    localparam [WORD_W-1:0] TABLE_SIZE = TABLE_ENTRIES;

    // Fully populated, immutable calibration table: hotter codes request
    // progressively faster refresh. Each entry has its own valid bit.
    reg [WORD_W-1:0] multiplier_table [0:TABLE_ENTRIES-1];
    reg [TABLE_ENTRIES-1:0] profile_valid;
    reg [WORD_W-1:0] profile_count;

    reg [WORD_W-1:0] poll_timer;
    reg [WORD_W-1:0] service_left;
    reg [WORD_W-1:0] deadline;
    reg [WORD_W-1:0] last_temperature;
    reg [WORD_W-1:0] active_multiplier;
    reg poll_pending;
    reg scope_window;

    function [WORD_W-1:0] initial_multiplier;
        input [WORD_W-1:0] code;
        begin
            if (code < TABLE_SIZE / 32'd4)
                initial_multiplier = 32'd1;
            else if (code < TABLE_SIZE / 32'd2)
                initial_multiplier = 32'd2;
            else if (code < (TABLE_SIZE * 32'd3) / 32'd4)
                initial_multiplier = 32'd4;
            else
                initial_multiplier = 32'd8;
        end
    endfunction

    genvar entry;
    generate
        for (entry = 32'd0; entry < TABLE_ENTRIES; entry = entry + 32'd1) begin : init_profiles
            initial begin
                multiplier_table[entry] = initial_multiplier(entry);
                profile_valid[entry] = 1'b1;
            end
        end
    endgenerate

    initial begin
        profile_count = TABLE_SIZE;
        poll_timer = POLL_PERIOD - 32'd1;
        service_left = 32'd0;
        deadline = 32'd0;
        last_temperature = 32'd0;
        active_multiplier = initial_multiplier(32'd0);
        poll_pending = 1'b0;
        scope_window = 1'b0;
    end

    wire [WORD_W-1:0] response_code;
    assign response_code = i_mr_temperature % TABLE_SIZE;

    // A request is accepted on o_mr_request && i_mr_ready.
    // The mode-register transport returns data after MR_LATENCY enabled
    // cycles. Its service timer and the watchdog have separate state.
    assign o_mr_request = i_ce && !poll_pending &&
                          (poll_timer == 32'd0) &&
                          (profile_count == TABLE_SIZE);
    assign o_mr_sample = i_ce && poll_pending &&
                         (service_left == 32'd1);
    assign o_last_temperature = last_temperature;
    assign o_refresh_multiplier = active_multiplier;
    assign o_refresh_interval =
        (active_multiplier == 32'd1) ? BASE_REFRESH_INTERVAL :
        (active_multiplier == 32'd2) ? (BASE_REFRESH_INTERVAL >> 32'd1) :
        (active_multiplier == 32'd4) ? (BASE_REFRESH_INTERVAL >> 32'd2) :
                                      (BASE_REFRESH_INTERVAL >> 32'd3);

    always @(posedge clk) begin
        if (i_ce) begin
            // Q opens the checking scope; R closes it. Without R it stays open.
            if (i_end_window)
                scope_window <= 1'b0;
            else if (i_begin_window)
                scope_window <= 1'b1;

            if (poll_pending) begin
                if (service_left == 32'd1) begin
                    poll_pending <= 1'b0;
                    service_left <= 32'd0;
                    deadline <= 32'd0;
                    if (profile_valid[response_code]) begin
                        last_temperature <= response_code;
                        active_multiplier <= multiplier_table[response_code];
                    end
                end else begin
                    service_left <= service_left - 32'd1;
                    deadline <= deadline - 32'd1;
                end
            end else if (poll_timer != 32'd0) begin
                poll_timer <= poll_timer - 32'd1;
            end else if (o_mr_request && i_mr_ready) begin
                poll_pending <= 1'b1;
                service_left <= MR_LATENCY;
                deadline <= MR_LATENCY + 32'd1;
                poll_timer <= POLL_PERIOD - 32'd1;
            end
        end
    end

    // Bounded response in enabled cycles: the watchdog cannot expire
    // while an accepted temperature read remains outstanding in the scope.
    always @(posedge clk)
        if (scope_window && poll_pending)
            assert (deadline != 32'd0);
endmodule

module residue_capture_latch #(
    parameter integer DATA_W = 32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_gate,
    input  wire                  i_begin_epoch,
    input  wire [DATA_W-1:0]     i_residue,
    output wire [DATA_W-1:0]     o_coeff
);
    reg                      gate_open;
    reg [DATA_W-1:0]         drive_coeff;
    reg [DATA_W-1:0]         held_coeff;
    reg [DATA_W-1:0]         prior_coeff;
    reg                      sealed;
    reg                      armed;

    initial begin
        gate_open  = 1'b0;
        drive_coeff = {DATA_W{1'b0}};
        held_coeff  = {DATA_W{1'b0}};
        prior_coeff = {DATA_W{1'b0}};
        sealed      = 1'b0;
        armed       = 1'b0;
    end

    // Synchronously driven active-high latch. The transparent path passes
    // its registered D while open; the keeper preserves the last D on close.
    assign o_coeff = gate_open ? drive_coeff : held_coeff;

    always @(posedge clk) begin
        if (i_ce) begin
            gate_open <= i_gate;
            sealed <= gate_open && !i_gate;

            if (i_begin_epoch)
                armed <= 1'b1;

            if (i_gate) begin
                drive_coeff <= i_residue;
                // Record the coefficient accepted before a later closure.
                prior_coeff <= i_residue;
            end

            // Includes the edge that lowers gate_open. D does not change
            // on that edge, so closing the gate preserves its last value.
            if (gate_open)
                held_coeff <= drive_coeff;
        end
    end

    // After the epoch begins, a closed capture must match the earlier sample.
    always @(posedge clk)
        assert (!(armed && sealed) || (o_coeff == prior_coeff));
endmodule

module elevator_probe #(
    parameter integer FLOORS = 32'd32,
    parameter integer WORD_WIDTH = 32'd64
) (
    input  wire clk,
    input  wire i_ce,
    input  wire [FLOORS-1:0] call_mask,
    output reg  [WORD_WIDTH-1:0] current_floor,
    output reg  direction_up,
    output reg  door_open,
    output reg  moving
);
    localparam [WORD_WIDTH-1:0] ZERO = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] ONE = {{(WORD_WIDTH-1){1'b0}}, 1'b1};
    localparam [WORD_WIDTH-1:0] FLOOR_LIMIT = WORD_WIDTH'(FLOORS);
    localparam [FLOORS-1:0] FLOOR_ONE = {{(FLOORS-1){1'b0}}, 1'b1};

    reg [WORD_WIDTH-1:0] target_floor;
    reg [WORD_WIDTH-1:0] steps_left;
    reg [FLOORS-1:0] pending;
    reg armed;

    initial begin
        current_floor = ZERO;
        target_floor = ZERO;
        steps_left = ZERO;
        direction_up = 1'b1;
        pending = {FLOORS{1'b0}};
        door_open = 1'b0;
        moving = 1'b0;
        armed = 1'b0;
    end

    // At a stop, acknowledge calls for the current floor.
    wire [FLOORS-1:0] current_floor_mask = FLOOR_ONE << current_floor;
    wire [FLOORS-1:0] arrivals = pending | call_mask;
    wire [FLOORS-1:0] queued = (steps_left == ZERO)
        ? (arrivals & ~current_floor_mask) : arrivals;

    // Lowest-floor-first dispatch among pending calls.
    function automatic [WORD_WIDTH-1:0] select_floor;
        input [FLOORS-1:0] requests;
        integer f;
        begin
            select_floor = ZERO;
            for (f = FLOORS - 32'd1; f >= 32'sd0; f = f - 32'sd1)
                if (requests[f])
                    select_floor = WORD_WIDTH'(f);
        end
    endfunction

    wire have_request = |queued;
    wire [WORD_WIDTH-1:0] selected_floor = select_floor(queued);

    always @(posedge clk) begin
        if (i_ce) begin
            pending <= queued;

            // Q is the first enabled sampling of a nonempty call mask.
            armed <= armed || (|call_mask);

            // Registered door and motion controls use two trip representations.
            door_open <= (current_floor == target_floor);
            moving <= (steps_left != ZERO);

            if (steps_left != ZERO) begin
                steps_left <= steps_left - ONE;
                if (direction_up)
                    current_floor <= current_floor + ONE;
                else
                    current_floor <= current_floor - ONE;
            end else if (have_request) begin
                target_floor <= selected_floor;
                direction_up <= (selected_floor > current_floor);
                if (selected_floor > current_floor)
                    steps_left <= selected_floor - current_floor;
                else
                    steps_left <= current_floor - selected_floor;
            end
        end
    end

    always @(*) begin
        if (armed)
            assert (!(door_open && moving));
    end
endmodule

module test_wave_quadrant #(
    parameter integer ROM_ENTRIES = 32'd16
) (
    input  wire               clk,
    input  wire               i_ce,
    input  wire               i_req_valid,
    output wire               o_req_ready,
    input  wire [31:0]        i_phase,
    input  wire               i_cosine,
    input  wire               i_cfg_load,
    input  wire [31:0]        i_phase_bias,
    input  wire               i_end_run,
    output reg signed [31:0]  o_sample,
    output reg                o_sample_valid
);
    localparam [31:0] QUARTER_SIZE = ROM_ENTRIES;
    localparam [31:0] HALF_PERIOD = QUARTER_SIZE + QUARTER_SIZE;
    localparam [31:0] FULL_PERIOD = HALF_PERIOD + HALF_PERIOD;

    reg [31:0] sine_rom [0:ROM_ENTRIES-1];
    reg [31:0] phase_bias;
    reg [31:0] phase_q;
    reg [31:0] folded_addr;
    reg [31:0] magnitude_q;
    reg [31:0] countdown;
    reg sample_negative;
    reg busy;
    reg fold_pending;
    reg read_pending;
    reg sign_pending;
    reg scope_open;
    reg pv;

    function [31:0] quadrant_word;
        input [31:0] slot;
        begin
            case (slot)
                32'd0:  quadrant_word = 32'd1608;
                32'd1:  quadrant_word = 32'd4808;
                32'd2:  quadrant_word = 32'd7962;
                32'd3:  quadrant_word = 32'd11039;
                32'd4:  quadrant_word = 32'd14010;
                32'd5:  quadrant_word = 32'd16846;
                32'd6:  quadrant_word = 32'd19520;
                32'd7:  quadrant_word = 32'd22006;
                32'd8:  quadrant_word = 32'd24279;
                32'd9:  quadrant_word = 32'd26320;
                32'd10: quadrant_word = 32'd28106;
                32'd11: quadrant_word = 32'd29622;
                32'd12: quadrant_word = 32'd30852;
                32'd13: quadrant_word = 32'd31786;
                32'd14: quadrant_word = 32'd32413;
                default: quadrant_word = 32'd32728;
            endcase
        end
    endfunction

    integer init_word;
    initial begin
        for (init_word = 32'd0; init_word < ROM_ENTRIES;
             init_word = init_word + 32'd1)
            sine_rom[init_word] =
                quadrant_word((init_word * 32'd16) / ROM_ENTRIES);
        phase_bias = 32'd0;
        phase_q = 32'd0;
        folded_addr = 32'd0;
        magnitude_q = 32'd0;
        countdown = 32'd0;
        sample_negative = 1'b0;
        busy = 1'b0;
        fold_pending = 1'b0;
        read_pending = 1'b0;
        sign_pending = 1'b0;
        scope_open = 1'b1;
        pv = 1'b0;
        o_sample = 32'sd0;
        o_sample_valid = 1'b0;
    end

    wire [31:0] phase_mod = phase_q % FULL_PERIOD;
    wire [31:0] quadrant_offset = phase_mod % QUARTER_SIZE;
    wire reflect_address =
        ((phase_mod / QUARTER_SIZE) & 32'd1) != 32'd0;
    wire [31:0] next_folded_addr = reflect_address
        ? QUARTER_SIZE - 32'd1 - quadrant_offset
        : quadrant_offset;
    wire next_negative = phase_mod >= HALF_PERIOD;

    // Requests are back-pressured during computation or configuration loads.
    assign o_req_ready = i_ce && !busy && !i_cfg_load;
    wire accept_request = i_req_valid && o_req_ready;

    // A response is produced within three enabled computation cycles.
    // The registered result remains available until another request is accepted.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (i_end_run)
                scope_open <= 1'b0;
            if (i_cfg_load)
                phase_bias <= i_phase_bias;

            if (busy) begin
                countdown <= countdown - 32'd1;
                if (fold_pending) begin
                    folded_addr <= next_folded_addr;
                    sample_negative <= next_negative;
                    fold_pending <= 1'b0;
                    read_pending <= 1'b1;
                end else if (read_pending) begin
                    magnitude_q <= sine_rom[folded_addr];
                    read_pending <= 1'b0;
                    sign_pending <= 1'b1;
                end else if (sign_pending) begin
                    o_sample <= sample_negative
                        ? (32'd0 - magnitude_q) : magnitude_q;
                    o_sample_valid <= 1'b1;
                    sign_pending <= 1'b0;
                    busy <= 1'b0;
                    countdown <= 32'd0;
                end
            end else if (accept_request) begin
                phase_q <= i_phase + phase_bias
                           + (i_cosine ? QUARTER_SIZE : 32'd0);
                fold_pending <= 1'b1;
                read_pending <= 1'b0;
                sign_pending <= 1'b0;
                busy <= 1'b1;
                countdown <= 32'd3;
                o_sample_valid <= 1'b0;
            end
        end
    end

    // Check the previous enabled cycle: if its deadline expires now,
    // its request must no longer be outstanding. Scope ends at i_end_run.
    always @(posedge clk) begin
        if (pv && $past(scope_open) && $past(busy) && $past(i_ce))
            assert (($past(countdown) > 32'd1) || !busy);
    end
endmodule

module spread_pwm_buffer #(
    parameter [63:0] TABLE_DEPTH = 64'd32,
    parameter [63:0] NOMINAL_PERIOD = 64'd8
) (
    input  wire        clk,
    input  wire        req_valid,
    output wire        req_ready,
    input  wire [63:0] req_base_adjust,
    input  wire [63:0] req_dither_depth,
    input  wire        req_open_window,
    input  wire        close_window,
    output wire        pwm_valid,
    input  wire        pwm_ready,
    output wire [63:0] pwm_data,
    output wire        done
);
    // Supported parameters: NOMINAL_PERIOD >= 1 and
    // NOMINAL_PERIOD + 10 <= TABLE_DEPTH, without 64-bit overflow.
    // One request builds one buffered PWM period. Output transfers are
    // enabled sample clocks; back-pressure stretches, rather than loses,
    // samples. Completion takes at most NOMINAL_PERIOD + 10 such clocks.
    reg [63:0] base_period;
    reg [63:0] dither_depth;
    reg [63:0] dither_offset;
    reg [63:0] prng;
    reg [63:0] period_length;
    reg [63:0] period_counter;
    reg [63:0] countdown;
    reg pending;
    reg scope_window;

    reg [63:0] samples [64'd0:TABLE_DEPTH-64'd1];
    reg [TABLE_DEPTH-64'd1:64'd0] sample_valid;

    wire [63:0] next_base = NOMINAL_PERIOD + {61'd0, req_base_adjust[2:0]};
    wire [63:0] next_depth = {62'd0, req_dither_depth[1:0]};
    wire [63:0] next_dither = prng & next_depth;
    wire [63:0] next_period = next_base + next_dither;

    assign req_ready = !pending;
    assign pwm_valid = pending;
    assign pwm_data = pending ? samples[period_counter] : 64'd0;

    wire accept = req_valid && req_ready;
    wire emit_sample = pwm_valid && pwm_ready;
    wire last_sample = (period_counter + 64'd1 == period_length);
    assign done = emit_sample && last_sample;

    initial begin
        base_period = NOMINAL_PERIOD;
        dither_depth = 64'd3;
        dither_offset = 64'd0;
        prng = 64'h0000000000000001;
        period_length = NOMINAL_PERIOD;
        period_counter = 64'd0;
        countdown = 64'd0;
        pending = 1'b0;
        scope_window = 1'b0;
        sample_valid = {TABLE_DEPTH{1'b0}};
    end

    always @(posedge clk) begin
        // Q: an accepted request explicitly opens the checking window.
        // R: a completed period explicitly closes it. R need never occur.
        if (accept && req_open_window)
            scope_window <= 1'b1;
        else if (done && close_window)
            scope_window <= 1'b0;

        if (accept) begin
            base_period <= next_base;
            dither_depth <= next_depth;
            dither_offset <= next_dither;
            period_length <= next_period;
            period_counter <= 64'd0;
            countdown <= next_period;
            pending <= 1'b1;
            prng <= {prng[62:0], prng[63] ^ prng[62] ^ prng[60] ^ prng[59]};
        end else if (emit_sample) begin
            countdown <= countdown - 64'd1;
            if (last_sample) begin
                pending <= 1'b0;
                period_counter <= 64'd0;
            end else begin
                period_counter <= period_counter + 64'd1;
            end
        end
    end

    // A period is a table of ordered, fixed-index samples, not a FIFO.
    // The validity bitmap identifies precisely the unconsumed suffix.
    wire [TABLE_DEPTH-64'd1:64'd0] slot_ok;
    wire [63:0] valid_prefix [64'd0:TABLE_DEPTH];
    wire [63:0] filled_count = valid_prefix[TABLE_DEPTH];
    assign valid_prefix[64'd0] = 64'd0;

    genvar g;
    generate
        for (g = 32'd0; g < TABLE_DEPTH; g = g + 32'd1) begin : sample_slots
            localparam [63:0] SLOT = g;
            initial samples[g] = 64'd0;

            always @(posedge clk) begin
                if (accept) begin
                    sample_valid[g] <= (SLOT < next_period);
                    samples[g] <= (SLOT < (next_base >> 64'd1)) ? 64'd1 : 64'd0;
                end else if (emit_sample && period_counter == SLOT) begin
                    sample_valid[g] <= 1'b0;
                end
            end

            assign valid_prefix[g + 32'd1] = valid_prefix[g]
                + {63'd0, sample_valid[g]};
            assign slot_ok[g] =
                (sample_valid[g] ==
                    (pending && period_counter <= SLOT && SLOT < period_length))
                && (!sample_valid[g] ||
                    samples[g] == ((SLOT < (base_period >> 64'd1)) ? 64'd1 : 64'd0));
        end
    endgenerate

    // No accepted request may exhaust its completion budget while pending
    // inside the latched scope. Only successful sample transfers spend it.
    always @(posedge clk)
        assert (!scope_window || !pending || countdown != 64'd0);
endmodule

module axi_qos_byte_regulator #(
    parameter integer DATA_W = 128,
    parameter integer BURST_BEATS = 4,
    parameter integer MAX_LATENCY = 8,
    parameter integer RATE_DIV = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_scope_open,
    input  wire i_scope_close,
    input  wire i_cfg_valid,
    input  wire [$clog2(DATA_W/8 + 1)-1:0] i_cfg_rate,
    input  wire [$clog2(BURST_BEATS*(DATA_W/8) + 1)-1:0] i_cfg_burst,
    input  wire [$clog2(MAX_LATENCY + 1)-1:0] i_cfg_latency,
    input  wire [3:0] i_cfg_qos,
    input  wire i_req_valid,
    input  wire [DATA_W-1:0] i_req_data,
    output wire o_req_ready,
    output wire o_launch,
    output wire [DATA_W-1:0] o_data,
    output wire [3:0] o_axqos
);
    localparam integer BEAT_BYTES = DATA_W / 8;
    localparam integer RATE_W = $clog2(BEAT_BYTES + 1);
    localparam integer BUDGET_W = $clog2(BURST_BEATS * BEAT_BYTES + 1);
    localparam integer LAT_W = $clog2(MAX_LATENCY + 1);
    localparam integer MIN_RATE_BYTES = (BEAT_BYTES + RATE_DIV - 1) / RATE_DIV;
    localparam integer MIN_LATENCY = (BEAT_BYTES + MIN_RATE_BYTES - 1) / MIN_RATE_BYTES + 2;
    localparam integer CALC_W = BUDGET_W + LAT_W + RATE_W + 1;

    localparam [RATE_W-1:0] RATE_MIN = RATE_W'(MIN_RATE_BYTES);
    localparam [RATE_W-1:0] RATE_MAX = RATE_W'(BEAT_BYTES);
    localparam [BUDGET_W-1:0] BURST_MIN = BUDGET_W'(BEAT_BYTES);
    localparam [BUDGET_W-1:0] BURST_MAX = BUDGET_W'(BURST_BEATS * BEAT_BYTES);
    localparam [LAT_W-1:0] LAT_MIN = LAT_W'(MIN_LATENCY);
    localparam [LAT_W-1:0] LAT_MAX = LAT_W'(MAX_LATENCY);

    typedef enum logic [1:0] {
        IDLE  = 2'b00,
        SHAPE = 2'b01,
        ISSUE = 2'b10
    } state_t;

    state_t state;
    reg [RATE_W-1:0] rate_cfg;
    reg [BUDGET_W-1:0] burst_cfg;
    reg [BUDGET_W-1:0] byte_budget;
    reg [LAT_W-1:0] latency_target;
    reg [LAT_W-1:0] countdown;
    reg [DATA_W-1:0] payload;
    reg [3:0] base_qos;
    reg scope_window;

    initial begin
        state = IDLE;
        rate_cfg = RATE_MIN;
        burst_cfg = BURST_MAX;
        byte_budget = BUDGET_W'(0);
        latency_target = LAT_MIN;
        countdown = LAT_W'(0);
        payload = {DATA_W{1'b0}};
        base_qos = 4'h2;
        scope_window = 1'b0;
    end

    wire config_ok =
        (i_cfg_rate >= RATE_MIN) && (i_cfg_rate <= RATE_MAX) &&
        (i_cfg_burst >= BURST_MIN) && (i_cfg_burst <= BURST_MAX) &&
        (i_cfg_latency >= LAT_MIN) && (i_cfg_latency <= LAT_MAX);

    wire [BUDGET_W:0] refill_sum =
        {1'b0, byte_budget} + (BUDGET_W+1)'(rate_cfg);

    assign o_req_ready = i_ce && (state == IDLE) && !i_cfg_valid;
    // The downstream launch port is a guaranteed-ready request sink.
    assign o_launch = i_ce && (state == ISSUE);
    assign o_data = payload;
    assign o_axqos = (((state == SHAPE) || (state == ISSUE)) &&
                     (countdown <= LAT_W'(2))) ? 4'hf : base_qos;

    // All scheduling, scope, and deadline state advances only on enabled ticks.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_scope_close)
                scope_window <= 1'b0;
            else if (i_scope_open)
                scope_window <= 1'b1;

            if (refill_sum >= {1'b0, burst_cfg})
                byte_budget <= burst_cfg;
            else
                byte_budget <= refill_sum[BUDGET_W-1:0];

            case (state)
                IDLE: begin
                    countdown <= LAT_W'(0);
                    if (i_cfg_valid) begin
                        if (config_ok) begin
                            rate_cfg <= i_cfg_rate;
                            burst_cfg <= i_cfg_burst;
                            latency_target <= i_cfg_latency;
                            base_qos <= i_cfg_qos;
                            byte_budget <= BUDGET_W'(0);
                        end
                    end else if (i_req_valid) begin
                        payload <= i_req_data;
                        countdown <= latency_target;
                        state <= SHAPE;
                    end
                end
                SHAPE: begin
                    countdown <= countdown - LAT_W'(1);
                    if (byte_budget >= BURST_MIN) begin
                        // Reserving the beat suppresses refill on this tick.
                        byte_budget <= byte_budget - BURST_MIN;
                        state <= ISSUE;
                    end
                end
                ISSUE: begin
                    // Launch completes the accepted request on this tick.
                    state <= IDLE;
                    countdown <= LAT_W'(0);
                end
                default: begin
                    state <= IDLE;
                    countdown <= LAT_W'(0);
                end
            endcase
        end
    end

    always @(posedge clk)
        assert (!scope_window ||
                !((state == SHAPE) || (state == ISSUE)) ||
                (countdown != LAT_W'(0)));
endmodule

module placement_instruction_expander #(
    parameter HALF_W = 16
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [HALF_W-1:0]     in_half,
    input  wire                  open_window,
    input  wire                  close_window,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [HALF_W-1:0]     out_lo,
    output reg  [HALF_W-1:0]     out_hi
);
    // Placement microengine instruction front end, with 16-bit fetch beats.
    // Compact tags 00/01/10 encode ADDI using C.ADDI field positions;
    // the upper three compact bits are reserved aliases. Tag 11 denotes
    // a native 32-bit instruction, delivered low halfword first.
    // Thus native instructions straddle fetch boundaries and need held_half.
    localparam [HALF_W-1:0] ADDI_OPCODE =
        {{(HALF_W-7){1'b0}}, 7'b0010011};

    reg [HALF_W-1:0] held_half;
    reg              half_valid;
    reg [HALF_W-1:0] raw_lo;
    reg [HALF_W-1:0] raw_hi;
    reg              window;
    reg              past_valid;

    wire [HALF_W-1:0] compact_lo =
        {in_half[7], 3'b000, in_half[11:7], 7'b0010011};
    wire [HALF_W-1:0] compact_hi =
        {{7{in_half[12]}}, in_half[6:2], in_half[11:8]};

    // A blocked output prevents acceptance of another fetch beat.
    assign in_ready = !out_valid || out_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    initial begin
        held_half = {HALF_W{1'b0}};
        half_valid = 1'b0;
        raw_lo = {HALF_W{1'b0}};
        raw_hi = {HALF_W{1'b0}};
        out_lo = ADDI_OPCODE;
        out_hi = {HALF_W{1'b0}};
        out_valid = 1'b0;
        window = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            held_half <= {HALF_W{1'b0}};
            half_valid <= 1'b0;
            raw_lo <= {HALF_W{1'b0}};
            raw_hi <= {HALF_W{1'b0}};
            out_lo <= ADDI_OPCODE;
            out_hi <= {HALF_W{1'b0}};
            out_valid <= 1'b0;
            window <= 1'b0;
            past_valid <= 1'b0;
        end else begin
            // With in_valid=0 and out_ready=0, every register holds.
            if (in_fire || out_fire)
                past_valid <= 1'b1;

            if (out_fire)
                out_valid <= 1'b0;

            if (in_fire) begin
                // Accepted Q opens the scope; accepted R closes it.
                if (close_window)
                    window <= 1'b0;
                else if (open_window)
                    window <= 1'b1;

                if (half_valid) begin
                    // Complete a native instruction spanning two fetches.
                    raw_lo <= held_half;
                    raw_hi <= in_half;
                    out_lo <= held_half;
                    out_hi <= in_half;
                    out_valid <= 1'b1;
                    half_valid <= 1'b0;
                end else if (in_half[1:0] == 2'b11) begin
                    held_half <= in_half;
                    half_valid <= 1'b1;
                end else begin
                    // Expand one compact instruction into two halfwords.
                    raw_lo <= in_half;
                    raw_hi <= {HALF_W{1'b0}};
                    out_lo <= compact_lo;
                    out_hi <= compact_hi;
                    out_valid <= 1'b1;
                end
            end
        end
    end

    // Inside the latched scope, an unchanged encoded instruction must
    // retain the same expanded instruction, including across reissues.
    always @(posedge clk)
        if (past_valid && window && $stable({raw_hi, raw_lo}))
            assert ($stable({out_hi, out_lo}));
endmodule

module chipset_bus_fifo #(
    parameter RAM_DEPTH = 4,
    parameter DATA_BITS = 64
) (
    input  wire                 clk,
    input  wire                 i_valid,
    output wire                 o_ready,
    input  wire [DATA_BITS-1:0]  i_data,
    output wire                 o_valid,
    input  wire                 i_ready,
    output wire [DATA_BITS-1:0]  o_data,
    input  wire                 i_load_config,
    input  wire [DATA_BITS-1:0]  i_xor_config,
    input  wire                 i_scope_open,
    input  wire                 i_scope_close
);
    localparam [63:0] RAM_ENTRIES = RAM_DEPTH;
    localparam [63:0] LAST_ENTRY = RAM_ENTRIES - 64'd1;
    localparam [63:0] CAPACITY = RAM_ENTRIES + 64'd2;

    // Oldest word in the head flop, newest word in the tail flop,
    // and intervening words in a synchronous-read SRAM ring.
    reg [DATA_BITS-1:0] head_data;
    reg [DATA_BITS-1:0] tail_data;
    reg [DATA_BITS-1:0] sram [0:RAM_DEPTH-1];
    reg head_valid;
    reg tail_valid;
    reg [63:0] total_count;
    reg [63:0] ram_count;
    reg [63:0] wr_ptr;
    reg [63:0] rd_ptr;
    reg bypass_select;

    reg [DATA_BITS-1:0] xor_config;
    reg window_open;
    reg pv;

    wire full = (total_count == CAPACITY);
    wire empty = !head_valid;
    wire push = i_valid && o_ready;
    wire pop = o_valid && i_ready;
    wire transfer = push || pop;
    wire [DATA_BITS-1:0] incoming_word = i_data ^ xor_config;
    wire [63:0] next_wr_ptr =
        (wr_ptr == LAST_ENTRY) ? 64'd0 : wr_ptr + 64'd1;
    wire [63:0] next_rd_ptr =
        (rd_ptr == LAST_ENTRY) ? 64'd0 : rd_ptr + 64'd1;

    assign o_ready = (total_count < CAPACITY);
    assign o_valid = head_valid;
    assign o_data = head_data;

    integer k;
    initial begin
        head_data = {DATA_BITS{1'b0}};
        tail_data = {DATA_BITS{1'b0}};
        head_valid = 1'b0;
        tail_valid = 1'b0;
        total_count = 64'd0;
        ram_count = 64'd0;
        wr_ptr = 64'd0;
        rd_ptr = 64'd0;
        bypass_select = 1'b1;
        xor_config = {DATA_BITS{1'b0}};
        window_open = 1'b0;
        pv = 1'b0;
        for (k = 0; k < RAM_DEPTH; k = k + 1)
            sram[k] = {DATA_BITS{1'b0}};
    end

    always @(posedge clk) begin
        // Configuration is metadata on an accepted input transaction;
        // a loaded mask applies to subsequent input transactions.
        if (push && i_load_config)
            xor_config <= i_xor_config;

        // Q and R are scope commands accepted with a FIFO transfer.
        // R has priority. Without R, an opened window stays open.
        if (transfer) begin
            pv <= 1'b1;
            if (i_scope_close)
                window_open <= 1'b0;
            else if (i_scope_open)
                window_open <= 1'b1;
        end

        case ({push, pop})
            2'b10: begin
                total_count <= total_count + 64'd1;
                if (total_count == 64'd0) begin
                    head_data <= incoming_word;
                    head_valid <= 1'b1;
                end else if (total_count == 64'd1) begin
                    tail_data <= incoming_word;
                    tail_valid <= 1'b1;
                end else begin
                    sram[wr_ptr] <= tail_data;
                    wr_ptr <= next_wr_ptr;
                    ram_count <= ram_count + 64'd1;
                    tail_data <= incoming_word;
                    bypass_select <= 1'b0;
                end
            end

            2'b01: begin
                total_count <= total_count - 64'd1;
                if (total_count == 64'd1) begin
                    head_valid <= 1'b0;
                end else if (bypass_select) begin
                    // No SRAM words: forward the tail flop directly.
                    head_data <= tail_data;
                    tail_valid <= 1'b0;
                end else begin
                    // The head flop captures the synchronous SRAM read.
                    head_data <= sram[rd_ptr];
                    rd_ptr <= next_rd_ptr;
                    ram_count <= ram_count - 64'd1;
                    bypass_select <= (ram_count == 64'd1);
                end
            end

            2'b11: begin
                if (total_count == 64'd1) begin
                    head_data <= incoming_word;
                end else if (bypass_select) begin
                    head_data <= tail_data;
                    tail_data <= incoming_word;
                end else begin
                    head_data <= sram[rd_ptr];
                    sram[wr_ptr] <= tail_data;
                    rd_ptr <= next_rd_ptr;
                    wr_ptr <= next_wr_ptr;
                    tail_data <= incoming_word;
                end
            end

            default: begin
                // In particular, i_valid=0 and i_ready=0 freeze all state.
            end
        endcase
    end

    // Within the latched scope, entering full must never coincide with empty.
    always @(posedge clk)
        if (pv && window_open && $rose(full))
            assert (!empty);
endmodule

module scoped_load_store_queue #(
    parameter integer DEPTH = 32'd64,
    parameter integer WORD_W = 32'd32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_q,
    input  wire                  i_r,
    input  wire                  i_valid,
    output wire                  o_ready,
    input  wire [1:0]            i_cmd,
    input  wire [WORD_W-1:0]     i_addr,
    input  wire [WORD_W-1:0]     i_data,
    output wire                  o_done,
    output wire                  o_hit,
    output wire [WORD_W-1:0]     o_addr,
    output wire [WORD_W-1:0]     o_data
);
    localparam [31:0] CAPACITY = DEPTH;
    localparam [31:0] LAST_SLOT = CAPACITY - 32'd1;
    localparam [1:0] CMD_STORE = 2'b00;
    localparam [1:0] CMD_LOAD  = 2'b01;
    localparam [1:0] CMD_DRAIN = 2'b10;

    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        SEARCH = 2'b01,
        DONE   = 2'b10
    } state_t;
    state_t state;

    reg window;
    reg pv;
    reg [DEPTH-1:0] slot_valid;
    reg [WORD_W-1:0] store_addr [0:DEPTH-1];
    reg [WORD_W-1:0] store_data [0:DEPTH-1];
    reg [31:0] store_age [0:DEPTH-1];
    reg [31:0] rd_ptr, wr_ptr, count;
    reg [31:0] next_age;

    // A serialized load lane searches the pending-store queue.
    reg [WORD_W-1:0] load_addr;
    reg [31:0] load_age;
    reg [31:0] scan_idx;
    reg [31:0] deadline;
    reg best_found;
    reg [31:0] best_distance;
    reg [WORD_W-1:0] best_data;

    reg result_hit;
    reg [WORD_W-1:0] result_addr;
    reg [WORD_W-1:0] result_data;

    initial begin
        state = IDLE;
        window = 1'b0;
        pv = 1'b0;
        slot_valid = {DEPTH{1'b0}};
        rd_ptr = 32'd0;
        wr_ptr = 32'd0;
        count = 32'd0;
        next_age = 32'd0;
        load_addr = {WORD_W{1'b0}};
        load_age = 32'd0;
        scan_idx = 32'd0;
        deadline = 32'd0;
        best_found = 1'b0;
        best_distance = 32'hffffffff;
        best_data = {WORD_W{1'b0}};
        result_hit = 1'b0;
        result_addr = {WORD_W{1'b0}};
        result_data = {WORD_W{1'b0}};
        for (integer k = 32'd0; k < DEPTH; k = k + 32'd1) begin
            store_addr[k] = {WORD_W{1'b0}};
            store_data[k] = {WORD_W{1'b0}};
            store_age[k] = 32'd0;
        end
    end

    // Stores are never overwritten when full. DRAIN removes the oldest
    // pending store and reports its address and data as a completed command.
    assign o_ready = i_ce && ((state == IDLE) || (state == DONE)) &&
                     (((i_cmd == CMD_STORE) && (count < CAPACITY)) ||
                      (i_cmd == CMD_LOAD) ||
                      ((i_cmd == CMD_DRAIN) && (count != 32'd0)));

    // Completion means result generation, not downstream consumption.
    // DONE and its payload remain unchanged until another command is accepted.
    assign o_done = (state == DONE);
    assign o_hit = result_hit;
    assign o_addr = result_addr;
    assign o_data = result_data;

    wire [31:0] candidate_distance = load_age - store_age[scan_idx];
    wire address_match = slot_valid[scan_idx] &&
                         (store_addr[scan_idx] == load_addr);
    wire take_candidate = address_match &&
                          (!best_found || (candidate_distance < best_distance));

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            // Q opens a persistent scope; R closes it, with closing priority.
            if (i_r)
                window <= 1'b0;
            else if (i_q)
                window <= 1'b1;

            case (state)
                IDLE, DONE: begin
                    if (i_valid && o_ready) begin
                        case (i_cmd)
                            CMD_STORE: begin
                                slot_valid[wr_ptr] <= 1'b1;
                                store_addr[wr_ptr] <= i_addr;
                                store_data[wr_ptr] <= i_data;
                                store_age[wr_ptr] <= next_age;
                                next_age <= next_age + 32'd1;
                                wr_ptr <= (wr_ptr == LAST_SLOT) ?
                                          32'd0 : wr_ptr + 32'd1;
                                count <= count + 32'd1;
                                result_hit <= 1'b0;
                                result_addr <= i_addr;
                                result_data <= i_data;
                                state <= DONE;
                            end
                            CMD_LOAD: begin
                                load_addr <= i_addr;
                                load_age <= next_age;
                                next_age <= next_age + 32'd1;
                                scan_idx <= 32'd0;
                                deadline <= CAPACITY;
                                best_found <= 1'b0;
                                best_distance <= 32'hffffffff;
                                best_data <= {WORD_W{1'b0}};
                                result_hit <= 1'b0;
                                result_addr <= i_addr;
                                result_data <= {WORD_W{1'b0}};
                                state <= SEARCH;
                            end
                            CMD_DRAIN: begin
                                result_hit <= 1'b1;
                                result_addr <= store_addr[rd_ptr];
                                result_data <= store_data[rd_ptr];
                                slot_valid[rd_ptr] <= 1'b0;
                                rd_ptr <= (rd_ptr == LAST_SLOT) ?
                                          32'd0 : rd_ptr + 32'd1;
                                count <= count - 32'd1;
                                state <= DONE;
                            end
                            default: begin end
                        endcase
                    end
                end
                SEARCH: begin
                    // One enabled cycle examines one physical queue entry.
                    // Modular age distance selects the youngest matching store.
                    deadline <= deadline - 32'd1;
                    if (take_candidate) begin
                        best_found <= 1'b1;
                        best_distance <= candidate_distance;
                        best_data <= store_data[scan_idx];
                    end
                    if (scan_idx == LAST_SLOT) begin
                        result_hit <= take_candidate || best_found;
                        result_data <= take_candidate ?
                                       store_data[scan_idx] : best_data;
                        state <= DONE;
                    end else begin
                        scan_idx <= scan_idx + 32'd1;
                    end
                end
                default: begin end
            endcase
        end
    end

    // Bounded response within the Q-to-R window: if the previous enabled
    // search cycle spent the final budget unit, the load must now be complete.
    // The budget counts enabled service cycles; i_ce low freezes all state.
    always @(posedge clk)
        if (pv && window &&
            $past(window && (state == SEARCH) &&
                  (deadline == 32'd1) && i_ce))
            assert (state == DONE);
endmodule

module completion_broadcast #(
    parameter integer DEPTH = 32,
    parameter integer DATA_W = 64,
    parameter integer TAG_W = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_complete,
    input  wire [TAG_W-1:0]      i_result_tag,
    input  wire [DATA_W-1:0]     i_result_value,
    input  wire                  i_issue,
    input  wire                  i_open_window,
    input  wire                  i_close_window,
    output wire                  bus_grant,
    output wire                  source_empty,
    output reg                   bus_valid,
    output reg  [TAG_W-1:0]      bus_tag,
    output reg  [DATA_W-1:0]     bus_value
);
    localparam logic [63:0] DEPTH_COUNT = DEPTH;

    typedef enum logic [1:0] {
        IDLE  = 2'd0,
        READY = 2'd1
    } state_t;
    state_t state;

    reg [DATA_W-1:0] value_mem [0:DEPTH-1];
    reg [TAG_W-1:0] tag_mem [0:DEPTH-1];
    reg [63:0] occupancy;
    reg [63:0] read_ptr;
    reg [63:0] write_ptr;
    reg window;
    reg pv;

    wire enqueue = i_complete && (occupancy < DEPTH_COUNT);
    wire dequeue = i_issue && (state == READY);

    assign bus_grant = i_ce && dequeue;
    assign source_empty = (occupancy == 64'd0);

    initial begin
        state = IDLE;
        occupancy = 64'd0;
        read_ptr = 64'd0;
        write_ptr = 64'd0;
        window = 1'b0;
        pv = 1'b0;
        bus_valid = 1'b0;
        bus_tag = {TAG_W{1'b0}};
        bus_value = {DATA_W{1'b0}};
    end

    genvar entry;
    generate
        for (entry = 0; entry < DEPTH; entry = entry + 1) begin : init_entries
            initial begin
                value_mem[entry] = {DATA_W{1'b0}};
                tag_mem[entry] = {TAG_W{1'b0}};
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            if (i_close_window)
                window <= 1'b0;
            else if (i_open_window)
                window <= 1'b1;

            bus_valid <= dequeue;

            if (enqueue) begin
                value_mem[write_ptr] <= i_result_value;
                tag_mem[write_ptr] <= i_result_tag;
                if (write_ptr == DEPTH_COUNT - 64'd1)
                    write_ptr <= 64'd0;
                else
                    write_ptr <= write_ptr + 64'd1;
            end

            if (dequeue) begin
                bus_value <= value_mem[read_ptr];
                bus_tag <= tag_mem[read_ptr];
                if (read_ptr == DEPTH_COUNT - 64'd1)
                    read_ptr <= 64'd0;
                else
                    read_ptr <= read_ptr + 64'd1;
            end

            case ({enqueue, dequeue})
                2'b10: begin
                    occupancy <= occupancy + 64'd1;
                    state <= READY;
                end
                2'b01: begin
                    occupancy <= occupancy - 64'd1;
                    if (occupancy == 64'd1)
                        state <= IDLE;
                    else
                        state <= READY;
                end
                default: begin
                    occupancy <= occupancy;
                    state <= state;
                end
            endcase
        end
    end

    // Within an opened scope, the preceding cycle must not have
    // granted the shared result bus while its completion queue was empty.
    always @(posedge clk) begin
        if (pv && $past(window))
            assert (!($past(bus_grant) && $past(source_empty)));
    end
endmodule

module alignment_funnel_unit #(
    parameter integer WORD_BITS = 32,
    parameter integer PIPE_STAGES = 4
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [WORD_BITS-1:0]  in_lower,
    input  wire [WORD_BITS-1:0]  in_upper,
    input  wire                 cfg_load,
    input  wire [31:0]          cfg_offset_in,
    input  wire                 scope_open,
    input  wire                 scope_close,
    output reg                  out_valid,
    input  wire                 out_ready,
    output reg  [WORD_BITS-1:0]  out_data
);
    localparam [31:0] LATENCY = PIPE_STAGES;
    localparam [31:0] WORD_SIZE = WORD_BITS;
    localparam [PIPE_STAGES-1:0] FIRST_STAGE =
        {{(PIPE_STAGES-1){1'b0}}, 1'b1};

    reg [WORD_BITS-1:0] lower_word;
    reg [WORD_BITS-1:0] upper_word;
    reg [31:0] cfg_offset;
    reg [PIPE_STAGES-1:0] stage_valid;
    reg [31:0] countdown;
    reg outstanding;
    reg window;
    reg pv;

    // The engine clock-enable is compatible with both handshakes.
    // Holding in_valid and out_ready low freezes every state register.
    wire advance = in_valid || out_ready;
    assign in_ready = !cfg_load && !outstanding &&
                      (!out_valid || out_ready);
    wire accept_request = in_valid && in_ready;

    // Purely combinational funnel extraction; there is no double-width state.
    // Every configuration value denotes an offset modulo the word width.
    wire [31:0] shift_amount = cfg_offset % WORD_SIZE;
    wire [(2*WORD_BITS)-1:0] shifted_pair =
        {upper_word, lower_word} >> shift_amount;
    wire [WORD_BITS-1:0] funnel_word = shifted_pair[WORD_BITS-1:0];

    initial begin
        lower_word  = {WORD_BITS{1'b0}};
        upper_word  = {WORD_BITS{1'b0}};
        cfg_offset  = 32'd0;
        stage_valid = {PIPE_STAGES{1'b0}};
        countdown   = 32'd0;
        outstanding = 1'b0;
        window      = 1'b0;
        pv          = 1'b0;
        out_valid   = 1'b0;
        out_data    = {WORD_BITS{1'b0}};
    end

    always @(posedge clk) begin
        if (advance) begin
            pv <= 1'b1;

            // Q opens the persistent scope; R closes it, with close priority.
            if (scope_close)
                window <= 1'b0;
            else if (scope_open)
                window <= 1'b1;

            // Configuration commands are serviced while no job is executing.
            if (cfg_load && !outstanding)
                cfg_offset <= cfg_offset_in;

            // A latency token controls completion independently of the deadline.
            stage_valid <= stage_valid << 32'd1;
            if (outstanding && countdown != 32'd0)
                countdown <= countdown - 32'd1;
            else
                countdown <= 32'd0;

            if (out_valid && out_ready)
                out_valid <= 1'b0;

            // Completion means publishing a result, not its downstream acceptance.
            if (stage_valid[PIPE_STAGES-1]) begin
                out_data    <= funnel_word;
                out_valid   <= 1'b1;
                outstanding <= 1'b0;
            end

            if (accept_request) begin
                lower_word  <= in_lower;
                upper_word  <= in_upper;
                stage_valid <= FIRST_STAGE;
                countdown   <= LATENCY;
                outstanding <= 1'b1;
            end
        end
    end

    // For the previous cycle's outstanding request, completion must have
    // happened now or its enabled-cycle deadline must remain unexpired.
    always @(posedge clk) begin
        if (pv && window && $past(outstanding))
            assert (!outstanding || countdown != 32'd0);
    end
endmodule

module axi_timestamp_reader #(
    parameter integer WORD_W = 64,
    parameter integer MAX_BEATS = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  arvalid,
    output wire                  arready,
    input  wire [WORD_W-1:0]     araddr,
    input  wire [WORD_W-1:0]     arlen,
    input  wire [2:0]            arsize,
    input  wire [1:0]            arburst,
    output wire                  rvalid,
    input  wire                  rready,
    output logic [WORD_W-1:0]    rdata,
    output logic [1:0]           rresp,
    output wire                  rlast
);
    localparam logic [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam logic [WORD_W-1:0] ONE = WORD_W'(32'd1);
    localparam logic [WORD_W-1:0] MAX_LEN = WORD_W'(MAX_BEATS) - ONE;
    localparam logic [WORD_W-1:0] ADDR_MASK = WORD_W'(WORD_W / 32'd8) - ONE;
    localparam logic [2:0] BEAT_SIZE = 3'($clog2(WORD_W / 32'd8));
    localparam logic [1:0] RESP_OKAY = 2'b00;
    localparam logic [1:0] RESP_SLVERR = 2'b10;

    typedef enum logic [1:0] {
        IDLE  = 2'b00,
        FETCH = 2'b01,
        SEND  = 2'b10
    } state_t;
    state_t state;

    logic [WORD_W-1:0] timestamp_counter;
    logic [WORD_W-1:0] captured_addr;
    logic [WORD_W-1:0] captured_len;
    logic [2:0] captured_size;
    logic [1:0] captured_burst;
    logic [WORD_W-1:0] beat_index;
    logic [WORD_W-1:0] base_stamp;

    // Acceptance-history shadow and the acceptance-to-completion window.
    logic [WORD_W-1:0] request_stamp;
    logic request_seen;
    logic window_open;

    // The clock enable gates both interface transfers and every state update.
    assign arready = i_ce && (state == IDLE) && (arlen <= MAX_LEN);
    assign rvalid = i_ce && (state == SEND);
    assign rlast = (state == SEND) && (beat_index == captured_len);

    initial begin
        state = IDLE;
        timestamp_counter = ZERO;
        captured_addr = ZERO;
        captured_len = ZERO;
        captured_size = BEAT_SIZE;
        captured_burst = 2'b01;
        beat_index = ZERO;
        base_stamp = ZERO;
        request_stamp = ZERO;
        request_seen = 1'b0;
        window_open = 1'b0;
        rdata = ZERO;
        rresp = RESP_OKAY;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            timestamp_counter <= timestamp_counter + ONE;
            case (state)
                IDLE: begin
                    if (arvalid && arready) begin
                        captured_addr <= araddr;
                        captured_len <= arlen;
                        captured_size <= arsize;
                        captured_burst <= arburst;
                        beat_index <= ZERO;
                        base_stamp <= timestamp_counter;
                        request_stamp <= timestamp_counter;
                        request_seen <= 1'b1;
                        window_open <= 1'b1;
                        rresp <= (((araddr & ADDR_MASK) == ZERO) &&
                                  (arsize == BEAT_SIZE) &&
                                  (arburst == 2'b01)) ? RESP_OKAY : RESP_SLVERR;
                        state <= FETCH;
                    end
                end
                FETCH: begin
                    // Each burst returns a sequence based on its captured time.
                    rdata <= base_stamp + beat_index;
                    state <= SEND;
                end
                SEND: begin
                    if (rready) begin
                        if (beat_index == captured_len) begin
                            window_open <= 1'b0;
                            request_seen <= 1'b0;
                            state <= IDLE;
                        end else begin
                            beat_index <= beat_index + ONE;
                            state <= FETCH;
                        end
                    end
                end
                default: begin
                    state <= IDLE;
                    window_open <= 1'b0;
                    request_seen <= 1'b0;
                end
            endcase
        end
    end

    // A prepared successful response must follow an address acceptance and
    // carry the timestamp sequence established by that earlier acceptance.
    always @(posedge clk)
        if (window_open && (state == SEND) && (rresp == RESP_OKAY))
            assert (request_seen && (rdata == request_stamp + beat_index));
endmodule

module accumulator_rotate_merge #(
    parameter integer WORD_W = 128
) (
    input  wire clk,
    input  wire in_valid,
    output wire in_ready,
    input  wire in_config,
    input  wire [$clog2(WORD_W)-1:0] in_begin,
    input  wire [$clog2(WORD_W)-1:0] in_end,
    input  wire [$clog2(WORD_W)-1:0] in_shift,
    input  wire [WORD_W-1:0] in_operand,
    input  wire [WORD_W-1:0] in_destination,
    input  wire in_merge,
    output reg  out_valid,
    input  wire out_ready,
    output reg  [WORD_W-1:0] out_result
);
    localparam integer INDEX_W = $clog2(WORD_W);

    reg [INDEX_W-1:0] mask_begin;
    reg [INDEX_W-1:0] mask_end;
    reg [WORD_W-1:0] cached_mask;
    reg [WORD_W-1:0] accepted_mask_shadow;
    reg [WORD_W-1:0] accepted_base_shadow;

    function automatic [WORD_W-1:0] make_mask;
        input [INDEX_W-1:0] first_bit;
        input [INDEX_W-1:0] last_bit;
        integer bit_index;
        begin
            for (bit_index = 0; bit_index < WORD_W; bit_index = bit_index + 1) begin
                if (first_bit <= last_bit)
                    make_mask[bit_index] = (bit_index >= first_bit) &&
                                          (bit_index <= last_bit);
                else
                    make_mask[bit_index] = (bit_index >= first_bit) ||
                                          (bit_index <= last_bit);
            end
        end
    endfunction

    wire [WORD_W-1:0] bounds_mask = make_mask(mask_begin, mask_end);
    wire [WORD_W-1:0] incoming_mask = make_mask(in_begin, in_end);
    wire [2*WORD_W-1:0] rotated_pair =
        {in_operand, in_operand} << in_shift;
    wire [WORD_W-1:0] rotated_operand =
        rotated_pair[2*WORD_W-1:WORD_W];
    wire [WORD_W-1:0] merge_base =
        in_merge ? in_destination : {WORD_W{1'b0}};

    assign in_ready = !out_valid || out_ready;

    initial begin
        mask_begin = {INDEX_W{1'b0}};
        mask_end = {INDEX_W{1'b0}};
        cached_mask = {{(WORD_W-1){1'b0}}, 1'b1};
        accepted_mask_shadow = {WORD_W{1'b0}};
        accepted_base_shadow = {WORD_W{1'b0}};
        out_valid = 1'b0;
        out_result = {WORD_W{1'b0}};
    end

    always @(posedge clk) begin
        if (out_valid && out_ready)
            out_valid <= 1'b0;

        if (in_valid && in_ready) begin
            if (in_config) begin
                // Configuration packets program an inclusive, wrapping mask.
                mask_begin <= in_begin;
                mask_end <= in_end;
                cached_mask <= incoming_mask;
            end else begin
                // Execute packets rotate an accumulator word and optionally merge.
                out_result <= (rotated_operand & cached_mask) |
                              (merge_base & ~cached_mask);
                out_valid <= 1'b1;

                // Remember the earlier accepted command's permissions and baseline.
                accepted_mask_shadow <= bounds_mask;
                accepted_base_shadow <= merge_base;
            end
        end
    end

    // Every published change must have been authorized by the earlier command.
    always @(*) begin
        if (out_valid)
            assert (((out_result ^ accepted_base_shadow) &
                     ~accepted_mask_shadow) == {WORD_W{1'b0}});
    end
endmodule

module armed_dual_modulus_prescaler #(
    parameter integer DATA_W = 32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_pulse,
    input  wire                  i_arm,
    input  wire                  i_mode,
    input  wire                  i_q,
    input  wire [DATA_W-1:0]     i_base_minus_two,
    output reg                   finish
);
    localparam [DATA_W:0] COUNT_ZERO = {(DATA_W+1){1'b0}};
    localparam [DATA_W:0] COUNT_ONE  = {{DATA_W{1'b0}}, 1'b1};

    reg [DATA_W-1:0] base_minus_two;
    reg             mode_q;
    reg [DATA_W:0]  phase;
    reg             arm_seen;
    reg             start_seen;
    reg             scope_armed;

    // P = base_minus_two + 2. The registered mode selects P or P+1.
    // An extra counter bit accommodates every possible configuration word.
    wire [DATA_W:0] terminal_count;
    assign terminal_count = {1'b0, base_minus_two}
                          + COUNT_ONE
                          + {{DATA_W{1'b0}}, mode_q};

    initial begin
        base_minus_two = {DATA_W{1'b0}};
        mode_q         = 1'b0;
        phase          = COUNT_ZERO;
        arm_seen       = 1'b0;
        start_seen     = 1'b0;
        finish         = 1'b0;
        scope_armed    = 1'b0;
    end

    // Controller states are encoded by arm_seen and start_seen:
    // 00: unarmed, 10: armed, 11: pulse stream started.
    // Rearming loads a new configuration and begins a new ordered session.
    always @(posedge clk) begin
        if (i_ce) begin
            scope_armed <= scope_armed || i_q;

            if (i_arm) begin
                base_minus_two <= i_base_minus_two;
                mode_q         <= i_mode;
                phase          <= COUNT_ZERO;
                arm_seen       <= 1'b1;
                start_seen     <= 1'b0;
                finish         <= 1'b0;
            end else if (arm_seen && i_pulse) begin
                // The first accepted pulse starts the armed session.
                if (phase == COUNT_ZERO)
                    start_seen <= 1'b1;

                // Repeat division periods until another arm command.
                if (phase == terminal_count) begin
                    phase  <= COUNT_ZERO;
                    finish <= 1'b1;
                end else begin
                    phase  <= phase + COUNT_ONE;
                    finish <= 1'b0;
                end
            end
        end
    end

    // finish describes the last accepted pulse and holds between pulses.
    // After Q, start requires arm, and finish requires start.
    always @(*) begin
        assert (!scope_armed ||
                ((!start_seen || arm_seen) &&
                 (!finish || start_seen)));
    end
endmodule

module console_lane_ring_fifo #(
    parameter integer WORD_BITS = 16,
    parameter integer DEPTH = 32
) (
    input  wire                 i_clk,
    input  wire                 i_req_valid,
    output wire                 o_req_ready,
    output wire                 o_lane_valid,
    input  wire                 i_lane_ready,
    output wire [WORD_BITS-1:0]  o_lane_mask
);
    localparam [WORD_BITS-1:0] ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] DEPTH_COUNT = DEPTH;
    localparam [WORD_BITS-1:0] LANE_COUNT = WORD_BITS;
    localparam [WORD_BITS-1:0] LAST_SLOT = DEPTH - 32'd1;
    localparam [WORD_BITS-1:0] LAST_LANE = WORD_BITS - 32'd1;

    reg [WORD_BITS-1:0] rotor;
    reg [WORD_BITS-1:0] lane_fifo [0:DEPTH-1];
    reg [WORD_BITS-1:0] read_ptr;
    reg [WORD_BITS-1:0] write_ptr;
    reg [WORD_BITS-1:0] fill_count;
    reg [WORD_BITS-1:0] read_lane;
    reg armed;

    wire push;
    wire pop;

    assign o_req_ready = (fill_count < DEPTH_COUNT);
    assign o_lane_valid = (fill_count != ZERO);
    assign o_lane_mask = lane_fifo[read_ptr];
    assign push = i_req_valid && o_req_ready;
    assign pop = o_lane_valid && i_lane_ready;

    initial begin
        rotor = ONE;
        read_ptr = ZERO;
        write_ptr = ZERO;
        fill_count = ZERO;
        read_lane = ZERO;
        armed = 1'b0;
    end

    genvar entry;
    generate
        for (entry = 0; entry < DEPTH; entry = entry + 1) begin : init_entries
            initial lane_fifo[entry] = ZERO;
        end
    endgenerate

    always @(posedge i_clk) begin
        if (push) begin
            // Queue the current scan lane, then circularly rotate left.
            lane_fifo[write_ptr] <= rotor;
            rotor <= {rotor[WORD_BITS-2:0], rotor[WORD_BITS-1]};
            if (write_ptr == LAST_SLOT)
                write_ptr <= ZERO;
            else
                write_ptr <= write_ptr + ONE;
        end

        if (pop) begin
            // Q is the first accepted output token; arming is sticky.
            armed <= 1'b1;
            if (read_ptr == LAST_SLOT)
                read_ptr <= ZERO;
            else
                read_ptr <= read_ptr + ONE;

            if (read_lane == LAST_LANE)
                read_lane <= ZERO;
            else
                read_lane <= read_lane + ONE;
        end

        case ({push, pop})
            2'b10: fill_count <= fill_count + ONE;
            2'b01: fill_count <= fill_count - ONE;
            default: fill_count <= fill_count;
        endcase
    end

    // After the first transfer, every available token names its expected lane.
    always @(*) begin
        if (armed && (fill_count != ZERO))
            assert (lane_fifo[read_ptr] == (ONE << read_lane));
    end
endmodule

module signed_divide_result_queue #(
    parameter integer WORD_W = 64,
    parameter integer DEPTH = 32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    input  wire [WORD_W-1:0]     i_dividend,
    input  wire [WORD_W-1:0]     i_divisor,
    output wire                  o_ready,
    input  wire                  i_take,
    output wire                  o_valid,
    output wire [WORD_W-1:0]     o_quotient,
    output wire [WORD_W-1:0]     o_remainder,
    output wire                  o_divide_by_zero,
    output wire                  o_overflow
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] ONES = {WORD_W{1'b1}};
    localparam [WORD_W-1:0] MIN_MAG = {1'b1, {(WORD_W-1){1'b0}}};
    localparam [WORD_W-1:0] CAPACITY = DEPTH;
    localparam [WORD_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [WORD_W-1:0] quotient_mag [0:DEPTH-1];
    reg [WORD_W-1:0] remainder_mag [0:DEPTH-1];
    reg [DEPTH-1:0] slot_valid;
    reg [DEPTH-1:0] saved_qneg;
    reg [DEPTH-1:0] saved_rneg;
    reg [DEPTH-1:0] saved_dbz;
    reg [DEPTH-1:0] saved_overflow;
    reg [WORD_W-1:0] rd_ptr;
    reg [WORD_W-1:0] wr_ptr;
    reg [WORD_W-1:0] outstanding;
    reg admitted;
    reg pv;

    integer j;
    initial begin
        rd_ptr = ZERO;
        wr_ptr = ZERO;
        outstanding = ZERO;
        admitted = 1'b0;
        pv = 1'b0;
        slot_valid = {DEPTH{1'b0}};
        saved_qneg = {DEPTH{1'b0}};
        saved_rneg = {DEPTH{1'b0}};
        saved_dbz = {DEPTH{1'b0}};
        saved_overflow = {DEPTH{1'b0}};
        for (j = 0; j < DEPTH; j = j + 1) begin
            quotient_mag[j] = ZERO;
            remainder_mag[j] = ZERO;
        end
    end

    wire dividend_negative = i_dividend[WORD_W-1];
    wire divisor_negative = i_divisor[WORD_W-1];
    wire quotient_negative = dividend_negative ^ divisor_negative;
    wire [WORD_W-1:0] abs_dividend = dividend_negative
        ? (~i_dividend + ONE) : i_dividend;
    wire [WORD_W-1:0] abs_divisor = divisor_negative
        ? (~i_divisor + ONE) : i_divisor;
    wire divide_by_zero_in = (abs_divisor == ZERO);
    wire overflow_in = (abs_dividend == MIN_MAG)
        && (abs_divisor == ONE)
        && dividend_negative && !quotient_negative;

    // Shared unsigned divide core, including explicit exceptional results.
    wire [WORD_W-1:0] unsigned_quotient = divide_by_zero_in ? ONES
        : ((abs_divisor == ONE) ? abs_dividend
                               : (abs_dividend / abs_divisor));
    wire [WORD_W-1:0] unsigned_remainder = divide_by_zero_in ? abs_dividend
        : ((abs_divisor == ONE) ? ZERO
                               : (abs_dividend % abs_divisor));

    // Slot ownership, rather than the occupancy counter, controls admission.
    assign o_ready = i_ce && !slot_valid[wr_ptr];
    assign o_valid = slot_valid[rd_ptr];
    wire push = i_valid && o_ready;
    wire pop = i_ce && i_take && o_valid;

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            admitted <= push;
            if (push) begin
                quotient_mag[wr_ptr] <= unsigned_quotient;
                remainder_mag[wr_ptr] <= unsigned_remainder;
                saved_qneg[wr_ptr] <= quotient_negative;
                saved_rneg[wr_ptr] <= dividend_negative;
                saved_dbz[wr_ptr] <= divide_by_zero_in;
                saved_overflow[wr_ptr] <= overflow_in;
                slot_valid[wr_ptr] <= 1'b1;
                wr_ptr <= (wr_ptr == LAST_SLOT) ? ZERO : (wr_ptr + ONE);
            end
            if (pop) begin
                slot_valid[rd_ptr] <= 1'b0;
                rd_ptr <= (rd_ptr == LAST_SLOT) ? ZERO : (rd_ptr + ONE);
            end
            case ({push, pop})
                2'b10: outstanding <= outstanding + ONE;
                2'b01: outstanding <= outstanding - ONE;
                default: outstanding <= outstanding;
            endcase
        end
    end

    // Sign fix-up uses the flags saved with this particular result.
    assign o_divide_by_zero = saved_dbz[rd_ptr];
    assign o_overflow = saved_overflow[rd_ptr];
    assign o_quotient = saved_dbz[rd_ptr] ? ONES
        : (saved_overflow[rd_ptr] ? MIN_MAG
        : (saved_qneg[rd_ptr] ? (~quotient_mag[rd_ptr] + ONE)
                             : quotient_mag[rd_ptr]));
    assign o_remainder = saved_overflow[rd_ptr] ? ZERO
        : (saved_rneg[rd_ptr] ? (~remainder_mag[rd_ptr] + ONE)
                             : remainder_mag[rd_ptr]);

    // Same-cycle structural descriptions supplied separately as invariants.
    wire [WORD_W-1:0] valid_sum [0:DEPTH];
    wire [WORD_W-1:0] valid_total;
    wire [DEPTH-1:0] expected_valid;
    wire [DEPTH-1:0] entry_metadata_ok;
    wire [DEPTH-1:0] slot_relation;
    assign valid_sum[0] = ZERO;
    assign valid_total = valid_sum[DEPTH];

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : describe_slot
            localparam [WORD_W-1:0] INDEX = g;
            assign valid_sum[g+1] = valid_sum[g]
                + (slot_valid[g] ? ONE : ZERO);
            assign expected_valid[g] = (outstanding == CAPACITY)
                || ((rd_ptr <= wr_ptr)
                    ? ((INDEX >= rd_ptr) && (INDEX < wr_ptr))
                    : ((INDEX >= rd_ptr) || (INDEX < wr_ptr)));
            assign entry_metadata_ok[g] =
                (!saved_dbz[g] || (quotient_mag[g] == ONES))
                && (!saved_overflow[g]
                    || (!saved_dbz[g] && !saved_qneg[g] && saved_rneg[g]
                        && (quotient_mag[g] == MIN_MAG)
                        && (remainder_mag[g] == ZERO)));
            assign slot_relation[g] =
                (slot_valid[g] == expected_valid[g])
                && (!slot_valid[g] || entry_metadata_ok[g]);
        end
    endgenerate

    // Global bounded existence: every rising admission notification observes
    // at most DEPTH outstanding results. pv only validates sampled history.
    always @(posedge clk) begin
        if (pv && $rose(admitted))
            assert (outstanding <= CAPACITY);
    end
endmodule

module droop_clock_stretcher #(
    parameter [31:0] BASE_TICKS = 32'd4,
    parameter [31:0] RECOVERY_CYCLES = 32'd4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        droop,
    output reg         stretched_clk,
    output reg         stretch_active,
    output reg [31:0]  stretch_amount,
    output reg [31:0]  recovery_left,
    output reg         arm_seen,
    output reg         start_seen,
    output reg         start_event,
    output reg         finish_event
);
    // Positive timing parameters; their sum must fit in 32 bits.
    localparam [31:0] PH_IDLE  = 32'd0;
    localparam [31:0] PH_ARMED = 32'd1;
    localparam [31:0] PH_RUN   = 32'd2;
    localparam [31:0] PH_DONE  = 32'd3;

    reg [31:0] phase;
    reg [31:0] ticks_left;
    reg scope_armed;

    wire cycle_boundary = (ticks_left == 32'd1);
    wire [31:0] reload_ticks =
        (phase == PH_ARMED) ? (BASE_TICKS + stretch_amount) :
        ((phase == PH_RUN) && (recovery_left > 32'd1)) ?
            (BASE_TICKS + (stretch_amount - 32'd1)) : BASE_TICKS;

    initial begin
        phase          = PH_IDLE;
        ticks_left     = BASE_TICKS;
        scope_armed    = 1'b0;
        stretched_clk  = 1'b0;
        stretch_active = 1'b0;
        stretch_amount = 32'd0;
        recovery_left  = 32'd0;
        arm_seen       = 1'b0;
        start_seen     = 1'b0;
        start_event    = 1'b0;
        finish_event   = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // The first detector event permanently opens the checking scope.
            if (droop)
                scope_armed <= 1'b1;

            start_event  <= 1'b0;
            finish_event <= 1'b0;

            // Each generated half-period is lengthened by stretch_amount.
            if (cycle_boundary) begin
                ticks_left    <= reload_ticks;
                stretched_clk <= ~stretched_clk;
            end else begin
                ticks_left <= ticks_left - 32'd1;
            end

            case (phase)
                PH_IDLE: begin
                    if (droop) begin
                        phase          <= PH_ARMED;
                        arm_seen       <= 1'b1;
                        start_seen     <= 1'b0;
                        recovery_left  <= RECOVERY_CYCLES;
                        stretch_amount <= RECOVERY_CYCLES;
                    end
                end

                PH_ARMED: begin
                    // Begin stretching only at a generated-clock boundary.
                    if (cycle_boundary) begin
                        phase          <= PH_RUN;
                        stretch_active <= 1'b1;
                        start_seen     <= 1'b1;
                        start_event    <= 1'b1;
                    end
                end

                PH_RUN: begin
                    if (cycle_boundary) begin
                        if (recovery_left == 32'd1) begin
                            phase          <= PH_DONE;
                            stretch_active <= 1'b0;
                            recovery_left  <= 32'd0;
                            stretch_amount <= 32'd0;
                            finish_event   <= 1'b1;
                        end else begin
                            recovery_left  <= recovery_left - 32'd1;
                            stretch_amount <= stretch_amount - 32'd1;
                        end
                    end
                end

                PH_DONE: begin
                    phase      <= PH_IDLE;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    // After the first droop: start requires arm, and finish requires both.
    always @(posedge clk)
        assert (!scope_armed ||
                ((!start_event || arm_seen) &&
                 (!finish_event || (arm_seen && start_seen))));
endmodule

module scl_stretch_handler #(
    parameter integer DATA_WIDTH = 8,
    parameter [DATA_WIDTH-1:0] MAX_STRETCH = 8'd8
) (
    input  wire clk,
    input  wire sample_valid,
    output wire sample_ready,
    input  wire sample_scl_high,
    input  wire [DATA_WIDTH-1:0] sample_limit,
    output wire report_valid,
    input  wire report_ready,
    output wire [DATA_WIDTH-1:0] report_duration,
    output wire scl_release,
    output wire hold_high_phase
);
    localparam [DATA_WIDTH-1:0] ZERO = {DATA_WIDTH{1'b0}};
    localparam [DATA_WIDTH-1:0] ONE = {{(DATA_WIDTH-1){1'b0}}, 1'b1};

    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        STRETCH = 2'b01,
        REPORT  = 2'b10
    } state_t;

    state_t state;
    reg stretching_active;
    reg [DATA_WIDTH-1:0] stretch_duration;
    reg [DATA_WIDTH-1:0] stretch_limit;

    wire [DATA_WIDTH-1:0] accepted_limit;
    assign accepted_limit = (sample_limit > MAX_STRETCH)
                          ? MAX_STRETCH : sample_limit;
    assign sample_ready = (state == IDLE) || (state == STRETCH);
    assign report_valid = (state == REPORT);
    assign report_duration = stretch_duration;
    assign scl_release = (state == STRETCH) || (state == REPORT);
    assign hold_high_phase = stretching_active;

    initial begin
        state = IDLE;
        stretching_active = 1'b0;
        stretch_duration = ZERO;
        stretch_limit = MAX_STRETCH;
    end

    // The first accepted sample starts a high phase and supplies its limit.
    // Further accepted samples are duration ticks while waiting for SCL.
    // With sample_valid and report_ready low, every register holds.
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (sample_valid && sample_ready) begin
                    stretch_duration <= ZERO;
                    stretch_limit <= accepted_limit;
                    if (sample_scl_high) begin
                        state <= REPORT;
                        stretching_active <= 1'b0;
                    end else begin
                        state <= STRETCH;
                        stretching_active <= 1'b1;
                    end
                end
            end

            STRETCH: begin
                if (sample_valid && sample_ready) begin
                    if (sample_scl_high) begin
                        state <= REPORT;
                        stretching_active <= 1'b0;
                    end else if (stretch_duration < stretch_limit) begin
                        stretch_duration <= stretch_duration + ONE;
                        if ((stretch_duration + ONE) == stretch_limit) begin
                            state <= REPORT;
                            stretching_active <= 1'b0;
                        end
                    end else begin
                        // The configured allowance is already exhausted.
                        state <= REPORT;
                        stretching_active <= 1'b0;
                    end
                end
            end

            REPORT: begin
                // Keep valid and duration steady under back-pressure.
                if (report_valid && report_ready)
                    state <= IDLE;
            end

            default: begin
                // Unused encodings hold; the supplied relation excludes them.
            end
        endcase
    end

    // Every newly available duration report is globally bounded.
    always @(posedge clk)
        if ($rose(report_valid))
            assert (stretch_duration <= MAX_STRETCH);
endmodule

module duty_trim_monitor #(
    parameter integer DATA_W = 128,
    parameter integer PERIOD_TICKS = 8
) (
    input  wire clk,
    input  wire i_sample_valid,
    output wire o_sample_ready,
    input  wire [DATA_W-1:0] i_imbalance,
    output wire o_report_valid,
    input  wire i_report_ready,
    output wire [DATA_W-1:0] o_report_data,
    input  wire [$clog2(PERIOD_TICKS)-1:0] i_phase,
    output wire o_corrected_clk
);
    // PERIOD_TICKS is at least four. i_phase is the oscillator's
    // phase within a period; the threshold selects its falling edge.
    localparam integer TICK_W = $clog2(PERIOD_TICKS);
    localparam integer TRIM_SPAN = PERIOD_TICKS - 2*(PERIOD_TICKS/4);
    localparam integer CODE_W = $clog2(TRIM_SPAN + 1);
    localparam [TICK_W-1:0] MIN_HIGH = TICK_W'(PERIOD_TICKS/4);
    localparam [TICK_W-1:0] MAX_HIGH = TICK_W'(PERIOD_TICKS - PERIOD_TICKS/4);
    localparam [CODE_W-1:0] CODE_MAX = CODE_W'(TRIM_SPAN);

    // The correction code integrates the sign of measured imbalance.
    // high_ticks is the corresponding applied high-time tick count.
    reg [CODE_W-1:0] correction_code;
    reg [TICK_W-1:0] high_ticks;
    reg report_valid;
    reg [DATA_W-1:0] report_data;
    wire sample_fire;

    initial begin
        correction_code = CODE_W'(PERIOD_TICKS/2 - PERIOD_TICKS/4);
        high_ticks = TICK_W'(PERIOD_TICKS/2);
        report_valid = 1'b0;
        report_data = {DATA_W{1'b0}};
    end

    // A one-item monitor report slot supplies back-pressure.
    assign o_sample_ready = !report_valid || i_report_ready;
    assign sample_fire = i_sample_valid && o_sample_ready;
    assign o_report_valid = report_valid;
    assign o_report_data = report_data;
    assign o_corrected_clk = (i_phase < high_ticks);

    // With sample-valid and report-ready both low, every register holds.
    always @(posedge clk) begin
        if (report_valid && i_report_ready)
            report_valid <= 1'b0;

        if (sample_fire) begin
            report_valid <= 1'b1;
            report_data <= i_imbalance;

            // Negative imbalance means the measured high interval is short.
            if (i_imbalance[DATA_W-1]) begin
                if (correction_code < CODE_MAX) begin
                    correction_code <= correction_code + CODE_W'(1);
                    high_ticks <= high_ticks + TICK_W'(1);
                end
            end else if (|i_imbalance) begin
                if (correction_code != CODE_W'(0)) begin
                    correction_code <= correction_code - CODE_W'(1);
                    high_ticks <= high_ticks - TICK_W'(1);
                end
            end
        end
    end

    always @(posedge clk) assert (high_ticks <= MAX_HIGH);
endmodule

module accelerator_alias_sequence #(
    parameter integer WORD_WIDTH = 8,
    parameter [7:0] SET_ADDR = 8'h00,
    parameter [7:0] CLEAR_ADDR = 8'h04,
    parameter [7:0] TOGGLE_ADDR = 8'h08
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire [7:0] write_addr,
    input wire [WORD_WIDTH-1:0] write_data,
    output reg [WORD_WIDTH-1:0] control_word
);
    localparam [WORD_WIDTH-1:0] ZERO_WORD = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] PH_IDLE = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] PH_ARMED = {{(WORD_WIDTH-3){1'b0}}, 3'b001};
    localparam [WORD_WIDTH-1:0] PH_RUNNING = {{(WORD_WIDTH-3){1'b0}}, 3'b010};
    localparam [WORD_WIDTH-1:0] PH_DONE = {{(WORD_WIDTH-3){1'b0}}, 3'b011};

    reg [WORD_WIDTH-1:0] phase;

    wire set_access = (write_addr == SET_ADDR);
    wire clear_access = (write_addr == CLEAR_ADDR);
    wire toggle_access = (write_addr == TOGGLE_ADDR);
    wire alias_access = set_access || clear_access || toggle_access;

    // Bits 0, 1 and 2 record arm, start and finish for this job.
    // Other bits are ordinary independently writable control flags.
    wire flags_only = (write_data[2:0] == 3'b000);
    wire advance = (set_access || toggle_access) &&
        (((phase == PH_IDLE) && (write_data[2:0] == 3'b001)) ||
         ((phase == PH_ARMED) && (write_data[2:0] == 3'b010)) ||
         ((phase == PH_RUNNING) && (write_data[2:0] == 3'b100)));
    wire retire = (clear_access || toggle_access) &&
        (phase == PH_DONE) && (write_data[2:0] == 3'b111);
    wire accept_write = alias_access && (flags_only || advance || retire);

    initial begin
        control_word = ZERO_WORD;
        phase = PH_IDLE;
    end

    // Invalid workflow writes are rejected without changing either register.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            control_word <= ZERO_WORD;
            phase <= PH_IDLE;
        end else if (i_ce && accept_write) begin
            if (set_access)
                control_word <= control_word | write_data;
            else if (clear_access)
                control_word <= control_word & ~write_data;
            else if (toggle_access)
                control_word <= control_word ^ write_data;

            if (advance)
                phase <= phase + PH_ARMED;
            else if (retire)
                phase <= PH_IDLE;
        end
    end

    // Globally, start requires arm; finish requires both arm and start.
    always @(*) begin
        if (control_word[2] || control_word[1])
            assert (control_word[0] && (!control_word[2] || control_word[1]));
    end
endmodule

module parasitic_phase_probe #(
    parameter [31:0] SKEW_CYCLES = 32'd4
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        i_ce,
    input  wire        launch,
    input  wire        i_ref_first,
    output reg         up,
    output reg         dn,
    output reg  [31:0] response_left
);
    // SKEW_CYCLES is a positive enabled-cycle path delay.
    localparam [31:0] RESPONSE_BUDGET = SKEW_CYCLES + 32'd1;

    reg [31:0] delay_left;
    reg ref_leads;

    wire accept = launch && !up && !dn;
    wire common_clear = up && dn;
    wire delayed_edge = (up ^ dn) && (delay_left == 32'd1);

    // A phase probe emits one edge immediately and its partner after
    // the modeled parasitic delay. Either clock may lead.
    wire reference_edge = (accept && i_ref_first) ||
                          (delayed_edge && !ref_leads);
    wire feedback_edge  = (accept && !i_ref_first) ||
                          (delayed_edge && ref_leads);

    initial begin
        up = 1'b0;
        dn = 1'b0;
        response_left = 32'd0;
        delay_left = 32'd0;
        ref_leads = 1'b0;
    end

    // Sampled phase-frequency detector. Each edge sets its own flop;
    // the shared reset path clears both after both edges have arrived.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            up <= 1'b0;
            dn <= 1'b0;
        end else if (i_ce) begin
            if (common_clear) begin
                up <= 1'b0;
                dn <= 1'b0;
            end else begin
                if (reference_edge)
                    up <= 1'b1;
                if (feedback_edge)
                    dn <= 1'b1;
            end
        end
    end

    // Acceptance starts the delayed partner edge and the completion
    // deadline. Completion includes the detector's shared-clear cycle.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            delay_left <= 32'd0;
            response_left <= 32'd0;
            ref_leads <= 1'b0;
        end else if (i_ce) begin
            if (common_clear) begin
                delay_left <= 32'd0;
                response_left <= 32'd0;
                ref_leads <= 1'b0;
            end else if (accept) begin
                delay_left <= SKEW_CYCLES;
                response_left <= RESPONSE_BUDGET;
                ref_leads <= i_ref_first;
            end else if (up || dn) begin
                if (delay_left != 32'd0)
                    delay_left <= delay_left - 32'd1;
                response_left <= response_left - 32'd1;
            end
        end
    end

    // Globally, an outstanding comparison must not exhaust its deadline.
    always @(posedge clk)
        if (up || dn)
            assert (response_left != 32'd0);
endmodule

module dma_first_fault_capture #(
    parameter integer WORD_WIDTH = 32
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_ce,
    input  wire                  clear_fault,
    input  wire                  bus_error,
    input  wire                  descriptor_fault,
    input  wire                  alignment_fault,
    input  wire [WORD_WIDTH-1:0]  error_address,
    input  wire [WORD_WIDTH-1:0]  error_channel,
    output reg                   fault_valid,
    output reg  [WORD_WIDTH-1:0]  fault_address,
    output reg  [WORD_WIDTH-1:0]  fault_code,
    output reg  [WORD_WIDTH-1:0]  fault_channel,
    output reg                   bus_irq,
    output reg                   descriptor_irq,
    output reg                   alignment_irq
);
    localparam [WORD_WIDTH-1:0] CODE_NONE = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] CODE_BUS = {{(WORD_WIDTH-2){1'b0}}, 2'b01};
    localparam [WORD_WIDTH-1:0] CODE_DESCRIPTOR = {{(WORD_WIDTH-2){1'b0}}, 2'b10};
    localparam [WORD_WIDTH-1:0] CODE_ALIGNMENT = {{(WORD_WIDTH-2){1'b0}}, 2'b11};

    // Captured per-class status feeds a registered notification stage.
    reg cause_bus;
    reg cause_descriptor;
    reg cause_alignment;

    initial begin
        fault_valid = 1'b0;
        fault_address = {WORD_WIDTH{1'b0}};
        fault_code = CODE_NONE;
        fault_channel = {WORD_WIDTH{1'b0}};
        cause_bus = 1'b0;
        cause_descriptor = 1'b0;
        cause_alignment = 1'b0;
        bus_irq = 1'b0;
        descriptor_irq = 1'b0;
        alignment_irq = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            fault_valid <= 1'b0;
            fault_address <= {WORD_WIDTH{1'b0}};
            fault_code <= CODE_NONE;
            fault_channel <= {WORD_WIDTH{1'b0}};
            cause_bus <= 1'b0;
            cause_descriptor <= 1'b0;
            cause_alignment <= 1'b0;
            bus_irq <= 1'b0;
            descriptor_irq <= 1'b0;
            alignment_irq <= 1'b0;
        end else if (i_ce) begin
            bus_irq <= cause_bus;
            descriptor_irq <= cause_descriptor;
            alignment_irq <= cause_alignment;

            if (clear_fault) begin
                fault_valid <= 1'b0;
                fault_address <= {WORD_WIDTH{1'b0}};
                fault_code <= CODE_NONE;
                fault_channel <= {WORD_WIDTH{1'b0}};
                cause_bus <= 1'b0;
                cause_descriptor <= 1'b0;
                cause_alignment <= 1'b0;
            end else if (!fault_valid &&
                         (bus_error || descriptor_fault || alignment_fault)) begin
                // Keep the first fault until explicitly cleared.
                // Simultaneous sources use bus, descriptor, alignment priority.
                fault_valid <= 1'b1;
                fault_address <= error_address;
                fault_channel <= error_channel;
                cause_bus <= bus_error;
                cause_descriptor <= !bus_error && descriptor_fault;
                cause_alignment <= !bus_error && !descriptor_fault && alignment_fault;
                if (bus_error)
                    fault_code <= CODE_BUS;
                else if (descriptor_fault)
                    fault_code <= CODE_DESCRIPTOR;
                else
                    fault_code <= CODE_ALIGNMENT;
            end
        end
    end

    always @(*) assert (!(bus_irq && descriptor_irq));
endmodule

module buffered_burst_router #(
    parameter integer PORTS = 32'd4,
    parameter integer DEPTH = 32'd96
) (
    input wire clk,
    input wire i_ce,
    input wire i_load,
    input wire i_launch,
    input wire i_reconfigure,
    input wire [7:0] i_port,
    input wire [7:0] i_route,
    input wire [7:0] i_flit,
    output reg [PORTS-1:0] o_send,
    output reg [(PORTS*32'd8)-1:0] o_flit
);
    localparam [7:0] LAST_ADDR = DEPTH - 32'd1;

    reg [7:0] buffers [0:PORTS-1][0:DEPTH-1];
    reg [7:0] occupancy [0:PORTS-1];
    reg [7:0] read_ptr [0:PORTS-1];
    reg [7:0] write_ptr [0:PORTS-1];
    reg [7:0] route_field [0:PORTS-1];

    reg [7:0] switch_input;
    reg [7:0] switch_output;
    reg [7:0] countdown;
    reg outstanding;
    reg before_reconfigure;
    reg past_valid;

    wire deadline_zero = (countdown == 8'd0);
    wire [PORTS-1:0] port_legal;

    genvar g;
    generate
        for (g = 32'd0; g < PORTS; g = g + 32'd1) begin: port_checks
            assign port_legal[g] =
                (occupancy[g] <= DEPTH) &&
                (read_ptr[g] < DEPTH) &&
                (write_ptr[g] < DEPTH) &&
                (route_field[g] < PORTS);
        end
    endgenerate

    integer p;
    integer a;
    initial begin
        switch_input = 8'd0;
        switch_output = 8'd0;
        countdown = 8'd0;
        outstanding = 1'b0;
        before_reconfigure = 1'b1;
        past_valid = 1'b0;
        o_send = {PORTS{1'b0}};
        o_flit = {(PORTS*32'd8){1'b0}};
        for (p = 32'd0; p < PORTS; p = p + 32'd1) begin
            occupancy[p] = 8'd0;
            read_ptr[p] = 8'd0;
            write_ptr[p] = 8'd0;
            route_field[p] = 8'd0;
            for (a = 32'd0; a < DEPTH; a = a + 32'd1)
                buffers[p][a] = 8'd0;
        end
    end

    // Commands and output transfers occur only on enabled clock edges.
    // A launch reserves a switch path and drains the selected input burst.
    // Its completion budget is at most DEPTH enabled clock edges.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            o_send <= {PORTS{1'b0}};

            if (i_reconfigure) begin
                before_reconfigure <= 1'b0;
                if ((i_port < PORTS) && (i_route < PORTS))
                    route_field[i_port] <= i_route;
            end

            if (outstanding) begin
                o_send[switch_output] <= 1'b1;
                o_flit[(switch_output * 32'd8) +: 32'd8]
                    <= buffers[switch_input][read_ptr[switch_input]];

                if (read_ptr[switch_input] == LAST_ADDR)
                    read_ptr[switch_input] <= 8'd0;
                else
                    read_ptr[switch_input] <= read_ptr[switch_input] + 8'd1;

                occupancy[switch_input] <= occupancy[switch_input] - 8'd1;
                if (countdown != 8'd0)
                    countdown <= countdown - 8'd1;
                if (occupancy[switch_input] == 8'd1)
                    outstanding <= 1'b0;
            end else if (i_launch) begin
                if (i_port < PORTS) begin
                    if (occupancy[i_port] != 8'd0) begin
                        switch_input <= i_port;
                        switch_output <= route_field[i_port];
                        countdown <= occupancy[i_port];
                        outstanding <= 1'b1;
                    end
                end
            end else if (i_load) begin
                if (i_port < PORTS) begin
                    if (occupancy[i_port] < DEPTH) begin
                        buffers[i_port][write_ptr[i_port]] <= i_flit;
                        occupancy[i_port] <= occupancy[i_port] + 8'd1;
                        if (write_ptr[i_port] == LAST_ADDR)
                            write_ptr[i_port] <= 8'd0;
                        else
                            write_ptr[i_port] <= write_ptr[i_port] + 8'd1;
                    end
                end
            end
        end
    end

    // Before the first route-programming event, expiration must coincide
    // with an already completed burst, never an outstanding request.
    always @(posedge clk) begin
        if (past_valid && before_reconfigure && $rose(deadline_zero))
            assert (!outstanding);
    end
endmodule

module cascade_vector_link #(
    parameter integer VECTOR_WIDTH = 8,
    parameter integer IRQ_WIDTH = 8
) (
    input  wire clk,

    input  wire i_cfg_valid,
    output wire o_cfg_ready,
    input  wire i_cfg_slave_mode,
    input  wire [IRQ_WIDTH-1:0] i_cfg_cascade_identity,

    input  wire i_irq_valid,
    output wire o_irq_ready,
    input  wire [IRQ_WIDTH-1:0] i_irq_slot,
    input  wire [VECTOR_WIDTH-1:0] i_primary_vector,
    input  wire [VECTOR_WIDTH-1:0] i_slave_vector,

    output wire o_primary_irq_valid,
    output wire [IRQ_WIDTH-1:0] o_primary_irq_slot,
    input  wire i_ack_valid,
    output wire o_ack_ready,
    output wire o_slave_ack,

    output wire o_rsp_valid,
    input  wire i_rsp_ready,
    output wire [VECTOR_WIDTH-1:0] o_rsp_vector
);
    typedef enum logic [1:0] {
        IDLE     = 2'b00,
        WAIT_ACK = 2'b01,
        RESPOND  = 2'b10
    } state_t;

    state_t state;
    logic slave_mode;
    logic [IRQ_WIDTH-1:0] cascade_identity;
    logic [IRQ_WIDTH-1:0] pending_slot;
    logic cascade_pending;
    logic [VECTOR_WIDTH-1:0] slave_vector_shadow;
    logic [VECTOR_WIDTH-1:0] primary_vector_latched;
    logic [VECTOR_WIDTH-1:0] forward_vector;
    logic window_open;
    logic past_valid;

    wire cfg_fire;
    wire irq_fire;
    wire ack_fire;
    wire rsp_fire;
    wire cascade_selected;

    assign o_cfg_ready = (state == IDLE);
    assign o_irq_ready = (state == IDLE) && !i_cfg_valid;
    assign o_ack_ready = (state == WAIT_ACK);
    assign o_rsp_valid = (state == RESPOND);
    assign o_rsp_vector = forward_vector;

    assign o_primary_irq_valid = (state == WAIT_ACK);
    assign o_primary_irq_slot = pending_slot;
    assign cascade_selected = slave_mode &&
                              (pending_slot == cascade_identity);
    assign o_slave_ack = ack_fire && cascade_selected;

    assign cfg_fire = i_cfg_valid && o_cfg_ready;
    assign irq_fire = i_irq_valid && o_irq_ready;
    assign ack_fire = i_ack_valid && o_ack_ready;
    assign rsp_fire = o_rsp_valid && i_rsp_ready;

    initial begin
        state = IDLE;
        slave_mode = 1'b0;
        cascade_identity = {IRQ_WIDTH{1'b0}};
        pending_slot = {IRQ_WIDTH{1'b0}};
        cascade_pending = 1'b0;
        slave_vector_shadow = {VECTOR_WIDTH{1'b0}};
        primary_vector_latched = {VECTOR_WIDTH{1'b0}};
        forward_vector = {VECTOR_WIDTH{1'b0}};
        window_open = 1'b0;
        past_valid = 1'b0;
    end

    // Every state register holds when all incoming valids and
    // i_rsp_ready are low. There are no autonomous transitions.
    always @(posedge clk) begin
        if (cfg_fire || irq_fire || ack_fire || rsp_fire)
            past_valid <= 1'b1;

        case (state)
            IDLE: begin
                if (cfg_fire) begin
                    slave_mode <= i_cfg_slave_mode;
                    cascade_identity <= i_cfg_cascade_identity;
                end else if (irq_fire) begin
                    pending_slot <= i_irq_slot;
                    cascade_pending <= slave_mode &&
                                       (i_irq_slot == cascade_identity);

                    // Record the slave vector at the earlier request event.
                    slave_vector_shadow <= i_slave_vector;
                    primary_vector_latched <= i_primary_vector;

                    // Prepare the response data before primary acknowledge.
                    forward_vector <=
                        (slave_mode && (i_irq_slot == cascade_identity))
                        ? i_slave_vector : i_primary_vector;

                    // Q: accepted interrupt request opens this transaction.
                    window_open <= 1'b1;
                    state <= WAIT_ACK;
                end
            end

            WAIT_ACK: begin
                if (ack_fire) begin
                    // The primary acknowledge selects the cascaded slave's
                    // saved vector only for its configured primary input.
                    forward_vector <= cascade_selected
                                      ? slave_vector_shadow
                                      : primary_vector_latched;
                    state <= RESPOND;
                end
            end

            RESPOND: begin
                // Valid and vector remain unchanged under back-pressure.
                if (rsp_fire) begin
                    // R: response retirement closes the transaction window.
                    window_open <= 1'b0;
                    state <= IDLE;
                end
            end
        endcase
    end

    // Inside the request-to-retirement window, a cascade response cannot
    // change its vector without a change in the earlier slave-vector shadow.
    always @(posedge clk)
        if (past_valid && window_open && (state == RESPOND) &&
            cascade_pending && $stable(slave_vector_shadow))
            assert ($stable(forward_vector));
endmodule

module stream_nonrestoring_divider #(
    parameter integer DATA_W = 128
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_req_valid,
    output wire                  o_req_ready,
    input  wire [DATA_W-1:0]     i_dividend,
    input  wire [DATA_W-1:0]     i_divisor,
    output reg                   o_done,
    output reg  [DATA_W-1:0]     o_quotient,
    output wire [DATA_W-1:0]     o_remainder
);
    localparam integer STEP_W = $clog2(DATA_W + 1);
    localparam [STEP_W-1:0] TOTAL_STEPS = DATA_W;
    localparam [STEP_W-1:0] LAST_STEP = DATA_W - 1;
    localparam [STEP_W-1:0] STEP_ONE = {{(STEP_W-1){1'b0}}, 1'b1};

    reg signed [DATA_W:0] remainder;
    reg [DATA_W-1:0] divisor;
    reg [STEP_W-1:0] step_count;
    reg busy;
    reg armed;
    reg past_valid;

    wire signed [DATA_W:0] divisor_pos = {1'b0, divisor};
    wire signed [DATA_W:0] divisor_neg = -divisor_pos;
    wire correction_pending = remainder[DATA_W];

    // The input is a valid/ready receiver. Zero divisors are not accepted.
    assign o_req_ready = i_ce && !busy && (i_divisor != {DATA_W{1'b0}});
    assign o_remainder = remainder[DATA_W-1:0];

    // Extra arithmetic width preserves the intermediate doubled remainder.
    wire signed [DATA_W+1:0] remainder_extended = {remainder[DATA_W], remainder};
    wire signed [DATA_W+1:0] doubled_remainder = remainder_extended <<< 1;
    wire signed [DATA_W+1:0] incoming_bit = {{(DATA_W+1){1'b0}}, o_quotient[DATA_W-1]};
    wire signed [DATA_W+1:0] divisor_wide = {2'b00, divisor};
    wire signed [DATA_W+1:0] trial_remainder = remainder[DATA_W]
        ? doubled_remainder + incoming_bit + divisor_wide
        : doubled_remainder + incoming_bit - divisor_wide;
    wire signed [DATA_W+1:0] normalized_remainder = trial_remainder[DATA_W+1]
        ? trial_remainder + divisor_wide
        : trial_remainder;

    initial begin
        remainder = {(DATA_W+1){1'b0}};
        divisor = {{(DATA_W-1){1'b0}}, 1'b1};
        o_quotient = {DATA_W{1'b0}};
        step_count = {STEP_W{1'b0}};
        busy = 1'b0;
        o_done = 1'b0;
        armed = 1'b0;
        past_valid = 1'b0;
    end

    // i_ce low freezes every state register. Completion remains latched until
    // the next accepted request; o_done is a status flag, not an output channel.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            if (!busy) begin
                if (i_req_valid && o_req_ready) begin
                    divisor <= i_divisor;
                    remainder <= {(DATA_W+1){1'b0}};
                    o_quotient <= i_dividend;
                    step_count <= {STEP_W{1'b0}};
                    busy <= 1'b1;
                    o_done <= 1'b0;
                    armed <= 1'b1;
                end
            end else begin
                // Non-restoring division chooses add/subtract from the old
                // remainder sign and generates a quotient bit from the new sign.
                o_quotient <= {o_quotient[DATA_W-2:0], !trial_remainder[DATA_W+1]};
                step_count <= step_count + STEP_ONE;
                if (step_count == LAST_STEP) begin
                    remainder <= normalized_remainder[DATA_W:0];
                    busy <= 1'b0;
                    o_done <= 1'b1;
                end else begin
                    remainder <= trial_remainder[DATA_W:0];
                end
            end
        end
    end

    // After the first accepted request, a completion edge must never coexist
    // with a remainder that still needs negative-remainder correction.
    always @(posedge clk) begin
        if (armed && past_valid && $rose(o_done))
            assert (!(o_done && correction_pending));
    end
endmodule

module rsa_crt_response #(
    parameter integer WORD_BITS = 64,
    parameter [WORD_BITS-1:0] MOD_P = 64'd61,
    parameter [WORD_BITS-1:0] MOD_Q = 64'd53
) (
    input  wire clk,
    input  wire rst_n,
    input  wire in_valid,
    output wire in_ready,
    input  wire [WORD_BITS-1:0] in_m_p,
    input  wire [WORD_BITS-1:0] in_m_q,
    input  wire [WORD_BITS-1:0] in_q_inv,
    output reg  out_valid,
    input  wire out_ready,
    output reg [WORD_BITS-1:0] out_result,
    output reg [WORD_BITS-1:0] out_m_p,
    output reg [WORD_BITS-1:0] out_m_q,
    output reg [WORD_BITS-1:0] out_q_inv
);
    localparam [WORD_BITS-1:0] WORD_ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] WORD_ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};

    reg [WORD_BITS-1:0] outstanding;
    reg window;
    reg pv;

    // One transaction is retained, including its operands and coefficient.
    assign in_ready = !out_valid;
    wire take_in = in_valid && in_ready;
    wire take_out = out_valid && out_ready;

    // Garner recombination: h = qInv*(m_p-m_q) mod p;
    // result = m_q + q*h. For the default primes, qInv is 64'd38.
    // Canonical RSA residues produce a result below p*q. Inputs are not
    // restricted: arbitrary words still have defined fixed-width behavior.
    wire [WORD_BITS-1:0] p_residue = in_m_p % MOD_P;
    wire [WORD_BITS-1:0] q_residue_mod_p = in_m_q % MOD_P;
    wire [WORD_BITS-1:0] coefficient = in_q_inv % MOD_P;
    wire [WORD_BITS-1:0] difference =
        (p_residue + MOD_P - q_residue_mod_p) % MOD_P;
    wire [WORD_BITS-1:0] correction =
        (coefficient * difference) % MOD_P;
    wire [WORD_BITS-1:0] recombined =
        in_m_q + MOD_Q * correction;

    initial begin
        outstanding = WORD_ZERO;
        window = 1'b0;
        pv = 1'b0;
        out_valid = 1'b0;
        out_result = WORD_ZERO;
        out_m_p = WORD_ZERO;
        out_m_q = WORD_ZERO;
        out_q_inv = WORD_ZERO;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            outstanding <= WORD_ZERO;
            window <= 1'b0;
            pv <= 1'b0;
            out_valid <= 1'b0;
            out_result <= WORD_ZERO;
            out_m_p <= WORD_ZERO;
            out_m_q <= WORD_ZERO;
            out_q_inv <= WORD_ZERO;
        end else begin
            if (take_in) begin
                out_m_p <= in_m_p;
                out_m_q <= in_m_q;
                out_q_inv <= in_q_inv;
                out_result <= recombined;
                out_valid <= 1'b1;
                outstanding <= outstanding + WORD_ONE;
                // Q: accepting a request opens the observation window.
                window <= 1'b1;
                pv <= 1'b1;
            end else if (take_out) begin
                out_valid <= 1'b0;
                outstanding <= outstanding - WORD_ONE;
                // R: delivering its response closes the window.
                window <= 1'b0;
                pv <= 1'b1;
            end
        end
    end

    // pv becomes valid only after a transfer, preserving complete idle holds.
    // Inside the latched window, the previous occupancy was at most one.
    always @(posedge clk)
        if (pv && window)
            assert ($past(outstanding) <= WORD_ONE);
endmodule

module twiddle_rom_sequencer #(
    parameter integer ROM_DEPTH = 16,
    parameter integer WORD_WIDTH = 128,
    localparam integer ADDR_W = $clog2(ROM_DEPTH),
    localparam integer STAGE_W = $clog2(ADDR_W + 1)
) (
    input  wire                  clk,
    input  wire                  i_valid,
    input  wire                  i_start,
    output wire                  i_ready,
    output wire                  o_valid,
    input  wire                  o_ready,
    output wire [WORD_WIDTH-1:0]  o_data,
    output wire [ADDR_W-1:0]      o_addr,
    output wire [STAGE_W-1:0]     o_stage,
    output wire [ADDR_W-1:0]      o_butterfly
);
    localparam [1:0] PH_EMPTY = 2'd0;
    localparam [1:0] PH_ARMED = 2'd1;
    localparam [1:0] PH_RUN   = 2'd2;
    localparam [1:0] PH_DONE  = 2'd3;

    localparam [1:0] EV_NONE   = 2'd0;
    localparam [1:0] EV_START  = 2'd1;
    localparam [1:0] EV_BEAT   = 2'd2;
    localparam [1:0] EV_FINISH = 2'd3;

    localparam [STAGE_W-1:0] LAST_STAGE = STAGE_W'(ADDR_W);
    localparam [ADDR_W-1:0] LAST_INDEX = ADDR_W'(ROM_DEPTH - 1);

    reg [1:0] phase;
    reg [1:0] event_code;
    reg descriptor_armed;
    reg job_started;
    reg [STAGE_W-1:0] stage;
    reg [ADDR_W-1:0] butterfly_index;
    reg [ADDR_W-1:0] twiddle_addr;
    reg [WORD_WIDTH-1:0] coefficient_rom [0:ROM_DEPTH-1];

    // Default table: packed binary64 real/imaginary pairs for W_32^k.
    function automatic [WORD_WIDTH-1:0] coefficient_value;
        input integer address;
        begin
            case (address)
                32'd0:  coefficient_value = WORD_WIDTH'(128'h3ff00000000000000000000000000000);
                32'd1:  coefficient_value = WORD_WIDTH'(128'h3fef6297cff75cb0bfc8f8b83c69a60a);
                32'd2:  coefficient_value = WORD_WIDTH'(128'h3fed906bcf328d46bfd87de2a6aea963);
                32'd3:  coefficient_value = WORD_WIDTH'(128'h3fea9b66290ea1a3bfe1c73b39ae68c8);
                32'd4:  coefficient_value = WORD_WIDTH'(128'h3fe6a09e667f3bcdbfe6a09e667f3bcc);
                32'd5:  coefficient_value = WORD_WIDTH'(128'h3fe1c73b39ae68c8bfea9b66290ea1a3);
                32'd6:  coefficient_value = WORD_WIDTH'(128'h3fd87de2a6aea963bfed906bcf328d46);
                32'd7:  coefficient_value = WORD_WIDTH'(128'h3fc8f8b83c69a60abfef6297cff75cb0);
                32'd8:  coefficient_value = WORD_WIDTH'(128'h0000000000000000bff0000000000000);
                32'd9:  coefficient_value = WORD_WIDTH'(128'hbfc8f8b83c69a60abfef6297cff75cb0);
                32'd10: coefficient_value = WORD_WIDTH'(128'hbfd87de2a6aea963bfed906bcf328d46);
                32'd11: coefficient_value = WORD_WIDTH'(128'hbfe1c73b39ae68c8bfea9b66290ea1a3);
                32'd12: coefficient_value = WORD_WIDTH'(128'hbfe6a09e667f3bccbfe6a09e667f3bcd);
                32'd13: coefficient_value = WORD_WIDTH'(128'hbfea9b66290ea1a3bfe1c73b39ae68c8);
                32'd14: coefficient_value = WORD_WIDTH'(128'hbfed906bcf328d46bfd87de2a6aea963);
                32'd15: coefficient_value = WORD_WIDTH'(128'hbfef6297cff75cb0bfc8f8b83c69a60a);
                default: coefficient_value = {WORD_WIDTH{1'b0}};
            endcase
        end
    endfunction

    integer k;
    initial begin
        phase = PH_EMPTY;
        event_code = EV_NONE;
        descriptor_armed = 1'b0;
        job_started = 1'b0;
        stage = {STAGE_W{1'b0}};
        butterfly_index = {ADDR_W{1'b0}};
        twiddle_addr = {ADDR_W{1'b0}};
        for (k = 32'd0; k < ROM_DEPTH; k = k + 32'd1)
            coefficient_rom[k] = coefficient_value(k);
    end

    // A command with i_start=0 arms a job; i_start=1 launches it.
    assign i_ready = ((!i_start) && ((phase == PH_EMPTY) || (phase == PH_DONE)))
                   || (i_start && (phase == PH_ARMED));

    assign o_valid = (phase == PH_RUN);
    assign o_data = coefficient_rom[twiddle_addr];
    assign o_addr = twiddle_addr;
    assign o_stage = stage;
    assign o_butterfly = butterfly_index;

    wire command_fire = i_valid && i_ready;
    wire coefficient_fire = o_valid && o_ready;
    wire [ADDR_W-1:0] stage_mask = {ADDR_W{1'b1}} >> (LAST_STAGE - stage);
    wire [ADDR_W-1:0] next_index = butterfly_index + ADDR_W'(1);
    wire [ADDR_W-1:0] next_address = (next_index & stage_mask)
                                               << (LAST_STAGE - stage);

    // Every state update is caused by an accepted command or coefficient.
    // Back-pressure therefore freezes the valid coefficient and its metadata.
    always @(posedge clk) begin
        if (command_fire) begin
            if (!i_start) begin
                phase <= PH_ARMED;
                descriptor_armed <= 1'b1;
                job_started <= 1'b0;
                event_code <= EV_NONE;
                stage <= {STAGE_W{1'b0}};
                butterfly_index <= {ADDR_W{1'b0}};
                twiddle_addr <= {ADDR_W{1'b0}};
            end else begin
                phase <= PH_RUN;
                job_started <= 1'b1;
                event_code <= EV_START;
                stage <= {STAGE_W{1'b0}};
                butterfly_index <= {ADDR_W{1'b0}};
                twiddle_addr <= {ADDR_W{1'b0}};
            end
        end else if (coefficient_fire) begin
            if (butterfly_index == LAST_INDEX) begin
                if (stage == LAST_STAGE) begin
                    phase <= PH_DONE;
                    event_code <= EV_FINISH;
                end else begin
                    stage <= stage + STAGE_W'(1);
                    butterfly_index <= {ADDR_W{1'b0}};
                    twiddle_addr <= {ADDR_W{1'b0}};
                    event_code <= EV_BEAT;
                end
            end else begin
                butterfly_index <= next_index;
                twiddle_addr <= next_address;
                event_code <= EV_BEAT;
            end
        end
    end

    // Global chain precedence: ARM precedes START, then START precedes FINISH.
    // The event marker is retained while idle, rather than cleared by a timer.
    always @(posedge clk)
        if (event_code == EV_START)
            assert (descriptor_armed);

    always @(posedge clk)
        if (event_code == EV_FINISH)
            assert (descriptor_armed && job_started);
endmodule

module ast_bitmap_rotator #(
    parameter [31:0] WORD_BITS = 32'd32
) (
    input  wire clk,
    input  wire i_valid,
    output wire o_ready,
    input  wire [WORD_BITS-32'd1:0] i_word,
    output wire o_valid,
    input  wire i_ready,
    output wire [WORD_BITS-32'd1:0] o_word
);
    localparam [31:0] LAST_PHASE = WORD_BITS - 32'd1;

    reg [WORD_BITS-32'd1:0] rotate_word;
    reg [WORD_BITS-32'd1:0] accepted_word;
    reg [31:0] phase;
    reg active;
    reg scope_open;

    assign o_ready = !active;
    assign o_valid = active;
    assign o_word = rotate_word;

    wire accept_word = i_valid && o_ready;
    wire emit_word = o_valid && i_ready;

    initial begin
        rotate_word = {WORD_BITS{1'b0}};
        accepted_word = {WORD_BITS{1'b0}};
        phase = 32'd0;
        active = 1'b0;
        scope_open = 1'b0;
    end

    always @(posedge clk) begin
        if (accept_word) begin
            // Q: capture an accepted syntax-node bitmap and open its scope.
            accepted_word <= i_word;
            rotate_word <= i_word;
            phase <= 32'd0;
            active <= 1'b1;
            scope_open <= 1'b1;
        end else if (emit_word) begin
            rotate_word <= {
                rotate_word[WORD_BITS-32'd2:32'd0],
                rotate_word[WORD_BITS-32'd1]
            };
            if (phase == LAST_PHASE) begin
                // R: the final transfer completes one circular traversal.
                phase <= 32'd0;
                active <= 1'b0;
                scope_open <= 1'b0;
            end else begin
                phase <= phase + 32'd1;
            end
        end
    end

    // An observed marker must originate in the earlier accepted bitmap.
    // The captured bitmap remains fixed while the live word rotates.
    always @(*) begin
        if (scope_open && active && rotate_word[32'd0])
            assert (accepted_word[(phase == 32'd0)
                                  ? 32'd0 : (WORD_BITS - phase)]);
    end
endmodule

module scoped_predicate_comparator #(
    parameter integer LANES = 8,
    parameter integer DATA_WIDTH = 16
) (
    input wire clk,
    input wire i_ce,
    input wire scope_open,
    input wire scope_close,
    input wire arm_req,
    input wire start_req,
    input wire finish_req,
    input wire [LANES*DATA_WIDTH-1:0] i_a,
    input wire [LANES*DATA_WIDTH-1:0] i_b,
    input wire [1:0] i_relation,
    output reg [LANES-1:0] predicate_mask,
    output reg [1:0] relation_sel,
    output reg finish
);
    localparam [1:0] IDLE = 2'b00;
    localparam [1:0] ARMED = 2'b01;
    localparam [1:0] CHECKED = 2'b10;
    localparam [1:0] DONE = 2'b11;

    reg [LANES*DATA_WIDTH-1:0] operand_a;
    reg [LANES*DATA_WIDTH-1:0] operand_b;
    reg [1:0] phase;
    reg window;
    reg arm_seen;
    reg start_seen;
    reg pv;

    wire [LANES-1:0] incoming_mask;
    wire [LANES-1:0] comparison_mask;

    // Relation codes: equal, unsigned less-than, unsigned less-or-equal,
    // and not-equal. Each lane produces one predicate bit.
    genvar lane;
    generate
        for (lane = 0; lane < LANES; lane = lane + 1) begin : g_compare
            wire [DATA_WIDTH-1:0] a_in;
            wire [DATA_WIDTH-1:0] b_in;
            wire [DATA_WIDTH-1:0] a_saved;
            wire [DATA_WIDTH-1:0] b_saved;
            assign a_in = i_a[lane*DATA_WIDTH +: DATA_WIDTH];
            assign b_in = i_b[lane*DATA_WIDTH +: DATA_WIDTH];
            assign a_saved = operand_a[lane*DATA_WIDTH +: DATA_WIDTH];
            assign b_saved = operand_b[lane*DATA_WIDTH +: DATA_WIDTH];

            assign incoming_mask[lane] =
                (i_relation == 2'b00) ? (a_in == b_in) :
                (i_relation == 2'b01) ? (a_in < b_in) :
                (i_relation == 2'b10) ? (a_in <= b_in) :
                                           (a_in != b_in);

            assign comparison_mask[lane] =
                (relation_sel == 2'b00) ? (a_saved == b_saved) :
                (relation_sel == 2'b01) ? (a_saved < b_saved) :
                (relation_sel == 2'b10) ? (a_saved <= b_saved) :
                                            (a_saved != b_saved);
        end
    endgenerate

    initial begin
        operand_a = {(LANES*DATA_WIDTH){1'b0}};
        operand_b = {(LANES*DATA_WIDTH){1'b0}};
        relation_sel = 2'b00;
        predicate_mask = {LANES{1'b1}};
        phase = IDLE;
        window = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        finish = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            // Opening starts a fresh scope; closing has priority.
            if (scope_open || scope_close) begin
                window <= scope_open && !scope_close;
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                finish <= 1'b0;
            end else if (window) begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            operand_a <= i_a;
                            operand_b <= i_b;
                            relation_sel <= i_relation;
                            predicate_mask <= incoming_mask;
                            arm_seen <= 1'b1;
                            phase <= ARMED;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            // Only a transaction with a matching lane starts.
                            start_seen <= |comparison_mask;
                            phase <= CHECKED;
                        end
                    end
                    CHECKED: begin
                        if (finish_req) begin
                            // Report completion from the captured mask.
                            finish <= |predicate_mask;
                            phase <= DONE;
                        end
                    end
                    DONE: begin
                        // Retain the transaction record until the scope changes.
                    end
                endcase
            end
        end
    end

    // Within the latched scope, a completion edge requires both predecessors.
    always @(posedge clk)
        if (pv && window && $rose(finish))
            assert (arm_seen && start_seen);
endmodule

module csr_sticky_status_bridge #(
    parameter WORD_WIDTH = 16,
    parameter COUNT_WIDTH = 16
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_src_tick,
    input  wire                  i_sw_tick,
    input  wire [WORD_WIDTH-1:0] i_async_events,
    input  wire                  i_load_mask,
    input  wire [WORD_WIDTH-1:0] i_event_mask,
    input  wire                  i_clear,
    output wire [WORD_WIDTH-1:0] o_status,
    output wire                  o_clear_busy,
    output wire [COUNT_WIDTH-1:0] o_pending_clears
);
    localparam [COUNT_WIDTH-1:0] COUNT_ZERO = {COUNT_WIDTH{1'b0}};
    localparam [COUNT_WIDTH-1:0] COUNT_ONE = {{(COUNT_WIDTH-1){1'b0}}, 1'b1};

    reg [WORD_WIDTH-1:0] event_mask;
    reg [WORD_WIDTH-1:0] src_sticky;
    reg [WORD_WIDTH-1:0] sw_status_meta;
    reg [WORD_WIDTH-1:0] sw_status_sync;

    reg clear_req;
    reg src_req_meta;
    reg src_req_sync;
    reg src_ack;
    reg sw_ack_meta;
    reg sw_ack_sync;
    reg clear_busy;
    reg [COUNT_WIDTH-1:0] pending_clears;
    reg armed;
    reg pv;

    wire clear_accept = i_ce && i_sw_tick && i_clear && !clear_busy;
    wire clear_finish = i_ce && i_sw_tick && clear_busy &&
                        (sw_ack_sync == clear_req);

    // Counter D input includes idle behavior, so its previous-cycle value
    // is precisely the occupancy installed by the preceding clock edge.
    wire [COUNT_WIDTH-1:0] clear_count_d =
        clear_accept ? (pending_clears + COUNT_ONE) :
        clear_finish ? (pending_clears - COUNT_ONE) : pending_clears;

    initial begin
        event_mask = {WORD_WIDTH{1'b1}};
        src_sticky = {WORD_WIDTH{1'b0}};
        sw_status_meta = {WORD_WIDTH{1'b0}};
        sw_status_sync = {WORD_WIDTH{1'b0}};
        clear_req = 1'b0;
        src_req_meta = 1'b0;
        src_req_sync = 1'b0;
        src_ack = 1'b0;
        sw_ack_meta = 1'b0;
        sw_ack_sync = 1'b0;
        clear_busy = 1'b0;
        pending_clears = COUNT_ZERO;
        armed = 1'b0;
        pv = 1'b0;
    end

    // Domain ticks model independently enabled source and software clocks.
    // The common enable freezes every state register when low.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            pending_clears <= clear_count_d;

            if (i_load_mask)
                event_mask <= i_event_mask;

            if (i_src_tick) begin
                src_req_meta <= clear_req;
                src_req_sync <= src_req_meta;

                if (src_req_sync != src_ack) begin
                    // Acknowledge the synchronized clear toggle. New events
                    // dominate clearing, so an arriving event is not lost.
                    src_ack <= src_req_sync;
                    src_sticky <= i_async_events & event_mask;
                end else begin
                    src_sticky <= src_sticky | (i_async_events & event_mask);
                end
            end

            if (i_sw_tick) begin
                sw_status_meta <= src_sticky;
                sw_status_sync <= sw_status_meta;
                sw_ack_meta <= src_ack;
                sw_ack_sync <= sw_ack_meta;

                // Q: software first observes a synchronized sticky event.
                if (|sw_status_sync)
                    armed <= 1'b1;

                if (clear_accept) begin
                    clear_req <= !clear_req;
                    clear_busy <= 1'b1;
                end else if (clear_finish) begin
                    clear_busy <= 1'b0;
                end
            end
        end
    end

    assign o_status = sw_status_sync;
    assign o_clear_busy = clear_busy;
    assign o_pending_clears = pending_clears;

    // After Q, the preceding cycle's installed clear occupancy is at most one.
    always @(posedge clk) begin
        if (pv && armed)
            assert ($past(clear_count_d) <= COUNT_ONE);
    end
endmodule

module pixel_pulse_pending #(
    parameter integer COUNT_W = 32
) (
    input wire clk,
    input wire i_ce,
    input wire i_pixel_pulse,
    input wire i_dispatch,
    input wire i_slow_tick,
    input wire i_load_limit,
    input wire [COUNT_W-1:0] i_limit,
    input wire i_begin_tile,
    input wire i_end_tile,
    output reg slow_pixel_pulse
);
    localparam [COUNT_W-1:0] ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] ONE = {{(COUNT_W-1){1'b0}}, 1'b1};

    reg [COUNT_W-1:0] pending;
    reg [COUNT_W-1:0] outstanding;
    reg [COUNT_W-1:0] pulse_limit;
    reg req_toggle;
    reg ack_toggle;
    reg window_open;
    reg pv;

    wire in_flight = (req_toggle != ack_toggle);
    wire accept_pulse = i_pixel_pulse && (outstanding < pulse_limit);
    wire launch_request = i_dispatch && !in_flight && (pending != ZERO);
    wire retire_request = i_slow_tick && in_flight;

    initial begin
        pending = ZERO;
        outstanding = ZERO;
        pulse_limit = {COUNT_W{1'b1}};
        req_toggle = 1'b0;
        ack_toggle = 1'b0;
        window_open = 1'b0;
        slow_pixel_pulse = 1'b0;
        pv = 1'b0;
    end

    // i_slow_tick models an edge of the slower receiving domain.
    // Requests remain outstanding until that domain acknowledges them.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            if (i_load_limit)
                pulse_limit <= i_limit;

            if (i_end_tile)
                window_open <= 1'b0;
            else if (i_begin_tile)
                window_open <= 1'b1;

            case ({accept_pulse, launch_request})
                2'b10: pending <= pending + ONE;
                2'b01: pending <= pending - ONE;
                default: pending <= pending;
            endcase

            case ({accept_pulse, retire_request})
                2'b10: outstanding <= outstanding + ONE;
                2'b01: outstanding <= outstanding - ONE;
                default: outstanding <= outstanding;
            endcase

            if (launch_request)
                req_toggle <= !req_toggle;

            if (retire_request)
                ack_toggle <= req_toggle;

            slow_pixel_pulse <= retire_request;
        end
    end

    // The registered pulse reports the preceding enabled edge's delivery.
    // Inside the previous tile window, delivery and an empty work ledger
    // must never have occurred together on that edge.
    always @(posedge clk) begin
        if (pv && $past(window_open) && $past(i_ce))
            assert (!(slow_pixel_pulse && ($past(outstanding) == ZERO)));
    end
endmodule

module phased_case_emitter #(
    parameter integer DEPTH = 16
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        seed_valid,
    input  wire [63:0] seed_in,
    output wire        seed_ready,
    output reg  [63:0] issued_word,
    output reg  [63:0] issued_phase,
    output reg  [63:0] issued_mask
);
    // DEPTH is the number of timing phases and table entries; use 2 through 16.
    localparam [63:0] DEPTH64 = DEPTH;
    localparam [63:0] LAST_PHASE = DEPTH64 - 64'd1;
    localparam [DEPTH-1:0] PHASE_ONE = {{(DEPTH-1){1'b0}}, 1'b1};

    reg [63:0] phase;
    reg [DEPTH-1:0] phase_enable;
    reg [63:0] filled;
    reg [63:0] seed;
    reg draining;
    reg window;

    reg [63:0] words [0:DEPTH-1];
    reg [DEPTH-1:0] valid;

    // A seed is accepted only when the preceding batch has completely drained.
    assign seed_ready = i_ce && !draining && (phase == 64'd0);
    wire advance = i_ce &&
                   (draining || (phase != 64'd0) || seed_valid);
    wire [63:0] next_phase = (phase == LAST_PHASE)
                             ? 64'd0 : phase + 64'd1;
    wire [63:0] fill_seed = (phase == 64'd0) ? seed_in : seed;

    // Q opens the checking window; the final dispatch closes it.
    wire open_window = advance && draining && (phase == 64'd0);
    wire close_window = advance && draining && (phase == LAST_PHASE);

    initial begin
        phase = 64'd0;
        phase_enable = PHASE_ONE;
        filled = 64'd0;
        seed = 64'd0;
        draining = 1'b0;
        window = 1'b0;
        issued_word = 64'd0;
        issued_phase = 64'd0;
        issued_mask = 64'd1;
    end

    // The registered decoder supplies the per-entry timing strobes.
    genvar slot;
    generate
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin : entries
            initial begin
                words[slot] = 64'd0;
                valid[slot] = 1'b0;
            end
            always @(posedge clk) begin
                if (advance && phase_enable[slot]) begin
                    if (!draining) begin
                        words[slot] <= fill_seed ^ phase;
                        valid[slot] <= 1'b1;
                    end else begin
                        valid[slot] <= 1'b0;
                    end
                end
            end
        end
    endgenerate

    reg [63:0] selected_word;
    integer mux_index;
    always @(*) begin
        selected_word = 64'd0;
        for (mux_index = 0; mux_index < DEPTH; mux_index = mux_index + 1)
            if (phase_enable[mux_index])
                selected_word = selected_word | words[mux_index];
    end

    always @(posedge clk) begin
        if (advance) begin
            phase <= next_phase;
            phase_enable <= PHASE_ONE << next_phase;

            if (!draining) begin
                if (phase == 64'd0)
                    seed <= seed_in;
                filled <= filled + 64'd1;
                if (phase == LAST_PHASE)
                    draining <= 1'b1;
            end else begin
                filled <= filled - 64'd1;
                issued_word <= selected_word;
                issued_phase <= phase;
                issued_mask <= phase_enable;
                if (phase == LAST_PHASE)
                    draining <= 1'b0;
            end

            if (close_window)
                window <= 1'b0;
            else if (open_window)
                window <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (window) begin
            assert (issued_word == (seed ^ issued_phase));
            assert (issued_mask == (64'd1 << issued_phase));
        end
    end
endmodule

module word_hash_padding #(
    // Supported block sizes are powers of two, at least four words.
    parameter [31:0] BLOCK_WORDS = 32'd4
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        ce,
    input  wire        i_valid,
    input  wire [31:0] i_data,
    input  wire        i_finish,
    output wire        o_valid,
    output wire [31:0] o_data,
    output wire        o_done
);
    localparam [31:0] BLOCK_BYTES = BLOCK_WORDS * 32'd4;
    localparam [63:0] BLOCK_BITS = {32'd0, BLOCK_BYTES} * 64'd8;
    localparam [63:0] LENGTH_HI_BIT_POS = BLOCK_BITS - 64'd64;
    localparam [63:0] LENGTH_LO_BIT_POS = BLOCK_BITS - 64'd32;

    reg [63:0] total_length_bits;
    reg [63:0] emitted_bits;
    reg [31:0] byte_pos;
    reg padding;
    reg marker_pending;
    reg length_hi_sent;
    reg finished;

    wire [63:0] stream_bit_pos;
    wire pad_body;
    wire length_hi_sel;
    wire length_lo_sel;
    wire zero_fill_sel;

    assign stream_bit_pos = emitted_bits % BLOCK_BITS;
    assign pad_body = padding && !marker_pending;

    // The global stream counter schedules the high length word and fill.
    // The block-local byte cursor schedules the low length word.
    assign length_hi_sel = pad_body &&
                           (stream_bit_pos == LENGTH_HI_BIT_POS);
    assign length_lo_sel = pad_body && length_hi_sent &&
                           (byte_pos == BLOCK_BYTES - 32'd4);
    assign zero_fill_sel = pad_body &&
                           (stream_bit_pos != LENGTH_HI_BIT_POS) &&
                           (!length_hi_sent ||
                            (stream_bit_pos != LENGTH_LO_BIT_POS));

    // Inputs are whole message words. Each output word is serialized
    // most-significant byte first, including the two length words.
    assign o_valid = ce && !finished &&
                     (padding || (i_valid && !i_finish));
    assign o_data = !padding ? i_data :
                    marker_pending ? 32'h80000000 :
                    length_hi_sel ? total_length_bits[63:32] :
                    length_lo_sel ? total_length_bits[31:0] :
                    32'd0;
    assign o_done = finished;

    initial begin
        total_length_bits = 64'd0;
        emitted_bits = 64'd0;
        byte_pos = 32'd0;
        padding = 1'b0;
        marker_pending = 1'b0;
        length_hi_sent = 1'b0;
        finished = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            total_length_bits <= 64'd0;
            emitted_bits <= 64'd0;
            byte_pos <= 32'd0;
            padding <= 1'b0;
            marker_pending <= 1'b0;
            length_hi_sent <= 1'b0;
            finished <= 1'b0;
        end else if (ce && !finished) begin
            if (o_valid) begin
                emitted_bits <= emitted_bits + 64'd32;
                if (byte_pos == BLOCK_BYTES - 32'd4)
                    byte_pos <= 32'd0;
                else
                    byte_pos <= byte_pos + 32'd4;
            end

            if (padding) begin
                if (marker_pending) begin
                    marker_pending <= 1'b0;
                end else begin
                    if (length_hi_sel)
                        length_hi_sent <= 1'b1;
                    if (length_lo_sel) begin
                        padding <= 1'b0;
                        finished <= 1'b1;
                    end
                end
            end else if (i_finish) begin
                padding <= 1'b1;
                marker_pending <= 1'b1;
                length_hi_sent <= 1'b0;
            end else if (i_valid) begin
                total_length_bits <= total_length_bits + 64'd32;
            end
        end
    end

    // Neither another length word nor zero fill may overlap the low word.
    always @(posedge clk) begin
        if (length_lo_sel)
            assert (!length_hi_sel);
        if (length_lo_sel)
            assert (!zero_fill_sel);
    end
endmodule

module scroll_command_counter #(
    parameter integer DATA_W = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [DATA_W-1:0]     i_cmd,
    output wire [DATA_W-1:0]     o_scroll,
    output wire                  o_pending
);
    localparam logic [DATA_W-1:0] UNIT          = 8'd1;
    localparam logic [DATA_W-1:0] CMD_OPEN      = 8'h10;
    localparam logic [DATA_W-1:0] CMD_CLOSE     = 8'h11;
    localparam logic [DATA_W-1:0] CMD_PREP_UP   = 8'h20;
    localparam logic [DATA_W-1:0] CMD_PREP_DOWN = 8'h21;
    localparam logic [DATA_W-1:0] CMD_COMMIT    = 8'h30;
    localparam logic [DATA_W-1:0] CMD_ACK       = 8'h40;

    typedef enum logic [1:0] {
        IDLE     = 2'b00,
        PREPARED = 2'b01,
        DONE     = 2'b10
    } state_t;

    state_t state;
    logic [DATA_W-1:0] count;
    logic [DATA_W-1:0] prior_count;
    logic last_up;
    logic window;

    initial begin
        state       = IDLE;
        count       = {DATA_W{1'b0}};
        prior_count = {DATA_W{1'b0}};
        last_up     = 1'b0;
        window      = 1'b0;
    end

    // Only commands supported by the current phase can transfer.
    // A pending result back-pressures new preparation commands until ACK.
    assign i_ready = i_ce && (
        ((state == IDLE) &&
         ((i_cmd == CMD_OPEN) || (i_cmd == CMD_CLOSE) ||
          (i_cmd == CMD_PREP_UP) || (i_cmd == CMD_PREP_DOWN))) ||
        ((state == PREPARED) && (i_cmd == CMD_COMMIT)) ||
        ((state == DONE) && (i_cmd == CMD_ACK))
    );

    wire take = i_valid && i_ready;
    assign o_scroll  = count;
    assign o_pending = (state == DONE);

    always @(posedge clk) begin
        if (take) begin
            case (state)
                IDLE: begin
                    case (i_cmd)
                        CMD_OPEN:  window <= 1'b1;
                        CMD_CLOSE: window <= 1'b0;
                        CMD_PREP_UP, CMD_PREP_DOWN: begin
                            prior_count <= count;
                            last_up <= (i_cmd == CMD_PREP_UP);
                            state <= PREPARED;
                        end
                        default: begin end
                    endcase
                end
                PREPARED: begin
                    // The scroll counter wraps modulo its declared width.
                    if (last_up)
                        count <= count + UNIT;
                    else
                        count <= count - UNIT;
                    state <= DONE;
                end
                DONE: begin
                    // ACK retires the result and synchronizes the snapshot.
                    prior_count <= count;
                    state <= IDLE;
                end
                default: begin end
            endcase
        end
    end

    // Between accepted OPEN and CLOSE commands, each completed movement
    // must correspond to the position recorded by its earlier preparation.
    always @(posedge clk) begin
        if (window && (state == DONE) && last_up)
            assert (count == prior_count + UNIT);
        if (window && (state == DONE) && !last_up)
            assert (count == prior_count - UNIT);
    end
endmodule

module instruction_prefetch_fifo #(
    parameter DATA_WIDTH = 8,
    parameter DEPTH = 16
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_fetch_begin,
    input  wire                  i_fetch_end,
    input  wire                  i_enqueue,
    input  wire                  i_retire,
    input  wire [DATA_WIDTH-1:0] i_instruction,
    output wire [DATA_WIDTH-1:0] o_instruction,
    output wire [7:0]            o_occupancy
);
    localparam [7:0] SRAM_LIMIT = DEPTH;
    localparam [7:0] LAST_ADDR = SRAM_LIMIT - 8'd1;
    localparam [7:0] TOTAL_LIMIT = SRAM_LIMIT + 8'd2;

    // One-entry input and output flop FIFOs surround the SRAM ring.
    reg [DATA_WIDTH-1:0] tail_data;
    reg [DATA_WIDTH-1:0] head_data;
    reg tail_valid;
    reg head_valid;
    reg [DATA_WIDTH-1:0] sram [0:DEPTH-1];
    reg [7:0] rd_ptr;
    reg [7:0] wr_ptr;
    reg [7:0] sram_count;
    reg [7:0] total_count;
    reg bypass_select;
    reg window_active;

    integer init_idx;
    initial begin
        tail_data = {DATA_WIDTH{1'b0}};
        head_data = {DATA_WIDTH{1'b0}};
        tail_valid = 1'b0;
        head_valid = 1'b0;
        rd_ptr = 8'd0;
        wr_ptr = 8'd0;
        sram_count = 8'd0;
        total_count = 8'd0;
        bypass_select = 1'b1;
        window_active = 1'b0;
        for (init_idx = 0; init_idx < DEPTH; init_idx = init_idx + 1)
            sram[init_idx] = {DATA_WIDTH{1'b0}};
    end

    wire retire_head = i_retire && head_valid;
    wire head_space = !head_valid || retire_head;
    wire read_sram = head_space && !bypass_select;
    wire bypass_tail = head_space && bypass_select && tail_valid;
    wire write_sram = tail_valid && !bypass_tail &&
                      (sram_count < SRAM_LIMIT);
    wire tail_depart = bypass_tail || write_sram;
    wire accept_input = i_enqueue && (!tail_valid || tail_depart);

    wire [7:0] sram_count_next =
        (write_sram && !read_sram) ? (sram_count + 8'd1) :
        (read_sram && !write_sram) ? (sram_count - 8'd1) :
                                   sram_count;

    assign o_instruction = head_data;
    assign o_occupancy = total_count;

    always @(posedge clk) begin
        if (i_ce) begin
            // Fetch-window end wins if both boundary commands occur.
            if (i_fetch_end)
                window_active <= 1'b0;
            else if (i_fetch_begin)
                window_active <= 1'b1;

            // The head flop is also the synchronous SRAM read register.
            if (head_space) begin
                head_valid <= read_sram || bypass_tail;
                if (read_sram)
                    head_data <= sram[rd_ptr];
                else if (bypass_tail)
                    head_data <= tail_data;
            end

            if (write_sram)
                sram[wr_ptr] <= tail_data;

            if (read_sram) begin
                if (rd_ptr == LAST_ADDR)
                    rd_ptr <= 8'd0;
                else
                    rd_ptr <= rd_ptr + 8'd1;
            end
            if (write_sram) begin
                if (wr_ptr == LAST_ADDR)
                    wr_ptr <= 8'd0;
                else
                    wr_ptr <= wr_ptr + 8'd1;
            end

            if (accept_input) begin
                tail_data <= i_instruction;
                tail_valid <= 1'b1;
            end else if (tail_depart) begin
                tail_valid <= 1'b0;
            end

            sram_count <= sram_count_next;
            bypass_select <= (sram_count_next == 8'd0);

            case ({accept_input, retire_head})
                2'b10: total_count <= total_count + 8'd1;
                2'b01: total_count <= total_count - 8'd1;
                default: total_count <= total_count;
            endcase
        end
    end

    always @(posedge clk)
        if (window_active)
            assert (total_count <= TOTAL_LIMIT);
endmodule

module loop_exit_predictor #(
    parameter integer ENTRIES = 16
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_req_valid,
    output wire        o_req_ready,
    input  wire        i_flush,
    input  wire        i_load_config,
    input  wire [15:0] i_conf_limit,
    input  wire [15:0] i_branch_tag,
    input  wire        i_taken,
    output reg         o_complete,
    output reg  [15:0] o_result_tag,
    output reg         o_predict_exit
);
    localparam [15:0] ENTRY_COUNT = ENTRIES;
    localparam [15:0] LAST_ENTRY = ENTRY_COUNT - 16'd1;
    localparam [15:0] MAX_COUNT = 16'hffff;

    reg [ENTRIES-1:0] entry_valid;
    reg [15:0] tags [0:ENTRIES-1];
    reg [15:0] trip_count [0:ENTRIES-1];
    reg [15:0] iteration [0:ENTRIES-1];
    reg [15:0] confidence [0:ENTRIES-1];

    reg [15:0] conf_limit;
    reg [15:0] pending_tag;
    reg        pending_taken;
    reg        busy;
    reg [15:0] scan_pos;
    reg [15:0] replace_pos;
    reg        hit_seen;
    reg [15:0] hit_pos;
    reg [15:0] deadline;
    reg        before_flush;

    assign o_req_ready = i_ce && !busy;
    wire accept_request = i_req_valid && o_req_ready;

    wire scan_match = entry_valid[scan_pos] &&
                      (tags[scan_pos] == pending_tag);
    wire resolved_hit = hit_seen || scan_match;
    wire [15:0] selected_pos = hit_seen ? hit_pos :
                              (scan_match ? scan_pos : replace_pos);
    wire [15:0] observed_trip =
        (iteration[selected_pos] == MAX_COUNT) ? MAX_COUNT :
        (iteration[selected_pos] + 16'd1);
    wire exit_prediction = resolved_hit &&
        (trip_count[selected_pos] != 16'd0) &&
        (confidence[selected_pos] >= conf_limit) &&
        (iteration[selected_pos] == (trip_count[selected_pos] - 16'd1));

    integer n;
    initial begin
        entry_valid = {ENTRIES{1'b0}};
        for (n = 0; n < ENTRIES; n = n + 1) begin
            tags[n] = 16'd0;
            trip_count[n] = 16'd0;
            iteration[n] = 16'd0;
            confidence[n] = 16'd0;
        end
        conf_limit = 16'd2;
        pending_tag = 16'd0;
        pending_taken = 1'b0;
        busy = 1'b0;
        scan_pos = 16'd0;
        replace_pos = 16'd0;
        hit_seen = 1'b0;
        hit_pos = 16'd0;
        deadline = 16'd0;
        before_flush = 1'b1;
        o_complete = 1'b0;
        o_result_tag = 16'd0;
        o_predict_exit = 1'b0;
    end

    // One associative-table entry is examined per enabled cycle.
    // Lowering i_ce freezes every register, including the response budget.
    always @(posedge clk) begin
        if (i_ce) begin
            if (busy) begin
                deadline <= deadline - 16'd1;
                if (!hit_seen && scan_match) begin
                    hit_seen <= 1'b1;
                    hit_pos <= scan_pos;
                end

                if (scan_pos == LAST_ENTRY) begin
                    busy <= 1'b0;
                    o_complete <= 1'b1;
                    o_result_tag <= pending_tag;
                    o_predict_exit <= exit_prediction;

                    if (resolved_hit) begin
                        if (pending_taken) begin
                            if (iteration[selected_pos] != MAX_COUNT)
                                iteration[selected_pos] <=
                                    iteration[selected_pos] + 16'd1;
                        end else begin
                            iteration[selected_pos] <= 16'd0;
                            if (trip_count[selected_pos] == observed_trip) begin
                                if (confidence[selected_pos] != MAX_COUNT)
                                    confidence[selected_pos] <=
                                        confidence[selected_pos] + 16'd1;
                            end else begin
                                trip_count[selected_pos] <= observed_trip;
                                confidence[selected_pos] <= 16'd0;
                            end
                        end
                    end else begin
                        entry_valid[selected_pos] <= 1'b1;
                        tags[selected_pos] <= pending_tag;
                        trip_count[selected_pos] <=
                            pending_taken ? 16'd0 : 16'd1;
                        iteration[selected_pos] <=
                            pending_taken ? 16'd1 : 16'd0;
                        confidence[selected_pos] <= 16'd0;
                        if (replace_pos == LAST_ENTRY)
                            replace_pos <= 16'd0;
                        else
                            replace_pos <= replace_pos + 16'd1;
                    end
                end else begin
                    scan_pos <= scan_pos + 16'd1;
                end
            end else if (accept_request) begin
                o_complete <= 1'b0;
                if (i_flush) begin
                    entry_valid <= {ENTRIES{1'b0}};
                    replace_pos <= 16'd0;
                    scan_pos <= 16'd0;
                    hit_seen <= 1'b0;
                    hit_pos <= 16'd0;
                    before_flush <= 1'b0;
                end else if (i_load_config) begin
                    conf_limit <= i_conf_limit;
                end else begin
                    pending_tag <= i_branch_tag;
                    pending_taken <= i_taken;
                    scan_pos <= 16'd0;
                    hit_seen <= 1'b0;
                    hit_pos <= 16'd0;
                    deadline <= ENTRY_COUNT;
                    busy <= 1'b1;
                end
            end
        end
    end

    // Before the first accepted flush, an outstanding lookup must not
    // exhaust its enabled-cycle budget before producing its result.
    always @(*) begin
        if (before_flush && busy)
            assert (deadline != 16'd0);
    end
endmodule

module message_packetizer #(
    parameter [31:0] PAYLOAD_WORDS = 32'd12
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_launch,
    input  wire [PAYLOAD_WORDS*32-1:0] i_message,
    output wire o_inject,
    output wire o_header,
    output wire [31:0] o_flit_word,
    output wire [31:0] o_flit_sequence,
    output wire [31:0] o_flit_index
);
    localparam [31:0] PACKET_FLITS = PAYLOAD_WORDS + 32'd1;
    localparam [PAYLOAD_WORDS-1:0] FIRST_CURSOR =
        {{(PAYLOAD_WORDS-1){1'b0}}, 1'b1};

    reg [31:0] pending_message [0:PAYLOAD_WORDS-1];
    reg [31:0] packet_sequence;
    reg [31:0] next_sequence;
    reg [31:0] flit_index;
    reg [PAYLOAD_WORDS-1:0] cursor;
    reg header_pending;
    reg packet_window;

    wire [31:0] payload_mux [0:PAYLOAD_WORDS];
    assign payload_mux[0] = 32'd0;

    genvar g;
    generate
        for (g = 32'd0; g < PAYLOAD_WORDS; g = g + 32'd1) begin : payload_slots
            initial pending_message[g] = 32'd0;

            always @(posedge clk) begin
                if (i_ce && !packet_window && i_launch)
                    pending_message[g] <= i_message[g*32 +: 32];
            end

            assign payload_mux[g+1] = payload_mux[g] |
                (pending_message[g] & {32{cursor[g]}});
        end
    endgenerate

    initial begin
        packet_sequence = 32'd0;
        next_sequence = 32'd0;
        flit_index = PACKET_FLITS;
        cursor = {PAYLOAD_WORDS{1'b0}};
        header_pending = 1'b0;
        packet_window = 1'b0;
    end

    // Injection occurs on enabled edges; there is no ready/acknowledge handshake.
    assign o_inject = i_ce && packet_window;
    assign o_header = header_pending;
    assign o_flit_sequence = packet_sequence;
    assign o_flit_index = flit_index;
    assign o_flit_word = header_pending ? packet_sequence : payload_mux[PAYLOAD_WORDS];

    always @(posedge clk) begin
        if (i_ce) begin
            if (!packet_window) begin
                if (i_launch) begin
                    // Q: capture a message and open its packet window.
                    packet_sequence <= next_sequence;
                    next_sequence <= next_sequence + 32'd1;
                    flit_index <= 32'd0;
                    cursor <= FIRST_CURSOR;
                    header_pending <= 1'b1;
                    packet_window <= 1'b1;
                end
            end else if (header_pending) begin
                header_pending <= 1'b0;
                flit_index <= flit_index + 32'd1;
            end else begin
                flit_index <= flit_index + 32'd1;
                cursor <= cursor << 32'd1;
                // R: injecting the final payload closes the window.
                if (cursor[PAYLOAD_WORDS-1])
                    packet_window <= 1'b0;
            end
        end
    end

    always @(*) begin
        if (packet_window)
            assert (flit_index <= PAYLOAD_WORDS);
    end
endmodule

module fp64_classify_queue #(
    parameter integer WORD_W = 64,
    parameter integer EXP_W = 11,
    parameter [63:0] DEPTH = 64'd2
) (
    input  wire clk,
    input  wire i_valid,
    output wire i_ready,
    input  wire [WORD_W-1:0] i_data,
    input  wire i_scope_begin,
    input  wire i_scope_end,
    output wire o_valid,
    input  wire o_ready,
    output wire [WORD_W-1:0] o_data,
    output wire [WORD_W-1:0] o_class
);
    localparam integer FRAC_W = WORD_W - EXP_W - 1;
    localparam [WORD_W-1:0] POS_ZERO   = 64'd1;
    localparam [WORD_W-1:0] NEG_ZERO   = 64'd2;
    localparam [WORD_W-1:0] POS_SUB    = 64'd4;
    localparam [WORD_W-1:0] NEG_SUB    = 64'd8;
    localparam [WORD_W-1:0] POS_NORMAL = 64'd16;
    localparam [WORD_W-1:0] NEG_NORMAL = 64'd32;
    localparam [WORD_W-1:0] POS_INF    = 64'd64;
    localparam [WORD_W-1:0] NEG_INF    = 64'd128;
    localparam [WORD_W-1:0] POS_SNAN   = 64'd256;
    localparam [WORD_W-1:0] NEG_SNAN   = 64'd512;
    localparam [WORD_W-1:0] POS_QNAN   = 64'd1024;
    localparam [WORD_W-1:0] NEG_QNAN   = 64'd2048;

    function automatic [WORD_W-1:0] classify(input [WORD_W-1:0] value);
        begin
            if (value[WORD_W-2:FRAC_W] == {EXP_W{1'b0}}) begin
                if (value[FRAC_W-1:0] == {FRAC_W{1'b0}})
                    classify = value[WORD_W-1] ? NEG_ZERO : POS_ZERO;
                else
                    classify = value[WORD_W-1] ? NEG_SUB : POS_SUB;
            end else if (value[WORD_W-2:FRAC_W] == {EXP_W{1'b1}}) begin
                if (value[FRAC_W-1:0] == {FRAC_W{1'b0}})
                    classify = value[WORD_W-1] ? NEG_INF : POS_INF;
                else if (value[FRAC_W-1])
                    classify = value[WORD_W-1] ? NEG_QNAN : POS_QNAN;
                else
                    classify = value[WORD_W-1] ? NEG_SNAN : POS_SNAN;
            end else begin
                classify = value[WORD_W-1] ? NEG_NORMAL : POS_NORMAL;
            end
        end
    endfunction

    reg [WORD_W-1:0] data_mem [0:DEPTH-64'd1];
    reg [WORD_W-1:0] class_mem [0:DEPTH-64'd1];
    reg [63:0] rptr, wptr, count;
    reg window;

    wire [WORD_W-1:0] decoded_mem [0:DEPTH-64'd1];
    wire [DEPTH-64'd1:0] slot_live;
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : entry_decode
            localparam [63:0] SLOT = g;
            wire [63:0] distance_from_head;
            assign distance_from_head = (SLOT >= rptr)
                ? SLOT - rptr : DEPTH - rptr + SLOT;
            assign slot_live[g] = distance_from_head < count;
            assign decoded_mem[g] = classify(data_mem[g]);
        end
    endgenerate

    assign i_ready = count < DEPTH;
    assign o_valid = count != 64'd0;
    assign o_data = data_mem[rptr];
    assign o_class = class_mem[rptr];
    wire [WORD_W-1:0] head_expected = decoded_mem[rptr];
    wire push = i_valid && i_ready;
    wire pop = o_valid && o_ready;

    // Scope commands accompany accepted operands; closing has priority.
    wire scope_q = push && i_scope_begin && !i_scope_end;
    wire scope_r = push && i_scope_end;

    integer k;
    initial begin
        rptr = 64'd0;
        wptr = 64'd0;
        count = 64'd0;
        window = 1'b0;
        for (k = 0; k < DEPTH; k = k + 1) begin
            data_mem[k] = 64'd0;
            class_mem[k] = POS_ZERO;
        end
    end

    always @(posedge clk) begin
        if (push) begin
            data_mem[wptr] <= i_data;
            class_mem[wptr] <= classify(i_data);
            if (wptr == DEPTH - 64'd1)
                wptr <= 64'd0;
            else
                wptr <= wptr + 64'd1;
        end
        if (pop) begin
            if (rptr == DEPTH - 64'd1)
                rptr <= 64'd0;
            else
                rptr <= rptr + 64'd1;
        end
        case ({push, pop})
            2'b10: count <= count + 64'd1;
            2'b01: count <= count - 64'd1;
            default: begin end
        endcase
        if (scope_r)
            window <= 1'b0;
        else if (scope_q)
            window <= 1'b1;
    end

    always @(posedge clk)
        assert (!window || !o_valid || (o_class == head_expected));
endmodule

module md5_command_round64 #(
    parameter integer WORD_WIDTH = 64,
    parameter integer STORAGE_ENTRIES = 128
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_valid,
    output wire i_ready,
    input  wire i_load,
    input  wire [511:0] i_block,
    output wire o_done,
    output wire [WORD_WIDTH-1:0] o_a,
    output wire [WORD_WIDTH-1:0] o_b,
    output wire [WORD_WIDTH-1:0] o_c,
    output wire [WORD_WIDTH-1:0] o_d
);
    // Commands are accepted only on valid && ready. A load command starts
    // a block; each subsequent non-load command executes one MD5 operation.
    // DONE retains the result until another load command is accepted.
    typedef enum logic [1:0] {
        IDLE = 2'b00,
        BUSY = 2'b01,
        DONE = 2'b10
    } state_t;
    state_t state;

    localparam [63:0] WORD_MASK = 64'h00000000ffffffff;
    localparam [63:0] BANK_COUNT = STORAGE_ENTRIES / 8;
    localparam [63:0] IV_A = 64'h0000000067452301;
    localparam [63:0] IV_B = 64'h00000000efcdab89;
    localparam [63:0] IV_C = 64'h0000000098badcfe;
    localparam [63:0] IV_D = 64'h0000000010325476;

    // Each bank retains one 512-bit message as eight full-width words.
    reg [WORD_WIDTH-1:0] block_store [0:STORAGE_ENTRIES-1];
    reg [WORD_WIDTH-1:0] write_bank, active_bank;
    reg [WORD_WIDTH-1:0] a, b, c, d;
    reg [WORD_WIDTH-1:0] step;
    reg [WORD_WIDTH-1:0] phase_token;
    reg window_open;

    assign i_ready = i_ce &&
        (((state == IDLE || state == DONE) && i_load) ||
         ((state == BUSY) && !i_load));
    wire fire = i_valid && i_ready;
    wire load_fire = fire && i_load;
    wire round_fire = fire && !i_load;

    assign o_done = (state == DONE);
    assign o_a = a;
    assign o_b = b;
    assign o_c = c;
    assign o_d = d;

    initial begin
        state = IDLE;
        write_bank = 64'd0;
        active_bank = 64'd0;
        a = IV_A;
        b = IV_B;
        c = IV_C;
        d = IV_D;
        step = 64'd0;
        phase_token = 64'd0;
        window_open = 1'b0;
    end

    genvar slot;
    generate
        for (slot = 0; slot < STORAGE_ENTRIES; slot = slot + 1) begin : message_storage
            localparam [63:0] THIS_BANK = slot / 8;
            localparam integer BIT_OFFSET = (slot % 8) * 64;
            initial block_store[slot] = 64'd0;
            always @(posedge clk) begin
                if (load_fire && write_bank == THIS_BANK)
                    block_store[slot] <= i_block[BIT_OFFSET +: 64];
            end
        end
    endgenerate

    function automatic [63:0] message_index(input [63:0] n);
        begin
            if (n < 64'd16)
                message_index = n;
            else if (n < 64'd32)
                message_index = (64'd5 * n + 64'd1) & 64'd15;
            else if (n < 64'd48)
                message_index = (64'd3 * n + 64'd5) & 64'd15;
            else
                message_index = (64'd7 * n) & 64'd15;
        end
    endfunction

    function automatic [63:0] rotation_amount(input [63:0] n);
        begin
            case (n >> 64'd4)
                64'd0: rotation_amount =
                    ((n & 64'd3) == 64'd0) ? 64'd7 :
                    ((n & 64'd3) == 64'd1) ? 64'd12 :
                    ((n & 64'd3) == 64'd2) ? 64'd17 : 64'd22;
                64'd1: rotation_amount =
                    ((n & 64'd3) == 64'd0) ? 64'd5 :
                    ((n & 64'd3) == 64'd1) ? 64'd9 :
                    ((n & 64'd3) == 64'd2) ? 64'd14 : 64'd20;
                64'd2: rotation_amount =
                    ((n & 64'd3) == 64'd0) ? 64'd4 :
                    ((n & 64'd3) == 64'd1) ? 64'd11 :
                    ((n & 64'd3) == 64'd2) ? 64'd16 : 64'd23;
                default: rotation_amount =
                    ((n & 64'd3) == 64'd0) ? 64'd6 :
                    ((n & 64'd3) == 64'd1) ? 64'd10 :
                    ((n & 64'd3) == 64'd2) ? 64'd15 : 64'd21;
            endcase
        end
    endfunction

    function automatic [63:0] md5_constant(input [63:0] n);
        begin
            case (n)
                64'd0:  md5_constant = 64'h00000000d76aa478;
                64'd1:  md5_constant = 64'h00000000e8c7b756;
                64'd2:  md5_constant = 64'h00000000242070db;
                64'd3:  md5_constant = 64'h00000000c1bdceee;
                64'd4:  md5_constant = 64'h00000000f57c0faf;
                64'd5:  md5_constant = 64'h000000004787c62a;
                64'd6:  md5_constant = 64'h00000000a8304613;
                64'd7:  md5_constant = 64'h00000000fd469501;
                64'd8:  md5_constant = 64'h00000000698098d8;
                64'd9:  md5_constant = 64'h000000008b44f7af;
                64'd10: md5_constant = 64'h00000000ffff5bb1;
                64'd11: md5_constant = 64'h00000000895cd7be;
                64'd12: md5_constant = 64'h000000006b901122;
                64'd13: md5_constant = 64'h00000000fd987193;
                64'd14: md5_constant = 64'h00000000a679438e;
                64'd15: md5_constant = 64'h0000000049b40821;
                64'd16: md5_constant = 64'h00000000f61e2562;
                64'd17: md5_constant = 64'h00000000c040b340;
                64'd18: md5_constant = 64'h00000000265e5a51;
                64'd19: md5_constant = 64'h00000000e9b6c7aa;
                64'd20: md5_constant = 64'h00000000d62f105d;
                64'd21: md5_constant = 64'h0000000002441453;
                64'd22: md5_constant = 64'h00000000d8a1e681;
                64'd23: md5_constant = 64'h00000000e7d3fbc8;
                64'd24: md5_constant = 64'h0000000021e1cde6;
                64'd25: md5_constant = 64'h00000000c33707d6;
                64'd26: md5_constant = 64'h00000000f4d50d87;
                64'd27: md5_constant = 64'h00000000455a14ed;
                64'd28: md5_constant = 64'h00000000a9e3e905;
                64'd29: md5_constant = 64'h00000000fcefa3f8;
                64'd30: md5_constant = 64'h00000000676f02d9;
                64'd31: md5_constant = 64'h000000008d2a4c8a;
                64'd32: md5_constant = 64'h00000000fffa3942;
                64'd33: md5_constant = 64'h000000008771f681;
                64'd34: md5_constant = 64'h000000006d9d6122;
                64'd35: md5_constant = 64'h00000000fde5380c;
                64'd36: md5_constant = 64'h00000000a4beea44;
                64'd37: md5_constant = 64'h000000004bdecfa9;
                64'd38: md5_constant = 64'h00000000f6bb4b60;
                64'd39: md5_constant = 64'h00000000bebfbc70;
                64'd40: md5_constant = 64'h00000000289b7ec6;
                64'd41: md5_constant = 64'h00000000eaa127fa;
                64'd42: md5_constant = 64'h00000000d4ef3085;
                64'd43: md5_constant = 64'h0000000004881d05;
                64'd44: md5_constant = 64'h00000000d9d4d039;
                64'd45: md5_constant = 64'h00000000e6db99e5;
                64'd46: md5_constant = 64'h000000001fa27cf8;
                64'd47: md5_constant = 64'h00000000c4ac5665;
                64'd48: md5_constant = 64'h00000000f4292244;
                64'd49: md5_constant = 64'h00000000432aff97;
                64'd50: md5_constant = 64'h00000000ab9423a7;
                64'd51: md5_constant = 64'h00000000fc93a039;
                64'd52: md5_constant = 64'h00000000655b59c3;
                64'd53: md5_constant = 64'h000000008f0ccc92;
                64'd54: md5_constant = 64'h00000000ffeff47d;
                64'd55: md5_constant = 64'h0000000085845dd1;
                64'd56: md5_constant = 64'h000000006fa87e4f;
                64'd57: md5_constant = 64'h00000000fe2ce6e0;
                64'd58: md5_constant = 64'h00000000a3014314;
                64'd59: md5_constant = 64'h000000004e0811a1;
                64'd60: md5_constant = 64'h00000000f7537e82;
                64'd61: md5_constant = 64'h00000000bd3af235;
                64'd62: md5_constant = 64'h000000002ad7d2bb;
                64'd63: md5_constant = 64'h00000000eb86d391;
                default: md5_constant = 64'd0;
            endcase
        end
    endfunction

    // The token owns the F, G, H, or I execution path, respectively.
    wire f_issue = (state == BUSY) && phase_token[0];
    wire g_issue = (state == BUSY) && phase_token[1];
    wire h_issue = (state == BUSY) && phase_token[2];
    wire i_issue = (state == BUSY) && phase_token[3];

    wire [63:0] f_value = (b & c) | ((~b) & d);
    wire [63:0] g_value = (d & b) | ((~d) & c);
    wire [63:0] h_value = b ^ c ^ d;
    wire [63:0] i_value = c ^ (b | (~d));
    wire [63:0] nonlinear =
        ((f_issue ? f_value : 64'd0) |
         (g_issue ? g_value : 64'd0) |
         (h_issue ? h_value : 64'd0) |
         (i_issue ? i_value : 64'd0)) & WORD_MASK;

    wire [63:0] g_index = message_index(step);
    wire [63:0] packed_word =
        block_store[(active_bank << 64'd3) + (g_index >> 64'd1)];
    wire [63:0] message_word =
        (packed_word >> ((g_index & 64'd1) << 64'd5)) & WORD_MASK;
    wire [63:0] shift_amount = rotation_amount(step);
    wire [63:0] sum_word =
        (a + nonlinear + md5_constant(step) + message_word) & WORD_MASK;
    wire [63:0] rotated_word =
        ((sum_word << shift_amount) |
         (sum_word >> (64'd32 - shift_amount))) & WORD_MASK;
    wire [63:0] next_b = (b + rotated_word) & WORD_MASK;

    always @(posedge clk) begin
        if (load_fire) begin
            state <= BUSY;
            active_bank <= write_bank;
            if (write_bank == BANK_COUNT - 64'd1)
                write_bank <= 64'd0;
            else
                write_bank <= write_bank + 64'd1;
            a <= IV_A;
            b <= IV_B;
            c <= IV_C;
            d <= IV_D;
            step <= 64'd0;
            phase_token <= 64'd1;
            // Q: an accepted block opens the checking window.
            window_open <= 1'b1;
        end else if (round_fire) begin
            a <= d;
            b <= next_b;
            c <= b;
            d <= c;
            if (step == 64'd63) begin
                state <= DONE;
                phase_token <= 64'd0;
                // Completion closes the window; it need never occur.
                window_open <= 1'b0;
            end else begin
                step <= step + 64'd1;
                if ((step & 64'd15) == 64'd15)
                    phase_token <= ((phase_token << 64'd1) & 64'd15) |
                                   ((phase_token >> 64'd3) & 64'd1);
            end
        end
    end

    // Absence: F and H must never own execution simultaneously in scope.
    assert property (!window_open || !(f_issue && h_issue));
endmodule

module price_mask_shift_pipeline #(
    parameter integer WORD_W = 64,
    parameter integer GROUP_BITS = 2,
    parameter integer STAGES = (WORD_W + GROUP_BITS - 1) / GROUP_BITS
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_ce,
    input  wire                  i_request,
    input  wire                  i_close,
    input  wire [WORD_W-1:0]     i_price_mask,
    input  wire [WORD_W-1:0]     i_distance,
    output wire                  o_ready,
    output wire                  o_valid,
    output wire [WORD_W-1:0]     o_shifted_mask
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] LOW_MASK = {WORD_W{1'b1}} >> (WORD_W-GROUP_BITS);
    localparam [WORD_W-1:0] DEADLINE = STAGES;
    localparam [STAGES-1:0] VALID_ZERO = {STAGES{1'b0}};
    localparam [STAGES-1:0] VALID_ONE = {{(STAGES-1){1'b0}}, 1'b1};

    // Default configuration: 32 pipeline entries, each holding 64-bit words.
    reg [WORD_W-1:0] partial_mask [0:STAGES-1];
    reg [WORD_W-1:0] remaining [0:STAGES-1];
    reg [STAGES-1:0] valid_pipe;
    reg [WORD_W-1:0] countdown;
    reg outstanding;
    reg before_close;

    wire accept = i_request && !outstanding;
    assign o_ready = !outstanding;
    assign o_valid = valid_pipe[STAGES-1];
    assign o_shifted_mask = partial_mask[STAGES-1];

    initial begin
        valid_pipe = VALID_ZERO;
        countdown = ZERO;
        outstanding = 1'b0;
        before_close = 1'b1;
    end

    // The response budget counts enabled pipeline advances, including retirement.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_pipe <= VALID_ZERO;
            countdown <= ZERO;
            outstanding <= 1'b0;
            before_close <= 1'b1;
        end else if (i_ce) begin
            valid_pipe <= (valid_pipe << 1) | (accept ? VALID_ONE : VALID_ZERO);
            // Closing is an enabled event; this scope latch never rearms itself.
            if (i_close)
                before_close <= 1'b0;

            if (!outstanding) begin
                if (accept) begin
                    outstanding <= 1'b1;
                    countdown <= DEADLINE;
                end else begin
                    countdown <= ZERO;
                end
            end else if (valid_pipe[STAGES-1]) begin
                outstanding <= 1'b0;
                countdown <= ZERO;
            end else if (countdown != ZERO) begin
                countdown <= countdown - ONE;
            end
        end
    end

    wire [WORD_W-1:0] budget_prefix [0:STAGES];
    wire [STAGES-1:0] remaining_bound;
    wire [WORD_W-1:0] token_budget;
    wire remaining_bounds_ok;
    assign budget_prefix[0] = ZERO;
    assign token_budget = budget_prefix[STAGES];
    assign remaining_bounds_ok = &remaining_bound;

    genvar g;
    generate
        for (g = 0; g < STAGES; g = g + 1) begin : shift_stage
            localparam integer CONSUMED =
                ((g+1)*GROUP_BITS < WORD_W) ? (g+1)*GROUP_BITS : WORD_W;
            localparam [WORD_W-1:0] STAGE_BUDGET = STAGES-g;

            assign budget_prefix[g+1] = budget_prefix[g]
                + (valid_pipe[g] ? STAGE_BUDGET : ZERO);
            assign remaining_bound[g] =
                ((remaining[g] >> (WORD_W-CONSUMED)) == ZERO);

            initial begin
                partial_mask[g] = ZERO;
                remaining[g] = ZERO;
            end

            if (g == 0) begin : first_stage
                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        partial_mask[g] <= ZERO;
                        remaining[g] <= ZERO;
                    end else if (i_ce) begin
                        partial_mask[g] <= i_price_mask >> (i_distance & LOW_MASK);
                        remaining[g] <= i_distance >> GROUP_BITS;
                    end
                end
            end else begin : later_stage
                // Consume the next amount group at its original bit significance.
                // Amount bits above bit 5 naturally implement overshift-to-zero.
                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        partial_mask[g] <= ZERO;
                        remaining[g] <= ZERO;
                    end else if (i_ce) begin
                        partial_mask[g] <= partial_mask[g-1]
                            >> ((remaining[g-1] & LOW_MASK) << (GROUP_BITS*g));
                        remaining[g] <= remaining[g-1] >> GROUP_BITS;
                    end
                end
            end
        end
    endgenerate

    // Before the first enabled close event, an outstanding request cannot expire.
    assert property (!before_close || !outstanding || (countdown != ZERO));
endmodule

module serial_product_stream #(
    parameter DATA_BITS = 64
) (
    input  wire                 clk,
    input  wire                 rst,
    input  wire                 ce,
    input  wire                 load_frame,
    input  wire                 close_frame,
    input  wire [DATA_BITS-1:0]  parallel_operand,
    input  wire                 multiplier_bit,
    output reg                  serial_one
);
    localparam [63:0] INPUT_STEPS   = DATA_BITS;
    localparam [63:0] PRODUCT_STEPS = INPUT_STEPS + INPUT_STEPS;

    reg [DATA_BITS-1:0] multiplicand;
    reg [DATA_BITS-1:0] sum_q;
    reg [DATA_BITS-1:0] carry_q;
    reg [63:0] bit_count;
    reg window;
    reg past_valid;

    wire zero_product = (multiplicand == {DATA_BITS{1'b0}});
    wire incoming_bit = (bit_count < INPUT_STEPS) && multiplier_bit;
    wire [DATA_BITS-1:0] partial_product =
        multiplicand & {DATA_BITS{incoming_bit}};
    wire [DATA_BITS-1:0] cell_sum;
    wire [DATA_BITS-1:0] cell_carry;

    // Each lane is a carry-save full-adder cell. Its sum moves
    // toward the serial output; its carry remains in the lane
    // because emitting one bit divides the residual by two.
    genvar lane;
    generate
        for (lane = 0; lane < DATA_BITS; lane = lane + 1) begin : cells
            assign cell_sum[lane] = sum_q[lane] ^ carry_q[lane]
                                    ^ partial_product[lane];
            assign cell_carry[lane] =
                (sum_q[lane] & carry_q[lane]) |
                (sum_q[lane] & partial_product[lane]) |
                (carry_q[lane] & partial_product[lane]);
        end
    endgenerate

    initial begin
        multiplicand = {DATA_BITS{1'b0}};
        sum_q         = {DATA_BITS{1'b0}};
        carry_q       = {DATA_BITS{1'b0}};
        bit_count     = 64'd0;
        serial_one    = 1'b0;
        window        = 1'b0;
        past_valid    = 1'b0;
    end

    // ce freezes every register, including the synchronous reset.
    always @(posedge clk) begin
        if (ce) begin
            if (rst) begin
                multiplicand <= {DATA_BITS{1'b0}};
                sum_q         <= {DATA_BITS{1'b0}};
                carry_q       <= {DATA_BITS{1'b0}};
                bit_count     <= 64'd0;
                serial_one    <= 1'b0;
                window        <= 1'b0;
                past_valid    <= 1'b0;
            end else begin
                past_valid <= 1'b1;
                if (load_frame) begin
                    multiplicand <= parallel_operand;
                    sum_q         <= {DATA_BITS{1'b0}};
                    carry_q       <= {DATA_BITS{1'b0}};
                    bit_count     <= 64'd0;
                    serial_one    <= 1'b0;
                    window        <= 1'b1;
                end else if (close_frame) begin
                    window <= 1'b0;
                end else if (window && (bit_count < PRODUCT_STEPS)) begin
                    serial_one <= cell_sum[0];
                    sum_q      <= {1'b0, cell_sum[DATA_BITS-1:1]};
                    carry_q    <= cell_carry;
                    bit_count  <= bit_count + 64'd1;
                end
            end
        end
    end

    // The frame window persists after multiplication finishes until
    // an explicit close marker arrives; that marker need never arrive.
    always @(posedge clk) begin
        if (past_valid && window && $rose(serial_one))
            assert (!(zero_product && serial_one));
    end
endmodule

module trace_word_assembler #(
    parameter integer WORD_BITS = 64
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 i_valid,
    output wire                 i_ready,
    input  wire [WORD_BITS-1:0] i_word,
    output wire [WORD_BITS-1:0] assembled_word,
    output reg                  word_ready
);
    localparam [63:0] WORD_CYCLES = WORD_BITS;

    // The extra bit carries the sentinel, not payload data.
    reg [WORD_BITS:0] assembler;
    reg [WORD_BITS-1:0] serial_source;
    reg [63:0] cycles_left;
    reg outstanding;
    reg armed;

    initial begin
        assembler    = {{WORD_BITS{1'b0}}, 1'b1};
        serial_source = {WORD_BITS{1'b0}};
        cycles_left  = WORD_CYCLES;
        outstanding  = 1'b0;
        word_ready   = 1'b0;
        armed        = 1'b0;
    end

    // Back-pressure prevents accepting another word during assembly.
    assign i_ready = i_ce && !outstanding;
    assign assembled_word = assembler[WORD_BITS-1:0];

    // Completion is bounded by WORD_CYCLES enabled clock cycles.
    // The completed snapshot remains ready until another request is accepted.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_valid && i_ready) begin
                serial_source <= i_word;
                assembler     <= {{WORD_BITS{1'b0}}, 1'b1};
                cycles_left   <= WORD_CYCLES;
                outstanding   <= 1'b1;
                word_ready    <= 1'b0;
                armed         <= 1'b1;
            end else if (outstanding) begin
                assembler <= {assembler[WORD_BITS-1:0],
                              serial_source[WORD_BITS-1]};
                serial_source <= {serial_source[WORD_BITS-2:0], 1'b0};
                cycles_left <= cycles_left - 64'd1;

                if (assembler[WORD_BITS-1]) begin
                    outstanding <= 1'b0;
                    word_ready  <= 1'b1;
                end
            end
        end
    end

    // After the first accepted request, its deadline must not expire
    // while assembly remains outstanding.
    always @(posedge clk)
        if (armed && outstanding)
            assert (cycles_left != 64'd0);
endmodule

module regional_congestion_monitor #(
    parameter integer DATA_W = 32'd32,
    parameter integer PORTS  = 32'd64
) (
    input  wire                  clk,
    input  wire                  i_sample_valid,
    output wire                  o_sample_ready,
    input  wire [DATA_W-1:0]     i_port,
    input  wire [DATA_W-1:0]     i_local_occupancy,
    input  wire [DATA_W-1:0]     i_neighbor_congestion,
    input  wire                  i_window_begin,
    input  wire                  i_window_end,
    output wire                  o_report_valid,
    input  wire                  i_report_ready,
    output wire [DATA_W-1:0]     o_report_port,
    output wire [DATA_W-1:0]     o_report_metric
);
    // Per-direction filtered congestion, committed when a report transfers.
    reg [DATA_W-1:0] filtered [0:PORTS-1];

    // One-entry report queue. The widened count accommodates four words.
    reg                  pending_valid;
    reg [DATA_W-1:0]     pending_port;
    reg [DATA_W+1:0]     pending_count;

    // Record the last delivered metric and its earlier accepted count.
    reg [DATA_W-1:0]     last_delivered_metric;
    reg [DATA_W+1:0]     delivered_basis;
    reg                  scope_window;
    reg                  past_valid;

    integer init_port;
    initial begin
        for (init_port = 32'd0; init_port < PORTS;
             init_port = init_port + 32'd1)
            filtered[init_port] = {DATA_W{1'b0}};
        pending_valid         = 1'b0;
        pending_port          = {DATA_W{1'b0}};
        pending_count         = {{DATA_W{1'b0}}, 2'b11};
        last_delivered_metric = {DATA_W{1'b0}};
        delivered_basis       = {{DATA_W{1'b0}}, 2'b11};
        scope_window          = 1'b0;
        past_valid            = 1'b0;
    end

    wire port_in_range = (i_port < PORTS);
    wire [DATA_W-1:0] previous_filter =
        port_in_range ? filtered[i_port] : {DATA_W{1'b0}};

    // Rounded EWMA: ceil((2*previous + local + neighbor)/4).
    wire [DATA_W+1:0] accepted_count =
        {1'b0, previous_filter, 1'b0}
        + {2'b00, i_local_occupancy}
        + {2'b00, i_neighbor_congestion}
        + {{DATA_W{1'b0}}, 2'b11};

    assign o_sample_ready = !pending_valid && port_in_range;
    assign o_report_valid = pending_valid;
    assign o_report_port = pending_port;
    assign o_report_metric = pending_count[DATA_W+1:2];

    wire sample_fire = i_sample_valid && o_sample_ready;
    wire report_fire = o_report_valid && i_report_ready;

    // With i_sample_valid and i_report_ready both low, all state holds.
    // A blocked report retains both valid and data until its handshake.
    always @(posedge clk) begin
        if (sample_fire || report_fire)
            past_valid <= 1'b1;

        if (sample_fire) begin
            pending_valid <= 1'b1;
            pending_port  <= i_port;
            pending_count <= accepted_count;

            // Accepted begin/end markers open and close a reusable window.
            if (i_window_end)
                scope_window <= 1'b0;
            else if (i_window_begin)
                scope_window <= 1'b1;
        end

        if (report_fire) begin
            pending_valid <= 1'b0;
            filtered[pending_port] <= pending_count[DATA_W+1:2];
            last_delivered_metric <= pending_count[DATA_W+1:2];
            delivered_basis <= pending_count;
        end
    end

    // Inside the window, a metric change requires a different earlier
    // accepted congestion count, retained in the delivery shadow.
    always @(posedge clk)
        if (past_valid && scope_window && $stable(delivered_basis))
            assert ($stable(last_delivered_metric));
endmodule

module flash_clear_delay_table #(
    parameter integer DEPTH = 8,
    parameter integer WORD_W = 64,
    parameter [WORD_W-1:0] MAX_DELAY = 64'd8,
    parameter integer ADDR_W = (DEPTH > 1) ? $clog2(DEPTH) : 1
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  scope_open,
    input  wire                  scope_close,
    input  wire                  flash_clear,
    input  wire                  wr_valid,
    input  wire [ADDR_W-1:0]     wr_addr,
    input  wire [WORD_W-1:0]     wr_delay,
    output wire                  wr_ready,
    input  wire                  req_valid,
    input  wire [ADDR_W-1:0]     req_addr,
    output wire                  req_ready,
    output wire [WORD_W-1:0]     read_delay,
    output reg                   pending,
    output reg                   done
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] CAPACITY = DEPTH;
    localparam [ADDR_W:0] ADDRESS_LIMIT = DEPTH;

    reg [WORD_W-1:0] delay_ram [0:DEPTH-1];
    reg [DEPTH-1:0] valid;
    reg [WORD_W-1:0] used;
    reg [WORD_W-1:0] work_remaining;
    reg [WORD_W-1:0] countdown;
    reg window;

    wire wr_address_ok;
    wire req_address_ok;
    assign wr_address_ok = ({1'b0, wr_addr} < ADDRESS_LIMIT);
    assign req_address_ok = ({1'b0, req_addr} < ADDRESS_LIMIT);

    // Invalid entries return the one-tick default, including after flash clear.
    assign read_delay = (req_address_ok && valid[req_addr])
                      ? delay_ram[req_addr] : ONE;

    // Filled entries cannot be overwritten. A full table backpressures writes.
    assign wr_ready = ce && !pending && !flash_clear
                   && wr_address_ok && !valid[wr_addr]
                   && (used < CAPACITY)
                   && (wr_delay >= ONE) && (wr_delay <= MAX_DELAY);
    assign req_ready = ce && !pending && !flash_clear
                    && !wr_valid && req_address_ok;

    initial begin
        valid = {DEPTH{1'b0}};
        used = ZERO;
        work_remaining = ZERO;
        countdown = ZERO;
        pending = 1'b0;
        done = 1'b0;
        window = 1'b0;
    end

    generate
        for (genvar entry = 0; entry < DEPTH; entry = entry + 1) begin : init_entries
            initial delay_ram[entry] = ZERO;
        end
    endgenerate

    // All timing is measured in enabled clock cycles. With ce low, every
    // register and every RAM entry holds its value.
    always @(posedge clk) begin
        if (ce) begin
            done <= 1'b0;

            // Latched after-open/until-close scope; closing is optional.
            if (scope_close)
                window <= 1'b0;
            else if (scope_open)
                window <= 1'b1;

            if (pending) begin
                if (work_remaining <= ONE) begin
                    pending <= 1'b0;
                    done <= 1'b1;
                    work_remaining <= ZERO;
                    countdown <= ZERO;
                end else begin
                    work_remaining <= work_remaining - ONE;
                    countdown <= countdown - ONE;
                end
            end else if (flash_clear) begin
                // The data array is retained; only validity is cleared.
                valid <= {DEPTH{1'b0}};
                used <= ZERO;
            end else if (wr_valid && wr_ready) begin
                delay_ram[wr_addr] <= wr_delay;
                valid[wr_addr] <= 1'b1;
                used <= used + ONE;
            end else if (req_valid && req_ready) begin
                // Snapshot the programmed duration, freeing the table from
                // any dependency on the in-flight request's later execution.
                pending <= 1'b1;
                work_remaining <= read_delay;
                countdown <= MAX_DELAY;
            end
        end
    end

    // During the latched scope, an outstanding request must not exhaust
    // its completion budget before it finishes.
    assert property (!window || !pending || (countdown != ZERO));
endmodule

module interleaved_pwm_boundary_sweep #(
    parameter integer CHANNELS = 32'd4,
    parameter [31:0] PERIOD = 32'd8
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_valid,
    output wire i_ready,
    input  wire [CHANNELS*32-1:0] i_phase,
    input  wire [CHANNELS*32-1:0] i_duty,
    output wire [CHANNELS-1:0] o_pwm,
    output wire [CHANNELS-1:0] o_pending,
    output wire o_busy,
    output wire o_done
);
    typedef enum logic [1:0] {
        IDLE  = 2'd0,
        SWEEP = 2'd1
    } state_t;

    state_t state;
    reg armed;
    reg [31:0] master;
    reg [31:0] remaining;
    reg [CHANNELS-1:0] pending;
    reg [31:0] phase_offset [0:CHANNELS-1];
    reg [31:0] duty [0:CHANNELS-1];

    wire fire;
    wire [CHANNELS-1:0] pending_after_tick;
    wire [CHANNELS-1:0] configuration_legal;
    wire [CHANNELS-1:0] pending_in_window;
    wire [31:0] local_phase [0:CHANNELS-1];
    wire [31:0] distance_to_phase [0:CHANNELS-1];

    // The input is a stream of timing tokens. In IDLE, a token also
    // carries a new configuration and launches a boundary sweep.
    // In SWEEP, each accepted token advances one enabled PWM cycle.
    // Deasserting i_ce applies back-pressure and freezes every register.
    assign i_ready = i_ce;
    assign fire = i_valid && i_ready;
    assign o_pending = pending;
    assign o_busy = (state == SWEEP);
    assign o_done = armed && (state == IDLE);

    initial begin
        state = IDLE;
        armed = 1'b0;
        master = 32'd0;
        remaining = 32'd0;
        pending = {CHANNELS{1'b0}};
    end

    genvar ch;
    generate
        for (ch = 32'd0; ch < CHANNELS; ch = ch + 32'd1) begin : channel
            initial begin
                phase_offset[ch] = 32'd0;
                duty[ch] = 32'd0;
            end

            always @(posedge clk) begin
                if (fire && (state == IDLE)) begin
                    phase_offset[ch] <= i_phase[ch*32 +: 32] % PERIOD;
                    if (i_duty[ch*32 +: 32] > PERIOD)
                        duty[ch] <= PERIOD;
                    else
                        duty[ch] <= i_duty[ch*32 +: 32];
                end
            end

            // All channels use the same master period, with independent
            // programmable phase origins and pulse widths.
            assign local_phase[ch] =
                (master >= phase_offset[ch])
                ? master - phase_offset[ch]
                : PERIOD - (phase_offset[ch] - master);
            assign o_pwm[ch] = (local_phase[ch] < duty[ch]);

            // A configuration is acknowledged for this channel when its
            // phase origin is serviced by an accepted timing token.
            assign pending_after_tick[ch] =
                pending[ch] && (master != phase_offset[ch]);

            assign distance_to_phase[ch] =
                (phase_offset[ch] >= master)
                ? phase_offset[ch] - master
                : PERIOD - (master - phase_offset[ch]);
            assign configuration_legal[ch] =
                (phase_offset[ch] < PERIOD) && (duty[ch] <= PERIOD);
            assign pending_in_window[ch] =
                !pending[ch] || (remaining > distance_to_phase[ch]);
        end
    endgenerate

    always @(posedge clk) begin
        if (fire) begin
            case (state)
                IDLE: begin
                    // Q: accept the first configuration. Arming is sticky.
                    armed <= 1'b1;
                    pending <= {CHANNELS{1'b1}};
                    remaining <= PERIOD;
                    state <= SWEEP;
                end
                SWEEP: begin
                    if (master == PERIOD - 32'd1)
                        master <= 32'd0;
                    else
                        master <= master + 32'd1;

                    if (remaining != 32'd0)
                        remaining <= remaining - 32'd1;

                    pending <= pending_after_tick;
                    if (pending_after_tick == {CHANNELS{1'b0}})
                        state <= IDLE;
                end
                default: begin
                    // Unused controller encodings hold their state.
                end
            endcase
        end
    end

    // Each launched sweep must service these channel requests before
    // its PERIOD-cycle enabled-time deadline expires.
    always @(posedge clk) begin
        if (armed && (state == SWEEP) && pending[0])
            assert (remaining != 32'd0);
    end

    always @(posedge clk) begin
        if (armed && (state == SWEEP) && pending[CHANNELS-1])
            assert (remaining != 32'd0);
    end
endmodule

module phy_event_read_clear #(
    parameter integer DATA_W = 128,
    parameter integer ENTRIES = 8,
    localparam integer INDEX_W = (ENTRIES > 1) ? $clog2(ENTRIES) : 1,
    localparam integer COUNT_W = $clog2(ENTRIES + 1)
) (
    input  wire                   clk,
    input  wire                   i_ce,
    input  wire                   begin_window,
    input  wire                   end_window,
    input  wire                   config_load,
    input  wire [DATA_W-1:0]      config_value,
    input  wire                   capture_event,
    input  wire [INDEX_W-1:0]     bank_index,
    input  wire [DATA_W-1:0]      event_bits,
    input  wire                   read_clear,
    output reg  [DATA_W-1:0]      read_data,
    output reg  [COUNT_W-1:0]     pending_count,
    output reg  [COUNT_W-1:0]     free_count,
    output reg                    window_active
);
    localparam [INDEX_W:0] ENTRY_LIMIT = (INDEX_W+1)'(ENTRIES);

    reg [DATA_W-1:0] event_mask;
    reg [DATA_W-1:0] event_bank [0:ENTRIES-1];
    reg [ENTRIES-1:0] dirty;

    wire [DATA_W-1:0] masked_events = event_bits & event_mask;
    wire bank_valid = {1'b0, bank_index} < ENTRY_LIMIT;
    wire do_read = read_clear && bank_valid;
    wire do_event = !read_clear && bank_valid && capture_event
                    && (|masked_events);

    wire [COUNT_W-1:0] dirty_sum [0:ENTRIES];
    wire [COUNT_W-1:0] dirty_total = dirty_sum[ENTRIES];
    assign dirty_sum[0] = {COUNT_W{1'b0}};

    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : dirty_population
            assign dirty_sum[g+1] = dirty_sum[g]
                + {{(COUNT_W-1){1'b0}}, dirty[g]};
        end
    endgenerate

    integer n;
    initial begin
        event_mask = {DATA_W{1'b1}};
        dirty = {ENTRIES{1'b0}};
        pending_count = {COUNT_W{1'b0}};
        free_count = COUNT_W'(ENTRIES);
        read_data = {DATA_W{1'b0}};
        window_active = 1'b0;
        for (n = 0; n < ENTRIES; n = n + 1)
            event_bank[n] = {DATA_W{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (end_window)
                window_active <= 1'b0;
            else if (begin_window)
                window_active <= 1'b1;

            if (config_load)
                event_mask <= config_value;

            // A bus read returns the selected accumulator and clears it.
            // Reads take priority over event accumulation on this port.
            if (do_read) begin
                read_data <= event_bank[bank_index];
                event_bank[bank_index] <= {DATA_W{1'b0}};
                dirty[bank_index] <= 1'b0;
                if (dirty[bank_index]) begin
                    pending_count <= pending_count - COUNT_W'(1);
                    free_count <= free_count + COUNT_W'(1);
                end
            end else if (do_event) begin
                event_bank[bank_index] <= event_bank[bank_index] | masked_events;
                dirty[bank_index] <= 1'b1;
                if (!dirty[bank_index]) begin
                    pending_count <= pending_count + COUNT_W'(1);
                    free_count <= free_count - COUNT_W'(1);
                end
            end
        end
    end

    always @(posedge clk)
        if (window_active)
            assert (pending_count <= COUNT_W'(ENTRIES));

    always @(posedge clk)
        if (window_active)
            assert (free_count <= COUNT_W'(ENTRIES));
endmodule

module sprite_scale_multiplier #(
    parameter integer WORD_W = 32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_valid,
    output wire                  o_ready,
    input  wire [WORD_W-1:0]     i_fraction_a,
    input  wire [WORD_W-1:0]     i_fraction_b,
    input  wire [WORD_W-1:0]     i_exponent_a,
    input  wire [WORD_W-1:0]     i_exponent_b,
    output reg                   result_done,
    output reg  [WORD_W-1:0]     result_mantissa,
    output reg  [WORD_W-1:0]     result_exponent
);
    // Positive floating-point scale factors. The input fraction fields use
    // their low MANT_BITS-1 bits and have an implicit leading one.
    // Mantissas, products, exponents and deadline counters occupy WORD_W bits.
    // The exponent arithmetic is modulo 2**WORD_W.
    localparam integer MANT_BITS = WORD_W / 2;
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] TWO = ONE + ONE;
    localparam [WORD_W-1:0] THREE = TWO + ONE;
    localparam [WORD_W-1:0] FOUR = TWO + TWO;
    localparam [WORD_W-1:0] MANT_MASK = (ONE << MANT_BITS) - ONE;

    // One transaction at a time, progressing through four registered stages.
    reg mul_valid, norm_valid, round_valid, pack_valid;
    reg window;
    reg [WORD_W-1:0] finish_left, normalize_left;
    reg [WORD_W-1:0] mant_a, mant_b, exp_a, exp_b;
    reg [WORD_W-1:0] product, exponent_sum;
    reg [WORD_W-1:0] norm_mant, norm_exponent;
    reg round_guard, round_sticky;
    reg [WORD_W-1:0] rounded_mant, rounded_exponent;

    wire occupied = mul_valid || norm_valid || round_valid || pack_valid;
    assign o_ready = i_ce && !occupied;
    wire accept = i_valid && o_ready;

    wire round_up = round_guard && (round_sticky || norm_mant[0]);
    wire [WORD_W-1:0] rounded_value =
        norm_mant + {{(WORD_W-1){1'b0}}, round_up};

    initial begin
        mul_valid = 1'b0;
        norm_valid = 1'b0;
        round_valid = 1'b0;
        pack_valid = 1'b0;
        window = 1'b0;
        finish_left = ZERO;
        normalize_left = ZERO;
        mant_a = ZERO;
        mant_b = ZERO;
        exp_a = ZERO;
        exp_b = ZERO;
        product = ZERO;
        exponent_sum = ZERO;
        norm_mant = ZERO;
        norm_exponent = ZERO;
        round_guard = 1'b0;
        round_sticky = 1'b0;
        rounded_mant = ZERO;
        rounded_exponent = ZERO;
        result_done = 1'b0;
        result_mantissa = ZERO;
        result_exponent = ZERO;
    end

    // Deadlines count enabled processing cycles. With i_ce low, every state
    // register holds and input ready is low. The request port is the
    // valid/ready channel; result_done is sticky completion status.
    always @(posedge clk) begin
        if (i_ce) begin
            mul_valid <= accept;
            norm_valid <= mul_valid;
            round_valid <= norm_valid;
            pack_valid <= round_valid;

            if (accept) begin
                mant_a <= {{(WORD_W-MANT_BITS){1'b0}},
                           1'b1, i_fraction_a[MANT_BITS-2:0]};
                mant_b <= {{(WORD_W-MANT_BITS){1'b0}},
                           1'b1, i_fraction_b[MANT_BITS-2:0]};
                exp_a <= i_exponent_a;
                exp_b <= i_exponent_b;
                finish_left <= FOUR;
                normalize_left <= TWO;
                window <= 1'b1;       // Q: accepted request opens the scope.
                result_done <= 1'b0;
            end else begin
                if (mul_valid || norm_valid || round_valid)
                    finish_left <= finish_left - ONE;
                else if (pack_valid)
                    finish_left <= ZERO;

                if (mul_valid || norm_valid)
                    normalize_left <= normalize_left - ONE;
            end

            if (mul_valid) begin
                product <= mant_a * mant_b;
                exponent_sum <= exp_a + exp_b;
            end

            if (norm_valid) begin
                if (product[2*MANT_BITS-1]) begin
                    norm_mant <= product >> MANT_BITS;
                    norm_exponent <= exponent_sum + ONE;
                    round_guard <= product[MANT_BITS-1];
                    round_sticky <= |product[MANT_BITS-2:0];
                end else begin
                    norm_mant <= product >> (MANT_BITS-1);
                    norm_exponent <= exponent_sum;
                    round_guard <= product[MANT_BITS-2];
                    round_sticky <= |product[MANT_BITS-3:0];
                end
            end

            if (round_valid) begin
                // Round to nearest, ties to even, including carry renormalization.
                if (rounded_value[MANT_BITS]) begin
                    rounded_mant <= ONE << (MANT_BITS-1);
                    rounded_exponent <= norm_exponent + ONE;
                end else begin
                    rounded_mant <= rounded_value;
                    rounded_exponent <= norm_exponent;
                end
            end

            if (pack_valid) begin
                result_mantissa <= rounded_mant;
                result_exponent <= rounded_exponent;
                result_done <= 1'b1;
                window <= 1'b0;       // R: completed result closes the scope.
            end
        end
    end

    // Full-result bounded response inside the accepted-request window.
    always @(posedge clk)
        if (window)
            assert (finish_left != ZERO);

    // Earlier normalization-milestone bounded response for the same request.
    always @(posedge clk)
        if (window && (mul_valid || norm_valid))
            assert (normalize_left != ZERO);
endmodule

module dithered_pwm_stream #(
    parameter integer WORD_W = 64,
    parameter [WORD_W-1:0] PERIOD_TICKS = 64'd8
) (
    input  wire                  clk,
    input  wire                  i_valid,
    output wire                  o_ready,
    input  wire [WORD_W-1:0]     i_duty_integer,
    input  wire [WORD_W-1:0]     i_duty_fraction,
    output wire                  o_valid,
    input  wire                  i_ready,
    output wire                  o_high,
    output wire                  o_low
);
    localparam [WORD_W-1:0] ZERO = 64'd0;
    localparam [WORD_W-1:0] ONE  = 64'd1;

    reg [WORD_W-1:0] phase;
    reg [WORD_W-1:0] remaining;
    reg [WORD_W-1:0] duty_integer;
    reg [WORD_W-1:0] duty_fraction;
    reg [WORD_W-1:0] fractional_error;
    reg dither_carry;
    reg sample_valid;
    reg sample_high;
    reg sample_low;
    reg armed;
    reg pv;

    initial begin
        phase            = ZERO;
        remaining        = PERIOD_TICKS;
        duty_integer     = PERIOD_TICKS / 64'd2;
        duty_fraction    = {1'b1, {(WORD_W-1){1'b0}}};
        fractional_error = ZERO;
        dither_carry     = 1'b0;
        sample_valid     = 1'b0;
        sample_high      = 1'b0;
        sample_low       = 1'b0;
        armed            = 1'b0;
        pv               = 1'b0;
    end

    wire [WORD_W:0] fractional_sum =
        {1'b0, fractional_error} + {1'b0, duty_fraction};
    wire [WORD_W-1:0] effective_duty =
        duty_integer + {{(WORD_W-1){1'b0}}, dither_carry};

    wire high_request = phase < effective_duty;
    wire low_request  = remaining <= PERIOD_TICKS - effective_duty;

    assign o_ready = !sample_valid || i_ready;
    wire fire = i_valid && o_ready;
    wire retire = sample_valid && i_ready;

    assign o_valid = sample_valid;
    assign o_high  = sample_high;
    assign o_low   = sample_low;

    // Each accepted input token advances one PWM clock and emits one sample.
    // The single output slot applies back-pressure without changing its data.
    always @(posedge clk) begin
        if (fire || retire)
            pv <= 1'b1;

        if (fire) begin
            armed        <= 1'b1;
            sample_valid <= 1'b1;
            sample_high  <= high_request;
            sample_low   <= low_request;

            if (phase == PERIOD_TICKS - ONE) begin
                phase            <= ZERO;
                remaining        <= PERIOD_TICKS;
                fractional_error <= fractional_sum[WORD_W-1:0];
                dither_carry     <= fractional_sum[WORD_W];

                // Boundary tokens load the next integer setting and the
                // fractional setting used by the following accumulator update.
                duty_integer <= (i_duty_integer < PERIOD_TICKS)
                              ? i_duty_integer : PERIOD_TICKS - ONE;
                duty_fraction <= i_duty_fraction;
            end else begin
                phase     <= phase + ONE;
                remaining <= remaining - ONE;
            end
        end else if (retire) begin
            sample_valid <= 1'b0;
        end
    end

    // After the first accepted tick, an emitted high-side grant must never
    // coincide with acceptance of a low-side request for that same sample.
    always @(posedge clk)
        if (pv && armed)
            assert (!(sample_high && $past(fire && low_request)));
endmodule

module microcoded_mul_array #(
    parameter integer DATA_W = 128,
    parameter integer PIPE_STAGES = 8
) (
    input  wire                       clk,
    input  wire                       in_valid,
    output wire                       in_ready,
    input  wire [DATA_W-1:0]          in_a,
    input  wire [DATA_W-1:0]          in_b,
    output wire                       out_valid,
    input  wire                       out_ready,
    output wire [(2*DATA_W)-1:0]      out_product
);
    localparam integer PRODUCT_W = 2 * DATA_W;
    localparam integer ROWS_PER_STAGE =
        (DATA_W + PIPE_STAGES - 1) / PIPE_STAGES;
    localparam integer COUNT_W = $clog2(PIPE_STAGES + 1);
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE =
        {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] CAPACITY = PIPE_STAGES;

    reg [DATA_W-1:0] operand_a [0:PIPE_STAGES-1];
    reg [DATA_W-1:0] operand_b [0:PIPE_STAGES-1];
    reg [PRODUCT_W-1:0] partial_acc [0:PIPE_STAGES-1];
    reg [PIPE_STAGES-1:0] stage_valid;
    reg [COUNT_W-1:0] occupancy;
    reg accepted;
    reg before_writeback;
    reg past_valid;

    wire [PRODUCT_W-1:0] stage_sum [0:PIPE_STAGES-1];
    wire [COUNT_W-1:0] live_prefix [0:PIPE_STAGES];
    wire [COUNT_W-1:0] live_count;

    assign out_valid = stage_valid[PIPE_STAGES-1];
    assign out_product = partial_acc[PIPE_STAGES-1];
    assign in_ready = !out_valid || out_ready;

    wire in_fire = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;
    // Freeze the entire array under output back-pressure. Also freeze it
    // when neither the input sender nor the output receiver requests work.
    wire advance = in_ready && (in_valid || out_ready);

    assign live_prefix[0] = COUNT_ZERO;
    assign live_count = live_prefix[PIPE_STAGES];

    genvar g, r;
    generate
        for (g = 0; g < PIPE_STAGES; g = g + 1) begin : array_stage
            wire [DATA_W-1:0] row_a;
            wire [DATA_W-1:0] row_b;
            wire [PRODUCT_W-1:0] row_sum [0:ROWS_PER_STAGE];

            if (g == 0) begin : first_stage
                assign row_a = in_a;
                assign row_b = in_b;
                assign row_sum[0] = {PRODUCT_W{1'b0}};
            end else begin : later_stage
                assign row_a = operand_a[g-1];
                assign row_b = operand_b[g-1];
                assign row_sum[0] = partial_acc[g-1];
            end

            // All partial products are combinational. Adjacent rows form
            // a regular addition array, with registers between groups.
            for (r = 0; r < ROWS_PER_STAGE; r = r + 1) begin : adder_row
                localparam integer BIT_INDEX = g * ROWS_PER_STAGE + r;
                wire [PRODUCT_W-1:0] partial_product;
                if (BIT_INDEX < DATA_W) begin : real_row
                    assign partial_product = row_b[BIT_INDEX]
                        ? ({{DATA_W{1'b0}}, row_a} << BIT_INDEX)
                        : {PRODUCT_W{1'b0}};
                end else begin : padding_row
                    assign partial_product = {PRODUCT_W{1'b0}};
                end
                assign row_sum[r+1] = row_sum[r] + partial_product;
            end

            assign stage_sum[g] = row_sum[ROWS_PER_STAGE];
            assign live_prefix[g+1] = live_prefix[g]
                + {{(COUNT_W-1){1'b0}}, stage_valid[g]};
        end
    endgenerate

    integer i;
    initial begin
        stage_valid = {PIPE_STAGES{1'b0}};
        occupancy = COUNT_ZERO;
        accepted = 1'b0;
        before_writeback = 1'b1;
        past_valid = 1'b0;
        for (i = 0; i < PIPE_STAGES; i = i + 1) begin
            operand_a[i] = {DATA_W{1'b0}};
            operand_b[i] = {DATA_W{1'b0}};
            partial_acc[i] = {PRODUCT_W{1'b0}};
        end
    end

    integer s;
    always @(posedge clk) begin
        if (advance) begin
            past_valid <= 1'b1;
            accepted <= in_fire;
            if (out_fire)
                before_writeback <= 1'b0;

            stage_valid[0] <= in_fire;
            operand_a[0] <= in_a;
            operand_b[0] <= in_b;
            for (s = 1; s < PIPE_STAGES; s = s + 1) begin
                stage_valid[s] <= stage_valid[s-1];
                operand_a[s] <= operand_a[s-1];
                operand_b[s] <= operand_b[s-1];
            end
            for (s = 0; s < PIPE_STAGES; s = s + 1)
                partial_acc[s] <= stage_sum[s];

            case ({in_fire, out_fire})
                2'b10: occupancy <= occupancy + COUNT_ONE;
                2'b01: occupancy <= occupancy - COUNT_ONE;
                default: occupancy <= occupancy;
            endcase
        end
    end

    // Before the first writeback, each rising admission indication must
    // observe at most one resident multiplication per array stage.
    always @(posedge clk)
        if (past_valid && before_writeback && $rose(accepted))
            assert (occupancy <= CAPACITY);
endmodule

module source_capture_window_fifo #(
    parameter integer DATA_W = 128,
    parameter integer DEPTH = 16
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_fwd_edge,
    input  wire                  i_local_edge,
    input  wire                  i_end_burst,
    input  wire [DATA_W-1:0]     i_source_word,
    output reg  [DATA_W-1:0]     o_local_word,
    output wire                 o_full,
    output wire                 o_empty
);
    // DEPTH is a power of two, at least two.
    localparam integer ADDR_W = $clog2(DEPTH);
    localparam integer SEQ_W = ADDR_W + 1;
    localparam integer COUNT_W = $clog2(DEPTH + 1);
    localparam [COUNT_W-1:0] DEPTH_COUNT = DEPTH;
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [SEQ_W-1:0] SEQ_ONE = {{(SEQ_W-1){1'b0}}, 1'b1};

    reg [DATA_W-1:0] capture_word;
    reg capture_valid;
    reg [DATA_W-1:0] slots [0:DEPTH-1];
    reg [SEQ_W-1:0] wr_seq, rd_seq;
    reg [COUNT_W-1:0] used;
    reg capture_window;
    integer init_index;

    wire count_full = (used == DEPTH_COUNT);
    wire count_empty = (used == COUNT_ZERO);
    wire pointer_empty = (wr_seq == rd_seq);
    wire pointer_full =
        (wr_seq[ADDR_W-1:0] == rd_seq[ADDR_W-1:0]) &&
        (wr_seq[SEQ_W-1] != rd_seq[SEQ_W-1]);

    wire push = i_fwd_edge && capture_valid && !count_full;
    wire pop = i_local_edge && !count_empty;

    assign o_full = count_full;
    assign o_empty = pointer_empty;

    initial begin
        capture_word = {DATA_W{1'b0}};
        capture_valid = 1'b0;
        o_local_word = {DATA_W{1'b0}};
        wr_seq = {SEQ_W{1'b0}};
        rd_seq = {SEQ_W{1'b0}};
        used = COUNT_ZERO;
        capture_window = 1'b0;
        for (init_index = 0; init_index < DEPTH; init_index = init_index + 1)
            slots[init_index] = {DATA_W{1'b0}};
    end

    // Common-clock specialization of the forwarded-clock/local-clock buffer:
    // the independent edge enables select its write and read port activity.
    // A forwarded edge captures a new word and transfers the previous capture
    // into a slot. There is no handshake; full-buffer transfers are dropped.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_end_burst)
                capture_window <= 1'b0;
            else if (i_fwd_edge)
                capture_window <= 1'b1;

            if (i_fwd_edge) begin
                capture_word <= i_source_word;
                capture_valid <= 1'b1;
            end

            if (push) begin
                slots[wr_seq[ADDR_W-1:0]] <= capture_word;
                wr_seq <= wr_seq + SEQ_ONE;
            end

            if (pop) begin
                o_local_word <= slots[rd_seq[ADDR_W-1:0]];
                rd_seq <= rd_seq + SEQ_ONE;
            end

            case ({push, pop})
                2'b10: used <= used + COUNT_ONE;
                2'b01: used <= used - COUNT_ONE;
                default: begin end
            endcase
        end
    end

    // During a capture burst, the occupancy and pointer views must never
    // simultaneously report opposite boundary conditions.
    always @(posedge clk) begin
        if (capture_window) begin
            assert (!(count_full && pointer_empty));
            assert (!(count_empty && pointer_full));
        end
    end
endmodule

module schroeder_phase_stage #(
    parameter [31:0] DEPTH = 32'd16,
    parameter signed [31:0] GAIN_NUM = 32'sd1,
    parameter [31:0] GAIN_SHIFT = 32'd1
) (
    input wire clk,
    input wire ce,
    input wire signed [31:0] sample_in,
    output reg signed [31:0] sample_out,
    output wire sample_valid
);
    typedef enum logic [1:0] {
        CAPTURE  = 2'b00,
        FEEDBACK = 2'b01,
        COMMIT   = 2'b10,
        REPORT   = 2'b11
    } state_t;

    state_t state;
    reg [31:0] delay_ptr;
    reg signed [31:0] delay_line [32'd0:DEPTH-32'd1];
    reg signed [31:0] sample_shadow;
    reg signed [31:0] tap_shadow;
    reg signed [31:0] feedback_word;

    // Dyadic gain g = GAIN_NUM / 2**GAIN_SHIFT, defaulting to 1/2.
    // Arithmetic and storage wrap at 32 bits; shifts round downward.
    wire signed [31:0] tap_product = tap_shadow * GAIN_NUM;
    wire signed [31:0] scaled_tap = tap_product >>> GAIN_SHIFT;
    wire signed [31:0] expected_feedback = sample_shadow + scaled_tap;

    wire signed [31:0] feedback_product = feedback_word * GAIN_NUM;
    wire signed [31:0] scaled_feedback = feedback_product >>> GAIN_SHIFT;

    wire signed [31:0] expected_product = expected_feedback * GAIN_NUM;
    wire signed [31:0] expected_scaled = expected_product >>> GAIN_SHIFT;
    wire signed [31:0] expected_output = tap_shadow - expected_scaled;

    assign sample_valid = (state == REPORT);

    initial begin
        state = CAPTURE;
        delay_ptr = 32'd0;
        sample_shadow = 32'sd0;
        tap_shadow = 32'sd0;
        feedback_word = 32'sd0;
        sample_out = 32'sd0;
    end

    genvar entry;
    generate
        for (entry = 32'd0; entry < DEPTH; entry = entry + 32'd1) begin : initialize_delay
            initial delay_line[entry] = 32'sd0;
        end
    endgenerate

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                CAPTURE: begin
                    // Record the input and the earlier circular-buffer value.
                    sample_shadow <= sample_in;
                    tap_shadow <= delay_line[delay_ptr];
                    state <= FEEDBACK;
                end
                FEEDBACK: begin
                    // Allpass feedback path: w = x + g*d.
                    feedback_word <= expected_feedback;
                    state <= COMMIT;
                end
                COMMIT: begin
                    // Allpass feedforward path: y = d - g*w.
                    delay_line[delay_ptr] <= feedback_word;
                    sample_out <= tap_shadow - scaled_feedback;
                    if (delay_ptr == DEPTH - 32'd1)
                        delay_ptr <= 32'd0;
                    else
                        delay_ptr <= delay_ptr + 32'd1;
                    state <= REPORT;
                end
                REPORT: begin
                    state <= CAPTURE;
                end
            endcase
        end
    end

    // Every reported result must correspond to the earlier captured values.
    always @(posedge clk)
        if (state == REPORT)
            assert (sample_out == expected_output);
endmodule

module phase_capture_deadlines #(
    parameter WORD_W = 8,
    parameter DEPTH = 16,
    parameter SERVICE_PERIOD = 8
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_ref_edge,
    input  wire i_fb_edge,
    output wire o_up,
    output wire o_dn,
    output wire o_pair_ready,
    output wire o_accept,
    output wire o_complete,
    output reg [WORD_W-1:0] o_result
);
    localparam [WORD_W-1:0] DEPTH8 = DEPTH;
    localparam [WORD_W-1:0] PERIOD8 = SERVICE_PERIOD;
    localparam [WORD_W-1:0] MAX_WAIT8 = DEPTH * SERVICE_PERIOD;

    reg up_q, dn_q;
    reg [WORD_W-1:0] phase_ticks;
    reg [WORD_W-1:0] samples [0:DEPTH-1];
    reg [WORD_W-1:0] budget [0:DEPTH-1];
    reg [DEPTH-1:0] valid;
    reg [WORD_W-1:0] rd_ptr, wr_ptr, count;
    reg [WORD_W-1:0] accepted_count, completed_count;
    reg [WORD_W-1:0] service_wait;
    reg armed, past_valid, expired;

    wire seen_up = up_q || i_ref_edge;
    wire seen_dn = dn_q || i_fb_edge;
    wire pair_pending = seen_up && seen_dn;
    wire push = pair_pending && (count < DEPTH8);
    wire pop = (count != 8'd0) && (service_wait == 8'd0);
    wire common_clear = push;
    wire [WORD_W-1:0] phase_sample =
        phase_ticks | (up_q ? 8'h80 : 8'h00);
    wire [WORD_W-1:0] slot_distance [0:DEPTH-1];
    wire [DEPTH-1:0] expiring;

    assign o_up = up_q;
    assign o_dn = dn_q;
    assign o_pair_ready = i_ce && (count < DEPTH8);
    assign o_accept = i_ce && push;
    assign o_complete = i_ce && pop;

    initial begin
        up_q = 1'b0;
        dn_q = 1'b0;
        phase_ticks = 8'd0;
        valid = {DEPTH{1'b0}};
        rd_ptr = 8'd0;
        wr_ptr = 8'd0;
        count = 8'd0;
        accepted_count = 8'd0;
        completed_count = 8'd0;
        service_wait = 8'd0;
        armed = 1'b0;
        past_valid = 1'b0;
        expired = 1'b0;
        o_result = 8'd0;
    end

    // Sampled phase-frequency detector. Both pulse flops use one clear path.
    // A full sample FIFO stretches the paired pulses until storage is free.
    always @(posedge clk) begin
        if (i_ce) begin
            if (common_clear) begin
                up_q <= 1'b0;
                dn_q <= 1'b0;
                phase_ticks <= 8'd0;
            end else begin
                up_q <= seen_up;
                dn_q <= seen_dn;
                if ((seen_up ^ seen_dn) && (phase_ticks < 8'd15))
                    phase_ticks <= phase_ticks + 8'd1;
            end
        end
    end

    // One queued comparison is completed every SERVICE_PERIOD enabled clocks.
    // Budgets count enabled clocks, so disabling i_ce freezes the whole design.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            if (service_wait == 8'd0)
                service_wait <= PERIOD8 - 8'd1;
            else
                service_wait <= service_wait - 8'd1;

            case ({push, pop})
                2'b10: count <= count + 8'd1;
                2'b01: count <= count - 8'd1;
                default: count <= count;
            endcase

            if (push) begin
                armed <= 1'b1;
                accepted_count <= accepted_count + 8'd1;
                if (wr_ptr == DEPTH8 - 8'd1)
                    wr_ptr <= 8'd0;
                else
                    wr_ptr <= wr_ptr + 8'd1;
            end
            if (pop) begin
                o_result <= samples[rd_ptr];
                completed_count <= completed_count + 8'd1;
                if (rd_ptr == DEPTH8 - 8'd1)
                    rd_ptr <= 8'd0;
                else
                    rd_ptr <= rd_ptr + 8'd1;
            end

            // Sticky witness of a countdown expiring before its response.
            if (|expiring)
                expired <= 1'b1;
        end
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : entry
            localparam [WORD_W-1:0] INDEX = g;
            assign slot_distance[g] = (INDEX >= rd_ptr)
                ? (INDEX - rd_ptr) : (DEPTH8 - rd_ptr + INDEX);
            assign expiring[g] = valid[g]
                && !(pop && (rd_ptr == INDEX))
                && (budget[g] <= 8'd1);

            initial begin
                samples[g] = 8'd0;
                budget[g] = 8'd0;
            end

            always @(posedge clk) begin
                if (i_ce) begin
                    if (valid[g] && !(pop && (rd_ptr == INDEX))
                            && (budget[g] != 8'd0))
                        budget[g] <= budget[g] - 8'd1;
                    if (pop && (rd_ptr == INDEX))
                        valid[g] <= 1'b0;
                    if (push && (wr_ptr == INDEX)) begin
                        valid[g] <= 1'b1;
                        samples[g] <= phase_sample;
                        budget[g] <= MAX_WAIT8;
                    end
                end
            end
        end
    endgenerate

    // After the first accepted comparison, an unchanged armed scope must
    // never see the deadline-expiration witness change.
    always @(posedge clk)
        if (past_valid && armed && $stable(armed))
            assert ($stable(expired));
endmodule

module routing_status_clear #(
    parameter integer STATUS_WIDTH = 64,
    parameter integer COUNT_WIDTH = 64
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire [STATUS_WIDTH-1:0] route_event_async,
    input wire clear_request,
    output reg [STATUS_WIDTH-1:0] sw_status,
    output reg outstanding,
    output reg [COUNT_WIDTH-1:0] countdown
);
    localparam [COUNT_WIDTH-1:0] COUNT_ZERO  = COUNT_WIDTH'(64'd0);
    localparam [COUNT_WIDTH-1:0] COUNT_ONE   = COUNT_WIDTH'(64'd1);
    localparam [COUNT_WIDTH-1:0] COUNT_TWO   = COUNT_WIDTH'(64'd2);
    localparam [COUNT_WIDTH-1:0] COUNT_THREE = COUNT_WIDTH'(64'd3);
    localparam [COUNT_WIDTH-1:0] COUNT_FOUR  = COUNT_WIDTH'(64'd4);
    localparam [COUNT_WIDTH-1:0] COUNT_FIVE  = COUNT_WIDTH'(64'd5);
    localparam [COUNT_WIDTH-1:0] COUNT_SIX   = COUNT_WIDTH'(64'd6);

    reg [STATUS_WIDTH-1:0] source_sticky;
    reg [STATUS_WIDTH-1:0] sw_status_meta;
    reg sw_clear_toggle;
    reg src_clear_meta;
    reg src_clear_sync;
    reg src_clear_seen;
    reg sw_ack_meta;
    reg sw_ack_sync;
    reg pv;

    initial begin
        source_sticky = {STATUS_WIDTH{1'b0}};
        sw_status_meta = {STATUS_WIDTH{1'b0}};
        sw_status = {STATUS_WIDTH{1'b0}};
        sw_clear_toggle = 1'b0;
        src_clear_meta = 1'b0;
        src_clear_sync = 1'b0;
        src_clear_seen = 1'b0;
        sw_ack_meta = 1'b0;
        sw_ack_sync = 1'b0;
        outstanding = 1'b0;
        countdown = COUNT_ZERO;
        pv = 1'b0;
    end

    // The common verification clock advances both logical domains.
    // i_ce freezes both domains, including all synchronizer stages.
    // Source domain: synchronize the clear toggle and latch routing events.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            source_sticky <= {STATUS_WIDTH{1'b0}};
            src_clear_meta <= 1'b0;
            src_clear_sync <= 1'b0;
            src_clear_seen <= 1'b0;
        end else if (i_ce) begin
            src_clear_meta <= sw_clear_toggle;
            src_clear_sync <= src_clear_meta;
            src_clear_seen <= src_clear_sync;

            // New events win over clearing, avoiding loss at the clear edge.
            if (src_clear_sync != src_clear_seen)
                source_sticky <= route_event_async;
            else
                source_sticky <= source_sticky | route_event_async;
        end
    end

    // Software domain: synchronize status and the clear acknowledgement.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sw_status_meta <= {STATUS_WIDTH{1'b0}};
            sw_status <= {STATUS_WIDTH{1'b0}};
            sw_ack_meta <= 1'b0;
            sw_ack_sync <= 1'b0;
            sw_clear_toggle <= 1'b0;
            outstanding <= 1'b0;
            countdown <= COUNT_ZERO;
            pv <= 1'b0;
        end else if (i_ce) begin
            pv <= 1'b1;
            sw_status_meta <= source_sticky;
            sw_status <= sw_status_meta;
            sw_ack_meta <= src_clear_seen;
            sw_ack_sync <= sw_ack_meta;

            if (!outstanding) begin
                countdown <= COUNT_ZERO;
                if (clear_request) begin
                    sw_clear_toggle <= !sw_clear_toggle;
                    outstanding <= 1'b1;
                    countdown <= COUNT_SIX;
                end
            end else if (sw_ack_sync == sw_clear_toggle) begin
                outstanding <= 1'b0;
                countdown <= COUNT_ZERO;
            end else if (countdown != COUNT_ZERO) begin
                countdown <= countdown - COUNT_ONE;
            end
        end
    end

    // A request active on the previous enabled cycle must finish if that
    // cycle consumed its final budget tick. The bound is six enabled cycles.
    always @(posedge clk)
        if (pv && $past(i_ce && outstanding))
            assert (!outstanding || ($past(countdown) > COUNT_ONE));
endmodule

module command_round_robin #(
    parameter [63:0] OUTPUTS = 64'd4  // Supported configurations: OUTPUTS >= 4.
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        i_ce,
    input  wire        q_open,
    input  wire        r_close,
    input  wire        item_valid,
    input  wire [63:0] item_word,
    output reg         window,
    output reg         have_dispatch,
    output reg  [63:0] last_output,
    output reg  [63:0] last_word
);
    localparam [1:0] WAIT_ARM = 2'd0;
    localparam [1:0] ARMED    = 2'd1;
    localparam [1:0] STARTED  = 2'd2;
    localparam [1:0] FINISHED = 2'd3;

    reg [63:0] next_output;
    reg [1:0] chain_state;

    // Each rotation sends command words to ARM, START, FINISH, then
    // housekeeping destinations. The FSM records the ordered history.
    // The output registers retain the most recently dispatched word.
    initial begin
        window        = 1'b0;
        have_dispatch = 1'b0;
        last_output   = 64'd0;
        last_word     = 64'd0;
        next_output   = 64'd0;
        chain_state   = WAIT_ARM;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            window        <= 1'b0;
            have_dispatch <= 1'b0;
            last_output   <= 64'd0;
            last_word     <= 64'd0;
            next_output   <= 64'd0;
            chain_state   <= WAIT_ARM;
        end else if (i_ce) begin
            if (r_close) begin
                window        <= 1'b0;
                have_dispatch <= 1'b0;
                last_output   <= 64'd0;
                last_word     <= 64'd0;
                next_output   <= 64'd0;
                chain_state   <= WAIT_ARM;
            end else if (q_open) begin
                window        <= 1'b1;
                have_dispatch <= 1'b0;
                last_output   <= 64'd0;
                last_word     <= 64'd0;
                next_output   <= 64'd0;
                chain_state   <= WAIT_ARM;
            end else if (window && item_valid) begin
                have_dispatch <= 1'b1;
                last_output   <= next_output;
                last_word     <= item_word;

                if (next_output == OUTPUTS - 64'd1) begin
                    next_output <= 64'd0;
                    chain_state <= WAIT_ARM;
                end else begin
                    next_output <= next_output + 64'd1;
                    case (next_output)
                        64'd0: chain_state <= ARMED;
                        64'd1: begin
                            if (chain_state == ARMED)
                                chain_state <= STARTED;
                        end
                        64'd2: begin
                            if (chain_state == STARTED)
                                chain_state <= FINISHED;
                        end
                        default: chain_state <= chain_state;
                    endcase
                end
            end
        end
    end

    // Inside the latched scope, START requires the arm/start history,
    // and FINISH requires the complete arm/start/finish history.
    always @(*) begin
        if (window && have_dispatch)
            assert (((last_output != 64'd1) ||
                     (chain_state == STARTED) ||
                     (chain_state == FINISHED)) &&
                    ((last_output != 64'd2) ||
                     (chain_state == FINISHED)));
    end
endmodule

module lift_arrival_monitor #(
    parameter integer FLOORS = 6,
    parameter integer WORD_W = 64
) (
    input wire clk,
    input wire i_ce,
    input wire [FLOORS-1:0] call_buttons,
    input wire begin_observation,
    input wire end_observation,
    output reg [WORD_W-1:0] current_floor,
    output reg [WORD_W-1:0] open_epoch
);
    localparam logic [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam logic [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam logic [WORD_W-1:0] LAST_FLOOR = WORD_W'(FLOORS - 32'd1);

    typedef enum logic [1:0] {
        IDLE       = 2'b00,
        MOVING     = 2'b01,
        ARRIVED    = 2'b10,
        DOORS_OPEN = 2'b11
    } phase_t;

    typedef enum logic [1:0] {
        DOOR_SHUT    = 2'b00,
        DOOR_RELEASE = 2'b01,
        DOOR_OPEN    = 2'b10
    } door_t;

    phase_t phase;
    door_t door_state;
    reg direction_up;
    reg [FLOORS-1:0] pending;
    reg [WORD_W-1:0] target_floor;
    reg [WORD_W-1:0] arrival_epoch;
    reg [WORD_W-1:0] arrival_shadow;
    reg observe_window;
    reg past_valid;

    wire [FLOORS-1:0] queued_calls = pending | call_buttons;
    reg [WORD_W-1:0] selected_floor;

    // Fixed-priority dispatch among the pending landing calls.
    always @(*) begin
        selected_floor = ZERO;
        for (integer f = 0; f < FLOORS; f = f + 1) begin
            if (queued_calls[f])
                selected_floor = WORD_W'(f);
        end
    end

    initial begin
        phase = IDLE;
        door_state = DOOR_SHUT;
        direction_up = 1'b0;
        pending = {FLOORS{1'b0}};
        current_floor = ZERO;
        target_floor = ZERO;
        arrival_epoch = ZERO;
        arrival_shadow = ZERO;
        open_epoch = ZERO;
        observe_window = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            pending <= queued_calls;

            // This shadow samples the earlier landing-arrival event count.
            arrival_shadow <= arrival_epoch;

            // Q begins the observation session; R ends it, if it arrives.
            if (end_observation)
                observe_window <= 1'b0;
            else if (begin_observation)
                observe_window <= 1'b1;

            case (phase)
                IDLE: begin
                    if (|queued_calls) begin
                        target_floor <= selected_floor;
                        direction_up <= (selected_floor > current_floor);
                        if (selected_floor == current_floor) begin
                            pending[selected_floor] <= 1'b0;
                            arrival_epoch <= arrival_epoch + ONE;
                            door_state <= DOOR_RELEASE;
                            phase <= ARRIVED;
                        end else begin
                            phase <= MOVING;
                        end
                    end
                end

                MOVING: begin
                    if (current_floor == target_floor) begin
                        pending[current_floor] <= 1'b0;
                        arrival_epoch <= arrival_epoch + ONE;
                        door_state <= DOOR_RELEASE;
                        phase <= ARRIVED;
                    end else if (direction_up) begin
                        current_floor <= current_floor + ONE;
                    end else begin
                        current_floor <= current_floor - ONE;
                    end
                end

                ARRIVED: begin
                    // Opening consumes the arrival recorded on an earlier tick.
                    open_epoch <= arrival_epoch;
                    door_state <= DOOR_OPEN;
                    phase <= DOORS_OPEN;
                end

                DOORS_OPEN: begin
                    door_state <= DOOR_SHUT;
                    phase <= IDLE;
                end
            endcase
        end
    end

    // During the latched session, an unchanged prior-arrival record must
    // not accompany a new door-opening receipt.
    always @(posedge clk) begin
        if (past_valid && observe_window && $stable(arrival_shadow))
            assert ($stable(open_epoch));
    end
endmodule

module manchester_stream #(
    parameter integer WORD_BITS = 16,
    parameter integer COUNT_BITS = 16
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [WORD_BITS-1:0] in_data,
    output wire                 out_valid,
    input  wire                 out_ready,
    output reg                  drive_high,
    output reg                  drive_low
);
    localparam [COUNT_BITS-1:0] COUNT_ZERO = {COUNT_BITS{1'b0}};
    localparam [COUNT_BITS-1:0] COUNT_ONE = {{(COUNT_BITS-1){1'b0}}, 1'b1};
    localparam [COUNT_BITS-1:0] WORD_COUNT = WORD_BITS;

    typedef enum logic [1:0] {
        IDLE = 2'b00,
        SEND = 2'b01
    } state_t;

    state_t state;
    reg [WORD_BITS-1:0] shift_reg;
    reg [COUNT_BITS-1:0] bits_left;
    reg half_phase;
    reg before_first_word_complete;

    assign in_ready = (state == IDLE);
    assign out_valid = (state == SEND);

    initial begin
        state = IDLE;
        shift_reg = {WORD_BITS{1'b0}};
        bits_left = COUNT_ZERO;
        half_phase = 1'b0;
        drive_high = 1'b0;
        drive_low = 1'b1;
        before_first_word_complete = 1'b1;
    end

    // Each output handshake consumes one Manchester half-symbol.
    // Both driver controls remain stable under output back-pressure.
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (in_valid && in_ready) begin
                    state <= SEND;
                    shift_reg <= in_data;
                    bits_left <= WORD_COUNT;
                    half_phase <= 1'b0;
                    drive_high <= in_data[0];
                    drive_low <= !in_data[0];
                end
            end
            SEND: begin
                if (out_valid && out_ready) begin
                    if (half_phase == 1'b0) begin
                        // The middle of every bit period reverses polarity.
                        half_phase <= 1'b1;
                        drive_high <= !drive_high;
                        drive_low <= !drive_low;
                    end else if (bits_left == COUNT_ONE) begin
                        state <= IDLE;
                        shift_reg <= {WORD_BITS{1'b0}};
                        bits_left <= COUNT_ZERO;
                        half_phase <= 1'b0;
                        drive_high <= 1'b0;
                        drive_low <= 1'b1;
                        before_first_word_complete <= 1'b0;
                    end else begin
                        shift_reg <= {1'b0, shift_reg[WORD_BITS-1:1]};
                        bits_left <= bits_left - COUNT_ONE;
                        half_phase <= 1'b0;
                        drive_high <= shift_reg[1];
                        drive_low <= !shift_reg[1];
                    end
                end
            end
            default: begin
                // Illegal controller encodings hold their state.
            end
        endcase
    end

    // Before the first completed word, opposing drivers never overlap.
    always @(posedge clk)
        assert (!before_first_word_complete || !(drive_high && drive_low));
endmodule

module board_retention_controller #(
    parameter integer WIDTH = 32'd32,
    parameter integer BANKS = 32'd8
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 i_sleep,
    input  wire                 i_wake,
    output wire [BANKS-1:0]     o_save,
    output wire [BANKS-1:0]     o_restore,
    output wire                 o_power_down
);
    localparam [WIDTH-1:0] ZERO = {WIDTH{1'b0}};
    localparam [WIDTH-1:0] ONE = {{(WIDTH-1){1'b0}}, 1'b1};
    localparam [WIDTH-1:0] BANK_LIMIT = BANKS;
    localparam [WIDTH-1:0] PH_RUN     = 32'd0;
    localparam [WIDTH-1:0] PH_SAVE    = 32'd1;
    localparam [WIDTH-1:0] PH_OFF     = 32'd2;
    localparam [WIDTH-1:0] PH_RESTORE = 32'd3;

    reg [WIDTH-1:0] phase;
    reg [WIDTH-1:0] retained_count;
    reg save_done;
    reg restore_pending;

    initial begin
        phase = PH_RUN;
        retained_count = ZERO;
        save_done = 1'b0;
        restore_pending = 1'b0;
    end

    // Save banks in ascending order and restore them in reverse order.
    genvar bank;
    generate
        for (bank = 32'd0; bank < BANKS; bank = bank + 32'd1) begin : g_bank
            localparam [WIDTH-1:0] BANK_INDEX = bank;
            assign o_save[bank] = i_ce && (phase == PH_SAVE)
                                 && !save_done
                                 && (retained_count == BANK_INDEX);
            assign o_restore[bank] = i_ce && (phase == PH_RESTORE)
                                    && restore_pending
                                    && (retained_count == BANK_INDEX + ONE);
        end
    endgenerate

    assign o_power_down = (phase == PH_OFF);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                PH_RUN: begin
                    if (i_sleep)
                        phase <= PH_SAVE;
                end
                PH_SAVE: begin
                    if (!save_done) begin
                        retained_count <= retained_count + ONE;
                        if (retained_count == BANK_LIMIT - ONE)
                            save_done <= 1'b1;
                    end else begin
                        phase <= PH_OFF;
                        restore_pending <= 1'b1;
                    end
                end
                PH_OFF: begin
                    if (i_wake)
                        phase <= PH_RESTORE;
                end
                PH_RESTORE: begin
                    if (restore_pending) begin
                        retained_count <= retained_count - ONE;
                        if (retained_count == ONE)
                            restore_pending <= 1'b0;
                    end else begin
                        phase <= PH_RUN;
                        save_done <= 1'b0;
                    end
                end
                default: begin
                    phase <= PH_RUN;
                    retained_count <= ZERO;
                    save_done <= 1'b0;
                    restore_pending <= 1'b0;
                end
            endcase
        end
    end

    always @(*)
        assert (retained_count <= BANK_LIMIT);
endmodule

module ternary_addsub_fifo #(
    parameter WORD_W = 64,
    parameter DEPTH = 32
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_a,
    input  wire [WORD_W-1:0]     in_b,
    input  wire                  in_sub,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [WORD_W-1:0]     out_result,
    output wire                  out_carry,
    output wire                  out_overflow,
    output wire                  out_zero,
    output wire                  out_overflow_up,
    output wire                  out_sub
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] CAPACITY = DEPTH;
    localparam [WORD_W-1:0] LAST = CAPACITY - ONE;

    reg [WORD_W-1:0] result_mem [0:DEPTH-1];
    reg [WORD_W-1:0] status_mem [0:DEPTH-1];
    reg [WORD_W-1:0] rd_ptr;
    reg [WORD_W-1:0] wr_ptr;
    reg [WORD_W-1:0] used;
    reg before_sub_retire;

    // Combinational add/sub datapath for accumulator updates.
    // Subtraction complements B and supplies the carry-in.
    wire [WORD_W-1:0] effective_b = in_b ^ {WORD_W{in_sub}};
    wire [WORD_W:0] extended_sum =
        {1'b0, in_a} + {1'b0, effective_b} + {{WORD_W{1'b0}}, in_sub};
    wire signed_overflow =
        (in_a[WORD_W-1] ^ extended_sum[WORD_W-1]) &
        ~(in_a[WORD_W-1] ^ effective_b[WORD_W-1]);

    // Status word: [4] subtract, [3] effective-B sign, [2] A sign,
    //              [1] signed overflow, [0] carry-out.
    wire [WORD_W-1:0] incoming_status = {
        {(WORD_W-5){1'b0}},
        in_sub, effective_b[WORD_W-1], in_a[WORD_W-1],
        signed_overflow, extended_sum[WORD_W]
    };

    assign in_ready = used < CAPACITY;
    assign out_valid = used != ZERO;
    wire push = in_valid && in_ready;
    wire pop = out_valid && out_ready;

    assign out_result = result_mem[rd_ptr];
    assign out_carry = status_mem[rd_ptr][0];
    assign out_overflow = status_mem[rd_ptr][1];
    assign out_zero = out_result == ZERO;
    assign out_overflow_up = out_overflow && !status_mem[rd_ptr][2];
    assign out_sub = status_mem[rd_ptr][4];

    integer k;
    initial begin
        rd_ptr = ZERO;
        wr_ptr = ZERO;
        used = ZERO;
        before_sub_retire = 1'b1;
        for (k = 0; k < DEPTH; k = k + 1) begin
            result_mem[k] = ZERO;
            status_mem[k] = ZERO;
        end
    end

    always @(posedge clk) begin
        if (push) begin
            result_mem[wr_ptr] <= extended_sum[WORD_W-1:0];
            status_mem[wr_ptr] <= incoming_status;
            wr_ptr <= (wr_ptr == LAST) ? ZERO : wr_ptr + ONE;
        end
        if (pop) begin
            rd_ptr <= (rd_ptr == LAST) ? ZERO : rd_ptr + ONE;
            if (out_sub)
                before_sub_retire <= 1'b0;
        end
        case ({push, pop})
            2'b10: used <= used + ONE;
            2'b01: used <= used - ONE;
            default: begin end
        endcase
    end

    // Same-cycle descriptions of occupied slots and arithmetic metadata.
    wire [DEPTH-1:0] occupied;
    wire [DEPTH-1:0] entry_ok;
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : slot_checks
            localparam [WORD_W-1:0] SLOT = g;
            wire [WORD_W-1:0] distance_from_head =
                (SLOT >= rd_ptr) ? (SLOT - rd_ptr) :
                                        (CAPACITY - rd_ptr + SLOT);
            assign occupied[g] = distance_from_head < used;
            assign entry_ok[g] =
                (status_mem[g][WORD_W-1:5] == {(WORD_W-5){1'b0}}) &&
                (status_mem[g][1] ==
                    ((status_mem[g][2] ^ result_mem[g][WORD_W-1]) &
                     ~(status_mem[g][2] ^ status_mem[g][3]))) &&
                (status_mem[g][0] ==
                    ((status_mem[g][2] & status_mem[g][3]) |
                     ((status_mem[g][2] | status_mem[g][3]) &
                      ~result_mem[g][WORD_W-1])));
        end
    endgenerate

    // Before the first subtraction retires, zero and upward signed
    // overflow must never be reported together for a valid result.
    always @(posedge clk)
        if (before_sub_retire && out_valid)
            assert (!(out_zero && out_overflow_up));
endmodule

module uart_flow_chain #(
    parameter integer WORD_W = 16,
    parameter integer RX_DEPTH = 96
) (
    input  wire                  clk,
    input  wire                  i_cts,
    input  wire                  i_cmd_valid,
    output logic                 o_cmd_ready,
    input  wire [15:0]           i_cmd,
    input  wire [WORD_W-1:0]     i_cmd_data,
    output wire                  o_finish_valid,
    input  wire                  i_finish_ready,
    output wire [WORD_W-1:0]     o_finish_data,
    output wire                  o_tx_active,
    output wire                  o_rts
);
    localparam logic [15:0] CMD_ARM          = 16'h0001;
    localparam logic [15:0] CMD_START        = 16'h0002;
    localparam logic [15:0] CMD_FINISH       = 16'h0003;
    localparam logic [15:0] CMD_RX_PUSH      = 16'h0004;
    localparam logic [15:0] CMD_RX_POP       = 16'h0005;
    localparam logic [15:0] CMD_CFG_ASSERT   = 16'h0006;
    localparam logic [15:0] CMD_CFG_DEASSERT = 16'h0007;

    localparam logic [WORD_W-1:0] ZERO = WORD_W'(16'd0);
    localparam logic [WORD_W-1:0] ONE = WORD_W'(16'd1);
    localparam logic [WORD_W-1:0] CAPACITY = WORD_W'(RX_DEPTH);
    localparam logic [WORD_W-1:0] INITIAL_ASSERT =
        WORD_W'(RX_DEPTH / 16'd4);
    localparam logic [WORD_W-1:0] INITIAL_DEASSERT =
        WORD_W'((RX_DEPTH * 16'd3) / 16'd4);

    typedef enum logic [1:0] {
        IDLE     = 2'b00,
        ARMED    = 2'b01,
        ACTIVE   = 2'b10,
        FINISHED = 2'b11
    } state_t;

    state_t state;
    logic arm_valid, start_valid;
    logic [WORD_W-1:0] tx_word;
    logic cts_meta, cts_sync;
    logic [WORD_W-1:0] rx_fill;
    logic [WORD_W-1:0] rts_assert_threshold;
    logic [WORD_W-1:0] rts_deassert_threshold;
    logic rts_reg;

    logic [WORD_W-1:0] fill_next;
    logic [WORD_W-1:0] assert_next, deassert_next;
    logic rts_next;

    wire cmd_fire = i_cmd_valid && o_cmd_ready;
    wire finish_fire = o_finish_valid && i_finish_ready;
    wire activity = i_cmd_valid || i_finish_ready;

    assign o_finish_valid = (state == FINISHED);
    assign o_finish_data = tx_word;
    assign o_tx_active = (state == ACTIVE) && start_valid;
    assign o_rts = rts_reg;

    initial begin
        state = IDLE;
        arm_valid = 1'b0;
        start_valid = 1'b0;
        tx_word = ZERO;
        cts_meta = 1'b0;
        cts_sync = 1'b0;
        rx_fill = ZERO;
        rts_assert_threshold = INITIAL_ASSERT;
        rts_deassert_threshold = INITIAL_DEASSERT;
        rts_reg = 1'b1;
    end

    // ARM captures a transmit word; START requests launch; FINISH is
    // the serial engine's completion notification. RX commands account
    // for transfers into and out of the external receive buffer.
    always @(*) begin
        o_cmd_ready = 1'b0;
        case (i_cmd)
            CMD_ARM:
                o_cmd_ready = (state == IDLE) && !arm_valid;
            CMD_START:
                o_cmd_ready = (state == ARMED) && arm_valid && cts_sync;
            CMD_FINISH:
                o_cmd_ready = (state == ACTIVE) && start_valid;
            CMD_RX_PUSH:
                o_cmd_ready = (rx_fill < CAPACITY);
            CMD_RX_POP:
                o_cmd_ready = (rx_fill != ZERO);
            CMD_CFG_ASSERT:
                o_cmd_ready = (i_cmd_data < rts_deassert_threshold);
            CMD_CFG_DEASSERT:
                o_cmd_ready = (i_cmd_data > rts_assert_threshold) &&
                              (i_cmd_data <= CAPACITY);
            default:
                o_cmd_ready = 1'b0;
        endcase
    end

    // Reevaluate hysteresis using the committed fill and thresholds.
    // Logical RTS high advertises receive capacity.
    always @(*) begin
        fill_next = rx_fill;
        assert_next = rts_assert_threshold;
        deassert_next = rts_deassert_threshold;
        if (cmd_fire) begin
            case (i_cmd)
                CMD_RX_PUSH:      fill_next = rx_fill + ONE;
                CMD_RX_POP:       fill_next = rx_fill - ONE;
                CMD_CFG_ASSERT:   assert_next = i_cmd_data;
                CMD_CFG_DEASSERT: deassert_next = i_cmd_data;
                default: begin end
            endcase
        end
        rts_next = rts_reg;
        if (fill_next >= deassert_next)
            rts_next = 1'b0;
        else if (fill_next <= assert_next)
            rts_next = 1'b1;
    end

    always @(posedge clk) begin
        // Both incoming handshake controls low freeze every register.
        // A blocked valid START still clocks the CTS synchronizer.
        if (activity) begin
            cts_meta <= i_cts;
            cts_sync <= cts_meta;
            rx_fill <= fill_next;
            rts_assert_threshold <= assert_next;
            rts_deassert_threshold <= deassert_next;
            rts_reg <= rts_next;

            if (finish_fire) begin
                state <= IDLE;
                arm_valid <= 1'b0;
                start_valid <= 1'b0;
            end

            if (cmd_fire) begin
                case (i_cmd)
                    CMD_ARM: begin
                        tx_word <= i_cmd_data;
                        arm_valid <= 1'b1;
                        start_valid <= 1'b0;
                        state <= ARMED;
                    end
                    CMD_START: begin
                        start_valid <= 1'b1;
                        state <= ACTIVE;
                    end
                    CMD_FINISH: begin
                        state <= FINISHED;
                    end
                    default: begin end
                endcase
            end
        end
    end

    // Globally, completion requires the arm-then-start chain for this word.
    assert property ((state != FINISHED) || (arm_valid && start_valid));
endmodule

module quarter_wave_sample_port #(
    parameter [31:0] TABLE_ENTRIES = 32'd12
) (
    input  wire        clk,
    input  wire        i_valid,
    output wire        i_ready,
    input  wire        i_end,
    output reg         o_valid,
    input  wire        o_ready,
    output wire [31:0] o_data
);
    // TABLE_ENTRIES must be at least two. Each accepted token requests
    // the next full-period sample; i_end marks the end of a measurement.
    localparam [31:0] HALF = TABLE_ENTRIES * 32'd2;
    localparam [31:0] THREE_QUARTERS = TABLE_ENTRIES * 32'd3;
    localparam [31:0] PERIOD = TABLE_ENTRIES * 32'd4;

    reg [31:0] qrom [0:TABLE_ENTRIES-32'd1];
    reg [31:0] phase;
    reg [31:0] folded_addr;
    reg        negative_half;

    // Registered magnitude and polarity form the output holding register.
    // The positive-half tag comes independently from the phase decoder.
    reg [31:0] out_magnitude;
    reg        out_negative;
    reg        out_positive;
    reg        before_end;
    reg        pv;

    function automatic [31:0] quarter_sample(input [31:0] addr);
        reg [31:0] bin;
        begin
            bin = (addr * 32'd11) / (TABLE_ENTRIES - 32'd1);
            case (bin)
                32'd0:  quarter_sample = 32'd0;
                32'd1:  quarter_sample = 32'd4663;
                32'd2:  quarter_sample = 32'd9232;
                32'd3:  quarter_sample = 32'd13612;
                32'd4:  quarter_sample = 32'd17715;
                32'd5:  quarter_sample = 32'd21458;
                32'd6:  quarter_sample = 32'd24764;
                32'd7:  quarter_sample = 32'd27566;
                32'd8:  quarter_sample = 32'd29805;
                32'd9:  quarter_sample = 32'd31440;
                32'd10: quarter_sample = 32'd32434;
                default: quarter_sample = 32'd32767;
            endcase
        end
    endfunction

    function automatic [31:0] fold_address(input [31:0] p);
        begin
            if (p < TABLE_ENTRIES)
                fold_address = p;
            else if (p < HALF)
                fold_address = HALF - 32'd1 - p;
            else if (p < THREE_QUARTERS)
                fold_address = p - HALF;
            else
                fold_address = PERIOD - 32'd1 - p;
        end
    endfunction

    integer init_index;
    initial begin
        for (init_index = 32'd0; init_index < TABLE_ENTRIES;
             init_index = init_index + 32'd1)
            qrom[init_index] = quarter_sample(init_index);
        phase = 32'd0;
        folded_addr = 32'd0;
        negative_half = 1'b0;
        out_magnitude = 32'd0;
        out_negative = 1'b0;
        out_positive = 1'b1;
        o_valid = 1'b0;
        before_end = 1'b1;
        pv = 1'b0;
    end

    wire [31:0] folded_phase = fold_address(phase);
    wire [31:0] next_phase = (phase == PERIOD - 32'd1)
                                  ? 32'd0 : phase + 32'd1;

    wire [TABLE_ENTRIES-32'd1:0] table_signs;
    genvar g;
    generate
        for (g = 32'd0; g < TABLE_ENTRIES; g = g + 32'd1) begin : rom_signs
            assign table_signs[g] = qrom[g][31];
        end
    endgenerate
    wire rom_nonnegative = !(|table_signs);

    assign i_ready = !o_valid || o_ready;
    wire accept = i_valid && i_ready;
    wire retire = o_valid && o_ready;
    assign o_data = out_negative
                        ? (32'd0 - out_magnitude) : out_magnitude;

    always @(posedge clk) begin
        if (accept) begin
            out_magnitude <= qrom[folded_addr];
            out_negative <= negative_half;
            out_positive <= (phase < HALF);
            o_valid <= 1'b1;
            phase <= next_phase;
            folded_addr <= fold_address(next_phase);
            negative_half <= (next_phase >= HALF);
            pv <= 1'b1;
            if (i_end)
                before_end <= 1'b0;
        end else if (retire) begin
            o_valid <= 1'b0;
            pv <= 1'b1;
        end
    end

    // Before the first accepted end marker, a newly announced sample
    // must not have both a positive-half tag and a negative signed word.
    always @(posedge clk) begin
        if (pv && before_end && $rose(o_valid))
            assert (!(out_positive && o_data[31]));
    end
endmodule

module video_luma_hysteresis #(
    parameter integer DATA_BITS = 32
) (
    input wire clk,
    input wire i_ce,
    input wire i_reset,
    input wire cfg_write,
    input wire [DATA_BITS-1:0] cfg_floor,
    input wire [DATA_BITS-1:0] sample_luma,
    input wire window_open,
    input wire window_close,
    output reg boost_active
);
    // DATA_BITS must be at least 8; the default datapath is 32 bits.
    localparam [DATA_BITS-1:0] HYST_GAP = 32'd16;
    localparam [DATA_BITS-1:0] RESET_FALLING = 32'd64;
    localparam [DATA_BITS-1:0] MAX_FALLING =
        {1'b0, {(DATA_BITS-1){1'b1}}};

    reg [DATA_BITS-1:0] falling_threshold;
    reg [DATA_BITS-1:0] rising_threshold;
    reg above_fall_shadow;
    reg scope_active;

    wire [DATA_BITS-1:0] bounded_floor =
        {1'b0, cfg_floor[DATA_BITS-2:0]};

    initial begin
        falling_threshold = RESET_FALLING;
        rising_threshold = RESET_FALLING + HYST_GAP;
        boost_active = 1'b0;
        above_fall_shadow = 1'b0;
        scope_active = 1'b0;
    end

    always @(posedge clk) begin
        // Even synchronous reset waits for the clock enable.
        if (i_ce) begin
            if (i_reset) begin
                falling_threshold <= RESET_FALLING;
                rising_threshold <= RESET_FALLING + HYST_GAP;
                boost_active <= 1'b0;
                above_fall_shadow <= 1'b0;
                scope_active <= 1'b0;
            end else begin
                // Program both thresholds together, leaving room for the gap.
                if (cfg_write) begin
                    falling_threshold <= bounded_floor;
                    rising_threshold <= bounded_floor + HYST_GAP;
                end

                // Comparisons use the thresholds preceding this clock edge.
                if (sample_luma >= rising_threshold)
                    boost_active <= 1'b1;
                else if (sample_luma <= falling_threshold)
                    boost_active <= 1'b0;

                // Historical event: the most recently accepted sample was
                // above the falling threshold in effect when it was sampled.
                above_fall_shadow <= (sample_luma > falling_threshold);

                // The observation window persists until explicitly closed.
                if (window_close)
                    scope_active <= 1'b0;
                else if (window_open)
                    scope_active <= 1'b1;
            end
        end
    end

    // Within the window, an observed boost requires an earlier above-floor sample.
    assert property (!(scope_active && boost_active) || above_fall_shadow);
endmodule

module artifact_dispatch #(
    parameter integer WORD_W = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_finish,
    input  wire [WORD_W-1:0]     i_requested,
    input  wire [WORD_W-1:0]     i_cached,
    output reg  [WORD_W-1:0]     install_mask,
    output reg  [WORD_W-1:0]     fetch_mask
);
    reg [WORD_W-1:0] requested_mask;
    reg [WORD_W-1:0] cached_mask;
    reg [WORD_W-1:0] blocked_mask;
    reg [WORD_W-1:0] cached_snapshot;
    reg before_commit;

    wire [WORD_W-1:0] nand_result;
    wire commit_event;
    assign commit_event = i_ce && i_finish;

    // Stateless NAND bank, sampled together with its operands.
    genvar bit_index;
    generate
        for (bit_index = 0; bit_index < WORD_W; bit_index = bit_index + 1) begin : g_nand
            nand u_nand(nand_result[bit_index],
                        i_requested[bit_index], i_cached[bit_index]);
        end
    endgenerate

    initial begin
        requested_mask = {WORD_W{1'b0}};
        cached_mask = {WORD_W{1'b0}};
        blocked_mask = {WORD_W{1'b1}};
        cached_snapshot = {WORD_W{1'b0}};
        install_mask = {WORD_W{1'b0}};
        fetch_mask = {WORD_W{1'b0}};
        before_commit = 1'b1;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            requested_mask <= i_requested;
            cached_mask <= i_cached;
            blocked_mask <= nand_result;

            // Dispatch the preceding sampled request using its NAND result.
            cached_snapshot <= cached_mask;
            install_mask <= requested_mask & ~blocked_mask;
            fetch_mask <= requested_mask & blocked_mask;

            // Permanently end the scope at the first enabled commit event.
            if (commit_event)
                before_commit <= 1'b0;
        end
    end

    always @(posedge clk) begin
        if (before_commit) begin
            assert ((install_mask & ~cached_snapshot) == {WORD_W{1'b0}});
            assert ((fetch_mask & cached_snapshot) == {WORD_W{1'b0}});
        end
    end
endmodule

module capture_irq_cascade #(
    parameter integer WORD_W = 64,
    parameter integer INPUTS = 32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_load_config,
    input  wire [WORD_W-1:0]     i_cascade_identity,
    input  wire                  i_slave_mode,
    input  wire                  i_open,
    input  wire                  i_close,
    input  wire                  i_arm,
    input  wire                  i_start,
    input  wire [WORD_W-1:0]     i_capture_vector,
    input  wire [INPUTS-1:0]     i_primary_irq,
    input  wire                  i_primary_ack,
    input  wire [WORD_W-1:0]     i_ack_identity,
    output wire [INPUTS-1:0]     o_primary_pending,
    output wire [WORD_W-1:0]     o_vector,
    output wire                  o_finish
);
    localparam [WORD_W-1:0] SLOT_COUNT = INPUTS;
    localparam [WORD_W-1:0] PH_IDLE    = 64'd0;
    localparam [WORD_W-1:0] PH_ARMED   = 64'd1;
    localparam [WORD_W-1:0] PH_STARTED = 64'd2;
    localparam [WORD_W-1:0] PH_FINISH  = 64'd3;

    reg [WORD_W-1:0] cascade_identity;
    reg slave_mode;
    reg window;
    reg [WORD_W-1:0] primary_phase;
    reg slave_armed;
    reg slave_started;
    reg [WORD_W-1:0] slave_vector;
    reg [WORD_W-1:0] forwarded_vector;
    reg pv;
    reg [INPUTS-1:0] primary_pending;

    initial begin
        cascade_identity = 64'd0;
        slave_mode = 1'b1;
        window = 1'b0;
        primary_phase = PH_IDLE;
        slave_armed = 1'b0;
        slave_started = 1'b0;
        slave_vector = 64'd0;
        forwarded_vector = 64'd0;
        pv = 1'b0;
    end

    // The secondary controller drives its configured primary interrupt input.
    always @(*) begin
        primary_pending = i_primary_irq;
        if (slave_mode && (cascade_identity < SLOT_COUNT))
            primary_pending[cascade_identity] =
                window && slave_armed && (i_start || slave_started);
    end

    wire cascade_request = (cascade_identity < SLOT_COUNT) &&
                           primary_pending[cascade_identity];
    wire cascade_ack = i_primary_ack &&
                       (i_ack_identity == cascade_identity);

    assign o_primary_pending = primary_pending;
    assign o_vector = forwarded_vector;
    assign o_finish = window && (primary_phase == PH_FINISH);

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (i_load_config) begin
                cascade_identity <= i_cascade_identity % SLOT_COUNT;
                slave_mode <= i_slave_mode;
                window <= 1'b0;
                primary_phase <= PH_IDLE;
                slave_armed <= 1'b0;
                slave_started <= 1'b0;
            end else if (i_close) begin
                window <= 1'b0;
                primary_phase <= PH_IDLE;
                slave_armed <= 1'b0;
                slave_started <= 1'b0;
            end else if (i_open) begin
                window <= 1'b1;
                primary_phase <= PH_IDLE;
                slave_armed <= 1'b0;
                slave_started <= 1'b0;
            end else if (window && slave_mode) begin
                // Primary controller: latch the cascade request, then await ACK.
                case (primary_phase)
                    PH_IDLE:
                        if (i_arm)
                            primary_phase <= PH_ARMED;
                    PH_ARMED:
                        if (i_start && cascade_request)
                            primary_phase <= PH_STARTED;
                    PH_STARTED:
                        if (cascade_ack) begin
                            primary_phase <= PH_FINISH;
                            forwarded_vector <= slave_vector;
                        end
                    default: begin end
                endcase

                // Secondary controller: arm its vector before starting a request.
                if (i_arm && !slave_armed) begin
                    slave_armed <= 1'b1;
                    slave_vector <= i_capture_vector;
                end
                if (i_start && slave_armed && !slave_started)
                    slave_started <= 1'b1;
            end
        end
    end

    // A completed cascade must have been armed and started in the prior cycle.
    always @(posedge clk)
        if (pv && window && (primary_phase == PH_FINISH))
            assert ($past(window && slave_armed && slave_started));
endmodule

module exclusive_reservation_monitor #(
    parameter ENTRIES = 32'd8,
    parameter WORD_W = 32'd32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_load_exclusive,
    input  wire                  i_write,
    input  wire                  i_write_exclusive,
    input  wire [WORD_W-1:0]     i_master,
    input  wire [WORD_W-1:0]     i_addr,
    input  wire [WORD_W-1:0]     i_size_bytes,
    output wire                  exclusive_success,
    output reg  [WORD_W-1:0]     reservation_count
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] ENTRY_LIMIT = ENTRIES;

    reg [ENTRIES-1:0] reservation_valid;
    reg [WORD_W-1:0] reservation_addr [0:ENTRIES-1];
    reg [WORD_W-1:0] reservation_size [0:ENTRIES-1];
    reg before_first_success;

    wire [ENTRIES-1:0] exact_match;
    wire [ENTRIES-1:0] kill_mask;
    wire [WORD_W-1:0] valid_prefix [0:ENTRIES];
    wire [WORD_W-1:0] kill_prefix [0:ENTRIES];
    wire [WORD_W-1:0] valid_total;
    wire [WORD_W-1:0] killed_total;
    wire exclusive_match;
    wire commit_write;

    assign exclusive_match = |exact_match;
    assign commit_write = i_write && (!i_write_exclusive || exclusive_match);
    assign exclusive_success = i_ce && i_write && i_write_exclusive && exclusive_match;
    assign valid_prefix[0] = ZERO;
    assign kill_prefix[0] = ZERO;
    assign valid_total = valid_prefix[ENTRIES];
    assign killed_total = kill_prefix[ENTRIES];

    genvar g;
    generate
        for (g = 32'd0; g < ENTRIES; g = g + 32'd1) begin : slot
            localparam [WORD_W-1:0] MASTER_ID = g;
            wire [WORD_W:0] reservation_end;
            wire [WORD_W:0] write_end;
            wire overlaps;

            // Half-open byte intervals; extended endpoints avoid address overflow.
            assign reservation_end = {1'b0, reservation_addr[g]} +
                                     {1'b0, reservation_size[g]};
            assign write_end = {1'b0, i_addr} + {1'b0, i_size_bytes};
            assign overlaps = (reservation_size[g] != ZERO) &&
                              (i_size_bytes != ZERO) &&
                              ({1'b0, i_addr} < reservation_end) &&
                              ({1'b0, reservation_addr[g]} < write_end);
            assign exact_match[g] = reservation_valid[g] &&
                                    (i_master == MASTER_ID) &&
                                    (reservation_addr[g] == i_addr) &&
                                    (reservation_size[g] == i_size_bytes);

            // Committed overlapping writes invalidate reservations. An exclusive
            // store also consumes its master's reservation even when it fails.
            assign kill_mask[g] = reservation_valid[g] &&
                ((commit_write && overlaps) ||
                 (i_write && i_write_exclusive && (i_master == MASTER_ID)));
            assign valid_prefix[g+1] = valid_prefix[g] +
                {{(WORD_W-1){1'b0}}, reservation_valid[g]};
            assign kill_prefix[g+1] = kill_prefix[g] +
                {{(WORD_W-1){1'b0}}, kill_mask[g]};
        end
    endgenerate

    integer init_index;
    initial begin
        reservation_valid = {ENTRIES{1'b0}};
        reservation_count = ZERO;
        before_first_success = 1'b1;
        for (init_index = 32'd0; init_index < ENTRIES;
             init_index = init_index + 32'd1) begin
            reservation_addr[init_index] = ZERO;
            reservation_size[init_index] = ZERO;
        end
    end

    integer update_index;
    always @(posedge clk) begin
        if (i_ce) begin
            if (exclusive_success)
                before_first_success <= 1'b0;

            // Writes take priority if both request inputs are asserted.
            if (i_write) begin
                reservation_valid <= reservation_valid & ~kill_mask;
                reservation_count <= reservation_count - killed_total;
            end else if (i_load_exclusive) begin
                for (update_index = 32'd0; update_index < ENTRIES;
                     update_index = update_index + 32'd1) begin
                    if (i_master == update_index) begin
                        reservation_addr[update_index] <= i_addr;
                        reservation_size[update_index] <= i_size_bytes;
                        reservation_valid[update_index] <= 1'b1;
                        if (!reservation_valid[update_index])
                            reservation_count <= reservation_count + ONE;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (!before_first_success || (reservation_count <= ENTRY_LIMIT));
endmodule

module vector_lane_implication_audit #(
    parameter WORD_WIDTH = 16
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire begin_vector,
    input wire close_window,
    input wire scan_lane,
    input wire [WORD_WIDTH-1:0] i_required_mask,
    input wire [WORD_WIDTH-1:0] i_permitted_mask,
    output reg [WORD_WIDTH-1:0] violation_count,
    output reg window_open
);
    localparam [WORD_WIDTH-1:0] ZERO_WORD = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] ONE_WORD = {{(WORD_WIDTH-1){1'b0}}, 1'b1};
    localparam [WORD_WIDTH-1:0] MAX_VIOLATIONS = WORD_WIDTH;
    localparam [WORD_WIDTH:0] MAX_VIOLATIONS_EXT = {1'b0, MAX_VIOLATIONS};

    reg [WORD_WIDTH-1:0] required_mask;
    reg [WORD_WIDTH-1:0] permitted_mask;
    reg [WORD_WIDTH-1:0] implication_mask;
    reg scan_event;
    reg past_valid;

    wire [WORD_WIDTH-1:0] input_implication;
    wire [WORD_WIDTH:0] bad_prefix [0:WORD_WIDTH];
    wire [WORD_WIDTH:0] remaining_bad;

    assign bad_prefix[0] = {(WORD_WIDTH+1){1'b0}};
    assign remaining_bad = bad_prefix[WORD_WIDTH];

    genvar lane;
    generate
        for (lane = 0; lane < WORD_WIDTH; lane = lane + 1) begin : lane_rules
            // Each lane contains an IMPLY gate: required implies permitted.
            assign input_implication[lane] =
                (!i_required_mask[lane]) || i_permitted_mask[lane];
            assign bad_prefix[lane+1] = bad_prefix[lane] +
                {{WORD_WIDTH{1'b0}},
                 (required_mask[lane] && !permitted_mask[lane])};
        end
    endgenerate

    initial begin
        required_mask = ZERO_WORD;
        permitted_mask = ZERO_WORD;
        implication_mask = {WORD_WIDTH{1'b1}};
        violation_count = ZERO_WORD;
        window_open = 1'b0;
        scan_event = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            required_mask <= ZERO_WORD;
            permitted_mask <= ZERO_WORD;
            implication_mask <= {WORD_WIDTH{1'b1}};
            violation_count <= ZERO_WORD;
            window_open <= 1'b0;
            scan_event <= 1'b0;
            past_valid <= 1'b0;
        end else if (i_ce) begin
            past_valid <= 1'b1;

            if (close_window)
                window_open <= 1'b0;
            else if (begin_vector)
                window_open <= 1'b1;

            if (begin_vector) begin
                required_mask <= i_required_mask;
                permitted_mask <= i_permitted_mask;
                implication_mask <= input_implication;
                violation_count <= ZERO_WORD;
                scan_event <= 1'b0;
            end else begin
                scan_event <= scan_lane;
                if (scan_lane) begin
                    required_mask <= {1'b0, required_mask[WORD_WIDTH-1:1]};
                    permitted_mask <= {1'b0, permitted_mask[WORD_WIDTH-1:1]};
                    implication_mask <= {1'b1, implication_mask[WORD_WIDTH-1:1]};
                    if (!implication_mask[0])
                        violation_count <= violation_count + ONE_WORD;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (past_valid && window_open && $rose(scan_event))
            assert (violation_count <= MAX_VIOLATIONS);
    end
endmodule

module peripheral_dco_calibrator #(
    parameter integer WORD_W = 16
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire scope_q,
    input wire scope_r,
    input wire cal_request,
    input wire [WORD_W-1:0] reference_count,
    input wire [WORD_W-1:0] dco_count,
    output reg [WORD_W-1:0] trial_code,
    output reg [WORD_W-1:0] band_code,
    output reg outstanding,
    output reg window
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] TWO = ONE + ONE;
    localparam [WORD_W-1:0] LAST_BIT = WORD_W - 32'd1;
    localparam [WORD_W-1:0] CAL_CYCLES = WORD_W * 32'd2;
    localparam [WORD_W-1:0] FIRST_TRIAL = ONE << LAST_BIT;

    reg [WORD_W-1:0] bit_pos;
    reg [WORD_W-1:0] measured_count;
    reg [WORD_W-1:0] target_count;
    reg [WORD_W-1:0] countdown;
    reg sample_valid;

    wire [WORD_W-1:0] current_mask = ONE << bit_pos;
    wire [WORD_W-1:0] decided_code =
        (measured_count > target_count)
        ? (trial_code & ~current_mask) : trial_code;
    wire [WORD_W-1:0] next_trial =
        decided_code | (current_mask >> ONE);

    initial begin
        trial_code = ZERO;
        band_code = ZERO;
        outstanding = 1'b0;
        window = 1'b0;
        bit_pos = ZERO;
        measured_count = ZERO;
        target_count = ZERO;
        countdown = ZERO;
        sample_valid = 1'b0;
    end

    // Each SAR bit takes one measurement tick and one decision tick.
    // The deadline counts enabled calibration ticks; i_ce low freezes all state.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            trial_code <= ZERO;
            band_code <= ZERO;
            outstanding <= 1'b0;
            window <= 1'b0;
            bit_pos <= ZERO;
            measured_count <= ZERO;
            target_count <= ZERO;
            countdown <= ZERO;
            sample_valid <= 1'b0;
        end else if (i_ce) begin
            if (scope_r)
                window <= 1'b0;
            else if (scope_q)
                window <= 1'b1;

            if (!outstanding) begin
                if (window && !scope_r && cal_request) begin
                    outstanding <= 1'b1;
                    target_count <= reference_count;
                    trial_code <= FIRST_TRIAL;
                    bit_pos <= LAST_BIT;
                    measured_count <= ZERO;
                    countdown <= CAL_CYCLES;
                    sample_valid <= 1'b0;
                end
            end else begin
                countdown <= countdown - ONE;
                if (!sample_valid) begin
                    measured_count <= dco_count;
                    sample_valid <= 1'b1;
                end else begin
                    sample_valid <= 1'b0;
                    if (bit_pos == ZERO) begin
                        trial_code <= decided_code;
                        band_code <= decided_code;
                        outstanding <= 1'b0;
                    end else begin
                        trial_code <= next_trial;
                        bit_pos <= bit_pos - ONE;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (!window || !outstanding || (countdown != ZERO));
endmodule

module retirement_batch_fifo #(
    parameter [31:0] DEPTH = 32'd16,
    parameter integer WORD_W = 32'd32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_word_valid,
    output wire                  o_word_ready,
    input  wire [WORD_W-1:0]     i_word,
    input  wire                  i_commit_valid,
    output wire                  o_commit_ready,
    input  wire                  i_trap,
    output wire                  o_retire_fire,
    output wire [WORD_W-1:0]     o_retire_word,
    output wire                  o_commit_done
);
    // DEPTH is a power of two. Service cycles are cycles with i_ce high.
    localparam integer ADDR_W = $clog2(DEPTH);
    localparam [31:0] PTR_MOD = DEPTH + DEPTH;
    localparam [31:0] PTR_LAST = PTR_MOD - 32'd1;

    typedef enum logic [1:0] {
        FILL     = 2'd0,
        DRAIN    = 2'd1,
        COMPLETE = 2'd2
    } state_t;

    state_t state;
    // Address plus wrap bit, carried in the requested 32-bit registers.
    // Bits above ADDR_W remain zero.
    reg [31:0] wr_ptr;
    reg [31:0] rd_ptr;
    reg [31:0] deadline;
    reg [WORD_W-1:0] storage [0:DEPTH-1];
    reg before_trap;
    reg pv;

    initial begin
        state = FILL;
        wr_ptr = 32'd0;
        rd_ptr = 32'd0;
        deadline = 32'd0;
        before_trap = 1'b1;
        pv = 1'b0;
        for (integer n = 32'd0; n < DEPTH; n = n + 32'd1)
            storage[n] = {WORD_W{1'b0}};
    end

    wire empty = (wr_ptr == rd_ptr);
    wire full = (wr_ptr[ADDR_W-1:0] == rd_ptr[ADDR_W-1:0]) &&
                (wr_ptr[ADDR_W] != rd_ptr[ADDR_W]);
    wire [31:0] wr_next = (wr_ptr == PTR_LAST) ? 32'd0 :
                                                        wr_ptr + 32'd1;
    wire [31:0] rd_next = (rd_ptr == PTR_LAST) ? 32'd0 :
                                                        rd_ptr + 32'd1;
    // Combinational pointer distance, not an occupancy register.
    wire [31:0] used_words = (wr_ptr >= rd_ptr) ?
                            (wr_ptr - rd_ptr) :
                            (PTR_MOD - (rd_ptr - wr_ptr));

    assign o_commit_ready = i_ce && (state == FILL);
    // Sealing a batch takes priority over accepting another word.
    assign o_word_ready = i_ce && (state == FILL) &&
                          !full && !i_commit_valid;
    // The retirement port is an always-accepting execution sink.
    assign o_retire_fire = i_ce && (state == DRAIN) && !empty;
    assign o_retire_word = storage[rd_ptr[ADDR_W-1:0]];
    assign o_commit_done = (state == COMPLETE);

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (i_trap)
                before_trap <= 1'b0;

            case (state)
                FILL: begin
                    if (i_commit_valid && o_commit_ready) begin
                        if (empty) begin
                            state <= COMPLETE;
                            deadline <= 32'd0;
                        end else begin
                            state <= DRAIN;
                            deadline <= DEPTH;
                        end
                    end else if (i_word_valid && o_word_ready) begin
                        storage[wr_ptr[ADDR_W-1:0]] <= i_word;
                        wr_ptr <= wr_next;
                    end
                end

                DRAIN: begin
                    if (empty) begin
                        state <= COMPLETE;
                        deadline <= 32'd0;
                    end else begin
                        rd_ptr <= rd_next;
                        if (rd_next == wr_ptr) begin
                            state <= COMPLETE;
                            deadline <= 32'd0;
                        end else if (deadline != 32'd0) begin
                            deadline <= deadline - 32'd1;
                        end
                    end
                end

                COMPLETE: begin
                    state <= FILL;
                end
            endcase
        end
    end

    // If the previous service cycle consumed the final budget tick,
    // its accepted commit request must now be complete, not outstanding.
    always @(posedge clk)
        if (pv && before_trap &&
            $past(i_ce && (state == DRAIN) && (deadline == 32'd1)))
            assert (state == COMPLETE);
endmodule

module serial_completion_broadcast #(
    parameter integer DATA_WIDTH = 64,
    parameter integer TAG_WIDTH = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  completion_valid,
    input  wire [TAG_WIDTH-1:0]   completion_tag,
    input  wire [DATA_WIDTH-1:0]  completion_value,
    output wire                  completion_ready,
    output wire                  bus_valid,
    output reg  [TAG_WIDTH-1:0]   bus_tag,
    output reg  [DATA_WIDTH-1:0]  bus_value
);
    typedef enum logic [1:0] {
        IDLE      = 2'b00,
        QUEUED    = 2'b01,
        BROADCAST = 2'b10
    } state_t;

    state_t state;
    reg armed;
    reg [TAG_WIDTH-1:0] pending_tag;
    reg [DATA_WIDTH-1:0] pending_value;

    // Historical record of the earlier accepted completion.
    reg [TAG_WIDTH-1:0] prior_complete_tag;
    reg [DATA_WIDTH-1:0] prior_complete_value;

    assign completion_ready = (state == IDLE);
    assign bus_valid = (state == BROADCAST);

    initial begin
        state = IDLE;
        armed = 1'b0;
        pending_tag = {TAG_WIDTH{1'b0}};
        pending_value = {DATA_WIDTH{1'b0}};
        prior_complete_tag = {TAG_WIDTH{1'b0}};
        prior_complete_value = {DATA_WIDTH{1'b0}};
        bus_tag = {TAG_WIDTH{1'b0}};
        bus_value = {DATA_WIDTH{1'b0}};
    end

    // A single holding slot decouples completion capture from bus broadcast.
    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                IDLE: begin
                    if (completion_valid) begin
                        pending_tag <= completion_tag;
                        pending_value <= completion_value;
                        prior_complete_tag <= completion_tag;
                        prior_complete_value <= completion_value;
                        // Q: the first accepted completion permanently arms checking.
                        armed <= 1'b1;
                        state <= QUEUED;
                    end
                end
                QUEUED: begin
                    bus_tag <= pending_tag;
                    bus_value <= pending_value;
                    state <= BROADCAST;
                end
                BROADCAST: begin
                    state <= IDLE;
                end
            endcase
        end
    end

    // After Q, each observed broadcast must match an earlier completion.
    always @(posedge clk) begin
        if (armed && (state == BROADCAST)) begin
            assert (bus_tag == prior_complete_tag);
            assert (bus_value == prior_complete_value);
        end
    end
endmodule

module ethertype_queue_dispatch #(
    parameter integer DATA_W = 8,
    parameter integer ENTRIES = 16,
    parameter [DATA_W-1:0] DEFAULT_QUEUE = 8'd0
) (
    input  wire                  clk,
    input  wire                  i_valid,
    output reg                   i_ready,
    input  wire [DATA_W-1:0]     i_cmd,
    input  wire [DATA_W-1:0]     i_data,
    input  wire [DATA_W-1:0]     i_index,
    input  wire [DATA_W-1:0]     i_type_hi,
    input  wire [DATA_W-1:0]     i_type_lo,
    output wire                  o_valid,
    input  wire                  o_ready,
    output wire [DATA_W-1:0]     o_data,
    output wire [DATA_W-1:0]     o_queue
);
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] TABLE_LIMIT = ENTRIES;
    localparam [DATA_W-1:0] TYPE_HI_OFFSET = 8'd12;
    localparam [DATA_W-1:0] HEADER_LAST = 8'd13;

    localparam [DATA_W-1:0] CMD_PROGRAM = 8'h01;
    localparam [DATA_W-1:0] CMD_OPEN    = 8'h02;
    localparam [DATA_W-1:0] CMD_HEADER  = 8'h03;
    localparam [DATA_W-1:0] CMD_START   = 8'h04;
    localparam [DATA_W-1:0] CMD_CLOSE   = 8'h05;

    typedef enum logic [2:0] {
        IDLE     = 3'd0,
        HEADER   = 3'd1,
        ARMED    = 3'd2,
        STARTED  = 3'd3,
        FINISHED = 3'd4
    } state_t;
    state_t state;

    reg window;
    reg arm_seen;
    reg start_seen;
    reg [DATA_W-1:0] header_count;
    reg [DATA_W-1:0] type_hi;
    reg [DATA_W-1:0] type_lo;
    reg [DATA_W-1:0] frame_token;
    reg [DATA_W-1:0] selected_queue;

    reg [DATA_W-1:0] table_hi [0:ENTRIES-1];
    reg [DATA_W-1:0] table_lo [0:ENTRIES-1];
    reg [DATA_W-1:0] table_queue [0:ENTRIES-1];
    reg [ENTRIES-1:0] table_valid;
    reg [DATA_W-1:0] match_queue;

    initial begin
        state = IDLE;
        window = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        header_count = ZERO;
        type_hi = ZERO;
        type_lo = ZERO;
        frame_token = ZERO;
        selected_queue = DEFAULT_QUEUE;
        table_valid = {ENTRIES{1'b0}};
    end

    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : initialize_table
            initial begin
                table_hi[g] = ZERO;
                table_lo[g] = ZERO;
                table_queue[g] = DEFAULT_QUEUE;
            end
        end
    endgenerate

    // Highest-index matching entry wins; unknown protocols use the default queue.
    integer scan;
    always @(*) begin
        match_queue = DEFAULT_QUEUE;
        for (scan = 0; scan < ENTRIES; scan = scan + 1) begin
            if (table_valid[scan] &&
                table_hi[scan] == type_hi && table_lo[scan] == type_lo)
                match_queue = table_queue[scan];
        end
    end

    always @(*) begin
        i_ready = 1'b0;
        case (state)
            IDLE: i_ready = (i_cmd == CMD_OPEN) ||
                            ((i_cmd == CMD_PROGRAM) && (i_index < TABLE_LIMIT));
            HEADER: i_ready = (i_cmd == CMD_HEADER);
            ARMED: i_ready = (i_cmd == CMD_START);
            FINISHED: i_ready = (i_cmd == CMD_CLOSE);
            default: i_ready = 1'b0;
        endcase
    end

    assign o_valid = (state == STARTED);
    assign o_data = frame_token;
    assign o_queue = selected_queue;

    // Every update requires an input or output handshake. Holding i_valid
    // and o_ready low freezes every state register, including the table.
    always @(posedge clk) begin
        if (i_valid && i_ready) begin
            case (state)
                IDLE: begin
                    if (i_cmd == CMD_PROGRAM) begin
                        table_hi[i_index] <= i_type_hi;
                        table_lo[i_index] <= i_type_lo;
                        table_queue[i_index] <= i_data;
                        table_valid[i_index] <= 1'b1;
                    end else if (i_cmd == CMD_OPEN) begin
                        // Q opens a fresh frame-processing scope.
                        window <= 1'b1;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        header_count <= ZERO;
                        state <= HEADER;
                    end
                end
                HEADER: begin
                    // The EtherType is extracted as two eight-bit header words.
                    if (header_count == TYPE_HI_OFFSET)
                        type_hi <= i_data;
                    if (header_count == HEADER_LAST) begin
                        type_lo <= i_data;
                        arm_seen <= 1'b1;
                        state <= ARMED;
                    end else begin
                        header_count <= header_count + ONE;
                    end
                end
                ARMED: begin
                    // Start transport to the programmed protocol queue.
                    selected_queue <= match_queue;
                    frame_token <= i_data;
                    start_seen <= 1'b1;
                    state <= STARTED;
                end
                FINISHED: begin
                    // R closes the scope; another OPEN can start a new frame.
                    window <= 1'b0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    header_count <= ZERO;
                    state <= IDLE;
                end
                default: begin end
            endcase
        end

        // Queue back-pressure holds valid, token and queue selection steady.
        if (o_valid && o_ready)
            state <= FINISHED;
    end

    // Within the scope: start requires an earlier arm, and finish also
    // requires an earlier start.
    always @(posedge clk)
        if (window && ((state == STARTED) || (state == FINISHED)))
            assert (arm_seen && ((state != FINISHED) || start_seen));
endmodule

module adaptive_clock_stretcher #(
    parameter integer WORD_W = 128,
    parameter integer RECOVERY_CYCLES = 4,
    parameter integer MAX_EXTRA_STEP = 4,
    parameter logic [WORD_W-1:0] NORMAL_PERIOD = WORD_W'(8)
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_cmd_valid,
    output wire                  o_cmd_ready,
    input  wire [WORD_W-1:0]     i_cmd,
    output wire [WORD_W-1:0]     o_period,
    output wire                  o_stretch_active
);
    localparam integer COUNT_W = (RECOVERY_CYCLES < 2) ? 1 : $clog2(RECOVERY_CYCLES + 1);
    localparam integer STEP_W = (MAX_EXTRA_STEP < 2) ? 1 : $clog2(MAX_EXTRA_STEP + 1);
    localparam integer AMOUNT_W = $clog2(MAX_EXTRA_STEP * RECOVERY_CYCLES + 1);

    localparam logic [COUNT_W-1:0] RECOVERY_LOAD = COUNT_W'(RECOVERY_CYCLES);
    localparam logic [COUNT_W-1:0] COUNT_ONE = COUNT_W'(1);
    localparam logic [STEP_W-1:0] STEP_LIMIT = STEP_W'(MAX_EXTRA_STEP);
    localparam logic [STEP_W-1:0] STEP_ONE = STEP_W'(1);
    localparam logic [AMOUNT_W-1:0] MAX_AMOUNT = AMOUNT_W'(MAX_EXTRA_STEP * RECOVERY_CYCLES);

    typedef enum logic [0:0] { NORMAL, RECOVERING } state_t;
    state_t state;
    reg stretch_active;
    reg [COUNT_W-1:0] recovery_count;
    reg [AMOUNT_W-1:0] stretch_amount;
    reg [WORD_W-1:0] history_word;

    wire [STEP_W-1:0] requested_step;
    wire [AMOUNT_W-1:0] starting_amount;

    assign requested_step =
        (i_cmd[STEP_W-1:0] == {STEP_W{1'b0}}) ? STEP_ONE :
        (i_cmd[STEP_W-1:0] > STEP_LIMIT) ? STEP_LIMIT :
        i_cmd[STEP_W-1:0];
    assign starting_amount = AMOUNT_W'(requested_step) * AMOUNT_W'(RECOVERY_LOAD);

    // Each accepted command is a clock-boundary event. Its top bit reports
    // a droop, and its low field requests the recovery taper step.
    // A paused scheduler applies back-pressure rather than consuming commands.
    assign o_cmd_ready = i_ce;
    assign o_stretch_active = stretch_active;

    // Duration supplied to the clock divider for the next clock cycle.
    assign o_period = NORMAL_PERIOD + {{(WORD_W-AMOUNT_W){1'b0}}, stretch_amount};

    initial begin
        state = NORMAL;
        stretch_active = 1'b0;
        recovery_count = {COUNT_W{1'b0}};
        stretch_amount = {AMOUNT_W{1'b0}};
        history_word = {WORD_W{1'b0}};
    end

    always @(posedge clk) begin
        if (i_cmd_valid && o_cmd_ready) begin
            if (i_cmd[WORD_W-1]) begin
                // Capture the accepted detector record, normalizing its step.
                history_word <= {1'b1, i_cmd[WORD_W-2:STEP_W], requested_step};
                recovery_count <= RECOVERY_LOAD;
                stretch_amount <= starting_amount;
                stretch_active <= 1'b1;
                state <= RECOVERING;
            end else begin
                case (state)
                    NORMAL: begin
                        // Ordinary boundaries leave the normal period unchanged.
                    end
                    RECOVERING: begin
                        if (recovery_count > COUNT_ONE) begin
                            recovery_count <= recovery_count - COUNT_ONE;
                            stretch_amount <= stretch_amount - AMOUNT_W'(history_word[STEP_W-1:0]);
                            stretch_active <= 1'b1;
                            state <= RECOVERING;
                        end else begin
                            recovery_count <= {COUNT_W{1'b0}};
                            stretch_amount <= {AMOUNT_W{1'b0}};
                            stretch_active <= 1'b0;
                            state <= NORMAL;
                        end
                    end
                endcase
            end
        end
    end

    // Every observed stretch must have an earlier accepted droop record.
    always @(posedge clk)
        if (stretch_active)
            assert (history_word[WORD_W-1]);

    // An active stretch must still provide at least the recorded taper step.
    always @(posedge clk)
        if (stretch_active)
            assert (stretch_amount >= history_word[STEP_W-1:0]);
endmodule

module loop_trip_predictor #(
    parameter integer ENTRIES = 32,
    parameter integer WORD_W = 64,
    parameter integer INDEX_W = (ENTRIES > 1) ? $clog2(ENTRIES) : 1
) (
    input  wire clk,
    input  wire i_branch_valid,
    output wire o_branch_ready,
    input  wire [INDEX_W-1:0] i_index,
    input  wire [WORD_W-1:0] i_branch_tag,
    input  wire i_backedge_taken,
    input  wire i_monitor_begin,
    input  wire i_monitor_end,

    output reg  o_pred_valid,
    input  wire i_pred_ready,
    output reg  [WORD_W-1:0] o_pred_tag,
    output reg  o_pred_confident,
    output reg  o_pred_exit,
    output reg  [WORD_W-1:0] resident_count
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] WORD_MAX = {WORD_W{1'b1}};
    localparam [WORD_W-1:0] CONF_THRESHOLD = 64'd3;
    localparam [WORD_W-1:0] TABLE_CAPACITY = ENTRIES;

    reg [ENTRIES-1:0] entry_valid;
    reg [WORD_W-1:0] entry_tag [0:ENTRIES-1];
    reg [WORD_W-1:0] learned_trip [0:ENTRIES-1];
    reg [WORD_W-1:0] current_iter [0:ENTRIES-1];
    reg [WORD_W-1:0] confidence [0:ENTRIES-1];
    reg monitor_window;

    // A one-entry prediction buffer propagates downstream back-pressure.
    assign o_branch_ready = (!o_pred_valid || i_pred_ready)
                          && (i_index < ENTRIES);
    wire accept_branch = i_branch_valid && o_branch_ready;
    wire lookup_hit = entry_valid[i_index]
                   && (entry_tag[i_index] == i_branch_tag);
    wire prediction_known = lookup_hit
                          && (confidence[i_index] >= CONF_THRESHOLD)
                          && (learned_trip[i_index] != ZERO);
    wire [WORD_W-1:0] observed_trip =
        (current_iter[i_index] == WORD_MAX)
        ? WORD_MAX : current_iter[i_index] + ONE;

    // Combinational population of the resident-entry bitmap.
    wire [WORD_W-1:0] tally_chain [0:ENTRIES];
    wire [WORD_W-1:0] resident_tally;
    assign tally_chain[0] = ZERO;
    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : make_tally
            assign tally_chain[g+1] = tally_chain[g]
                + {{(WORD_W-1){1'b0}}, entry_valid[g]};
        end
    endgenerate
    assign resident_tally = tally_chain[ENTRIES];

    integer init_i;
    initial begin
        entry_valid = {ENTRIES{1'b0}};
        resident_count = ZERO;
        monitor_window = 1'b0;
        o_pred_valid = 1'b0;
        o_pred_tag = ZERO;
        o_pred_confident = 1'b0;
        o_pred_exit = 1'b0;
        for (init_i = 0; init_i < ENTRIES; init_i = init_i + 1) begin
            entry_tag[init_i] = ZERO;
            learned_trip[init_i] = ZERO;
            current_iter[init_i] = ZERO;
            confidence[init_i] = ZERO;
        end
    end

    always @(posedge clk) begin
        if (o_pred_valid && i_pred_ready)
            o_pred_valid <= 1'b0;

        if (accept_branch) begin
            // Predictions use the history preceding this observation.
            o_pred_valid <= 1'b1;
            o_pred_tag <= i_branch_tag;
            o_pred_confident <= prediction_known;
            o_pred_exit <= prediction_known
                        && (current_iter[i_index]
                            == learned_trip[i_index] - ONE);

            // Q opens the monitoring interval; R closes it.
            if (i_monitor_end)
                monitor_window <= 1'b0;
            else if (i_monitor_begin)
                monitor_window <= 1'b1;

            if (!lookup_hit) begin
                // A tag collision replaces a resident entry, not its occupancy.
                if (!entry_valid[i_index])
                    resident_count <= resident_count + ONE;
                entry_valid[i_index] <= 1'b1;
                entry_tag[i_index] <= i_branch_tag;
                confidence[i_index] <= ZERO;
                if (i_backedge_taken) begin
                    current_iter[i_index] <= ONE;
                    learned_trip[i_index] <= ZERO;
                end else begin
                    current_iter[i_index] <= ZERO;
                    learned_trip[i_index] <= ONE;
                end
            end else if (i_backedge_taken) begin
                current_iter[i_index] <= observed_trip;
            end else begin
                // An exiting branch completes one measured loop execution.
                current_iter[i_index] <= ZERO;
                learned_trip[i_index] <= observed_trip;
                if ((learned_trip[i_index] == observed_trip)
                    && (learned_trip[i_index] != ZERO)) begin
                    if (confidence[i_index] != WORD_MAX)
                        confidence[i_index] <= confidence[i_index] + ONE;
                end else begin
                    confidence[i_index] <= ZERO;
                end
            end
        end
    end

    assert property (!monitor_window
                     || (resident_count <= TABLE_CAPACITY));
endmodule

module boot_reset_qualifier #(
    parameter [31:0] RESET_CYCLES = 32'd32
) (
    input  wire        clk,
    input  wire        cmd_valid,
    input  wire [31:0] cmd_word,
    output wire        cmd_ready,
    output reg         por_reset,
    output reg  [31:0] stable_cycles
);
    localparam [31:0] CMD_BEGIN    = 32'd0;
    localparam [31:0] CMD_STABLE   = 32'd1;
    localparam [31:0] CMD_UNSTABLE = 32'd2;
    localparam [31:0] CMD_END      = 32'd3;

    reg scope_window;
    reg past_valid;

    initial begin
        stable_cycles = 32'd0;
        por_reset = (RESET_CYCLES != 32'd0);
        scope_window = 1'b0;
        past_valid = 1'b0;
    end

    // Stable commands represent enabled observations of the monitored clock.
    // Back-pressure prevents ending qualification before reset is released.
    assign cmd_ready =
        (!scope_window && (cmd_word == CMD_BEGIN)) ||
        (scope_window &&
            ((cmd_word == CMD_STABLE) ||
             (cmd_word == CMD_UNSTABLE) ||
             ((cmd_word == CMD_END) && !por_reset)));

    wire transfer = cmd_valid && cmd_ready;

    always @(posedge clk) begin
        if (transfer) begin
            past_valid <= 1'b1;
            case (cmd_word)
                CMD_BEGIN: begin
                    // Q opens a new qualification window.
                    scope_window <= 1'b1;
                    stable_cycles <= 32'd0;
                    por_reset <= (RESET_CYCLES != 32'd0);
                end
                CMD_STABLE: begin
                    if (stable_cycles < RESET_CYCLES) begin
                        stable_cycles <= stable_cycles + 32'd1;
                        por_reset <=
                            ((stable_cycles + 32'd1) < RESET_CYCLES);
                    end else begin
                        por_reset <= 1'b0;
                    end
                end
                CMD_UNSTABLE: begin
                    stable_cycles <= 32'd0;
                    por_reset <= (RESET_CYCLES != 32'd0);
                end
                CMD_END: begin
                    // R closes the window; another BEGIN can reopen it.
                    scope_window <= 1'b0;
                end
                default: begin end
            endcase
        end
    end

    always @(posedge clk) begin
        if (past_valid && scope_window && $stable(stable_cycles))
            assert ($stable(por_reset));
    end
endmodule

module dram_read_fp_classify #(
    parameter integer WORD_BITS = 32,
    parameter integer EXP_BITS = 8
) (
    input  wire                 clk,
    input  wire                 i_valid,
    output wire                 i_ready,
    input  wire [WORD_BITS-1:0]  i_read_word,
    input  wire                 i_begin_window,
    input  wire                 i_end_window,
    output reg                  o_valid,
    input  wire                 o_ready,
    output reg  [WORD_BITS-1:0]  o_category
);
    localparam integer FRAC_BITS = WORD_BITS - EXP_BITS - 1;

    // One outstanding read sample, with classification and publication stages.
    reg                         sample_valid;
    reg [WORD_BITS-1:0]          sample_word;
    reg [WORD_BITS-1:0]          sample_category;
    reg [WORD_BITS-1:0]          shadow_word;
    reg                         window_active;

    // Category pairs are positive/negative:
    // zero [1:0], subnormal [3:2], normal [5:4], infinity [7:6],
    // signaling NaN [9:8], quiet NaN [11:10]. Other bits are zero.
    function [WORD_BITS-1:0] classify_word;
        input [WORD_BITS-1:0] word;
        begin
            classify_word = {WORD_BITS{1'b0}};
            if (word[WORD_BITS-2:FRAC_BITS] == {EXP_BITS{1'b0}}) begin
                if (word[FRAC_BITS-1:0] == {FRAC_BITS{1'b0}})
                    classify_word[32'd0 + word[WORD_BITS-1]] = 1'b1;
                else
                    classify_word[32'd2 + word[WORD_BITS-1]] = 1'b1;
            end else if (&word[WORD_BITS-2:FRAC_BITS]) begin
                if (word[FRAC_BITS-1:0] == {FRAC_BITS{1'b0}})
                    classify_word[32'd6 + word[WORD_BITS-1]] = 1'b1;
                else if (word[FRAC_BITS-1])
                    classify_word[32'd10 + word[WORD_BITS-1]] = 1'b1;
                else
                    classify_word[32'd8 + word[WORD_BITS-1]] = 1'b1;
            end else begin
                classify_word[32'd4 + word[WORD_BITS-1]] = 1'b1;
            end
        end
    endfunction

    wire [WORD_BITS-1:0] sample_expected_category;
    wire [WORD_BITS-1:0] shadow_expected_category;
    assign sample_expected_category = classify_word(sample_word);
    assign shadow_expected_category = classify_word(shadow_word);

    assign i_ready = !sample_valid && !o_valid;
    wire accept_sample = i_valid && i_ready;
    wire output_space = !o_valid || o_ready;
    wire advance_sample = sample_valid && output_space;

    // No external request and no downstream readiness freezes every register.
    wire run = i_valid || o_ready;

    initial begin
        sample_valid = 1'b0;
        sample_word = {WORD_BITS{1'b0}};
        sample_category = {WORD_BITS{1'b0}};
        shadow_word = {WORD_BITS{1'b0}};
        o_valid = 1'b0;
        o_category = {WORD_BITS{1'b0}};
        window_active = 1'b0;
    end

    always @(posedge clk) begin
        if (run) begin
            if (accept_sample) begin
                sample_valid <= 1'b1;
                sample_word <= i_read_word;
                sample_category <= classify_word(i_read_word);
            end else if (advance_sample) begin
                sample_valid <= 1'b0;
            end

            if (output_space) begin
                o_valid <= sample_valid;
                if (sample_valid) begin
                    o_category <= sample_category;
                    // Preserve the earlier accepted word as provenance.
                    shadow_word <= sample_word;
                end
            end

            // Q and R are accepted begin-window and end-window markers.
            // An accepted end marker has priority if both markers are present.
            if (accept_sample) begin
                if (i_end_window)
                    window_active <= 1'b0;
                else if (i_begin_window)
                    window_active <= 1'b1;
            end
        end
    end

    // A reported signaling NaN must have an earlier accepted signaling-NaN
    // encoding, including the reported sign, throughout the latched window.
    always @(posedge clk)
        if (window_active && o_valid && (o_category[8] || o_category[9]))
            assert ((&shadow_word[WORD_BITS-2:FRAC_BITS]) &&
                    (shadow_word[FRAC_BITS-1:0] != {FRAC_BITS{1'b0}}) &&
                    !shadow_word[FRAC_BITS-1] &&
                    (o_category[9] == shadow_word[WORD_BITS-1]));
endmodule

module placement_cost_ram #(
    parameter integer DEPTH = 32,
    parameter integer ADDR_WIDTH = (DEPTH > 1) ? $clog2(DEPTH) : 1
) (
    input wire clk,
    input wire i_ce,
    input wire i_clear,
    input wire i_write,
    input wire [ADDR_WIDTH-1:0] i_write_addr,
    input wire [15:0] i_write_cost,
    input wire [ADDR_WIDTH-1:0] i_read_addr,
    output reg [15:0] selected_cost
);
    localparam [ADDR_WIDTH:0] DEPTH_LIMIT = DEPTH;

    reg [15:0] data_mem [0:DEPTH-1];
    reg [DEPTH-1:0] valid_bits;
    reg [ADDR_WIDTH-1:0] read_addr;
    reg [15:0] revision;
    reg past_valid;
    integer k;

    wire write_ok = i_write &&
                    ({1'b0, i_write_addr} < DEPTH_LIMIT);
    wire [ADDR_WIDTH-1:0] next_read_addr =
        ({1'b0, i_read_addr} < DEPTH_LIMIT) ? i_read_addr : read_addr;

    initial begin
        valid_bits = {DEPTH{1'b0}};
        read_addr = {ADDR_WIDTH{1'b0}};
        revision = 16'd0;
        selected_cost = 16'd0;
        past_valid = 1'b0;
        for (k = 0; k < DEPTH; k = k + 1)
            data_mem[k] = 16'd0;
    end

    // Registered read port with write-through forwarding. Flash clear
    // invalidates every entry without modifying the stored cost words.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            read_addr <= next_read_addr;

            if (i_clear) begin
                valid_bits <= {DEPTH{1'b0}};
                revision <= revision + 16'd1;
                selected_cost <= 16'd0;
            end else begin
                if (write_ok) begin
                    data_mem[i_write_addr] <= i_write_cost;
                    valid_bits[i_write_addr] <= 1'b1;
                    revision <= revision + 16'd1;
                end

                if (write_ok && (i_write_addr == next_read_addr))
                    selected_cost <= i_write_cost;
                else if (valid_bits[next_read_addr])
                    selected_cost <= data_mem[next_read_addr];
                else
                    selected_cost <= 16'd0;
            end
        end
    end

    // An unchanged table revision and selected address imply an
    // unchanged registered cost.
    always @(posedge clk) begin
        if (past_valid && $stable({revision, read_addr}))
            assert ($stable(selected_cost));
    end
endmodule

module half_integer_chain_divider #(
    parameter logic [63:0] DIV_INTEGER = 64'd4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire source_clk,
    input  wire q_event,
    output reg  arm_pulse,
    output reg  start_pulse,
    output reg  finish_pulse,
    output wire divided_clk
);
    // clk samples source_clk; sample every source transition for the
    // nominal divide ratio. DIV_INTEGER must be at least 64'd2.
    // Successive finish pulses alternate source-edge polarity and are
    // DIV_INTEGER + one half source periods apart.
    typedef enum logic [1:0] {
        WAIT_ARM = 2'b00,
        ARMED    = 2'b01,
        RUNNING  = 2'b10
    } phase_t;

    phase_t phase;
    reg [63:0] count;
    reg source_prev;
    reg edge_sel;       // 1: select rising edges; 0: select falling edges
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    wire source_rise = source_clk && !source_prev;
    wire source_fall = !source_clk && source_prev;
    wire selected_edge = (edge_sel && source_rise) ||
                         (!edge_sel && source_fall);

    assign divided_clk = finish_pulse;

    initial begin
        phase        = WAIT_ARM;
        count        = 64'd0;
        source_prev  = 1'b0;
        edge_sel     = 1'b1;
        arm_seen     = 1'b0;
        start_seen   = 1'b0;
        scope_armed  = 1'b0;
        arm_pulse    = 1'b0;
        start_pulse  = 1'b0;
        finish_pulse = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            source_prev <= source_clk;
            // Q is an accepted q_event on an enabled sampling cycle.
            if (q_event)
                scope_armed <= 1'b1;

            arm_pulse    <= 1'b0;
            start_pulse  <= 1'b0;
            finish_pulse <= 1'b0;

            // Retire the previous interval's history with its finish pulse.
            if (phase == WAIT_ARM) begin
                arm_seen   <= 1'b0;
                start_seen <= 1'b0;
            end

            if (selected_edge) begin
                case (phase)
                    WAIT_ARM: begin
                        count      <= 64'd1;
                        phase      <= ARMED;
                        arm_seen   <= 1'b1;
                        start_seen <= 1'b0;
                        arm_pulse  <= 1'b1;
                    end
                    ARMED: begin
                        count       <= count + 64'd1;
                        phase       <= RUNNING;
                        start_seen  <= 1'b1;
                        start_pulse <= 1'b1;
                    end
                    RUNNING: begin
                        if (count == DIV_INTEGER) begin
                            count        <= 64'd0;
                            phase        <= WAIT_ARM;
                            edge_sel     <= !edge_sel;
                            finish_pulse <= 1'b1;
                        end else begin
                            count <= count + 64'd1;
                        end
                    end
                    default: begin end
                endcase
            end
        end
    end

    // After Q: start requires an earlier arm, and finish requires both
    // an earlier arm and an earlier start in the current interval.
    always @(*) begin
        if (scope_armed)
            assert ((!start_pulse || arm_seen) &&
                    (!finish_pulse || (arm_seen && start_seen)));
    end
endmodule

module scoped_mlt3_encoder #(
    parameter DATA_W = 64,
    parameter COUNT_W = 64
) (
    input  wire                     clk,
    input  wire                     i_ce,
    input  wire                     i_scope_begin,
    input  wire                     i_scope_end,
    input  wire                     i_request,
    input  wire [DATA_W-1:0]        i_word,
    output wire signed [DATA_W-1:0] o_line
);
    localparam [COUNT_W-1:0] PAYLOAD_CYCLES = COUNT_W'(DATA_W);
    localparam [COUNT_W-1:0] FRAME_BUDGET = PAYLOAD_CYCLES + COUNT_W'(4);

    reg [DATA_W-1:0] payload;
    reg [COUNT_W-1:0] remaining;
    reg [COUNT_W-1:0] deadline;
    reg [1:0] level_phase;
    reg busy;
    reg scope_window;

    initial begin
        payload = {DATA_W{1'b0}};
        remaining = COUNT_W'(0);
        deadline = COUNT_W'(0);
        level_phase = 2'd0;
        busy = 1'b0;
        scope_window = 1'b0;
    end

    // The cyclic MLT-3 sequence is 0, +1, 0, -1.
    // Only an encoded one advances the two-bit sequence state.
    assign o_line = (level_phase == 2'd1) ? DATA_W'(1) :
                    (level_phase == 2'd3) ? {DATA_W{1'b1}} :
                                            {DATA_W{1'b0}};

    // Number of postamble ones needed to restore phase zero.
    wire [COUNT_W-1:0] tail_cycles;
    assign tail_cycles = (level_phase == 2'd0) ? COUNT_W'(0) :
                         (level_phase == 2'd1) ? COUNT_W'(3) :
                         (level_phase == 2'd2) ? COUNT_W'(2) :
                                                COUNT_W'(1);

    // All timing, including the deadline, counts enabled clock edges.
    // A frame has DATA_W payload cycles, at most three postamble
    // cycles, and one final completion cycle.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_scope_end)
                scope_window <= 1'b0;
            else if (i_scope_begin)
                scope_window <= 1'b1;

            if (!busy) begin
                if (i_request) begin
                    payload <= i_word;
                    remaining <= PAYLOAD_CYCLES;
                    deadline <= FRAME_BUDGET;
                    busy <= 1'b1;
                end
            end else begin
                deadline <= deadline - COUNT_W'(1);
                if (remaining != COUNT_W'(0)) begin
                    if (payload[0])
                        level_phase <= level_phase + 2'd1;
                    payload <= {1'b0, payload[DATA_W-1:1]};
                    remaining <= remaining - COUNT_W'(1);
                end else if (tail_cycles != COUNT_W'(0)) begin
                    // Postamble bits are ones, so each advances MLT-3.
                    level_phase <= level_phase + 2'd1;
                end else begin
                    busy <= 1'b0;
                end
            end
        end
    end

    // After scope begin, until scope end, an outstanding frame
    // must never exhaust its completion deadline.
    always @(posedge clk)
        assert (!scope_window || !busy || deadline != COUNT_W'(0));
endmodule

module sampled_i2c_event_queue #(
    parameter integer WORD_BITS = 64,
    parameter integer DEPTH = 2
) (
    input  wire clk,
    input  wire i_ce,
    input  wire sample_scl,
    input  wire sample_sda,
    output wire sample_ready,
    output wire start_event,
    output wire repeated_start_event,
    output wire stop_event,
    output reg  bus_busy,
    output wire [WORD_BITS-1:0] active_event,
    output wire [WORD_BITS-1:0] active_ticket
);
    localparam [WORD_BITS-1:0] ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] TWO = ONE + ONE;
    localparam [WORD_BITS-1:0] THREE = TWO + ONE;
    localparam [WORD_BITS-1:0] DEPTH_VALUE = DEPTH;
    localparam [WORD_BITS-1:0] MAX_TICKS =
        (DEPTH_VALUE > ONE) ? DEPTH_VALUE * TWO - ONE : TWO;

    reg prev_scl;
    reg prev_sda;
    reg window;
    reg pv;
    reg [WORD_BITS-1:0] count;
    reg [WORD_BITS-1:0] rd_ptr;
    reg [WORD_BITS-1:0] wr_ptr;
    reg [WORD_BITS-1:0] issued;
    reg [WORD_BITS-1:0] retired;
    reg [DEPTH-1:0] valid;

    // Event codes: ordinary START, repeated START, and STOP.
    reg [WORD_BITS-1:0] payload [0:DEPTH-1];
    reg [WORD_BITS-1:0] ticket [0:DEPTH-1];
    reg [WORD_BITS-1:0] remaining [0:DEPTH-1];
    reg [WORD_BITS-1:0] deadline [0:DEPTH-1];

    wire [WORD_BITS-1:0] distance [0:DEPTH-1];
    wire [WORD_BITS-1:0] service_need [0:DEPTH-1];
    wire [DEPTH-1:0] due_mask;
    wire [DEPTH-1:0] slot_relation;

    assign sample_ready = count < DEPTH_VALUE;
    assign start_event = sample_ready && prev_scl && sample_scl &&
                         prev_sda && !sample_sda;
    assign stop_event = sample_ready && prev_scl && sample_scl &&
                        !prev_sda && sample_sda;
    assign repeated_start_event = start_event && bus_busy;

    wire enqueue = start_event || stop_event;
    wire dequeue = (count != ZERO) && (remaining[rd_ptr] == ONE);
    wire [WORD_BITS-1:0] incoming_event =
        stop_event ? THREE : (bus_busy ? TWO : ONE);

    assign active_event = (count != ZERO) ? payload[rd_ptr] : ZERO;
    assign active_ticket = (count != ZERO) ? ticket[rd_ptr] : ZERO;

    initial begin
        prev_scl = 1'b1;
        prev_sda = 1'b1;
        bus_busy = 1'b0;
        window = 1'b0;
        pv = 1'b0;
        count = ZERO;
        rd_ptr = ZERO;
        wr_ptr = ZERO;
        issued = ZERO;
        retired = ZERO;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            // A full queue backpressures sampling, without overwriting events.
            if (sample_ready) begin
                prev_scl <= sample_scl;
                prev_sda <= sample_sda;
                if (start_event) begin
                    bus_busy <= 1'b1;
                    window <= 1'b1;
                end else if (stop_event) begin
                    bus_busy <= 1'b0;
                    window <= 1'b0;
                end
            end

            case ({enqueue, dequeue})
                2'b10: count <= count + ONE;
                2'b01: count <= count - ONE;
                default: count <= count;
            endcase

            if (enqueue) begin
                issued <= issued + ONE;
                wr_ptr <= (wr_ptr == DEPTH_VALUE - ONE) ? ZERO : wr_ptr + ONE;
            end
            if (dequeue) begin
                retired <= retired + ONE;
                rd_ptr <= (rd_ptr == DEPTH_VALUE - ONE) ? ZERO : rd_ptr + ONE;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : slots
            localparam [WORD_BITS-1:0] SLOT = g;

            initial begin
                valid[g] = 1'b0;
                payload[g] = ZERO;
                ticket[g] = ZERO;
                remaining[g] = ZERO;
                deadline[g] = ZERO;
            end

            assign distance[g] = (SLOT >= rd_ptr) ?
                SLOT - rd_ptr : SLOT + DEPTH_VALUE - rd_ptr;
            assign service_need[g] = remaining[rd_ptr] + TWO * distance[g];
            assign due_mask[g] = valid[g] && (deadline[g] == ONE);

            // These are same-cycle structural facts, not assertions.
            // Only the oldest entry works; every younger entry needs two ticks.
            assign slot_relation[g] =
                (valid[g] == (distance[g] < count)) &&
                (valid[g] ?
                    ((payload[g] == ONE || payload[g] == TWO || payload[g] == THREE) &&
                     (ticket[g] == retired + distance[g]) &&
                     (remaining[g] >= ONE) && (remaining[g] <= TWO) &&
                     ((distance[g] == ZERO) || (remaining[g] == TWO)) &&
                     (deadline[g] >= service_need[g]) &&
                     (deadline[g] <= MAX_TICKS)) :
                    ((payload[g] == ZERO) && (ticket[g] == ZERO) &&
                     (remaining[g] == ZERO) && (deadline[g] == ZERO)));

            always @(posedge clk) begin
                if (i_ce) begin
                    if (valid[g])
                        deadline[g] <= deadline[g] - ONE;

                    if ((count != ZERO) && (rd_ptr == SLOT) &&
                        (remaining[g] > ONE))
                        remaining[g] <= remaining[g] - ONE;

                    if (dequeue && (rd_ptr == SLOT)) begin
                        valid[g] <= 1'b0;
                        payload[g] <= ZERO;
                        ticket[g] <= ZERO;
                        remaining[g] <= ZERO;
                        deadline[g] <= ZERO;
                    end

                    if (enqueue && (wr_ptr == SLOT)) begin
                        valid[g] <= 1'b1;
                        payload[g] <= incoming_event;
                        ticket[g] <= issued;
                        remaining[g] <= TWO;
                        deadline[g] <= MAX_TICKS;
                    end
                end
            end
        end
    endgenerate

    // Within a START-to-STOP window, an outstanding request on its
    // previous enabled tick's last deadline count must now be complete.
    always @(posedge clk)
        if (pv && $past(window) && $past(i_ce))
            assert ((valid & $past(due_mask)) == {DEPTH{1'b0}});
endmodule

module deadline_grant_scheduler #(
    parameter integer REQUESTERS = 2,
    parameter integer WORD_W = 16,
    parameter integer INDEX_W = (REQUESTERS > 1) ? $clog2(REQUESTERS) : 1
) (
    input wire clk,
    input wire rst_n,
    input wire cmd_valid,
    output wire cmd_ready,
    input wire [REQUESTERS-1:0] cmd_pending,
    input wire [REQUESTERS*WORD_W-1:0] cmd_periods,
    input wire cmd_end_monitor,
    output reg grant_valid,
    input wire grant_ready,
    output reg [WORD_W-1:0] grant_requester,
    output reg [WORD_W-1:0] grant_deadline
);
    reg [REQUESTERS*WORD_W-1:0] deadline_words;
    reg [INDEX_W-1:0] earliest;
    reg before_end;
    reg past_valid;

    function automatic [INDEX_W-1:0] find_earliest(
        input [REQUESTERS*WORD_W-1:0] words
    );
        integer n;
        reg [WORD_W-1:0] best;
        reg [INDEX_W-1:0] index;
        begin
            best = words[0 +: WORD_W];
            index = {INDEX_W{1'b0}};
            for (n = 1; n < REQUESTERS; n = n + 1) begin
                if (words[n*WORD_W +: WORD_W] < best) begin
                    best = words[n*WORD_W +: WORD_W];
                    index = INDEX_W'(n);
                end
            end
            find_earliest = index;
        end
    endfunction

    wire [INDEX_W-1:0] earliest_from_deadlines;
    assign earliest_from_deadlines = find_earliest(deadline_words);
    assign cmd_ready = !grant_valid || grant_ready;
    wire accept_command = cmd_valid && cmd_ready;

    reg any_pending;
    reg [INDEX_W-1:0] selected;
    reg [WORD_W-1:0] selected_deadline;
    integer k;
    always @(*) begin
        any_pending = 1'b0;
        selected = {INDEX_W{1'b0}};
        selected_deadline = {WORD_W{1'b0}};
        // Scan pending requesters; equal deadlines favor the lower index.
        for (k = 0; k < REQUESTERS; k = k + 1) begin
            if (cmd_pending[k] &&
                (!any_pending ||
                 deadline_words[k*WORD_W +: WORD_W] < selected_deadline)) begin
                any_pending = 1'b1;
                selected = INDEX_W'(k);
                selected_deadline = deadline_words[k*WORD_W +: WORD_W];
            end
        end
        // The cached globally earliest requester provides the common fast path.
        if ((earliest < REQUESTERS) && cmd_pending[earliest])
            selected = earliest;
    end

    reg [REQUESTERS*WORD_W-1:0] next_deadline_words;
    integer j;
    always @(*) begin
        next_deadline_words = deadline_words;
        for (j = 0; j < REQUESTERS; j = j + 1) begin
            if (deadline_words[j*WORD_W +: WORD_W] != {WORD_W{1'b0}})
                next_deadline_words[j*WORD_W +: WORD_W] =
                    deadline_words[j*WORD_W +: WORD_W] - WORD_W'(1);
        end
        if (any_pending)
            next_deadline_words[selected*WORD_W +: WORD_W] =
                cmd_periods[selected*WORD_W +: WORD_W];
    end

    initial begin
        deadline_words = {(REQUESTERS*WORD_W){1'b0}};
        earliest = {INDEX_W{1'b0}};
        grant_valid = 1'b0;
        grant_requester = {WORD_W{1'b0}};
        grant_deadline = {WORD_W{1'b0}};
        before_end = 1'b1;
        past_valid = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            deadline_words <= {(REQUESTERS*WORD_W){1'b0}};
            earliest <= {INDEX_W{1'b0}};
            grant_valid <= 1'b0;
            grant_requester <= {WORD_W{1'b0}};
            grant_deadline <= {WORD_W{1'b0}};
            before_end <= 1'b1;
            past_valid <= 1'b0;
        end else begin
            if (accept_command) begin
                deadline_words <= next_deadline_words;
                earliest <= find_earliest(next_deadline_words);
                past_valid <= 1'b1;
                if (cmd_end_monitor)
                    before_end <= 1'b0;
                grant_valid <= any_pending;
                if (any_pending) begin
                    grant_requester <= WORD_W'(selected);
                    grant_deadline <= deadline_words[selected*WORD_W +: WORD_W];
                end
            end else if (grant_valid && grant_ready) begin
                grant_valid <= 1'b0;
                past_valid <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (past_valid && before_end && $stable(deadline_words))
            assert ($stable(earliest));
endmodule

module peripheral_event_rtc #(
    parameter integer WORD_BITS = 64,
    parameter integer CHANNELS = 4
) (
    input  wire                     clk,
    input  wire                     i_ce,
    input  wire                     bus_read,
    input  wire [CHANNELS-1:0]      event_bits,
    input  wire                     scope_open,
    input  wire                     scope_close,
    output reg  [WORD_BITS-1:0]     pending_count,
    output reg  [WORD_BITS-1:0]     read_data
);
    localparam [WORD_BITS-1:0] ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] CAPACITY = CHANNELS;
    localparam [WORD_BITS-1:0] EVENT_MASK =
        {{(WORD_BITS-CHANNELS){1'b0}}, {CHANNELS{1'b1}}};

    reg [WORD_BITS-1:0] pending_events;
    reg window_active;

    // Count distinct peripheral sources recorded since the last read.
    function automatic [WORD_BITS-1:0] source_population;
        input [WORD_BITS-1:0] bits_in;
        integer n;
        begin
            source_population = ZERO;
            for (n = 0; n < CHANNELS; n = n + 1)
                source_population = source_population +
                    {{(WORD_BITS-1){1'b0}}, bits_in[n]};
        end
    endfunction

    wire [WORD_BITS-1:0] event_word =
        {{(WORD_BITS-CHANNELS){1'b0}}, event_bits};
    wire [WORD_BITS-1:0] pending_population =
        source_population(pending_events);
    wire [WORD_BITS-1:0] newly_pending =
        source_population(event_word & ~pending_events);

    initial begin
        pending_events = ZERO;
        pending_count = ZERO;
        read_data = ZERO;
        window_active = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (scope_close)
                window_active <= 1'b0;
            else if (scope_open)
                window_active <= 1'b1;

            // A read returns the tally and clears both accumulation registers.
            // Read has priority over events arriving on that same edge.
            if (bus_read) begin
                read_data <= pending_count;
                pending_count <= ZERO;
                pending_events <= ZERO;
            end else begin
                pending_events <= pending_events | event_word;
                pending_count <= pending_count + newly_pending;
            end
        end
    end

    assert property (!window_active || (pending_count <= CAPACITY));
endmodule

module prescaler_event_queue #(
    parameter [63:0] P = 64'd4,
    parameter [63:0] DEPTH = 64'd32
) (
    input  wire        clk,
    input  wire        i_pulse_valid,
    output wire        o_pulse_ready,
    input  wire        i_mode,
    output wire        o_valid,
    input  wire        i_out_ready,
    output wire [63:0] o_data
);
    // Supported modulus settings: 3 <= P <= 16.
    // First accepted pulse: ARM and sample mode.
    // Second accepted pulse: START.
    // Pulse P or P+1: FINISH and enqueue its event record.
    localparam [63:0] IDLE  = 64'd0;
    localparam [63:0] ARMED = 64'd1;
    localparam [63:0] RUN   = 64'd2;

    reg [63:0] phase;
    reg [63:0] pulse_count;
    reg mode_q;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    reg [63:0] event_mem [0:DEPTH-1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] fifo_count;

    wire [63:0] modulus;
    wire pulse_fire;
    wire finish_fire;
    wire pop_fire;
    wire [DEPTH-1:0] filled;

    assign modulus = mode_q ? P + 64'd1 : P;
    assign o_pulse_ready = fifo_count < DEPTH;
    assign pulse_fire = i_pulse_valid && o_pulse_ready;
    assign finish_fire = pulse_fire && (phase == RUN)
                         && (pulse_count == modulus - 64'd1);
    assign o_valid = fifo_count != 64'd0;
    assign o_data = event_mem[rd_ptr];
    assign pop_fire = o_valid && i_out_ready;

    // Filled slots are the circular interval starting at rd_ptr.
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupied_slots
            localparam [63:0] ENTRY = g;
            assign filled[g] = ((ENTRY >= rd_ptr)
                              ? (ENTRY - rd_ptr)
                              : (ENTRY + DEPTH - rd_ptr)) < fifo_count;
        end
    endgenerate

    integer j;
    initial begin
        phase = IDLE;
        pulse_count = 64'd0;
        mode_q = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        scope_armed = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        fifo_count = 64'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            event_mem[j] = 64'd0;
    end

    always @(posedge clk) begin
        if (pulse_fire) begin
            case (phase)
                IDLE: begin
                    // Q is the ARM event; its scope latch never clears.
                    scope_armed <= 1'b1;
                    mode_q <= i_mode;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    pulse_count <= 64'd1;
                    phase <= ARMED;
                end
                ARMED: begin
                    start_seen <= 1'b1;
                    pulse_count <= 64'd2;
                    phase <= RUN;
                end
                RUN: begin
                    if (finish_fire) begin
                        pulse_count <= 64'd0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= IDLE;
                    end else begin
                        pulse_count <= pulse_count + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    pulse_count <= 64'd0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end

        if (finish_fire) begin
            // Record: ARM witness, START witness, sampled mode,
            // and the number of accepted pulses in this division.
            event_mem[wr_ptr] <= (pulse_count + 64'd1)
                | (arm_seen ? 64'h8000000000000000 : 64'd0)
                | (start_seen ? 64'h4000000000000000 : 64'd0)
                | (mode_q ? 64'h2000000000000000 : 64'd0);
            wr_ptr <= (wr_ptr == DEPTH - 64'd1)
                    ? 64'd0 : wr_ptr + 64'd1;
        end
        if (pop_fire)
            rd_ptr <= (rd_ptr == DEPTH - 64'd1)
                    ? 64'd0 : rd_ptr + 64'd1;

        case ({finish_fire, pop_fire})
            2'b10: fifo_count <= fifo_count + 64'd1;
            2'b01: fifo_count <= fifo_count - 64'd1;
            default: begin end
        endcase
    end

    // After Q: START requires ARM, and every observable FINISH
    // must carry both earlier event witnesses.
    always @(posedge clk)
        if (scope_armed)
            assert ((!start_seen || arm_seen)
                    && (!o_valid || (o_data[63] && o_data[62])));
endmodule

module spectral_cfg_axi_apb_bridge #(
    parameter integer ADDR_WIDTH = 16,
    parameter integer DATA_WIDTH = 16
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_ce,
    input  wire                  s_axi_awvalid,
    output wire                  s_axi_awready,
    input  wire [ADDR_WIDTH-1:0] s_axi_awaddr,
    input  wire                  s_axi_wvalid,
    output wire                  s_axi_wready,
    input  wire [DATA_WIDTH-1:0] s_axi_wdata,
    output wire                  s_axi_bvalid,
    input  wire                  s_axi_bready,
    output wire [1:0]            s_axi_bresp,
    output reg  [ADDR_WIDTH-1:0] apb_paddr,
    output reg  [DATA_WIDTH-1:0] apb_pwdata,
    output reg                   apb_psel,
    output reg                   apb_penable,
    output wire                  apb_pwrite,
    input  wire                  apb_pready
);
    localparam [15:0] PH_IDLE   = 16'd0;
    localparam [15:0] PH_LOAD   = 16'd1;
    localparam [15:0] PH_SETUP  = 16'd2;
    localparam [15:0] PH_ACCESS = 16'd3;
    localparam [15:0] PH_RESP   = 16'd4;

    reg [15:0] phase;
    reg aw_full, w_full;
    reg [ADDR_WIDTH-1:0] req_addr;
    reg [DATA_WIDTH-1:0] req_data;

    // Historical values from the independently accepted AXI channels.
    reg [ADDR_WIDTH-1:0] accepted_addr;
    reg [DATA_WIDTH-1:0] accepted_data;
    reg past_valid;

    assign s_axi_awready = i_ce && (phase == PH_IDLE) && !aw_full;
    assign s_axi_wready  = i_ce && (phase == PH_IDLE) && !w_full;
    assign s_axi_bvalid  = (phase == PH_RESP);
    assign s_axi_bresp  = 2'b00;
    assign apb_pwrite   = 1'b1;

    initial begin
        phase = PH_IDLE;
        aw_full = 1'b0;
        w_full = 1'b0;
        req_addr = {ADDR_WIDTH{1'b0}};
        req_data = {DATA_WIDTH{1'b0}};
        accepted_addr = {ADDR_WIDTH{1'b0}};
        accepted_data = {DATA_WIDTH{1'b0}};
        apb_paddr = {ADDR_WIDTH{1'b0}};
        apb_pwdata = {DATA_WIDTH{1'b0}};
        apb_psel = 1'b0;
        apb_penable = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase <= PH_IDLE;
            aw_full <= 1'b0;
            w_full <= 1'b0;
            req_addr <= {ADDR_WIDTH{1'b0}};
            req_data <= {DATA_WIDTH{1'b0}};
            accepted_addr <= {ADDR_WIDTH{1'b0}};
            accepted_data <= {DATA_WIDTH{1'b0}};
            apb_paddr <= {ADDR_WIDTH{1'b0}};
            apb_pwdata <= {DATA_WIDTH{1'b0}};
            apb_psel <= 1'b0;
            apb_penable <= 1'b0;
            past_valid <= 1'b0;
        end else if (i_ce) begin
            past_valid <= 1'b1;
            case (phase)
                PH_IDLE: begin
                    if (s_axi_awvalid && !aw_full) begin
                        req_addr <= s_axi_awaddr;
                        accepted_addr <= s_axi_awaddr;
                        aw_full <= 1'b1;
                    end
                    if (s_axi_wvalid && !w_full) begin
                        req_data <= s_axi_wdata;
                        accepted_data <= s_axi_wdata;
                        w_full <= 1'b1;
                    end
                    if (aw_full && w_full) begin
                        aw_full <= 1'b0;
                        w_full <= 1'b0;
                        phase <= PH_LOAD;
                    end
                end
                PH_LOAD: begin
                    apb_paddr <= req_addr;
                    apb_pwdata <= req_data;
                    apb_psel <= 1'b1;
                    apb_penable <= 1'b0;
                    phase <= PH_SETUP;
                end
                PH_SETUP: begin
                    apb_penable <= 1'b1;
                    phase <= PH_ACCESS;
                end
                PH_ACCESS: begin
                    if (apb_pready) begin
                        apb_psel <= 1'b0;
                        apb_penable <= 1'b0;
                        phase <= PH_RESP;
                    end
                end
                PH_RESP: begin
                    if (s_axi_bready)
                        phase <= PH_IDLE;
                end
                default: begin
                    phase <= PH_IDLE;
                    aw_full <= 1'b0;
                    w_full <= 1'b0;
                    apb_psel <= 1'b0;
                    apb_penable <= 1'b0;
                end
            endcase
        end
    end

    // A continuing peripheral selection preserves the bus words and presents
    // the address and data recorded by earlier AXI acceptance events.
    always @(posedge clk)
        if (past_valid && apb_psel && $stable(apb_psel))
            assert ($stable(apb_paddr) && $stable(apb_pwdata) &&
                    (apb_paddr == accepted_addr) &&
                    (apb_pwdata == accepted_data));
endmodule

module tdm_capture_demux #(
    parameter integer CHANNELS = 32,
    parameter integer DATA_WIDTH = 32,
    parameter integer COUNT_WIDTH = 32
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_valid,
    output wire o_ready,
    input  wire i_frame_sync,
    input  wire [DATA_WIDTH-1:0] i_data,
    output wire o_frame_complete,
    output wire [CHANNELS*DATA_WIDTH-1:0] o_channels
);
    localparam logic [COUNT_WIDTH-1:0] ZERO_COUNT = COUNT_WIDTH'(32'd0);
    localparam logic [COUNT_WIDTH-1:0] ONE_COUNT = COUNT_WIDTH'(32'd1);
    localparam logic [COUNT_WIDTH-1:0] CHANNEL_COUNT = COUNT_WIDTH'(CHANNELS);
    localparam logic [COUNT_WIDTH-1:0] LAST_SLOT = CHANNEL_COUNT - ONE_COUNT;
    localparam logic [CHANNELS-1:0] ALL_SEEN = {CHANNELS{1'b1}};
    localparam logic [CHANNELS-1:0] FIRST_SEEN = {{(CHANNELS-1){1'b0}}, 1'b1};

    typedef enum logic [1:0] {
        WAIT_SYNC  = 2'b00,
        RECEIVE    = 2'b01,
        FRAME_DONE = 2'b10
    } state_t;

    state_t state;
    logic [COUNT_WIDTH-1:0] slot_count;
    logic frame_sync_flag;
    logic [DATA_WIDTH-1:0] channel_data [0:CHANNELS-1];

    // Shadow history: each bit records an accepted slot in this frame.
    logic [CHANNELS-1:0] seen_slots;
    logic armed;
    logic past_valid;
    wire accept;

    initial begin
        state = WAIT_SYNC;
        slot_count = ZERO_COUNT;
        frame_sync_flag = 1'b0;
        seen_slots = {CHANNELS{1'b0}};
        armed = 1'b0;
        past_valid = 1'b0;
    end

    genvar channel;
    generate
        for (channel = 0; channel < CHANNELS; channel = channel + 1) begin : channels
            initial channel_data[channel] = {DATA_WIDTH{1'b0}};
            assign o_channels[channel*DATA_WIDTH +: DATA_WIDTH] = channel_data[channel];
        end
    endgenerate

    // Between frames, refuse samples that do not identify a frame start.
    // During a frame, every accepted sample advances one demultiplexer slot.
    assign o_ready = i_ce &&
                     (i_frame_sync || ((state == RECEIVE) && frame_sync_flag));
    assign accept = i_valid && o_ready;
    assign o_frame_complete = (state == FRAME_DONE);

    always @(posedge clk) begin
        if (accept) begin
            past_valid <= 1'b1;
            if (i_frame_sync) begin
                // An accepted sync starts, or restarts, a frame at channel zero.
                channel_data[ZERO_COUNT] <= i_data;
                slot_count <= ONE_COUNT;
                seen_slots <= FIRST_SEEN;
                armed <= 1'b1;
                if (CHANNEL_COUNT == ONE_COUNT) begin
                    state <= FRAME_DONE;
                    frame_sync_flag <= 1'b0;
                end else begin
                    state <= RECEIVE;
                    frame_sync_flag <= 1'b1;
                end
            end else if (state == RECEIVE) begin
                channel_data[slot_count] <= i_data;
                seen_slots[slot_count] <= 1'b1;
                slot_count <= slot_count + ONE_COUNT;
                if (slot_count == LAST_SLOT) begin
                    state <= FRAME_DONE;
                    frame_sync_flag <= 1'b0;
                end
            end
        end
    end

    // After the first accepted sync, a completion edge requires prior
    // acceptance of every channel's slot in the completed frame.
    always @(posedge clk) begin
        if (past_valid && armed && $rose(o_frame_complete))
            assert (seen_slots == ALL_SEEN);
    end
endmodule

module power_mode_handshake #(
    parameter integer DATA_W = 128,
    parameter integer CFG_ENTRIES = 16,
    parameter integer INDEX_W = $clog2(CFG_ENTRIES)
) (
    input  wire                   clk,
    input  wire                   i_valid,
    output wire                   o_ready,
    input  wire                   i_cfg_write,
    input  wire                   i_wake,
    input  wire [INDEX_W-1:0]     i_index,
    input  wire [DATA_W-1:0]      i_word,
    output wire                   o_valid,
    input  wire                   i_ready,
    output wire [DATA_W-1:0]      o_word,
    output wire [1:0]             o_requested_mode,
    output wire [1:0]             o_power_mode,
    output wire                   o_cpu_clock_enable,
    output wire                   o_isolation_enable,
    output wire                   o_run_grant,
    output wire                   o_isolate_grant
);
    // Four modes per profile; CFG_ENTRIES is a multiple of four, at least eight.
    localparam [1:0] MODE_RUN   = 2'd0;
    localparam [1:0] MODE_IDLE  = 2'd1;
    localparam [1:0] MODE_SLEEP = 2'd2;
    localparam [1:0] MODE_DEEP  = 2'd3;

    reg [DATA_W-1:0] mode_cfg [0:CFG_ENTRIES-1];
    reg [DATA_W-1:0] pending_config;
    reg [INDEX_W-1:0] pending_index;
    reg pending_valid;
    reg pending_wake;
    reg [1:0] power_mode;
    reg [DATA_W-1:0] active_config;
    reg before_first_wake;
    reg pv;

    // The remaining 126 bits are software-programmable timing/configuration data.
    // Clock and isolation controls are normalized according to the selected mode.
    function automatic [DATA_W-1:0] normalize_config;
        input [DATA_W-1:0] payload;
        input [1:0] mode;
        begin
            normalize_config = {
                payload[DATA_W-1:2],
                ((mode == MODE_SLEEP) || (mode == MODE_DEEP)),
                (mode == MODE_RUN)
            };
        end
    endfunction

    wire [INDEX_W-1:0] request_index;
    assign request_index = {
        i_index[INDEX_W-1:2],
        (i_wake ? MODE_RUN : i_index[1:0])
    };

    // A pending transition back-pressures all further input commands.
    assign o_ready = !pending_valid && (i_index < CFG_ENTRIES);
    assign o_valid = pending_valid;
    assign o_word = pending_config;
    assign o_requested_mode = pending_index[1:0];

    wire accept_command = i_valid && o_ready;
    wire apply_transition = o_valid && i_ready;

    // These are the two power-control grants issued on a completed transition.
    assign o_run_grant = apply_transition && pending_config[0];
    assign o_isolate_grant = apply_transition && pending_config[1];
    assign o_power_mode = power_mode;
    assign o_cpu_clock_enable = active_config[0];
    assign o_isolation_enable = active_config[1];

    wire [CFG_ENTRIES-1:0] cfg_control_ok;
    genvar g;
    generate
        for (g = 0; g < CFG_ENTRIES; g = g + 1) begin : check_cfg_encoding
            localparam [1:0] SLOT_MODE = g % 4;
            assign cfg_control_ok[g] =
                (mode_cfg[g][0] == (SLOT_MODE == MODE_RUN)) &&
                (mode_cfg[g][1] == ((SLOT_MODE == MODE_SLEEP) ||
                                         (SLOT_MODE == MODE_DEEP)));
        end
    endgenerate

    integer n;
    initial begin
        for (n = 0; n < CFG_ENTRIES; n = n + 1)
            mode_cfg[n] = normalize_config({DATA_W{1'b0}}, n[1:0]);
        pending_config = {DATA_W{1'b0}};
        pending_index = {INDEX_W{1'b0}};
        pending_valid = 1'b0;
        pending_wake = 1'b0;
        power_mode = MODE_RUN;
        active_config = normalize_config({DATA_W{1'b0}}, MODE_RUN);
        before_first_wake = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        // Conditional initialization preserves the all-state idle condition.
        if (accept_command || apply_transition)
            pv <= 1'b1;

        if (accept_command) begin
            if (i_cfg_write) begin
                mode_cfg[i_index] <= normalize_config(i_word, i_index[1:0]);
            end else begin
                pending_index <= request_index;
                pending_config <= mode_cfg[request_index];
                pending_wake <= i_wake;
                pending_valid <= 1'b1;
            end
        end

        if (apply_transition) begin
            power_mode <= pending_index[1:0];
            active_config <= pending_config;
            pending_valid <= 1'b0;
            if (pending_wake)
                before_first_wake <= 1'b0;
        end
    end

    // Previous-cycle absence, scoped to before the first completed wake.
    always @(posedge clk)
        if (pv && $past(before_first_wake))
            assert (!($past(o_run_grant) && $past(o_isolate_grant)));
endmodule

module interrupt_ack_chain #(
    parameter integer ENTRIES = 16,
    parameter integer DATA_WIDTH = 64
) (
    input  wire                      clk,
    input  wire                      i_ce,
    input  wire                      i_ack,
    input  wire                      i_close,
    input  wire [ENTRIES-1:0]        i_request,
    input  wire [ENTRIES-1:0]        i_vector_we,
    input  wire [DATA_WIDTH-1:0]     i_vector_data,
    output reg                       window_active,
    output reg  [ENTRIES-1:0]        claimed,
    output reg                       token_passed,
    output wire                      vector_valid,
    output wire [DATA_WIDTH-1:0]     vector_bus
);
    reg [ENTRIES-1:0] pending;
    reg [ENTRIES-1:0] token;
    reg [DATA_WIDTH-1:0] local_vector [0:ENTRIES-1];

    wire [ENTRIES:0] forwarded;
    wire [DATA_WIDTH-1:0] vector_chain [0:ENTRIES];

    assign forwarded[0] = 1'b0;
    assign vector_chain[0] = {DATA_WIDTH{1'b0}};
    assign vector_bus = vector_chain[ENTRIES];
    assign vector_valid = |claimed;

    initial begin
        window_active = 1'b0;
        token_passed = 1'b0;
    end

    // Q accepts an acknowledge token. R closes its observation window.
    always @(posedge clk) begin
        if (i_ce) begin
            if (!window_active) begin
                token_passed <= 1'b0;
                if (i_ack)
                    window_active <= 1'b1;
            end else if (i_close) begin
                window_active <= 1'b0;
                token_passed <= 1'b0;
            end else if (forwarded[ENTRIES]) begin
                token_passed <= 1'b1;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : cells
            initial begin
                pending[g] = 1'b0;
                token[g] = 1'b0;
                claimed[g] = 1'b0;
                local_vector[g] = {DATA_WIDTH{1'b0}};
            end

            // A requesting cell consumes the token; otherwise it forwards it.
            assign forwarded[g+1] = token[g] && !pending[g];
            assign vector_chain[g+1] = vector_chain[g]
                | (local_vector[g] & {DATA_WIDTH{claimed[g]}});

            always @(posedge clk) begin
                if (i_ce) begin
                    if (i_vector_we[g])
                        local_vector[g] <= i_vector_data;

                    pending[g] <= pending[g] | i_request[g];
                    if (window_active && !i_close && token[g] && pending[g])
                        pending[g] <= 1'b0;

                    if (!window_active) begin
                        if (g == 0)
                            token[g] <= i_ack;
                        else
                            token[g] <= 1'b0;
                        claimed[g] <= 1'b0;
                    end else if (i_close) begin
                        token[g] <= 1'b0;
                        claimed[g] <= 1'b0;
                    end else begin
                        token[g] <= forwarded[g];
                        if (token[g] && pending[g])
                            claimed[g] <= 1'b1;
                    end
                end
            end
        end
    endgenerate

    // The two halves of the chain must never both own the vector bus.
    always @(posedge clk) begin
        if (window_active)
            assert (!((|claimed[ENTRIES/2-1:0])
                   && (|claimed[ENTRIES-1:ENTRIES/2])));
    end

    // A locally claimed token must never also escape the chain.
    always @(posedge clk) begin
        if (window_active)
            assert (!((|claimed) && token_passed));
    end
endmodule

module rom_patch_bank #(
    parameter integer ENTRIES = 32'd16,
    parameter integer ADDR_WIDTH = 32'd16,
    parameter integer WORD_WIDTH = 32'd16
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  cfg_valid,
    input  wire                  cfg_enable,
    input  wire [15:0]           cfg_slot,
    input  wire [ADDR_WIDTH-1:0] cfg_address,
    input  wire [WORD_WIDTH-1:0] cfg_word,
    input  wire [ADDR_WIDTH-1:0] fetch_address,
    input  wire [WORD_WIDTH-1:0] rom_word,
    output reg  [WORD_WIDTH-1:0] fetch_word,
    output reg                   patch_hit,
    output reg  [15:0]           patch_count
);
    localparam logic [15:0] ENTRY_LIMIT = ENTRIES;

    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        COMMIT = 2'b01
    } state_t;
    state_t state;

    reg [ADDR_WIDTH-1:0] patch_address [0:ENTRIES-1];
    reg [WORD_WIDTH-1:0] patch_word [0:ENTRIES-1];
    reg [ENTRIES-1:0] slot_enable;

    reg [15:0] pending_slot;
    reg pending_enable;
    reg [ADDR_WIDTH-1:0] pending_address;
    reg [WORD_WIDTH-1:0] pending_word;
    reg [15:0] enabled_count;

    initial begin
        state = IDLE;
        patch_count = 16'd0;
        slot_enable = {ENTRIES{1'b0}};
        pending_slot = 16'd0;
        pending_enable = 1'b0;
        pending_address = {ADDR_WIDTH{1'b0}};
        pending_word = {WORD_WIDTH{1'b0}};
        for (integer n = 32'd0; n < ENTRIES; n = n + 32'd1) begin
            patch_address[n] = {ADDR_WIDTH{1'b0}};
            patch_word[n] = {WORD_WIDTH{1'b0}};
        end
    end

    // Highest numbered matching slot wins if addresses overlap.
    always @(*) begin
        fetch_word = rom_word;
        patch_hit = 1'b0;
        enabled_count = 16'd0;
        for (integer n = 32'd0; n < ENTRIES; n = n + 32'd1) begin
            enabled_count = enabled_count + {15'd0, slot_enable[n]};
            if (slot_enable[n] && patch_address[n] == fetch_address) begin
                fetch_word = patch_word[n];
                patch_hit = 1'b1;
            end
        end
    end

    // Clock enable freezes the entire configuration state, including requests.
    always @(posedge clk) begin
        if (ce) begin
            case (state)
                IDLE: begin
                    if (cfg_valid && cfg_slot < ENTRY_LIMIT) begin
                        pending_slot <= cfg_slot;
                        pending_enable <= cfg_enable;
                        pending_address <= cfg_address;
                        pending_word <= cfg_word;
                        state <= COMMIT;
                    end
                end
                COMMIT: begin
                    patch_address[pending_slot] <= pending_address;
                    patch_word[pending_slot] <= pending_word;
                    slot_enable[pending_slot] <= pending_enable;
                    if (pending_enable && !slot_enable[pending_slot])
                        patch_count <= patch_count + 16'd1;
                    else if (!pending_enable && slot_enable[pending_slot])
                        patch_count <= patch_count - 16'd1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk) assert (patch_count <= ENTRY_LIMIT);
endmodule

module phase_lock_monitor #(
    parameter [31:0] LOCK_SAMPLES = 32'd6,
    parameter signed [31:0] PHASE_WINDOW = 32'sd8
) (
    input  wire               clk,
    input  wire               tracking_enable,
    input  wire               sample_valid,
    output wire               sample_ready,
    input  wire signed [31:0] phase_error,
    output reg                locked,
    output reg [31:0]         good_count
);
    reg before_first_loss;
    reg past_valid;

    // Disabled tracking applies back-pressure; no sample is consumed.
    assign sample_ready = tracking_enable;
    wire sample_take = sample_valid && sample_ready;
    wire in_window = (phase_error >= -PHASE_WINDOW) &&
                     (phase_error <=  PHASE_WINDOW);

    initial begin
        locked = 1'b0;
        good_count = 32'd0;
        before_first_loss = 1'b1;
        past_valid = 1'b0;
    end

    // LOCK_SAMPLES is a positive acquisition threshold.
    // The lock bit freezes the consecutive-sample counter at acquisition.
    always @(posedge clk) begin
        if (sample_take) begin
            past_valid <= 1'b1;
            if (in_window) begin
                if (!locked) begin
                    good_count <= good_count + 32'd1;
                    if (good_count >= (LOCK_SAMPLES - 32'd1))
                        locked <= 1'b1;
                end
            end else begin
                good_count <= 32'd0;
                locked <= 1'b0;
                if (locked)
                    before_first_loss <= 1'b0;
            end
        end
    end

    // Before the first loss of lock, each acquisition edge respects the bound.
    always @(posedge clk) begin
        if (past_valid && before_first_loss && $rose(locked))
            assert (good_count <= LOCK_SAMPLES);
    end
endmodule

module dma_descriptor_chain #(
    parameter [7:0] DESC_WORDS = 8'd4
) (
    input  wire       clk,
    input  wire       rst_n,

    input  wire       cmd_valid,
    output wire       cmd_ready,
    input  wire [7:0] cmd_descriptor_ptr,

    output wire       mem_req_valid,
    input  wire       mem_req_ready,
    output wire [7:0] mem_req_addr,

    input  wire       mem_rsp_valid,
    output wire       mem_rsp_ready,
    input  wire [7:0] mem_rsp_data,

    output wire       desc_valid,
    input  wire       desc_ready,
    output reg  [7:0] source_addr,
    output reg  [7:0] destination_addr,
    output reg  [7:0] transfer_count,
    output reg  [7:0] address_stride
);
    localparam [7:0] ST_IDLE  = 8'd0;
    localparam [7:0] ST_ARMED = 8'd1;
    localparam [7:0] ST_WAIT  = 8'd2;
    localparam [7:0] ST_REQ   = 8'd3;
    localparam [7:0] ST_DONE  = 8'd4;
    localparam [7:0] LAST_WORD = DESC_WORDS - 8'd1;

    reg [7:0] fetch_state;
    reg [7:0] descriptor_ptr;
    reg [7:0] fetch_addr;
    reg [7:0] fetch_index;
    reg       window;
    reg       arm_seen;
    reg       start_seen;
    reg       past_valid;

    wire cmd_fire;
    wire req_fire;
    wire rsp_fire;
    wire desc_fire;

    assign cmd_ready = (fetch_state == ST_IDLE);
    assign mem_req_valid = (fetch_state == ST_ARMED) ||
                           (fetch_state == ST_REQ);
    assign mem_req_addr = fetch_addr;
    assign mem_rsp_ready = (fetch_state == ST_WAIT);
    assign desc_valid = (fetch_state == ST_DONE);

    assign cmd_fire = cmd_valid && cmd_ready;
    assign req_fire = mem_req_valid && mem_req_ready;
    assign rsp_fire = mem_rsp_valid && mem_rsp_ready;
    assign desc_fire = desc_valid && desc_ready;

    initial begin
        fetch_state = ST_IDLE;
        descriptor_ptr = 8'd0;
        fetch_addr = 8'd0;
        fetch_index = 8'd0;
        source_addr = 8'd0;
        destination_addr = 8'd0;
        transfer_count = 8'd0;
        address_stride = 8'd0;
        window = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        past_valid = 1'b0;
    end

    // Descriptor words are source, destination, count, and stride.
    // Larger descriptor formats may append ignored extension words.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            fetch_state <= ST_IDLE;
            descriptor_ptr <= 8'd0;
            fetch_addr <= 8'd0;
            fetch_index <= 8'd0;
            source_addr <= 8'd0;
            destination_addr <= 8'd0;
            transfer_count <= 8'd0;
            address_stride <= 8'd0;
            window <= 1'b0;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            past_valid <= 1'b0;
        end else begin
            // Updating this checker register also requires a handshake,
            // so a fully stalled engine leaves every register unchanged.
            if (cmd_fire || req_fire || rsp_fire || desc_fire)
                past_valid <= 1'b1;

            case (fetch_state)
                ST_IDLE: begin
                    if (cmd_fire) begin
                        // Q opens the scope and arms this descriptor.
                        descriptor_ptr <= cmd_descriptor_ptr;
                        fetch_addr <= cmd_descriptor_ptr;
                        fetch_index <= 8'd0;
                        window <= 1'b1;
                        arm_seen <= 1'b1;
                        start_seen <= 1'b0;
                        fetch_state <= ST_ARMED;
                    end
                end

                ST_ARMED: begin
                    if (req_fire) begin
                        // The first accepted read starts descriptor fetching.
                        start_seen <= 1'b1;
                        fetch_state <= ST_WAIT;
                    end
                end

                ST_WAIT: begin
                    if (rsp_fire) begin
                        case (fetch_index)
                            8'd0: source_addr <= mem_rsp_data;
                            8'd1: destination_addr <= mem_rsp_data;
                            8'd2: transfer_count <= mem_rsp_data;
                            8'd3: address_stride <= mem_rsp_data;
                            default: begin end
                        endcase

                        if (fetch_index == LAST_WORD) begin
                            // Entering DONE raises desc_valid: fetch finish.
                            fetch_state <= ST_DONE;
                        end else begin
                            fetch_index <= fetch_index + 8'd1;
                            fetch_addr <= fetch_addr + 8'd1;
                            fetch_state <= ST_REQ;
                        end
                    end
                end

                ST_REQ: begin
                    if (req_fire)
                        fetch_state <= ST_WAIT;
                end

                ST_DONE: begin
                    if (desc_fire) begin
                        // R closes the scope; another command can reopen it.
                        fetch_state <= ST_IDLE;
                        window <= 1'b0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                    end
                end

                default: begin end
            endcase
        end
    end

    // Within each command-to-delivery window: arm precedes start,
    // and both arm and start precede the rising finish indication.
    always @(posedge clk) begin
        if (past_valid && window)
            assert ((!$rose(start_seen) || arm_seen) &&
                    (!$rose(desc_valid) || (arm_seen && start_seen)));
    end
endmodule

module vector_rrip_replacement #(
    parameter integer ENTRIES = 32,
    parameter integer WORD_W = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  scope_q,
    input  wire                  scope_r,
    input  wire                  arm_req,
    input  wire                  hit_valid,
    input  wire [WORD_W-1:0]     hit_way,
    output logic                 start_event,
    output logic                 finish_event,
    output logic [WORD_W-1:0]    victim_way
);
    localparam logic [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam logic [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam logic [WORD_W-1:0] MAX_RRPV = {WORD_W{1'b1}};
    localparam logic [WORD_W-1:0] INSERT_RRPV = MAX_RRPV - ONE;

    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        ARMED  = 2'b01,
        SEARCH = 2'b10,
        RETIRE = 2'b11
    } state_t;
    state_t state;

    logic window;
    logic arm_seen;
    logic start_seen;

    // One eight-bit reuse prediction per vector operand-cache line.
    logic [ENTRIES*WORD_W-1:0] rrpv;
    logic [ENTRIES*WORD_W-1:0] aged_rrpv;
    logic candidate_found;
    logic [WORD_W-1:0] candidate_way;

    initial begin
        state = IDLE;
        window = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        start_event = 1'b0;
        finish_event = 1'b0;
        victim_way = ZERO;
        rrpv = {ENTRIES{INSERT_RRPV}};
    end

    // Priority-select a distant-reuse line and prepare saturating aging.
    always @(*) begin
        candidate_found = 1'b0;
        candidate_way = ZERO;
        aged_rrpv = rrpv;
        for (integer k = 0; k < ENTRIES; k = k + 1) begin
            if (rrpv[k*WORD_W +: WORD_W] == MAX_RRPV) begin
                if (!candidate_found) begin
                    candidate_found = 1'b1;
                    candidate_way = k[WORD_W-1:0];
                end
            end else begin
                aged_rrpv[k*WORD_W +: WORD_W] =
                    rrpv[k*WORD_W +: WORD_W] + ONE;
            end
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            start_event <= 1'b0;
            finish_event <= 1'b0;

            if (scope_r) begin
                window <= 1'b0;
                state <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
            end else if (scope_q && !window) begin
                window <= 1'b1;
                state <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
            end else if (window) begin
                case (state)
                    IDLE: begin
                        if (arm_req) begin
                            arm_seen <= 1'b1;
                            start_seen <= 1'b0;
                            state <= ARMED;
                        end else if (hit_valid && (hit_way < ENTRIES)) begin
                            rrpv[hit_way*WORD_W +: WORD_W] <= ZERO;
                        end
                    end
                    ARMED: begin
                        start_seen <= 1'b1;
                        start_event <= 1'b1;
                        state <= SEARCH;
                    end
                    SEARCH: begin
                        if (candidate_found) begin
                            victim_way <= candidate_way;
                            rrpv[candidate_way*WORD_W +: WORD_W] <= INSERT_RRPV;
                            finish_event <= 1'b1;
                            state <= RETIRE;
                        end else begin
                            // Advance predictions only when no victim exists.
                            rrpv <= aged_rrpv;
                        end
                    end
                    RETIRE: begin
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        state <= IDLE;
                    end
                endcase
            end
        end
    end

    // Within each Q-to-R window: arm precedes start, and start precedes finish.
    always @(*) begin
        if (window)
            assert ((!start_event || arm_seen) &&
                    (!finish_event || (arm_seen && start_seen)));
    end
endmodule

module sir_word_codec #(
    parameter integer WORD_BITS = 128,
    parameter integer BIT_TICKS = 16
) (
    input  wire                 clk,
    input  wire                 i_word_valid,
    output wire                 o_word_ready,
    input  wire [WORD_BITS-1:0] i_word,
    output wire                 o_ir_valid,
    input  wire                 i_sample_ready,
    output wire                 o_ir_sample,
    input  wire                 i_rx_pulse,
    output reg  [WORD_BITS-1:0] o_rx_word,
    output reg                  o_rx_complete
);
    localparam integer PHASE_W = (BIT_TICKS > 1) ? $clog2(BIT_TICKS) : 1;
    localparam integer PULSE_TICKS = (3 * BIT_TICKS) / 16;
    localparam integer PULSE_W = (PULSE_TICKS > 0) ? $clog2(PULSE_TICKS + 1) : 1;
    localparam integer INDEX_W = (WORD_BITS > 1) ? $clog2(WORD_BITS) : 1;

    localparam [PHASE_W-1:0] LAST_PHASE = PHASE_W'(BIT_TICKS - 1);
    localparam [PHASE_W-1:0] PULSE_END = PHASE_W'(PULSE_TICKS);
    localparam [PULSE_W-1:0] PULSE_LOAD = PULSE_W'(PULSE_TICKS);
    localparam [INDEX_W-1:0] LAST_BIT = INDEX_W'(WORD_BITS - 1);

    reg active;
    reg [WORD_BITS-1:0] tx_word;
    reg [INDEX_W-1:0] bit_index;
    reg [PHASE_W-1:0] phase;
    reg [PULSE_W-1:0] pulse_width;
    reg rx_pulse_latch;
    reg before_first_completion;
    reg pv = 1'b0;

    wire word_fire;
    wire sample_fire;
    wire pulse_transfer;
    wire late_slot;
    wire [WORD_BITS-1:0] shifted_tx_word;

    assign o_word_ready = !active;
    assign o_ir_valid = active;
    assign o_ir_sample = (pulse_width != {PULSE_W{1'b0}});
    assign word_fire = i_word_valid && o_word_ready;
    assign sample_fire = o_ir_valid && i_sample_ready;
    assign pulse_transfer = sample_fire && o_ir_sample;
    assign late_slot = (phase >= PULSE_END);
    assign shifted_tx_word = tx_word >> 1'b1;

    initial begin
        active = 1'b0;
        tx_word = {WORD_BITS{1'b0}};
        bit_index = {INDEX_W{1'b0}};
        phase = {PHASE_W{1'b0}};
        pulse_width = {PULSE_W{1'b0}};
        rx_pulse_latch = 1'b0;
        o_rx_word = {WORD_BITS{1'b0}};
        o_rx_complete = 1'b0;
        before_first_completion = 1'b1;
    end

    // Each accepted IR sample represents one sixteenth-bit tick.
    // Backpressure holds the current sample, phase, and decoder state.
    // With i_word_valid and i_sample_ready both low, all registers hold.
    always @(posedge clk) begin
        if (word_fire || sample_fire)
            pv <= 1'b1;

        if (word_fire) begin
            active <= 1'b1;
            tx_word <= i_word;
            bit_index <= {INDEX_W{1'b0}};
            phase <= {PHASE_W{1'b0}};
            pulse_width <= i_word[0] ? {PULSE_W{1'b0}} : PULSE_LOAD;
            rx_pulse_latch <= 1'b0;
            o_rx_word <= {WORD_BITS{1'b0}};
            o_rx_complete <= 1'b0;
        end else if (sample_fire) begin
            if (phase == LAST_PHASE) begin
                // A received pulse anywhere in this bit decodes as UART zero.
                o_rx_word[bit_index] <= !(rx_pulse_latch || i_rx_pulse);
                rx_pulse_latch <= 1'b0;
                phase <= {PHASE_W{1'b0}};
                tx_word <= shifted_tx_word;

                if (bit_index == LAST_BIT) begin
                    active <= 1'b0;
                    pulse_width <= {PULSE_W{1'b0}};
                    o_rx_complete <= 1'b1;
                    before_first_completion <= 1'b0;
                end else begin
                    bit_index <= bit_index + INDEX_W'(1);
                    pulse_width <= shifted_tx_word[0] ? {PULSE_W{1'b0}} : PULSE_LOAD;
                end
            end else begin
                phase <= phase + PHASE_W'(1);
                rx_pulse_latch <= rx_pulse_latch || i_rx_pulse;
                if (pulse_width != {PULSE_W{1'b0}})
                    pulse_width <= pulse_width - PULSE_W'(1);
            end
        end
    end

    // Before the first completed word, a transferred infrared pulse and
    // the late portion of a bit must never have coincided last cycle.
    always @(posedge clk)
        if (pv && $past(before_first_completion))
            assert (!($past(pulse_transfer) && $past(late_slot)));
endmodule

module layer_scan_deadline #(
    parameter integer WORD_BITS = 8,
    parameter integer TIMER_BITS = 8,
    parameter [WORD_BITS-1:0] LAYER_SEED = 8'hA5
) (
    input wire clk,
    input wire i_ce,
    input wire scope_q,
    input wire scope_r,
    input wire request_render,
    input wire request_map,
    output reg [WORD_BITS-1:0] layer_word,
    output reg carry,
    output reg [TIMER_BITS-1:0] ticks_left,
    output reg render_pending,
    output reg map_pending,
    output reg window
);
    localparam [TIMER_BITS-1:0] TICK_ZERO = {TIMER_BITS{1'b0}};
    localparam [TIMER_BITS-1:0] TICK_ONE = {{(TIMER_BITS-1){1'b0}}, 1'b1};
    localparam [TIMER_BITS-1:0] PASS_TICKS = WORD_BITS + 1;
    localparam [WORD_BITS:0] RING_SEED = {1'b0, LAYER_SEED};
    localparam [WORD_BITS:0] LAST_PHASE = {RING_SEED[0], RING_SEED[WORD_BITS:1]};

    initial begin
        layer_word = LAYER_SEED;
        carry = 1'b0;
        ticks_left = TICK_ZERO;
        render_pending = 1'b0;
        map_pending = 1'b0;
        window = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Q opens the scope; R closes it, with closing priority.
            if (scope_r)
                window <= 1'b0;
            else if (scope_q)
                window <= 1'b1;

            if (!render_pending && !map_pending) begin
                // Requests are accepted together only while the scanner is idle.
                if (request_render || request_map) begin
                    render_pending <= request_render;
                    map_pending <= request_map;
                    ticks_left <= PASS_TICKS;
                    layer_word <= LAYER_SEED;
                    carry <= 1'b0;
                end
            end else if (ticks_left != TICK_ZERO) begin
                // Rotate the layer mask through its extra carry flip-flop.
                layer_word <= {layer_word[WORD_BITS-2:0], carry};
                carry <= layer_word[WORD_BITS-1];
                ticks_left <= ticks_left - TICK_ONE;

                // This rotation completes one full scan of the ring.
                if ({carry, layer_word} == LAST_PHASE) begin
                    render_pending <= 1'b0;
                    map_pending <= 1'b0;
                end
            end else begin
                // Recover an already-expired context on the following step.
                render_pending <= 1'b0;
                map_pending <= 1'b0;
                layer_word <= LAYER_SEED;
                carry <= 1'b0;
            end
        end
    end

    // Each accepted request must finish within PASS_TICKS enabled clocks.
    always @(posedge clk) begin
        if (window) begin
            assert (!render_pending || (ticks_left != TICK_ZERO));
            assert (!map_pending || (ticks_left != TICK_ZERO));
        end
    end
endmodule

module pipeline_domain_power #(
    parameter [15:0] SEGMENTS = 16'd16,
    parameter [15:0] STEP_CYCLES = 16'd4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire req_valid,
    output wire req_ready,
    input  wire [15:0] req_data,
    output wire [SEGMENTS-16'd1:0] switch_enable,
    output wire pipeline_power_ready
);
    localparam [15:0] CMD_BEGIN = 16'h0001;
    localparam [15:0] CMD_STEP  = 16'h0002;
    localparam [15:0] CMD_END   = 16'h0003;
    localparam [SEGMENTS-16'd1:0] ALL_SWITCHES = {SEGMENTS{1'b1}};
    localparam [SEGMENTS-16'd1:0] FIRST_SWITCH =
        {{(SEGMENTS-16'd1){1'b0}}, 1'b1};

    reg [15:0] segment_index;
    reg [15:0] delay_count;
    reg [SEGMENTS-16'd1:0] switch_chain;
    reg ramp_window;

    initial begin
        segment_index = 16'd0;
        delay_count = 16'd0;
        switch_chain = {SEGMENTS{1'b0}};
        ramp_window = 1'b0;
    end

    // Requests are BEGIN, pacing STEP credits, and END.
    // Back-pressure rejects steps outside an unfinished ramp.
    assign req_ready = i_ce &&
        (((req_data == CMD_BEGIN) && !ramp_window) ||
         ((req_data == CMD_STEP) && ramp_window &&
          (segment_index < SEGMENTS)) ||
         ((req_data == CMD_END) && ramp_window));

    assign switch_enable = switch_chain;
    assign pipeline_power_ready = ramp_window &&
                                  (segment_index == SEGMENTS);

    // All state changes require an accepted request. Missing credits
    // stretch the inter-segment delay; they never shorten it.
    always @(posedge clk) begin
        if (req_valid && req_ready) begin
            case (req_data)
                CMD_BEGIN: begin
                    ramp_window <= 1'b1;
                    segment_index <= 16'd0;
                    delay_count <= 16'd0;
                    switch_chain <= {SEGMENTS{1'b0}};
                end
                CMD_STEP: begin
                    if (delay_count == STEP_CYCLES - 16'd1) begin
                        delay_count <= 16'd0;
                        segment_index <= segment_index + 16'd1;
                        switch_chain <= (switch_chain << 16'd1) |
                                        FIRST_SWITCH;
                    end else begin
                        delay_count <= delay_count + 16'd1;
                    end
                end
                CMD_END: begin
                    ramp_window <= 1'b0;
                    segment_index <= 16'd0;
                    delay_count <= 16'd0;
                    switch_chain <= {SEGMENTS{1'b0}};
                end
                default: begin end
            endcase
        end
    end

    // From accepted BEGIN until accepted END, the final switch agrees
    // with the segment index's indication that the ramp is complete.
    always @(posedge clk)
        assert (!ramp_window ||
                (switch_chain[SEGMENTS-16'd1] ==
                 (segment_index == SEGMENTS)));
endmodule

module rotating_operand_file #(
    parameter integer ENTRIES = 64
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_port_grant,
    input  wire        i_valid,
    output wire        o_ready,
    input  wire [1:0]  i_command,
    input  wire [63:0] i_index,
    input  wire [63:0] i_data,
    output wire [63:0] o_operand,
    output wire [63:0] o_head
);
    localparam [63:0] ENTRY_COUNT = ENTRIES;
    localparam [63:0] LAST_ENTRY = ENTRY_COUNT - 64'd1;
    localparam [1:0] LOAD_MASK = 2'd0;
    localparam [1:0] WRITE_OPERAND = 2'd1;
    localparam [1:0] ADVANCE_LOOP = 2'd2;

    reg [63:0] rf [0:ENTRIES-1];
    reg [63:0] base;
    reg [63:0] head;
    reg [63:0] lookahead;
    reg [63:0] write_mask;
    reg armed;

    initial begin
        base = 64'd0;
        head = 64'd0;
        lookahead = 64'd0;
        write_mask = 64'hffffffffffffffff;
        armed = 1'b0;
    end

    genvar slot;
    generate
        for (slot = 0; slot < ENTRIES; slot = slot + 1) begin : initialize_words
            initial rf[slot] = 64'd0;
        end
    endgenerate

    wire [63:0] next_base =
        (base == LAST_ENTRY) ? 64'd0 : base + 64'd1;
    wire [63:0] next_next_base =
        (next_base == LAST_ENTRY) ? 64'd0 : next_base + 64'd1;

    // Logical operand indices are renamed through the rotating base.
    wire [63:0] logical_slot = i_index % ENTRY_COUNT;
    wire [63:0] address_sum = base + logical_slot;
    wire [63:0] physical_slot =
        (address_sum >= ENTRY_COUNT) ? address_sum - ENTRY_COUNT : address_sum;
    wire [63:0] merged_word =
        (rf[physical_slot] & ~write_mask) | (i_data & write_mask);

    // The shared register-file port applies back-pressure without accepting
    // or dropping commands while its arbiter withholds the grant.
    assign o_ready = i_ce && i_port_grant;
    wire accept = i_valid && o_ready;

    assign o_operand = rf[physical_slot];
    assign o_head = head;

    always @(posedge clk) begin
        if (accept) begin
            case (i_command)
                LOAD_MASK: begin
                    write_mask <= i_data;
                end
                WRITE_OPERAND: begin
                    rf[physical_slot] <= merged_word;
                    if (physical_slot == base)
                        head <= merged_word;
                    if (physical_slot == next_base)
                        lookahead <= merged_word;
                end
                ADVANCE_LOOP: begin
                    base <= next_base;
                    head <= lookahead;
                    lookahead <= rf[next_next_base];
                    armed <= 1'b1;
                end
                default: begin
                end
            endcase
        end
    end

    // After the first loop advance, the cached logical-zero operand agrees
    // with the physical register selected by the rotating base.
    always @(posedge clk)
        if (armed)
            assert (head == rf[base]);
endmodule

module panorama_record_mux_queue #(
    parameter integer DATA_WIDTH = 32,
    parameter integer COUNT_WIDTH = 32,
    parameter integer DEPTH = 16
) (
    input  wire                  clk,
    input  wire                  s_valid,
    output wire                  s_ready,
    input  wire [DATA_WIDTH-1:0] s_record,
    input  wire                  s_camera,
    output wire                  m_valid,
    input  wire                  m_ready,
    output wire [DATA_WIDTH-1:0] m_record,
    output wire                  left_grant,
    output wire                  right_grant
);
    localparam [COUNT_WIDTH-1:0] COUNT_ZERO = {COUNT_WIDTH{1'b0}};
    localparam [COUNT_WIDTH-1:0] COUNT_ONE = {{(COUNT_WIDTH-1){1'b0}}, 1'b1};
    localparam [COUNT_WIDTH-1:0] DEPTH_COUNT = DEPTH;
    localparam integer SELECT_BITS = (DEPTH > 1) ? $clog2(DEPTH) : 1;
    localparam integer LEAVES = 2 ** SELECT_BITS;

    // The upper bits hold a feature record. The low two bits are reserved
    // for the source-camera ownership tag, inserted on acceptance.
    reg [DATA_WIDTH-1:0] records [0:DEPTH-1];
    reg [COUNT_WIDTH-1:0] rd_ptr;
    reg [COUNT_WIDTH-1:0] wr_ptr;
    reg [COUNT_WIDTH-1:0] count;
    reg armed;
    reg past_valid;

    wire push;
    wire pop;
    wire route_collision;
    wire [DEPTH-1:0] occupied;
    wire [DATA_WIDTH-1:0] mux_tree [1:2*LEAVES-1];

    assign s_ready = (count < DEPTH_COUNT);
    assign m_valid = (count != COUNT_ZERO);
    assign push = s_valid && s_ready;
    assign pop = m_valid && m_ready;

    // A binary multiplexer tree selects the complete oldest record.
    genvar leaf;
    generate
        for (leaf = 0; leaf < LEAVES; leaf = leaf + 1) begin : mux_leaves
            if (leaf < DEPTH) begin : real_leaf
                assign mux_tree[LEAVES + leaf] = records[leaf];
            end else begin : padding_leaf
                assign mux_tree[LEAVES + leaf] = {DATA_WIDTH{1'b0}};
            end
        end
    endgenerate

    genvar node;
    generate
        for (node = 1; node < LEAVES; node = node + 1) begin : mux_branches
            localparam integer SELECT_BIT = SELECT_BITS - $clog2(node + 1);
            assign mux_tree[node] = rd_ptr[SELECT_BIT]
                ? mux_tree[2*node + 1] : mux_tree[2*node];
        end
    endgenerate

    assign m_record = mux_tree[1];
    assign left_grant = m_valid && m_record[0];
    assign right_grant = m_valid && m_record[1];
    assign route_collision = left_grant && right_grant;

    // Occupancy is decoded from the circular interval, not counted from bits.
    genvar slot;
    generate
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin : occupancy_decode
            localparam [COUNT_WIDTH-1:0] SLOT_INDEX = slot;
            assign occupied[slot] = (rd_ptr <= SLOT_INDEX)
                ? ((SLOT_INDEX - rd_ptr) < count)
                : ((DEPTH_COUNT - rd_ptr + SLOT_INDEX) < count);
        end
    endgenerate

    integer init_slot;
    initial begin
        rd_ptr = COUNT_ZERO;
        wr_ptr = COUNT_ZERO;
        count = COUNT_ZERO;
        armed = 1'b0;
        past_valid = 1'b0;
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1)
            records[init_slot] = {DATA_WIDTH{1'b0}};
    end

    // With s_valid=0 and m_ready=0, every state element holds its value.
    // A full queue back-pressures the sender, even during a simultaneous pop.
    always @(posedge clk) begin
        if (push) begin
            records[wr_ptr] <= {s_record[DATA_WIDTH-1:2], s_camera, !s_camera};
            wr_ptr <= (wr_ptr == DEPTH_COUNT - COUNT_ONE)
                ? COUNT_ZERO : wr_ptr + COUNT_ONE;
            armed <= 1'b1;
        end
        if (pop) begin
            rd_ptr <= (rd_ptr == DEPTH_COUNT - COUNT_ONE)
                ? COUNT_ZERO : rd_ptr + COUNT_ONE;
        end
        case ({push, pop})
            2'b10: count <= count + COUNT_ONE;
            2'b01: count <= count - COUNT_ONE;
            default: begin end
        endcase
        if (push || pop)
            past_valid <= 1'b1;
    end

    // After the first accepted record, unchanged output validity must not
    // permit a source-ownership collision to appear or persist.
    always @(posedge clk)
        if (past_valid && armed && $stable(m_valid))
            assert ($stable(route_collision) && !route_collision);
endmodule

module sklansky_rail_accumulator #(
    parameter integer WIDTH = 128
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire                 i_ce,
    input  wire                 i_open,
    input  wire                 i_close,
    input  wire [WIDTH-1:0]     i_addend,
    output wire [WIDTH-1:0]     o_value
);
    localparam integer LEVELS = $clog2(WIDTH);

    // Retimed adder output: register the propagate and carry rails
    // separately, placing the final sum XOR after the registers.
    reg [WIDTH-1:0] propagate_q;
    reg [WIDTH-1:0] carry_q;
    reg [WIDTH-1:0] reference_q;
    reg window_q;
    reg pv;

    wire [WIDTH-1:0] prefix_p [0:LEVELS];
    wire [WIDTH-1:0] prefix_g [0:LEVELS];
    wire [WIDTH-1:0] reference_next;

    assign o_value = propagate_q ^ carry_q;
    assign prefix_p[0] = o_value ^ i_addend;
    assign prefix_g[0] = o_value & i_addend;
    assign reference_next = i_ce ? (reference_q + i_addend)
                                : reference_q;

    // Sklansky tree: the lower-half endpoint fans out to every
    // position in the upper half of each progressively larger group.
    genvar level, bit_index;
    generate
        for (level = 0; level < LEVELS; level = level + 1) begin : sklansky_level
            localparam integer HALF_SIZE = (1 << level);
            localparam integer GROUP_SIZE = (HALF_SIZE << 1);
            for (bit_index = 0; bit_index < WIDTH; bit_index = bit_index + 1) begin : column
                if ((bit_index % GROUP_SIZE) >= HALF_SIZE) begin : combine
                    localparam integer PIVOT =
                        (bit_index / GROUP_SIZE) * GROUP_SIZE + HALF_SIZE - 1;
                    assign prefix_p[level+1][bit_index] =
                        prefix_p[level][bit_index] & prefix_p[level][PIVOT];
                    assign prefix_g[level+1][bit_index] =
                        prefix_g[level][bit_index] |
                        (prefix_p[level][bit_index] & prefix_g[level][PIVOT]);
                end else begin : pass_through
                    assign prefix_p[level+1][bit_index] = prefix_p[level][bit_index];
                    assign prefix_g[level+1][bit_index] = prefix_g[level][bit_index];
                end
            end
        end
    endgenerate

    initial begin
        propagate_q = {WIDTH{1'b0}};
        carry_q = {WIDTH{1'b0}};
        reference_q = {WIDTH{1'b0}};
        window_q = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            propagate_q <= {WIDTH{1'b0}};
            carry_q <= {WIDTH{1'b0}};
            reference_q <= {WIDTH{1'b0}};
            window_q <= 1'b0;
            pv <= 1'b0;
        end else if (i_ce) begin
            propagate_q <= prefix_p[0];
            carry_q <= {prefix_g[LEVELS][WIDTH-2:0], 1'b0};
            reference_q <= reference_next;
            pv <= 1'b1;
            if (i_close)
                window_q <= 1'b0;
            else if (i_open)
                window_q <= 1'b1;
        end
    end

    // The armed register relation is expressed using the previous
    // cycle's reference prediction. Past-valid also freezes on idle.
    always @(posedge clk)
        if (pv && window_q)
            assert ((propagate_q[WIDTH-1] ^ carry_q[WIDTH-1]) ==
                    $past(reference_next[WIDTH-1]));
endmodule

module banked_translation_cam #(
    parameter [31:0] ENTRIES = 32'd24,
    parameter [31:0] BANKS = 32'd4
) (
    input  wire        clk,
    input  wire        req_valid,
    output wire        req_ready,
    input  wire        req_insert,
    input  wire [31:0] req_key,
    output wire        rsp_valid,
    input  wire        rsp_ready,
    output reg         rsp_hit,
    output reg         rsp_empty,
    output reg  [31:0] rsp_key
);
    // BANKS is a power of two and ENTRIES is divisible by BANKS.
    localparam [31:0] PER_BANK = ENTRIES / BANKS;
    localparam integer BANK_BITS = (BANKS > 32'd1) ? $clog2(BANKS) : 32'd1;

    typedef enum logic [1:0] {
        IDLE = 2'b00,
        RESP = 2'b01
    } state_t;
    state_t state;

    reg [31:0] bank_key [0:BANKS-1][0:PER_BANK-1];
    reg [PER_BANK-1:0] bank_valid [0:BANKS-1];
    reg [31:0] bank_occupancy [0:BANKS-1];

    reg [31:0] bank_population [0:BANKS-1];
    wire [BANKS-1:0] occupancy_agrees;
    wire [BANKS-1:0] occupancy_in_range;
    wire [BANK_BITS-1:0] selected_bank = req_key[BANK_BITS-1:0];

    reg selected_ok;
    reg lookup_hit;
    reg lookup_empty;
    reg free_found;
    reg [31:0] free_slot;

    initial begin
        state = IDLE;
        rsp_hit = 1'b0;
        rsp_empty = 1'b1;
        rsp_key = 32'd0;
        for (integer b = 32'd0; b < BANKS; b = b + 32'd1) begin
            bank_valid[b] = {PER_BANK{1'b0}};
            bank_occupancy[b] = 32'd0;
            for (integer s = 32'd0; s < PER_BANK; s = s + 32'd1)
                bank_key[b][s] = 32'd0;
        end
    end

    always @(*) begin
        for (integer b = 32'd0; b < BANKS; b = b + 32'd1) begin
            bank_population[b] = 32'd0;
            for (integer s = 32'd0; s < PER_BANK; s = s + 32'd1)
                bank_population[b] = bank_population[b]
                    + (bank_valid[b][s] ? 32'd1 : 32'd0);
        end
    end

    generate
        for (genvar b = 32'd0; b < BANKS; b = b + 32'd1) begin : occupancy_summary
            assign occupancy_agrees[b] =
                (bank_occupancy[b] == bank_population[b]);
            assign occupancy_in_range[b] =
                (bank_occupancy[b] <= PER_BANK);
        end
    endgenerate

    // Only the bank selected by the low key bits participates in the CAM search.
    always @(*) begin
        selected_ok = 1'b0;
        lookup_hit = 1'b0;
        lookup_empty = 1'b1;
        free_found = 1'b0;
        free_slot = 32'd0;
        for (integer b = 32'd0; b < BANKS; b = b + 32'd1) begin
            if (selected_bank == b) begin
                selected_ok = 1'b1;
                lookup_empty = (bank_occupancy[b] == 32'd0);
                for (integer s = 32'd0; s < PER_BANK; s = s + 32'd1) begin
                    if (bank_valid[b][s] && bank_key[b][s] == req_key)
                        lookup_hit = 1'b1;
                    if (!bank_valid[b][s] && !free_found) begin
                        free_found = 1'b1;
                        free_slot = s;
                    end
                end
            end
        end
    end

    // A full bank back-pressures new insertions, but still accepts probes
    // and duplicate insertions. There is one outstanding response.
    assign req_ready = (state == IDLE) && selected_ok
                     && (!req_insert || lookup_hit || free_found);
    assign rsp_valid = (state == RESP);

    // With req_valid and rsp_ready both low, every state register holds.
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (req_valid && req_ready) begin
                    // Response describes the bank before any insertion.
                    rsp_hit <= lookup_hit;
                    rsp_empty <= lookup_empty;
                    rsp_key <= req_key;
                    state <= RESP;
                    if (req_insert && !lookup_hit && free_found) begin
                        bank_valid[selected_bank][free_slot] <= 1'b1;
                        bank_key[selected_bank][free_slot] <= req_key;
                        bank_occupancy[selected_bank] <=
                            bank_occupancy[selected_bank] + 32'd1;
                    end
                end
            end
            RESP: begin
                if (rsp_valid && rsp_ready)
                    state <= IDLE;
            end
            default: begin
                // Unused controller encodings hold their state.
            end
        endcase
    end

    always @(posedge clk)
        if (state == RESP)
            assert (!(rsp_hit && rsp_empty));
endmodule

module scoped_wishbone_intercon #(
    parameter integer MASTERS = 8,
    parameter integer SLAVES = 8,
    parameter integer WORD_BITS = 16,
    parameter integer TIMER_BITS = 16,
    parameter [TIMER_BITS-1:0] SERVICE_TICKS = 16'd8
) (
    input wire i_clk,
    input wire i_ce,
    input wire i_scope_begin,
    input wire i_scope_end,
    input wire [MASTERS-1:0] i_m_cyc,
    input wire [MASTERS-1:0] i_m_stb,
    input wire [MASTERS-1:0] i_m_we,
    input wire [MASTERS*WORD_BITS-1:0] i_m_addr,
    input wire [MASTERS*WORD_BITS-1:0] i_m_wdata,
    output wire [MASTERS-1:0] o_m_ack,
    output wire [MASTERS*WORD_BITS-1:0] o_m_rdata,
    output wire [SLAVES-1:0] o_s_cyc,
    output wire [SLAVES-1:0] o_s_stb,
    output wire [WORD_BITS-1:0] o_bus_addr,
    output wire [WORD_BITS-1:0] o_bus_wdata,
    output wire o_bus_we,
    output wire o_deadline_miss
);
    localparam integer OWNER_BITS = (MASTERS > 1) ? $clog2(MASTERS) : 1;
    localparam integer SLAVE_BITS = (SLAVES > 1) ? $clog2(SLAVES) : 1;
    localparam [TIMER_BITS-1:0] TIMER_ZERO = {TIMER_BITS{1'b0}};
    localparam [TIMER_BITS-1:0] TIMER_ONE = {{(TIMER_BITS-1){1'b0}}, 1'b1};
    localparam [TIMER_BITS-1:0] LAST_TICK = SERVICE_TICKS - TIMER_ONE;

    typedef enum logic [1:0] {
        ARBITRATE  = 2'b00,
        WAIT_ACK   = 2'b01,
        HOLD_CYCLE = 2'b10
    } state_t;

    state_t state;
    reg cycle_active;
    reg [OWNER_BITS-1:0] owner;
    reg [SLAVE_BITS-1:0] slave_sel;
    reg [WORD_BITS-1:0] request_addr;
    reg [WORD_BITS-1:0] request_data;
    reg request_write;
    reg [TIMER_BITS-1:0] elapsed;
    reg [TIMER_BITS-1:0] deadline;
    reg scope_open;

    // Eight default register slaves share one fixed-latency service path.
    reg [WORD_BITS-1:0] slave_words [0:SLAVES-1];
    wire [SLAVES-1:0] slave_ack;
    wire shared_ack = |slave_ack;

    initial begin
        state = ARBITRATE;
        cycle_active = 1'b0;
        owner = {OWNER_BITS{1'b0}};
        slave_sel = {SLAVE_BITS{1'b0}};
        request_addr = {WORD_BITS{1'b0}};
        request_data = {WORD_BITS{1'b0}};
        request_write = 1'b0;
        elapsed = TIMER_ZERO;
        deadline = TIMER_ZERO;
        scope_open = 1'b0;
    end

    reg grant_valid;
    reg [OWNER_BITS-1:0] grant_owner;
    integer m;
    always @(*) begin
        grant_valid = 1'b0;
        grant_owner = {OWNER_BITS{1'b0}};
        for (m = 0; m < MASTERS; m = m + 1) begin
            if (!grant_valid && i_m_cyc[m] && i_m_stb[m]) begin
                grant_valid = 1'b1;
                grant_owner = OWNER_BITS'(m);
            end
        end
    end

    wire take_new = ((state == ARBITRATE) && grant_valid) ||
                    ((state == HOLD_CYCLE) && i_m_cyc[owner] && i_m_stb[owner]);
    wire [OWNER_BITS-1:0] accepting_owner =
        (state == ARBITRATE) ? grant_owner : owner;

    assign o_bus_addr = request_addr;
    assign o_bus_wdata = request_data;
    assign o_bus_we = request_write;
    assign o_deadline_miss = (state == WAIT_ACK) && (deadline == TIMER_ZERO);

    genvar s;
    generate
        for (s = 0; s < SLAVES; s = s + 1) begin : register_slaves
            initial slave_words[s] = {WORD_BITS{1'b0}};
            assign o_s_cyc[s] = cycle_active && i_m_cyc[owner] &&
                                (slave_sel == SLAVE_BITS'(s));
            assign o_s_stb[s] = o_s_cyc[s] && (state == WAIT_ACK);
            assign slave_ack[s] = o_s_stb[s] && (elapsed == LAST_TICK);
        end
    endgenerate

    genvar p;
    generate
        for (p = 0; p < MASTERS; p = p + 1) begin : master_returns
            assign o_m_ack[p] = i_ce && cycle_active &&
                                (owner == OWNER_BITS'(p)) && shared_ack;
            assign o_m_rdata[p*WORD_BITS +: WORD_BITS] =
                (cycle_active && (owner == OWNER_BITS'(p))) ?
                slave_words[slave_sel] : {WORD_BITS{1'b0}};
        end
    endgenerate

    always @(posedge i_clk) begin
        if (i_ce) begin
            // A repeatable, latched between-events observation window.
            if (i_scope_end)
                scope_open <= 1'b0;
            else if (i_scope_begin)
                scope_open <= 1'b1;

            case (state)
                ARBITRATE: begin
                    if (grant_valid) begin
                        owner <= grant_owner;
                        cycle_active <= 1'b1;
                        state <= WAIT_ACK;
                    end
                end

                WAIT_ACK: begin
                    if (!i_m_cyc[owner]) begin
                        // Dropping CYC cancels the outstanding access.
                        cycle_active <= 1'b0;
                        state <= ARBITRATE;
                        elapsed <= TIMER_ZERO;
                        deadline <= TIMER_ZERO;
                    end else if (shared_ack) begin
                        if (request_write)
                            slave_words[slave_sel] <= request_data;
                        state <= HOLD_CYCLE;
                        elapsed <= TIMER_ZERO;
                        deadline <= TIMER_ZERO;
                    end else begin
                        elapsed <= elapsed + TIMER_ONE;
                        deadline <= deadline - TIMER_ONE;
                    end
                end

                HOLD_CYCLE: begin
                    // The current owner retains the bus throughout CYC,
                    // including gaps between its individual transfers.
                    if (!i_m_cyc[owner]) begin
                        cycle_active <= 1'b0;
                        state <= ARBITRATE;
                    end else if (i_m_stb[owner]) begin
                        state <= WAIT_ACK;
                    end
                end
            endcase

            if (take_new) begin
                request_addr <= i_m_addr[accepting_owner*WORD_BITS +: WORD_BITS];
                request_data <= i_m_wdata[accepting_owner*WORD_BITS +: WORD_BITS];
                request_write <= i_m_we[accepting_owner];
                slave_sel <= SLAVE_BITS'(
                    i_m_addr[accepting_owner*WORD_BITS +: WORD_BITS] % SLAVES);
                elapsed <= TIMER_ZERO;
                deadline <= SERVICE_TICKS;
            end
        end
    end

    // An accepted, uncancelled request completes within SERVICE_TICKS
    // enabled service cycles; its deadline cannot expire while outstanding.
    always @(*) begin
        if (scope_open && (state == WAIT_ACK))
            assert (deadline != TIMER_ZERO);
    end
endmodule

module masked_pipe_dispatch #(
    parameter integer DATA_W = 64,
    parameter integer CHANNELS = 16
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  write_mask,
    input  wire [DATA_W-1:0]     mask_data,
    input  wire                  dispatch,
    input  wire                  end_window,
    output reg  [DATA_W-1:0]     issued_count,
    output reg  [DATA_W-1:0]     last_index,
    output reg                   last_valid
);
    // Supported configurations have 1 <= CHANNELS <= DATA_W.
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] CAPACITY = DATA_W'(CHANNELS);
    localparam [DATA_W-1:0] CHANNEL_BITS =
        {DATA_W{1'b1}} >> (DATA_W - CHANNELS);

    // Each channel initially has one pending notification.
    reg [DATA_W-1:0] pending;
    reg [DATA_W-1:0] sw_mask;
    reg before_window_end;
    reg past_valid;

    // Lowest numbered enabled request has highest priority.
    function automatic [DATA_W-1:0] priority_index(
        input [DATA_W-1:0] bits
    );
        integer j;
        begin
            priority_index = ZERO;
            for (j = CHANNELS - 1; j >= 0; j = j - 1)
                if (bits[j])
                    priority_index = DATA_W'(j);
        end
    endfunction

    wire [DATA_W-1:0] eligible = pending & sw_mask;
    wire [DATA_W-1:0] encoded_index = priority_index(eligible);

    // Mask writes take priority over dispatch commands.
    wire take = dispatch && last_valid && !write_mask;
    wire [DATA_W-1:0] next_mask =
        write_mask ? (mask_data & CHANNEL_BITS) : sw_mask;
    wire [DATA_W-1:0] next_pending =
        take ? (pending & ~(ONE << last_index)) : pending;
    wire [DATA_W-1:0] next_eligible = next_pending & next_mask;

    reg [DATA_W-1:0] pending_population;
    integer p;
    always @(*) begin
        pending_population = ZERO;
        for (p = 0; p < CHANNELS; p = p + 1)
            pending_population = pending_population +
                {{(DATA_W-1){1'b0}}, pending[p]};
    end

    initial begin
        pending = CHANNEL_BITS;
        sw_mask = CHANNEL_BITS;
        issued_count = ZERO;
        last_index = ZERO;
        last_valid = 1'b1;
        before_window_end = 1'b1;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            pending <= next_pending;
            sw_mask <= next_mask;
            last_index <= priority_index(next_eligible);
            last_valid <= (next_eligible != ZERO);
            if (take)
                issued_count <= issued_count + ONE;
            if (end_window)
                before_window_end <= 1'b0;
            past_valid <= 1'b1;
        end
    end

    // Before the first enabled end_window event, an unchanged request
    // set means no additional dispatches, and the batch budget holds.
    always @(posedge clk)
        if (past_valid && before_window_end && $stable(pending))
            assert ($stable(issued_count) && issued_count <= CAPACITY);
endmodule

module timing_marker_compare #(
    parameter integer WORD_W = 64
) (
    input  wire                  clk,
    input  wire                  cmd_valid,
    output wire                  cmd_ready,
    input  wire [1:0]            cmd_op,
    input  wire [WORD_W-1:0]     cmd_compare,
    input  wire [WORD_W-1:0]     cmd_mode,
    output reg                   rsp_valid,
    input  wire                  rsp_ready,
    output reg  [WORD_W-1:0]     rsp_data,
    output reg                   pin_out,
    output reg                   set_strobe,
    output reg                   clear_strobe
);
    localparam [1:0] CMD_CONFIG = 2'b00;
    localparam [1:0] CMD_STEP   = 2'b01;
    localparam [1:0] CMD_OPEN   = 2'b10;
    localparam [1:0] CMD_CLOSE  = 2'b11;

    localparam [WORD_W-1:0] ZERO        = WORD_W'(0);
    localparam [WORD_W-1:0] ONE         = WORD_W'(1);
    localparam [WORD_W-1:0] MODE_OFF    = WORD_W'(0);
    localparam [WORD_W-1:0] MODE_SET    = WORD_W'(1);
    localparam [WORD_W-1:0] MODE_CLEAR  = WORD_W'(2);
    localparam [WORD_W-1:0] MODE_TOGGLE = WORD_W'(3);

    reg [WORD_W-1:0] timer_count;
    reg [WORD_W-1:0] compare_value;
    reg [WORD_W-1:0] action_mode;
    reg decode_set;
    reg decode_clear;
    reg decode_toggle;
    reg window_open;

    // A pending timestamp response back-pressures the command receiver.
    assign cmd_ready = !rsp_valid || rsp_ready;

    initial begin
        timer_count   = ZERO;
        compare_value = ZERO;
        action_mode   = MODE_OFF;
        decode_set    = 1'b0;
        decode_clear  = 1'b0;
        decode_toggle = 1'b0;
        window_open   = 1'b0;
        pin_out       = 1'b0;
        set_strobe    = 1'b0;
        clear_strobe  = 1'b0;
        rsp_valid     = 1'b0;
        rsp_data      = ZERO;
    end

    // Every accepted command produces a timestamp response. All command
    // state changes require cmd_valid && cmd_ready. Holding cmd_valid and
    // rsp_ready low leaves every state register unchanged.
    always @(posedge clk) begin
        if (cmd_ready) begin
            rsp_valid <= cmd_valid;
            if (cmd_valid) begin
                rsp_data     <= timer_count;
                set_strobe   <= 1'b0;
                clear_strobe <= 1'b0;

                case (cmd_op)
                    CMD_CONFIG: begin
                        compare_value <= cmd_compare;
                        action_mode <= (cmd_mode <= MODE_TOGGLE)
                                     ? cmd_mode : MODE_OFF;
                        // Registered predecode feeds the compare-action path.
                        decode_set    <= (cmd_mode == MODE_SET);
                        decode_clear  <= (cmd_mode == MODE_CLEAR);
                        decode_toggle <= (cmd_mode == MODE_TOGGLE);
                    end

                    CMD_STEP: begin
                        timer_count <= timer_count + ONE;
                        if (timer_count == compare_value) begin
                            set_strobe   <= decode_set;
                            clear_strobe <= decode_clear;
                            if (decode_set)
                                pin_out <= 1'b1;
                            if (decode_clear)
                                pin_out <= 1'b0;
                            if (decode_toggle)
                                pin_out <= !pin_out;
                        end
                    end

                    CMD_OPEN:  window_open <= 1'b1;
                    CMD_CLOSE: window_open <= 1'b0;
                endcase
            end
        end
    end

    // Between accepted OPEN and CLOSE commands, opposing compare actions
    // must never be asserted together.
    assert property (!window_open || !(set_strobe && clear_strobe));
endmodule

module regional_congestion_monitor #(
    parameter integer PORTS = 4,
    parameter integer WORD_W = 32,
    parameter integer LOCAL_DEPTH = 4
) (
    input  wire                         clk,
    input  wire                         i_enable,
    input  wire                         i_valid,
    output wire                         o_ready,
    input  wire                         i_epoch_end,
    input  wire [PORTS*WORD_W-1:0]      i_local_occupancy,
    input  wire [PORTS*WORD_W-1:0]      i_neighbor_congestion,
    output wire [PORTS*WORD_W-1:0]      o_congestion
);
    localparam [WORD_W-1:0] LOCAL_LIMIT = LOCAL_DEPTH;
    localparam [WORD_W-1:0] REGIONAL_LIMIT = LOCAL_LIMIT + LOCAL_LIMIT;

    reg [WORD_W-1:0] local_filter [0:PORTS-1];
    reg [WORD_W-1:0] neighbor_filter [0:PORTS-1];
    reg [WORD_W-1:0] regional_occupancy [0:PORTS-1];
    reg pv = 1'b0;
    reg before_epoch_end = 1'b1;

    wire accept;
    wire [PORTS-1:0] component_bounds;
    wire [PORTS-1:0] aggregation_matches;
    wire [PORTS-1:0] metric_in_range;

    // A disabled filtering engine applies back-pressure to its sender.
    // Nothing is consumed, and every register holds, unless accept is high.
    assign o_ready = i_enable;
    assign accept = i_valid && o_ready;

    always @(posedge clk) begin
        if (accept) begin
            pv <= 1'b1;
            if (i_epoch_end)
                before_epoch_end <= 1'b0;
        end
    end

    genvar p;
    generate
        for (p = 0; p < PORTS; p = p + 1) begin : direction
            wire [WORD_W-1:0] local_sample;
            wire [WORD_W-1:0] neighbor_sample;
            wire [WORD_W-1:0] capped_local;
            wire [WORD_W-1:0] capped_neighbor;
            wire [WORD_W:0] local_sum;
            wire [WORD_W:0] neighbor_sum;
            wire [WORD_W-1:0] next_local;
            wire [WORD_W-1:0] next_neighbor;
            wire [WORD_W:0] next_regional_sum;

            assign local_sample = i_local_occupancy[p*WORD_W +: WORD_W];
            assign neighbor_sample = i_neighbor_congestion[p*WORD_W +: WORD_W];
            assign capped_local = (local_sample > LOCAL_LIMIT)
                                ? LOCAL_LIMIT : local_sample;
            assign capped_neighbor = (neighbor_sample > LOCAL_LIMIT)
                                   ? LOCAL_LIMIT : neighbor_sample;

            // Independently filter the two occupancy contributions, then
            // aggregate them into the registered per-direction metric.
            assign local_sum = {1'b0, local_filter[p]} + {1'b0, capped_local};
            assign neighbor_sum = {1'b0, neighbor_filter[p]} + {1'b0, capped_neighbor};
            assign next_local = local_sum[WORD_W:1];
            assign next_neighbor = neighbor_sum[WORD_W:1];
            assign next_regional_sum = {1'b0, next_local} + {1'b0, next_neighbor};

            initial begin
                local_filter[p] = {WORD_W{1'b0}};
                neighbor_filter[p] = {WORD_W{1'b0}};
                regional_occupancy[p] = {WORD_W{1'b0}};
            end

            always @(posedge clk) begin
                if (accept) begin
                    local_filter[p] <= next_local;
                    neighbor_filter[p] <= next_neighbor;
                    regional_occupancy[p] <= next_regional_sum[WORD_W-1:0];
                end
            end

            assign o_congestion[p*WORD_W +: WORD_W] = regional_occupancy[p];
            assign component_bounds[p] =
                (local_filter[p] <= LOCAL_LIMIT) &&
                (neighbor_filter[p] <= LOCAL_LIMIT);
            assign aggregation_matches[p] =
                ({1'b0, regional_occupancy[p]} ==
                 ({1'b0, local_filter[p]} + {1'b0, neighbor_filter[p]}));
            assign metric_in_range[p] =
                (regional_occupancy[p] <= REGIONAL_LIMIT);
        end
    endgenerate

    // Before the first accepted epoch-end event, every direction's
    // previous-cycle filtered regional occupancy is at most eight.
    always @(posedge clk)
        if (pv && before_epoch_end)
            assert (&$past(metric_in_range));
endmodule

module rotation_coefficient_register #(
    parameter integer BYTE_LANES = 8
) (
    input  wire                        clk,
    input  wire                        rst_n,
    input  wire                        i_ce,
    input  wire                        i_write,
    input  wire [BYTE_LANES-1:0]       i_byte_en,
    input  wire [8*BYTE_LANES-1:0]     i_write_data,
    input  wire                        window_open,
    input  wire                        window_close,
    output reg  [8*BYTE_LANES-1:0]     coefficient_word,
    output reg  [63:0]                 nonzero_bytes,
    output reg                         window
);
    localparam integer WORD_BITS = 8 * BYTE_LANES;
    localparam [63:0] BYTE_LIMIT = BYTE_LANES;

    wire [WORD_BITS-1:0] merged_word;

    genvar lane;
    generate
        for (lane = 0; lane < BYTE_LANES; lane = lane + 1) begin : byte_merge
            assign merged_word[8*lane +: 8] =
                (i_write && i_byte_en[lane])
                ? i_write_data[8*lane +: 8]
                : coefficient_word[8*lane +: 8];
        end
    endgenerate

    function automatic [63:0] populated_byte_count(
        input [WORD_BITS-1:0] word_value
    );
        integer b;
        begin
            populated_byte_count = 64'd0;
            for (b = 0; b < BYTE_LANES; b = b + 1)
                populated_byte_count = populated_byte_count +
                    ((word_value[8*b +: 8] != 8'h00) ? 64'd1 : 64'd0);
        end
    endfunction

    wire [63:0] stored_population;
    wire [63:0] merged_population;
    assign stored_population = populated_byte_count(coefficient_word);
    assign merged_population = populated_byte_count(merged_word);

    initial begin
        coefficient_word = {WORD_BITS{1'b0}};
        nonzero_bytes = 64'd0;
        window = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            coefficient_word <= {WORD_BITS{1'b0}};
            nonzero_bytes <= 64'd0;
            window <= 1'b0;
        end else if (i_ce) begin
            coefficient_word <= merged_word;
            nonzero_bytes <= nonzero_bytes + merged_population - stored_population;
            if (window_close)
                window <= 1'b0;
            else if (window_open)
                window <= 1'b1;
        end
    end

    always @(*) begin
        if (window)
            assert (nonzero_bytes <= BYTE_LIMIT);
    end
endmodule

module channel_split_counter #(
    parameter SEGMENT_W = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       i_ce,
    input  wire                       i_frame_end,
    output wire [(2*SEGMENT_W)-1:0]    o_split_count,
    output wire [SEGMENT_W-1:0]        o_block_epoch
);
    localparam [SEGMENT_W-1:0] ZERO = {SEGMENT_W{1'b0}};
    localparam [SEGMENT_W-1:0] ONE  = {{(SEGMENT_W-1){1'b0}}, 1'b1};
    localparam [SEGMENT_W-1:0] MAX  = {SEGMENT_W{1'b1}};

    reg [SEGMENT_W-1:0] low_count;
    reg [SEGMENT_W-1:0] high_count;
    reg [SEGMENT_W-1:0] block_epoch;
    reg carry_pipe;
    reg before_first_frame_end;

    initial begin
        low_count = ZERO;
        high_count = ZERO;
        block_epoch = ZERO;
        carry_pipe = 1'b0;
        before_first_frame_end = 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            low_count <= ZERO;
            high_count <= ZERO;
            block_epoch <= ZERO;
            carry_pipe <= 1'b0;
            before_first_frame_end <= 1'b1;
        end else if (i_ce) begin
            // The upper segment consumes the preceding enabled cycle's carry.
            low_count <= low_count + ONE;
            high_count <= high_count + {{(SEGMENT_W-1){1'b0}}, carry_pipe};
            carry_pipe <= (low_count == MAX);

            // The formatter records each completed low-segment block immediately.
            if (low_count == MAX)
                block_epoch <= block_epoch + ONE;

            // A frame-end event is accepted only on an enabled cycle.
            if (i_frame_end)
                before_first_frame_end <= 1'b0;
        end
    end

    assign o_split_count = {high_count, low_count};
    assign o_block_epoch = block_epoch;

    assert property (!before_first_frame_end ||
                     (low_count == ZERO) ||
                     (high_count == block_epoch));
endmodule

module tile_completion_ring #(
    parameter integer RING_ENTRIES = 16,
    parameter [7:0] RING_BASE = 8'h80
) (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       transfer_done,
    input  wire [7:0] transfer_status,
    input  wire [7:0] transferred_length,
    input  wire [7:0] host_slot,
    output wire [7:0] host_status,
    output wire [7:0] host_length,
    output reg  [7:0] ring_base,
    output reg  [7:0] ring_size,
    output reg  [7:0] producer_index,
    output reg  [7:0] last_write_address,
    output reg  [7:0] last_write_status,
    output reg  [7:0] last_write_length
);
    // Supported ring configurations have 2 through 16 entries.
    // Each completion record contains two eight-bit words.
    localparam [7:0] ENTRY_COUNT = RING_ENTRIES;

    reg [7:0] status_ring [0:RING_ENTRIES-1];
    reg [7:0] length_ring [0:RING_ENTRIES-1];
    reg [7:0] next_producer;
    reg       pending_valid;
    reg [7:0] pending_status;
    reg [7:0] pending_length;
    reg       past_valid;

    initial begin
        ring_base          = RING_BASE;
        ring_size          = ENTRY_COUNT;
        producer_index     = 8'd0;
        next_producer      = 8'd1;
        pending_valid      = 1'b0;
        pending_status     = 8'd0;
        pending_length     = 8'd0;
        last_write_address = RING_BASE;
        last_write_status  = 8'd0;
        last_write_length  = 8'd0;
        past_valid         = 1'b0;
    end

    genvar slot;
    generate
        for (slot = 0; slot < RING_ENTRIES; slot = slot + 1) begin : init_slots
            initial begin
                status_ring[slot] = 8'd0;
                length_ring[slot] = 8'd0;
            end
        end
    endgenerate

    wire [7:0] following_producer =
        (next_producer == (ring_size - 8'd1))
        ? 8'd0 : (next_producer + 8'd1);
    wire [7:0] write_address =
        ring_base + (producer_index << 8'd1);

    // Host reads do not affect the writer. No ready/acknowledge is used.
    assign host_status = (host_slot < ring_size)
                       ? status_ring[host_slot] : 8'd0;
    assign host_length = (host_slot < ring_size)
                       ? length_ring[host_slot] : 8'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;

            // Retire the pending transfer into the host-visible ring.
            if (pending_valid) begin
                status_ring[producer_index] <= pending_status;
                length_ring[producer_index] <= pending_length;
                last_write_address <= write_address;
                last_write_status  <= pending_status;
                last_write_length  <= pending_length;
                producer_index     <= next_producer;
                next_producer      <= following_producer;
            end

            // Capture the next completion; capture and retirement may overlap.
            pending_valid <= transfer_done;
            if (transfer_done) begin
                pending_status <= transfer_status;
                pending_length <= transferred_length;
            end
        end
    end

    always @(posedge clk) begin
        if (past_valid && $stable(producer_index))
            assert ($stable({last_write_address, last_write_status,
                             last_write_length}));
    end
endmodule

module axi_write_order_queue #(
    parameter integer DEPTH = 8,
    parameter integer PORTS = 8,
    parameter integer WORD_W = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_awvalid,
    input  wire [WORD_W-1:0]     i_awport,
    output wire                  o_awready,
    input  wire                  i_wvalid,
    input  wire [WORD_W-1:0]     i_wdata,
    input  wire                  i_wlast,
    output wire                  o_wready,
    input  wire [PORTS-1:0]      i_port_ready,
    output wire [PORTS-1:0]      o_port_valid,
    output wire [WORD_W-1:0]     o_port_data,
    output wire                  o_port_last,
    output wire [WORD_W-1:0]     o_route_port
);
    localparam logic [WORD_W-1:0] WORD_ZERO = {WORD_W{1'b0}};
    localparam logic [WORD_W-1:0] WORD_ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam logic [WORD_W-1:0] QUEUE_LIMIT = WORD_W'(DEPTH);
    localparam logic [WORD_W-1:0] PORT_LIMIT = WORD_W'(PORTS);
    localparam logic [DEPTH-1:0] EMPTY_MASK = {DEPTH{1'b0}};
    localparam logic [DEPTH-1:0] HEAD_MASK = {{(DEPTH-1){1'b0}}, 1'b1};

    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        ARMED  = 2'b01,
        ACTIVE = 2'b10
    } phase_t;
    typedef enum logic [1:0] {
        EV_NONE   = 2'b00,
        EV_ARM    = 2'b01,
        EV_START  = 2'b10,
        EV_FINISH = 2'b11
    } event_t;

    phase_t phase;
    event_t event_kind;
    logic [WORD_W-1:0] count;
    logic [WORD_W-1:0] destinations [0:DEPTH-1];
    logic [DEPTH-1:0] arm_bits;
    logic [DEPTH-1:0] start_bits;
    logic scope_armed;
    logic event_had_arm;
    logic event_had_start;

    wire [DEPTH-1:0] occupied_mask;
    wire [DEPTH-1:0] port_in_range;
    wire [PORTS-1:0] port_select;
    wire aw_fire;
    wire finish_fire;

    initial begin
        phase = IDLE;
        event_kind = EV_NONE;
        count = WORD_ZERO;
        arm_bits = EMPTY_MASK;
        start_bits = EMPTY_MASK;
        scope_armed = 1'b0;
        event_had_arm = 1'b0;
        event_had_start = 1'b0;
    end

    generate
        for (genvar g = 0; g < DEPTH; g = g + 1) begin : entries
            initial destinations[g] = WORD_ZERO;
            assign occupied_mask[g] = count > WORD_W'(g);
            assign port_in_range[g] = destinations[g] < PORT_LIMIT;
        end
        for (genvar p = 0; p < PORTS; p = p + 1) begin : routing
            assign port_select[p] = destinations[0] == WORD_W'(p);
            assign o_port_valid[p] = i_ce && (phase == ACTIVE)
                                  && i_wvalid && port_select[p];
        end
    endgenerate

    assign o_route_port = destinations[0];
    assign o_port_data = i_wdata;
    assign o_port_last = i_wlast;
    assign o_wready = i_ce && (phase == ACTIVE)
                    && (|(port_select & i_port_ready));
    assign finish_fire = i_wvalid && o_wready && i_wlast;

    // Address acceptance is serialized against route startup and retirement.
    assign o_awready = i_ce && (count < QUEUE_LIMIT)
                     && (i_awport < PORT_LIMIT)
                     && (phase != ARMED) && !finish_fire;
    assign aw_fire = i_awvalid && o_awready;

    always @(posedge clk) begin
        if (i_ce) begin
            event_kind <= EV_NONE;
            event_had_arm <= 1'b0;
            event_had_start <= 1'b0;

            case (phase)
                IDLE: begin
                    if (count != WORD_ZERO)
                        phase <= ARMED;
                end
                ARMED: begin
                    // Start the head's routing context before accepting W beats.
                    phase <= ACTIVE;
                    start_bits <= HEAD_MASK;
                    event_kind <= EV_START;
                    event_had_arm <= arm_bits[0];
                end
                ACTIVE: begin
                    if (finish_fire) begin
                        phase <= IDLE;
                        count <= count - WORD_ONE;
                        arm_bits <= arm_bits >> 1'b1;
                        start_bits <= EMPTY_MASK;
                        for (integer j = 0; j < DEPTH-1; j = j + 1)
                            destinations[j] <= destinations[j+1];
                        destinations[DEPTH-1] <= WORD_ZERO;
                        event_kind <= EV_FINISH;
                        event_had_arm <= arm_bits[0];
                        event_had_start <= start_bits[0];
                    end
                end
                default: phase <= IDLE;
            endcase

            if (aw_fire) begin
                destinations[count] <= i_awport;
                arm_bits[count] <= 1'b1;
                start_bits[count] <= 1'b0;
                count <= count + WORD_ONE;
                scope_armed <= 1'b1;
                event_kind <= EV_ARM;
                event_had_arm <= 1'b1;
                event_had_start <= 1'b0;
            end
        end
    end

    // After the first AW acceptance: arm precedes start, and both precede finish.
    always @(posedge clk)
        assert (!scope_armed ||
                (((event_kind != EV_START) || event_had_arm) &&
                 ((event_kind != EV_FINISH) ||
                  (event_had_arm && event_had_start))));
endmodule

module program_route_allocator #(
    parameter integer INPUTS = 32'd4,
    parameter integer OUTPUTS = 32'd4,
    parameter integer DATA_BITS = 32'd32
) (
    input  wire clk,
    input  wire [INPUTS-1:0] in_valid,
    output reg  [INPUTS-1:0] in_ready,
    input  wire [INPUTS*OUTPUTS-1:0] in_request,
    input  wire [INPUTS*DATA_BITS-1:0] in_data,
    input  wire [INPUTS-1:0] in_begin,
    input  wire [INPUTS-1:0] in_end,
    output wire out_valid,
    input  wire out_ready,
    output wire [DATA_BITS-1:0] out_data,
    output wire [INPUTS*OUTPUTS-1:0] out_pair,
    output wire out_begin,
    output wire out_end
);
    localparam integer PTR_BITS = 32'd32;
    localparam integer PAIRS = INPUTS * OUTPUTS;
    localparam [PTR_BITS-1:0] INPUT_COUNT = INPUTS;
    localparam [PTR_BITS-1:0] OUTPUT_COUNT = OUTPUTS;

    // Each slice is the round-robin pointer of one arbiter.
    reg [INPUTS*PTR_BITS-1:0] input_rr;
    reg [OUTPUTS*PTR_BITS-1:0] output_rr;
    wire [INPUTS-1:0] input_rr_ok;
    wire [OUTPUTS-1:0] output_rr_ok;

    genvar gi, go;
    generate
        for (gi = 32'd0; gi < INPUTS; gi = gi + 32'd1) begin : input_bounds
            assign input_rr_ok[gi] =
                input_rr[gi*PTR_BITS +: PTR_BITS] < OUTPUT_COUNT;
        end
        for (go = 32'd0; go < OUTPUTS; go = go + 32'd1) begin : output_bounds
            assign output_rr_ok[go] =
                output_rr[go*PTR_BITS +: PTR_BITS] < INPUT_COUNT;
        end
    endgenerate

    // Virtual programming destinations share one elastic physical link.
    // There is exactly one payload storage slot, not a multi-item memory.
    reg slot_valid;
    reg [DATA_BITS-1:0] slot_data;
    reg slot_begin, slot_end;
    reg [PAIRS-1:0] slot_grant;
    reg [PAIRS-1:0] slot_nomination;
    reg [PAIRS-1:0] slot_request_history;

    // Retained audit record of the most recent completed delivery.
    reg receipt_valid;
    reg [PAIRS-1:0] receipt_grant;
    reg [PAIRS-1:0] receipt_request_history;
    reg window;

    reg [PAIRS-1:0] eligible_requests;
    reg [PAIRS-1:0] nominations;
    reg [PAIRS-1:0] output_winners;
    reg [PAIRS-1:0] chosen_grant;
    reg chosen_valid;
    reg [DATA_BITS-1:0] chosen_data;
    reg chosen_begin, chosen_end;
    reg [PTR_BITS-1:0] selected_input, selected_output;
    reg [PTR_BITS-1:0] probe;
    reg found;
    integer i, o, k;

    wire take_in = chosen_valid && (!slot_valid || out_ready);
    wire take_out = slot_valid && out_ready;

    assign out_valid = slot_valid;
    assign out_data = slot_data;
    assign out_pair = slot_grant;
    assign out_begin = slot_begin;
    assign out_end = slot_end;

    always @(*) begin
        eligible_requests = {PAIRS{1'b0}};
        nominations = {PAIRS{1'b0}};
        output_winners = {PAIRS{1'b0}};
        chosen_grant = {PAIRS{1'b0}};
        chosen_valid = 1'b0;
        chosen_data = {DATA_BITS{1'b0}};
        chosen_begin = 1'b0;
        chosen_end = 1'b0;
        selected_input = 32'd0;
        selected_output = 32'd0;
        probe = 32'd0;
        found = 1'b0;
        in_ready = {INPUTS{1'b0}};

        for (i = 32'd0; i < INPUTS; i = i + 32'd1) begin
            for (o = 32'd0; o < OUTPUTS; o = o + 32'd1) begin
                eligible_requests[i*OUTPUTS+o] =
                    in_valid[i] && in_request[i*OUTPUTS+o];
            end
        end

        // Stage one: each input nominates at most one requested output.
        for (i = 32'd0; i < INPUTS; i = i + 32'd1) begin
            found = 1'b0;
            for (k = 32'd0; k < OUTPUTS; k = k + 32'd1) begin
                probe = input_rr[i*PTR_BITS +: PTR_BITS] + k;
                if (probe >= OUTPUT_COUNT)
                    probe = probe - OUTPUT_COUNT;
                if (!found && (probe < OUTPUT_COUNT)) begin
                    if (eligible_requests[i*OUTPUTS+probe]) begin
                        nominations[i*OUTPUTS+probe] = 1'b1;
                        found = 1'b1;
                    end
                end
            end
        end

        // Stage two: each output arbitrates among its input nominations.
        for (o = 32'd0; o < OUTPUTS; o = o + 32'd1) begin
            found = 1'b0;
            for (k = 32'd0; k < INPUTS; k = k + 32'd1) begin
                probe = output_rr[o*PTR_BITS +: PTR_BITS] + k;
                if (probe >= INPUT_COUNT)
                    probe = probe - INPUT_COUNT;
                if (!found && (probe < INPUT_COUNT)) begin
                    if (nominations[probe*OUTPUTS+o]) begin
                        output_winners[probe*OUTPUTS+o] = 1'b1;
                        found = 1'b1;
                    end
                end
            end
        end

        // Serialize the matching onto the shared egress link. Unselected
        // winners are not consumed and their input ready remains low.
        for (o = 32'd0; o < OUTPUTS; o = o + 32'd1) begin
            for (i = 32'd0; i < INPUTS; i = i + 32'd1) begin
                if (!chosen_valid && output_winners[i*OUTPUTS+o]) begin
                    chosen_valid = 1'b1;
                    chosen_grant[i*OUTPUTS+o] = 1'b1;
                    chosen_data = in_data[i*DATA_BITS +: DATA_BITS];
                    chosen_begin = in_begin[i];
                    chosen_end = in_end[i];
                    selected_input = i;
                    selected_output = o;
                end
            end
        end
        if (chosen_valid && (!slot_valid || out_ready))
            in_ready[selected_input] = 1'b1;
    end

    initial begin
        input_rr = {(INPUTS*PTR_BITS){1'b0}};
        output_rr = {(OUTPUTS*PTR_BITS){1'b0}};
        slot_valid = 1'b0;
        slot_data = {DATA_BITS{1'b0}};
        slot_begin = 1'b0;
        slot_end = 1'b0;
        slot_grant = {PAIRS{1'b0}};
        slot_nomination = {PAIRS{1'b0}};
        slot_request_history = {PAIRS{1'b0}};
        receipt_valid = 1'b0;
        receipt_grant = {PAIRS{1'b0}};
        receipt_request_history = {PAIRS{1'b0}};
        window = 1'b0;
    end

    always @(posedge clk) begin
        if (take_in) begin
            slot_valid <= 1'b1;
            slot_data <= chosen_data;
            slot_begin <= chosen_begin;
            slot_end <= chosen_end;
            slot_grant <= chosen_grant;
            slot_nomination <= nominations;
            slot_request_history <= eligible_requests;

            if (selected_output == OUTPUT_COUNT - 32'd1)
                input_rr[selected_input*PTR_BITS +: PTR_BITS] <= 32'd0;
            else
                input_rr[selected_input*PTR_BITS +: PTR_BITS] <=
                    selected_output + 32'd1;
            if (selected_input == INPUT_COUNT - 32'd1)
                output_rr[selected_output*PTR_BITS +: PTR_BITS] <= 32'd0;
            else
                output_rr[selected_output*PTR_BITS +: PTR_BITS] <=
                    selected_input + 32'd1;
        end else if (take_out) begin
            slot_valid <= 1'b0;
        end

        if (take_out) begin
            receipt_valid <= 1'b1;
            receipt_grant <= slot_grant;
            receipt_request_history <= slot_request_history;
            // Q: deliver BEGIN. R: deliver END, with END taking priority.
            if (slot_end)
                window <= 1'b0;
            else if (slot_begin)
                window <= 1'b1;
        end
    end

    // During an open programming session, the last delivered pair must
    // have appeared in the request snapshot captured at its earlier admission.
    always @(posedge clk)
        assert (!window || !receipt_valid ||
                ((receipt_grant & ~receipt_request_history) == {PAIRS{1'b0}}));
endmodule

module camera_mask_classifier #(
    parameter integer WORD_BITS = 64
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 cfg_load,
    input  wire [WORD_BITS-1:0]  cfg_mask,
    input  wire [WORD_BITS-1:0]  cfg_reference,
    input  wire [WORD_BITS-1:0]  pixel_word,
    output reg                  match_flag,
    output reg                  masked_error,
    output reg                  armed
);
    reg [WORD_BITS-1:0] active_mask;
    reg [WORD_BITS-1:0] reference_pattern;
    reg [WORD_BITS-1:0] masked_reference;

    initial begin
        active_mask       = {WORD_BITS{1'b1}};
        reference_pattern = {WORD_BITS{1'b0}};
        masked_reference  = {WORD_BITS{1'b0}};
        match_flag        = 1'b0;
        masked_error      = 1'b0;
        armed             = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_load) begin
                active_mask       <= cfg_mask;
                reference_pattern <= cfg_reference;
                masked_reference  <= cfg_reference & cfg_mask;
            end else begin
                // Compare against the pre-masked reference cache.
                match_flag <= ((pixel_word & active_mask) == masked_reference);
                // Independently detect differences in enabled bit positions.
                masked_error <= (((pixel_word ^ reference_pattern) & active_mask)
                                 != {WORD_BITS{1'b0}});
                // Q is the first enabled pixel classification, not configuration.
                armed <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (!(match_flag && masked_error));
endmodule

module activation_block_encoder #(
    parameter integer WORD_WIDTH = 16,
    parameter integer COUNT_WIDTH = 16,
    parameter integer BLOCK_WORDS = 8,
    parameter integer STAGING_ENTRIES = 32
) (
    input wire clk,
    input wire i_ce,
    input wire load_write,
    input wire [COUNT_WIDTH-1:0] load_address,
    input wire [WORD_WIDTH-1:0] activation_word,
    input wire block_request,
    input wire ordered_set,
    input wire [COUNT_WIDTH-1:0] request_block,
    output reg serial_bit,
    output reg serial_valid,
    output reg outstanding
);
    localparam [COUNT_WIDTH-1:0] ZERO = 16'd0;
    localparam [COUNT_WIDTH-1:0] ONE = 16'd1;
    localparam [COUNT_WIDTH-1:0] HEADER_BITS = 16'd2;
    localparam [COUNT_WIDTH-1:0] HEADER_LAST = HEADER_BITS - ONE;
    localparam [COUNT_WIDTH-1:0] WORD_BITS = WORD_WIDTH;
    localparam [COUNT_WIDTH-1:0] WORD_LAST = WORD_BITS - ONE;
    localparam [COUNT_WIDTH-1:0] BLOCK_WORD_COUNT = BLOCK_WORDS;
    localparam [COUNT_WIDTH-1:0] LAST_WORD = BLOCK_WORD_COUNT - ONE;
    localparam [COUNT_WIDTH-1:0] STAGE_WORD_COUNT = STAGING_ENTRIES;
    localparam [COUNT_WIDTH-1:0] BLOCK_COUNT = STAGING_ENTRIES / BLOCK_WORDS;
    localparam [COUNT_WIDTH-1:0] ENCODED_BITS = WORD_WIDTH * BLOCK_WORDS + HEADER_BITS;

    // Four staged 128-bit blocks by default, organized as 16-bit words.
    reg [WORD_WIDTH-1:0] staged_data [0:STAGING_ENTRIES-1];
    reg [COUNT_WIDTH-1:0] selected_block;
    reg [COUNT_WIDTH-1:0] symbol_count;
    reg [COUNT_WIDTH-1:0] bit_count;
    reg [COUNT_WIDTH-1:0] countdown;
    reg block_type;
    reg [1:0] sync_header;
    reg header_phase;
    integer init_index;

    initial begin
        serial_bit = 1'b0;
        serial_valid = 1'b0;
        outstanding = 1'b0;
        selected_block = ZERO;
        symbol_count = ZERO;
        bit_count = ZERO;
        countdown = ZERO;
        block_type = 1'b0;
        sync_header = 2'b01;
        header_phase = 1'b0;
        for (init_index = 0; init_index < STAGING_ENTRIES; init_index = init_index + 1)
            staged_data[init_index] = {WORD_WIDTH{1'b0}};
    end

    // Every state element holds when i_ce is low. The deadline therefore
    // counts enabled serializer cycles, not cycles spent externally stalled.
    always @(posedge clk) begin
        if (i_ce) begin
            serial_valid <= 1'b0;
            if (!outstanding) begin
                if (load_write && load_address < STAGE_WORD_COUNT)
                    staged_data[load_address] <= activation_word;

                if (block_request && request_block < BLOCK_COUNT) begin
                    selected_block <= request_block;
                    block_type <= ordered_set;
                    sync_header <= ordered_set ? 2'b10 : 2'b01;
                    symbol_count <= ZERO;
                    bit_count <= ZERO;
                    header_phase <= 1'b1;
                    countdown <= ENCODED_BITS;
                    outstanding <= 1'b1;
                end
            end else begin
                serial_valid <= 1'b1;
                countdown <= countdown - ONE;
                if (header_phase) begin
                    // Prepend the two-bit data/ordered-set sync header.
                    serial_bit <= sync_header[HEADER_LAST - bit_count];
                    if (bit_count == HEADER_LAST) begin
                        header_phase <= 1'b0;
                        bit_count <= ZERO;
                    end else begin
                        bit_count <= bit_count + ONE;
                    end
                end else begin
                    serial_bit <= staged_data[selected_block * BLOCK_WORD_COUNT + symbol_count][bit_count];
                    if (bit_count == WORD_LAST) begin
                        bit_count <= ZERO;
                        if (symbol_count == LAST_WORD) begin
                            symbol_count <= ZERO;
                            countdown <= ZERO;
                            outstanding <= 1'b0;
                        end else begin
                            symbol_count <= symbol_count + ONE;
                        end
                    end else begin
                        bit_count <= bit_count + ONE;
                    end
                end
            end
        end
    end

    // Globally, an accepted block must finish before its deadline expires.
    assert property (!outstanding || (countdown != ZERO));
endmodule

module token_phase_sequencer #(
    parameter logic [7:0] NUM_PHASES = 8'd8
) (
    input  wire       clk,
    input  wire       token_valid,
    output wire       token_ready,
    input  wire [7:0] token_data,
    output wire       result_valid,
    input  wire       result_ready,
    output logic [7:0] result_data
);
    // NUM_PHASES supports values from 3 through 16.
    localparam logic [7:0] LAST_PHASE = NUM_PHASES - 8'd1;
    localparam logic [NUM_PHASES-8'd1:0] FIRST_STROBE =
        {{(NUM_PHASES-8'd1){1'b0}}, 1'b1};

    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        ACTIVE = 2'b01,
        RESULT = 2'b10
    } state_t;

    state_t state;
    logic [7:0] phase;
    logic [NUM_PHASES-8'd1:0] phase_enable;
    logic window;
    logic arm_seen, start_seen, finish_seen;

    wire [7:0] next_phase = phase + 8'd1;
    assign token_ready = (state == IDLE) || (state == ACTIVE);
    assign result_valid = (state == RESULT);
    wire token_take = token_valid && token_ready;
    wire result_take = result_valid && result_ready;

    initial begin
        state = IDLE;
        phase = 8'd0;
        phase_enable = FIRST_STROBE;
        window = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        finish_seen = 1'b0;
        result_data = 8'd0;
    end

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (token_take) begin
                    // Q: accepting a header opens the precedence window.
                    window <= 1'b1;
                    state <= ACTIVE;
                    phase <= 8'd0;
                    phase_enable <= FIRST_STROBE;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    finish_seen <= 1'b0;
                    result_data <= token_data;
                end
            end
            ACTIVE: begin
                if (token_take) begin
                    result_data <= result_data ^ token_data;
                    if (phase_enable[0])
                        arm_seen <= 1'b1;
                    if (phase_enable[1])
                        start_seen <= 1'b1;

                    if (phase_enable[NUM_PHASES-8'd1]) begin
                        finish_seen <= 1'b1;
                        state <= RESULT;
                    end else begin
                        phase <= next_phase;
                        // Registered binary-to-one-hot timing-phase decoder.
                        phase_enable <= FIRST_STROBE << next_phase;
                    end
                end
            end
            RESULT: begin
                // Back-pressure holds valid, data, and all state steady.
                if (result_take) begin
                    // R: accepting the result closes the window.
                    window <= 1'b0;
                    state <= IDLE;
                    phase <= 8'd0;
                    phase_enable <= FIRST_STROBE;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    finish_seen <= 1'b0;
                    result_data <= 8'd0;
                end
            end
        endcase
    end

    // Within the latched window: arm precedes start, which precedes finish.
    always @(posedge clk)
        assert (!window ||
                ((!start_seen || arm_seen) &&
                 (!finish_seen || (start_seen && arm_seen))));
endmodule

module scoped_token_assembler #(
    parameter integer WORD_BITS = 16
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 cmd_valid,
    output wire                 cmd_ready,
    input  wire [2:0]           cmd,
    input  wire                 serial_bit,
    output wire [WORD_BITS-1:0] o_word,
    output wire                 o_word_ready
);
    // WORD_BITS must be at least two.
    localparam [2:0] OP_OPEN  = 3'd0;
    localparam [2:0] OP_CLOSE = 3'd1;
    localparam [2:0] OP_ARM   = 3'd2;
    localparam [2:0] OP_BIT   = 3'd3;
    localparam [2:0] OP_TAKE  = 3'd4;

    localparam [1:0] PH_IDLE     = 2'd0;
    localparam [1:0] PH_ARMED    = 2'd1;
    localparam [1:0] PH_STARTED  = 2'd2;
    localparam [1:0] PH_FINISHED = 2'd3;

    localparam [WORD_BITS-1:0] COUNT_ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] COUNT_ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] WORD_COUNT = WORD_BITS;
    localparam [WORD_BITS:0] SHIFT_ZERO = {(WORD_BITS+1){1'b0}};
    localparam [WORD_BITS:0] SHIFT_SEED = {{WORD_BITS{1'b0}}, 1'b1};

    reg window_open;
    reg [1:0] phase;
    reg [WORD_BITS-1:0] bit_count;
    reg [WORD_BITS:0] shift_word;
    reg word_ready;
    reg pv;

    initial begin
        window_open = 1'b0;
        phase = PH_IDLE;
        bit_count = COUNT_ZERO;
        shift_word = SHIFT_ZERO;
        word_ready = 1'b0;
        pv = 1'b0;
    end

    // The command channel is the receiver-side valid/ready interface.
    // In particular, serial data is back-pressured until armed, and
    // again after the sentinel announces a complete word.
    assign cmd_ready = i_ce && (
        ((cmd == OP_OPEN)  && !window_open) ||
        ((cmd == OP_CLOSE) && window_open) ||
        ((cmd == OP_ARM)   && window_open && (phase == PH_IDLE)) ||
        ((cmd == OP_BIT)   && window_open && !word_ready &&
            ((phase == PH_ARMED) || (phase == PH_STARTED))) ||
        ((cmd == OP_TAKE)  && window_open && word_ready &&
            (phase == PH_FINISHED))
    );

    wire command_fire;
    assign command_fire = cmd_valid && cmd_ready;
    assign o_word = shift_word[WORD_BITS-1:0];
    assign o_word_ready = word_ready;

    always @(posedge clk) begin
        if (command_fire) begin
            pv <= 1'b1;
            case (cmd)
                OP_OPEN: begin
                    // Q opens a persistent checking window.
                    window_open <= 1'b1;
                end
                OP_CLOSE: begin
                    // R closes the window and discards any partial word.
                    window_open <= 1'b0;
                    phase <= PH_IDLE;
                    bit_count <= COUNT_ZERO;
                    shift_word <= SHIFT_ZERO;
                    word_ready <= 1'b0;
                end
                OP_ARM: begin
                    // Arm: preload the sentinel below the incoming data.
                    phase <= PH_ARMED;
                    bit_count <= COUNT_ZERO;
                    shift_word <= SHIFT_SEED;
                    word_ready <= 1'b0;
                end
                OP_BIT: begin
                    shift_word <= {shift_word[WORD_BITS-1:0], serial_bit};
                    bit_count <= bit_count + COUNT_ONE;
                    word_ready <= shift_word[WORD_BITS-1];

                    // Start is the first accepted bit after arm.
                    // Finish is permitted only from the started phase.
                    if (phase == PH_ARMED)
                        phase <= PH_STARTED;
                    else if (shift_word[WORD_BITS-1])
                        phase <= PH_FINISHED;
                end
                OP_TAKE: begin
                    phase <= PH_IDLE;
                    bit_count <= COUNT_ZERO;
                    shift_word <= SHIFT_ZERO;
                    word_ready <= 1'b0;
                end
                default: begin
                end
            endcase
        end
    end

    // A completion edge inside the window requires the arm-start-finish
    // sequence to have reached its final phase.
    always @(posedge clk)
        if (pv && window_open && $rose(word_ready))
            assert (phase == PH_FINISHED);
endmodule

module wave_line_prefetcher #(
    parameter integer LINE_W = 8,
    parameter integer DEPTH = 64,
    parameter integer COUNT_W = 8
) (
    input  wire                  clk,
    input  wire                  miss_valid,
    output wire                  miss_ready,
    input  wire [LINE_W-1:0]     miss_line,
    output wire                  prefetch_valid,
    input  wire                  prefetch_ready,
    output wire [LINE_W-1:0]     prefetch_line
);
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [LINE_W-1:0] LINE_ZERO = {LINE_W{1'b0}};
    localparam [LINE_W-1:0] LINE_ONE = {{(LINE_W-1){1'b0}}, 1'b1};

    reg [LINE_W-1:0] prefetch_q [0:DEPTH-1];
    reg [COUNT_W-1:0] wr_ptr;
    reg [COUNT_W-1:0] rd_ptr;
    reg [COUNT_W-1:0] used;
    reg [LINE_W-1:0] last_miss;
    reg pv;

    initial begin
        wr_ptr = COUNT_ZERO;
        rd_ptr = COUNT_ZERO;
        used = COUNT_ZERO;
        last_miss = {LINE_W{1'b1}};
        pv = 1'b0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : initialize_queue
            initial prefetch_q[g] = LINE_ZERO;
        end
    endgenerate

    assign miss_ready = (used < CAPACITY);
    assign prefetch_valid = (used != COUNT_ZERO);
    assign prefetch_line = prefetch_q[rd_ptr];

    wire push = miss_valid && miss_ready;
    wire pop = prefetch_valid && prefetch_ready;

    // The slot immediately preceding the write pointer retains the
    // most recently generated next-line request, even after retirement.
    wire [COUNT_W-1:0] latest_slot =
        (wr_ptr == COUNT_ZERO) ? LAST_SLOT : (wr_ptr - COUNT_ONE);
    wire [LINE_W-1:0] latest_line = prefetch_q[latest_slot];

    always @(posedge clk) begin
        if (push) begin
            prefetch_q[wr_ptr] <= miss_line + LINE_ONE;
            last_miss <= miss_line;
            wr_ptr <= (wr_ptr == LAST_SLOT) ? COUNT_ZERO : (wr_ptr + COUNT_ONE);
        end
        if (pop)
            rd_ptr <= (rd_ptr == LAST_SLOT) ? COUNT_ZERO : (rd_ptr + COUNT_ONE);

        if (push && !pop)
            used <= used + COUNT_ONE;
        else if (pop && !push)
            used <= used - COUNT_ONE;

        // No history check is needed before the first transaction.
        // Keeping this update transaction-gated preserves complete idle.
        if (push || pop)
            pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $stable(last_miss))
            assert ($stable(latest_line));
endmodule

module inference_zq_scheduler #(
    parameter integer DEPTH = 32'd2,
    parameter [63:0] ZQ_INTERVAL = 64'd4,
    parameter [63:0] ZQ_BLOCK = 64'd4
) (
    input wire clk,
    input wire i_ce,
    input wire inference_begin,
    input wire inference_end,
    output reg zq_short,
    output wire [63:0] zq_short_ticket,
    output wire inference_blocked,
    output wire schedule_stalled,
    output reg calibration_done,
    output reg [63:0] completed_ticket
);
    // DEPTH is at least two; interval and blocking durations are positive.
    localparam [63:0] DEPTH64 = DEPTH;

    reg [63:0] interval_counter;
    reg [63:0] blocking_timer;
    reg calibration_in_progress;

    // Periodic requests wait in a bounded FIFO until calibration can start.
    reg [63:0] pending_ticket [32'd0:DEPTH-32'd1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] pending_count;
    reg [63:0] accepted_serial;

    // These shadows record earlier ZQ command issuance.
    reg [63:0] issued_serial;
    reg issue_seen;
    reg [63:0] active_ticket;
    reg scope_window;

    wire interval_due = interval_counter == ZQ_INTERVAL - 64'd1;
    wire enqueue_request = i_ce && interval_due && pending_count < DEPTH64;
    wire issue_command = i_ce && !calibration_in_progress &&
                         pending_count != 64'd0;

    assign inference_blocked = calibration_in_progress;
    assign zq_short_ticket = active_ticket;
    assign schedule_stalled = interval_due && pending_count == DEPTH64;

    // Per-entry ordering predicates. Occupancy comes from pointers/count,
    // not from summing entry-valid bits.
    wire [63:0] slot_distance [32'd0:DEPTH-32'd1];
    wire [DEPTH-32'd1:32'd0] slot_occupied;
    wire [DEPTH-32'd1:32'd0] entry_consistent;
    genvar g;
    generate
        for (g = 32'd0; g < DEPTH; g = g + 32'd1) begin : slots
            localparam [63:0] SLOT = g;
            assign slot_distance[g] = (SLOT >= rd_ptr) ?
                SLOT - rd_ptr : DEPTH64 - rd_ptr + SLOT;
            assign slot_occupied[g] = slot_distance[g] < pending_count;
            assign entry_consistent[g] = !slot_occupied[g] ||
                pending_ticket[g] == issued_serial + slot_distance[g] + 64'd1;
        end
    endgenerate

    integer k;
    initial begin
        interval_counter = 64'd0;
        blocking_timer = 64'd0;
        calibration_in_progress = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        pending_count = 64'd0;
        accepted_serial = 64'd0;
        issued_serial = 64'd0;
        issue_seen = 1'b0;
        active_ticket = 64'd0;
        scope_window = 1'b0;
        zq_short = 1'b0;
        calibration_done = 1'b0;
        completed_ticket = 64'd0;
        for (k = 32'd0; k < DEPTH; k = k + 32'd1)
            pending_ticket[k] = 64'd0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Q opens a persistent observation window; R closes it.
            if (inference_end)
                scope_window <= 1'b0;
            else if (inference_begin)
                scope_window <= 1'b1;

            zq_short <= 1'b0;
            calibration_done <= 1'b0;

            // A full FIFO makes the periodic source wait at its deadline.
            if (enqueue_request) begin
                interval_counter <= 64'd0;
                accepted_serial <= accepted_serial + 64'd1;
                pending_ticket[wr_ptr] <= accepted_serial + 64'd1;
                if (wr_ptr == DEPTH64 - 64'd1)
                    wr_ptr <= 64'd0;
                else
                    wr_ptr <= wr_ptr + 64'd1;
            end else if (!interval_due) begin
                interval_counter <= interval_counter + 64'd1;
            end

            // Only the oldest pending request can enter service, and no
            // request enters service until the previous blocking period ends.
            if (issue_command) begin
                active_ticket <= pending_ticket[rd_ptr];
                issued_serial <= issued_serial + 64'd1;
                issue_seen <= 1'b1;
                zq_short <= 1'b1;
                calibration_in_progress <= 1'b1;
                blocking_timer <= ZQ_BLOCK;
                if (rd_ptr == DEPTH64 - 64'd1)
                    rd_ptr <= 64'd0;
                else
                    rd_ptr <= rd_ptr + 64'd1;
            end else if (calibration_in_progress) begin
                if (blocking_timer == 64'd1) begin
                    blocking_timer <= 64'd0;
                    calibration_in_progress <= 1'b0;
                    calibration_done <= 1'b1;
                    completed_ticket <= active_ticket;
                end else begin
                    blocking_timer <= blocking_timer - 64'd1;
                end
            end

            case ({enqueue_request, issue_command})
                2'b10: pending_count <= pending_count + 64'd1;
                2'b01: pending_count <= pending_count - 64'd1;
                default: pending_count <= pending_count;
            endcase
        end
    end

    // Completion must be preceded by a command, with the recorded ticket.
    always @(posedge clk) begin
        if (scope_window && calibration_done)
            assert (issue_seen);
        if (scope_window && calibration_done)
            assert (completed_ticket == issued_serial);
    end
endmodule

module neural_operand_exchange #(
    parameter WORD_W = 128,
    parameter SERVICE_CYCLES = 4
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  cmd_valid,
    output wire                  cmd_ready,
    input  wire [1:0]            cmd,
    input  wire [WORD_W-1:0]     cmd_word,
    output reg  [WORD_W-1:0]     left_word,
    output reg  [WORD_W-1:0]     right_word,
    output reg                   busy
);
    localparam BUDGET_W = (SERVICE_CYCLES < 2) ? 1 : $clog2(SERVICE_CYCLES + 1);
    localparam [BUDGET_W-1:0] ZERO_BUDGET = {BUDGET_W{1'b0}};
    localparam [BUDGET_W-1:0] ONE_BUDGET = {{(BUDGET_W-1){1'b0}}, 1'b1};
    localparam [BUDGET_W-1:0] FULL_BUDGET = SERVICE_CYCLES;
    localparam [1:0] LOAD_LEFT  = 2'b00;
    localparam [1:0] LOAD_RIGHT = 2'b01;
    localparam [1:0] EXCHANGE   = 2'b10;
    localparam [1:0] ADVANCE    = 2'b11;

    reg [WORD_W-1:0] pair_signature;
    reg [BUDGET_W-1:0] budget;
    reg pv;

    // While occupied, only scheduler ADVANCE beats can be accepted.
    assign cmd_ready = !busy || (cmd == ADVANCE);
    wire fire = cmd_valid && cmd_ready;

    initial begin
        left_word = {WORD_W{1'b0}};
        right_word = {WORD_W{1'b0}};
        pair_signature = {WORD_W{1'b0}};
        budget = ZERO_BUDGET;
        busy = 1'b0;
        pv = 1'b0;
    end

    // A deadline counts accepted scheduler cycles, so backpressure pauses it.
    // Independent loads update the pair's integrity signature; exchanging the
    // registers preserves that signature without modifying it.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            left_word <= {WORD_W{1'b0}};
            right_word <= {WORD_W{1'b0}};
            pair_signature <= {WORD_W{1'b0}};
            budget <= ZERO_BUDGET;
            busy <= 1'b0;
            pv <= 1'b0;
        end else if (fire) begin
            pv <= 1'b1;
            if (!busy) begin
                case (cmd)
                    LOAD_LEFT: begin
                        left_word <= cmd_word;
                        pair_signature <= pair_signature ^ left_word ^ cmd_word;
                    end
                    LOAD_RIGHT: begin
                        right_word <= cmd_word;
                        pair_signature <= pair_signature ^ right_word ^ cmd_word;
                    end
                    EXCHANGE: begin
                        busy <= 1'b1;
                        budget <= FULL_BUDGET;
                    end
                    ADVANCE: begin end
                endcase
            end else begin
                if (budget != ZERO_BUDGET)
                    budget <= budget - ONE_BUDGET;
                if (budget == FULL_BUDGET) begin
                    left_word <= right_word;
                    right_word <= left_word;
                end
                // Retire only an integrity-checked exchange.
                if ((budget == ONE_BUDGET) &&
                    ((left_word ^ right_word) == pair_signature))
                    busy <= 1'b0;
            end
        end
    end

    // A previously serviced outstanding request must not remain outstanding
    // with an expired deadline. This applies globally, without scope arming.
    always @(posedge clk)
        if (pv && $past(busy && fire))
            assert (!busy || (budget != ZERO_BUDGET));
endmodule

module debug_ahb_axi_write_bridge #(
    parameter integer WORD_WIDTH = 32
) (
    input  wire                      clk,
    input  wire                      rst_n,

    // Qualified AHB-Lite write address and data phases.
    input  wire                      haddr_valid,
    output wire                      haddr_ready,
    input  wire [WORD_WIDTH-1:0]     haddr,
    input  wire [2:0]                hsize,
    input  wire [2:0]                hburst,
    input  wire                      hwdata_valid,
    output wire                      hwdata_ready,
    input  wire [WORD_WIDTH-1:0]     hwdata,
    output wire                      hready,

    output wire                      axi_awvalid,
    input  wire                      axi_awready,
    output wire [WORD_WIDTH-1:0]     axi_awaddr,
    output wire [2:0]                axi_awsize,
    output wire [1:0]                axi_awburst,
    output wire [7:0]                axi_awlen,
    output wire                      axi_wvalid,
    input  wire                      axi_wready,
    output wire [WORD_WIDTH-1:0]     axi_wdata,
    output wire [(WORD_WIDTH/8)-1:0] axi_wstrb,
    output wire                      axi_wlast,
    input  wire                      axi_bvalid,
    output wire                      axi_bready
);
    // Serialize AHB beats into single-beat AXI writes. AHB burst
    // addresses arrive individually; no multi-entry storage is used.
    localparam [31:0] IDLE = 32'd0;
    localparam [31:0] DATA = 32'd1;
    localparam [31:0] SEND = 32'd2;
    localparam [31:0] RESP = 32'd3;

    reg [31:0] phase;
    reg [WORD_WIDTH-1:0] captured_haddr;
    reg [31:0] captured_hsize;
    reg [31:0] captured_hburst;
    reg [WORD_WIDTH-1:0] write_data_buffer;
    reg addr_armed;
    reg data_armed;
    reg aw_started;
    reg w_started;
    reg waiting_for_response;

    assign haddr_ready = (phase == IDLE) && !addr_armed;
    assign hwdata_ready = (phase == DATA) && !data_armed;
    assign hready = !addr_armed ||
                    (waiting_for_response && axi_bvalid);

    assign axi_awvalid = (phase == SEND) && !aw_started;
    assign axi_awaddr = captured_haddr;
    assign axi_awsize = captured_hsize[2:0];
    assign axi_awburst = (captured_hburst == 32'd0) ? 2'b00 : 2'b01;
    assign axi_awlen = 8'd0;
    assign axi_wvalid = (phase == SEND) && !w_started;
    assign axi_wdata = write_data_buffer;
    assign axi_wstrb = {(WORD_WIDTH/8){1'b1}};
    assign axi_wlast = 1'b1;
    assign axi_bready = waiting_for_response;

    wire address_arm = haddr_valid && haddr_ready;
    wire data_arm = hwdata_valid && hwdata_ready;
    wire aw_fire = axi_awvalid && axi_awready;
    wire w_fire = axi_wvalid && axi_wready;
    wire response_finish = axi_bvalid && axi_bready;

    initial begin
        phase = IDLE;
        captured_haddr = {WORD_WIDTH{1'b0}};
        captured_hsize = 32'd0;
        captured_hburst = 32'd0;
        write_data_buffer = {WORD_WIDTH{1'b0}};
        addr_armed = 1'b0;
        data_armed = 1'b0;
        aw_started = 1'b0;
        w_started = 1'b0;
        waiting_for_response = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase <= IDLE;
            captured_haddr <= {WORD_WIDTH{1'b0}};
            captured_hsize <= 32'd0;
            captured_hburst <= 32'd0;
            write_data_buffer <= {WORD_WIDTH{1'b0}};
            addr_armed <= 1'b0;
            data_armed <= 1'b0;
            aw_started <= 1'b0;
            w_started <= 1'b0;
            waiting_for_response <= 1'b0;
        end else begin
            case (phase)
                IDLE: begin
                    if (address_arm) begin
                        captured_haddr <= haddr;
                        captured_hsize <= {29'd0, hsize};
                        captured_hburst <= {29'd0, hburst};
                        addr_armed <= 1'b1;
                        phase <= DATA;
                    end
                end
                DATA: begin
                    if (data_arm) begin
                        write_data_buffer <= hwdata;
                        data_armed <= 1'b1;
                        phase <= SEND;
                    end
                end
                SEND: begin
                    if (aw_fire)
                        aw_started <= 1'b1;
                    if (w_fire)
                        w_started <= 1'b1;
                    if ((aw_fire || w_fire) &&
                        (aw_started || aw_fire) &&
                        (w_started || w_fire)) begin
                        waiting_for_response <= 1'b1;
                        phase <= RESP;
                    end
                end
                RESP: begin
                    if (response_finish) begin
                        addr_armed <= 1'b0;
                        data_armed <= 1'b0;
                        aw_started <= 1'b0;
                        w_started <= 1'b0;
                        waiting_for_response <= 1'b0;
                        phase <= IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    // Address chain: AHB address arm, AXI AW start, response finish.
    always @(posedge clk)
        if (aw_started || response_finish)
            assert (addr_armed && (!response_finish || aw_started));

    // Data chain: AHB data arm, AXI W start, response finish.
    always @(posedge clk)
        if (w_started || response_finish)
            assert (data_armed && (!response_finish || w_started));
endmodule

module complex_butterfly_pipe #(
    parameter integer DATA_W = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_valid,
    output wire i_ready,
    input  wire i_epoch_end,
    input  wire signed [DATA_W-1:0] i_a_re,
    input  wire signed [DATA_W-1:0] i_a_im,
    input  wire signed [DATA_W-1:0] i_b_re,
    input  wire signed [DATA_W-1:0] i_b_im,
    input  wire signed [DATA_W-1:0] i_tw_re,
    input  wire signed [DATA_W-1:0] i_tw_im,
    input  wire o_ready,
    output reg  o_valid,
    output reg  o_zero_b,
    output reg signed [DATA_W-1:0] o_plus_re,
    output reg signed [DATA_W-1:0] o_plus_im,
    output reg signed [DATA_W-1:0] o_minus_re,
    output reg signed [DATA_W-1:0] o_minus_im
);
    reg mul_valid;
    reg mul_zero_b;
    reg signed [DATA_W-1:0] mul_a_re, mul_a_im;
    reg signed [DATA_W-1:0] mul_re, mul_im;
    reg before_epoch_end;

    wire out_space;
    wire take_input;
    wire move_product;
    wire take_output;

    // Each stage accepts an item whenever it has room, independently of
    // downstream ready when that stage is empty.
    assign out_space = !o_valid || o_ready;
    assign i_ready = !mul_valid || out_space;
    assign take_input = i_valid && i_ready;
    assign move_product = mul_valid && out_space;
    assign take_output = o_valid && o_ready;

    initial begin
        mul_valid = 1'b0;
        mul_zero_b = 1'b0;
        mul_a_re = {DATA_W{1'b0}};
        mul_a_im = {DATA_W{1'b0}};
        mul_re = {DATA_W{1'b0}};
        mul_im = {DATA_W{1'b0}};
        o_valid = 1'b0;
        o_zero_b = 1'b0;
        o_plus_re = {DATA_W{1'b0}};
        o_plus_im = {DATA_W{1'b0}};
        o_minus_re = {DATA_W{1'b0}};
        o_minus_im = {DATA_W{1'b0}};
        before_epoch_end = 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_valid <= 1'b0;
            mul_zero_b <= 1'b0;
            mul_a_re <= {DATA_W{1'b0}};
            mul_a_im <= {DATA_W{1'b0}};
            mul_re <= {DATA_W{1'b0}};
            mul_im <= {DATA_W{1'b0}};
            o_valid <= 1'b0;
            o_zero_b <= 1'b0;
            o_plus_re <= {DATA_W{1'b0}};
            o_plus_im <= {DATA_W{1'b0}};
            o_minus_re <= {DATA_W{1'b0}};
            o_minus_im <= {DATA_W{1'b0}};
            before_epoch_end <= 1'b1;
        end else begin
            if (take_input) begin
                mul_valid <= 1'b1;
                mul_a_re <= i_a_re;
                mul_a_im <= i_a_im;
                mul_re <= (i_b_re * i_tw_re) - (i_b_im * i_tw_im);
                mul_im <= (i_b_re * i_tw_im) + (i_b_im * i_tw_re);
                mul_zero_b <= (i_b_re == {DATA_W{1'b0}}) &&
                              (i_b_im == {DATA_W{1'b0}});
                if (i_epoch_end)
                    before_epoch_end <= 1'b0;
            end else if (move_product) begin
                mul_valid <= 1'b0;
            end

            // An empty output stage raises valid without waiting for ready.
            if (move_product) begin
                o_valid <= 1'b1;
                o_zero_b <= mul_zero_b;
                o_plus_re <= mul_a_re + mul_re;
                o_plus_im <= mul_a_im + mul_im;
                o_minus_re <= mul_a_re - mul_re;
                o_minus_im <= mul_a_im - mul_im;
            end else if (take_output) begin
                o_valid <= 1'b0;
            end

            // With both stages occupied and o_ready low, all state holds:
            // no input, internal transfer, or output transfer is possible.
        end
    end

    always @(posedge clk) begin
        if (before_epoch_end && o_valid && o_zero_b)
            assert ((o_plus_re == o_minus_re) &&
                    (o_plus_im == o_minus_im));
    end
endmodule

module phase_window_pwm #(
    parameter [31:0] CHANNELS = 32'd16,
    parameter [31:0] SLOT_TICKS = 32'd4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire cfg_write,
    input  wire [31:0] cfg_channel,
    input  wire [31:0] cfg_phase,
    input  wire [31:0] cfg_duty,
    output wire [CHANNELS-32'd1:32'd0] pwm,
    output reg  [31:0] active_count
);
    localparam [31:0] PERIOD_TICKS = CHANNELS * SLOT_TICKS;

    reg [31:0] master_count;
    reg [31:0] phase_offset [32'd0:CHANNELS-32'd1];
    reg [31:0] duty [32'd0:CHANNELS-32'd1];
    reg past_valid;

    wire [31:0] overlap_limit = 32'd1;
    wire [31:0] programmed_trim =
        (cfg_phase < SLOT_TICKS) ? cfg_phase : SLOT_TICKS - 32'd1;
    wire [31:0] programmed_duty =
        (cfg_duty <= SLOT_TICKS - programmed_trim)
        ? cfg_duty : SLOT_TICKS - programmed_trim;

    // Programming pauses the shared period counter for one enabled cycle.
    wire [31:0] master_after =
        (!i_ce || cfg_write) ? master_count :
        ((master_count == PERIOD_TICKS - 32'd1)
            ? 32'd0 : master_count + 32'd1);

    wire [CHANNELS-32'd1:32'd0] pwm_after;
    wire [CHANNELS-32'd1:32'd0] slot_legal;
    reg [31:0] active_sum;
    reg [31:0] next_active_sum;
    integer k;

    initial begin
        master_count = 32'd0;
        active_count = 32'd0;
        past_valid = 1'b0;
    end

    genvar g;
    generate
        for (g = 32'd0; g < CHANNELS; g = g + 32'd1) begin : lanes
            localparam [31:0] LANE_INDEX = g;
            localparam [31:0] SLOT_BASE = LANE_INDEX * SLOT_TICKS;
            localparam [31:0] SLOT_END = SLOT_BASE + SLOT_TICKS;

            wire write_lane = i_ce && cfg_write &&
                                   (cfg_channel == LANE_INDEX);
            wire [31:0] phase_after = write_lane
                ? SLOT_BASE + programmed_trim : phase_offset[g];
            wire [31:0] duty_after = write_lane
                ? programmed_duty : duty[g];

            initial begin
                phase_offset[g] = SLOT_BASE;
                duty[g] = 32'd0;
            end

            always @(posedge clk) begin
                if (i_ce) begin
                    phase_offset[g] <= phase_after;
                    duty[g] <= duty_after;
                end
            end

            assign pwm[g] =
                (master_count >= phase_offset[g]) &&
                ((master_count - phase_offset[g]) < duty[g]);
            assign pwm_after[g] =
                (master_after >= phase_after) &&
                ((master_after - phase_after) < duty_after);

            assign slot_legal[g] =
                (phase_offset[g] >= SLOT_BASE) &&
                (phase_offset[g] < SLOT_END) &&
                (duty[g] <= SLOT_TICKS) &&
                (duty[g] <= SLOT_END - phase_offset[g]);
        end
    endgenerate

    always @(*) begin
        active_sum = 32'd0;
        next_active_sum = 32'd0;
        for (k = 32'd0; k < CHANNELS; k = k + 32'd1) begin
            active_sum = active_sum + {{31{1'b0}}, pwm[k]};
            next_active_sum = next_active_sum + {{31{1'b0}}, pwm_after[k]};
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            master_count <= master_after;
            active_count <= next_active_sum;
            past_valid <= 1'b1;
        end
    end

    // The fixed overlap budget is one active channel. Upper count bits
    // start at zero, so their no-change check expresses active_count <= 1.
    // past_valid cannot become set until an enabled transition has occurred.
    always @(posedge clk) begin
        if (past_valid && $stable(overlap_limit))
            assert ($stable(active_count[31:1]));
    end
endmodule

module dma_completion_tolerance #(
    parameter integer DATA_W = 8
) (
    input  wire                  clk,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [DATA_W-1:0]     i_observed,
    input  wire [DATA_W-1:0]     i_expected,
    input  wire [DATA_W-1:0]     i_epsilon,
    input  wire                  i_calibration_done,
    output reg                   o_valid,
    input  wire                  o_ready,
    output reg  [DATA_W-1:0]     o_epsilon,
    output reg                   o_within,
    output reg                   o_exact_mismatch
);
    reg [DATA_W-1:0] observed_reg;
    reg [DATA_W-1:0] expected_reg;
    reg [DATA_W-1:0] delta_reg;
    reg [DATA_W-1:0] epsilon_reg;
    reg pending_valid;
    reg before_commit;

    wire [DATA_W-1:0] input_delta;
    wire output_can_load;

    assign input_delta = (i_observed >= i_expected)
                       ? (i_observed - i_expected)
                       : (i_expected - i_observed);

    // Each stage can fill an empty slot without downstream readiness.
    assign output_can_load = !o_valid || o_ready;
    assign i_ready = !pending_valid || output_can_load;

    initial begin
        observed_reg     = {DATA_W{1'b0}};
        expected_reg     = {DATA_W{1'b0}};
        delta_reg        = {DATA_W{1'b0}};
        epsilon_reg      = {DATA_W{1'b0}};
        pending_valid    = 1'b0;
        before_commit    = 1'b1;
        o_valid          = 1'b0;
        o_epsilon        = {DATA_W{1'b0}};
        o_within         = 1'b0;
        o_exact_mismatch = 1'b0;
    end

    always @(posedge clk) begin
        // Present a pending result whenever the output slot is available,
        // including when the receiver has not yet asserted ready.
        if (output_can_load) begin
            o_valid <= pending_valid;
            if (pending_valid) begin
                o_epsilon        <= epsilon_reg;
                o_within         <= (delta_reg <= epsilon_reg);
                o_exact_mismatch <= (observed_reg != expected_reg);
            end
        end

        // Accept into an empty pending slot, or replace an item advancing
        // to the output on this edge.
        if (i_ready) begin
            pending_valid <= i_valid;
            if (i_valid) begin
                observed_reg <= i_observed;
                expected_reg <= i_expected;
                delta_reg    <= input_delta;
                epsilon_reg  <= i_epsilon;
                if (i_calibration_done)
                    before_commit <= 1'b0;
            end
        end
    end

    // With both slots occupied, o_ready low freezes every state register.
    always @(*) begin
        if (before_commit && o_valid &&
            (o_epsilon == {DATA_W{1'b0}}))
            assert (!(o_within && o_exact_mismatch));
    end
endmodule

module windowed_fft_butterfly #(
    parameter DATA_W = 32,
    parameter PHASE_W = 32
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_q,
    input  wire i_r,
    input  wire i_in_valid,
    output wire o_in_ready,
    input  wire signed [DATA_W-1:0] i_a_re,
    input  wire signed [DATA_W-1:0] i_a_im,
    input  wire signed [DATA_W-1:0] i_b_re,
    input  wire signed [DATA_W-1:0] i_b_im,
    input  wire signed [DATA_W-1:0] i_tw_re,
    input  wire signed [DATA_W-1:0] i_tw_im,
    output wire o_out_valid,
    input  wire i_out_ready,
    output wire signed [DATA_W-1:0] o_plus_re,
    output wire signed [DATA_W-1:0] o_plus_im,
    output wire signed [DATA_W-1:0] o_minus_re,
    output wire signed [DATA_W-1:0] o_minus_im
);
    localparam [PHASE_W-1:0] PH_IDLE    = 0;
    localparam [PHASE_W-1:0] PH_ARMED   = 1;
    localparam [PHASE_W-1:0] PH_STARTED = 2;
    localparam [PHASE_W-1:0] PH_FINISH  = 3;

    reg [PHASE_W-1:0] phase;
    reg window;
    reg arm_seen, start_seen, finish_seen;

    reg signed [DATA_W-1:0] a0_re, a0_im;
    reg signed [DATA_W-1:0] b0_re, b0_im;
    reg signed [DATA_W-1:0] tw0_re, tw0_im;
    reg signed [DATA_W-1:0] a1_re, a1_im;
    reg signed [DATA_W-1:0] product1_re, product1_im;
    reg signed [DATA_W-1:0] plus2_re, plus2_im;
    reg signed [DATA_W-1:0] minus2_re, minus2_im;

    initial begin
        phase = PH_IDLE;
        window = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        finish_seen = 1'b0;
        a0_re = {DATA_W{1'b0}};
        a0_im = {DATA_W{1'b0}};
        b0_re = {DATA_W{1'b0}};
        b0_im = {DATA_W{1'b0}};
        tw0_re = {DATA_W{1'b0}};
        tw0_im = {DATA_W{1'b0}};
        a1_re = {DATA_W{1'b0}};
        a1_im = {DATA_W{1'b0}};
        product1_re = {DATA_W{1'b0}};
        product1_im = {DATA_W{1'b0}};
        plus2_re = {DATA_W{1'b0}};
        plus2_im = {DATA_W{1'b0}};
        minus2_re = {DATA_W{1'b0}};
        minus2_im = {DATA_W{1'b0}};
    end

    // Accept an input whenever the transaction slot is empty, independently
    // of downstream ready. Disabled cycles perform no interface transfers.
    assign o_in_ready = i_ce && window &&
                        (phase == PH_IDLE) && !i_q && !i_r;
    assign o_out_valid = i_ce && (phase == PH_FINISH);
    assign o_plus_re = plus2_re;
    assign o_plus_im = plus2_im;
    assign o_minus_re = minus2_re;
    assign o_minus_im = minus2_im;

    always @(posedge clk) begin
        // Explicit enable freezes every register when low.
        if (i_ce) begin
            case (phase)
                PH_IDLE: begin
                    // Scope boundaries are accepted between transactions.
                    if (i_q) begin
                        window <= 1'b1;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        finish_seen <= 1'b0;
                    end else if (i_r) begin
                        window <= 1'b0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        finish_seen <= 1'b0;
                    end else if (i_in_valid && o_in_ready) begin
                        a0_re <= i_a_re;
                        a0_im <= i_a_im;
                        b0_re <= i_b_re;
                        b0_im <= i_b_im;
                        tw0_re <= i_tw_re;
                        tw0_im <= i_tw_im;
                        arm_seen <= 1'b1;
                        phase <= PH_ARMED;
                    end
                end
                PH_ARMED: begin
                    // Internal processing never waits for downstream ready.
                    a1_re <= a0_re;
                    a1_im <= a0_im;
                    product1_re <= b0_re * tw0_re - b0_im * tw0_im;
                    product1_im <= b0_re * tw0_im + b0_im * tw0_re;
                    start_seen <= 1'b1;
                    phase <= PH_STARTED;
                end
                PH_STARTED: begin
                    // Arithmetic wraps modulo 2**DATA_W.
                    plus2_re <= a1_re + product1_re;
                    plus2_im <= a1_im + product1_im;
                    minus2_re <= a1_re - product1_re;
                    minus2_im <= a1_im - product1_im;
                    finish_seen <= 1'b1;
                    phase <= PH_FINISH;
                end
                PH_FINISH: begin
                    // The completed result is advertised without waiting for
                    // ready. Only its retirement depends on ready.
                    if (i_out_ready)
                        phase <= PH_IDLE;
                end
                default: begin
                    phase <= PH_IDLE;
                end
            endcase
        end
    end

    always @(*) begin
        if (window)
            assert ((!start_seen || arm_seen) &&
                    (!finish_seen || start_seen));
    end
endmodule

module checked_oai_execute #(
    parameter integer DATA_W = 128,
    parameter integer SERVICE_BUDGET = 4
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [DATA_W-1:0]     in_a,
    input  wire [DATA_W-1:0]     in_b,
    input  wire [DATA_W-1:0]     in_c,
    input  wire                 in_scope_open,
    input  wire                 in_scope_close,
    input  wire                 out_ready,
    output wire                 out_valid,
    output wire [DATA_W-1:0]     out_data
);
    localparam integer TIMER_W =
        (SERVICE_BUDGET < 2) ? 1 : $clog2(SERVICE_BUDGET + 1);
    localparam [TIMER_W-1:0] BUDGET_COUNT = TIMER_W'(SERVICE_BUDGET);
    localparam [TIMER_W-1:0] COUNT_ONE = TIMER_W'(1);

    reg [DATA_W-1:0] saved_a, saved_b, saved_c;
    reg [DATA_W-1:0] result_word;
    reg [TIMER_W-1:0] countdown;
    reg pending;
    reg scope_window;

    wire [DATA_W-1:0] issue_result;
    wire [DATA_W-1:0] checked_result;
    wire result_ok;
    wire accept;

    oai21_bank #(.DATA_W(DATA_W)) issue_gates (
        .a(in_a), .b(in_b), .c(in_c), .y(issue_result)
    );
    oai21_bank #(.DATA_W(DATA_W)) verify_gates (
        .a(saved_a), .b(saved_b), .c(saved_c), .y(checked_result)
    );

    assign result_ok = (result_word == checked_result);

    // Present a checked item without waiting for downstream readiness.
    assign out_valid = pending && result_ok;
    assign out_data = result_word;

    // A departing item may be replaced on the same edge.
    assign in_ready = !pending || (out_valid && out_ready);
    assign accept = in_valid && in_ready;

    initial begin
        saved_a = {DATA_W{1'b0}};
        saved_b = {DATA_W{1'b0}};
        saved_c = {DATA_W{1'b0}};
        result_word = {DATA_W{1'b1}};
        countdown = {TIMER_W{1'b0}};
        pending = 1'b0;
        scope_window = 1'b0;
    end

    always @(posedge clk) begin
        if (accept) begin
            saved_a <= in_a;
            saved_b <= in_b;
            saved_c <= in_c;
            result_word <= issue_result;
            pending <= 1'b1;
            countdown <= BUDGET_COUNT;

            // Closing has priority when both markers accompany an item.
            if (in_scope_close)
                scope_window <= 1'b0;
            else if (in_scope_open)
                scope_window <= 1'b1;
        end else if (pending && out_ready) begin
            // Count downstream-enabled opportunities to retire the item.
            if (countdown != {TIMER_W{1'b0}})
                countdown <= countdown - COUNT_ONE;

            if (result_ok)
                pending <= 1'b0;
        end
        // With in_valid and out_ready both low, every register holds.
    end

    assert property (!(scope_window && pending) ||
                     (countdown != {TIMER_W{1'b0}}));
endmodule

module oai21_bank #(
    parameter integer DATA_W = 128
) (
    input  wire [DATA_W-1:0] a,
    input  wire [DATA_W-1:0] b,
    input  wire [DATA_W-1:0] c,
    output wire [DATA_W-1:0] y
);
    assign y = ~((a | b) & c);
endmodule

module debug_alias_trace #(
    parameter integer DEPTH = 32'd64
) (
    input  wire       clk,
    input  wire       i_valid,
    output wire       i_ready,
    input  wire [7:0] i_addr,
    input  wire [7:0] i_data,
    output wire       o_valid,
    input  wire       o_ready,
    output wire [7:0] o_data,
    output wire [7:0] o_status
);
    localparam [7:0] CAPACITY   = DEPTH;
    localparam [7:0] LAST_INDEX = CAPACITY - 8'd1;
    localparam [7:0] SET_ADDR   = 8'h00;
    localparam [7:0] CLEAR_ADDR = 8'h04;
    localparam [7:0] TOGGLE_ADDR = 8'h08;

    reg [7:0] debug_word;
    reg [7:0] activation_history;
    reg       armed;
    reg [7:0] trace_fifo [0:DEPTH-1];
    reg [7:0] read_ptr;
    reg [7:0] write_ptr;
    reg [7:0] queued;

    wire push;
    wire pop;
    wire [7:0] next_word;
    wire [8:0] ring_sum;
    wire [7:0] ring_tail;
    wire [DEPTH-1:0] slot_used;

    initial begin
        debug_word = 8'h00;
        activation_history = 8'h00;
        armed = 1'b0;
        read_ptr = 8'd0;
        write_ptr = 8'd0;
        queued = 8'd0;
    end

    genvar g;
    generate
        for (g = 32'd0; g < DEPTH; g = g + 32'd1) begin : slots
            localparam [8:0] SLOT = g;
            initial trace_fifo[g] = 8'h00;
            assign slot_used[g] =
                ((SLOT >= {1'b0, read_ptr})
                    ? (SLOT - {1'b0, read_ptr})
                    : (SLOT + {1'b0, CAPACITY} - {1'b0, read_ptr}))
                < {1'b0, queued};
        end
    endgenerate

    assign ring_sum = {1'b0, read_ptr} + {1'b0, queued};
    assign ring_tail = (ring_sum >= {1'b0, CAPACITY})
                     ? (ring_sum - {1'b0, CAPACITY}) : ring_sum;

    assign i_ready = (queued < CAPACITY)
                  && ((i_addr == SET_ADDR)
                   || (i_addr == CLEAR_ADDR)
                   || (i_addr == TOGGLE_ADDR));
    assign o_valid = (queued != 8'd0);
    assign o_data = trace_fifo[read_ptr];
    assign o_status = debug_word;
    assign push = i_valid && i_ready;
    assign pop = o_valid && o_ready;

    // Three write addresses atomically update the same stored word.
    assign next_word = (i_addr == SET_ADDR) ? (debug_word | i_data)
                     : (i_addr == CLEAR_ADDR) ? (debug_word & ~i_data)
                     : (i_addr == TOGGLE_ADDR) ? (debug_word ^ i_data)
                     : debug_word;

    always @(posedge clk) begin
        if (push) begin
            debug_word <= next_word;
            trace_fifo[write_ptr] <= next_word;
            write_ptr <= (write_ptr == LAST_INDEX)
                       ? 8'd0 : write_ptr + 8'd1;

            // Shadow records earlier accepted operations that can enable bits.
            if ((i_addr == SET_ADDR) || (i_addr == TOGGLE_ADDR))
                activation_history <= activation_history | i_data;

            // Q is the first accepted alias write; this scope never disarms.
            armed <= 1'b1;
        end

        if (pop)
            read_ptr <= (read_ptr == LAST_INDEX)
                      ? 8'd0 : read_ptr + 8'd1;

        case ({push, pop})
            2'b10: queued <= queued + 8'd1;
            2'b01: queued <= queued - 8'd1;
            default: queued <= queued;
        endcase
    end

    // After Q, every observed set bit requires an earlier activating write.
    always @(*)
        assert (!armed || !o_valid
                || ((o_data & ~activation_history) == 8'h00));
endmodule

module dco_band_calibrator #(
    parameter integer WORD_W = 32,
    parameter [WORD_W-1:0] REFERENCE_COUNT = 32'd100000
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  measurement_valid,
    output wire                  measurement_ready,
    input  wire [WORD_W-1:0]     measurement_count_in,
    output wire                  result_valid,
    input  wire                  result_ready,
    output reg                   done,
    output reg  [WORD_W-1:0]     band_code,
    output reg  [WORD_W-1:0]     measured_count
);
    // WORD_W must be at least two. Each measurement resolves one band bit.
    localparam integer POS_W = (WORD_W > 1) ? $clog2(WORD_W) : 1;
    localparam [POS_W-1:0] LAST_BIT = WORD_W - 1;
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] PREFIX_MASK = {WORD_W{1'b1}} ^ ONE;

    reg [WORD_W-1:0] trial_code;
    reg [POS_W-1:0] bit_pos;
    reg [WORD_W-1:0] prefix_shadow;
    reg shadow_valid;

    // Both interfaces transfer only on enabled cycles. Neither valid nor
    // input ready waits for the corresponding opposite handshake signal.
    assign measurement_ready = i_ce && !done;
    assign result_valid = i_ce && done;
    wire take_measurement = measurement_valid && measurement_ready;

    wire [WORD_W-1:0] accepted_code =
        (measurement_count_in <= REFERENCE_COUNT)
        ? trial_code
        : (trial_code & ~(ONE << bit_pos));

    initial begin
        trial_code = ONE << LAST_BIT;
        bit_pos = LAST_BIT;
        prefix_shadow = ZERO;
        shadow_valid = 1'b0;
        done = 1'b0;
        band_code = ZERO;
        measured_count = ZERO;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (done) begin
                // Hold the completed result until its own receiver takes it,
                // then restart the search instead of remaining done forever.
                if (result_ready) begin
                    done <= 1'b0;
                    trial_code <= ONE << LAST_BIT;
                    bit_pos <= LAST_BIT;
                    prefix_shadow <= ZERO;
                    shadow_valid <= 1'b0;
                end
            end else if (take_measurement) begin
                measured_count <= measurement_count_in;
                if (bit_pos != 0) begin
                    prefix_shadow <= accepted_code;
                    shadow_valid <= 1'b1;
                    bit_pos <= bit_pos - 1'b1;
                    trial_code <= accepted_code |
                                  (ONE << (bit_pos - 1'b1));
                end else begin
                    band_code <= accepted_code;
                    done <= 1'b1;
                end
            end
        end
    end

    // A completed calibration preserves all previously resolved upper bits.
    always @(posedge clk) begin
        if (done)
            assert (shadow_valid &&
                    ((band_code & PREFIX_MASK) ==
                     (prefix_shadow & PREFIX_MASK)));
    end
endmodule

module sklansky_result_channel #(
    parameter integer WIDTH = 32
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [WIDTH-1:0]     in_a,
    input  wire [WIDTH-1:0]     in_b,
    output wire                 out_valid,
    input  wire                 out_ready,
    output wire [WIDTH-1:0]     out_sum,
    output wire                 out_carry
);
    localparam integer LEVELS = $clog2(WIDTH);

    // Two storage slots: a captured-prefix tail and a reconstructed front.
    reg pending;
    reg window;
    reg [WIDTH-1:0] operand_a, operand_b;
    reg [WIDTH-1:0] propagate_hold, prefix_hold;
    reg [WIDTH-1:0] result_a, result_b;
    reg [WIDTH-1:0] result_sum;
    reg result_carry;

    wire [WIDTH-1:0] tree_g [0:LEVELS];
    wire [WIDTH-1:0] tree_p [0:LEVELS];

    assign tree_g[0] = in_a & in_b;
    assign tree_p[0] = in_a ^ in_b;

    // Sklansky tree: each upper half shares the lower half's root.
    genvar level, bit_index;
    generate
        for (level = 0; level < LEVELS; level = level + 1) begin : prefix_level
            localparam integer HALF = 1 << level;
            localparam integer GROUP = HALF << 1;
            for (bit_index = 0; bit_index < WIDTH; bit_index = bit_index + 1) begin : prefix_bit
                if ((bit_index % GROUP) >= HALF) begin : combine
                    localparam integer ROOT = (bit_index / GROUP) * GROUP + HALF - 1;
                    assign tree_g[level+1][bit_index] =
                        tree_g[level][bit_index] |
                        (tree_p[level][bit_index] & tree_g[level][ROOT]);
                    assign tree_p[level+1][bit_index] =
                        tree_p[level][bit_index] & tree_p[level][ROOT];
                end else begin : bypass
                    assign tree_g[level+1][bit_index] = tree_g[level][bit_index];
                    assign tree_p[level+1][bit_index] = tree_p[level][bit_index];
                end
            end
        end
    endgenerate

    wire [WIDTH-1:0] pending_sum;
    wire pending_carry;
    assign pending_sum = propagate_hold ^ (prefix_hold << 1);
    assign pending_carry = prefix_hold[WIDTH-1];

    // A lone prefix-slot item is directly visible: valid never waits for ready.
    assign out_valid = window || pending;
    assign out_sum = window ? result_sum : pending_sum;
    assign out_carry = window ? result_carry : pending_carry;
    assign in_ready = !(window && pending) || out_ready;

    wire push;
    wire pop;
    wire promote;
    assign push = in_valid && in_ready;
    assign pop = out_valid && out_ready;

    // Promote the tail when removing an occupied front, or when an arriving
    // item needs the occupied tail slot and the front is empty.
    assign promote = pending && ((pop && window) || (push && !pop));

    wire [WIDTH:0] reference_sum;
    assign reference_sum = window
        ? ({1'b0, result_a} + {1'b0, result_b})
        : ({1'b0, operand_a} + {1'b0, operand_b});

    initial begin
        pending = 1'b0;
        window = 1'b0;
        operand_a = {WIDTH{1'b0}};
        operand_b = {WIDTH{1'b0}};
        propagate_hold = {WIDTH{1'b0}};
        prefix_hold = {WIDTH{1'b0}};
        result_a = {WIDTH{1'b0}};
        result_b = {WIDTH{1'b0}};
        result_sum = {WIDTH{1'b0}};
        result_carry = 1'b0;
    end

    // Every register holds when in_valid and out_ready are both low.
    always @(posedge clk) begin
        if (pop) begin
            pending <= 1'b0;
            window <= 1'b0;
        end

        if (promote) begin
            result_a <= operand_a;
            result_b <= operand_b;
            result_sum <= pending_sum;
            result_carry <= pending_carry;
            window <= 1'b1;
        end

        if (push) begin
            operand_a <= in_a;
            operand_b <= in_b;
            propagate_hold <= tree_p[0];
            prefix_hold <= tree_g[LEVELS];
            pending <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (out_valid)
            assert ({out_carry, out_sum} == reference_sum);
    end
endmodule

module exponent_swap_launch #(
    parameter integer WORD_W = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire                  in_scope_q,
    input  wire [WORD_W-1:0]     in_exp_a,
    input  wire [WORD_W-1:0]     in_exp_b,
    input  wire [WORD_W-1:0]     in_sig_a,
    input  wire [WORD_W-1:0]     in_sig_b,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [WORD_W-1:0]     out_exp,
    output wire [WORD_W-1:0]     out_big_sig,
    output wire [WORD_W-1:0]     out_small_sig,
    output wire [WORD_W-1:0]     out_delta,
    output wire                  out_swapped
);
    typedef enum logic [1:0] {
        IDLE, ARMED, STARTED, FINISHED
    } state_t;
    state_t state;

    reg [WORD_W-1:0] hi_exp;
    reg [WORD_W-1:0] lo_exp;
    reg [WORD_W-1:0] hi_sig;
    reg [WORD_W-1:0] lo_sig;
    reg [WORD_W-1:0] exp_delta;
    reg [WORD_W-1:0] launch_exp;
    reg swapped;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    wire choose_b = (in_exp_b > in_exp_a) ||
                    ((in_exp_b == in_exp_a) && (in_sig_b > in_sig_a));

    // i_ce explicitly enables both state updates and interface transfers.
    // Neither input acceptance nor internal progress waits for out_ready.
    assign in_ready      = i_ce && (state == IDLE);
    assign out_valid     = i_ce && (state == FINISHED);
    assign out_exp       = hi_exp;
    assign out_big_sig   = hi_sig;
    assign out_small_sig = lo_sig;
    assign out_delta     = exp_delta;
    assign out_swapped   = swapped;

    initial begin
        state       = IDLE;
        hi_exp      = {WORD_W{1'b0}};
        lo_exp      = {WORD_W{1'b0}};
        hi_sig      = {WORD_W{1'b0}};
        lo_sig      = {WORD_W{1'b0}};
        exp_delta   = {WORD_W{1'b0}};
        launch_exp  = {WORD_W{1'b0}};
        swapped     = 1'b0;
        arm_seen    = 1'b0;
        start_seen  = 1'b0;
        scope_armed = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                IDLE: begin
                    if (in_valid) begin
                        // Capture whenever this transaction slot is empty.
                        hi_exp    <= choose_b ? in_exp_b : in_exp_a;
                        lo_exp    <= choose_b ? in_exp_a : in_exp_b;
                        hi_sig    <= choose_b ? in_sig_b : in_sig_a;
                        lo_sig    <= choose_b ? in_sig_a : in_sig_b;
                        exp_delta <= choose_b ? (in_exp_b - in_exp_a)
                                              : (in_exp_a - in_exp_b);
                        swapped    <= choose_b;
                        arm_seen   <= 1'b1;
                        start_seen <= 1'b0;
                        state      <= ARMED;
                        if (in_scope_q)
                            scope_armed <= 1'b1;
                    end
                end
                ARMED: begin
                    // Reconstruct the alignment target without waiting
                    // for the downstream receiver to assert ready.
                    launch_exp <= lo_exp + exp_delta;
                    start_seen <= 1'b1;
                    state      <= STARTED;
                end
                STARTED: begin
                    state <= FINISHED;
                end
                FINISHED: begin
                    // Only retirement depends on downstream readiness.
                    // Otherwise keep the completed item unchanged.
                    if (out_ready) begin
                        arm_seen   <= 1'b0;
                        start_seen <= 1'b0;
                        state      <= IDLE;
                    end
                end
            endcase
        end
    end

    assert property (!scope_armed ||
                     ((!start_seen || arm_seen) &&
                      ((state != FINISHED) ||
                       (arm_seen && start_seen && (launch_exp == hi_exp)))));
endmodule

module ddr_waveform_capture #(
    parameter integer WORD_BITS = 8
) (
    input  wire clk,
    input  wire i_ce,
    input  wire serial_in,
    input  wire flush,
    input  wire resume,
    output wire [WORD_BITS-1:0] recent_word,
    output wire [WORD_BITS-1:0] older_word,
    output wire [WORD_BITS-1:0] recent_check,
    output wire [WORD_BITS-1:0] older_check
);
    // WORD_BITS is even and at least four.
    localparam integer HALF_WORD = WORD_BITS / 2;
    localparam [1:0] CAPTURE = 2'b00;
    localparam [1:0] DRAIN   = 2'b01;

    reg [1:0] state;
    reg phase;
    reg [WORD_BITS-1:0] rise_data;
    reg [WORD_BITS-1:0] rise_check;
    reg [WORD_BITS-1:0] fall_data;
    reg [WORD_BITS-1:0] fall_check;

    initial begin
        state      = CAPTURE;
        phase      = 1'b0;
        rise_data  = {WORD_BITS{1'b0}};
        rise_check = {WORD_BITS{1'b1}};
        fall_data  = {WORD_BITS{1'b0}};
        fall_check = {WORD_BITS{1'b1}};
    end

    // clk is a uniform half-cycle sampling clock. Alternating phases
    // model the two DDR edges without opposite-polarity clocked flops.
    // Disabling i_ce freezes both the phase and every history register.
    always @(posedge clk) begin
        if (i_ce) begin
            phase <= ~phase;
            if (!phase) begin
                case (state)
                    CAPTURE: if (flush)  state <= DRAIN;
                    DRAIN:   if (resume) state <= CAPTURE;
                    default: state <= CAPTURE;
                endcase

                rise_data <= {rise_data[WORD_BITS-2:0],
                              (state == CAPTURE) ? serial_in : 1'b0};
                rise_check <= {rise_check[WORD_BITS-2:0],
                               (state == CAPTURE) ? ~serial_in : 1'b1};
            end else begin
                fall_data <= {fall_data[WORD_BITS-2:0],
                              (state == CAPTURE) ? serial_in : 1'b0};
                fall_check <= {fall_check[WORD_BITS-2:0],
                               (state == CAPTURE) ? ~serial_in : 1'b1};
            end
        end
    end

    genvar bit_index;
    generate
        for (bit_index = 0; bit_index < HALF_WORD; bit_index = bit_index + 1) begin : merge_lanes
            assign recent_word[2*bit_index]    = rise_data[bit_index];
            assign recent_word[2*bit_index+1]  = fall_data[bit_index];
            assign recent_check[2*bit_index]   = rise_check[bit_index];
            assign recent_check[2*bit_index+1] = fall_check[bit_index];
            assign older_word[2*bit_index]     = rise_data[HALF_WORD+bit_index];
            assign older_word[2*bit_index+1]   = fall_data[HALF_WORD+bit_index];
            assign older_check[2*bit_index]    = rise_check[HALF_WORD+bit_index];
            assign older_check[2*bit_index+1]  = fall_check[HALF_WORD+bit_index];
        end
    endgenerate

    always @(*) begin
        if (state == CAPTURE)
            assert ((recent_word[WORD_BITS-1:WORD_BITS-2] ==
                     ~recent_check[WORD_BITS-1:WORD_BITS-2]) &&
                    (older_word[WORD_BITS-1:WORD_BITS-2] ==
                     ~older_check[WORD_BITS-1:WORD_BITS-2]));
    end
endmodule

module aes_subbytes_audit #(
    parameter integer WORD_BITS = 64,
    parameter integer PIPE_ENTRIES = 6
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_valid,
    output wire i_ready,
    input  wire [WORD_BITS-1:0] i_data,
    input  wire i_begin,
    input  wire i_finish,
    output wire o_valid,
    input  wire o_ready,
    output wire [WORD_BITS-1:0] o_data
);
    // WORD_BITS is a positive multiple of eight; PIPE_ENTRIES is at least six.
    // Entries beyond stage five are elastic output holding stages.
    localparam [WORD_BITS-1:0] ZERO_WORD = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] ZERO_IMAGE = {(WORD_BITS/8){8'h63}};

    // GF(16), with polynomial z^4 + z + 1.
    function automatic [3:0] mul4;
        input [3:0] a;
        input [3:0] b;
        reg [3:0] p, t;
        integer k;
        begin
            p = 4'h0;
            t = a;
            for (k = 0; k < 4; k = k + 1) begin
                if (b[k]) p = p ^ t;
                t = {t[2:0], 1'b0} ^ (t[3] ? 4'h3 : 4'h0);
            end
            mul4 = p;
        end
    endfunction

    function automatic [3:0] inv4;
        input [3:0] a;
        reg [3:0] a2, a4, a8;
        begin
            a2 = mul4(a, a);
            a4 = mul4(a2, a2);
            a8 = mul4(a4, a4);
            inv4 = mul4(mul4(a2, a4), a8);
        end
    endfunction

    // {b,a} represents a + b*u, with u^2 + u + 8 = 0.
    function automatic [7:0] tower_mul;
        input [7:0] x;
        input [7:0] y;
        reg [3:0] ac, bd, lo, hi;
        begin
            ac = mul4(x[3:0], y[3:0]);
            bd = mul4(x[7:4], y[7:4]);
            lo = ac ^ mul4(4'h8, bd);
            hi = mul4(x[3:0], y[7:4]) ^ mul4(x[7:4], y[3:0]) ^ bd;
            tower_mul = {hi, lo};
        end
    endfunction

    function automatic [7:0] find_root;
        reg [7:0] x, x2, x3, x4, x8;
        integer k;
        begin
            find_root = 8'h00;
            for (k = 1; k < 256; k = k + 1) begin
                x = k[7:0];
                x2 = tower_mul(x, x);
                x3 = tower_mul(x2, x);
                x4 = tower_mul(x2, x2);
                x8 = tower_mul(x4, x4);
                if ((x8 ^ x4 ^ x3 ^ x ^ 8'h01) == 8'h00)
                    find_root = x;
            end
        end
    endfunction

    function automatic [63:0] make_basis;
        input [7:0] root;
        reg [7:0] power;
        integer k;
        begin
            make_basis = 64'd0;
            power = 8'h01;
            for (k = 0; k < 8; k = k + 1) begin
                make_basis[8*k +: 8] = power;
                power = tower_mul(power, root);
            end
        end
    endfunction

    function automatic [7:0] linear8;
        input [7:0] x;
        input [63:0] basis;
        reg [7:0] y;
        integer k;
        begin
            y = 8'h00;
            for (k = 0; k < 8; k = k + 1)
                if (x[k]) y = y ^ basis[8*k +: 8];
            linear8 = y;
        end
    endfunction

    function automatic [63:0] inverse_basis;
        input [63:0] basis;
        integer k, candidate;
        begin
            inverse_basis = 64'd0;
            for (k = 0; k < 8; k = k + 1)
                for (candidate = 0; candidate < 256; candidate = candidate + 1)
                    if (linear8(candidate[7:0], basis) == (8'h01 << k))
                        inverse_basis[8*k +: 8] = candidate[7:0];
        end
    endfunction

    localparam [63:0] TO_TOWER = make_basis(find_root());
    localparam [63:0] FROM_TOWER = inverse_basis(TO_TOWER);

    function automatic [WORD_BITS-1:0] map_word;
        input [WORD_BITS-1:0] x;
        integer lane;
        begin
            map_word = ZERO_WORD;
            for (lane = 0; lane < WORD_BITS/8; lane = lane + 1)
                map_word[8*lane +: 8] = linear8(x[8*lane +: 8], TO_TOWER);
        end
    endfunction

    function automatic [WORD_BITS-1:0] norm_word;
        input [WORD_BITS-1:0] x;
        reg [3:0] a, b, n;
        integer lane;
        begin
            norm_word = ZERO_WORD;
            for (lane = 0; lane < WORD_BITS/8; lane = lane + 1) begin
                a = x[8*lane +: 4];
                b = x[8*lane+4 +: 4];
                n = mul4(a, a) ^ mul4(a, b) ^ mul4(4'h8, mul4(b, b));
                norm_word[8*lane +: 8] = {4'h0, n};
            end
        end
    endfunction

    function automatic [WORD_BITS-1:0] invnorm_word;
        input [WORD_BITS-1:0] x;
        integer lane;
        begin
            invnorm_word = ZERO_WORD;
            for (lane = 0; lane < WORD_BITS/8; lane = lane + 1)
                invnorm_word[8*lane +: 8] = {4'h0, inv4(x[8*lane +: 4])};
        end
    endfunction

    function automatic [WORD_BITS-1:0] tower_inverse_word;
        input [WORD_BITS-1:0] mapped;
        input [WORD_BITS-1:0] inverse_norm;
        reg [3:0] a, b, n;
        integer lane;
        begin
            tower_inverse_word = ZERO_WORD;
            for (lane = 0; lane < WORD_BITS/8; lane = lane + 1) begin
                a = mapped[8*lane +: 4];
                b = mapped[8*lane+4 +: 4];
                n = inverse_norm[8*lane +: 4];
                tower_inverse_word[8*lane +: 8] = {mul4(b, n), mul4(a ^ b, n)};
            end
        end
    endfunction

    function automatic [WORD_BITS-1:0] unmap_word;
        input [WORD_BITS-1:0] x;
        integer lane;
        begin
            unmap_word = ZERO_WORD;
            for (lane = 0; lane < WORD_BITS/8; lane = lane + 1)
                unmap_word[8*lane +: 8] = linear8(x[8*lane +: 8], FROM_TOWER);
        end
    endfunction

    function automatic [WORD_BITS-1:0] affine_word;
        input [WORD_BITS-1:0] x;
        reg [7:0] b;
        integer lane;
        begin
            affine_word = ZERO_WORD;
            for (lane = 0; lane < WORD_BITS/8; lane = lane + 1) begin
                b = x[8*lane +: 8];
                affine_word[8*lane +: 8] = b ^ {b[6:0], b[7]} ^
                    {b[5:0], b[7:6]} ^ {b[4:0], b[7:5]} ^
                    {b[3:0], b[7:4]} ^ 8'h63;
            end
        end
    endfunction

    function automatic [WORD_BITS-1:0] advance_word;
        input [WORD_BITS-1:0] previous;
        input [WORD_BITS-1:0] original;
        input integer stage_number;
        begin
            case (stage_number)
                1: advance_word = norm_word(previous);
                2: advance_word = invnorm_word(previous);
                3: advance_word = tower_inverse_word(map_word(original), previous);
                4: advance_word = unmap_word(previous);
                5: advance_word = affine_word(previous);
                default: advance_word = previous;
            endcase
        end
    endfunction

    reg [WORD_BITS-1:0] source [0:PIPE_ENTRIES-1];
    reg [WORD_BITS-1:0] payload [0:PIPE_ENTRIES-1];
    reg [PIPE_ENTRIES-1:0] valid;
    reg audit_window;
    wire [PIPE_ENTRIES-1:0] zero_consistent;
    wire [PIPE_ENTRIES:0] stage_ready;

    // Each stage accepts whenever empty or its current item can advance.
    // Thus valid items advance into empty stages without requiring o_ready.
    assign stage_ready[PIPE_ENTRIES] = o_ready;
    assign i_ready = stage_ready[0];
    assign o_valid = valid[PIPE_ENTRIES-1];
    assign o_data = payload[PIPE_ENTRIES-1];

    initial begin
        valid = {PIPE_ENTRIES{1'b0}};
        audit_window = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            audit_window <= 1'b0;
        end else if (i_valid && i_ready) begin
            if (i_finish)
                audit_window <= 1'b0;
            else if (i_begin)
                audit_window <= 1'b1;
        end
    end

    genvar g;
    generate
        for (g = 0; g < PIPE_ENTRIES; g = g + 1) begin : stages
            assign stage_ready[g] = !valid[g] || stage_ready[g+1];

            initial begin
                source[g] = ZERO_WORD;
                payload[g] = ZERO_WORD;
            end

            if (g == 0) begin : input_stage
                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        valid[g] <= 1'b0;
                        source[g] <= ZERO_WORD;
                        payload[g] <= ZERO_WORD;
                    end else if (stage_ready[g]) begin
                        valid[g] <= i_valid;
                        if (i_valid) begin
                            source[g] <= i_data;
                            payload[g] <= map_word(i_data);
                        end
                    end
                end
            end else begin : later_stage
                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        valid[g] <= 1'b0;
                        source[g] <= ZERO_WORD;
                        payload[g] <= ZERO_WORD;
                    end else if (stage_ready[g]) begin
                        valid[g] <= valid[g-1];
                        if (valid[g-1]) begin
                            source[g] <= source[g-1];
                            payload[g] <= advance_word(payload[g-1], source[g-1], g);
                        end
                    end
                end
            end

            if (g < 5) begin : before_affine
                assign zero_consistent[g] = !valid[g] ||
                    (source[g] != ZERO_WORD) || (payload[g] == ZERO_WORD);
            end else begin : after_affine
                assign zero_consistent[g] = !valid[g] ||
                    (source[g] != ZERO_WORD) || (payload[g] == ZERO_IMAGE);
            end
        end
    endgenerate

    // With every slot occupied, holding o_ready low freezes all state,
    // including audit_window because no input handshake can occur.
    wire zero_operand = (source[PIPE_ENTRIES-1] == ZERO_WORD);
    wire noncanonical_result = (o_data != ZERO_IMAGE);

    always @(posedge clk)
        if (audit_window && o_valid)
            assert (!(zero_operand && noncanonical_result));
endmodule

module scoped_ghash_engine #(
    parameter integer WORD_BITS = 64
) (
    input wire i_clk,
    input wire i_ce,
    input wire i_open,
    input wire i_close,
    input wire i_load_h,
    input wire i_start,
    input wire [WORD_BITS-1:0] i_h_hi,
    input wire [WORD_BITS-1:0] i_h_lo,
    input wire [WORD_BITS-1:0] i_block_hi,
    input wire [WORD_BITS-1:0] i_block_lo,
    output wire o_busy,
    output wire o_tag_valid,
    output wire [WORD_BITS-1:0] o_tag_hi,
    output wire [WORD_BITS-1:0] o_tag_lo
);
    localparam integer WORD_ROUNDS = WORD_BITS;
    localparam integer BLOCK_ROUNDS = 2 * WORD_BITS;
    localparam integer LAST_BIT = BLOCK_ROUNDS - 1;
    localparam integer INDEX_BITS = $clog2(BLOCK_ROUNDS);
    localparam integer COUNT_BITS = $clog2(BLOCK_ROUNDS + 1);
    localparam [WORD_BITS-1:0] REDUCTION =
        {8'he1, {(WORD_BITS-8){1'b0}}};

    reg [WORD_BITS-1:0] h_hi, h_lo;
    reg [WORD_BITS-1:0] tag_hi, tag_lo;
    reg [WORD_BITS-1:0] operand_hi, operand_lo;
    reg [WORD_BITS-1:0] v_hi, v_lo;
    reg [WORD_BITS-1:0] product_hi, product_lo;
    reg [INDEX_BITS-1:0] bit_index;
    reg [COUNT_BITS-1:0] rounds_left;
    reg tag_valid;
    reg window_open;

    wire busy = (rounds_left != 0);
    wire operand_bit = (bit_index < WORD_ROUNDS)
        ? operand_hi[WORD_ROUNDS - 1 - bit_index]
        : operand_lo[LAST_BIT - bit_index];
    wire [WORD_BITS-1:0] product_next_hi =
        product_hi ^ (operand_bit ? v_hi : {WORD_BITS{1'b0}});
    wire [WORD_BITS-1:0] product_next_lo =
        product_lo ^ (operand_bit ? v_lo : {WORD_BITS{1'b0}});

    assign o_busy = busy;
    assign o_tag_valid = tag_valid;
    assign o_tag_hi = tag_hi;
    assign o_tag_lo = tag_lo;

    initial begin
        h_hi = '0;
        h_lo = '0;
        tag_hi = '0;
        tag_lo = '0;
        operand_hi = '0;
        operand_lo = '0;
        v_hi = '0;
        v_lo = '0;
        product_hi = '0;
        product_lo = '0;
        bit_index = '0;
        rounds_left = '0;
        tag_valid = 1'b0;
        window_open = 1'b0;
    end

    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_close)
                window_open <= 1'b0;
            else if (i_open)
                window_open <= 1'b1;

            tag_valid <= 1'b0;
            if (!busy) begin
                if (i_load_h) begin
                    h_hi <= i_h_hi;
                    h_lo <= i_h_lo;
                    tag_hi <= '0;
                    tag_lo <= '0;
                end else if (i_start) begin
                    // GHASH recurrence: tag := (tag XOR block) * H.
                    operand_hi <= tag_hi ^ i_block_hi;
                    operand_lo <= tag_lo ^ i_block_lo;
                    v_hi <= h_hi;
                    v_lo <= h_lo;
                    product_hi <= '0;
                    product_lo <= '0;
                    bit_index <= '0;
                    rounds_left <= BLOCK_ROUNDS;
                end
            end else begin
                product_hi <= product_next_hi;
                product_lo <= product_next_lo;

                // GF(2^128) right-shift multiplication at WORD_BITS=64.
                v_hi <= {1'b0, v_hi[WORD_BITS-1:1]}
                    ^ (v_lo[0] ? REDUCTION : {WORD_BITS{1'b0}});
                v_lo <= {v_hi[0], v_lo[WORD_BITS-1:1]};
                rounds_left <= rounds_left - 1'b1;

                if (bit_index == LAST_BIT) begin
                    tag_hi <= product_next_hi;
                    tag_lo <= product_next_lo;
                    tag_valid <= 1'b1;
                    bit_index <= '0;
                end else begin
                    bit_index <= bit_index + 1'b1;
                end
            end
        end
    end

    // A valid tag inside the monitoring window must not coincide with busy.
    // This same-cycle guard requires no sampled-value function.
    always @(posedge i_clk)
        if (window_open && tag_valid)
            assert (!busy);
endmodule

module detector_window_file #(
    parameter integer NUM_WINDOWS = 2,
    parameter integer DATA_W = 64,
    parameter integer PTR_W = (NUM_WINDOWS > 1) ? $clog2(NUM_WINDOWS) : 1
) (
    input  wire clk,
    input  wire ce,
    input  wire q_open,
    input  wire r_close,
    input  wire advance_window,
    input  wire transfer_start,
    input  wire transfer_done,
    input  wire retire,
    input  wire write_local,
    input  wire write_out,
    input  wire [DATA_W-1:0] write_data,
    input  wire [DATA_W-1:0] fill_local_data,
    input  wire [DATA_W-1:0] fill_out_data,
    output wire [DATA_W-1:0] win_in,
    output wire [DATA_W-1:0] win_local,
    output wire [DATA_W-1:0] win_out,
    output wire spill_trap,
    output wire fill_busy,
    output wire window_done
);
    // NUM_WINDOWS must be at least two.
    typedef enum logic [1:0] {
        READY    = 2'd0,
        ARMED    = 2'd1,
        TRANSFER = 2'd2,
        FINISHED = 2'd3
    } state_t;

    localparam [PTR_W-1:0] PTR_ZERO = {PTR_W{1'b0}};
    localparam [PTR_W-1:0] PTR_ONE = {{(PTR_W-1){1'b0}}, 1'b1};
    localparam [PTR_W-1:0] LAST_WINDOW = NUM_WINDOWS - 1;
    localparam [NUM_WINDOWS-1:0] ALL_INVALID = {NUM_WINDOWS{1'b1}};
    localparam [NUM_WINDOWS-1:0] ONE_WINDOW =
        {{(NUM_WINDOWS-1){1'b0}}, 1'b1};

    state_t phase;
    reg scope_open;
    reg armed_seen;
    reg started_seen;
    reg [PTR_W-1:0] cwp;
    reg [PTR_W-1:0] target;
    reg [NUM_WINDOWS-1:0] invalid_mask;
    reg [DATA_W-1:0] local_bank [0:NUM_WINDOWS-1];
    reg [DATA_W-1:0] out_bank [0:NUM_WINDOWS-1];

    wire [PTR_W-1:0] previous_window =
        (cwp == PTR_ZERO) ? LAST_WINDOW : (cwp - PTR_ONE);
    wire [PTR_W-1:0] target_next =
        (target == LAST_WINDOW) ? PTR_ZERO : (target + PTR_ONE);
    wire [NUM_WINDOWS-1:0] current_bit = ONE_WINDOW << cwp;
    wire [NUM_WINDOWS-1:0] target_bit = ONE_WINDOW << target;

    assign win_in = out_bank[previous_window];
    assign win_local = local_bank[cwp];
    assign win_out = out_bank[cwp];
    assign spill_trap = scope_open && (phase == ARMED);
    assign fill_busy = scope_open && (phase == TRANSFER);
    assign window_done = scope_open && (phase == FINISHED);

    initial begin
        phase = READY;
        scope_open = 1'b0;
        armed_seen = 1'b0;
        started_seen = 1'b0;
        cwp = PTR_ZERO;
        target = PTR_ONE;
        // Explicit width: every bank except bank zero starts invalid.
        invalid_mask = {{(NUM_WINDOWS-1){1'b1}}, 1'b0};
        for (integer idx = 0; idx < NUM_WINDOWS; idx = idx + 1) begin
            local_bank[idx] = {DATA_W{1'b0}};
            out_bank[idx] = {DATA_W{1'b0}};
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            if (r_close) begin
                scope_open <= 1'b0;
                phase <= READY;
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
            end else if (q_open && !scope_open) begin
                scope_open <= 1'b1;
                phase <= READY;
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
            end else if (scope_open) begin
                case (phase)
                    READY: begin
                        if (write_local)
                            local_bank[cwp] <= write_data;
                        if (write_out)
                            out_bank[cwp] <= write_data;
                        if (advance_window) begin
                            if (invalid_mask[target]) begin
                                phase <= ARMED;
                                armed_seen <= 1'b1;
                                started_seen <= 1'b0;
                            end else begin
                                // Resident-target fast path bypasses transfer.
                                cwp <= target;
                                target <= target_next;
                                invalid_mask <= (invalid_mask | current_bit)
                                                & (ALL_INVALID ^ target_bit);
                                phase <= FINISHED;
                            end
                        end
                    end
                    ARMED: begin
                        if (transfer_start) begin
                            started_seen <= 1'b1;
                            phase <= TRANSFER;
                        end
                    end
                    TRANSFER: begin
                        if (transfer_done) begin
                            local_bank[target] <= fill_local_data;
                            out_bank[target] <= fill_out_data;
                            invalid_mask <= (invalid_mask | current_bit)
                                            & (ALL_INVALID ^ target_bit);
                            cwp <= target;
                            target <= target_next;
                            phase <= FINISHED;
                        end
                    end
                    FINISHED: begin
                        if (retire) begin
                            phase <= READY;
                            armed_seen <= 1'b0;
                            started_seen <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    // A transfer requires arming; completion requires arming and starting.
    always @(posedge clk) begin
        if (scope_open)
            assert (((phase != TRANSFER) || armed_seen) &&
                    ((phase != FINISHED) || (armed_seen && started_seen)));
    end
endmodule

module rs485_buffered_turnaround #(
    parameter integer DEPTH = 16,
    parameter integer DATA_WIDTH = 16,
    parameter integer PRE_TICKS = 4,
    parameter integer TURN_TICKS = 4
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  s_valid,
    output wire                  s_ready,
    input  wire [DATA_WIDTH-1:0] s_data,
    output wire                  tx_valid,
    input  wire                  tx_ready,
    output wire                  tx_bit,
    output reg                   driver_enable,
    output reg                   tx_active
);
    localparam integer PTR_W = (DEPTH <= 1) ? 1 : $clog2(DEPTH);
    localparam integer COUNT_W = $clog2(DEPTH + 1);
    localparam integer BIT_W = $clog2(DATA_WIDTH + 2);
    localparam integer GUARD_LIMIT = (PRE_TICKS > TURN_TICKS)
                                      ? PRE_TICKS : TURN_TICKS;
    localparam integer GUARD_W = (GUARD_LIMIT < 1)
                                  ? 1 : $clog2(GUARD_LIMIT + 1);

    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [PTR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [BIT_W-1:0] STOP_INDEX = DATA_WIDTH + 1;
    localparam [1:0] PH_IDLE = 2'd0;
    localparam [1:0] PH_PRE  = 2'd1;
    localparam [1:0] PH_SEND = 2'd2;
    localparam [1:0] PH_TURN = 2'd3;

    // Packed storage contains DEPTH independently addressed FIFO words.
    reg [DEPTH*DATA_WIDTH-1:0] fifo;
    reg [PTR_W-1:0] read_ptr;
    reg [PTR_W-1:0] write_ptr;
    reg [COUNT_W-1:0] queued_count;
    reg [DATA_WIDTH-1:0] current_word;
    reg [GUARD_W-1:0] guard_count;
    reg [BIT_W-1:0] bit_index;
    reg [1:0] phase;

    initial begin
        fifo = '0;
        read_ptr = '0;
        write_ptr = '0;
        queued_count = '0;
        current_word = '0;
        guard_count = '0;
        bit_index = '0;
        phase = PH_IDLE;
        driver_enable = 1'b0;
        tx_active = 1'b0;
    end

    // Disabled cycles accept no interface transfers and freeze all state.
    assign s_ready = i_ce && (queued_count < CAPACITY);
    assign tx_valid = i_ce && tx_active;

    wire push_word = s_valid && s_ready;
    wire retire_word = i_ce && (phase == PH_TURN) &&
                       (guard_count == 0);

    assign tx_bit = (phase != PH_SEND) ? 1'b1 :
                    (bit_index == 0) ? 1'b0 :
                    (bit_index == STOP_INDEX) ? 1'b1 :
                    current_word[bit_index - 1'b1];

    always @(posedge clk) begin
        if (i_ce) begin
            if (push_word) begin
                fifo[write_ptr*DATA_WIDTH +: DATA_WIDTH] <= s_data;
                write_ptr <= (write_ptr == LAST_SLOT)
                             ? '0 : write_ptr + 1'b1;
            end

            // The head remains allocated until turnaround completes.
            if (retire_word) begin
                read_ptr <= (read_ptr == LAST_SLOT)
                            ? '0 : read_ptr + 1'b1;
            end

            case ({push_word, retire_word})
                2'b10: queued_count <= queued_count + 1'b1;
                2'b01: queued_count <= queued_count - 1'b1;
                default: begin end
            endcase

            case (phase)
                PH_IDLE: begin
                    // Starting a word never waits for downstream ready.
                    if (queued_count != 0) begin
                        current_word <= fifo[read_ptr*DATA_WIDTH +: DATA_WIDTH];
                        driver_enable <= 1'b1;
                        guard_count <= PRE_TICKS;
                        bit_index <= '0;
                        phase <= PH_PRE;
                    end
                end
                PH_PRE: begin
                    // Guard time advances independently of tx_ready.
                    if (guard_count == 0) begin
                        tx_active <= 1'b1;
                        phase <= PH_SEND;
                    end else begin
                        guard_count <= guard_count - 1'b1;
                    end
                end
                PH_SEND: begin
                    // Only actual serial symbols require a ready handshake.
                    if (tx_ready) begin
                        if (bit_index == STOP_INDEX) begin
                            tx_active <= 1'b0;
                            guard_count <= TURN_TICKS;
                            phase <= PH_TURN;
                        end else begin
                            bit_index <= bit_index + 1'b1;
                        end
                    end
                end
                PH_TURN: begin
                    // Retirement must not wait for ready after valid drops.
                    if (guard_count == 0) begin
                        driver_enable <= 1'b0;
                        bit_index <= '0;
                        phase <= PH_IDLE;
                    end else begin
                        guard_count <= guard_count - 1'b1;
                    end
                end
            endcase
        end
    end

    always @(posedge clk)
        if (tx_active) assert (driver_enable);
endmodule

module retro_key_distance_cam #(
    parameter integer ENTRIES = 8,
    parameter integer WORD_BITS = 32
) (
    input  wire                   clk,
    input  wire                   rst_n,
    input  wire                   i_ce,
    input  wire                   i_req_valid,
    output wire                   o_req_ready,
    input  wire [31:0]            i_req_opcode,
    input  wire [31:0]            i_req_index,
    input  wire [WORD_BITS-1:0]   i_req_data,
    output wire                   o_rsp_valid,
    input  wire                   i_rsp_ready,
    output wire [31:0]            o_rsp_count,
    output wire [ENTRIES-1:0]     o_rsp_hits
);
    localparam integer COUNT_BITS = $clog2(ENTRIES + 1);
    localparam [COUNT_BITS-1:0] ENTRY_LIMIT = ENTRIES;
    localparam [31:0] CMD_WRITE = 32'd0;
    localparam [31:0] CMD_INVALIDATE = 32'd1;
    localparam [31:0] CMD_THRESHOLD = 32'd2;
    localparam [31:0] CMD_SEARCH = 32'd3;

    reg [WORD_BITS-1:0] keys [0:ENTRIES-1];
    reg [ENTRIES-1:0] entry_valid;
    reg [31:0] threshold;
    reg [ENTRIES-1:0] pending;
    reg [ENTRIES-1:0] retired;
    reg [COUNT_BITS-1:0] result_count;
    reg busy;
    reg response_valid;

    wire [ENTRIES-1:0] match_flags;
    wire request_fire;

    // An occupied response slot may be replaced when its response is taken.
    assign o_req_ready = i_ce && !busy && (!response_valid || i_rsp_ready);
    assign request_fire = i_req_valid && o_req_ready;
    // No interface transfers occur while the whole module is disabled.
    assign o_rsp_valid = i_ce && response_valid;
    assign o_rsp_count = result_count;
    assign o_rsp_hits = retired;

    initial begin
        entry_valid = {ENTRIES{1'b0}};
        threshold = 32'd2;
        pending = {ENTRIES{1'b0}};
        retired = {ENTRIES{1'b0}};
        result_count = {COUNT_BITS{1'b0}};
        busy = 1'b0;
        response_valid = 1'b0;
    end

    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : entry_compare
            localparam [31:0] ENTRY_NUMBER = g;
            wire [WORD_BITS-1:0] mismatch;
            reg [31:0] distance;
            integer bit_index;

            initial keys[g] = {WORD_BITS{1'b0}};
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    keys[g] <= {WORD_BITS{1'b0}};
                else if (i_ce && request_fire &&
                         i_req_opcode == CMD_WRITE &&
                         i_req_index == ENTRY_NUMBER)
                    keys[g] <= i_req_data;
            end

            assign mismatch = keys[g] ^ i_req_data;
            always @(*) begin
                distance = 32'd0;
                for (bit_index = 0; bit_index < WORD_BITS;
                     bit_index = bit_index + 1)
                    distance = distance + {{31{1'b0}}, mismatch[bit_index]};
            end
            assign match_flags[g] = entry_valid[g] && (distance <= threshold);
        end
    endgenerate

    reg [ENTRIES-1:0] chosen;
    reg found;
    integer select_index;
    always @(*) begin
        chosen = {ENTRIES{1'b0}};
        found = 1'b0;
        for (select_index = 0; select_index < ENTRIES;
             select_index = select_index + 1) begin
            if (pending[select_index] && !found) begin
                chosen[select_index] = 1'b1;
                found = 1'b1;
            end
        end
    end

    reg [COUNT_BITS-1:0] retired_population;
    integer population_index;
    always @(*) begin
        retired_population = {COUNT_BITS{1'b0}};
        for (population_index = 0; population_index < ENTRIES;
             population_index = population_index + 1)
            retired_population = retired_population +
                {{(COUNT_BITS-1){1'b0}}, retired[population_index]};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            entry_valid <= {ENTRIES{1'b0}};
            threshold <= 32'd2;
            pending <= {ENTRIES{1'b0}};
            retired <= {ENTRIES{1'b0}};
            result_count <= {COUNT_BITS{1'b0}};
            busy <= 1'b0;
            response_valid <= 1'b0;
        end else if (i_ce) begin
            if (response_valid && i_rsp_ready)
                response_valid <= 1'b0;

            if (request_fire) begin
                case (i_req_opcode)
                    CMD_WRITE: begin
                        if (i_req_index < ENTRIES)
                            entry_valid[i_req_index] <= 1'b1;
                    end
                    CMD_INVALIDATE: begin
                        if (i_req_index < ENTRIES)
                            entry_valid[i_req_index] <= 1'b0;
                    end
                    CMD_THRESHOLD: threshold <= i_req_data;
                    CMD_SEARCH: begin
                        pending <= match_flags;
                        retired <= {ENTRIES{1'b0}};
                        result_count <= {COUNT_BITS{1'b0}};
                        busy <= |match_flags;
                        response_valid <= !(|match_flags);
                    end
                    default: begin end
                endcase
            end

            // Work proceeds independently of downstream ready. The response
            // slot is reserved throughout the search, so completion cannot
            // overwrite an unconsumed response.
            if (busy) begin
                pending <= pending & ~chosen;
                retired <= retired | chosen;
                result_count <= result_count + 1'b1;
                if ((pending & ~chosen) == {ENTRIES{1'b0}}) begin
                    busy <= 1'b0;
                    response_valid <= 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (response_valid)
            assert (result_count <= ENTRY_LIMIT);
endmodule

module memory_scale_multiplier #(
    parameter integer WORD_W = 64
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [WORD_W-1:0]    fraction_a,
    input  wire [WORD_W-1:0]    fraction_b,
    input  wire [WORD_W-1:0]    exponent_a,
    input  wire [WORD_W-1:0]    exponent_b,
    input  wire                 load_bias,
    input  wire [WORD_W-1:0]    bias_in,
    output reg                  out_valid,
    input  wire                 out_ready,
    output reg  [WORD_W-1:0]    out_mantissa,
    output reg  [WORD_W-1:0]    out_exponent,
    output reg                  out_exact,
    output reg                  out_rounded_up
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] LEADING_ONE = {1'b1, {(WORD_W-1){1'b0}}};

    reg [WORD_W-1:0] exponent_bias;
    reg stage_valid;
    reg [WORD_W-1:0] product_hi;
    reg [WORD_W-1:0] product_lo;
    reg [WORD_W-1:0] exponent_sum;
    reg stage_guard;
    reg stage_sticky;

    wire [WORD_W-1:0] mantissa_a = {1'b1, fraction_a[WORD_W-2:0]};
    wire [WORD_W-1:0] mantissa_b = {1'b1, fraction_b[WORD_W-2:0]};
    wire [WORD_W-1:0] multiply_hi;
    wire [WORD_W-1:0] multiply_lo;
    assign {multiply_hi, multiply_lo} = mantissa_a * mantissa_b;

    wire normalize_high = multiply_hi[WORD_W-1];
    wire [WORD_W-1:0] normalized_hi = normalize_high
        ? multiply_hi
        : {multiply_hi[WORD_W-2:0], multiply_lo[WORD_W-1]};
    wire [WORD_W-1:0] normalized_lo = normalize_high
        ? multiply_lo
        : {multiply_lo[WORD_W-2:0], 1'b0};

    // An empty output slot can accept an item without downstream ready.
    // A full slot can be replaced on the same edge that consumes it.
    wire output_room = !out_valid || out_ready;
    assign in_ready = !stage_valid || output_room;
    wire input_fire = in_valid && in_ready;

    wire round_increment = stage_guard && (stage_sticky || product_hi[0]);
    wire round_carry = round_increment && (&product_hi);
    wire [WORD_W-1:0] rounded_mantissa =
        product_hi + (round_increment ? ONE : ZERO);

    initial begin
        exponent_bias = ZERO;
        stage_valid = 1'b0;
        product_hi = ZERO;
        product_lo = ZERO;
        exponent_sum = ZERO;
        stage_guard = 1'b0;
        stage_sticky = 1'b0;
        out_valid = 1'b0;
        out_mantissa = ZERO;
        out_exponent = ZERO;
        out_exact = 1'b0;
        out_rounded_up = 1'b0;
    end

    always @(posedge clk) begin
        // A bias load affects subsequent accepted inputs.
        if (input_fire && load_bias)
            exponent_bias <= bias_in;

        if (in_ready)
            stage_valid <= in_valid;

        if (input_fire) begin
            product_hi <= normalized_hi;
            product_lo <= normalized_lo;
            exponent_sum <= exponent_a + exponent_b - exponent_bias
                            + (normalize_high ? ONE : ZERO);
            stage_guard <= normalized_lo[WORD_W-1];
            stage_sticky <= |normalized_lo[WORD_W-2:0];
        end

        // Both valid and payload advance into an empty or consumed slot.
        // Neither waits for ready when the output slot is empty.
        if (output_room) begin
            out_valid <= stage_valid;
            if (stage_valid) begin
                out_mantissa <= round_carry ? LEADING_ONE : rounded_mantissa;
                out_exponent <= exponent_sum + (round_carry ? ONE : ZERO);
                out_exact <= (product_lo == ZERO);
                out_rounded_up <= round_increment;
            end
        end
    end

    // An exact output never requires a rounding increment.
    always @(posedge clk)
        if (out_valid && out_exact)
            assert (!out_rounded_up);
endmodule

module serial_tool_line_encoder #(
    parameter integer LINES = 64,
    parameter integer INDEX_WIDTH = $clog2(LINES + 1)
) (
    input  wire                   clk,
    input  wire                   in_valid,
    output wire                   in_ready,
    input  wire [LINES-1:0]       in_lines,
    output reg                    out_valid,
    input  wire                   out_ready,
    output reg                    found,
    output reg [INDEX_WIDTH-1:0]  captured_index
);
    localparam [INDEX_WIDTH-1:0] INDEX_LIMIT = LINES;
    localparam [INDEX_WIDTH-1:0] ZERO_INDEX = {INDEX_WIDTH{1'b0}};
    localparam [INDEX_WIDTH-1:0] ONE_INDEX = {{(INDEX_WIDTH-1){1'b0}}, 1'b1};

    reg [LINES-1:0] pending_lines;
    reg [INDEX_WIDTH-1:0] scan_count;
    reg window;

    assign in_ready = !window;

    initial begin
        pending_lines = {LINES{1'b0}};
        scan_count = ZERO_INDEX;
        captured_index = INDEX_LIMIT;
        found = 1'b0;
        out_valid = 1'b0;
        window = 1'b0;
    end

    always @(posedge clk) begin
        if (!window) begin
            if (in_valid && in_ready) begin
                pending_lines <= in_lines;
                scan_count <= ZERO_INDEX;
                captured_index <= INDEX_LIMIT;
                found <= 1'b0;
                out_valid <= 1'b0;
                window <= 1'b1;
            end
        end else if (out_valid) begin
            // A full output stalls every register while out_ready is low.
            if (out_ready) begin
                window <= 1'b0;
                out_valid <= 1'b0;
                // Retain the completed result and its scan position until
                // another request is accepted.
            end
        end else if (found || scan_count == INDEX_LIMIT) begin
            // Publishing never waits for downstream readiness.
            out_valid <= 1'b1;
        end else if (pending_lines[scan_count]) begin
            // Scanning also progresses independently of out_ready.
            found <= 1'b1;
            captured_index <= scan_count;
        end else begin
            scan_count <= scan_count + ONE_INDEX;
        end
    end

    // A retained successful result cannot exceed its completed scan position.
    always @(*) begin
        if (!window && found)
            assert (captured_index <= scan_count);
    end
endmodule

module image_norm_divsqrt #(
    parameter integer WORD_W = 128,
    parameter integer ITER_W = $clog2(WORD_W + 1)
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire                 i_ce,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire                 req_sqrt,
    input  wire [WORD_W-1:0]    in_operand,
    input  wire [WORD_W-1:0]    in_divisor,
    output reg                  out_valid,
    input  wire                 out_ready,
    output wire [WORD_W-1:0]    out_data,
    output reg                  div_done,
    output reg                  sqrt_done
);
    // WORD_W is even and at least two. Each enabled processing cycle
    // consumes one division bit or two square-root operand bits.
    localparam [WORD_W-1:0] WORD_ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] WORD_ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [ITER_W-1:0] COUNT_ZERO = {ITER_W{1'b0}};
    localparam [ITER_W-1:0] COUNT_ONE = {{(ITER_W-1){1'b0}}, 1'b1};
    localparam [ITER_W-1:0] DIV_STEPS = WORD_W;
    localparam [ITER_W-1:0] SQRT_STEPS = WORD_W / 32'd2;

    reg busy;
    reg is_sqrt;
    reg [WORD_W-1:0] partial_rem;
    reg [WORD_W-1:0] root_quot;
    reg [WORD_W-1:0] divisor;
    reg [WORD_W-1:0] digit_stream;
    reg [ITER_W-1:0] iter_left;
    reg armed;
    reg pv;

    // A zero divisor-bank value selects the square-root trial generator.
    // Division requests normalize a zero denominator to one.
    wire divisor_is_zero = (divisor == WORD_ZERO);
    wire [WORD_W+1:0] brought_digit = is_sqrt
        ? {{WORD_W{1'b0}}, digit_stream[WORD_W-1:WORD_W-2]}
        : {{(WORD_W+1){1'b0}}, digit_stream[WORD_W-1]};
    wire [WORD_W+1:0] shifted_rem = is_sqrt
        ? (({2'b00, partial_rem} << 2'd2) | brought_digit)
        : (({2'b00, partial_rem} << 1'b1) | brought_digit);
    wire [WORD_W+1:0] root_trial =
        ({2'b00, root_quot} << 2'd2)
        | {{(WORD_W+1){1'b0}}, 1'b1};
    wire [WORD_W+1:0] trial_divisor = divisor_is_zero
        ? root_trial : {2'b00, divisor};

    // Both operations share this compare/subtract digit recurrence.
    wire accept_digit = (shifted_rem >= trial_divisor);
    wire [WORD_W+1:0] next_rem = accept_digit
        ? shifted_rem - trial_divisor : shifted_rem;
    wire [WORD_W-1:0] next_root_quot =
        {root_quot[WORD_W-2:0], accept_digit};

    assign out_data = root_quot;

    // Accept whenever the datapath and result slot are empty. Neither
    // request acceptance nor computation waits for downstream readiness.
    assign in_ready = i_ce && !busy && !out_valid;
    wire take_req = in_valid && in_ready;
    wire run_digit = i_ce && busy;
    wire take_result = i_ce && out_valid && out_ready;

    initial begin
        busy = 1'b0;
        is_sqrt = 1'b0;
        partial_rem = WORD_ZERO;
        root_quot = WORD_ZERO;
        divisor = WORD_ONE;
        digit_stream = WORD_ZERO;
        iter_left = COUNT_ZERO;
        out_valid = 1'b0;
        div_done = 1'b0;
        sqrt_done = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0;
            is_sqrt <= 1'b0;
            partial_rem <= WORD_ZERO;
            root_quot <= WORD_ZERO;
            divisor <= WORD_ONE;
            digit_stream <= WORD_ZERO;
            iter_left <= COUNT_ZERO;
            out_valid <= 1'b0;
            div_done <= 1'b0;
            sqrt_done <= 1'b0;
            armed <= 1'b0;
            pv <= 1'b0;
        end else if (i_ce) begin
            if (take_req || run_digit || take_result)
                pv <= 1'b1;

            if (take_req) begin
                armed <= 1'b1;
                busy <= 1'b1;
                is_sqrt <= req_sqrt;
                divisor <= req_sqrt ? WORD_ZERO
                    : ((in_divisor == WORD_ZERO) ? WORD_ONE : in_divisor);
                partial_rem <= WORD_ZERO;
                root_quot <= WORD_ZERO;
                digit_stream <= in_operand;
                iter_left <= req_sqrt ? SQRT_STEPS : DIV_STEPS;
                out_valid <= 1'b0;
                div_done <= 1'b0;
                sqrt_done <= 1'b0;
            end else if (run_digit) begin
                partial_rem <= next_rem[WORD_W-1:0];
                root_quot <= next_root_quot;
                digit_stream <= is_sqrt
                    ? (digit_stream << 2'd2)
                    : (digit_stream << 1'b1);
                iter_left <= iter_left - COUNT_ONE;
                if (iter_left == COUNT_ONE) begin
                    busy <= 1'b0;
                    // Publish immediately, even when out_ready is low.
                    // The result and ownership flags then remain stable
                    // until an enabled output handshake.
                    out_valid <= 1'b1;
                    div_done <= !is_sqrt;
                    sqrt_done <= divisor_is_zero;
                end
            end else if (take_result) begin
                out_valid <= 1'b0;
                div_done <= 1'b0;
                sqrt_done <= 1'b0;
            end
        end
    end

    // A newly published result cannot belong to both operations.
    always @(posedge clk)
        if (pv && armed)
            assert (!$rose(out_valid) || !(div_done && sqrt_done));
endmodule

module noc_packet_router #(
    parameter integer PORTS = 3
) (
    input  wire clk,
    input  wire rst_n,
    input  wire [PORTS-1:0] s_valid,
    output wire [PORTS-1:0] s_ready,
    input  wire [32*PORTS-1:0] s_data,
    input  wire [32*PORTS-1:0] s_route,
    output wire [PORTS-1:0] m_valid,
    input  wire [PORTS-1:0] m_ready,
    output wire [32*PORTS-1:0] m_data
);
    // PORTS must be at least two: the property observes inputs 0 and 1.
    localparam integer INDEX_W = (PORTS <= 1) ? 1 : $clog2(PORTS);
    localparam [31:0] PORT_COUNT = PORTS;
    localparam [31:0] LAST_PORT = PORT_COUNT - 32'd1;
    localparam [PORTS-1:0] FIRST_SELECT = {{(PORTS-1){1'b0}}, 1'b1};
    localparam [31:0] START_WORD = 32'hA500_0001;
    localparam [31:0] END_WORD = 32'hA500_0002;

    reg [PORTS-1:0] buf_valid;
    reg [31:0] buf_data [0:PORTS-1];
    reg [31:0] route_field [0:PORTS-1];
    reg [INDEX_W-1:0] rr_index [0:PORTS-1];
    reg [PORTS-1:0] switch_cfg [0:PORTS-1];

    wire [PORTS-1:0] grants [0:PORTS-1];
    wire [PORTS-1:0] in_fire;
    wire [PORTS-1:0] out_fire;
    wire [PORTS-1:0] begin_event;
    wire [PORTS-1:0] end_event;
    reg window;
    reg past_valid;

    assign in_fire = s_valid & s_ready;
    assign out_fire = m_valid & m_ready;

    genvar ip, op, gi, go;
    generate
        for (ip = 0; ip < PORTS; ip = ip + 1) begin : INPUT_PORT
            wire [PORTS-1:0] pop_terms;

            initial begin
                buf_valid[ip] = 1'b0;
                buf_data[ip] = 32'd0;
                route_field[ip] = 32'd0;
            end

            for (go = 0; go < PORTS; go = go + 1) begin : POP_SOURCE
                assign pop_terms[go] = grants[go][ip] && m_ready[go];
            end

            // A departing flit can be replaced on the same clock edge.
            // Invalid destinations are never accepted.
            assign s_ready[ip] = (!buf_valid[ip] || (|pop_terms)) &&
                (s_route[32*ip +: 32] < PORT_COUNT);
            assign begin_event[ip] = in_fire[ip] &&
                (s_data[32*ip +: 32] == START_WORD);

            always @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    buf_valid[ip] <= 1'b0;
                    buf_data[ip] <= 32'd0;
                    route_field[ip] <= 32'd0;
                end else if (in_fire[ip]) begin
                    buf_valid[ip] <= 1'b1;
                    buf_data[ip] <= s_data[32*ip +: 32];
                    route_field[ip] <= s_route[32*ip +: 32];
                end else if (|pop_terms) begin
                    buf_valid[ip] <= 1'b0;
                end
            end
        end

        for (op = 0; op < PORTS; op = op + 1) begin : OUTPUT_PORT
            localparam [31:0] OUTPUT_NUMBER = op;
            wire [PORTS-1:0] requests;
            reg [PORTS-1:0] selected;
            reg [31:0] mux_word;
            reg found;
            integer start;
            integer offset;
            integer candidate;
            integer j;

            initial begin
                rr_index[op] = {INDEX_W{1'b0}};
                switch_cfg[op] = FIRST_SELECT;
            end

            for (gi = 0; gi < PORTS; gi = gi + 1) begin : REQUEST_SOURCE
                assign requests[gi] = buf_valid[gi] &&
                    (route_field[gi] == OUTPUT_NUMBER);
            end

            // Each encoded starting position searches all inputs in
            // cyclic order. The one-hot configuration enables one search.
            // Selection never waits for ready, including at empty outputs.
            always @(*) begin
                selected = {PORTS{1'b0}};
                found = 1'b0;
                candidate = 0;
                for (start = 0; start < PORTS; start = start + 1) begin
                    found = 1'b0;
                    for (offset = 0; offset < PORTS; offset = offset + 1) begin
                        candidate = start + offset;
                        if (candidate >= PORTS)
                            candidate = candidate - PORTS;
                        if (!found && requests[candidate]) begin
                            if (switch_cfg[op][start])
                                selected[candidate] = 1'b1;
                            found = 1'b1;
                        end
                    end
                end
            end

            assign grants[op] = selected;

            always @(*) begin
                mux_word = 32'd0;
                for (j = 0; j < PORTS; j = j + 1) begin
                    if (grants[op][j])
                        mux_word = mux_word | buf_data[j];
                end
            end

            assign m_valid[op] = |grants[op];
            assign m_data[32*op +: 32] = mux_word;
            assign end_event[op] = out_fire[op] &&
                (m_data[32*op +: 32] == END_WORD);

            // Each output advances independently on its own transfer.
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    rr_index[op] <= {INDEX_W{1'b0}};
                    switch_cfg[op] <= FIRST_SELECT;
                end else if (out_fire[op]) begin
                    if (rr_index[op] == LAST_PORT) begin
                        rr_index[op] <= {INDEX_W{1'b0}};
                        switch_cfg[op] <= FIRST_SELECT;
                    end else begin
                        rr_index[op] <= rr_index[op] + 1'b1;
                        switch_cfg[op] <= switch_cfg[op] << 1;
                    end
                end
            end
        end
    endgenerate

    initial begin
        window = 1'b0;
        past_valid = 1'b0;
    end

    // Accepting a start opens the observation window; transmitting an
    // end closes it. End takes precedence on simultaneous events.
    // With s_valid=0 and m_ready=0, every state register holds.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            window <= 1'b0;
            past_valid <= 1'b0;
        end else begin
            if (|begin_event)
                window <= 1'b1;
            if (|end_event)
                window <= 1'b0;
            if ((|in_fire) || (|out_fire))
                past_valid <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (past_valid && window &&
            ($rose(grants[0][0]) || $rose(grants[0][1])))
            assert (!(grants[0][0] && grants[0][1]));
    end
endmodule

module peripheral_i2c_recovery #(
    parameter integer MAX_PULSES = 8
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        i_valid,
    output wire        o_ready,
    input  wire [15:0] i_sample,
    output reg         o_valid,
    input  wire        i_ready,
    output reg  [15:0] o_sample,
    output reg         scl_drive_low,
    output reg         sda_drive_low,
    output wire        done
);
    localparam integer PULSE_W = (MAX_PULSES < 2) ? 1 : $clog2(MAX_PULSES + 1);
    localparam integer EDGE_W = $clog2((2 * MAX_PULSES) + 1);

    localparam [2:0] PH_IDLE       = 3'd0;
    localparam [2:0] PH_CLOCK_LOW  = 3'd1;
    localparam [2:0] PH_CLOCK_HIGH = 3'd2;
    localparam [2:0] PH_STOP_LOW   = 3'd3;
    localparam [2:0] PH_STOP_HIGH  = 3'd4;
    localparam [2:0] PH_DONE       = 3'd5;

    reg [2:0] phase;
    reg [PULSE_W-1:0] pulse_count;
    reg [EDGE_W-1:0] edge_count;

    // Each accepted sample advances recovery and produces one echoed token.
    // An empty output accepts immediately, without waiting for its receiver.
    // An occupied output can be drained and replaced in the same cycle.
    assign o_ready = !o_valid || i_ready;
    wire accept_token = i_valid && o_ready;
    assign done = (phase == PH_DONE);

    initial begin
        phase         = PH_IDLE;
        pulse_count   = 0;
        edge_count    = 0;
        scl_drive_low = 1'b0;
        sda_drive_low = 1'b0;
        o_valid       = 1'b0;
        o_sample      = 16'd0;
    end

    // With i_valid and i_ready both low, every state register holds.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase         <= PH_IDLE;
            pulse_count   <= 0;
            edge_count    <= 0;
            scl_drive_low <= 1'b0;
            sda_drive_low <= 1'b0;
            o_valid       <= 1'b0;
            o_sample      <= 16'd0;
        end else begin
            // Output retirement depends only on this output's ready input.
            if (o_valid && i_ready)
                o_valid <= 1'b0;

            if (accept_token) begin
                o_valid  <= 1'b1;
                o_sample <= i_sample;

                case (phase)
                    PH_IDLE: begin
                        phase         <= PH_CLOCK_LOW;
                        pulse_count   <= 0;
                        edge_count    <= 1;
                        scl_drive_low <= 1'b1;
                        sda_drive_low <= 1'b0;
                    end

                    PH_CLOCK_LOW: begin
                        phase         <= PH_CLOCK_HIGH;
                        pulse_count   <= pulse_count + 1'b1;
                        edge_count    <= edge_count + 1'b1;
                        scl_drive_low <= 1'b0;
                    end

                    PH_CLOCK_HIGH: begin
                        if (i_sample[0]) begin
                            phase         <= PH_STOP_LOW;
                            scl_drive_low <= 1'b1;
                            sda_drive_low <= 1'b1;
                        end else if (pulse_count < MAX_PULSES) begin
                            phase         <= PH_CLOCK_LOW;
                            edge_count    <= edge_count + 1'b1;
                            scl_drive_low <= 1'b1;
                        end
                        // At the pulse budget, continue accepting and echoing
                        // samples while waiting for SDA to become high.
                    end

                    PH_STOP_LOW: begin
                        phase         <= PH_STOP_HIGH;
                        scl_drive_low <= 1'b0;
                    end

                    PH_STOP_HIGH: begin
                        phase         <= PH_DONE;
                        sda_drive_low <= 1'b0;
                    end

                    PH_DONE: begin
                        // Completion never permanently blocks the stream.
                        // The next token rearms the engine for another run.
                        phase         <= PH_IDLE;
                        pulse_count   <= 0;
                        edge_count    <= 0;
                        scl_drive_low <= 1'b0;
                        sda_drive_low <= 1'b0;
                    end

                    default: begin
                        phase         <= PH_IDLE;
                        pulse_count   <= 0;
                        edge_count    <= 0;
                        scl_drive_low <= 1'b0;
                        sda_drive_low <= 1'b0;
                    end
                endcase
            end
        end
    end

    // STOP edges are excluded from edge_count.
    always @(posedge clk) begin
        if (done)
            assert ((edge_count == (2 * pulse_count)) &&
                    !scl_drive_low && !sda_drive_low);
    end
endmodule

module boot_residue_adder #(
    parameter integer DATA_W = 32,
    parameter [DATA_W-1:0] INITIAL_MODULUS = 32'd17
) (
    input  wire                  clk,
    input  wire                  cfg_valid,
    output wire                  cfg_ready,
    input  wire [DATA_W-1:0]     cfg_modulus,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [DATA_W-1:0]     in_a,
    input  wire [DATA_W-1:0]     in_b,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [DATA_W-1:0]     result,
    output reg                   out_error
);
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};

    reg [DATA_W-1:0] active_modulus;
    // The buffered transaction retains its own reduction argument.
    reg [DATA_W-1:0] modulus;
    reg [DATA_W-1:0] sum_word;
    reg sum_carry;
    reg past_valid;

    // Configuration never waits for the output receiver. Zero selects one.
    // A simultaneous data transfer uses the previous active configuration.
    assign cfg_ready = 1'b1;

    // An empty buffer accepts data without waiting for output ready.
    // A consumed output can be replaced on the same edge.
    assign in_ready = !out_valid || out_ready;

    wire cfg_fire = cfg_valid && cfg_ready;
    wire in_fire = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    // The arithmetic interface accepts canonical residues. Noncanonical
    // operands are consumed and reported as an error transaction with a
    // zero result, rather than permanently deasserting input ready.
    wire operand_error = (in_a >= active_modulus)
                       || (in_b >= active_modulus);
    wire [DATA_W:0] input_sum = operand_error
        ? {(DATA_W+1){1'b0}}
        : ({1'b0, in_a} + {1'b0, in_b});
    wire [DATA_W:0] extended_active_modulus = {1'b0, active_modulus};
    wire [DATA_W:0] reduced_sum =
        (input_sum >= extended_active_modulus)
        ? input_sum - extended_active_modulus : input_sum;

    initial begin
        active_modulus = (INITIAL_MODULUS == ZERO) ? ONE : INITIAL_MODULUS;
        modulus = (INITIAL_MODULUS == ZERO) ? ONE : INITIAL_MODULUS;
        sum_word = ZERO;
        sum_carry = 1'b0;
        result = ZERO;
        out_valid = 1'b0;
        out_error = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (cfg_fire)
            active_modulus <= (cfg_modulus == ZERO) ? ONE : cfg_modulus;

        if (out_fire)
            out_valid <= 1'b0;

        if (in_fire) begin
            modulus <= active_modulus;
            sum_word <= input_sum[DATA_W-1:0];
            sum_carry <= input_sum[DATA_W];
            result <= reduced_sum[DATA_W-1:0];
            out_error <= operand_error;
            out_valid <= 1'b1;
        end

        // With cfg_valid, in_valid, and out_ready low, every register holds.
        if (cfg_fire || in_fire || out_fire)
            past_valid <= 1'b1;
    end

    // Equal stored reduction arguments must have equal stored results.
    always @(posedge clk)
        if (past_valid && $stable({modulus, sum_carry, sum_word}))
            assert ($stable(result));
endmodule

module hmac_pass_sequencer #(
    parameter integer KEY_WORDS = 8,
    parameter integer WORD_BITS = 32
) (
    input wire clk,
    input wire i_ce,
    input wire i_start,
    input wire i_key_load,
    input wire [31:0] i_key_index,
    input wire [WORD_BITS-1:0] i_key_word,
    input wire i_message_load,
    input wire [WORD_BITS-1:0] i_message_word,
    input wire i_hash_ready,
    input wire i_hash_digest_valid,
    input wire [WORD_BITS-1:0] i_hash_digest,
    output wire o_hash_init,
    output wire o_hash_valid,
    output wire o_hash_last,
    output wire [WORD_BITS-1:0] o_hash_data,
    output wire o_inner_busy,
    output wire o_outer_busy,
    output wire o_done,
    output wire [WORD_BITS-1:0] o_digest
);
    localparam integer INDEX_BITS = (KEY_WORDS > 1) ? $clog2(KEY_WORDS) : 1;
    localparam [3:0] PH_IDLE         = 4'd0;
    localparam [3:0] PH_INNER_START  = 4'd1;
    localparam [3:0] PH_INNER_KEY    = 4'd2;
    localparam [3:0] PH_INNER_MSG    = 4'd3;
    localparam [3:0] PH_INNER_WAIT   = 4'd4;
    localparam [3:0] PH_OUTER_START  = 4'd5;
    localparam [3:0] PH_OUTER_KEY    = 4'd6;
    localparam [3:0] PH_OUTER_DIGEST = 4'd7;
    localparam [3:0] PH_OUTER_WAIT   = 4'd8;
    localparam [3:0] PH_DONE         = 4'd9;

    localparam [WORD_BITS-1:0] IPAD = 32'h36363636;
    localparam [WORD_BITS-1:0] PAD_DELTA = 32'h6a6a6a6a;

    reg [WORD_BITS-1:0] padded_key [0:KEY_WORDS-1];
    reg [WORD_BITS-1:0] message_word;
    reg [WORD_BITS-1:0] inner_digest;
    reg [WORD_BITS-1:0] result_digest;
    reg [3:0] phase;
    reg [INDEX_BITS-1:0] word_index;
    reg inner_busy;
    reg outer_busy;
    integer init_index;

    initial begin
        phase = PH_IDLE;
        word_index = '0;
        inner_busy = 1'b0;
        outer_busy = 1'b0;
        message_word = '0;
        inner_digest = '0;
        result_digest = '0;
        for (init_index = 0; init_index < KEY_WORDS; init_index = init_index + 1)
            padded_key[init_index] = IPAD;
    end

    // Initialization is an enabled command pulse, not a ready-qualified transfer.
    assign o_hash_init = i_ce && ((phase == PH_INNER_START) ||
                                 (phase == PH_OUTER_START));
    assign o_hash_valid = i_ce && ((phase == PH_INNER_KEY) ||
                                  (phase == PH_INNER_MSG) ||
                                  (phase == PH_OUTER_KEY) ||
                                  (phase == PH_OUTER_DIGEST));
    assign o_hash_last = o_hash_valid && ((phase == PH_INNER_MSG) ||
                                        (phase == PH_OUTER_DIGEST));
    assign o_hash_data = (phase == PH_INNER_KEY) ? padded_key[word_index] :
                         (phase == PH_OUTER_KEY) ? (padded_key[word_index] ^ PAD_DELTA) :
                         (phase == PH_INNER_MSG) ? message_word :
                         (phase == PH_OUTER_DIGEST) ? inner_digest : {WORD_BITS{1'b0}};
    assign o_inner_busy = inner_busy;
    assign o_outer_busy = outer_busy;
    assign o_done = (phase == PH_DONE);
    assign o_digest = result_digest;

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                PH_IDLE: begin
                    if (i_key_load && (i_key_index < KEY_WORDS))
                        padded_key[i_key_index] <= i_key_word ^ IPAD;
                    if (i_message_load)
                        message_word <= i_message_word;
                    if (i_start)
                        phase <= PH_INNER_START;
                end
                PH_INNER_START: begin
                    // Present the first available word without waiting for ready.
                    inner_busy <= 1'b1;
                    word_index <= '0;
                    phase <= PH_INNER_KEY;
                end
                PH_INNER_KEY: begin
                    if (i_hash_ready) begin
                        if (word_index == KEY_WORDS-1)
                            phase <= PH_INNER_MSG;
                        else
                            word_index <= word_index + 1'b1;
                    end
                end
                PH_INNER_MSG: begin
                    if (i_hash_ready)
                        phase <= PH_INNER_WAIT;
                end
                PH_INNER_WAIT: begin
                    if (i_hash_digest_valid) begin
                        inner_digest <= i_hash_digest;
                        inner_busy <= 1'b0;
                        phase <= PH_OUTER_START;
                    end
                end
                PH_OUTER_START: begin
                    // As above, initialization never waits for stream readiness.
                    outer_busy <= 1'b1;
                    word_index <= '0;
                    phase <= PH_OUTER_KEY;
                end
                PH_OUTER_KEY: begin
                    if (i_hash_ready) begin
                        if (word_index == KEY_WORDS-1)
                            phase <= PH_OUTER_DIGEST;
                        else
                            word_index <= word_index + 1'b1;
                    end
                end
                PH_OUTER_DIGEST: begin
                    if (i_hash_ready)
                        phase <= PH_OUTER_WAIT;
                end
                PH_OUTER_WAIT: begin
                    if (i_hash_digest_valid) begin
                        result_digest <= i_hash_digest;
                        outer_busy <= 1'b0;
                        phase <= PH_DONE;
                    end
                end
                PH_DONE: phase <= PH_IDLE;
                default: begin
                    phase <= PH_IDLE;
                    word_index <= '0;
                    inner_busy <= 1'b0;
                    outer_busy <= 1'b0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (inner_busy)
            assert (!outer_busy);
endmodule

module fp_service_keypad_lock #(
    parameter integer CODE_DIGITS = 16,
    parameter [63:0] MAX_FAILURES = 64'd4,
    parameter [63:0] LOCKOUT_CYCLES = 64'd8
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        i_ce,
    input  wire        req_valid,
    output wire        req_ready,
    input  wire [63:0] req_digit,
    output wire        rsp_valid,
    input  wire        rsp_ready,
    output reg  [63:0] rsp_data,
    output reg         service_unlocked
);
    localparam [63:0] CODE_DIGITS_WORD = CODE_DIGITS;
    localparam [63:0] PH_IDLE    = 64'd0;
    localparam [63:0] PH_FETCH   = 64'd1;
    localparam [63:0] PH_COMPARE = 64'd2;
    localparam [63:0] PH_COMMIT  = 64'd3;

    // Fixed keypad code ROM.
    reg [63:0] code_mem [0:CODE_DIGITS-1];
    genvar g;
    generate
        for (g = 0; g < CODE_DIGITS; g = g + 1) begin : stored_code
            localparam [63:0] DIGIT_VALUE = g;
            initial code_mem[g] = DIGIT_VALUE;
        end
    endgenerate

    reg [63:0] phase;
    reg [63:0] digit_position;
    reg [63:0] failed_attempts;
    reg [63:0] lockout_timer;
    reg [63:0] response_deadline;
    reg [63:0] captured_digit;
    reg [63:0] expected_digit;
    reg outstanding;
    reg armed;
    reg digit_bad;
    reg attempt_bad;
    reg response_pending;

    // Reserve the response slot when accepting a request. Neither request
    // acceptance nor checker execution waits for the receiver's ready.
    assign req_ready = i_ce && !outstanding && !response_pending &&
                       (lockout_timer == 64'd0);

    // Both interfaces transfer only on enabled clock edges. A completed
    // response is advertised independently of rsp_ready and held until taken.
    assign rsp_valid = i_ce && response_pending;

    initial begin
        phase = PH_IDLE;
        digit_position = 64'd0;
        failed_attempts = 64'd0;
        lockout_timer = 64'd0;
        response_deadline = 64'd0;
        captured_digit = 64'd0;
        expected_digit = 64'd0;
        outstanding = 1'b0;
        armed = 1'b0;
        digit_bad = 1'b0;
        attempt_bad = 1'b0;
        response_pending = 1'b0;
        rsp_data = 64'd0;
        service_unlocked = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase <= PH_IDLE;
            digit_position <= 64'd0;
            failed_attempts <= 64'd0;
            lockout_timer <= 64'd0;
            response_deadline <= 64'd0;
            captured_digit <= 64'd0;
            expected_digit <= 64'd0;
            outstanding <= 1'b0;
            armed <= 1'b0;
            digit_bad <= 1'b0;
            attempt_bad <= 1'b0;
            response_pending <= 1'b0;
            rsp_data <= 64'd0;
            service_unlocked <= 1'b0;
        end else if (i_ce) begin
            if (response_pending && rsp_ready)
                response_pending <= 1'b0;

            if (lockout_timer != 64'd0)
                lockout_timer <= lockout_timer - 64'd1;

            // Accepted work progresses without consulting rsp_ready.
            if (outstanding) begin
                response_deadline <= response_deadline - 64'd1;
                case (phase)
                    PH_FETCH: begin
                        expected_digit <= code_mem[digit_position];
                        phase <= PH_COMPARE;
                    end
                    PH_COMPARE: begin
                        digit_bad <= (captured_digit != expected_digit);
                        phase <= PH_COMMIT;
                    end
                    PH_COMMIT: begin
                        phase <= PH_IDLE;
                        outstanding <= 1'b0;
                        response_pending <= 1'b1;
                        rsp_data <= digit_bad ? 64'd0 : 64'd1;

                        if (digit_position == CODE_DIGITS_WORD - 64'd1) begin
                            digit_position <= 64'd0;
                            attempt_bad <= 1'b0;
                            if (attempt_bad || digit_bad) begin
                                rsp_data <= 64'd0;
                                service_unlocked <= 1'b0;
                                if (failed_attempts == MAX_FAILURES - 64'd1) begin
                                    failed_attempts <= 64'd0;
                                    lockout_timer <= LOCKOUT_CYCLES;
                                end else begin
                                    failed_attempts <= failed_attempts + 64'd1;
                                end
                            end else begin
                                rsp_data <= 64'd2;
                                service_unlocked <= 1'b1;
                                failed_attempts <= 64'd0;
                            end
                        end else begin
                            digit_position <= digit_position + 64'd1;
                            attempt_bad <= attempt_bad || digit_bad;
                        end
                    end
                    default: begin
                        // Excluded by the supplied structural relation.
                    end
                endcase
            end else if (req_valid && req_ready) begin
                armed <= 1'b1;
                captured_digit <= req_digit;
                outstanding <= 1'b1;
                response_deadline <= 64'd3;
                phase <= PH_FETCH;
                service_unlocked <= 1'b0;
            end
        end
    end

    always @(*) begin
        if (armed)
            assert (!outstanding || response_deadline != 64'd0);
    end
endmodule

module signed_divide_service #(
    parameter integer WIDTH = 64
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 i_req_valid,
    output wire                 o_req_ready,
    input  wire [WIDTH-1:0]     i_dividend,
    input  wire [WIDTH-1:0]     i_divisor,
    output wire                 o_rsp_valid,
    input  wire                 i_rsp_ready,
    output wire [WIDTH-1:0]     o_quotient,
    output wire [WIDTH-1:0]     o_remainder,
    output wire                 o_divide_by_zero,
    output wire                 o_overflow,
    input  wire                 i_cfg_load,
    input  wire [WIDTH-1:0]     i_cfg_budget,
    input  wire                 i_session_begin,
    input  wire                 i_session_end
);
    localparam [WIDTH-1:0] ZERO = {WIDTH{1'b0}};
    localparam [WIDTH-1:0] ONE = {{(WIDTH-1){1'b0}}, 1'b1};
    localparam [WIDTH-1:0] ALL_ONES = {WIDTH{1'b1}};
    localparam [WIDTH-1:0] SIGN_MIN = {1'b1, {(WIDTH-1){1'b0}}};
    localparam [WIDTH-1:0] ITERATIONS = WIDTH;
    localparam [WIDTH-1:0] MIN_BUDGET = ITERATIONS + ONE;

    localparam [1:0] ST_IDLE = 2'b00;
    localparam [1:0] ST_RUN = 2'b01;
    localparam [1:0] ST_FIX = 2'b10;
    localparam [1:0] ST_RESULT = 2'b11;

    reg [1:0] phase;
    reg scope_window;
    reg [WIDTH-1:0] cfg_budget;
    reg [WIDTH-1:0] steps_left;
    reg [WIDTH-1:0] deadline_left;
    reg [WIDTH-1:0] saved_dividend;
    reg [WIDTH-1:0] divisor_mag;
    reg [WIDTH-1:0] quotient_work;
    reg [WIDTH-1:0] remainder_work;
    reg quotient_negative;
    reg remainder_negative;
    reg divide_by_zero;
    reg signed_overflow;
    reg [WIDTH-1:0] quotient_result;
    reg [WIDTH-1:0] remainder_result;

    initial begin
        phase = ST_IDLE;
        scope_window = 1'b0;
        cfg_budget = MIN_BUDGET;
        steps_left = ZERO;
        deadline_left = ZERO;
        saved_dividend = ZERO;
        divisor_mag = ZERO;
        quotient_work = ZERO;
        remainder_work = ZERO;
        quotient_negative = 1'b0;
        remainder_negative = 1'b0;
        divide_by_zero = 1'b0;
        signed_overflow = 1'b0;
        quotient_result = ZERO;
        remainder_result = ZERO;
    end

    wire [WIDTH-1:0] dividend_abs = i_dividend[WIDTH-1]
        ? (~i_dividend + ONE) : i_dividend;
    wire [WIDTH-1:0] divisor_abs = i_divisor[WIDTH-1]
        ? (~i_divisor + ONE) : i_divisor;

    wire [WIDTH-1:0] shifted_remainder =
        {remainder_work[WIDTH-2:0], quotient_work[WIDTH-1]};
    wire take_subtract = remainder_work[WIDTH-1] ||
        (shifted_remainder >= divisor_mag);
    wire [WIDTH-1:0] next_remainder = take_subtract
        ? shifted_remainder - divisor_mag : shifted_remainder;
    wire [WIDTH-1:0] next_quotient =
        {quotient_work[WIDTH-2:0], take_subtract};

    // Request acceptance and computation do not depend on response ready.
    assign o_req_ready = i_ce && (phase == ST_IDLE) && !i_cfg_load;
    assign o_rsp_valid = (phase == ST_RESULT);
    assign o_quotient = quotient_result;
    assign o_remainder = remainder_result;
    assign o_divide_by_zero = divide_by_zero;
    assign o_overflow = signed_overflow;

    // i_ce enables computation and control updates. A published response
    // can always be consumed, even while computation is disabled.
    // With both i_ce and i_rsp_ready low, every register holds its value.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_session_end)
                scope_window <= 1'b0;
            else if (i_session_begin)
                scope_window <= 1'b1;

            case (phase)
                ST_IDLE: begin
                    if (i_cfg_load) begin
                        cfg_budget <= i_cfg_budget;
                    end else if (i_req_valid && o_req_ready) begin
                        saved_dividend <= i_dividend;
                        divisor_mag <= divisor_abs;
                        quotient_work <= dividend_abs;
                        remainder_work <= ZERO;
                        quotient_negative <= i_dividend[WIDTH-1] ^ i_divisor[WIDTH-1];
                        remainder_negative <= i_dividend[WIDTH-1];
                        divide_by_zero <= (i_divisor == ZERO);
                        signed_overflow <= (i_dividend == SIGN_MIN) &&
                                           (i_divisor == ALL_ONES);
                        steps_left <= ITERATIONS;
                        deadline_left <= (cfg_budget < MIN_BUDGET)
                            ? MIN_BUDGET : cfg_budget;
                        phase <= ST_RUN;
                    end
                end

                ST_RUN: begin
                    quotient_work <= next_quotient;
                    remainder_work <= next_remainder;
                    steps_left <= steps_left - ONE;
                    deadline_left <= deadline_left - ONE;
                    if (steps_left == ONE)
                        phase <= ST_FIX;
                end

                ST_FIX: begin
                    if (divide_by_zero) begin
                        quotient_result <= ALL_ONES;
                        remainder_result <= saved_dividend;
                    end else if (signed_overflow) begin
                        quotient_result <= SIGN_MIN;
                        remainder_result <= ZERO;
                    end else begin
                        quotient_result <= quotient_negative
                            ? (~quotient_work + ONE) : quotient_work;
                        remainder_result <= remainder_negative
                            ? (~remainder_work + ONE) : remainder_work;
                    end
                    deadline_left <= deadline_left - ONE;
                    phase <= ST_RESULT;
                end

                ST_RESULT: begin
                    // Response transfer is handled independently below.
                end
            endcase
        end

        // Valid is asserted as soon as the result exists, without waiting
        // for ready. Keep valid and response data until an actual transfer.
        if (o_rsp_valid && i_rsp_ready)
            phase <= ST_IDLE;
    end

    always @(posedge clk)
        if (scope_window && ((phase == ST_RUN) || (phase == ST_FIX)))
            assert (deadline_left != ZERO);
endmodule

module modular_alu_audit #(
    parameter integer DATA_W = 32
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire                  in_config,
    input  wire [DATA_W-1:0]     in_modulus,
    input  wire [DATA_W-1:0]     in_a,
    input  wire [DATA_W-1:0]     in_b,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [DATA_W-1:0]     out_data,
    output wire                  out_reduced
);
    logic pending;
    logic [DATA_W-1:0] modulus_cfg;
    logic [DATA_W-1:0] shadow_a, shadow_b, shadow_modulus;
    logic [DATA_W-1:0] result_data;
    logic result_reduced;
    logic accepted_seen;

    logic receipt_valid;
    logic [DATA_W-1:0] retired_data;
    logic retired_reduced;
    logic [DATA_W-1:0] retired_a, retired_b, retired_modulus;

    // Every accepted request produces a response. A configuration request
    // also installs its modulus and performs the addition using that modulus.
    // Invalid moduli become two; operands outside the residue range become
    // zero. Malformed payloads therefore never cause handshake deadlock.
    wire [DATA_W-1:0] configured_modulus =
        (in_modulus >= DATA_W'(2)) ? in_modulus : DATA_W'(2);
    wire [DATA_W-1:0] operation_modulus =
        in_config ? configured_modulus : modulus_cfg;
    wire [DATA_W-1:0] operand_a =
        (in_a < operation_modulus) ? in_a : DATA_W'(0);
    wire [DATA_W-1:0] operand_b =
        (in_b < operation_modulus) ? in_b : DATA_W'(0);

    wire [DATA_W:0] input_sum =
        {1'b0, operand_a} + {1'b0, operand_b};
    wire input_reduce = input_sum >= {1'b0, operation_modulus};
    wire [DATA_W:0] input_remainder = input_reduce
        ? input_sum - {1'b0, operation_modulus} : input_sum;

    wire [DATA_W:0] reference_sum =
        {1'b0, shadow_a} + {1'b0, shadow_b};
    wire reference_reduce = reference_sum >= {1'b0, shadow_modulus};
    wire [DATA_W:0] reference_remainder = reference_reduce
        ? reference_sum - {1'b0, shadow_modulus} : reference_sum;

    wire [DATA_W:0] audit_sum =
        {1'b0, retired_a} + {1'b0, retired_b};
    wire audit_reduce = audit_sum >= {1'b0, retired_modulus};
    wire [DATA_W:0] audit_remainder = audit_reduce
        ? audit_sum - {1'b0, retired_modulus} : audit_sum;

    // A one-entry elastic response buffer. Valid never waits for ready,
    // and consuming a response permits its simultaneous replacement.
    assign in_ready = !pending || out_ready;
    assign out_valid = pending;
    assign out_data = result_data;
    assign out_reduced = result_reduced;

    initial begin
        pending = 1'b0;
        modulus_cfg = DATA_W'(2);
        shadow_a = DATA_W'(0);
        shadow_b = DATA_W'(0);
        shadow_modulus = DATA_W'(2);
        result_data = DATA_W'(0);
        result_reduced = 1'b0;
        accepted_seen = 1'b0;
        receipt_valid = 1'b0;
        retired_data = DATA_W'(0);
        retired_reduced = 1'b0;
        retired_a = DATA_W'(0);
        retired_b = DATA_W'(0);
        retired_modulus = DATA_W'(2);
    end

    always @(posedge clk) begin
        if (out_valid && out_ready) begin
            pending <= 1'b0;
            retired_data <= result_data;
            retired_reduced <= result_reduced;
            retired_a <= shadow_a;
            retired_b <= shadow_b;
            retired_modulus <= shadow_modulus;
            receipt_valid <= 1'b1;
        end

        if (in_valid && in_ready) begin
            if (in_config)
                modulus_cfg <= configured_modulus;
            shadow_a <= operand_a;
            shadow_b <= operand_b;
            shadow_modulus <= operation_modulus;
            result_data <= input_remainder[DATA_W-1:0];
            result_reduced <= input_reduce;
            accepted_seen <= 1'b1;
            pending <= 1'b1;
        end
    end

    // The retirement snapshot is independent of any replacement request.
    always @(posedge clk) begin
        if (receipt_valid)
            assert (accepted_seen &&
                    ({1'b0, retired_data} == audit_remainder) &&
                    (retired_reduced == audit_reduce));
    end
endmodule

module imaging_irq_ack_cell #(
    parameter integer VECTOR_BITS = 64,
    parameter integer SERVICE_STEPS = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_ce,

    input  wire irq_valid,
    output wire irq_ready,
    input  wire [VECTOR_BITS-1:0] irq_vector,

    input  wire ack_valid,
    output wire ack_ready,
    output wire ack_next_valid,
    input  wire ack_next_ready,

    output wire vector_valid,
    input  wire vector_ready,
    output wire [VECTOR_BITS-1:0] vector_data
);
    localparam integer COUNT_W = (SERVICE_STEPS < 2) ? 1 : $clog2(SERVICE_STEPS + 1);
    localparam [SERVICE_STEPS-1:0] TOKEN_ZERO = {SERVICE_STEPS{1'b0}};
    localparam [SERVICE_STEPS-1:0] TOKEN_ONE = {{(SERVICE_STEPS-1){1'b0}}, 1'b1};

    reg request_pending;
    reg [VECTOR_BITS-1:0] local_vector;
    reg ack_outstanding;
    reg [SERVICE_STEPS-1:0] service_token;
    reg [COUNT_W-1:0] countdown;
    reg pass_valid;

    wire terminal_token;
    wire retire_vector;
    wire service_room;
    wire pass_room;
    wire irq_take;
    wire want_local;
    wire ack_take;
    wire claim_take;
    wire forward_take;

    assign terminal_token = service_token[SERVICE_STEPS-1];
    assign retire_vector = ack_outstanding && terminal_token && vector_ready;
    assign service_room = !ack_outstanding || retire_vector;
    assign pass_room = !pass_valid || ack_next_ready;

    // A retiring vector can be replaced by a new request on the same edge.
    assign irq_ready = i_ce && (!request_pending || retire_vector);
    assign irq_take = irq_valid && irq_ready;

    // Include an IRQ accepted on this edge: its simultaneous ACK must not
    // be forwarded merely because request_pending was previously clear.
    assign want_local = (!ack_outstanding && request_pending) || irq_take;
    assign ack_ready = i_ce && service_room && (want_local || pass_room);
    assign ack_take = ack_valid && ack_ready;
    assign claim_take = ack_take && want_local;
    assign forward_take = ack_take && !want_local;

    // Neither output waits for ready before advertising its item.
    assign ack_next_valid = i_ce && pass_valid;
    assign vector_valid = i_ce && ack_outstanding && terminal_token;
    assign vector_data = local_vector;

    initial begin
        request_pending = 1'b0;
        local_vector = {VECTOR_BITS{1'b0}};
        ack_outstanding = 1'b0;
        service_token = TOKEN_ZERO;
        countdown = {COUNT_W{1'b0}};
        pass_valid = 1'b0;
    end

    // Synchronous, enable-qualified reset; i_ce low freezes every register.
    always @(posedge clk) begin
        if (i_ce) begin
            if (!rst_n) begin
                request_pending <= 1'b0;
                local_vector <= {VECTOR_BITS{1'b0}};
                ack_outstanding <= 1'b0;
                service_token <= TOKEN_ZERO;
                countdown <= {COUNT_W{1'b0}};
                pass_valid <= 1'b0;
            end else begin
                // The forwarded output drains only with its own ready.
                // A simultaneous replacement keeps the buffer occupied.
                if (pass_valid && ack_next_ready)
                    pass_valid <= 1'b0;
                if (forward_take)
                    pass_valid <= 1'b1;

                if (retire_vector)
                    request_pending <= 1'b0;
                if (irq_take) begin
                    request_pending <= 1'b1;
                    local_vector <= irq_vector;
                end

                // Service advances independently of either receiver's ready.
                // Only the completed vector waits for vector_ready.
                if (ack_outstanding) begin
                    if (terminal_token) begin
                        if (vector_ready) begin
                            ack_outstanding <= 1'b0;
                            service_token <= TOKEN_ZERO;
                            countdown <= {COUNT_W{1'b0}};
                        end
                    end else begin
                        service_token <= service_token << 1;
                        if (countdown != 0)
                            countdown <= countdown - 1'b1;
                    end
                end

                // Claiming is independent of a blocked forwarded output.
                // This also permits replacement on a vector-retirement edge.
                if (claim_take) begin
                    ack_outstanding <= 1'b1;
                    service_token <= TOKEN_ONE;
                    countdown <= SERVICE_STEPS;
                end
            end
        end
    end

    always @(posedge clk)
        if (ack_outstanding)
            assert (countdown != 0);
endmodule

module checksum_word_divider #(
    parameter integer WORD_BITS = 64
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 cmd_valid,
    output wire                 cmd_ready,
    input  wire [WORD_BITS-1:0]  checksum_word,
    input  wire [WORD_BITS-1:0]  divisor_in,
    output reg                  busy,
    output reg                  done,
    output reg  [WORD_BITS-1:0]  quotient,
    output wire                 quotient_valid,
    input  wire                 quotient_ready,
    output reg  [WORD_BITS-1:0]  remainder,
    output wire                 remainder_valid,
    input  wire                 remainder_ready
);
    localparam integer COUNT_BITS = (WORD_BITS < 2) ? 1 : $clog2(WORD_BITS + 1);
    localparam [COUNT_BITS-1:0] COUNT_ZERO = {COUNT_BITS{1'b0}};
    localparam [COUNT_BITS-1:0] COUNT_ONE = {{(COUNT_BITS-1){1'b0}}, 1'b1};
    localparam [COUNT_BITS-1:0] TOTAL_STEPS = WORD_BITS;
    localparam [WORD_BITS-1:0] WORD_ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] WORD_ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};

    reg [WORD_BITS-1:0] divisor;
    reg [WORD_BITS-1:0] quotient_work;
    reg [WORD_BITS-1:0] remainder_work;
    reg [COUNT_BITS-1:0] iteration;
    reg [COUNT_BITS-1:0] deadline;
    reg q_pending;
    reg r_pending;

    // Each result channel advertises its item independently of ready.
    // When disabled, no interface transfer occurs and all state holds.
    assign quotient_valid = i_ce && q_pending;
    assign remainder_valid = i_ce && r_pending;

    // Accept a new operation when both result slots are empty or are
    // independently being consumed on this edge.
    assign cmd_ready = i_ce && !busy
                     && (!q_pending || quotient_ready)
                     && (!r_pending || remainder_ready);

    wire [WORD_BITS-1:0] shifted_remainder =
        (remainder_work << 1)
        | {{(WORD_BITS-1){1'b0}}, quotient_work[WORD_BITS-1]};
    wire shift_carry = remainder_work[WORD_BITS-1];
    wire [WORD_BITS-1:0] trial_remainder = shifted_remainder - divisor;
    wire trial_borrow = !shift_carry && (shifted_remainder < divisor);
    wire [WORD_BITS-1:0] remainder_next =
        trial_borrow ? shifted_remainder : trial_remainder;
    wire [WORD_BITS-1:0] quotient_next =
        (quotient_work << 1) | {{(WORD_BITS-1){1'b0}}, !trial_borrow};

    initial begin
        busy = 1'b0;
        done = 1'b0;
        quotient = WORD_ZERO;
        remainder = WORD_ZERO;
        divisor = WORD_ONE;
        quotient_work = WORD_ZERO;
        remainder_work = WORD_ZERO;
        iteration = COUNT_ZERO;
        deadline = COUNT_ZERO;
        q_pending = 1'b0;
        r_pending = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            done <= 1'b0;

            // Consuming one output never waits for the other output.
            if (q_pending && quotient_ready)
                q_pending <= 1'b0;
            if (r_pending && remainder_ready)
                r_pending <= 1'b0;

            // Once accepted, an operation advances without further commands
            // and without waiting for either result receiver to assert ready.
            if (busy) begin
                quotient_work <= quotient_next;
                remainder_work <= remainder_next;
                iteration <= iteration + COUNT_ONE;
                deadline <= deadline - COUNT_ONE;
                if (iteration == TOTAL_STEPS - COUNT_ONE) begin
                    busy <= 1'b0;
                    done <= 1'b1;
                    quotient <= quotient_next;
                    remainder <= remainder_next;
                    q_pending <= 1'b1;
                    r_pending <= 1'b1;
                end
            end else if (cmd_valid && cmd_ready) begin
                divisor <= divisor_in;
                quotient_work <= checksum_word;
                remainder_work <= WORD_ZERO;
                iteration <= COUNT_ZERO;
                deadline <= TOTAL_STEPS;
                busy <= 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (deadline == COUNT_ZERO)
            assert (!busy);
    end
endmodule

module rs_suffix_stream64 #(
    parameter integer SYMBOL_W = 64,
    parameter integer PARITY_SYMBOLS = 16,
    parameter [SYMBOL_W-1:0] FIELD_REDUCTION = 64'h000000000000001b
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_valid,
    output wire i_ready,
    input  wire [SYMBOL_W-1:0] i_data,
    input  wire i_last,
    output wire o_valid,
    input  wire o_ready,
    output wire [SYMBOL_W-1:0] o_data,
    output wire o_last,
    output wire [63:0] o_active_symbols
);
    localparam [63:0] PARITY_LIMIT = PARITY_SYMBOLS;
    localparam [SYMBOL_W-1:0] SYMBOL_ZERO = {SYMBOL_W{1'b0}};
    localparam [SYMBOL_W-1:0] SYMBOL_ONE = {{(SYMBOL_W-1){1'b0}}, 1'b1};
    localparam [SYMBOL_W-1:0] SYMBOL_ALPHA = SYMBOL_ONE << 1;

    function automatic [SYMBOL_W-1:0] gf_mul;
        input [SYMBOL_W-1:0] a;
        input [SYMBOL_W-1:0] b;
        reg [SYMBOL_W-1:0] x, y, product;
        integer bit_index;
        begin
            x = a;
            y = b;
            product = SYMBOL_ZERO;
            for (bit_index = 0; bit_index < SYMBOL_W; bit_index = bit_index + 1) begin
                if (y[0])
                    product = product ^ x;
                x = (x << 1)
                    ^ (x[SYMBOL_W-1] ? FIELD_REDUCTION : SYMBOL_ZERO);
                y = y >> 1;
            end
            gf_mul = product;
        end
    endfunction

    // Elaborate g(x) = product_j (x + alpha^j), alpha = 2.
    // A packed vector avoids unsupported unpacked arrays in constant functions.
    function automatic [SYMBOL_W-1:0] generator_coefficient;
        input integer coefficient_index;
        reg [((PARITY_SYMBOLS+1)*SYMBOL_W)-1:0] coefficients;
        reg [SYMBOL_W-1:0] root;
        integer root_index, coefficient;
        begin
            coefficients = {((PARITY_SYMBOLS+1)*SYMBOL_W){1'b0}};
            coefficients[0 +: SYMBOL_W] = SYMBOL_ONE;
            root = SYMBOL_ONE;
            for (root_index = 0; root_index < PARITY_SYMBOLS; root_index = root_index + 1) begin
                for (coefficient = PARITY_SYMBOLS; coefficient > 0; coefficient = coefficient - 1)
                    coefficients[coefficient*SYMBOL_W +: SYMBOL_W] =
                        coefficients[(coefficient-1)*SYMBOL_W +: SYMBOL_W]
                        ^ gf_mul(coefficients[coefficient*SYMBOL_W +: SYMBOL_W], root);
                coefficients[0 +: SYMBOL_W] =
                    gf_mul(coefficients[0 +: SYMBOL_W], root);
                root = gf_mul(root, SYMBOL_ALPHA);
            end
            generator_coefficient = coefficients[coefficient_index*SYMBOL_W +: SYMBOL_W];
        end
    endfunction

    reg [SYMBOL_W-1:0] remainder [0:PARITY_SYMBOLS-1];
    wire [SYMBOL_W-1:0] data_next [0:PARITY_SYMBOLS-1];
    wire [SYMBOL_W-1:0] parity_next [0:PARITY_SYMBOLS-1];
    wire [SYMBOL_W-1:0] feedback;

    reg [SYMBOL_W-1:0] held_data;
    reg held_valid;
    reg draining;
    reg window;
    reg [63:0] parity_left;
    reg [63:0] active_symbols;

    wire take_data;
    wire take_payload;
    wire take_parity;
    wire open_frame;
    wire close_frame;

    // A one-symbol elastic buffer forwards payload before its parity suffix.
    // With i_valid=0 and o_ready=0, every state register holds its value.
    assign i_ready = !draining && (!held_valid || o_ready);
    assign o_valid = held_valid || draining;
    assign o_data = held_valid ? held_data : remainder[PARITY_SYMBOLS-1];
    assign o_last = draining && !held_valid && (parity_left == 64'd1);
    assign o_active_symbols = active_symbols;

    assign take_data = i_valid && i_ready;
    assign take_payload = held_valid && o_ready;
    assign take_parity = draining && !held_valid && o_ready;
    assign open_frame = take_data && !window;
    assign close_frame = take_parity && (parity_left == 64'd1);
    assign feedback = i_data ^ remainder[PARITY_SYMBOLS-1];

    wire [63:0] live_prefix [0:PARITY_SYMBOLS];
    wire [63:0] next_live_prefix [0:PARITY_SYMBOLS];
    wire [63:0] current_live;
    wire [63:0] next_live;
    assign live_prefix[0] = 64'd0;
    assign next_live_prefix[0] = 64'd0;
    assign current_live = live_prefix[PARITY_SYMBOLS];
    assign next_live = next_live_prefix[PARITY_SYMBOLS];

    genvar lane;
    generate
        for (lane = 0; lane < PARITY_SYMBOLS; lane = lane + 1) begin : parity_bank
            localparam [SYMBOL_W-1:0] COEFFICIENT = generator_coefficient(lane);

            if (lane == 0) begin : low_lane
                assign data_next[lane] = gf_mul(feedback, COEFFICIENT);
                assign parity_next[lane] = SYMBOL_ZERO;
            end else begin : other_lane
                assign data_next[lane] = remainder[lane-1] ^ gf_mul(feedback, COEFFICIENT);
                assign parity_next[lane] = remainder[lane-1];
            end

            assign live_prefix[lane+1] = live_prefix[lane]
                + ((remainder[lane] != SYMBOL_ZERO) ? 64'd1 : 64'd0);
            assign next_live_prefix[lane+1] = next_live_prefix[lane]
                + ((data_next[lane] != SYMBOL_ZERO) ? 64'd1 : 64'd0);

            initial remainder[lane] = SYMBOL_ZERO;
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    remainder[lane] <= SYMBOL_ZERO;
                else if (take_data)
                    remainder[lane] <= data_next[lane];
                else if (take_parity)
                    remainder[lane] <= parity_next[lane];
            end
        end
    endgenerate

    initial begin
        held_data = SYMBOL_ZERO;
        held_valid = 1'b0;
        draining = 1'b0;
        window = 1'b0;
        parity_left = 64'd0;
        active_symbols = 64'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            held_data <= SYMBOL_ZERO;
            held_valid <= 1'b0;
            draining <= 1'b0;
            window <= 1'b0;
            parity_left <= 64'd0;
            active_symbols <= 64'd0;
        end else begin
            if (take_payload)
                held_valid <= 1'b0;

            if (take_data) begin
                held_data <= i_data;
                held_valid <= 1'b1;
                active_symbols <= active_symbols + next_live - current_live;
                if (i_last) begin
                    draining <= 1'b1;
                    parity_left <= PARITY_LIMIT;
                end
            end

            if (take_parity) begin
                active_symbols <= active_symbols
                    - ((remainder[PARITY_SYMBOLS-1] != SYMBOL_ZERO) ? 64'd1 : 64'd0);
                parity_left <= parity_left - 64'd1;
                if (close_frame)
                    draining <= 1'b0;
            end

            if (open_frame)
                window <= 1'b1;
            if (close_frame)
                window <= 1'b0;
        end
    end

    always @(posedge clk)
        if (window)
            assert (active_symbols <= PARITY_LIMIT);
endmodule

module age_stamped_tag_cam #(
    parameter integer ENTRIES = 4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        insert_en,
    input  wire        lookup_en,
    input  wire [31:0] insert_key,
    input  wire [31:0] lookup_key,
    output reg         report_valid,
    output reg  [31:0] report_key,
    output reg  [31:0] report_stamp
);
    localparam integer INDEX_W = (ENTRIES > 1) ? $clog2(ENTRIES) : 1;

    reg [31:0] key [0:ENTRIES-1];
    reg [31:0] stamp [0:ENTRIES-1];
    reg [ENTRIES-1:0] valid;
    reg [31:0] time_counter;
    reg armed;

    wire [ENTRIES-1:0] stamp_in_range;

    // Explicit feed-forward selection stages avoid dynamically indexed
    // feedback through procedural search variables.
    wire [ENTRIES:0] match_seen;
    wire [31:0] match_stamp_stage [0:ENTRIES];
    wire [31:0] match_key_stage [0:ENTRIES];

    wire [ENTRIES:0] free_seen;
    wire [INDEX_W-1:0] free_index_stage [0:ENTRIES];

    wire [ENTRIES:0] oldest_seen;
    wire [31:0] oldest_stamp_stage [0:ENTRIES];
    wire [INDEX_W-1:0] oldest_index_stage [0:ENTRIES];

    wire [INDEX_W-1:0] victim_index;

    assign match_seen[0] = 1'b0;
    assign match_stamp_stage[0] = 32'd0;
    assign match_key_stage[0] = 32'd0;
    assign free_seen[0] = 1'b0;
    assign free_index_stage[0] = {INDEX_W{1'b0}};
    assign oldest_seen[0] = 1'b0;
    assign oldest_stamp_stage[0] = 32'd0;
    assign oldest_index_stage[0] = {INDEX_W{1'b0}};

    assign victim_index = free_seen[ENTRIES]
                        ? free_index_stage[ENTRIES]
                        : oldest_index_stage[ENTRIES];

    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : entries
            localparam [INDEX_W-1:0] ENTRY_INDEX = g;
            wire is_match;
            wire take_match;
            wire take_free;
            wire take_oldest;

            initial begin
                key[g] = 32'd0;
                stamp[g] = 32'd0;
                valid[g] = 1'b0;
            end

            assign stamp_in_range[g] = !valid[g] ||
                                      (stamp[g] <= time_counter);

            assign is_match = valid[g] && (key[g] == lookup_key);
            assign take_match = is_match &&
                                (!match_seen[g] ||
                                 (stamp[g] < match_stamp_stage[g]));
            assign match_seen[g+1] = match_seen[g] || is_match;
            assign match_stamp_stage[g+1] = take_match
                                          ? stamp[g]
                                          : match_stamp_stage[g];
            assign match_key_stage[g+1] = take_match
                                        ? key[g]
                                        : match_key_stage[g];

            assign take_free = !valid[g] && !free_seen[g];
            assign free_seen[g+1] = free_seen[g] || !valid[g];
            assign free_index_stage[g+1] = take_free
                                         ? ENTRY_INDEX
                                         : free_index_stage[g];

            assign take_oldest = valid[g] &&
                                 (!oldest_seen[g] ||
                                  (stamp[g] < oldest_stamp_stage[g]));
            assign oldest_seen[g+1] = oldest_seen[g] || valid[g];
            assign oldest_stamp_stage[g+1] = take_oldest
                                           ? stamp[g]
                                           : oldest_stamp_stage[g];
            assign oldest_index_stage[g+1] = take_oldest
                                           ? ENTRY_INDEX
                                           : oldest_index_stage[g];

            always @(posedge clk) begin
                if (i_ce && insert_en && (victim_index == ENTRY_INDEX)) begin
                    valid[g] <= 1'b1;
                    key[g] <= insert_key;
                    stamp[g] <= time_counter;
                end
            end
        end
    endgenerate

    initial begin
        time_counter = 32'd0;
        report_valid = 1'b0;
        report_key = 32'd0;
        report_stamp = 32'd0;
        armed = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Saturation prevents timestamp order from wrapping.
            if (time_counter != 32'hffffffff)
                time_counter <= time_counter + 32'd1;

            // Concurrent insertions and lookups both observe the old entries.
            if (lookup_en) begin
                report_valid <= match_seen[ENTRIES];
                if (match_seen[ENTRIES]) begin
                    report_key <= match_key_stage[ENTRIES];
                    report_stamp <= match_stamp_stage[ENTRIES];
                    armed <= 1'b1;
                end
            end
        end
    end

    // After the first successful lookup, the reported stamp is not future-dated.
    assert property (!armed || (report_stamp <= time_counter));
endmodule

module timed_output_table #(
    parameter integer CHANNELS = 16,
    parameter integer TIMER_WIDTH = 8
) (
    input  wire clk,
    input  wire i_ce,
    input  wire in_valid,
    output wire in_ready,
    input  wire [31:0] in_opcode,
    input  wire [31:0] in_channel,
    input  wire [TIMER_WIDTH-1:0] in_compare,
    input  wire [31:0] in_action,
    output reg  [CHANNELS-1:0] pin_out,
    output reg  [CHANNELS-1:0] out_valid,
    input  wire [CHANNELS-1:0] out_ready,
    output reg  [TIMER_WIDTH-1:0] timer_count,
    output reg  [31:0] pending_count,
    output reg  scope_active
);
    localparam [31:0] CMD_PROGRAM = 32'd0;
    localparam [31:0] CMD_TICK    = 32'd1;
    localparam [31:0] CMD_OPEN    = 32'd2;
    localparam [31:0] CMD_CLOSE   = 32'd3;

    reg [CHANNELS*TIMER_WIDTH-1:0] compare_table;
    reg [CHANNELS*2-1:0] action_table;
    reg [CHANNELS-1:0] armed;
    reg [CHANNELS-1:0] due;

    wire [CHANNELS-1:0] compare_hit;
    wire [CHANNELS-1:0] retire;
    wire [31:0] armed_sum [0:CHANNELS];
    wire [31:0] retired_sum [0:CHANNELS];
    wire [31:0] armed_population;

    assign armed_sum[0] = 32'd0;
    assign retired_sum[0] = 32'd0;
    assign armed_population = armed_sum[CHANNELS];

    wire target_available = (in_channel < CHANNELS)
                          ? (!armed[in_channel] || retire[in_channel])
                          : 1'b0;
    assign in_ready = i_ce &&
                      ((in_opcode != CMD_PROGRAM) || target_available);
    wire transfer = in_valid && in_ready;
    wire program_accept = transfer && (in_opcode == CMD_PROGRAM);

    initial begin
        compare_table = {CHANNELS*TIMER_WIDTH{1'b0}};
        action_table = {CHANNELS*2{1'b0}};
        armed = {CHANNELS{1'b0}};
        due = {CHANNELS{1'b0}};
        pin_out = {CHANNELS{1'b0}};
        out_valid = {CHANNELS{1'b0}};
        timer_count = {TIMER_WIDTH{1'b0}};
        pending_count = 32'd0;
        scope_active = 1'b0;
    end

    genvar g;
    generate
        for (g = 0; g < CHANNELS; g = g + 1) begin : channels
            localparam [31:0] CHANNEL_ID = g;
            wire load_here = program_accept &&
                             (in_channel == CHANNEL_ID);

            assign compare_hit[g] = armed[g] &&
                (timer_count == compare_table[g*TIMER_WIDTH +: TIMER_WIDTH]);

            // An empty output accepts a completion without waiting for ready.
            // A full output can be consumed and replaced on the same edge.
            assign retire[g] = i_ce && armed[g] &&
                               (due[g] || compare_hit[g]) &&
                               (!out_valid[g] || out_ready[g]);

            assign armed_sum[g+1] = armed_sum[g] + {31'd0, armed[g]};
            assign retired_sum[g+1] = retired_sum[g] + {31'd0, retire[g]};

            always @(posedge clk) begin
                if (i_ce) begin
                    // Each output drains using only its own ready signal.
                    if (retire[g]) begin
                        out_valid[g] <= 1'b1;
                        case (action_table[g*2 +: 2])
                            2'd0: pin_out[g] <= 1'b0;
                            2'd1: pin_out[g] <= 1'b1;
                            2'd2: pin_out[g] <= !pin_out[g];
                            2'd3: pin_out[g] <= pin_out[g];
                        endcase
                    end else if (out_ready[g]) begin
                        out_valid[g] <= 1'b0;
                    end

                    // Programming may refill a channel on its retirement edge.
                    if (load_here) begin
                        armed[g] <= 1'b1;
                        due[g] <= 1'b0;
                        compare_table[g*TIMER_WIDTH +: TIMER_WIDTH] <= in_compare;
                        action_table[g*2 +: 2] <= in_action[1:0];
                    end else if (retire[g]) begin
                        armed[g] <= 1'b0;
                        due[g] <= 1'b0;
                    end else if (compare_hit[g]) begin
                        // Preserve a match while its output buffer is occupied.
                        due[g] <= 1'b1;
                    end
                end
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            // Time advances independently of command acceptance, so a blocked
            // program command cannot prevent an occupied channel from expiring.
            timer_count <= timer_count + 1'b1;
            pending_count <= pending_count
                           + (program_accept ? 32'd1 : 32'd0)
                           - retired_sum[CHANNELS];

            if (transfer) begin
                case (in_opcode)
                    CMD_OPEN: scope_active <= 1'b1;
                    CMD_CLOSE: scope_active <= 1'b0;
                    CMD_TICK: begin end // Time already advances on every enabled edge.
                    default: begin end
                endcase
            end
        end
    end

    // Handshakes and state updates use enabled clock edges.
    always @(posedge clk) begin
        if (scope_active)
            assert (pending_count <= CHANNELS);
    end
endmodule

module chien_deadline_search #(
    parameter integer FIELD_W = 8,
    parameter integer COEFFS = 4,
    parameter [FIELD_W-1:0] REDUCTION = 8'h1d
) (
    input  wire clk,
    input  wire req_valid,
    output wire req_ready,
    input  wire [COEFFS*FIELD_W-1:0] req_coeffs,
    output wire result_valid,
    input  wire result_ready,
    output reg  [FIELD_W-1:0] position,
    output reg  hit,
    output reg  [3:0] debug_nibble
);
    localparam [FIELD_W-1:0] FIELD_ZERO = {FIELD_W{1'b0}};
    localparam [FIELD_W-1:0] FIELD_ONE = {{(FIELD_W-1){1'b0}}, 1'b1};
    localparam [FIELD_W-1:0] LAST_POSITION = {FIELD_W{1'b1}};
    localparam [FIELD_W:0] FIELD_SIZE = {1'b1, {FIELD_W{1'b0}}};
    localparam [FIELD_W:0] CREDIT_ONE = {{FIELD_W{1'b0}}, 1'b1};

    reg busy;
    reg armed;
    reg pv;
    reg [FIELD_W:0] credits;
    reg [FIELD_W-1:0] terms [0:COEFFS-1];
    wire [FIELD_W-1:0] stepped_terms [0:COEFFS-1];
    reg [FIELD_W-1:0] eval_now;
    reg [FIELD_W-1:0] eval_next;

    wire request_fire;
    wire trial_fire;
    assign req_ready = !busy;
    assign result_valid = busy;
    assign request_fire = req_valid && req_ready;
    assign trial_fire = result_valid && result_ready;

    function automatic [FIELD_W-1:0] gf_xtime;
        input [FIELD_W-1:0] a;
        begin
            gf_xtime = (a << 1'b1) ^
                       (a[FIELD_W-1] ? REDUCTION : FIELD_ZERO);
        end
    endfunction

    function automatic [FIELD_W-1:0] gf_mul;
        input [FIELD_W-1:0] a;
        input [FIELD_W-1:0] b;
        reg [FIELD_W-1:0] multiplicand;
        reg [FIELD_W-1:0] multiplier;
        reg [FIELD_W-1:0] product;
        integer bit_index;
        begin
            multiplicand = a;
            multiplier = b;
            product = FIELD_ZERO;
            for (bit_index = 0; bit_index < FIELD_W; bit_index = bit_index + 1) begin
                if (multiplier[0])
                    product = product ^ multiplicand;
                multiplicand = gf_xtime(multiplicand);
                multiplier = multiplier >> 1'b1;
            end
            gf_mul = product;
        end
    endfunction

    function automatic [FIELD_W-1:0] alpha_factor;
        input integer exponent;
        reg [FIELD_W-1:0] factor;
        integer power_index;
        begin
            factor = FIELD_ONE;
            for (power_index = 0; power_index < exponent; power_index = power_index + 1)
                factor = gf_xtime(factor);
            alpha_factor = factor;
        end
    endfunction

    genvar coefficient;
    generate
        for (coefficient = 0; coefficient < COEFFS; coefficient = coefficient + 1) begin : coefficient_steps
            assign stepped_terms[coefficient] =
                gf_mul(terms[coefficient], alpha_factor(coefficient));
        end
    endgenerate

    integer eval_index;
    always @(*) begin
        eval_now = FIELD_ZERO;
        eval_next = FIELD_ZERO;
        for (eval_index = 0; eval_index < COEFFS; eval_index = eval_index + 1) begin
            eval_now = eval_now ^ terms[eval_index];
            eval_next = eval_next ^ stepped_terms[eval_index];
        end
    end

    reg [15:0] mon_requests;
    reg [15:0] mon_results;
    reg [15:0] mon_hits;
    reg [15:0] mon_stalls;
    reg [15:0] mon_stall_run;
    reg [15:0] mon_stall_peak;
    reg [15:0] mon_search_age;
    reg [15:0] mon_last_latency;
    reg [4:0] mon_scan;
    wire [127:0] mon_frame;
    assign mon_frame = {mon_last_latency, mon_search_age,
                        mon_stall_peak, mon_stall_run,
                        mon_stalls, mon_hits, mon_results, mon_requests};

    initial begin
        mon_requests = 16'd0;
        mon_results = 16'd0;
        mon_hits = 16'd0;
        mon_stalls = 16'd0;
        mon_stall_run = 16'd0;
        mon_stall_peak = 16'd0;
        mon_search_age = 16'd0;
        mon_last_latency = 16'd0;
        mon_scan = 5'd0;
        debug_nibble = 4'd0;
    end

    always @(posedge clk) begin
        mon_scan <= mon_scan + 5'd1;
        debug_nibble <= mon_frame[{mon_scan, 2'b00} +: 4];
        if (request_fire && mon_requests != 16'hffff)
            mon_requests <= mon_requests + 16'd1;
        if (trial_fire && mon_results != 16'hffff)
            mon_results <= mon_results + 16'd1;
        if (trial_fire && hit && mon_hits != 16'hffff)
            mon_hits <= mon_hits + 16'd1;
        if (busy && !result_ready) begin
            if (mon_stalls != 16'hffff)
                mon_stalls <= mon_stalls + 16'd1;
            if (mon_stall_run != 16'hffff) begin
                mon_stall_run <= mon_stall_run + 16'd1;
                if (mon_stall_run >= mon_stall_peak)
                    mon_stall_peak <= mon_stall_run + 16'd1;
            end
        end else begin
            mon_stall_run <= 16'd0;
        end
        if (request_fire) begin
            mon_search_age <= 16'd0;
        end else if (busy) begin
            if (mon_search_age != 16'hffff)
                mon_search_age <= mon_search_age + 16'd1;
        end
        if (trial_fire && position == LAST_POSITION) begin
            mon_last_latency <= (mon_search_age == 16'hffff) ?
                                16'hffff : mon_search_age + 16'd1;
        end
    end


    integer init_index;
    initial begin
        busy = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
        credits = {1'b0, FIELD_ZERO};
        position = FIELD_ZERO;
        hit = 1'b0;
        for (init_index = 0; init_index < COEFFS; init_index = init_index + 1)
            terms[init_index] = FIELD_ZERO;
    end

    // Position zero tests x=0. Positions 1..255 test alpha^0..alpha^254.
    // Each accepted result consumes one enabled search cycle. Back-pressure
    // freezes the countdown, multiplier registers, position and hit flag.
    integer state_index;
    always @(posedge clk) begin
        if (request_fire || trial_fire)
            pv <= 1'b1;

        if (request_fire) begin
            armed <= 1'b1;
            busy <= 1'b1;
            credits <= FIELD_SIZE;
            position <= FIELD_ZERO;
            hit <= (req_coeffs[0 +: FIELD_W] == FIELD_ZERO);
            for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                terms[state_index] <= req_coeffs[state_index*FIELD_W +: FIELD_W];
        end else if (trial_fire) begin
            credits <= credits - CREDIT_ONE;
            if (position == LAST_POSITION) begin
                busy <= 1'b0;
            end else begin
                position <= position + FIELD_ONE;
                if (position == FIELD_ZERO) begin
                    // The first nonzero element is one; coefficients stay unchanged.
                    hit <= (eval_now == FIELD_ZERO);
                end else begin
                    for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                        terms[state_index] <= stepped_terms[state_index];
                    hit <= (eval_next == FIELD_ZERO);
                end
            end
        end
    end

    // After the first accepted request, consuming the previous cycle's final
    // countdown credit must leave no search outstanding.
    always @(posedge clk)
        if (pv && armed && $past(trial_fire))
            assert (!busy || ($past(credits) > CREDIT_ONE));
endmodule

module trellis_acs_accel #(
    parameter WORD_W = 128,
    parameter STATES = 8,
    parameter TRACE_DEPTH = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_valid,
    output wire i_ready,
    input  wire [STATES*WORD_W-1:0] i_branch_a,
    input  wire [STATES*WORD_W-1:0] i_branch_b,
    output wire o_valid,
    input  wire o_ready,
    output wire [WORD_W-1:0] o_terminal_metric,
    output wire [WORD_W-1:0] o_terminal_runner_up,
    output wire [STATES-1:0] o_survivors,
    input  wire [((TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1)-1:0] trace_read_addr,
    output wire [WORD_W-1:0] trace_read_word,
    output wire [159:0] o_debug_stats
);
    localparam TRACE_AW = (TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1;

    reg [WORD_W-1:0] path_metric [0:STATES-1];
    reg [WORD_W-1:0] runner_up   [0:STATES-1];
    reg [WORD_W-1:0] cand_a      [0:STATES-1];
    reg [WORD_W-1:0] cand_b      [0:STATES-1];
    reg [STATES-1:0] survivor;
    reg [WORD_W-1:0] traceback [0:TRACE_DEPTH-1];
    reg [TRACE_AW-1:0] trace_wr;
    reg pending;
    reg armed;

    function automatic [WORD_W-1:0] metric_add;
        input [WORD_W-1:0] a;
        input [WORD_W-1:0] b;
        reg [WORD_W:0] total;
        begin
            total = {1'b0, a} + {1'b0, b};
            metric_add = total[WORD_W] ? {WORD_W{1'b1}} : total[WORD_W-1:0];
        end
    endfunction

    wire [WORD_W-1:0] next_a [0:STATES-1];
    wire [WORD_W-1:0] next_b [0:STATES-1];

    genvar g;
    generate
        for (g = 0; g < STATES; g = g + 1) begin : trellis
            localparam PRED_A = (2*g) % STATES;
            localparam PRED_B = (2*g + 1) % STATES;
            assign next_a[g] = metric_add(
                path_metric[PRED_A], i_branch_a[g*WORD_W +: WORD_W]);
            assign next_b[g] = metric_add(
                path_metric[PRED_B], i_branch_b[g*WORD_W +: WORD_W]);
        end
    endgenerate

    assign i_ready = !pending;
    assign o_valid = pending;
    wire accept_branches = i_valid && i_ready;
    wire retire_survivors = o_valid && o_ready;

    assign o_terminal_metric = survivor[0] ? cand_b[0] : cand_a[0];
    assign o_terminal_runner_up = survivor[0] ? cand_a[0] : cand_b[0];
    assign o_survivors = survivor;
    assign trace_read_word = traceback[trace_read_addr];
    wire [WORD_W-1:0] survivor_word = {{(WORD_W-STATES){1'b0}}, survivor};

    reg [31:0] dbg_accept_count;
    reg [31:0] dbg_retire_count;
    reg [31:0] dbg_input_stalls;
    reg [31:0] dbg_output_stalls;
    reg [15:0] dbg_stall_run;
    reg [15:0] dbg_stall_peak;
    wire dbg_output_stalled = o_valid && !o_ready;
    assign o_debug_stats = {dbg_accept_count, dbg_retire_count,
                           dbg_input_stalls, dbg_output_stalls, dbg_stall_run, dbg_stall_peak};

    initial begin
        dbg_accept_count = 32'd0;
        dbg_retire_count = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_peak = 16'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dbg_accept_count <= 32'd0;
            dbg_retire_count <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_peak <= 16'd0;
        end else begin
            if (accept_branches) begin
                if (dbg_accept_count != 32'hffff_ffff)
                    dbg_accept_count <= dbg_accept_count + 32'd1;
            end
            if (retire_survivors) begin
                if (dbg_retire_count != 32'hffff_ffff)
                    dbg_retire_count <= dbg_retire_count + 32'd1;
            end
            if (i_valid && !i_ready) begin
                if (dbg_input_stalls != 32'hffff_ffff)
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
            end
            if (dbg_output_stalled) begin
                if (dbg_output_stalls != 32'hffff_ffff)
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (dbg_stall_run != 16'hffff) begin
                    dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_peak)
                        dbg_stall_peak <= dbg_stall_run + 16'd1;
                end
            end else begin
                dbg_stall_run <= 16'd0;
            end
        end
    end

    initial begin
        pending = 1'b0;
        armed = 1'b0;
        survivor = {STATES{1'b0}};
        trace_wr = {TRACE_AW{1'b0}};
        for (integer s = 0; s < STATES; s = s + 1) begin
            path_metric[s] = {WORD_W{1'b0}};
            runner_up[s] = {WORD_W{1'b0}};
            cand_a[s] = {WORD_W{1'b0}};
            cand_b[s] = {WORD_W{1'b0}};
        end
        for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
            traceback[t] = {WORD_W{1'b0}};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending <= 1'b0;
            armed <= 1'b0;
            survivor <= {STATES{1'b0}};
            trace_wr <= {TRACE_AW{1'b0}};
            for (integer s = 0; s < STATES; s = s + 1) begin
                path_metric[s] <= {WORD_W{1'b0}};
                runner_up[s] <= {WORD_W{1'b0}};
                cand_a[s] <= {WORD_W{1'b0}};
                cand_b[s] <= {WORD_W{1'b0}};
            end
            for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
                traceback[t] <= {WORD_W{1'b0}};
        end else begin
            // Capture both path candidates and their comparison together.
            if (accept_branches) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    cand_a[s] <= next_a[s];
                    cand_b[s] <= next_b[s];
                    survivor[s] <= (next_b[s] < next_a[s]);
                end
                pending <= 1'b1;
            end

            // Back-pressure holds the candidate bank and output unchanged.
            // Retain the losing metric for decoder confidence estimation.
            if (retire_survivors) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    path_metric[s] <= survivor[s] ? cand_b[s] : cand_a[s];
                    runner_up[s] <= survivor[s] ? cand_a[s] : cand_b[s];
                end
                traceback[trace_wr] <= survivor_word;
                if (trace_wr == TRACE_AW'(TRACE_DEPTH - 1))
                    trace_wr <= {TRACE_AW{1'b0}};
                else
                    trace_wr <= trace_wr + {{(TRACE_AW-1){1'b0}}, 1'b1};
                pending <= 1'b0;
                // Q: the first completed trellis update.
                armed <= 1'b1;
            end
        end
    end

    // After Q, the committed terminal-state survivor never exceeds its runner-up.
    always @(posedge clk)
        assert (!armed || (path_metric[0] <= runner_up[0]));
endmodule

module pixel_dot_accumulator #(
    parameter integer LANES = 16,
    parameter integer WORD_W = 64
) (
    input wire clk,
    input wire ce,
    input wire end_frame,
    input wire [(LANES*WORD_W)-1:0] shade_operands,
    input wire [(LANES*WORD_W)-1:0] texture_operands,
    input wire peer_valid,
    input wire [(LANES*WORD_W)-1:0] peer_terms,
    output wire [WORD_W-1:0] accumulated_value, peer_accumulated_value,
    output wire issue_ready, peer_ready,
    output wire peer_nonzero_issued,
    output reg staged_valid
);
    localparam integer CHANNELS = 2;
    // Products and additions use fixed-width modular arithmetic.
    reg [WORD_W-1:0] products [0:LANES-1];
    wire [WORD_W-1:0] incoming_product [0:LANES-1];
    wire [WORD_W-1:0] adder_tree [1:(2*LANES)-1];
    wire [LANES-1:0] incoming_nonzero;
    wire [LANES-1:0] staged_nonzero;
    wire pending_nonzero;

    reg [WORD_W-1:0] running_sum;
    reg seen_nonzero_issue;
    reg before_end;
    reg past_valid;
    reg [WORD_W-1:0] peer_running_sum;
    reg peer_seen_nonzero_issue;
    reg [$clog2(CHANNELS)-1:0] stage_owner, next_owner;
    wire peer_grant = peer_valid && (next_owner == 1'b1);

    initial begin
        running_sum = {WORD_W{1'b0}};
        seen_nonzero_issue = 1'b0;
        before_end = 1'b1;
        past_valid = 1'b0;
        peer_running_sum = {WORD_W{1'b0}};
        peer_seen_nonzero_issue = 1'b0;
        stage_owner = 1'b0;
        next_owner = 1'b0;
        staged_valid = 1'b0;
    end

    genvar lane;
    generate
        for (lane = 0; lane < LANES; lane = lane + 1) begin : lanes
            assign incoming_product[lane] =
                shade_operands[lane*WORD_W +: WORD_W] *
                texture_operands[lane*WORD_W +: WORD_W];
            assign incoming_nonzero[lane] =
                incoming_product[lane] != {WORD_W{1'b0}};
            assign staged_nonzero[lane] =
                products[lane] != {WORD_W{1'b0}};
            assign adder_tree[LANES+lane] = products[lane];

            initial products[lane] = {WORD_W{1'b0}};
            always @(posedge clk) begin
                if (ce)
                    products[lane] <= peer_grant ?
                        peer_terms[lane*WORD_W +: WORD_W] : incoming_product[lane];
            end
        end
    endgenerate

    genvar node;
    generate
        for (node = 1; node < LANES; node = node + 1) begin : reduction_tree
            assign adder_tree[node] =
                adder_tree[2*node] + adder_tree[2*node+1];
        end
    endgenerate

    assign pending_nonzero = |staged_nonzero;
    assign accumulated_value = running_sum;
    assign issue_ready = ce && !peer_grant;
    assign peer_ready = ce && (next_owner == 1'b1);
    assign peer_accumulated_value = peer_running_sum;
    assign peer_nonzero_issued = peer_seen_nonzero_issue;

    always @(posedge clk) begin
        if (ce) begin
            if (staged_valid) begin
                if (!stage_owner) running_sum <= running_sum + adder_tree[1];
                else peer_running_sum <= peer_running_sum + adder_tree[1];
            end
            stage_owner <= peer_grant;
            next_owner <= !peer_grant;
            staged_valid <= 1'b1;
            if (peer_grant)
                peer_seen_nonzero_issue <= peer_seen_nonzero_issue || (|peer_terms);
            else begin
            // History of a nonzero product entering the preceding stage.
            seen_nonzero_issue <= seen_nonzero_issue || (|incoming_nonzero);
            if (end_frame)
                before_end <= 1'b0;
            end
            past_valid <= 1'b1;
        end
    end

    // Before the first frame-end event, a rising nonzero accumulated value
    // must be preceded by an issued nonzero product.
    always @(posedge clk) begin
        if (past_valid && before_end &&
            $rose(running_sum != {WORD_W{1'b0}}))
            assert (seen_nonzero_issue);
    end
    always @(posedge clk) begin
        if (past_valid && $rose(peer_running_sum != {WORD_W{1'b0}}))
            assert (peer_seen_nonzero_issue);
    end
endmodule

module wave_line_prefetcher #(
    parameter integer LINE_W = 8,
    parameter integer DEPTH = 64,
    parameter integer COUNT_W = 8
) (
    input  wire                  clk,
    input  wire                  miss_valid,
    output wire                  miss_ready,
    input  wire [LINE_W-1:0]     miss_line,
    output wire                  prefetch_valid,
    input  wire                  prefetch_ready,
output wire [LINE_W-1:0]     prefetch_line,
input  wire                  peer_miss_valid,
output wire                  peer_miss_ready,
input  wire [LINE_W-1:0]     peer_miss_line,
output wire                  prefetch_peer
);
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [LINE_W-1:0] LINE_ZERO = {LINE_W{1'b0}};
    localparam [LINE_W-1:0] LINE_ONE = {{(LINE_W-1){1'b0}}, 1'b1};
localparam integer CHANNELS = 2, PEER_DEPTH = 4;
localparam integer PEER_PTR_W = $clog2(PEER_DEPTH), PEER_COUNT_W = $clog2(PEER_DEPTH+1);

    reg [LINE_W-1:0] prefetch_q [0:DEPTH-1];
    reg [COUNT_W-1:0] wr_ptr;
    reg [COUNT_W-1:0] rd_ptr;
    reg [COUNT_W-1:0] used;
    reg [LINE_W-1:0] last_miss;
    reg pv;
reg [LINE_W-1:0] peer_q [0:PEER_DEPTH-1];
reg [PEER_PTR_W-1:0] peer_wr, peer_rd;
reg [PEER_COUNT_W-1:0] peer_used;
reg output_locked;
reg [$clog2(CHANNELS)-1:0] output_owner, output_turn;

    initial begin
        wr_ptr = COUNT_ZERO;
        rd_ptr = COUNT_ZERO;
        used = COUNT_ZERO;
        last_miss = {LINE_W{1'b1}};
        pv = 1'b0;
peer_wr = 0; peer_rd = 0; peer_used = 0;
output_locked = 1'b0; output_owner = 1'b0; output_turn = 1'b0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : initialize_queue
            initial prefetch_q[g] = LINE_ZERO;
        end
for (g = 0; g < PEER_DEPTH; g = g + 1) begin : initialize_peer
    initial peer_q[g] = LINE_ZERO;
end
    endgenerate

    assign miss_ready = (used < CAPACITY);
assign peer_miss_ready = (peer_used < PEER_DEPTH);
assign prefetch_peer = output_locked ? output_owner :
    ((peer_used != 0) && ((used == COUNT_ZERO) || output_turn));
assign prefetch_valid = prefetch_peer ? (peer_used != 0) : (used != COUNT_ZERO);
assign prefetch_line = prefetch_peer ? peer_q[peer_rd] : prefetch_q[rd_ptr];

    wire push = miss_valid && miss_ready;
wire pop = prefetch_valid && prefetch_ready && !prefetch_peer;
wire peer_push = peer_miss_valid && peer_miss_ready;
wire peer_pop = prefetch_valid && prefetch_ready && prefetch_peer;

    // The slot immediately preceding the write pointer retains the
    // most recently generated next-line request, even after retirement.
    wire [COUNT_W-1:0] latest_slot =
        (wr_ptr == COUNT_ZERO) ? LAST_SLOT : (wr_ptr - COUNT_ONE);
    wire [LINE_W-1:0] latest_line = prefetch_q[latest_slot];

    always @(posedge clk) begin
        if (push) begin
            prefetch_q[wr_ptr] <= miss_line + LINE_ONE;
            last_miss <= miss_line;
            wr_ptr <= (wr_ptr == LAST_SLOT) ? COUNT_ZERO : (wr_ptr + COUNT_ONE);
        end
        if (pop)
            rd_ptr <= (rd_ptr == LAST_SLOT) ? COUNT_ZERO : (rd_ptr + COUNT_ONE);

        if (push && !pop)
            used <= used + COUNT_ONE;
        else if (pop && !push)
            used <= used - COUNT_ONE;

        // No history check is needed before the first transaction.
        // Keeping this update transaction-gated preserves complete idle.
        if (push || pop)
            pv <= 1'b1;
    end

always @(posedge clk) begin
    if (peer_push) begin
        peer_q[peer_wr] <= peer_miss_line + LINE_ONE;
        peer_wr <= (peer_wr == PEER_DEPTH-1) ? 0 : peer_wr + 1'b1;
    end
    if (peer_pop) peer_rd <= (peer_rd == PEER_DEPTH-1) ? 0 : peer_rd + 1'b1;
    if (peer_push && !peer_pop) peer_used <= peer_used + 1'b1;
    else if (peer_pop && !peer_push) peer_used <= peer_used - 1'b1;
    if (prefetch_valid) begin
        output_locked <= !prefetch_ready;
        output_owner <= prefetch_peer;
        if (prefetch_ready) output_turn <= !prefetch_peer;
    end
end

    always @(posedge clk)
        if (pv && $stable(last_miss))
            assert ($stable(latest_line));

always @(posedge clk)
    if (output_locked && prefetch_ready)
        assert (prefetch_valid);
endmodule

module video_allpass_sweep #(
    parameter [31:0] DEPTH = 32'd256,
    parameter [31:0] GAIN_SHIFT = 32'd1
) (
    input  wire               clk,
    input  wire               i_ce,
    input  wire               i_frame_sync,
    input  wire               i_block_start,
    input  wire signed [31:0] i_sample,
    output reg  signed [31:0] o_sample,
    output reg         [31:0] o_debug_status
);
    reg signed [31:0] delay_mem [0:DEPTH-32'd1];
    reg [31:0] ptr;
    reg [31:0] countdown;
    reg busy;
    reg armed;
    integer init_index;
    reg [15:0] stat_samples;
    reg [7:0] stat_blocks;
    reg [7:0] stat_rejected;

    // Schroeder allpass with dyadic gain g = 2^(-GAIN_SHIFT):
    // y = delayed - g*x; delay_write = x + g*y.
    // Arithmetic shifts implement the fixed-point gain coefficient.
    wire signed [31:0] delayed_sample;
    wire signed [31:0] feedforward;
    wire signed [31:0] allpass_sample;
    wire signed [31:0] feedback;
    wire signed [31:0] delay_write;

    assign delayed_sample = delay_mem[ptr];
    assign feedforward = i_sample >>> GAIN_SHIFT;
    assign allpass_sample = delayed_sample - feedforward;
    assign feedback = allpass_sample >>> GAIN_SHIFT;
    assign delay_write = i_sample + feedback;

    initial begin
        ptr = 32'd0;
        countdown = 32'd0;
        busy = 1'b0;
        armed = 1'b0;
        o_sample = 32'sd0;
        for (init_index = 32'd0; init_index < DEPTH;
             init_index = init_index + 32'd1)
            delay_mem[init_index] = 32'sd0;
    end
    initial begin
        stat_samples = 16'd0;
        stat_blocks = 8'd0;
        stat_rejected = 8'd0;
        o_debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_frame_sync) begin
                o_debug_status <= {stat_blocks, stat_rejected, stat_samples};
                stat_samples <= 16'd0;
                stat_blocks <= 8'd0;
                stat_rejected <= 8'd0;
            end else begin
                if (busy && (stat_samples != 16'hffff))
                    stat_samples <= stat_samples + 16'd1;
                if (!busy && i_block_start && (stat_blocks != 8'hff))
                    stat_blocks <= stat_blocks + 8'd1;
                if (busy && i_block_start && (stat_rejected != 8'hff))
                    stat_rejected <= stat_rejected + 8'd1;
            end
        end
    end

    // Each accepted block processes one complete circular-buffer sweep.
    // Countdown measures enabled processing cycles; i_ce freezes all state.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_frame_sync)
                armed <= 1'b1;

            if (!busy) begin
                if (i_block_start) begin
                    busy <= 1'b1;
                    ptr <= 32'd0;
                    countdown <= DEPTH;
                end
            end else begin
                o_sample <= allpass_sample;
                delay_mem[ptr] <= delay_write;

                if (ptr == (DEPTH - 32'd1)) begin
                    ptr <= 32'd0;
                    countdown <= 32'd0;
                    busy <= 1'b0;
                end else begin
                    ptr <= ptr + 32'd1;
                    countdown <= countdown - 32'd1;
                end
            end
        end
    end

    // After the first enabled frame-sync event, an outstanding block
    // must never exhaust its processing-cycle deadline.
    assert property (!armed || !busy || (countdown != 32'd0));
endmodule

module sklansky_result_channel #(
    parameter integer WIDTH = 32
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [WIDTH-1:0]     in_a,
    input  wire [WIDTH-1:0]     in_b,
    output wire                 out_valid,
    input  wire                 out_ready,
    output wire [WIDTH-1:0]     out_sum,
    output wire                 out_carry
,
    output wire [WIDTH-1:0] operand_a_o,
    output wire [WIDTH-1:0] operand_b_o,
    output wire [WIDTH-1:0] prefix_hold_o,
    output wire [WIDTH-1:0] propagate_hold_o
);
    localparam integer LEVELS = $clog2(WIDTH);

    // Two storage slots: a captured-prefix tail and a reconstructed front.
    reg pending;
    reg window;
    reg [WIDTH-1:0] operand_a, operand_b;
    reg [WIDTH-1:0] propagate_hold, prefix_hold;
    reg [WIDTH-1:0] result_a, result_b;
    reg [WIDTH-1:0] result_sum;
    reg result_carry;

    wire [WIDTH-1:0] tree_g [0:LEVELS];
    wire [WIDTH-1:0] tree_p [0:LEVELS];

    assign tree_g[0] = in_a & in_b;
    assign tree_p[0] = in_a ^ in_b;

    // Sklansky tree: each upper half shares the lower half's root.
    genvar level, bit_index;
    generate
        for (level = 0; level < LEVELS; level = level + 1) begin : prefix_level
            localparam integer HALF = 1 << level;
            localparam integer GROUP = HALF << 1;
            for (bit_index = 0; bit_index < WIDTH; bit_index = bit_index + 1) begin : prefix_bit
                if ((bit_index % GROUP) >= HALF) begin : combine
                    localparam integer ROOT = (bit_index / GROUP) * GROUP + HALF - 1;
                    assign tree_g[level+1][bit_index] =
                        tree_g[level][bit_index] |
                        (tree_p[level][bit_index] & tree_g[level][ROOT]);
                    assign tree_p[level+1][bit_index] =
                        tree_p[level][bit_index] & tree_p[level][ROOT];
                end else begin : bypass
                    assign tree_g[level+1][bit_index] = tree_g[level][bit_index];
                    assign tree_p[level+1][bit_index] = tree_p[level][bit_index];
                end
            end
        end
    endgenerate

    wire [WIDTH-1:0] pending_sum;
    wire pending_carry;
    assign pending_sum = propagate_hold ^ (prefix_hold << 1);
    assign pending_carry = prefix_hold[WIDTH-1];

    // A lone prefix-slot item is directly visible: valid never waits for ready.
    assign out_valid = window || pending;
    assign out_sum = window ? result_sum : pending_sum;
    assign out_carry = window ? result_carry : pending_carry;
    assign in_ready = !(window && pending) || out_ready;

    wire push;
    wire pop;
    wire promote;
    assign push = in_valid && in_ready;
    assign pop = out_valid && out_ready;

    // Promote the tail when removing an occupied front, or when an arriving
    // item needs the occupied tail slot and the front is empty.
    assign promote = pending && ((pop && window) || (push && !pop));

    wire [WIDTH:0] reference_sum;
    assign reference_sum = window
        ? ({1'b0, result_a} + {1'b0, result_b})
        : ({1'b0, operand_a} + {1'b0, operand_b});

    initial begin
        pending = 1'b0;
        window = 1'b0;
        operand_a = {WIDTH{1'b0}};
        operand_b = {WIDTH{1'b0}};
        propagate_hold = {WIDTH{1'b0}};
        prefix_hold = {WIDTH{1'b0}};
        result_a = {WIDTH{1'b0}};
        result_b = {WIDTH{1'b0}};
        result_sum = {WIDTH{1'b0}};
        result_carry = 1'b0;
    end

    // Every register holds when in_valid and out_ready are both low.
    always @(posedge clk) begin
        if (pop) begin
            pending <= 1'b0;
            window <= 1'b0;
        end

        if (promote) begin
            result_a <= operand_a;
            result_b <= operand_b;
            result_sum <= pending_sum;
            result_carry <= pending_carry;
            window <= 1'b1;
        end

        if (push) begin
            operand_a <= in_a;
            operand_b <= in_b;
            propagate_hold <= tree_p[0];
            prefix_hold <= tree_g[LEVELS];
            pending <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (out_valid)
            assert ({out_carry, out_sum} == reference_sum);
    end
    assign operand_a_o = operand_a;
    assign operand_b_o = operand_b;
    assign prefix_hold_o = prefix_hold;
    assign propagate_hold_o = propagate_hold;
endmodule

module dma_completion_tolerance #(
    parameter integer DATA_W = 8
) (
    input  wire                  clk,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [DATA_W-1:0]     i_observed,
    input  wire [DATA_W-1:0]     i_expected,
    input  wire [DATA_W-1:0]     i_epsilon,
    input  wire                  i_calibration_done,
    output reg                   o_valid,
    input  wire                  o_ready,
    output reg  [DATA_W-1:0]     o_epsilon,
    output reg                   o_within,
    output reg                   o_exact_mismatch
,
    output wire [DATA_W-1:0] delta_reg_o,
    output wire [DATA_W-1:0] expected_reg_o,
    output wire [DATA_W-1:0] observed_reg_o
);
    reg [DATA_W-1:0] observed_reg;
    reg [DATA_W-1:0] expected_reg;
    reg [DATA_W-1:0] delta_reg;
    reg [DATA_W-1:0] epsilon_reg;
    reg pending_valid;
    reg before_commit;

    wire [DATA_W-1:0] input_delta;
    wire output_can_load;

    assign input_delta = (i_observed >= i_expected)
                       ? (i_observed - i_expected)
                       : (i_expected - i_observed);

    // Each stage can fill an empty slot without downstream readiness.
    assign output_can_load = !o_valid || o_ready;
    assign i_ready = !pending_valid || output_can_load;

    initial begin
        observed_reg     = {DATA_W{1'b0}};
        expected_reg     = {DATA_W{1'b0}};
        delta_reg        = {DATA_W{1'b0}};
        epsilon_reg      = {DATA_W{1'b0}};
        pending_valid    = 1'b0;
        before_commit    = 1'b1;
        o_valid          = 1'b0;
        o_epsilon        = {DATA_W{1'b0}};
        o_within         = 1'b0;
        o_exact_mismatch = 1'b0;
    end

    always @(posedge clk) begin
        // Present a pending result whenever the output slot is available,
        // including when the receiver has not yet asserted ready.
        if (output_can_load) begin
            o_valid <= pending_valid;
            if (pending_valid) begin
                o_epsilon        <= epsilon_reg;
                o_within         <= (delta_reg <= epsilon_reg);
                o_exact_mismatch <= (observed_reg != expected_reg);
            end
        end

        // Accept into an empty pending slot, or replace an item advancing
        // to the output on this edge.
        if (i_ready) begin
            pending_valid <= i_valid;
            if (i_valid) begin
                observed_reg <= i_observed;
                expected_reg <= i_expected;
                delta_reg    <= input_delta;
                epsilon_reg  <= i_epsilon;
                if (i_calibration_done)
                    before_commit <= 1'b0;
            end
        end
    end

    // With both slots occupied, o_ready low freezes every state register.
    always @(*) begin
        if (before_commit && o_valid &&
            (o_epsilon == {DATA_W{1'b0}}))
            assert (!(o_within && o_exact_mismatch));
    end
    assign delta_reg_o = delta_reg;
    assign expected_reg_o = expected_reg;
    assign observed_reg_o = observed_reg;
endmodule

module dma_sum_tolerance_system #(
    parameter integer WIDTH = 32,
    parameter integer FIFO_DEPTH = 4
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [WIDTH-1:0]     in_a,
    input  wire [WIDTH-1:0]     in_b,
    input  wire [WIDTH:0]       i_expected,
    input  wire [WIDTH:0]       i_epsilon,
    input  wire                 i_calibration_done,
    output wire                 o_valid,
    input  wire                 o_ready,
    output wire [WIDTH:0]       o_epsilon,
    output wire                 o_within,
    output wire                 o_exact_mismatch,
    output wire [$clog2(FIFO_DEPTH+1)-1:0] queued_count_o,
    output wire                 a_out_valid,
    output wire                 a_out_ready,
    output wire [WIDTH-1:0]     a_out_sum,
    output wire                 a_out_carry,
    output wire [WIDTH-1:0]     a_operand_a_o,
    output wire [WIDTH-1:0]     a_operand_b_o,
    output wire [WIDTH-1:0]     a_prefix_hold_o,
    output wire [WIDTH-1:0]     a_propagate_hold_o,
    output wire [WIDTH:0]       b_delta_reg_o,
    output wire [WIDTH:0]       b_expected_reg_o,
    output wire [WIDTH:0]       b_observed_reg_o
);
    localparam integer COUNT_W = WIDTH + 1;
    localparam integer PTR_W = (FIFO_DEPTH > 1) ? $clog2(FIFO_DEPTH) : 1;
    localparam integer OCC_W = $clog2(FIFO_DEPTH + 1);
    localparam [WIDTH:0] MAX_TOTAL = {{WIDTH{1'b1}}, 1'b0};

    // Capture the expected length and tolerance when accepting each result.
    reg [COUNT_W-1:0] q_observed [0:FIFO_DEPTH-1];
    reg [COUNT_W-1:0] q_expected [0:FIFO_DEPTH-1];
    reg [COUNT_W-1:0] q_epsilon [0:FIFO_DEPTH-1];
    reg [PTR_W-1:0] q_read, q_write;
    reg [OCC_W-1:0] q_count;
    wire b_i_valid, b_i_ready;
    wire q_push, q_pop;
    integer k;

    assign queued_count_o = q_count;
    assign b_i_valid = (q_count != 0);
    assign q_pop = b_i_valid && b_i_ready;
    // A full queue may replace its departing head without a throughput bubble.
    assign a_out_ready = (q_count < FIFO_DEPTH) || q_pop;
    assign q_push = a_out_valid && a_out_ready;

    sklansky_result_channel #(.WIDTH(WIDTH)) adder (
        .clk(clk), .in_valid(in_valid), .in_ready(in_ready),
        .in_a(in_a), .in_b(in_b),
        .out_valid(a_out_valid), .out_ready(a_out_ready),
        .out_sum(a_out_sum), .out_carry(a_out_carry),
        .operand_a_o(a_operand_a_o), .operand_b_o(a_operand_b_o),
        .prefix_hold_o(a_prefix_hold_o),
        .propagate_hold_o(a_propagate_hold_o)
    );

    dma_completion_tolerance #(.DATA_W(COUNT_W)) comparator (
        .clk(clk), .i_valid(b_i_valid), .i_ready(b_i_ready),
        .i_observed(q_observed[q_read]),
        .i_expected(q_expected[q_read]),
        .i_epsilon(q_epsilon[q_read]),
        .i_calibration_done(i_calibration_done),
        .o_valid(o_valid), .o_ready(o_ready), .o_epsilon(o_epsilon),
        .o_within(o_within), .o_exact_mismatch(o_exact_mismatch),
        .delta_reg_o(b_delta_reg_o),
        .expected_reg_o(b_expected_reg_o),
        .observed_reg_o(b_observed_reg_o)
    );

    initial begin
        q_read = {PTR_W{1'b0}};
        q_write = {PTR_W{1'b0}};
        q_count = {OCC_W{1'b0}};
        for (k = 0; k < FIFO_DEPTH; k = k + 1) begin
            q_observed[k] = {COUNT_W{1'b0}};
            q_expected[k] = {COUNT_W{1'b0}};
            q_epsilon[k] = {COUNT_W{1'b0}};
        end
    end

    always @(posedge clk) begin
        if (q_push) begin
            q_observed[q_write] <= {a_out_carry, a_out_sum};
            q_expected[q_write] <= i_expected;
            q_epsilon[q_write] <= i_epsilon;
            if (q_write == FIFO_DEPTH-1)
                q_write <= {PTR_W{1'b0}};
            else
                q_write <= q_write + 1'b1;
        end
        if (q_pop) begin
            if (q_read == FIFO_DEPTH-1)
                q_read <= {PTR_W{1'b0}};
            else
                q_read <= q_read + 1'b1;
        end
        case ({q_push, q_pop})
            2'b10: q_count <= q_count + 1'b1;
            2'b01: q_count <= q_count - 1'b1;
            default: q_count <= q_count;
        endcase
    end

    always @(posedge clk) begin
        if (b_expected_reg_o <= MAX_TOTAL)
            assert (b_delta_reg_o <=
                ((b_expected_reg_o > (MAX_TOTAL - b_expected_reg_o))
                    ? b_expected_reg_o : (MAX_TOTAL - b_expected_reg_o)));
    end
endmodule

module duty_cycle_corrector #(
    parameter integer WORD_W = 64
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_high_ticks,
    input  wire [WORD_W-1:0]     in_low_ticks,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [WORD_W-1:0]     out_high_ticks,
    output reg  [WORD_W-1:0]     applied_high_time,
    input  wire                  peer_valid,
    output wire                  peer_ready,
    input  wire [WORD_W-1:0]     peer_high_ticks,
    input  wire [WORD_W-1:0]     peer_low_ticks,
    output reg                   peer_active
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] HALF_SCALE = {1'b1, {(WORD_W-1){1'b0}}};
    localparam integer CHANNELS = 2, PEER_DEPTH = 4;
    localparam integer PEER_PTR_W = $clog2(PEER_DEPTH), PEER_COUNT_W = $clog2(PEER_DEPTH+1);

    reg [WORD_W-1:0] high_shadow;
    reg [WORD_W-1:0] low_shadow;
    reg [WORD_W-1:0] correction_code;
    reg pending;
    reg armed;
    reg pv;
    reg [WORD_W-1:0] peer_high_q [0:PEER_DEPTH-1], peer_low_q [0:PEER_DEPTH-1];
    reg [PEER_PTR_W-1:0] peer_rd, peer_wr;
    reg [PEER_COUNT_W-1:0] peer_count;
    integer peer_idx;
    wire [CHANNELS-1:0] lane_valid = {peer_active, pending};

    // The code is a two's-complement adjustment in high-time units.
    // Halving each measured interval avoids overflowing the imbalance.
    wire [WORD_W-1:0] shadow_half_imbalance =
        (high_shadow >> ONE) - (low_shadow >> ONE);
    wire [WORD_W-1:0] reference_high =
        HALF_SCALE - shadow_half_imbalance;

    assign in_ready = !(|lane_valid);
    assign out_valid = |lane_valid;
    assign out_high_ticks = HALF_SCALE + correction_code;
    assign peer_ready = peer_count < PEER_DEPTH;

    wire take_measurement = in_valid && in_ready;
    wire apply_correction = pending && out_ready;
    wire enqueue_peer = peer_valid && peer_ready;
    wire finish_peer = peer_active && out_ready;
    wire start_peer = in_ready && !in_valid && (peer_count != 0);

    initial begin
        high_shadow = ZERO;
        low_shadow = ZERO;
        correction_code = ZERO;
        applied_high_time = HALF_SCALE;
        pending = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
        peer_rd = 0; peer_wr = 0;
        peer_count = 0; peer_active = 1'b0;
        for (peer_idx = 0; peer_idx < PEER_DEPTH; peer_idx = peer_idx + 1)
            {peer_high_q[peer_idx], peer_low_q[peer_idx]} = {ZERO, ZERO};
    end

    always @(posedge clk) begin
        if (take_measurement || start_peer)
            correction_code <= ((start_peer ? peer_low_q[peer_rd] : in_low_ticks) >> ONE)
                             - ((start_peer ? peer_high_q[peer_rd] : in_high_ticks) >> ONE);
        if (enqueue_peer) begin
            {peer_high_q[peer_wr], peer_low_q[peer_wr]} <= {peer_high_ticks, peer_low_ticks};
            peer_wr <= peer_wr + 1'b1;
        end
        if (start_peer || finish_peer) peer_active <= start_peer;
        if (finish_peer) peer_rd <= peer_rd + 1'b1;
        case ({enqueue_peer, finish_peer})
            2'b10: peer_count <= peer_count + 1'b1;
            2'b01: peer_count <= peer_count - 1'b1;
        endcase
        if (take_measurement) begin
            high_shadow <= in_high_ticks;
            low_shadow <= in_low_ticks;
            pending <= 1'b1;
            // Q: the first accepted duty-cycle measurement.
            armed <= 1'b1;
        end

        if (apply_correction) begin
            applied_high_time <= out_high_ticks;
            pending <= 1'b0;
        end

        // No checker state changes during an idle cycle either.
        if (take_measurement || apply_correction)
            pv <= 1'b1;
    end
    always @(posedge clk)
        if (peer_active && out_ready)
            assert (!pending && (out_high_ticks == HALF_SCALE - ((peer_high_q[peer_rd] >> ONE) - (peer_low_q[peer_rd] >> ONE))));

    // Once armed, a committed setting must agree with the measurement
    // shadows that already existed in the previous cycle.
    always @(posedge clk)
        if (pv && armed && !pending)
            assert (applied_high_time == $past(reference_high));
endmodule

module i2c_stretch_watchdog #(
    parameter integer WIDTH = 32,
    parameter integer PERIOD = 4,
    parameter integer FILTER = 4,
    parameter [WIDTH-1:0] RESET_BUDGET = 32'd8
) (
    input wire clk, rst_n, ce, pending, scl_in, config_valid,
    input wire [WIDTH-1:0] budget, config_budget,
    output wire debit,
    output reg [WIDTH-1:0] remaining,
    output reg [$clog2(PERIOD)-1:0] phase,
    output reg [$clog2(FILTER)-1:0] qualification
);
    initial begin
        remaining = RESET_BUDGET;
        phase = 0;
        qualification = 0;
    end
    assign debit = ce && pending && !scl_in &&
                   (phase == PERIOD-1) && (qualification == FILTER-1);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            remaining <= RESET_BUDGET;
            phase <= 0;
            qualification <= 0;
        end else if (ce) begin
            if (!pending) begin
                remaining <= config_valid ? config_budget : budget;
                phase <= 0;
                qualification <= 0;
            end else if (!scl_in) begin
                if (phase == PERIOD-1) begin
                    phase <= 0;
                    if (qualification != FILTER-1)
                        qualification <= qualification + 1'b1;
                    if (debit && remaining != {WIDTH{1'b0}})
                        remaining <= remaining - {{(WIDTH-1){1'b0}}, 1'b1};
                end else
                    phase <= phase + 1'b1;
            end
        end
    end
endmodule

module i2c_stretch_handler #(
    parameter integer COUNTER_WIDTH = 32,
    parameter [COUNTER_WIDTH-1:0] RESET_MAX_STRETCH = 32'd8,
    parameter integer WATCHDOG_PERIOD = 4, WATCHDOG_FILTER = 4
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire request_high,
    input wire scl_in,
    input wire config_valid,
    input wire [COUNTER_WIDTH-1:0] config_max_stretch,
    output wire scl_release,
    output wire high_phase_done,
    output reg high_pending,
    output reg stretching_active,
    output reg stretch_timeout,
    output reg [COUNTER_WIDTH-1:0] stretch_duration,
    output reg [COUNTER_WIDTH-1:0] max_stretch,
    output wire config_ready,
    output wire request_ready,
    output wire [COUNTER_WIDTH-1:0] watchdog_remaining,
    output wire [$clog2(WATCHDOG_PERIOD)-1:0] watchdog_phase,
    output wire [$clog2(WATCHDOG_FILTER)-1:0] watchdog_qualification
);
    localparam [COUNTER_WIDTH-1:0] COUNT_ZERO = {COUNTER_WIDTH{1'b0}};
    localparam [COUNTER_WIDTH-1:0] COUNT_ONE = {{(COUNTER_WIDTH-1){1'b0}}, 1'b1};
    reg past_valid;
    wire watchdog_debit;
    i2c_stretch_watchdog #(
        .WIDTH(COUNTER_WIDTH), .PERIOD(WATCHDOG_PERIOD),
        .FILTER(WATCHDOG_FILTER), .RESET_BUDGET(RESET_MAX_STRETCH)
    ) budget_timer (
        .clk(clk), .rst_n(rst_n), .ce(i_ce), .pending(high_pending),
        .scl_in(scl_in), .config_valid(config_valid),
        .budget(max_stretch), .config_budget(config_max_stretch),
        .debit(watchdog_debit), .remaining(watchdog_remaining),
        .phase(watchdog_phase), .qualification(watchdog_qualification)
    );

    initial begin
        high_pending = 1'b0;
        stretching_active = 1'b0;
        stretch_timeout = 1'b0;
        stretch_duration = COUNT_ZERO;
        max_stretch = RESET_MAX_STRETCH;
        past_valid = 1'b0;
    end

    // Release the open-drain SCL output throughout the pending high phase.
    // Even a timeout does not end that phase before the slave releases SCL.
    assign scl_release = high_pending;
    assign high_phase_done = high_pending && scl_in;
    assign config_ready = i_ce && !high_pending;
    assign request_ready = i_ce && !high_pending && !config_valid;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            high_pending <= 1'b0;
            stretching_active <= 1'b0;
            stretch_timeout <= 1'b0;
            stretch_duration <= COUNT_ZERO;
            max_stretch <= RESET_MAX_STRETCH;
            past_valid <= 1'b0;
        end else if (i_ce) begin
            past_valid <= 1'b1;
            if (!high_pending) begin
                stretching_active <= 1'b0;
                if (config_valid) begin
                    max_stretch <= config_max_stretch;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end else if (request_high) begin
                    high_pending <= 1'b1;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end
            end else if (scl_in) begin
                high_pending <= 1'b0;
                stretching_active <= 1'b0;
            end else begin
                stretching_active <= 1'b1;
                // Saturate the duration at the programmed stretch budget.
                if (watchdog_debit && (watchdog_remaining != COUNT_ZERO))
                    stretch_duration <= stretch_duration + COUNT_ONE;
                if (watchdog_debit && (watchdog_remaining <= COUNT_ONE))
                    stretch_timeout <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (past_valid && $rose(stretch_timeout))
            assert (stretch_duration == max_stretch);
endmodule

module prescaler_event_queue #(
    parameter [63:0] P = 64'd4,
parameter [63:0] DEPTH = 64'd32,
parameter PREFETCH_DEPTH = 4
) (
    input  wire        clk,
    input  wire        i_pulse_valid,
    output wire        o_pulse_ready,
    input  wire        i_mode,
    output wire        o_valid,
    input  wire        i_out_ready,
output wire [63:0] o_data,
output wire [$clog2(PREFETCH_DEPTH):0] o_prefetch_level
);
    // Supported modulus settings: 3 <= P <= 16.
    // First accepted pulse: ARM and sample mode.
    // Second accepted pulse: START.
    // Pulse P or P+1: FINISH and enqueue its event record.
    localparam [63:0] IDLE  = 64'd0;
    localparam [63:0] ARMED = 64'd1;
    localparam [63:0] RUN   = 64'd2;

// The read-ahead FIFO supports power-of-two depths, normally 4 or 8.
localparam PREFETCH_ADDR_W = $clog2(PREFETCH_DEPTH);
localparam EVENT_ADDR_W = $clog2(DEPTH);

    reg [63:0] phase;
    reg [63:0] pulse_count;
    reg mode_q;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    reg [63:0] event_mem [0:DEPTH-1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] fifo_count;

    wire [63:0] modulus;
    wire pulse_fire;
    wire finish_fire;
    wire pop_fire;
    wire [DEPTH-1:0] filled;

reg [63:0] prefetch_mem [0:PREFETCH_DEPTH-1];
reg [PREFETCH_ADDR_W:0] prefetch_rd_ptr;
reg [PREFETCH_ADDR_W:0] prefetch_wr_ptr;
reg [EVENT_ADDR_W-1:0] fetch_addr;
reg read_valid;
reg [63:0] read_data;
reg head_valid;
reg [63:0] head_data;

wire [PREFETCH_ADDR_W-1:0] prefetch_rd_index;
wire [PREFETCH_ADDR_W-1:0] prefetch_wr_index;
wire [PREFETCH_ADDR_W:0] prefetch_used;
wire [PREFETCH_ADDR_W:0] prefetch_level;
wire prefetch_empty;
wire prefetch_full;
wire fetch_available;
wire read_ready;
wire fetch_fire;
wire enqueue_fire;
wire head_ready;
wire refill_fire;

    assign modulus = mode_q ? P + 64'd1 : P;
    assign o_pulse_ready = fifo_count < DEPTH;
    assign pulse_fire = i_pulse_valid && o_pulse_ready;
    assign finish_fire = pulse_fire && (phase == RUN)
                         && (pulse_count == modulus - 64'd1);
assign o_valid = head_valid;
assign o_data = head_data;
    assign pop_fire = o_valid && i_out_ready;

assign prefetch_rd_index =
    prefetch_rd_ptr[PREFETCH_ADDR_W-1:0];
assign prefetch_wr_index =
    prefetch_wr_ptr[PREFETCH_ADDR_W-1:0];
assign prefetch_used = prefetch_wr_ptr - prefetch_rd_ptr;
assign prefetch_level = prefetch_used
    + {{PREFETCH_ADDR_W{1'b0}}, head_valid}
    + {{PREFETCH_ADDR_W{1'b0}}, read_valid};
assign prefetch_empty = prefetch_wr_ptr == prefetch_rd_ptr;
assign prefetch_full =
    (prefetch_wr_ptr[PREFETCH_ADDR_W] != prefetch_rd_ptr[PREFETCH_ADDR_W])
    && (prefetch_wr_index == prefetch_rd_index);
assign fetch_available = prefetch_level < fifo_count;
assign read_ready = !read_valid || !prefetch_full;
assign fetch_fire = fetch_available && read_ready;
assign enqueue_fire = read_valid && !prefetch_full;
assign head_ready = !head_valid || i_out_ready;
assign refill_fire = !prefetch_empty && head_ready;
assign o_prefetch_level = prefetch_level;

    // Filled slots are the circular interval starting at rd_ptr.
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupied_slots
            localparam [63:0] ENTRY = g;
            assign filled[g] = ((ENTRY >= rd_ptr)
                              ? (ENTRY - rd_ptr)
                              : (ENTRY + DEPTH - rd_ptr)) < fifo_count;
        end
    endgenerate

    integer j;
    initial begin
        phase = IDLE;
        pulse_count = 64'd0;
        mode_q = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        scope_armed = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        fifo_count = 64'd0;
prefetch_rd_ptr = {(PREFETCH_ADDR_W+1){1'b0}};
prefetch_wr_ptr = {(PREFETCH_ADDR_W+1){1'b0}};
fetch_addr = {EVENT_ADDR_W{1'b0}};
read_valid = 1'b0;
read_data = 64'd0;
head_valid = 1'b0;
head_data = 64'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            event_mem[j] = 64'd0;
for (j = 0; j < PREFETCH_DEPTH; j = j + 1)
    prefetch_mem[j] = 64'd0;
    end

    always @(posedge clk) begin
        if (pulse_fire) begin
            case (phase)
                IDLE: begin
                    // Q is the ARM event; its scope latch never clears.
                    scope_armed <= 1'b1;
                    mode_q <= i_mode;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    pulse_count <= 64'd1;
                    phase <= ARMED;
                end
                ARMED: begin
                    start_seen <= 1'b1;
                    pulse_count <= 64'd2;
                    phase <= RUN;
                end
                RUN: begin
                    if (finish_fire) begin
                        pulse_count <= 64'd0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= IDLE;
                    end else begin
                        pulse_count <= pulse_count + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    pulse_count <= 64'd0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end

        if (finish_fire) begin
            // Record: ARM witness, START witness, sampled mode,
            // and the number of accepted pulses in this division.
            event_mem[wr_ptr] <= (pulse_count + 64'd1)
                | (arm_seen ? 64'h8000000000000000 : 64'd0)
                | (start_seen ? 64'h4000000000000000 : 64'd0)
                | (mode_q ? 64'h2000000000000000 : 64'd0);
            wr_ptr <= (wr_ptr == DEPTH - 64'd1)
                    ? 64'd0 : wr_ptr + 64'd1;
        end
        if (pop_fire)
            rd_ptr <= (rd_ptr == DEPTH - 64'd1)
                    ? 64'd0 : rd_ptr + 64'd1;

        case ({finish_fire, pop_fire})
            2'b10: fifo_count <= fifo_count + 64'd1;
            2'b01: fifo_count <= fifo_count - 64'd1;
            default: begin end
        endcase
    end

// A stalled read response keeps its data and reserves its backing slot.
always @(posedge clk) begin
    if (read_ready)
        read_valid <= fetch_fire;
    if (fetch_fire) begin
        read_data <= event_mem[fetch_addr];
        if (fetch_addr == DEPTH - 64'd1)
            fetch_addr <= {EVENT_ADDR_W{1'b0}};
        else
            fetch_addr <= fetch_addr + 1'b1;
    end
end

always @(posedge clk) begin
    if (enqueue_fire) begin
        prefetch_mem[prefetch_wr_index] <= read_data;
        prefetch_wr_ptr <= prefetch_wr_ptr + 1'b1;
    end
    if (refill_fire)
        prefetch_rd_ptr <= prefetch_rd_ptr + 1'b1;
end

// Backing slots are released by pop_fire, not by speculative reads.
always @(posedge clk) begin
    if (head_ready) begin
        head_valid <= refill_fire;
        if (refill_fire)
            head_data <= prefetch_mem[prefetch_rd_index];
    end
end

    // After Q: START requires ARM, and every observable FINISH
    // must carry both earlier event witnesses.
    always @(posedge clk)
        if (scope_armed)
            assert ((!start_seen || arm_seen)
                    && (!o_valid || (o_data[63] && o_data[62])));
endmodule

module pixel_pulse_pending #(
    parameter integer COUNT_W = 32
) (
    input wire clk,
    input wire i_ce,
    input wire i_pixel_pulse,
    input wire i_dispatch,
    input wire i_slow_tick,
    input wire i_load_limit,
    input wire [COUNT_W-1:0] i_limit,
    input wire i_begin_tile,
    input wire i_end_tile,
input wire i_peer_pixel_pulse,
output reg slow_pixel_pulse,
output wire pixel_ready,
output wire peer_ready,
output reg peer_slow_pixel_pulse
);
    localparam [COUNT_W-1:0] ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
localparam integer CHANNELS = 2, PEER_DEPTH = 7;
localparam integer PEER_W = $clog2(PEER_DEPTH + 1);

    reg [COUNT_W-1:0] pending;
    reg [COUNT_W-1:0] outstanding;
    reg [COUNT_W-1:0] pulse_limit;
    reg req_toggle;
    reg ack_toggle;
    reg window_open;
    reg pv;
reg peer_valid [0:PEER_DEPTH-1];
reg [PEER_W-1:0] peer_outstanding;
reg [$clog2(CHANNELS)-1:0] flight_lane;
integer k;

    wire in_flight = (req_toggle != ack_toggle);
    wire accept_pulse = i_pixel_pulse && (outstanding < pulse_limit);
    wire launch_request = i_dispatch && !in_flight && (pending != ZERO);
wire retire_request = i_slow_tick && in_flight && (flight_lane == 1'b0);
wire peer_launch = i_dispatch && !in_flight && (pending == ZERO) && peer_valid[PEER_DEPTH-1];
wire peer_shift = !peer_valid[PEER_DEPTH-1] || peer_launch;
wire peer_retire = i_slow_tick && in_flight && (flight_lane == 1'b1);
wire peer_accept = i_peer_pixel_pulse && peer_ready;
assign pixel_ready = i_ce && (outstanding < pulse_limit);
assign peer_ready = i_ce && peer_shift && (peer_outstanding < PEER_DEPTH);

    initial begin
        pending = ZERO;
        outstanding = ZERO;
        pulse_limit = {COUNT_W{1'b1}};
        req_toggle = 1'b0;
        ack_toggle = 1'b0;
        window_open = 1'b0;
        slow_pixel_pulse = 1'b0;
        pv = 1'b0;
for (k = 0; k < PEER_DEPTH; k = k + 1) peer_valid[k] = 1'b0;
peer_outstanding = 0;
flight_lane = 0;
peer_slow_pixel_pulse = 1'b0;
    end

    // i_slow_tick models an edge of the slower receiving domain.
    // Requests remain outstanding until that domain acknowledges them.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            if (i_load_limit)
                pulse_limit <= i_limit;

            if (i_end_tile)
                window_open <= 1'b0;
            else if (i_begin_tile)
                window_open <= 1'b1;

            case ({accept_pulse, launch_request})
                2'b10: pending <= pending + ONE;
                2'b01: pending <= pending - ONE;
                default: pending <= pending;
            endcase

            case ({accept_pulse, retire_request})
                2'b10: outstanding <= outstanding + ONE;
                2'b01: outstanding <= outstanding - ONE;
                default: outstanding <= outstanding;
            endcase
if (peer_shift) begin
    for (k = PEER_DEPTH-1; k > 0; k = k - 1)
        peer_valid[k] <= peer_valid[k-1];
    peer_valid[0] <= peer_accept;
end
case ({peer_accept, peer_retire})
    2'b10: peer_outstanding <= peer_outstanding + 1'b1;
    2'b01: peer_outstanding <= peer_outstanding - 1'b1;
    default: peer_outstanding <= peer_outstanding;
endcase

if (launch_request || peer_launch)
                req_toggle <= !req_toggle;
if (launch_request || peer_launch)
    flight_lane <= peer_launch;

if (retire_request || peer_retire)
                ack_toggle <= req_toggle;

            slow_pixel_pulse <= retire_request;
peer_slow_pixel_pulse <= peer_retire;
        end
    end

    // The registered pulse reports the preceding enabled edge's delivery.
    // Inside the previous tile window, delivery and an empty work ledger
    // must never have occurred together on that edge.
    always @(posedge clk) begin
        if (pv && $past(window_open) && $past(i_ce))
            assert (!(slow_pixel_pulse && ($past(outstanding) == ZERO)));
    end
always @(posedge clk) begin
    if (pv && $past(i_ce))
        assert (!(peer_slow_pixel_pulse && ($past(peer_outstanding) == 0)));
end
endmodule

module forwarded_sample_buffer #(
    parameter integer unsigned DEPTH = 32'd24,
    parameter integer unsigned DATA_WIDTH = 32'd32,
    parameter integer unsigned INDEX_WIDTH = 32'd32
) (
    input  wire clk,
    input  wire forwarded_clk,
    input  wire i_ce,
    input  wire in_valid,
    output wire in_ready,
    input  wire [DATA_WIDTH-32'd1:0] in_data,
    output wire out_valid,
    input  wire out_ready,
    output logic [DATA_WIDTH-32'd1:0] out_data,
    output reg [31:0] debug_status
);
    typedef enum logic [1:0] {
        RX_IDLE  = 2'd0,
        RX_STORE = 2'd1,
        RX_WAIT  = 2'd2
    } rx_state_t;

    typedef enum logic [1:0] {
        TX_IDLE  = 2'd0,
        TX_VALID = 2'd1
    } tx_state_t;

    localparam logic [INDEX_WIDTH-32'd1:0] LAST_INDEX =
        INDEX_WIDTH'(DEPTH - 32'd1);

    rx_state_t rx_state;
    tx_state_t tx_state;
    logic [DATA_WIDTH-32'd1:0] capture_data;
    logic [DATA_WIDTH-32'd1:0] sample_buffer [0:DEPTH-32'd1];
    logic [INDEX_WIDTH-32'd1:0] write_index;
    logic [INDEX_WIDTH-32'd1:0] read_index;
    logic request_toggle;
    logic acknowledge_toggle;
    logic past_valid;
    logic [7:0] dbg_transfer_count;
    logic [7:0] dbg_stall_cycles;
    logic [7:0] dbg_stall_run;
    logic [7:0] dbg_stall_peak;
    logic [7:0] dbg_idle_run;
    logic dbg_stall_alarm;
    logic dbg_idle_alarm;

    wire [INDEX_WIDTH-32'd1:0] next_write_index =
        (write_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        write_index + INDEX_WIDTH'(32'd1);
    wire [INDEX_WIDTH-32'd1:0] next_read_index =
        (read_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        read_index + INDEX_WIDTH'(32'd1);

    assign in_ready = i_ce && (rx_state == RX_IDLE);
    assign out_valid = (tx_state == TX_VALID);

    initial begin
        rx_state = RX_IDLE;
        tx_state = TX_IDLE;
        capture_data = {DATA_WIDTH{1'b0}};
        out_data = {DATA_WIDTH{1'b0}};
        write_index = {INDEX_WIDTH{1'b0}};
        read_index = {INDEX_WIDTH{1'b0}};
        request_toggle = 1'b0;
        acknowledge_toggle = 1'b0;
        past_valid = 1'b0;
        for (integer k = 32'd0; k < DEPTH; k = k + 32'd1)
            sample_buffer[k] = {DATA_WIDTH{1'b0}};
    end
    initial begin
        dbg_transfer_count = 8'd0;
        dbg_stall_cycles = 8'd0;
        dbg_stall_run = 8'd0;
        dbg_stall_peak = 8'd0;
        dbg_idle_run = 8'd0;
        dbg_stall_alarm = 1'b0;
        dbg_idle_alarm = 1'b0;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (out_valid && out_ready) begin
                if (dbg_transfer_count != 8'hff)
                    dbg_transfer_count <= dbg_transfer_count + 8'd1;
            end
            if (out_valid && !out_ready) begin
                if (dbg_stall_cycles != 8'hff)
                    dbg_stall_cycles <= dbg_stall_cycles + 8'd1;
                if (dbg_stall_run != 8'hff)
                    dbg_stall_run <= dbg_stall_run + 8'd1;
                if ((dbg_stall_run >= dbg_stall_peak) && (dbg_stall_run != 8'hff))
                    dbg_stall_peak <= dbg_stall_run + 8'd1;
                if (dbg_stall_run >= 8'd63)
                    dbg_stall_alarm <= 1'b1;
            end else begin
                dbg_stall_run <= 8'd0;
            end
            if (!out_valid) begin
                if (dbg_idle_run != 8'hff)
                    dbg_idle_run <= dbg_idle_run + 8'd1;
                if (dbg_idle_run >= 8'd127)
                    dbg_idle_alarm <= 1'b1;
            end else begin
                dbg_idle_run <= 8'd0;
            end
            debug_status <= {dbg_stall_alarm, dbg_idle_alarm, out_valid, out_ready,
                             dbg_idle_run[3:0], dbg_stall_peak,
                             dbg_stall_cycles, dbg_transfer_count};
        end
    end

    // Forwarded-clock capture followed by a write into the rotating buffer.
    // One outstanding transfer keeps the bundled sample and its slot stable
    // until the local-clock consumer acknowledges it.
    always @(posedge forwarded_clk) begin
        if (i_ce) begin
            case (rx_state)
                RX_IDLE: begin
                    if (in_valid && in_ready) begin
                        capture_data <= in_data;
                        rx_state <= RX_STORE;
                    end
                end
                RX_STORE: begin
                    sample_buffer[write_index] <= capture_data;
                    request_toggle <= !request_toggle;
                    rx_state <= RX_WAIT;
                end
                RX_WAIT: begin
                    if (request_toggle == acknowledge_toggle) begin
                        write_index <= next_write_index;
                        rx_state <= RX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    // The other port of the buffer is read in the local-clock domain.
    // Output data and valid remain held throughout back-pressure.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            case (tx_state)
                TX_IDLE: begin
                    if (request_toggle != acknowledge_toggle) begin
                        out_data <= sample_buffer[read_index];
                        tx_state <= TX_VALID;
                    end
                end
                TX_VALID: begin
                    if (out_valid && out_ready) begin
                        acknowledge_toggle <= request_toggle;
                        read_index <= next_read_index;
                        tx_state <= TX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    always @(posedge clk) begin
        if (past_valid && $rose(out_valid))
            assert (out_data == capture_data);
    end
endmodule

module timestamp_burst_buffer #(
    parameter integer WORD_W = 64,
    parameter integer MAX_BEATS = 8,
    parameter integer DEPTH = 4
) (
    input wire clk,
    input wire i_ce,
    input wire cmd_valid,
    output wire cmd_ready,
    input wire [WORD_W-1:0] cmd_stamp,
    input wire [WORD_W-1:0] cmd_len,
    output wire data_valid,
    input wire data_ready,
    output wire [WORD_W-1:0] data,
    output reg [$clog2(DEPTH+1)-1:0] count,
    output reg [$clog2(MAX_BEATS+1)-1:0] left,
    output reg [WORD_W-1:0] next_stamp,
    output wire [DEPTH*WORD_W-1:0] contents
);
    localparam integer CW = $clog2(DEPTH+1);
    localparam integer LW = $clog2(MAX_BEATS+1);
    localparam logic [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam logic [WORD_W-1:0] ONE = WORD_W'(32'd1);
    reg [WORD_W-1:0] words [0:DEPTH-1];
    wire pop = i_ce && data_valid && data_ready;
    wire push = i_ce && (left != LW'(0)) &&
                ((count < CW'(DEPTH)) || pop);
    integer j;
    assign cmd_ready = (left == LW'(0)) && (count == CW'(0));
    assign data_valid = (count != CW'(0));
    assign data = words[0];
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : export_words
            assign contents[g*WORD_W +: WORD_W] = words[g];
        end
    endgenerate
    initial begin
        count = CW'(0);
        left = LW'(0);
        next_stamp = ZERO;
        for (j = 0; j < DEPTH; j = j + 1)
            words[j] = ZERO;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (cmd_valid && cmd_ready) begin
                left <= LW'(cmd_len) + LW'(1);
                next_stamp <= cmd_stamp;
            end else begin
                if (pop) begin
                    for (j = 0; j < DEPTH-1; j = j + 1)
                        words[j] <= words[j+1];
                end
                if (push) begin
                    for (j = 0; j < DEPTH; j = j + 1)
                        if (count == CW'(j) + CW'(pop))
                            words[j] <= next_stamp;
                    next_stamp <= next_stamp + ONE;
                    left <= left - LW'(1);
                end
                count <= count + CW'(push) - CW'(pop);
            end
        end
    end
endmodule

module axi_timestamp_reader #(
    parameter integer WORD_W = 64,
    parameter integer MAX_BEATS = 8
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  arvalid,
    output wire                  arready,
    input  wire [WORD_W-1:0]     araddr,
    input  wire [WORD_W-1:0]     arlen,
    input  wire [2:0]            arsize,
    input  wire [1:0]            arburst,
    output wire                  rvalid,
    input  wire                  rready,
    output logic [WORD_W-1:0]    rdata,
    output logic [1:0]           rresp,
    output wire                  rlast
);
    localparam logic [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam logic [WORD_W-1:0] ONE = WORD_W'(32'd1);
    localparam logic [WORD_W-1:0] MAX_LEN = WORD_W'(MAX_BEATS) - ONE;
    localparam logic [WORD_W-1:0] ADDR_MASK = WORD_W'(WORD_W / 32'd8) - ONE;
    localparam logic [2:0] BEAT_SIZE = 3'($clog2(WORD_W / 32'd8));
    localparam logic [1:0] RESP_OKAY = 2'b00;
    localparam logic [1:0] RESP_SLVERR = 2'b10;
    localparam integer SEQ_DEPTH = 4;
    localparam integer SEQ_CW = $clog2(SEQ_DEPTH+1);
    localparam integer SEQ_LW = $clog2(MAX_BEATS+1);

    typedef enum logic [1:0] {
        IDLE  = 2'b00,
        FETCH = 2'b01,
        SEND  = 2'b10
    } state_t;
    state_t state;

    logic [WORD_W-1:0] timestamp_counter;
    logic [WORD_W-1:0] captured_addr;
    logic [WORD_W-1:0] captured_len;
    logic [2:0] captured_size;
    logic [1:0] captured_burst;
    logic [WORD_W-1:0] beat_index;
    logic [WORD_W-1:0] base_stamp;

    // Acceptance-history shadow and the acceptance-to-completion window.
    logic [WORD_W-1:0] request_stamp;
    logic request_seen;
    logic window_open;
    wire seq_cmd_ready, seq_valid;
    wire [WORD_W-1:0] seq_data, seq_next;
    wire [SEQ_CW-1:0] seq_count;
    wire [SEQ_LW-1:0] seq_left;
    wire [SEQ_DEPTH*WORD_W-1:0] seq_words;
    timestamp_burst_buffer #(
        .WORD_W(WORD_W), .MAX_BEATS(MAX_BEATS), .DEPTH(SEQ_DEPTH)
    ) sequence_buffer (
        .clk(clk), .i_ce(i_ce),
        .cmd_valid(arvalid && (state == IDLE) && (arlen <= MAX_LEN)),
        .cmd_ready(seq_cmd_ready), .cmd_stamp(timestamp_counter),
        .cmd_len(arlen), .data_valid(seq_valid),
        .data_ready(state == FETCH), .data(seq_data),
        .count(seq_count), .left(seq_left),
        .next_stamp(seq_next), .contents(seq_words)
    );


    // The clock enable gates both interface transfers and every state update.
    assign arready = i_ce && (state == IDLE) && (arlen <= MAX_LEN) && seq_cmd_ready;
    assign rvalid = i_ce && (state == SEND);
    assign rlast = (state == SEND) && (beat_index == captured_len);

    initial begin
        state = IDLE;
        timestamp_counter = ZERO;
        captured_addr = ZERO;
        captured_len = ZERO;
        captured_size = BEAT_SIZE;
        captured_burst = 2'b01;
        beat_index = ZERO;
        base_stamp = ZERO;
        request_stamp = ZERO;
        request_seen = 1'b0;
        window_open = 1'b0;
        rdata = ZERO;
        rresp = RESP_OKAY;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            timestamp_counter <= timestamp_counter + ONE;
            case (state)
                IDLE: begin
                    if (arvalid && arready) begin
                        captured_addr <= araddr;
                        captured_len <= arlen;
                        captured_size <= arsize;
                        captured_burst <= arburst;
                        beat_index <= ZERO;
                        base_stamp <= timestamp_counter;
                        request_stamp <= timestamp_counter;
                        request_seen <= 1'b1;
                        window_open <= 1'b1;
                        rresp <= (((araddr & ADDR_MASK) == ZERO) &&
                                  (arsize == BEAT_SIZE) &&
                                  (arburst == 2'b01)) ? RESP_OKAY : RESP_SLVERR;
                        state <= FETCH;
                    end
                end
                FETCH: begin
                    // Each burst returns a sequence based on its captured time.
                    if (seq_valid) begin
                        rdata <= seq_data;
                        state <= SEND;
                    end
                end
                SEND: begin
                    if (rready) begin
                        if (beat_index == captured_len) begin
                            window_open <= 1'b0;
                            request_seen <= 1'b0;
                            state <= IDLE;
                        end else begin
                            beat_index <= beat_index + ONE;
                            state <= FETCH;
                        end
                    end
                end
                default: begin
                    state <= IDLE;
                    window_open <= 1'b0;
                    request_seen <= 1'b0;
                end
            endcase
        end
    end

    // A prepared successful response must follow an address acceptance and
    // carry the timestamp sequence established by that earlier acceptance.
    always @(posedge clk)
        if (window_open && (state == SEND) && (rresp == RESP_OKAY))
            assert (request_seen && (rdata == request_stamp + beat_index));

    always @(posedge clk)
        if ((state == SEND) && (beat_index == captured_len))
            assert ((seq_count == SEQ_CW'(0)) && (seq_left == SEQ_LW'(0)));
endmodule

module masked_pipe_dispatch #(
    parameter integer DATA_W = 64,
    parameter integer CHANNELS = 16
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  write_mask,
    input  wire [DATA_W-1:0]     mask_data,
    input  wire                  dispatch,
    input  wire                  end_window,
    output reg  [DATA_W-1:0]     issued_count,
    output reg  [DATA_W-1:0]     last_index,
output reg                   last_valid,
output wire                  dispatch_ready,
output reg  [DATA_W-1:0]     issue_index,
output reg                   issue_valid,
output wire                  issue_fire
);
    // Supported configurations have 1 <= CHANNELS <= DATA_W.
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] CAPACITY = DATA_W'(CHANNELS);
    localparam [DATA_W-1:0] CHANNEL_BITS =
        {DATA_W{1'b1}} >> (DATA_W - CHANNELS);
localparam integer FIFO_DEPTH = 4;
localparam integer FIFO_AW = $clog2(FIFO_DEPTH);

    // Each channel initially has one pending notification.
    reg [DATA_W-1:0] pending;
    reg [DATA_W-1:0] sw_mask;
    reg before_window_end;
    reg past_valid;

    // Lowest numbered enabled request has highest priority.
    function automatic [DATA_W-1:0] priority_index(
        input [DATA_W-1:0] bits
    );
        integer j;
        begin
            priority_index = ZERO;
            for (j = CHANNELS - 1; j >= 0; j = j - 1)
                if (bits[j])
                    priority_index = DATA_W'(j);
        end
    endfunction
reg [DATA_W-1:0] fifo_index [0:FIFO_DEPTH-1];
reg [FIFO_AW:0] fifo_rd;
reg [FIFO_AW:0] fifo_wr;
wire [FIFO_AW:0] fifo_used = fifo_wr - fifo_rd;
wire fifo_empty = (fifo_wr == fifo_rd);
wire fifo_full = (fifo_wr[FIFO_AW] != fifo_rd[FIFO_AW]) &&
    (fifo_wr[FIFO_AW-1:0] == fifo_rd[FIFO_AW-1:0]);
reg [FIFO_DEPTH-1:0] fifo_live;
reg [DATA_W-1:0] reserved_channels;
integer f, s;

// Gather a burst, then release work when gathering stalls or ends.
wire retire_request = issue_valid &&
    (!dispatch || fifo_full || !last_valid || end_window);
assign dispatch_ready = ce && !write_mask &&
    !fifo_full && last_valid;
assign issue_fire = ce && retire_request;
wire fifo_push = dispatch && dispatch_ready;
wire fifo_pop = ce && !fifo_empty &&
    (!issue_valid || retire_request);
wire [FIFO_AW+1:0] dispatch_held = {1'b0, fifo_used} +
    {{(FIFO_AW+1){1'b0}}, issue_valid};

always @(*) begin
    reserved_channels = issue_valid ? (ONE << issue_index) : ZERO;
    for (f = 0; f < FIFO_DEPTH; f = f + 1) begin
        fifo_live[f] =
            FIFO_AW'(f - fifo_rd[FIFO_AW-1:0]) < fifo_used;
        if (fifo_live[f])
            reserved_channels = reserved_channels | (ONE << fifo_index[f]);
    end
end

wire [DATA_W-1:0] eligible = pending & sw_mask & ~reserved_channels;
    wire [DATA_W-1:0] encoded_index = priority_index(eligible);

    // Mask writes take priority over dispatch commands.
wire take = retire_request;
    wire [DATA_W-1:0] next_mask =
        write_mask ? (mask_data & CHANNEL_BITS) : sw_mask;
wire [DATA_W-1:0] next_reserved =
    (reserved_channels | (fifo_push ? (ONE << last_index) : ZERO)) &
    ~(take ? (ONE << issue_index) : ZERO);
    wire [DATA_W-1:0] next_pending =
take ? (pending & ~(ONE << issue_index)) : pending;
wire [DATA_W-1:0] next_eligible = next_pending & next_mask & ~next_reserved;

    reg [DATA_W-1:0] pending_population;
    integer p;
    always @(*) begin
        pending_population = ZERO;
        for (p = 0; p < CHANNELS; p = p + 1)
            pending_population = pending_population +
                {{(DATA_W-1){1'b0}}, pending[p]};
    end

initial begin
    fifo_rd = {(FIFO_AW+1){1'b0}};
    fifo_wr = {(FIFO_AW+1){1'b0}};
    issue_index = ZERO;
    issue_valid = 1'b0;
    for (s = 0; s < FIFO_DEPTH; s = s + 1)
        fifo_index[s] = ZERO;
end

always @(posedge clk) begin
    if (ce) begin
        if (fifo_push) begin
            fifo_index[fifo_wr[FIFO_AW-1:0]] <= last_index;
            fifo_wr <= fifo_wr + 1'b1;
        end
        if (fifo_pop) begin
            issue_index <= fifo_index[fifo_rd[FIFO_AW-1:0]];
            issue_valid <= 1'b1;
            fifo_rd <= fifo_rd + 1'b1;
        end else if (take)
            issue_valid <= 1'b0;
    end
end

    initial begin
        pending = CHANNEL_BITS;
        sw_mask = CHANNEL_BITS;
        issued_count = ZERO;
        last_index = ZERO;
        last_valid = 1'b1;
        before_window_end = 1'b1;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            pending <= next_pending;
            sw_mask <= next_mask;
            last_index <= priority_index(next_eligible);
            last_valid <= (next_eligible != ZERO);
            if (take)
                issued_count <= issued_count + ONE;
            if (end_window)
                before_window_end <= 1'b0;
            past_valid <= 1'b1;
        end
    end

    // Before the first enabled end_window event, an unchanged request
    // set means no additional dispatches, and the batch budget holds.
    always @(posedge clk)
        if (past_valid && before_window_end && $stable(pending))
            assert ($stable(issued_count) && issued_count <= CAPACITY);
endmodule

module retirement_batch_fifo #(
   parameter integer PREFETCH_DEPTH = 4,
    parameter [31:0] DEPTH = 32'd16,
    parameter integer WORD_W = 32'd32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_word_valid,
    output wire                  o_word_ready,
    input  wire [WORD_W-1:0]     i_word,
    input  wire                  i_commit_valid,
    output wire                  o_commit_ready,
    input  wire                  i_trap,
    output wire                  o_retire_fire,
    output wire [WORD_W-1:0]     o_retire_word,
   output wire                  o_commit_done,
   output wire [$clog2(DEPTH):0] o_buffered_words,
   output wire [$clog2(DEPTH)-1:0] o_retire_slot,
   output wire                  o_retire_fault
);
    // DEPTH is a power of two. Service cycles are cycles with i_ce high.
    localparam integer ADDR_W = $clog2(DEPTH);
    localparam [31:0] PTR_MOD = DEPTH + DEPTH;
    localparam [31:0] PTR_LAST = PTR_MOD - 32'd1;
   localparam integer PF_ADDR_W = $clog2(PREFETCH_DEPTH);
   localparam integer PF_PTR_W = PF_ADDR_W + 1;

    typedef enum logic [1:0] {
        FILL     = 2'd0,
        DRAIN    = 2'd1,
        COMPLETE = 2'd2
    } state_t;

    state_t state;
    // Address plus wrap bit, carried in the requested 32-bit registers.
    // Bits above ADDR_W remain zero.
    reg [31:0] wr_ptr;
    reg [31:0] rd_ptr;
    reg [31:0] deadline;
    reg [WORD_W-1:0] storage [0:DEPTH-1];
    reg before_trap;
    reg pv;

   reg [WORD_W-1:0] prefetch_data [0:PREFETCH_DEPTH-1];
   reg [ADDR_W-1:0] prefetch_slot [0:PREFETCH_DEPTH-1];
   reg prefetch_parity [0:PREFETCH_DEPTH-1];
   reg [PF_PTR_W-1:0] pf_wr_ptr;
   reg [PF_PTR_W-1:0] pf_rd_ptr;
   reg retire_valid;
   reg [WORD_W-1:0] retire_data;
   reg [ADDR_W-1:0] retire_slot;
   reg retire_parity;

    initial begin
        state = FILL;
        wr_ptr = 32'd0;
        rd_ptr = 32'd0;
        deadline = 32'd0;
        before_trap = 1'b1;
        pv = 1'b0;
       pf_wr_ptr = {PF_PTR_W{1'b0}};
       pf_rd_ptr = {PF_PTR_W{1'b0}};
       retire_valid = 1'b0;
       retire_data = {WORD_W{1'b0}};
       retire_slot = {ADDR_W{1'b0}};
       retire_parity = 1'b0;
       for (integer n = 0; n < PREFETCH_DEPTH; n = n + 1) begin
           prefetch_data[n] = {WORD_W{1'b0}};
           prefetch_slot[n] = {ADDR_W{1'b0}};
           prefetch_parity[n] = 1'b0;
       end
        for (integer n = 32'd0; n < DEPTH; n = n + 32'd1)
            storage[n] = {WORD_W{1'b0}};
    end

    wire empty = (wr_ptr == rd_ptr);
    wire full = (wr_ptr[ADDR_W-1:0] == rd_ptr[ADDR_W-1:0]) &&
                (wr_ptr[ADDR_W] != rd_ptr[ADDR_W]);
    wire [31:0] wr_next = (wr_ptr == PTR_LAST) ? 32'd0 :
                                                        wr_ptr + 32'd1;
    wire [31:0] rd_next = (rd_ptr == PTR_LAST) ? 32'd0 :
                                                        rd_ptr + 32'd1;
    // Combinational pointer distance, not an occupancy register.
    wire [31:0] used_words = (wr_ptr >= rd_ptr) ?
                            (wr_ptr - rd_ptr) :
                            (PTR_MOD - (rd_ptr - wr_ptr));

   wire pf_empty = (pf_wr_ptr == pf_rd_ptr);
   wire pf_full =
       (pf_wr_ptr[PF_ADDR_W-1:0] == pf_rd_ptr[PF_ADDR_W-1:0]) &&
       (pf_wr_ptr[PF_ADDR_W] != pf_rd_ptr[PF_ADDR_W]);
   wire [PF_PTR_W-1:0] pf_used = pf_wr_ptr - pf_rd_ptr;
   wire [ADDR_W:0] buffered_words =
       used_words + pf_used + retire_valid;
   wire [PF_PTR_W-1:0] pf_wr_next =
       pf_wr_ptr + 1'b1;
   wire [PF_PTR_W-1:0] pf_rd_next =
       pf_rd_ptr + 1'b1;
   wire prefetch_push = i_ce && (state != COMPLETE) &&
                        !empty && !pf_full;
   wire prefetch_take = i_ce && !pf_empty &&
                        (!retire_valid || o_retire_fire);

   assign o_commit_ready = i_ce && (state == FILL) &&
                           ((buffered_words == 32'd0) || retire_valid);
    // Sealing a batch takes priority over accepting another word.
    assign o_word_ready = i_ce && (state == FILL) &&
                         !full && (buffered_words < DEPTH) &&
                         !i_commit_valid;
    // The retirement port is an always-accepting execution sink.
   assign o_retire_fire = i_ce && (state == DRAIN) && retire_valid;
   assign o_retire_word = retire_data;
    assign o_commit_done = (state == COMPLETE);
   assign o_buffered_words = buffered_words;
   assign o_retire_slot = retire_slot;
   assign o_retire_fault = retire_valid &&
                           (retire_parity != (^retire_data));

   always @(posedge clk) begin
       if (i_ce) begin
           if (prefetch_push) begin
               prefetch_data[pf_wr_ptr[PF_ADDR_W-1:0]] <=
                   storage[rd_ptr[ADDR_W-1:0]];
               prefetch_slot[pf_wr_ptr[PF_ADDR_W-1:0]] <=
                   rd_ptr[ADDR_W-1:0];
               prefetch_parity[pf_wr_ptr[PF_ADDR_W-1:0]] <=
                   ^storage[rd_ptr[ADDR_W-1:0]];
               pf_wr_ptr <= pf_wr_next;
           end
           if (prefetch_take) begin
               retire_data <=
                   prefetch_data[pf_rd_ptr[PF_ADDR_W-1:0]];
               retire_slot <=
                   prefetch_slot[pf_rd_ptr[PF_ADDR_W-1:0]];
               retire_parity <=
                   prefetch_parity[pf_rd_ptr[PF_ADDR_W-1:0]];
               pf_rd_ptr <= pf_rd_next;
           end
           if (prefetch_take || o_retire_fire)
               retire_valid <= prefetch_take;
       end
   end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (i_trap)
                before_trap <= 1'b0;
           if (prefetch_push)
               rd_ptr <= rd_next;

            case (state)
                FILL: begin
                    if (i_commit_valid && o_commit_ready) begin
                       if (buffered_words == 32'd0) begin
                            state <= COMPLETE;
                            deadline <= 32'd0;
                        end else begin
                            state <= DRAIN;
                            deadline <= DEPTH;
                        end
                    end else if (i_word_valid && o_word_ready) begin
                        storage[wr_ptr[ADDR_W-1:0]] <= i_word;
                        wr_ptr <= wr_next;
                    end
                end

                DRAIN: begin
                   if (buffered_words == 32'd0) begin
                        state <= COMPLETE;
                        deadline <= 32'd0;
                    end else begin
                       if (o_retire_fire && (buffered_words == 32'd1)) begin
                            state <= COMPLETE;
                            deadline <= 32'd0;
                        end else if (deadline != 32'd0) begin
                            deadline <= deadline - 32'd1;
                        end
                    end
                end

                COMPLETE: begin
                    state <= FILL;
                end
            endcase
        end
    end

    // If the previous service cycle consumed the final budget tick,
    // its accepted commit request must now be complete, not outstanding.
    always @(posedge clk)
        if (pv && before_trap &&
            $past(i_ce && (state == DRAIN) && (deadline == 32'd1)))
            assert (state == COMPLETE);

   always @(posedge clk)
       if (o_retire_fire)
           assert ((o_retire_word == storage[o_retire_slot]) &&
                   !o_retire_fault);
endmodule

module chien_scan_engine #(
    parameter integer COEFFS = 16,
    parameter integer REQUEST_DEPTH = 4 // Power-of-two request queue depth.
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [8*COEFFS-1:0]   i_coeffs,
    output reg                   o_valid,
    input  wire                  o_ready,
    output reg  [7:0]            o_position,
    output reg  [7:0]            o_value,
    output reg                   o_root,
    output wire [$clog2(REQUEST_DEPTH):0] o_queued
);
    // GF(256), with primitive polynomial x^8+x^4+x^3+x^2+1.
    function automatic [7:0] xtime;
        input [7:0] a;
        begin
            xtime = {a[6:0], 1'b0} ^ (a[7] ? 8'h1d : 8'h00);
        end
    endfunction

    function automatic [7:0] gf_mul;
        input [7:0] a;
        input [7:0] b;
        reg [7:0] aa, bb, product;
        integer k;
        begin
            aa = a;
            bb = b;
            product = 8'h00;
            for (k = 0; k < 8; k = k + 1) begin
                if (bb[0])
                    product = product ^ aa;
                aa = xtime(aa);
                bb = {1'b0, bb[7:1]};
            end
            gf_mul = product;
        end
    endfunction

    function automatic [7:0] alpha_power;
        input integer exponent;
        reg [7:0] value;
        integer k;
        begin
            value = 8'h01;
            for (k = 0; k < exponent; k = k + 1)
                value = xtime(value);
            alpha_power = value;
        end
    endfunction

    function automatic [7:0] coefficient_sum;
        input [8*COEFFS-1:0] coefficients;
        reg [7:0] accumulator;
        integer j;
        begin
            accumulator = 8'h00;
            for (j = 0; j < COEFFS; j = j + 1)
                accumulator = accumulator ^ coefficients[8*j +: 8];
            coefficient_sum = accumulator;
        end
    endfunction

    reg [7:0] terms [0:COEFFS-1];
    wire [7:0] next_terms [0:COEFFS-1];
    reg [7:0] eval_cache;
    reg [7:0] scan_position;
    reg window;

    localparam integer REQUEST_AW = $clog2(REQUEST_DEPTH);
    reg [8*COEFFS-1:0] request_coeffs [0:REQUEST_DEPTH-1];
    reg [7:0] request_sum [0:REQUEST_DEPTH-1];
    reg request_zero [0:REQUEST_DEPTH-1];
    reg [REQUEST_AW:0] request_rd, request_wr;
    wire [REQUEST_AW:0] request_used;
    wire request_empty, request_full;
    wire request_push, request_fetch, launch_start;
    reg launch_pending, launch_zero;

    reg [7:0] load_sum;
    reg [7:0] term_sum;
    reg [7:0] next_sum;
    integer reduction_index;

    genvar lane;
    generate
        for (lane = 0; lane < COEFFS; lane = lane + 1) begin : multipliers
            assign next_terms[lane] =
                gf_mul(terms[lane], alpha_power(lane));
        end
    endgenerate

    always @(*) begin
        load_sum = coefficient_sum(i_coeffs);
        term_sum = 8'h00;
        next_sum = 8'h00;
        for (reduction_index = 0; reduction_index < COEFFS;
             reduction_index = reduction_index + 1) begin
            term_sum = term_sum ^ terms[reduction_index];
            next_sum = next_sum ^ next_terms[reduction_index];
        end
    end

    // A polynomial cannot be replaced while its result stream is pending.
    // Buffer whole requests independently of result backpressure.
    assign request_empty = (request_rd == request_wr);
    assign request_full =
        (request_rd[REQUEST_AW] != request_wr[REQUEST_AW]) &&
        (request_rd[REQUEST_AW-1:0] == request_wr[REQUEST_AW-1:0]);
    assign request_used = request_wr - request_rd;
    assign i_ready = !request_full;
    assign request_push = i_valid && i_ready;
    assign request_fetch = !request_empty && !launch_pending &&
                           (!o_valid || o_position == 8'hff);
    assign launch_start = launch_pending &&
                          (!o_valid || (o_ready && o_position == 8'hff));
    assign o_queued = request_used + {{REQUEST_AW{1'b0}}, launch_pending};

    integer init_index;
    integer init_request;
    initial begin
        request_rd = {(REQUEST_AW+1){1'b0}};
        request_wr = {(REQUEST_AW+1){1'b0}};
        launch_pending = 1'b0;
        launch_zero = 1'b1;
        for (init_request = 0; init_request < REQUEST_DEPTH;
             init_request = init_request + 1) begin
            request_coeffs[init_request] = {(8*COEFFS){1'b0}};
            request_sum[init_request] = 8'h00;
            request_zero[init_request] = 1'b1;
        end
        o_valid = 1'b0;
        o_position = 8'h00;
        o_value = 8'h00;
        o_root = 1'b1;
        eval_cache = 8'h00;
        scan_position = 8'h01;
        window = 1'b0;
        for (init_index = 0; init_index < COEFFS; init_index = init_index + 1)
            terms[init_index] = 8'h00;
    end

    integer request_index;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            request_rd <= {(REQUEST_AW+1){1'b0}};
            request_wr <= {(REQUEST_AW+1){1'b0}};
            launch_pending <= 1'b0;
            launch_zero <= 1'b1;
            for (request_index = 0; request_index < REQUEST_DEPTH;
                 request_index = request_index + 1) begin
                request_coeffs[request_index] <= {(8*COEFFS){1'b0}};
                request_sum[request_index] <= 8'h00;
                request_zero[request_index] <= 1'b1;
            end
        end else begin
            if (request_push) begin
                request_coeffs[request_wr[REQUEST_AW-1:0]] <= i_coeffs;
                request_sum[request_wr[REQUEST_AW-1:0]] <= load_sum;
                request_zero[request_wr[REQUEST_AW-1:0]] <=
                    (i_coeffs[0 +: 8] == 8'h00);
                request_wr <= request_wr + 1'b1;
            end
            if (request_fetch) begin
                request_rd <= request_rd + 1'b1;
                launch_pending <= 1'b1;
                launch_zero <= request_zero[request_rd[REQUEST_AW-1:0]];
            end else if (launch_start) begin
                launch_pending <= 1'b0;
            end
        end
    end

    integer state_index;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_valid <= 1'b0;
            o_position <= 8'h00;
            o_value <= 8'h00;
            o_root <= 1'b1;
            eval_cache <= 8'h00;
            scan_position <= 8'h01;
            window <= 1'b0;
            for (state_index = 0; state_index < COEFFS;
                 state_index = state_index + 1)
                terms[state_index] <= 8'h00;
        end else if (request_fetch) begin
            // Once the final result is buffered, the lanes can prefetch.
            eval_cache <= request_sum[request_rd[REQUEST_AW-1:0]];
            for (state_index = 0; state_index < COEFFS;
                 state_index = state_index + 1)
                terms[state_index] <=
                    request_coeffs[request_rd[REQUEST_AW-1:0]][8*state_index +: 8];
            if (o_valid && o_ready) begin
                o_valid <= 1'b0;
                window <= 1'b0;
            end
        end else if (launch_start) begin
            // Launch only after the previous final result has cleared.
            window <= 1'b1;
            o_valid <= 1'b1;
            o_position <= 8'h00;
            o_value <= terms[0];
            o_root <= launch_zero;
            scan_position <= 8'h01;
        end else if (o_valid && o_ready) begin
            if (o_position == 8'hff) begin
                // Close only after the final result is accepted.
                o_valid <= 1'b0;
                window <= 1'b0;
            end else begin
                // Positions 1..255 enumerate alpha^0 through alpha^254.
                o_position <= scan_position;
                scan_position <= scan_position + 8'h01;
                // Cached reduction drives root detection; the payload also
                // captures an independent reduction of the coefficient lanes.
                o_root <= (eval_cache == 8'h00);
                o_value <= term_sum;
                eval_cache <= next_sum;
                for (state_index = 0; state_index < COEFFS;
                     state_index = state_index + 1)
                    terms[state_index] <= next_terms[state_index];
            end
        end
    end

    assert property (!window || (o_root == (o_value == 8'h00)));
endmodule

module sampled_i2c_event_queue #(
    parameter integer WORD_BITS = 64,
    parameter integer DEPTH = 2,
    parameter integer PEER_DEPTH = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire sample_scl,
    input  wire sample_sda,
    output wire sample_ready,
    output wire start_event,
    output wire repeated_start_event,
    output wire stop_event,
    output reg  bus_busy,
    output wire [WORD_BITS-1:0] active_event,
    output wire [WORD_BITS-1:0] active_ticket,
    input  wire peer_valid,
    input  wire [WORD_BITS-1:0] peer_data,
    output wire peer_ready,
    output wire completion_valid,
    output wire completion_lane,
    output wire [WORD_BITS-1:0] completion_data,
    output wire [WORD_BITS-1:0] completion_ticket,
    output wire [WORD_BITS-1:0] completion_local_ticket
);
    localparam [WORD_BITS-1:0] ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] TWO = ONE + ONE;
    localparam [WORD_BITS-1:0] THREE = TWO + ONE;
    localparam [WORD_BITS-1:0] DEPTH_VALUE = DEPTH;
    localparam [WORD_BITS-1:0] MAX_TICKS =
        (DEPTH_VALUE > ONE) ? DEPTH_VALUE * TWO - ONE : TWO;

    reg prev_scl;
    reg prev_sda;
    reg window;
    reg pv;
    reg [WORD_BITS-1:0] count;
    reg [WORD_BITS-1:0] rd_ptr;
    reg [WORD_BITS-1:0] wr_ptr;
    reg [WORD_BITS-1:0] issued;
    reg [WORD_BITS-1:0] retired;
    reg [DEPTH-1:0] valid;

    // Event codes: ordinary START, repeated START, and STOP.
    reg [WORD_BITS-1:0] payload [0:DEPTH-1];
    reg [WORD_BITS-1:0] ticket [0:DEPTH-1];
    reg [WORD_BITS-1:0] remaining [0:DEPTH-1];
    reg [WORD_BITS-1:0] deadline [0:DEPTH-1];

    wire [WORD_BITS-1:0] distance [0:DEPTH-1];
    wire [WORD_BITS-1:0] service_need [0:DEPTH-1];
    wire [DEPTH-1:0] due_mask;
    wire [DEPTH-1:0] slot_relation;
    localparam integer CHANNELS = 2;
    localparam integer PEER_PTR_BITS = $clog2(PEER_DEPTH);
    localparam integer PEER_COUNT_BITS = $clog2(PEER_DEPTH + 1);
    reg [PEER_PTR_BITS-1:0] peer_rd, peer_wr;
    reg [PEER_COUNT_BITS-1:0] peer_count;
    reg [$clog2(CHANNELS)-1:0] turn;
    reg peer_phase;
    reg [WORD_BITS-1:0] peer_issued, peer_retired, completed;
    reg [WORD_BITS-1:0] peer_payload [0:PEER_DEPTH-1];
    reg [WORD_BITS-1:0] peer_ticket [0:PEER_DEPTH-1];
    wire [PEER_COUNT_BITS-1:0] peer_distance [0:PEER_DEPTH-1];
    wire [PEER_DEPTH-1:0] peer_relation;
    wire peer_grant = (peer_count != 0) && ((count == ZERO) || turn);
    wire [WORD_BITS-1:0] service_left =
        peer_grant ? (peer_phase ? ONE : TWO) : remaining[rd_ptr];
    wire [WORD_BITS-1:0] service_next = service_left - ONE;
    wire peer_pop = peer_grant && (service_left == ONE);
    wire peer_push = peer_valid && peer_ready;
    assign peer_ready = peer_count < PEER_DEPTH;
    assign completion_valid = i_ce && (dequeue || peer_pop);
    assign completion_lane = peer_grant;
    assign completion_data = peer_grant ? peer_payload[peer_rd] : active_event;
    assign completion_ticket = completed;
    assign completion_local_ticket = peer_grant ? peer_ticket[peer_rd] : active_ticket;
    wire [WORD_BITS:0] stream_held = {1'b0, count} + peer_count;
    wire [1:0] stream_delivered = {1'b0, (i_ce && sample_ready && !enqueue)} +
        {1'b0, (i_ce && dequeue)} + {1'b0, (i_ce && peer_pop)};

    assign sample_ready = (count < DEPTH_VALUE) && !peer_grant;
    assign start_event = sample_ready && prev_scl && sample_scl &&
                         prev_sda && !sample_sda;
    assign stop_event = sample_ready && prev_scl && sample_scl &&
                        !prev_sda && sample_sda;
    assign repeated_start_event = start_event && bus_busy;

    wire enqueue = start_event || stop_event;
    wire dequeue = !peer_grant && (count != ZERO) && (service_left == ONE);
    wire [WORD_BITS-1:0] incoming_event =
        stop_event ? THREE : (bus_busy ? TWO : ONE);

    assign active_event = (count != ZERO) ? payload[rd_ptr] : ZERO;
    assign active_ticket = (count != ZERO) ? ticket[rd_ptr] : ZERO;

    initial begin
        prev_scl = 1'b1;
        prev_sda = 1'b1;
        bus_busy = 1'b0;
        window = 1'b0;
        pv = 1'b0;
        count = ZERO;
        rd_ptr = ZERO;
        wr_ptr = ZERO;
        issued = ZERO;
        retired = ZERO;
        peer_rd = 0; peer_wr = 0; peer_count = 0;
        turn = 0; peer_phase = 1'b0;
        peer_issued = ZERO; peer_retired = ZERO; completed = ZERO;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            // A full queue backpressures sampling, without overwriting events.
            if (sample_ready) begin
                prev_scl <= sample_scl;
                prev_sda <= sample_sda;
                if (start_event) begin
                    bus_busy <= 1'b1;
                    window <= 1'b1;
                end else if (stop_event) begin
                    bus_busy <= 1'b0;
                    window <= 1'b0;
                end
            end

            case ({enqueue, dequeue})
                2'b10: count <= count + ONE;
                2'b01: count <= count - ONE;
                default: count <= count;
            endcase

            if (enqueue) begin
                issued <= issued + ONE;
                wr_ptr <= (wr_ptr == DEPTH_VALUE - ONE) ? ZERO : wr_ptr + ONE;
            end
            if (dequeue) begin
                retired <= retired + ONE;
                rd_ptr <= (rd_ptr == DEPTH_VALUE - ONE) ? ZERO : rd_ptr + ONE;
            end
        end
    end

    genvar g;
    // Both event sources use the same two-tick countdown engine.
    always @(posedge clk) begin
        if (i_ce) begin
            if ((count != ZERO) || (peer_count != 0)) turn <= !peer_grant;
            if (peer_grant) peer_phase <= (service_next != ZERO);
            if (dequeue || peer_pop) completed <= completed + ONE;
            case ({peer_push, peer_pop})
                2'b10: peer_count <= peer_count + 1'b1;
                2'b01: peer_count <= peer_count - 1'b1;
                default: peer_count <= peer_count;
            endcase
            if (peer_push) begin
                peer_issued <= peer_issued + ONE;
                peer_wr <= (peer_wr == PEER_DEPTH - 1) ? 0 : peer_wr + 1'b1;
            end
            if (peer_pop) begin
                peer_retired <= peer_retired + ONE;
                peer_rd <= (peer_rd == PEER_DEPTH - 1) ? 0 : peer_rd + 1'b1;
            end
        end
    end
    genvar p;
    generate
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin : peer_slots
            localparam [PEER_PTR_BITS-1:0] INDEX = p;
            initial begin peer_payload[p] = ZERO; peer_ticket[p] = ZERO; end
            assign peer_distance[p] = (INDEX >= peer_rd) ?
                INDEX - peer_rd : INDEX + PEER_DEPTH - peer_rd;
            assign peer_relation[p] = (peer_distance[p] < peer_count) ?
                (peer_ticket[p] == peer_retired + peer_distance[p]) :
                (peer_ticket[p] == ZERO);
            always @(posedge clk) begin
                if (i_ce) begin
                    if (peer_pop && (peer_rd == INDEX)) begin
                        peer_payload[p] <= ZERO; peer_ticket[p] <= ZERO;
                    end
                    if (peer_push && (peer_wr == INDEX)) begin
                        peer_payload[p] <= peer_data; peer_ticket[p] <= peer_issued;
                    end
                end
            end
        end
    endgenerate
    always @(posedge clk)
        if (pv && completion_valid)
            assert (completion_ticket == completion_local_ticket +
                    (completion_lane ? retired : peer_retired));
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : slots
            localparam [WORD_BITS-1:0] SLOT = g;

            initial begin
                valid[g] = 1'b0;
                payload[g] = ZERO;
                ticket[g] = ZERO;
                remaining[g] = ZERO;
                deadline[g] = ZERO;
            end

            assign distance[g] = (SLOT >= rd_ptr) ?
                SLOT - rd_ptr : SLOT + DEPTH_VALUE - rd_ptr;
            assign service_need[g] = remaining[rd_ptr] + TWO * distance[g];
            assign due_mask[g] = valid[g] && (deadline[g] == ONE) && !peer_grant;

            // These are same-cycle structural facts, not assertions.
            // Only the oldest entry works; every younger entry needs two ticks.
            assign slot_relation[g] =
                (valid[g] == (distance[g] < count)) &&
                (valid[g] ?
                    ((payload[g] == ONE || payload[g] == TWO || payload[g] == THREE) &&
                     (ticket[g] == retired + distance[g]) &&
                     (remaining[g] >= ONE) && (remaining[g] <= TWO) &&
                     ((distance[g] == ZERO) || (remaining[g] == TWO)) &&
                     (deadline[g] >= service_need[g]) &&
                     (deadline[g] <= MAX_TICKS)) :
                    ((payload[g] == ZERO) && (ticket[g] == ZERO) &&
                     (remaining[g] == ZERO) && (deadline[g] == ZERO)));

            always @(posedge clk) begin
                if (i_ce) begin
                    if (valid[g] && !peer_grant)
                        deadline[g] <= deadline[g] - ONE;

                    if (!peer_grant && (count != ZERO) && (rd_ptr == SLOT) &&
                        (remaining[g] > ONE))
                        remaining[g] <= service_next;

                    if (dequeue && (rd_ptr == SLOT)) begin
                        valid[g] <= 1'b0;
                        payload[g] <= ZERO;
                        ticket[g] <= ZERO;
                        remaining[g] <= ZERO;
                        deadline[g] <= ZERO;
                    end

                    if (enqueue && (wr_ptr == SLOT)) begin
                        valid[g] <= 1'b1;
                        payload[g] <= incoming_event;
                        ticket[g] <= issued;
                        remaining[g] <= TWO;
                        deadline[g] <= MAX_TICKS;
                    end
                end
            end
        end
    endgenerate

    // Within a START-to-STOP window, an outstanding request on its
    // previous enabled tick's last deadline count must now be complete.
    always @(posedge clk)
        if (pv && $past(window) && $past(i_ce))
            assert ((valid & $past(due_mask)) == {DEPTH{1'b0}});
endmodule

module boot_completion_queue #(
    parameter integer DATA_W = 32, DEPTH = 4
) (
    input wire clk, push_valid, pop_ready,
    output wire push_ready, pop_valid,
    input wire [DATA_W-1:0] push_sum, push_result,
    input wire push_carry, push_error,
    output reg [$clog2(DEPTH+1)-1:0] used,
    output reg [DEPTH*DATA_W-1:0] sum_words, result_words,
    output reg [DEPTH-1:0] carry_words, error_words
);
    reg [DATA_W-1:0] sum_mem [0:DEPTH-1], result_mem [0:DEPTH-1];
    integer i, j;
    wire push = push_valid && push_ready, pop = pop_valid && pop_ready;
    assign pop_valid = (used != 0);
    assign push_ready = (used < DEPTH) || pop;
    initial begin
        used = 0;
        carry_words = {DEPTH{1'b0}}; error_words = {DEPTH{1'b0}};
        for (i = 0; i < DEPTH; i = i + 1) begin
            sum_mem[i] = {DATA_W{1'b0}}; result_mem[i] = {DATA_W{1'b0}};
        end
    end
    always @(*)
        for (j = 0; j < DEPTH; j = j + 1) begin
            sum_words[j*DATA_W +: DATA_W] = sum_mem[j];
            result_words[j*DATA_W +: DATA_W] = result_mem[j];
        end
    always @(posedge clk) begin
        case ({push, pop})
            2'b10: used <= used + 1'b1;
            2'b01: used <= used - 1'b1;
        endcase
        if (pop)
            for (i = 0; i < DEPTH-1; i = i + 1) begin
                sum_mem[i] <= sum_mem[i+1];
                result_mem[i] <= result_mem[i+1];
                carry_words[i] <= carry_words[i+1]; error_words[i] <= error_words[i+1];
            end
        if (push) begin
            sum_mem[used-pop] <= push_sum;
            result_mem[used-pop] <= push_result;
            carry_words[used-pop] <= push_carry;
            error_words[used-pop] <= push_error;
        end
    end
endmodule

module boot_residue_adder #(
    parameter integer DATA_W = 32,
    parameter [DATA_W-1:0] INITIAL_MODULUS = 32'd17,
    parameter integer QUEUE_DEPTH = 4
) (
    input  wire                  clk,
    input  wire                  cfg_valid,
    output wire                  cfg_ready,
    input  wire [DATA_W-1:0]     cfg_modulus,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [DATA_W-1:0]     in_a,
    input  wire [DATA_W-1:0]     in_b,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [DATA_W-1:0]     result,
    output reg                   out_error,
    output wire [$clog2(QUEUE_DEPTH+1)-1:0] queue_count,
    output wire [QUEUE_DEPTH*DATA_W-1:0] queue_sums, queue_results,
    output wire [QUEUE_DEPTH-1:0] queue_carries, queue_errors
);
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};

    reg [DATA_W-1:0] active_modulus;
    // The buffered transaction retains its own reduction argument.
    reg [DATA_W-1:0] modulus;
    reg [DATA_W-1:0] sum_word;
    reg sum_carry;
    reg past_valid;

    // Keep a batch's reduction argument fixed until its queue has drained.
    // Data wins arbitration at the boundary between configurations.
    assign cfg_ready = (queue_count == 0) && !in_valid;

    // The completion queue may replace a consumed output on the same edge.
    wire queue_pop_ready = !out_valid || out_ready;

    wire cfg_fire = cfg_valid && cfg_ready;
    wire in_fire = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    // The arithmetic interface accepts canonical residues. Noncanonical
    // operands are consumed and reported as an error transaction with a
    // zero result, rather than permanently deasserting input ready.
    wire operand_error = (in_a >= active_modulus)
                       || (in_b >= active_modulus);
    wire [DATA_W:0] input_sum = operand_error
        ? {(DATA_W+1){1'b0}}
        : ({1'b0, in_a} + {1'b0, in_b});
    wire [DATA_W:0] extended_active_modulus = {1'b0, active_modulus};
    wire [DATA_W:0] reduced_sum =
        (input_sum >= extended_active_modulus)
        ? input_sum - extended_active_modulus : input_sum;
    wire queue_valid;
    wire queue_fire = queue_valid && queue_pop_ready;
    boot_completion_queue #(.DATA_W(DATA_W), .DEPTH(QUEUE_DEPTH)) pending (
        .clk(clk), .push_valid(in_valid), .push_ready(in_ready),
        .pop_ready(queue_pop_ready), .pop_valid(queue_valid), .used(queue_count),
        .push_sum(input_sum[DATA_W-1:0]), .push_result(reduced_sum[DATA_W-1:0]),
        .push_carry(input_sum[DATA_W]), .push_error(operand_error),
        .sum_words(queue_sums), .result_words(queue_results),
        .carry_words(queue_carries), .error_words(queue_errors)
    );

    initial begin
        active_modulus = (INITIAL_MODULUS == ZERO) ? ONE : INITIAL_MODULUS;
        modulus = (INITIAL_MODULUS == ZERO) ? ONE : INITIAL_MODULUS;
        sum_word = ZERO;
        sum_carry = 1'b0;
        result = ZERO;
        out_valid = 1'b0;
        out_error = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (cfg_fire)
            active_modulus <= (cfg_modulus == ZERO) ? ONE : cfg_modulus;

        if (out_fire)
            out_valid <= 1'b0;

        if (queue_fire) begin
            modulus <= active_modulus;
            sum_word <= queue_sums[0 +: DATA_W];
            sum_carry <= queue_carries[0];
            result <= queue_results[0 +: DATA_W];
            out_error <= queue_errors[0];
            out_valid <= 1'b1;
        end

        // Remember activity across both completion and output storage.
        if (cfg_fire || in_fire || queue_fire || out_fire)
            past_valid <= 1'b1;
    end

    // Equal stored reduction arguments must have equal stored results.
    always @(posedge clk)
        if (past_valid && $stable({modulus, sum_carry, sum_word}))
            assert ($stable(result));
endmodule

module rotation_coefficient_register #(
    parameter integer BYTE_LANES = 8,
    parameter integer PEER_DEPTH = 4
) (
    input  wire                        clk,
    input  wire                        rst_n,
    input  wire                        i_ce,
    input  wire                        i_write,
    input  wire [BYTE_LANES-1:0]       i_byte_en,
    input  wire [8*BYTE_LANES-1:0]     i_write_data,
    input  wire                        window_open,
    input  wire                        window_close,
    input  wire                        i_peer_write,
    input  wire [BYTE_LANES-1:0]        i_peer_byte_en,
    input  wire [8*BYTE_LANES-1:0]      i_peer_write_data,
    input  wire [$clog2(PEER_DEPTH)-1:0] i_peer_index,
    output reg  [8*BYTE_LANES-1:0]     coefficient_word,
    output reg  [63:0]                 nonzero_bytes,
    output reg                         window,
    output wire                        peer_ready,
    output wire [8*BYTE_LANES-1:0]     peer_read_word,
    output reg [$clog2((PEER_DEPTH+1)*BYTE_LANES+1)-1:0] total_nonzero_bytes
);
    localparam integer WORD_BITS = 8 * BYTE_LANES;
    localparam [63:0] BYTE_LIMIT = BYTE_LANES;
    localparam integer CHANNELS = 2;
    reg [WORD_BITS-1:0] peer_words [0:PEER_DEPTH-1];
    integer entry;
    wire grant_peer;
    wire [WORD_BITS-1:0] selected_word;
    wire [63:0] selected_population;
    assign peer_ready = i_ce && !i_write && (i_peer_index < PEER_DEPTH);
    assign grant_peer = i_peer_write && peer_ready;
    assign selected_word = grant_peer ? peer_words[i_peer_index] : coefficient_word;
    assign peer_read_word = peer_words[i_peer_index];

    wire [WORD_BITS-1:0] merged_word;

    genvar lane;
    generate
        for (lane = 0; lane < BYTE_LANES; lane = lane + 1) begin : byte_merge
            assign merged_word[8*lane +: 8] =
                (grant_peer ? i_peer_byte_en[lane] : (i_write && i_byte_en[lane]))
                ? (grant_peer ? i_peer_write_data[8*lane +: 8] : i_write_data[8*lane +: 8])
                : selected_word[8*lane +: 8];
        end
    endgenerate

    function automatic [63:0] populated_byte_count(
        input [WORD_BITS-1:0] word_value
    );
        integer b;
        begin
            populated_byte_count = 64'd0;
            for (b = 0; b < BYTE_LANES; b = b + 1)
                populated_byte_count = populated_byte_count +
                    ((word_value[8*b +: 8] != 8'h00) ? 64'd1 : 64'd0);
        end
    endfunction

    wire [63:0] stored_population;
    wire [63:0] merged_population;
    assign stored_population = populated_byte_count(coefficient_word);
    assign merged_population = populated_byte_count(merged_word);
    assign selected_population = populated_byte_count(selected_word);

    initial begin
        coefficient_word = {WORD_BITS{1'b0}};
        nonzero_bytes = 64'd0;
        window = 1'b0;
        total_nonzero_bytes = 0;
        for (entry = 0; entry < PEER_DEPTH; entry = entry + 1)
            peer_words[entry] = {WORD_BITS{1'b0}};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            coefficient_word <= {WORD_BITS{1'b0}};
            nonzero_bytes <= 64'd0;
            window <= 1'b0;
            total_nonzero_bytes <= 0;
            for (entry = 0; entry < PEER_DEPTH; entry = entry + 1)
                peer_words[entry] <= {WORD_BITS{1'b0}};
        end else if (i_ce) begin
            if (grant_peer)
                peer_words[i_peer_index] <= merged_word;
            else begin
            coefficient_word <= merged_word;
            nonzero_bytes <= nonzero_bytes + merged_population - stored_population;
            end
            total_nonzero_bytes <= total_nonzero_bytes + merged_population - selected_population;
            if (window_close)
                window <= 1'b0;
            else if (window_open)
                window <= 1'b1;
        end
    end

    always @(*) begin
        if (window)
            assert (nonzero_bytes <= BYTE_LIMIT);
    end
    always @(*) begin
        assert ((total_nonzero_bytes - nonzero_bytes) <= PEER_DEPTH * BYTE_LIMIT);
    end
endmodule

module comparison_history #(
    parameter integer WORD_W = 64,
    parameter integer DEPTH = 4
) (
    input wire clk, ce, program_config,
    input wire [WORD_W-1:0] sample_word, mask_word, reference_word,
    output reg [$clog2(DEPTH)-1:0] head,
    output wire [DEPTH-1:0] hits,
    output wire [DEPTH*WORD_W-1:0] masks,
    output wire [DEPTH*WORD_W-1:0] keys
);
    localparam integer INDEX_W = $clog2(DEPTH);
    reg [WORD_W-1:0] mask_bank [0:DEPTH-1];
    reg [WORD_W-1:0] key_bank [0:DEPTH-1];
    wire [INDEX_W-1:0] next_head =
        (head == DEPTH-1) ? {INDEX_W{1'b0}} : head + 1'b1;
    integer i;
    initial begin
        head = {INDEX_W{1'b0}};
        for (i = 0; i < DEPTH; i = i + 1) begin
            mask_bank[i] = {WORD_W{1'b1}};
            key_bank[i] = {WORD_W{1'b0}};
        end
    end
    always @(posedge clk) begin
        if (ce && program_config) begin
            head <= next_head;
            mask_bank[next_head] <= mask_word;
            key_bank[next_head] <= reference_word & mask_word;
        end
    end
    genvar slot;
    generate for (slot = 0; slot < DEPTH; slot = slot + 1) begin: readback
        assign masks[slot*WORD_W +: WORD_W] = mask_bank[slot];
        assign keys[slot*WORD_W +: WORD_W] = key_bank[slot];
        assign hits[slot] = ((sample_word & mask_bank[slot]) == key_bank[slot]);
    end endgenerate
endmodule

module scoped_masked_comparator #(
    parameter integer WORD_W = 64,
    parameter integer HISTORY_DEPTH = 4
) (
    input wire clk,
    input wire ce,
    input wire program_config,
    input wire open_window,
    input wire close_window,
    input wire [WORD_W-1:0] sample_in,
    input wire [WORD_W-1:0] mask_in,
    input wire [WORD_W-1:0] reference_in,
    output reg match,
    output wire [HISTORY_DEPTH-1:0] history_hits,
    output wire [$clog2(HISTORY_DEPTH)-1:0] history_head,
    output wire [HISTORY_DEPTH*WORD_W-1:0] history_masks,
    output wire [HISTORY_DEPTH*WORD_W-1:0] history_keys
);
    reg [WORD_W-1:0] mask_reg;
    reg [WORD_W-1:0] reference_reg;
    reg [WORD_W-1:0] sample_reg;
    reg window_open;
    reg past_valid;

    wire [WORD_W-1:0] selected_mask =
        program_config ? mask_in : mask_reg;
    wire [WORD_W-1:0] selected_reference =
        program_config ? reference_in : reference_reg;

    comparison_history #(.WORD_W(WORD_W), .DEPTH(HISTORY_DEPTH)) history (
        .clk(clk), .ce(ce), .program_config(program_config),
        .sample_word(sample_reg), .mask_word(mask_in), .reference_word(reference_in),
        .head(history_head), .hits(history_hits),
        .masks(history_masks), .keys(history_keys));

    initial begin
        mask_reg = {WORD_W{1'b1}};
        reference_reg = {WORD_W{1'b0}};
        sample_reg = {WORD_W{1'b0}};
        match = 1'b1;
        window_open = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            past_valid <= 1'b1;
            if (program_config) begin
                mask_reg <= mask_in;
                reference_reg <= reference_in;
            end
            sample_reg <= sample_in;
            match <= (((sample_in ^ selected_reference) & selected_mask)
                      == {WORD_W{1'b0}});

            if (close_window)
                window_open <= 1'b0;
            else if (open_window)
                window_open <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (past_valid && window_open &&
            $stable({mask_reg, reference_reg, sample_reg}))
            assert ($stable(match));
    end

    always @(posedge clk) begin
        if (past_valid)
            assert (history_hits[history_head] == match);
    end
endmodule

module sdram_rr_route_queue #(
    parameter integer DEPTH = 4, BANKS = 4, DATA_W = 64,
    parameter integer BANK_W = (BANKS > 1) ? $clog2(BANKS) : 1,
    parameter integer FILL_W = $clog2(DEPTH+1)
) (
    input wire i_clk, i_valid, output wire o_ready,
    input wire [DATA_W-1:0] i_data, input wire i_ready,
    output wire o_valid, output wire [DATA_W-1:0] o_data,
    output wire [BANK_W-1:0] o_bank,
    output reg [FILL_W-1:0] o_count,
    output reg [BANK_W-1:0] o_alloc,
    output reg [DEPTH*BANK_W-1:0] o_tags
);
    reg [DATA_W-1:0] data [0:DEPTH-1];
    reg [BANK_W-1:0] bank [0:DEPTH-1];
    integer k, j;
    wire push, pop;
    assign o_valid = (o_count != 0);
    assign o_ready = (o_count < DEPTH) || pop;
    assign push = i_valid && o_ready, pop = o_valid && i_ready;
    assign o_data = data[0], o_bank = bank[0];
    always @(*) begin
        for (j = 0; j < DEPTH; j = j + 1) o_tags[j*BANK_W +: BANK_W] = bank[j];
    end
    initial begin
        o_count = {FILL_W{1'b0}}; o_alloc = {BANK_W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin data[k] = {DATA_W{1'b0}}; bank[k] = {BANK_W{1'b0}}; end
    end
    always @(posedge i_clk) begin
        o_count <= o_count + push - pop;
        if (pop) for (k = 0; k < DEPTH-1; k = k + 1) begin
            data[k] <= data[k+1]; bank[k] <= bank[k+1];
        end
        if (push) begin
            data[o_count - pop] <= i_data;
            bank[o_count - pop] <= o_alloc;
            o_alloc <= (o_alloc == BANKS-1) ? {BANK_W{1'b0}} : o_alloc + 1'b1;
        end
    end
endmodule

module sdram_rr_request_dispatch #(
    parameter integer BANKS = 4,
    parameter integer DATA_W = 64,
    parameter integer COUNTER_W = 64,
    parameter integer QUEUE_DEPTH = 4
) (
    input  wire                  i_clk,
    input  wire                  i_req_valid,
    output wire                  o_req_ready,
    input  wire [DATA_W-1:0]     i_req_data,
    output wire [BANKS-1:0]      o_bank_valid,
    input  wire [BANKS-1:0]      i_bank_ready,
    output wire [DATA_W-1:0]     o_bank_data,
    output wire [$clog2(QUEUE_DEPTH+1)-1:0] o_queue_count
);
    localparam [COUNTER_W-1:0] COUNT_ZERO = {COUNTER_W{1'b0}};
    localparam [COUNTER_W-1:0] COUNT_ONE = {{(COUNTER_W-1){1'b0}}, 1'b1};
    localparam [COUNTER_W-1:0] BANK_COUNT = BANKS;
    localparam [COUNTER_W-1:0] LAST_BANK = BANK_COUNT - COUNT_ONE;
    localparam [BANKS-1:0] MASK_ZERO = {BANKS{1'b0}};
    localparam [BANKS-1:0] MASK_ONE = {{(BANKS-1){1'b0}}, 1'b1};
    localparam integer QUEUE_BANK_W = (BANKS > 1) ? $clog2(BANKS) : 1;

    // Binary next-bank pointer and its cached one-hot routing mask.
    reg [COUNTER_W-1:0] next_bank;
    reg [BANKS-1:0] next_mask;

    // One shared command slot: only its selected bank sees valid.
    reg pending_valid;
    reg [BANKS-1:0] pending_mask;
    reg [DATA_W-1:0] pending_data;
    reg armed;

    initial begin
        next_bank = COUNT_ZERO;
        next_mask = MASK_ONE;
        pending_valid = 1'b0;
        pending_mask = MASK_ZERO;
        pending_data = {DATA_W{1'b0}};
        armed = 1'b0;
    end

    wire [COUNTER_W-1:0] following_bank;
    wire retire;
    wire accept;
    wire queue_valid, queue_ready;
    wire [DATA_W-1:0] queue_data;
    wire [QUEUE_BANK_W-1:0] queue_bank, queue_alloc;
    wire [QUEUE_DEPTH*QUEUE_BANK_W-1:0] queue_tags;
    wire [BANKS-1:0] queue_mask;
    assign queue_mask = MASK_ONE << queue_bank;
    sdram_rr_route_queue #(.DEPTH(QUEUE_DEPTH), .BANKS(BANKS), .DATA_W(DATA_W),
        .BANK_W(QUEUE_BANK_W)) request_queue (
        .i_clk(i_clk), .i_valid(i_req_valid), .o_ready(o_req_ready),
        .i_data(i_req_data), .i_ready(queue_ready),
        .o_valid(queue_valid), .o_data(queue_data), .o_bank(queue_bank),
        .o_count(o_queue_count), .o_alloc(queue_alloc), .o_tags(queue_tags));

    assign following_bank = (next_bank == LAST_BANK)
                          ? COUNT_ZERO : next_bank + COUNT_ONE;
    assign o_bank_valid = pending_valid ? pending_mask : MASK_ZERO;
    assign o_bank_data = pending_data;
    assign retire = |(o_bank_valid & i_bank_ready);
    assign queue_ready = !pending_valid || retire;
    assign accept = queue_valid && queue_ready;

    always @(posedge i_clk) begin
        if (accept) begin
            pending_valid <= 1'b1;
            pending_mask <= queue_mask;
            pending_data <= queue_data;
            armed <= 1'b1;

            next_bank <= following_bank;
            // Move the cached route from the old bank to the following bank.
            next_mask <= (next_mask & ~(MASK_ONE << next_bank))
                       | (MASK_ONE << following_bank);
        end else if (retire) begin
            pending_valid <= 1'b0;
        end
    end

    always @(posedge i_clk)
        if (accept) assert (queue_mask == next_mask);

    // After the first accepted command, banks zero and one must never
    // simultaneously own the shared command slot.
    always @(posedge i_clk)
        if (armed) assert (!(o_bank_valid[0] && o_bank_valid[1]));
endmodule

module usb_report_mailbox #(
    parameter integer DEPTH = 32'd256,
    parameter integer DATA_WIDTH = 32'd32,
parameter integer ADDR_WIDTH = 32'd32,
parameter integer QUEUE_DEPTH = 32'd4
) (
    input  wire                  wr_clk,
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [DATA_WIDTH-1:0] in_data,
    input  wire                  release_read,
    input  wire                  session_end,
    output reg                   read_valid,
output reg  [DATA_WIDTH-1:0] read_data,
output wire [$clog2(QUEUE_DEPTH):0] queued_reports,
output reg                   staging_valid
);
    localparam [ADDR_WIDTH-1:0] LAST_ADDR = DEPTH - 32'd1;
    localparam [ADDR_WIDTH-1:0] ADDR_ONE =
        {{(ADDR_WIDTH-32'd1){1'b0}}, 1'b1};

    // Single-write-port, synchronous-read-port RAM in separate domains.
    reg [DATA_WIDTH-1:0] ram [0:DEPTH-1];
    reg [ADDR_WIDTH-1:0] next_wr_addr;
    reg [ADDR_WIDTH-1:0] wr_addr;
    reg [ADDR_WIDTH-1:0] rd_addr;

    // The mailbox permits one outstanding report. The writer keeps its
    // accepted payload and address unchanged until the reader releases it.
    reg [DATA_WIDTH-1:0] accepted_payload;
    reg request;
    reg acknowledge;
    reg before_session_end;
    reg pv;
    integer init_index;

// Power-of-two ingress storage reserves RAM words before mailbox issue.
localparam integer Q_INDEX_WIDTH = $clog2(QUEUE_DEPTH);
localparam integer Q_PTR_WIDTH = Q_INDEX_WIDTH + 1;
localparam [Q_PTR_WIDTH-1:0] Q_ONE =
    {{(Q_PTR_WIDTH-1){1'b0}}, 1'b1};
reg [DATA_WIDTH-1:0] queue_data [0:QUEUE_DEPTH-1];
reg [ADDR_WIDTH-1:0] queue_addr [0:QUEUE_DEPTH-1];
reg [Q_PTR_WIDTH-1:0] queue_wr_ptr, queue_rd_ptr;
reg [DATA_WIDTH-1:0] staging_data;
reg [ADDR_WIDTH-1:0] staging_addr;
wire [Q_INDEX_WIDTH-1:0] queue_head =
    queue_rd_ptr[Q_INDEX_WIDTH-1:0];
wire queue_empty = (queue_wr_ptr == queue_rd_ptr);
wire queue_full =
    (queue_wr_ptr[Q_INDEX_WIDTH] != queue_rd_ptr[Q_INDEX_WIDTH]) &&
    (queue_wr_ptr[Q_INDEX_WIDTH-1:0] == queue_rd_ptr[Q_INDEX_WIDTH-1:0]);
wire queue_push = in_valid && in_ready;
wire queue_issue =
    i_ce && staging_valid && (request == acknowledge);
wire queue_fetch =
    i_ce && !queue_empty && (!staging_valid || queue_issue);
reg [Q_INDEX_WIDTH-1:0] queue_age [0:QUEUE_DEPTH-1];
reg [QUEUE_DEPTH-1:0] queue_live;
integer queue_index;
assign queued_reports = queue_wr_ptr - queue_rd_ptr;
always @(*) begin
    for (queue_index = 0; queue_index < QUEUE_DEPTH;
         queue_index = queue_index + 1) begin
        queue_age[queue_index] = queue_index - queue_rd_ptr[Q_INDEX_WIDTH-1:0];
        queue_live[queue_index] = {1'b0, queue_age[queue_index]} < queued_reports;
    end
end

    initial begin
        next_wr_addr = {ADDR_WIDTH{1'b0}};
        wr_addr = {ADDR_WIDTH{1'b0}};
        rd_addr = {ADDR_WIDTH{1'b0}};
        accepted_payload = {DATA_WIDTH{1'b0}};
        request = 1'b0;
        acknowledge = 1'b0;
        read_valid = 1'b0;
        read_data = {DATA_WIDTH{1'b0}};
        before_session_end = 1'b1;
        pv = 1'b0;
queue_wr_ptr = {Q_PTR_WIDTH{1'b0}};
queue_rd_ptr = {Q_PTR_WIDTH{1'b0}};
staging_valid = 1'b0;
staging_data = {DATA_WIDTH{1'b0}};
staging_addr = {ADDR_WIDTH{1'b0}};
for (init_index = 32'd0; init_index < QUEUE_DEPTH;
     init_index = init_index + 32'd1) begin
    queue_data[init_index] = {DATA_WIDTH{1'b0}};
    queue_addr[init_index] = {ADDR_WIDTH{1'b0}};
end
        for (init_index = 32'd0; init_index < DEPTH;
             init_index = init_index + 32'd1)
            ram[init_index] = {DATA_WIDTH{1'b0}};
    end

    // Back-pressure prevents another input handshake while a report is pending.
assign in_ready = i_ce && !queue_full;

    always @(posedge wr_clk) begin
if (queue_push) begin
            ram[next_wr_addr] <= in_data;
queue_data[queue_wr_ptr[Q_INDEX_WIDTH-1:0]] <= in_data;
queue_addr[queue_wr_ptr[Q_INDEX_WIDTH-1:0]] <= next_wr_addr;
queue_wr_ptr <= queue_wr_ptr + Q_ONE;
            if (next_wr_addr == LAST_ADDR)
                next_wr_addr <= {ADDR_WIDTH{1'b0}};
            else
                next_wr_addr <= next_wr_addr + ADDR_ONE;
        end
if (queue_fetch) begin
    staging_data <= queue_data[queue_head];
    staging_addr <= queue_addr[queue_head];
    staging_valid <= 1'b1;
    queue_rd_ptr <= queue_rd_ptr + Q_ONE;
end else if (queue_issue)
    staging_valid <= 1'b0;
if (queue_issue) begin
    wr_addr <= staging_addr;
    accepted_payload <= staging_data;
    request <= !request;
end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (session_end)
                before_session_end <= 1'b0;

            if (!read_valid && (request != acknowledge)) begin
                rd_addr <= wr_addr;
                read_data <= ram[wr_addr];
                read_valid <= 1'b1;
            end else if (read_valid && release_read) begin
                read_valid <= 1'b0;
                acknowledge <= request;
            end
        end
    end

    // Before session termination, an observed report must match the payload
    // recorded by an earlier input handshake, sampled on the previous cycle.
    always @(posedge clk) begin
        if (pv && before_session_end && read_valid)
            assert (read_data == $past(accepted_payload));
    end

// Issued descriptors must still describe their reserved backing word.
always @(posedge wr_clk) begin
    if (queue_issue)
        assert (staging_data == ram[staging_addr]);
end
endmodule

module gesture_operand_sort #(
    parameter integer WORD_W = 128,
    parameter integer EXP_W = 15
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_a_sig,
    input  wire [WORD_W-1:0]     in_b_sig,
    input  wire [EXP_W-1:0]      in_a_exp,
    input  wire [EXP_W-1:0]      in_b_exp,
    input  wire                  in_last,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [WORD_W-1:0]     large_sig,
    output reg  [WORD_W-1:0]     small_sig,
    output reg  [EXP_W-1:0]      large_exp,
    output reg  [EXP_W-1:0]      small_exp,
    output reg  [EXP_W-1:0]      exponent_gap,
    output reg                   swap_flag,
    output reg                   out_last,
    output reg  [EXP_W-1:0]      retired_span,
    output reg  [39:0]          debug_status
);
    reg before_frame_end;
    reg pv;
    reg [7:0] diag_accepted;
    reg [7:0] diag_retired;
    reg [7:0] diag_frames;
    reg [7:0] diag_stall_cycles;
    reg [3:0] diag_stall_run;
    reg [3:0] diag_peak_stall;

    wire swap_inputs = (in_a_exp < in_b_exp) ||
                       ((in_a_exp == in_b_exp) &&
                        (in_a_sig < in_b_sig));
    assign in_ready = !out_valid || out_ready;
    wire in_fire = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    initial begin
        out_valid = 1'b0;
        large_sig = {WORD_W{1'b0}};
        small_sig = {WORD_W{1'b0}};
        large_exp = {EXP_W{1'b0}};
        small_exp = {EXP_W{1'b0}};
        exponent_gap = {EXP_W{1'b0}};
        swap_flag = 1'b0;
        out_last = 1'b0;
        retired_span = {EXP_W{1'b0}};
        before_frame_end = 1'b1;
        pv = 1'b0;
    end
    initial begin
        diag_accepted = 8'd0;
        diag_retired = 8'd0;
        diag_frames = 8'd0;
        diag_stall_cycles = 8'd0;
        diag_stall_run = 4'd0;
        diag_peak_stall = 4'd0;
        debug_status = 40'd0;
    end
    always @(posedge clk) begin
        if (in_fire)
            diag_accepted <= diag_accepted + 8'd1;
        if (out_fire)
            diag_retired <= diag_retired + 8'd1;
        if (out_fire && out_last)
            diag_frames <= diag_frames + 8'd1;
        if (out_valid && !out_ready) begin
            if (diag_stall_cycles != 8'hff)
                diag_stall_cycles <= diag_stall_cycles + 8'd1;
            if (diag_stall_run != 4'hf)
                diag_stall_run <= diag_stall_run + 4'd1;
            if ((diag_stall_run != 4'hf) &&
                ((diag_stall_run + 4'd1) > diag_peak_stall))
                diag_peak_stall <= diag_stall_run + 4'd1;
        end else begin
            diag_stall_run <= 4'd0;
        end
        debug_status <= {diag_accepted, diag_retired, diag_frames,
                         diag_stall_cycles, diag_peak_stall, diag_stall_run};
    end

    always @(posedge clk) begin
        if (in_fire || out_fire)
            pv <= 1'b1;

        if (in_fire) begin
            out_valid <= 1'b1;
            swap_flag <= swap_inputs;
            out_last <= in_last;
            if (swap_inputs) begin
                large_sig <= in_b_sig;
                small_sig <= in_a_sig;
                large_exp <= in_b_exp;
                small_exp <= in_a_exp;
                exponent_gap <= in_b_exp - in_a_exp;
            end else begin
                large_sig <= in_a_sig;
                small_sig <= in_b_sig;
                large_exp <= in_a_exp;
                small_exp <= in_b_exp;
                exponent_gap <= in_a_exp - in_b_exp;
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end

        // Alignment-span telemetry for the operand pair just consumed.
        if (out_fire)
            retired_span <= large_exp - small_exp;

        // Permanently close the checking scope at the first frame end.
        if (out_fire && out_last)
            before_frame_end <= 1'b0;
    end

    always @(posedge clk) begin
        if (pv && before_frame_end && $past(out_fire))
            assert (retired_span == $past(exponent_gap));
    end
endmodule

module inference_zq_scheduler #(
    parameter integer DEPTH = 32'd2,
    parameter [63:0] ZQ_INTERVAL = 64'd4,
    parameter [63:0] ZQ_BLOCK = 64'd4
) (
    input wire clk,
    input wire i_ce,
    input wire inference_begin,
    input wire inference_end,
    output reg zq_short,
    output wire [63:0] zq_short_ticket,
    output wire inference_blocked,
    output wire schedule_stalled,
    output reg calibration_done,
    output reg [63:0] completed_ticket,
    output reg [255:0] scheduler_telemetry
);
    // DEPTH is at least two; interval and blocking durations are positive.
    localparam [63:0] DEPTH64 = DEPTH;

    reg [63:0] interval_counter;
    reg [63:0] blocking_timer;
    reg calibration_in_progress;

    // Periodic requests wait in a bounded FIFO until calibration can start.
    reg [63:0] pending_ticket [32'd0:DEPTH-32'd1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] pending_count;
    reg [63:0] accepted_serial;

    // These shadows record earlier ZQ command issuance.
    reg [63:0] issued_serial;
    reg issue_seen;
    reg [63:0] active_ticket;
    reg scope_window;

    reg [31:0] diag_enabled_cycles;
    reg [31:0] diag_accepted_count;
    reg [31:0] diag_issued_count;
    reg [31:0] diag_completed_count;
    reg [31:0] diag_stalled_cycles;
    reg [31:0] diag_busy_cycles;
    reg [15:0] diag_stall_run;
    reg [15:0] diag_peak_stall;
    reg [31:0] diag_peak_pending;

    wire interval_due = interval_counter == ZQ_INTERVAL - 64'd1;
    wire enqueue_request = i_ce && interval_due && pending_count < DEPTH64;
    wire issue_command = i_ce && !calibration_in_progress &&
                         pending_count != 64'd0;

    assign inference_blocked = calibration_in_progress;
    assign zq_short_ticket = active_ticket;
    assign schedule_stalled = interval_due && pending_count == DEPTH64;

    // Per-entry ordering predicates. Occupancy comes from pointers/count,
    // not from summing entry-valid bits.
    wire [63:0] slot_distance [32'd0:DEPTH-32'd1];
    wire [DEPTH-32'd1:32'd0] slot_occupied;
    wire [DEPTH-32'd1:32'd0] entry_consistent;
    genvar g;
    generate
        for (g = 32'd0; g < DEPTH; g = g + 32'd1) begin : slots
            localparam [63:0] SLOT = g;
            assign slot_distance[g] = (SLOT >= rd_ptr) ?
                SLOT - rd_ptr : DEPTH64 - rd_ptr + SLOT;
            assign slot_occupied[g] = slot_distance[g] < pending_count;
            assign entry_consistent[g] = !slot_occupied[g] ||
                pending_ticket[g] == issued_serial + slot_distance[g] + 64'd1;
        end
    endgenerate

    integer k;
    initial begin
        interval_counter = 64'd0;
        blocking_timer = 64'd0;
        calibration_in_progress = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        pending_count = 64'd0;
        accepted_serial = 64'd0;
        issued_serial = 64'd0;
        issue_seen = 1'b0;
        active_ticket = 64'd0;
        scope_window = 1'b0;
        zq_short = 1'b0;
        calibration_done = 1'b0;
        completed_ticket = 64'd0;
        diag_enabled_cycles = 32'd0;
        diag_accepted_count = 32'd0;
        diag_issued_count = 32'd0;
        diag_completed_count = 32'd0;
        diag_stalled_cycles = 32'd0;
        diag_busy_cycles = 32'd0;
        diag_stall_run = 16'd0;
        diag_peak_stall = 16'd0;
        diag_peak_pending = 32'd0;
        scheduler_telemetry = 256'd0;
        for (k = 32'd0; k < DEPTH; k = k + 32'd1)
            pending_ticket[k] = 64'd0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Q opens a persistent observation window; R closes it.
            if (inference_end)
                scope_window <= 1'b0;
            else if (inference_begin)
                scope_window <= 1'b1;

            zq_short <= 1'b0;
            calibration_done <= 1'b0;

            // A full FIFO makes the periodic source wait at its deadline.
            if (enqueue_request) begin
                interval_counter <= 64'd0;
                accepted_serial <= accepted_serial + 64'd1;
                pending_ticket[wr_ptr] <= accepted_serial + 64'd1;
                if (wr_ptr == DEPTH64 - 64'd1)
                    wr_ptr <= 64'd0;
                else
                    wr_ptr <= wr_ptr + 64'd1;
            end else if (!interval_due) begin
                interval_counter <= interval_counter + 64'd1;
            end

            // Only the oldest pending request can enter service, and no
            // request enters service until the previous blocking period ends.
            if (issue_command) begin
                active_ticket <= pending_ticket[rd_ptr];
                issued_serial <= issued_serial + 64'd1;
                issue_seen <= 1'b1;
                zq_short <= 1'b1;
                calibration_in_progress <= 1'b1;
                blocking_timer <= ZQ_BLOCK;
                if (rd_ptr == DEPTH64 - 64'd1)
                    rd_ptr <= 64'd0;
                else
                    rd_ptr <= rd_ptr + 64'd1;
            end else if (calibration_in_progress) begin
                if (blocking_timer == 64'd1) begin
                    blocking_timer <= 64'd0;
                    calibration_in_progress <= 1'b0;
                    calibration_done <= 1'b1;
                    completed_ticket <= active_ticket;
                end else begin
                    blocking_timer <= blocking_timer - 64'd1;
                end
            end

            case ({enqueue_request, issue_command})
                2'b10: pending_count <= pending_count + 64'd1;
                2'b01: pending_count <= pending_count - 64'd1;
                default: pending_count <= pending_count;
            endcase
        end
    end

    // Passive statistics, with a registered snapshot for debug readout.
    always @(posedge clk) begin
        if (i_ce) begin
            if (diag_enabled_cycles != 32'hffff_ffff)
                diag_enabled_cycles <= diag_enabled_cycles + 32'd1;
            if (enqueue_request && diag_accepted_count != 32'hffff_ffff)
                diag_accepted_count <= diag_accepted_count + 32'd1;
            if (issue_command && diag_issued_count != 32'hffff_ffff)
                diag_issued_count <= diag_issued_count + 32'd1;
            if (calibration_in_progress && blocking_timer == 64'd1 &&
                diag_completed_count != 32'hffff_ffff)
                diag_completed_count <= diag_completed_count + 32'd1;
            if (schedule_stalled && diag_stalled_cycles != 32'hffff_ffff)
                diag_stalled_cycles <= diag_stalled_cycles + 32'd1;
            if (calibration_in_progress && diag_busy_cycles != 32'hffff_ffff)
                diag_busy_cycles <= diag_busy_cycles + 32'd1;
            if (schedule_stalled) begin
                if (diag_stall_run != 16'hffff)
                    diag_stall_run <= diag_stall_run + 16'd1;
                if (diag_stall_run >= diag_peak_stall &&
                    diag_stall_run != 16'hffff)
                    diag_peak_stall <= diag_stall_run + 16'd1;
            end else begin
                diag_stall_run <= 16'd0;
            end
            if (pending_count > {32'd0, diag_peak_pending})
                diag_peak_pending <= pending_count[31:0];
            scheduler_telemetry <= {
                diag_enabled_cycles, diag_accepted_count,
                diag_issued_count, diag_completed_count,
                diag_stalled_cycles, diag_busy_cycles,
                diag_stall_run, diag_peak_stall, diag_peak_pending
            };
        end
    end

    // Completion must be preceded by a command, with the recorded ticket.
    always @(posedge clk) begin
        if (scope_window && calibration_done)
            assert (issue_seen);
        if (scope_window && calibration_done)
            assert (completed_ticket == issued_serial);
    end
endmodule

module retained_seed_fifo #(
    parameter integer DEPTH = 4
) (
    input  wire clk,
    input  wire ce,
    input  wire in_valid,
    input  wire [63:0] in_data,
    output wire in_ready,
    input  wire release_head,
    output wire out_valid,
    output wire [63:0] out_data,
    output reg [$clog2(DEPTH+1)-1:0] count,
    output reg [$clog2(DEPTH)-1:0] read_index,
    output reg [$clog2(DEPTH)-1:0] write_index,
    output wire [64*DEPTH-1:0] contents
);
    localparam integer PTR_W = $clog2(DEPTH);
    reg [63:0] storage [0:DEPTH-1];
    wire take_out = ce && release_head && out_valid;
    wire take_in = in_valid && in_ready;
    assign in_ready = ce && ((count < DEPTH) || take_out);
    assign out_valid = (count != 0);
    assign out_data = storage[read_index];

    integer entry_index;
    initial begin
        count = 0;
        read_index = 0;
        write_index = 0;
        for (entry_index = 0; entry_index < DEPTH; entry_index = entry_index + 1)
            storage[entry_index] = 64'd0;
    end

    genvar entry_slot;
    generate
        for (entry_slot = 0; entry_slot < DEPTH; entry_slot = entry_slot + 1) begin : inspection
            assign contents[64*entry_slot +: 64] = storage[entry_slot];
        end
    endgenerate

    // A request stays at the head until its complete batch has retired.
    always @(posedge clk) begin
        if (take_in) begin
            storage[write_index] <= in_data;
            write_index <= (write_index == DEPTH-1)
                           ? {PTR_W{1'b0}} : write_index + 1'b1;
        end
        if (take_out)
            read_index <= (read_index == DEPTH-1)
                          ? {PTR_W{1'b0}} : read_index + 1'b1;
        case ({take_in, take_out})
            2'b10: count <= count + 1'b1;
            2'b01: count <= count - 1'b1;
            default: begin end
        endcase
    end
endmodule

module phased_case_emitter #(
    parameter integer DEPTH = 16,
    parameter integer SEED_DEPTH = 4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        seed_valid,
    input  wire [63:0] seed_in,
    output wire        seed_ready,
    output reg  [63:0] issued_word,
    output reg  [63:0] issued_phase,
    output reg  [63:0] issued_mask,
    output wire [63:0] pending_seed,
    output wire [$clog2(SEED_DEPTH+1)-1:0] pending_count,
    output wire [$clog2(SEED_DEPTH)-1:0] seed_read_index,
    output wire [$clog2(SEED_DEPTH)-1:0] seed_write_index,
    output wire [64*SEED_DEPTH-1:0] seed_storage
);
    // DEPTH is the number of timing phases and table entries; use 2 through 16.
    localparam [63:0] DEPTH64 = DEPTH;
    localparam [63:0] LAST_PHASE = DEPTH64 - 64'd1;
    localparam [DEPTH-1:0] PHASE_ONE = {{(DEPTH-1){1'b0}}, 1'b1};

    reg [63:0] phase;
    reg [DEPTH-1:0] phase_enable;
    reg [63:0] filled;
    reg [63:0] seed;
    reg draining;
    reg window;

    reg [63:0] words [0:DEPTH-1];
    reg [DEPTH-1:0] valid;
    wire pending_valid;
    wire release_seed;

    // Admission is independent of execution; the active request retains its slot.
    retained_seed_fifo #(.DEPTH(SEED_DEPTH)) seed_requests (
        .clk(clk), .ce(i_ce),
        .in_valid(seed_valid), .in_data(seed_in), .in_ready(seed_ready),
        .release_head(release_seed),
        .out_valid(pending_valid), .out_data(pending_seed),
        .count(pending_count), .read_index(seed_read_index),
        .write_index(seed_write_index), .contents(seed_storage)
    );
    wire advance = i_ce &&
                   (draining || (phase != 64'd0) || pending_valid);
    wire [63:0] next_phase = (phase == LAST_PHASE)
                             ? 64'd0 : phase + 64'd1;
    wire [63:0] fill_seed = pending_seed;

    // Q opens the checking window; the final dispatch closes it.
    wire open_window = advance && draining && (phase == 64'd0);
    wire close_window = advance && draining && (phase == LAST_PHASE);
    assign release_seed = close_window;

    initial begin
        phase = 64'd0;
        phase_enable = PHASE_ONE;
        filled = 64'd0;
        seed = 64'd0;
        draining = 1'b0;
        window = 1'b0;
        issued_word = 64'd0;
        issued_phase = 64'd0;
        issued_mask = 64'd1;
    end

    // The registered decoder supplies the per-entry timing strobes.
    genvar slot;
    generate
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin : entries
            initial begin
                words[slot] = 64'd0;
                valid[slot] = 1'b0;
            end
            always @(posedge clk) begin
                if (advance && phase_enable[slot]) begin
                    if (!draining) begin
                        words[slot] <= fill_seed ^ phase;
                        valid[slot] <= 1'b1;
                    end else begin
                        valid[slot] <= 1'b0;
                    end
                end
            end
        end
    endgenerate

    reg [63:0] selected_word;
    integer mux_index;
    always @(*) begin
        selected_word = 64'd0;
        for (mux_index = 0; mux_index < DEPTH; mux_index = mux_index + 1)
            if (phase_enable[mux_index])
                selected_word = selected_word | words[mux_index];
    end

    always @(posedge clk) begin
        if (advance) begin
            phase <= next_phase;
            phase_enable <= PHASE_ONE << next_phase;

            if (!draining) begin
                if (phase == 64'd0)
                    seed <= fill_seed;
                filled <= filled + 64'd1;
                if (phase == LAST_PHASE)
                    draining <= 1'b1;
            end else begin
                filled <= filled - 64'd1;
                issued_word <= selected_word;
                issued_phase <= phase;
                issued_mask <= phase_enable;
                if (phase == LAST_PHASE)
                    draining <= 1'b0;
            end

            if (close_window)
                window <= 1'b0;
            else if (open_window)
                window <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (window) begin
            assert (issued_word == (seed ^ issued_phase));
            assert (issued_mask == (64'd1 << issued_phase));
        end
    end

    always @(posedge clk) begin
        if (window) begin
            assert (issued_word == (pending_seed ^ issued_phase));
        end
    end
endmodule

module chien_deadline_search #(
    parameter integer FIELD_W = 8,
    parameter integer COEFFS = 4,
    parameter [FIELD_W-1:0] REDUCTION = 8'h1d
) (
    input  wire clk,
    input  wire req_valid,
    output wire req_ready,
    input  wire [COEFFS*FIELD_W-1:0] req_coeffs,
    output wire result_valid,
    input  wire result_ready,
    output reg  [FIELD_W-1:0] position,
    output reg  hit,
    output reg  [3:0] debug_nibble,
    output reg  [3:0] diag_nibble
);
    localparam [FIELD_W-1:0] FIELD_ZERO = {FIELD_W{1'b0}};
    localparam [FIELD_W-1:0] FIELD_ONE = {{(FIELD_W-1){1'b0}}, 1'b1};
    localparam [FIELD_W-1:0] LAST_POSITION = {FIELD_W{1'b1}};
    localparam [FIELD_W:0] FIELD_SIZE = {1'b1, {FIELD_W{1'b0}}};
    localparam [FIELD_W:0] CREDIT_ONE = {{FIELD_W{1'b0}}, 1'b1};

    reg busy;
    reg armed;
    reg pv;
    reg [FIELD_W:0] credits;
    reg [FIELD_W-1:0] terms [0:COEFFS-1];
    wire [FIELD_W-1:0] stepped_terms [0:COEFFS-1];
    reg [FIELD_W-1:0] eval_now;
    reg [FIELD_W-1:0] eval_next;

    wire request_fire;
    wire trial_fire;
    assign req_ready = !busy;
    assign result_valid = busy;
    assign request_fire = req_valid && req_ready;
    assign trial_fire = result_valid && result_ready;

    function automatic [FIELD_W-1:0] gf_xtime;
        input [FIELD_W-1:0] a;
        begin
            gf_xtime = (a << 1'b1) ^
                       (a[FIELD_W-1] ? REDUCTION : FIELD_ZERO);
        end
    endfunction

    function automatic [FIELD_W-1:0] gf_mul;
        input [FIELD_W-1:0] a;
        input [FIELD_W-1:0] b;
        reg [FIELD_W-1:0] multiplicand;
        reg [FIELD_W-1:0] multiplier;
        reg [FIELD_W-1:0] product;
        integer bit_index;
        begin
            multiplicand = a;
            multiplier = b;
            product = FIELD_ZERO;
            for (bit_index = 0; bit_index < FIELD_W; bit_index = bit_index + 1) begin
                if (multiplier[0])
                    product = product ^ multiplicand;
                multiplicand = gf_xtime(multiplicand);
                multiplier = multiplier >> 1'b1;
            end
            gf_mul = product;
        end
    endfunction

    function automatic [FIELD_W-1:0] alpha_factor;
        input integer exponent;
        reg [FIELD_W-1:0] factor;
        integer power_index;
        begin
            factor = FIELD_ONE;
            for (power_index = 0; power_index < exponent; power_index = power_index + 1)
                factor = gf_xtime(factor);
            alpha_factor = factor;
        end
    endfunction

    genvar coefficient;
    generate
        for (coefficient = 0; coefficient < COEFFS; coefficient = coefficient + 1) begin : coefficient_steps
            assign stepped_terms[coefficient] =
                gf_mul(terms[coefficient], alpha_factor(coefficient));
        end
    endgenerate

    integer eval_index;
    always @(*) begin
        eval_now = FIELD_ZERO;
        eval_next = FIELD_ZERO;
        for (eval_index = 0; eval_index < COEFFS; eval_index = eval_index + 1) begin
            eval_now = eval_now ^ terms[eval_index];
            eval_next = eval_next ^ stepped_terms[eval_index];
        end
    end

    reg [31:0] diag_trace [0:3];
    reg [15:0] diag_ticks;
    reg [15:0] diag_watchdog;
    reg [15:0] diag_timeouts;
    reg [15:0] diag_events;
    reg [15:0] diag_wraps;
    reg [15:0] diag_long_stalls;
    reg [3:0] diag_tag;
    reg [1:0] diag_wr_ptr;
    reg [5:0] diag_scan;
    reg [3:0] diag_fold;
    reg [3:0] diag_event;
    wire [7:0] diag_position;
    wire [223:0] diag_frame;
    wire diag_timeout;
    integer diag_bit;
    integer diag_init;

    assign diag_position = position;
    assign diag_timeout = busy && !result_ready &&
                          (diag_watchdog == 16'd1023);
    assign diag_frame = {diag_wraps, diag_long_stalls,
                         diag_timeouts, diag_events, diag_watchdog, diag_ticks,
                         diag_trace[3], diag_trace[2], diag_trace[1], diag_trace[0]};

    always @(*) begin
        diag_fold = 4'd0;
        for (diag_bit = 0; diag_bit < COEFFS*FIELD_W; diag_bit = diag_bit + 1)
            diag_fold[diag_bit % 4] = diag_fold[diag_bit % 4] ^ req_coeffs[diag_bit];
        diag_event = 4'd0;
        if (request_fire)
            diag_event = 4'd1;
        else if (diag_timeout)
            diag_event = 4'd4;
        else if (trial_fire && position == LAST_POSITION)
            diag_event = 4'd3;
        else if (trial_fire && hit)
            diag_event = 4'd2;
    end

    initial begin
        diag_ticks = 16'd0;
        diag_watchdog = 16'd0;
        diag_timeouts = 16'd0;
        diag_events = 16'd0;
        diag_wraps = 16'd0;
        diag_long_stalls = 16'd0;
        diag_tag = 4'd0;
        diag_wr_ptr = 2'd0;
        diag_scan = 6'd0;
        diag_nibble = 4'd0;
        for (diag_init = 0; diag_init < 4; diag_init = diag_init + 1)
            diag_trace[diag_init] = 32'd0;
    end

    always @(posedge clk) begin
        diag_ticks <= diag_ticks + 16'd1;
        if (diag_scan == 6'd55)
            diag_scan <= 6'd0;
        else
            diag_scan <= diag_scan + 6'd1;
        diag_nibble <= diag_frame[{diag_scan, 2'b00} +: 4];
        if (request_fire)
            diag_tag <= diag_fold;
        if (busy && !result_ready) begin
            if (diag_watchdog != 16'hffff)
                diag_watchdog <= diag_watchdog + 16'd1;
        end else begin
            diag_watchdog <= 16'd0;
        end
        if (diag_timeout && diag_timeouts != 16'hffff)
            diag_timeouts <= diag_timeouts + 16'd1;
        if (busy && !result_ready && diag_watchdog >= 16'd1023) begin
            if (diag_long_stalls != 16'hffff)
                diag_long_stalls <= diag_long_stalls + 16'd1;
        end
        if (diag_event != 4'd0) begin
            diag_trace[diag_wr_ptr] <= {diag_ticks, diag_position,
                                       diag_event, request_fire ? diag_fold : diag_tag};
            diag_wr_ptr <= diag_wr_ptr + 2'd1;
            if (diag_events != 16'hffff)
                diag_events <= diag_events + 16'd1;
            if (diag_wr_ptr == 2'd3) begin
                if (diag_wraps != 16'hffff)
                    diag_wraps <= diag_wraps + 16'd1;
            end
        end
    end

    reg [15:0] mon_requests;
    reg [15:0] mon_results;
    reg [15:0] mon_hits;
    reg [15:0] mon_stalls;
    reg [15:0] mon_stall_run;
    reg [15:0] mon_stall_peak;
    reg [15:0] mon_search_age;
    reg [15:0] mon_last_latency;
    reg [4:0] mon_scan;
    wire [127:0] mon_frame;
    assign mon_frame = {mon_last_latency, mon_search_age,
                        mon_stall_peak, mon_stall_run,
                        mon_stalls, mon_hits, mon_results, mon_requests};

    initial begin
        mon_requests = 16'd0;
        mon_results = 16'd0;
        mon_hits = 16'd0;
        mon_stalls = 16'd0;
        mon_stall_run = 16'd0;
        mon_stall_peak = 16'd0;
        mon_search_age = 16'd0;
        mon_last_latency = 16'd0;
        mon_scan = 5'd0;
        debug_nibble = 4'd0;
    end

    always @(posedge clk) begin
        mon_scan <= mon_scan + 5'd1;
        debug_nibble <= mon_frame[{mon_scan, 2'b00} +: 4];
        if (request_fire && mon_requests != 16'hffff)
            mon_requests <= mon_requests + 16'd1;
        if (trial_fire && mon_results != 16'hffff)
            mon_results <= mon_results + 16'd1;
        if (trial_fire && hit && mon_hits != 16'hffff)
            mon_hits <= mon_hits + 16'd1;
        if (busy && !result_ready) begin
            if (mon_stalls != 16'hffff)
                mon_stalls <= mon_stalls + 16'd1;
            if (mon_stall_run != 16'hffff) begin
                mon_stall_run <= mon_stall_run + 16'd1;
                if (mon_stall_run >= mon_stall_peak)
                    mon_stall_peak <= mon_stall_run + 16'd1;
            end
        end else begin
            mon_stall_run <= 16'd0;
        end
        if (request_fire) begin
            mon_search_age <= 16'd0;
        end else if (busy) begin
            if (mon_search_age != 16'hffff)
                mon_search_age <= mon_search_age + 16'd1;
        end
        if (trial_fire && position == LAST_POSITION) begin
            mon_last_latency <= (mon_search_age == 16'hffff) ?
                                16'hffff : mon_search_age + 16'd1;
        end
    end


    integer init_index;
    initial begin
        busy = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
        credits = {1'b0, FIELD_ZERO};
        position = FIELD_ZERO;
        hit = 1'b0;
        for (init_index = 0; init_index < COEFFS; init_index = init_index + 1)
            terms[init_index] = FIELD_ZERO;
    end

    // Position zero tests x=0. Positions 1..255 test alpha^0..alpha^254.
    // Each accepted result consumes one enabled search cycle. Back-pressure
    // freezes the countdown, multiplier registers, position and hit flag.
    integer state_index;
    always @(posedge clk) begin
        if (request_fire || trial_fire)
            pv <= 1'b1;

        if (request_fire) begin
            armed <= 1'b1;
            busy <= 1'b1;
            credits <= FIELD_SIZE;
            position <= FIELD_ZERO;
            hit <= (req_coeffs[0 +: FIELD_W] == FIELD_ZERO);
            for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                terms[state_index] <= req_coeffs[state_index*FIELD_W +: FIELD_W];
        end else if (trial_fire) begin
            credits <= credits - CREDIT_ONE;
            if (position == LAST_POSITION) begin
                busy <= 1'b0;
            end else begin
                position <= position + FIELD_ONE;
                if (position == FIELD_ZERO) begin
                    // The first nonzero element is one; coefficients stay unchanged.
                    hit <= (eval_now == FIELD_ZERO);
                end else begin
                    for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                        terms[state_index] <= stepped_terms[state_index];
                    hit <= (eval_next == FIELD_ZERO);
                end
            end
        end
    end

    // After the first accepted request, consuming the previous cycle's final
    // countdown credit must leave no search outstanding.
    always @(posedge clk)
        if (pv && armed && $past(trial_fire))
            assert (!busy || ($past(credits) > CREDIT_ONE));
endmodule

module stream_nonrestoring_divider #(
    parameter integer DATA_W = 128
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_req_valid,
    output wire                  o_req_ready,
    input  wire [DATA_W-1:0]     i_dividend,
    input  wire [DATA_W-1:0]     i_divisor,
    output reg                   o_done,
    output reg  [DATA_W-1:0]     o_quotient,
    output wire [DATA_W-1:0]     o_remainder,
    output wire [95:0]           o_debug_stats
);
    localparam integer STEP_W = $clog2(DATA_W + 1);
    localparam [STEP_W-1:0] TOTAL_STEPS = DATA_W;
    localparam [STEP_W-1:0] LAST_STEP = DATA_W - 1;
    localparam [STEP_W-1:0] STEP_ONE = {{(STEP_W-1){1'b0}}, 1'b1};

    reg signed [DATA_W:0] remainder;
    reg [DATA_W-1:0] divisor;
    reg [STEP_W-1:0] step_count;
    reg busy;
    reg armed;
    reg past_valid;

    wire signed [DATA_W:0] divisor_pos = {1'b0, divisor};
    wire signed [DATA_W:0] divisor_neg = -divisor_pos;
    wire correction_pending = remainder[DATA_W];

    // The input is a valid/ready receiver. Zero divisors are not accepted.
    assign o_req_ready = i_ce && !busy && (i_divisor != {DATA_W{1'b0}});
    assign o_remainder = remainder[DATA_W-1:0];

    // Extra arithmetic width preserves the intermediate doubled remainder.
    wire signed [DATA_W+1:0] remainder_extended = {remainder[DATA_W], remainder};
    wire signed [DATA_W+1:0] doubled_remainder = remainder_extended <<< 1;
    wire signed [DATA_W+1:0] incoming_bit = {{(DATA_W+1){1'b0}}, o_quotient[DATA_W-1]};
    wire signed [DATA_W+1:0] divisor_wide = {2'b00, divisor};
    wire signed [DATA_W+1:0] trial_remainder = remainder[DATA_W]
        ? doubled_remainder + incoming_bit + divisor_wide
        : doubled_remainder + incoming_bit - divisor_wide;
    wire signed [DATA_W+1:0] normalized_remainder = trial_remainder[DATA_W+1]
        ? trial_remainder + divisor_wide
        : trial_remainder;

    reg [15:0] stats_accepted;
    reg [15:0] stats_completed;
    reg [15:0] stats_zero_rejects;
    reg [15:0] stats_busy_cycles;
    reg [15:0] stats_latency;
    reg [15:0] stats_peak_latency;
    wire stats_accept = i_req_valid && o_req_ready;
    wire stats_finish = busy && (step_count == LAST_STEP);
    assign o_debug_stats = {stats_peak_latency, stats_latency,
        stats_busy_cycles, stats_zero_rejects, stats_completed, stats_accepted};
    initial begin
        stats_accepted = 16'd0;
        stats_completed = 16'd0;
        stats_zero_rejects = 16'd0;
        stats_busy_cycles = 16'd0;
        stats_latency = 16'd0;
        stats_peak_latency = 16'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (stats_accept && (stats_accepted != 16'hffff))
                stats_accepted <= stats_accepted + 16'd1;
            if (stats_finish && (stats_completed != 16'hffff))
                stats_completed <= stats_completed + 16'd1;
            if (i_req_valid && !busy && (i_divisor == {DATA_W{1'b0}})
                && (stats_zero_rejects != 16'hffff))
                stats_zero_rejects <= stats_zero_rejects + 16'd1;
            if (busy && (stats_busy_cycles != 16'hffff))
                stats_busy_cycles <= stats_busy_cycles + 16'd1;
            if (stats_accept)
                stats_latency <= 16'd0;
            else if (busy && (stats_latency != 16'hffff))
                stats_latency <= stats_latency + 16'd1;
            if (stats_finish && (stats_latency >= stats_peak_latency)) begin
                if (stats_latency != 16'hffff)
                    stats_peak_latency <= stats_latency + 16'd1;
                else
                    stats_peak_latency <= 16'hffff;
            end
        end
    end

    initial begin
        remainder = {(DATA_W+1){1'b0}};
        divisor = {{(DATA_W-1){1'b0}}, 1'b1};
        o_quotient = {DATA_W{1'b0}};
        step_count = {STEP_W{1'b0}};
        busy = 1'b0;
        o_done = 1'b0;
        armed = 1'b0;
        past_valid = 1'b0;
    end

    // i_ce low freezes every state register. Completion remains latched until
    // the next accepted request; o_done is a status flag, not an output channel.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            if (!busy) begin
                if (i_req_valid && o_req_ready) begin
                    divisor <= i_divisor;
                    remainder <= {(DATA_W+1){1'b0}};
                    o_quotient <= i_dividend;
                    step_count <= {STEP_W{1'b0}};
                    busy <= 1'b1;
                    o_done <= 1'b0;
                    armed <= 1'b1;
                end
            end else begin
                // Non-restoring division chooses add/subtract from the old
                // remainder sign and generates a quotient bit from the new sign.
                o_quotient <= {o_quotient[DATA_W-2:0], !trial_remainder[DATA_W+1]};
                step_count <= step_count + STEP_ONE;
                if (step_count == LAST_STEP) begin
                    remainder <= normalized_remainder[DATA_W:0];
                    busy <= 1'b0;
                    o_done <= 1'b1;
                end else begin
                    remainder <= trial_remainder[DATA_W:0];
                end
            end
        end
    end

    // After the first accepted request, a completion edge must never coexist
    // with a remainder that still needs negative-remainder correction.
    always @(posedge clk) begin
        if (armed && past_valid && $rose(o_done))
            assert (!(o_done && correction_pending));
    end
endmodule

module phase_capture_deadlines #(
    parameter WORD_W = 8,
    parameter DEPTH = 16,
parameter SERVICE_PERIOD = 8,
parameter RESULT_DEPTH = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_ref_edge,
    input  wire i_fb_edge,
    output wire o_up,
    output wire o_dn,
    output wire o_pair_ready,
    output wire o_accept,
    output wire o_complete,
output reg [WORD_W-1:0] o_result,
output wire o_retire_ready,
output wire o_serial_valid,
output wire o_serial_bit,
output wire o_serial_first,
output wire o_serial_last,
output wire [$clog2(RESULT_DEPTH+3)-1:0] o_result_level
);
    localparam [WORD_W-1:0] DEPTH8 = DEPTH;
    localparam [WORD_W-1:0] PERIOD8 = SERVICE_PERIOD;
    localparam [WORD_W-1:0] MAX_WAIT8 = DEPTH * SERVICE_PERIOD;
localparam RESULT_ADDR_W = $clog2(RESULT_DEPTH);
localparam RESULT_PTR_W = RESULT_ADDR_W + 1;
localparam SERIAL_COUNT_W =
    (WORD_W > 1) ? $clog2(WORD_W) : 1;
localparam [SERIAL_COUNT_W-1:0] SERIAL_LAST = WORD_W - 1;

    reg up_q, dn_q;
    reg [WORD_W-1:0] phase_ticks;
    reg [WORD_W-1:0] samples [0:DEPTH-1];
    reg [WORD_W-1:0] budget [0:DEPTH-1];
    reg [DEPTH-1:0] valid;
    reg [WORD_W-1:0] rd_ptr, wr_ptr, count;
    reg [WORD_W-1:0] accepted_count, completed_count;
    reg [WORD_W-1:0] service_wait;
    reg armed, past_valid, expired;

    wire seen_up = up_q || i_ref_edge;
    wire seen_dn = dn_q || i_fb_edge;
    wire pair_pending = seen_up && seen_dn;
    wire push = pair_pending && (count < DEPTH8);
wire pop = (count != 8'd0) && (service_wait == 8'd0)
    && !result_full;
    wire common_clear = push;
    wire [WORD_W-1:0] phase_sample =
        phase_ticks | (up_q ? 8'h80 : 8'h00);
    wire [WORD_W-1:0] slot_distance [0:DEPTH-1];
    wire [DEPTH-1:0] expiring;

reg [WORD_W-1:0] result_words [0:RESULT_DEPTH-1];
reg [RESULT_PTR_W-1:0] result_rd_ptr, result_wr_ptr;
reg [WORD_W-1:0] prefetch_sample;
reg prefetch_valid, serial_busy;
reg [SERIAL_COUNT_W-1:0] serial_left;
wire [RESULT_ADDR_W-1:0] result_rd_addr = result_rd_ptr[RESULT_ADDR_W-1:0];
wire [RESULT_ADDR_W-1:0] result_wr_addr = result_wr_ptr[RESULT_ADDR_W-1:0];
wire result_empty = (result_rd_ptr == result_wr_ptr);
wire result_full = (result_rd_addr == result_wr_addr)
    && (result_rd_ptr[RESULT_ADDR_W] != result_wr_ptr[RESULT_ADDR_W]);
wire [RESULT_PTR_W-1:0] result_used =
    (result_rd_ptr[RESULT_ADDR_W] == result_wr_ptr[RESULT_ADDR_W])
    ? ({1'b0, result_wr_addr} - {1'b0, result_rd_addr})
    : (RESULT_DEPTH - {1'b0, result_rd_addr} + {1'b0, result_wr_addr});
wire serial_done = serial_busy && (serial_left == 0);
wire tx_launch = prefetch_valid && (!serial_busy || serial_done);
wire result_read = !result_empty && (!prefetch_valid || tx_launch);
reg [RESULT_PTR_W-1:0] result_rd_next, result_wr_next;
reg [WORD_W-1:0] result_head;
integer scan;

// Small flop-based RAM with independent address generators and read mux.
always @(*) begin
    result_rd_next = result_rd_ptr;
    result_wr_next = result_wr_ptr;
    result_head = 8'd0;
    for (scan = 0; scan < RESULT_DEPTH; scan = scan + 1) begin
        if (result_rd_addr == scan)
            result_head = result_words[scan];
    end
    if (pop) begin
        if (result_wr_addr == RESULT_DEPTH - 1) begin
            result_wr_next[RESULT_ADDR_W-1:0] = {RESULT_ADDR_W{1'b0}};
            result_wr_next[RESULT_ADDR_W] = !result_wr_ptr[RESULT_ADDR_W];
        end else
            result_wr_next = result_wr_ptr + 1'b1;
    end
    if (result_read) begin
        if (result_rd_addr == RESULT_DEPTH - 1) begin
            result_rd_next[RESULT_ADDR_W-1:0] = {RESULT_ADDR_W{1'b0}};
            result_rd_next[RESULT_ADDR_W] = !result_rd_ptr[RESULT_ADDR_W];
        end else
            result_rd_next = result_rd_ptr + 1'b1;
    end
end

assign o_retire_ready = i_ce && (service_wait == 8'd0)
    && !result_full;
assign o_serial_valid = i_ce && serial_busy;
assign o_serial_bit = o_result[(WORD_W - 1) - serial_left];
assign o_serial_first = o_serial_valid && (serial_left == SERIAL_LAST);
assign o_serial_last = i_ce && serial_done;
assign o_result_level = result_used + prefetch_valid + serial_busy;

    assign o_up = up_q;
    assign o_dn = dn_q;
    assign o_pair_ready = i_ce && (count < DEPTH8);
    assign o_accept = i_ce && push;
assign o_complete = i_ce && tx_launch;

    initial begin
        up_q = 1'b0;
        dn_q = 1'b0;
        phase_ticks = 8'd0;
        valid = {DEPTH{1'b0}};
        rd_ptr = 8'd0;
        wr_ptr = 8'd0;
        count = 8'd0;
        accepted_count = 8'd0;
        completed_count = 8'd0;
        service_wait = 8'd0;
        armed = 1'b0;
        past_valid = 1'b0;
        expired = 1'b0;
        o_result = 8'd0;
    end

integer r;
initial begin
    result_rd_ptr = {RESULT_PTR_W{1'b0}};
    result_wr_ptr = {RESULT_PTR_W{1'b0}};
    prefetch_sample = 8'd0;
    prefetch_valid = 1'b0;
    serial_busy = 1'b0;
    serial_left = {SERIAL_COUNT_W{1'b0}};
    for (r = 0; r < RESULT_DEPTH; r = r + 1)
        result_words[r] = 8'd0;
end

// Prefetch hides the RAM access while the preceding word is serialized.
// The parallel result changes only at a serial frame boundary.
always @(posedge clk) begin
    if (i_ce) begin
        result_rd_ptr <= result_rd_next;
        result_wr_ptr <= result_wr_next;
        if (pop)
            result_words[result_wr_addr] <= samples[rd_ptr];
        if (result_read) begin
            prefetch_sample <= result_head;
            prefetch_valid <= 1'b1;
        end else if (tx_launch) begin
            prefetch_valid <= 1'b0;
        end

        if (serial_busy) begin
            if (serial_done) begin
                serial_busy <= 1'b0;
                serial_left <= {SERIAL_COUNT_W{1'b0}};
            end else
                serial_left <= serial_left - 1'b1;
        end
        if (tx_launch) begin
            o_result <= prefetch_sample;
            serial_busy <= 1'b1;
            serial_left <= SERIAL_LAST;
        end
    end
end

    // Sampled phase-frequency detector. Both pulse flops use one clear path.
    // A full sample FIFO stretches the paired pulses until storage is free.
    always @(posedge clk) begin
        if (i_ce) begin
            if (common_clear) begin
                up_q <= 1'b0;
                dn_q <= 1'b0;
                phase_ticks <= 8'd0;
            end else begin
                up_q <= seen_up;
                dn_q <= seen_dn;
                if ((seen_up ^ seen_dn) && (phase_ticks < 8'd15))
                    phase_ticks <= phase_ticks + 8'd1;
            end
        end
    end

    // One queued comparison is completed every SERVICE_PERIOD enabled clocks.
    // Budgets count enabled clocks, so disabling i_ce freezes the whole design.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
if (service_wait == 8'd0) begin
    if ((count == 8'd0) || !result_full)
        service_wait <= PERIOD8 - 8'd1;
end else
                service_wait <= service_wait - 8'd1;

            case ({push, pop})
                2'b10: count <= count + 8'd1;
                2'b01: count <= count - 8'd1;
                default: count <= count;
            endcase

            if (push) begin
                armed <= 1'b1;
                accepted_count <= accepted_count + 8'd1;
                if (wr_ptr == DEPTH8 - 8'd1)
                    wr_ptr <= 8'd0;
                else
                    wr_ptr <= wr_ptr + 8'd1;
            end
            if (pop) begin
                completed_count <= completed_count + 8'd1;
                if (rd_ptr == DEPTH8 - 8'd1)
                    rd_ptr <= 8'd0;
                else
                    rd_ptr <= rd_ptr + 8'd1;
            end

            // Sticky witness of a countdown expiring before its response.
            if (|expiring)
                expired <= 1'b1;
        end
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : entry
            localparam [WORD_W-1:0] INDEX = g;
            assign slot_distance[g] = (INDEX >= rd_ptr)
                ? (INDEX - rd_ptr) : (DEPTH8 - rd_ptr + INDEX);
            assign expiring[g] = valid[g]
                && !(pop && (rd_ptr == INDEX))
                && (budget[g] <= 8'd1);

            initial begin
                samples[g] = 8'd0;
                budget[g] = 8'd0;
            end

            always @(posedge clk) begin
                if (i_ce) begin
                    if (valid[g] && !(pop && (rd_ptr == INDEX))
                            && (budget[g] != 8'd0))
                        budget[g] <= budget[g] - 8'd1;
                    if (pop && (rd_ptr == INDEX))
                        valid[g] <= 1'b0;
                    if (push && (wr_ptr == INDEX)) begin
                        valid[g] <= 1'b1;
                        samples[g] <= phase_sample;
                        budget[g] <= MAX_WAIT8;
                    end
                end
            end
        end
    endgenerate

    // After the first accepted comparison, an unchanged armed scope must
    // never see the deadline-expiration witness change.
    always @(posedge clk)
        if (past_valid && armed && $stable(armed))
            assert ($stable(expired));
endmodule

module trellis_acs_accel #(
    parameter WORD_W = 128,
    parameter STATES = 8,
    parameter TRACE_DEPTH = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_valid,
    output wire i_ready,
    input  wire [STATES*WORD_W-1:0] i_branch_a,
    input  wire [STATES*WORD_W-1:0] i_branch_b,
    output wire o_valid,
    input  wire o_ready,
    output wire [WORD_W-1:0] o_terminal_metric,
    output wire [WORD_W-1:0] o_terminal_runner_up,
    output wire [STATES-1:0] o_survivors,
    input  wire [((TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1)-1:0] trace_read_addr,
    output wire [WORD_W-1:0] trace_read_word,
    output wire [127:0] o_debug_stats
);
    localparam TRACE_AW = (TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1;

    reg [WORD_W-1:0] path_metric [0:STATES-1];
    reg [WORD_W-1:0] runner_up   [0:STATES-1];
    reg [WORD_W-1:0] cand_a      [0:STATES-1];
    reg [WORD_W-1:0] cand_b      [0:STATES-1];
    reg [STATES-1:0] survivor;
    reg [WORD_W-1:0] traceback [0:TRACE_DEPTH-1];
    reg [TRACE_AW-1:0] trace_wr;
    reg pending;
    reg armed;
    reg [31:0] dbg_cycles;
    reg [15:0] dbg_accepted;
    reg [15:0] dbg_retired;
    reg [15:0] dbg_stall_cycles;
    reg [15:0] dbg_stall_run;
    reg [15:0] dbg_stall_peak;
    reg [14:0] dbg_tie_count;
    reg dbg_watchdog;

    function automatic [WORD_W-1:0] metric_add;
        input [WORD_W-1:0] a;
        input [WORD_W-1:0] b;
        reg [WORD_W:0] total;
        begin
            total = {1'b0, a} + {1'b0, b};
            metric_add = total[WORD_W] ? {WORD_W{1'b1}} : total[WORD_W-1:0];
        end
    endfunction

    wire [WORD_W-1:0] next_a [0:STATES-1];
    wire [WORD_W-1:0] next_b [0:STATES-1];

    genvar g;
    generate
        for (g = 0; g < STATES; g = g + 1) begin : trellis
            localparam PRED_A = (2*g) % STATES;
            localparam PRED_B = (2*g + 1) % STATES;
            assign next_a[g] = metric_add(
                path_metric[PRED_A], i_branch_a[g*WORD_W +: WORD_W]);
            assign next_b[g] = metric_add(
                path_metric[PRED_B], i_branch_b[g*WORD_W +: WORD_W]);
        end
    endgenerate

    assign i_ready = !pending;
    assign o_valid = pending;
    wire accept_branches = i_valid && i_ready;
    wire retire_survivors = o_valid && o_ready;

    assign o_terminal_metric = survivor[0] ? cand_b[0] : cand_a[0];
    assign o_terminal_runner_up = survivor[0] ? cand_a[0] : cand_b[0];
    assign o_survivors = survivor;
    assign trace_read_word = traceback[trace_read_addr];
    wire [WORD_W-1:0] survivor_word = {{(WORD_W-STATES){1'b0}}, survivor};
    assign o_debug_stats =
        {dbg_cycles, dbg_accepted, dbg_retired,
         dbg_stall_cycles, dbg_stall_run, dbg_stall_peak,
         dbg_watchdog, dbg_tie_count};
    initial begin
        dbg_cycles = 32'd0;
        dbg_accepted = 16'd0;
        dbg_retired = 16'd0;
        dbg_stall_cycles = 16'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_peak = 16'd0;
        dbg_tie_count = 15'd0;
        dbg_watchdog = 1'b0;
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dbg_cycles <= 32'd0;
            dbg_accepted <= 16'd0;
            dbg_retired <= 16'd0;
            dbg_stall_cycles <= 16'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_peak <= 16'd0;
            dbg_tie_count <= 15'd0;
            dbg_watchdog <= 1'b0;
        end else begin
            dbg_cycles <= dbg_cycles + 32'd1;
            if (accept_branches && (dbg_accepted != 16'hffff))
                dbg_accepted <= dbg_accepted + 16'd1;
            if (retire_survivors) begin
                if (dbg_retired != 16'hffff)
                    dbg_retired <= dbg_retired + 16'd1;
                if ((cand_a[0] == cand_b[0]) && (dbg_tie_count != 15'h7fff))
                    dbg_tie_count <= dbg_tie_count + 15'd1;
            end
            if (o_valid && !o_ready) begin
                if (dbg_stall_cycles != 16'hffff)
                    dbg_stall_cycles <= dbg_stall_cycles + 16'd1;
                if (dbg_stall_run != 16'hffff) begin
                    dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_peak)
                        dbg_stall_peak <= dbg_stall_run + 16'd1;
                end
                if (dbg_stall_run >= 16'd255)
                    dbg_watchdog <= 1'b1;
            end else begin
                dbg_stall_run <= 16'd0;
            end
        end
    end

    initial begin
        pending = 1'b0;
        armed = 1'b0;
        survivor = {STATES{1'b0}};
        trace_wr = {TRACE_AW{1'b0}};
        for (integer s = 0; s < STATES; s = s + 1) begin
            path_metric[s] = {WORD_W{1'b0}};
            runner_up[s] = {WORD_W{1'b0}};
            cand_a[s] = {WORD_W{1'b0}};
            cand_b[s] = {WORD_W{1'b0}};
        end
        for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
            traceback[t] = {WORD_W{1'b0}};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending <= 1'b0;
            armed <= 1'b0;
            survivor <= {STATES{1'b0}};
            trace_wr <= {TRACE_AW{1'b0}};
            for (integer s = 0; s < STATES; s = s + 1) begin
                path_metric[s] <= {WORD_W{1'b0}};
                runner_up[s] <= {WORD_W{1'b0}};
                cand_a[s] <= {WORD_W{1'b0}};
                cand_b[s] <= {WORD_W{1'b0}};
            end
            for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
                traceback[t] <= {WORD_W{1'b0}};
        end else begin
            // Capture both path candidates and their comparison together.
            if (accept_branches) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    cand_a[s] <= next_a[s];
                    cand_b[s] <= next_b[s];
                    survivor[s] <= (next_b[s] < next_a[s]);
                end
                pending <= 1'b1;
            end

            // Back-pressure holds the candidate bank and output unchanged.
            // Retain the losing metric for decoder confidence estimation.
            if (retire_survivors) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    path_metric[s] <= survivor[s] ? cand_b[s] : cand_a[s];
                    runner_up[s] <= survivor[s] ? cand_a[s] : cand_b[s];
                end
                traceback[trace_wr] <= survivor_word;
                if (trace_wr == TRACE_AW'(TRACE_DEPTH - 1))
                    trace_wr <= {TRACE_AW{1'b0}};
                else
                    trace_wr <= trace_wr + {{(TRACE_AW-1){1'b0}}, 1'b1};
                pending <= 1'b0;
                // Q: the first completed trellis update.
                armed <= 1'b1;
            end
        end
    end

    // After Q, the committed terminal-state survivor never exceeds its runner-up.
    always @(posedge clk)
        assert (!armed || (path_metric[0] <= runner_up[0]));
endmodule

module pixel_dot_batch #(
    parameter integer DEPTH = 4, WORD_W = 64,
    parameter integer COUNT_W = $clog2(DEPTH+1)
) (
    input wire clk, ce, in_valid, in_last,
    input wire [WORD_W-1:0] in_sum,
    output wire in_ready,
    output reg out_valid,
    output reg [COUNT_W-1:0] count,
    output reg [WORD_W-1:0] out_sum,
    output reg [(DEPTH*WORD_W)-1:0] entry_state
);
    reg [WORD_W-1:0] entries [0:DEPTH-1];
    integer init_slot, scan_slot;
    initial begin
        count = {COUNT_W{1'b0}};
        out_valid = 1'b0;
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1)
            entries[init_slot] = {WORD_W{1'b0}};
    end
    assign in_ready = !out_valid && (count < DEPTH);
    always @(*) begin
        out_sum = {WORD_W{1'b0}};
        for (scan_slot = 0; scan_slot < DEPTH; scan_slot = scan_slot + 1) begin
            entry_state[scan_slot*WORD_W +: WORD_W] = entries[scan_slot];
            if (scan_slot < count) out_sum = out_sum + entries[scan_slot];
        end
    end
    always @(posedge clk) begin
        if (ce) begin
            if (out_valid) begin
                count <= {COUNT_W{1'b0}};
                out_valid <= 1'b0;
            end else if (in_valid && in_ready) begin
                entries[count] <= in_sum;
                count <= count + 1'b1;
                out_valid <= in_last || (count == DEPTH-1);
            end
        end
    end
endmodule

module pixel_dot_accumulator #(
    parameter integer LANES = 16,
    parameter integer WORD_W = 64,
    parameter integer BATCH_DEPTH = 4
) (
    input wire clk,
    input wire ce,
    input wire end_frame,
    input wire [(LANES*WORD_W)-1:0] shade_operands,
    input wire [(LANES*WORD_W)-1:0] texture_operands,
    output wire input_ready,
    output wire [WORD_W-1:0] accumulated_value
);
    // Products and additions use fixed-width modular arithmetic.
    reg [WORD_W-1:0] products [0:LANES-1];
    wire [WORD_W-1:0] incoming_product [0:LANES-1];
    wire [WORD_W-1:0] adder_tree [1:(2*LANES)-1];
    wire [LANES-1:0] incoming_nonzero;
    wire [LANES-1:0] staged_nonzero;
    wire pending_nonzero;

    reg [WORD_W-1:0] running_sum;
    reg seen_nonzero_issue;
    reg before_end;
    reg past_valid;
    localparam integer BATCH_COUNT_W = $clog2(BATCH_DEPTH+1);
    wire batch_ready, batch_valid;
    wire [BATCH_COUNT_W-1:0] batch_count;
    wire [WORD_W-1:0] batch_sum;
    wire [(BATCH_DEPTH*WORD_W)-1:0] batch_entries;
    reg staged_last;
    assign input_ready = !past_valid || batch_ready;
    pixel_dot_batch #(.DEPTH(BATCH_DEPTH), .WORD_W(WORD_W)) batcher (
        .clk(clk), .ce(ce), .in_valid(past_valid), .in_last(staged_last),
        .in_sum(adder_tree[1]), .in_ready(batch_ready), .out_valid(batch_valid),
        .count(batch_count), .out_sum(batch_sum), .entry_state(batch_entries)
    );

    initial begin
        running_sum = {WORD_W{1'b0}};
        seen_nonzero_issue = 1'b0;
        before_end = 1'b1;
        past_valid = 1'b0;
        staged_last = 1'b0;
    end

    genvar lane;
    generate
        for (lane = 0; lane < LANES; lane = lane + 1) begin : lanes
            assign incoming_product[lane] =
                shade_operands[lane*WORD_W +: WORD_W] *
                texture_operands[lane*WORD_W +: WORD_W];
            assign incoming_nonzero[lane] =
                incoming_product[lane] != {WORD_W{1'b0}};
            assign staged_nonzero[lane] =
                products[lane] != {WORD_W{1'b0}};
            assign adder_tree[LANES+lane] = products[lane];

            initial products[lane] = {WORD_W{1'b0}};
            always @(posedge clk) begin
                if (ce && input_ready)
                    products[lane] <= incoming_product[lane];
            end
        end
    endgenerate

    genvar node;
    generate
        for (node = 1; node < LANES; node = node + 1) begin : reduction_tree
            assign adder_tree[node] =
                adder_tree[2*node] + adder_tree[2*node+1];
        end
    endgenerate

    assign pending_nonzero = |staged_nonzero;
    assign accumulated_value = running_sum;

    always @(posedge clk) begin
        if (ce && batch_valid)
            running_sum <= running_sum + batch_sum;
        if (ce && input_ready) begin
            // History of a nonzero product entering the preceding stage.
            seen_nonzero_issue <= seen_nonzero_issue || (|incoming_nonzero);
            past_valid <= 1'b1;
            staged_last <= end_frame;
            if (end_frame)
                before_end <= 1'b0;
        end
    end

    // Before the first frame-end event, a rising nonzero accumulated value
    // must be preceded by an issued nonzero product.
    always @(posedge clk) begin
        if (past_valid && before_end &&
            $rose(running_sum != {WORD_W{1'b0}}))
            assert (seen_nonzero_issue);
    end
endmodule

module wave_line_prefetcher #(
    parameter integer LINE_W = 8,
    parameter integer DEPTH = 64,
    parameter integer COUNT_W = 8
) (
    input  wire                  clk,
    input  wire                  miss_valid,
    output wire                  miss_ready,
    input  wire [LINE_W-1:0]     miss_line,
    input  wire                  peer_valid,
    output wire                  peer_ready,
    input  wire [LINE_W-1:0]     peer_line,
    output wire                  peer_prefetch_valid,
    input  wire                  peer_prefetch_ready,
    output wire [LINE_W-1:0]     peer_prefetch_line,
    output wire                  prefetch_valid,
    input  wire                  prefetch_ready,
    output wire [LINE_W-1:0]     prefetch_line
);
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [LINE_W-1:0] LINE_ZERO = {LINE_W{1'b0}};
    localparam [LINE_W-1:0] LINE_ONE = {{(LINE_W-1){1'b0}}, 1'b1};
    localparam integer CHANNELS = 2, PEER_DEPTH = 4;
    localparam integer PEER_PTR_W = $clog2(PEER_DEPTH);

    reg [LINE_W-1:0] prefetch_q [0:DEPTH-1];
    reg [COUNT_W-1:0] wr_ptr;
    reg [COUNT_W-1:0] rd_ptr;
    reg [COUNT_W-1:0] used;
    reg [LINE_W-1:0] last_miss;
    reg pv;
    reg [LINE_W-1:0] peer_q [0:PEER_DEPTH-1];
    reg [PEER_PTR_W-1:0] peer_wr, peer_rd;
    reg [$clog2(PEER_DEPTH+1)-1:0] peer_used;
    reg [LINE_W-1:0] peer_last, alu_last;
    reg [$clog2(CHANNELS)-1:0] alu_owner;

    initial begin
        wr_ptr = COUNT_ZERO;
        rd_ptr = COUNT_ZERO;
        used = COUNT_ZERO;
        last_miss = {LINE_W{1'b1}};
        pv = 1'b0;
        peer_wr = 0;
        peer_rd = 0;
        peer_used = 0;
        peer_last = LINE_ZERO;
        alu_last = LINE_ZERO;
        alu_owner = 0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : initialize_queue
            initial prefetch_q[g] = LINE_ZERO;
        end
        for (g = 0; g < PEER_DEPTH; g = g + 1) begin : initialize_peer_queue
            initial peer_q[g] = LINE_ZERO;
        end
    endgenerate

    assign miss_ready = (used < CAPACITY);
    assign prefetch_valid = (used != COUNT_ZERO);
    assign prefetch_line = prefetch_q[rd_ptr];

    wire push = miss_valid && miss_ready;
    wire pop = prefetch_valid && prefetch_ready;
    assign peer_ready = (peer_used < PEER_DEPTH) && !push;
    assign peer_prefetch_valid = (peer_used != 0);
    assign peer_prefetch_line = peer_q[peer_rd];
    wire peer_push = peer_valid && peer_ready;
    wire peer_pop = peer_prefetch_valid && peer_prefetch_ready;
    wire [LINE_W-1:0] issue_line = push ? miss_line : peer_line;
    wire [LINE_W-1:0] cached_line = alu_owner ? peer_last : last_miss;
    wire [LINE_W-1:0] shared_next = (issue_line == cached_line) ? alu_last : (issue_line + LINE_ONE);

    // The slot immediately preceding the write pointer retains the
    // most recently generated next-line request, even after retirement.
    wire [COUNT_W-1:0] latest_slot =
        (wr_ptr == COUNT_ZERO) ? LAST_SLOT : (wr_ptr - COUNT_ONE);
    wire [LINE_W-1:0] latest_line = prefetch_q[latest_slot];

    always @(posedge clk) begin
        if (push || peer_push) begin
            alu_last <= shared_next;
            alu_owner <= !push;
        end
        if (peer_push) begin
            peer_q[peer_wr] <= shared_next;
            peer_last <= peer_line;
            peer_wr <= (peer_wr == PEER_DEPTH-1) ? 0 : (peer_wr + 1'b1);
        end
        if (peer_pop) peer_rd <= (peer_rd == PEER_DEPTH-1) ? 0 : (peer_rd + 1'b1);
        if (peer_push != peer_pop)
            peer_used <= peer_push ? (peer_used + 1'b1) : (peer_used - 1'b1);
        if (push) begin
            prefetch_q[wr_ptr] <= shared_next;
            last_miss <= miss_line;
            wr_ptr <= (wr_ptr == LAST_SLOT) ? COUNT_ZERO : (wr_ptr + COUNT_ONE);
        end
        if (pop)
            rd_ptr <= (rd_ptr == LAST_SLOT) ? COUNT_ZERO : (rd_ptr + COUNT_ONE);

        if (push && !pop)
            used <= used + COUNT_ONE;
        else if (pop && !push)
            used <= used - COUNT_ONE;

        // No history check is needed before the first transaction.
        // Keeping this update transaction-gated preserves complete idle.
        if (push || pop)
            pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $stable(last_miss))
            assert ($stable(latest_line));
endmodule

module pixel_dot_accumulator #(
    parameter integer LANES = 16,
    parameter integer WORD_W = 64
) (
    input wire clk,
    input wire ce,
    input wire end_frame,
    input wire [(LANES*WORD_W)-1:0] shade_operands,
    input wire [(LANES*WORD_W)-1:0] texture_operands,
    input wire peer_valid,
    input wire [(LANES*WORD_W)-1:0] peer_terms,
    output wire [WORD_W-1:0] accumulated_value, peer_accumulated_value,
    output wire issue_ready, peer_ready,
    output wire peer_nonzero_issued,
    output reg staged_valid
,
    output wire [WORD_W-1:0] peer_running_sum_o,
    output wire peer_seen_nonzero_issue_o,
    output wire pending_nonzero_o,
    output wire [WORD_W-1:0] running_sum_o,
    output wire seen_nonzero_issue_o,
    output wire [$clog2(CHANNELS)-1:0] stage_owner_o
);
    localparam integer CHANNELS = 2;
    // Products and additions use fixed-width modular arithmetic.
    reg [WORD_W-1:0] products [0:LANES-1];
    wire [WORD_W-1:0] incoming_product [0:LANES-1];
    wire [WORD_W-1:0] adder_tree [1:(2*LANES)-1];
    wire [LANES-1:0] incoming_nonzero;
    wire [LANES-1:0] staged_nonzero;
    wire pending_nonzero;

    reg [WORD_W-1:0] running_sum;
    reg seen_nonzero_issue;
    reg before_end;
    reg past_valid;
    reg [WORD_W-1:0] peer_running_sum;
    reg peer_seen_nonzero_issue;
    reg [$clog2(CHANNELS)-1:0] stage_owner, next_owner;
    wire peer_grant = peer_valid && (next_owner == 1'b1);

    initial begin
        running_sum = {WORD_W{1'b0}};
        seen_nonzero_issue = 1'b0;
        before_end = 1'b1;
        past_valid = 1'b0;
        peer_running_sum = {WORD_W{1'b0}};
        peer_seen_nonzero_issue = 1'b0;
        stage_owner = 1'b0;
        next_owner = 1'b0;
        staged_valid = 1'b0;
    end

    genvar lane;
    generate
        for (lane = 0; lane < LANES; lane = lane + 1) begin : lanes
            assign incoming_product[lane] =
                shade_operands[lane*WORD_W +: WORD_W] *
                texture_operands[lane*WORD_W +: WORD_W];
            assign incoming_nonzero[lane] =
                incoming_product[lane] != {WORD_W{1'b0}};
            assign staged_nonzero[lane] =
                products[lane] != {WORD_W{1'b0}};
            assign adder_tree[LANES+lane] = products[lane];

            initial products[lane] = {WORD_W{1'b0}};
            always @(posedge clk) begin
                if (ce)
                    products[lane] <= peer_grant ?
                        peer_terms[lane*WORD_W +: WORD_W] : incoming_product[lane];
            end
        end
    endgenerate

    genvar node;
    generate
        for (node = 1; node < LANES; node = node + 1) begin : reduction_tree
            assign adder_tree[node] =
                adder_tree[2*node] + adder_tree[2*node+1];
        end
    endgenerate

    assign pending_nonzero = |staged_nonzero;
    assign accumulated_value = running_sum;
    assign issue_ready = ce && !peer_grant;
    assign peer_ready = ce && (next_owner == 1'b1);
    assign peer_accumulated_value = peer_running_sum;
    assign peer_nonzero_issued = peer_seen_nonzero_issue;

    always @(posedge clk) begin
        if (ce) begin
            if (staged_valid) begin
                if (!stage_owner) running_sum <= running_sum + adder_tree[1];
                else peer_running_sum <= peer_running_sum + adder_tree[1];
            end
            stage_owner <= peer_grant;
            next_owner <= !peer_grant;
            staged_valid <= 1'b1;
            if (peer_grant)
                peer_seen_nonzero_issue <= peer_seen_nonzero_issue || (|peer_terms);
            else begin
            // History of a nonzero product entering the preceding stage.
            seen_nonzero_issue <= seen_nonzero_issue || (|incoming_nonzero);
            if (end_frame)
                before_end <= 1'b0;
            end
            past_valid <= 1'b1;
        end
    end

    // Before the first frame-end event, a rising nonzero accumulated value
    // must be preceded by an issued nonzero product.
    always @(posedge clk) begin
        if (past_valid && before_end &&
            $rose(running_sum != {WORD_W{1'b0}}))
            assert (seen_nonzero_issue);
    end
    always @(posedge clk) begin
        if (past_valid && $rose(peer_running_sum != {WORD_W{1'b0}}))
            assert (peer_seen_nonzero_issue);
    end
    assign peer_running_sum_o = peer_running_sum;
    assign peer_seen_nonzero_issue_o = peer_seen_nonzero_issue;
    assign pending_nonzero_o = pending_nonzero;
    assign running_sum_o = running_sum;
    assign seen_nonzero_issue_o = seen_nonzero_issue;
    assign stage_owner_o = stage_owner;
endmodule

module camera_mask_classifier #(
    parameter integer WORD_BITS = 64
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 cfg_load,
    input  wire [WORD_BITS-1:0]  cfg_mask,
    input  wire [WORD_BITS-1:0]  cfg_reference,
    input  wire [WORD_BITS-1:0]  pixel_word,
    output reg                  match_flag,
    output reg                  masked_error,
    output reg                  armed
,
    output wire [WORD_BITS-1:0] active_mask_o,
    output wire [WORD_BITS-1:0] masked_reference_o,
    output wire [WORD_BITS-1:0] reference_pattern_o
);
    reg [WORD_BITS-1:0] active_mask;
    reg [WORD_BITS-1:0] reference_pattern;
    reg [WORD_BITS-1:0] masked_reference;

    initial begin
        active_mask       = {WORD_BITS{1'b1}};
        reference_pattern = {WORD_BITS{1'b0}};
        masked_reference  = {WORD_BITS{1'b0}};
        match_flag        = 1'b0;
        masked_error      = 1'b0;
        armed             = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_load) begin
                active_mask       <= cfg_mask;
                reference_pattern <= cfg_reference;
                masked_reference  <= cfg_reference & cfg_mask;
            end else begin
                // Compare against the pre-masked reference cache.
                match_flag <= ((pixel_word & active_mask) == masked_reference);
                // Independently detect differences in enabled bit positions.
                masked_error <= (((pixel_word ^ reference_pattern) & active_mask)
                                 != {WORD_BITS{1'b0}});
                // Q is the first enabled pixel classification, not configuration.
                armed <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (!(match_flag && masked_error));
    assign active_mask_o = active_mask;
    assign masked_reference_o = masked_reference;
    assign reference_pattern_o = reference_pattern;
endmodule

module pixel_pattern_monitor #(
    parameter integer LANES = 16,
    parameter integer WORD_W = 64,
    parameter integer DEPTH = 4
) (
    input wire clk,
    input wire ce,
    input wire i_ce,
    input wire end_frame,
    input wire [(LANES*WORD_W)-1:0] shade_operands,
    input wire [(LANES*WORD_W)-1:0] texture_operands,
    input wire peer_valid,
    input wire [(LANES*WORD_W)-1:0] peer_terms,
    input wire cfg_load,
    input wire [WORD_W-1:0] cfg_mask,
    input wire [WORD_W-1:0] cfg_reference,
    output wire cfg_ready,
    output wire issue_ready,
    output wire peer_ready,
    output wire a_peer_ready,
    output wire [WORD_W-1:0] accumulated_value,
    output wire [WORD_W-1:0] peer_accumulated_value,
    output wire peer_nonzero_issued,
    output wire a_staged_valid,
    output wire [WORD_W-1:0] a_peer_running_sum,
    output wire a_peer_seen_nonzero_issue,
    output wire a_pending_nonzero,
    output wire [WORD_W-1:0] a_running_sum,
    output wire a_seen_nonzero_issue,
    output wire a_stage_owner,
    output wire match_flag,
    output wire masked_error,
    output wire armed,
    output wire [WORD_W-1:0] b_active_mask,
    output wire [WORD_W-1:0] b_masked_reference,
    output wire [WORD_W-1:0] b_reference_pattern,
    output wire [(DEPTH*WORD_W)-1:0] buffered_sums,
    output reg [$clog2(DEPTH+1)-1:0] fifo_count,
    output reg [$clog2(DEPTH)-1:0] fifo_rd_ptr,
    output reg [$clog2(DEPTH)-1:0] fifo_wr_ptr,
    output wire [$clog2(DEPTH+1):0] reserved_credits,
    output reg capture_valid,
    output reg monitor_valid,
    output reg [1:0] control_state,
    output reg [WORD_W-1:0] saved_cfg_mask,
    output reg [WORD_W-1:0] saved_cfg_reference,
    output wire fifo_push,
    output wire fifo_pop,
    output wire cfg_apply
);
    localparam integer PTR_W = $clog2(DEPTH);
    localparam integer COUNT_W = $clog2(DEPTH+1);
    localparam [1:0] WAIT_CFG=2'd0, DRAIN=2'd1,
                     WARM=2'd2, RUN=2'd3;
    reg [WORD_W-1:0] sample_fifo [0:DEPTH-1];
    wire staged_peer = a_staged_valid && a_stage_owner;
    wire peer_commit = ce && staged_peer;
    wire b_cfg_load;
    wire admit_peer;
    wire cfg_accept = cfg_load && cfg_ready;
    wire [WORD_W-1:0] monitor_pixel =
        (fifo_count != 0) ? sample_fifo[fifo_rd_ptr] : {WORD_W{1'b0}};

    // Reserve storage when a request starts, not when its sum appears.
    assign reserved_credits = {1'b0, fifo_count} +
        {{COUNT_W{1'b0}}, capture_valid} +
        {{COUNT_W{1'b0}}, staged_peer};
    assign admit_peer = (control_state == RUN) && armed &&
        !cfg_load && (reserved_credits < DEPTH);
    assign peer_ready = a_peer_ready && admit_peer;
    assign cfg_ready = i_ce &&
        ((control_state == WAIT_CFG) || (control_state == RUN));
    assign b_cfg_load = (control_state == DRAIN) && (reserved_credits == 0);
    assign cfg_apply = i_ce && b_cfg_load;
    assign fifo_push = capture_valid;
    assign fifo_pop = i_ce && !b_cfg_load && (fifo_count != 0);

    pixel_dot_accumulator #(.LANES(LANES), .WORD_W(WORD_W)) source (
        .clk(clk), .ce(ce), .end_frame(end_frame),
        .shade_operands(shade_operands), .texture_operands(texture_operands),
        .peer_valid(peer_valid && admit_peer), .peer_terms(peer_terms),
        .accumulated_value(accumulated_value),
        .peer_accumulated_value(peer_accumulated_value),
        .issue_ready(issue_ready), .peer_ready(a_peer_ready),
        .peer_nonzero_issued(peer_nonzero_issued),
        .staged_valid(a_staged_valid),
        .peer_running_sum_o(a_peer_running_sum),
        .peer_seen_nonzero_issue_o(a_peer_seen_nonzero_issue),
        .pending_nonzero_o(a_pending_nonzero),
        .running_sum_o(a_running_sum),
        .seen_nonzero_issue_o(a_seen_nonzero_issue), .stage_owner_o(a_stage_owner)
    );
    camera_mask_classifier #(.WORD_BITS(WORD_W)) sink (
        .clk(clk), .i_ce(i_ce), .cfg_load(b_cfg_load),
        .cfg_mask(saved_cfg_mask), .cfg_reference(saved_cfg_reference),
        .pixel_word(monitor_pixel), .match_flag(match_flag),
        .masked_error(masked_error), .armed(armed),
        .active_mask_o(b_active_mask),
        .masked_reference_o(b_masked_reference),
        .reference_pattern_o(b_reference_pattern)
    );

    genvar slot;
    generate
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin : sample_outputs
            assign buffered_sums[slot*WORD_W +: WORD_W] = sample_fifo[slot];
        end
    endgenerate

    integer init_slot;
    initial begin
        fifo_count = {COUNT_W{1'b0}};
        fifo_rd_ptr = {PTR_W{1'b0}};
        fifo_wr_ptr = {PTR_W{1'b0}};
        capture_valid = 1'b0;
        monitor_valid = 1'b0;
        control_state = WAIT_CFG;
        saved_cfg_mask = {WORD_W{1'b0}};
        saved_cfg_reference = {WORD_W{1'b0}};
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1)
            sample_fifo[init_slot] = {WORD_W{1'b0}};
    end

    always @(posedge clk) begin
        // The accumulator output holds a newly committed sum until this write.
        capture_valid <= peer_commit;
        monitor_valid <= fifo_pop;
        if (fifo_push) begin
            sample_fifo[fifo_wr_ptr] <= peer_accumulated_value;
            if (fifo_wr_ptr == DEPTH-1)
                fifo_wr_ptr <= {PTR_W{1'b0}};
            else
                fifo_wr_ptr <= fifo_wr_ptr + 1'b1;
        end
        if (fifo_pop) begin
            if (fifo_rd_ptr == DEPTH-1)
                fifo_rd_ptr <= {PTR_W{1'b0}};
            else
                fifo_rd_ptr <= fifo_rd_ptr + 1'b1;
        end
        case ({fifo_push, fifo_pop})
            2'b10: fifo_count <= fifo_count + 1'b1;
            2'b01: fifo_count <= fifo_count - 1'b1;
            default: begin end
        endcase

        case (control_state)
            WAIT_CFG, RUN: begin
                if (cfg_accept) begin
                    saved_cfg_mask <= cfg_mask;
                    saved_cfg_reference <= cfg_reference;
                    control_state <= DRAIN;
                end
            end
            DRAIN: begin
                if (cfg_apply)
                    control_state <= WARM;
            end
            WARM: begin
                if (i_ce)
                    control_state <= RUN;
            end
            default: control_state <= WAIT_CFG;
        endcase
    end

    // Valid classifications use the current configuration, never a reload.
    always @(posedge clk) begin
        if (monitor_valid && (b_masked_reference == {WORD_W{1'b0}}))
            assert (!masked_error || a_peer_seen_nonzero_issue);
    end
endmodule

module wave_prefetch_set_guard #(
    parameter integer SETS = 4,
    parameter integer SLOTS = 64,
    parameter integer SLOT_W = $clog2(SLOTS),
    parameter integer SET_W = $clog2(SETS)
) (
    input wire clk,
    input wire [SET_W-1:0] request_set,
    input wire [SLOT_W-1:0] alloc_slot,
    input wire reserve,
    input wire retire,
    input wire [SLOT_W-1:0] retire_slot,
    output wire request_ready,
    output reg [SETS-1:0] busy,
    output wire [SETS*SLOT_W-1:0] slots,
    output reg retire_found,
    output reg [SET_W-1:0] retire_set
);
    reg [SLOT_W-1:0] owner_slot [0:SETS-1];
    integer scan;
    integer update;

    initial begin
        busy = {SETS{1'b0}};
    end
    genvar entry;
    generate
        for (entry = 0; entry < SETS; entry = entry + 1) begin : reservation_view
            initial begin
                owner_slot[entry] = {SLOT_W{1'b0}};
            end
            assign slots[entry*SLOT_W +: SLOT_W] = owner_slot[entry];
        end
    endgenerate

    assign request_ready = !busy[request_set];
    always @(*) begin
        retire_found = 1'b0;
        retire_set = {SET_W{1'b0}};
        for (scan = 0; scan < SETS; scan = scan + 1) begin
            if (busy[scan] && owner_slot[scan] == retire_slot) begin
                retire_found = 1'b1;
                retire_set = scan;
            end
        end
    end

    always @(posedge clk) begin
        for (update = 0; update < SETS; update = update + 1) begin
            if (retire && busy[update] &&
                owner_slot[update] == retire_slot) begin
                busy[update] <= 1'b0;
            end
            if (reserve && request_set == update) begin
                busy[update] <= 1'b1;
                owner_slot[update] <= alloc_slot;
            end
        end
    end
endmodule

module wave_line_prefetcher #(
    parameter integer LINE_W = 8,
    parameter integer DEPTH = 64,
    parameter integer COUNT_W = 8,
    parameter integer HAZARD_SETS = 4
) (
    input  wire                  clk,
    input  wire                  miss_valid,
    output wire                  miss_ready,
    input  wire [LINE_W-1:0]     miss_line,
    output wire                  prefetch_valid,
    input  wire                  prefetch_ready,
output wire [LINE_W-1:0]     prefetch_line,
input  wire                  peer_miss_valid,
output wire                  peer_miss_ready,
input  wire [LINE_W-1:0]     peer_miss_line,
output wire                  prefetch_peer,
output wire [HAZARD_SETS-1:0] hazard_busy,
output wire [HAZARD_SETS*$clog2(DEPTH)-1:0] hazard_slots
);
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [LINE_W-1:0] LINE_ZERO = {LINE_W{1'b0}};
    localparam [LINE_W-1:0] LINE_ONE = {{(LINE_W-1){1'b0}}, 1'b1};
localparam integer CHANNELS = 2, PEER_DEPTH = 4;
localparam integer PEER_PTR_W = $clog2(PEER_DEPTH), PEER_COUNT_W = $clog2(PEER_DEPTH+1);

    reg [LINE_W-1:0] prefetch_q [0:DEPTH-1];
    reg [COUNT_W-1:0] wr_ptr;
    reg [COUNT_W-1:0] rd_ptr;
    reg [COUNT_W-1:0] used;
    reg [LINE_W-1:0] last_miss;
    reg pv;
reg [LINE_W-1:0] peer_q [0:PEER_DEPTH-1];
reg [PEER_PTR_W-1:0] peer_wr, peer_rd;
reg [PEER_COUNT_W-1:0] peer_used;
reg output_locked;
reg [$clog2(CHANNELS)-1:0] output_owner, output_turn;

    initial begin
        wr_ptr = COUNT_ZERO;
        rd_ptr = COUNT_ZERO;
        used = COUNT_ZERO;
        last_miss = {LINE_W{1'b1}};
        pv = 1'b0;
peer_wr = 0; peer_rd = 0; peer_used = 0;
output_locked = 1'b0; output_owner = 1'b0; output_turn = 1'b0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : initialize_queue
            initial prefetch_q[g] = LINE_ZERO;
        end
for (g = 0; g < PEER_DEPTH; g = g + 1) begin : initialize_peer
    initial peer_q[g] = LINE_ZERO;
end
    endgenerate

    assign miss_ready = (used < CAPACITY) && hazard_ready;
assign peer_miss_ready = (peer_used < PEER_DEPTH);
assign prefetch_peer = output_locked ? output_owner :
    ((peer_used != 0) && ((used == COUNT_ZERO) || output_turn));
assign prefetch_valid = prefetch_peer ? (peer_used != 0) : (used != COUNT_ZERO);
assign prefetch_line = prefetch_peer ? peer_q[peer_rd] : prefetch_q[rd_ptr];

    wire push = miss_valid && miss_ready;
wire pop = prefetch_valid && prefetch_ready && !prefetch_peer;
wire peer_push = peer_miss_valid && peer_miss_ready;
wire peer_pop = prefetch_valid && prefetch_ready && prefetch_peer;
    localparam integer HAZARD_SET_W = $clog2(HAZARD_SETS);
    localparam integer HAZARD_SLOT_W = $clog2(DEPTH);
    wire [LINE_W-1:0] requested_line = miss_line + LINE_ONE;
    wire hazard_ready;
    wire hazard_retire_found;
    wire [HAZARD_SET_W-1:0] hazard_retire_set;
    wire [HAZARD_SLOT_W-1:0] hazard_slot [0:HAZARD_SETS-1];
    wire [COUNT_W-1:0] hazard_distance [0:HAZARD_SETS-1];
    genvar h;
    generate
        for (h = 0; h < HAZARD_SETS; h = h + 1) begin : reservation_decode
            assign hazard_slot[h] = hazard_slots[h*HAZARD_SLOT_W +: HAZARD_SLOT_W];
            assign hazard_distance[h] = (hazard_slot[h] >= rd_ptr) ?
                (hazard_slot[h] - rd_ptr) :
                (CAPACITY - rd_ptr + hazard_slot[h]);
        end
    endgenerate
    wave_prefetch_set_guard #(
        .SETS(HAZARD_SETS),
        .SLOTS(DEPTH)
    ) set_guard (
        .clk(clk),
        .request_set(requested_line[HAZARD_SET_W-1:0]),
        .alloc_slot(wr_ptr[HAZARD_SLOT_W-1:0]),
        .reserve(push),
        .retire(pop),
        .retire_slot(rd_ptr[HAZARD_SLOT_W-1:0]),
        .request_ready(hazard_ready),
        .busy(hazard_busy),
        .slots(hazard_slots),
        .retire_found(hazard_retire_found),
        .retire_set(hazard_retire_set)
    );

    // The slot immediately preceding the write pointer retains the
    // most recently generated next-line request, even after retirement.
    wire [COUNT_W-1:0] latest_slot =
        (wr_ptr == COUNT_ZERO) ? LAST_SLOT : (wr_ptr - COUNT_ONE);
    wire [LINE_W-1:0] latest_line = prefetch_q[latest_slot];

    always @(posedge clk) begin
        if (push) begin
            prefetch_q[wr_ptr] <= miss_line + LINE_ONE;
            last_miss <= miss_line;
            wr_ptr <= (wr_ptr == LAST_SLOT) ? COUNT_ZERO : (wr_ptr + COUNT_ONE);
        end
        if (pop)
            rd_ptr <= (rd_ptr == LAST_SLOT) ? COUNT_ZERO : (rd_ptr + COUNT_ONE);

        if (push && !pop)
            used <= used + COUNT_ONE;
        else if (pop && !push)
            used <= used - COUNT_ONE;

        // No history check is needed before the first transaction.
        // Keeping this update transaction-gated preserves complete idle.
        if (push || pop)
            pv <= 1'b1;
    end

always @(posedge clk) begin
    if (peer_push) begin
        peer_q[peer_wr] <= peer_miss_line + LINE_ONE;
        peer_wr <= (peer_wr == PEER_DEPTH-1) ? 0 : peer_wr + 1'b1;
    end
    if (peer_pop) peer_rd <= (peer_rd == PEER_DEPTH-1) ? 0 : peer_rd + 1'b1;
    if (peer_push && !peer_pop) peer_used <= peer_used + 1'b1;
    else if (peer_pop && !peer_push) peer_used <= peer_used - 1'b1;
    if (prefetch_valid) begin
        output_locked <= !prefetch_ready;
        output_owner <= prefetch_peer;
        if (prefetch_ready) output_turn <= !prefetch_peer;
    end
end

    always @(posedge clk)
        if (pv && $stable(last_miss))
            assert ($stable(latest_line));

always @(posedge clk)
    if (output_locked && prefetch_ready)
        assert (prefetch_valid);

always @(posedge clk)
    if (pop)
        assert (hazard_retire_found &&
                hazard_retire_set == prefetch_line[HAZARD_SET_W-1:0]);
endmodule

module allpass_sample_queue #(
    parameter SLOTS = 4, LIMIT = 256,
    parameter AW = $clog2(LIMIT), CW = $clog2(SLOTS+1), IW = $clog2(LIMIT+1)
) (
    input wire clk, i_start, i_push, i_pop,
    input wire signed [31:0] i_sample,
    output wire signed [31:0] o_sample,
    output wire [AW-1:0] o_addr, output wire [SLOTS*AW-1:0] o_tags,
    output reg [CW-1:0] o_count, output reg [IW-1:0] o_issued
);
    reg signed [31:0] samples [0:SLOTS-1];
    reg [AW-1:0] tags [0:SLOTS-1];
    wire [CW-1:0] tail_slot = o_count - (i_pop ? 1'b1 : 1'b0);
    integer n;
    genvar g;
    assign o_sample = samples[0]; assign o_addr = tags[0];
    generate for (g = 0; g < SLOTS; g = g + 1) begin : export_tags
        assign o_tags[g*AW +: AW] = tags[g];
    end endgenerate
    initial begin
        o_count = 0; o_issued = 0;
        for (n = 0; n < SLOTS; n = n + 1) begin samples[n] = 32'sd0; tags[n] = 0; end
    end
    always @(posedge clk) begin
        if (i_start) begin o_count <= 0; o_issued <= 0; end
        else begin
            if (i_push != i_pop) o_count <= i_push ? o_count + 1'b1 : o_count - 1'b1;
            if (i_pop) for (n = 0; n < SLOTS-1; n = n + 1) begin
                samples[n] <= samples[n+1]; tags[n] <= tags[n+1];
            end
            if (i_push) begin
                samples[tail_slot] <= i_sample; tags[tail_slot] <= o_issued[AW-1:0];
                o_issued <= o_issued + 1'b1;
            end
        end
    end
endmodule
module video_allpass_sweep #(
    parameter [31:0] DEPTH = 32'd256,
    parameter [31:0] GAIN_SHIFT = 32'd1
) (
    input  wire               clk,
    input  wire               i_ce,
    input  wire               i_frame_sync,
    input  wire               i_block_start,
    input  wire signed [31:0] i_sample,
output reg  signed [31:0] o_sample,
output wire               o_block_ready,
output wire               o_sample_ready
);
    reg signed [31:0] delay_mem [0:DEPTH-32'd1];
    reg [31:0] ptr;
    reg [31:0] countdown;
    reg busy;
    reg armed;
    integer init_index;
    localparam QUEUE_SLOTS = 4, ADDR_W = $clog2(DEPTH);
    localparam COUNT_W = $clog2(QUEUE_SLOTS+1), ISSUE_W = $clog2(DEPTH+32'd1);
    localparam [ADDR_W-1:0] LAST_ADDR = DEPTH - 32'd1;
    wire [COUNT_W-1:0] queued_count;
    wire [ISSUE_W-1:0] queued_issued;
    wire [QUEUE_SLOTS*ADDR_W-1:0] queued_tags;
    wire [ADDR_W-1:0] queued_addr;
    wire signed [31:0] queued_sample;
    wire queue_pop, sweep_done;
    assign o_block_ready = i_ce && !busy;
    assign o_sample_ready = i_ce && busy && (queued_issued < DEPTH) && (queued_count < QUEUE_SLOTS);
    assign queue_pop = i_ce && busy && (queued_count != 0);
    assign sweep_done = queue_pop && (queued_addr == LAST_ADDR);
    allpass_sample_queue #(.SLOTS(QUEUE_SLOTS), .LIMIT(DEPTH)) sample_queue (
        .clk(clk), .i_start(o_block_ready && i_block_start),
        .i_push(o_sample_ready), .i_pop(queue_pop), .i_sample(i_sample),
        .o_sample(queued_sample), .o_addr(queued_addr), .o_tags(queued_tags),
        .o_count(queued_count), .o_issued(queued_issued));

    // Schroeder allpass with dyadic gain g = 2^(-GAIN_SHIFT):
    // y = delayed - g*x; delay_write = x + g*y.
    // Arithmetic shifts implement the fixed-point gain coefficient.
    wire signed [31:0] delayed_sample;
    wire signed [31:0] feedforward;
    wire signed [31:0] allpass_sample;
    wire signed [31:0] feedback;
    wire signed [31:0] delay_write;

assign delayed_sample = delay_mem[queued_addr];
assign feedforward = queued_sample >>> GAIN_SHIFT;
    assign allpass_sample = delayed_sample - feedforward;
    assign feedback = allpass_sample >>> GAIN_SHIFT;
assign delay_write = queued_sample + feedback;

    initial begin
        ptr = 32'd0;
        countdown = 32'd0;
        busy = 1'b0;
        armed = 1'b0;
        o_sample = 32'sd0;
        for (init_index = 32'd0; init_index < DEPTH;
             init_index = init_index + 32'd1)
            delay_mem[init_index] = 32'sd0;
    end

    // Each accepted block processes one complete circular-buffer sweep.
    // Countdown measures enabled processing cycles; i_ce freezes all state.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_frame_sync)
                armed <= 1'b1;

            if (!busy) begin
                if (i_block_start) begin
                    busy <= 1'b1;
                    ptr <= 32'd0;
                    countdown <= DEPTH;
                end
end else if (queue_pop) begin
                o_sample <= allpass_sample;
delay_mem[queued_addr] <= delay_write;

if (sweep_done) begin
                    ptr <= 32'd0;
                    countdown <= 32'd0;
                    busy <= 1'b0;
                end else begin
ptr <= queued_addr + 32'd1;
                    countdown <= countdown - 32'd1;
                end
            end
        end
    end

    // After the first enabled frame-sync event, an outstanding block
    // must never exhaust its processing-cycle deadline.
    assert property (!armed || !busy || (countdown != 32'd0));
endmodule

module duty_cycle_corrector #(
    parameter integer WORD_W = 64
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_high_ticks,
    input  wire [WORD_W-1:0]     in_low_ticks,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [WORD_W-1:0]     out_high_ticks,
    output reg  [WORD_W-1:0]     applied_high_time,
    input  wire                  peer_valid,
    output wire                  peer_ready,
    input  wire [WORD_W-1:0]     peer_high_ticks,
    input  wire [WORD_W-1:0]     peer_low_ticks,
    output reg                   peer_active,
    output reg  [3:0]            monitor_status
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] HALF_SCALE = {1'b1, {(WORD_W-1){1'b0}}};
    localparam integer CHANNELS = 2, PEER_DEPTH = 4;
    localparam integer PEER_PTR_W = $clog2(PEER_DEPTH), PEER_COUNT_W = $clog2(PEER_DEPTH+1);

    reg [WORD_W-1:0] high_shadow;
    reg [WORD_W-1:0] low_shadow;
    reg [WORD_W-1:0] correction_code;
    reg pending;
    reg armed;
    reg pv;
    reg [WORD_W-1:0] peer_high_q [0:PEER_DEPTH-1], peer_low_q [0:PEER_DEPTH-1];
    reg [PEER_PTR_W-1:0] peer_rd, peer_wr;
    reg [PEER_COUNT_W-1:0] peer_count;
    integer peer_idx;
    wire [CHANNELS-1:0] lane_valid = {peer_active, pending};

    // The code is a two's-complement adjustment in high-time units.
    // Halving each measured interval avoids overflowing the imbalance.
    wire [WORD_W-1:0] shadow_half_imbalance =
        (high_shadow >> ONE) - (low_shadow >> ONE);
    wire [WORD_W-1:0] reference_high =
        HALF_SCALE - shadow_half_imbalance;

    assign in_ready = !(|lane_valid);
    assign out_valid = |lane_valid;
    assign out_high_ticks = HALF_SCALE + correction_code;
    assign peer_ready = peer_count < PEER_DEPTH;

    wire take_measurement = in_valid && in_ready;
    wire apply_correction = pending && out_ready;
    wire enqueue_peer = peer_valid && peer_ready;
    wire finish_peer = peer_active && out_ready;
    wire start_peer = in_ready && !in_valid && (peer_count != 0);
    reg [15:0] mon_accept_count;
    reg [15:0] mon_finish_count;
    reg [7:0] mon_stall_run;
    reg [7:0] mon_stall_peak;
    reg [15:0] mon_watchdog;
    reg [PEER_COUNT_W-1:0] mon_queue_peak;
    initial begin
        mon_accept_count = 16'd0;
        mon_finish_count = 16'd0;
        mon_stall_run = 8'd0;
        mon_stall_peak = 8'd0;
        mon_watchdog = 16'd0;
        mon_queue_peak = 0;
        monitor_status = 4'b0000;
    end
    always @(posedge clk) begin
        if (take_measurement || enqueue_peer) begin
            mon_accept_count <= mon_accept_count
                + {15'd0, take_measurement} + {15'd0, enqueue_peer};
        end
        if (apply_correction || finish_peer) begin
            mon_finish_count <= mon_finish_count
                + {15'd0, apply_correction} + {15'd0, finish_peer};
        end
        if (out_valid && !out_ready) begin
            if (mon_stall_run != 8'hff)
                mon_stall_run <= mon_stall_run + 8'd1;
        end else begin
            mon_stall_run <= 8'd0;
        end
        if (mon_stall_run > mon_stall_peak)
            mon_stall_peak <= mon_stall_run;
        if (peer_count > mon_queue_peak)
            mon_queue_peak <= peer_count;
        if ((mon_accept_count == mon_finish_count) ||
            apply_correction || finish_peer) begin
            mon_watchdog <= 16'd0;
        end else if (mon_watchdog != 16'hffff) begin
            mon_watchdog <= mon_watchdog + 16'd1;
        end
        monitor_status[0] <= mon_accept_count != mon_finish_count;
        monitor_status[1] <= mon_stall_peak >= 8'd32;
        monitor_status[2] <= mon_queue_peak == PEER_DEPTH;
        monitor_status[3] <= mon_watchdog >= 16'd1024;
    end

    initial begin
        high_shadow = ZERO;
        low_shadow = ZERO;
        correction_code = ZERO;
        applied_high_time = HALF_SCALE;
        pending = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
        peer_rd = 0; peer_wr = 0;
        peer_count = 0; peer_active = 1'b0;
        for (peer_idx = 0; peer_idx < PEER_DEPTH; peer_idx = peer_idx + 1)
            {peer_high_q[peer_idx], peer_low_q[peer_idx]} = {ZERO, ZERO};
    end

    always @(posedge clk) begin
        if (take_measurement || start_peer)
            correction_code <= ((start_peer ? peer_low_q[peer_rd] : in_low_ticks) >> ONE)
                             - ((start_peer ? peer_high_q[peer_rd] : in_high_ticks) >> ONE);
        if (enqueue_peer) begin
            {peer_high_q[peer_wr], peer_low_q[peer_wr]} <= {peer_high_ticks, peer_low_ticks};
            peer_wr <= peer_wr + 1'b1;
        end
        if (start_peer || finish_peer) peer_active <= start_peer;
        if (finish_peer) peer_rd <= peer_rd + 1'b1;
        case ({enqueue_peer, finish_peer})
            2'b10: peer_count <= peer_count + 1'b1;
            2'b01: peer_count <= peer_count - 1'b1;
        endcase
        if (take_measurement) begin
            high_shadow <= in_high_ticks;
            low_shadow <= in_low_ticks;
            pending <= 1'b1;
            // Q: the first accepted duty-cycle measurement.
            armed <= 1'b1;
        end

        if (apply_correction) begin
            applied_high_time <= out_high_ticks;
            pending <= 1'b0;
        end

        // No checker state changes during an idle cycle either.
        if (take_measurement || apply_correction)
            pv <= 1'b1;
    end
    always @(posedge clk)
        if (peer_active && out_ready)
            assert (!pending && (out_high_ticks == HALF_SCALE - ((peer_high_q[peer_rd] >> ONE) - (peer_low_q[peer_rd] >> ONE))));

    // Once armed, a committed setting must agree with the measurement
    // shadows that already existed in the previous cycle.
    always @(posedge clk)
        if (pv && armed && !pending)
            assert (applied_high_time == $past(reference_high));
endmodule

module stretch_config_queue #(
    parameter integer WIDTH = 32, DEPTH = 4,
    parameter integer PTR_WIDTH = $clog2(DEPTH), COUNT_WIDTH = $clog2(DEPTH+1)
) (
    input wire clk, rst_n, ce, valid,
    input wire [WIDTH-1:0] data, measured,
    output wire ready, preparing,
    output reg apply,
    output reg [WIDTH-1:0] limit,
    output reg [COUNT_WIDTH-1:0] queued
);
    reg [WIDTH-1:0] entries [0:DEPTH-1];
    reg [PTR_WIDTH-1:0] rd, wr;
    integer k;
    wire push = valid && ready;
    assign ready = ce && (queued < DEPTH);
    assign preparing = !apply && (queued != 0);
    initial begin
        rd = 0; wr = 0; queued = 0; apply = 0; limit = 0;
        for (k = 0; k < DEPTH; k = k + 1) entries[k] = 0;
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rd <= 0; wr <= 0; queued <= 0; apply <= 0; limit <= 0;
            for (k = 0; k < DEPTH; k = k + 1) entries[k] <= 0;
        end else if (ce) begin
            apply <= preparing;
            if (push) begin
                entries[wr] <= data;
                wr <= (wr == DEPTH-1) ? 0 : wr + 1'b1;
            end
            if (preparing) begin
                limit <= (entries[rd] < measured) ? measured : entries[rd];
                rd <= (rd == DEPTH-1) ? 0 : rd + 1'b1;
            end
            case ({push, preparing})
                2'b10: queued <= queued + 1'b1;
                2'b01: queued <= queued - 1'b1;
                default: queued <= queued;
            endcase
        end
    end
endmodule
module i2c_stretch_handler #(
    parameter integer COUNTER_WIDTH = 32,
    parameter [COUNTER_WIDTH-1:0] RESET_MAX_STRETCH = 32'd8,
    parameter integer CONFIG_DEPTH = 4
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire request_high,
    input wire scl_in,
    input wire config_valid,
    input wire [COUNTER_WIDTH-1:0] config_max_stretch,
    output wire scl_release,
    output wire high_phase_done,
    output reg high_pending,
    output reg stretching_active,
    output reg stretch_timeout,
    output reg [COUNTER_WIDTH-1:0] stretch_duration,
    output reg [COUNTER_WIDTH-1:0] max_stretch,
    output wire config_ready,
    output wire request_ready,
    output wire [$clog2(CONFIG_DEPTH+1)-1:0] config_queued
);
    localparam [COUNTER_WIDTH-1:0] COUNT_ZERO = {COUNTER_WIDTH{1'b0}};
    localparam [COUNTER_WIDTH-1:0] COUNT_ONE = {{(COUNTER_WIDTH-1){1'b0}}, 1'b1};
    reg past_valid;
    wire cfg_apply, cfg_prepare;
    wire [COUNTER_WIDTH-1:0] cfg_limit;
    stretch_config_queue #(.WIDTH(COUNTER_WIDTH), .DEPTH(CONFIG_DEPTH)) config_queue (
        .clk(clk), .rst_n(rst_n), .ce(i_ce), .valid(config_valid),
        .data(config_max_stretch), .measured(stretch_duration), .ready(config_ready),
        .preparing(cfg_prepare), .apply(cfg_apply), .limit(cfg_limit), .queued(config_queued)
    );
    assign request_ready = i_ce && !high_pending && !cfg_apply;

    initial begin
        high_pending = 1'b0;
        stretching_active = 1'b0;
        stretch_timeout = 1'b0;
        stretch_duration = COUNT_ZERO;
        max_stretch = RESET_MAX_STRETCH;
        past_valid = 1'b0;
    end

    // Release the open-drain SCL output throughout the pending high phase.
    // Even a timeout does not end that phase before the slave releases SCL.
    assign scl_release = high_pending;
    assign high_phase_done = high_pending && scl_in;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            high_pending <= 1'b0;
            stretching_active <= 1'b0;
            stretch_timeout <= 1'b0;
            stretch_duration <= COUNT_ZERO;
            max_stretch <= RESET_MAX_STRETCH;
            past_valid <= 1'b0;
        end else if (i_ce) begin
            past_valid <= 1'b1;
            if (!high_pending) begin
                stretching_active <= 1'b0;
                if (cfg_apply) begin
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end else if (request_high) begin
                    high_pending <= 1'b1;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end
            end else if (scl_in) begin
                high_pending <= 1'b0;
                stretching_active <= 1'b0;
            end else begin
                stretching_active <= 1'b1;
                // Saturate the duration at the programmed stretch budget.
                if (!cfg_prepare && !cfg_apply) begin
                if (stretch_duration < max_stretch) begin
                    stretch_duration <= stretch_duration + COUNT_ONE;
                    if ((stretch_duration + COUNT_ONE) == max_stretch)
                        stretch_timeout <= 1'b1;
                end else begin
                    stretch_timeout <= 1'b1;
                end
                end
            end
            if (cfg_apply) begin
                max_stretch <= cfg_limit;
                stretch_timeout <= high_pending && !scl_in && (stretch_duration >= cfg_limit);
            end
        end
    end

    always @(posedge clk)
        if (past_valid && $rose(stretch_timeout))
            assert (stretch_duration == max_stretch);
endmodule

module sklansky_result_channel #(
    parameter integer WIDTH = 32
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [WIDTH-1:0]     in_a,
    input  wire [WIDTH-1:0]     in_b,
    output wire                 out_valid,
    input  wire                 out_ready,
    output wire [WIDTH-1:0]     out_sum,
    output wire                 out_carry
,
    output wire [WIDTH-1:0] operand_a_o,
    output wire [WIDTH-1:0] operand_b_o,
    output wire [WIDTH-1:0] prefix_hold_o,
    output wire [WIDTH-1:0] propagate_hold_o
);
    localparam integer LEVELS = $clog2(WIDTH);

    // Two storage slots: a captured-prefix tail and a reconstructed front.
    reg pending;
    reg window;
    reg [WIDTH-1:0] operand_a, operand_b;
    reg [WIDTH-1:0] propagate_hold, prefix_hold;
    reg [WIDTH-1:0] result_a, result_b;
    reg [WIDTH-1:0] result_sum;
    reg result_carry;

    wire [WIDTH-1:0] tree_g [0:LEVELS];
    wire [WIDTH-1:0] tree_p [0:LEVELS];

    assign tree_g[0] = in_a & in_b;
    assign tree_p[0] = in_a ^ in_b;

    // Sklansky tree: each upper half shares the lower half's root.
    genvar level, bit_index;
    generate
        for (level = 0; level < LEVELS; level = level + 1) begin : prefix_level
            localparam integer HALF = 1 << level;
            localparam integer GROUP = HALF << 1;
            for (bit_index = 0; bit_index < WIDTH; bit_index = bit_index + 1) begin : prefix_bit
                if ((bit_index % GROUP) >= HALF) begin : combine
                    localparam integer ROOT = (bit_index / GROUP) * GROUP + HALF - 1;
                    assign tree_g[level+1][bit_index] =
                        tree_g[level][bit_index] |
                        (tree_p[level][bit_index] & tree_g[level][ROOT]);
                    assign tree_p[level+1][bit_index] =
                        tree_p[level][bit_index] & tree_p[level][ROOT];
                end else begin : bypass
                    assign tree_g[level+1][bit_index] = tree_g[level][bit_index];
                    assign tree_p[level+1][bit_index] = tree_p[level][bit_index];
                end
            end
        end
    endgenerate

    wire [WIDTH-1:0] pending_sum;
    wire pending_carry;
    assign pending_sum = propagate_hold ^ (prefix_hold << 1);
    assign pending_carry = prefix_hold[WIDTH-1];

    // A lone prefix-slot item is directly visible: valid never waits for ready.
    assign out_valid = window || pending;
    assign out_sum = window ? result_sum : pending_sum;
    assign out_carry = window ? result_carry : pending_carry;
    assign in_ready = !(window && pending) || out_ready;

    wire push;
    wire pop;
    wire promote;
    assign push = in_valid && in_ready;
    assign pop = out_valid && out_ready;

    // Promote the tail when removing an occupied front, or when an arriving
    // item needs the occupied tail slot and the front is empty.
    assign promote = pending && ((pop && window) || (push && !pop));

    wire [WIDTH:0] reference_sum;
    assign reference_sum = window
        ? ({1'b0, result_a} + {1'b0, result_b})
        : ({1'b0, operand_a} + {1'b0, operand_b});

    initial begin
        pending = 1'b0;
        window = 1'b0;
        operand_a = {WIDTH{1'b0}};
        operand_b = {WIDTH{1'b0}};
        propagate_hold = {WIDTH{1'b0}};
        prefix_hold = {WIDTH{1'b0}};
        result_a = {WIDTH{1'b0}};
        result_b = {WIDTH{1'b0}};
        result_sum = {WIDTH{1'b0}};
        result_carry = 1'b0;
    end

    // Every register holds when in_valid and out_ready are both low.
    always @(posedge clk) begin
        if (pop) begin
            pending <= 1'b0;
            window <= 1'b0;
        end

        if (promote) begin
            result_a <= operand_a;
            result_b <= operand_b;
            result_sum <= pending_sum;
            result_carry <= pending_carry;
            window <= 1'b1;
        end

        if (push) begin
            operand_a <= in_a;
            operand_b <= in_b;
            propagate_hold <= tree_p[0];
            prefix_hold <= tree_g[LEVELS];
            pending <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (out_valid)
            assert ({out_carry, out_sum} == reference_sum);
    end
    assign operand_a_o = operand_a;
    assign operand_b_o = operand_b;
    assign prefix_hold_o = prefix_hold;
    assign propagate_hold_o = propagate_hold;
endmodule

module signed_alu_retirement #(
    parameter integer DATA_W = 64
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [DATA_W-1:0]     in_a,
    input  wire [DATA_W-1:0]     in_b,
    input  wire                  in_sub,
    input  wire                  in_checkpoint,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [DATA_W-1:0]     out_result,
    output wire                  out_carry,
    output wire                  out_overflow
,
    output wire [DATA_W-1:0] req_a_o,
    output wire [DATA_W-1:0] req_b_o,
    output wire req_eligible_o,
    output wire req_sub_o
);
    reg                          req_valid;
    reg [DATA_W-1:0]             req_a, req_b;
    reg                          req_sub;
    // Shadow of the operand-sign eligibility observed at acceptance.
    reg                          req_eligible;

    // Sticky record of the most recently retired operation.
    reg                          retired_seen;
    reg                          retired_overflow;
    reg                          retired_prior_eligible;
    reg                          before_checkpoint;

    initial begin
        req_valid = 1'b0;
        req_a = {DATA_W{1'b0}};
        req_b = {DATA_W{1'b0}};
        req_sub = 1'b0;
        req_eligible = 1'b1;
        retired_seen = 1'b0;
        retired_overflow = 1'b0;
        retired_prior_eligible = 1'b0;
        before_checkpoint = 1'b1;
    end

    assign out_valid = req_valid;
    assign in_ready = !req_valid || out_ready;
    wire accept = in_valid && in_ready;
    wire retire = out_valid && out_ready;

    // Stateless adder-subtractor: complement B and inject the mode as carry-in.
    wire [DATA_W-1:0] effective_b = req_b ^ {DATA_W{req_sub}};
    wire [DATA_W:0] arithmetic_sum =
        {1'b0, req_a} + {1'b0, effective_b}
        + {{DATA_W{1'b0}}, req_sub};
    assign out_result = arithmetic_sum[DATA_W-1:0];
    assign out_carry = arithmetic_sum[DATA_W];
    assign out_overflow =
        !(req_a[DATA_W-1] ^ effective_b[DATA_W-1]) &&
         (out_result[DATA_W-1] ^ req_a[DATA_W-1]);

    always @(posedge clk) begin
        if (retire) begin
            req_valid <= 1'b0;
            retired_seen <= 1'b1;
            retired_overflow <= out_overflow;
            retired_prior_eligible <= req_eligible;
        end
        // Simultaneous retirement and acceptance replace the occupied slot.
        if (accept) begin
            req_valid <= 1'b1;
            req_a <= in_a;
            req_b <= in_b;
            req_sub <= in_sub;
            req_eligible <= !(in_a[DATA_W-1] ^ in_b[DATA_W-1] ^ in_sub);
            // The first accepted checkpoint permanently ends the scope.
            if (in_checkpoint)
                before_checkpoint <= 1'b0;
        end
    end

    // Before the first checkpoint, a recorded overflow must have been
    // preceded by acceptance of sign-eligible operands.
    always @(*) assert (
        !(before_checkpoint && retired_seen && retired_overflow)
        || retired_prior_eligible
    );
    assign req_a_o = req_a;
    assign req_b_o = req_b;
    assign req_eligible_o = req_eligible;
    assign req_sub_o = req_sub;
endmodule

module ternary_retirement_channel #(
    parameter integer WIDTH = 32
) (
    input  wire clk,
    input  wire in_valid,
    output wire in_ready,
    input  wire [WIDTH-1:0] in_a,
    input  wire [WIDTH-1:0] in_b,
    input  wire [WIDTH-1:0] in_c,
    input  wire in_sub,
    input  wire in_checkpoint,
    output wire out_valid,
    input  wire out_ready,
    output wire [WIDTH-1:0] out_result,
    output wire out_carry,
    output wire out_overflow,
    output wire [WIDTH+1:0] out_extended,
    output wire out_checkpoint,
    output wire [WIDTH-1:0] a_operand_a_o,
    output wire [WIDTH-1:0] a_operand_b_o,
    output wire [WIDTH-1:0] a_prefix_hold_o,
    output wire [WIDTH-1:0] a_propagate_hold_o,
    output wire [WIDTH-1:0] b_req_a_o,
    output wire [WIDTH-1:0] b_req_b_o,
    output wire b_req_eligible_o,
    output wire b_req_sub_o
);
    localparam integer DEPTH = 4;
    localparam integer INDEX_W = $clog2(DEPTH);
    localparam integer PTR_W = INDEX_W + 1;

    // Reserve before starting the prefix operation; reclaim at retirement.
    // Each cursor includes a wrap phase so all four entries remain usable.
    reg [PTR_W-1:0] alloc_seq, fill_seq, send_seq, retire_seq;
    reg [WIDTH-1:0] third_q [0:DEPTH-1];
    reg [WIDTH-1:0] sum_q [0:DEPTH-1];
    reg sub_q [0:DEPTH-1];
    reg checkpoint_q [0:DEPTH-1];
    reg carry_q [0:DEPTH-1];

    wire [INDEX_W-1:0] alloc_index = alloc_seq[INDEX_W-1:0];
    wire [INDEX_W-1:0] fill_index = fill_seq[INDEX_W-1:0];
    wire [INDEX_W-1:0] send_index = send_seq[INDEX_W-1:0];
    wire [INDEX_W-1:0] retire_index = retire_seq[INDEX_W-1:0];

    wire [PTR_W-1:0] live_count = alloc_seq - retire_seq;
    wire [PTR_W-1:0] complete_count = fill_seq - retire_seq;
    wire [PTR_W-1:0] issue_count = send_seq - retire_seq;
    wire [PTR_W-1:0] await_sum_count = alloc_seq - fill_seq;
    wire [PTR_W-1:0] ready_count = fill_seq - send_seq;

    wire have_credit = live_count < DEPTH;
    wire a_in_ready, a_out_valid, a_out_ready;
    wire [WIDTH-1:0] a_out_sum;
    wire a_out_carry;
    wire a_in_valid = in_valid && have_credit;
    assign in_ready = a_in_ready && have_credit;
    assign a_out_ready = await_sum_count != 0;
    wire input_accept = in_valid && in_ready;
    wire collect = a_out_valid && a_out_ready;

    sklansky_result_channel #(.WIDTH(WIDTH)) sum_stage (
        .clk(clk), .in_valid(a_in_valid), .in_ready(a_in_ready),
        .in_a(in_a), .in_b(in_b),
        .out_valid(a_out_valid), .out_ready(a_out_ready),
        .out_sum(a_out_sum), .out_carry(a_out_carry),
        .operand_a_o(a_operand_a_o), .operand_b_o(a_operand_b_o),
        .prefix_hold_o(a_prefix_hold_o),
        .propagate_hold_o(a_propagate_hold_o)
    );

    wire b_in_ready;
    wire b_in_valid = ready_count != 0;
    wire b_accept = b_in_valid && b_in_ready;
    wire retire = out_valid && out_ready;
    signed_alu_retirement #(.DATA_W(WIDTH)) retire_stage (
        .clk(clk), .in_valid(b_in_valid), .in_ready(b_in_ready),
        .in_a(sum_q[send_index]), .in_b(third_q[send_index]),
        .in_sub(sub_q[send_index]),
        .in_checkpoint(checkpoint_q[send_index]),
        .out_valid(out_valid), .out_ready(out_ready),
        .out_result(out_result), .out_carry(out_carry),
        .out_overflow(out_overflow),
        .req_a_o(b_req_a_o), .req_b_o(b_req_b_o),
        .req_eligible_o(b_req_eligible_o), .req_sub_o(b_req_sub_o)
    );

    // Combine the prefix carry with the ALU carry or subtraction borrow.
    // Negative unsigned-operand differences use WIDTH+2-bit two's complement.
    wire [1:0] carry_adjust = sub_q[retire_index]
        ? (out_carry ? 2'b00 : 2'b11) : {1'b0, out_carry};
    wire [1:0] upper_result =
        {1'b0, carry_q[retire_index]} + carry_adjust;
    assign out_extended = {upper_result, out_result};
    assign out_checkpoint = checkpoint_q[retire_index];
    wire [WIDTH+1:0] extended_base =
        {1'b0, carry_q[retire_index], sum_q[retire_index]};
    wire [WIDTH+1:0] extended_third = {2'b00, third_q[retire_index]};
    wire [WIDTH+1:0] extended_reference = sub_q[retire_index]
        ? extended_base - extended_third : extended_base + extended_third;

    integer i;
    initial begin
        alloc_seq = {PTR_W{1'b0}};
        fill_seq = {PTR_W{1'b0}};
        send_seq = {PTR_W{1'b0}};
        retire_seq = {PTR_W{1'b0}};
        for (i = 0; i < DEPTH; i = i + 1) begin
            third_q[i] = {WIDTH{1'b0}};
            sum_q[i] = {WIDTH{1'b0}};
            sub_q[i] = 1'b0;
            checkpoint_q[i] = 1'b0;
            carry_q[i] = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (input_accept) begin
            third_q[alloc_index] <= in_c;
            sub_q[alloc_index] <= in_sub;
            checkpoint_q[alloc_index] <= in_checkpoint;
            alloc_seq <= alloc_seq + 1'b1;
        end
        if (collect) begin
            sum_q[fill_index] <= a_out_sum;
            carry_q[fill_index] <= a_out_carry;
            fill_seq <= fill_seq + 1'b1;
        end
        if (b_accept)
            send_seq <= send_seq + 1'b1;
        if (retire)
            retire_seq <= retire_seq + 1'b1;
    end

    always @(posedge clk) begin
        if (out_valid)
            assert (out_extended == extended_reference);
    end
endmodule

module i2c_stretch_watchdog #(
    parameter integer WIDTH = 32,
    parameter integer PERIOD = 4,
    parameter integer FILTER = 4,
    parameter [WIDTH-1:0] RESET_BUDGET = 32'd8
) (
    input wire clk, rst_n, ce, pending, scl_in, config_valid,
    input wire [WIDTH-1:0] budget, config_budget,
    output wire debit,
    output reg [WIDTH-1:0] remaining,
    output reg [$clog2(PERIOD)-1:0] phase,
    output reg [$clog2(FILTER)-1:0] qualification
);
    initial begin
        remaining = RESET_BUDGET;
        phase = 0;
        qualification = 0;
    end
    assign debit = ce && pending && !scl_in &&
                   (phase == PERIOD-1) && (qualification == FILTER-1);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            remaining <= RESET_BUDGET;
            phase <= 0;
            qualification <= 0;
        end else if (ce) begin
            if (!pending) begin
                remaining <= config_valid ? config_budget : budget;
                phase <= 0;
                qualification <= 0;
            end else if (!scl_in) begin
                if (phase == PERIOD-1) begin
                    phase <= 0;
                    if (qualification != FILTER-1)
                        qualification <= qualification + 1'b1;
                    if (debit && remaining != {WIDTH{1'b0}})
                        remaining <= remaining - {{(WIDTH-1){1'b0}}, 1'b1};
                end else
                    phase <= phase + 1'b1;
            end
        end
    end
endmodule

module i2c_stretch_handler #(
    parameter integer COUNTER_WIDTH = 32,
    parameter [COUNTER_WIDTH-1:0] RESET_MAX_STRETCH = 32'd8,
    parameter integer WATCHDOG_PERIOD = 4, WATCHDOG_FILTER = 4,
    parameter integer EVENT_DEPTH = 4
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire request_high,
    input wire scl_in,
    input wire config_valid,
    input wire [COUNTER_WIDTH-1:0] config_max_stretch,
    output wire scl_release,
    output wire high_phase_done,
    output reg high_pending,
    output reg stretching_active,
    output reg stretch_timeout,
    output reg [COUNTER_WIDTH-1:0] stretch_duration,
    output reg [COUNTER_WIDTH-1:0] max_stretch,
    output wire config_ready,
    output wire request_ready,
    output wire [COUNTER_WIDTH-1:0] watchdog_remaining,
    output wire [$clog2(WATCHDOG_PERIOD)-1:0] watchdog_phase,
    output wire [$clog2(WATCHDOG_FILTER)-1:0] watchdog_qualification,
    output wire [$clog2(EVENT_DEPTH):0] event_count,
    output reg [EVENT_DEPTH-1:0] event_occupied,
    output wire event_full, event_empty,
    output wire report_valid,
    output wire report_first,
    output wire report_last,
    output reg [1:0] report_kind,
    output reg [COUNTER_WIDTH-1:0] report_word,
    output wire report_timed_out
);
    localparam [COUNTER_WIDTH-1:0] COUNT_ZERO = {COUNTER_WIDTH{1'b0}};
    localparam [COUNTER_WIDTH-1:0] COUNT_ONE = {{(COUNTER_WIDTH-1){1'b0}}, 1'b1};
    localparam integer EVENT_ADDR_WIDTH = $clog2(EVENT_DEPTH);
    localparam integer EVENT_PTR_WIDTH = EVENT_ADDR_WIDTH + 1;
    reg [COUNTER_WIDTH-1:0] event_budget [0:EVENT_DEPTH-1];
    reg [COUNTER_WIDTH-1:0] event_duration [0:EVENT_DEPTH-1];
    reg [COUNTER_WIDTH-1:0] event_unused [0:EVENT_DEPTH-1];
    reg event_timeout [0:EVENT_DEPTH-1];
    reg [EVENT_PTR_WIDTH-1:0] event_read, event_write;
    wire [EVENT_ADDR_WIDTH-1:0] event_read_index, event_write_index;
    wire event_reserve, event_push, event_pop;
    integer event_init, event_reset, event_slot;
    reg past_valid;
    wire watchdog_debit;
    i2c_stretch_watchdog #(
        .WIDTH(COUNTER_WIDTH), .PERIOD(WATCHDOG_PERIOD),
        .FILTER(WATCHDOG_FILTER), .RESET_BUDGET(RESET_MAX_STRETCH)
    ) budget_timer (
        .clk(clk), .rst_n(rst_n), .ce(i_ce), .pending(high_pending),
        .scl_in(scl_in), .config_valid(config_valid),
        .budget(max_stretch), .config_budget(config_max_stretch),
        .debit(watchdog_debit), .remaining(watchdog_remaining),
        .phase(watchdog_phase), .qualification(watchdog_qualification)
    );

    initial begin
        high_pending = 1'b0;
        stretching_active = 1'b0;
        stretch_timeout = 1'b0;
        stretch_duration = COUNT_ZERO;
        max_stretch = RESET_MAX_STRETCH;
        past_valid = 1'b0;
        event_read = 0;
        event_write = 0;
        report_kind = 0;
        for (event_init = 0; event_init < EVENT_DEPTH; event_init = event_init + 1) begin
            event_budget[event_init] = COUNT_ZERO;
            event_duration[event_init] = COUNT_ZERO;
            event_unused[event_init] = COUNT_ZERO;
            event_timeout[event_init] = 1'b0;
        end
    end

    // Release the open-drain SCL output throughout the pending high phase.
    // Even a timeout does not end that phase before the slave releases SCL.
    assign scl_release = high_pending;
    assign high_phase_done = high_pending && scl_in;
    assign config_ready = i_ce && !high_pending;
    assign request_ready = i_ce && !high_pending && !config_valid &&
                           !event_full;

    assign event_read_index = event_read[EVENT_ADDR_WIDTH-1:0];
    assign event_write_index = event_write[EVENT_ADDR_WIDTH-1:0];
    assign event_empty = (event_read == event_write);
    assign event_full = (event_read_index == event_write_index) &&
                       (event_read[EVENT_ADDR_WIDTH] != event_write[EVENT_ADDR_WIDTH]);
    assign event_count = event_write - event_read;
    assign event_reserve = request_high && request_ready;
    assign event_push = i_ce && high_pending && scl_in;
    assign report_valid = i_ce && !event_empty;
    assign report_first = report_valid && (report_kind == 2'd0);
    assign report_last = report_valid && (report_kind == 2'd3);
    assign report_timed_out = !event_empty && event_timeout[event_read_index];
    assign event_pop = report_last;

    always @(*) begin
        for (event_slot = 0; event_slot < EVENT_DEPTH; event_slot = event_slot + 1) begin
            if (event_slot >= event_read_index)
                event_occupied[event_slot] = (event_slot - event_read_index) < event_count;
            else
                event_occupied[event_slot] = (EVENT_DEPTH + event_slot - event_read_index) < event_count;
        end
    end

    always @(*) begin
        report_word = COUNT_ZERO;
        if (!event_empty) begin
            case (report_kind)
                2'd0: report_word = event_budget[event_read_index];
                2'd1: report_word = event_duration[event_read_index];
                2'd2: report_word = event_unused[event_read_index];
                2'd3: report_word = event_timeout[event_read_index] ?
                                   COUNT_ONE : COUNT_ZERO;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            event_read <= 0;
            event_write <= 0;
            report_kind <= 0;
            for (event_reset = 0; event_reset < EVENT_DEPTH; event_reset = event_reset + 1) begin
                event_budget[event_reset] <= COUNT_ZERO;
                event_duration[event_reset] <= COUNT_ZERO;
                event_unused[event_reset] <= COUNT_ZERO;
                event_timeout[event_reset] <= 1'b0;
            end
        end else if (i_ce) begin
            if (event_reserve)
                event_budget[event_write_index] <= max_stretch;
            if (event_push) begin
                event_duration[event_write_index] <= stretch_duration;
                event_unused[event_write_index] <= watchdog_remaining;
                event_timeout[event_write_index] <= stretch_timeout;
                event_write <= event_write + 1'b1;
            end
            if (report_valid) begin
                if (report_kind == 2'd3) begin
                    report_kind <= 0;
                    event_read <= event_read + 1'b1;
                end else
                    report_kind <= report_kind + 1'b1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            high_pending <= 1'b0;
            stretching_active <= 1'b0;
            stretch_timeout <= 1'b0;
            stretch_duration <= COUNT_ZERO;
            max_stretch <= RESET_MAX_STRETCH;
            past_valid <= 1'b0;
        end else if (i_ce) begin
            past_valid <= 1'b1;
            if (!high_pending) begin
                stretching_active <= 1'b0;
                if (config_valid) begin
                    max_stretch <= config_max_stretch;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end else if (event_reserve) begin
                    high_pending <= 1'b1;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end
            end else if (scl_in) begin
                high_pending <= 1'b0;
                stretching_active <= 1'b0;
            end else begin
                stretching_active <= 1'b1;
                // Saturate the duration at the programmed stretch budget.
                if (watchdog_debit && (watchdog_remaining != COUNT_ZERO))
                    stretch_duration <= stretch_duration + COUNT_ONE;
                if (watchdog_debit && (watchdog_remaining <= COUNT_ONE))
                    stretch_timeout <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (past_valid && $rose(stretch_timeout))
            assert (stretch_duration == max_stretch);

    always @(posedge clk)
        if (past_valid && report_valid &&
            (report_kind == 2'd1) && report_timed_out)
            assert (report_word == event_budget[event_read_index]);
endmodule

module prescaler_event_queue #(
    parameter [63:0] P = 64'd4,
parameter [63:0] DEPTH = 64'd32,
parameter PREFETCH_DEPTH = 4
) (
    input  wire        clk,
    input  wire        i_pulse_valid,
    output wire        o_pulse_ready,
    input  wire        i_mode,
    output wire        o_valid,
    input  wire        i_out_ready,
output wire [63:0] o_data,
output wire [$clog2(PREFETCH_DEPTH):0] o_prefetch_level,
output reg [3:0] o_diag_status
);
    // Supported modulus settings: 3 <= P <= 16.
    // First accepted pulse: ARM and sample mode.
    // Second accepted pulse: START.
    // Pulse P or P+1: FINISH and enqueue its event record.
    localparam [63:0] IDLE  = 64'd0;
    localparam [63:0] ARMED = 64'd1;
    localparam [63:0] RUN   = 64'd2;

// The read-ahead FIFO supports power-of-two depths, normally 4 or 8.
localparam PREFETCH_ADDR_W = $clog2(PREFETCH_DEPTH);
localparam EVENT_ADDR_W = $clog2(DEPTH);

    reg [63:0] phase;
    reg [63:0] pulse_count;
    reg mode_q;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    reg [63:0] event_mem [0:DEPTH-1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] fifo_count;

    wire [63:0] modulus;
    wire pulse_fire;
    wire finish_fire;
    wire pop_fire;
    wire [DEPTH-1:0] filled;

reg [63:0] prefetch_mem [0:PREFETCH_DEPTH-1];
reg [PREFETCH_ADDR_W:0] prefetch_rd_ptr;
reg [PREFETCH_ADDR_W:0] prefetch_wr_ptr;
reg [EVENT_ADDR_W-1:0] fetch_addr;
reg read_valid;
reg [63:0] read_data;
reg head_valid;
reg [63:0] head_data;

wire [PREFETCH_ADDR_W-1:0] prefetch_rd_index;
wire [PREFETCH_ADDR_W-1:0] prefetch_wr_index;
wire [PREFETCH_ADDR_W:0] prefetch_used;
wire [PREFETCH_ADDR_W:0] prefetch_level;
wire prefetch_empty;
wire prefetch_full;
wire fetch_available;
wire read_ready;
wire fetch_fire;
wire enqueue_fire;
wire head_ready;
wire refill_fire;

    assign modulus = mode_q ? P + 64'd1 : P;
    assign o_pulse_ready = fifo_count < DEPTH;
    assign pulse_fire = i_pulse_valid && o_pulse_ready;
    assign finish_fire = pulse_fire && (phase == RUN)
                         && (pulse_count == modulus - 64'd1);
assign o_valid = head_valid;
assign o_data = head_data;
    assign pop_fire = o_valid && i_out_ready;

assign prefetch_rd_index =
    prefetch_rd_ptr[PREFETCH_ADDR_W-1:0];
assign prefetch_wr_index =
    prefetch_wr_ptr[PREFETCH_ADDR_W-1:0];
assign prefetch_used = prefetch_wr_ptr - prefetch_rd_ptr;
assign prefetch_level = prefetch_used
    + {{PREFETCH_ADDR_W{1'b0}}, head_valid}
    + {{PREFETCH_ADDR_W{1'b0}}, read_valid};
assign prefetch_empty = prefetch_wr_ptr == prefetch_rd_ptr;
assign prefetch_full =
    (prefetch_wr_ptr[PREFETCH_ADDR_W] != prefetch_rd_ptr[PREFETCH_ADDR_W])
    && (prefetch_wr_index == prefetch_rd_index);
assign fetch_available = prefetch_level < fifo_count;
assign read_ready = !read_valid || !prefetch_full;
assign fetch_fire = fetch_available && read_ready;
assign enqueue_fire = read_valid && !prefetch_full;
assign head_ready = !head_valid || i_out_ready;
assign refill_fire = !prefetch_empty && head_ready;
assign o_prefetch_level = prefetch_level;

    // Filled slots are the circular interval starting at rd_ptr.
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupied_slots
            localparam [63:0] ENTRY = g;
            assign filled[g] = ((ENTRY >= rd_ptr)
                              ? (ENTRY - rd_ptr)
                              : (ENTRY + DEPTH - rd_ptr)) < fifo_count;
        end
    endgenerate

// Read-only telemetry, serialized least-significant nibble first.
reg [5:0] diag_tick;
reg [15:0] diag_accepted;
reg [15:0] diag_completed;
reg [15:0] diag_delivered;
reg [15:0] diag_blocked_cycles;
reg [15:0] diag_stall_run;
reg [15:0] diag_stall_peak;
reg [15:0] diag_stall_episodes;
reg [15:0] diag_idle_age;
reg [15:0] diag_event_gap;
reg [15:0] diag_gap_peak;
reg [63:0] diag_watermark;
reg [3:0] diag_sticky;
reg [31:0] diag_signature;
reg [255:0] diag_scan;
initial begin
    diag_tick = 6'd0;
    diag_accepted = 16'd0;
    diag_completed = 16'd0;
    diag_delivered = 16'd0;
    diag_blocked_cycles = 16'd0;
    diag_stall_run = 16'd0;
    diag_stall_peak = 16'd0;
    diag_stall_episodes = 16'd0;
    diag_idle_age = 16'd0;
    diag_event_gap = 16'd0;
    diag_gap_peak = 16'd0;
    diag_watermark = 64'd0;
    diag_sticky = 4'd0;
    diag_signature = 32'd0;
    diag_scan = 256'd0;
    o_diag_status = 4'd0;
end

always @(posedge clk) begin
    diag_tick <= diag_tick + 6'd1;
    if (pulse_fire && (diag_accepted != 16'hffff))
        diag_accepted <= diag_accepted + 16'd1;
    if (finish_fire && (diag_completed != 16'hffff))
        diag_completed <= diag_completed + 16'd1;
    if (pop_fire) begin
        if (diag_delivered != 16'hffff)
            diag_delivered <= diag_delivered + 16'd1;
        diag_signature <= {diag_signature[26:0], diag_signature[31:27]}
                          ^ o_data[31:0] ^ o_data[63:32];
    end
    if (i_pulse_valid && !o_pulse_ready) begin
        diag_sticky[1] <= 1'b1;
        if (diag_blocked_cycles != 16'hffff)
            diag_blocked_cycles <= diag_blocked_cycles + 16'd1;
    end
    if (o_valid && !i_out_ready) begin
        if (diag_stall_run != 16'hffff)
            diag_stall_run <= diag_stall_run + 16'd1;
        if ((diag_stall_run == 16'd0)
            && (diag_stall_episodes != 16'hffff))
            diag_stall_episodes <= diag_stall_episodes + 16'd1;
        if (diag_stall_run == 16'd1023)
            diag_sticky[0] <= 1'b1;
    end else
        diag_stall_run <= 16'd0;
    if (diag_stall_run > diag_stall_peak)
        diag_stall_peak <= diag_stall_run;
    if (pulse_fire || pop_fire)
        diag_idle_age <= 16'd0;
    else if (diag_idle_age != 16'hffff)
        diag_idle_age <= diag_idle_age + 16'd1;
    if (diag_idle_age == 16'hffff)
        diag_sticky[3] <= 1'b1;
    if (finish_fire)
        diag_event_gap <= 16'd0;
    else if (diag_event_gap != 16'hffff)
        diag_event_gap <= diag_event_gap + 16'd1;
    if (finish_fire && (diag_event_gap > diag_gap_peak))
        diag_gap_peak <= diag_event_gap;
    if (fifo_count > diag_watermark)
        diag_watermark <= fifo_count;
    if (fifo_count == DEPTH)
        diag_sticky[2] <= 1'b1;
    if (diag_tick == 6'd0) begin
        diag_scan <= {28'hd1a6001, diag_sticky,
                      diag_signature, diag_watermark,
                      diag_accepted, diag_completed,
                      diag_delivered, diag_blocked_cycles,
                      diag_stall_peak, diag_idle_age,
                      diag_stall_episodes, diag_gap_peak};
    end else
        diag_scan <= {4'd0, diag_scan[255:4]};
    o_diag_status <= diag_scan[3:0];
end

    integer j;
    initial begin
        phase = IDLE;
        pulse_count = 64'd0;
        mode_q = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        scope_armed = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        fifo_count = 64'd0;
prefetch_rd_ptr = {(PREFETCH_ADDR_W+1){1'b0}};
prefetch_wr_ptr = {(PREFETCH_ADDR_W+1){1'b0}};
fetch_addr = {EVENT_ADDR_W{1'b0}};
read_valid = 1'b0;
read_data = 64'd0;
head_valid = 1'b0;
head_data = 64'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            event_mem[j] = 64'd0;
for (j = 0; j < PREFETCH_DEPTH; j = j + 1)
    prefetch_mem[j] = 64'd0;
    end

    always @(posedge clk) begin
        if (pulse_fire) begin
            case (phase)
                IDLE: begin
                    // Q is the ARM event; its scope latch never clears.
                    scope_armed <= 1'b1;
                    mode_q <= i_mode;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    pulse_count <= 64'd1;
                    phase <= ARMED;
                end
                ARMED: begin
                    start_seen <= 1'b1;
                    pulse_count <= 64'd2;
                    phase <= RUN;
                end
                RUN: begin
                    if (finish_fire) begin
                        pulse_count <= 64'd0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= IDLE;
                    end else begin
                        pulse_count <= pulse_count + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    pulse_count <= 64'd0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end

        if (finish_fire) begin
            // Record: ARM witness, START witness, sampled mode,
            // and the number of accepted pulses in this division.
            event_mem[wr_ptr] <= (pulse_count + 64'd1)
                | (arm_seen ? 64'h8000000000000000 : 64'd0)
                | (start_seen ? 64'h4000000000000000 : 64'd0)
                | (mode_q ? 64'h2000000000000000 : 64'd0);
            wr_ptr <= (wr_ptr == DEPTH - 64'd1)
                    ? 64'd0 : wr_ptr + 64'd1;
        end
        if (pop_fire)
            rd_ptr <= (rd_ptr == DEPTH - 64'd1)
                    ? 64'd0 : rd_ptr + 64'd1;

        case ({finish_fire, pop_fire})
            2'b10: fifo_count <= fifo_count + 64'd1;
            2'b01: fifo_count <= fifo_count - 64'd1;
            default: begin end
        endcase
    end

// A stalled read response keeps its data and reserves its backing slot.
always @(posedge clk) begin
    if (read_ready)
        read_valid <= fetch_fire;
    if (fetch_fire) begin
        read_data <= event_mem[fetch_addr];
        if (fetch_addr == DEPTH - 64'd1)
            fetch_addr <= {EVENT_ADDR_W{1'b0}};
        else
            fetch_addr <= fetch_addr + 1'b1;
    end
end

always @(posedge clk) begin
    if (enqueue_fire) begin
        prefetch_mem[prefetch_wr_index] <= read_data;
        prefetch_wr_ptr <= prefetch_wr_ptr + 1'b1;
    end
    if (refill_fire)
        prefetch_rd_ptr <= prefetch_rd_ptr + 1'b1;
end

// Backing slots are released by pop_fire, not by speculative reads.
always @(posedge clk) begin
    if (head_ready) begin
        head_valid <= refill_fire;
        if (refill_fire)
            head_data <= prefetch_mem[prefetch_rd_index];
    end
end

    // After Q: START requires ARM, and every observable FINISH
    // must carry both earlier event witnesses.
    always @(posedge clk)
        if (scope_armed)
            assert ((!start_seen || arm_seen)
                    && (!o_valid || (o_data[63] && o_data[62])));
endmodule

module pixel_pulse_pending #(
    parameter integer COUNT_W = 32
) (
    input wire clk,
    input wire i_ce,
    input wire i_pixel_pulse,
    input wire i_dispatch,
    input wire i_slow_tick,
    input wire i_load_limit,
    input wire [COUNT_W-1:0] i_limit,
    input wire i_begin_tile,
    input wire i_end_tile,
input wire i_peer_pixel_pulse,
output reg slow_pixel_pulse,
output wire pixel_ready,
output wire peer_ready,
output reg peer_slow_pixel_pulse,
output reg [63:0] debug_stats
);
    localparam [COUNT_W-1:0] ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
localparam integer CHANNELS = 2, PEER_DEPTH = 7;
localparam integer PEER_W = $clog2(PEER_DEPTH + 1);

    reg [COUNT_W-1:0] pending;
    reg [COUNT_W-1:0] outstanding;
    reg [COUNT_W-1:0] pulse_limit;
    reg req_toggle;
    reg ack_toggle;
    reg window_open;
    reg pv;
reg peer_valid [0:PEER_DEPTH-1];
reg [PEER_W-1:0] peer_outstanding;
reg [$clog2(CHANNELS)-1:0] flight_lane;
integer k;

    wire in_flight = (req_toggle != ack_toggle);
    wire accept_pulse = i_pixel_pulse && (outstanding < pulse_limit);
    wire launch_request = i_dispatch && !in_flight && (pending != ZERO);
wire retire_request = i_slow_tick && in_flight && (flight_lane == 1'b0);
wire peer_launch = i_dispatch && !in_flight && (pending == ZERO) && peer_valid[PEER_DEPTH-1];
wire peer_shift = !peer_valid[PEER_DEPTH-1] || peer_launch;
wire peer_retire = i_slow_tick && in_flight && (flight_lane == 1'b1);
wire peer_accept = i_peer_pixel_pulse && peer_ready;
assign pixel_ready = i_ce && (outstanding < pulse_limit);
assign peer_ready = i_ce && peer_shift && (peer_outstanding < PEER_DEPTH);
    reg [7:0] dbg_accept_cycles;
    reg [7:0] dbg_retire_cycles;
    reg [7:0] dbg_blocked_cycles;
    reg [7:0] dbg_stall_run;
    reg [7:0] dbg_stall_peak;
    reg [15:0] dbg_watchdog;
    reg dbg_timeout_seen;
    reg dbg_blocked_seen;
    wire dbg_blocked = (i_pixel_pulse && !pixel_ready) ||
                       (i_peer_pixel_pulse && !peer_ready);
    initial begin
        dbg_accept_cycles = 8'd0;
        dbg_retire_cycles = 8'd0;
        dbg_blocked_cycles = 8'd0;
        dbg_stall_run = 8'd0;
        dbg_stall_peak = 8'd0;
        dbg_watchdog = 16'd0;
        dbg_timeout_seen = 1'b0;
        dbg_blocked_seen = 1'b0;
        debug_stats = 64'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_begin_tile) begin
                dbg_accept_cycles <= 8'd0;
                dbg_retire_cycles <= 8'd0;
                dbg_blocked_cycles <= 8'd0;
                dbg_stall_run <= 8'd0;
                dbg_stall_peak <= 8'd0;
                dbg_watchdog <= 16'd0;
                dbg_timeout_seen <= 1'b0;
                dbg_blocked_seen <= 1'b0;
            end else begin
                if ((accept_pulse || peer_accept) && !(&dbg_accept_cycles))
                    dbg_accept_cycles <= dbg_accept_cycles + 8'd1;
                if ((retire_request || peer_retire) && !(&dbg_retire_cycles))
                    dbg_retire_cycles <= dbg_retire_cycles + 8'd1;
                if (dbg_blocked && !(&dbg_blocked_cycles))
                    dbg_blocked_cycles <= dbg_blocked_cycles + 8'd1;
                if (dbg_blocked) begin
                    dbg_blocked_seen <= 1'b1;
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 8'd1;
                    if ((dbg_stall_run >= dbg_stall_peak) && !(&dbg_stall_run))
                        dbg_stall_peak <= dbg_stall_run + 8'd1;
                end else
                    dbg_stall_run <= 8'd0;
                if (!in_flight || retire_request || peer_retire)
                    dbg_watchdog <= 16'd0;
                else if (!(&dbg_watchdog))
                    dbg_watchdog <= dbg_watchdog + 16'd1;
                if (&dbg_watchdog)
                    dbg_timeout_seen <= 1'b1;
            end
            debug_stats <= {dbg_accept_cycles, dbg_retire_cycles,
                            dbg_blocked_cycles, dbg_stall_peak,
                            dbg_watchdog, dbg_stall_run, 6'b0,
                            dbg_timeout_seen, dbg_blocked_seen};
        end
    end

    initial begin
        pending = ZERO;
        outstanding = ZERO;
        pulse_limit = {COUNT_W{1'b1}};
        req_toggle = 1'b0;
        ack_toggle = 1'b0;
        window_open = 1'b0;
        slow_pixel_pulse = 1'b0;
        pv = 1'b0;
for (k = 0; k < PEER_DEPTH; k = k + 1) peer_valid[k] = 1'b0;
peer_outstanding = 0;
flight_lane = 0;
peer_slow_pixel_pulse = 1'b0;
    end

    // i_slow_tick models an edge of the slower receiving domain.
    // Requests remain outstanding until that domain acknowledges them.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            if (i_load_limit)
                pulse_limit <= i_limit;

            if (i_end_tile)
                window_open <= 1'b0;
            else if (i_begin_tile)
                window_open <= 1'b1;

            case ({accept_pulse, launch_request})
                2'b10: pending <= pending + ONE;
                2'b01: pending <= pending - ONE;
                default: pending <= pending;
            endcase

            case ({accept_pulse, retire_request})
                2'b10: outstanding <= outstanding + ONE;
                2'b01: outstanding <= outstanding - ONE;
                default: outstanding <= outstanding;
            endcase
if (peer_shift) begin
    for (k = PEER_DEPTH-1; k > 0; k = k - 1)
        peer_valid[k] <= peer_valid[k-1];
    peer_valid[0] <= peer_accept;
end
case ({peer_accept, peer_retire})
    2'b10: peer_outstanding <= peer_outstanding + 1'b1;
    2'b01: peer_outstanding <= peer_outstanding - 1'b1;
    default: peer_outstanding <= peer_outstanding;
endcase

if (launch_request || peer_launch)
                req_toggle <= !req_toggle;
if (launch_request || peer_launch)
    flight_lane <= peer_launch;

if (retire_request || peer_retire)
                ack_toggle <= req_toggle;

            slow_pixel_pulse <= retire_request;
peer_slow_pixel_pulse <= peer_retire;
        end
    end

    // The registered pulse reports the preceding enabled edge's delivery.
    // Inside the previous tile window, delivery and an empty work ledger
    // must never have occurred together on that edge.
    always @(posedge clk) begin
        if (pv && $past(window_open) && $past(i_ce))
            assert (!(slow_pixel_pulse && ($past(outstanding) == ZERO)));
    end
always @(posedge clk) begin
    if (pv && $past(i_ce))
        assert (!(peer_slow_pixel_pulse && ($past(peer_outstanding) == 0)));
end
endmodule

module schroeder_phase_stage #(
    parameter [31:0] DEPTH = 32'd16,
    parameter signed [31:0] GAIN_NUM = 32'sd1,
parameter [31:0] GAIN_SHIFT = 32'd1,
parameter INPUT_DEPTH = 4
) (
    input wire clk,
    input wire ce,
    input wire signed [31:0] sample_in,
    output reg signed [31:0] sample_out,
output wire sample_valid,
output wire sample_ready,
output wire [$clog2(INPUT_DEPTH):0] input_queued
);
    typedef enum logic [1:0] {
        CAPTURE  = 2'b00,
        FEEDBACK = 2'b01,
        COMMIT   = 2'b10,
        REPORT   = 2'b11
    } state_t;

    state_t state;
    reg [31:0] delay_ptr;
    reg signed [31:0] delay_line [32'd0:DEPTH-32'd1];
    reg signed [31:0] sample_shadow;
    reg signed [31:0] tap_shadow;
    reg signed [31:0] feedback_word;

localparam INPUT_ADDR_W = $clog2(INPUT_DEPTH);
reg signed [31:0] input_fifo [0:INPUT_DEPTH-1];
reg [INPUT_ADDR_W:0] input_rd_ptr;
reg [INPUT_ADDR_W:0] input_wr_ptr;
reg signed [31:0] head_sample;
reg head_valid;
wire [INPUT_ADDR_W-1:0] input_rd_addr = input_rd_ptr[INPUT_ADDR_W-1:0];
wire [INPUT_ADDR_W-1:0] input_wr_addr = input_wr_ptr[INPUT_ADDR_W-1:0];
wire input_empty = (input_rd_ptr == input_wr_ptr);
wire input_full =
    (input_rd_ptr[INPUT_ADDR_W] != input_wr_ptr[INPUT_ADDR_W]) &&
    (input_rd_addr == input_wr_addr);
wire input_push = ce && sample_ready;
wire input_pop = ce && (state == COMMIT);
wire input_fetch = ce && !head_valid && !input_empty;

    // Dyadic gain g = GAIN_NUM / 2**GAIN_SHIFT, defaulting to 1/2.
    // Arithmetic and storage wrap at 32 bits; shifts round downward.
    wire signed [31:0] tap_product = tap_shadow * GAIN_NUM;
    wire signed [31:0] scaled_tap = tap_product >>> GAIN_SHIFT;
    wire signed [31:0] expected_feedback = sample_shadow + scaled_tap;

    wire signed [31:0] feedback_product = feedback_word * GAIN_NUM;
    wire signed [31:0] scaled_feedback = feedback_product >>> GAIN_SHIFT;

    wire signed [31:0] expected_product = expected_feedback * GAIN_NUM;
    wire signed [31:0] expected_scaled = expected_product >>> GAIN_SHIFT;
    wire signed [31:0] expected_output = tap_shadow - expected_scaled;

wire signed [31:0] retiring_feedback =
    input_fifo[input_rd_addr] + scaled_tap;

    assign sample_valid = (state == REPORT);
assign sample_ready = ce && !input_full;
assign input_queued =
    (input_rd_ptr[INPUT_ADDR_W] == input_wr_ptr[INPUT_ADDR_W]) ?
    ({1'b0, input_wr_addr} - {1'b0, input_rd_addr}) :
    (INPUT_DEPTH + {1'b0, input_wr_addr} - {1'b0, input_rd_addr});

    initial begin
        state = CAPTURE;
        delay_ptr = 32'd0;
        sample_shadow = 32'sd0;
        tap_shadow = 32'sd0;
        feedback_word = 32'sd0;
        sample_out = 32'sd0;
input_rd_ptr = 0;
input_wr_ptr = 0;
head_sample = 32'sd0;
head_valid = 1'b0;
    end

    genvar entry;
    generate
        for (entry = 32'd0; entry < DEPTH; entry = entry + 32'd1) begin : initialize_delay
            initial delay_line[entry] = 32'sd0;
        end
for (entry = 0; entry < INPUT_DEPTH; entry = entry + 1) begin : initialize_input
    initial input_fifo[entry] = 32'sd0;
end
    endgenerate

always @(posedge clk) begin
    if (input_push) begin
        input_fifo[input_wr_addr] <= sample_in;
        if (input_wr_addr == INPUT_DEPTH - 1)
            input_wr_ptr <= {~input_wr_ptr[INPUT_ADDR_W], {INPUT_ADDR_W{1'b0}}};
        else
            input_wr_ptr <= input_wr_ptr + 1'b1;
    end
    if (input_pop) begin
        if (input_rd_addr == INPUT_DEPTH - 1)
            input_rd_ptr <= {~input_rd_ptr[INPUT_ADDR_W], {INPUT_ADDR_W{1'b0}}};
        else
            input_rd_ptr <= input_rd_ptr + 1'b1;
    end
    if (input_pop)
        head_valid <= 1'b0;
    else if (input_fetch) begin
        head_sample <= input_fifo[input_rd_addr];
        head_valid <= 1'b1;
    end
end

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                CAPTURE: begin
                    // Record the input and the earlier circular-buffer value.
if (head_valid) begin
    sample_shadow <= head_sample;
    tap_shadow <= delay_line[delay_ptr];
    state <= FEEDBACK;
end
                end
                FEEDBACK: begin
                    // Allpass feedback path: w = x + g*d.
                    feedback_word <= expected_feedback;
                    state <= COMMIT;
                end
                COMMIT: begin
                    // Allpass feedforward path: y = d - g*w.
                    delay_line[delay_ptr] <= feedback_word;
                    sample_out <= tap_shadow - scaled_feedback;
                    if (delay_ptr == DEPTH - 32'd1)
                        delay_ptr <= 32'd0;
                    else
                        delay_ptr <= delay_ptr + 32'd1;
                    state <= REPORT;
                end
                REPORT: begin
                    state <= CAPTURE;
                end
            endcase
        end
    end

    // Every reported result must correspond to the earlier captured values.
    always @(posedge clk)
        if (state == REPORT)
            assert (sample_out == expected_output);

// A retiring delay write belongs to the oldest accepted sample.
always @(posedge clk)
    if (ce && (state == COMMIT))
        assert (feedback_word == retiring_feedback);
endmodule

module forwarded_sample_buffer #(
    parameter integer unsigned DEPTH = 32'd24,
    parameter integer unsigned DATA_WIDTH = 32'd32,
    parameter integer unsigned INDEX_WIDTH = 32'd32
) (
    input  wire clk,
    input  wire forwarded_clk,
    input  wire i_ce,
    input  wire in_valid,
    output wire in_ready,
    input  wire [DATA_WIDTH-32'd1:0] in_data,
    output wire out_valid,
    input  wire out_ready,
    output logic [DATA_WIDTH-32'd1:0] out_data,
    output reg [63:0] debug_stats
);
    typedef enum logic [1:0] {
        RX_IDLE  = 2'd0,
        RX_STORE = 2'd1,
        RX_WAIT  = 2'd2
    } rx_state_t;

    typedef enum logic [1:0] {
        TX_IDLE  = 2'd0,
        TX_VALID = 2'd1
    } tx_state_t;

    localparam logic [INDEX_WIDTH-32'd1:0] LAST_INDEX =
        INDEX_WIDTH'(DEPTH - 32'd1);

    rx_state_t rx_state;
    tx_state_t tx_state;
    logic [DATA_WIDTH-32'd1:0] capture_data;
    logic [DATA_WIDTH-32'd1:0] sample_buffer [0:DEPTH-32'd1];
    logic [INDEX_WIDTH-32'd1:0] write_index;
    logic [INDEX_WIDTH-32'd1:0] read_index;
    logic request_toggle;
    logic acknowledge_toggle;
    logic past_valid;
    logic [15:0] stats_transfers;
    logic [15:0] stats_stall_cycles;
    logic [14:0] stats_idle_cycles;
    logic [7:0] stats_stall_run;
    logic [7:0] stats_stall_peak;
    logic stats_watchdog;

    wire [INDEX_WIDTH-32'd1:0] next_write_index =
        (write_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        write_index + INDEX_WIDTH'(32'd1);
    wire [INDEX_WIDTH-32'd1:0] next_read_index =
        (read_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        read_index + INDEX_WIDTH'(32'd1);

    assign in_ready = i_ce && (rx_state == RX_IDLE);
    assign out_valid = (tx_state == TX_VALID);

    initial begin
        rx_state = RX_IDLE;
        tx_state = TX_IDLE;
        capture_data = {DATA_WIDTH{1'b0}};
        out_data = {DATA_WIDTH{1'b0}};
        write_index = {INDEX_WIDTH{1'b0}};
        read_index = {INDEX_WIDTH{1'b0}};
        request_toggle = 1'b0;
        acknowledge_toggle = 1'b0;
        past_valid = 1'b0;
        stats_transfers = 16'd0;
        stats_stall_cycles = 16'd0;
        stats_idle_cycles = 15'd0;
        stats_stall_run = 8'd0;
        stats_stall_peak = 8'd0;
        stats_watchdog = 1'b0;
        debug_stats = 64'd0;
        for (integer k = 32'd0; k < DEPTH; k = k + 32'd1)
            sample_buffer[k] = {DATA_WIDTH{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (out_valid && out_ready) begin
                if (stats_transfers != 16'hffff)
                    stats_transfers <= stats_transfers + 16'd1;
            end
            if (!out_valid) begin
                if (stats_idle_cycles != 15'h7fff)
                    stats_idle_cycles <= stats_idle_cycles + 15'd1;
            end
            if (out_valid && !out_ready) begin
                if (stats_stall_cycles != 16'hffff)
                    stats_stall_cycles <= stats_stall_cycles + 16'd1;
                if (stats_stall_run != 8'hff) begin
                    stats_stall_run <= stats_stall_run + 8'd1;
                    if (stats_stall_run >= stats_stall_peak)
                        stats_stall_peak <= stats_stall_run + 8'd1;
                end
                if (stats_stall_run >= 8'd63)
                    stats_watchdog <= 1'b1;
            end else begin
                stats_stall_run <= 8'd0;
            end
            debug_stats[63:49] <= stats_idle_cycles;
            debug_stats[48] <= stats_watchdog;
            debug_stats[47:40] <= stats_stall_peak;
            debug_stats[39:32] <= stats_stall_run;
            debug_stats[31:16] <= stats_stall_cycles;
            debug_stats[15:0] <= stats_transfers;
        end
    end

    // Forwarded-clock capture followed by a write into the rotating buffer.
    // One outstanding transfer keeps the bundled sample and its slot stable
    // until the local-clock consumer acknowledges it.
    always @(posedge forwarded_clk) begin
        if (i_ce) begin
            case (rx_state)
                RX_IDLE: begin
                    if (in_valid && in_ready) begin
                        capture_data <= in_data;
                        rx_state <= RX_STORE;
                    end
                end
                RX_STORE: begin
                    sample_buffer[write_index] <= capture_data;
                    request_toggle <= !request_toggle;
                    rx_state <= RX_WAIT;
                end
                RX_WAIT: begin
                    if (request_toggle == acknowledge_toggle) begin
                        write_index <= next_write_index;
                        rx_state <= RX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    // The other port of the buffer is read in the local-clock domain.
    // Output data and valid remain held throughout back-pressure.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            case (tx_state)
                TX_IDLE: begin
                    if (request_toggle != acknowledge_toggle) begin
                        out_data <= sample_buffer[read_index];
                        tx_state <= TX_VALID;
                    end
                end
                TX_VALID: begin
                    if (out_valid && out_ready) begin
                        acknowledge_toggle <= request_toggle;
                        read_index <= next_read_index;
                        tx_state <= TX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    always @(posedge clk) begin
        if (past_valid && $rose(out_valid))
            assert (out_data == capture_data);
    end
endmodule

module forwarded_sample_buffer #(
    parameter integer unsigned DEPTH = 32'd24,
    parameter integer unsigned DATA_WIDTH = 32'd32,
    parameter integer unsigned INDEX_WIDTH = 32'd32
) (
    input  wire clk,
    input  wire forwarded_clk,
    input  wire i_ce,
    input  wire in_valid,
    output wire in_ready,
    input  wire [DATA_WIDTH-32'd1:0] in_data,
    output wire out_valid,
    input  wire out_ready,
    output logic [DATA_WIDTH-32'd1:0] out_data,
    output reg [31:0] debug_status,
    output reg [39:0] perf_snapshot
);
    typedef enum logic [1:0] {
        RX_IDLE  = 2'd0,
        RX_STORE = 2'd1,
        RX_WAIT  = 2'd2
    } rx_state_t;

    typedef enum logic [1:0] {
        TX_IDLE  = 2'd0,
        TX_VALID = 2'd1
    } tx_state_t;

    localparam logic [INDEX_WIDTH-32'd1:0] LAST_INDEX =
        INDEX_WIDTH'(DEPTH - 32'd1);

    rx_state_t rx_state;
    tx_state_t tx_state;
    logic [DATA_WIDTH-32'd1:0] capture_data;
    logic [DATA_WIDTH-32'd1:0] sample_buffer [0:DEPTH-32'd1];
    logic [INDEX_WIDTH-32'd1:0] write_index;
    logic [INDEX_WIDTH-32'd1:0] read_index;
    logic request_toggle;
    logic acknowledge_toggle;
    logic past_valid;
    logic [7:0] dbg_transfer_count;
    logic [7:0] dbg_stall_cycles;
    logic [7:0] dbg_stall_run;
    logic [7:0] dbg_stall_peak;
    logic [7:0] dbg_idle_run;
    logic dbg_stall_alarm;
    logic dbg_idle_alarm;
    logic [7:0] perf_window;
    logic [7:0] perf_transfers;
    logic [7:0] perf_busy;
    logic [7:0] perf_gap;
    logic [7:0] perf_peak;
    logic [7:0] perf_signature;
    logic [5:0] perf_epoch;
    logic perf_alarm;
    logic perf_stalled;
    wire perf_take = out_valid && out_ready;
    wire [7:0] perf_transfers_next =
        (perf_take && (perf_transfers != 8'hff)) ? perf_transfers + 8'd1 : perf_transfers;
    wire [7:0] perf_busy_next =
        (out_valid && (perf_busy != 8'hff)) ? perf_busy + 8'd1 : perf_busy;
    wire [7:0] perf_gap_next =
        perf_take ? 8'd0 :
        ((perf_gap != 8'hff) ? perf_gap + 8'd1 : perf_gap);
    wire [7:0] perf_peak_next =
        (perf_gap_next > perf_peak) ? perf_gap_next : perf_peak;
    wire [7:0] perf_signature_next =
        perf_take ? ({perf_signature[6:0], ^out_data} ^
                     (perf_signature[7] ? 8'h1d : 8'h00)) : perf_signature;
    wire perf_alarm_next = perf_alarm || (perf_gap_next >= 8'd128);
    wire perf_stalled_next = perf_stalled || (out_valid && !out_ready);

    wire [INDEX_WIDTH-32'd1:0] next_write_index =
        (write_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        write_index + INDEX_WIDTH'(32'd1);
    wire [INDEX_WIDTH-32'd1:0] next_read_index =
        (read_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        read_index + INDEX_WIDTH'(32'd1);

    assign in_ready = i_ce && (rx_state == RX_IDLE);
    assign out_valid = (tx_state == TX_VALID);
    initial begin
        perf_window = 8'd0;
        perf_transfers = 8'd0;
        perf_busy = 8'd0;
        perf_gap = 8'd0;
        perf_peak = 8'd0;
        perf_signature = 8'h01;
        perf_epoch = 6'd0;
        perf_alarm = 1'b0;
        perf_stalled = 1'b0;
        perf_snapshot = 40'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (perf_window == 8'hff) begin
                perf_window <= 8'd0;
                perf_epoch <= perf_epoch + 6'd1;
                perf_snapshot <= {perf_epoch, perf_stalled_next, perf_alarm_next,
                                  perf_transfers_next, perf_busy_next, perf_peak_next, perf_signature_next};
                perf_transfers <= 8'd0;
                perf_busy <= 8'd0;
                perf_gap <= 8'd0;
                perf_peak <= 8'd0;
                perf_signature <= 8'h01;
                perf_alarm <= 1'b0;
                perf_stalled <= 1'b0;
            end else begin
                perf_window <= perf_window + 8'd1;
                perf_transfers <= perf_transfers_next;
                perf_busy <= perf_busy_next;
                perf_gap <= perf_gap_next;
                perf_peak <= perf_peak_next;
                perf_signature <= perf_signature_next;
                perf_alarm <= perf_alarm_next;
                perf_stalled <= perf_stalled_next;
            end
        end
    end

    initial begin
        rx_state = RX_IDLE;
        tx_state = TX_IDLE;
        capture_data = {DATA_WIDTH{1'b0}};
        out_data = {DATA_WIDTH{1'b0}};
        write_index = {INDEX_WIDTH{1'b0}};
        read_index = {INDEX_WIDTH{1'b0}};
        request_toggle = 1'b0;
        acknowledge_toggle = 1'b0;
        past_valid = 1'b0;
        for (integer k = 32'd0; k < DEPTH; k = k + 32'd1)
            sample_buffer[k] = {DATA_WIDTH{1'b0}};
    end
    initial begin
        dbg_transfer_count = 8'd0;
        dbg_stall_cycles = 8'd0;
        dbg_stall_run = 8'd0;
        dbg_stall_peak = 8'd0;
        dbg_idle_run = 8'd0;
        dbg_stall_alarm = 1'b0;
        dbg_idle_alarm = 1'b0;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (out_valid && out_ready) begin
                if (dbg_transfer_count != 8'hff)
                    dbg_transfer_count <= dbg_transfer_count + 8'd1;
            end
            if (out_valid && !out_ready) begin
                if (dbg_stall_cycles != 8'hff)
                    dbg_stall_cycles <= dbg_stall_cycles + 8'd1;
                if (dbg_stall_run != 8'hff)
                    dbg_stall_run <= dbg_stall_run + 8'd1;
                if ((dbg_stall_run >= dbg_stall_peak) && (dbg_stall_run != 8'hff))
                    dbg_stall_peak <= dbg_stall_run + 8'd1;
                if (dbg_stall_run >= 8'd63)
                    dbg_stall_alarm <= 1'b1;
            end else begin
                dbg_stall_run <= 8'd0;
            end
            if (!out_valid) begin
                if (dbg_idle_run != 8'hff)
                    dbg_idle_run <= dbg_idle_run + 8'd1;
                if (dbg_idle_run >= 8'd127)
                    dbg_idle_alarm <= 1'b1;
            end else begin
                dbg_idle_run <= 8'd0;
            end
            debug_status <= {dbg_stall_alarm, dbg_idle_alarm, out_valid, out_ready,
                             dbg_idle_run[3:0], dbg_stall_peak,
                             dbg_stall_cycles, dbg_transfer_count};
        end
    end

    // Forwarded-clock capture followed by a write into the rotating buffer.
    // One outstanding transfer keeps the bundled sample and its slot stable
    // until the local-clock consumer acknowledges it.
    always @(posedge forwarded_clk) begin
        if (i_ce) begin
            case (rx_state)
                RX_IDLE: begin
                    if (in_valid && in_ready) begin
                        capture_data <= in_data;
                        rx_state <= RX_STORE;
                    end
                end
                RX_STORE: begin
                    sample_buffer[write_index] <= capture_data;
                    request_toggle <= !request_toggle;
                    rx_state <= RX_WAIT;
                end
                RX_WAIT: begin
                    if (request_toggle == acknowledge_toggle) begin
                        write_index <= next_write_index;
                        rx_state <= RX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    // The other port of the buffer is read in the local-clock domain.
    // Output data and valid remain held throughout back-pressure.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            case (tx_state)
                TX_IDLE: begin
                    if (request_toggle != acknowledge_toggle) begin
                        out_data <= sample_buffer[read_index];
                        tx_state <= TX_VALID;
                    end
                end
                TX_VALID: begin
                    if (out_valid && out_ready) begin
                        acknowledge_toggle <= request_toggle;
                        read_index <= next_read_index;
                        tx_state <= TX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    always @(posedge clk) begin
        if (past_valid && $rose(out_valid))
            assert (out_data == capture_data);
    end
endmodule

module prescaler_event_queue #(
    parameter [63:0] P = 64'd4,
    parameter [63:0] DEPTH = 64'd32
) (
    input  wire        clk,
    input  wire        i_pulse_valid,
    output wire        o_pulse_ready,
    input  wire        i_mode,
    output wire        o_valid,
    input  wire        i_out_ready,
output wire [63:0] o_data,
output wire        o_trace_valid,
output reg         o_trace_bit,
output wire        o_trace_last,
output wire        o_trace_busy
);
    // Supported modulus settings: 3 <= P <= 16.
    // First accepted pulse: ARM and sample mode.
    // Second accepted pulse: START.
    // Pulse P or P+1: FINISH and enqueue its event record.
    localparam [63:0] IDLE  = 64'd0;
    localparam [63:0] ARMED = 64'd1;
    localparam [63:0] RUN   = 64'd2;

    reg [63:0] phase;
    reg [63:0] pulse_count;
    reg mode_q;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    reg [63:0] event_mem [0:DEPTH-1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] fifo_count;

    localparam TRACE_DEPTH = 4;
    localparam TRACE_ADDR_W = $clog2(TRACE_DEPTH);
    reg [63:0] trace_mem [0:TRACE_DEPTH-1];
    reg [TRACE_ADDR_W:0] trace_rd;
    reg [TRACE_ADDR_W:0] trace_wr;
    reg [63:0] trace_shift;
    reg [6:0] trace_index;
    reg trace_active;

    wire trace_empty;
    wire trace_full;
    wire trace_push;
    wire trace_load;
    wire trace_step;
    wire trace_done;
    wire [TRACE_ADDR_W:0] trace_used;
    wire [TRACE_ADDR_W:0] trace_held;
    wire [TRACE_DEPTH-1:0] trace_filled;

    wire [63:0] modulus;
    wire pulse_fire;
    wire finish_fire;
    wire pop_fire;
    wire [DEPTH-1:0] filled;

    assign modulus = mode_q ? P + 64'd1 : P;
    assign o_pulse_ready = fifo_count < DEPTH;
    assign pulse_fire = i_pulse_valid && o_pulse_ready;
    assign finish_fire = pulse_fire && (phase == RUN)
                         && (pulse_count == modulus - 64'd1);
assign o_valid = (fifo_count != 64'd0) && !trace_full;
    assign o_data = event_mem[rd_ptr];
    assign pop_fire = o_valid && i_out_ready;

    // Parallel delivery and its diagnostic copy are accepted together.
    assign trace_empty = trace_rd == trace_wr;
    assign trace_full = trace_wr == {~trace_rd[TRACE_ADDR_W],
                                     trace_rd[TRACE_ADDR_W-1:0]};
    assign trace_used = trace_wr - trace_rd;
    assign trace_held = trace_used + trace_active;
    assign trace_push = pop_fire;
    assign trace_load = !trace_active && !trace_empty;
    assign trace_step = trace_active && i_out_ready;
    assign trace_done = trace_step && (trace_index == 7'd65);
    assign o_trace_valid = trace_active;
    assign o_trace_last = trace_active && (trace_index == 7'd65);
    assign o_trace_busy = trace_active || !trace_empty;

    // Filled slots are the circular interval starting at rd_ptr.
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupied_slots
            localparam [63:0] ENTRY = g;
            assign filled[g] = ((ENTRY >= rd_ptr)
                              ? (ENTRY - rd_ptr)
                              : (ENTRY + DEPTH - rd_ptr)) < fifo_count;
        end
    endgenerate

    genvar t;
    generate
        for (t = 0; t < TRACE_DEPTH; t = t + 1) begin : trace_slots
            localparam [TRACE_ADDR_W-1:0] ENTRY = t;
            wire [TRACE_ADDR_W-1:0] offset;
            assign offset = ENTRY - trace_rd[TRACE_ADDR_W-1:0];
            assign trace_filled[t] = {1'b0, offset} < trace_used;
        end
    endgenerate

    integer j;
    initial begin
        phase = IDLE;
        pulse_count = 64'd0;
        mode_q = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        scope_armed = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        fifo_count = 64'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            event_mem[j] = 64'd0;
        trace_rd = 0;
        trace_wr = 0;
        trace_shift = 64'd0;
        trace_index = 7'd0;
        trace_active = 1'b0;
        for (j = 0; j < TRACE_DEPTH; j = j + 1)
            trace_mem[j] = 64'd0;
    end

    always @(posedge clk) begin
        if (pulse_fire) begin
            case (phase)
                IDLE: begin
                    // Q is the ARM event; its scope latch never clears.
                    scope_armed <= 1'b1;
                    mode_q <= i_mode;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    pulse_count <= 64'd1;
                    phase <= ARMED;
                end
                ARMED: begin
                    start_seen <= 1'b1;
                    pulse_count <= 64'd2;
                    phase <= RUN;
                end
                RUN: begin
                    if (finish_fire) begin
                        pulse_count <= 64'd0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= IDLE;
                    end else begin
                        pulse_count <= pulse_count + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    pulse_count <= 64'd0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end

        if (finish_fire) begin
            // Record: ARM witness, START witness, sampled mode,
            // and the number of accepted pulses in this division.
            event_mem[wr_ptr] <= (pulse_count + 64'd1)
                | (arm_seen ? 64'h8000000000000000 : 64'd0)
                | (start_seen ? 64'h4000000000000000 : 64'd0)
                | (mode_q ? 64'h2000000000000000 : 64'd0);
            wr_ptr <= (wr_ptr == DEPTH - 64'd1)
                    ? 64'd0 : wr_ptr + 64'd1;
        end
        if (pop_fire)
            rd_ptr <= (rd_ptr == DEPTH - 64'd1)
                    ? 64'd0 : rd_ptr + 64'd1;

        case ({finish_fire, pop_fire})
            2'b10: fifo_count <= fifo_count + 64'd1;
            2'b01: fifo_count <= fifo_count - 64'd1;
            default: begin end
        endcase
    end

    // The drain-ready input also clocks acceptance of trace symbols.
    // Frames contain a low start, the complete record, and a high stop.
    always @(*) begin
        o_trace_bit = 1'b1;
        if (trace_active) begin
            if (trace_index == 7'd0)
                o_trace_bit = 1'b0;
            else if (trace_index <= 7'd64)
                o_trace_bit = trace_shift[0];
        end
    end

    always @(posedge clk) begin
        if (trace_push) begin
            trace_mem[trace_wr[TRACE_ADDR_W-1:0]] <= o_data;
            trace_wr <= trace_wr + 1'b1;
        end
        if (trace_load) begin
            trace_shift <= trace_mem[trace_rd[TRACE_ADDR_W-1:0]];
            trace_rd <= trace_rd + 1'b1;
            trace_index <= 7'd0;
            trace_active <= 1'b1;
        end else if (trace_step) begin
            if (trace_done) begin
                trace_active <= 1'b0;
                trace_index <= 7'd0;
            end else begin
                trace_index <= trace_index + 7'd1;
                if (trace_index != 7'd0)
                    trace_shift <= {1'b0, trace_shift[63:1]};
            end
        end
    end

    always @(posedge clk)
        if (trace_step && ((trace_index == 7'd63)
                          || (trace_index == 7'd64)))
            assert (scope_armed && o_trace_bit);

    // After Q: START requires ARM, and every observable FINISH
    // must carry both earlier event witnesses.
    always @(posedge clk)
        if (scope_armed)
            assert ((!start_seen || arm_seen)
                    && (!o_valid || (o_data[63] && o_data[62])));
endmodule

module masked_pipe_dispatch #(
    parameter integer DATA_W = 64,
    parameter integer CHANNELS = 16
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  write_mask,
    input  wire [DATA_W-1:0]     mask_data,
    input  wire                  dispatch,
    input  wire                  end_window,
    output reg  [DATA_W-1:0]     issued_count,
    output reg  [DATA_W-1:0]     last_index,
    output reg                   last_valid,
    output reg  [39:0]           debug_status
);
    // Supported configurations have 1 <= CHANNELS <= DATA_W.
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] CAPACITY = DATA_W'(CHANNELS);
    localparam [DATA_W-1:0] CHANNEL_BITS =
        {DATA_W{1'b1}} >> (DATA_W - CHANNELS);

    // Each channel initially has one pending notification.
    reg [DATA_W-1:0] pending;
    reg [DATA_W-1:0] sw_mask;
    reg before_window_end;
    reg past_valid;

    // Lowest numbered enabled request has highest priority.
    function automatic [DATA_W-1:0] priority_index(
        input [DATA_W-1:0] bits
    );
        integer j;
        begin
            priority_index = ZERO;
            for (j = CHANNELS - 1; j >= 0; j = j - 1)
                if (bits[j])
                    priority_index = DATA_W'(j);
        end
    endfunction

    wire [DATA_W-1:0] eligible = pending & sw_mask;
    wire [DATA_W-1:0] encoded_index = priority_index(eligible);

    // Mask writes take priority over dispatch commands.
    wire take = dispatch && last_valid && !write_mask;
    wire [DATA_W-1:0] next_mask =
        write_mask ? (mask_data & CHANNEL_BITS) : sw_mask;
    wire [DATA_W-1:0] next_pending =
        take ? (pending & ~(ONE << last_index)) : pending;
    wire [DATA_W-1:0] next_eligible = next_pending & next_mask;

    reg [DATA_W-1:0] pending_population;
    integer p;
    always @(*) begin
        pending_population = ZERO;
        for (p = 0; p < CHANNELS; p = p + 1)
            pending_population = pending_population +
                {{(DATA_W-1){1'b0}}, pending[p]};
    end

    initial begin
        pending = CHANNEL_BITS;
        sw_mask = CHANNEL_BITS;
        issued_count = ZERO;
        last_index = ZERO;
        last_valid = 1'b1;
        before_window_end = 1'b1;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            pending <= next_pending;
            sw_mask <= next_mask;
            last_index <= priority_index(next_eligible);
            last_valid <= (next_eligible != ZERO);
            if (take)
                issued_count <= issued_count + ONE;
            if (end_window)
                before_window_end <= 1'b0;
            past_valid <= 1'b1;
        end
    end

   reg [7:0] dbg_accepted;
   reg [7:0] dbg_blocked;
   reg [7:0] dbg_mask_writes;
   reg [7:0] dbg_idle_streak;
   reg [7:0] dbg_idle_peak;

   initial begin
       dbg_accepted = 8'd0;
       dbg_blocked = 8'd0;
       dbg_mask_writes = 8'd0;
       dbg_idle_streak = 8'd0;
       dbg_idle_peak = 8'd0;
       debug_status = 40'd0;
   end

   always @(posedge clk) begin
       if (ce) begin
           if (take && dbg_accepted != 8'hff)
               dbg_accepted <= dbg_accepted + 8'd1;
           if (dispatch && !take && dbg_blocked != 8'hff)
               dbg_blocked <= dbg_blocked + 8'd1;
           if (write_mask && dbg_mask_writes != 8'hff)
               dbg_mask_writes <= dbg_mask_writes + 8'd1;
           if (dispatch || write_mask)
               dbg_idle_streak <= 8'd0;
           else if (dbg_idle_streak != 8'hff)
               dbg_idle_streak <= dbg_idle_streak + 8'd1;
           if (!dispatch && !write_mask &&
               dbg_idle_streak != 8'hff &&
               dbg_idle_streak >= dbg_idle_peak)
               dbg_idle_peak <= dbg_idle_streak + 8'd1;
           debug_status <= {dbg_idle_peak, dbg_idle_streak,
                            dbg_mask_writes, dbg_blocked, dbg_accepted};
       end
   end

    // Before the first enabled end_window event, an unchanged request
    // set means no additional dispatches, and the batch budget holds.
    always @(posedge clk)
        if (past_valid && before_window_end && $stable(pending))
            assert ($stable(issued_count) && issued_count <= CAPACITY);
endmodule

module retirement_batch_fifo #(
    parameter [31:0] DEPTH = 32'd16,
    parameter integer WORD_W = 32'd32
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_word_valid,
    output wire                  o_word_ready,
    input  wire [WORD_W-1:0]     i_word,
    input  wire                  i_commit_valid,
    output wire                  o_commit_ready,
    input  wire                  i_trap,
    output wire                  o_retire_fire,
    output wire [WORD_W-1:0]     o_retire_word,
    output wire                  o_commit_done,
    output reg  [35:0]           o_debug_stats
);
    // DEPTH is a power of two. Service cycles are cycles with i_ce high.
    localparam integer ADDR_W = $clog2(DEPTH);
    localparam [31:0] PTR_MOD = DEPTH + DEPTH;
    localparam [31:0] PTR_LAST = PTR_MOD - 32'd1;

    typedef enum logic [1:0] {
        FILL     = 2'd0,
        DRAIN    = 2'd1,
        COMPLETE = 2'd2
    } state_t;

    state_t state;
    // Address plus wrap bit, carried in the requested 32-bit registers.
    // Bits above ADDR_W remain zero.
    reg [31:0] wr_ptr;
    reg [31:0] rd_ptr;
    reg [31:0] deadline;
    reg [WORD_W-1:0] storage [0:DEPTH-1];
    reg before_trap;
    reg pv;

    initial begin
        state = FILL;
        wr_ptr = 32'd0;
        rd_ptr = 32'd0;
        deadline = 32'd0;
        before_trap = 1'b1;
        pv = 1'b0;
        for (integer n = 32'd0; n < DEPTH; n = n + 32'd1)
            storage[n] = {WORD_W{1'b0}};
    end

    wire empty = (wr_ptr == rd_ptr);
    wire full = (wr_ptr[ADDR_W-1:0] == rd_ptr[ADDR_W-1:0]) &&
                (wr_ptr[ADDR_W] != rd_ptr[ADDR_W]);
    wire [31:0] wr_next = (wr_ptr == PTR_LAST) ? 32'd0 :
                                                        wr_ptr + 32'd1;
    wire [31:0] rd_next = (rd_ptr == PTR_LAST) ? 32'd0 :
                                                        rd_ptr + 32'd1;
    // Combinational pointer distance, not an occupancy register.
    wire [31:0] used_words = (wr_ptr >= rd_ptr) ?
                            (wr_ptr - rd_ptr) :
                            (PTR_MOD - (rd_ptr - wr_ptr));

    assign o_commit_ready = i_ce && (state == FILL);
    // Sealing a batch takes priority over accepting another word.
    assign o_word_ready = i_ce && (state == FILL) &&
                          !full && !i_commit_valid;
    // The retirement port is an always-accepting execution sink.
    assign o_retire_fire = i_ce && (state == DRAIN) && !empty;
    assign o_retire_word = storage[rd_ptr[ADDR_W-1:0]];
    assign o_commit_done = (state == COMPLETE);
    reg [7:0] dbg_accepted;
    reg [7:0] dbg_retired;
    reg [7:0] dbg_commits;
    reg [7:0] dbg_stalls;
    reg [3:0] dbg_overflow;
    initial begin
        dbg_accepted = 8'd0;
        dbg_retired = 8'd0;
        dbg_commits = 8'd0;
        dbg_stalls = 8'd0;
        dbg_overflow = 4'd0;
        o_debug_stats = 36'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_word_valid && o_word_ready) begin
                if (dbg_accepted != 8'hff)
                    dbg_accepted <= dbg_accepted + 8'd1;
                else
                    dbg_overflow[0] <= 1'b1;
            end
            if (o_retire_fire) begin
                if (dbg_retired != 8'hff)
                    dbg_retired <= dbg_retired + 8'd1;
                else
                    dbg_overflow[1] <= 1'b1;
            end
            if (i_commit_valid && o_commit_ready) begin
                if (dbg_commits != 8'hff)
                    dbg_commits <= dbg_commits + 8'd1;
                else
                    dbg_overflow[2] <= 1'b1;
            end
            if (i_word_valid && !o_word_ready) begin
                if (dbg_stalls != 8'hff)
                    dbg_stalls <= dbg_stalls + 8'd1;
                else
                    dbg_overflow[3] <= 1'b1;
            end
            o_debug_stats <= {dbg_overflow, dbg_stalls, dbg_commits, dbg_retired, dbg_accepted};
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (i_trap)
                before_trap <= 1'b0;

            case (state)
                FILL: begin
                    if (i_commit_valid && o_commit_ready) begin
                        if (empty) begin
                            state <= COMPLETE;
                            deadline <= 32'd0;
                        end else begin
                            state <= DRAIN;
                            deadline <= DEPTH;
                        end
                    end else if (i_word_valid && o_word_ready) begin
                        storage[wr_ptr[ADDR_W-1:0]] <= i_word;
                        wr_ptr <= wr_next;
                    end
                end

                DRAIN: begin
                    if (empty) begin
                        state <= COMPLETE;
                        deadline <= 32'd0;
                    end else begin
                        rd_ptr <= rd_next;
                        if (rd_next == wr_ptr) begin
                            state <= COMPLETE;
                            deadline <= 32'd0;
                        end else if (deadline != 32'd0) begin
                            deadline <= deadline - 32'd1;
                        end
                    end
                end

                COMPLETE: begin
                    state <= FILL;
                end
            endcase
        end
    end

    // If the previous service cycle consumed the final budget tick,
    // its accepted commit request must now be complete, not outstanding.
    always @(posedge clk)
        if (pv && before_trap &&
            $past(i_ce && (state == DRAIN) && (deadline == 32'd1)))
            assert (state == COMPLETE);
endmodule

module timestamp_request_queue #(
    parameter integer WORD_W = 64,
    parameter integer DEPTH = 4
) (
    input wire clk, i_ce,
    input wire in_valid,
    output wire in_ready,
    input wire [WORD_W-1:0] in_addr, in_len, in_stamp,
    input wire [2:0] in_size,
    input wire [1:0] in_burst,
    output wire out_valid,
    input wire retire,
    output wire [WORD_W-1:0] out_addr, out_len, out_stamp,
    output wire [2:0] out_size,
    output wire [1:0] out_burst,
    output logic [$clog2(DEPTH+1)-1:0] count,
    output logic [$clog2(DEPTH)-1:0] read_ptr, write_ptr,
    output logic [DEPTH*WORD_W-1:0] length_words
);
    localparam integer PTR_W = $clog2(DEPTH);
    logic [WORD_W-1:0] addresses [0:DEPTH-1];
    logic [WORD_W-1:0] lengths [0:DEPTH-1];
    logic [WORD_W-1:0] stamps [0:DEPTH-1];
    logic [2:0] sizes [0:DEPTH-1];
    logic [1:0] bursts [0:DEPTH-1];
    wire push, pop;
    assign in_ready = i_ce && (count < DEPTH);
    assign out_valid = (count != 0);
    assign push = in_valid && in_ready;
    assign pop = i_ce && retire && out_valid;
    assign out_addr = addresses[read_ptr];
    assign out_len = lengths[read_ptr];
    assign out_stamp = stamps[read_ptr];
    assign out_size = sizes[read_ptr];
    assign out_burst = bursts[read_ptr];
    integer k;
    initial begin
        count = 0; read_ptr = 0; write_ptr = 0;
        for (k = 0; k < DEPTH; k = k + 1) begin
            addresses[k] = {WORD_W{1'b0}};
            lengths[k] = {WORD_W{1'b0}};
            stamps[k] = {WORD_W{1'b0}};
            sizes[k] = 3'b000;
            bursts[k] = 2'b00;
        end
    end
    integer n;
    always @(*) begin
        for (n = 0; n < DEPTH; n = n + 1)
            length_words[n*WORD_W +: WORD_W] = lengths[n];
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (push) begin
                addresses[write_ptr] <= in_addr;
                lengths[write_ptr] <= in_len;
                stamps[write_ptr] <= in_stamp;
                sizes[write_ptr] <= in_size;
                bursts[write_ptr] <= in_burst;
                write_ptr <= (write_ptr == PTR_W'(DEPTH-1)) ? {PTR_W{1'b0}} : write_ptr + 1'b1;
            end
            if (pop)
                read_ptr <= (read_ptr == PTR_W'(DEPTH-1)) ? {PTR_W{1'b0}} : read_ptr + 1'b1;
            case ({push, pop})
                2'b10: count <= count + 1'b1;
                2'b01: count <= count - 1'b1;
                default: begin end
            endcase
        end
    end
endmodule

module axi_timestamp_reader #(
    parameter integer WORD_W = 64,
    parameter integer MAX_BEATS = 8,
    parameter integer REQUEST_DEPTH = 4
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  arvalid,
    output wire                  arready,
    input  wire [WORD_W-1:0]     araddr,
    input  wire [WORD_W-1:0]     arlen,
    input  wire [2:0]            arsize,
    input  wire [1:0]            arburst,
    output wire                  rvalid,
    input  wire                  rready,
    output logic [WORD_W-1:0]    rdata,
    output logic [1:0]           rresp,
    output wire                  rlast,
    output wire [$clog2(REQUEST_DEPTH+1)-1:0] pending_requests
);
    localparam logic [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam logic [WORD_W-1:0] ONE = WORD_W'(32'd1);
    localparam logic [WORD_W-1:0] MAX_LEN = WORD_W'(MAX_BEATS) - ONE;
    localparam logic [WORD_W-1:0] ADDR_MASK = WORD_W'(WORD_W / 32'd8) - ONE;
    localparam logic [2:0] BEAT_SIZE = 3'($clog2(WORD_W / 32'd8));
    localparam logic [1:0] RESP_OKAY = 2'b00;
    localparam logic [1:0] RESP_SLVERR = 2'b10;

    typedef enum logic [1:0] {
        IDLE  = 2'b00,
        FETCH = 2'b01,
        SEND  = 2'b10
    } state_t;
    state_t state;

    logic [WORD_W-1:0] timestamp_counter;
    logic [WORD_W-1:0] captured_addr;
    logic [WORD_W-1:0] captured_len;
    logic [2:0] captured_size;
    logic [1:0] captured_burst;
    logic [WORD_W-1:0] beat_index;
    logic [WORD_W-1:0] base_stamp;

    // Acceptance-history shadow and the acceptance-to-completion window.
    logic [WORD_W-1:0] request_stamp;
    logic request_seen;
    logic window_open;
    localparam integer QPTR_W = $clog2(REQUEST_DEPTH);
    wire q_ready, q_valid;
    wire [WORD_W-1:0] q_addr, q_len, q_stamp;
    wire [2:0] q_size;
    wire [1:0] q_burst;
    wire [QPTR_W-1:0] q_read_ptr, q_write_ptr;
    wire [REQUEST_DEPTH*WORD_W-1:0] q_lengths;
    wire q_retire;
    assign q_retire = i_ce && (state == SEND) && rready && rlast;
    timestamp_request_queue #(.WORD_W(WORD_W), .DEPTH(REQUEST_DEPTH)) request_queue (
        .clk(clk), .i_ce(i_ce),
        .in_valid(arvalid && (arlen <= MAX_LEN)), .in_ready(q_ready),
        .in_addr(araddr), .in_len(arlen), .in_stamp(timestamp_counter),
        .in_size(arsize), .in_burst(arburst),
        .out_valid(q_valid), .retire(q_retire),
        .out_addr(q_addr), .out_len(q_len), .out_stamp(q_stamp),
        .out_size(q_size), .out_burst(q_burst),
        .count(pending_requests), .read_ptr(q_read_ptr), .write_ptr(q_write_ptr),
        .length_words(q_lengths)
    );

    // The clock enable gates both interface transfers and every state update.
    assign arready = q_ready && (arlen <= MAX_LEN);
    assign rvalid = i_ce && (state == SEND);
    assign rlast = (state == SEND) && (beat_index == captured_len);

    initial begin
        state = IDLE;
        timestamp_counter = ZERO;
        captured_addr = ZERO;
        captured_len = ZERO;
        captured_size = BEAT_SIZE;
        captured_burst = 2'b01;
        beat_index = ZERO;
        base_stamp = ZERO;
        request_stamp = ZERO;
        request_seen = 1'b0;
        window_open = 1'b0;
        rdata = ZERO;
        rresp = RESP_OKAY;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            timestamp_counter <= timestamp_counter + ONE;
            case (state)
                IDLE: begin
                    if (q_valid) begin
                        captured_addr <= q_addr;
                        captured_len <= q_len;
                        captured_size <= q_size;
                        captured_burst <= q_burst;
                        beat_index <= ZERO;
                        base_stamp <= q_stamp;
                        request_stamp <= q_stamp;
                        request_seen <= 1'b1;
                        window_open <= 1'b1;
                        rresp <= (((q_addr & ADDR_MASK) == ZERO) &&
                                  (q_size == BEAT_SIZE) &&
                                  (q_burst == 2'b01)) ? RESP_OKAY : RESP_SLVERR;
                        state <= FETCH;
                    end
                end
                FETCH: begin
                    // Each burst returns a sequence based on its captured time.
                    rdata <= q_stamp + beat_index;
                    state <= SEND;
                end
                SEND: begin
                    if (rready) begin
                        if (beat_index == captured_len) begin
                            window_open <= 1'b0;
                            request_seen <= 1'b0;
                            state <= IDLE;
                        end else begin
                            beat_index <= beat_index + ONE;
                            state <= FETCH;
                        end
                    end
                end
                default: begin
                    state <= IDLE;
                    window_open <= 1'b0;
                    request_seen <= 1'b0;
                end
            endcase
        end
    end

    // A prepared successful response must follow an address acceptance and
    // carry the timestamp sequence established by that earlier acceptance.
    always @(posedge clk)
        if (window_open && (state == SEND) && (rresp == RESP_OKAY))
            assert (request_seen && (rdata == request_stamp + beat_index));
endmodule

module coefficient_write_queue #(
    parameter integer WORD_BITS = 64, LANES = 8, DEPTH = 4,
    parameter integer COUNT_BITS = $clog2(DEPTH+1), POP_BITS = $clog2(LANES+1)
) (
    input wire clk, rst_n, push, pop,
    input wire [WORD_BITS-1:0] in_word,
    input wire [POP_BITS-1:0] in_before,
    output wire ready,
    output reg [COUNT_BITS-1:0] count,
    output reg [DEPTH*WORD_BITS-1:0] words,
    output reg [DEPTH*POP_BITS-1:0] before_words
);
    reg [WORD_BITS-1:0] data [0:DEPTH-1];
    reg [POP_BITS-1:0] prior [0:DEPTH-1];
    integer k, j;
    assign ready = (count < DEPTH) || pop;
    initial begin
        count = {COUNT_BITS{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin data[k] = {WORD_BITS{1'b0}}; prior[k] = {POP_BITS{1'b0}}; end
    end
    always @(*) begin
        for (j = 0; j < DEPTH; j = j + 1) begin
            words[j*WORD_BITS +: WORD_BITS] = data[j]; before_words[j*POP_BITS +: POP_BITS] = prior[j];
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= {COUNT_BITS{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin data[k] <= {WORD_BITS{1'b0}}; prior[k] <= {POP_BITS{1'b0}}; end
        end else begin
            case ({push, pop}) 2'b10: count <= count + 1'b1; 2'b01: count <= count - 1'b1; default: count <= count; endcase
            if (pop) for (k = 0; k < DEPTH-1; k = k + 1) begin
                data[k] <= data[k+1]; prior[k] <= prior[k+1];
            end
            if (push) begin data[count-pop] <= in_word; prior[count-pop] <= in_before; end
        end
    end
endmodule

module rotation_coefficient_register #(
    parameter integer BYTE_LANES = 8,
    parameter integer WRITE_DEPTH = 4
) (
    input  wire                        clk,
    input  wire                        rst_n,
    input  wire                        i_ce,
    input  wire                        i_write,
    input  wire [BYTE_LANES-1:0]       i_byte_en,
    input  wire [8*BYTE_LANES-1:0]     i_write_data,
    input  wire                        window_open,
    input  wire                        window_close,
    output reg  [8*BYTE_LANES-1:0]     coefficient_word,
    output reg  [63:0]                 nonzero_bytes,
    output reg                         window,
    output wire                        i_write_ready,
    output wire [$clog2(WRITE_DEPTH+1)-1:0] pending_writes
);
    localparam integer WORD_BITS = 8 * BYTE_LANES;
    localparam [63:0] BYTE_LIMIT = BYTE_LANES;

    wire [WORD_BITS-1:0] merged_word;
    localparam integer POP_BITS = $clog2(BYTE_LANES+1);
    wire [WRITE_DEPTH*WORD_BITS-1:0] queued_words;
    wire [WRITE_DEPTH*POP_BITS-1:0] queued_before;
    wire [WORD_BITS-1:0] write_base;
    wire [POP_BITS-1:0] base_population;
    wire retire_write;
    assign retire_write = i_ce && window && (pending_writes != 0);
    assign write_base = (pending_writes != 0)
        ? queued_words[(pending_writes-1'b1)*WORD_BITS +: WORD_BITS] : coefficient_word;
    assign base_population = populated_byte_count(write_base);
    coefficient_write_queue #(.WORD_BITS(WORD_BITS), .LANES(BYTE_LANES), .DEPTH(WRITE_DEPTH)) writes (
        .clk(clk), .rst_n(rst_n), .push(i_ce && i_write && i_write_ready), .pop(retire_write),
        .in_word(merged_word), .in_before(base_population),
        .ready(i_write_ready), .count(pending_writes), .words(queued_words), .before_words(queued_before));

    genvar lane;
    generate
        for (lane = 0; lane < BYTE_LANES; lane = lane + 1) begin : byte_merge
            assign merged_word[8*lane +: 8] =
                (i_write && i_byte_en[lane])
                ? i_write_data[8*lane +: 8]
                : write_base[8*lane +: 8];
        end
    endgenerate

    function automatic [63:0] populated_byte_count(
        input [WORD_BITS-1:0] word_value
    );
        integer b;
        begin
            populated_byte_count = 64'd0;
            for (b = 0; b < BYTE_LANES; b = b + 1)
                populated_byte_count = populated_byte_count +
                    ((word_value[8*b +: 8] != 8'h00) ? 64'd1 : 64'd0);
        end
    endfunction

    wire [63:0] stored_population;
    wire [63:0] commit_population;
    assign stored_population = populated_byte_count(coefficient_word);
    assign commit_population = populated_byte_count(queued_words[0 +: WORD_BITS]);

    initial begin
        coefficient_word = {WORD_BITS{1'b0}};
        nonzero_bytes = 64'd0;
        window = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            coefficient_word <= {WORD_BITS{1'b0}};
            nonzero_bytes <= 64'd0;
            window <= 1'b0;
        end else if (i_ce) begin
            if (retire_write) begin
                coefficient_word <= queued_words[0 +: WORD_BITS];
                nonzero_bytes <= nonzero_bytes + commit_population - queued_before[0 +: POP_BITS];
            end
            if (window_close)
                window <= 1'b0;
            else if (window_open)
                window <= 1'b1;
        end
    end

    always @(*) begin
        if (window)
            assert (nonzero_bytes <= BYTE_LIMIT);
    end
endmodule

module sampled_i2c_event_queue #(
    parameter integer WORD_BITS = 64,
parameter integer DEPTH = 2,
parameter integer PEER_DEPTH = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire sample_scl,
    input  wire sample_sda,
    output wire sample_ready,
    output wire start_event,
    output wire repeated_start_event,
    output wire stop_event,
    output reg  bus_busy,
    output wire [WORD_BITS-1:0] active_event,
output wire [WORD_BITS-1:0] active_ticket,
input  wire peer_valid,
input  wire [WORD_BITS-1:0] peer_data,
input  wire peer_last,
output wire peer_ready,
output reg  completion_valid,
output reg  completion_peer,
output reg  completion_last,
output reg  [WORD_BITS-1:0] completion_data,
output reg  [WORD_BITS-1:0] completion_ticket
);
    localparam [WORD_BITS-1:0] ZERO = {WORD_BITS{1'b0}};
    localparam [WORD_BITS-1:0] ONE = {{(WORD_BITS-1){1'b0}}, 1'b1};
    localparam [WORD_BITS-1:0] TWO = ONE + ONE;
    localparam [WORD_BITS-1:0] THREE = TWO + ONE;
    localparam [WORD_BITS-1:0] DEPTH_VALUE = DEPTH;
    localparam [WORD_BITS-1:0] MAX_TICKS =
        (DEPTH_VALUE > ONE) ? DEPTH_VALUE * TWO - ONE : TWO;
    localparam integer CHANNELS = 2;
    localparam integer PEER_PTR_BITS = (PEER_DEPTH > 1) ? $clog2(PEER_DEPTH) : 1;
    localparam integer PEER_COUNT_BITS = $clog2(PEER_DEPTH + 1);

    reg prev_scl;
    reg prev_sda;
    reg window;
    reg pv;
    reg [WORD_BITS-1:0] count;
    reg [WORD_BITS-1:0] rd_ptr;
    reg [WORD_BITS-1:0] wr_ptr;
    reg [WORD_BITS-1:0] issued;
    reg [WORD_BITS-1:0] retired;
    reg [DEPTH-1:0] valid;

    // Event codes: ordinary START, repeated START, and STOP.
    reg [WORD_BITS-1:0] payload [0:DEPTH-1];
    reg [WORD_BITS-1:0] ticket [0:DEPTH-1];
    reg [WORD_BITS-1:0] remaining [0:DEPTH-1];
    reg [WORD_BITS-1:0] deadline [0:DEPTH-1];

    wire [WORD_BITS-1:0] distance [0:DEPTH-1];
    wire [WORD_BITS-1:0] service_need [0:DEPTH-1];
    wire [DEPTH-1:0] due_mask;
    wire [DEPTH-1:0] slot_relation;

    reg [WORD_BITS-1:0] peer_q [0:PEER_DEPTH-1];
    reg [PEER_PTR_BITS-1:0] peer_rd;
    reg [PEER_COUNT_BITS-1:0] peer_count;
    reg peer_sealed;
    wire [CHANNELS-1:0] port_request;
    reg [CHANNELS-1:0] port_grant;
    wire event_wait;
    wire peer_push = peer_valid && peer_ready;
    wire peer_send = port_grant[1];

    assign port_request[0] = (count != ZERO) && (remaining[rd_ptr] == ONE);
    assign port_request[1] = peer_sealed;
    // Drain sealed packets in bursts, except at a primary deadline.
    always @(*) begin
        port_grant = {CHANNELS{1'b0}};
        if (port_request[1] && !(|due_mask))
            port_grant[1] = 1'b1;
        else
            port_grant[0] = port_request[0];
    end
    assign event_wait = port_request[0] && !port_grant[0];
    assign peer_ready = !peer_sealed && (peer_count < PEER_DEPTH);

    assign sample_ready = (count < DEPTH_VALUE) && !event_wait;
    assign start_event = sample_ready && prev_scl && sample_scl &&
                         prev_sda && !sample_sda;
    assign stop_event = sample_ready && prev_scl && sample_scl &&
                        !prev_sda && sample_sda;
    assign repeated_start_event = start_event && bus_busy;

    wire enqueue = start_event || stop_event;
    wire dequeue = port_grant[0];
    wire [WORD_BITS-1:0] incoming_event =
        stop_event ? THREE : (bus_busy ? TWO : ONE);

    assign active_event = (count != ZERO) ? payload[rd_ptr] : ZERO;
    assign active_ticket = (count != ZERO) ? ticket[rd_ptr] : ZERO;

    initial begin
        prev_scl = 1'b1;
        prev_sda = 1'b1;
        bus_busy = 1'b0;
        window = 1'b0;
        pv = 1'b0;
        count = ZERO;
        rd_ptr = ZERO;
        wr_ptr = ZERO;
        issued = ZERO;
        retired = ZERO;
    end

    integer j;
    initial begin
        peer_rd = 0;
        peer_count = 0;
        peer_sealed = 1'b0;
        completion_valid = 1'b0;
        completion_peer = 1'b0;
        completion_last = 1'b0;
        completion_data = ZERO;
        completion_ticket = ZERO;
        for (j = 0; j < PEER_DEPTH; j = j + 1)
            peer_q[j] = ZERO;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            completion_valid <= |port_grant;
            if (|port_grant) begin
                completion_peer <= peer_send;
                completion_data <= peer_send ? peer_q[peer_rd] : payload[rd_ptr];
                completion_ticket <= peer_send ? ZERO : ticket[rd_ptr];
                completion_last <= !peer_send || (peer_count == 1);
            end
            if (peer_push) begin
                peer_q[peer_count] <= peer_data;
                peer_count <= peer_count + 1'b1;
                if (peer_last || (peer_count == PEER_DEPTH - 1))
                    peer_sealed <= 1'b1;
            end
            if (peer_send) begin
                peer_count <= peer_count - 1'b1;
                if (peer_count == 1) begin
                    peer_rd <= 0;
                    peer_sealed <= 1'b0;
                end else
                    peer_rd <= peer_rd + 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (i_ce)
            assert ((!completion_valid || completion_peer ||
                     (completion_ticket + ONE == retired)) &&
                    (!port_grant[1] ||
                     ((peer_count != 0) && (peer_count <= PEER_DEPTH))));

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            // A full queue backpressures sampling, without overwriting events.
            if (sample_ready) begin
                prev_scl <= sample_scl;
                prev_sda <= sample_sda;
                if (start_event) begin
                    bus_busy <= 1'b1;
                    window <= 1'b1;
                end else if (stop_event) begin
                    bus_busy <= 1'b0;
                    window <= 1'b0;
                end
            end

            case ({enqueue, dequeue})
                2'b10: count <= count + ONE;
                2'b01: count <= count - ONE;
                default: count <= count;
            endcase

            if (enqueue) begin
                issued <= issued + ONE;
                wr_ptr <= (wr_ptr == DEPTH_VALUE - ONE) ? ZERO : wr_ptr + ONE;
            end
            if (dequeue) begin
                retired <= retired + ONE;
                rd_ptr <= (rd_ptr == DEPTH_VALUE - ONE) ? ZERO : rd_ptr + ONE;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : slots
            localparam [WORD_BITS-1:0] SLOT = g;

            initial begin
                valid[g] = 1'b0;
                payload[g] = ZERO;
                ticket[g] = ZERO;
                remaining[g] = ZERO;
                deadline[g] = ZERO;
            end

            assign distance[g] = (SLOT >= rd_ptr) ?
                SLOT - rd_ptr : SLOT + DEPTH_VALUE - rd_ptr;
            assign service_need[g] = remaining[rd_ptr] + TWO * distance[g];
            assign due_mask[g] = valid[g] && (deadline[g] == ONE);

            // These are same-cycle structural facts, not assertions.
            // Only the oldest entry works; every younger entry needs two ticks.
            assign slot_relation[g] =
                (valid[g] == (distance[g] < count)) &&
                (valid[g] ?
                    ((payload[g] == ONE || payload[g] == TWO || payload[g] == THREE) &&
                     (ticket[g] == retired + distance[g]) &&
                     (remaining[g] >= ONE) && (remaining[g] <= TWO) &&
                     ((distance[g] == ZERO) || (remaining[g] == TWO)) &&
                     (deadline[g] >= service_need[g]) &&
                     (deadline[g] <= MAX_TICKS)) :
                    ((payload[g] == ZERO) && (ticket[g] == ZERO) &&
                     (remaining[g] == ZERO) && (deadline[g] == ZERO)));

            always @(posedge clk) begin
                if (i_ce && !event_wait) begin
                    if (valid[g])
                        deadline[g] <= deadline[g] - ONE;

                    if ((count != ZERO) && (rd_ptr == SLOT) &&
                        (remaining[g] > ONE))
                        remaining[g] <= remaining[g] - ONE;

                    if (dequeue && (rd_ptr == SLOT)) begin
                        valid[g] <= 1'b0;
                        payload[g] <= ZERO;
                        ticket[g] <= ZERO;
                        remaining[g] <= ZERO;
                        deadline[g] <= ZERO;
                    end

                    if (enqueue && (wr_ptr == SLOT)) begin
                        valid[g] <= 1'b1;
                        payload[g] <= incoming_event;
                        ticket[g] <= issued;
                        remaining[g] <= TWO;
                        deadline[g] <= MAX_TICKS;
                    end
                end
            end
        end
    endgenerate

    // Within a START-to-STOP window, an outstanding request on its
    // previous enabled tick's last deadline count must now be complete.
    always @(posedge clk)
        if (pv && $past(window) && $past(i_ce))
            assert ((valid & $past(due_mask)) == {DEPTH{1'b0}});
endmodule

module chien_scan_engine #(
    parameter integer COEFFS = 16
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  i_valid,
    output wire                  i_ready,
    input  wire [8*COEFFS-1:0]   i_coeffs,
    output reg                   o_valid,
    input  wire                  o_ready,
    output reg  [7:0]            o_position,
    output reg  [7:0]            o_value,
    output reg                   o_root,
    input  wire                  peer_i_valid,
    output wire                  peer_i_ready,
    input  wire [8*COEFFS-1:0]   peer_i_coeffs,
    output reg                   peer_o_valid,
    input  wire                  peer_o_ready,
    output reg  [7:0]            peer_o_position,
    output reg  [7:0]            peer_o_value,
    output reg                   peer_o_root
);
    // GF(256), with primitive polynomial x^8+x^4+x^3+x^2+1.
    function automatic [7:0] xtime;
        input [7:0] a;
        begin
            xtime = {a[6:0], 1'b0} ^ (a[7] ? 8'h1d : 8'h00);
        end
    endfunction

    function automatic [7:0] gf_mul;
        input [7:0] a;
        input [7:0] b;
        reg [7:0] aa, bb, product;
        integer k;
        begin
            aa = a;
            bb = b;
            product = 8'h00;
            for (k = 0; k < 8; k = k + 1) begin
                if (bb[0])
                    product = product ^ aa;
                aa = xtime(aa);
                bb = {1'b0, bb[7:1]};
            end
            gf_mul = product;
        end
    endfunction

    function automatic [7:0] alpha_power;
        input integer exponent;
        reg [7:0] value;
        integer k;
        begin
            value = 8'h01;
            for (k = 0; k < exponent; k = k + 1)
                value = xtime(value);
            alpha_power = value;
        end
    endfunction

    reg [7:0] terms [0:COEFFS-1];
    wire [7:0] next_terms [0:COEFFS-1];
    reg [7:0] eval_cache;
    reg [7:0] scan_position;
    reg window;
    localparam integer CHANNELS = 2;
    wire [CHANNELS-1:0] request_grant;
    reg [7:0] peer_cache, peer_scan_position;
    reg [7:0] peer_load_sum;

    reg [7:0] load_sum;
    reg [7:0] term_sum;
    reg [7:0] next_sum;
    integer reduction_index;

    genvar lane;
    generate
        for (lane = 0; lane < COEFFS; lane = lane + 1) begin : multipliers
            assign next_terms[lane] =
                gf_mul(terms[lane], alpha_power(lane));
        end
    endgenerate

    always @(*) begin
        load_sum = 8'h00;
        peer_load_sum = 8'h00;
        term_sum = 8'h00;
        next_sum = 8'h00;
        for (reduction_index = 0; reduction_index < COEFFS;
             reduction_index = reduction_index + 1) begin
            load_sum = load_sum ^ i_coeffs[8*reduction_index +: 8];
            peer_load_sum = peer_load_sum ^ peer_i_coeffs[8*reduction_index +: 8];
            term_sum = term_sum ^ terms[reduction_index];
            next_sum = next_sum ^ next_terms[reduction_index];
        end
    end

    // A polynomial cannot be replaced while its result stream is pending.
    // Reserve the shared coefficient bank through the final result handshake.
    assign i_ready = !o_valid && !peer_o_valid;
    assign peer_i_ready = !o_valid && !peer_o_valid && !i_valid;
    assign request_grant = {peer_i_valid && peer_i_ready, i_valid && i_ready};

    integer init_index;
    initial begin
        o_valid = 1'b0;
        o_position = 8'h00;
        o_value = 8'h00;
        o_root = 1'b1;
        eval_cache = 8'h00;
        scan_position = 8'h01;
        window = 1'b0;
        peer_o_valid = 1'b0;
        peer_o_position = 8'h00;
        peer_o_value = 8'h00;
        peer_o_root = 1'b1;
        peer_cache = 8'h00;
        peer_scan_position = 8'h01;
        for (init_index = 0; init_index < COEFFS; init_index = init_index + 1)
            terms[init_index] = 8'h00;
    end

    integer state_index;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_valid <= 1'b0;
            o_position <= 8'h00;
            o_value <= 8'h00;
            o_root <= 1'b1;
            eval_cache <= 8'h00;
            scan_position <= 8'h01;
            window <= 1'b0;
            peer_o_valid <= 1'b0;
            peer_o_position <= 8'h00;
            peer_o_value <= 8'h00;
            peer_o_root <= 1'b1;
            peer_cache <= 8'h00;
            peer_scan_position <= 8'h01;
            for (state_index = 0; state_index < COEFFS;
                 state_index = state_index + 1)
                terms[state_index] <= 8'h00;
        end else if (request_grant[0]) begin
            // Q: open the checking window and report the zero field element.
            window <= 1'b1;
            o_valid <= 1'b1;
            o_position <= 8'h00;
            o_value <= i_coeffs[0 +: 8];
            o_root <= (i_coeffs[0 +: 8] == 8'h00);
            scan_position <= 8'h01;
            eval_cache <= load_sum;
            for (state_index = 0; state_index < COEFFS;
                 state_index = state_index + 1)
                terms[state_index] <= i_coeffs[8*state_index +: 8];
        end else if (request_grant[1]) begin
            peer_o_valid <= 1'b1;
            peer_o_position <= 8'h00;
            peer_o_value <= peer_i_coeffs[0 +: 8];
            peer_o_root <= (peer_i_coeffs[0 +: 8] == 8'h00);
            peer_scan_position <= 8'h01;
            peer_cache <= peer_load_sum;
            for (state_index = 0; state_index < COEFFS;
                 state_index = state_index + 1)
                terms[state_index] <= peer_i_coeffs[8*state_index +: 8];
        end else if (peer_o_valid && peer_o_ready) begin
            if (peer_o_position == 8'hff) begin
                peer_o_valid <= 1'b0;
            end else begin
                peer_o_position <= peer_scan_position;
                peer_scan_position <= peer_scan_position + 8'h01;
                peer_o_root <= (peer_cache == 8'h00);
                peer_o_value <= term_sum;
                peer_cache <= next_sum;
                for (state_index = 0; state_index < COEFFS;
                     state_index = state_index + 1)
                    terms[state_index] <= next_terms[state_index];
            end
        end else if (!peer_o_valid && o_valid && o_ready) begin
            if (o_position == 8'hff) begin
                // Close only after the final result is accepted.
                o_valid <= 1'b0;
                window <= 1'b0;
            end else begin
                // Positions 1..255 enumerate alpha^0 through alpha^254.
                o_position <= scan_position;
                scan_position <= scan_position + 8'h01;
                // Cached reduction drives root detection; the payload also
                // captures an independent reduction of the coefficient lanes.
                o_root <= (eval_cache == 8'h00);
                o_value <= term_sum;
                eval_cache <= next_sum;
                for (state_index = 0; state_index < COEFFS;
                     state_index = state_index + 1)
                    terms[state_index] <= next_terms[state_index];
            end
        end
    end

    assert property (!window || (o_root == (o_value == 8'h00)));
    always @(*) begin
        assert (!peer_o_valid || (peer_o_root == (peer_o_value == 8'h00)));
    end
endmodule

module sdram_rr_request_dispatch #(
    parameter integer BANKS = 4,
    parameter integer DATA_W = 64,
    parameter integer COUNTER_W = 64
) (
    input  wire                  i_clk,
    input  wire                  i_req_valid,
    output wire                  o_req_ready,
    input  wire [DATA_W-1:0]     i_req_data,
   input  wire                  i_peer_valid,
   output wire                  o_peer_ready,
   input  wire [DATA_W-1:0]     i_peer_data,
   output wire                  o_bank_peer,
    output wire [BANKS-1:0]      o_bank_valid,
    input  wire [BANKS-1:0]      i_bank_ready,
    output wire [DATA_W-1:0]     o_bank_data
);
    localparam [COUNTER_W-1:0] COUNT_ZERO = {COUNTER_W{1'b0}};
    localparam [COUNTER_W-1:0] COUNT_ONE = {{(COUNTER_W-1){1'b0}}, 1'b1};
    localparam [COUNTER_W-1:0] BANK_COUNT = BANKS;
    localparam [COUNTER_W-1:0] LAST_BANK = BANK_COUNT - COUNT_ONE;
    localparam [BANKS-1:0] MASK_ZERO = {BANKS{1'b0}};
    localparam [BANKS-1:0] MASK_ONE = {{(BANKS-1){1'b0}}, 1'b1};
   localparam integer CHANNELS = 2;

    // Binary next-bank pointer and its cached one-hot routing mask.
    reg [COUNTER_W-1:0] next_bank;
   wire [BANKS-1:0] next_mask;
   reg [BANKS-1:0] route_mask [0:CHANNELS-1];
   reg prefer_peer, pending_peer;
   integer lane;

    // One shared command slot: only its selected bank sees valid.
    reg pending_valid;
    reg [BANKS-1:0] pending_mask;
    reg [DATA_W-1:0] pending_data;
    reg armed;

    initial begin
        next_bank = COUNT_ZERO;
       for (lane = 0; lane < CHANNELS; lane = lane + 1) route_mask[lane] = MASK_ONE;
       prefer_peer = 1'b0;
       pending_peer = 1'b0;
        pending_valid = 1'b0;
        pending_mask = MASK_ZERO;
        pending_data = {DATA_W{1'b0}};
        armed = 1'b0;
    end

    wire [COUNTER_W-1:0] following_bank;
    wire retire;
    wire accept;
   wire [CHANNELS-1:0] lane_take;
   wire choose_peer;

    assign following_bank = (next_bank == LAST_BANK)
                          ? COUNT_ZERO : next_bank + COUNT_ONE;
    assign o_bank_valid = pending_valid ? pending_mask : MASK_ZERO;
    assign o_bank_data = pending_data;
    assign retire = |(o_bank_valid & i_bank_ready);
   assign next_mask = route_mask[0];
   assign choose_peer = i_peer_valid && (!i_req_valid || prefer_peer);
   assign lane_take = {i_peer_valid && o_peer_ready, accept};
   assign o_bank_peer = pending_peer;
   assign o_req_ready = (!pending_valid || retire) && !choose_peer;
   assign o_peer_ready = (!pending_valid || retire) && (!i_req_valid || prefer_peer);
    assign accept = i_req_valid && o_req_ready;

    always @(posedge i_clk) begin
       if (accept) next_bank <= following_bank;
       for (lane = 0; lane < CHANNELS; lane = lane + 1)
           if (lane_take[lane])
               route_mask[lane] <= (lane == 0)
                   ? (next_mask & ~(MASK_ONE << next_bank)) | (MASK_ONE << following_bank)
                   : (route_mask[lane] << 1) | (route_mask[lane] >> (BANKS-1));
       if (|lane_take) begin
            pending_valid <= 1'b1;
           pending_mask <= route_mask[choose_peer];
           pending_data <= choose_peer ? i_peer_data : i_req_data;
           pending_peer <= choose_peer;
           prefer_peer <= !choose_peer;
            armed <= 1'b1;

        end else if (retire) begin
            pending_valid <= 1'b0;
        end
    end

    // After the first accepted command, banks zero and one must never
    // simultaneously own the shared command slot.
    always @(posedge i_clk)
        if (armed) assert (!(o_bank_valid[0] && o_bank_valid[1]));
   always @(posedge i_clk)
       if (armed && retire)
           assert (((pending_mask << 1) | (pending_mask >> (BANKS-1))) ==
                   (pending_peer ? route_mask[1] : next_mask));
endmodule

module boot_residue_adder #(
    parameter integer DATA_W = 32,
parameter [DATA_W-1:0] INITIAL_MODULUS = 32'd17,
parameter integer CFG_DEPTH = 4
) (
    input  wire                  clk,
    input  wire                  cfg_valid,
    output wire                  cfg_ready,
    input  wire [DATA_W-1:0]     cfg_modulus,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [DATA_W-1:0]     in_a,
    input  wire [DATA_W-1:0]     in_b,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [DATA_W-1:0]     result,
output reg                   out_error,
output reg  [DATA_W-1:0]     operand_limit,
output wire [$clog2(CFG_DEPTH):0] cfg_pending,
output wire                  cfg_commit
);
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};

    reg [DATA_W-1:0] active_modulus;
    // The buffered transaction retains its own reduction argument.
    reg [DATA_W-1:0] modulus;
    reg [DATA_W-1:0] sum_word;
    reg sum_carry;
    reg past_valid;
localparam integer CFG_ADDR_W = $clog2(CFG_DEPTH);
reg [DATA_W-1:0] cfg_moduli [0:CFG_DEPTH-1];
reg [CFG_ADDR_W:0] cfg_wr;
reg [CFG_ADDR_W:0] cfg_rd;
reg [DATA_W-1:0] cfg_stage_modulus;
reg [DATA_W-1:0] cfg_stage_limit;
reg cfg_stage_valid;
integer cfg_slot;

// CFG_DEPTH is a power of two; the extra pointer bit tracks wrapping.
wire cfg_empty = (cfg_wr == cfg_rd);
wire cfg_full = (cfg_wr ==
    {~cfg_rd[CFG_ADDR_W], cfg_rd[CFG_ADDR_W-1:0]});
wire [CFG_ADDR_W:0] cfg_used = cfg_wr - cfg_rd;
wire cfg_apply = cfg_stage_valid && (!out_valid || out_ready);
wire cfg_pop = !cfg_empty && (!cfg_stage_valid || cfg_apply);

// Predecode queued settings, then commit at an output boundary.
// A simultaneous operand transfer still uses the previous setting.
assign cfg_ready = !cfg_full || cfg_pop;
assign cfg_pending = cfg_used + cfg_stage_valid;
assign cfg_commit = cfg_apply;

    // An empty buffer accepts data without waiting for output ready.
    // A consumed output can be replaced on the same edge.
    assign in_ready = !out_valid || out_ready;

    wire cfg_fire = cfg_valid && cfg_ready;
    wire in_fire = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;
wire cfg_direct = cfg_fire && cfg_empty
                && (!cfg_stage_valid || cfg_apply);
wire [DATA_W-1:0] normalized_cfg_modulus =
    (cfg_modulus == ZERO) ? ONE : cfg_modulus;
wire [DATA_W-1:0] cfg_decode_modulus = cfg_pop
    ? cfg_moduli[cfg_rd[CFG_ADDR_W-1:0]] : normalized_cfg_modulus;

    // The arithmetic interface accepts canonical residues. Noncanonical
    // operands are consumed and reported as an error transaction with a
    // zero result, rather than permanently deasserting input ready.
wire operand_error = (in_a > operand_limit)
                   || (in_b > operand_limit);
    wire [DATA_W:0] input_sum = operand_error
        ? {(DATA_W+1){1'b0}}
        : ({1'b0, in_a} + {1'b0, in_b});
    wire [DATA_W:0] extended_active_modulus = {1'b0, active_modulus};
    wire [DATA_W:0] reduced_sum =
        (input_sum >= extended_active_modulus)
        ? input_sum - extended_active_modulus : input_sum;

    initial begin
operand_limit = ((INITIAL_MODULUS == ZERO) ? ONE : INITIAL_MODULUS) - ONE;
cfg_wr = {(CFG_ADDR_W+1){1'b0}};
cfg_rd = {(CFG_ADDR_W+1){1'b0}};
cfg_stage_modulus = ONE;
cfg_stage_limit = ZERO;
cfg_stage_valid = 1'b0;
for (cfg_slot = 0; cfg_slot < CFG_DEPTH; cfg_slot = cfg_slot + 1)
    cfg_moduli[cfg_slot] = ONE;
        active_modulus = (INITIAL_MODULUS == ZERO) ? ONE : INITIAL_MODULUS;
        modulus = (INITIAL_MODULUS == ZERO) ? ONE : INITIAL_MODULUS;
        sum_word = ZERO;
        sum_carry = 1'b0;
        result = ZERO;
        out_valid = 1'b0;
        out_error = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
if (cfg_fire && !cfg_direct) begin
    cfg_moduli[cfg_wr[CFG_ADDR_W-1:0]] <= normalized_cfg_modulus;
    cfg_wr <= cfg_wr + 1'b1;
end
if (cfg_pop)
    cfg_rd <= cfg_rd + 1'b1;
if (cfg_pop || cfg_direct) begin
    cfg_stage_modulus <= cfg_decode_modulus;
    cfg_stage_limit <= cfg_decode_modulus - ONE;
    cfg_stage_valid <= 1'b1;
end else if (cfg_apply)
    cfg_stage_valid <= 1'b0;
if (cfg_apply) begin
    active_modulus <= cfg_stage_modulus;
    operand_limit <= cfg_stage_limit;
end

        if (out_fire)
            out_valid <= 1'b0;

        if (in_fire) begin
            modulus <= active_modulus;
            sum_word <= input_sum[DATA_W-1:0];
            sum_carry <= input_sum[DATA_W];
            result <= reduced_sum[DATA_W-1:0];
            out_error <= operand_error;
            out_valid <= 1'b1;
        end

// Internal configuration transfers also establish clock history.
if (cfg_fire || cfg_pop || cfg_apply || in_fire || out_fire)
            past_valid <= 1'b1;
    end

always @(posedge clk)
    if (in_fire && !operand_error)
        assert (!reduced_sum[DATA_W]
            && (reduced_sum[DATA_W-1:0] <= operand_limit));

    // Equal stored reduction arguments must have equal stored results.
    always @(posedge clk)
        if (past_valid && $stable({modulus, sum_carry, sum_word}))
            assert ($stable(result));
endmodule

module gesture_alignment_engine #(
    parameter integer WORD_W = 128,
    parameter integer EXP_W = 15,
    parameter integer STEPS = 4,
    parameter integer SHIFT_W = $clog2(WORD_W + 1),
    parameter integer PHASE_W = $clog2(STEPS + 1)
) (
    input wire clk,
    input wire launch,
    input wire take,
    input wire downstream_ready,
    input wire [WORD_W-1:0] operand,
    input wire [EXP_W-1:0] span,
    output wire ready,
    output wire done,
    output reg active,
    output reg [WORD_W-1:0] value,
    output reg guard_bit,
    output reg sticky_bit,
    output reg [SHIFT_W-1:0] remaining,
    output reg [PHASE_W-1:0] phase
);
    localparam integer CHUNK = (WORD_W + STEPS - 1) / STEPS;
    reg [SHIFT_W-1:0] amount;
    assign done = active && (phase == STEPS);
    assign ready = !active || (done && downstream_ready);
    always @(*) begin
        if (remaining > CHUNK)
            amount = CHUNK;
        else
            amount = remaining;
    end
    initial begin
        active = 1'b0;
        value = {WORD_W{1'b0}};
        guard_bit = 1'b0;
        sticky_bit = 1'b0;
        remaining = {SHIFT_W{1'b0}};
        phase = STEPS;
    end
    always @(posedge clk) begin
        if (launch) begin
            active <= 1'b1;
            phase <= {PHASE_W{1'b0}};
            guard_bit <= 1'b0;
            sticky_bit <= 1'b0;
            if (span > WORD_W) begin
                value <= {WORD_W{1'b0}};
                remaining <= {SHIFT_W{1'b0}};
                sticky_bit <= (operand != {WORD_W{1'b0}});
            end else begin
                value <= operand;
                remaining <= span;
            end
        end else if (active) begin
            if (phase < STEPS) begin
                phase <= phase + 1'b1;
                remaining <= remaining - amount;
                value <= value >> amount;
                if (amount != 0) begin
                    guard_bit <= (value >> (amount - 1'b1)) & 1'b1;
                    sticky_bit <= sticky_bit || guard_bit ||
                        ((value << (WORD_W - (amount - 1'b1))) != {WORD_W{1'b0}});
                end
            end else if (take) begin
                active <= 1'b0;
            end
        end
    end
endmodule

module gesture_operand_sort #(
    parameter integer WORD_W = 128,
    parameter integer EXP_W = 15
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_a_sig,
    input  wire [WORD_W-1:0]     in_b_sig,
    input  wire [EXP_W-1:0]      in_a_exp,
    input  wire [EXP_W-1:0]      in_b_exp,
    input  wire                  in_last,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [WORD_W-1:0]     large_sig,
    output reg  [WORD_W-1:0]     small_sig,
    output reg  [EXP_W-1:0]      large_exp,
    output reg  [EXP_W-1:0]      small_exp,
    output reg  [EXP_W-1:0]      exponent_gap,
    output reg                   swap_flag,
    output reg                   out_last,
    output reg  [EXP_W-1:0]      retired_span,
    output reg  [39:0]          debug_status,
    output wire [WORD_W-1:0]    aligned_small,
    output wire                 alignment_guard,
    output wire                 alignment_sticky,
    output wire                 alignment_busy
);
    localparam integer ALIGN_STEPS = 4;
    localparam integer ALIGN_SHIFT_W = $clog2(WORD_W + 1);
    localparam integer ALIGN_PHASE_W = $clog2(ALIGN_STEPS + 1);
    wire align_active, align_done;
    wire [ALIGN_SHIFT_W-1:0] align_remaining;
    wire [ALIGN_PHASE_W-1:0] align_phase;
    reg before_frame_end;
    reg pv;
    reg [7:0] diag_accepted;
    reg [7:0] diag_retired;
    reg [7:0] diag_frames;
    reg [7:0] diag_stall_cycles;
    reg [3:0] diag_stall_run;
    reg [3:0] diag_peak_stall;

    wire swap_inputs = (in_a_exp < in_b_exp) ||
                       ((in_a_exp == in_b_exp) &&
                        (in_a_sig < in_b_sig));
    wire in_fire = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;
    gesture_alignment_engine #(
        .WORD_W(WORD_W), .EXP_W(EXP_W), .STEPS(ALIGN_STEPS)
    ) aligner (
        .clk(clk), .launch(in_fire), .take(out_fire),
        .downstream_ready(out_ready),
        .operand(swap_inputs ? in_a_sig : in_b_sig),
        .span(swap_inputs ? (in_b_exp - in_a_exp) : (in_a_exp - in_b_exp)),
        .ready(in_ready), .done(align_done), .active(align_active),
        .value(aligned_small), .guard_bit(alignment_guard),
        .sticky_bit(alignment_sticky),
        .remaining(align_remaining), .phase(align_phase)
    );
    assign alignment_busy = align_active && !align_done;
    always @(*) begin
        out_valid = align_done;
    end

    initial begin
        large_sig = {WORD_W{1'b0}};
        small_sig = {WORD_W{1'b0}};
        large_exp = {EXP_W{1'b0}};
        small_exp = {EXP_W{1'b0}};
        exponent_gap = {EXP_W{1'b0}};
        swap_flag = 1'b0;
        out_last = 1'b0;
        retired_span = {EXP_W{1'b0}};
        before_frame_end = 1'b1;
        pv = 1'b0;
    end
    initial begin
        diag_accepted = 8'd0;
        diag_retired = 8'd0;
        diag_frames = 8'd0;
        diag_stall_cycles = 8'd0;
        diag_stall_run = 4'd0;
        diag_peak_stall = 4'd0;
        debug_status = 40'd0;
    end
    always @(posedge clk) begin
        if (in_fire)
            diag_accepted <= diag_accepted + 8'd1;
        if (out_fire)
            diag_retired <= diag_retired + 8'd1;
        if (out_fire && out_last)
            diag_frames <= diag_frames + 8'd1;
        if (out_valid && !out_ready) begin
            if (diag_stall_cycles != 8'hff)
                diag_stall_cycles <= diag_stall_cycles + 8'd1;
            if (diag_stall_run != 4'hf)
                diag_stall_run <= diag_stall_run + 4'd1;
            if ((diag_stall_run != 4'hf) &&
                ((diag_stall_run + 4'd1) > diag_peak_stall))
                diag_peak_stall <= diag_stall_run + 4'd1;
        end else begin
            diag_stall_run <= 4'd0;
        end
        debug_status <= {diag_accepted, diag_retired, diag_frames,
                         diag_stall_cycles, diag_peak_stall, diag_stall_run};
    end

    always @(posedge clk) begin
        if (in_fire || out_fire)
            pv <= 1'b1;

        if (in_fire) begin
            swap_flag <= swap_inputs;
            out_last <= in_last;
            if (swap_inputs) begin
                large_sig <= in_b_sig;
                small_sig <= in_a_sig;
                large_exp <= in_b_exp;
                small_exp <= in_a_exp;
                exponent_gap <= in_b_exp - in_a_exp;
            end else begin
                large_sig <= in_a_sig;
                small_sig <= in_b_sig;
                large_exp <= in_a_exp;
                small_exp <= in_b_exp;
                exponent_gap <= in_a_exp - in_b_exp;
            end
        end

        // Alignment-span telemetry for the operand pair just consumed.
        if (out_fire)
            retired_span <= large_exp - small_exp;

        // Permanently close the checking scope at the first frame end.
        if (out_fire && out_last)
            before_frame_end <= 1'b0;
    end

    always @(posedge clk) begin
        if (pv && before_frame_end && $past(out_fire))
            assert (retired_span == $past(exponent_gap));
    end
    always @(posedge clk) begin
        if (out_fire && (large_exp == small_exp))
            assert (aligned_small <= large_sig);
    end
endmodule

module usb_report_mailbox #(
    parameter integer DEPTH = 32'd256,
    parameter integer DATA_WIDTH = 32'd32,
    parameter integer ADDR_WIDTH = 32'd32
) (
    input  wire                  wr_clk,
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [DATA_WIDTH-1:0] in_data,
    input  wire                  release_read,
    input  wire                  session_end,
    output reg                   read_valid,
output reg  [DATA_WIDTH-1:0] read_data,
output wire                  audit_valid,
output wire [DATA_WIDTH-1:0] audit_data,
output wire [ADDR_WIDTH-1:0] audit_addr
);
    localparam [ADDR_WIDTH-1:0] LAST_ADDR = DEPTH - 32'd1;
    localparam [ADDR_WIDTH-1:0] ADDR_ONE =
        {{(ADDR_WIDTH-32'd1){1'b0}}, 1'b1};
    localparam integer JOURNAL_DEPTH = 32'd4;
    localparam integer JOURNAL_AW = $clog2(JOURNAL_DEPTH);
    localparam [JOURNAL_AW:0] JOURNAL_ONE =
        {{JOURNAL_AW{1'b0}}, 1'b1};

    // Single-write-port, synchronous-read-port RAM in separate domains.
    reg [DATA_WIDTH-1:0] ram [0:DEPTH-1];
    reg [ADDR_WIDTH-1:0] next_wr_addr;
    reg [ADDR_WIDTH-1:0] wr_addr;
    reg [ADDR_WIDTH-1:0] rd_addr;

    // The mailbox permits one outstanding report. The writer keeps its
    // accepted payload and address unchanged until the reader releases it.
    reg [DATA_WIDTH-1:0] accepted_payload;
    reg request;
    reg acknowledge;
    reg before_session_end;
    reg pv;
    // Retain session records independently of the live mailbox output.
    // Their backing words stay pinned until the audit consumer takes them.
    reg [DATA_WIDTH-1:0] journal [0:JOURNAL_DEPTH-1];
    reg [ADDR_WIDTH-1:0] journal_tag [0:JOURNAL_DEPTH-1];
    reg [JOURNAL_AW:0] journal_wr;
    reg [JOURNAL_AW:0] journal_rd;
    wire [JOURNAL_AW-1:0] journal_head = journal_rd[JOURNAL_AW-1:0];
    wire [JOURNAL_AW-1:0] journal_tail = journal_wr[JOURNAL_AW-1:0];
    wire journal_empty = (journal_wr == journal_rd);
    wire journal_full =
        (journal_wr == {~journal_rd[JOURNAL_AW], journal_head});
    wire [JOURNAL_AW:0] journal_used = journal_wr - journal_rd;
    wire journal_push = in_valid && in_ready;
    wire journal_pop = i_ce && session_end && audit_valid;
    reg [JOURNAL_DEPTH-1:0] journal_live;
    reg journal_conflict;
    integer journal_index;
    integer init_index;

    initial begin
        next_wr_addr = {ADDR_WIDTH{1'b0}};
        wr_addr = {ADDR_WIDTH{1'b0}};
        rd_addr = {ADDR_WIDTH{1'b0}};
        accepted_payload = {DATA_WIDTH{1'b0}};
        request = 1'b0;
        acknowledge = 1'b0;
        read_valid = 1'b0;
        read_data = {DATA_WIDTH{1'b0}};
        before_session_end = 1'b1;
        pv = 1'b0;
        journal_wr = {(JOURNAL_AW+32'd1){1'b0}};
        journal_rd = {(JOURNAL_AW+32'd1){1'b0}};
        for (init_index = 32'd0; init_index < JOURNAL_DEPTH;
             init_index = init_index + 32'd1) begin
            journal[init_index] = {DATA_WIDTH{1'b0}};
            journal_tag[init_index] = {ADDR_WIDTH{1'b0}};
        end
        for (init_index = 32'd0; init_index < DEPTH;
             init_index = init_index + 32'd1)
            ram[init_index] = {DATA_WIDTH{1'b0}};
    end
    // session_end authorizes audit transfers; it does not discard records.
    assign audit_valid = !journal_empty;
    assign audit_data = journal[journal_head];
    assign audit_addr = journal_tag[journal_head];
    always @(*) begin
        journal_conflict = 1'b0;
        for (journal_index = 32'd0; journal_index < JOURNAL_DEPTH;
             journal_index = journal_index + 32'd1) begin
            if (journal_wr[JOURNAL_AW] == journal_rd[JOURNAL_AW])
                journal_live[journal_index] =
                    (journal_index >= journal_head) &&
                    (journal_index < journal_tail);
            else
                journal_live[journal_index] =
                    (journal_index >= journal_head) ||
                    (journal_index < journal_tail);
            if (journal_live[journal_index] &&
                (journal_tag[journal_index] == next_wr_addr))
                journal_conflict = 1'b1;
        end
    end

    // Back-pressure prevents another input handshake while a report is pending.
    assign in_ready = i_ce && (request == acknowledge) &&
                      !journal_full && !journal_conflict;

    always @(posedge wr_clk) begin
        if (journal_push) begin
            journal[journal_tail] <= in_data;
            journal_tag[journal_tail] <= next_wr_addr;
            journal_wr <= journal_wr + JOURNAL_ONE;
            ram[next_wr_addr] <= in_data;
            wr_addr <= next_wr_addr;
            accepted_payload <= in_data;
            request <= !request;
            if (next_wr_addr == LAST_ADDR)
                next_wr_addr <= {ADDR_WIDTH{1'b0}};
            else
                next_wr_addr <= next_wr_addr + ADDR_ONE;
        end
    end
    always @(posedge clk) begin
        if (journal_pop)
            journal_rd <= journal_rd + JOURNAL_ONE;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (session_end)
                before_session_end <= 1'b0;

            if (!read_valid && (request != acknowledge)) begin
                rd_addr <= wr_addr;
                read_data <= ram[wr_addr];
                read_valid <= 1'b1;
            end else if (read_valid && release_read) begin
                read_valid <= 1'b0;
                acknowledge <= request;
            end
        end
    end

    // Before session termination, an observed report must match the payload
    // recorded by an earlier input handshake, sampled on the previous cycle.
    always @(posedge clk) begin
        if (pv && before_session_end && read_valid)
            assert (read_data == $past(accepted_payload));
    end
    // Validate each exported record against its still-pinned backing word.
    always @(posedge clk) begin
        if (pv && journal_pop)
            assert (audit_data == ram[audit_addr]);
    end
endmodule

module inference_zq_scheduler #(
    parameter integer DEPTH = 32'd2,
    parameter [63:0] ZQ_INTERVAL = 64'd4,
    parameter [63:0] ZQ_BLOCK = 64'd4
) (
    input wire clk,
    input wire i_ce,
    input wire inference_begin,
    input wire inference_end,
    output reg zq_short,
    output wire [63:0] zq_short_ticket,
    output wire inference_blocked,
    output wire schedule_stalled,
    output reg calibration_done,
    output reg [63:0] completed_ticket,
    output reg [127:0] scheduler_debug
);
    // DEPTH is at least two; interval and blocking durations are positive.
    localparam [63:0] DEPTH64 = DEPTH;

    reg [63:0] interval_counter;
    reg [63:0] blocking_timer;
    reg calibration_in_progress;

    // Periodic requests wait in a bounded FIFO until calibration can start.
    reg [63:0] pending_ticket [32'd0:DEPTH-32'd1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] pending_count;
    reg [63:0] accepted_serial;

    // These shadows record earlier ZQ command issuance.
    reg [63:0] issued_serial;
    reg issue_seen;
    reg [63:0] active_ticket;
    reg scope_window;

    reg [15:0] dbg_requests;
    reg [15:0] dbg_issues;
    reg [15:0] dbg_completions;
    reg [15:0] dbg_stalls;
    reg [15:0] dbg_busy_cycles;
    reg [15:0] dbg_stall_run;
    reg [15:0] dbg_stall_peak;
    reg [15:0] dbg_queue_peak;
    reg [15:0] dbg_windows;

    wire interval_due = interval_counter == ZQ_INTERVAL - 64'd1;
    wire enqueue_request = i_ce && interval_due && pending_count < DEPTH64;
    wire issue_command = i_ce && !calibration_in_progress &&
                         pending_count != 64'd0;

    assign inference_blocked = calibration_in_progress;
    assign zq_short_ticket = active_ticket;
    assign schedule_stalled = interval_due && pending_count == DEPTH64;

    // Per-entry ordering predicates. Occupancy comes from pointers/count,
    // not from summing entry-valid bits.
    wire [63:0] slot_distance [32'd0:DEPTH-32'd1];
    wire [DEPTH-32'd1:32'd0] slot_occupied;
    wire [DEPTH-32'd1:32'd0] entry_consistent;
    genvar g;
    generate
        for (g = 32'd0; g < DEPTH; g = g + 32'd1) begin : slots
            localparam [63:0] SLOT = g;
            assign slot_distance[g] = (SLOT >= rd_ptr) ?
                SLOT - rd_ptr : DEPTH64 - rd_ptr + SLOT;
            assign slot_occupied[g] = slot_distance[g] < pending_count;
            assign entry_consistent[g] = !slot_occupied[g] ||
                pending_ticket[g] == issued_serial + slot_distance[g] + 64'd1;
        end
    endgenerate

    integer k;
    initial begin
        interval_counter = 64'd0;
        blocking_timer = 64'd0;
        calibration_in_progress = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        pending_count = 64'd0;
        accepted_serial = 64'd0;
        issued_serial = 64'd0;
        issue_seen = 1'b0;
        active_ticket = 64'd0;
        scope_window = 1'b0;
        zq_short = 1'b0;
        calibration_done = 1'b0;
        completed_ticket = 64'd0;
        for (k = 32'd0; k < DEPTH; k = k + 32'd1)
            pending_ticket[k] = 64'd0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Q opens a persistent observation window; R closes it.
            if (inference_end)
                scope_window <= 1'b0;
            else if (inference_begin)
                scope_window <= 1'b1;

            zq_short <= 1'b0;
            calibration_done <= 1'b0;

            // A full FIFO makes the periodic source wait at its deadline.
            if (enqueue_request) begin
                interval_counter <= 64'd0;
                accepted_serial <= accepted_serial + 64'd1;
                pending_ticket[wr_ptr] <= accepted_serial + 64'd1;
                if (wr_ptr == DEPTH64 - 64'd1)
                    wr_ptr <= 64'd0;
                else
                    wr_ptr <= wr_ptr + 64'd1;
            end else if (!interval_due) begin
                interval_counter <= interval_counter + 64'd1;
            end

            // Only the oldest pending request can enter service, and no
            // request enters service until the previous blocking period ends.
            if (issue_command) begin
                active_ticket <= pending_ticket[rd_ptr];
                issued_serial <= issued_serial + 64'd1;
                issue_seen <= 1'b1;
                zq_short <= 1'b1;
                calibration_in_progress <= 1'b1;
                blocking_timer <= ZQ_BLOCK;
                if (rd_ptr == DEPTH64 - 64'd1)
                    rd_ptr <= 64'd0;
                else
                    rd_ptr <= rd_ptr + 64'd1;
            end else if (calibration_in_progress) begin
                if (blocking_timer == 64'd1) begin
                    blocking_timer <= 64'd0;
                    calibration_in_progress <= 1'b0;
                    calibration_done <= 1'b1;
                    completed_ticket <= active_ticket;
                end else begin
                    blocking_timer <= blocking_timer - 64'd1;
                end
            end

            case ({enqueue_request, issue_command})
                2'b10: pending_count <= pending_count + 64'd1;
                2'b01: pending_count <= pending_count - 64'd1;
                default: pending_count <= pending_count;
            endcase
        end
    end

    initial begin
        dbg_requests = 16'd0;
        dbg_issues = 16'd0;
        dbg_completions = 16'd0;
        dbg_stalls = 16'd0;
        dbg_busy_cycles = 16'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_peak = 16'd0;
        dbg_queue_peak = 16'd0;
        dbg_windows = 16'd0;
        scheduler_debug = 128'd0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (enqueue_request && dbg_requests != 16'hffff)
                dbg_requests <= dbg_requests + 16'd1;
            if (issue_command && dbg_issues != 16'hffff)
                dbg_issues <= dbg_issues + 16'd1;
            if (calibration_in_progress && blocking_timer == 64'd1 &&
                dbg_completions != 16'hffff)
                dbg_completions <= dbg_completions + 16'd1;

            if (schedule_stalled) begin
                if (dbg_stalls != 16'hffff)
                    dbg_stalls <= dbg_stalls + 16'd1;
                if (dbg_stall_run != 16'hffff)
                    dbg_stall_run <= dbg_stall_run + 16'd1;
                if (dbg_stall_run >= dbg_stall_peak &&
                    dbg_stall_run != 16'hffff)
                    dbg_stall_peak <= dbg_stall_run + 16'd1;
            end else begin
                dbg_stall_run <= 16'd0;
            end

            if (calibration_in_progress &&
                dbg_busy_cycles != 16'hffff)
                dbg_busy_cycles <= dbg_busy_cycles + 16'd1;
            if (pending_count > 64'd65535)
                dbg_queue_peak <= 16'hffff;
            else if (pending_count > {48'd0, dbg_queue_peak})
                dbg_queue_peak <= pending_count[15:0];
            if (inference_begin && !inference_end && !scope_window &&
                dbg_windows != 16'hffff)
                dbg_windows <= dbg_windows + 16'd1;

            scheduler_debug <= {dbg_requests, dbg_issues,
                                dbg_completions, dbg_stalls,
                                dbg_busy_cycles, dbg_stall_peak,
                                dbg_queue_peak, dbg_windows};
        end
    end

    // Completion must be preceded by a command, with the recorded ticket.
    always @(posedge clk) begin
        if (scope_window && calibration_done)
            assert (issue_seen);
        if (scope_window && calibration_done)
            assert (completed_ticket == issued_serial);
    end
endmodule

module reconfigurable_sample_queue #(parameter integer WORD_W = 64, DEPTH = 4) (
    input wire clk, ce, program_config, drain,
    input wire [WORD_W-1:0] sample_in, mask, reference,
    output wire ready,
    output reg [$clog2(DEPTH+1)-1:0] count,
    output wire [WORD_W-1:0] sample_out, difference_out,
    output wire [DEPTH*WORD_W-1:0] samples, differences
);
    reg [WORD_W-1:0] data [0:DEPTH-1], delta [0:DEPTH-1];
    reg [$clog2(DEPTH)-1:0] rd, wr;
    integer i;
    wire push = ce && ready, pop = ce && drain && (count != 0);
    assign ready = count < DEPTH;
    assign sample_out = data[rd], difference_out = delta[rd];
    genvar g;
    generate for (g = 0; g < DEPTH; g = g + 1) begin: bank_view
        assign samples[g*WORD_W +: WORD_W] = data[g];
        assign differences[g*WORD_W +: WORD_W] = delta[g];
    end endgenerate
    initial begin
        rd = 0; wr = 0; count = 0;
        for (i = 0; i < DEPTH; i = i + 1) begin data[i] = {WORD_W{1'b0}}; delta[i] = {WORD_W{1'b0}}; end
    end
    always @(posedge clk) if (ce) begin
        if (push) begin data[wr] <= sample_in; wr <= (wr == DEPTH-1) ? 0 : wr + 1'b1; end
        if (pop) rd <= (rd == DEPTH-1) ? 0 : rd + 1'b1;
        for (i = 0; i < DEPTH; i = i + 1) begin
            if (push && wr == i) delta[i] <= ((sample_in ^ reference) & mask);
            else if (program_config) delta[i] <= ((data[i] ^ reference) & mask);
        end
        case ({push, pop})
            2'b10: count <= count + 1'b1;
            2'b01: count <= count - 1'b1;
        endcase
    end
endmodule
module scoped_masked_comparator #(
    parameter integer WORD_W = 64, QUEUE_DEPTH = 4
) (
    input wire clk,
    input wire ce,
    input wire program_config,
    input wire open_window,
    input wire close_window,
    input wire [WORD_W-1:0] sample_in,
    input wire [WORD_W-1:0] mask_in,
    input wire [WORD_W-1:0] reference_in,
    output reg match,
    output wire sample_ready,
    output wire [$clog2(QUEUE_DEPTH+1)-1:0] queued_samples
);
    reg [WORD_W-1:0] mask_reg;
    reg [WORD_W-1:0] reference_reg;
    reg [WORD_W-1:0] sample_reg;
    reg window_open;
    reg past_valid;

    wire [WORD_W-1:0] selected_mask =
        program_config ? mask_in : mask_reg;
    wire [WORD_W-1:0] selected_reference =
        program_config ? reference_in : reference_reg;
    wire [WORD_W-1:0] queued_sample, queued_difference;
    wire [QUEUE_DEPTH*WORD_W-1:0] buffered_samples, buffered_differences;
    wire take_sample = ce && window_open && (queued_samples != 0);
    reconfigurable_sample_queue #(.WORD_W(WORD_W), .DEPTH(QUEUE_DEPTH)) pending (
        .clk(clk), .ce(ce), .program_config(program_config), .drain(window_open),
        .sample_in(sample_in), .mask(selected_mask), .reference(selected_reference),
        .ready(sample_ready), .count(queued_samples), .sample_out(queued_sample),
        .difference_out(queued_difference), .samples(buffered_samples), .differences(buffered_differences));

    initial begin
        mask_reg = {WORD_W{1'b1}};
        reference_reg = {WORD_W{1'b0}};
        sample_reg = {WORD_W{1'b0}};
        match = 1'b1;
        window_open = 1'b0;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            past_valid <= 1'b1;
            if (program_config) begin
                mask_reg <= mask_in;
                reference_reg <= reference_in;
            end
            if (take_sample)
                sample_reg <= queued_sample;
            if (take_sample || program_config)
                match <= program_config ?
                    (((((take_sample ? queued_sample : sample_reg) ^ selected_reference) & selected_mask)) == {WORD_W{1'b0}}) :
                    (queued_difference == {WORD_W{1'b0}});

            if (close_window)
                window_open <= 1'b0;
            else if (open_window)
                window_open <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (past_valid && window_open &&
            $stable({mask_reg, reference_reg, sample_reg}))
            assert ($stable(match));
    end
endmodule

module elevator_probe #(
    parameter integer FLOORS = 32'd32,
    parameter integer WORD_WIDTH = 32'd64
) (
    input  wire clk,
    input  wire i_ce,
    input  wire [FLOORS-1:0] call_mask,
    output reg  [WORD_WIDTH-1:0] current_floor,
    output reg  direction_up,
    output reg  door_open,
output reg  moving,
output wire dispatch_ready,
output reg  [WORD_WIDTH-1:0] next_stop,
output reg  [WORD_WIDTH-1:0] next_distance,
output reg  next_direction_up,
output reg  next_valid,
output reg  [WORD_WIDTH-1:0] planned_floor
);
    localparam [WORD_WIDTH-1:0] ZERO = {WORD_WIDTH{1'b0}};
    localparam [WORD_WIDTH-1:0] ONE = {{(WORD_WIDTH-1){1'b0}}, 1'b1};
    localparam [WORD_WIDTH-1:0] FLOOR_LIMIT = WORD_WIDTH'(FLOORS);
    localparam [FLOORS-1:0] FLOOR_ONE = {{(FLOORS-1){1'b0}}, 1'b1};
localparam integer ROUTE_DEPTH = 4;
localparam integer ROUTE_BITS = $clog2(ROUTE_DEPTH);

    reg [WORD_WIDTH-1:0] target_floor;
    reg [WORD_WIDTH-1:0] steps_left;
    reg [FLOORS-1:0] pending;
    reg armed;
reg [WORD_WIDTH-1:0] route_floor [0:ROUTE_DEPTH-1];
reg [WORD_WIDTH-1:0] route_steps [0:ROUTE_DEPTH-1];
reg route_up [0:ROUTE_DEPTH-1];
reg [ROUTE_BITS:0] route_read;
reg [ROUTE_BITS:0] route_write;
integer q;

    initial begin
        current_floor = ZERO;
        target_floor = ZERO;
        steps_left = ZERO;
        direction_up = 1'b1;
        pending = {FLOORS{1'b0}};
        door_open = 1'b0;
        moving = 1'b0;
        armed = 1'b0;
route_read = {(ROUTE_BITS+1){1'b0}};
route_write = {(ROUTE_BITS+1){1'b0}};
planned_floor = ZERO;
next_stop = ZERO;
next_distance = ZERO;
next_direction_up = 1'b1;
next_valid = 1'b0;
for (q = 0; q < ROUTE_DEPTH; q = q + 1) begin
    route_floor[q] = ZERO;
    route_steps[q] = ZERO;
    route_up[q] = 1'b1;
end
    end

// Retain call bits until the route planner schedules their visits.
    wire [FLOORS-1:0] arrivals = pending | call_mask;

    // Lowest-floor-first dispatch among pending calls.
    function automatic [WORD_WIDTH-1:0] select_floor;
        input [FLOORS-1:0] requests;
        integer f;
        begin
            select_floor = ZERO;
            for (f = FLOORS - 32'd1; f >= 32'sd0; f = f - 32'sd1)
                if (requests[f])
                    select_floor = WORD_WIDTH'(f);
        end
    endfunction

wire have_request = |pending;
wire [WORD_WIDTH-1:0] selected_floor = select_floor(pending);

wire [ROUTE_BITS-1:0] route_rindex = route_read[ROUTE_BITS-1:0];
wire [ROUTE_BITS-1:0] route_windex = route_write[ROUTE_BITS-1:0];
wire [ROUTE_BITS:0] route_used = route_write - route_read;
wire route_empty = (route_write == route_read);
wire route_full = (route_write ==
    {~route_read[ROUTE_BITS], route_rindex});
wire route_push = dispatch_ready && have_request;
wire route_pop = i_ce && !next_valid && !route_empty;
wire route_launch = i_ce && next_valid &&
    (steps_left == ZERO) && door_open;
wire [WORD_WIDTH-1:0] route_distance = (selected_floor > planned_floor)
    ? selected_floor - planned_floor
    : planned_floor - selected_floor;
assign dispatch_ready = i_ce && !route_full;

    always @(posedge clk) begin
        if (i_ce) begin
pending <= route_push
    ? (arrivals & ~(FLOOR_ONE << selected_floor)) : arrivals;

            // Q is the first enabled sampling of a nonempty call mask.
            armed <= armed || (|call_mask);

if (route_push) begin
    route_floor[route_windex] <= selected_floor;
    route_steps[route_windex] <= route_distance;
    route_up[route_windex] <= (selected_floor > planned_floor);
    planned_floor <= selected_floor;
    route_write <= route_write + 1'b1;
end
if (route_pop) begin
    next_stop <= route_floor[route_rindex];
    next_distance <= route_steps[route_rindex];
    next_direction_up <= route_up[route_rindex];
    next_valid <= 1'b1;
    route_read <= route_read + 1'b1;
end

            // Registered door and motion controls use two trip representations.
            door_open <= (current_floor == target_floor);
            moving <= (steps_left != ZERO);

            if (steps_left != ZERO) begin
                steps_left <= steps_left - ONE;
                if (direction_up)
                    current_floor <= current_floor + ONE;
                else
                    current_floor <= current_floor - ONE;
end else if (route_launch) begin
    target_floor <= next_stop;
    direction_up <= next_direction_up;
    steps_left <= next_distance;
    next_valid <= 1'b0;
    door_open <= (current_floor == next_stop);
    moving <= (next_distance != ZERO);
            end
        end
    end

    always @(*) begin
        if (armed)
            assert (!(door_open && moving));
    end
endmodule

module phased_case_emitter #(
    parameter integer DEPTH = 16,
    parameter integer TRACE_DEPTH = 4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        seed_valid,
    input  wire [63:0] seed_in,
    output wire        seed_ready,
    output reg  [63:0] issued_word,
    output reg  [63:0] issued_phase,
    output reg  [63:0] issued_mask,
    output reg  [63:0] trace_word,
    output reg  [63:0] trace_phase,
    output reg  [63:0] trace_mask,
    output reg         trace_valid,
    output wire [$clog2(TRACE_DEPTH):0] trace_pending
);
    // DEPTH is the number of timing phases and table entries; use 2 through 16.
    localparam [63:0] DEPTH64 = DEPTH;
    localparam [63:0] LAST_PHASE = DEPTH64 - 64'd1;
    localparam [DEPTH-1:0] PHASE_ONE = {{(DEPTH-1){1'b0}}, 1'b1};
    // The paced trace FIFO supports power-of-two depths of four or eight.
    localparam integer TRACE_ADDR_W = $clog2(TRACE_DEPTH);

    reg [63:0] phase;
    reg [DEPTH-1:0] phase_enable;
    reg [63:0] filled;
    reg [63:0] seed;
    reg draining;
    reg window;

    reg [63:0] words [0:DEPTH-1];
    reg [DEPTH-1:0] valid;

    // Dispatch records wait here independently of the paced trace receiver.
    reg [63:0] trace_words [0:TRACE_DEPTH-1];
    reg [63:0] trace_phases [0:TRACE_DEPTH-1];
    reg [63:0] trace_masks [0:TRACE_DEPTH-1];
    reg [TRACE_ADDR_W:0] trace_rptr;
    reg [TRACE_ADDR_W:0] trace_wptr;

    wire trace_empty = (trace_wptr == trace_rptr);
    wire trace_full =
        (trace_wptr == {~trace_rptr[TRACE_ADDR_W],
                        trace_rptr[TRACE_ADDR_W-1:0]});
    wire [TRACE_ADDR_W:0] trace_used = trace_wptr - trace_rptr;
    wire trace_idle = trace_empty && !trace_valid;
    wire trace_pop = i_ce && !trace_valid && !trace_empty;
    assign trace_pending = trace_used +
                           {{TRACE_ADDR_W{1'b0}}, trace_valid};

    // A seed is accepted only when the preceding batch has completely drained.
    assign seed_ready = i_ce && !draining && (phase == 64'd0) &&
                        trace_idle;
    wire advance = i_ce &&
                   (draining ? !trace_full :
                    ((phase != 64'd0) || (seed_valid && trace_idle)));
    wire [63:0] next_phase = (phase == LAST_PHASE)
                             ? 64'd0 : phase + 64'd1;
    wire [63:0] fill_seed = (phase == 64'd0) ? seed_in : seed;

    // Q opens the checking window; the final dispatch closes it.
    wire open_window = advance && draining && (phase == 64'd0);
    wire close_window = advance && draining && (phase == LAST_PHASE);
    wire trace_push = advance && draining;

    initial begin
        phase = 64'd0;
        phase_enable = PHASE_ONE;
        filled = 64'd0;
        seed = 64'd0;
        draining = 1'b0;
        window = 1'b0;
        issued_word = 64'd0;
        issued_phase = 64'd0;
        issued_mask = 64'd1;
        trace_word = 64'd0;
        trace_phase = 64'd0;
        trace_mask = 64'd1;
        trace_valid = 1'b0;
        trace_rptr = 0;
        trace_wptr = 0;
    end

    // The registered decoder supplies the per-entry timing strobes.
    genvar slot;
    generate
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin : entries
            initial begin
                words[slot] = 64'd0;
                valid[slot] = 1'b0;
            end
            always @(posedge clk) begin
                if (advance && phase_enable[slot]) begin
                    if (!draining) begin
                        words[slot] <= fill_seed ^ phase;
                        valid[slot] <= 1'b1;
                    end else begin
                        valid[slot] <= 1'b0;
                    end
                end
            end
        end
    endgenerate

    genvar trace_slot;
    generate
        for (trace_slot = 0; trace_slot < TRACE_DEPTH; trace_slot = trace_slot + 1) begin : trace_entries
            initial begin
                trace_words[trace_slot] = 64'd0;
                trace_phases[trace_slot] = 64'd0;
                trace_masks[trace_slot] = 64'd1;
            end
        end
    endgenerate

    reg [63:0] selected_word;
    integer mux_index;
    always @(*) begin
        selected_word = 64'd0;
        for (mux_index = 0; mux_index < DEPTH; mux_index = mux_index + 1)
            if (phase_enable[mux_index])
                selected_word = selected_word | words[mux_index];
    end

    always @(posedge clk) begin
        if (advance) begin
            phase <= next_phase;
            phase_enable <= PHASE_ONE << next_phase;

            if (!draining) begin
                if (phase == 64'd0)
                    seed <= seed_in;
                filled <= filled + 64'd1;
                if (phase == LAST_PHASE)
                    draining <= 1'b1;
            end else begin
                filled <= filled - 64'd1;
                issued_word <= selected_word;
                issued_phase <= phase;
                issued_mask <= phase_enable;
                if (phase == LAST_PHASE)
                    draining <= 1'b0;
            end

            if (close_window)
                window <= 1'b0;
            else if (open_window)
                window <= 1'b1;
        end
    end

    // The receiver samples valid beats on enabled clocks. Loading and
    // presenting a beat use separate cycles, limiting the trace link rate.
    always @(posedge clk) begin
        if (trace_push) begin
            trace_words[trace_wptr[TRACE_ADDR_W-1:0]] <=
                selected_word;
            trace_phases[trace_wptr[TRACE_ADDR_W-1:0]] <=
                phase;
            trace_masks[trace_wptr[TRACE_ADDR_W-1:0]] <=
                phase_enable;
            trace_wptr <= trace_wptr + 1'b1;
        end
        if (i_ce) begin
            trace_valid <= trace_pop;
            if (trace_pop) begin
                trace_word <=
                    trace_words[trace_rptr[TRACE_ADDR_W-1:0]];
                trace_phase <=
                    trace_phases[trace_rptr[TRACE_ADDR_W-1:0]];
                trace_mask <=
                    trace_masks[trace_rptr[TRACE_ADDR_W-1:0]];
                trace_rptr <= trace_rptr + 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (window) begin
            assert (issued_word == (seed ^ issued_phase));
            assert (issued_mask == (64'd1 << issued_phase));
        end
    end

    always @(posedge clk) begin
        if (trace_valid) begin
            assert ((trace_word == (seed ^ trace_phase)) &&
                    (trace_mask == (64'd1 << trace_phase)));
        end
    end
endmodule

module inference_zq_scheduler #(
    parameter integer DEPTH = 32'd2,
    parameter integer JOURNAL_DEPTH = 32'd4,
    parameter [63:0] ZQ_INTERVAL = 64'd4,
    parameter [63:0] ZQ_BLOCK = 64'd4
) (
    input wire clk,
    input wire i_ce,
    input wire inference_begin,
    input wire inference_end,
    output reg zq_short,
    output wire [63:0] zq_short_ticket,
    output wire inference_blocked,
    output wire schedule_stalled,
    output reg calibration_done,
    output reg [63:0] completed_ticket,
    output reg [255:0] scheduler_telemetry,
    output wire completion_ready,
    output wire completion_stalled,
    output wire [$clog2(JOURNAL_DEPTH):0] journal_used,
    output wire [63:0] journal_head_ticket,
    output wire [63:0] journal_head_horizon,
    output reg audit_busy,
    output reg audit_done,
    output reg [63:0] audit_last_ticket,
    output reg [63:0] audit_last_horizon,
    output wire [63:0] audit_last_backlog,
    output reg [63:0] audit_digest
);
    // DEPTH is at least two; interval and blocking durations are positive.
    localparam [63:0] DEPTH64 = DEPTH;
    // The journal depth is a power of two, at least four.
    localparam integer JOURNAL_ADDR_W = $clog2(JOURNAL_DEPTH);
    localparam integer JOURNAL_PTR_W = JOURNAL_ADDR_W + 32'd1;
    localparam [63:0] AUDIT_POLYNOMIAL = 64'h42f0_e1eb_a9ea_3693;

    // Each completion records the producer's acceptance watermark.
    reg [63:0] journal_ticket [32'd0:JOURNAL_DEPTH-32'd1];
    reg [63:0] journal_horizon [32'd0:JOURNAL_DEPTH-32'd1];
    reg [JOURNAL_PTR_W-1:0] journal_rd_ptr;
    reg [JOURNAL_PTR_W-1:0] journal_wr_ptr;
    reg [63:0] audit_ticket;
    reg [63:0] audit_work_horizon;
    reg [63:0] audit_crc;
    reg [3:0] audit_byte;

    reg [63:0] interval_counter;
    reg [63:0] blocking_timer;
    reg calibration_in_progress;

    // Periodic requests wait in a bounded FIFO until calibration can start.
    reg [63:0] pending_ticket [32'd0:DEPTH-32'd1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] pending_count;
    reg [63:0] accepted_serial;

    // These shadows record earlier ZQ command issuance.
    reg [63:0] issued_serial;
    reg issue_seen;
    reg [63:0] active_ticket;
    reg scope_window;

    reg [31:0] diag_enabled_cycles;
    reg [31:0] diag_accepted_count;
    reg [31:0] diag_issued_count;
    reg [31:0] diag_completed_count;
    reg [31:0] diag_stalled_cycles;
    reg [31:0] diag_busy_cycles;
    reg [15:0] diag_stall_run;
    reg [15:0] diag_peak_stall;
    reg [31:0] diag_peak_pending;

    wire interval_due = interval_counter == ZQ_INTERVAL - 64'd1;
    wire enqueue_request = i_ce && interval_due && pending_count < DEPTH64;
    wire issue_command = i_ce && !calibration_in_progress &&
                         pending_count != 64'd0;

    wire journal_empty = journal_rd_ptr == journal_wr_ptr;
    wire journal_full =
        journal_rd_ptr[JOURNAL_ADDR_W] != journal_wr_ptr[JOURNAL_ADDR_W] &&
        journal_rd_ptr[JOURNAL_ADDR_W-1:0] ==
            journal_wr_ptr[JOURNAL_ADDR_W-1:0];
    wire journal_pop =
        i_ce && !audit_busy && !journal_empty;
    wire completion_event =
        i_ce && calibration_in_progress &&
        blocking_timer == 64'd1 && completion_ready;
    wire audit_commit =
        i_ce && audit_busy && audit_byte == 4'd15;
    wire [63:0] audit_crc_word = audit_byte[3] ?
        audit_work_horizon : audit_ticket;
    wire [5:0] audit_shift = {audit_byte[2:0], 3'b000};
    reg [63:0] audit_crc_next;
    integer crc_bit;

    assign completion_ready = !journal_full;
    assign completion_stalled = calibration_in_progress &&
        blocking_timer == 64'd1 && !completion_ready;
    assign journal_used = journal_wr_ptr - journal_rd_ptr;
    assign journal_head_ticket = journal_empty ? 64'd0 :
        journal_ticket[journal_rd_ptr[JOURNAL_ADDR_W-1:0]];
    assign journal_head_horizon = journal_empty ? 64'd0 :
        journal_horizon[journal_rd_ptr[JOURNAL_ADDR_W-1:0]];
    assign audit_last_backlog = audit_last_horizon - audit_last_ticket;

    assign inference_blocked = calibration_in_progress;
    assign zq_short_ticket = active_ticket;
    assign schedule_stalled = interval_due && pending_count == DEPTH64;

    // Per-entry ordering predicates. Occupancy comes from pointers/count,
    // not from summing entry-valid bits.
    wire [63:0] slot_distance [32'd0:DEPTH-32'd1];
    wire [DEPTH-32'd1:32'd0] slot_occupied;
    wire [DEPTH-32'd1:32'd0] entry_consistent;
    genvar g;
    generate
        for (g = 32'd0; g < DEPTH; g = g + 32'd1) begin : slots
            localparam [63:0] SLOT = g;
            assign slot_distance[g] = (SLOT >= rd_ptr) ?
                SLOT - rd_ptr : DEPTH64 - rd_ptr + SLOT;
            assign slot_occupied[g] = slot_distance[g] < pending_count;
            assign entry_consistent[g] = !slot_occupied[g] ||
                pending_ticket[g] == issued_serial + slot_distance[g] + 64'd1;
        end
    endgenerate

    integer k;
    initial begin
        interval_counter = 64'd0;
        blocking_timer = 64'd0;
        calibration_in_progress = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        pending_count = 64'd0;
        accepted_serial = 64'd0;
        issued_serial = 64'd0;
        issue_seen = 1'b0;
        active_ticket = 64'd0;
        scope_window = 1'b0;
        zq_short = 1'b0;
        calibration_done = 1'b0;
        completed_ticket = 64'd0;
        diag_enabled_cycles = 32'd0;
        diag_accepted_count = 32'd0;
        diag_issued_count = 32'd0;
        diag_completed_count = 32'd0;
        diag_stalled_cycles = 32'd0;
        diag_busy_cycles = 32'd0;
        diag_stall_run = 16'd0;
        diag_peak_stall = 16'd0;
        diag_peak_pending = 32'd0;
        scheduler_telemetry = 256'd0;
        journal_rd_ptr = {JOURNAL_PTR_W{1'b0}};
        journal_wr_ptr = {JOURNAL_PTR_W{1'b0}};
        audit_ticket = 64'd0;
        audit_work_horizon = 64'd0;
        audit_crc = 64'd0;
        audit_byte = 4'd0;
        audit_busy = 1'b0;
        audit_done = 1'b0;
        audit_last_ticket = 64'd0;
        audit_last_horizon = 64'd0;
        audit_digest = 64'd0;
        for (k = 32'd0; k < JOURNAL_DEPTH; k = k + 32'd1) begin
            journal_ticket[k] = 64'd0;
            journal_horizon[k] = 64'd0;
        end
        for (k = 32'd0; k < DEPTH; k = k + 32'd1)
            pending_ticket[k] = 64'd0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Q opens a persistent observation window; R closes it.
            if (inference_end)
                scope_window <= 1'b0;
            else if (inference_begin)
                scope_window <= 1'b1;

            zq_short <= 1'b0;
            calibration_done <= 1'b0;

            // A full FIFO makes the periodic source wait at its deadline.
            if (enqueue_request) begin
                interval_counter <= 64'd0;
                accepted_serial <= accepted_serial + 64'd1;
                pending_ticket[wr_ptr] <= accepted_serial + 64'd1;
                if (wr_ptr == DEPTH64 - 64'd1)
                    wr_ptr <= 64'd0;
                else
                    wr_ptr <= wr_ptr + 64'd1;
            end else if (!interval_due) begin
                interval_counter <= interval_counter + 64'd1;
            end

            // Only the oldest pending request can enter service, and no
            // request enters service until the previous blocking period ends.
            if (issue_command) begin
                active_ticket <= pending_ticket[rd_ptr];
                issued_serial <= issued_serial + 64'd1;
                issue_seen <= 1'b1;
                zq_short <= 1'b1;
                calibration_in_progress <= 1'b1;
                blocking_timer <= ZQ_BLOCK;
                if (rd_ptr == DEPTH64 - 64'd1)
                    rd_ptr <= 64'd0;
                else
                    rd_ptr <= rd_ptr + 64'd1;
            end else if (calibration_in_progress) begin
                if (blocking_timer == 64'd1 && completion_ready) begin
                    blocking_timer <= 64'd0;
                    calibration_in_progress <= 1'b0;
                    calibration_done <= 1'b1;
                    completed_ticket <= active_ticket;
                end else if (blocking_timer != 64'd1) begin
                    blocking_timer <= blocking_timer - 64'd1;
                end
            end

            case ({enqueue_request, issue_command})
                2'b10: pending_count <= pending_count + 64'd1;
                2'b01: pending_count <= pending_count - 64'd1;
                default: pending_count <= pending_count;
            endcase
        end
    end

    // Passive statistics, with a registered snapshot for debug readout.
    always @(posedge clk) begin
        if (i_ce) begin
            if (diag_enabled_cycles != 32'hffff_ffff)
                diag_enabled_cycles <= diag_enabled_cycles + 32'd1;
            if (enqueue_request && diag_accepted_count != 32'hffff_ffff)
                diag_accepted_count <= diag_accepted_count + 32'd1;
            if (issue_command && diag_issued_count != 32'hffff_ffff)
                diag_issued_count <= diag_issued_count + 32'd1;
            if (completion_event &&
                diag_completed_count != 32'hffff_ffff)
                diag_completed_count <= diag_completed_count + 32'd1;
            if (schedule_stalled && diag_stalled_cycles != 32'hffff_ffff)
                diag_stalled_cycles <= diag_stalled_cycles + 32'd1;
            if (calibration_in_progress && diag_busy_cycles != 32'hffff_ffff)
                diag_busy_cycles <= diag_busy_cycles + 32'd1;
            if (schedule_stalled) begin
                if (diag_stall_run != 16'hffff)
                    diag_stall_run <= diag_stall_run + 16'd1;
                if (diag_stall_run >= diag_peak_stall &&
                    diag_stall_run != 16'hffff)
                    diag_peak_stall <= diag_stall_run + 16'd1;
            end else begin
                diag_stall_run <= 16'd0;
            end
            if (pending_count > {32'd0, diag_peak_pending})
                diag_peak_pending <= pending_count[31:0];
            scheduler_telemetry <= {
                diag_enabled_cycles, diag_accepted_count,
                diag_issued_count, diag_completed_count,
                diag_stalled_cycles, diag_busy_cycles,
                diag_stall_run, diag_peak_stall, diag_peak_pending
            };
        end
    end

    // CRC64 covers ticket bytes followed by acceptance-watermark bytes.
    // Advancing one byte per enabled cycle keeps the datapath narrow.
    always @(*) begin
        audit_crc_next = audit_crc ^
            ((audit_crc_word >> audit_shift) << 6'd56);
        for (crc_bit = 32'd0; crc_bit < 32'd8;
             crc_bit = crc_bit + 32'd1) begin
            if (audit_crc_next[63]) begin
                audit_crc_next =
                    (audit_crc_next << 1'b1) ^ AUDIT_POLYNOMIAL;
            end else begin
                audit_crc_next = audit_crc_next << 1'b1;
            end
        end
    end

    // The wrap bits distinguish a full journal from an empty one.
    // A final blocking cycle waits here until its record can be retained.
    always @(posedge clk) begin
        if (i_ce) begin
            if (completion_event) begin
                journal_ticket[
                    journal_wr_ptr[JOURNAL_ADDR_W-1:0]
                ] <= active_ticket;
                journal_horizon[
                    journal_wr_ptr[JOURNAL_ADDR_W-1:0]
                ] <= accepted_serial;
                journal_wr_ptr <= journal_wr_ptr + 1'b1;
            end
            if (journal_pop) begin
                journal_rd_ptr <= journal_rd_ptr + 1'b1;
            end
        end
    end

    // Pull one complete record, then keep it resident for all sixteen
    // byte updates. Published results change only at record boundaries.
    always @(posedge clk) begin
        if (i_ce) begin
            audit_done <= 1'b0;
            if (journal_pop) begin
                audit_ticket <= journal_ticket[
                    journal_rd_ptr[JOURNAL_ADDR_W-1:0]
                ];
                audit_work_horizon <= journal_horizon[
                    journal_rd_ptr[JOURNAL_ADDR_W-1:0]
                ];
                audit_byte <= 4'd0;
                audit_busy <= 1'b1;
            end else if (audit_busy) begin
                audit_crc <= audit_crc_next;
                if (audit_commit) begin
                    audit_last_ticket <= audit_ticket;
                    audit_last_horizon <= audit_work_horizon;
                    audit_digest <= audit_crc_next;
                    audit_done <= 1'b1;
                    audit_busy <= 1'b0;
                    audit_byte <= 4'd0;
                end else begin
                    audit_byte <= audit_byte + 4'd1;
                end
            end
        end
    end

    // Completion must be preceded by a command, with the recorded ticket.
    always @(posedge clk) begin
        if (scope_window && calibration_done)
            assert (issue_seen);
        if (scope_window && calibration_done)
            assert (completed_ticket == issued_serial);
    end

    // Audit records must be contiguous and carry a bounded backlog.
    always @(posedge clk) begin
        if (audit_commit)
            assert (audit_ticket == audit_last_ticket + 64'd1 &&
                    audit_work_horizon - audit_ticket <= DEPTH64);
    end
endmodule

module striped_activity_reducer #(
    parameter integer LANES = 4,
    parameter integer WORDS = 16
) (
    input  wire clk,
    input  wire ce,
    input  wire in_valid,
    input  wire [63:0] in_word,
    input  wire [63:0] in_phase,
    output wire input_ready,
    output reg busy,
    output reg report_valid,
    output reg [63:0] first_word,
    output reg [63:0] any_bits,
    output reg [63:0] all_bits,
    output reg [63:0] parity_bits,
    output reg [$clog2(WORDS+1)-1:0] sample_count,
    output reg [$clog2(LANES+1)-1:0] reduced_count,
    output wire [64*LANES-1:0] any_contents,
    output wire [64*LANES-1:0] all_contents,
    output wire [64*LANES-1:0] parity_contents
);
    localparam integer BANK_W = $clog2(LANES);
    localparam [63:0] WORDS64 = WORDS;
    reg [63:0] lane_any [0:LANES-1];
    reg [63:0] lane_all [0:LANES-1];
    reg [63:0] lane_parity [0:LANES-1];
    wire [BANK_W-1:0] bank = in_phase % LANES;
    wire take = in_valid && input_ready;
    wire first_sample = (in_phase == 64'd0);
    wire last_sample = (in_phase == WORDS64 - 64'd1);
    assign input_ready = ce && !busy;

    integer lane_index;
    initial begin
        busy = 1'b0;
        report_valid = 1'b0;
        first_word = 64'd0;
        any_bits = 64'd0;
        all_bits = 64'hffffffffffffffff;
        parity_bits = 64'd0;
        sample_count = 0;
        reduced_count = 0;
        for (lane_index = 0; lane_index < LANES; lane_index = lane_index + 1) begin
            lane_any[lane_index] = 64'd0;
            lane_all[lane_index] = 64'hffffffffffffffff;
            lane_parity[lane_index] = 64'd0;
        end
    end

    genvar lane_slot;
    generate
        for (lane_slot = 0; lane_slot < LANES; lane_slot = lane_slot + 1) begin : inspection
            assign any_contents[64*lane_slot +: 64] = lane_any[lane_slot];
            assign all_contents[64*lane_slot +: 64] = lane_all[lane_slot];
            assign parity_contents[64*lane_slot +: 64] = lane_parity[lane_slot];
        end
    endgenerate

    always @(posedge clk) begin
        report_valid <= 1'b0;
        if (take) begin
            if (first_sample) begin
                first_word <= in_word;
                sample_count <= 1;
                for (lane_index = 0; lane_index < LANES; lane_index = lane_index + 1) begin
                    lane_any[lane_index] <= (bank == lane_index)
                                            ? in_word : 64'd0;
                    lane_all[lane_index] <= (bank == lane_index)
                                            ? in_word : 64'hffffffffffffffff;
                    lane_parity[lane_index] <= (bank == lane_index)
                                               ? in_word : 64'd0;
                end
            end else begin
                sample_count <= sample_count + 1'b1;
                lane_any[bank] <= lane_any[bank] | in_word;
                lane_all[bank] <= lane_all[bank] & in_word;
                lane_parity[bank] <= lane_parity[bank] ^ in_word;
            end
            if (last_sample) begin
                busy <= 1'b1;
                reduced_count <= 0;
                any_bits <= 64'd0;
                all_bits <= 64'hffffffffffffffff;
                parity_bits <= 64'd0;
            end
        end
        if (ce && busy) begin
            any_bits <= any_bits | lane_any[reduced_count];
            all_bits <= all_bits & lane_all[reduced_count];
            parity_bits <= parity_bits ^ lane_parity[reduced_count];
            reduced_count <= reduced_count + 1'b1;
            if (reduced_count == LANES-1) begin
                busy <= 1'b0;
                report_valid <= 1'b1;
            end
        end
    end
endmodule

module retained_seed_fifo #(
    parameter integer DEPTH = 4
) (
    input  wire clk,
    input  wire ce,
    input  wire in_valid,
    input  wire [63:0] in_data,
    output wire in_ready,
    input  wire release_head,
    output wire out_valid,
    output wire [63:0] out_data,
    output reg [$clog2(DEPTH+1)-1:0] count,
    output reg [$clog2(DEPTH)-1:0] read_index,
    output reg [$clog2(DEPTH)-1:0] write_index,
    output wire [64*DEPTH-1:0] contents
);
    localparam integer PTR_W = $clog2(DEPTH);
    reg [63:0] storage [0:DEPTH-1];
    wire take_out = ce && release_head && out_valid;
    wire take_in = in_valid && in_ready;
    assign in_ready = ce && ((count < DEPTH) || take_out);
    assign out_valid = (count != 0);
    assign out_data = storage[read_index];

    integer entry_index;
    initial begin
        count = 0;
        read_index = 0;
        write_index = 0;
        for (entry_index = 0; entry_index < DEPTH; entry_index = entry_index + 1)
            storage[entry_index] = 64'd0;
    end

    genvar entry_slot;
    generate
        for (entry_slot = 0; entry_slot < DEPTH; entry_slot = entry_slot + 1) begin : inspection
            assign contents[64*entry_slot +: 64] = storage[entry_slot];
        end
    endgenerate

    // A request stays at the head until its complete batch has retired.
    always @(posedge clk) begin
        if (take_in) begin
            storage[write_index] <= in_data;
            write_index <= (write_index == DEPTH-1)
                           ? {PTR_W{1'b0}} : write_index + 1'b1;
        end
        if (take_out)
            read_index <= (read_index == DEPTH-1)
                          ? {PTR_W{1'b0}} : read_index + 1'b1;
        case ({take_in, take_out})
            2'b10: count <= count + 1'b1;
            2'b01: count <= count - 1'b1;
            default: begin end
        endcase
    end
endmodule

module phased_case_emitter #(
    parameter integer DEPTH = 16,
parameter integer SEED_DEPTH = 4,
parameter integer SIG_LANES = 4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        seed_valid,
    input  wire [63:0] seed_in,
    output wire        seed_ready,
    output reg  [63:0] issued_word,
    output reg  [63:0] issued_phase,
    output reg  [63:0] issued_mask,
    output wire [63:0] pending_seed,
    output wire [$clog2(SEED_DEPTH+1)-1:0] pending_count,
    output wire [$clog2(SEED_DEPTH)-1:0] seed_read_index,
    output wire [$clog2(SEED_DEPTH)-1:0] seed_write_index,
output wire [64*SEED_DEPTH-1:0] seed_storage,
output wire signature_ready,
output wire signature_busy,
output wire signature_valid,
output wire [63:0] signature_first,
output wire [63:0] signature_any,
output wire [63:0] signature_all,
output wire [63:0] signature_parity,
output wire [$clog2(DEPTH+1)-1:0] signature_words,
output wire [$clog2(SIG_LANES+1)-1:0] signature_reduced,
output wire [64*SIG_LANES-1:0] signature_any_storage,
output wire [64*SIG_LANES-1:0] signature_all_storage,
output wire [64*SIG_LANES-1:0] signature_parity_storage,
output wire [$clog2(DEPTH+1)-1:0] signature_held
);
    // DEPTH is the number of timing phases and table entries; use 2 through 16.
    localparam [63:0] DEPTH64 = DEPTH;
    localparam [63:0] LAST_PHASE = DEPTH64 - 64'd1;
    localparam [DEPTH-1:0] PHASE_ONE = {{(DEPTH-1){1'b0}}, 1'b1};
    localparam [63:0] PHASE_SPREAD = (64'd1 << $clog2(DEPTH)) - 64'd1;
    localparam [63:0] PHASE_PARITY = ((DEPTH % 4) == 0) ? 64'd0 :
                                   ((DEPTH % 4) == 1) ? LAST_PHASE :
                                   ((DEPTH % 4) == 2) ? 64'd1 : DEPTH64;

    reg [63:0] phase;
    reg [DEPTH-1:0] phase_enable;
    reg [63:0] filled;
    reg [63:0] seed;
    reg draining;
    reg window;

    reg [63:0] words [0:DEPTH-1];
    reg [DEPTH-1:0] valid;
    wire pending_valid;
    wire release_seed;

    // Admission is independent of execution; the active request retains its slot.
    retained_seed_fifo #(.DEPTH(SEED_DEPTH)) seed_requests (
        .clk(clk), .ce(i_ce),
        .in_valid(seed_valid), .in_data(seed_in), .in_ready(seed_ready),
        .release_head(release_seed),
        .out_valid(pending_valid), .out_data(pending_seed),
        .count(pending_count), .read_index(seed_read_index),
        .write_index(seed_write_index), .contents(seed_storage)
    );
    wire advance = i_ce && (!draining || signature_ready) &&
                   (draining || (phase != 64'd0) || pending_valid);
    wire [63:0] next_phase = (phase == LAST_PHASE)
                             ? 64'd0 : phase + 64'd1;
    wire [63:0] fill_seed = pending_seed;

    // Q opens the checking window; the final dispatch closes it.
    wire open_window = advance && draining && (phase == 64'd0);
    wire close_window = advance && draining && (phase == LAST_PHASE);
    assign release_seed = close_window;

    initial begin
        phase = 64'd0;
        phase_enable = PHASE_ONE;
        filled = 64'd0;
        seed = 64'd0;
        draining = 1'b0;
        window = 1'b0;
        issued_word = 64'd0;
        issued_phase = 64'd0;
        issued_mask = 64'd1;
    end

    // The registered decoder supplies the per-entry timing strobes.
    genvar slot;
    generate
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin : entries
            initial begin
                words[slot] = 64'd0;
                valid[slot] = 1'b0;
            end
            always @(posedge clk) begin
                if (advance && phase_enable[slot]) begin
                    if (!draining) begin
                        words[slot] <= fill_seed ^ phase;
                        valid[slot] <= 1'b1;
                    end else begin
                        valid[slot] <= 1'b0;
                    end
                end
            end
        end
    endgenerate

    reg [63:0] selected_word;
    integer mux_index;
    always @(*) begin
        selected_word = 64'd0;
        for (mux_index = 0; mux_index < DEPTH; mux_index = mux_index + 1)
            if (phase_enable[mux_index])
                selected_word = selected_word | words[mux_index];
    end

    // Collect striped bit activity, then serialize the batch reduction.
    striped_activity_reducer #(
        .LANES(SIG_LANES), .WORDS(DEPTH)
    ) dispatch_activity (
        .clk(clk), .ce(i_ce),
        .in_valid(draining), .in_word(selected_word), .in_phase(phase),
        .input_ready(signature_ready), .busy(signature_busy),
        .report_valid(signature_valid), .first_word(signature_first),
        .any_bits(signature_any), .all_bits(signature_all),
        .parity_bits(signature_parity),
        .sample_count(signature_words), .reduced_count(signature_reduced),
        .any_contents(signature_any_storage),
        .all_contents(signature_all_storage),
        .parity_contents(signature_parity_storage)
    );
    assign signature_held =
        (signature_busy || signature_valid ||
         (draining && (phase != 64'd0))) ? signature_words : 1'b0;

    always @(posedge clk) begin
        if (advance) begin
            phase <= next_phase;
            phase_enable <= PHASE_ONE << next_phase;

            if (!draining) begin
                if (phase == 64'd0)
                    seed <= fill_seed;
                filled <= filled + 64'd1;
                if (phase == LAST_PHASE)
                    draining <= 1'b1;
            end else begin
                filled <= filled - 64'd1;
                issued_word <= selected_word;
                issued_phase <= phase;
                issued_mask <= phase_enable;
                if (phase == LAST_PHASE)
                    draining <= 1'b0;
            end

            if (close_window)
                window <= 1'b0;
            else if (open_window)
                window <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (window) begin
            assert (issued_word == (seed ^ issued_phase));
            assert (issued_mask == (64'd1 << issued_phase));
        end
    end

    always @(posedge clk) begin
        if (window) begin
            assert (issued_word == (pending_seed ^ issued_phase));
        end
    end

    always @(posedge clk) begin
        if (signature_valid) begin
            assert ((signature_any == (signature_first | PHASE_SPREAD)) &&
                    (signature_all == (signature_first & ~PHASE_SPREAD)) &&
                    (signature_parity == (((DEPTH % 2) != 0
                        ? signature_first : 64'd0) ^ PHASE_PARITY)));
        end
    end
endmodule

module chien_sparse_intervals #(
    parameter integer FIELD_W = 8,
    parameter integer DEPTH = 4,
    parameter integer COUNT_W = $clog2(DEPTH + 1)
) (
    input  wire clk,
    input  wire begin_search,
    input  wire sample_valid,
    output wire sample_ready,
    input  wire [FIELD_W-1:0] sample_position,
    input  wire sample_hit,
    input  wire sample_last,
    output wire packet_valid,
    input  wire packet_ready,
    output wire [FIELD_W-1:0] packet_first,
    output wire [FIELD_W-1:0] packet_position,
    output wire [FIELD_W:0] packet_length,
    output wire packet_hit,
    output wire packet_last,
    output reg  [COUNT_W-1:0] count,
    output reg  [FIELD_W-1:0] run_first,
    output reg  [FIELD_W-1:0] run_skip,
    output reg  stage_valid,
    output reg  [FIELD_W-1:0] stage_first,
    output reg  [FIELD_W-1:0] stage_skip,
    output reg  [FIELD_W-1:0] stage_end,
    output reg  stage_last,
    output wire [DEPTH*FIELD_W-1:0] fifo_first_state,
    output wire [DEPTH*FIELD_W-1:0] fifo_skip_state,
    output wire [DEPTH*FIELD_W-1:0] fifo_end_state,
    output wire [DEPTH-1:0] fifo_last_state
);
    localparam [FIELD_W-1:0] ZERO = {FIELD_W{1'b0}};
    localparam [FIELD_W-1:0] ONE = {{(FIELD_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};

    reg [FIELD_W-1:0] fifo_first [0:DEPTH-1];
    reg [FIELD_W-1:0] fifo_skip [0:DEPTH-1];
    reg [FIELD_W-1:0] fifo_end [0:DEPTH-1];
    reg [DEPTH-1:0] fifo_hit;
    reg [DEPTH-1:0] fifo_last;
    reg stage_hit;

    wire endpoint;
    wire take_sample;
    wire queue_space;
    wire fifo_push;
    wire fifo_pop;
    wire [COUNT_W-1:0] write_slot;
    integer init_slot;
    integer shift_slot;

    assign endpoint = sample_hit || sample_last;
    assign queue_space = count < DEPTH;
    assign fifo_push = stage_valid && queue_space;
    assign packet_valid = count != {COUNT_W{1'b0}};
    assign fifo_pop = packet_valid && packet_ready;
    assign sample_ready = !endpoint || !stage_valid || fifo_push;
    assign take_sample = sample_valid && sample_ready;
    assign write_slot = count - {{(COUNT_W-1){1'b0}}, fifo_pop};

    assign packet_first = fifo_first[0];
    assign packet_position = fifo_end[0];
    assign packet_length = {1'b0, fifo_skip[0]} + {{FIELD_W{1'b0}}, 1'b1};
    assign packet_hit = fifo_hit[0];
    assign packet_last = fifo_last[0];
    assign fifo_last_state = fifo_last;

    genvar view_slot;
    generate
        for (view_slot = 0; view_slot < DEPTH; view_slot = view_slot + 1) begin : descriptor_views
            assign fifo_first_state[view_slot*FIELD_W +: FIELD_W] = fifo_first[view_slot];
            assign fifo_skip_state[view_slot*FIELD_W +: FIELD_W] = fifo_skip[view_slot];
            assign fifo_end_state[view_slot*FIELD_W +: FIELD_W] = fifo_end[view_slot];
        end
    endgenerate

    initial begin
        count = {COUNT_W{1'b0}};
        run_first = ZERO;
        run_skip = ZERO;
        stage_valid = 1'b0;
        stage_first = ZERO;
        stage_skip = ZERO;
        stage_end = ZERO;
        stage_hit = 1'b0;
        stage_last = 1'b0;
        fifo_hit = {DEPTH{1'b0}};
        fifo_last = {DEPTH{1'b0}};
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            fifo_first[init_slot] = ZERO;
            fifo_skip[init_slot] = ZERO;
            fifo_end[init_slot] = ZERO;
        end
    end

    always @(posedge clk) begin
        case ({fifo_push, fifo_pop})
            2'b10: count <= count + COUNT_ONE;
            2'b01: count <= count - COUNT_ONE;
            default: begin end
        endcase

        if (fifo_pop) begin
            for (shift_slot = 0; shift_slot < DEPTH-1; shift_slot = shift_slot + 1) begin
                fifo_first[shift_slot] <= fifo_first[shift_slot+1];
                fifo_skip[shift_slot] <= fifo_skip[shift_slot+1];
                fifo_end[shift_slot] <= fifo_end[shift_slot+1];
                fifo_hit[shift_slot] <= fifo_hit[shift_slot+1];
                fifo_last[shift_slot] <= fifo_last[shift_slot+1];
            end
        end

        if (fifo_push) begin
            fifo_first[write_slot] <= stage_first;
            fifo_skip[write_slot] <= stage_skip;
            fifo_end[write_slot] <= stage_end;
            fifo_hit[write_slot] <= stage_hit;
            fifo_last[write_slot] <= stage_last;
        end

        if (fifo_push)
            stage_valid <= 1'b0;

        if (take_sample && endpoint) begin
            stage_valid <= 1'b1;
            stage_first <= run_first;
            stage_skip <= run_skip;
            stage_end <= sample_position;
            stage_hit <= sample_hit;
            stage_last <= sample_last;
        end

        if (begin_search) begin
            run_first <= ZERO;
            run_skip <= ZERO;
        end else if (take_sample) begin
            if (endpoint) begin
                run_skip <= ZERO;
                if (sample_last)
                    run_first <= ZERO;
                else
                    run_first <= sample_position + ONE;
            end else begin
                run_skip <= run_skip + ONE;
            end
        end
    end
endmodule

module chien_deadline_search #(
    parameter integer FIELD_W = 8,
    parameter integer COEFFS = 4,
    parameter [FIELD_W-1:0] REDUCTION = 8'h1d,
    parameter integer ROOT_DEPTH = 4
) (
    input  wire clk,
    input  wire req_valid,
    output wire req_ready,
    input  wire [COEFFS*FIELD_W-1:0] req_coeffs,
    output wire result_valid,
    input  wire result_ready,
    output reg  [FIELD_W-1:0] position,
    output reg  hit,
    output reg  [3:0] debug_nibble,
    output reg  [3:0] diag_nibble,
    output wire root_valid,
    output wire [FIELD_W-1:0] root_first,
    output wire [FIELD_W-1:0] root_position,
    output wire [FIELD_W:0] root_length,
    output wire root_hit,
    output wire root_last
);
    localparam integer ROOT_COUNT_W = $clog2(ROOT_DEPTH + 1);
    localparam [FIELD_W-1:0] FIELD_ZERO = {FIELD_W{1'b0}};
    localparam [FIELD_W-1:0] FIELD_ONE = {{(FIELD_W-1){1'b0}}, 1'b1};
    localparam [FIELD_W-1:0] LAST_POSITION = {FIELD_W{1'b1}};
    localparam [FIELD_W:0] FIELD_SIZE = {1'b1, {FIELD_W{1'b0}}};
    localparam [FIELD_W:0] CREDIT_ONE = {{FIELD_W{1'b0}}, 1'b1};

    reg busy;
    reg armed;
    reg pv;
    reg [FIELD_W:0] credits;
    reg [FIELD_W-1:0] terms [0:COEFFS-1];
    wire [FIELD_W-1:0] stepped_terms [0:COEFFS-1];
    reg [FIELD_W-1:0] eval_now;
    reg [FIELD_W-1:0] eval_next;

    wire sparse_ready;
    wire [ROOT_COUNT_W-1:0] root_count;
    wire [ROOT_COUNT_W-1:0] root_held;
    wire [FIELD_W-1:0] root_run_first;
    wire [FIELD_W-1:0] root_run_skip;
    wire root_stage_valid;
    wire [FIELD_W-1:0] root_stage_first;
    wire [FIELD_W-1:0] root_stage_skip;
    wire [FIELD_W-1:0] root_stage_end;
    wire root_stage_last;
    wire [ROOT_DEPTH*FIELD_W-1:0] root_q_first;
    wire [ROOT_DEPTH*FIELD_W-1:0] root_q_skip;
    wire [ROOT_DEPTH*FIELD_W-1:0] root_q_end;
    wire [ROOT_DEPTH-1:0] root_q_last;

    wire request_fire;
    wire trial_fire;
    assign req_ready = !busy;
    assign result_valid = busy && sparse_ready;
    assign request_fire = req_valid && req_ready;
    assign trial_fire = result_valid && result_ready;

    assign root_held = root_count + {{(ROOT_COUNT_W-1){1'b0}}, root_stage_valid};

    chien_sparse_intervals #(
        .FIELD_W(FIELD_W),
        .DEPTH(ROOT_DEPTH),
        .COUNT_W(ROOT_COUNT_W)
    ) root_intervals (
        .clk(clk),
        .begin_search(request_fire),
        .sample_valid(trial_fire),
        .sample_ready(sparse_ready),
        .sample_position(position),
        .sample_hit(hit),
        .sample_last(position == LAST_POSITION),
        .packet_valid(root_valid),
        .packet_ready(result_ready),
        .packet_first(root_first),
        .packet_position(root_position),
        .packet_length(root_length),
        .packet_hit(root_hit),
        .packet_last(root_last),
        .count(root_count),
        .run_first(root_run_first),
        .run_skip(root_run_skip),
        .stage_valid(root_stage_valid),
        .stage_first(root_stage_first),
        .stage_skip(root_stage_skip),
        .stage_end(root_stage_end),
        .stage_last(root_stage_last),
        .fifo_first_state(root_q_first),
        .fifo_skip_state(root_q_skip),
        .fifo_end_state(root_q_end),
        .fifo_last_state(root_q_last)
    );

    function automatic [FIELD_W-1:0] gf_xtime;
        input [FIELD_W-1:0] a;
        begin
            gf_xtime = (a << 1'b1) ^
                       (a[FIELD_W-1] ? REDUCTION : FIELD_ZERO);
        end
    endfunction

    function automatic [FIELD_W-1:0] gf_mul;
        input [FIELD_W-1:0] a;
        input [FIELD_W-1:0] b;
        reg [FIELD_W-1:0] multiplicand;
        reg [FIELD_W-1:0] multiplier;
        reg [FIELD_W-1:0] product;
        integer bit_index;
        begin
            multiplicand = a;
            multiplier = b;
            product = FIELD_ZERO;
            for (bit_index = 0; bit_index < FIELD_W; bit_index = bit_index + 1) begin
                if (multiplier[0])
                    product = product ^ multiplicand;
                multiplicand = gf_xtime(multiplicand);
                multiplier = multiplier >> 1'b1;
            end
            gf_mul = product;
        end
    endfunction

    function automatic [FIELD_W-1:0] alpha_factor;
        input integer exponent;
        reg [FIELD_W-1:0] factor;
        integer power_index;
        begin
            factor = FIELD_ONE;
            for (power_index = 0; power_index < exponent; power_index = power_index + 1)
                factor = gf_xtime(factor);
            alpha_factor = factor;
        end
    endfunction

    genvar coefficient;
    generate
        for (coefficient = 0; coefficient < COEFFS; coefficient = coefficient + 1) begin : coefficient_steps
            assign stepped_terms[coefficient] =
                gf_mul(terms[coefficient], alpha_factor(coefficient));
        end
    endgenerate

    integer eval_index;
    always @(*) begin
        eval_now = FIELD_ZERO;
        eval_next = FIELD_ZERO;
        for (eval_index = 0; eval_index < COEFFS; eval_index = eval_index + 1) begin
            eval_now = eval_now ^ terms[eval_index];
            eval_next = eval_next ^ stepped_terms[eval_index];
        end
    end

    reg [31:0] diag_trace [0:3];
    reg [15:0] diag_ticks;
    reg [15:0] diag_watchdog;
    reg [15:0] diag_timeouts;
    reg [15:0] diag_events;
    reg [15:0] diag_wraps;
    reg [15:0] diag_long_stalls;
    reg [3:0] diag_tag;
    reg [1:0] diag_wr_ptr;
    reg [5:0] diag_scan;
    reg [3:0] diag_fold;
    reg [3:0] diag_event;
    wire [7:0] diag_position;
    wire [223:0] diag_frame;
    wire diag_timeout;
    integer diag_bit;
    integer diag_init;

    assign diag_position = position;
    assign diag_timeout = busy && !result_ready &&
                          (diag_watchdog == 16'd1023);
    assign diag_frame = {diag_wraps, diag_long_stalls,
                         diag_timeouts, diag_events, diag_watchdog, diag_ticks,
                         diag_trace[3], diag_trace[2], diag_trace[1], diag_trace[0]};

    always @(*) begin
        diag_fold = 4'd0;
        for (diag_bit = 0; diag_bit < COEFFS*FIELD_W; diag_bit = diag_bit + 1)
            diag_fold[diag_bit % 4] = diag_fold[diag_bit % 4] ^ req_coeffs[diag_bit];
        diag_event = 4'd0;
        if (request_fire)
            diag_event = 4'd1;
        else if (diag_timeout)
            diag_event = 4'd4;
        else if (trial_fire && position == LAST_POSITION)
            diag_event = 4'd3;
        else if (trial_fire && hit)
            diag_event = 4'd2;
    end

    initial begin
        diag_ticks = 16'd0;
        diag_watchdog = 16'd0;
        diag_timeouts = 16'd0;
        diag_events = 16'd0;
        diag_wraps = 16'd0;
        diag_long_stalls = 16'd0;
        diag_tag = 4'd0;
        diag_wr_ptr = 2'd0;
        diag_scan = 6'd0;
        diag_nibble = 4'd0;
        for (diag_init = 0; diag_init < 4; diag_init = diag_init + 1)
            diag_trace[diag_init] = 32'd0;
    end

    always @(posedge clk) begin
        diag_ticks <= diag_ticks + 16'd1;
        if (diag_scan == 6'd55)
            diag_scan <= 6'd0;
        else
            diag_scan <= diag_scan + 6'd1;
        diag_nibble <= diag_frame[{diag_scan, 2'b00} +: 4];
        if (request_fire)
            diag_tag <= diag_fold;
        if (busy && !result_ready) begin
            if (diag_watchdog != 16'hffff)
                diag_watchdog <= diag_watchdog + 16'd1;
        end else begin
            diag_watchdog <= 16'd0;
        end
        if (diag_timeout && diag_timeouts != 16'hffff)
            diag_timeouts <= diag_timeouts + 16'd1;
        if (busy && !result_ready && diag_watchdog >= 16'd1023) begin
            if (diag_long_stalls != 16'hffff)
                diag_long_stalls <= diag_long_stalls + 16'd1;
        end
        if (diag_event != 4'd0) begin
            diag_trace[diag_wr_ptr] <= {diag_ticks, diag_position,
                                       diag_event, request_fire ? diag_fold : diag_tag};
            diag_wr_ptr <= diag_wr_ptr + 2'd1;
            if (diag_events != 16'hffff)
                diag_events <= diag_events + 16'd1;
            if (diag_wr_ptr == 2'd3) begin
                if (diag_wraps != 16'hffff)
                    diag_wraps <= diag_wraps + 16'd1;
            end
        end
    end

    reg [15:0] mon_requests;
    reg [15:0] mon_results;
    reg [15:0] mon_hits;
    reg [15:0] mon_stalls;
    reg [15:0] mon_stall_run;
    reg [15:0] mon_stall_peak;
    reg [15:0] mon_search_age;
    reg [15:0] mon_last_latency;
    reg [4:0] mon_scan;
    wire [127:0] mon_frame;
    assign mon_frame = {mon_last_latency, mon_search_age,
                        mon_stall_peak, mon_stall_run,
                        mon_stalls, mon_hits, mon_results, mon_requests};

    initial begin
        mon_requests = 16'd0;
        mon_results = 16'd0;
        mon_hits = 16'd0;
        mon_stalls = 16'd0;
        mon_stall_run = 16'd0;
        mon_stall_peak = 16'd0;
        mon_search_age = 16'd0;
        mon_last_latency = 16'd0;
        mon_scan = 5'd0;
        debug_nibble = 4'd0;
    end

    always @(posedge clk) begin
        mon_scan <= mon_scan + 5'd1;
        debug_nibble <= mon_frame[{mon_scan, 2'b00} +: 4];
        if (request_fire && mon_requests != 16'hffff)
            mon_requests <= mon_requests + 16'd1;
        if (trial_fire && mon_results != 16'hffff)
            mon_results <= mon_results + 16'd1;
        if (trial_fire && hit && mon_hits != 16'hffff)
            mon_hits <= mon_hits + 16'd1;
        if (busy && !result_ready) begin
            if (mon_stalls != 16'hffff)
                mon_stalls <= mon_stalls + 16'd1;
            if (mon_stall_run != 16'hffff) begin
                mon_stall_run <= mon_stall_run + 16'd1;
                if (mon_stall_run >= mon_stall_peak)
                    mon_stall_peak <= mon_stall_run + 16'd1;
            end
        end else begin
            mon_stall_run <= 16'd0;
        end
        if (request_fire) begin
            mon_search_age <= 16'd0;
        end else if (busy) begin
            if (mon_search_age != 16'hffff)
                mon_search_age <= mon_search_age + 16'd1;
        end
        if (trial_fire && position == LAST_POSITION) begin
            mon_last_latency <= (mon_search_age == 16'hffff) ?
                                16'hffff : mon_search_age + 16'd1;
        end
    end


    integer init_index;
    initial begin
        busy = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
        credits = {1'b0, FIELD_ZERO};
        position = FIELD_ZERO;
        hit = 1'b0;
        for (init_index = 0; init_index < COEFFS; init_index = init_index + 1)
            terms[init_index] = FIELD_ZERO;
    end

    // Position zero tests x=0. Positions 1..255 test alpha^0..alpha^254.
    // Each accepted result consumes one enabled search cycle. Back-pressure
    // freezes the countdown, multiplier registers, position and hit flag.
    integer state_index;
    always @(posedge clk) begin
        if (request_fire || trial_fire)
            pv <= 1'b1;

        if (request_fire) begin
            armed <= 1'b1;
            busy <= 1'b1;
            credits <= FIELD_SIZE;
            position <= FIELD_ZERO;
            hit <= (req_coeffs[0 +: FIELD_W] == FIELD_ZERO);
            for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                terms[state_index] <= req_coeffs[state_index*FIELD_W +: FIELD_W];
        end else if (trial_fire) begin
            credits <= credits - CREDIT_ONE;
            if (position == LAST_POSITION) begin
                busy <= 1'b0;
            end else begin
                position <= position + FIELD_ONE;
                if (position == FIELD_ZERO) begin
                    // The first nonzero element is one; coefficients stay unchanged.
                    hit <= (eval_now == FIELD_ZERO);
                end else begin
                    for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                        terms[state_index] <= stepped_terms[state_index];
                    hit <= (eval_next == FIELD_ZERO);
                end
            end
        end
    end

    always @(posedge clk)
        if (root_valid)
            assert ((({1'b0, root_first} + root_length) ==
                     ({1'b0, root_position} + CREDIT_ONE)) &&
                    (!root_last || (root_position == LAST_POSITION)));

    // After the first accepted request, consuming the previous cycle's final
    // countdown credit must leave no search outstanding.
    always @(posedge clk)
        if (pv && armed && $past(trial_fire))
            assert (!busy || ($past(credits) > CREDIT_ONE));
endmodule

module gesture_operand_sort #(
    parameter integer WORD_W = 128,
    parameter integer EXP_W = 15,
    parameter integer CACHE_DEPTH = 4
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_a_sig,
    input  wire [WORD_W-1:0]     in_b_sig,
    input  wire [EXP_W-1:0]      in_a_exp,
    input  wire [EXP_W-1:0]      in_b_exp,
    input  wire                  in_last,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [WORD_W-1:0]     large_sig,
    output reg  [WORD_W-1:0]     small_sig,
    output reg  [EXP_W-1:0]      large_exp,
    output reg  [EXP_W-1:0]      small_exp,
    output reg  [EXP_W-1:0]      exponent_gap,
    output reg                   swap_flag,
    output reg                   out_last,
    output reg  [EXP_W-1:0]      retired_span,
    output reg                   cache_hit,
    output reg                   retire_cache_hit
);
    reg before_frame_end;
    reg pv;
    localparam integer CACHE_AW = (CACHE_DEPTH <= 1) ? 1 : $clog2(CACHE_DEPTH);
    reg [EXP_W-1:0] pending_a_exp, pending_b_exp;
    reg [EXP_W-1:0] cache_a_exp [0:CACHE_DEPTH-1];
    reg [EXP_W-1:0] cache_b_exp [0:CACHE_DEPTH-1];
    reg [EXP_W-1:0] cache_gap [0:CACHE_DEPTH-1];
    reg [CACHE_DEPTH-1:0] cache_valid;
    reg [CACHE_DEPTH-1:0] cache_less;
    reg [CACHE_AW-1:0] cache_replace;
    reg [CACHE_AW-1:0] hit_way, retire_way;
    wire [CACHE_AW-1:0] fill_way = retire_cache_hit ? retire_way : cache_replace;
    integer cache_init_i;
    integer cache_lookup_i;

    wire swap_inputs = (cache_hit ? cache_less[hit_way] : (in_a_exp < in_b_exp)) ||
                       ((in_a_exp == in_b_exp) &&
                        (in_a_sig < in_b_sig));
    assign in_ready = !out_valid || out_ready;
    wire in_fire = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    always @(*) begin
        cache_hit = 1'b0;
        retire_cache_hit = 1'b0;
        hit_way = {CACHE_AW{1'b0}};
        retire_way = {CACHE_AW{1'b0}};
        for (cache_lookup_i = 0; cache_lookup_i < CACHE_DEPTH; cache_lookup_i = cache_lookup_i + 1) begin
            if (cache_valid[cache_lookup_i] && cache_a_exp[cache_lookup_i] == in_a_exp &&
                cache_b_exp[cache_lookup_i] == in_b_exp) begin
                cache_hit = 1'b1;
                hit_way = cache_lookup_i;
            end
            if (cache_valid[cache_lookup_i] && cache_a_exp[cache_lookup_i] == pending_a_exp &&
                cache_b_exp[cache_lookup_i] == pending_b_exp) begin
                retire_cache_hit = 1'b1;
                retire_way = cache_lookup_i;
            end
        end
    end

    initial begin
        out_valid = 1'b0;
        large_sig = {WORD_W{1'b0}};
        small_sig = {WORD_W{1'b0}};
        large_exp = {EXP_W{1'b0}};
        small_exp = {EXP_W{1'b0}};
        exponent_gap = {EXP_W{1'b0}};
        swap_flag = 1'b0;
        out_last = 1'b0;
        retired_span = {EXP_W{1'b0}};
        before_frame_end = 1'b1;
        pv = 1'b0;
        pending_a_exp = {EXP_W{1'b0}};
        pending_b_exp = {EXP_W{1'b0}};
        cache_replace = {CACHE_AW{1'b0}};
        cache_valid = {CACHE_DEPTH{1'b0}};
        cache_less = {CACHE_DEPTH{1'b0}};
        for (cache_init_i = 0; cache_init_i < CACHE_DEPTH; cache_init_i = cache_init_i + 1) begin
            cache_a_exp[cache_init_i] = {EXP_W{1'b0}};
            cache_b_exp[cache_init_i] = {EXP_W{1'b0}};
            cache_gap[cache_init_i] = {EXP_W{1'b0}};
        end
    end

    always @(posedge clk) begin
        if (in_fire || out_fire)
            pv <= 1'b1;

        if (out_fire) begin
            cache_valid[fill_way] <= 1'b1;
            cache_a_exp[fill_way] <= pending_a_exp;
            cache_b_exp[fill_way] <= pending_b_exp;
            cache_gap[fill_way] <= exponent_gap;
            cache_less[fill_way] <= (large_exp != small_exp) && swap_flag;
            if (!retire_cache_hit) begin
                if (cache_replace == CACHE_DEPTH-1)
                    cache_replace <= {CACHE_AW{1'b0}};
                else
                    cache_replace <= cache_replace + 1'b1;
            end
        end

        if (in_fire) begin
            out_valid <= 1'b1;
            pending_a_exp <= in_a_exp;
            pending_b_exp <= in_b_exp;
            swap_flag <= swap_inputs;
            out_last <= in_last;
            if (swap_inputs) begin
                large_sig <= in_b_sig;
                small_sig <= in_a_sig;
                large_exp <= in_b_exp;
                small_exp <= in_a_exp;
                exponent_gap <= cache_hit ? cache_gap[hit_way] :
                                            in_b_exp - in_a_exp;
            end else begin
                large_sig <= in_a_sig;
                small_sig <= in_b_sig;
                large_exp <= in_a_exp;
                small_exp <= in_b_exp;
                exponent_gap <= cache_hit ? cache_gap[hit_way] :
                                            in_a_exp - in_b_exp;
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end

        // Alignment-span telemetry for the operand pair just consumed.
        if (out_fire)
            retired_span <= retire_cache_hit ? cache_gap[retire_way] :
                                               large_exp - small_exp;

        // Permanently close the checking scope at the first frame end.
        if (out_fire && out_last)
            before_frame_end <= 1'b0;
    end

    always @(posedge clk) begin
        if (pv && before_frame_end && $past(out_fire))
            assert (retired_span == $past(exponent_gap));
    end
endmodule

module phase_block_statistics #(
    parameter WORD_W = 8,
    parameter ENTRIES = 4,
    parameter INDEX_W = $clog2(ENTRIES),
    parameter COUNT_W = $clog2(ENTRIES+1)
) (
    input wire clk,
    input wire i_ce,
    input wire i_valid,
    input wire [WORD_W-1:0] i_word,
    output wire o_ready,
    output reg [INDEX_W-1:0] o_fill,
    output reg o_busy,
    output reg [INDEX_W-1:0] o_index,
    output reg [WORD_W-1:0] o_work_min,
    output reg [WORD_W-1:0] o_work_max,
    output reg [WORD_W-1:0] o_work_total,
    output reg [COUNT_W-1:0] o_work_leads,
    output reg o_report_valid,
    output reg [WORD_W-1:0] o_min,
    output reg [WORD_W-1:0] o_max,
    output reg [WORD_W-1:0] o_total,
    output reg [WORD_W-1:0] o_spread,
    output reg [COUNT_W-1:0] o_leads,
    output reg [INDEX_W-1:0] o_reversals,
    output wire [ENTRIES*WORD_W-1:0] o_window
);
    reg [WORD_W-1:0] window_words [0:ENTRIES-1];
    reg [WORD_W-1:0] scan_word;
    reg [INDEX_W-1:0] work_crossings;
    reg last_direction;
    integer mux_slot;
    integer init_slot;
    wire take = i_valid && o_ready;
    wire [WORD_W-1:0] magnitude = scan_word & 8'h0f;
    wire [WORD_W-1:0] next_min =
        (magnitude < o_work_min) ? magnitude : o_work_min;
    wire [WORD_W-1:0] next_max =
        (magnitude > o_work_max) ? magnitude : o_work_max;
    wire [WORD_W-1:0] next_total = o_work_total + magnitude;
    wire [COUNT_W-1:0] next_leads = o_work_leads + scan_word[7];
    wire [INDEX_W-1:0] next_crossings = work_crossings
        + ((o_index != 0) && (scan_word[7] != last_direction));

    assign o_ready = !o_busy;

    // A single read mux feeds the block reduction datapath.
    always @(*) begin
        scan_word = 8'd0;
        for (mux_slot = 0; mux_slot < ENTRIES; mux_slot = mux_slot + 1)
            if (o_index == mux_slot)
                scan_word = window_words[mux_slot];
    end

    genvar e;
    generate
        for (e = 0; e < ENTRIES; e = e + 1) begin : snapshot
            assign o_window[e*WORD_W +: WORD_W] = window_words[e];
        end
    endgenerate

    initial begin
        o_fill = {INDEX_W{1'b0}};
        o_busy = 1'b0;
        o_index = {INDEX_W{1'b0}};
        o_work_min = 8'd15;
        o_work_max = 8'd0;
        o_work_total = 8'd0;
        o_work_leads = {COUNT_W{1'b0}};
        work_crossings = {INDEX_W{1'b0}};
        last_direction = 1'b0;
        o_report_valid = 1'b0;
        o_min = 8'd0;
        o_max = 8'd0;
        o_total = 8'd0;
        o_spread = 8'd0;
        o_leads = {COUNT_W{1'b0}};
        o_reversals = {INDEX_W{1'b0}};
        for (init_slot = 0; init_slot < ENTRIES; init_slot = init_slot + 1)
            window_words[init_slot] = 8'd0;
    end

    // Collect a block, then visit its samples in acquisition order.
    // The report is held until the next enabled output cycle.
    always @(posedge clk) begin
        if (i_ce) begin
            o_report_valid <= 1'b0;
            if (o_busy) begin
                o_work_min <= next_min;
                o_work_max <= next_max;
                o_work_total <= next_total;
                o_work_leads <= next_leads;
                work_crossings <= next_crossings;
                last_direction <= scan_word[7];
                if (o_index == ENTRIES - 1) begin
                    o_busy <= 1'b0;
                    o_index <= {INDEX_W{1'b0}};
                    o_report_valid <= 1'b1;
                    o_min <= next_min;
                    o_max <= next_max;
                    o_total <= next_total;
                    o_spread <= next_max - next_min;
                    o_leads <= next_leads;
                    o_reversals <= next_crossings;
                end else
                    o_index <= o_index + 1'b1;
            end
            if (take) begin
                window_words[o_fill] <= i_word;
                if (o_fill == ENTRIES - 1) begin
                    o_fill <= {INDEX_W{1'b0}};
                    o_busy <= 1'b1;
                    o_index <= {INDEX_W{1'b0}};
                    o_work_min <= 8'd15;
                    o_work_max <= 8'd0;
                    o_work_total <= 8'd0;
                    o_work_leads <= {COUNT_W{1'b0}};
                    work_crossings <= {INDEX_W{1'b0}};
                    last_direction <= 1'b0;
                end else
                    o_fill <= o_fill + 1'b1;
            end
        end
    end
endmodule

module phase_capture_deadlines #(
    parameter WORD_W = 8,
    parameter DEPTH = 16,
parameter SERVICE_PERIOD = 8,
parameter RESULT_DEPTH = 4,
parameter ANALYSIS_ENTRIES = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_ref_edge,
    input  wire i_fb_edge,
    output wire o_up,
    output wire o_dn,
    output wire o_pair_ready,
    output wire o_accept,
    output wire o_complete,
output reg [WORD_W-1:0] o_result,
output wire o_retire_ready,
output wire o_serial_valid,
output wire o_serial_bit,
output wire o_serial_first,
output wire o_serial_last,
output wire [$clog2(RESULT_DEPTH+3)-1:0] o_result_level,
output wire o_analysis_valid,
output wire o_analysis_busy,
output wire [WORD_W-1:0] o_analysis_min,
output wire [WORD_W-1:0] o_analysis_max,
output wire [WORD_W-1:0] o_analysis_total,
output wire [WORD_W-1:0] o_analysis_spread,
output wire [$clog2(ANALYSIS_ENTRIES+1)-1:0] o_analysis_leads,
output wire [$clog2(ANALYSIS_ENTRIES)-1:0] o_analysis_reversals,
output wire [$clog2(ANALYSIS_ENTRIES+1)-1:0] o_analysis_level
);
    localparam [WORD_W-1:0] DEPTH8 = DEPTH;
    localparam [WORD_W-1:0] PERIOD8 = SERVICE_PERIOD;
    localparam [WORD_W-1:0] MAX_WAIT8 = DEPTH * SERVICE_PERIOD;
localparam RESULT_ADDR_W = $clog2(RESULT_DEPTH);
localparam RESULT_PTR_W = RESULT_ADDR_W + 1;
localparam SERIAL_COUNT_W =
    (WORD_W > 1) ? $clog2(WORD_W) : 1;
localparam [SERIAL_COUNT_W-1:0] SERIAL_LAST = WORD_W - 1;
localparam ANALYSIS_INDEX_W = $clog2(ANALYSIS_ENTRIES);
localparam ANALYSIS_COUNT_W = $clog2(ANALYSIS_ENTRIES+1);
localparam [ANALYSIS_COUNT_W-1:0] ANALYSIS_SIZE = ANALYSIS_ENTRIES;

    reg up_q, dn_q;
    reg [WORD_W-1:0] phase_ticks;
    reg [WORD_W-1:0] samples [0:DEPTH-1];
    reg [WORD_W-1:0] budget [0:DEPTH-1];
    reg [DEPTH-1:0] valid;
    reg [WORD_W-1:0] rd_ptr, wr_ptr, count;
    reg [WORD_W-1:0] accepted_count, completed_count;
    reg [WORD_W-1:0] service_wait;
    reg armed, past_valid, expired;

    wire seen_up = up_q || i_ref_edge;
    wire seen_dn = dn_q || i_fb_edge;
    wire pair_pending = seen_up && seen_dn;
    wire push = pair_pending && (count < DEPTH8);
wire pop = (count != 8'd0) && (service_wait == 8'd0)
&& !result_full && stats_ready;
    wire common_clear = push;
    wire [WORD_W-1:0] phase_sample =
        phase_ticks | (up_q ? 8'h80 : 8'h00);
    wire [WORD_W-1:0] slot_distance [0:DEPTH-1];
    wire [DEPTH-1:0] expiring;

reg [WORD_W-1:0] result_words [0:RESULT_DEPTH-1];
reg [RESULT_PTR_W-1:0] result_rd_ptr, result_wr_ptr;
reg [WORD_W-1:0] prefetch_sample;
reg prefetch_valid, serial_busy;
reg [SERIAL_COUNT_W-1:0] serial_left;
wire [RESULT_ADDR_W-1:0] result_rd_addr = result_rd_ptr[RESULT_ADDR_W-1:0];
wire [RESULT_ADDR_W-1:0] result_wr_addr = result_wr_ptr[RESULT_ADDR_W-1:0];
wire result_empty = (result_rd_ptr == result_wr_ptr);
wire result_full = (result_rd_addr == result_wr_addr)
    && (result_rd_ptr[RESULT_ADDR_W] != result_wr_ptr[RESULT_ADDR_W]);
wire [RESULT_PTR_W-1:0] result_used =
    (result_rd_ptr[RESULT_ADDR_W] == result_wr_ptr[RESULT_ADDR_W])
    ? ({1'b0, result_wr_addr} - {1'b0, result_rd_addr})
    : (RESULT_DEPTH - {1'b0, result_rd_addr} + {1'b0, result_wr_addr});
wire serial_done = serial_busy && (serial_left == 0);
wire tx_launch = prefetch_valid && (!serial_busy || serial_done);
wire result_read = !result_empty && (!prefetch_valid || tx_launch);
reg [RESULT_PTR_W-1:0] result_rd_next, result_wr_next;
reg [WORD_W-1:0] result_head;
integer scan;
wire stats_ready;
wire stats_report_valid;
wire [ANALYSIS_INDEX_W-1:0] stats_fill;
wire [ANALYSIS_INDEX_W-1:0] stats_index;
wire [WORD_W-1:0] stats_work_min;
wire [WORD_W-1:0] stats_work_max;
wire [WORD_W-1:0] stats_work_total;
wire [ANALYSIS_COUNT_W-1:0] stats_work_leads;
wire [ANALYSIS_ENTRIES*WORD_W-1:0] stats_window;
wire [WORD_W-1:0] stats_words [0:ANALYSIS_ENTRIES-1];

// Retired comparisons also feed block-level jitter and direction reports.
phase_block_statistics #(
    .WORD_W(WORD_W),
    .ENTRIES(ANALYSIS_ENTRIES)
) analysis_unit (
    .clk(clk),
    .i_ce(i_ce),
    .i_valid((count != 8'd0) && (service_wait == 8'd0) && !result_full),
    .i_word(samples[rd_ptr]),
    .o_ready(stats_ready),
    .o_fill(stats_fill),
    .o_busy(o_analysis_busy),
    .o_index(stats_index),
    .o_work_min(stats_work_min),
    .o_work_max(stats_work_max),
    .o_work_total(stats_work_total),
    .o_work_leads(stats_work_leads),
    .o_report_valid(stats_report_valid),
    .o_min(o_analysis_min),
    .o_max(o_analysis_max),
    .o_total(o_analysis_total),
    .o_spread(o_analysis_spread),
    .o_leads(o_analysis_leads),
    .o_reversals(o_analysis_reversals),
    .o_window(stats_window)
);

genvar a;
generate
    for (a = 0; a < ANALYSIS_ENTRIES; a = a + 1) begin : analysis_snapshot
        assign stats_words[a] = stats_window[a*WORD_W +: WORD_W];
    end
endgenerate

assign o_analysis_valid = i_ce && stats_report_valid;
assign o_analysis_level = stats_fill
    + (o_analysis_busy ? ANALYSIS_SIZE : {ANALYSIS_COUNT_W{1'b0}})
    + (stats_report_valid ? ANALYSIS_SIZE : {ANALYSIS_COUNT_W{1'b0}});

// Small flop-based RAM with independent address generators and read mux.
always @(*) begin
    result_rd_next = result_rd_ptr;
    result_wr_next = result_wr_ptr;
    result_head = 8'd0;
    for (scan = 0; scan < RESULT_DEPTH; scan = scan + 1) begin
        if (result_rd_addr == scan)
            result_head = result_words[scan];
    end
    if (pop) begin
        if (result_wr_addr == RESULT_DEPTH - 1) begin
            result_wr_next[RESULT_ADDR_W-1:0] = {RESULT_ADDR_W{1'b0}};
            result_wr_next[RESULT_ADDR_W] = !result_wr_ptr[RESULT_ADDR_W];
        end else
            result_wr_next = result_wr_ptr + 1'b1;
    end
    if (result_read) begin
        if (result_rd_addr == RESULT_DEPTH - 1) begin
            result_rd_next[RESULT_ADDR_W-1:0] = {RESULT_ADDR_W{1'b0}};
            result_rd_next[RESULT_ADDR_W] = !result_rd_ptr[RESULT_ADDR_W];
        end else
            result_rd_next = result_rd_ptr + 1'b1;
    end
end

assign o_retire_ready = i_ce && (service_wait == 8'd0)
&& !result_full && stats_ready;
assign o_serial_valid = i_ce && serial_busy;
assign o_serial_bit = o_result[(WORD_W - 1) - serial_left];
assign o_serial_first = o_serial_valid && (serial_left == SERIAL_LAST);
assign o_serial_last = i_ce && serial_done;
assign o_result_level = result_used + prefetch_valid + serial_busy;

    assign o_up = up_q;
    assign o_dn = dn_q;
    assign o_pair_ready = i_ce && (count < DEPTH8);
    assign o_accept = i_ce && push;
assign o_complete = i_ce && tx_launch;

    initial begin
        up_q = 1'b0;
        dn_q = 1'b0;
        phase_ticks = 8'd0;
        valid = {DEPTH{1'b0}};
        rd_ptr = 8'd0;
        wr_ptr = 8'd0;
        count = 8'd0;
        accepted_count = 8'd0;
        completed_count = 8'd0;
        service_wait = 8'd0;
        armed = 1'b0;
        past_valid = 1'b0;
        expired = 1'b0;
        o_result = 8'd0;
    end

integer r;
initial begin
    result_rd_ptr = {RESULT_PTR_W{1'b0}};
    result_wr_ptr = {RESULT_PTR_W{1'b0}};
    prefetch_sample = 8'd0;
    prefetch_valid = 1'b0;
    serial_busy = 1'b0;
    serial_left = {SERIAL_COUNT_W{1'b0}};
    for (r = 0; r < RESULT_DEPTH; r = r + 1)
        result_words[r] = 8'd0;
end

// Prefetch hides the RAM access while the preceding word is serialized.
// The parallel result changes only at a serial frame boundary.
always @(posedge clk) begin
    if (i_ce) begin
        result_rd_ptr <= result_rd_next;
        result_wr_ptr <= result_wr_next;
        if (pop)
            result_words[result_wr_addr] <= samples[rd_ptr];
        if (result_read) begin
            prefetch_sample <= result_head;
            prefetch_valid <= 1'b1;
        end else if (tx_launch) begin
            prefetch_valid <= 1'b0;
        end

        if (serial_busy) begin
            if (serial_done) begin
                serial_busy <= 1'b0;
                serial_left <= {SERIAL_COUNT_W{1'b0}};
            end else
                serial_left <= serial_left - 1'b1;
        end
        if (tx_launch) begin
            o_result <= prefetch_sample;
            serial_busy <= 1'b1;
            serial_left <= SERIAL_LAST;
        end
    end
end

    // Sampled phase-frequency detector. Both pulse flops use one clear path.
    // A full sample FIFO stretches the paired pulses until storage is free.
    always @(posedge clk) begin
        if (i_ce) begin
            if (common_clear) begin
                up_q <= 1'b0;
                dn_q <= 1'b0;
                phase_ticks <= 8'd0;
            end else begin
                up_q <= seen_up;
                dn_q <= seen_dn;
                if ((seen_up ^ seen_dn) && (phase_ticks < 8'd15))
                    phase_ticks <= phase_ticks + 8'd1;
            end
        end
    end

    // One queued comparison is completed every SERVICE_PERIOD enabled clocks.
    // Budgets count enabled clocks, so disabling i_ce freezes the whole design.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
if (service_wait == 8'd0) begin
if ((count == 8'd0) || (!result_full && stats_ready))
        service_wait <= PERIOD8 - 8'd1;
end else
                service_wait <= service_wait - 8'd1;

            case ({push, pop})
                2'b10: count <= count + 8'd1;
                2'b01: count <= count - 8'd1;
                default: count <= count;
            endcase

            if (push) begin
                armed <= 1'b1;
                accepted_count <= accepted_count + 8'd1;
                if (wr_ptr == DEPTH8 - 8'd1)
                    wr_ptr <= 8'd0;
                else
                    wr_ptr <= wr_ptr + 8'd1;
            end
            if (pop) begin
                completed_count <= completed_count + 8'd1;
                if (rd_ptr == DEPTH8 - 8'd1)
                    rd_ptr <= 8'd0;
                else
                    rd_ptr <= rd_ptr + 8'd1;
            end

            // Sticky witness of a countdown expiring before its response.
            if (|expiring)
                expired <= 1'b1;
        end
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : entry
            localparam [WORD_W-1:0] INDEX = g;
            assign slot_distance[g] = (INDEX >= rd_ptr)
                ? (INDEX - rd_ptr) : (DEPTH8 - rd_ptr + INDEX);
            assign expiring[g] = valid[g]
                && !(pop && (rd_ptr == INDEX))
                && (budget[g] <= 8'd1);

            initial begin
                samples[g] = 8'd0;
                budget[g] = 8'd0;
            end

            always @(posedge clk) begin
                if (i_ce) begin
                    if (valid[g] && !(pop && (rd_ptr == INDEX))
                            && (budget[g] != 8'd0))
                        budget[g] <= budget[g] - 8'd1;
                    if (pop && (rd_ptr == INDEX))
                        valid[g] <= 1'b0;
                    if (push && (wr_ptr == INDEX)) begin
                        valid[g] <= 1'b1;
                        samples[g] <= phase_sample;
                        budget[g] <= MAX_WAIT8;
                    end
                end
            end
        end
    endgenerate

    // After the first accepted comparison, an unchanged armed scope must
    // never see the deadline-expiration witness change.
    always @(posedge clk)
        if (past_valid && armed && $stable(armed))
            assert ($stable(expired));
endmodule

module trellis_acs_accel #(
    parameter WORD_W = 128,
    parameter STATES = 8,
    parameter TRACE_DEPTH = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_valid,
    output wire i_ready,
    input  wire [STATES*WORD_W-1:0] i_branch_a,
    input  wire [STATES*WORD_W-1:0] i_branch_b,
    output wire o_valid,
    input  wire o_ready,
    output wire [WORD_W-1:0] o_terminal_metric,
    output wire [WORD_W-1:0] o_terminal_runner_up,
    output wire [STATES-1:0] o_survivors,
    input  wire p_valid,
    output wire p_ready,
    input  wire [WORD_W-1:0] p_metric_a,
    input  wire [WORD_W-1:0] p_metric_b,
    output wire o_peer,
    input  wire [((TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1)-1:0] trace_read_addr,
    output wire [WORD_W-1:0] trace_read_word
);
    localparam TRACE_AW = (TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PEER_AW = $clog2(PEER_DEPTH), PEER_CW = $clog2(PEER_DEPTH + 1);
    localparam LANE_W = $clog2(CHANNELS);
    reg [WORD_W-1:0] peer_a [0:PEER_DEPTH-1], peer_b [0:PEER_DEPTH-1];
    reg [PEER_AW-1:0] peer_rd, peer_wr;
    reg [PEER_CW-1:0] peer_count;
    reg port_busy, port_pick;
    reg [LANE_W-1:0] port_lane;

    reg [WORD_W-1:0] path_metric [0:STATES-1];
    reg [WORD_W-1:0] runner_up   [0:STATES-1];
    reg [WORD_W-1:0] cand_a      [0:STATES-1];
    reg [WORD_W-1:0] cand_b      [0:STATES-1];
    reg [STATES-1:0] survivor;
    reg [WORD_W-1:0] traceback [0:TRACE_DEPTH-1];
    reg [TRACE_AW-1:0] trace_wr;
    reg pending;
    reg armed;

    function automatic [WORD_W-1:0] metric_add;
        input [WORD_W-1:0] a;
        input [WORD_W-1:0] b;
        reg [WORD_W:0] total;
        begin
            total = {1'b0, a} + {1'b0, b};
            metric_add = total[WORD_W] ? {WORD_W{1'b1}} : total[WORD_W-1:0];
        end
    endfunction

    wire [WORD_W-1:0] next_a [0:STATES-1];
    wire [WORD_W-1:0] next_b [0:STATES-1];

    genvar g;
    generate
        for (g = 0; g < STATES; g = g + 1) begin : trellis
            localparam PRED_A = (2*g) % STATES;
            localparam PRED_B = (2*g + 1) % STATES;
            assign next_a[g] = metric_add(
                path_metric[PRED_A], i_branch_a[g*WORD_W +: WORD_W]);
            assign next_b[g] = metric_add(
                path_metric[PRED_B], i_branch_b[g*WORD_W +: WORD_W]);
        end
    endgenerate

    assign i_ready = !pending;
    assign o_valid = port_busy;
    wire accept_branches = i_valid && i_ready;
    wire retire_survivors = o_valid && o_ready && !port_lane;
    assign p_ready = peer_count < PEER_DEPTH;
    assign o_peer = port_lane;
    wire peer_push = p_valid && p_ready;
    wire peer_pop = o_valid && o_ready && port_lane;
    wire [PEER_CW-1:0] peer_after = peer_count + PEER_CW'(peer_push) - PEER_CW'(peer_pop);
    wire [PEER_AW-1:0] peer_rd_after = peer_rd + PEER_AW'(peer_pop);
    wire primary_after = (pending || accept_branches) && !retire_survivors;
    wire [WORD_W-1:0] selected_a = port_lane ? peer_a[peer_rd] : cand_a[0];
    wire [WORD_W-1:0] selected_b = port_lane ? peer_b[peer_rd] : cand_b[0];

    assign o_terminal_metric = port_pick ? selected_b : selected_a;
    assign o_terminal_runner_up = port_pick ? selected_a : selected_b;
    assign o_survivors = port_lane ? {{(STATES-1){1'b0}}, port_pick} : survivor;
    assign trace_read_word = traceback[trace_read_addr];
    wire [WORD_W-1:0] survivor_word = {{(WORD_W-STATES){1'b0}}, survivor};

    initial begin
        pending = 1'b0;
        armed = 1'b0;
        survivor = {STATES{1'b0}};
        trace_wr = {TRACE_AW{1'b0}};
        for (integer s = 0; s < STATES; s = s + 1) begin
            path_metric[s] = {WORD_W{1'b0}};
            runner_up[s] = {WORD_W{1'b0}};
            cand_a[s] = {WORD_W{1'b0}};
            cand_b[s] = {WORD_W{1'b0}};
        end
        for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
            traceback[t] = {WORD_W{1'b0}};
        {peer_rd, peer_wr} = {(2*PEER_AW){1'b0}};
        peer_count = {PEER_CW{1'b0}};
        {port_busy, port_lane, port_pick} = {(LANE_W+2){1'b0}};
        for (integer q = 0; q < PEER_DEPTH; q = q + 1) begin
            peer_a[q] = {WORD_W{1'b0}};
            peer_b[q] = {WORD_W{1'b0}};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending <= 1'b0;
            armed <= 1'b0;
            survivor <= {STATES{1'b0}};
            trace_wr <= {TRACE_AW{1'b0}};
            for (integer s = 0; s < STATES; s = s + 1) begin
                path_metric[s] <= {WORD_W{1'b0}};
                runner_up[s] <= {WORD_W{1'b0}};
                cand_a[s] <= {WORD_W{1'b0}};
                cand_b[s] <= {WORD_W{1'b0}};
            end
            for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
                traceback[t] <= {WORD_W{1'b0}};
            {peer_rd, peer_wr} <= {(2*PEER_AW){1'b0}};
            peer_count <= {PEER_CW{1'b0}};
            {port_busy, port_lane, port_pick} <= {(LANE_W+2){1'b0}};
            for (integer q = 0; q < PEER_DEPTH; q = q + 1) begin
                peer_a[q] <= {WORD_W{1'b0}};
                peer_b[q] <= {WORD_W{1'b0}};
            end
        end else begin
            if (peer_push) begin
                peer_a[peer_wr] <= p_metric_a;
                peer_b[peer_wr] <= p_metric_b;
                peer_wr <= peer_wr + {{(PEER_AW-1){1'b0}}, 1'b1};
            end
            peer_rd <= peer_rd_after;
            peer_count <= peer_after;
            // Keep the reservation stable until the common output accepts it.
            if (!port_busy || o_ready) begin
                port_busy <= primary_after || (peer_after != 0);
                if (primary_after && ((peer_after == 0) || port_lane)) begin
                    port_lane <= {LANE_W{1'b0}};
                    port_pick <= accept_branches ? (next_b[0] < next_a[0]) : survivor[0];
                end else if (peer_after != 0) begin
                    port_lane <= LANE_W'(1);
                    port_pick <= (peer_count == PEER_CW'(peer_pop)) ?
                        (p_metric_b < p_metric_a) : (peer_b[peer_rd_after] < peer_a[peer_rd_after]);
                end
            end
            // Capture both path candidates and their comparison together.
            if (accept_branches) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    cand_a[s] <= next_a[s];
                    cand_b[s] <= next_b[s];
                    survivor[s] <= (next_b[s] < next_a[s]);
                end
                pending <= 1'b1;
            end

            // Back-pressure holds the candidate bank and output unchanged.
            // Retain the losing metric for decoder confidence estimation.
            if (retire_survivors) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    path_metric[s] <= survivor[s] ? cand_b[s] : cand_a[s];
                    runner_up[s] <= survivor[s] ? cand_a[s] : cand_b[s];
                end
                traceback[trace_wr] <= survivor_word;
                if (trace_wr == TRACE_AW'(TRACE_DEPTH - 1))
                    trace_wr <= {TRACE_AW{1'b0}};
                else
                    trace_wr <= trace_wr + {{(TRACE_AW-1){1'b0}}, 1'b1};
                pending <= 1'b0;
                // Q: the first completed trellis update.
                armed <= 1'b1;
            end
        end
    end

    // After Q, the committed terminal-state survivor never exceeds its runner-up.
    always @(posedge clk)
        assert (!armed || (path_metric[0] <= runner_up[0]));

    always @(posedge clk)
        assert (!(port_busy && o_ready) ||
                ((port_lane ? (peer_count != 0) : pending) &&
                 (o_terminal_metric <= o_terminal_runner_up)));
endmodule

module link_manchester_chain #(
    parameter [31:0] WORD_BITS = 32'd32
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 arm_cmd,
    input  wire [WORD_BITS-1:0]  word_in,
    input  wire                 scope_end,
    output reg                  tx_line,
    output reg                  start_pulse,
    output reg                  finish_pulse,
    input  wire                 peer_valid,
    input  wire [WORD_BITS-1:0]  peer_word,
    output wire                 arm_ready,
    output wire                 peer_ready,
    output reg                  peer_emit
);
    localparam [1:0] ST_IDLE    = 2'd0;
    localparam [1:0] ST_ARMED   = 2'd1;
    localparam [1:0] ST_STARTED = 2'd2;
    localparam [1:0] ST_DONE    = 2'd3;
    localparam [31:0] LAST_BIT  = WORD_BITS - 32'd1;

    reg [WORD_BITS-1:0] shift_data;
    reg [31:0] bit_index;
    reg half_phase;
    reg [1:0] stage;
    reg scope_open;
    reg pv;
    localparam CHANNELS = 2, DEPTH = 4, PTR_BITS = $clog2(DEPTH);
    localparam PEER_BITS = (WORD_BITS > 1) ? $clog2(WORD_BITS) : 1;
    reg [WORD_BITS-1:0] peer_q [0:DEPTH-1];
    reg [PTR_BITS-1:0] peer_rd, peer_wr;
    reg [$clog2(DEPTH+1)-1:0] peer_count;
    reg [PEER_BITS-1:0] peer_index;
    reg peer_half, peer_active;
    integer n;
    assign arm_ready = i_ce && !peer_active && ((stage == ST_IDLE) || (stage == ST_DONE));
    assign peer_ready = i_ce && (peer_count < DEPTH);
    wire peer_pop = i_ce && peer_active && peer_half && (peer_index == LAST_BIT);

    initial begin
        shift_data  = {WORD_BITS{1'b0}};
        bit_index   = 32'd0;
        half_phase  = 1'b0;
        stage       = ST_IDLE;
        scope_open  = 1'b1;
        pv          = 1'b0;
        tx_line     = 1'b0;
        start_pulse = 1'b0;
        finish_pulse = 1'b0;
        peer_rd = 0;
        peer_wr = 0;
        peer_count = 0;
        peer_index = 0;
        peer_half = 1'b0;
        peer_active = 1'b0;
        peer_emit = 1'b0;
        for (n = 0; n < DEPTH; n = n + 1) peer_q[n] = {WORD_BITS{1'b0}};
    end

    // Each enabled clock emits one Manchester half-bit. All state,
    // including the registered event strobes, holds during a stall.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (scope_end)
                scope_open <= 1'b0;

            start_pulse  <= 1'b0;
            finish_pulse <= 1'b0;
            peer_emit <= peer_active;
            peer_count <= peer_count + (peer_valid && peer_ready) - peer_pop;
            if (peer_valid && peer_ready) begin
                peer_q[peer_wr] <= peer_word;
                peer_wr <= peer_wr + 1'b1;
            end
            if (peer_pop) peer_rd <= peer_rd + 1'b1;
            if (peer_active) begin
                tx_line <= peer_q[peer_rd][0] ^ peer_half;
                peer_half <= !peer_half;
                if (peer_half) begin
                    peer_q[peer_rd] <= peer_q[peer_rd] >> 32'd1;
                    peer_index <= peer_pop ? 0 : peer_index + 1'b1;
                end
                if (peer_pop) peer_active <= 1'b0;
            end else if (!arm_cmd && peer_count != 0 &&
                         ((stage == ST_IDLE) || (stage == ST_DONE)))
                peer_active <= 1'b1;

            if (!peer_active) case (stage)
                ST_IDLE, ST_DONE: begin
                    if (arm_cmd) begin
                        shift_data <= word_in;
                        bit_index  <= 32'd0;
                        half_phase <= 1'b0;
                        stage      <= ST_ARMED;
                    end
                end

                ST_ARMED, ST_STARTED: begin
                    if (!half_phase) begin
                        tx_line    <= shift_data[0];
                        half_phase <= 1'b1;
                        if (bit_index == 32'd0) begin
                            start_pulse <= 1'b1;
                            stage       <= ST_STARTED;
                        end
                    end else begin
                        tx_line    <= ~shift_data[0];
                        shift_data <= shift_data >> 32'd1;
                        half_phase <= 1'b0;
                        if (bit_index == LAST_BIT) begin
                            bit_index    <= 32'd0;
                            finish_pulse <= 1'b1;
                            stage        <= ST_DONE;
                        end else begin
                            bit_index <= bit_index + 32'd1;
                        end
                    end
                end
            endcase
        end
    end

    // Check the events produced by the previous enabled clock:
    // starting requires an earlier arm; finishing requires an earlier start.
    // scope_open permanently closes on the first enabled scope_end event.
    always @(posedge clk) begin
        if (pv && scope_open && $past(i_ce))
            assert ((!start_pulse || ($past(stage) == ST_ARMED)) &&
                    (!finish_pulse || ($past(stage) == ST_STARTED)));
    end
    always @(posedge clk) begin
        if (pv && $past(i_ce) && $past((stage == ST_ARMED) || (stage == ST_STARTED)))
            assert (!peer_emit);
    end
endmodule

module loop_trip_predictor #(
    parameter integer ENTRIES = 32,
    parameter integer WORD_W = 64,
    parameter integer INDEX_W = (ENTRIES > 1) ? $clog2(ENTRIES) : 1,
    parameter integer PRED_DEPTH = 4
) (
    input  wire clk,
    input  wire i_branch_valid,
    output wire o_branch_ready,
    input  wire [INDEX_W-1:0] i_index,
    input  wire [WORD_W-1:0] i_branch_tag,
    input  wire i_backedge_taken,
    input  wire i_monitor_begin,
    input  wire i_monitor_end,

    output reg  o_pred_valid,
    input  wire i_pred_ready,
    output reg  [WORD_W-1:0] o_pred_tag,
    output reg  o_pred_confident,
    output reg  o_pred_exit,
    output reg  [WORD_W-1:0] resident_count,
    output reg  [WORD_W-1:0] o_pred_residents,
    output wire [$clog2(PRED_DEPTH):0] o_pred_queued
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] WORD_MAX = {WORD_W{1'b1}};
    localparam [WORD_W-1:0] CONF_THRESHOLD = 64'd3;
    localparam [WORD_W-1:0] TABLE_CAPACITY = ENTRIES;

    localparam integer PRED_ADDR_W = (PRED_DEPTH > 1) ? $clog2(PRED_DEPTH) : 1;
    localparam integer PRED_PTR_W = PRED_ADDR_W + 1;
    localparam [PRED_ADDR_W-1:0] PRED_LAST = PRED_DEPTH - 1;
    localparam [PRED_PTR_W-1:0] PRED_CAPACITY = PRED_DEPTH;

    reg [ENTRIES-1:0] entry_valid;
    reg [WORD_W-1:0] entry_tag [0:ENTRIES-1];
    reg [WORD_W-1:0] learned_trip [0:ENTRIES-1];
    reg [WORD_W-1:0] current_iter [0:ENTRIES-1];
    reg [WORD_W-1:0] confidence [0:ENTRIES-1];
    reg monitor_window;

    // Queue the history needed to finish predictions independently of training.
    reg [PRED_PTR_W-1:0] pred_read_ptr;
    reg [PRED_PTR_W-1:0] pred_write_ptr;
    reg [WORD_W-1:0] pred_tag_mem [0:PRED_DEPTH-1];
    reg [WORD_W-1:0] pred_iter_mem [0:PRED_DEPTH-1];
    reg [WORD_W-1:0] pred_trip_mem [0:PRED_DEPTH-1];
    reg [WORD_W-1:0] pred_resident_mem [0:PRED_DEPTH-1];
    reg pred_confident_mem [0:PRED_DEPTH-1];
    wire [PRED_ADDR_W-1:0] pred_read_addr =
        pred_read_ptr[PRED_ADDR_W-1:0];
    wire [PRED_ADDR_W-1:0] pred_write_addr =
        pred_write_ptr[PRED_ADDR_W-1:0];
    wire pred_empty = (pred_read_ptr == pred_write_ptr);
    wire pred_full = (pred_read_addr == pred_write_addr)
                  && (pred_read_ptr[PRED_ADDR_W] != pred_write_ptr[PRED_ADDR_W]);
    wire pred_output_ready = !o_pred_valid || i_pred_ready;
    wire pred_dequeue = !pred_empty && pred_output_ready;
    wire pred_queue_ready = !pred_full || pred_dequeue;
    wire [PRED_PTR_W-1:0] pred_occupancy =
        (pred_read_ptr[PRED_ADDR_W] == pred_write_ptr[PRED_ADDR_W])
        ? ({1'b0, pred_write_addr} - {1'b0, pred_read_addr})
        : (PRED_CAPACITY - {1'b0, pred_read_addr}
                         + {1'b0, pred_write_addr});
    assign o_pred_queued = pred_occupancy;

    // An empty queue bypasses directly into the available output stage.
    assign o_branch_ready = pred_queue_ready
                          && (i_index < ENTRIES);
    wire accept_branch = i_branch_valid && o_branch_ready;
    wire pred_bypass = accept_branch && pred_empty
                     && pred_output_ready;
    wire pred_enqueue = accept_branch && !pred_bypass;
    wire lookup_hit = entry_valid[i_index]
                   && (entry_tag[i_index] == i_branch_tag);
    wire prediction_known = lookup_hit
                          && (confidence[i_index] >= CONF_THRESHOLD)
                          && (learned_trip[i_index] != ZERO);
    wire [WORD_W-1:0] observed_trip =
        (current_iter[i_index] == WORD_MAX)
        ? WORD_MAX : current_iter[i_index] + ONE;

    wire prediction_exit = prediction_known
                         && (current_iter[i_index]
                             == learned_trip[i_index] - ONE);

    // Combinational population of the resident-entry bitmap.
    wire [WORD_W-1:0] tally_chain [0:ENTRIES];
    wire [WORD_W-1:0] resident_tally;
    assign tally_chain[0] = ZERO;
    genvar g;
    generate
        for (g = 0; g < ENTRIES; g = g + 1) begin : make_tally
            assign tally_chain[g+1] = tally_chain[g]
                + {{(WORD_W-1){1'b0}}, entry_valid[g]};
        end
    endgenerate
    assign resident_tally = tally_chain[ENTRIES];

    integer init_i;
    initial begin
        entry_valid = {ENTRIES{1'b0}};
        resident_count = ZERO;
        monitor_window = 1'b0;
        o_pred_valid = 1'b0;
        o_pred_tag = ZERO;
        o_pred_confident = 1'b0;
        o_pred_exit = 1'b0;
        o_pred_residents = ZERO;
        pred_read_ptr = {PRED_PTR_W{1'b0}};
        pred_write_ptr = {PRED_PTR_W{1'b0}};
        for (init_i = 0; init_i < ENTRIES; init_i = init_i + 1) begin
            entry_tag[init_i] = ZERO;
            learned_trip[init_i] = ZERO;
            current_iter[init_i] = ZERO;
            confidence[init_i] = ZERO;
        end
        for (init_i = 0; init_i < PRED_DEPTH; init_i = init_i + 1) begin
            pred_tag_mem[init_i] = ZERO;
            pred_iter_mem[init_i] = ZERO;
            pred_trip_mem[init_i] = ZERO;
            pred_resident_mem[init_i] = ZERO;
            pred_confident_mem[init_i] = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (o_pred_valid && i_pred_ready)
            o_pred_valid <= 1'b0;

        // Older queued predictions always precede a newly accepted branch.
        if (pred_dequeue) begin
            o_pred_valid <= 1'b1;
            o_pred_tag <= pred_tag_mem[pred_read_addr];
            o_pred_confident <= pred_confident_mem[pred_read_addr];
            o_pred_exit <= pred_confident_mem[pred_read_addr]
                        && (pred_iter_mem[pred_read_addr]
                            == pred_trip_mem[pred_read_addr] - ONE);
            o_pred_residents <= pred_resident_mem[pred_read_addr];
        end else if (pred_bypass) begin
            o_pred_valid <= 1'b1;
            o_pred_tag <= i_branch_tag;
            o_pred_confident <= prediction_known;
            o_pred_exit <= prediction_exit;
            o_pred_residents <= resident_count;
        end

        if (pred_dequeue) begin
            if (pred_read_addr == PRED_LAST)
                pred_read_ptr <= {~pred_read_ptr[PRED_ADDR_W],
                                  {PRED_ADDR_W{1'b0}}};
            else
                pred_read_ptr <= pred_read_ptr + 1'b1;
        end

        if (pred_enqueue) begin
            pred_tag_mem[pred_write_addr] <= i_branch_tag;
            pred_confident_mem[pred_write_addr] <= prediction_known;
            pred_iter_mem[pred_write_addr] <= current_iter[i_index];
            pred_trip_mem[pred_write_addr] <= learned_trip[i_index];
            pred_resident_mem[pred_write_addr] <= resident_count;
            if (pred_write_addr == PRED_LAST)
                pred_write_ptr <= {~pred_write_ptr[PRED_ADDR_W],
                                   {PRED_ADDR_W{1'b0}}};
            else
                pred_write_ptr <= pred_write_ptr + 1'b1;
        end

        if (accept_branch) begin
            // Training advances only after the prediction has a destination.

            // Q opens the monitoring interval; R closes it.
            if (i_monitor_end)
                monitor_window <= 1'b0;
            else if (i_monitor_begin)
                monitor_window <= 1'b1;

            if (!lookup_hit) begin
                // A tag collision replaces a resident entry, not its occupancy.
                if (!entry_valid[i_index])
                    resident_count <= resident_count + ONE;
                entry_valid[i_index] <= 1'b1;
                entry_tag[i_index] <= i_branch_tag;
                confidence[i_index] <= ZERO;
                if (i_backedge_taken) begin
                    current_iter[i_index] <= ONE;
                    learned_trip[i_index] <= ZERO;
                end else begin
                    current_iter[i_index] <= ZERO;
                    learned_trip[i_index] <= ONE;
                end
            end else if (i_backedge_taken) begin
                current_iter[i_index] <= observed_trip;
            end else begin
                // An exiting branch completes one measured loop execution.
                current_iter[i_index] <= ZERO;
                learned_trip[i_index] <= observed_trip;
                if ((learned_trip[i_index] == observed_trip)
                    && (learned_trip[i_index] != ZERO)) begin
                    if (confidence[i_index] != WORD_MAX)
                        confidence[i_index] <= confidence[i_index] + ONE;
                end else begin
                    confidence[i_index] <= ZERO;
                end
            end
        end
    end

    // Each prediction reports the table occupancy when it was constructed.
    always @(posedge clk) begin
        if (o_pred_valid)
            assert (o_pred_residents <= TABLE_CAPACITY);
    end

    assert property (!monitor_window
                     || (resident_count <= TABLE_CAPACITY));
endmodule

module wave_line_prefetcher #(
    parameter integer LINE_W = 8,
    parameter integer DEPTH = 64,
    parameter integer COUNT_W = 8
) (
    input  wire                  clk,
    input  wire                  miss_valid,
    output wire                  miss_ready,
    input  wire [LINE_W-1:0]     miss_line,
    output wire                  prefetch_valid,
    input  wire                  prefetch_ready,
    output wire [LINE_W-1:0]     prefetch_line,
    output reg  [3:0]            stats_status
);
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [LINE_W-1:0] LINE_ZERO = {LINE_W{1'b0}};
    localparam [LINE_W-1:0] LINE_ONE = {{(LINE_W-1){1'b0}}, 1'b1};

    reg [LINE_W-1:0] prefetch_q [0:DEPTH-1];
    reg [COUNT_W-1:0] wr_ptr;
    reg [COUNT_W-1:0] rd_ptr;
    reg [COUNT_W-1:0] used;
    reg [LINE_W-1:0] last_miss;
    reg pv;

    initial begin
        wr_ptr = COUNT_ZERO;
        rd_ptr = COUNT_ZERO;
        used = COUNT_ZERO;
        last_miss = {LINE_W{1'b1}};
        pv = 1'b0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : initialize_queue
            initial prefetch_q[g] = LINE_ZERO;
        end
    endgenerate

    assign miss_ready = (used < CAPACITY);
    assign prefetch_valid = (used != COUNT_ZERO);
    assign prefetch_line = prefetch_q[rd_ptr];

    wire push = miss_valid && miss_ready;
    wire pop = prefetch_valid && prefetch_ready;

    reg [6:0] stats_phase;
    reg [7:0] stats_accepted;
    reg [7:0] stats_miss_stalls;
    reg [7:0] stats_prefetch_stalls;
    initial begin
        stats_phase = 7'd0;
        stats_accepted = 8'd0;
        stats_miss_stalls = 8'd0;
        stats_prefetch_stalls = 8'd0;
        stats_status = 4'b0000;
    end
    always @(posedge clk) begin
        stats_phase <= stats_phase + 7'd1;
        if (stats_phase == 7'd127) begin
            stats_status[0] <= (stats_accepted == 8'd0) && !push;
            stats_status[1] <= (stats_accepted + {7'd0, push}) >= 8'd64;
            stats_status[2] <= (stats_miss_stalls + {7'd0, (miss_valid && !miss_ready)}) >= 8'd32;
            stats_status[3] <= (stats_prefetch_stalls + {7'd0, (prefetch_valid && !prefetch_ready)}) >= 8'd32;
            stats_accepted <= 8'd0;
            stats_miss_stalls <= 8'd0;
            stats_prefetch_stalls <= 8'd0;
        end else begin
            if (push)
                stats_accepted <= stats_accepted + 8'd1;
            if (miss_valid && !miss_ready)
                stats_miss_stalls <= stats_miss_stalls + 8'd1;
            if (prefetch_valid && !prefetch_ready)
                stats_prefetch_stalls <= stats_prefetch_stalls + 8'd1;
        end
    end

    // The slot immediately preceding the write pointer retains the
    // most recently generated next-line request, even after retirement.
    wire [COUNT_W-1:0] latest_slot =
        (wr_ptr == COUNT_ZERO) ? LAST_SLOT : (wr_ptr - COUNT_ONE);
    wire [LINE_W-1:0] latest_line = prefetch_q[latest_slot];

    always @(posedge clk) begin
        if (push) begin
            prefetch_q[wr_ptr] <= miss_line + LINE_ONE;
            last_miss <= miss_line;
            wr_ptr <= (wr_ptr == LAST_SLOT) ? COUNT_ZERO : (wr_ptr + COUNT_ONE);
        end
        if (pop)
            rd_ptr <= (rd_ptr == LAST_SLOT) ? COUNT_ZERO : (rd_ptr + COUNT_ONE);

        if (push && !pop)
            used <= used + COUNT_ONE;
        else if (pop && !push)
            used <= used - COUNT_ONE;

        // No history check is needed before the first transaction.
        // Keeping this update transaction-gated preserves complete idle.
        if (push || pop)
            pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $stable(last_miss))
            assert ($stable(latest_line));
endmodule

module pixel_dot_batch #(
    parameter integer DEPTH = 4, WORD_W = 64,
    parameter integer COUNT_W = $clog2(DEPTH+1)
) (
    input wire clk, ce, in_valid, in_last,
    input wire [WORD_W-1:0] in_sum,
    output wire in_ready,
    output reg out_valid,
    output reg [COUNT_W-1:0] count,
    output reg [WORD_W-1:0] out_sum,
    output reg [(DEPTH*WORD_W)-1:0] entry_state
);
    reg [WORD_W-1:0] entries [0:DEPTH-1];
    integer init_slot, scan_slot;
    initial begin
        count = {COUNT_W{1'b0}};
        out_valid = 1'b0;
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1)
            entries[init_slot] = {WORD_W{1'b0}};
    end
    assign in_ready = !out_valid && (count < DEPTH);
    always @(*) begin
        out_sum = {WORD_W{1'b0}};
        for (scan_slot = 0; scan_slot < DEPTH; scan_slot = scan_slot + 1) begin
            entry_state[scan_slot*WORD_W +: WORD_W] = entries[scan_slot];
            if (scan_slot < count) out_sum = out_sum + entries[scan_slot];
        end
    end
    always @(posedge clk) begin
        if (ce) begin
            if (out_valid) begin
                count <= {COUNT_W{1'b0}};
                out_valid <= 1'b0;
            end else if (in_valid && in_ready) begin
                entries[count] <= in_sum;
                count <= count + 1'b1;
                out_valid <= in_last || (count == DEPTH-1);
            end
        end
    end
endmodule

module pixel_dot_accumulator #(
    parameter integer LANES = 16,
    parameter integer WORD_W = 64,
    parameter integer BATCH_DEPTH = 4
) (
    input wire clk,
    input wire ce,
    input wire end_frame,
    input wire [(LANES*WORD_W)-1:0] shade_operands,
    input wire [(LANES*WORD_W)-1:0] texture_operands,
    output wire input_ready,
output wire [WORD_W-1:0] accumulated_value,
output wire [287:0] diagnostic_status
);
    // Products and additions use fixed-width modular arithmetic.
    reg [WORD_W-1:0] products [0:LANES-1];
    wire [WORD_W-1:0] incoming_product [0:LANES-1];
    wire [WORD_W-1:0] adder_tree [1:(2*LANES)-1];
    wire [LANES-1:0] incoming_nonzero;
    wire [LANES-1:0] staged_nonzero;
    wire pending_nonzero;

    reg [WORD_W-1:0] running_sum;
    reg seen_nonzero_issue;
    reg before_end;
    reg past_valid;
    localparam integer BATCH_COUNT_W = $clog2(BATCH_DEPTH+1);
    wire batch_ready, batch_valid;
    wire [BATCH_COUNT_W-1:0] batch_count;
    wire [WORD_W-1:0] batch_sum;
    wire [(BATCH_DEPTH*WORD_W)-1:0] batch_entries;
    reg staged_last;
reg [31:0] diag_enabled_cycles;
reg [31:0] diag_paused_cycles;
reg [31:0] diag_accepted_issues;
reg [31:0] diag_nonzero_issues;
reg [31:0] diag_frame_ends;
reg [31:0] diag_retired_batches;
reg [31:0] diag_blocked_cycles;
reg [31:0] diag_stall_run;
reg [31:0] diag_stall_peak;

initial begin
    diag_enabled_cycles = 32'd0;
    diag_paused_cycles = 32'd0;
    diag_accepted_issues = 32'd0;
    diag_nonzero_issues = 32'd0;
    diag_frame_ends = 32'd0;
    diag_retired_batches = 32'd0;
    diag_blocked_cycles = 32'd0;
    diag_stall_run = 32'd0;
    diag_stall_peak = 32'd0;
end

assign diagnostic_status = {
    diag_enabled_cycles, diag_paused_cycles,
    diag_accepted_issues, diag_nonzero_issues,
    diag_frame_ends, diag_retired_batches,
    diag_blocked_cycles, diag_stall_run,
    diag_stall_peak
};

always @(posedge clk) begin
    if (ce) begin
        if (diag_enabled_cycles != 32'hffffffff)
            diag_enabled_cycles <= diag_enabled_cycles + 32'd1;
        if (input_ready) begin
            if (diag_accepted_issues != 32'hffffffff)
                diag_accepted_issues <= diag_accepted_issues + 32'd1;
            if (end_frame && (diag_frame_ends != 32'hffffffff))
                diag_frame_ends <= diag_frame_ends + 32'd1;
            if ((|incoming_nonzero) && (diag_nonzero_issues != 32'hffffffff))
                diag_nonzero_issues <= diag_nonzero_issues + 32'd1;
            diag_stall_run <= 32'd0;
        end else begin
            if (diag_blocked_cycles != 32'hffffffff)
                diag_blocked_cycles <= diag_blocked_cycles + 32'd1;
            if (diag_stall_run != 32'hffffffff) begin
                diag_stall_run <= diag_stall_run + 32'd1;
                if (diag_stall_run >= diag_stall_peak)
                    diag_stall_peak <= diag_stall_run + 32'd1;
            end
        end
        if (batch_valid && (diag_retired_batches != 32'hffffffff))
            diag_retired_batches <= diag_retired_batches + 32'd1;
    end else begin
        if (diag_paused_cycles != 32'hffffffff)
            diag_paused_cycles <= diag_paused_cycles + 32'd1;
    end
end

    assign input_ready = !past_valid || batch_ready;
    pixel_dot_batch #(.DEPTH(BATCH_DEPTH), .WORD_W(WORD_W)) batcher (
        .clk(clk), .ce(ce), .in_valid(past_valid), .in_last(staged_last),
        .in_sum(adder_tree[1]), .in_ready(batch_ready), .out_valid(batch_valid),
        .count(batch_count), .out_sum(batch_sum), .entry_state(batch_entries)
    );

    initial begin
        running_sum = {WORD_W{1'b0}};
        seen_nonzero_issue = 1'b0;
        before_end = 1'b1;
        past_valid = 1'b0;
        staged_last = 1'b0;
    end

    genvar lane;
    generate
        for (lane = 0; lane < LANES; lane = lane + 1) begin : lanes
            assign incoming_product[lane] =
                shade_operands[lane*WORD_W +: WORD_W] *
                texture_operands[lane*WORD_W +: WORD_W];
            assign incoming_nonzero[lane] =
                incoming_product[lane] != {WORD_W{1'b0}};
            assign staged_nonzero[lane] =
                products[lane] != {WORD_W{1'b0}};
            assign adder_tree[LANES+lane] = products[lane];

            initial products[lane] = {WORD_W{1'b0}};
            always @(posedge clk) begin
                if (ce && input_ready)
                    products[lane] <= incoming_product[lane];
            end
        end
    endgenerate

    genvar node;
    generate
        for (node = 1; node < LANES; node = node + 1) begin : reduction_tree
            assign adder_tree[node] =
                adder_tree[2*node] + adder_tree[2*node+1];
        end
    endgenerate

    assign pending_nonzero = |staged_nonzero;
    assign accumulated_value = running_sum;

    always @(posedge clk) begin
        if (ce && batch_valid)
            running_sum <= running_sum + batch_sum;
        if (ce && input_ready) begin
            // History of a nonzero product entering the preceding stage.
            seen_nonzero_issue <= seen_nonzero_issue || (|incoming_nonzero);
            past_valid <= 1'b1;
            staged_last <= end_frame;
            if (end_frame)
                before_end <= 1'b0;
        end
    end

    // Before the first frame-end event, a rising nonzero accumulated value
    // must be preceded by an issued nonzero product.
    always @(posedge clk) begin
        if (past_valid && before_end &&
            $rose(running_sum != {WORD_W{1'b0}}))
            assert (seen_nonzero_issue);
    end
endmodule

module pixel_dot_accumulator #(
    parameter integer LANES = 16,
parameter integer WORD_W = 64,
parameter integer CONTEXTS = 4
) (
    input wire clk,
    input wire ce,
    input wire end_frame,
    input wire [(LANES*WORD_W)-1:0] shade_operands,
    input wire [(LANES*WORD_W)-1:0] texture_operands,
output wire [WORD_W-1:0] accumulated_value,
output wire issue_ready,
output wire context_result_valid,
output wire [$clog2(CONTEXTS)-1:0] context_result_index
);
    // Products and additions use fixed-width modular arithmetic.
    reg [WORD_W-1:0] products [0:LANES-1];
    wire [WORD_W-1:0] incoming_product [0:LANES-1];
    wire [WORD_W-1:0] adder_tree [1:(2*LANES)-1];
    wire [LANES-1:0] incoming_nonzero;
    wire [LANES-1:0] staged_nonzero;
    wire pending_nonzero;

    reg [WORD_W-1:0] running_sum;
    reg seen_nonzero_issue;
    reg before_end;
    reg past_valid;

localparam integer CONTEXT_W = $clog2(CONTEXTS);
localparam [1:0] CTX_IDLE = 2'd0;
localparam [1:0] CTX_READ = 2'd1;
localparam [1:0] CTX_WRITE = 2'd2;
reg [WORD_W-1:0] context_sums [0:CONTEXTS-1];
reg [CONTEXT_W-1:0] context_index;
reg [1:0] context_phase;
reg context_done;
wire issue_accept;
wire context_write;
wire [WORD_W-1:0] context_next_sum;
integer context_slot;

    initial begin
        running_sum = {WORD_W{1'b0}};
        seen_nonzero_issue = 1'b0;
        before_end = 1'b1;
        past_valid = 1'b0;
context_index = CONTEXTS - 1;
context_phase = CTX_IDLE;
context_done = 1'b0;
for (context_slot = 0; context_slot < CONTEXTS; context_slot = context_slot + 1) begin
    context_sums[context_slot] = {WORD_W{1'b0}};
end
    end

    genvar lane;
    generate
        for (lane = 0; lane < LANES; lane = lane + 1) begin : lanes
            assign incoming_product[lane] =
                shade_operands[lane*WORD_W +: WORD_W] *
                texture_operands[lane*WORD_W +: WORD_W];
            assign incoming_nonzero[lane] =
                incoming_product[lane] != {WORD_W{1'b0}};
            assign staged_nonzero[lane] =
                products[lane] != {WORD_W{1'b0}};
            assign adder_tree[LANES+lane] = products[lane];

            initial products[lane] = {WORD_W{1'b0}};
            always @(posedge clk) begin
if (issue_accept)
                    products[lane] <= incoming_product[lane];
            end
        end
    endgenerate

    genvar node;
    generate
        for (node = 1; node < LANES; node = node + 1) begin : reduction_tree
            assign adder_tree[node] =
                adder_tree[2*node] + adder_tree[2*node+1];
        end
    endgenerate

    assign pending_nonzero = |staged_nonzero;
    assign accumulated_value = running_sum;
assign issue_ready = context_phase == CTX_IDLE;
assign context_result_valid = context_done;
assign context_result_index = context_index;
assign issue_accept = ce && issue_ready;
assign context_write = ce && (context_phase == CTX_WRITE);
assign context_next_sum = running_sum + adder_tree[1];

always @(posedge clk) begin
    if (context_write)
        context_sums[context_index] <= context_next_sum;
end

always @(posedge clk) begin
    context_done <= 1'b0;
    if (ce) begin
        case (context_phase)
            CTX_IDLE: begin
                if (context_index == CONTEXTS - 1)
                    context_index <= {CONTEXT_W{1'b0}};
                else
                    context_index <= context_index + 1'b1;
                context_phase <= CTX_READ;
            end
            CTX_READ: begin
                running_sum <= context_sums[context_index];
                context_phase <= CTX_WRITE;
            end
            CTX_WRITE: begin
                running_sum <= context_next_sum;
                context_done <= 1'b1;
                context_phase <= CTX_IDLE;
            end
            default: context_phase <= CTX_IDLE;
        endcase
    end
end

    always @(posedge clk) begin
if (issue_accept) begin
            // History of a nonzero product entering the preceding stage.
            seen_nonzero_issue <= seen_nonzero_issue || (|incoming_nonzero);
            past_valid <= 1'b1;
            if (end_frame)
                before_end <= 1'b0;
        end
    end

    // Before the first frame-end event, a rising nonzero accumulated value
    // must be preceded by an issued nonzero product.
    always @(posedge clk) begin
        if (past_valid && before_end &&
            $rose(running_sum != {WORD_W{1'b0}}))
            assert (seen_nonzero_issue);
    end
endmodule

module wave_line_prefetcher #(
    parameter integer LINE_W = 8,
    parameter integer DEPTH = 64,
    parameter integer COUNT_W = 8
) (
    input  wire                  clk,
    input  wire                  miss_valid,
    output wire                  miss_ready,
    input  wire [LINE_W-1:0]     miss_line,
    output wire                  prefetch_valid,
    input  wire                  prefetch_ready,
output wire [LINE_W-1:0]     prefetch_line,
input  wire                  peer_miss_valid,
output wire                  peer_miss_ready,
input  wire [LINE_W-1:0]     peer_miss_line,
output wire                  prefetch_peer,
output reg [3:0]             telemetry_nibble
);
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [LINE_W-1:0] LINE_ZERO = {LINE_W{1'b0}};
    localparam [LINE_W-1:0] LINE_ONE = {{(LINE_W-1){1'b0}}, 1'b1};
localparam integer CHANNELS = 2, PEER_DEPTH = 4;
localparam integer PEER_PTR_W = $clog2(PEER_DEPTH), PEER_COUNT_W = $clog2(PEER_DEPTH+1);

    reg [LINE_W-1:0] prefetch_q [0:DEPTH-1];
    reg [COUNT_W-1:0] wr_ptr;
    reg [COUNT_W-1:0] rd_ptr;
    reg [COUNT_W-1:0] used;
    reg [LINE_W-1:0] last_miss;
    reg pv;
reg [LINE_W-1:0] peer_q [0:PEER_DEPTH-1];
reg [PEER_PTR_W-1:0] peer_wr, peer_rd;
reg [PEER_COUNT_W-1:0] peer_used;
reg output_locked;
reg [$clog2(CHANNELS)-1:0] output_owner, output_turn;

    initial begin
        wr_ptr = COUNT_ZERO;
        rd_ptr = COUNT_ZERO;
        used = COUNT_ZERO;
        last_miss = {LINE_W{1'b1}};
        pv = 1'b0;
peer_wr = 0; peer_rd = 0; peer_used = 0;
output_locked = 1'b0; output_owner = 1'b0; output_turn = 1'b0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : initialize_queue
            initial prefetch_q[g] = LINE_ZERO;
        end
for (g = 0; g < PEER_DEPTH; g = g + 1) begin : initialize_peer
    initial peer_q[g] = LINE_ZERO;
end
    endgenerate

    assign miss_ready = (used < CAPACITY);
assign peer_miss_ready = (peer_used < PEER_DEPTH);
assign prefetch_peer = output_locked ? output_owner :
    ((peer_used != 0) && ((used == COUNT_ZERO) || output_turn));
assign prefetch_valid = prefetch_peer ? (peer_used != 0) : (used != COUNT_ZERO);
assign prefetch_line = prefetch_peer ? peer_q[peer_rd] : prefetch_q[rd_ptr];

    wire push = miss_valid && miss_ready;
wire pop = prefetch_valid && prefetch_ready && !prefetch_peer;
wire peer_push = peer_miss_valid && peer_miss_ready;
wire peer_pop = prefetch_valid && prefetch_ready && prefetch_peer;

    // The slot immediately preceding the write pointer retains the
    // most recently generated next-line request, even after retirement.
    wire [COUNT_W-1:0] latest_slot =
        (wr_ptr == COUNT_ZERO) ? LAST_SLOT : (wr_ptr - COUNT_ONE);
    wire [LINE_W-1:0] latest_line = prefetch_q[latest_slot];
    reg [15:0] stats_local_requests;
    reg [15:0] stats_peer_requests;
    reg [15:0] stats_retired;
    reg [7:0] stats_stall_run;
    reg [7:0] stats_stall_peak;
    reg [3:0] stats_page;
    initial begin
        stats_local_requests = 16'd0;
        stats_peer_requests = 16'd0;
        stats_retired = 16'd0;
        stats_stall_run = 8'd0;
        stats_stall_peak = 8'd0;
        stats_page = 4'd0;
        telemetry_nibble = 4'd0;
    end
    always @(posedge clk) begin
        stats_page <= stats_page + 4'd1;
        if (push && (stats_local_requests != 16'hffff))
            stats_local_requests <= stats_local_requests + 16'd1;
        if (peer_push && (stats_peer_requests != 16'hffff))
            stats_peer_requests <= stats_peer_requests + 16'd1;
        if ((pop || peer_pop) && (stats_retired != 16'hffff))
            stats_retired <= stats_retired + 16'd1;
        if (prefetch_valid && !prefetch_ready) begin
            if (stats_stall_run != 8'hff)
                stats_stall_run <= stats_stall_run + 8'd1;
            if ((stats_stall_run >= stats_stall_peak) && (stats_stall_run != 8'hff))
                stats_stall_peak <= stats_stall_run + 8'd1;
        end else begin
            stats_stall_run <= 8'd0;
        end
        case (stats_page)
            4'h0: telemetry_nibble <= stats_local_requests[3:0];
            4'h1: telemetry_nibble <= stats_local_requests[7:4];
            4'h2: telemetry_nibble <= stats_local_requests[11:8];
            4'h3: telemetry_nibble <= stats_local_requests[15:12];
            4'h4: telemetry_nibble <= stats_peer_requests[3:0];
            4'h5: telemetry_nibble <= stats_peer_requests[7:4];
            4'h6: telemetry_nibble <= stats_peer_requests[11:8];
            4'h7: telemetry_nibble <= stats_peer_requests[15:12];
            4'h8: telemetry_nibble <= stats_retired[3:0];
            4'h9: telemetry_nibble <= stats_retired[7:4];
            4'ha: telemetry_nibble <= stats_retired[11:8];
            4'hb: telemetry_nibble <= stats_retired[15:12];
            4'hc: telemetry_nibble <= stats_stall_run[3:0];
            4'hd: telemetry_nibble <= stats_stall_run[7:4];
            4'he: telemetry_nibble <= stats_stall_peak[3:0];
            4'hf: telemetry_nibble <= stats_stall_peak[7:4];
        endcase
    end

    always @(posedge clk) begin
        if (push) begin
            prefetch_q[wr_ptr] <= miss_line + LINE_ONE;
            last_miss <= miss_line;
            wr_ptr <= (wr_ptr == LAST_SLOT) ? COUNT_ZERO : (wr_ptr + COUNT_ONE);
        end
        if (pop)
            rd_ptr <= (rd_ptr == LAST_SLOT) ? COUNT_ZERO : (rd_ptr + COUNT_ONE);

        if (push && !pop)
            used <= used + COUNT_ONE;
        else if (pop && !push)
            used <= used - COUNT_ONE;

        // No history check is needed before the first transaction.
        // Keeping this update transaction-gated preserves complete idle.
        if (push || pop)
            pv <= 1'b1;
    end

always @(posedge clk) begin
    if (peer_push) begin
        peer_q[peer_wr] <= peer_miss_line + LINE_ONE;
        peer_wr <= (peer_wr == PEER_DEPTH-1) ? 0 : peer_wr + 1'b1;
    end
    if (peer_pop) peer_rd <= (peer_rd == PEER_DEPTH-1) ? 0 : peer_rd + 1'b1;
    if (peer_push && !peer_pop) peer_used <= peer_used + 1'b1;
    else if (peer_pop && !peer_push) peer_used <= peer_used - 1'b1;
    if (prefetch_valid) begin
        output_locked <= !prefetch_ready;
        output_owner <= prefetch_peer;
        if (prefetch_ready) output_turn <= !prefetch_peer;
    end
end

    always @(posedge clk)
        if (pv && $stable(last_miss))
            assert ($stable(latest_line));

always @(posedge clk)
    if (output_locked && prefetch_ready)
        assert (prefetch_valid);
endmodule

module video_allpass_sweep #(
    parameter [31:0] DEPTH = 32'd256,
    parameter [31:0] GAIN_SHIFT = 32'd1
) (
    input  wire               clk,
    input  wire               i_ce,
    input  wire               i_frame_sync,
    input  wire               i_block_start,
    input  wire signed [31:0] i_sample,
output reg  signed [31:0] o_sample,
input  wire               i_peer_valid,
input  wire signed [31:0] i_peer_sample,
output wire               o_sample_ready,
output wire               o_block_ready,
output wire               o_peer_ready,
output reg  signed [31:0] o_peer_sample
);
    reg signed [31:0] delay_mem [0:DEPTH-32'd1];
    reg [31:0] ptr;
    reg [31:0] countdown;
    reg busy;
    reg armed;
    integer init_index;
localparam CHANNELS = 2, ADDR_W = $clog2(DEPTH);
reg [ADDR_W-1:0] peer_ptr, separation;
reg [$clog2(CHANNELS)-1:0] next_lane;
wire peer_slot = !busy || ((next_lane == 1'b1) && (separation != {ADDR_W{1'b0}}));
wire peer_grant = i_peer_valid && peer_slot;
wire signed [31:0] selected_sample = peer_grant ? i_peer_sample : i_sample;
assign o_sample_ready = i_ce && busy && !peer_grant;
assign o_block_ready = i_ce && !busy;
assign o_peer_ready = i_ce && peer_slot;

    // Schroeder allpass with dyadic gain g = 2^(-GAIN_SHIFT):
    // y = delayed - g*x; delay_write = x + g*y.
    // Arithmetic shifts implement the fixed-point gain coefficient.
    wire signed [31:0] delayed_sample;
    wire signed [31:0] feedforward;
    wire signed [31:0] allpass_sample;
    wire signed [31:0] feedback;
    wire signed [31:0] delay_write;

assign delayed_sample = delay_mem[peer_grant ? peer_ptr : ptr];
assign feedforward = selected_sample >>> GAIN_SHIFT;
    assign allpass_sample = delayed_sample - feedforward;
    assign feedback = allpass_sample >>> GAIN_SHIFT;
assign delay_write = selected_sample + feedback;

    initial begin
        ptr = 32'd0;
        countdown = 32'd0;
        busy = 1'b0;
        armed = 1'b0;
        o_sample = 32'sd0;
peer_ptr = {ADDR_W{1'b0}};
separation = {ADDR_W{1'b0}};
next_lane = 1'b0;
o_peer_sample = 32'sd0;
        for (init_index = 32'd0; init_index < DEPTH;
             init_index = init_index + 32'd1)
            delay_mem[init_index] = 32'sd0;
    end

    // Each accepted block processes one complete circular-buffer sweep.
    // Countdown measures enabled processing cycles; i_ce freezes all state.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_frame_sync)
                armed <= 1'b1;

            if (!busy) begin
                if (i_block_start) begin
                    busy <= 1'b1;
                    ptr <= 32'd0;
                    countdown <= DEPTH;
                end
end else if (!peer_grant) begin
next_lane <= 1'b1;
separation <= (separation == DEPTH - 32'd1) ? {ADDR_W{1'b0}} : separation + 1'b1;
                o_sample <= allpass_sample;
                delay_mem[ptr] <= delay_write;

                if (ptr == (DEPTH - 32'd1)) begin
                    ptr <= 32'd0;
                    countdown <= 32'd0;
                    busy <= 1'b0;
                end else begin
                    ptr <= ptr + 32'd1;
                    countdown <= countdown - 32'd1;
                end
            end
if (peer_grant) begin
    o_peer_sample <= allpass_sample;
    delay_mem[peer_ptr] <= delay_write;
    peer_ptr <= (peer_ptr == DEPTH - 32'd1) ? {ADDR_W{1'b0}} : peer_ptr + 1'b1;
    separation <= (separation == {ADDR_W{1'b0}}) ? DEPTH - 32'd1 : separation - 1'b1;
    next_lane <= 1'b0;
end
        end
    end

always @(*) begin
    if (i_ce && busy && peer_grant)
        assert (ptr != peer_ptr);
end

    // After the first enabled frame-sync event, an outstanding block
    // must never exhaust its processing-cycle deadline.
    assert property (!armed || !busy || (countdown != 32'd0));
endmodule

module trellis_acs_accel #(
    parameter WORD_W = 128,
    parameter STATES = 8,
    parameter TRACE_DEPTH = 8
) (
    input  wire clk,
    input  wire rst_n,
    input  wire i_valid,
    output wire i_ready,
    input  wire [STATES*WORD_W-1:0] i_branch_a,
    input  wire [STATES*WORD_W-1:0] i_branch_b,
    output wire o_valid,
    input  wire o_ready,
    output wire [WORD_W-1:0] o_terminal_metric,
    output wire [WORD_W-1:0] o_terminal_runner_up,
    output wire [STATES-1:0] o_survivors,
    input  wire [((TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1)-1:0] trace_read_addr,
    output wire [WORD_W-1:0] trace_read_word,
    output wire [159:0] o_debug_stats,
    output wire o_confidence_valid,
    output wire [((TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1)-1:0] o_confidence_addr,
    output wire [WORD_W-1:0] o_confidence_metric,
    output wire [WORD_W-1:0] o_confidence_runner_up,
    output wire [WORD_W-1:0] o_confidence_margin,
    output wire [WORD_W-1:0] o_confidence_trace_word,
    output wire o_confidence_saturated,
    output wire [1:0] o_confidence_class,
    output wire o_confidence_write_busy,
    output wire o_confidence_read_busy
);
    localparam TRACE_AW = (TRACE_DEPTH > 1) ? $clog2(TRACE_DEPTH) : 1;

    reg [WORD_W-1:0] path_metric [0:STATES-1];
    reg [WORD_W-1:0] runner_up   [0:STATES-1];
    reg [WORD_W-1:0] cand_a      [0:STATES-1];
    reg [WORD_W-1:0] cand_b      [0:STATES-1];
    reg [STATES-1:0] survivor;
    reg [WORD_W-1:0] traceback [0:TRACE_DEPTH-1];
    reg [TRACE_AW-1:0] trace_wr;
    reg pending;
    reg armed;

    reg [WORD_W-1:0] confidence_lo [0:TRACE_DEPTH-1];
    reg [WORD_W-1:0] confidence_hi [0:TRACE_DEPTH-1];
    reg [TRACE_DEPTH-1:0] confidence_live;
    reg [TRACE_AW-1:0] confidence_wr_slot;
    reg confidence_wr_pending;
    reg [TRACE_AW-1:0] confidence_rd_slot;
    reg confidence_rd_pending;
    reg [WORD_W-1:0] confidence_rd_lo;
    reg [WORD_W-1:0] confidence_rd_trace_word;
    reg [WORD_W-1:0] confidence_out_lo;
    reg [WORD_W-1:0] confidence_out_hi;
    reg [WORD_W-1:0] confidence_out_margin;
    reg [WORD_W-1:0] confidence_out_trace_word;
    reg confidence_out_valid;

    function automatic [WORD_W-1:0] metric_add;
        input [WORD_W-1:0] a;
        input [WORD_W-1:0] b;
        reg [WORD_W:0] total;
        begin
            total = {1'b0, a} + {1'b0, b};
            metric_add = total[WORD_W] ? {WORD_W{1'b1}} : total[WORD_W-1:0];
        end
    endfunction

    wire [WORD_W-1:0] next_a [0:STATES-1];
    wire [WORD_W-1:0] next_b [0:STATES-1];

    genvar g;
    generate
        for (g = 0; g < STATES; g = g + 1) begin : trellis
            localparam PRED_A = (2*g) % STATES;
            localparam PRED_B = (2*g + 1) % STATES;
            assign next_a[g] = metric_add(
                path_metric[PRED_A], i_branch_a[g*WORD_W +: WORD_W]);
            assign next_b[g] = metric_add(
                path_metric[PRED_B], i_branch_b[g*WORD_W +: WORD_W]);
        end
    endgenerate

    assign i_ready = !pending && !confidence_wr_pending;
    assign o_valid = pending;
    wire accept_branches = i_valid && i_ready;
    wire retire_survivors = o_valid && o_ready;

    assign o_terminal_metric = survivor[0] ? cand_b[0] : cand_a[0];
    assign o_terminal_runner_up = survivor[0] ? cand_a[0] : cand_b[0];
    assign o_survivors = survivor;
    assign trace_read_word = traceback[trace_read_addr];
    wire [WORD_W-1:0] survivor_word = {{(WORD_W-STATES){1'b0}}, survivor};

    reg [31:0] dbg_accept_count;
    reg [31:0] dbg_retire_count;
    reg [31:0] dbg_input_stalls;
    reg [31:0] dbg_output_stalls;
    reg [15:0] dbg_stall_run;
    reg [15:0] dbg_stall_peak;
    wire dbg_output_stalled = o_valid && !o_ready;
    assign o_debug_stats = {dbg_accept_count, dbg_retire_count,
                           dbg_input_stalls, dbg_output_stalls, dbg_stall_run, dbg_stall_peak};

    wire confidence_cache_hit = confidence_out_valid &&
                                (confidence_rd_slot == trace_read_addr);
    assign o_confidence_valid = confidence_cache_hit;
    assign o_confidence_addr = confidence_rd_slot;
    assign o_confidence_metric = confidence_out_lo;
    assign o_confidence_runner_up = confidence_out_hi;
    assign o_confidence_margin = confidence_out_margin;
    assign o_confidence_trace_word = confidence_out_trace_word;
    assign o_confidence_saturated = o_confidence_valid &&
                                   (confidence_out_hi == {WORD_W{1'b1}});
    assign o_confidence_write_busy = confidence_wr_pending;
    assign o_confidence_read_busy = confidence_rd_pending;
    assign o_confidence_class =
        !o_confidence_valid ? 2'd0 :
        (confidence_out_hi == {WORD_W{1'b1}}) ? 2'd0 :
        (confidence_out_margin == {WORD_W{1'b0}}) ? 2'd1 :
        (|confidence_out_margin[WORD_W-1:WORD_W/2]) ? 2'd3 :
        2'd2;

    initial begin
        confidence_wr_slot = {TRACE_AW{1'b0}};
        confidence_wr_pending = 1'b0;
        confidence_live = {TRACE_DEPTH{1'b0}};
        for (integer c = 0; c < TRACE_DEPTH; c = c + 1) begin
            confidence_lo[c] = {WORD_W{1'b0}};
            confidence_hi[c] = {WORD_W{1'b0}};
        end
    end

    // Archive each trace record through a single-word write datapath.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            confidence_wr_slot <= {TRACE_AW{1'b0}};
            confidence_wr_pending <= 1'b0;
            confidence_live <= {TRACE_DEPTH{1'b0}};
            for (integer c = 0; c < TRACE_DEPTH; c = c + 1) begin
                confidence_lo[c] <= {WORD_W{1'b0}};
                confidence_hi[c] <= {WORD_W{1'b0}};
            end
        end else begin
            if (confidence_wr_pending) begin
                confidence_hi[confidence_wr_slot] <=
                    survivor[0] ? cand_a[0] : cand_b[0];
                confidence_live[confidence_wr_slot] <= 1'b1;
                confidence_wr_pending <= 1'b0;
            end
            if (retire_survivors) begin
                confidence_lo[trace_wr] <=
                    survivor[0] ? cand_b[0] : cand_a[0];
                confidence_live[trace_wr] <= 1'b0;
                confidence_wr_slot <= trace_wr;
                confidence_wr_pending <= 1'b1;
            end
        end
    end

    initial begin
        confidence_rd_slot = {TRACE_AW{1'b0}};
        confidence_rd_pending = 1'b0;
        confidence_rd_lo = {WORD_W{1'b0}};
        confidence_rd_trace_word = {WORD_W{1'b0}};
        confidence_out_lo = {WORD_W{1'b0}};
        confidence_out_hi = {WORD_W{1'b0}};
        confidence_out_margin = {WORD_W{1'b0}};
        confidence_out_trace_word = {WORD_W{1'b0}};
        confidence_out_valid = 1'b0;
    end

    // Writes invalidate matching snapshots and restart unfinished reads.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            confidence_rd_slot <= {TRACE_AW{1'b0}};
            confidence_rd_pending <= 1'b0;
            confidence_rd_lo <= {WORD_W{1'b0}};
            confidence_rd_trace_word <= {WORD_W{1'b0}};
            confidence_out_lo <= {WORD_W{1'b0}};
            confidence_out_hi <= {WORD_W{1'b0}};
            confidence_out_margin <= {WORD_W{1'b0}};
            confidence_out_trace_word <= {WORD_W{1'b0}};
            confidence_out_valid <= 1'b0;
        end else begin
            if (retire_survivors || confidence_wr_pending) begin
                confidence_rd_pending <= 1'b0;
                if ((retire_survivors && (confidence_rd_slot == trace_wr)) ||
                    (confidence_wr_pending &&
                     (confidence_rd_slot == confidence_wr_slot)))
                    confidence_out_valid <= 1'b0;
            end else if (confidence_rd_pending) begin
                confidence_out_lo <= confidence_rd_lo;
                confidence_out_hi <= confidence_hi[confidence_rd_slot];
                confidence_out_margin <=
                    confidence_hi[confidence_rd_slot] - confidence_rd_lo;
                confidence_out_trace_word <= confidence_rd_trace_word;
                confidence_out_valid <= confidence_live[confidence_rd_slot];
                confidence_rd_pending <= 1'b0;
            end else if ((trace_read_addr < TRACE_DEPTH) &&
                         !confidence_cache_hit) begin
                if (confidence_live[trace_read_addr]) begin
                    confidence_rd_slot <= trace_read_addr;
                    confidence_rd_lo <= confidence_lo[trace_read_addr];
                    confidence_rd_trace_word <= traceback[trace_read_addr];
                    confidence_rd_pending <= 1'b1;
                    confidence_out_valid <= 1'b0;
                end else begin
                    confidence_out_valid <= 1'b0;
                end
            end else if (trace_read_addr >= TRACE_DEPTH) begin
                confidence_out_valid <= 1'b0;
            end
        end
    end

    initial begin
        dbg_accept_count = 32'd0;
        dbg_retire_count = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_peak = 16'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dbg_accept_count <= 32'd0;
            dbg_retire_count <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_peak <= 16'd0;
        end else begin
            if (accept_branches) begin
                if (dbg_accept_count != 32'hffff_ffff)
                    dbg_accept_count <= dbg_accept_count + 32'd1;
            end
            if (retire_survivors) begin
                if (dbg_retire_count != 32'hffff_ffff)
                    dbg_retire_count <= dbg_retire_count + 32'd1;
            end
            if (i_valid && !i_ready) begin
                if (dbg_input_stalls != 32'hffff_ffff)
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
            end
            if (dbg_output_stalled) begin
                if (dbg_output_stalls != 32'hffff_ffff)
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (dbg_stall_run != 16'hffff) begin
                    dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_peak)
                        dbg_stall_peak <= dbg_stall_run + 16'd1;
                end
            end else begin
                dbg_stall_run <= 16'd0;
            end
        end
    end

    initial begin
        pending = 1'b0;
        armed = 1'b0;
        survivor = {STATES{1'b0}};
        trace_wr = {TRACE_AW{1'b0}};
        for (integer s = 0; s < STATES; s = s + 1) begin
            path_metric[s] = {WORD_W{1'b0}};
            runner_up[s] = {WORD_W{1'b0}};
            cand_a[s] = {WORD_W{1'b0}};
            cand_b[s] = {WORD_W{1'b0}};
        end
        for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
            traceback[t] = {WORD_W{1'b0}};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending <= 1'b0;
            armed <= 1'b0;
            survivor <= {STATES{1'b0}};
            trace_wr <= {TRACE_AW{1'b0}};
            for (integer s = 0; s < STATES; s = s + 1) begin
                path_metric[s] <= {WORD_W{1'b0}};
                runner_up[s] <= {WORD_W{1'b0}};
                cand_a[s] <= {WORD_W{1'b0}};
                cand_b[s] <= {WORD_W{1'b0}};
            end
            for (integer t = 0; t < TRACE_DEPTH; t = t + 1)
                traceback[t] <= {WORD_W{1'b0}};
        end else begin
            // Capture both path candidates and their comparison together.
            if (accept_branches) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    cand_a[s] <= next_a[s];
                    cand_b[s] <= next_b[s];
                    survivor[s] <= (next_b[s] < next_a[s]);
                end
                pending <= 1'b1;
            end

            // Back-pressure holds the candidate bank and output unchanged.
            // Retain the losing metric for decoder confidence estimation.
            if (retire_survivors) begin
                for (integer s = 0; s < STATES; s = s + 1) begin
                    path_metric[s] <= survivor[s] ? cand_b[s] : cand_a[s];
                    runner_up[s] <= survivor[s] ? cand_a[s] : cand_b[s];
                end
                traceback[trace_wr] <= survivor_word;
                if (trace_wr == TRACE_AW'(TRACE_DEPTH - 1))
                    trace_wr <= {TRACE_AW{1'b0}};
                else
                    trace_wr <= trace_wr + {{(TRACE_AW-1){1'b0}}, 1'b1};
                pending <= 1'b0;
                // Q: the first completed trellis update.
                armed <= 1'b1;
            end
        end
    end

    // After Q, the committed terminal-state survivor never exceeds its runner-up.
    always @(posedge clk)
        assert (!armed || (path_metric[0] <= runner_up[0]));

    always @(posedge clk)
        assert (!confidence_rd_pending ||
                (confidence_rd_lo <= confidence_hi[confidence_rd_slot]));
endmodule

module wave_stride_profile #(
    parameter integer LINE_W = 8,
    parameter integer ENTRIES = 4
) (
    input wire clk,
    input wire sample,
    input wire lane,
    input wire [LINE_W-1:0] previous_line,
    input wire [LINE_W-1:0] sample_line,
    output wire [LINE_W-1:0] hint_line,
    output wire [LINE_W-1:0] hint_step,
    output wire [1:0] hint_score,
    output wire hint_confident,
    output wire [ENTRIES*LINE_W-1:0] history_words,
    output reg [$clog2(ENTRIES)-1:0] recent,
    output reg sampled
);
    localparam integer PTR_W = $clog2(ENTRIES);
    reg [LINE_W-1:0] source [0:ENTRIES-1];
    reg [LINE_W-1:0] history [0:ENTRIES-1], step [0:ENTRIES-1];
    reg [1:0] score [0:ENTRIES-1];
    reg valid [0:ENTRIES-1], owner [0:ENTRIES-1];
    reg [PTR_W-1:0] replace_ptr, selected;
    reg hit;
    integer j;
    initial begin
        replace_ptr = 0;
        recent = 0;
        sampled = 1'b0;
    end
    genvar e;
    generate
        for (e = 0; e < ENTRIES; e = e + 1) begin : initialize_profiles
            initial begin
                source[e] = {LINE_W{1'b0}};
                history[e] = {LINE_W{1'b0}};
                step[e] = {LINE_W{1'b0}};
                score[e] = 2'b00;
                valid[e] = 1'b0;
                owner[e] = 1'b0;
            end
            assign history_words[e*LINE_W +: LINE_W] = history[e];
        end
    endgenerate
    wire [LINE_W-1:0] difference = sample_line - previous_line;
    always @(*) begin
        hit = 1'b0;
        selected = replace_ptr;
        for (j = 0; j < ENTRIES; j = j + 1) begin
            if (valid[j] && owner[j] == lane && source[j] == previous_line) begin
                hit = 1'b1;
                selected = j;
            end
        end
    end
    assign hint_line = history[recent] + step[recent];
    assign hint_step = step[recent];
    assign hint_score = score[recent];
    assign hint_confident = sampled && valid[recent] &&
                            (score[recent] >= 2'b10);
    always @(posedge clk) begin
        if (sample) begin
            recent <= selected;
            sampled <= 1'b1;
            history[selected] <= sample_line;
            step[selected] <= difference;
            if (hit && step[selected] == difference) begin
                if (score[selected] != 2'b11)
                    score[selected] <= score[selected] + 1'b1;
            end else
                score[selected] <= 2'b00;
            if (!hit) begin
                valid[selected] <= 1'b1;
                owner[selected] <= lane;
                source[selected] <= previous_line;
                replace_ptr <= (replace_ptr == ENTRIES-1) ? 0 : (replace_ptr + 1'b1);
            end
        end
    end
endmodule

module wave_line_prefetcher #(
    parameter integer LINE_W = 8,
    parameter integer DEPTH = 64,
    parameter integer COUNT_W = 8
) (
    input  wire                  clk,
    input  wire                  miss_valid,
    output wire                  miss_ready,
    input  wire [LINE_W-1:0]     miss_line,
    input  wire                  peer_valid,
    output wire                  peer_ready,
    input  wire [LINE_W-1:0]     peer_line,
    output wire                  peer_prefetch_valid,
    input  wire                  peer_prefetch_ready,
    output wire [LINE_W-1:0]     peer_prefetch_line,
    output wire                  prefetch_valid,
    input  wire                  prefetch_ready,
    output wire [LINE_W-1:0]     stride_hint_line,
    output wire [LINE_W-1:0]     stride_hint_step,
    output wire [1:0]            stride_hint_score,
    output wire                  stride_hint_confident,
    output wire [LINE_W-1:0]     prefetch_line
);
    localparam [COUNT_W-1:0] COUNT_ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] COUNT_ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam [LINE_W-1:0] LINE_ZERO = {LINE_W{1'b0}};
    localparam [LINE_W-1:0] LINE_ONE = {{(LINE_W-1){1'b0}}, 1'b1};
    localparam integer CHANNELS = 2, PEER_DEPTH = 4;
    localparam integer PEER_PTR_W = $clog2(PEER_DEPTH);
    localparam integer PROFILE_ENTRIES = 4;
    localparam integer PROFILE_PTR_W = $clog2(PROFILE_ENTRIES);

    reg [LINE_W-1:0] prefetch_q [0:DEPTH-1];
    reg [COUNT_W-1:0] wr_ptr;
    reg [COUNT_W-1:0] rd_ptr;
    reg [COUNT_W-1:0] used;
    reg [LINE_W-1:0] last_miss;
    reg pv;
    reg [LINE_W-1:0] peer_q [0:PEER_DEPTH-1];
    reg [PEER_PTR_W-1:0] peer_wr, peer_rd;
    reg [$clog2(PEER_DEPTH+1)-1:0] peer_used;
    reg [LINE_W-1:0] peer_last, alu_last;
    reg [$clog2(CHANNELS)-1:0] alu_owner;

    initial begin
        wr_ptr = COUNT_ZERO;
        rd_ptr = COUNT_ZERO;
        used = COUNT_ZERO;
        last_miss = {LINE_W{1'b1}};
        pv = 1'b0;
        peer_wr = 0;
        peer_rd = 0;
        peer_used = 0;
        peer_last = LINE_ZERO;
        alu_last = LINE_ZERO;
        alu_owner = 0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : initialize_queue
            initial prefetch_q[g] = LINE_ZERO;
        end
        for (g = 0; g < PEER_DEPTH; g = g + 1) begin : initialize_peer_queue
            initial peer_q[g] = LINE_ZERO;
        end
    endgenerate

    assign miss_ready = (used < CAPACITY);
    assign prefetch_valid = (used != COUNT_ZERO);
    assign prefetch_line = prefetch_q[rd_ptr];

    wire push = miss_valid && miss_ready;
    wire pop = prefetch_valid && prefetch_ready;
    assign peer_ready = (peer_used < PEER_DEPTH) && !push;
    assign peer_prefetch_valid = (peer_used != 0);
    assign peer_prefetch_line = peer_q[peer_rd];
    wire peer_push = peer_valid && peer_ready;
    wire peer_pop = peer_prefetch_valid && peer_prefetch_ready;
    wire [LINE_W-1:0] issue_line = push ? miss_line : peer_line;
    wire [LINE_W-1:0] cached_line = alu_owner ? peer_last : last_miss;
    wire [LINE_W-1:0] shared_next = (issue_line == cached_line) ? alu_last : (issue_line + LINE_ONE);

    wire [PROFILE_ENTRIES*LINE_W-1:0] profile_history;
    wire [PROFILE_PTR_W-1:0] profile_recent;
    wire profile_sampled;
    wave_stride_profile #(.LINE_W(LINE_W), .ENTRIES(PROFILE_ENTRIES))
        stride_profile (
            .clk(clk), .sample(push || peer_push), .lane(!push),
            .previous_line(push ? last_miss : peer_last),
            .sample_line(issue_line),
            .hint_line(stride_hint_line), .hint_step(stride_hint_step),
            .hint_score(stride_hint_score),
            .hint_confident(stride_hint_confident),
            .history_words(profile_history),
            .recent(profile_recent), .sampled(profile_sampled)
        );

    // The slot immediately preceding the write pointer retains the
    // most recently generated next-line request, even after retirement.
    wire [COUNT_W-1:0] latest_slot =
        (wr_ptr == COUNT_ZERO) ? LAST_SLOT : (wr_ptr - COUNT_ONE);
    wire [LINE_W-1:0] latest_line = prefetch_q[latest_slot];

    always @(posedge clk) begin
        if (push || peer_push) begin
            alu_last <= shared_next;
            alu_owner <= !push;
        end
        if (peer_push) begin
            peer_q[peer_wr] <= shared_next;
            peer_last <= peer_line;
            peer_wr <= (peer_wr == PEER_DEPTH-1) ? 0 : (peer_wr + 1'b1);
        end
        if (peer_pop) peer_rd <= (peer_rd == PEER_DEPTH-1) ? 0 : (peer_rd + 1'b1);
        if (peer_push != peer_pop)
            peer_used <= peer_push ? (peer_used + 1'b1) : (peer_used - 1'b1);
        if (push) begin
            prefetch_q[wr_ptr] <= shared_next;
            last_miss <= miss_line;
            wr_ptr <= (wr_ptr == LAST_SLOT) ? COUNT_ZERO : (wr_ptr + COUNT_ONE);
        end
        if (pop)
            rd_ptr <= (rd_ptr == LAST_SLOT) ? COUNT_ZERO : (rd_ptr + COUNT_ONE);

        if (push && !pop)
            used <= used + COUNT_ONE;
        else if (pop && !push)
            used <= used - COUNT_ONE;

        // No history check is needed before the first transaction.
        // Keeping this update transaction-gated preserves complete idle.
        if (push || pop)
            pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $stable(last_miss))
            assert ($stable(latest_line));

    always @(posedge clk)
        if ((push || peer_push) && stride_hint_confident &&
            (stride_hint_step == LINE_ONE))
            assert (stride_hint_line == alu_last);
endmodule

module chien_request_window #(
    parameter integer FIELD_W = 8,
    parameter integer COEFFS = 4,
    parameter integer DEPTH = 4
) (
    input wire clk,
    input wire in_valid,
    output wire in_ready,
    input wire [COEFFS*FIELD_W-1:0] in_coeffs,
    input wire release_head,
    output wire head_valid,
    output reg [$clog2(DEPTH+1)-1:0] count,
    output wire [DEPTH*COEFFS*FIELD_W-1:0] coeff_state,
    output wire [DEPTH*FIELD_W-1:0] seed_state
);
    localparam integer COUNT_W = $clog2(DEPTH+1);
    reg [FIELD_W-1:0] coeff_mem [0:DEPTH*COEFFS-1];
    reg [FIELD_W-1:0] seed_mem [0:DEPTH-1];
    reg [FIELD_W-1:0] incoming_seed;
    wire pop, push;
    wire [COUNT_W-1:0] write_slot;

    assign head_valid = (count != 0);
    assign pop = release_head && head_valid;
    assign in_ready = (count < DEPTH) || pop;
    assign push = in_valid && in_ready;
    assign write_slot = count - pop;

    integer decode_index;
    always @(*) begin
        incoming_seed = {FIELD_W{1'b0}};
        for (decode_index = 0; decode_index < COEFFS; decode_index = decode_index + 1)
            incoming_seed = incoming_seed ^ in_coeffs[decode_index*FIELD_W +: FIELD_W];
    end

    genvar slot_view, term_view;
    generate
        for (slot_view = 0; slot_view < DEPTH; slot_view = slot_view + 1) begin : window_view
            assign seed_state[slot_view*FIELD_W +: FIELD_W] = seed_mem[slot_view];
            for (term_view = 0; term_view < COEFFS; term_view = term_view + 1) begin : word_view
                assign coeff_state[(slot_view*COEFFS+term_view)*FIELD_W +: FIELD_W] =
                    coeff_mem[slot_view*COEFFS+term_view];
            end
        end
    endgenerate

    integer init_slot, init_term;
    initial begin
        count = {COUNT_W{1'b0}};
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            seed_mem[init_slot] = {FIELD_W{1'b0}};
            for (init_term = 0; init_term < COEFFS; init_term = init_term + 1)
                coeff_mem[init_slot*COEFFS+init_term] = {FIELD_W{1'b0}};
        end
    end

    integer slot, term;
    always @(posedge clk) begin
        case ({push, pop})
            2'b10: count <= count + 1'b1;
            2'b01: count <= count - 1'b1;
            default: count <= count;
        endcase
        for (slot = 0; slot < DEPTH; slot = slot + 1) begin
            if (pop && (slot < DEPTH-1)) begin
                seed_mem[slot] <= seed_mem[slot+1];
                for (term = 0; term < COEFFS; term = term + 1)
                    coeff_mem[slot*COEFFS+term] <= coeff_mem[(slot+1)*COEFFS+term];
            end
            if (push && (write_slot == slot)) begin
                seed_mem[slot] <= incoming_seed;
                for (term = 0; term < COEFFS; term = term + 1)
                    coeff_mem[slot*COEFFS+term] <= in_coeffs[term*FIELD_W +: FIELD_W];
            end
        end
    end
endmodule

module chien_deadline_search #(
    parameter integer FIELD_W = 8,
    parameter integer COEFFS = 4,
    parameter [FIELD_W-1:0] REDUCTION = 8'h1d,
    parameter integer REQUEST_DEPTH = 4
) (
    input  wire clk,
    input  wire req_valid,
    output wire req_ready,
    input  wire [COEFFS*FIELD_W-1:0] req_coeffs,
    output wire result_valid,
    input  wire result_ready,
    output reg  [FIELD_W-1:0] position,
    output reg  hit,
    output wire [$clog2(REQUEST_DEPTH+1)-1:0] queued_count,
    output wire [REQUEST_DEPTH*COEFFS*FIELD_W-1:0] queued_coeffs,
    output wire [REQUEST_DEPTH*FIELD_W-1:0] queued_seeds
);
    localparam [FIELD_W-1:0] FIELD_ZERO = {FIELD_W{1'b0}};
    localparam [FIELD_W-1:0] FIELD_ONE = {{(FIELD_W-1){1'b0}}, 1'b1};
    localparam [FIELD_W-1:0] LAST_POSITION = {FIELD_W{1'b1}};
    localparam [FIELD_W:0] FIELD_SIZE = {1'b1, {FIELD_W{1'b0}}};
    localparam [FIELD_W:0] CREDIT_ONE = {{FIELD_W{1'b0}}, 1'b1};

    reg busy;
    reg armed;
    reg pv;
    reg [FIELD_W:0] credits;
    reg [FIELD_W-1:0] terms [0:COEFFS-1];
    wire [FIELD_W-1:0] stepped_terms [0:COEFFS-1];
    reg [FIELD_W-1:0] eval_now;
    reg [FIELD_W-1:0] eval_next;

    wire request_fire;
    wire trial_fire;
    wire queue_head_valid;
    wire queue_retire;

    chien_request_window #(
        .FIELD_W(FIELD_W),
        .COEFFS(COEFFS),
        .DEPTH(REQUEST_DEPTH)
    ) request_window (
        .clk(clk),
        .in_valid(req_valid),
        .in_ready(req_ready),
        .in_coeffs(req_coeffs),
        .release_head(queue_retire),
        .head_valid(queue_head_valid),
        .count(queued_count),
        .coeff_state(queued_coeffs),
        .seed_state(queued_seeds)
    );

    assign result_valid = busy;
    assign request_fire = queue_head_valid && !busy;
    assign trial_fire = result_valid && result_ready;
    assign queue_retire = trial_fire && (position == LAST_POSITION);

    function automatic [FIELD_W-1:0] gf_xtime;
        input [FIELD_W-1:0] a;
        begin
            gf_xtime = (a << 1'b1) ^
                       (a[FIELD_W-1] ? REDUCTION : FIELD_ZERO);
        end
    endfunction

    function automatic [FIELD_W-1:0] gf_mul;
        input [FIELD_W-1:0] a;
        input [FIELD_W-1:0] b;
        reg [FIELD_W-1:0] multiplicand;
        reg [FIELD_W-1:0] multiplier;
        reg [FIELD_W-1:0] product;
        integer bit_index;
        begin
            multiplicand = a;
            multiplier = b;
            product = FIELD_ZERO;
            for (bit_index = 0; bit_index < FIELD_W; bit_index = bit_index + 1) begin
                if (multiplier[0])
                    product = product ^ multiplicand;
                multiplicand = gf_xtime(multiplicand);
                multiplier = multiplier >> 1'b1;
            end
            gf_mul = product;
        end
    endfunction

    function automatic [FIELD_W-1:0] alpha_factor;
        input integer exponent;
        reg [FIELD_W-1:0] factor;
        integer power_index;
        begin
            factor = FIELD_ONE;
            for (power_index = 0; power_index < exponent; power_index = power_index + 1)
                factor = gf_xtime(factor);
            alpha_factor = factor;
        end
    endfunction

    genvar coefficient;
    generate
        for (coefficient = 0; coefficient < COEFFS; coefficient = coefficient + 1) begin : coefficient_steps
            assign stepped_terms[coefficient] =
                gf_mul(terms[coefficient], alpha_factor(coefficient));
        end
    endgenerate

    integer eval_index;
    always @(*) begin
        eval_now = FIELD_ZERO;
        eval_next = FIELD_ZERO;
        for (eval_index = 0; eval_index < COEFFS; eval_index = eval_index + 1) begin
            eval_now = eval_now ^ terms[eval_index];
            eval_next = eval_next ^ stepped_terms[eval_index];
        end
    end

    integer init_index;
    initial begin
        busy = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
        credits = {1'b0, FIELD_ZERO};
        position = FIELD_ZERO;
        hit = 1'b0;
        for (init_index = 0; init_index < COEFFS; init_index = init_index + 1)
            terms[init_index] = FIELD_ZERO;
    end

    // Position zero tests x=0. Positions 1..255 test alpha^0..alpha^254.
    // Each accepted result consumes one enabled search cycle. Back-pressure
    // freezes the countdown, multiplier registers, position and hit flag.
    integer state_index;
    always @(posedge clk) begin
        if (request_fire || trial_fire)
            pv <= 1'b1;

        if (request_fire) begin
            armed <= 1'b1;
            busy <= 1'b1;
            credits <= FIELD_SIZE;
            position <= FIELD_ZERO;
            hit <= (queued_coeffs[0 +: FIELD_W] == FIELD_ZERO);
            for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                terms[state_index] <= queued_coeffs[state_index*FIELD_W +: FIELD_W];
        end else if (trial_fire) begin
            credits <= credits - CREDIT_ONE;
            if (position == LAST_POSITION) begin
                busy <= 1'b0;
            end else begin
                position <= position + FIELD_ONE;
                if (position == FIELD_ZERO) begin
                    // The first nonzero element is one; coefficients stay unchanged.
                    hit <= (queued_seeds[0 +: FIELD_W] == FIELD_ZERO);
                end else begin
                    for (state_index = 0; state_index < COEFFS; state_index = state_index + 1)
                        terms[state_index] <= stepped_terms[state_index];
                    hit <= (eval_next == FIELD_ZERO);
                end
            end
        end
    end

    // After the first accepted request, consuming the previous cycle's final
    // countdown credit must leave no search outstanding.
    always @(posedge clk)
        if (pv && armed && $past(trial_fire))
            assert (!busy || ($past(credits) > CREDIT_ONE));

    always @(posedge clk)
        if (pv && trial_fire && (position == FIELD_ZERO))
            assert (hit == (queued_coeffs[0 +: FIELD_W] == FIELD_ZERO));
endmodule

module i2c_stretch_watchdog #(
    parameter integer WIDTH = 32,
    parameter integer PERIOD = 4,
    parameter integer FILTER = 4,
    parameter [WIDTH-1:0] RESET_BUDGET = 32'd8
) (
    input wire clk, rst_n, ce, pending, scl_in, config_valid,
    input wire [WIDTH-1:0] budget, config_budget,
    output wire debit,
    output reg [WIDTH-1:0] remaining,
    output reg [$clog2(PERIOD)-1:0] phase,
    output reg [$clog2(FILTER)-1:0] qualification
);
    initial begin
        remaining = RESET_BUDGET;
        phase = 0;
        qualification = 0;
    end
    assign debit = ce && pending && !scl_in &&
                   (phase == PERIOD-1) && (qualification == FILTER-1);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            remaining <= RESET_BUDGET;
            phase <= 0;
            qualification <= 0;
        end else if (ce) begin
            if (!pending) begin
                remaining <= config_valid ? config_budget : budget;
                phase <= 0;
                qualification <= 0;
            end else if (!scl_in) begin
                if (phase == PERIOD-1) begin
                    phase <= 0;
                    if (qualification != FILTER-1)
                        qualification <= qualification + 1'b1;
                    if (debit && remaining != {WIDTH{1'b0}})
                        remaining <= remaining - {{(WIDTH-1){1'b0}}, 1'b1};
                end else
                    phase <= phase + 1'b1;
            end
        end
    end
endmodule

module i2c_stretch_handler #(
    parameter integer COUNTER_WIDTH = 32,
    parameter [COUNTER_WIDTH-1:0] RESET_MAX_STRETCH = 32'd8,
    parameter integer WATCHDOG_PERIOD = 4, WATCHDOG_FILTER = 4,
    parameter integer EVENT_DEPTH = 4
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire request_high,
    input wire scl_in,
    input wire config_valid,
    input wire [COUNTER_WIDTH-1:0] config_max_stretch,
    output wire scl_release,
    output wire high_phase_done,
    output reg high_pending,
    output reg stretching_active,
    output reg stretch_timeout,
    output reg [COUNTER_WIDTH-1:0] stretch_duration,
    output reg [COUNTER_WIDTH-1:0] max_stretch,
    output wire config_ready,
    output wire request_ready,
    output wire [COUNTER_WIDTH-1:0] watchdog_remaining,
    output wire [$clog2(WATCHDOG_PERIOD)-1:0] watchdog_phase,
    output wire [$clog2(WATCHDOG_FILTER)-1:0] watchdog_qualification,
    output wire [$clog2(EVENT_DEPTH):0] event_count,
    output reg [EVENT_DEPTH-1:0] event_occupied,
    output wire event_full, event_empty,
    output wire report_valid,
    output wire report_first,
    output wire report_last,
    output reg [1:0] report_kind,
    output reg [COUNTER_WIDTH-1:0] report_word,
output wire report_timed_out,
output reg [COUNTER_WIDTH-1:0] diagnostic_word
);
    localparam [COUNTER_WIDTH-1:0] COUNT_ZERO = {COUNTER_WIDTH{1'b0}};
    localparam [COUNTER_WIDTH-1:0] COUNT_ONE = {{(COUNTER_WIDTH-1){1'b0}}, 1'b1};
    localparam integer EVENT_ADDR_WIDTH = $clog2(EVENT_DEPTH);
    localparam integer EVENT_PTR_WIDTH = EVENT_ADDR_WIDTH + 1;
    reg [COUNTER_WIDTH-1:0] event_budget [0:EVENT_DEPTH-1];
    reg [COUNTER_WIDTH-1:0] event_duration [0:EVENT_DEPTH-1];
    reg [COUNTER_WIDTH-1:0] event_unused [0:EVENT_DEPTH-1];
    reg event_timeout [0:EVENT_DEPTH-1];
    reg [EVENT_PTR_WIDTH-1:0] event_read, event_write;
    wire [EVENT_ADDR_WIDTH-1:0] event_read_index, event_write_index;
    wire event_reserve, event_push, event_pop;
    integer event_init, event_reset, event_slot;
    reg past_valid;
    wire watchdog_debit;
    i2c_stretch_watchdog #(
        .WIDTH(COUNTER_WIDTH), .PERIOD(WATCHDOG_PERIOD),
        .FILTER(WATCHDOG_FILTER), .RESET_BUDGET(RESET_MAX_STRETCH)
    ) budget_timer (
        .clk(clk), .rst_n(rst_n), .ce(i_ce), .pending(high_pending),
        .scl_in(scl_in), .config_valid(config_valid),
        .budget(max_stretch), .config_budget(config_max_stretch),
        .debit(watchdog_debit), .remaining(watchdog_remaining),
        .phase(watchdog_phase), .qualification(watchdog_qualification)
    );
reg [COUNTER_WIDTH-1:0] diag_ticks, diag_low_ticks;
reg [COUNTER_WIDTH-1:0] diag_requests, diag_completions;
reg [COUNTER_WIDTH-1:0] diag_timeouts, diag_stalls;
reg [COUNTER_WIDTH-1:0] diag_configs, diag_reports;
reg [COUNTER_WIDTH-1:0] diag_run_ticks, diag_longest_run;
reg [COUNTER_WIDTH-1:0] diag_last_budget, diag_last_duration;
reg [COUNTER_WIDTH-1:0] diag_last_unused;
reg [$clog2(EVENT_DEPTH):0] diag_peak_queue;
reg [3:0] diag_page;
initial begin
    diagnostic_word = COUNT_ZERO;
    diag_page = 4'd0;
    diag_ticks = COUNT_ZERO;
    diag_low_ticks = COUNT_ZERO;
    diag_requests = COUNT_ZERO;
    diag_completions = COUNT_ZERO;
    diag_timeouts = COUNT_ZERO;
    diag_stalls = COUNT_ZERO;
    diag_configs = COUNT_ZERO;
    diag_reports = COUNT_ZERO;
    diag_run_ticks = COUNT_ZERO;
    diag_longest_run = COUNT_ZERO;
    diag_last_budget = COUNT_ZERO;
    diag_last_duration = COUNT_ZERO;
    diag_last_unused = COUNT_ZERO;
    diag_peak_queue = 0;
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        diagnostic_word <= COUNT_ZERO;
        diag_page <= 4'd0;
        diag_ticks <= COUNT_ZERO;
        diag_low_ticks <= COUNT_ZERO;
        diag_requests <= COUNT_ZERO;
        diag_completions <= COUNT_ZERO;
        diag_timeouts <= COUNT_ZERO;
        diag_stalls <= COUNT_ZERO;
        diag_configs <= COUNT_ZERO;
        diag_reports <= COUNT_ZERO;
        diag_run_ticks <= COUNT_ZERO;
        diag_longest_run <= COUNT_ZERO;
        diag_last_budget <= COUNT_ZERO;
        diag_last_duration <= COUNT_ZERO;
        diag_last_unused <= COUNT_ZERO;
        diag_peak_queue <= 0;
    end else if (i_ce) begin
        diag_page <= (diag_page == 4'd13) ? 4'd0 : diag_page + 4'd1;
        if (!(&diag_ticks)) begin
            diag_ticks <= diag_ticks + COUNT_ONE;
        end
        if (high_pending && !scl_in && !(&diag_low_ticks)) begin
            diag_low_ticks <= diag_low_ticks + COUNT_ONE;
        end
        if (event_reserve && !(&diag_requests)) begin
            diag_requests <= diag_requests + COUNT_ONE;
        end
        if (event_push && !(&diag_completions)) begin
            diag_completions <= diag_completions + COUNT_ONE;
        end
        if (event_push && stretch_timeout && !(&diag_timeouts)) begin
            diag_timeouts <= diag_timeouts + COUNT_ONE;
        end
        if (request_high && !request_ready && !(&diag_stalls)) begin
            diag_stalls <= diag_stalls + COUNT_ONE;
        end
        if (config_valid && config_ready && !(&diag_configs)) begin
            diag_configs <= diag_configs + COUNT_ONE;
        end
        if (event_pop && !(&diag_reports)) begin
            diag_reports <= diag_reports + COUNT_ONE;
        end
        if (event_reserve) begin
            diag_run_ticks <= COUNT_ZERO;
            diag_last_budget <= max_stretch;
        end else if (high_pending) begin
            if (!(&diag_run_ticks))
                diag_run_ticks <= diag_run_ticks + COUNT_ONE;
            if (diag_run_ticks >= diag_longest_run)
                diag_longest_run <= (&diag_run_ticks) ?
                                    diag_run_ticks : diag_run_ticks + COUNT_ONE;
        end
        if (event_push) begin
            diag_last_duration <= stretch_duration;
            diag_last_unused <= watchdog_remaining;
        end
        if (event_count > diag_peak_queue)
            diag_peak_queue <= event_count;
        case (diag_page)
            4'd0: diagnostic_word <= diag_ticks;
            4'd1: diagnostic_word <= diag_low_ticks;
            4'd2: diagnostic_word <= diag_requests;
            4'd3: diagnostic_word <= diag_completions;
            4'd4: diagnostic_word <= diag_timeouts;
            4'd5: diagnostic_word <= diag_stalls;
            4'd6: diagnostic_word <= diag_configs;
            4'd7: diagnostic_word <= diag_reports;
            4'd8: diagnostic_word <= diag_run_ticks;
            4'd9: diagnostic_word <= diag_longest_run;
            4'd10: diagnostic_word <= diag_peak_queue;
            4'd11: diagnostic_word <= diag_last_budget;
            4'd12: diagnostic_word <= diag_last_duration;
            4'd13: diagnostic_word <= diag_last_unused;
            default: diagnostic_word <= COUNT_ZERO;
        endcase
    end
end

    initial begin
        high_pending = 1'b0;
        stretching_active = 1'b0;
        stretch_timeout = 1'b0;
        stretch_duration = COUNT_ZERO;
        max_stretch = RESET_MAX_STRETCH;
        past_valid = 1'b0;
        event_read = 0;
        event_write = 0;
        report_kind = 0;
        for (event_init = 0; event_init < EVENT_DEPTH; event_init = event_init + 1) begin
            event_budget[event_init] = COUNT_ZERO;
            event_duration[event_init] = COUNT_ZERO;
            event_unused[event_init] = COUNT_ZERO;
            event_timeout[event_init] = 1'b0;
        end
    end

    // Release the open-drain SCL output throughout the pending high phase.
    // Even a timeout does not end that phase before the slave releases SCL.
    assign scl_release = high_pending;
    assign high_phase_done = high_pending && scl_in;
    assign config_ready = i_ce && !high_pending;
    assign request_ready = i_ce && !high_pending && !config_valid &&
                           !event_full;

    assign event_read_index = event_read[EVENT_ADDR_WIDTH-1:0];
    assign event_write_index = event_write[EVENT_ADDR_WIDTH-1:0];
    assign event_empty = (event_read == event_write);
    assign event_full = (event_read_index == event_write_index) &&
                       (event_read[EVENT_ADDR_WIDTH] != event_write[EVENT_ADDR_WIDTH]);
    assign event_count = event_write - event_read;
    assign event_reserve = request_high && request_ready;
    assign event_push = i_ce && high_pending && scl_in;
    assign report_valid = i_ce && !event_empty;
    assign report_first = report_valid && (report_kind == 2'd0);
    assign report_last = report_valid && (report_kind == 2'd3);
    assign report_timed_out = !event_empty && event_timeout[event_read_index];
    assign event_pop = report_last;

    always @(*) begin
        for (event_slot = 0; event_slot < EVENT_DEPTH; event_slot = event_slot + 1) begin
            if (event_slot >= event_read_index)
                event_occupied[event_slot] = (event_slot - event_read_index) < event_count;
            else
                event_occupied[event_slot] = (EVENT_DEPTH + event_slot - event_read_index) < event_count;
        end
    end

    always @(*) begin
        report_word = COUNT_ZERO;
        if (!event_empty) begin
            case (report_kind)
                2'd0: report_word = event_budget[event_read_index];
                2'd1: report_word = event_duration[event_read_index];
                2'd2: report_word = event_unused[event_read_index];
                2'd3: report_word = event_timeout[event_read_index] ?
                                   COUNT_ONE : COUNT_ZERO;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            event_read <= 0;
            event_write <= 0;
            report_kind <= 0;
            for (event_reset = 0; event_reset < EVENT_DEPTH; event_reset = event_reset + 1) begin
                event_budget[event_reset] <= COUNT_ZERO;
                event_duration[event_reset] <= COUNT_ZERO;
                event_unused[event_reset] <= COUNT_ZERO;
                event_timeout[event_reset] <= 1'b0;
            end
        end else if (i_ce) begin
            if (event_reserve)
                event_budget[event_write_index] <= max_stretch;
            if (event_push) begin
                event_duration[event_write_index] <= stretch_duration;
                event_unused[event_write_index] <= watchdog_remaining;
                event_timeout[event_write_index] <= stretch_timeout;
                event_write <= event_write + 1'b1;
            end
            if (report_valid) begin
                if (report_kind == 2'd3) begin
                    report_kind <= 0;
                    event_read <= event_read + 1'b1;
                end else
                    report_kind <= report_kind + 1'b1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            high_pending <= 1'b0;
            stretching_active <= 1'b0;
            stretch_timeout <= 1'b0;
            stretch_duration <= COUNT_ZERO;
            max_stretch <= RESET_MAX_STRETCH;
            past_valid <= 1'b0;
        end else if (i_ce) begin
            past_valid <= 1'b1;
            if (!high_pending) begin
                stretching_active <= 1'b0;
                if (config_valid) begin
                    max_stretch <= config_max_stretch;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end else if (event_reserve) begin
                    high_pending <= 1'b1;
                    stretch_duration <= COUNT_ZERO;
                    stretch_timeout <= 1'b0;
                end
            end else if (scl_in) begin
                high_pending <= 1'b0;
                stretching_active <= 1'b0;
            end else begin
                stretching_active <= 1'b1;
                // Saturate the duration at the programmed stretch budget.
                if (watchdog_debit && (watchdog_remaining != COUNT_ZERO))
                    stretch_duration <= stretch_duration + COUNT_ONE;
                if (watchdog_debit && (watchdog_remaining <= COUNT_ONE))
                    stretch_timeout <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (past_valid && $rose(stretch_timeout))
            assert (stretch_duration == max_stretch);

    always @(posedge clk)
        if (past_valid && report_valid &&
            (report_kind == 2'd1) && report_timed_out)
            assert (report_word == event_budget[event_read_index]);
endmodule

module sklansky_result_channel #(
    parameter integer WIDTH = 32
) (
    input  wire                 clk,
    input  wire                 in_valid,
    output wire                 in_ready,
    input  wire [WIDTH-1:0]     in_a,
    input  wire [WIDTH-1:0]     in_b,
    output wire                 out_valid,
    input  wire                 out_ready,
    output wire [WIDTH-1:0]     out_sum,
    output wire                 out_carry
,
    output wire [WIDTH-1:0] operand_a_o,
    output wire [WIDTH-1:0] operand_b_o,
    output wire [WIDTH-1:0] prefix_hold_o,
    output wire [WIDTH-1:0] propagate_hold_o
);
    localparam integer LEVELS = $clog2(WIDTH);

    // Two storage slots: a captured-prefix tail and a reconstructed front.
    reg pending;
    reg window;
    reg [WIDTH-1:0] operand_a, operand_b;
    reg [WIDTH-1:0] propagate_hold, prefix_hold;
    reg [WIDTH-1:0] result_a, result_b;
    reg [WIDTH-1:0] result_sum;
    reg result_carry;

    wire [WIDTH-1:0] tree_g [0:LEVELS];
    wire [WIDTH-1:0] tree_p [0:LEVELS];

    assign tree_g[0] = in_a & in_b;
    assign tree_p[0] = in_a ^ in_b;

    // Sklansky tree: each upper half shares the lower half's root.
    genvar level, bit_index;
    generate
        for (level = 0; level < LEVELS; level = level + 1) begin : prefix_level
            localparam integer HALF = 1 << level;
            localparam integer GROUP = HALF << 1;
            for (bit_index = 0; bit_index < WIDTH; bit_index = bit_index + 1) begin : prefix_bit
                if ((bit_index % GROUP) >= HALF) begin : combine
                    localparam integer ROOT = (bit_index / GROUP) * GROUP + HALF - 1;
                    assign tree_g[level+1][bit_index] =
                        tree_g[level][bit_index] |
                        (tree_p[level][bit_index] & tree_g[level][ROOT]);
                    assign tree_p[level+1][bit_index] =
                        tree_p[level][bit_index] & tree_p[level][ROOT];
                end else begin : bypass
                    assign tree_g[level+1][bit_index] = tree_g[level][bit_index];
                    assign tree_p[level+1][bit_index] = tree_p[level][bit_index];
                end
            end
        end
    endgenerate

    wire [WIDTH-1:0] pending_sum;
    wire pending_carry;
    assign pending_sum = propagate_hold ^ (prefix_hold << 1);
    assign pending_carry = prefix_hold[WIDTH-1];

    // A lone prefix-slot item is directly visible: valid never waits for ready.
    assign out_valid = window || pending;
    assign out_sum = window ? result_sum : pending_sum;
    assign out_carry = window ? result_carry : pending_carry;
    assign in_ready = !(window && pending) || out_ready;

    wire push;
    wire pop;
    wire promote;
    assign push = in_valid && in_ready;
    assign pop = out_valid && out_ready;

    // Promote the tail when removing an occupied front, or when an arriving
    // item needs the occupied tail slot and the front is empty.
    assign promote = pending && ((pop && window) || (push && !pop));

    wire [WIDTH:0] reference_sum;
    assign reference_sum = window
        ? ({1'b0, result_a} + {1'b0, result_b})
        : ({1'b0, operand_a} + {1'b0, operand_b});

    initial begin
        pending = 1'b0;
        window = 1'b0;
        operand_a = {WIDTH{1'b0}};
        operand_b = {WIDTH{1'b0}};
        propagate_hold = {WIDTH{1'b0}};
        prefix_hold = {WIDTH{1'b0}};
        result_a = {WIDTH{1'b0}};
        result_b = {WIDTH{1'b0}};
        result_sum = {WIDTH{1'b0}};
        result_carry = 1'b0;
    end

    // Every register holds when in_valid and out_ready are both low.
    always @(posedge clk) begin
        if (pop) begin
            pending <= 1'b0;
            window <= 1'b0;
        end

        if (promote) begin
            result_a <= operand_a;
            result_b <= operand_b;
            result_sum <= pending_sum;
            result_carry <= pending_carry;
            window <= 1'b1;
        end

        if (push) begin
            operand_a <= in_a;
            operand_b <= in_b;
            propagate_hold <= tree_p[0];
            prefix_hold <= tree_g[LEVELS];
            pending <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (out_valid)
            assert ({out_carry, out_sum} == reference_sum);
    end
    assign operand_a_o = operand_a;
    assign operand_b_o = operand_b;
    assign prefix_hold_o = prefix_hold;
    assign propagate_hold_o = propagate_hold;
endmodule

module accumulator_rotate_merge #(
    parameter integer WORD_W = 128
) (
    input  wire clk,
    input  wire in_valid,
    output wire in_ready,
    input  wire in_config,
    input  wire [$clog2(WORD_W)-1:0] in_begin,
    input  wire [$clog2(WORD_W)-1:0] in_end,
    input  wire [$clog2(WORD_W)-1:0] in_shift,
    input  wire [WORD_W-1:0] in_operand,
    input  wire [WORD_W-1:0] in_destination,
    input  wire in_merge,
    output reg  out_valid,
    input  wire out_ready,
    output reg  [WORD_W-1:0] out_result
,
    output wire [WORD_W-1:0] bounds_mask_o,
    output wire [WORD_W-1:0] cached_mask_o
);
    localparam integer INDEX_W = $clog2(WORD_W);

    reg [INDEX_W-1:0] mask_begin;
    reg [INDEX_W-1:0] mask_end;
    reg [WORD_W-1:0] cached_mask;
    reg [WORD_W-1:0] accepted_mask_shadow;
    reg [WORD_W-1:0] accepted_base_shadow;

    function automatic [WORD_W-1:0] make_mask;
        input [INDEX_W-1:0] first_bit;
        input [INDEX_W-1:0] last_bit;
        integer bit_index;
        begin
            for (bit_index = 0; bit_index < WORD_W; bit_index = bit_index + 1) begin
                if (first_bit <= last_bit)
                    make_mask[bit_index] = (bit_index >= first_bit) &&
                                          (bit_index <= last_bit);
                else
                    make_mask[bit_index] = (bit_index >= first_bit) ||
                                          (bit_index <= last_bit);
            end
        end
    endfunction

    wire [WORD_W-1:0] bounds_mask = make_mask(mask_begin, mask_end);
    wire [WORD_W-1:0] incoming_mask = make_mask(in_begin, in_end);
    wire [2*WORD_W-1:0] rotated_pair =
        {in_operand, in_operand} << in_shift;
    wire [WORD_W-1:0] rotated_operand =
        rotated_pair[2*WORD_W-1:WORD_W];
    wire [WORD_W-1:0] merge_base =
        in_merge ? in_destination : {WORD_W{1'b0}};

    assign in_ready = !out_valid || out_ready;

    initial begin
        mask_begin = {INDEX_W{1'b0}};
        mask_end = {INDEX_W{1'b0}};
        cached_mask = {{(WORD_W-1){1'b0}}, 1'b1};
        accepted_mask_shadow = {WORD_W{1'b0}};
        accepted_base_shadow = {WORD_W{1'b0}};
        out_valid = 1'b0;
        out_result = {WORD_W{1'b0}};
    end

    always @(posedge clk) begin
        if (out_valid && out_ready)
            out_valid <= 1'b0;

        if (in_valid && in_ready) begin
            if (in_config) begin
                // Configuration packets program an inclusive, wrapping mask.
                mask_begin <= in_begin;
                mask_end <= in_end;
                cached_mask <= incoming_mask;
            end else begin
                // Execute packets rotate an accumulator word and optionally merge.
                out_result <= (rotated_operand & cached_mask) |
                              (merge_base & ~cached_mask);
                out_valid <= 1'b1;

                // Remember the earlier accepted command's permissions and baseline.
                accepted_mask_shadow <= bounds_mask;
                accepted_base_shadow <= merge_base;
            end
        end
    end

    // Every published change must have been authorized by the earlier command.
    always @(*) begin
        if (out_valid)
            assert (((out_result ^ accepted_base_shadow) &
                     ~accepted_mask_shadow) == {WORD_W{1'b0}});
    end
    assign bounds_mask_o = bounds_mask;
    assign cached_mask_o = cached_mask;
endmodule

module masked_index_address_pipeline #(
    parameter integer WIDTH = 32,
    parameter integer QUEUE_DEPTH = 4
) (
    input wire clk,
    input wire in_valid,
    output wire in_ready,
    input wire in_config,
    input wire [$clog2(WIDTH)-1:0] in_begin,
    input wire [$clog2(WIDTH)-1:0] in_end,
    input wire [$clog2(WIDTH)-1:0] in_shift,
    input wire [WIDTH-1:0] in_index,
    input wire [WIDTH-1:0] in_base,
    output wire out_valid,
    input wire out_ready,
    output wire [WIDTH-1:0] out_address,
    output wire out_carry,

    // Pipeline snapshots for tracing address transactions.
    output wire b_out_valid,
    output wire b_out_ready,
    output wire [WIDTH-1:0] b_out_result,
    output wire [WIDTH-1:0] b_bounds_mask,
    output wire [WIDTH-1:0] b_cached_mask,
    output wire [WIDTH-1:0] a_operand_a,
    output wire [WIDTH-1:0] a_operand_b,
    output wire [WIDTH-1:0] a_prefix_hold,
    output wire [WIDTH-1:0] a_propagate_hold,
    output reg [WIDTH-1:0] b_base_hold,
    output reg [$clog2(QUEUE_DEPTH+1)-1:0] queue_count,
    output wire [QUEUE_DEPTH*WIDTH-1:0] queued_offsets_o,
    output wire [QUEUE_DEPTH*WIDTH-1:0] queued_bases_o
);
    localparam integer COUNT_W = $clog2(QUEUE_DEPTH+1);
    reg [WIDTH-1:0] fifo_offset [0:QUEUE_DEPTH-1];
    reg [WIDTH-1:0] fifo_base [0:QUEUE_DEPTH-1];
    wire dispatch_valid;
    wire dispatch_ready;
    wire enqueue;
    wire dequeue;
    wire [COUNT_W-1:0] insert_at;
    integer slot;

    assign dispatch_valid = (queue_count != 0);
    assign dequeue = dispatch_valid && dispatch_ready;
    assign b_out_ready = (queue_count < QUEUE_DEPTH) || dequeue;
    assign enqueue = b_out_valid && b_out_ready;
    assign insert_at = queue_count - {{(COUNT_W-1){1'b0}}, dequeue};

    accumulator_rotate_merge #(.WORD_W(WIDTH)) index_stage (
        .clk(clk),
        .in_valid(in_valid),
        .in_ready(in_ready),
        .in_config(in_config),
        .in_begin(in_begin),
        .in_end(in_end),
        .in_shift(in_shift),
        .in_operand(in_index),
        .in_destination({WIDTH{1'b0}}),
        .in_merge(1'b0),
        .out_valid(b_out_valid),
        .out_ready(b_out_ready),
        .out_result(b_out_result),
        .bounds_mask_o(b_bounds_mask),
        .cached_mask_o(b_cached_mask)
    );

    sklansky_result_channel #(.WIDTH(WIDTH)) address_stage (
        .clk(clk),
        .in_valid(dispatch_valid),
        .in_ready(dispatch_ready),
        .in_a(fifo_offset[0]),
        .in_b(fifo_base[0]),
        .out_valid(out_valid),
        .out_ready(out_ready),
        .out_sum(out_address),
        .out_carry(out_carry),
        .operand_a_o(a_operand_a),
        .operand_b_o(a_operand_b),
        .prefix_hold_o(a_prefix_hold),
        .propagate_hold_o(a_propagate_hold)
    );

    // The result and its base reservation share B's output handshake.
    // Configurations do not reserve a base or enter the address FIFO.
    initial begin
        b_base_hold = {WIDTH{1'b0}};
        queue_count = {COUNT_W{1'b0}};
        for (slot = 0; slot < QUEUE_DEPTH; slot = slot + 1) begin
            fifo_offset[slot] = {WIDTH{1'b0}};
            fifo_base[slot] = {WIDTH{1'b0}};
        end
    end

    always @(posedge clk) begin
        if (in_valid && in_ready && !in_config)
            b_base_hold <= in_base & ~b_cached_mask;

        case ({enqueue, dequeue})
            2'b10: queue_count <= queue_count + 1'b1;
            2'b01: queue_count <= queue_count - 1'b1;
            default: queue_count <= queue_count;
        endcase

        // A compact shift FIFO supports a full-queue simultaneous exchange.
        if (dequeue) begin
            for (slot = 0; slot < QUEUE_DEPTH-1; slot = slot + 1) begin
                fifo_offset[slot] <= fifo_offset[slot+1];
                fifo_base[slot] <= fifo_base[slot+1];
            end
        end
        if (enqueue) begin
            fifo_offset[insert_at] <= b_out_result;
            fifo_base[insert_at] <= b_base_hold;
        end
    end

    genvar entry;
    generate
        for (entry = 0; entry < QUEUE_DEPTH; entry = entry + 1) begin : queue_view
            assign queued_offsets_o[entry*WIDTH +: WIDTH] = fifo_offset[entry];
            assign queued_bases_o[entry*WIDTH +: WIDTH] = fifo_base[entry];
        end
    endgenerate

    // The selected index field must not overflow the normalized base.
    always @(posedge clk) begin
        if (out_valid)
            assert (!out_carry);
    end
endmodule

module prescaler_event_queue #(
    parameter [63:0] P = 64'd4,
parameter [63:0] DEPTH = 64'd32,
parameter PREFETCH_DEPTH = 4,
parameter PEER_DEPTH = 4,
parameter PEER_BATCH = 5
) (
    input  wire        clk,
    input  wire        i_pulse_valid,
    output wire        o_pulse_ready,
    input  wire        i_mode,
    output wire        o_valid,
    input  wire        i_out_ready,
output wire [63:0] o_data,
output wire [$clog2(PREFETCH_DEPTH):0] o_prefetch_level,
input wire i_peer_valid,
input wire [63:0] i_peer_data,
output wire o_peer_ready,
output wire [$clog2(PEER_DEPTH):0] o_peer_level,
output wire o_output_peer,
output reg [3:0] o_diag_status
);
    // Supported modulus settings: 3 <= P <= 16.
    // First accepted pulse: ARM and sample mode.
    // Second accepted pulse: START.
    // Pulse P or P+1: FINISH and enqueue its event record.
    localparam [63:0] IDLE  = 64'd0;
    localparam [63:0] ARMED = 64'd1;
    localparam [63:0] RUN   = 64'd2;

// The read-ahead FIFO supports power-of-two depths, normally 4 or 8.
localparam PREFETCH_ADDR_W = $clog2(PREFETCH_DEPTH);
localparam EVENT_ADDR_W = $clog2(DEPTH);
localparam CHANNELS = 2;
localparam CHANNEL_W = $clog2(CHANNELS);
localparam PEER_ADDR_W = $clog2(PEER_DEPTH);
localparam PEER_BEAT_W = $clog2(PEER_BATCH);

    reg [63:0] phase;
    reg [63:0] pulse_count;
    reg mode_q;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    reg [63:0] event_mem [0:DEPTH-1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] fifo_count;

    wire [63:0] modulus;
    wire pulse_fire;
    wire finish_fire;
    wire pop_fire;
    wire [DEPTH-1:0] filled;

reg [63:0] prefetch_mem [0:PREFETCH_DEPTH-1];
reg [PREFETCH_ADDR_W:0] prefetch_rd_ptr;
reg [PREFETCH_ADDR_W:0] prefetch_wr_ptr;
reg [EVENT_ADDR_W-1:0] fetch_addr;
reg read_valid;
reg [63:0] read_data;
reg head_valid;
reg [63:0] head_data;

wire [PREFETCH_ADDR_W-1:0] prefetch_rd_index;
wire [PREFETCH_ADDR_W-1:0] prefetch_wr_index;
wire [PREFETCH_ADDR_W:0] prefetch_used;
wire [PREFETCH_ADDR_W:0] prefetch_level;
wire prefetch_empty;
wire prefetch_full;
wire fetch_available;
wire read_ready;
wire fetch_fire;
wire enqueue_fire;
wire head_ready;
wire refill_fire;

// Independent sample signatures join the completed-event output.
reg [63:0] peer_mem [0:PEER_DEPTH-1];
reg [PEER_ADDR_W-1:0] peer_rd_ptr;
reg [PEER_ADDR_W-1:0] peer_wr_ptr;
reg [PEER_ADDR_W:0] peer_count;
reg [PEER_BEAT_W-1:0] peer_beats;
reg [63:0] peer_fold;
reg [CHANNEL_W-1:0] rr_lane;
reg [CHANNEL_W-1:0] grant_owner;
reg grant_locked;
reg [CHANNEL_W-1:0] output_lane;
wire [PEER_DEPTH-1:0] peer_filled;
wire [60:0] peer_payload;
wire [63:0] peer_next;
wire peer_input_fire;
wire peer_commit;
wire peer_pop;
wire shared_fire;
reg [63:0] stream_held;
integer peer_init;
integer held_slot;

assign o_peer_ready = peer_count < PEER_DEPTH;
assign o_peer_level = peer_count;
assign peer_input_fire = i_peer_valid && o_peer_ready;
assign peer_commit = peer_input_fire && (peer_beats == PEER_BATCH - 1);
assign peer_payload = i_peer_data[60:0] ^ {58'd0, i_peer_data[63:61]};
// Open on sample one, start on sample two; bit 61 identifies signatures.
assign peer_next = {(peer_fold[63] || (peer_beats == 0)),
                    (peer_fold[62] || (peer_beats == 1)),
                    1'b1, peer_fold[60:0] ^ peer_payload};
assign shared_fire = o_valid && i_out_ready;
assign o_output_peer = output_lane == 1'b1;
assign peer_pop = shared_fire && o_output_peer;

always @(*) begin
    if (grant_locked)
        output_lane = grant_owner;
    else if (head_valid && (peer_count != 0))
        output_lane = rr_lane;
    else
        output_lane = head_valid ? 1'b0 : 1'b1;
end

// A stalled transfer owns its grant until the receiver accepts it.
always @(posedge clk) begin
    if (shared_fire) begin
        grant_locked <= 1'b0;
        rr_lane <= ~output_lane;
    end else if (o_valid) begin
        grant_locked <= 1'b1;
        grant_owner <= output_lane;
    end
end

genvar peer_slot;
generate
    for (peer_slot = 0; peer_slot < PEER_DEPTH; peer_slot = peer_slot + 1) begin : signature_slots
        localparam [PEER_ADDR_W:0] SLOT = peer_slot;
        assign peer_filled[peer_slot] = ((SLOT >= peer_rd_ptr)
            ? (SLOT - peer_rd_ptr)
            : (SLOT + PEER_DEPTH - peer_rd_ptr)) < peer_count;
    end
endgenerate

initial begin
    peer_rd_ptr = {PEER_ADDR_W{1'b0}};
    peer_wr_ptr = {PEER_ADDR_W{1'b0}};
    peer_count = {(PEER_ADDR_W+1){1'b0}};
    peer_beats = {PEER_BEAT_W{1'b0}};
    peer_fold = 64'd0;
    rr_lane = {CHANNEL_W{1'b0}};
    grant_owner = {CHANNEL_W{1'b0}};
    grant_locked = 1'b0;
    for (peer_init = 0; peer_init < PEER_DEPTH; peer_init = peer_init + 1)
        peer_mem[peer_init] = 64'd0;
end

always @(posedge clk) begin
    if (peer_input_fire) begin
        if (peer_commit) begin
            peer_beats <= {PEER_BEAT_W{1'b0}};
            peer_fold <= 64'd0;
        end else begin
            peer_beats <= peer_beats + 1'b1;
            peer_fold <= peer_next;
        end
    end
    if (peer_commit) begin
        peer_mem[peer_wr_ptr] <= peer_next;
        if (peer_wr_ptr == PEER_DEPTH - 1)
            peer_wr_ptr <= {PEER_ADDR_W{1'b0}};
        else
            peer_wr_ptr <= peer_wr_ptr + 1'b1;
    end
    if (peer_pop) begin
        if (peer_rd_ptr == PEER_DEPTH - 1)
            peer_rd_ptr <= {PEER_ADDR_W{1'b0}};
        else
            peer_rd_ptr <= peer_rd_ptr + 1'b1;
    end
    case ({peer_commit, peer_pop})
        2'b10: peer_count <= peer_count + 1'b1;
        2'b01: peer_count <= peer_count - 1'b1;
        default: begin end
    endcase
end

// Express outstanding work in accepted input beats, including partial groups.
always @(*) begin
    stream_held = pulse_count + peer_beats
                + fifo_count * P + peer_count * PEER_BATCH;
    for (held_slot = 0; held_slot < DEPTH; held_slot = held_slot + 1)
        if (filled[held_slot] && event_mem[held_slot][61])
            stream_held = stream_held + 64'd1;
end

    assign modulus = mode_q ? P + 64'd1 : P;
    assign o_pulse_ready = fifo_count < DEPTH;
    assign pulse_fire = i_pulse_valid && o_pulse_ready;
    assign finish_fire = pulse_fire && (phase == RUN)
                         && (pulse_count == modulus - 64'd1);
assign o_valid = grant_locked || head_valid || (peer_count != 0);
assign o_data = o_output_peer ? peer_mem[peer_rd_ptr] : head_data;
    assign pop_fire = shared_fire && !o_output_peer;

assign prefetch_rd_index =
    prefetch_rd_ptr[PREFETCH_ADDR_W-1:0];
assign prefetch_wr_index =
    prefetch_wr_ptr[PREFETCH_ADDR_W-1:0];
assign prefetch_used = prefetch_wr_ptr - prefetch_rd_ptr;
assign prefetch_level = prefetch_used
    + {{PREFETCH_ADDR_W{1'b0}}, head_valid}
    + {{PREFETCH_ADDR_W{1'b0}}, read_valid};
assign prefetch_empty = prefetch_wr_ptr == prefetch_rd_ptr;
assign prefetch_full =
    (prefetch_wr_ptr[PREFETCH_ADDR_W] != prefetch_rd_ptr[PREFETCH_ADDR_W])
    && (prefetch_wr_index == prefetch_rd_index);
assign fetch_available = prefetch_level < fifo_count;
assign read_ready = !read_valid || !prefetch_full;
assign fetch_fire = fetch_available && read_ready;
assign enqueue_fire = read_valid && !prefetch_full;
assign head_ready = !head_valid || pop_fire;
assign refill_fire = !prefetch_empty && head_ready;
assign o_prefetch_level = prefetch_level;

    // Filled slots are the circular interval starting at rd_ptr.
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupied_slots
            localparam [63:0] ENTRY = g;
            assign filled[g] = ((ENTRY >= rd_ptr)
                              ? (ENTRY - rd_ptr)
                              : (ENTRY + DEPTH - rd_ptr)) < fifo_count;
        end
    endgenerate

// Read-only telemetry, serialized least-significant nibble first.
reg [5:0] diag_tick;
reg [15:0] diag_accepted;
reg [15:0] diag_completed;
reg [15:0] diag_delivered;
reg [15:0] diag_blocked_cycles;
reg [15:0] diag_stall_run;
reg [15:0] diag_stall_peak;
reg [15:0] diag_stall_episodes;
reg [15:0] diag_idle_age;
reg [15:0] diag_event_gap;
reg [15:0] diag_gap_peak;
reg [63:0] diag_watermark;
reg [3:0] diag_sticky;
reg [31:0] diag_signature;
reg [255:0] diag_scan;
initial begin
    diag_tick = 6'd0;
    diag_accepted = 16'd0;
    diag_completed = 16'd0;
    diag_delivered = 16'd0;
    diag_blocked_cycles = 16'd0;
    diag_stall_run = 16'd0;
    diag_stall_peak = 16'd0;
    diag_stall_episodes = 16'd0;
    diag_idle_age = 16'd0;
    diag_event_gap = 16'd0;
    diag_gap_peak = 16'd0;
    diag_watermark = 64'd0;
    diag_sticky = 4'd0;
    diag_signature = 32'd0;
    diag_scan = 256'd0;
    o_diag_status = 4'd0;
end

always @(posedge clk) begin
    diag_tick <= diag_tick + 6'd1;
    if (pulse_fire && (diag_accepted != 16'hffff))
        diag_accepted <= diag_accepted + 16'd1;
    if (finish_fire && (diag_completed != 16'hffff))
        diag_completed <= diag_completed + 16'd1;
    if (pop_fire) begin
        if (diag_delivered != 16'hffff)
            diag_delivered <= diag_delivered + 16'd1;
        diag_signature <= {diag_signature[26:0], diag_signature[31:27]}
                          ^ o_data[31:0] ^ o_data[63:32];
    end
    if (i_pulse_valid && !o_pulse_ready) begin
        diag_sticky[1] <= 1'b1;
        if (diag_blocked_cycles != 16'hffff)
            diag_blocked_cycles <= diag_blocked_cycles + 16'd1;
    end
    if (o_valid && !i_out_ready) begin
        if (diag_stall_run != 16'hffff)
            diag_stall_run <= diag_stall_run + 16'd1;
        if ((diag_stall_run == 16'd0)
            && (diag_stall_episodes != 16'hffff))
            diag_stall_episodes <= diag_stall_episodes + 16'd1;
        if (diag_stall_run == 16'd1023)
            diag_sticky[0] <= 1'b1;
    end else
        diag_stall_run <= 16'd0;
    if (diag_stall_run > diag_stall_peak)
        diag_stall_peak <= diag_stall_run;
    if (pulse_fire || pop_fire)
        diag_idle_age <= 16'd0;
    else if (diag_idle_age != 16'hffff)
        diag_idle_age <= diag_idle_age + 16'd1;
    if (diag_idle_age == 16'hffff)
        diag_sticky[3] <= 1'b1;
    if (finish_fire)
        diag_event_gap <= 16'd0;
    else if (diag_event_gap != 16'hffff)
        diag_event_gap <= diag_event_gap + 16'd1;
    if (finish_fire && (diag_event_gap > diag_gap_peak))
        diag_gap_peak <= diag_event_gap;
    if (fifo_count > diag_watermark)
        diag_watermark <= fifo_count;
    if (fifo_count == DEPTH)
        diag_sticky[2] <= 1'b1;
    if (diag_tick == 6'd0) begin
        diag_scan <= {28'hd1a6001, diag_sticky,
                      diag_signature, diag_watermark,
                      diag_accepted, diag_completed,
                      diag_delivered, diag_blocked_cycles,
                      diag_stall_peak, diag_idle_age,
                      diag_stall_episodes, diag_gap_peak};
    end else
        diag_scan <= {4'd0, diag_scan[255:4]};
    o_diag_status <= diag_scan[3:0];
end

    integer j;
    initial begin
        phase = IDLE;
        pulse_count = 64'd0;
        mode_q = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        scope_armed = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        fifo_count = 64'd0;
prefetch_rd_ptr = {(PREFETCH_ADDR_W+1){1'b0}};
prefetch_wr_ptr = {(PREFETCH_ADDR_W+1){1'b0}};
fetch_addr = {EVENT_ADDR_W{1'b0}};
read_valid = 1'b0;
read_data = 64'd0;
head_valid = 1'b0;
head_data = 64'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            event_mem[j] = 64'd0;
for (j = 0; j < PREFETCH_DEPTH; j = j + 1)
    prefetch_mem[j] = 64'd0;
    end

    always @(posedge clk) begin
        if (pulse_fire) begin
            case (phase)
                IDLE: begin
                    // Q is the ARM event; its scope latch never clears.
                    scope_armed <= 1'b1;
                    mode_q <= i_mode;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    pulse_count <= 64'd1;
                    phase <= ARMED;
                end
                ARMED: begin
                    start_seen <= 1'b1;
                    pulse_count <= 64'd2;
                    phase <= RUN;
                end
                RUN: begin
                    if (finish_fire) begin
                        pulse_count <= 64'd0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= IDLE;
                    end else begin
                        pulse_count <= pulse_count + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    pulse_count <= 64'd0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end

        if (finish_fire) begin
            // Record: ARM witness, START witness, sampled mode,
            // and the number of accepted pulses in this division.
            event_mem[wr_ptr] <= (pulse_count + 64'd1)
                | (arm_seen ? 64'h8000000000000000 : 64'd0)
                | (start_seen ? 64'h4000000000000000 : 64'd0)
                | (mode_q ? 64'h2000000000000000 : 64'd0);
            wr_ptr <= (wr_ptr == DEPTH - 64'd1)
                    ? 64'd0 : wr_ptr + 64'd1;
        end
        if (pop_fire)
            rd_ptr <= (rd_ptr == DEPTH - 64'd1)
                    ? 64'd0 : rd_ptr + 64'd1;

        case ({finish_fire, pop_fire})
            2'b10: fifo_count <= fifo_count + 64'd1;
            2'b01: fifo_count <= fifo_count - 64'd1;
            default: begin end
        endcase
    end

// A stalled read response keeps its data and reserves its backing slot.
always @(posedge clk) begin
    if (read_ready)
        read_valid <= fetch_fire;
    if (fetch_fire) begin
        read_data <= event_mem[fetch_addr];
        if (fetch_addr == DEPTH - 64'd1)
            fetch_addr <= {EVENT_ADDR_W{1'b0}};
        else
            fetch_addr <= fetch_addr + 1'b1;
    end
end

always @(posedge clk) begin
    if (enqueue_fire) begin
        prefetch_mem[prefetch_wr_index] <= read_data;
        prefetch_wr_ptr <= prefetch_wr_ptr + 1'b1;
    end
    if (refill_fire)
        prefetch_rd_ptr <= prefetch_rd_ptr + 1'b1;
end

// Backing slots are released by pop_fire, not by speculative reads.
always @(posedge clk) begin
    if (head_ready) begin
        head_valid <= refill_fire;
        if (refill_fire)
            head_data <= prefetch_mem[prefetch_rd_index];
    end
end

    // After Q: START requires ARM, and every observable FINISH
    // must carry both earlier event witnesses.
    always @(posedge clk)
        if (scope_armed)
            assert ((!start_seen || arm_seen)
                    && (!o_valid || (o_data[63] && o_data[62])));
endmodule

module pixel_pulse_pending #(
    parameter integer COUNT_W = 32
) (
    input wire clk,
    input wire i_ce,
    input wire i_pixel_pulse,
    input wire i_dispatch,
    input wire i_slow_tick,
    input wire i_load_limit,
    input wire [COUNT_W-1:0] i_limit,
    input wire i_begin_tile,
    input wire i_end_tile,
input wire i_peer_pixel_pulse,
output reg slow_pixel_pulse,
output wire pixel_ready,
output wire peer_ready,
output reg peer_slow_pixel_pulse,
input wire i_aux_pixel_pulse,
input wire [COUNT_W-1:0] i_aux_data,
output wire aux_ready,
output reg [COUNT_W-1:0] aux_data,
output reg aux_slow_pixel_pulse
);
    localparam [COUNT_W-1:0] ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
localparam integer CHANNELS = 3, PEER_DEPTH = 7;
localparam integer PEER_W = $clog2(PEER_DEPTH + 1);
localparam integer AUX_DEPTH = 4, AUX_ADDR_W = $clog2(AUX_DEPTH);
localparam integer AUX_PTR_W = AUX_ADDR_W + 1;

    reg [COUNT_W-1:0] pending;
    reg [COUNT_W-1:0] outstanding;
    reg [COUNT_W-1:0] pulse_limit;
    reg req_toggle;
    reg ack_toggle;
    reg window_open;
    reg pv;
reg peer_valid [0:PEER_DEPTH-1];
reg [PEER_W-1:0] peer_outstanding;
reg [$clog2(CHANNELS)-1:0] flight_lane;
integer k;
reg [COUNT_W-1:0] aux_fifo [0:AUX_DEPTH-1];
reg [AUX_PTR_W-1:0] aux_wr, aux_rd;
reg [AUX_PTR_W-1:0] aux_outstanding;
reg [COUNT_W-1:0] aux_mailbox;

    wire in_flight = (req_toggle != ack_toggle);
    wire accept_pulse = i_pixel_pulse && (outstanding < pulse_limit);
    wire launch_request = i_dispatch && !in_flight && (pending != ZERO);
wire retire_request = i_slow_tick && in_flight && (flight_lane == 1'b0);
wire peer_launch = i_dispatch && !in_flight && (pending == ZERO) && peer_valid[PEER_DEPTH-1];
wire peer_shift = !peer_valid[PEER_DEPTH-1] || peer_launch;
wire peer_retire = i_slow_tick && in_flight && (flight_lane == 1'b1);
wire peer_accept = i_peer_pixel_pulse && peer_ready;
assign pixel_ready = i_ce && (outstanding < pulse_limit);
assign peer_ready = i_ce && peer_shift && (peer_outstanding < PEER_DEPTH);
wire [AUX_PTR_W-1:0] aux_queued = aux_wr - aux_rd;
wire aux_launch = i_dispatch && !in_flight && (pending == ZERO)
                  && !peer_valid[PEER_DEPTH-1] && (aux_queued != 0);
wire aux_retire = i_slow_tick && in_flight && (flight_lane == 2'd2);
wire aux_accept = i_aux_pixel_pulse && aux_ready;
assign aux_ready = i_ce && (aux_outstanding < AUX_DEPTH);

    initial begin
        pending = ZERO;
        outstanding = ZERO;
        pulse_limit = {COUNT_W{1'b1}};
        req_toggle = 1'b0;
        ack_toggle = 1'b0;
        window_open = 1'b0;
        slow_pixel_pulse = 1'b0;
        pv = 1'b0;
for (k = 0; k < PEER_DEPTH; k = k + 1) peer_valid[k] = 1'b0;
peer_outstanding = 0;
flight_lane = 0;
peer_slow_pixel_pulse = 1'b0;
for (k = 0; k < AUX_DEPTH; k = k + 1) aux_fifo[k] = ZERO;
aux_wr = 0;
aux_rd = 0;
aux_outstanding = 0;
aux_mailbox = ZERO;
aux_data = ZERO;
aux_slow_pixel_pulse = 1'b0;
    end

    // i_slow_tick models an edge of the slower receiving domain.
    // Requests remain outstanding until that domain acknowledges them.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            if (i_load_limit)
                pulse_limit <= i_limit;

            if (i_end_tile)
                window_open <= 1'b0;
            else if (i_begin_tile)
                window_open <= 1'b1;

            case ({accept_pulse, launch_request})
                2'b10: pending <= pending + ONE;
                2'b01: pending <= pending - ONE;
                default: pending <= pending;
            endcase

            case ({accept_pulse, retire_request})
                2'b10: outstanding <= outstanding + ONE;
                2'b01: outstanding <= outstanding - ONE;
                default: outstanding <= outstanding;
            endcase
if (peer_shift) begin
    for (k = PEER_DEPTH-1; k > 0; k = k - 1)
        peer_valid[k] <= peer_valid[k-1];
    peer_valid[0] <= peer_accept;
end
case ({peer_accept, peer_retire})
    2'b10: peer_outstanding <= peer_outstanding + 1'b1;
    2'b01: peer_outstanding <= peer_outstanding - 1'b1;
    default: peer_outstanding <= peer_outstanding;
endcase
if (aux_accept) begin
    aux_fifo[aux_wr[AUX_ADDR_W-1:0]] <= i_aux_data;
    aux_wr <= aux_wr + 1'b1;
end
if (aux_launch) begin
    aux_mailbox <= aux_fifo[aux_rd[AUX_ADDR_W-1:0]];
    aux_rd <= aux_rd + 1'b1;
end
case ({aux_accept, aux_retire})
    2'b10: aux_outstanding <= aux_outstanding + 1'b1;
    2'b01: aux_outstanding <= aux_outstanding - 1'b1;
    default: aux_outstanding <= aux_outstanding;
endcase

if (launch_request || peer_launch || aux_launch)
                req_toggle <= !req_toggle;
if (launch_request || peer_launch || aux_launch)
    flight_lane <= aux_launch ? 2'd2 : (peer_launch ? 2'd1 : 2'd0);

if (retire_request || peer_retire || aux_retire)
                ack_toggle <= req_toggle;

            slow_pixel_pulse <= retire_request;
peer_slow_pixel_pulse <= peer_retire;
aux_slow_pixel_pulse <= aux_retire;
if (aux_retire)
    aux_data <= aux_mailbox;
        end
    end

    // The registered pulse reports the preceding enabled edge's delivery.
    // Inside the previous tile window, delivery and an empty work ledger
    // must never have occurred together on that edge.
    always @(posedge clk) begin
        if (pv && $past(window_open) && $past(i_ce))
            assert (!(slow_pixel_pulse && ($past(outstanding) == ZERO)));
    end
always @(posedge clk) begin
    if (pv && $past(i_ce))
        assert (!(peer_slow_pixel_pulse && ($past(peer_outstanding) == 0)));
end
always @(posedge clk) begin
    if (pv && $past(i_ce))
        assert (!(aux_slow_pixel_pulse && ($past(aux_outstanding) == 0)));
end
endmodule

module duty_phase_plan #(
    parameter integer WORD_W = 64,
    parameter integer PHASES = 4,
    parameter integer COUNT_W = $clog2(PHASES+1)
) (
    input  wire                         clk,
    input  wire                         load_valid,
    output wire                         load_ready,
    input  wire [WORD_W-1:0]            high_ticks,
    output wire                         plan_valid,
    input  wire                         plan_ready,
    output wire [PHASES*WORD_W-1:0]     falling_edges,
    output wire [PHASES-1:0]            wraps,
    output reg  [COUNT_W-1:0]           populated
);
    localparam integer PHASE_BITS = $clog2(PHASES);
    localparam [WORD_W:0] STEP =
        {1'b1, {WORD_W{1'b0}}} >> PHASE_BITS;
    reg [WORD_W-1:0] edges [0:PHASES-1];
    reg [PHASES-1:0] wrap_bits;
    integer init_index;
    genvar phase;

    assign load_ready = populated == 0;
    assign plan_valid = populated == PHASES;
    assign wraps = wrap_bits;
    generate
        for (phase = 0; phase < PHASES; phase = phase + 1) begin : export_edges
            assign falling_edges[phase*WORD_W +: WORD_W] = edges[phase];
        end
    endgenerate
    wire load = load_valid && load_ready;
    wire retire = plan_valid && plan_ready;

    initial begin
        populated = 0;
        wrap_bits = 0;
        for (init_index = 0; init_index < PHASES; init_index = init_index + 1)
            edges[init_index] = {WORD_W{1'b0}};
    end

    always @(posedge clk) begin
        if (load) begin
            edges[0] <= high_ticks;
            wrap_bits[0] <= 1'b0;
            populated <= 1;
        end else if (populated != 0 && populated < PHASES) begin
            {wrap_bits[populated], edges[populated]} <=
                {wrap_bits[populated-1'b1], edges[populated-1'b1]} + STEP;
            populated <= populated + 1'b1;
        end else if (retire)
            populated <= 0;
    end
endmodule

module duty_cycle_corrector #(
    parameter integer WORD_W = 64,
    parameter integer PHASES = 4
) (
    input  wire                  clk,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     in_high_ticks,
    input  wire [WORD_W-1:0]     in_low_ticks,
    output wire                  out_valid,
    input  wire                  out_ready,
    output wire [WORD_W-1:0]     out_high_ticks,
    output reg  [WORD_W-1:0]     applied_high_time,
    input  wire                  peer_valid,
    output wire                  peer_ready,
    input  wire [WORD_W-1:0]     peer_high_ticks,
    input  wire [WORD_W-1:0]     peer_low_ticks,
    output reg                   peer_active,
    output wire [PHASES*WORD_W-1:0] phase_fall_ticks,
    output wire [PHASES-1:0]     phase_wraps
);
    localparam [WORD_W-1:0] ZERO = {WORD_W{1'b0}};
    localparam [WORD_W-1:0] ONE = {{(WORD_W-1){1'b0}}, 1'b1};
    localparam [WORD_W-1:0] HALF_SCALE = {1'b1, {(WORD_W-1){1'b0}}};
    localparam integer CHANNELS = 2, PEER_DEPTH = 4;
    localparam integer PEER_PTR_W = $clog2(PEER_DEPTH), PEER_COUNT_W = $clog2(PEER_DEPTH+1);
    localparam integer PHASE_COUNT_W = $clog2(PHASES+1);
    localparam [WORD_W:0] PHASE_STEP =
        {1'b1, {WORD_W{1'b0}}} >> $clog2(PHASES);

    reg [WORD_W-1:0] high_shadow;
    reg [WORD_W-1:0] low_shadow;
    reg [WORD_W-1:0] correction_code;
    reg pending;
    reg armed;
    reg pv;
    reg [WORD_W-1:0] peer_high_q [0:PEER_DEPTH-1], peer_low_q [0:PEER_DEPTH-1];
    reg [PEER_PTR_W-1:0] peer_rd, peer_wr;
    reg [PEER_COUNT_W-1:0] peer_count;
    integer peer_idx;
    wire [CHANNELS-1:0] lane_valid = {peer_active, pending};
    wire phase_load_ready, phase_plan_valid;
    wire [PHASE_COUNT_W-1:0] phase_entries;

    // The code is a two's-complement adjustment in high-time units.
    // Halving each measured interval avoids overflowing the imbalance.
    wire [WORD_W-1:0] shadow_half_imbalance =
        (high_shadow >> ONE) - (low_shadow >> ONE);
    wire [WORD_W-1:0] reference_high =
        HALF_SCALE - shadow_half_imbalance;

    assign in_ready = !(|lane_valid) && phase_load_ready;
    assign out_valid = (|lane_valid) && phase_plan_valid;
    assign out_high_ticks = HALF_SCALE + correction_code;
    assign peer_ready = peer_count < PEER_DEPTH;

    wire take_measurement = in_valid && in_ready;
    wire apply_correction = pending && phase_plan_valid && out_ready;
    wire enqueue_peer = peer_valid && peer_ready;
    wire finish_peer = peer_active && phase_plan_valid && out_ready;
    wire start_peer = in_ready && !in_valid && (peer_count != 0);
    wire phase_load_valid = take_measurement || start_peer;
    wire [WORD_W-1:0] selected_high = start_peer ? peer_high_q[peer_rd] : in_high_ticks;
    wire [WORD_W-1:0] selected_low = start_peer ? peer_low_q[peer_rd] : in_low_ticks;
    wire [WORD_W-1:0] selected_correction =
        (selected_low >> ONE) - (selected_high >> ONE);

    duty_phase_plan #(.WORD_W(WORD_W), .PHASES(PHASES)) phase_plan (
        .clk(clk), .load_valid(phase_load_valid),
        .load_ready(phase_load_ready),
        .high_ticks(HALF_SCALE + selected_correction),
        .plan_valid(phase_plan_valid), .plan_ready(out_ready),
        .falling_edges(phase_fall_ticks), .wraps(phase_wraps),
        .populated(phase_entries)
    );

    initial begin
        high_shadow = ZERO;
        low_shadow = ZERO;
        correction_code = ZERO;
        applied_high_time = HALF_SCALE;
        pending = 1'b0;
        armed = 1'b0;
        pv = 1'b0;
        peer_rd = 0; peer_wr = 0;
        peer_count = 0; peer_active = 1'b0;
        for (peer_idx = 0; peer_idx < PEER_DEPTH; peer_idx = peer_idx + 1)
            {peer_high_q[peer_idx], peer_low_q[peer_idx]} = {ZERO, ZERO};
    end

    always @(posedge clk) begin
        if (take_measurement || start_peer)
            correction_code <= selected_correction;
        if (enqueue_peer) begin
            {peer_high_q[peer_wr], peer_low_q[peer_wr]} <= {peer_high_ticks, peer_low_ticks};
            peer_wr <= peer_wr + 1'b1;
        end
        if (start_peer || finish_peer) peer_active <= start_peer;
        if (finish_peer) peer_rd <= peer_rd + 1'b1;
        case ({enqueue_peer, finish_peer})
            2'b10: peer_count <= peer_count + 1'b1;
            2'b01: peer_count <= peer_count - 1'b1;
        endcase
        if (take_measurement) begin
            high_shadow <= in_high_ticks;
            low_shadow <= in_low_ticks;
            pending <= 1'b1;
            // Q: the first accepted duty-cycle measurement.
            armed <= 1'b1;
        end

        if (apply_correction) begin
            applied_high_time <= out_high_ticks;
            pending <= 1'b0;
        end

        // No checker state changes during an idle cycle either.
        if (take_measurement || apply_correction)
            pv <= 1'b1;
    end
    always @(posedge clk)
        if (peer_active && out_ready)
            assert (!pending && (out_high_ticks == HALF_SCALE - ((peer_high_q[peer_rd] >> ONE) - (peer_low_q[peer_rd] >> ONE))));

    integer phase_check;
    always @(posedge clk)
        if (out_valid && out_ready)
            for (phase_check = 0; phase_check < PHASES; phase_check = phase_check + 1)
                assert (({phase_wraps[phase_check],
                          phase_fall_ticks[phase_check*WORD_W +: WORD_W]}
                         - PHASE_STEP * phase_check) == {1'b0, out_high_ticks});

    // Once armed, a committed setting must agree with the measurement
    // shadows that already existed in the previous cycle.
    always @(posedge clk)
        if (pv && armed && !pending)
            assert (applied_high_time == $past(reference_high));
endmodule

module prescaler_event_queue #(
    parameter [63:0] P = 64'd4,
parameter [63:0] DEPTH = 64'd32,
parameter PREFETCH_DEPTH = 4,
parameter PEER_DEPTH = 4
) (
    input  wire        clk,
    input  wire        i_pulse_valid,
    output wire        o_pulse_ready,
    input  wire        i_mode,
    output wire        o_valid,
    input  wire        i_out_ready,
output wire [63:0] o_data,
output wire [$clog2(PREFETCH_DEPTH):0] o_prefetch_level,
input wire i_peer_valid,
input wire [63:0] i_peer_data,
output wire o_peer_ready,
output wire o_peer,
output wire o_peer_last
);
    // Supported modulus settings: 3 <= P <= 16.
    // First accepted pulse: ARM and sample mode.
    // Second accepted pulse: START.
    // Pulse P or P+1: FINISH and enqueue its event record.
    localparam [63:0] IDLE  = 64'd0;
    localparam [63:0] ARMED = 64'd1;
    localparam [63:0] RUN   = 64'd2;

// The read-ahead FIFO supports power-of-two depths, normally 4 or 8.
localparam PREFETCH_ADDR_W = $clog2(PREFETCH_DEPTH);
localparam EVENT_ADDR_W = $clog2(DEPTH);
localparam CHANNELS = 2;
localparam PEER_ADDR_W = $clog2(PEER_DEPTH);
localparam HELD_W = $clog2((DEPTH + 1) * (P + 1) + PEER_DEPTH + 1);

    reg [63:0] phase;
    reg [63:0] pulse_count;
    reg mode_q;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    reg [63:0] event_mem [0:DEPTH-1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] fifo_count;

    wire [63:0] modulus;
    wire pulse_fire;
    wire finish_fire;
    wire pop_fire;
    wire [DEPTH-1:0] filled;

reg [63:0] prefetch_mem [0:PREFETCH_DEPTH-1];
reg [PREFETCH_ADDR_W:0] prefetch_rd_ptr;
reg [PREFETCH_ADDR_W:0] prefetch_wr_ptr;
reg [EVENT_ADDR_W-1:0] fetch_addr;
reg read_valid;
reg [63:0] read_data;
reg head_valid;
reg [63:0] head_data;

wire [PREFETCH_ADDR_W-1:0] prefetch_rd_index;
wire [PREFETCH_ADDR_W-1:0] prefetch_wr_index;
wire [PREFETCH_ADDR_W:0] prefetch_used;
wire [PREFETCH_ADDR_W:0] prefetch_level;
wire prefetch_empty;
wire prefetch_full;
wire fetch_available;
wire read_ready;
wire fetch_fire;
wire enqueue_fire;
wire head_ready;
wire refill_fire;

// Auxiliary words retain their backing slot through both output fragments.
reg [63:0] peer_mem [0:PEER_DEPTH-1];
reg [PEER_ADDR_W:0] peer_rd_ptr, peer_wr_ptr;
reg peer_half, head_peer, head_last, prefer_peer;
wire [PEER_ADDR_W-1:0] peer_rd_index;
wire [PEER_ADDR_W:0] peer_used;
wire peer_push, peer_pop, peer_refill;
wire [CHANNELS-1:0] lane_request;
reg [CHANNELS-1:0] grant;
wire [63:0] peer_record;
reg [HELD_W-1:0] queued_pulses;
wire [HELD_W-1:0] stream_held;
integer h;

assign peer_rd_index = peer_rd_ptr[PEER_ADDR_W-1:0];
assign peer_used = peer_wr_ptr - peer_rd_ptr;
assign o_peer_ready = peer_used < PEER_DEPTH;
assign peer_push = i_peer_valid && o_peer_ready;
assign peer_pop = head_valid && head_peer && head_last
                  && i_out_ready;
assign lane_request[0] = !prefetch_empty;
assign lane_request[1] = (peer_used != 0)
                         && !(head_valid && head_peer);
assign peer_refill = grant[1];
// E/F identify the low/high payload fragments of an auxiliary record.
assign peer_record =
    (peer_half ? 64'hf000000000000000 : 64'he000000000000000)
    | (peer_half ? {32'd0, peer_mem[peer_rd_index][63:32]}
                 : {32'd0, peer_mem[peer_rd_index][31:0]});
assign o_peer = head_valid && head_peer;
assign o_peer_last = head_valid && head_peer && head_last;
assign stream_held = pulse_count + queued_pulses + peer_used;

always @(*) begin
    grant = {CHANNELS{1'b0}};
    if (lane_request[1] && (prefer_peer || !lane_request[0]))
        grant[1] = head_ready;
    else if (lane_request[0])
        grant[0] = head_ready;
end

// Express occupancy in input-item units, including pulses grouped in records.
always @(*) begin
    queued_pulses = {HELD_W{1'b0}};
    for (h = 0; h < DEPTH; h = h + 1)
        if (filled[h])
            queued_pulses = queued_pulses
                + (event_mem[h] & 64'h1fffffffffffffff);
end

    assign modulus = mode_q ? P + 64'd1 : P;
    assign o_pulse_ready = fifo_count < DEPTH;
    assign pulse_fire = i_pulse_valid && o_pulse_ready;
    assign finish_fire = pulse_fire && (phase == RUN)
                         && (pulse_count == modulus - 64'd1);
assign o_valid = head_valid;
assign o_data = head_data;
assign pop_fire = o_valid && i_out_ready && !head_peer;

assign prefetch_rd_index =
    prefetch_rd_ptr[PREFETCH_ADDR_W-1:0];
assign prefetch_wr_index =
    prefetch_wr_ptr[PREFETCH_ADDR_W-1:0];
assign prefetch_used = prefetch_wr_ptr - prefetch_rd_ptr;
assign prefetch_level = prefetch_used
+ {{PREFETCH_ADDR_W{1'b0}}, (head_valid && !head_peer)}
    + {{PREFETCH_ADDR_W{1'b0}}, read_valid};
assign prefetch_empty = prefetch_wr_ptr == prefetch_rd_ptr;
assign prefetch_full =
    (prefetch_wr_ptr[PREFETCH_ADDR_W] != prefetch_rd_ptr[PREFETCH_ADDR_W])
    && (prefetch_wr_index == prefetch_rd_index);
assign fetch_available = prefetch_level < fifo_count;
assign read_ready = !read_valid || !prefetch_full;
assign fetch_fire = fetch_available && read_ready;
assign enqueue_fire = read_valid && !prefetch_full;
assign head_ready = !head_valid || i_out_ready;
assign refill_fire = grant[0];
assign o_prefetch_level = prefetch_level;

    // Filled slots are the circular interval starting at rd_ptr.
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupied_slots
            localparam [63:0] ENTRY = g;
            assign filled[g] = ((ENTRY >= rd_ptr)
                              ? (ENTRY - rd_ptr)
                              : (ENTRY + DEPTH - rd_ptr)) < fifo_count;
        end
    endgenerate

    integer j;
    initial begin
        phase = IDLE;
        pulse_count = 64'd0;
        mode_q = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        scope_armed = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        fifo_count = 64'd0;
prefetch_rd_ptr = {(PREFETCH_ADDR_W+1){1'b0}};
prefetch_wr_ptr = {(PREFETCH_ADDR_W+1){1'b0}};
fetch_addr = {EVENT_ADDR_W{1'b0}};
read_valid = 1'b0;
read_data = 64'd0;
head_valid = 1'b0;
head_data = 64'd0;
peer_rd_ptr = {(PEER_ADDR_W+1){1'b0}};
peer_wr_ptr = {(PEER_ADDR_W+1){1'b0}};
peer_half = 1'b0;
head_peer = 1'b0;
head_last = 1'b0;
prefer_peer = 1'b0;
for (j = 0; j < PEER_DEPTH; j = j + 1)
    peer_mem[j] = 64'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            event_mem[j] = 64'd0;
for (j = 0; j < PREFETCH_DEPTH; j = j + 1)
    prefetch_mem[j] = 64'd0;
    end

always @(posedge clk) begin
    if (peer_push) begin
        peer_mem[peer_wr_ptr[PEER_ADDR_W-1:0]] <= i_peer_data;
        peer_wr_ptr <= peer_wr_ptr + 1'b1;
    end
    if (peer_pop)
        peer_rd_ptr <= peer_rd_ptr + 1'b1;
    if (peer_refill)
        peer_half <= !peer_half;
    if (refill_fire || peer_refill)
        prefer_peer <= !peer_refill;
end

    always @(posedge clk) begin
        if (pulse_fire) begin
            case (phase)
                IDLE: begin
                    // Q is the ARM event; its scope latch never clears.
                    scope_armed <= 1'b1;
                    mode_q <= i_mode;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    pulse_count <= 64'd1;
                    phase <= ARMED;
                end
                ARMED: begin
                    start_seen <= 1'b1;
                    pulse_count <= 64'd2;
                    phase <= RUN;
                end
                RUN: begin
                    if (finish_fire) begin
                        pulse_count <= 64'd0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= IDLE;
                    end else begin
                        pulse_count <= pulse_count + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    pulse_count <= 64'd0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end

        if (finish_fire) begin
            // Record: ARM witness, START witness, sampled mode,
            // and the number of accepted pulses in this division.
            event_mem[wr_ptr] <= (pulse_count + 64'd1)
                | (arm_seen ? 64'h8000000000000000 : 64'd0)
                | (start_seen ? 64'h4000000000000000 : 64'd0)
                | (mode_q ? 64'h2000000000000000 : 64'd0);
            wr_ptr <= (wr_ptr == DEPTH - 64'd1)
                    ? 64'd0 : wr_ptr + 64'd1;
        end
        if (pop_fire)
            rd_ptr <= (rd_ptr == DEPTH - 64'd1)
                    ? 64'd0 : rd_ptr + 64'd1;

        case ({finish_fire, pop_fire})
            2'b10: fifo_count <= fifo_count + 64'd1;
            2'b01: fifo_count <= fifo_count - 64'd1;
            default: begin end
        endcase
    end

// A stalled read response keeps its data and reserves its backing slot.
always @(posedge clk) begin
    if (read_ready)
        read_valid <= fetch_fire;
    if (fetch_fire) begin
        read_data <= event_mem[fetch_addr];
        if (fetch_addr == DEPTH - 64'd1)
            fetch_addr <= {EVENT_ADDR_W{1'b0}};
        else
            fetch_addr <= fetch_addr + 1'b1;
    end
end

always @(posedge clk) begin
    if (enqueue_fire) begin
        prefetch_mem[prefetch_wr_index] <= read_data;
        prefetch_wr_ptr <= prefetch_wr_ptr + 1'b1;
    end
    if (refill_fire)
        prefetch_rd_ptr <= prefetch_rd_ptr + 1'b1;
end

// Backing slots are released by pop_fire, not by speculative reads.
always @(posedge clk) begin
    if (head_ready) begin
head_valid <= refill_fire || peer_refill;
head_peer <= peer_refill;
head_last <= peer_refill && peer_half;
if (peer_refill)
    head_data <= peer_record;
else if (refill_fire)
            head_data <= prefetch_mem[prefetch_rd_index];
    end
end

    // After Q: START requires ARM, and every observable FINISH
    // must carry both earlier event witnesses.
    always @(posedge clk)
        if (scope_armed)
            assert ((!start_seen || arm_seen)
                    && (!o_valid || (o_data[63] && o_data[62])));
endmodule

module sample_storage_whitener #(
    parameter integer unsigned DATA_WIDTH = 32'd32,
    parameter integer unsigned BANKS = 32'd4,
    parameter integer unsigned ROUNDS = 32'd4
) (
    input wire clk,
    input wire i_ce,
    input wire start,
    input wire retire,
    input wire [DATA_WIDTH-32'd1:0] write_data,
    input wire [DATA_WIDTH-32'd1:0] read_code,
    output wire [DATA_WIDTH-32'd1:0] write_code,
    output wire [DATA_WIDTH-32'd1:0] read_data,
    output wire ready_o,
    output wire mask_valid_o,
    output reg [1:0] phase_o,
    output reg [DATA_WIDTH-32'd1:0] mask_o
);
    localparam integer unsigned BANK_WIDTH =
        (BANKS > 32'd1) ? $clog2(BANKS) : 32'd1;
    localparam integer unsigned ROUND_WIDTH =
        (ROUNDS > 32'd1) ? $clog2(ROUNDS) : 32'd1;
    localparam [BANK_WIDTH-32'd1:0] LAST_BANK =
        BANK_WIDTH'(BANKS - 32'd1);
    localparam [ROUND_WIDTH-32'd1:0] LAST_ROUND =
        ROUND_WIDTH'(ROUNDS - 32'd1);
    localparam [1:0] PH_IDLE = 2'd0;
    localparam [1:0] PH_MIX = 2'd1;
    localparam [1:0] PH_SEAL = 2'd2;
    localparam [1:0] PH_LOCKED = 2'd3;

    reg [DATA_WIDTH-32'd1:0] pool [0:BANKS-32'd1];
    reg [DATA_WIDTH-32'd1:0] lane_a;
    reg [DATA_WIDTH-32'd1:0] lane_b;
    reg [DATA_WIDTH-32'd1:0] orbit;
    reg [DATA_WIDTH-32'd1:0] round_salt;
    reg [BANK_WIDTH-32'd1:0] bank_index;
    reg [BANK_WIDTH-32'd1:0] mix_index;
    reg [ROUND_WIDTH-32'd1:0] round_index;

    function automatic [DATA_WIDTH-32'd1:0] rotate_word;
        input [DATA_WIDTH-32'd1:0] word_value;
        input integer unsigned distance;
        begin
            rotate_word = (word_value << (distance % DATA_WIDTH)) |
                (word_value >> ((DATA_WIDTH - (distance % DATA_WIDTH)) % DATA_WIDTH));
        end
    endfunction

    wire [BANK_WIDTH-32'd1:0] next_bank =
        (bank_index == LAST_BANK) ? {BANK_WIDTH{1'b0}} :
        bank_index + BANK_WIDTH'(32'd1);
    wire [BANK_WIDTH-32'd1:0] next_mix =
        (mix_index == LAST_BANK) ? {BANK_WIDTH{1'b0}} :
        mix_index + BANK_WIDTH'(32'd1);
    wire [DATA_WIDTH-32'd1:0] pool_word = pool[mix_index];
    wire [DATA_WIDTH-32'd1:0] launch_a =
        pool[bank_index] ^ orbit;
    wire [DATA_WIDTH-32'd1:0] launch_b =
        rotate_word(pool[next_bank], 32'd3) + rotate_word(orbit, 32'd9);
    wire [DATA_WIDTH-32'd1:0] sum_a =
        lane_a + rotate_word(lane_b, 32'd5);
    wire [DATA_WIDTH-32'd1:0] cross_b =
        lane_b ^ rotate_word(pool_word, 32'd11);
    wire [DATA_WIDTH-32'd1:0] mixed_a =
        rotate_word(sum_a, 32'd7) ^ pool_word ^ round_salt;
    wire [DATA_WIDTH-32'd1:0] mixed_b =
        rotate_word(cross_b, 32'd13) + lane_a;
    wire [DATA_WIDTH-32'd1:0] returned_word =
        rotate_word(pool_word, 32'd1) ^ mixed_a ^ rotate_word(mixed_b, 32'd17);
    wire [DATA_WIDTH-32'd1:0] sealed_mask =
        lane_a ^ rotate_word(lane_b, 32'd11) ^ rotate_word(orbit, 32'd1);
    wire [DATA_WIDTH-32'd1:0] advanced_orbit =
        rotate_word(orbit, 32'd1) ^
        (orbit[DATA_WIDTH-32'd1] ? DATA_WIDTH'(32'h04c11db7) : {DATA_WIDTH{1'b0}}) ^
        rotate_word(lane_a, 32'd3) ^ lane_b;
    wire [DATA_WIDTH-32'd1:0] advanced_salt =
        (round_salt << 32'd1) ^
        (round_salt[DATA_WIDTH-32'd1] ? DATA_WIDTH'(32'h0000001b) : {DATA_WIDTH{1'b0}});

    assign ready_o = (phase_o == PH_IDLE);
    assign mask_valid_o = (phase_o == PH_LOCKED);
    assign write_code = write_data ^ mask_o;
    assign read_data = read_code ^ mask_o;

    initial begin
        phase_o = PH_IDLE;
        mask_o = {DATA_WIDTH{1'b0}};
        lane_a = {DATA_WIDTH{1'b0}};
        lane_b = {DATA_WIDTH{1'b0}};
        orbit = DATA_WIDTH'(32'h6d2b79f5);
        round_salt = DATA_WIDTH'(32'h00000001);
        bank_index = {BANK_WIDTH{1'b0}};
        mix_index = {BANK_WIDTH{1'b0}};
        round_index = {ROUND_WIDTH{1'b0}};
        for (integer k = 32'd0; k < BANKS; k = k + 32'd1)
            pool[k] = rotate_word(DATA_WIDTH'(k + 32'd1) ^
                                  DATA_WIDTH'(32'h9e3779b9), 32'd7);
    end

    // Expand a fresh storage mask without putting the mixer on the RAM path.
    always @(posedge clk) begin
        if (i_ce) begin
            case (phase_o)
                PH_IDLE: begin
                    if (start && ready_o) begin
                        lane_a <= launch_a;
                        lane_b <= launch_b;
                        round_salt <= orbit ^ DATA_WIDTH'(32'hb7e15163);
                        mix_index <= bank_index;
                        round_index <= {ROUND_WIDTH{1'b0}};
                        phase_o <= PH_MIX;
                    end
                end
                PH_MIX: begin
                    lane_a <= mixed_a;
                    lane_b <= mixed_b;
                    round_salt <= advanced_salt;
                    pool[mix_index] <= returned_word;
                    if (round_index == LAST_ROUND) begin
                        phase_o <= PH_SEAL;
                    end else begin
                        round_index <= round_index + ROUND_WIDTH'(32'd1);
                        mix_index <= next_mix;
                    end
                end
                PH_SEAL: begin
                    mask_o <= (sealed_mask == {DATA_WIDTH{1'b0}}) ?
                              DATA_WIDTH'(32'd1) : sealed_mask;
                    orbit <= advanced_orbit;
                    phase_o <= PH_LOCKED;
                end
                PH_LOCKED: begin
                    if (retire) begin
                        bank_index <= next_bank;
                        phase_o <= PH_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end
endmodule

module forwarded_sample_buffer #(
    parameter integer unsigned DEPTH = 32'd24,
    parameter integer unsigned DATA_WIDTH = 32'd32,
    parameter integer unsigned INDEX_WIDTH = 32'd32
) (
    input  wire clk,
    input  wire forwarded_clk,
    input  wire i_ce,
    input  wire in_valid,
    output wire in_ready,
    input  wire [DATA_WIDTH-32'd1:0] in_data,
    output wire out_valid,
    input  wire out_ready,
    output logic [DATA_WIDTH-32'd1:0] out_data,
    output reg [31:0] debug_status,
    output reg [39:0] perf_snapshot,
    output wire [DATA_WIDTH-32'd1:0] whitening_mask,
    output wire [1:0] whitening_phase
);
    typedef enum logic [1:0] {
        RX_IDLE  = 2'd0,
        RX_STORE = 2'd1,
        RX_WAIT  = 2'd2
    } rx_state_t;

    typedef enum logic [1:0] {
        TX_IDLE  = 2'd0,
        TX_VALID = 2'd1
    } tx_state_t;

    localparam logic [INDEX_WIDTH-32'd1:0] LAST_INDEX =
        INDEX_WIDTH'(DEPTH - 32'd1);

    rx_state_t rx_state;
    tx_state_t tx_state;
    logic [DATA_WIDTH-32'd1:0] capture_data;
    logic [DATA_WIDTH-32'd1:0] sample_buffer [0:DEPTH-32'd1];
    logic [INDEX_WIDTH-32'd1:0] write_index;
    logic [INDEX_WIDTH-32'd1:0] read_index;
    logic request_toggle;
    logic acknowledge_toggle;
    logic past_valid;
    logic [7:0] dbg_transfer_count;
    logic [7:0] dbg_stall_cycles;
    logic [7:0] dbg_stall_run;
    logic [7:0] dbg_stall_peak;
    logic [7:0] dbg_idle_run;
    logic dbg_stall_alarm;
    logic dbg_idle_alarm;
    logic [7:0] perf_window;
    logic [7:0] perf_transfers;
    logic [7:0] perf_busy;
    logic [7:0] perf_gap;
    logic [7:0] perf_peak;
    logic [7:0] perf_signature;
    logic [5:0] perf_epoch;
    logic perf_alarm;
    logic perf_stalled;
    wire perf_take = out_valid && out_ready;
    wire [7:0] perf_transfers_next =
        (perf_take && (perf_transfers != 8'hff)) ? perf_transfers + 8'd1 : perf_transfers;
    wire [7:0] perf_busy_next =
        (out_valid && (perf_busy != 8'hff)) ? perf_busy + 8'd1 : perf_busy;
    wire [7:0] perf_gap_next =
        perf_take ? 8'd0 :
        ((perf_gap != 8'hff) ? perf_gap + 8'd1 : perf_gap);
    wire [7:0] perf_peak_next =
        (perf_gap_next > perf_peak) ? perf_gap_next : perf_peak;
    wire [7:0] perf_signature_next =
        perf_take ? ({perf_signature[6:0], ^out_data} ^
                     (perf_signature[7] ? 8'h1d : 8'h00)) : perf_signature;
    wire perf_alarm_next = perf_alarm || (perf_gap_next >= 8'd128);
    wire perf_stalled_next = perf_stalled || (out_valid && !out_ready);

    wire [INDEX_WIDTH-32'd1:0] next_write_index =
        (write_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        write_index + INDEX_WIDTH'(32'd1);
    wire [INDEX_WIDTH-32'd1:0] next_read_index =
        (read_index == LAST_INDEX) ? {INDEX_WIDTH{1'b0}} :
        read_index + INDEX_WIDTH'(32'd1);
    localparam integer unsigned WHITEN_BANKS = 32'd4;
    localparam integer unsigned WHITEN_ROUNDS = 32'd4;
    wire whitening_ready;
    wire whitening_valid;
    wire [DATA_WIDTH-32'd1:0] encoded_capture;
    wire [DATA_WIDTH-32'd1:0] decoded_sample;

    sample_storage_whitener #(
        .DATA_WIDTH(DATA_WIDTH),
        .BANKS(WHITEN_BANKS),
        .ROUNDS(WHITEN_ROUNDS)
    ) storage_whitener (
        .clk(forwarded_clk),
        .i_ce(i_ce),
        .start(in_valid && in_ready),
        .retire((rx_state == RX_WAIT) &&
                (request_toggle == acknowledge_toggle)),
        .write_data(capture_data),
        .read_code(sample_buffer[read_index]),
        .write_code(encoded_capture),
        .read_data(decoded_sample),
        .ready_o(whitening_ready),
        .mask_valid_o(whitening_valid),
        .phase_o(whitening_phase),
        .mask_o(whitening_mask)
    );


    assign in_ready = i_ce && (rx_state == RX_IDLE) && whitening_ready;
    assign out_valid = (tx_state == TX_VALID);
    initial begin
        perf_window = 8'd0;
        perf_transfers = 8'd0;
        perf_busy = 8'd0;
        perf_gap = 8'd0;
        perf_peak = 8'd0;
        perf_signature = 8'h01;
        perf_epoch = 6'd0;
        perf_alarm = 1'b0;
        perf_stalled = 1'b0;
        perf_snapshot = 40'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (perf_window == 8'hff) begin
                perf_window <= 8'd0;
                perf_epoch <= perf_epoch + 6'd1;
                perf_snapshot <= {perf_epoch, perf_stalled_next, perf_alarm_next,
                                  perf_transfers_next, perf_busy_next, perf_peak_next, perf_signature_next};
                perf_transfers <= 8'd0;
                perf_busy <= 8'd0;
                perf_gap <= 8'd0;
                perf_peak <= 8'd0;
                perf_signature <= 8'h01;
                perf_alarm <= 1'b0;
                perf_stalled <= 1'b0;
            end else begin
                perf_window <= perf_window + 8'd1;
                perf_transfers <= perf_transfers_next;
                perf_busy <= perf_busy_next;
                perf_gap <= perf_gap_next;
                perf_peak <= perf_peak_next;
                perf_signature <= perf_signature_next;
                perf_alarm <= perf_alarm_next;
                perf_stalled <= perf_stalled_next;
            end
        end
    end

    initial begin
        rx_state = RX_IDLE;
        tx_state = TX_IDLE;
        capture_data = {DATA_WIDTH{1'b0}};
        out_data = {DATA_WIDTH{1'b0}};
        write_index = {INDEX_WIDTH{1'b0}};
        read_index = {INDEX_WIDTH{1'b0}};
        request_toggle = 1'b0;
        acknowledge_toggle = 1'b0;
        past_valid = 1'b0;
        for (integer k = 32'd0; k < DEPTH; k = k + 32'd1)
            sample_buffer[k] = {DATA_WIDTH{1'b0}};
    end
    initial begin
        dbg_transfer_count = 8'd0;
        dbg_stall_cycles = 8'd0;
        dbg_stall_run = 8'd0;
        dbg_stall_peak = 8'd0;
        dbg_idle_run = 8'd0;
        dbg_stall_alarm = 1'b0;
        dbg_idle_alarm = 1'b0;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (out_valid && out_ready) begin
                if (dbg_transfer_count != 8'hff)
                    dbg_transfer_count <= dbg_transfer_count + 8'd1;
            end
            if (out_valid && !out_ready) begin
                if (dbg_stall_cycles != 8'hff)
                    dbg_stall_cycles <= dbg_stall_cycles + 8'd1;
                if (dbg_stall_run != 8'hff)
                    dbg_stall_run <= dbg_stall_run + 8'd1;
                if ((dbg_stall_run >= dbg_stall_peak) && (dbg_stall_run != 8'hff))
                    dbg_stall_peak <= dbg_stall_run + 8'd1;
                if (dbg_stall_run >= 8'd63)
                    dbg_stall_alarm <= 1'b1;
            end else begin
                dbg_stall_run <= 8'd0;
            end
            if (!out_valid) begin
                if (dbg_idle_run != 8'hff)
                    dbg_idle_run <= dbg_idle_run + 8'd1;
                if (dbg_idle_run >= 8'd127)
                    dbg_idle_alarm <= 1'b1;
            end else begin
                dbg_idle_run <= 8'd0;
            end
            debug_status <= {dbg_stall_alarm, dbg_idle_alarm, out_valid, out_ready,
                             dbg_idle_run[3:0], dbg_stall_peak,
                             dbg_stall_cycles, dbg_transfer_count};
        end
    end

    // Forwarded-clock capture followed by a write into the rotating buffer.
    // One outstanding transfer keeps the bundled sample and its slot stable
    // until the local-clock consumer acknowledges it.
    always @(posedge forwarded_clk) begin
        if (i_ce) begin
            case (rx_state)
                RX_IDLE: begin
                    if (in_valid && in_ready) begin
                        capture_data <= in_data;
                        rx_state <= RX_STORE;
                    end
                end
                RX_STORE: begin
                    if (whitening_valid) begin
                        sample_buffer[write_index] <= encoded_capture;
                        request_toggle <= !request_toggle;
                        rx_state <= RX_WAIT;
                    end
                end
                RX_WAIT: begin
                    if (request_toggle == acknowledge_toggle) begin
                        write_index <= next_write_index;
                        rx_state <= RX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    // The other port of the buffer is read in the local-clock domain.
    // Output data and valid remain held throughout back-pressure.
    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;
            case (tx_state)
                TX_IDLE: begin
                    if (request_toggle != acknowledge_toggle) begin
                        out_data <= decoded_sample;
                        tx_state <= TX_VALID;
                    end
                end
                TX_VALID: begin
                    if (out_valid && out_ready) begin
                        acknowledge_toggle <= request_toggle;
                        read_index <= next_read_index;
                        tx_state <= TX_IDLE;
                    end
                end
                default: begin end
            endcase
        end
    end

    always @(posedge clk) begin
        if (past_valid && $rose(out_valid))
            assert (out_data == capture_data);
    end
endmodule

module schroeder_integrity #(
    parameter integer BANKS = 4,
    parameter integer BANK_BITS = $clog2(BANKS)
) (
    input wire clk, ce, write_valid,
    input wire [BANK_BITS-1:0] write_bank,
    input wire [31:0] old_word, new_word,
    input wire [BANKS*32-1:0] live_signatures,
    output wire [BANKS*32-1:0] signature_state,
    output reg [BANK_BITS-1:0] scan_bank,
    output reg [31:0] observed, expected,
    output reg valid
);
    reg [31:0] signature [0:BANKS-1];
    initial begin
        scan_bank = 0;
        observed = 32'd0;
        expected = 32'd0;
        valid = 1'b0;
    end
    genvar bank;
    generate
        for (bank = 0; bank < BANKS; bank = bank + 1) begin : signature_banks
            initial signature[bank] = 32'd0;
            assign signature_state[bank*32 +: 32] = signature[bank];
        end
    endgenerate
    always @(posedge clk) begin
        if (ce) begin
            if (write_valid)
                signature[write_bank] <= signature[write_bank] ^ old_word ^ new_word;
            observed <= live_signatures[scan_bank*32 +: 32];
            expected <= signature[scan_bank];
            valid <= 1'b1;
            if (scan_bank == BANKS-1) scan_bank <= 0;
            else scan_bank <= scan_bank + 1'b1;
        end
    end
endmodule

module schroeder_phase_stage #(
    parameter [31:0] DEPTH = 32'd16,
    parameter signed [31:0] GAIN_NUM = 32'sd1,
    parameter [31:0] GAIN_SHIFT = 32'd1,
    parameter integer AUDIT_BANKS = 4
) (
    input wire clk,
    input wire ce,
    input wire signed [31:0] sample_in,
    output reg signed [31:0] sample_out,
    output wire sample_valid,
    output wire audit_valid,
    output wire [31:0] audit_observed,
    output wire [31:0] audit_expected,
    output wire [$clog2(AUDIT_BANKS)-1:0] audit_bank
);
    typedef enum logic [1:0] {
        CAPTURE  = 2'b00,
        FEEDBACK = 2'b01,
        COMMIT   = 2'b10,
        REPORT   = 2'b11
    } state_t;

    state_t state;
    reg [31:0] delay_ptr;
    reg signed [31:0] delay_line [32'd0:DEPTH-32'd1];
    reg signed [31:0] sample_shadow;
    reg signed [31:0] tap_shadow;
    reg signed [31:0] feedback_word;
    wire [AUDIT_BANKS*32-1:0] integrity_signatures;
    reg [AUDIT_BANKS*32-1:0] integrity_live;
    wire integrity_write = ce && (state == COMMIT);
    wire [$clog2(AUDIT_BANKS)-1:0] integrity_write_bank = delay_ptr % AUDIT_BANKS;
    integer audit_entry;
    always @(*) begin
        integrity_live = {AUDIT_BANKS{32'd0}};
        for (audit_entry = 0; audit_entry < DEPTH; audit_entry = audit_entry + 1)
            integrity_live[(audit_entry % AUDIT_BANKS)*32 +: 32] =
                integrity_live[(audit_entry % AUDIT_BANKS)*32 +: 32] ^ delay_line[audit_entry];
    end
    schroeder_integrity #(.BANKS(AUDIT_BANKS)) integrity_unit (
        .clk(clk), .ce(ce), .write_valid(integrity_write),
        .write_bank(integrity_write_bank), .old_word(delay_line[delay_ptr]),
        .new_word(feedback_word), .live_signatures(integrity_live),
        .signature_state(integrity_signatures), .scan_bank(audit_bank),
        .observed(audit_observed), .expected(audit_expected), .valid(audit_valid)
    );

    // Dyadic gain g = GAIN_NUM / 2**GAIN_SHIFT, defaulting to 1/2.
    // Arithmetic and storage wrap at 32 bits; shifts round downward.
    wire signed [31:0] tap_product = tap_shadow * GAIN_NUM;
    wire signed [31:0] scaled_tap = tap_product >>> GAIN_SHIFT;
    wire signed [31:0] expected_feedback = sample_shadow + scaled_tap;

    wire signed [31:0] feedback_product = feedback_word * GAIN_NUM;
    wire signed [31:0] scaled_feedback = feedback_product >>> GAIN_SHIFT;

    wire signed [31:0] expected_product = expected_feedback * GAIN_NUM;
    wire signed [31:0] expected_scaled = expected_product >>> GAIN_SHIFT;
    wire signed [31:0] expected_output = tap_shadow - expected_scaled;

    assign sample_valid = (state == REPORT);

    initial begin
        state = CAPTURE;
        delay_ptr = 32'd0;
        sample_shadow = 32'sd0;
        tap_shadow = 32'sd0;
        feedback_word = 32'sd0;
        sample_out = 32'sd0;
    end

    genvar entry;
    generate
        for (entry = 32'd0; entry < DEPTH; entry = entry + 32'd1) begin : initialize_delay
            initial delay_line[entry] = 32'sd0;
        end
    endgenerate

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                CAPTURE: begin
                    // Record the input and the earlier circular-buffer value.
                    sample_shadow <= sample_in;
                    tap_shadow <= delay_line[delay_ptr];
                    state <= FEEDBACK;
                end
                FEEDBACK: begin
                    // Allpass feedback path: w = x + g*d.
                    feedback_word <= expected_feedback;
                    state <= COMMIT;
                end
                COMMIT: begin
                    // Allpass feedforward path: y = d - g*w.
                    delay_line[delay_ptr] <= feedback_word;
                    sample_out <= tap_shadow - scaled_feedback;
                    if (delay_ptr == DEPTH - 32'd1)
                        delay_ptr <= 32'd0;
                    else
                        delay_ptr <= delay_ptr + 32'd1;
                    state <= REPORT;
                end
                REPORT: begin
                    state <= CAPTURE;
                end
            endcase
        end
    end

    // Every reported result must correspond to the earlier captured values.
    always @(posedge clk)
        if (state == REPORT)
            assert (sample_out == expected_output);

    always @(posedge clk)
        if (audit_valid)
            assert (audit_observed == audit_expected);
endmodule

module pixel_pulse_pending #(
parameter integer COUNT_W = 32,
parameter integer TILE_DEPTH = 4
) (
    input wire clk,
    input wire i_ce,
    input wire i_pixel_pulse,
    input wire i_dispatch,
    input wire i_slow_tick,
    input wire i_load_limit,
    input wire [COUNT_W-1:0] i_limit,
    input wire i_begin_tile,
    input wire i_end_tile,
input wire i_peer_pixel_pulse,
output reg slow_pixel_pulse,
output wire pixel_ready,
output wire peer_ready,
output reg peer_slow_pixel_pulse,
output reg [63:0] debug_stats,
output wire tile_begin_ready,
output wire tile_end_ready,
output wire tile_active,
output reg tile_done,
output reg [COUNT_W-1:0] tile_done_pixels,
output reg [$clog2(TILE_DEPTH)-1:0] tile_done_slot,
output reg tile_done_overflow,
output reg [TILE_DEPTH*COUNT_W-1:0] tile_progress,
output reg [TILE_DEPTH-1:0] tile_waiting,
output wire [$clog2(TILE_DEPTH):0] tile_queue_level
);
    localparam [COUNT_W-1:0] ZERO = {COUNT_W{1'b0}};
    localparam [COUNT_W-1:0] ONE = {{(COUNT_W-1){1'b0}}, 1'b1};
localparam integer CHANNELS = 2, PEER_DEPTH = 7;
localparam integer PEER_W = $clog2(PEER_DEPTH + 1);

    reg [COUNT_W-1:0] pending;
    reg [COUNT_W-1:0] outstanding;
    reg [COUNT_W-1:0] pulse_limit;
    reg req_toggle;
    reg ack_toggle;
    reg window_open;
    reg pv;
reg peer_valid [0:PEER_DEPTH-1];
reg [PEER_W-1:0] peer_outstanding;
reg [$clog2(CHANNELS)-1:0] flight_lane;
integer k;

    // TILE_DEPTH is a power of two; contexts are tile retirement fences.
    localparam integer TILE_AW = $clog2(TILE_DEPTH);
    localparam integer TILE_PW = TILE_AW + 1;
    reg [COUNT_W-1:0] tile_credit [0:TILE_DEPTH-1];
    reg [COUNT_W-1:0] tile_size [0:TILE_DEPTH-1];
    reg tile_sealed [0:TILE_DEPTH-1];
    reg tile_overflow [0:TILE_DEPTH-1];
    reg [COUNT_W-1:0] tile_credit_next [0:TILE_DEPTH-1];
    reg [COUNT_W-1:0] tile_size_next [0:TILE_DEPTH-1];
    reg tile_sealed_next [0:TILE_DEPTH-1];
    reg tile_overflow_next [0:TILE_DEPTH-1];
    reg [TILE_PW-1:0] tile_wr;
    reg [TILE_PW-1:0] tile_rd;
    reg tile_open;
    reg [TILE_DEPTH-1:0] tile_live;
    integer tile_scan;
    integer tile_reg;

    wire in_flight = (req_toggle != ack_toggle);
wire accept_pulse = i_pixel_pulse && tile_open && (outstanding < pulse_limit);
wire launch_request = i_dispatch && !in_flight && (pending != ZERO) &&
                      !tile_empty && (tile_credit[tile_head] != ZERO);
wire retire_request = i_slow_tick && in_flight && (flight_lane == 1'b0);
wire peer_launch = i_dispatch && !in_flight && (pending == ZERO) && peer_valid[PEER_DEPTH-1];
wire peer_shift = !peer_valid[PEER_DEPTH-1] || peer_launch;
wire peer_retire = i_slow_tick && in_flight && (flight_lane == 1'b1);
wire peer_accept = i_peer_pixel_pulse && peer_ready;
assign pixel_ready = i_ce && tile_open && (outstanding < pulse_limit);
assign peer_ready = i_ce && peer_shift && (peer_outstanding < PEER_DEPTH);

    wire [TILE_AW-1:0] tile_head = tile_rd[TILE_AW-1:0];
    wire [TILE_AW-1:0] tile_tail = tile_wr[TILE_AW-1:0] - 1'b1;
    wire [TILE_PW-1:0] tile_level = tile_wr - tile_rd;
    wire tile_empty = (tile_wr == tile_rd);
    wire tile_full = (tile_wr[TILE_AW] != tile_rd[TILE_AW]) &&
                     (tile_wr[TILE_AW-1:0] == tile_rd[TILE_AW-1:0]);
    wire tile_allocate = i_begin_tile && tile_begin_ready;
    wire tile_close = i_end_tile && tile_end_ready;
    wire tile_pop = i_ce && !tile_empty && tile_sealed[tile_head] &&
                    (tile_credit[tile_head] == ZERO);
    wire [TILE_PW:0] tile_held = {1'b0, tile_level} +
                               {{TILE_PW{1'b0}}, tile_done};
    assign tile_begin_ready = i_ce && !tile_open && !tile_full;
    assign tile_end_ready = i_ce && tile_open;
    assign tile_active = tile_open;
    assign tile_queue_level = tile_level;

    always @(*) begin
        for (tile_scan = 0; tile_scan < TILE_DEPTH;
             tile_scan = tile_scan + 1) begin
            if (tile_wr[TILE_AW] == tile_rd[TILE_AW])
                tile_live[tile_scan] = (tile_scan >= tile_head) &&
                                      (tile_scan < tile_wr[TILE_AW-1:0]);
            else
                tile_live[tile_scan] = (tile_scan >= tile_head) ||
                                      (tile_scan < tile_wr[TILE_AW-1:0]);
            tile_progress[tile_scan*COUNT_W +: COUNT_W] = tile_credit[tile_scan];
            tile_waiting[tile_scan] = tile_live[tile_scan] && tile_sealed[tile_scan];
            tile_credit_next[tile_scan] = tile_credit[tile_scan];
            tile_size_next[tile_scan] = tile_size[tile_scan];
            tile_sealed_next[tile_scan] = tile_sealed[tile_scan];
            tile_overflow_next[tile_scan] = tile_overflow[tile_scan];
            if (tile_allocate && (tile_wr[TILE_AW-1:0] == tile_scan)) begin
                tile_credit_next[tile_scan] = ZERO;
                tile_size_next[tile_scan] = ZERO;
                tile_sealed_next[tile_scan] = 1'b0;
                tile_overflow_next[tile_scan] = 1'b0;
            end else begin
                case ({accept_pulse && (tile_tail == tile_scan),
                       retire_request && (tile_head == tile_scan)})
                    2'b10: tile_credit_next[tile_scan] = tile_credit[tile_scan] + ONE;
                    2'b01: tile_credit_next[tile_scan] = tile_credit[tile_scan] - ONE;
                    default: tile_credit_next[tile_scan] = tile_credit[tile_scan];
                endcase
                if (accept_pulse && (tile_tail == tile_scan)) begin
                    if (!(&tile_size[tile_scan]))
                        tile_size_next[tile_scan] = tile_size[tile_scan] + ONE;
                    else
                        tile_overflow_next[tile_scan] = 1'b1;
                end
                if (tile_close && (tile_tail == tile_scan))
                    tile_sealed_next[tile_scan] = 1'b1;
                if (tile_pop && (tile_head == tile_scan))
                    tile_sealed_next[tile_scan] = 1'b0;
            end
        end
    end

    initial begin
        tile_wr = 0;
        tile_rd = 0;
        tile_open = 1'b0;
        tile_done = 1'b0;
        tile_done_pixels = ZERO;
        tile_done_slot = 0;
        tile_done_overflow = 1'b0;
        for (tile_reg = 0; tile_reg < TILE_DEPTH; tile_reg = tile_reg + 1) begin
            tile_credit[tile_reg] = ZERO;
            tile_size[tile_reg] = ZERO;
            tile_sealed[tile_reg] = 1'b0;
            tile_overflow[tile_reg] = 1'b0;
        end
    end

    // Completion reports advance on enabled cycles, like delivery pulses.
    always @(posedge clk) begin
        if (i_ce) begin
            if (tile_allocate) begin
                tile_wr <= tile_wr + 1'b1;
                tile_open <= 1'b1;
            end
            if (tile_close)
                tile_open <= 1'b0;
            if (tile_pop) begin
                tile_rd <= tile_rd + 1'b1;
                tile_done_pixels <= tile_size[tile_head];
                tile_done_slot <= tile_head;
                tile_done_overflow <= tile_overflow[tile_head];
            end
            tile_done <= tile_pop;
            for (tile_reg = 0; tile_reg < TILE_DEPTH; tile_reg = tile_reg + 1) begin
                tile_credit[tile_reg] <= tile_credit_next[tile_reg];
                tile_size[tile_reg] <= tile_size_next[tile_reg];
                tile_sealed[tile_reg] <= tile_sealed_next[tile_reg];
                tile_overflow[tile_reg] <= tile_overflow_next[tile_reg];
            end
        end
    end

    reg [7:0] dbg_accept_cycles;
    reg [7:0] dbg_retire_cycles;
    reg [7:0] dbg_blocked_cycles;
    reg [7:0] dbg_stall_run;
    reg [7:0] dbg_stall_peak;
    reg [15:0] dbg_watchdog;
    reg dbg_timeout_seen;
    reg dbg_blocked_seen;
    wire dbg_blocked = (i_pixel_pulse && !pixel_ready) ||
                       (i_peer_pixel_pulse && !peer_ready);
    initial begin
        dbg_accept_cycles = 8'd0;
        dbg_retire_cycles = 8'd0;
        dbg_blocked_cycles = 8'd0;
        dbg_stall_run = 8'd0;
        dbg_stall_peak = 8'd0;
        dbg_watchdog = 16'd0;
        dbg_timeout_seen = 1'b0;
        dbg_blocked_seen = 1'b0;
        debug_stats = 64'd0;
    end
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_begin_tile) begin
                dbg_accept_cycles <= 8'd0;
                dbg_retire_cycles <= 8'd0;
                dbg_blocked_cycles <= 8'd0;
                dbg_stall_run <= 8'd0;
                dbg_stall_peak <= 8'd0;
                dbg_watchdog <= 16'd0;
                dbg_timeout_seen <= 1'b0;
                dbg_blocked_seen <= 1'b0;
            end else begin
                if ((accept_pulse || peer_accept) && !(&dbg_accept_cycles))
                    dbg_accept_cycles <= dbg_accept_cycles + 8'd1;
                if ((retire_request || peer_retire) && !(&dbg_retire_cycles))
                    dbg_retire_cycles <= dbg_retire_cycles + 8'd1;
                if (dbg_blocked && !(&dbg_blocked_cycles))
                    dbg_blocked_cycles <= dbg_blocked_cycles + 8'd1;
                if (dbg_blocked) begin
                    dbg_blocked_seen <= 1'b1;
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 8'd1;
                    if ((dbg_stall_run >= dbg_stall_peak) && !(&dbg_stall_run))
                        dbg_stall_peak <= dbg_stall_run + 8'd1;
                end else
                    dbg_stall_run <= 8'd0;
                if (!in_flight || retire_request || peer_retire)
                    dbg_watchdog <= 16'd0;
                else if (!(&dbg_watchdog))
                    dbg_watchdog <= dbg_watchdog + 16'd1;
                if (&dbg_watchdog)
                    dbg_timeout_seen <= 1'b1;
            end
            debug_stats <= {dbg_accept_cycles, dbg_retire_cycles,
                            dbg_blocked_cycles, dbg_stall_peak,
                            dbg_watchdog, dbg_stall_run, 6'b0,
                            dbg_timeout_seen, dbg_blocked_seen};
        end
    end

    initial begin
        pending = ZERO;
        outstanding = ZERO;
        pulse_limit = {COUNT_W{1'b1}};
        req_toggle = 1'b0;
        ack_toggle = 1'b0;
        window_open = 1'b0;
        slow_pixel_pulse = 1'b0;
        pv = 1'b0;
for (k = 0; k < PEER_DEPTH; k = k + 1) peer_valid[k] = 1'b0;
peer_outstanding = 0;
flight_lane = 0;
peer_slow_pixel_pulse = 1'b0;
    end

    // i_slow_tick models an edge of the slower receiving domain.
    // Requests remain outstanding until that domain acknowledges them.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            if (i_load_limit)
                pulse_limit <= i_limit;

if (tile_close)
                window_open <= 1'b0;
else if (tile_allocate)
                window_open <= 1'b1;

            case ({accept_pulse, launch_request})
                2'b10: pending <= pending + ONE;
                2'b01: pending <= pending - ONE;
                default: pending <= pending;
            endcase

            case ({accept_pulse, retire_request})
                2'b10: outstanding <= outstanding + ONE;
                2'b01: outstanding <= outstanding - ONE;
                default: outstanding <= outstanding;
            endcase
if (peer_shift) begin
    for (k = PEER_DEPTH-1; k > 0; k = k - 1)
        peer_valid[k] <= peer_valid[k-1];
    peer_valid[0] <= peer_accept;
end
case ({peer_accept, peer_retire})
    2'b10: peer_outstanding <= peer_outstanding + 1'b1;
    2'b01: peer_outstanding <= peer_outstanding - 1'b1;
    default: peer_outstanding <= peer_outstanding;
endcase

if (launch_request || peer_launch)
                req_toggle <= !req_toggle;
if (launch_request || peer_launch)
    flight_lane <= peer_launch;

if (retire_request || peer_retire)
                ack_toggle <= req_toggle;

            slow_pixel_pulse <= retire_request;
peer_slow_pixel_pulse <= peer_retire;
        end
    end

    // The registered pulse reports the preceding enabled edge's delivery.
    // Inside the previous tile window, delivery and an empty work ledger
    // must never have occurred together on that edge.
    always @(posedge clk) begin
        if (pv && $past(window_open) && $past(i_ce))
            assert (!(slow_pixel_pulse && ($past(outstanding) == ZERO)));
    end
always @(posedge clk) begin
    if (pv && $past(i_ce))
        assert (!(peer_slow_pixel_pulse && ($past(peer_outstanding) == 0)));
end

    always @(posedge clk) begin
        if (pv && $past(i_ce))
            assert (!(slow_pixel_pulse &&
                      ($past(tile_credit[tile_head]) == ZERO)));
    end
endmodule

module event_queue_signature #(
    parameter BANKS = 4
) (
    input  wire clk,
    input  wire i_append,
    input  wire [63:0] i_append_slot,
    input  wire [63:0] i_append_data,
    input  wire i_retire,
    input  wire [63:0] i_retire_slot,
    input  wire [63:0] i_retire_data,
    output wire [64*BANKS-1:0] o_committed,
    output wire [64*BANKS-1:0] o_delta,
    output reg  [63:0] o_signature,
    output wire [1:0] o_pending
);
    // Power-of-two banking supports four or eight update lanes.
    localparam BANK_BITS = $clog2(BANKS);
    reg [63:0] committed [0:BANKS-1];
    reg [63:0] delta [0:BANKS-1];
    reg [63:0] next_delta [0:BANKS-1];
    reg append_pending;
    reg retire_pending;
    wire [BANK_BITS-1:0] append_bank;
    wire [BANK_BITS-1:0] retire_bank;
    assign append_bank = i_append_slot[BANK_BITS-1:0];
    assign retire_bank = i_retire_slot[BANK_BITS-1:0];

    // Combine simultaneous operations before the registered feedback path.
    integer b;
    always @(*) begin
        for (b = 0; b < BANKS; b = b + 1) begin
            next_delta[b] = 64'd0;
            if (i_append && (append_bank == b))
                next_delta[b] = next_delta[b] ^ i_append_data;
            if (i_retire && (retire_bank == b))
                next_delta[b] = next_delta[b] ^ i_retire_data;
        end
    end

    integer j;
    initial begin
        append_pending = 1'b0;
        retire_pending = 1'b0;
        for (j = 0; j < BANKS; j = j + 1) begin
            committed[j] = 64'd0;
            delta[j] = 64'd0;
        end
    end

    always @(posedge clk) begin
        append_pending <= i_append;
        retire_pending <= i_retire;
        for (j = 0; j < BANKS; j = j + 1) begin
            committed[j] <= committed[j] ^ delta[j];
            delta[j] <= next_delta[j];
        end
    end

    genvar g;
    generate
        for (g = 0; g < BANKS; g = g + 1) begin : signature_lanes
            assign o_committed[64*g +: 64] = committed[g];
            assign o_delta[64*g +: 64] = delta[g];
        end
    endgenerate

    // Forward pending updates so the public fingerprint is current.
    integer r;
    always @(*) begin
        o_signature = 64'd0;
        for (r = 0; r < BANKS; r = r + 1)
            o_signature = o_signature ^ committed[r] ^ delta[r];
    end
    assign o_pending = {1'b0, append_pending}
                     + {1'b0, retire_pending};
endmodule

module prescaler_event_queue #(
    parameter [63:0] P = 64'd4,
    parameter [63:0] DEPTH = 64'd32
) (
    input  wire        clk,
    input  wire        i_pulse_valid,
    output wire        o_pulse_ready,
    input  wire        i_mode,
    output wire        o_valid,
    input  wire        i_out_ready,
    output wire [63:0] o_data,
    output wire [63:0] o_queue_signature,
    output wire [1:0]  o_signature_pending
);
    // Supported modulus settings: 3 <= P <= 16.
    // First accepted pulse: ARM and sample mode.
    // Second accepted pulse: START.
    // Pulse P or P+1: FINISH and enqueue its event record.
    localparam [63:0] IDLE  = 64'd0;
    localparam [63:0] ARMED = 64'd1;
    localparam [63:0] RUN   = 64'd2;
    localparam SIGNATURE_BANKS = 4;

    reg [63:0] phase;
    reg [63:0] pulse_count;
    reg mode_q;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    reg [63:0] event_mem [0:DEPTH-1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] fifo_count;

    wire [63:0] modulus;
    wire pulse_fire;
    wire finish_fire;
    wire pop_fire;
    wire [DEPTH-1:0] filled;
    wire [63:0] event_record;
    wire [64*SIGNATURE_BANKS-1:0] sig_committed;
    wire [64*SIGNATURE_BANKS-1:0] sig_delta;

    assign modulus = mode_q ? P + 64'd1 : P;
    assign event_record = (pulse_count + 64'd1)
        | (arm_seen ? 64'h8000000000000000 : 64'd0)
        | (start_seen ? 64'h4000000000000000 : 64'd0)
        | (mode_q ? 64'h2000000000000000 : 64'd0);
    assign o_pulse_ready = fifo_count < DEPTH;
    assign pulse_fire = i_pulse_valid && o_pulse_ready;
    assign finish_fire = pulse_fire && (phase == RUN)
                         && (pulse_count == modulus - 64'd1);
    assign o_valid = fifo_count != 64'd0;
    assign o_data = event_mem[rd_ptr];
    assign pop_fire = o_valid && i_out_ready;
    event_queue_signature #(.BANKS(SIGNATURE_BANKS)) signature_unit (
        .clk(clk), .i_append(finish_fire),
        .i_append_slot(wr_ptr), .i_append_data(event_record),
        .i_retire(pop_fire), .i_retire_slot(rd_ptr),
        .i_retire_data(o_data), .o_committed(sig_committed),
        .o_delta(sig_delta), .o_signature(o_queue_signature),
        .o_pending(o_signature_pending)
    );

    // Filled slots are the circular interval starting at rd_ptr.
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupied_slots
            localparam [63:0] ENTRY = g;
            assign filled[g] = ((ENTRY >= rd_ptr)
                              ? (ENTRY - rd_ptr)
                              : (ENTRY + DEPTH - rd_ptr)) < fifo_count;
        end
    endgenerate

    integer j;
    initial begin
        phase = IDLE;
        pulse_count = 64'd0;
        mode_q = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        scope_armed = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        fifo_count = 64'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            event_mem[j] = 64'd0;
    end

    always @(posedge clk) begin
        if (pulse_fire) begin
            case (phase)
                IDLE: begin
                    // Q is the ARM event; its scope latch never clears.
                    scope_armed <= 1'b1;
                    mode_q <= i_mode;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    pulse_count <= 64'd1;
                    phase <= ARMED;
                end
                ARMED: begin
                    start_seen <= 1'b1;
                    pulse_count <= 64'd2;
                    phase <= RUN;
                end
                RUN: begin
                    if (finish_fire) begin
                        pulse_count <= 64'd0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= IDLE;
                    end else begin
                        pulse_count <= pulse_count + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    pulse_count <= 64'd0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end

        if (finish_fire) begin
            // Record: ARM witness, START witness, sampled mode,
            // and the number of accepted pulses in this division.
            event_mem[wr_ptr] <= event_record;
            wr_ptr <= (wr_ptr == DEPTH - 64'd1)
                    ? 64'd0 : wr_ptr + 64'd1;
        end
        if (pop_fire)
            rd_ptr <= (rd_ptr == DEPTH - 64'd1)
                    ? 64'd0 : rd_ptr + 64'd1;

        case ({finish_fire, pop_fire})
            2'b10: fifo_count <= fifo_count + 64'd1;
            2'b01: fifo_count <= fifo_count - 64'd1;
            default: begin end
        endcase
    end
    always @(posedge clk)
        if (scope_armed && pop_fire && (fifo_count == 64'd1))
            assert (o_queue_signature == o_data);

    // After Q: START requires ARM, and every observable FINISH
    // must carry both earlier event witnesses.
    always @(posedge clk)
        if (scope_armed)
            assert ((!start_seen || arm_seen)
                    && (!o_valid || (o_data[63] && o_data[62])));
endmodule

module notification_serializer #(
    parameter integer DATA_W = 64,
    parameter integer CHANNELS = 16,
    parameter integer DEPTH = 4
) (
    input wire clk, ce,
    input wire enqueue,
    input wire [DATA_W-1:0] enqueue_index,
    output wire ready,
    output reg [$clog2(DEPTH+1)-1:0] used,
    output reg [((CHANNELS > 1) ? $clog2(CHANNELS) : 1)-1:0] cursor,
    output reg [DATA_W-1:0] retired,
    output wire notify_valid,
    output wire [DATA_W-1:0] notify_index,
    output reg [DEPTH*DATA_W-1:0] queue_state
);
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};
    reg [DATA_W-1:0] tags [0:DEPTH-1];
    integer i, s;

    assign notify_index = tags[0];
    assign notify_valid = ce && (used != 0) &&
                          (tags[0] == DATA_W'(cursor));
    assign ready = (used < DEPTH) || notify_valid;

    always @(*) begin
        for (s = 0; s < DEPTH; s = s + 1)
            queue_state[s*DATA_W +: DATA_W] = tags[s];
    end

    initial begin
        used = 0;
        cursor = 0;
        retired = {DATA_W{1'b0}};
        for (i = 0; i < DEPTH; i = i + 1)
            tags[i] = {DATA_W{1'b0}};
    end

    always @(posedge clk) begin
        if (ce) begin
            if (cursor == CHANNELS-1)
                cursor <= 0;
            else
                cursor <= cursor + 1'b1;
            if (notify_valid) begin
                retired <= retired | (ONE << tags[0]);
                for (i = 0; i < DEPTH-1; i = i + 1)
                    tags[i] <= tags[i+1];
            end
            if (enqueue)
                tags[used - notify_valid] <= enqueue_index;
            case ({enqueue, notify_valid})
                2'b10: used <= used + 1'b1;
                2'b01: used <= used - 1'b1;
            endcase
        end
    end
endmodule

module masked_pipe_dispatch #(
    parameter integer DATA_W = 64,
parameter integer CHANNELS = 16,
parameter integer NOTIFY_DEPTH = 4
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  write_mask,
    input  wire [DATA_W-1:0]     mask_data,
    input  wire                  dispatch,
    input  wire                  end_window,
    output reg  [DATA_W-1:0]     issued_count,
    output reg  [DATA_W-1:0]     last_index,
    output reg                   last_valid,
output reg  [39:0]           debug_status,
output wire                  dispatch_ready,
output wire                  notification_valid,
output wire [DATA_W-1:0]     notification_index,
output wire [DATA_W-1:0]     completed_channels,
output wire [$clog2(NOTIFY_DEPTH+1)-1:0] notification_count,
output wire [((CHANNELS > 1) ? $clog2(CHANNELS) : 1)-1:0] scan_channel,
output wire [NOTIFY_DEPTH*DATA_W-1:0] notification_state
);
    // Supported configurations have 1 <= CHANNELS <= DATA_W.
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] CAPACITY = DATA_W'(CHANNELS);
    localparam [DATA_W-1:0] CHANNEL_BITS =
        {DATA_W{1'b1}} >> (DATA_W - CHANNELS);

    // Each channel initially has one pending notification.
    reg [DATA_W-1:0] pending;
    reg [DATA_W-1:0] sw_mask;
    reg before_window_end;
    reg past_valid;

    // Lowest numbered enabled request has highest priority.
    function automatic [DATA_W-1:0] priority_index(
        input [DATA_W-1:0] bits
    );
        integer j;
        begin
            priority_index = ZERO;
            for (j = CHANNELS - 1; j >= 0; j = j - 1)
                if (bits[j])
                    priority_index = DATA_W'(j);
        end
    endfunction

    wire [DATA_W-1:0] eligible = pending & sw_mask;
    wire [DATA_W-1:0] encoded_index = priority_index(eligible);
    wire serializer_ready;
    wire [DATA_W-1:0] notification_tags [0:NOTIFY_DEPTH-1];
    genvar n;
    generate for (n = 0; n < NOTIFY_DEPTH; n = n + 1) begin : unpack_notifications
        assign notification_tags[n] = notification_state[n*DATA_W +: DATA_W];
    end endgenerate

    notification_serializer #(
        .DATA_W(DATA_W), .CHANNELS(CHANNELS), .DEPTH(NOTIFY_DEPTH)
    ) notifications (
        .clk(clk), .ce(ce), .enqueue(take), .enqueue_index(last_index),
        .ready(serializer_ready), .used(notification_count),
        .cursor(scan_channel), .retired(completed_channels),
        .notify_valid(notification_valid), .notify_index(notification_index),
        .queue_state(notification_state)
    );

    // Mask writes take priority over dispatch commands.
    assign dispatch_ready = ce && last_valid && !write_mask && serializer_ready;
    wire take = dispatch && dispatch_ready;
    wire [DATA_W-1:0] next_mask =
        write_mask ? (mask_data & CHANNEL_BITS) : sw_mask;
    wire [DATA_W-1:0] next_pending =
        take ? (pending & ~(ONE << last_index)) : pending;
    wire [DATA_W-1:0] next_eligible = next_pending & next_mask;

    reg [DATA_W-1:0] pending_population;
    reg [DATA_W-1:0] completed_population;
    reg [DATA_W-1:0] queued_channels;
    integer p;
    integer q;
    always @(*) begin
        pending_population = ZERO;
        completed_population = ZERO;
        queued_channels = ZERO;
        for (p = 0; p < CHANNELS; p = p + 1) begin
            pending_population = pending_population +
                {{(DATA_W-1){1'b0}}, pending[p]};
            completed_population = completed_population +
                {{(DATA_W-1){1'b0}}, completed_channels[p]};
        end
        for (q = 0; q < NOTIFY_DEPTH; q = q + 1)
            if (q < notification_count)
                queued_channels = queued_channels | (ONE << notification_tags[q]);
    end

    initial begin
        pending = CHANNEL_BITS;
        sw_mask = CHANNEL_BITS;
        issued_count = ZERO;
        last_index = ZERO;
        last_valid = 1'b1;
        before_window_end = 1'b1;
        past_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            pending <= next_pending;
            sw_mask <= next_mask;
            last_index <= priority_index(next_eligible);
            last_valid <= (next_eligible != ZERO);
            if (take)
                issued_count <= issued_count + ONE;
            if (end_window)
                before_window_end <= 1'b0;
            past_valid <= 1'b1;
        end
    end

   reg [7:0] dbg_accepted;
   reg [7:0] dbg_blocked;
   reg [7:0] dbg_mask_writes;
   reg [7:0] dbg_idle_streak;
   reg [7:0] dbg_idle_peak;

   initial begin
       dbg_accepted = 8'd0;
       dbg_blocked = 8'd0;
       dbg_mask_writes = 8'd0;
       dbg_idle_streak = 8'd0;
       dbg_idle_peak = 8'd0;
       debug_status = 40'd0;
   end

   always @(posedge clk) begin
       if (ce) begin
           if (take && dbg_accepted != 8'hff)
               dbg_accepted <= dbg_accepted + 8'd1;
           if (dispatch && !take && dbg_blocked != 8'hff)
               dbg_blocked <= dbg_blocked + 8'd1;
           if (write_mask && dbg_mask_writes != 8'hff)
               dbg_mask_writes <= dbg_mask_writes + 8'd1;
           if (dispatch || write_mask)
               dbg_idle_streak <= 8'd0;
           else if (dbg_idle_streak != 8'hff)
               dbg_idle_streak <= dbg_idle_streak + 8'd1;
           if (!dispatch && !write_mask &&
               dbg_idle_streak != 8'hff &&
               dbg_idle_streak >= dbg_idle_peak)
               dbg_idle_peak <= dbg_idle_streak + 8'd1;
           debug_status <= {dbg_idle_peak, dbg_idle_streak,
                            dbg_mask_writes, dbg_blocked, dbg_accepted};
       end
   end

    always @(posedge clk)
        if (past_valid && notification_valid)
            assert (completed_population < issued_count &&
                    (pending & (ONE << notification_index)) == ZERO &&
                    (completed_channels & (ONE << notification_index)) == ZERO);

    // Before the first enabled end_window event, an unchanged request
    // set means no additional dispatches, and the batch budget holds.
    always @(posedge clk)
        if (past_valid && before_window_end && $stable(pending))
            assert ($stable(issued_count) && issued_count <= CAPACITY);
endmodule

module prescaler_event_queue #(
    parameter [63:0] P = 64'd4,
parameter [63:0] DEPTH = 64'd32,
parameter integer STATS_DEPTH = 4,
parameter integer STATS_BATCH = 4
) (
    input  wire        clk,
    input  wire        i_pulse_valid,
    output wire        o_pulse_ready,
    input  wire        i_mode,
    output wire        o_valid,
    input  wire        i_out_ready,
output wire [63:0] o_data,
output wire        o_trace_valid,
output reg         o_trace_bit,
output wire        o_trace_last,
output wire        o_trace_busy,
output wire        o_stats_valid,
output wire        o_stats_busy,
output wire [$clog2(STATS_BATCH+1)-1:0] o_stats_count,
output wire [$clog2(STATS_BATCH+1)-1:0] o_stats_extended,
output wire [63:0] o_stats_total,
output wire [63:0] o_stats_min,
output wire [63:0] o_stats_max,
output wire [63:0] o_stats_span,
output wire [1:0]  o_stats_witnesses
);
    // Supported modulus settings: 3 <= P <= 16.
    // First accepted pulse: ARM and sample mode.
    // Second accepted pulse: START.
    // Pulse P or P+1: FINISH and enqueue its event record.
    localparam [63:0] IDLE  = 64'd0;
    localparam [63:0] ARMED = 64'd1;
    localparam [63:0] RUN   = 64'd2;

    reg [63:0] phase;
    reg [63:0] pulse_count;
    reg mode_q;
    reg arm_seen;
    reg start_seen;
    reg scope_armed;

    reg [63:0] event_mem [0:DEPTH-1];
    reg [63:0] rd_ptr;
    reg [63:0] wr_ptr;
    reg [63:0] fifo_count;

    localparam TRACE_DEPTH = 4;
    localparam TRACE_ADDR_W = $clog2(TRACE_DEPTH);
    reg [63:0] trace_mem [0:TRACE_DEPTH-1];
    reg [TRACE_ADDR_W:0] trace_rd;
    reg [TRACE_ADDR_W:0] trace_wr;
    reg [63:0] trace_shift;
    reg [6:0] trace_index;
    reg trace_active;

    wire trace_empty;
    wire trace_full;
    wire trace_push;
    wire trace_load;
    wire trace_step;
    wire trace_done;
    wire [TRACE_ADDR_W:0] trace_used;
    wire [TRACE_ADDR_W:0] trace_held;
    wire [TRACE_DEPTH-1:0] trace_filled;

    // Statistics ingress uses a power-of-two depth, independently of tracing.
    localparam STATS_ADDR_W = $clog2(STATS_DEPTH);
    localparam STATS_COUNT_W = $clog2(STATS_BATCH+1);
    localparam STATS_HOLD_W = $clog2(STATS_DEPTH+STATS_BATCH+1);
    localparam [1:0] STATS_WAIT = 2'd0;
    localparam [1:0] STATS_DECODE = 2'd1;
    localparam [1:0] STATS_FOLD = 2'd2;
    localparam [1:0] STATS_REPORT = 2'd3;

    reg [63:0] stats_mem [0:STATS_DEPTH-1];
    reg [STATS_ADDR_W:0] stats_rd;
    reg [STATS_ADDR_W:0] stats_wr;
    reg [1:0] stats_state;
    reg [63:0] stats_word;
    reg [63:0] stats_payload;
    reg stats_extended;
    reg [1:0] stats_witnesses;
    reg [STATS_COUNT_W-1:0] stats_count;
    reg [STATS_COUNT_W-1:0] stats_extended_count;
    reg [63:0] stats_total;
    reg [63:0] stats_min;
    reg [63:0] stats_max;
    reg [1:0] stats_all_witnesses;
    reg [63:0] stats_next_min;
    reg [63:0] stats_next_max;

    wire stats_empty;
    wire stats_full;
    wire [STATS_ADDR_W:0] stats_used;
    wire [STATS_DEPTH-1:0] stats_filled;
    wire stats_load;
    wire stats_fold;
    wire stats_report_fire;
    wire stats_inflight;
    wire [STATS_HOLD_W-1:0] stats_held;

    wire [63:0] modulus;
    wire pulse_fire;
    wire finish_fire;
    wire pop_fire;
    wire [DEPTH-1:0] filled;

    assign modulus = mode_q ? P + 64'd1 : P;
    assign o_pulse_ready = fifo_count < DEPTH;
    assign pulse_fire = i_pulse_valid && o_pulse_ready;
    assign finish_fire = pulse_fire && (phase == RUN)
                         && (pulse_count == modulus - 64'd1);
    assign o_valid = (fifo_count != 64'd0)
                     && !trace_full && !stats_full;
    assign o_data = event_mem[rd_ptr];
    assign pop_fire = o_valid && i_out_ready;

    // Parallel delivery and its diagnostic copy are accepted together.
    assign trace_empty = trace_rd == trace_wr;
    assign trace_full = trace_wr == {~trace_rd[TRACE_ADDR_W],
                                     trace_rd[TRACE_ADDR_W-1:0]};
    assign trace_used = trace_wr - trace_rd;
    assign trace_held = trace_used + trace_active;
    assign trace_push = pop_fire;
    assign trace_load = !trace_active && !trace_empty;
    assign trace_step = trace_active && i_out_ready;
    assign trace_done = trace_step && (trace_index == 7'd65);
    assign o_trace_valid = trace_active;
    assign o_trace_last = trace_active && (trace_index == 7'd65);
    assign o_trace_busy = trace_active || !trace_empty;

    // A parallel transfer fans out atomically to both diagnostic consumers.
    assign stats_empty = stats_rd == stats_wr;
    assign stats_full = stats_wr == {~stats_rd[STATS_ADDR_W],
                                     stats_rd[STATS_ADDR_W-1:0]};
    assign stats_used = stats_wr - stats_rd;
    assign stats_load = (stats_state == STATS_WAIT)
                        && !stats_empty;
    assign stats_fold = stats_state == STATS_FOLD;
    assign stats_report_fire = o_stats_valid && i_out_ready;
    assign stats_inflight = (stats_state == STATS_DECODE)
                            || (stats_state == STATS_FOLD);
    assign stats_held = stats_used + stats_count
                        + stats_inflight;
    assign o_stats_valid = stats_state == STATS_REPORT;
    assign o_stats_busy = !stats_empty || stats_inflight
                          || (stats_count != 0);
    assign o_stats_count = stats_count;
    assign o_stats_extended = stats_extended_count;
    assign o_stats_total = stats_total;
    assign o_stats_min = stats_min;
    assign o_stats_max = stats_max;
    assign o_stats_span = (stats_count == 0) ? 64'd0
                         : stats_max - stats_min;
    assign o_stats_witnesses = stats_all_witnesses;

    // Filled slots are the circular interval starting at rd_ptr.
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupied_slots
            localparam [63:0] ENTRY = g;
            assign filled[g] = ((ENTRY >= rd_ptr)
                              ? (ENTRY - rd_ptr)
                              : (ENTRY + DEPTH - rd_ptr)) < fifo_count;
        end
    endgenerate

    genvar s;
    generate
        for (s = 0; s < STATS_DEPTH; s = s + 1) begin : stats_slots
            localparam [STATS_ADDR_W-1:0] ENTRY = s;
            wire [STATS_ADDR_W-1:0] offset;
            assign offset = ENTRY - stats_rd[STATS_ADDR_W-1:0];
            assign stats_filled[s] = {1'b0, offset} < stats_used;
        end
    endgenerate

    genvar t;
    generate
        for (t = 0; t < TRACE_DEPTH; t = t + 1) begin : trace_slots
            localparam [TRACE_ADDR_W-1:0] ENTRY = t;
            wire [TRACE_ADDR_W-1:0] offset;
            assign offset = ENTRY - trace_rd[TRACE_ADDR_W-1:0];
            assign trace_filled[t] = {1'b0, offset} < trace_used;
        end
    endgenerate

    integer j;
    initial begin
        phase = IDLE;
        pulse_count = 64'd0;
        mode_q = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        scope_armed = 1'b0;
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        fifo_count = 64'd0;
        for (j = 0; j < DEPTH; j = j + 1)
            event_mem[j] = 64'd0;
        trace_rd = 0;
        trace_wr = 0;
        trace_shift = 64'd0;
        trace_index = 7'd0;
        trace_active = 1'b0;
        for (j = 0; j < TRACE_DEPTH; j = j + 1)
            trace_mem[j] = 64'd0;
        stats_rd = 0;
        stats_wr = 0;
        stats_state = STATS_WAIT;
        stats_word = 64'd0;
        stats_payload = 64'd0;
        stats_extended = 1'b0;
        stats_witnesses = 2'b00;
        stats_count = 0;
        stats_extended_count = 0;
        stats_total = 64'd0;
        stats_min = 64'd0;
        stats_max = 64'd0;
        stats_all_witnesses = 2'b11;
        for (j = 0; j < STATS_DEPTH; j = j + 1)
            stats_mem[j] = 64'd0;
    end

    always @(posedge clk) begin
        if (pulse_fire) begin
            case (phase)
                IDLE: begin
                    // Q is the ARM event; its scope latch never clears.
                    scope_armed <= 1'b1;
                    mode_q <= i_mode;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    pulse_count <= 64'd1;
                    phase <= ARMED;
                end
                ARMED: begin
                    start_seen <= 1'b1;
                    pulse_count <= 64'd2;
                    phase <= RUN;
                end
                RUN: begin
                    if (finish_fire) begin
                        pulse_count <= 64'd0;
                        arm_seen <= 1'b0;
                        start_seen <= 1'b0;
                        phase <= IDLE;
                    end else begin
                        pulse_count <= pulse_count + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    pulse_count <= 64'd0;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end

        if (finish_fire) begin
            // Record: ARM witness, START witness, sampled mode,
            // and the number of accepted pulses in this division.
            event_mem[wr_ptr] <= (pulse_count + 64'd1)
                | (arm_seen ? 64'h8000000000000000 : 64'd0)
                | (start_seen ? 64'h4000000000000000 : 64'd0)
                | (mode_q ? 64'h2000000000000000 : 64'd0);
            wr_ptr <= (wr_ptr == DEPTH - 64'd1)
                    ? 64'd0 : wr_ptr + 64'd1;
        end
        if (pop_fire)
            rd_ptr <= (rd_ptr == DEPTH - 64'd1)
                    ? 64'd0 : rd_ptr + 64'd1;

        case ({finish_fire, pop_fire})
            2'b10: fifo_count <= fifo_count + 64'd1;
            2'b01: fifo_count <= fifo_count - 64'd1;
            default: begin end
        endcase
    end

    // The drain-ready input also clocks acceptance of trace symbols.
    // Frames contain a low start, the complete record, and a high stop.
    always @(*) begin
        o_trace_bit = 1'b1;
        if (trace_active) begin
            if (trace_index == 7'd0)
                o_trace_bit = 1'b0;
            else if (trace_index <= 7'd64)
                o_trace_bit = trace_shift[0];
        end
    end

    always @(posedge clk) begin
        if (trace_push) begin
            trace_mem[trace_wr[TRACE_ADDR_W-1:0]] <= o_data;
            trace_wr <= trace_wr + 1'b1;
        end
        if (trace_load) begin
            trace_shift <= trace_mem[trace_rd[TRACE_ADDR_W-1:0]];
            trace_rd <= trace_rd + 1'b1;
            trace_index <= 7'd0;
            trace_active <= 1'b1;
        end else if (trace_step) begin
            if (trace_done) begin
                trace_active <= 1'b0;
                trace_index <= 7'd0;
            end else begin
                trace_index <= trace_index + 7'd1;
                if (trace_index != 7'd0)
                    trace_shift <= {1'b0, trace_shift[63:1]};
            end
        end
    end

    always @(posedge clk)
        if (trace_step && ((trace_index == 7'd63)
                          || (trace_index == 7'd64)))
            assert (scope_armed && o_trace_bit);

    // After Q: START requires ARM, and every observable FINISH
    // must carry both earlier event witnesses.
    always @(posedge clk)
        if (scope_armed)
            assert ((!start_seen || arm_seen)
                    && (!o_valid || (o_data[63] && o_data[62])));

    // The first record seeds extrema; subsequent records compare normally.
    always @(*) begin
        stats_next_min = stats_min;
        stats_next_max = stats_max;
        if (stats_count == 0) begin
            stats_next_min = stats_payload;
            stats_next_max = stats_payload;
        end else begin
            if (stats_payload < stats_min)
                stats_next_min = stats_payload;
            if (stats_payload > stats_max)
                stats_next_max = stats_payload;
        end
    end

    always @(posedge clk) begin
        if (pop_fire) begin
            stats_mem[stats_wr[STATS_ADDR_W-1:0]] <= o_data;
            stats_wr <= stats_wr + 1'b1;
        end
        if (stats_load) begin
            stats_word <= stats_mem[stats_rd[STATS_ADDR_W-1:0]];
            stats_rd <= stats_rd + 1'b1;
        end
        case (stats_state)
            STATS_WAIT: begin
                if (stats_load)
                    stats_state <= STATS_DECODE;
            end
            STATS_DECODE: begin
                stats_payload <= stats_word & 64'h1fffffffffffffff;
                stats_extended <= stats_word[61];
                stats_witnesses <= stats_word[63:62];
                stats_state <= STATS_FOLD;
            end
            STATS_FOLD: begin
                stats_total <= stats_total + stats_payload;
                stats_extended_count <= stats_extended_count + stats_extended;
                stats_count <= stats_count + 1'b1;
                stats_min <= stats_next_min;
                stats_max <= stats_next_max;
                stats_all_witnesses <= stats_all_witnesses & stats_witnesses;
                if (stats_count == STATS_BATCH - 1)
                    stats_state <= STATS_REPORT;
                else
                    stats_state <= STATS_WAIT;
            end
            STATS_REPORT: begin
                if (stats_report_fire) begin
                    stats_state <= STATS_WAIT;
                    stats_count <= 0;
                    stats_extended_count <= 0;
                    stats_total <= 64'd0;
                    stats_min <= 64'd0;
                    stats_max <= 64'd0;
                    stats_all_witnesses <= 2'b11;
                end
            end
        endcase
    end

    // The shared drain handshake accepts one complete statistics batch.
    always @(posedge clk)
        if (o_stats_valid && i_out_ready)
            assert (scope_armed
                    && (stats_count == STATS_BATCH)
                    && (stats_all_witnesses == 2'b11)
                    && (stats_total == (P * STATS_BATCH)
                                       + stats_extended_count));
endmodule

module masked_pipe_dispatch #(
    parameter integer DATA_W = 64,
    parameter integer CHANNELS = 16,
    parameter integer MASK_DEPTH = 4
) (
    input  wire                  clk,
    input  wire                  ce,
    input  wire                  write_mask,
    input  wire [DATA_W-1:0]     mask_data,
    input  wire                  dispatch,
    input  wire                  end_window,
    output reg  [DATA_W-1:0]     issued_count,
    output reg  [DATA_W-1:0]     last_index,
    output reg                   last_valid,
    output wire                  mask_ready,
    output wire                  dispatch_ready,
    output wire                  mask_queue_valid,
    output wire [$clog2(MASK_DEPTH):0] mask_queued,
    output wire [DATA_W-1:0]     mask_head,
    output wire [DATA_W-1:0]     mask_origin,
    output wire [DATA_W-1:0]     mask_retired
);
    // Supported configurations have 1 <= CHANNELS <= DATA_W.
    localparam [DATA_W-1:0] ZERO = {DATA_W{1'b0}};
    localparam [DATA_W-1:0] ONE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] CAPACITY = DATA_W'(CHANNELS);
    localparam [DATA_W-1:0] CHANNEL_BITS =
        {DATA_W{1'b1}} >> (DATA_W - CHANNELS);
    // The command FIFO supports power-of-two depths, four or eight.
    localparam integer MASK_ADDR_W = $clog2(MASK_DEPTH);

    // Each channel initially has one pending notification.
    reg [DATA_W-1:0] pending;
    reg [DATA_W-1:0] sw_mask;
    reg before_window_end;
    reg past_valid;
    reg [MASK_ADDR_W:0] mask_wr;
    reg [MASK_ADDR_W:0] mask_rd;
    reg [DATA_W-1:0] mask_words [0:MASK_DEPTH-1];
    reg [DATA_W-1:0] mask_snapshot [0:MASK_DEPTH-1];
    reg [MASK_DEPTH-1:0] mask_live;
    integer ms;
    integer mi;

    wire mask_empty = (mask_wr == mask_rd);
    wire mask_full = (mask_wr ==
        (mask_rd ^ {1'b1, {MASK_ADDR_W{1'b0}}}));
    wire mask_push = write_mask && mask_ready;
    wire mask_pop = ce && !mask_empty &&
        (!dispatch || !last_valid);
    assign mask_ready = ce && !mask_full;
    assign dispatch_ready = ce && last_valid;
    assign mask_queued = mask_wr - mask_rd;
    assign mask_queue_valid = !mask_empty;
    assign mask_head = mask_words[mask_rd[MASK_ADDR_W-1:0]];
    assign mask_origin = mask_snapshot[mask_rd[MASK_ADDR_W-1:0]];
    assign mask_retired = mask_origin & ~pending;

    always @(*) begin
        for (ms = 0; ms < MASK_DEPTH; ms = ms + 1) begin
            if (mask_rd[MASK_ADDR_W-1:0] < mask_wr[MASK_ADDR_W-1:0])
                mask_live[ms] = !mask_empty &&
                    ms >= mask_rd[MASK_ADDR_W-1:0] &&
                    ms < mask_wr[MASK_ADDR_W-1:0];
            else
                mask_live[ms] = !mask_empty &&
                    (ms >= mask_rd[MASK_ADDR_W-1:0] ||
                     ms < mask_wr[MASK_ADDR_W-1:0]);
        end
    end

    // Lowest numbered enabled request has highest priority.
    function automatic [DATA_W-1:0] priority_index(
        input [DATA_W-1:0] bits
    );
        integer j;
        begin
            priority_index = ZERO;
            for (j = CHANNELS - 1; j >= 0; j = j - 1)
                if (bits[j])
                    priority_index = DATA_W'(j);
        end
    endfunction

    wire [DATA_W-1:0] eligible = pending & sw_mask;
    wire [DATA_W-1:0] encoded_index = priority_index(eligible);

    // Deploy queued settings between dispatches, without blocking writes.
    wire take = dispatch && last_valid;
    wire [DATA_W-1:0] next_mask =
        mask_pop ? mask_head : sw_mask;
    wire [DATA_W-1:0] next_pending =
        take ? (pending & ~(ONE << last_index)) : pending;
    wire [DATA_W-1:0] next_eligible = next_pending & next_mask;

    reg [DATA_W-1:0] pending_population;
    integer p;
    always @(*) begin
        pending_population = ZERO;
        for (p = 0; p < CHANNELS; p = p + 1)
            pending_population = pending_population +
                {{(DATA_W-1){1'b0}}, pending[p]};
    end

    initial begin
        pending = CHANNEL_BITS;
        sw_mask = CHANNEL_BITS;
        issued_count = ZERO;
        last_index = ZERO;
        last_valid = 1'b1;
        before_window_end = 1'b1;
        past_valid = 1'b0;
        mask_wr = 0;
        mask_rd = 0;
        for (mi = 0; mi < MASK_DEPTH; mi = mi + 1) begin
            mask_words[mi] = ZERO;
            mask_snapshot[mi] = ZERO;
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            if (mask_push) begin
                mask_words[mask_wr[MASK_ADDR_W-1:0]] <= mask_data & pending;
                mask_snapshot[mask_wr[MASK_ADDR_W-1:0]] <= pending;
                mask_wr <= mask_wr + 1'b1;
            end
            if (mask_pop)
                mask_rd <= mask_rd + 1'b1;
            pending <= next_pending;
            sw_mask <= next_mask;
            last_index <= priority_index(next_eligible);
            last_valid <= (next_eligible != ZERO);
            if (take)
                issued_count <= issued_count + ONE;
            if (end_window)
                before_window_end <= 1'b0;
            past_valid <= 1'b1;
        end
    end

    // Before the first enabled end_window event, an unchanged request
    // set means no additional dispatches, and the batch budget holds.
    always @(posedge clk)
        if (past_valid && before_window_end && $stable(pending))
            assert ($stable(issued_count) && issued_count <= CAPACITY);

    // A deployed command refers only to its submission-time request set.
    always @(posedge clk)
        if (past_valid && mask_pop)
            assert (((pending | mask_words[mask_rd[MASK_ADDR_W-1:0]]) &
                ~mask_snapshot[mask_rd[MASK_ADDR_W-1:0]]) == ZERO);
endmodule
